        // ═══════════════════════════════════════════════════════════════
        // 构造函数与初始化
        // ═══════════════════════════════════════════════════════════════
        // ScheduleEditor 模式：入口程序集名 = "ScheduleEditor" 时，
        // 跳过 WebSocket 服务/计时硬件初始化，并隐藏与编排/成绩/文档无关的标签页。
        // 这样同一份 MainWindow XAML/代码两个 EXE 共用，"编排记录及成绩处理"完全照搬主服务器样式。
        public static bool IsScheduleEditorMode {
            get {
                try {
                    var asm = System.Reflection.Assembly.GetEntryAssembly();
                    if (asm == null) return false;
                    return string.Equals(asm.GetName().Name, "ScheduleEditor", StringComparison.OrdinalIgnoreCase);
                } catch { return false; }
            }
        }

        // 2026-06-17 RemoteTimingControl 模式: 入口程序集名 = "RemoteTimingControl" 时,
        // 跳过 WebSocket Server 启动, 跳过本地硬件直连. 只保留"比赛控制"标签页.
        // ══════════════════════════════════════════════════════════════
        // 2026-08-25 机器角色
        //
        //   standalone(默认)  一台机器全干 —— 小比赛照旧, 什么都不变
        //   server            主服务器: 【不承担计时】, 计时交给专门的计时机
        //   timing            计时机: 专心计时(RemoteTimingControl 走这个)
        //
        // 正规比赛不该由一台机器包办, 计时必须独立 —— 这是行业做法。
        // 但【代码一行不删】: 两个 exe 编的是同一份 MainWindow.xaml.cs,
        // 删了主服务器的计时, RemoteTimingControl 的也一起没了。
        // 所以只能像下面 IsRemoteTimingControlMode 那样做成运行时开关。
        //
        // 来源(命令行优先): --role server  |  meet_service.json { "Role": "server" }
        // ══════════════════════════════════════════════════════════════
        private static string _roleCache;
        public static string MachineRole {
            get {
                if (_roleCache != null) return _roleCache;
                _roleCache = "standalone";
                try {
                    var args = Environment.GetCommandLineArgs();
                    for (int i = 0; i < args.Length; i++) {
                        if (args[i].StartsWith("--role=", StringComparison.OrdinalIgnoreCase))
                        { _roleCache = args[i].Substring(7).Trim().ToLowerInvariant(); return _roleCache; }
                        if (string.Equals(args[i], "--role", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
                        { _roleCache = args[i + 1].Trim().ToLowerInvariant(); return _roleCache; }
                    }
                    string cfg = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "meet_service.json");
                    if (File.Exists(cfg)) {
                        var o = JObject.Parse(File.ReadAllText(cfg, Encoding.UTF8));
                        if (o["Role"] != null) _roleCache = o["Role"].ToString().Trim().ToLowerInvariant();
                    }
                } catch { }
                return _roleCache;
            }
        }

        /// <summary>本机是"只管竞赛数据、不承担计时"的主服务器。</summary>
        public static bool IsScoringServerNoTiming {
            get { return MachineRole == "server" && !IsRemoteTimingControlMode; }
        }

        /// <summary>
        /// 主服务器角色: 把"比赛控制"整个标签页从界面上摘掉 —— 不是禁用按钮,
        /// 是根本进不去。计时是计时机的事, 主服务器上不该有这个入口,
        /// 免得操作员误以为可以在这台机器上发令。
        /// 用 Remove 而不是 Visibility=Collapsed: 折叠只是看不见, Tab 键还能切进去。
        /// </summary>
        // ══════════════════════════════════════════════════════════════
        // 2026-09-13 右侧"运动员注册"面板只在用得上的两页出现
        //
        // 「赛事管理与报名」右边那块注册表单, 只有 运动员管理 / 接力队管理 两页在用;
        // 赛事概览、赛程管理、出场编排微调、比赛参数设置管理、记录管理都用不着 ——
        // 留在那儿既占掉 400 像素(左边表格被挤窄), 又让人以为当前页能注册。
        //
        // 收起来的时候把那一列的宽度也归零, 不然只是内容看不见, 空白还占着位置。
        private void UpdateAthleteRegPanelVisibility() {
            if (MeetMgmtTabs == null || AthleteRegPanel == null || AthleteRegColumn == null) return;
            string header = "";
            var ti = MeetMgmtTabs.SelectedItem as TabItem;
            if (ti != null && ti.Header != null) header = ti.Header.ToString();
            // 2026-10-06 同一类坑: Header 文本 English 模式下已是英文, 跟硬编码中文比永远比不中——
            //   导致 English 模式下不管切到哪页, 右边的运动员注册面板都不出现。
            bool show = (header == Loc.TChinese("Str_EM_Tab_Swimmers") || header == Loc.TEnglish("Str_EM_Tab_Swimmers")
                || header == Loc.TChinese("Str_EM_Tab_Relay") || header == Loc.TEnglish("Str_EM_Tab_Relay"));
            AthleteRegPanel.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
            AthleteRegColumn.Width = show ? new GridLength(400) : new GridLength(0);
        }

        private void MeetMgmtTabs_SelectionChanged(object sender, SelectionChangedEventArgs e) {
            // 里层控件(DataGrid 选中行之类)的 SelectionChanged 也会冒泡到这里, 只认这一个 TabControl 自己的
            if (!ReferenceEquals(e.OriginalSource, MeetMgmtTabs)) return;
            UpdateAthleteRegPanelVisibility();
        }

        private void ApplyMachineRoleToUi() {
            try {
                if (!IsScoringServerNoTiming) return;
                if (RaceControlTab != null && RaceControlTab.Parent is System.Windows.Controls.TabControl) {
                    var tc = (System.Windows.Controls.TabControl)RaceControlTab.Parent;
                    tc.Items.Remove(RaceControlTab);
                    AddLog(Loc.T("Str_Log_RoleServerRemovedRaceControl"));
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ApplyRoleUiFailedFmt", ex.Message)); }
        }

        /// <summary>计时相关操作的统一守卫。被挡下时回 true。</summary>
        private bool BlockIfNoTiming(string what) {
            if (!IsScoringServerNoTiming) return false;
            AddLog(Loc.F("Str_Log_IgnoredNoTimingFmt", what));
            return true;
        }

        public static bool IsRemoteTimingControlMode {
            get {
                try {
                    var asm = System.Reflection.Assembly.GetEntryAssembly();
                    if (asm == null) return false;
                    return string.Equals(asm.GetName().Name, "RemoteTimingControl", StringComparison.OrdinalIgnoreCase);
                } catch { return false; }
            }
        }

        /// <summary>
        /// 2026-09-18 "这台机器是不是一个连着远端主服务器的计时站"——不按 exe 名字判,
        /// 按两种情况算: ① 真正的 RemoteTimingControl.exe(IsRemoteTimingControlMode);
        /// ② 普通 SwimmingScoreboard.exe 配了 --role timing / meet_service.json
        /// {"Role":"timing"}, 直接连硬件、连远端主服务器, 但不像 RTC.exe 那样收起界面、
        /// 也照常开自己的本机 WebSocket/HTTP 服务(race_control.html 可以直接连这台机器)。
        ///
        /// 用户明确要用这第二种部署方式——这是原来完全没接通的一条路: MachineRole 早就
        /// 认得 "timing" 这个值, 但代码里唯一读它的地方(注释文档)从没真的据此做过任何事,
        /// "推参数/推确认成绩/连远端竞赛库"这几处只认 IsRemoteTimingControlMode, 换成这种
        /// 部署方式全部落空(数据只进了本机, 主服务器完全不知道)。
        ///
        /// 只用来放宽"要不要把本机状态/数据同步给远端主服务器"这一类判断——RTC 特有的
        /// "没有本机 WebSocket/HTTP 服务, 必须经 EditorSyncClient 转发广播" 那一大类判断
        /// 不能换成这个: 普通 exe 本来就开着本机服务, 走本机 _allSockets 广播才是对的,
        /// 硬套这个反而会把 race_control.html 等本机连接方式打断。
        /// </summary>
        public static bool IsTimingClientMode {
            get { return IsRemoteTimingControlMode || (!IsScheduleEditorMode && MachineRole == "timing"); }
        }

        public MainWindow() {
            InitializeComponent();
            // 2026-08-28 竞赛库那一层原来传的是 null, 日志全进了黑洞 —— 三个 exe 都受影响。
            //   放在 InitializeComponent 之后: 此时 SystemLogListBox 已存在, AddLog 可用。
            _meetDb.SetLogger(AddLog);
            bool editorMode = IsScheduleEditorMode;
            bool rtcMode = IsRemoteTimingControlMode;
            // 2026-09-18 普通主程序配了 --role timing 连远端主服务器: 界面/本机服务都
            //   保持全功能(不像 RTC 那样收起 tab、不开本机 WebSocket/HTTP), 只额外
            //   把"推参数/推确认成绩/连远端竞赛库"这条通道接上——见 IsTimingClientMode 和
            //   下面 ApplyPlainTimingRoleMode 的说明。
            bool plainTimingRole = !editorMode && !rtcMode && MachineRole == "timing";
            // 2026-06-17 模式角色:
            //   编辑端 (ScheduleEditor): 跳过 Server + 硬件 + 自动连接 (只管数据编辑)
            //   RTC (RemoteTimingControl): 跳过 Server 但开硬件 (直连硬件计时器, 当 Client 连主服务器拉数据/推成绩)
            if (editorMode) ApplyScheduleEditorMode();
            if (rtcMode) ApplyRemoteTimingControlMode();
            if (plainTimingRole) ApplyPlainTimingRoleMode();
            InitializeData();
            // 2026-06-17 RTC 也开 Server (RTC 连硬件 = 主控, 大屏直接连 RTC).
            //   主服务器和 RTC 不应同时跑同一台机器, 否则 3002 端口冲突.
            if (!editorMode) InitializeWebSocketServer();
            if (!editorMode) InitializeHttpFileServer();                // 2026-06-17 HTTP 文件服务 (大屏 display.html 用)
            if (!editorMode) InitializeTimingBridge();                  // 硬件: 主控 + RTC 都连
            InitializeTimers();
            LoadTimingSettings();
            LoadDisplayStyleFromDisk();      // 2026-06-01 大屏样式持久化还原
            RefreshRecordsHiddenBtn();       // 2026-06-03 同步 "记录显示/隐藏" 按钮初始文字
            RefreshRemarkReactionBtn();      // 2026-06-04 同步 "备注: 显/不显反应时" 按钮初始文字
            LoadAutoSaveTxtPath();           // 2026-06-05 加载 成绩 txt 自动存盘路径
            LoadThermalPrinterConfig();      // 2026-06-12 加载 USB 热敏打印机 配置 (实时打印 TP/SB/MB)
            ApplyPersistedDeviceStates();   // 设备状态（损坏/未安装/手动按键）从 device_states.json 还原
            LoadTimingConnectionConfig();   // 通讯参数从 timing_connection.json 还原
            ApplyMachineRoleToUi();         // 2026-08-25 主服务器角色: 摘掉「比赛控制」页
            LoadLastCompetition();
            // 2026-05-26 不在此处再调 ApplyTouchpadInstallModeToLanes — 它会覆盖 ApplyPersistedDeviceStates
            //   刚还原的 NotInstalled 标志. 所有"计算后状态"已在 (设置变更 / 硬件 0x3A / 0x42) 时
            //   通过 SaveDeviceStates 落盘, 开机只需读回即可.
            if (!editorMode) PopulateComPorts();              // RTC 也要选串口
            if (!editorMode) ApplyTimingConnectionToUi();     // RTC 也要还原 UI
            if (!editorMode) TryAutoReconnectTiming();        // RTC 也要尝试自动连硬件
            UpdateConnectionStatus();
            // 2026-08-31 大屏的数据来自服务器内存 —— 开个低频轮询, 第三台机器改了库也能跟上
            // 2026-09-18 原来这句排除了编排端(IsScheduleEditorMode), 大概是当初以为"编排端
            //   只管编辑赛程, 不用跟结果实时状态"。但编排端自己的"赛程导航"/"项目成绩打印"
            //   跟主服务器、计时端是同一份界面代码, 一样要显示【正在计时】/【已确认】——
            //   用户实拍到: 远程计时控制正在跑一组接力, 主服务器赛程导航显示【进行中】,
            //   "编排记录及成绩处理"(= 编排端)却停在【未开始】, 因为它压根没启动过这个
            //   10 秒轮询, RefreshChangedFromDb 里"正在计时"指纹比对那段代码永远不会跑到。
            //   现在编排端也开这个轮询——它不碰硬件/不驱动比赛(_raceState 在编排端上永远
            //   是 Waiting, DbPoll_Tick 开头那句"比赛中不动"的跳过条件对它不成立), 纯读库,
            //   没有跟主服务器/计时端冲突的写操作。
            try { StartDbPoll(); } catch { }
            try { BuildUnitBibAllocTab(); } catch (Exception ex) { AddLog("参赛单位及号码分配 tab 初始化失败: " + ex.Message); }
            _initialized = true;
            // 2026-09-13 右侧"运动员注册"面板按当前页决定显不显示(默认落在"赛事概览", 所以是隐藏)
            try { UpdateAthleteRegPanelVisibility(); } catch { }
            // 2026-09-13 开机就把控制模式算一次 —— 原来只在"有客户端连上本机"时才算,
            //   RTC 的客户端连的是主服务器, 于是 RTC 顶栏一直显示"本地"(实际是它在控制)
            try { UpdateScoringControlMode(); } catch { }
            RefreshBackupList();
            UpdateEditHeatCombo();
            UpdateResultHeatCombo();
            RefreshResultGrid();
            // 2026-06-06 Ctrl+0..9 全局键盘快捷键: 跳第 N 道圈 (= 应急用, 替代鼠标点击触发跳圈)
            this.PreviewKeyDown += MainWindow_PreviewKeyDown_SkipLapShortcut;
            this.PreviewKeyDown += MainWindow_PreviewKeyDown_BackupShortcut;   // 2026-06-10 Ctrl+Shift+B 查事件备份 / Ctrl+Shift+L 清空
            // 2026-06-08 P3-B/C: 顶栏内存监控 10s 一次刷新 + 5 分钟一次兜底轻量 GC (Optimized 模式, 非阻塞)
            StartMemoryMonitorAndPeriodicGc();
            AddLog(editorMode ? Loc.T("Str_Log_EditorModeStarted")
                  : rtcMode ? "远程计时控制 启动完成"
                  : "系统启动完成");
        }

        // 2026-06-17 RemoteTimingControl 模式: 只显示"比赛控制" tab, 隐藏其他 tab. RTC 专心做计时.
        //   RTC 角色 = 现场计时操作端: 直接连本地硬件计时器, 当 Client 连主服务器 同步赛程/运动员/推送成绩.
        //   不开 WebSocket Server (现场 RTC 不需要给大屏推数据, 那是主服务器的事).
        //   硬件连接在"比赛控制" tab 右下方"系统硬件"区操作 (网络连接 / 设备测试 / 设备全开).
        private void ApplyRemoteTimingControlMode() {
            Title = Loc.T("Str_AppTitle_Rtc");
            if (MainTabControl == null) return;
            // 2026-10-06 现场反馈: RTC/编排端启动后显示的是"系统状态"而不是该留的那个 Tab——
            //   根因是这里原来拿 Tab 的 Header 文本跟硬编码中文字面量比, Header 本身是
            //   {DynamicResource Str_Tab_*} 绑的, English 模式下已经是英文, 比不中 → keep
            //   命中个空集, 全部 Tab 被 Collapsed, SelectedItem 也没人设, 停在默认的"系统状态"。
            //   改成拿 Loc.TChinese/Loc.TEnglish 两个语种的真实值来比, 不管当前什么语言都认。
            var keep = new System.Collections.Generic.HashSet<string> {
                Loc.TChinese("Str_Tab_RaceControl"), Loc.TEnglish("Str_Tab_RaceControl")
            };
            TabItem firstVisible = null;
            foreach (var obj in MainTabControl.Items) {
                var ti = obj as TabItem;
                if (ti == null) continue;
                string header = ti.Header == null ? null : ti.Header.ToString();
                if (keep.Contains(header)) {
                    if (firstVisible == null) firstVisible = ti;
                } else {
                    ti.Visibility = Visibility.Collapsed;
                }
            }
            if (firstVisible != null) MainTabControl.SelectedItem = firstVisible;

            // 顶部状态栏注入"主服务器: [IP] [连接/断开] [状态]"控件 + 启动 EditorSyncClient
            // (复用 ScheduleEditor 同套同步机制 — 拉赛程/运动员, 推改动)
            InjectEditorSyncToolbar();
            SetupEditorSyncClient();
        }

        /// <summary>
        /// 2026-09-18 普通 SwimmingScoreboard.exe 配了 --role timing(或 meet_service.json
        /// {"Role":"timing"}) 连远端主服务器——跟 ApplyRemoteTimingControlMode 的区别只有一条:
        /// 不收起 tab、不改标题、照常开本机 WebSocket(3002)/HTTP(8080), 因为这台机器本来就是
        /// 全功能主程序, 操作员就站在它跟前操作, race_control.html/display.html 也可能直接
        /// 连这台机器本机(不是连远端那个"真身"主服务器)。
        ///
        /// 需要额外接通的只是"这台机器的确认成绩/参数改动/硬件在线状态要不要同步给远端那份
        /// 真身竞赛库"——这条路原来完全没人走(IsRemoteTimingControlMode 卡在最前面), 于是
        /// 这种部署方式下改的参数、确认的成绩全部只留在本机, 远端主服务器一无所知。
        /// 跟 RTC 共用同一套 EditorSyncClient + BindMeetServiceToHost 机制, 后续各处
        /// IsTimingClientMode 判断会一并放行。
        /// </summary>
        private void ApplyPlainTimingRoleMode() {
            InjectEditorSyncToolbar();
