        // 2026-06-08 P3-B/C: 顶栏内存监控 + 后台 5 分钟兜底 GC
        //   B: 每 10 秒读 Working Set, 显示 MB. 用户能实时看长跑下内存有没有持续涨 (= 是否漏)
        //   C: 每 5 分钟 GC.Collect(2, Optimized) — 即使用户不确认成绩 (= 比赛中长时间未到 ConfirmResult_Click)
        //      也能定期回收 可回收对象, 防止 Gen2 累计触发大停顿.
        private DispatcherTimer _memoryMonitorTimer;
        private DispatcherTimer _periodicGcTimer;
        // 2026-06-15 取系统内存占用率(% 0-100) — GlobalMemoryStatusEx.dwMemoryLoad, 供"内存占用到80%红色提示"
        [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]
        private struct MEMORYSTATUSEX {
            public uint dwLength; public uint dwMemoryLoad;
            public ulong ullTotalPhys; public ulong ullAvailPhys;
            public ulong ullTotalPageFile; public ulong ullAvailPageFile;
            public ulong ullTotalVirtual; public ulong ullAvailVirtual; public ulong ullAvailExtendedVirtual;
        }
        [System.Runtime.InteropServices.DllImport("kernel32.dll", SetLastError = true)]
        [return: System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.Bool)]
        private static extern bool GlobalMemoryStatusEx(ref MEMORYSTATUSEX lpBuffer);
        private static int GetSystemMemoryLoadPercent() {
            try {
                var m = new MEMORYSTATUSEX();
                m.dwLength = (uint)System.Runtime.InteropServices.Marshal.SizeOf(typeof(MEMORYSTATUSEX));
                if (GlobalMemoryStatusEx(ref m)) return (int)m.dwMemoryLoad;
            } catch { }
            return -1;
        }
        // 2026-06-20 扩展: 同时取 占用% + 物理总量GB + 可用GB. 失败返 false, 此时显示退回 "进程 MB" 单字段
        private static bool GetSystemMemoryInfo(out int loadPct, out double totalGB, out double availGB) {
            loadPct = -1; totalGB = 0; availGB = 0;
            try {
                var m = new MEMORYSTATUSEX();
                m.dwLength = (uint)System.Runtime.InteropServices.Marshal.SizeOf(typeof(MEMORYSTATUSEX));
                if (GlobalMemoryStatusEx(ref m)) {
                    loadPct = (int)m.dwMemoryLoad;
                    totalGB = m.ullTotalPhys / 1073741824.0;
                    availGB = m.ullAvailPhys / 1073741824.0;
                    return true;
                }
            } catch { }
            return false;
        }
        // 2026-06-20 SetProcessWorkingSetSize(handle, -1, -1) 把本进程 WS 压到最小, 视觉上立即降 MB.
        //   实质把部分页移到 PageFile, 重新访问时调回 — 用户主动按"释放内存"接受此延迟.
        [System.Runtime.InteropServices.DllImport("kernel32.dll", SetLastError = true)]
        [return: System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.Bool)]
        private static extern bool SetProcessWorkingSetSize(IntPtr hProcess, IntPtr dwMinimumWorkingSetSize, IntPtr dwMaximumWorkingSetSize);

        private void StartMemoryMonitorAndPeriodicGc() {
            try {
                _memoryMonitorTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(10) };
                _memoryMonitorTimer.Tick += delegate {
                    try {
                        if (MemoryStatusText == null) return;
                        long ws = System.Diagnostics.Process.GetCurrentProcess().WorkingSet64;
                        double mb = ws / 1048576.0;
                        // 2026-06-20 显示格式 (A): "本进程 350MB · 剩余 12.3/16.0GB · 占用 23%"
                        //   取不到系统信息退回 "350MB". G2 字段移除 (用户长跑泄漏不关心).
                        int load; double totalGB, availGB;
                        bool hasSys = GetSystemMemoryInfo(out load, out totalGB, out availGB);
                        MemoryStatusText.Text = hasSys
                            ? Loc.F("Str_Status_MemoryDetailFmt", mb, availGB, totalGB, load)
                            : string.Format("{0:F0}MB", mb);
                        // 颜色提示(按系统内存占用率): >=80% 红(吃紧提示), 60-80% 琥珀, <60% 绿; 取不到则退回按 MB
                        string memCol;
                        if (hasSys) memCol = load >= 80 ? "#EF4444" : (load >= 60 ? "#F59E0B" : "#22C55E");
                        else memCol = mb >= 1000 ? "#EF4444" : (mb >= 500 ? "#F59E0B" : "#22C55E");
                        MemoryStatusText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString(memCol));
                    } catch { }
                };
                _memoryMonitorTimer.Start();

                _periodicGcTimer = new DispatcherTimer { Interval = TimeSpan.FromMinutes(5) };
                _periodicGcTimer.Tick += delegate {
                    try {
                        GC.Collect(2, GCCollectionMode.Optimized, blocking: false);
                    } catch { }
                };
                _periodicGcTimer.Start();
            } catch { }
        }

        // 2026-06-20 手动释放内存 (顶栏 ♻ 按钮 + race_control.html RELEASE_MEMORY 远程命令).
        //   两步:
        //     (1) 强制 GC: Collect → WaitForPendingFinalizers → Collect, 回收可回收对象 + 终结器对象
        //     (2) SetProcessWorkingSetSize(-1, -1): OS 把本进程 WS 压到最小 (视觉上立即降 MB),
        //         实质把部分页移到 PageFile, 重新访问时调回 — 用户主动触发可接受短暂延迟.
        //   不能释放其他进程的内存 (普通进程无权).
        private void ReleaseMemory_Click(object sender, RoutedEventArgs e) {
            long beforeMB = 0, afterMB = 0;
            try {
                var proc = System.Diagnostics.Process.GetCurrentProcess();
                beforeMB = proc.WorkingSet64 / 1048576;
                // 第一步: 强制 GC
                GC.Collect(2, GCCollectionMode.Forced);
                GC.WaitForPendingFinalizers();
                GC.Collect(2, GCCollectionMode.Forced);
                // 第二步: 压 Working Set 到最小
                try { SetProcessWorkingSetSize(proc.Handle, (IntPtr)(-1), (IntPtr)(-1)); } catch { }
                proc.Refresh();
                afterMB = proc.WorkingSet64 / 1048576;
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_FreeMemFailedFmt", ex.Message));
                return;
            }
            long freedMB = beforeMB - afterMB;
            AddLog(Loc.F("Str_Log_FreeMemDoneFmt", beforeMB, afterMB, freedMB));
            try { Broadcast(); } catch { }   // 让 race_control 顶栏内存数字立即刷新
            // sender != null = 用户本地按按钮触发, 弹结果对话框; 远端调用 (HandleRemoteControl) sender=null 静默
            if (sender != null) {
                try {
                    AppMessageBox.Show(
                        Loc.F("Str_Msg_FreeMemoryDoneFmt", beforeMB, afterMB, freedMB),
                        Loc.T("Str_MsgTitle_FreeMemory"), MessageBoxButton.OK, MessageBoxImage.Information);
                } catch { }
            }
        }

        // 2026-06-10 Ctrl+Shift+B 查事件备份 / Ctrl+Shift+L 清空事件备份
        private void MainWindow_PreviewKeyDown_BackupShortcut(object sender, System.Windows.Input.KeyEventArgs e) {
            var mods = System.Windows.Input.Keyboard.Modifiers;
            if (mods != (System.Windows.Input.ModifierKeys.Control | System.Windows.Input.ModifierKeys.Shift)) return;
            if (e.Key == System.Windows.Input.Key.B) { e.Handled = true; QueryBackupLog(); }
            else if (e.Key == System.Windows.Input.Key.L) { e.Handled = true; ClearBackupLog(); }
        }

        // 2026-06-06 Ctrl+0..9 全局快捷键 = 跳第 0..9 道圈. PreviewKeyDown 保证比 TextBox 等元素先收到事件
        //   (Ctrl+数字 不是常见编辑快捷键, 不会与 TextBox 输入冲突). 仅 Control 单独按下生效 (= 排除 Ctrl+Shift+数字 等).
        private void MainWindow_PreviewKeyDown_SkipLapShortcut(object sender, System.Windows.Input.KeyEventArgs e) {
            if (System.Windows.Input.Keyboard.Modifiers != System.Windows.Input.ModifierKeys.Control) return;
            int digit = -1;
            if (e.Key >= System.Windows.Input.Key.D0 && e.Key <= System.Windows.Input.Key.D9) {
                digit = e.Key - System.Windows.Input.Key.D0;
            } else if (e.Key >= System.Windows.Input.Key.NumPad0 && e.Key <= System.Windows.Input.Key.NumPad9) {
                digit = e.Key - System.Windows.Input.Key.NumPad0;
            }
            if (digit < 0) return;
            e.Handled = true;
            ProcessSkipLapAdvanceOnly(digit);
        }

        // ScheduleEditor 模式：把标题和标签页缩到"赛事管理与报名 / 成绩与排名 / 文档编辑/输出/打印"三项
