            if (HwTimerLabel != null) HwTimerLabel.Visibility = Visibility.Collapsed;
            if (HwConnStatusText != null) HwConnStatusText.Visibility = Visibility.Collapsed;

            // 在顶部状态栏里注入"主服务器: [IP] [连接/断开] [状态]"控件 + 启动同步客户端
            InjectEditorSyncToolbar();
            SetupEditorSyncClient();
        }

        // ── 编排 EXE 双向同步：UI + 客户端 ─────────────────────────────────
        private TextBox _editorSyncHostBox;
        private Button _editorSyncConnectButton;
        private TextBlock _editorSyncStatusText;
        // 2026-09-28【跨客户端语言同步】这俩也是 InjectEditorSyncToolbar 里创建时赋值一次就不再变的
        // (不是 DynamicResource 绑定), 之前没存成字段所以语言切换/同步刷新不到——实机联调才发现。
        private Button _editorSyncHwConnButton;
        private TextBlock _editorSyncMainServerLabel;

        private void InjectEditorSyncToolbar() {
            if (ControlModeText == null) return;
            var parent = ControlModeText.Parent as StackPanel;
            if (parent == null) return;
            // 2026-06-17 不清空整个 StackPanel (会丢失 内存监控 MemoryStatusText / 硬件计时器灯 HwConnDot+HwConnStatusText);
            //   只移除"控制模式: ..." (= label + ControlModeText) 两个控件, 再追加"硬件连接"按钮 + "主服务器: [IP] [连接] [状态]"
            // 2026-10-06 原来靠 prev.Text.IndexOf("控制模式") 判断"要不要连标签一起删"——
            //   English 模式下这个 TextBlock 显示的是 "Control Mode: ", 根本不含"控制模式"
            //   这个中文子串, 判断必然落空: "控制模式"标签留了下来, 但后面绑的 ControlModeText
            //   已经被删掉, 现场看到的就是孤零零一个 "Control Mode:" 后面直接接"主服务器:",
            //   中间空了一截。改成直接认 x:Name="ControlModeLabel", 不比较文本内容。
            int idx = parent.Children.IndexOf(ControlModeText);
            if (idx >= 0) {
                parent.Children.RemoveAt(idx);
                if (idx > 0 && parent.Children[idx - 1] == ControlModeLabel) {
                    parent.Children.RemoveAt(idx - 1);
                }
            }
            // 2026-06-17 顶端右侧加"硬件连接"按钮 (RTC 上方便, 主服务器有原入口也可加)
            if (IsRemoteTimingControlMode) {
                _editorSyncHwConnButton = new Button {
                    Content = Loc.T("Str_Btn_HwConnLabel"),
                    Padding = new Thickness(10, 2, 10, 2), FontSize = 12,
                    Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#DC2626")),
                    Foreground = Brushes.White, BorderThickness = new Thickness(0),
                    Margin = new Thickness(8, 0, 12, 0)
                };
                _editorSyncHwConnButton.Click += delegate { ShowHardwareConnectionDialog(); };
                parent.Children.Add(_editorSyncHwConnButton);
            }
            _editorSyncMainServerLabel = new TextBlock {
                Text = Loc.T("Str_Label_MainServerColon"),
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")),
                FontSize = 12, VerticalAlignment = VerticalAlignment.Center
            };
            parent.Children.Add(_editorSyncMainServerLabel);
            _editorSyncHostBox = new TextBox {
                Text = "127.0.0.1", Width = 110, FontSize = 12,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155")),
                Foreground = Brushes.White,
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")),
                Padding = new Thickness(4, 2, 4, 2), Margin = new Thickness(0, 0, 6, 0),
                VerticalContentAlignment = VerticalAlignment.Center, CaretBrush = Brushes.White
            };
            parent.Children.Add(_editorSyncHostBox);
            _editorSyncConnectButton = new Button {
                Content = Loc.T("Str_Btn_Connect"), Padding = new Thickness(10, 2, 10, 2), FontSize = 12,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")),
                Foreground = Brushes.White, BorderThickness = new Thickness(0),
                Margin = new Thickness(0, 0, 8, 0)
            };
            _editorSyncConnectButton.Click += EditorSyncToggle_Click;
            parent.Children.Add(_editorSyncConnectButton);
            _editorSyncStatusText = new TextBlock {
                Text = Loc.T("Str_SyncStatus_Offline"), FontSize = 12, VerticalAlignment = VerticalAlignment.Center,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8"))
            };
            parent.Children.Add(_editorSyncStatusText);

            // 2026-06-17 "用户名和密码"按钮已从顶端移出, 改入"参数设置"窗口 (TimingSettingsCore 内追加).
            //   入口程序集独立凭据 (editor_credentials.json / display_credentials.json 等) 通过反射打开
            //   各自入口程序集的 ChangePasswordWindow, 跟之前一致.
        }

        // 反射打开入口程序集的 ChangePasswordWindow (该类在入口程序集里, 主服务器代码无法直接 new).
        // 2026-06-17 通用化: 支持 ScheduleEditor / RemoteTimingControl 等多个入口程序集
        private void EditorChangePassword_Click(object sender, RoutedEventArgs e) {
            try {
                var asm = System.Reflection.Assembly.GetEntryAssembly();
                if (asm == null) { AppMessageBox.Show(Loc.T("Str_Msg_NoEntryAssembly")); return; }
                // 用入口程序集的 RootNamespace + .ChangePasswordWindow
                string asmName = asm.GetName().Name;
                string typeName = asmName + ".ChangePasswordWindow";
                var t = asm.GetType(typeName);
                if (t == null) {
                    AppMessageBox.Show(Loc.F("Str_Msg_TypeNotFoundFmt", typeName), Loc.T("Str_MsgTitle_Info"),
                        MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                var win = Activator.CreateInstance(t) as Window;
                if (win == null) return;
                win.Owner = this;
                win.ShowDialog();
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_OpenChangePwdFailedFmt", ex.Message));
                AppMessageBox.Show(Loc.F("Str_Msg_OpenChangePwdFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"),
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void SetupEditorSyncClient() {
            _editorSyncClient = new EditorSyncClient();
            _editorSyncClient.OnMessage += delegate(string raw) {
                // LOCK_REPLY 必须不上 UI 线程，否则 UI 线程在 evt.Wait 上会和 Dispatcher.Invoke 互锁
                try {
                    var quick = JObject.Parse(raw);
                    string qtype = quick["type"] != null ? quick["type"].ToString() : "";
                    // 2026-09-12 EDITOR_PATCH_ACK 跟 LOCK_REPLY 一样是"同步等回执",
                    //   同样不许上 UI 线程 —— UI 线程正卡在 evt.Wait 上。
                    if (qtype == "LOCK_REPLY" || qtype == "EDITOR_PATCH_ACK") {
                        string corrId = quick["corrId"] != null ? quick["corrId"].ToString() : "";
                        if (!string.IsNullOrEmpty(corrId)) {
                            lock (_lockSync) {
                                _lockReplies[corrId] = quick;
                                System.Threading.ManualResetEventSlim evt;
                                if (_lockWaiters.TryGetValue(corrId, out evt)) evt.Set();
                            }
                        }
                        return;
                    }
                } catch { }
                // 2026-06-17 性能修复: 改 BeginInvoke (异步), 不再阻塞 IO 线程.
                // 同步 Invoke 在 UI 线程忙 (硬件 0x7F 帧 / RaceTimer_Tick) 时会让 EditorSync IO 线程跟着卡死,
                // 间接导致硬件计时帧 backlog → 中间面板触板成绩/状态灯刷新不及时.
                Dispatcher.BeginInvoke((Action)delegate() { HandleEditorSyncMessage(raw); });
            };
            _editorSyncClient.OnConnected += delegate() {
                Dispatcher.BeginInvoke((Action)delegate() { OnEditorSyncConnected(); });
            };
            _editorSyncClient.OnDisconnected += delegate() {
                Dispatcher.BeginInvoke((Action)delegate() { OnEditorSyncDisconnected(); });
            };
            _editorSyncClient.OnLog += delegate(string s) {
                Dispatcher.BeginInvoke((Action)delegate() { AddLog(Loc.F("Str_Log_SyncPrefixFmt", s)); });
            };

            // 读 editor_sync.json：上次连接地址 + 是否自动重连
            try {
                string cfg = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "editor_sync.json");
                if (File.Exists(cfg)) {
                    var o = JObject.Parse(File.ReadAllText(cfg, Encoding.UTF8));
                    if (o["host"] != null && _editorSyncHostBox != null) _editorSyncHostBox.Text = o["host"].ToString();
                    bool auto = o["autoConnect"] != null && (bool)o["autoConnect"];
                    if (auto) Dispatcher.BeginInvoke((Action)delegate() { TryEditorSyncConnect(); });
                }
            } catch { }
        }

        private void TryEditorSyncConnect() {
            if (_editorSyncClient == null) return;
            try {
                string host = _editorSyncHostBox != null ? (_editorSyncHostBox.Text ?? "").Trim() : "127.0.0.1";
                if (string.IsNullOrEmpty(host)) host = "127.0.0.1";
                UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_Connecting"), "#F59E0B");
                _editorSyncClient.Connect(host, 3002);
                var hello = new JObject();
                hello["type"] = "EDITOR_IDENTITY";
                _editorSyncClient.Send(hello.ToString(Formatting.None));
                // 2026-06-17 RTC 模式: 额外发 TIMING_EXE_IDENTITY 让主服务器"系统工作状态" tab 显示 RTC 已连
                // 2026-09-14 顺带带上本机此刻是否真接着硬件(hwConnected) —— 主服务器据此
                //   判断"比赛控制"该让谁管, 不再只看"是不是 EXE 类型连接"。
                //   连上主服务器这一刻硬件多半还没连(操作员通常先连主服务器、再连硬件),
                //   所以这里大概率是 false; 真正的信号靠下面 OnStatusChanged 里的
                //   PushHwConnStatusToMainServer 在硬件真连上的那一刻补发。
                if (IsTimingClientMode) {
                    var rtcHello = new JObject();
                    rtcHello["type"] = "TIMING_EXE_IDENTITY";
                    rtcHello["hwConnected"] = (_timingBridge != null && _timingBridge.IsConnected);
                    // 2026-09-14 带上本机机器名, 让主服务器"连接状态"面板能明确标出
                    // "是哪台电脑"接着硬件, 不止是"有没有接"。
                    rtcHello["machine"] = Environment.MachineName;
                    _editorSyncClient.Send(rtcHello.ToString(Formatting.None));
                }
                // 2026-09-15 编排端(ScheduleEditor.exe)同样额外报一条专属身份 ——
                //   跟 query.html 一样借 EDITOR_IDENTITY 那条路拿整包/订阅补丁(不改),
                //   但那条身份是"信息查询终端"也在用的(见 query.html QUERY_IDENTITY),
                //   两者混在 _editorSockets 里主服务器分不出"连着的是编排端还是查询页"。
                //   这条专属身份只为"连接状态"面板单独计数, 不影响数据同步逻辑。
                if (IsScheduleEditorMode) {
                    var seHello = new JObject();
                    seHello["type"] = "SCHEDULE_EDITOR_IDENTITY";
                    _editorSyncClient.Send(seHello.ToString(Formatting.None));
                }
                SaveEditorSyncConfig(host, true);

                // 2026-08-28 计时端: 界面上这个「主服务器」框原来【只管 EditorSync】,
                //   不管竞赛数据服务(MeetDbBridge) —— 两套配置各走各的。
                //   后果很隐蔽: MeetDbBridge 没配 meet_service.json 就退回单机模式,
                //   自己开一个 meet.db, 【确认成绩会写进计时端自己的库】,
                //   主服务器那边什么都没有, 赛后才发现就晚了。
                //   所以这里把它一并配上, 并落盘, 下次开机自动生效。
                //
                // 2026-09-18 【这才是"编排记录及成绩处理"赛程导航/项目成绩打印跟主服务器
                //   一直不一致的真正病根】——上面一大段全是 EditorSyncClient(WebSocket,
                //   走 EDITOR_PACKAGE/EDITOR_PATCH 同步赛程/名单)那条独立的通道, 原来只有
                //   IsTimingClientMode(RTC/role=timing) 才顺带把 MeetDbBridge(_meetDb/_meet,
                //   IMeetService RPC 通道)也绑到同一个主服务器上；编排端连"主服务器"框
                //   点了"连接"、状态显示"已连接", 但那只连通了 EditorSyncClient 一条线,
                //   _meetDb.Service 压根没被重新指过, 一直是它自己那份【单机本地库】——
                //   这个会话里这几轮全部改成"经 _meet 读"的地方(赛程导航正在计时/已确认、
                //   项目成绩打印定稿状态、round/event 索引……)在编排端上因此全部还是在问
                //   自己本机那份过时的库, 表面上像是"没生效", 其实是根本没连到真身。
                //   编排端本身不计时、不推确认成绩/参数, 不需要 IsTimingClientMode 那批
                //   判断, 但它的【只读查询】必须经 _meet 问到真身, 所以单独把
                //   IsScheduleEditorMode 也加进来。
                if (IsTimingClientMode || IsScheduleEditorMode) BindMeetServiceToHost(host);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ConnectMainServerFailedFmt", ex.Message));
                UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_Offline"), "#94A3B8");
            }
        }

        /// <summary>
        /// 2026-09-14 【原则】哪台机器接着硬件计时器、正在做比赛计时控制，
        /// 哪台机器的"比赛控制"就是最高优先级 —— 不是"哪个是 EXE、哪个是网页"。
        /// RTC 每次硬件连接状态变化(连上/断开)都调这个, 把事实告诉主服务器;
        /// 主服务器据此决定自己该不该把「比赛控制」页让给远程(见 UpdateScoringControlMode)。
        /// </summary>
        private void PushHwConnStatusToMainServer() {
            if (!IsTimingClientMode) return;
            if (_editorSyncClient == null || !_editorSyncClient.IsConnected) return;
            try {
                var msg = new JObject();
                msg["type"] = "TIMING_EXE_HW_STATUS";
                msg["hwConnected"] = (_timingBridge != null && _timingBridge.IsConnected);
                msg["machine"] = Environment.MachineName;
                _editorSyncClient.Send(msg.ToString(Formatting.None));
            } catch { }
        }

        /// <summary>
        /// 2026-09-18 告诉主服务器"数据变了, 请转告你那边挂着的其它客户端"——
        /// 专给那些【不经 AutoSaveData】的变化用, 比如"准备就绪"把 heats.state 写成
        /// racing 这一步只经 _meet RPC 直接落库, 不落 JSON 存档, 自然不会触发
        /// AutoSaveData→PropagateSyncAfterSave 那条已有的 PushDataChanged 链路——
        /// 这类变化原来只能靠编排端/主服务器自己 10 秒一次的轮询追上, 用户明确反映过
        /// "更新有延迟"。本机是主服务器/单机时 _editorSyncClient 是 null, 静默跳过
        /// (本机自己的轮询本来就没有跨进程延迟这一说, 不需要这条)。
        /// </summary>
        private void NotifyRemoteDataChanged(string what) {
            if (_editorSyncClient == null || !_editorSyncClient.IsConnected) return;
            try {
                var msg = new JObject();
                msg["type"] = "CLIENT_DATA_CHANGED";
                msg["what"] = what ?? "";
                _editorSyncClient.Send(msg.ToString(Formatting.None));
            } catch { }
        }

        /// <summary>
        /// 把竞赛数据服务(MeetDbBridge)指到同一台主服务器, 并写进 meet_service.json。
        /// 已经开着库的话就重开一次, 否则这一场还是按单机在跑。
        /// </summary>
        private void BindMeetServiceToHost(string host) {
            try {
                if (string.IsNullOrWhiteSpace(host)) return;
                bool changed = !string.Equals(_meetDb.ServerHost ?? "", host, StringComparison.OrdinalIgnoreCase);
                _meetDb.ServerHost = host;
                _meetDb.ServerPort = 3002;

                // 落盘, 下次开机不用再点一次
                // 2026-09-18 【先读旧文件, 保留 Role 字段】—— 原来这里整份新建覆盖写,
                //   普通主程序配了 meet_service.json{"Role":"timing"} 才会走到这个函数
                //   (见 ApplyPlainTimingRoleMode/IsTimingClientMode), 点一次"连接"就把
                //   "Role":"timing" 连同整份文件一起覆盖没了——本次运行没事(角色在
                //   MachineRole 的静态缓存里已经读过一次), 但下次重启读这份文件时
                //   Role 字段已经不见了, 退回 standalone, 这一整套(主服务器工具栏/
                //   EditorSyncClient/推参数/推确认成绩)全部悄悄失效, 而且不报错。
                try {
                    string cfgPath = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "meet_service.json");
                    JObject o = null;
                    if (File.Exists(cfgPath)) {
                        try { o = JObject.Parse(File.ReadAllText(cfgPath, Encoding.UTF8)); } catch { }
                    }
                    if (o == null) o = new JObject();
                    o["Mode"] = "remote";
                    o["Host"] = host;
                    o["Port"] = 3002;
                    File.WriteAllText(cfgPath, o.ToString(Formatting.Indented), new UTF8Encoding(false));
                } catch (Exception ex) { AddLog(Loc.F("Str_Log_WriteMeetServiceJsonFailedFmt", ex.Message)); }

                // 已经开着(多半是刚才按单机开的)就重开, 让它真正连到主服务器
                if (changed && _meetDb.IsOpen && !string.IsNullOrEmpty(_competitionName)) {
                    if (_meetDb.Open(_competitionName))
                        AddLog(Loc.F("Str_Log_MeetDbSwitchedToMainFmt", host));
                    else
                        AddLog(Loc.T("Str_Log_MeetDbReopenFailed"));
                } else if (changed) {
                    AddLog(Loc.F("Str_Log_MeetDbPointsToMainFmt", host));
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_BindMeetServiceFailedFmt", ex.Message)); }
        }

        private void SaveEditorSyncConfig(string host, bool autoConnect) {
            try {
                var o = new JObject();
                o["host"] = host;
                o["autoConnect"] = autoConnect;
                File.WriteAllText(
                    IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "editor_sync.json"),
                    o.ToString(Formatting.Indented), Encoding.UTF8);
            } catch { }
        }

        private void EditorSyncToggle_Click(object sender, RoutedEventArgs e) {
            if (_editorSyncClient == null) return;
            if (_editorSyncClient.IsConnected) {
                _editorSyncClient.Disconnect();
                SaveEditorSyncConfig(_editorSyncHostBox != null ? (_editorSyncHostBox.Text ?? "").Trim() : "", false);
            } else {
                TryEditorSyncConnect();
            }
        }

        private void OnEditorSyncConnected() {
            UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_Connected"), "#22C55E");
            if (_editorSyncConnectButton != null) _editorSyncConnectButton.Content = Loc.T("Str_Btn_Disconnect");
            // 2026-08-29 服务器回来了 —— 把断线期间跑的组补上去。
            //   延后一点发: 身份帧(TIMING_WEB_IDENTITY)要先到, 否则服务器那边还没认人。
            if (IsTimingClientMode) {
                var t = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(1200) };
                t.Tick += delegate(object s2, EventArgs e2) {
                    t.Stop();
                    try { DrainPendingPush(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_DrainPendingPushFailedFmt", ex.Message)); }
                };
                t.Start();
            }
        }

        private void OnEditorSyncDisconnected() {
            UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_Offline"), "#94A3B8");
            if (_editorSyncConnectButton != null) _editorSyncConnectButton.Content = Loc.T("Str_Btn_Connect");
        }

        private void UpdateEditorSyncStatus(string text, string color) {
            if (_editorSyncStatusText != null) {
                _editorSyncStatusText.Text = text;
                try {
                    _editorSyncStatusText.Foreground =
                        new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));
                } catch { }
            }
        }

        // 2026-06-17 EDITOR_PACKAGE 节流 (去抖):
        //   主服务器有任何风吹草动就推一次整包, RTC 收到立即 ApplyPackageInMemory 会做"序列化 → 写盘 → LoadCompetitionFromFile"
        //   全量重建, 极其昂贵, 在 UI 线程上跑 → 硬件 0x7F 帧排队. 这里改成:
        //   收到 package 缓存到 _pendingPackage, 启动 1500ms 计时器; 期间又来新包替换 _pendingPackage 重置计时器;
        //   计时器 Tick 时才真正应用最新一份. 用户感觉是"最后一次主服务器改动 1.5s 后生效", 完全可接受.
        private CompetitionPackage _pendingPackage;
        // 2026-08-24 上一次推给主服务器被拒(计时中) → 本地改动尚未提交
        private bool _editorPushRejected = false;
        private DispatcherTimer _packageApplyDebounceTimer;
        // 2026-09-19 用户明确要求: 正在比的这一组用的当前组临时数据库(current_heat.db)
        //   在比赛期间绝对不能被重建——收到的整包同步不是"想办法安全地应用", 是【压根
        //   不给它应用的机会】, 原样按下不表, 存在这里, 等这一组确认/取消(LiveActive
        //   变回 false)后由 DbPoll_Tick 自动补上。见 PackageApplyDebounceTick 的说明。
        private CompetitionPackage _deferredEditorPackage;

        // 编排端：收到主服务器推过来的 EDITOR_PACKAGE → 覆盖本地（_applyingRemoteSync 防回环）
        private void HandleEditorSyncMessage(string raw) {
            try {
                var msg = JObject.Parse(raw);
                string type = msg["type"] != null ? msg["type"].ToString() : "";
                // 2026-09-28【跨客户端语言同步】主服务器权威语言状态(切换那一刻广播 / 本机
                //   刚连上补发一次)。只应用, 不再往下转发——这条消息只在"真身主服务器→桌面exe"
                //   这一个方向传递, 这里(ScheduleEditor.exe/RemoteTimingControl.exe)是终点。
                if (type == "LANGUAGE_SYNC") {
                    string lang = msg["lang"] != null ? msg["lang"].ToString() : Loc.Zh;
                    if (Loc.SetLanguage(lang)) RefreshAllForLanguageChange();
                    return;
                }
                // 2026-08-24 主服务器拒绝了本次保存(计时中/成绩未确认)。
                //   原来是静默失败, 操作员以为存上了, 实际主服务器没收 —— 必须弹出来。
                if (type == "EDITOR_PUSH_REJECTED") {
                    string reason = msg["reason"] != null ? msg["reason"].ToString() : "主服务器暂时不能接收修改";
                    _editorPushRejected = true;
                    UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_NotSavedToServer"), "#DC2626");
                    AddLog(Loc.F("Str_Log_NotSavedToMainServerFmt", reason));
                    AppMessageBox.Show(
                        Loc.F("Str_Msg_NotSavedToServerFmt", reason),
                        Loc.T("Str_MsgTitle_NotSavedToServer"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                if (type == "HEAT_CONFIRMED_ACK") { HandleHeatConfirmedAck(msg); return; }
                // 2026-09-18 主服务器"数据真变了"的轻量通知(几十字节, PushDataChanged 发的)——
                //   网页端(race_control.html 等)早就认这条、收到就立刻去取新状态; 这个 WPF
                //   exe 这一侧的 EditorSyncClient 接的是同一路消息, 却从没接过线, 一直只能
                //   干等 10 秒一次的 DbPoll_Tick 轮询才追得上, 这才是编排端"数据更新有延迟"
                //   的根子。直接复用 DbPoll_Tick 的判断(比赛中不动、有变化才推大屏)——
                //   等于把"轮询"从"固定 10 秒一次"改成"固定 10 秒一次 + 数据一变立刻多补一次",
                //   平时那句"不给主服务器太大压力"的初衷不变, 只是变化发生的那一刻不用再等。
                if (type == "DATA_CHANGED") { DbPoll_Tick(null, EventArgs.Empty); return; }
                // 2026-09-12 主服务器转来的并组补丁(别的编排端做的)。照着改本机,
                //   不要整包 —— 整包会把正在看的这份数据整批换掉。
                if (type == "EDITOR_PATCH") {
                    string perr;
                    if (ApplyPatch(msg, out perr)) AddLog(Loc.T("Str_Log_PatchFromMainServerApplied"));
                    else AddLog(Loc.F("Str_Log_PatchFromMainServerFailedFmt", perr));
                    return;
                }
                if (type == "EDITOR_PACKAGE") {
                    var pkgToken = msg["package"];
                    if (pkgToken == null) return;
                    var package = pkgToken.ToObject<CompetitionPackage>();
                    if (package == null) return;
                    _pendingPackage = package;
                    UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_Receiving"), "#F59E0B");
                    if (_packageApplyDebounceTimer == null) {
                        _packageApplyDebounceTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(1500) };
                        _packageApplyDebounceTimer.Tick += PackageApplyDebounceTick;
                    }
                    _packageApplyDebounceTimer.Stop();
                    _packageApplyDebounceTimer.Start();
                }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_SyncMsgHandleFailedFmt", ex.Message));
            }
        }

        private void PackageApplyDebounceTick(object sender, EventArgs e) {
            _packageApplyDebounceTimer.Stop();
            var pkg = _pendingPackage;
            _pendingPackage = null;
            // 2026-08-24 上次保存被主服务器拒了(本地改动还没提交上去), 这时如果直接套用
            //   主服务器推来的包, 本地改动就被悄无声息地覆盖掉了。先问一句。
            if (_editorPushRejected && pkg != null) {
                var ans = AppMessageBox.Show(
                    Loc.T("Str_Msg_LocalUnsavedConfirm"),
                    Loc.T("Str_MsgTitle_LocalUnsaved"), MessageBoxButton.YesNo, MessageBoxImage.Warning);
                if (ans != MessageBoxResult.Yes) {
                    AddLog(Loc.T("Str_Log_KeptLocalUnsubmitted"));
                    UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_LocalUncommitted"), "#DC2626");
                    return;
                }
                _editorPushRejected = false;
            }
            if (pkg == null) return;
            // 2026-09-19 【用户明确要求, 按此重做】正在比的这一组, 当前组临时数据库
            //   (current_heat.db, _meetDb.LiveActive 为 true 期间)绝对不能被重建——
            //   之前"重建前摘成绩、重建完再贴回去"的补救办法, 用户认为比赛实时性太强,
            //   摘/贴两步之间理论上仍有缝隙, 算不上万无一失。这次改成釜底抽薪: LiveActive
            //   还是 true 就【原样按下不表】, ApplyPackageInMemory 一次都不跑, 存进
            //   _deferredEditorPackage, 等这一组确认成绩/取消(LiveActive 变回 false,
            //   数据这时候已经安全地写进 meet.db 了, "临时数据库使命完成")才由
            //   DbPoll_Tick 自动补上——不是"重建后恢复", 是压根不给它发生的机会。
            //   赛前(LiveActive 是 false)收到的整包照旧立即应用, 不受影响。
            if (_meetDb.LiveActive) {
                _deferredEditorPackage = pkg;
                UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_PausedDuringRace"), "#F59E0B");
                AddLog(Loc.T("Str_Log_MainPackageDeferredLiveActive"));
                return;
            }
            try {
                ApplyPackageInMemory(pkg);
                UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_Synced"), "#22C55E");
                AddLog(Loc.T("Str_Log_MainPackageAppliedThrottled"));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ApplySyncPackageFailedFmt", ex.Message));
            }
        }

        private string GetDatePickerText(DatePicker dp) {
            if (dp == null || dp.SelectedDate == null) return "";
            return dp.SelectedDate.Value.ToString("yyyy-MM-dd");
        }

        private void SetDatePicker(DatePicker dp, string dateStr) {
            if (dp == null) return;
            DateTime dt;
            if (!string.IsNullOrEmpty(dateStr) && DateTime.TryParse(dateStr, out dt))
                dp.SelectedDate = dt;
            else
                dp.SelectedDate = null;
        }

        // 2026-10-05 国际游泳竞赛规则英文规范 —— 性别/赛次/组数的标准英文默认值, 字段初始化器
        //   和"恢复默认"按钮共用同一份, 避免两处写法分叉。沿用 Loc.GenderDisplay/StageDisplay
        //   已有的英文词汇("Men"/"Women"/"Mixed"、"Prelim"/"Semifinal"/"Final"), 哨兵值=显示值。
        private static List<string> DefaultGenders() {
            return (Loc.CurrentLanguage == Loc.En)
                ? new List<string> { "Men", "Women", "Mixed" }
                : new List<string> { "男", "女", "混合" };
        }
        private static List<string> DefaultStages() {
            return (Loc.CurrentLanguage == Loc.En)
                ? new List<string> { "Prelim", "Semifinal", "Final" }
                : new List<string> { "预赛", "半决赛", "决赛" };
        }
        private static List<string> DefaultHeatCounts() {
            var list = new List<string>();
            for (int n = 1; n <= 8; n++) list.Add(Loc.F("Str_HeatCountSuffixFmt", n));
            return list;
        }
        // 项目名用标准国际泳联英文术语(50m Freestyle / 4x100m Medley Relay 等); "个人混合泳"/
        //   "混合泳接力" 都含"混合泳(Medley)"子串、"接力"对应"Relay"子串——特意保持跟中文
        //   同构, 全系统靠 .Contains("接力")/.Contains("混合泳") 判断接力/混氧泳项目的逻辑,
        //   换成英文哨兵值后用 .Contains("Relay")/.Contains("Medley") 能保持同样的判断结构
        //   (这批判断逻辑本身是否要跟着改, 属于后续专项工作, 这里只负责给出正确的英文默认值)。
        private static List<string> DefaultEvents() {
            if (Loc.CurrentLanguage == Loc.En) {
                return new List<string> {
                    "50m Freestyle", "100m Freestyle", "200m Freestyle", "400m Freestyle",
                    "800m Freestyle", "1500m Freestyle",
                    "50m Backstroke", "100m Backstroke", "200m Backstroke",
