        private void InitializeData() {
            SwimmerGrid.ItemsSource = _swimmers;
            RelayGrid.ItemsSource = _relayTeams;
            RebuildRelayGroupedView();
            // ScheduleGrid replaced by ScheduleGroupedPanel
            RecordGrid.ItemsSource = _records;
            RefreshRecordFilterCombos();

            // 初始化默认项目列表
            _events = DefaultEvents();
            _ageGroups = DefaultAgeGroups();
            AgeGroupRegistry.Set(_ageGroups);
            RefreshEventComboBoxes();
            RefreshEventsPreview();
            RefreshAgeGroupsPreview();
            RefreshAllAgeGroupFilterCombos();
            RefreshDisplayRecordLabelText();
            RefreshUnitComboBox();
            if (RegEventCombo != null && RegEventCombo.Items.Count > 0) RegEventCombo.SelectedIndex = 0;

            // 初始化泳道设备状态
            InitLaneDeviceStates();

            // 显示服务器地址 (RTC / ScheduleEditor 是客户端, 不开服务, 改为显示角色而不是 ws/http URL)
            string ip = GetLocalIP();
            if (IsRemoteTimingControlMode) {
                ServerAddressText.Text = Loc.T("Str_Mode_RtcDesc");
            } else if (IsScheduleEditorMode) {
                ServerAddressText.Text = Loc.T("Str_Mode_ScheduleEditorDesc");
            } else {
                ServerAddressText.Text = Loc.F("Str_Mode_MainServerAddrFmt", ip);
            }
        }

        private void InitLaneDeviceStates() {
            _laneDeviceStates.Clear();
            foreach (int lane in _poolConfig.LaneNumbers) {
                _laneDeviceStates.Add(new LaneDeviceState { Lane = lane });
            }
            ApplyTouchpadInstallModeToLanes();
            // 2026-08-31 盲表数量也要重新套用 —— 原来只套触板, 这里是个不对称。
            //   本函数在【加载赛事包】(联机时主服务器一推包就触发) 和改泳道数时都会调,
            //   新建的 LaneDeviceState 全是默认值, 用户设的"每侧 2 个"就这么没了:
            //   当前组还是对的(内存里已经改过), 换到下一组重建界面就变回 3 个。
            ApplyBlindWatchCountToLanes();
        }

        /// <summary>
        /// 2026-08-31 把"每侧盲表数量"套到每道的 NotInstalled 标志上。
        /// 只管【装没装】, 不碰 Broken —— 坏表是现场标的, 不能被数量设置冲掉。
        /// </summary>
        /// <summary>
        /// 2026-08-31 计时端改完参数后, 把整份参数推给主服务器【让它自己也应用】。
        ///
        /// 原来只有 Broadcast() —— 它在 RTC 模式下会包成 RTC_FORWARD 推过去, 但主服务器
        /// 收到 RTC_FORWARD 只做一件事: EnqueueToAll 转发给大屏/网页。【它自己的
        /// _laneCloseSettings 和 device_states.json 一个字都没改】。
        /// 结果就是: 计时端上改的盲表数量/时间参数, 主服务器那边根本不知道,
        /// 重启或切回主服务器控制时又变回旧值, 而且全程不报错。
        ///
        /// 信封跟网页端 race_control.html 的 sendCmd 完全一样 (TIMING_CMD +
        /// SET_LANE_CLOSE_SETTINGS), 走的是主服务器已有的处理分支, 不新增协议。
        /// </summary>
        private void PushSettingsToServer() {
            if (!IsTimingClientMode) return;
            if (_editorSyncClient == null || !_editorSyncClient.IsConnected) {
                AddLog(Loc.T("Str_Log_NotConnectedMainServerParamsLocal"));
                return;
            }
            try {
                // 2026-08-31 【全量推送】—— 主服务器 SET_LANE_CLOSE_SETTINGS 能接的
                //   19 个字段一个不落。第一版只发了 6 个, 剩下的照样到不了主服务器,
                //   等于只修了盲表, 别的参数还是老毛病。参数设置里的每一项都要能同步。
                var d = new JObject();
                d["laneCloseTime"]            = _laneCloseSettings.LaneCloseTime;
                d["startBlockCloseDelay"]     = _laneCloseSettings.StartBlockCloseDelay;
                d["resultConfirmCloseDelay"]  = _laneCloseSettings.ResultConfirmCloseDelay;
                d["falseStartThreshold"]      = _laneCloseSettings.FalseStartThreshold;
                d["relayHandoffFalseStartThreshold"] = _laneCloseSettings.RelayHandoffFalseStartThreshold;
                d["splitDisplayTime"]         = _laneCloseSettings.SplitDisplayTime;
                d["blindReplaceDelay"]        = _laneCloseSettings.BlindReplaceDelay;
                d["firstPlaceHoldTime"]       = _laneCloseSettings.FirstPlaceHoldTime;
                d["reactionEventWindowSec"]   = _laneCloseSettings.ReactionEventWindowSec;
                d["bigDisplayPageInterval"]   = _laneCloseSettings.BigDisplayPageInterval;
                d["leftBlindWatchCount"]      = _laneCloseSettings.LeftBlindWatchCount;
                d["rightBlindWatchCount"]     = _laneCloseSettings.RightBlindWatchCount;
                d["startPosition"]            = _laneCloseSettings.StartPosition ?? "";
                d["laneOrder"]                = _laneCloseSettings.LaneOrder ?? "";
                d["reactionTimeEnabled"]      = _laneCloseSettings.ReactionTimeEnabled;
                d["hardwareAlwaysOpen"]       = _laneCloseSettings.HardwareAlwaysOpen;
                d["autoBlindReplaceTouchpad"] = _laneCloseSettings.AutoBlindReplaceTouchpad;
                d["manualTpReplaceTp"]        = _laneCloseSettings.ManualTpReplaceTp;
                d["startBoxEdgeFalling"]      = _laneCloseSettings.StartBoxEdgeFalling;
                // 触板单端/两端: 服务器那边用 poolSingleSide 表示, 与 HasRightStartBlock 相反
                d["poolSingleSide"]           = !_laneCloseSettings.HasRightStartBlock;
                var env = new JObject();
                env["type"]    = "TIMING_CMD";
                env["command"] = "SET_LANE_CLOSE_SETTINGS";
                env["data"]    = d;
                _editorSyncClient.Send(env.ToString(Formatting.None));
                AddLog(Loc.F("Str_Log_ParamsPushedToMainFmt",
                    _laneCloseSettings.LeftBlindWatchCount, _laneCloseSettings.RightBlindWatchCount,
                    _laneCloseSettings.LaneCloseTime, _laneCloseSettings.StartBlockCloseDelay,
                    _laneCloseSettings.ResultConfirmCloseDelay));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ParamsPushFailedFmt", ex.Message));
            }
        }

        private void ApplyBlindWatchCountToLanes() {
            if (_laneCloseSettings == null || _laneDeviceStates == null) return;
            int l = _laneCloseSettings.LeftBlindWatchCount;
            int r = _laneCloseSettings.RightBlindWatchCount;
            foreach (var st in _laneDeviceStates) {
                st.LeftBlindWatch1NotInstalled  = (l < 1);
                st.LeftBlindWatch2NotInstalled  = (l < 2);
                st.LeftBlindWatch3NotInstalled  = (l < 3);
                st.RightBlindWatch1NotInstalled = (r < 1);
                st.RightBlindWatch2NotInstalled = (r < 2);
                st.RightBlindWatch3NotInstalled = (r < 3);
            }
        }

        // 2026-05-13 电池电压显示：把 _hwBatteryVoltage 渲染到顶部状态栏 TimingHwConnText 旁
        // 没有专门控件时退到 AddLog 提示；用现成的 TimingStatusText 作为"硬件状态"载体追加电压串
        //
        // 2026-05-13(2) 阈值按 硬件实际电池 = 7.4V 标称（2 节锂电串联）调整：
        //   单节锂电  3.0V (耗尽截止) / 3.5V (低) / 3.7V (标称) / 4.2V (满充)
        //   2 节合计  6.0V (危险)    / 7.0V (低) / 7.4V (标称) / 8.4V (满充)
        //   显示阈值：
        //       < 7.00 V          → 红 (严重低电，请立即更换/充电)
        //       7.00 V – 7.40 V   → 琥珀色 (偏低，注意监视)
        //       ≥ 7.40 V          → 绿 (健康)
        //   旧 11.0V/11.5V 阈值适用于 12V 标称电池组(3 节)，不适配本机 7.4V 包。
        private const double BATTERY_CRITICAL_V = 7.00;   //红色阈值
        private const double BATTERY_LOW_V      = 7.40;   //琥珀阈值

        private void UpdateBatteryVoltageDisplay() {
            try {
                bool fresh = _hwBatteryVoltage > 0 && (DateTime.Now - _hwBatteryReceivedAt).TotalSeconds < 30;
                SolidColorBrush voltBrush;
                string voltText;
                if (fresh) {
                    voltText = string.Format("{0:F2} V", _hwBatteryVoltage);
                    if (_hwBatteryVoltage < BATTERY_CRITICAL_V)
                        voltBrush = new SolidColorBrush(Colors.Red);
                    else if (_hwBatteryVoltage < BATTERY_LOW_V)
                        voltBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B"));
                    else
                        voltBrush = new SolidColorBrush(Colors.LimeGreen);
                } else {
                    voltText = "—";
                    voltBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8"));
                }
                //2026-05-14 新增"系统硬件"栏专属电压显示控件
                if (BatteryVoltageText != null) {
                    BatteryVoltageText.Text = voltText;
                    BatteryVoltageText.Foreground = voltBrush;
                }
                // 同时仍刷一份到 TimingStatusText（系统状态 Tab 的"硬件计时器连接"区显示）
                if (TimingStatusText != null) {
                    string baseText = (_timingBridge != null) ? _timingBridge.StatusText : "未连接";
                    if (fresh) {
                        TimingStatusText.Text = string.Format("{0}  ｜ 电池: {1}", baseText, voltText);
                        TimingStatusText.Foreground = voltBrush;
                    } else {
                        TimingStatusText.Text = baseText;
                    }
                }
            } catch { }
        }

        // 2026-05-14 把"单端 / 两端"安装方式落到每条泳道的设备状态：
        //   两端 (HasRightStartBlock=true)：两端所有设备 NotInstalled 标记全部清除
        //   单端 (HasRightStartBlock=false)：终点端 NotInstalled 清除；非终点端整列设备 NotInstalled=true
        //         （硬件约定 PoolSingleOrDoubleTPbit=1 时把 1-FinalPlace 端标 4(未安装)，本端代码与之对齐）
        // 用 NotInstalled flag（而不是直接改 _xxStatus）—— 这样 ResetForNewRace / OpenAll / CloseAll
        // 等流程把 status 重置为 Closed/Open 时不会覆盖"未安装"语义。
        private void ApplyTouchpadInstallModeToLanes() {
            bool dualEnd = _poolConfig != null && _poolConfig.HasRightStartBlock;
            bool finishIsLeft = _laneCloseSettings == null || _laneCloseSettings.FinishPosition != "right";
            // 单端时，非终点端整列未安装
            bool markRightNotInstalled = !dualEnd && finishIsLeft;
            bool markLeftNotInstalled  = !dualEnd && !finishIsLeft;
            foreach (var st in _laneDeviceStates) {
                // 左端
                st.LeftTouchpadNotInstalled   = markLeftNotInstalled;
                st.LeftStartBlockNotInstalled = markLeftNotInstalled;
                st.LeftBlindWatch1NotInstalled = markLeftNotInstalled;
                st.LeftBlindWatch2NotInstalled = markLeftNotInstalled;
                st.LeftBlindWatch3NotInstalled = markLeftNotInstalled;
                // 右端
                st.RightTouchpadNotInstalled   = markRightNotInstalled;
                st.RightStartBlockNotInstalled = markRightNotInstalled;
                st.RightBlindWatch1NotInstalled = markRightNotInstalled;
                st.RightBlindWatch2NotInstalled = markRightNotInstalled;
                st.RightBlindWatch3NotInstalled = markRightNotInstalled;
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // WebSocket 服务器
        // ═══════════════════════════════════════════════════════════════
        // 2026-06-17 启动前先探测 3002 端口是否被占 (常见于主服务器 + RTC 跑在同一台机器):
        //   被占则 Fleck 仍会"启动成功"但无法接受连接, 大屏静默拿不到数据, 极难排查.
        //   主动 TcpListener 试绑能立刻发现冲突, RTC 模式下弹框提示用户.
        private static bool IsPort3002Occupied() {
            System.Net.Sockets.TcpListener probe = null;
            try {
                probe = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Any, 3002);
                probe.Start();
                return false;
            } catch (System.Net.Sockets.SocketException) {
                return true;
            } catch { return false; } finally {
                try { if (probe != null) probe.Stop(); } catch { }
            }
        }

        // 2026-06-18 每客户端独立发送队列 + 后台 worker, 防止慢 socket (弱 Wi-Fi) 拖累整体广播链.
        //   旧版用 lock _broadcastSerialLock + foreach s.Send 同步串行 → 1 个慢 socket 阻塞 200ms,
        //   N 帧 × M 客户端 → 10Hz 帧累积排队几秒到十几秒 → 大屏延迟清零.
        //   新版每 socket 一个 ConcurrentQueue + Task worker: 慢的自己堵, 不影响其他 socket;
        //   队列深度 >100 时丢最旧的, SHOW_LIVE_RACE 是全量快照丢中间无影响.
        private class SocketSender {
            public IWebSocketConnection Socket;
            public ConcurrentQueue<string> Queue = new ConcurrentQueue<string>();
            public ManualResetEventSlim Signal = new ManualResetEventSlim(false);
            public CancellationTokenSource Cts = new CancellationTokenSource();
            public Task Worker;
            public const int MaxQueueDepth = 100;
        }
        private readonly Dictionary<IWebSocketConnection, SocketSender> _socketSenders =
            new Dictionary<IWebSocketConnection, SocketSender>();
        private readonly object _socketSendersLock = new object();

        private void RegisterSocketSender(IWebSocketConnection socket) {
            var sender = new SocketSender { Socket = socket };
            lock (_socketSendersLock) _socketSenders[socket] = sender;
            sender.Worker = Task.Run(() => SenderLoop(sender));
        }

        private void UnregisterSocketSender(IWebSocketConnection socket) {
            SocketSender sender;
            lock (_socketSendersLock) {
                if (!_socketSenders.TryGetValue(socket, out sender)) return;
                _socketSenders.Remove(socket);
            }
            try { sender.Cts.Cancel(); sender.Signal.Set(); } catch { }
        }

        private void SenderLoop(SocketSender sender) {
            try {
                while (!sender.Cts.IsCancellationRequested) {
                    string msg;
                    if (!sender.Queue.TryDequeue(out msg)) {
                        try { sender.Signal.Wait(500, sender.Cts.Token); } catch { }
                        try { sender.Signal.Reset(); } catch { }
                        continue;
                    }
                    try { sender.Socket.Send(msg); } catch { break; }   // 发送失败 → 退出, OnClose 会清理
                }
            } catch { }
        }

        // 把消息入队到所有已连接的 socket. 主线程 microsec 级返回, 各 socket worker 异步发送.
        private void EnqueueToAll(string json) {
            if (string.IsNullOrEmpty(json)) return;
            lock (_socketSendersLock) {
                foreach (var sender in _socketSenders.Values) {
                    // 队列超深 → 丢最旧的, 避免慢 socket 无限积压
                    if (sender.Queue.Count >= SocketSender.MaxQueueDepth) {
                        string discard;
                        sender.Queue.TryDequeue(out discard);
                    }
                    sender.Queue.Enqueue(json);
                    try { sender.Signal.Set(); } catch { }
                }
            }
        }

        // 入队到指定 socket. OnOpen 喂初始快照 / BroadcastSingle 用此.
        private void EnqueueToSocket(IWebSocketConnection socket, string json) {
            if (socket == null || string.IsNullOrEmpty(json)) return;
            SocketSender sender;
            lock (_socketSendersLock) { _socketSenders.TryGetValue(socket, out sender); }
            if (sender == null) { try { socket.Send(json); } catch { } return; }
            if (sender.Queue.Count >= SocketSender.MaxQueueDepth) {
                string discard;
                sender.Queue.TryDequeue(out discard);
            }
            sender.Queue.Enqueue(json);
            try { sender.Signal.Set(); } catch { }
        }

        // 2026-09-15 【广播分级】入队到"这一组"socket, 不是全体。
        //   TP/SB/MB 设备状态、泳道事件日志、0.1s 滚动时间、比赛实况精简帧这几路
        //   原来一律 EnqueueToAll —— 检录台/信息查询/排名屏/报名终端/显示控制/编排端
        //   全都收到, 而它们的页面代码根本不处理这些类型, 白白经过序列化+网络+解析
        //   一趟, 收到即丢。这几路的真正订阅者只有"大屏"(_displaySockets)、
        //   "比赛控制网页"(_timingWebSockets)、"显示控制端"(_displayControlSockets)
        //   这三类里的几种组合, 见各调用点注释。
        private void EnqueueToSet(IEnumerable<IWebSocketConnection> targets, string json) {
            if (string.IsNullOrEmpty(json) || targets == null) return;
            foreach (var s in targets) EnqueueToSocket(s, json);
        }

        private void InitializeWebSocketServer() {
            // 2026-06-17 方案 B: RTC 模式不再开 WebSocket Server.
            //   display.html / race_control.html 改为连主服务器, RTC 通过 EditorSyncClient
            //   把比赛状态 (SHOW_LIVE_RACE 等) 推给主服务器, 主服务器再分发给 display 客户端.
            //   这样 RTC UI 线程不必处理 display.html 的高频 WebSocket 消息, 大幅降负载.
            if (IsRemoteTimingControlMode) {
                AddLog(Loc.T("Str_Log_RtcNoLocalWs"));
                return;
            }
            if (IsPort3002Occupied()) {
                string msg = Loc.T("Str_Msg_Port3002Occupied");
                AddLog(Loc.F("Str_Log_SeverePrefixFmt", msg.Replace("\r\n", " ")));
                if (IsRemoteTimingControlMode) {
                    try {
                        Dispatcher.BeginInvoke((Action)delegate() {
                            AppMessageBox.Show(this, msg, Loc.T("Str_MsgTitle_PortConflict"),
                                MessageBoxButton.OK, MessageBoxImage.Warning);
                        });
                    } catch { }
                }
                return;
            }
            try {
                _server = new WebSocketServer("ws://0.0.0.0:3002");
                _server.Start(delegate(IWebSocketConnection socket) {
                    socket.OnOpen = delegate() {
                        _allSockets.Add(socket);
                        // 2026-06-18 per-socket 发送队列, 防慢 socket 拖累整体
                        RegisterSocketSender(socket);
                        Dispatcher.Invoke((Action)delegate() {
                            AddLog(Loc.F("Str_Log_ClientConnectedFmt", socket.ConnectionInfo.ClientIpAddress));
                            UpdateConnectionStatus();
                        });
                        // 2026-06-17 方案 B: 若有 RTC 主控推过来的完整快照, 优先发给新客户端,
                        //   避免显示空白等待下次事件触发. 没有快照时回退到本机 BroadcastSingle.
                        // ── 2026-09-13 新客户端一律用【本机这份完整数据】开局 ──────────
                        //   原来优先发 _lastRtcSnapshot(RTC 转发过来的最近一帧完整包)。
                        //   现在 RTC 平时只发精简帧, 而切显示模式时发的是【大屏专用包】——
                        //   拿任何一种当新客户端的底子都是错的: 精简帧没有名单/赛程,
                        //   大屏专用包也没有, 非大屏客户端(比赛控制页/查询页)收到就把
                        //   自己那份静态数据冲空了。
                        //   主服务器手里的才是静态数据的权威来源, 直接发它;
                        //   实况字段下一帧(100ms)就到, 不差这一下。
                        BroadcastSingle(socket);
                    };
                    socket.OnClose = delegate() {
                        UnregisterSocketSender(socket);   // 2026-06-18 停 sender worker
                        _allSockets.Remove(socket);
                        _displaySockets.Remove(socket);
                        _leaderboardSockets.Remove(socket);
                        _registerSockets.Remove(socket);
                        _timingExeSockets.Remove(socket);
                        _timingExeInfo.Remove(socket);
                        _timingWebSockets.Remove(socket);
                        _editorSockets.Remove(socket);
                        _querySockets.Remove(socket);
                        _checkinSockets.Remove(socket);
                        _displayControlSockets.Remove(socket);
                        _scheduleEditorSockets.Remove(socket);
                        _registrationToolSockets.Remove(socket);
                        _rdcSockets.Remove(socket);
                        // 客户端断开 → 释放其持有的所有编辑锁，避免数据被永久锁死
                        ReleaseLocksHeldBy(socket);
                        Dispatcher.Invoke((Action)delegate() {
                            UpdateScoringControlMode();
                            UpdateConnectionStatus();
                            // 2026-09-13 计时端(EXE)全断了 → "当前比赛"那块回归本机, 别停在它最后那一组
                            if (_timingExeSockets.Count == 0) ClearRtcRaceDisplay("计时端已退出");
                        });
                    };
                    socket.OnMessage = delegate(string message) {
                        Dispatcher.Invoke((Action)delegate() {
                            HandleMessage(socket, message);
                        });
                    };
                });
                AddLog(Loc.T("Str_Log_WsServerStarted"));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_WsStartFailedFmt", ex.Message));
            }
        }

        // 2026-06-17 HTTP 文件服务: 主服务器 / RTC 模式下都开, 服务 Web/ 子目录下的 display.html / race_control.html 等
        //   端口 8080. 浏览器访问 http://<主控IP>:8080/display.html 即可看大屏.
        //   注: HttpListener "http://+:port/" 在 Windows 需要 URL ACL (netsh http add urlacl) 或管理员权限.
        //   失败时回退到 http://localhost:8080/ (只本机能访问).
        private System.Net.HttpListener _httpFileServer;
        private System.Threading.Thread _httpFileServerThread;
        private void InitializeHttpFileServer() {
            // 2026-06-17 方案 B: RTC 模式不再开 HTTP 文件服务.
            //   display.html / race_control.html 改为从主服务器 http://主服务器IP:8080/display.html 取.
            if (IsRemoteTimingControlMode) {
                AddLog(Loc.T("Str_Log_RtcNoLocalHttp"));
                return;
            }
            try {
                _httpFileServer = new System.Net.HttpListener();
                _httpFileServer.Prefixes.Add("http://+:8080/");
                _httpFileServer.Start();
                AddLog(Loc.T("Str_Log_HttpServerStarted"));
            } catch (Exception ex1) {
                AddLog(Loc.F("Str_Log_HttpRemoteBindFailedFmt", ex1.Message));
                try {
                    _httpFileServer = new System.Net.HttpListener();
                    _httpFileServer.Prefixes.Add("http://localhost:8080/");
                    _httpFileServer.Start();
                    AddLog(Loc.T("Str_Log_HttpDegradedLocalOnly"));
                } catch (Exception ex2) {
                    AddLog(Loc.F("Str_Log_HttpServerStartFailedFmt", ex2.Message));
                    _httpFileServer = null;
                    return;
                }
            }
            _httpFileServerThread = new System.Threading.Thread(HttpFileServerLoop);
            _httpFileServerThread.IsBackground = true;
            _httpFileServerThread.Start();
        }
        private void HttpFileServerLoop() {
            string webRoot = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Web");
            while (_httpFileServer != null && _httpFileServer.IsListening) {
                System.Net.HttpListenerContext ctx = null;
                try { ctx = _httpFileServer.GetContext(); }
                catch { break; }
                try {
                    string urlPath = ctx.Request.Url.AbsolutePath.TrimStart('/');
                    if (string.IsNullOrEmpty(urlPath)) urlPath = "display.html";
                    urlPath = urlPath.Replace("..", "").Replace("\\", "/");
                    string fullPath = System.IO.Path.Combine(webRoot, urlPath.Replace("/", System.IO.Path.DirectorySeparatorChar.ToString()));
                    if (System.IO.File.Exists(fullPath)) {
                        byte[] bytes = System.IO.File.ReadAllBytes(fullPath);
                        string ext = (System.IO.Path.GetExtension(fullPath) ?? "").ToLower();
                        ctx.Response.ContentType =
                              ext == ".html" || ext == ".htm" ? "text/html; charset=utf-8"
                            : ext == ".css"  ? "text/css; charset=utf-8"
                            : ext == ".js"   ? "application/javascript; charset=utf-8"
                            : ext == ".json" ? "application/json; charset=utf-8"
                            : ext == ".png"  ? "image/png"
                            : ext == ".jpg" || ext == ".jpeg" ? "image/jpeg"
                            : ext == ".gif"  ? "image/gif"
                            : ext == ".svg"  ? "image/svg+xml; charset=utf-8"
                            : ext == ".ico"  ? "image/x-icon"
                            : ext == ".woff" ? "font/woff" : ext == ".woff2" ? "font/woff2"
                            : ext == ".ttf"  ? "font/ttf"  : ext == ".otf"   ? "font/otf"
                            : ext == ".mp4"  ? "video/mp4" : ext == ".webm" ? "video/webm"
                            : "application/octet-stream";
                        // ── 2026-09-13 网页一律不许进浏览器缓存 ────────────────
                        //   "旧页面配新 exe"的真正来源不是忘了拷文件, 而是【浏览器缓存】:
                        //   HttpListener 默认一个缓存头都不发, 浏览器就按自己的启发式规则
                        //   把 html/js 留着用, 盘上的文件早换了, 屏幕上跑的还是上一版。
                        //   页面就那几十 KB, 每次重取一遍不值一提; 图片/字体/视频照旧可缓存。
                        if (ext == ".html" || ext == ".htm" || ext == ".js" || ext == ".css") {
                            ctx.Response.Headers["Cache-Control"] = "no-cache, no-store, must-revalidate";
                            ctx.Response.Headers["Pragma"] = "no-cache";
                            ctx.Response.Headers["Expires"] = "0";
                        }
                        ctx.Response.ContentLength64 = bytes.Length;
                        ctx.Response.OutputStream.Write(bytes, 0, bytes.Length);
                    } else {
                        ctx.Response.StatusCode = 404;
                        byte[] body = System.Text.Encoding.UTF8.GetBytes("404 Not Found: " + urlPath);
                        ctx.Response.ContentLength64 = body.Length;
                        ctx.Response.OutputStream.Write(body, 0, body.Length);
                    }
                    ctx.Response.Close();
                } catch { try { if (ctx != null) ctx.Response.Close(); } catch { } }
            }
        }

        private void HandleMessage(IWebSocketConnection socket, string message) {
            try {
                var msg = JObject.Parse(message);
                string type = msg["type"] != null ? msg["type"].ToString() : "";

                // ── 2026-09-13 EXE 接管时, 网页端这几条【会动硬件的】一律不收 ────────
                //   TIMING_CMD 里那些就位/发令/判罚在 HandleTimingCommand 里另挡;
                //   这里挡的是绕开 TIMING_CMD 直接发的两条 —— 尤其 CONNECT_HW:
                //   比赛中从网页上把计时硬件断开, 后果比按错发令键还严重。
                if (socket != null && IsRaceControlTakenByExe() && _timingWebSockets.Contains(socket)) {
                    if (type == "CONNECT_HW" || type == "DEVICE_OVERRIDE") {
                        AddLog(Loc.F("Str_Log_RaceControlHeldByExeRejectFmt", type));
                        try {
                            EnqueueToSocket(socket, Newtonsoft.Json.JsonConvert.SerializeObject(new {
                                type = "TIMING_CMD_REJECTED", command = type,
                                reason = "比赛控制程序(EXE)正在接管 —— 硬件和计时请在那台机器上操作"
                            }));
                        } catch { }
                        return;
                    }
                }

                switch (type) {
                    case "DISPLAY_IDENTITY":
                        if (!_displaySockets.Contains(socket)) _displaySockets.Add(socket);
                        AddLog(Loc.T("Str_Log_DisplayConnected"));
                        // 2026-06-01 新连接的大屏立即收到服务器侧最新样式 (bg/fs/textStyle), 不依赖本地 localStorage
                        try { SendDisplayStyleTo(socket); } catch { }
                        break;
                    case "SET_DISPLAY_STYLE":
                        // 2026-06-01 任意控制端 (control.html / RemoteDisplayControl / 主控 PC / 大屏自身) 推送新样式
                        try { HandleSetDisplayStyle(msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_DisplayStyleSetFailedFmt", ex.Message)); }
                        break;
                    case "GET_DISPLAY_STYLE":
                        // 2026-06-01 控制端打开"大屏样式"面板时主动拉一次当前值, 让 UI 同步
                        try { SendDisplayStyleTo(socket); } catch { }
                        break;
                    case "LEADERBOARD_IDENTITY":
                        if (!_leaderboardSockets.Contains(socket)) _leaderboardSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_LeaderboardConnected"));
                        break;
                    case "REGISTER_TERMINAL_IDENTITY":
                        if (!_registerSockets.Contains(socket)) _registerSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_RegisterTerminalConnected"));
                        // 2026-09-03 一上线就把【比赛参数设置管理】的五张表发过去 ——
                        //   它是独立 exe, 不发它就只能用自己写死的那几个性别/组别。
                        try { socket.Send(BuildMetaListsJson()); } catch { }
                        break;
                    // 2026-09-28【跨客户端语言同步】RegistrationTool.exe 专属身份标记(紧跟在
                    //   REGISTER_TERMINAL_IDENTITY 后面报, register.html 网页端不会报这条)——
                    //   只有报了这条的才是桌面 exe, 新连上/断线重连立即用主服务器当前语言校准一次,
                    //   不用等下次有人手动切换语言才追上。
                    case "REGISTRATION_TOOL_IDENTITY":
                        if (!_registrationToolSockets.Contains(socket)) _registrationToolSockets.Add(socket);
                        try { EnqueueToSocket(socket, BuildLanguageSyncJson()); } catch { }
                        break;
                    case "TIMING_EXE_IDENTITY":
                        if (!_timingExeSockets.Contains(socket)) _timingExeSockets.Add(socket);
                        // 2026-09-28 同上, RTC 是桌面 exe, 新连上就用主服务器当前语言校准一次。
                        try { EnqueueToSocket(socket, BuildLanguageSyncJson()); } catch { }
                        // 2026-09-14 记下这个 EXE 连上这一刻是否真接着硬件、是哪台机器
                        //   (见 PushHwConnStatusToMainServer 的注释) —— 机器名拿不到(老版本
                        //   RTC 没带这个字段)就退回连接方 IP, "连接状态"面板好歹能看出个大概。
                        {
                            var info = new RemoteExeInfo {
                                HwConnected = (msg["hwConnected"] != null && (bool)msg["hwConnected"]),
                                MachineName = msg["machine"] != null ? msg["machine"].ToString() : ""
                            };
                            if (string.IsNullOrEmpty(info.MachineName)) {
                                try { info.MachineName = socket.ConnectionInfo.ClientIpAddress; } catch { }
                            }
                            _timingExeInfo[socket] = info;
                            AddLog(Loc.F("Str_Log_TimingExeConnectedFmt", info.MachineName,
                                info.HwConnected ? "已接硬件" : "尚未接硬件"));
                        }
                        UpdateScoringControlMode();
                        UpdateConnectionStatus();   // 2026-09-14 刷新"连接状态"里"计时硬件"那一行(哪台机器)
                        break;
                    // 2026-09-14 RTC 硬件连接状态变化(连上/断开硬件计时器)实时上报 ——
                    //   "比赛控制"该让谁管靠这个信号判断, 不是靠"连接类型是 EXE 还是网页"。
                    case "TIMING_EXE_HW_STATUS":
                        {
                            RemoteExeInfo info;
                            if (!_timingExeInfo.TryGetValue(socket, out info)) {
                                info = new RemoteExeInfo();
                                try { info.MachineName = socket.ConnectionInfo.ClientIpAddress; } catch { }
                                _timingExeInfo[socket] = info;
                            }
                            if (msg["machine"] != null && !string.IsNullOrEmpty(msg["machine"].ToString()))
                                info.MachineName = msg["machine"].ToString();
                            info.HwConnected = (msg["hwConnected"] != null && (bool)msg["hwConnected"]);
                            AddLog(Loc.F("Str_Log_RtcHwStatusFmt",
                                info.MachineName, info.HwConnected ? "已连接" : "已断开"));
                        }
                        UpdateScoringControlMode();
                        UpdateConnectionStatus();   // 2026-09-14 刷新"连接状态"里"计时硬件"那一行(哪台机器)
                        break;
                    case "TIMING_WEB_IDENTITY":
                        if (!_timingWebSockets.Contains(socket)) _timingWebSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_TimingWebConnected"));
                        UpdateScoringControlMode();
                        // 2026-09-18 race_control.html 的"记录显示/显反应时"按钮态跟
                        //   DisplayStyleWindow 同一个毛病: 只在"有人改动"那一刻广播,
                        //   这里连上来的新连接(含断线重连)不知道当前真实状态, 要等下一次
                        //   别处有人改动才追得上。新连上就补一次当前快照。
                        try { EnqueueToSocket(socket, BuildDisplayStyleJson()); } catch { }
                        break;
                    case "CHECKIN_IDENTITY":
                        if (!_checkinSockets.Contains(socket)) _checkinSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_CheckinConnected"));
                        UpdateConnectionStatus();
                        break;
                    case "EDITOR_IDENTITY":
                        if (!_editorSockets.Contains(socket)) _editorSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_EditorClientConnectedPushFull"));
                        SendEditorPackageTo(socket);   // 上线立即喂一次整包，编排端覆盖本地
                        break;
                    // 2026-09-14 query.html("信息查询"终端) 的身份标记 —— 只为"连接状态"面板计数,
                    //   不影响它借用 EDITOR_IDENTITY 拿整包/订阅补丁那条路(见上面那个 case)。
                    case "QUERY_IDENTITY":
                        if (!_querySockets.Contains(socket)) _querySockets.Add(socket);
                        AddLog(Loc.T("Str_Log_QueryTerminalConnected"));
                        UpdateConnectionStatus();
                        break;
                    // 2026-09-14 显示控制端(control.html / RemoteDisplayControl.exe) 身份标记 ——
                    //   只为"连接状态"面板计数, 不影响它俩原有的 REMOTE_CONTROL 命令收发。
                    case "DISPLAY_CONTROL_IDENTITY":
                        if (!_displayControlSockets.Contains(socket)) _displayControlSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_DisplayControlConnected"));
                        UpdateConnectionStatus();
                        // 2026-09-18 大屏样式(记录显示/隐藏、显反应时等开关)只在"有人改动"那一刻
                        //   广播一次(BroadcastDisplayStyle), 断线重连/新开一个显示控制端之后、
                        //   下一次有人改之前, 这台机器完全不知道当前开关状态——按钮显示的是
                        //   程序刚启动的默认值, 跟真实状态可能对不上。新连上来就补一次当前快照,
                        //   不用等"下一次谁改了"才追得上。
                        try { EnqueueToSocket(socket, BuildDisplayStyleJson()); } catch { }
                        break;
                    // 2026-09-28【跨客户端语言同步】RemoteDisplayControl.exe 专属身份标记(紧跟在
                    //   DISPLAY_CONTROL_IDENTITY 后面报, control.html 网页端不会报这条)——只有
                    //   报了这条的才是桌面 exe, 新连上就用主服务器当前语言校准一次。
                    case "RDC_IDENTITY":
                        if (!_rdcSockets.Contains(socket)) _rdcSockets.Add(socket);
                        try { EnqueueToSocket(socket, BuildLanguageSyncJson()); } catch { }
                        break;
                    // 2026-09-15 编排端(ScheduleEditor.exe)身份标记 —— 只为"连接状态"面板计数,
                    //   不影响它借用 EDITOR_IDENTITY 拿整包/订阅补丁那条路(见上面 EDITOR_IDENTITY)。
                    case "SCHEDULE_EDITOR_IDENTITY":
                        if (!_scheduleEditorSockets.Contains(socket)) _scheduleEditorSockets.Add(socket);
                        AddLog(Loc.T("Str_Log_EditorConnected"));
                        UpdateConnectionStatus();
                        // 2026-09-28 同上, 编排端是桌面 exe, 新连上就用主服务器当前语言校准一次。
                        try { EnqueueToSocket(socket, BuildLanguageSyncJson()); } catch { }
                        break;
                    // 2026-09-18 计时端(RTC/role=timing)本地状态变了、但走的不是 AutoSaveData
                    //   那条路(比如"准备就绪"把 heats.state 写成 racing——这一步只经 _meet RPC
                    //   直接落库, 不落 JSON 存档, 自然也不会触发 AutoSaveData→PushDataChanged)。
                    //   这类变化以前只能靠编排端/主服务器自己 10 秒一次的轮询追上。计时端这边
                    //   补发一条轻量通知, 主服务器收到就用同一条 PushDataChanged 管道转给它
                    //   自己这边挂着的其它客户端(编排端等)——它们收到后走新加的 DATA_CHANGED
                    //   处理, 立刻多轮询一次, 不用等下一个 10 秒整点。
                    case "CLIENT_DATA_CHANGED":
                        // 2026-09-21 【订正】上面这条只是转告"数据变了, 自己来取"——但检录台/
                        //   编排端收到后发 REQUEST_FULL_STATUS 拿到的 heatStatus 是主服务器
                        //   当场算的(HeatStatus() 读 _racingHeatKeys), 而 _racingHeatKeys 只在
                        //   RebuildNavTree() 里才刷新(见其说明), 从不因为收到这条通知而重新
                        //   查一次 _meetDb.GetRacingHeats()。之前只转发不重算, 于是主服务器
                        //   自己那份 _racingHeatKeys 停留在这一组开赛前的旧值, 转告"数据变了"
                        //   反而喂给检录台一份跟没变一样的旧状态——用户实拍到"检录台迟迟不见
                        //   【进行中】"正是这个空档。跟"准备就绪"在本机那侧的补法(9431 行
                        //   RebuildBothNavTrees())同一个道理, 这里补一次真正的重算再转告。
                        try { BuildScheduleTree(); } catch { }
                        PushDataChanged(msg["what"] != null ? msg["what"].ToString() : "");
                        break;
                    // 2026-06-17 方案 B: RTC 把比赛状态 (SHOW_LIVE_RACE / RUNNING_TIME_UPDATE 等) 经此连接
                    //   推给主服务器, 主服务器透传给所有本机 _allSockets (display.html / race_control.html ...).
                    //   RTC 是计时主控, 它的状态才是真实状态, 主服务器在此场景下纯当消息总线.
                    case "RTC_FORWARD":
                        try {
                            var payload = msg["payload"];
                            if (payload == null) break;
                            string json = payload.ToString(Newtonsoft.Json.Formatting.None);
                            // 2026-06-17 原本缓存 RTC 最近一次完整快照给新客户端开局。
                            // 2026-09-13 不再缓存也不再用它 —— RTC 平时只发精简帧, 切视图时发的是
                            //   大屏专用包, 两种都没有名单/赛程, 拿来当新客户端的底子会把它那份
                            //   静态数据冲空。新客户端改由主服务器自己那份完整数据开局(见 OnOpen)。
                            string ptype = payload["type"] != null ? payload["type"].ToString() : "";
                            // 2026-09-12 顺手记下 RTC 正开着哪一组 —— 编排端发来的补丁要靠它挡
                            if (ptype == "SHOW_LIVE_RACE" || ptype == "SHOW_LIVE_RACE_LITE")
                                NoteRtcRaceState(payload as JObject);
                            // 2026-09-13 RTC 可以指定这一帧发给谁: to="display" 只发大屏,
                            //   to="others" 只发非大屏。切显示模式时 RTC 就靠这个把
                            //   【大屏专用包(约 23KB)】和【给其它客户端的精简帧】分开发 ——
                            //   原来不分, 一律发 GetStatusData() 整包(278KB), 大屏切个视图
                            //   要等那 278KB 传完再解析, 现场感觉就是"按了半天才变"。
                            // 2026-09-15 【广播分级】to="others" 的含义收窄: 原来是"除大屏外
                            //   所有人"(检录台/信息查询/排名屏/报名终端/显示控制/编排端全在内,
                            //   但它们谁都不处理这些消息), 现在改成"比赛控制网页"
                            //   (_timingWebSockets, race_control.html) —— 真正会用这些数据的
                            //   只有它。同时新增两个更窄的收件人组: to="display_control"
                            //   (大屏∪比赛控制网页, 给滚动时间用) 和 to="style"
                            //   (大屏∪比赛控制网页∪显示控制端, 给大屏样式推送用)。
                            //   没带 to 的默认分支保留 EnqueueToAll, 给低频结构性消息
                            //   (比如成绩回推类通知)兜底广播, 本次不收窄。
                            string to = msg["to"] != null ? msg["to"].ToString() : "";
                            if (to == "display") {
                                foreach (var s in _displaySockets.ToList()) EnqueueToSocket(s, json);
                            } else if (to == "others") {
                                foreach (var s in _timingWebSockets.ToList()) EnqueueToSocket(s, json);
                            } else if (to == "display_control") {
                                foreach (var s in _displaySockets.Concat(_timingWebSockets).ToList()) EnqueueToSocket(s, json);
                            } else if (to == "style") {
                                foreach (var s in _displaySockets.Concat(_timingWebSockets).Concat(_displayControlSockets).ToList()) EnqueueToSocket(s, json);
                            } else {
                                // 2026-06-18 per-socket 队列, 不再 lock 串行 send
                                EnqueueToAll(json);
                            }
                        } catch { }
                        // 2026-10-09 【严重回归根因】这里原来是 break, 会继续往下掉到整个
                        //   switch 末尾(HandleMessage 结尾处)那句无条件 BroadcastSingle(socket)——
                        //   等于"处理完任何消息都给发送方回发一份 278KB 整包"。RTC_FORWARD 是
                        //   RTC 每 100ms(BroadcastImmediate)+ 硬件每 100ms(BroadcastRunningTime)
                        //   两路高频帧共用的信封, 实测每秒 9~10 条——于是主服务器每秒把 9~10 份
                        //   278KB 的 SHOW_LIVE_RACE 整包怼回 RTC 自己那条 EditorSyncClient 连接。
                        //   RTC 这边 HandleEditorSyncMessage 对 SHOW_LIVE_RACE 这个类型根本
                        //   没有对应 case(白白解析), 但 JObject.Parse 一个 278KB 字符串本身就要
                        //   25~70ms, 这些全排在 UI 线程(Dispatcher Normal 优先级)上, 硬件帧(纵使
                        //   给了 Send 优先级)排在它后面一样要等——这才是"远程计时控制连上主
                        //   服务器后滚动时间跳跃、触板成绩延迟几秒、大屏延迟近十秒"的真正根源,
                        //   跟今天早些时候修的按钮卡顿是同一个机制的另一种触发方式。RTC_FORWARD
                        //   自己已经按 to 精确分发过了, 不需要也不应该再触发这个兜底整包回声。
                        return;
                    // 2026-08-28 计时端确认成绩后回推本组 —— 让主服务器内存模型跟上,
                    //   否则赛程树的"已完赛"和项目成绩都看不到计时端跑出来的结果。
                    // 2026-08-31 计时端操作员确认过"生成组成绩"了, 主服务器也生成自己那份。
                    //   这边没人看着, 所以不弹窗(confirm 传 null) —— 该问的已经在计时端问过了。
                    case "GENERATE_EVENT_RANKING":
                        try {
                            var gd2 = msg["data"] as JObject;
                            if (gd2 != null)
                                HandleGenerateEventRanking(socket,
                                    msg["id"] != null ? msg["id"].ToString() : "",
                                    gd2["ageGroup"] != null ? gd2["ageGroup"].ToString() : "",
                                    gd2["gender"] != null ? gd2["gender"].ToString() : "",
                                    gd2["eventName"] != null ? gd2["eventName"].ToString() : "",
                                    gd2["stage"] != null ? gd2["stage"].ToString() : "");
                        } catch (Exception ex) { AddLog(Loc.F("Str_Log_GenEventRankingFailedFmt", ex.Message)); }
                        break;
                    case "HEAT_CONFIRMED_PUSH":
                        try { HandleHeatConfirmedPush(socket, msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ApplyPushedResultFailedFmt", ex.Message)); }
                        break;
                    case "EDITOR_PULL_PACKAGE":
                        SendEditorPackageTo(socket);
                        break;
                    // 2026-09-13 完整状态包改成"要才给" —— 客户端收到 DATA_CHANGED
                    //   或者自己需要时来取一次, 服务器不再每 10 秒定时重发 278KB。
                    case "REQUEST_FULL_STATUS":
                        BroadcastSingle(socket);
                        break;
                    // 2026-09-13 页面一连上就报自己的版本。对不上就在系统日志里点名 ——
                    //   页面那头也会挂红条, 但没人盯着浏览器时, 这条日志是唯一的线索。
                    case "CLIENT_VERSION":
                        try {
                            string pageName = msg["page"] != null ? msg["page"].ToString() : Loc.T("Str_Log_UnknownPage");
                            string pageVer = msg["ver"] != null ? msg["ver"].ToString() : "";
                            if (pageVer != WEB_ASSET_VERSION) {
                                AddLog(Loc.F("Str_Log_VersionMismatchFmt",
                                    pageName, string.IsNullOrEmpty(pageVer) ? Loc.T("Str_Log_OldVerNoReport") : pageVer, WEB_ASSET_VERSION));
                            } else {
                                AddLog(Loc.F("Str_Log_PageConnectedVersionOkFmt", pageName, pageVer));
                            }
                        } catch { }
                        break;
                    case "EDITOR_PUSH_PACKAGE":
                        HandleEditorPushPackage(socket, msg);
                        break;
                    // 2026-09-12 增量补丁: 比赛中也收 —— 它不重载整库, 只改点名的那几个人
                    case "EDITOR_PATCH":
                        HandleEditorPatch(socket, msg);
                        break;
                    case "LOCK_REQUEST":
                        HandleLockRequest(socket, msg);
                        break;
                    case "LOCK_RELEASE":
                        HandleLockRelease(socket, msg);
                        break;
                    case "DEVICE_OVERRIDE":
                        HandleDeviceOverride(msg);
                        break;
                    case "GET_HEAT_SWIMMERS":
                        HandleGetHeatSwimmers(socket, msg);
                        break;
                    case "SAVE_CHECKIN":
                        HandleSaveCheckin(socket, msg);
                        break;
                    case "REGISTER_SWIMMER":
                        HandleRegisterSwimmer(msg);
                        break;
                    case "REGISTER_QUERY":
                        HandleRegisterQuery(socket, msg);
                        break;
                    case "REGISTER_SWIMMER_BATCH":
                        HandleRegisterSwimmerBatch(socket, msg);
                        break;
                    case "REGISTER_SWIMMERS_MULTI":
                        HandleRegisterSwimmersMulti(socket, msg);
                        break;
                    case "REGISTER_RELAY":
                        HandleRegisterRelay(socket, msg);
                        break;
                    case "REGISTER_RELAYS_MULTI":
                        HandleRegisterRelaysMulti(socket, msg);
                        break;
                    case "RELAY_QUERY":
                        HandleRelayQuery(socket, msg);
                        break;
                    case "CONNECT_HW":
                        HandleConnectHw(msg);
                        break;
                    case "TIMING_CMD":
                        HandleTimingCommand(msg, socket);
                        break;
                    // 2026-08-25 竞赛数据服务: 主服务器独占 meet.db, 别的机器把请求发过来。
                    //   计时端靠这个在【选组】和【确认成绩】两个时刻取名单/回写成绩;
                    //   比赛中它只写自己的 current_heat.db, 这条路一次都不走。
                    case SwimmingScoreboard.Db.MeetRpc.RequestType:
                        HandleMeetRpc(msg, socket);
                        break;
                    case "TIMING_DATA":
                        HandleTimingData(msg);
                        break;
                    case "REMOTE_CONTROL":
                        HandleRemoteControl(msg, socket);
                        break;
                    case "FALSE_START_DETECTED":
                        HandleFalseStartDetected(msg);
                        break;
                }

                UpdateConnectionStatus();
                BroadcastSingle(socket);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_MsgHandleErrorFmt", ex.Message));
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 检录台支持
        // ═══════════════════════════════════════════════════════════════

        // 查询指定组运动员（不改变服务器当前组状态；只回复给请求者）
        // 2026-06-16 加 ageGroup 参数: 修跨组别污染 bug (跟 PublishResultToDisplay 同类) -
        //   多组别共用 (gender, event, stage) 时, 漏 ageGroup 会返回所有组别的运动员到检录台.
        private void HandleGetHeatSwimmers(IWebSocketConnection socket, JObject msg) {
            var data = msg["data"];
            if (data == null) return;
            string ageGroup = data["ageGroup"] != null ? data["ageGroup"].ToString() : "";
            string gender = data["gender"] != null ? data["gender"].ToString() : "";
            string eventName = data["eventName"] != null ? data["eventName"].ToString() : "";
            string stage = data["stage"] != null ? data["stage"].ToString() : "";
            int heat = data["heat"] != null ? (int)data["heat"] : 0;

            bool isRelay = eventName.Contains("接力");
            // 2026-08-21 见 GenderMatchEx 的说明
            // 2026-08-24 改调分组名单唯一入口 (原来自己筛一遍, 与大屏的筛法略有出入)
            var heatSwimmers = GetHeatEntries(ageGroup, gender, eventName, stage, heat);

            var list = new List<object>();
            foreach (var s in heatSwimmers) {
                var sa = s.GetAssignmentForStage(stage);
                int lane = LaneOfStage(s, stage);
                string entryTime = s.EntryTime ?? "";
                if (sa != null && !string.IsNullOrEmpty(sa.EntryTime)) entryTime = sa.EntryTime;

                // 接力队员列表（按棒次顺序）
                var memberList = new List<object>();
                if (isRelay) {
                    // 优先从 RelayTeam.Legs 按棒次顺序取
                    var relayTeam = _relayTeams.FirstOrDefault(rt =>
                        rt.TeamName == s.Country && rt.EventName == s.EventName && rt.Gender == s.Gender);
                    if (relayTeam != null && relayTeam.Legs != null && relayTeam.Legs.Count > 0) {
                        var orderedLegs = relayTeam.Legs.OrderBy(l => l.LegOrder).ToList();
                        foreach (var leg in orderedLegs) {
                            // 通过 bibNumber 或 name 在 _swimmers 中找到该队员
                            var mem = _swimmers.FirstOrDefault(m =>
                                m.Notes != null && m.Notes.StartsWith("接力队员")
                                && m.EventName == s.EventName && m.Country == s.Country
                                && ((!string.IsNullOrEmpty(leg.SwimmerBibNumber) && m.BibNumber == leg.SwimmerBibNumber)
                                    || (!string.IsNullOrEmpty(leg.SwimmerName) && m.Name == leg.SwimmerName)));
                            // 身份证号：优先取 Swimmer 记录；否则取 RelayLeg 存储的值
                            string memIdNum = (mem != null && !string.IsNullOrEmpty(mem.IDNumber))
                                ? mem.IDNumber : (leg.SwimmerIDNumber ?? "");
                            memberList.Add(new {
                                legOrder = leg.LegOrder,
                                bibNumber = mem != null ? (mem.BibNumber ?? "") : (leg.SwimmerBibNumber ?? ""),
                                name = mem != null ? (mem.Name ?? "") : (leg.SwimmerName ?? ""),
                                idNumber = memIdNum,
                                status = mem != null ? (mem.Status ?? "") : ""
                            });
                        }
                    } else {
                        // 兼容：没有 RelayTeam 数据时，按 _swimmers 直接过滤
                        var members = _swimmers.Where(m => m.Notes != null && m.Notes.StartsWith("接力队员")
                            && m.Country == s.Country && m.EventName == s.EventName).ToList();
                        int idx = 1;
                        foreach (var m in members) {
                            memberList.Add(new {
                                legOrder = idx++,
                                bibNumber = m.BibNumber ?? "",
                                name = m.Name ?? "",
                                idNumber = m.IDNumber ?? "",
                                status = m.Status ?? ""
                            });
                        }
                    }
                }

                list.Add(new {
                    lane = lane,
                    bibNumber = s.BibNumber ?? "",
                    name = s.Name ?? "",
                    idNumber = s.IDNumber ?? "",
                    // 2026-06-17 显式分开 country (单位全名) 和 countryShort (简称), 方便前端区分
                    country = s.Country ?? "",
                    countryShort = s.CountryShort ?? "",
                    team = s.Country ?? "",     // 兼容: team = Country 全名
                    age = s.Age,
                    ageCategory = s.AgeCategory ?? "",
                    entryTime = entryTime,
                    status = s.Status ?? "",
                    members = memberList,
                    isRelay = isRelay
                });
            }
            list = list.OrderBy(o => ((dynamic)o).lane).ToList();

            try {
                var reply = new {
                    type = "HEAT_SWIMMERS",
                    data = new { ageGroup, gender, eventName, stage, heat, isRelay, swimmers = list }
                };
                socket.Send(JsonConvert.SerializeObject(reply));
            } catch { }
        }

        // 检录表确认：批量更新状态（DNS 等），保存并广播
        // statuses 支持两种键：bibNumber（首选，兼容接力队员）或 lane（个人项目兼容）
        private void HandleSaveCheckin(IWebSocketConnection socket, JObject msg) {
            var data = msg["data"];
            if (data == null) return;
            // 2026-06-16 加 ageGroup: 防跨组别 bibNumber 撞号 (虽然 bibNumber 一般全局唯一, 兜底)
            string ageGroup = data["ageGroup"] != null ? data["ageGroup"].ToString() : "";
            string gender = data["gender"] != null ? data["gender"].ToString() : "";
            string eventName = data["eventName"] != null ? data["eventName"].ToString() : "";
            string stage = data["stage"] != null ? data["stage"].ToString() : "";
            int heat = data["heat"] != null ? (int)data["heat"] : 0;
            var statuses = data["statuses"] as JArray;
            if (statuses == null) return;

            // 2026-09-21 用户明确要求: 正在比赛"进行中"、"已确认"的组不能再检录——
            //   前端(checkin.html)已经把按钮/表单禁掉, 这里再挡一道, 防止老页面缓存/
            //   绕过前端直接发消息。
            string curStatus = HeatStatus(ageGroup, gender, eventName, stage, heat);
            if (curStatus == "running" || curStatus == "confirmed") {
                string why = curStatus == "running" ? "这一组正在比赛中" : "这一组成绩已确认";
                AddLog(Loc.F("Str_Log_CheckinRejectedFmt", gender, eventName, stage, heat, why));
                try {
                    if (socket != null) {
                        var rej = new JObject();
                        rej["type"] = "CHECKIN_RESULT";
                        rej["ok"] = false;
                        rej["reason"] = why + "，不能再检录。";
                        socket.Send(rej.ToString(Formatting.None));
                    }
                } catch { }
                return;
            }

            int updated = 0;
            var touchedRows = new List<Swimmer>();
            foreach (JObject st in statuses.Cast<JObject>()) {
                string bib = st["bibNumber"] != null ? st["bibNumber"].ToString() : "";
                int lane = st["lane"] != null ? (int)st["lane"] : 0;
                string newStatus = st["status"] != null ? st["status"].ToString() : "";

                Swimmer target = null;
                // 首选按 bibNumber 精准匹配（个人 + 接力队员通用）
                // 2026-06-16 加 ageGroup 兜底, 防跨组别撞 bib
                if (!string.IsNullOrEmpty(bib)) {
                    target = _swimmers.FirstOrDefault(s =>
                        s.BibNumber == bib && s.EventName == eventName && SgMatch(s.Gender, gender)
                        && (string.IsNullOrEmpty(ageGroup) || (s.AgeCategory ?? "") == ageGroup));
                }
                // 回退按泳道匹配（仅针对当前组的非接力队员代表条目）
                if (target == null && lane > 0) {
                    target = _swimmers.FirstOrDefault(s => {
                        if (!SgMatch(s.Gender, gender) || s.EventName != eventName) return false;
                        if (!string.IsNullOrEmpty(ageGroup) && (s.AgeCategory ?? "") != ageGroup) return false;
                        if (s.Notes != null && s.Notes.StartsWith("接力队员")) return false;
                        var sa = s.GetAssignmentForStage(stage);
                        if (sa != null && sa.Heat == heat && sa.Lane == lane) return true;
                        if (s.CurrentStage == stage && s.Heat == heat && s.Lane == lane) return true;
                        return false;
                    });
                }
                if (target != null && (target.Status ?? "") != newStatus) {
                    target.Status = newStatus;
                    updated++;
                    touchedRows.Add(target);
                }
            }

            // 2026-09-21 标记"这一组已经检录过"——跟 ConfirmedHeats(赛后锁成绩)是两个
            //   不同阶段, 分开一张表。一旦提交过, checkin.html 的赛程导航要能看出来。
            MarkHeatCheckedInCore(ageGroup, gender, eventName, stage, heat);

            AddLog(Loc.F("Str_Log_CheckinSavedFmt",
                gender, eventName, stage, heat, updated));
            // 2026-09-21 【再订正】上一版这里改成了走 SwimmerRowsUpsert 补丁("想得美, 但…"
            //   那句注释), 以为带着 Swimmer.Status 字段过去就够了——结果主服务器自己这棵树
            //   都没刷新, 编排端/计时端更是白等: 三棵"赛程导航"树的[已检录]标签只认
            //   _checkedInHeats 这张表(见 BuildScheduleTree/HeatStatus), 压根不看 Swimmer.Status,
            //   SwimmerRowsUpsert 补丁再怎么带数据也带不到这张表上; 而且当时也没在本机调用
            //   BuildScheduleTree() 刷新——主服务器自己那份内存其实早改对了, 只是 WPF 的
            //   TreeView 控件没人告诉它"该重画了"。现在分两步真正补上: 本机 MarkHeatCheckedInCore
            //   里已经重建过树, 这里再单独发一条"CheckIn"补丁(见 ApplyCheckInPatch)把
            //   _checkedInHeats 这张表本身同步给比赛控制exe/编排端, 它们收到后同样会各自调
            //   BuildScheduleTree() 重画。Swimmer.Status 的 upsert 补丁仍然要发(DNS 等状态
            //   本身也要同步), 两条补丁并不冲突, 各管各的字段。
            UpdateLaneStatusDisplay();
            FinishAndSyncPatch(BuildSwimmerRowsUpsertPatch(touchedRows, null, ClientLabel()), "swimmer");
            var checkInPatch = NewPatch("CheckIn", ageGroup, gender, eventName, stage, ClientLabel());
            checkInPatch["heat"] = heat;
            string cierr;
            if (!SpreadPatch(checkInPatch, out cierr))
                AddLog(Loc.F("Str_Log_CheckinNotSyncedFmt", cierr));
            try {
                if (socket != null) {
                    var ack = new JObject();
                    ack["type"] = "CHECKIN_RESULT";
                    ack["ok"] = true;
                    socket.Send(ack.ToString(Formatting.None));
                }
            } catch { }
        }

        private void HandleRegisterSwimmer(JObject msg) {
            var data = msg["data"];
            if (data == null) return;
            string bibNumber = data["bibNumber"] != null ? data["bibNumber"].ToString() : "";
            string regCountry = data["country"] != null ? data["country"].ToString() : "";
            if (string.IsNullOrEmpty(bibNumber)) bibNumber = GenerateNextBibNumber(regCountry);
            var swimmer = new Swimmer {
                Name = data["name"] != null ? data["name"].ToString() : "",
                BibNumber = bibNumber,
                Gender = data["gender"] != null ? data["gender"].ToString() : "男",
                Age = data["age"] != null ? (int)data["age"] : 0,
                Country = data["country"] != null ? data["country"].ToString() : "",
                CountryShort = data["countryShort"] != null ? data["countryShort"].ToString() : "",
                IDNumber = data["idNumber"] != null ? data["idNumber"].ToString() : "",
                Phone = data["phone"] != null ? data["phone"].ToString() : "",
                EventName = data["eventName"] != null ? data["eventName"].ToString() : "",
                EntryTime = data["entryTime"] != null ? data["entryTime"].ToString() : "",
                BirthDate = data["birthDate"] != null ? data["birthDate"].ToString() : "",
                CSANumber = data["csaNumber"] != null ? data["csaNumber"].ToString() : "",
                FINANumber = data["finaNumber"] != null ? data["finaNumber"].ToString() : "",
                Notes = data["notes"] != null ? data["notes"].ToString() : ""
            };
            // 远程指定组别（如"甲组/乙组"）→ 覆盖按年龄自动推断
            string ageGroupStr = data["ageGroup"] != null ? data["ageGroup"].ToString() : "";
            if (!string.IsNullOrEmpty(ageGroupStr)) swimmer.AgeCategory = ageGroupStr;
            swimmer.EntryTimeSeconds = TimeFormatter.Parse(swimmer.EntryTime);
            var dup = FindDuplicate(swimmer.Name, swimmer.Gender, swimmer.EventName, swimmer.BibNumber, swimmer.IDNumber, swimmer.Country);
            if (dup != null) {
                AddLog(Loc.F("Str_Log_RemoteRegRejectedDupFmt", swimmer.Name, swimmer.EventName, dup.BibNumber));
                return;
            }
            _swimmers.Add(swimmer);
            AddLog(Loc.F("Str_Log_RemoteRegisteredFmt", swimmer.Name, bibNumber, swimmer.EventName));
            RefreshOverviewStats();
            RefreshSwimmerFilter();
            FinishAndSyncPatch(BuildSwimmerRowsAddPatch(new List<Swimmer> { swimmer }, ClientLabel()), "swimmer");
        }

        private void HandleRegisterSwimmerBatch(IWebSocketConnection socket, JObject msg) {
            var data = msg["data"];
            if (data == null) return;
            var swimmerData = data["swimmer"];
            var eventsArr = data["events"] as JArray;
            bool isResubmit = data["isResubmit"] != null && (bool)data["isResubmit"];

            if (swimmerData == null || eventsArr == null || eventsArr.Count == 0) {
                SendRegisterResult(socket, false, "数据不完整", "");
                return;
            }

            string name = swimmerData["name"] != null ? swimmerData["name"].ToString() : "";
            string gender = swimmerData["gender"] != null ? swimmerData["gender"].ToString() : "男";
            string bibNumber = swimmerData["bibNumber"] != null ? swimmerData["bibNumber"].ToString() : "";

            // 如果是重新提交，先删除该运动员之前的所有报名记录
            var removedKeys = new List<SwimmerDeleteKey>();
            if (isResubmit && !string.IsNullOrEmpty(bibNumber)) {
                var toRemove = _swimmers.Where(s => s.BibNumber == bibNumber).ToList();
                foreach (var s in toRemove) {
                    _swimmers.Remove(s);
                    removedKeys.Add(new SwimmerDeleteKey { BibNumber = s.BibNumber, Name = s.Name, EventName = s.EventName });
                }
                AddLog(Loc.F("Str_Log_ResubmitClearedFmt", name, bibNumber, toRemove.Count));
            }

            // 生成参赛号（按代表队号码段）
            string batchCountry = swimmerData["country"] != null ? swimmerData["country"].ToString() : "";
            if (string.IsNullOrEmpty(bibNumber)) bibNumber = GenerateNextBibNumber(batchCountry);

            int added = 0;
            int skipped = 0;
            var addedRows = new List<Swimmer>();
            foreach (JObject ev in eventsArr) {
                string eventName = ev["eventName"] != null ? ev["eventName"].ToString() : "";
                string entryTime = ev["entryTime"] != null ? ev["entryTime"].ToString() : "";

                string idNum = swimmerData["idNumber"] != null ? swimmerData["idNumber"].ToString() : "";
                string country = swimmerData["country"] != null ? swimmerData["country"].ToString() : "";
                var dup = FindDuplicate(name, gender, eventName, bibNumber, idNum, country);
                if (dup != null && !isResubmit) { skipped++; continue; }

                var swimmer = new Swimmer {
                    BibNumber = bibNumber,
                    Name = name,
                    Gender = gender,
                    Age = swimmerData["age"] != null ? (int)swimmerData["age"] : 0,
                    Country = country,
                    CountryShort = swimmerData["countryShort"] != null ? swimmerData["countryShort"].ToString() : "",
                    IDNumber = idNum,
                    Phone = swimmerData["phone"] != null ? swimmerData["phone"].ToString() : "",
                    EventName = eventName,
                    EntryTime = entryTime,
                    BirthDate = swimmerData["birthDate"] != null ? swimmerData["birthDate"].ToString() : "",
                    CSANumber = swimmerData["csaNumber"] != null ? swimmerData["csaNumber"].ToString() : "",
                    Notes = swimmerData["notes"] != null ? swimmerData["notes"].ToString() : ""
                };
                string batchAgeGroup = swimmerData["ageGroup"] != null ? swimmerData["ageGroup"].ToString() : "";
                if (!string.IsNullOrEmpty(batchAgeGroup)) swimmer.AgeCategory = batchAgeGroup;
                swimmer.EntryTimeSeconds = TimeFormatter.Parse(swimmer.EntryTime);
                _swimmers.Add(swimmer);
                addedRows.Add(swimmer);
                added++;
            }

            AddLog(Loc.F("Str_Log_BatchRegFmt",
                name, bibNumber, added, skipped));
            RefreshOverviewStats();
            RefreshSwimmerFilter();
            FinishAndSyncPatch(BuildSwimmerRowsAddPatch(addedRows, null, removedKeys, ClientLabel()), "swimmer");

            // 2026-05-21：原来无论 added=多少都回 success=true，导致"提交的全是重复项目"
            // 时 EXE 仍显示"报名成功"，用户去主服务器查看运动员列表却找不到新数据，
            // 以为"主服务器没收到"。现在分三种情况明确反馈：
            //   全部重复（added==0 && skipped>0） → success=false，红字提示
            //   部分重复（added>0  && skipped>0） → success=true，绿字带说明
            //   全部新增（skipped==0）           → success=true，原行为
            if (added == 0 && skipped > 0) {
                SendRegisterResult(socket, false, string.Format(
                    "提交的 {0} 个项目均已注册过，未新增任何记录。如需修改，请使用网页报名端的\"查询/修改已提交报名\"功能。",
                    skipped), bibNumber);
            } else if (skipped > 0) {
                SendRegisterResult(socket, true, string.Format(
                    "成功新增 {0} 个项目，跳过 {1} 个已存在的项目。", added, skipped), bibNumber);
            } else {
                SendRegisterResult(socket, true, "", bibNumber);
            }
        }

        private void SendRegisterResult(IWebSocketConnection socket, bool success, string message, string bibNumber) {
            try {
                var result = new { type = "REGISTER_RESULT", data = new { success = success, message = message, bibNumber = bibNumber } };
                socket.Send(JsonConvert.SerializeObject(result));
            } catch { }
        }

        // 网页报名端"多人一次提交"：批量校验整组数据；任何一条失败都不入库，回传逐条结果。
        // 全部通过则一次性写入并广播。客户端按 perEntry[i].success 显示并允许修改未通过的条目。
        private void HandleRegisterSwimmersMulti(IWebSocketConnection socket, JObject msg) {
            var data = msg["data"];
            var entries = data != null ? data["entries"] as JArray : null;
            if (entries == null || entries.Count == 0) {
                SendMultiResult(socket, false, "无报名条目", new List<object>());
                return;
            }

            // 校验阶段：组装规范化条目；同时检查批内重名+项目重复
            var normalized = new List<Tuple<JObject, JArray, bool, string, string>>(); // swimmerData, eventsArr, isResubmit, key(name|gender|country), reason
            var perEntry = new List<object>();
            var batchKeys = new HashSet<string>();
            bool anyFail = false;

            for (int i = 0; i < entries.Count; i++) {
                var en = entries[i] as JObject;
                if (en == null) {
                    perEntry.Add(new { ok = false, message = "条目格式错误", bibNumber = "" });
                    anyFail = true; normalized.Add(null);
                    continue;
                }
                var sw = en["swimmer"] as JObject;
                var evs = en["events"] as JArray;
                bool isResub = en["isResubmit"] != null && (bool)en["isResubmit"];

                if (sw == null) {
                    perEntry.Add(new { ok = false, message = "缺少运动员信息", bibNumber = "" });
                    anyFail = true; normalized.Add(null);
                    continue;
                }
                string nm = sw["name"] != null ? sw["name"].ToString().Trim() : "";
                if (string.IsNullOrEmpty(nm)) {
                    perEntry.Add(new { ok = false, message = "姓名不能为空", bibNumber = "" });
                    anyFail = true; normalized.Add(null);
                    continue;
                }
                if (evs == null || evs.Count == 0) {
                    perEntry.Add(new { ok = false, message = nm + ": 至少添加一个参赛项目", bibNumber = "" });
                    anyFail = true; normalized.Add(null);
                    continue;
                }
                string gd = sw["gender"] != null ? sw["gender"].ToString() : "男";
                string ct = sw["country"] != null ? sw["country"].ToString().Trim() : "";

                // 批内重复：2026-05-21 改为 ID 优先 — 与 FindDuplicate 哲学保持一致：
                //   • 有身份证号 → 用 "ID:身份证号" 做唯一键（同名不同 ID 不再误杀）
                //   • 无身份证号 → 退化到 "NA:姓名+性别+代表队"（保留无 ID 时的去重）
                string idNum = sw["idNumber"] != null ? sw["idNumber"].ToString().Trim() : "";
                string key = !string.IsNullOrEmpty(idNum)
                    ? ("ID:" + idNum)
                    : ("NA:" + nm + "|" + gd + "|" + ct);
                if (batchKeys.Contains(key)) {
                    string dupReason = !string.IsNullOrEmpty(idNum)
                        ? (nm + ": 与本批内其他条目重复（身份证号同 " + idNum + "）")
                        : (nm + ": 与本批内其他条目重复（同姓名+性别+代表队，且双方均未填身份证号）");
                    perEntry.Add(new { ok = false, message = dupReason, bibNumber = "" });
                    anyFail = true; normalized.Add(null);
                    continue;
                }
                batchKeys.Add(key);

                // 批内项目重复
                var seenEvents = new HashSet<string>();
                bool dupEv = false;
                string dupName = "";
                foreach (JObject ev in evs) {
                    string en2 = ev["eventName"] != null ? ev["eventName"].ToString() : "";
                    if (seenEvents.Contains(en2)) { dupEv = true; dupName = en2; break; }
                    seenEvents.Add(en2);
                }
                if (dupEv) {
                    perEntry.Add(new { ok = false, message = nm + ": 项目重复 " + dupName, bibNumber = "" });
                    anyFail = true; normalized.Add(null);
                    continue;
                }

                normalized.Add(Tuple.Create(sw, evs, isResub, key, ""));
                perEntry.Add(new { ok = true, message = "", bibNumber = sw["bibNumber"] != null ? sw["bibNumber"].ToString() : "" });
            }

            if (anyFail) {
                SendMultiResult(socket, false, "部分条目校验未通过，请修改后重新提交", perEntry);
                return;
            }

            // 写入阶段：每条独立处理（与现有 HandleRegisterSwimmerBatch 逻辑一致）
            var newPerEntry = new List<object>();
            var addedRows = new List<Swimmer>();
            var removedKeys = new List<SwimmerDeleteKey>();
            for (int i = 0; i < normalized.Count; i++) {
                var norm = normalized[i];
                if (norm == null) { newPerEntry.Add(perEntry[i]); continue; }
                var sw = norm.Item1;
                var evs = norm.Item2;
                bool isResub = norm.Item3;

                string name = sw["name"].ToString().Trim();
                string gender = sw["gender"] != null ? sw["gender"].ToString() : "男";
                string bibNumber = sw["bibNumber"] != null ? sw["bibNumber"].ToString() : "";
                string country = sw["country"] != null ? sw["country"].ToString() : "";

                if (isResub && !string.IsNullOrEmpty(bibNumber)) {
                    var toRemove = _swimmers.Where(s => s.BibNumber == bibNumber).ToList();
                    foreach (var s in toRemove) {
                        _swimmers.Remove(s);
                        removedKeys.Add(new SwimmerDeleteKey { BibNumber = s.BibNumber, Name = s.Name, EventName = s.EventName });
                    }
                    AddLog(Loc.F("Str_Log_ResubmitClearedFmt", name, bibNumber, toRemove.Count));
                }
                if (string.IsNullOrEmpty(bibNumber)) bibNumber = GenerateNextBibNumber(country, gender);

                int added = 0;
                foreach (JObject ev in evs) {
                    string eventName = ev["eventName"] != null ? ev["eventName"].ToString() : "";
                    string entryTime = ev["entryTime"] != null ? ev["entryTime"].ToString() : "";
                    string idNum = sw["idNumber"] != null ? sw["idNumber"].ToString() : "";
                    var dup = FindDuplicate(name, gender, eventName, bibNumber, idNum, country);
                    if (dup != null && !isResub) continue;

                    var swimmer = new Swimmer {
                        BibNumber = bibNumber,
                        Name = name,
                        Gender = gender,
                        Age = sw["age"] != null ? (int)sw["age"] : 0,
                        Country = country,
                        CountryShort = sw["countryShort"] != null ? sw["countryShort"].ToString() : "",
                        IDNumber = idNum,
                        Phone = sw["phone"] != null ? sw["phone"].ToString() : "",
                        EventName = eventName,
                        EntryTime = entryTime,
                        BirthDate = sw["birthDate"] != null ? sw["birthDate"].ToString() : "",
                        CSANumber = sw["csaNumber"] != null ? sw["csaNumber"].ToString() : "",
                        Notes = sw["notes"] != null ? sw["notes"].ToString() : ""
                    };
                    string ag = sw["ageGroup"] != null ? sw["ageGroup"].ToString() : "";
                    if (!string.IsNullOrEmpty(ag)) swimmer.AgeCategory = ag;
                    swimmer.EntryTimeSeconds = TimeFormatter.Parse(swimmer.EntryTime);
                    _swimmers.Add(swimmer);
                    addedRows.Add(swimmer);
                    added++;
                }
                AddLog(Loc.F("Str_Log_MultiBatchRegFmt", name, bibNumber, added));
                newPerEntry.Add(new { ok = true, message = "", bibNumber = bibNumber, name = name, addedCount = added });
            }

            RefreshOverviewStats();
            RefreshSwimmerFilter();
            FinishAndSyncPatch(BuildSwimmerRowsAddPatch(addedRows, null, removedKeys, ClientLabel()), "swimmer");
            SendMultiResult(socket, true, "全部报名提交成功", newPerEntry);
        }

        private void SendMultiResult(IWebSocketConnection socket, bool success, string message, List<object> perEntry) {
            try {
                var result = new {
                    type = "REGISTER_MULTI_RESULT",
                    data = new { success = success, message = message, entries = perEntry }
                };
                socket.Send(JsonConvert.SerializeObject(result));
            } catch { }
        }

        // 网页报名端"查询/修改我已经提交的报名"：根据 bibNumber 或 (姓名+代表队) 找到该运动员所有报名条目，
        // 回送基本资料 + 参赛项目列表，用户在浏览器修改后会以 isResubmit=true 重新提交，服务器先清旧记录再写入新记录
        private void HandleRegisterQuery(IWebSocketConnection socket, JObject msg) {
            try {
                var data = msg["data"];
                string bib = data != null && data["bibNumber"] != null ? data["bibNumber"].ToString().Trim() : "";
                string name = data != null && data["name"] != null ? data["name"].ToString().Trim() : "";
                string country = data != null && data["country"] != null ? data["country"].ToString().Trim() : "";

                List<Swimmer> matches = null;
                if (!string.IsNullOrEmpty(bib)) {
                    matches = _swimmers.Where(s => s.BibNumber == bib && !(s.Notes != null && s.Notes.StartsWith("接力队员"))).ToList();
                } else if (!string.IsNullOrEmpty(name) && !string.IsNullOrEmpty(country)) {
                    matches = _swimmers.Where(s => s.Name == name && (s.Country ?? "") == country &&
                        !(s.Notes != null && s.Notes.StartsWith("接力队员"))).ToList();
                }
                if (matches == null || matches.Count == 0) {
                    var miss = new { type = "REGISTER_QUERY_RESULT", data = new { success = false, message = "未找到对应的报名记录" } };
                    socket.Send(JsonConvert.SerializeObject(miss));
                    return;
                }

                var first = matches[0];
                var swimmerInfo = new {
                    bibNumber = first.BibNumber ?? "",
                    name = first.Name ?? "",
                    gender = first.Gender ?? "",
                    birthDate = first.BirthDate ?? "",
                    idNumber = first.IDNumber ?? "",
                    country = first.Country ?? "",
                    countryShort = first.CountryShort ?? "",
                    ageGroup = first.AgeCategory ?? "",
                    phone = first.Phone ?? "",
                    csaNumber = first.CSANumber ?? "",
                    notes = first.Notes ?? ""
                };
                var eventList = matches.Select(s => new {
                    eventName = s.EventName ?? "",
                    entryTime = s.EntryTime ?? ""
                }).ToList();

                var result = new {
                    type = "REGISTER_QUERY_RESULT",
                    data = new { success = true, swimmer = swimmerInfo, events = eventList }
                };
                socket.Send(JsonConvert.SerializeObject(result));
                AddLog(Loc.F("Str_Log_WebQueryRegFmt", first.Name, first.BibNumber, eventList.Count));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_RegisterQueryExceptionFmt", ex.Message));
            }
        }

        private void SendRelayResult(IWebSocketConnection socket, bool success, string message, string teamName, string bibNumber, int legCount, bool updated) {
            if (socket == null) return;
            try {
                var result = new {
                    type = "REGISTER_RELAY_RESULT",
                    data = new {
                        success = success,
                        message = message,
                        teamName = teamName,
                        bibNumber = bibNumber,
                        legCount = legCount,
                        updated = updated
                    }
                };
                socket.Send(JsonConvert.SerializeObject(result));
            } catch { }
        }

        // 2026-05-25 按队名查询接力队 (注册页面用), 返回首个匹配的整队信息便于回填修改
        private void HandleRelayQuery(IWebSocketConnection socket, JObject msg) {
            try {
                var data = msg["data"];
                string teamName = data != null && data["teamName"] != null ? data["teamName"].ToString().Trim() : "";
                if (string.IsNullOrEmpty(teamName)) {
                    var miss = new { type = "RELAY_QUERY_RESULT", data = new { success = false, message = "请输入队名" } };
                    socket.Send(JsonConvert.SerializeObject(miss));
                    return;
                }
                var t = _relayTeams.FirstOrDefault(x => string.Equals(x.TeamName ?? "", teamName, StringComparison.OrdinalIgnoreCase));
                if (t == null) {
                    var miss = new { type = "RELAY_QUERY_RESULT", data = new { success = false, message = "未找到队名为 \"" + teamName + "\" 的接力队" } };
                    socket.Send(JsonConvert.SerializeObject(miss));
                    return;
                }
                var legs = new List<object>();
                foreach (var leg in t.Legs.OrderBy(l => l.LegOrder)) {
                    legs.Add(new {
                        legOrder = leg.LegOrder,
                        swimmerName = leg.SwimmerName ?? "",
                        swimmerBibNumber = leg.SwimmerBibNumber ?? "",
                        swimmerIDNumber = leg.SwimmerIDNumber ?? "",
                        swimmerBirthDate = leg.SwimmerBirthDate ?? ""
                    });
                }
                var result = new {
                    type = "RELAY_QUERY_RESULT",
                    data = new {
                        success = true,
                        team = new {
                            teamName = t.TeamName ?? "",
                            eventName = t.EventName ?? "",
                            gender = t.Gender ?? "",
                            ageGroup = t.AgeGroup ?? "",
                            entryTime = t.EntryTime ?? "",
                            countryShort = "",
                            legs = legs
                        }
                    }
                };
                socket.Send(JsonConvert.SerializeObject(result));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_RelayQueryExceptionFmt", ex.Message));
            }
        }

        private void HandleRegisterRelay(IWebSocketConnection socket, JObject msg) {
            var data = msg["data"];
            if (data == null) { SendRelayResult(socket, false, "数据不完整", "", "", 0, false); return; }
            string message, teamName, bibNumber; int legCount; bool updated;
            bool ok = RegisterOneRelayTeam(data, out message, out teamName, out bibNumber, out legCount, out updated);
            SendRelayResult(socket, ok, message, teamName, bibNumber, legCount, updated);
        }

        // 2026-09-22 网页/RegistrationTool "多队多项目一次提交": 每个 entries[i] = 一支队(队名+性别+组别+棒次),
        //   entries[i].events[] = 这支队要报的多个接力项目(与个人项目"一人多项目"同一个模型)。
        //   逐条(队×项目)调用与单条 REGISTER_RELAY 完全相同的落库逻辑(RegisterOneRelayTeam), 互不影响、
        //   一条失败不影响其它条——不像 REGISTER_MULTI_RESULT(个人)那样先整批校验再整批写入, 因为接力
        //   "队名+性别+项目+组别 四键唯一"本身就是幂等 upsert, 没有"批内互相冲突"这类需要预校验的情形。
        private void HandleRegisterRelaysMulti(IWebSocketConnection socket, JObject msg) {
            var data = msg["data"];
            var entries = data != null ? data["entries"] as JArray : null;
            if (entries == null || entries.Count == 0) {
                SendRelaysMultiResult(socket, false, "无接力报名条目", new List<object>());
                return;
            }
            var perEntry = new List<object>();
            bool anyOk = false;
            for (int i = 0; i < entries.Count; i++) {
                var en = entries[i] as JObject;
                if (en == null) { perEntry.Add(new { ok = false, message = "条目格式错误", teamName = "", eventName = "" }); continue; }
                string teamNameIn = en["teamName"] != null ? en["teamName"].ToString() : "";
                var evs = en["events"] as JArray;
                if (evs == null || evs.Count == 0) {
                    perEntry.Add(new { ok = false, message = teamNameIn + ": 至少添加一个接力项目", teamName = teamNameIn, eventName = "" });
                    continue;
                }
                foreach (JObject ev in evs) {
                    string evName = ev["eventName"] != null ? ev["eventName"].ToString() : "";
                    string evEntryTime = ev["entryTime"] != null ? ev["entryTime"].ToString() : "";
                    // 拼一条与单条 REGISTER_RELAY 相同形状的 data: 队信息(entry级) + 这一个项目(event级)
                    var perCallData = new JObject();
                    perCallData["teamName"] = teamNameIn;
                    perCallData["eventName"] = evName;
                    perCallData["gender"] = en["gender"];
                    perCallData["ageGroup"] = en["ageGroup"];
                    perCallData["countryShort"] = en["countryShort"];
                    perCallData["entryTime"] = evEntryTime;
                    perCallData["legs"] = en["legs"];

                    string message, teamName, bibNumber; int legCount; bool updated;
                    bool ok = RegisterOneRelayTeam(perCallData, out message, out teamName, out bibNumber, out legCount, out updated);
                    if (ok) anyOk = true;
                    perEntry.Add(new { ok = ok, message = message, teamName = teamName, eventName = evName, bibNumber = bibNumber, legCount = legCount, updated = updated });
                }
            }
            SendRelaysMultiResult(socket, anyOk, anyOk ? "接力报名提交完成，详见各条结果" : "接力报名全部未通过", perEntry);
        }

        private void SendRelaysMultiResult(IWebSocketConnection socket, bool success, string message, List<object> perEntry) {
            if (socket == null) return;
            try {
                var result = new {
                    type = "REGISTER_RELAYS_MULTI_RESULT",
                    data = new { success = success, message = message, entries = perEntry }
                };
                socket.Send(JsonConvert.SerializeObject(result));
            } catch { }
        }

        // 2026-09-22 从 HandleRegisterRelay 抽出的核心落库逻辑(原样保留, 未改行为)——
        //   供单条 REGISTER_RELAY 和批量 REGISTER_RELAYS_MULTI 共用, 不再各写一份。
        //   不直接发 socket 回执, 用 out 参数把结果交回调用方自行组装/发送。
        private bool RegisterOneRelayTeam(JToken data, out string message, out string teamName, out string bibNumber, out int legCount, out bool updated) {
            message = ""; teamName = ""; bibNumber = ""; legCount = 0; updated = false;
            var team = new RelayTeam {
                TeamName = data["teamName"] != null ? data["teamName"].ToString() : "",
                EventName = data["eventName"] != null ? data["eventName"].ToString() : "",
                Gender = data["gender"] != null ? data["gender"].ToString() : "男",
                AgeGroup = data["ageGroup"] != null ? data["ageGroup"].ToString() : "",
                EntryTime = data["entryTime"] != null ? data["entryTime"].ToString() : ""
            };
            teamName = team.TeamName;
            if (string.IsNullOrEmpty(team.TeamName)) { message = "队名不能为空"; return false; }
            if (string.IsNullOrEmpty(team.EventName)) { message = "请选择项目"; return false; }
            if (string.IsNullOrEmpty(team.AgeGroup)) { message = "请选择组别"; return false; }
            team.EntryTimeSeconds = TimeFormatter.Parse(team.EntryTime);
            var legs = data["legs"] as JArray;
            if (legs != null) {
                foreach (JObject leg in legs) {
                    team.Legs.Add(new RelayLeg {
                        LegOrder = leg["legOrder"] != null ? (int)leg["legOrder"] : 0,
                        SwimmerName = leg["swimmerName"] != null ? leg["swimmerName"].ToString() : "",
                        SwimmerBibNumber = leg["swimmerBibNumber"] != null ? leg["swimmerBibNumber"].ToString() : "",
                        SwimmerIDNumber = leg["swimmerIDNumber"] != null ? leg["swimmerIDNumber"].ToString() : "",
                        SwimmerBirthDate = leg["swimmerBirthDate"] != null ? leg["swimmerBirthDate"].ToString() : ""
                    });
                }
            }
            // 自动匹配队员号码/身份证：从已注册运动员中查找
            foreach (var leg in team.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName)) continue;
                var match = _swimmers.FirstOrDefault(s => s.Name == leg.SwimmerName && s.Country == team.TeamName);
                if (match != null) {
                    if (string.IsNullOrEmpty(leg.SwimmerBibNumber) && !string.IsNullOrEmpty(match.BibNumber))
                        leg.SwimmerBibNumber = match.BibNumber;
                    if (string.IsNullOrEmpty(leg.SwimmerIDNumber) && !string.IsNullOrEmpty(match.IDNumber))
                        leg.SwimmerIDNumber = match.IDNumber;
                }
            }

            if (team.Legs.Count == 0) { message = "请至少填写 1 棒队员姓名"; return false; }

            // 防止同一接力队重复注册（队名+性别+项目+组别 四键唯一）
            var existingTeam = _relayTeams.FirstOrDefault(t =>
                t.TeamName == team.TeamName && t.Gender == team.Gender && t.EventName == team.EventName
                && (t.AgeGroup ?? "") == (team.AgeGroup ?? ""));
            if (existingTeam != null) {
                // 重复注册：用最新数据覆盖现有队伍（更新报名成绩与棒次）
                existingTeam.EntryTime = team.EntryTime;
                existingTeam.EntryTimeSeconds = team.EntryTimeSeconds;
                existingTeam.AgeGroup = team.AgeGroup;
                existingTeam.Legs.Clear();
                foreach (var leg in team.Legs) existingTeam.Legs.Add(leg);
                AddLog(Loc.F("Str_Log_RelayUpdatedFmt", team.TeamName, team.EventName, team.Legs.Count));
                RebuildRelayGroupedView();
                FinishAndSyncPatch(BuildSwimmerRowsUpsertPatch(new List<Swimmer>(), new List<RelayTeam> { existingTeam }, null, ClientLabel()), "swimmer");
                // 反馈：更新已存在的接力队
                var existingProxy = _swimmers.FirstOrDefault(s =>
                    s.Country == team.TeamName && s.Gender == team.Gender && s.EventName == team.EventName
                    && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:"));
                string existBib = existingProxy != null ? (existingProxy.BibNumber ?? "") : "";
                message = "接力队信息已更新"; bibNumber = existBib; legCount = team.Legs.Count; updated = true;
                return true;
            }
            _relayTeams.Add(team);
            var touchedRows = new List<Swimmer>();

            // 在_swimmers中创建代表该接力队的条目，统一走日程/分组/成绩流程
            string legNames = "";
            foreach (var leg in team.Legs) legNames += (legNames.Length > 0 ? "," : "") + leg.SwimmerName;
            bibNumber = "R" + (_relayTeams.Count).ToString("D3");
            // 检查重复
            var dup = FindDuplicate(team.TeamName, team.Gender, team.EventName, bibNumber, "", team.TeamName);
            string relayCountryShort = data["countryShort"] != null ? data["countryShort"].ToString() : "";
            string relayAgeGroup = data["ageGroup"] != null ? data["ageGroup"].ToString() : "";
            if (dup == null) {
                var proxy = new Swimmer {
                    BibNumber = bibNumber,
                    Name = team.TeamName,
                    Gender = team.Gender,
                    Country = team.TeamName,
                    CountryShort = relayCountryShort,
                    EventName = team.EventName,
                    EntryTime = team.EntryTime,
                    EntryTimeSeconds = team.EntryTimeSeconds,
                    Notes = string.Format("接力队 棒次:{0}", legNames)
                };
                if (!string.IsNullOrEmpty(relayAgeGroup)) proxy.AgeCategory = relayAgeGroup;
                _swimmers.Add(proxy);
                touchedRows.Add(proxy);
            }

            // 为每位队员创建/更新 Swimmer 子条目（用于存储身份证并承载检录状态）
            foreach (var leg in team.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName)) continue;
                // 队员条目的 BibNumber 取自 RelayLeg.SwimmerBibNumber（若无则生成 teamBib-legN）
                string memBib = !string.IsNullOrEmpty(leg.SwimmerBibNumber)
                    ? leg.SwimmerBibNumber : bibNumber + "-" + leg.LegOrder;

                var memExisting = _swimmers.FirstOrDefault(s =>
                    s.Notes != null && s.Notes.StartsWith("接力队员")
                    && s.EventName == team.EventName && s.Country == team.TeamName
                    && (s.Name == leg.SwimmerName || s.BibNumber == memBib));
                if (memExisting != null) {
                    // 补充/更新身份证号（若新数据非空）
                    if (!string.IsNullOrEmpty(leg.SwimmerIDNumber))
                        memExisting.IDNumber = leg.SwimmerIDNumber;
                    if (!string.IsNullOrEmpty(leg.SwimmerBirthDate))
                        memExisting.BirthDate = leg.SwimmerBirthDate;
                    if (string.IsNullOrEmpty(memExisting.BibNumber)) memExisting.BibNumber = memBib;
                    touchedRows.Add(memExisting);
                } else {
                    var mem = new Swimmer {
                        BibNumber = memBib,
                        Name = leg.SwimmerName,
                        Gender = team.Gender == "混合" ? "男" : team.Gender, // 混合默认标男，可后续编辑
                        Country = team.TeamName,
                        CountryShort = relayCountryShort,
                        IDNumber = leg.SwimmerIDNumber ?? "",
                        BirthDate = leg.SwimmerBirthDate ?? "",
                        EventName = team.EventName,
                        Notes = string.Format("接力队员 {0} 第{1}棒", team.EventName, leg.LegOrder)
                    };
                    if (!string.IsNullOrEmpty(relayAgeGroup)) mem.AgeCategory = relayAgeGroup;
                    _swimmers.Add(mem);
                    touchedRows.Add(mem);
                }
            }

            AddLog(Loc.F("Str_Log_RelayRegisteredFmt", team.TeamName, team.EventName, team.Legs.Count, legNames));
            RebuildRelayGroupedView();
            FinishAndSyncPatch(BuildSwimmerRowsUpsertPatch(touchedRows, new List<RelayTeam> { team }, null, ClientLabel()), "swimmer");
            message = "接力队报名成功"; legCount = team.Legs.Count; updated = false;
            return true;
        }

        // 2026-08-25 竞赛数据服务 服务端入口。
        //   业务规则一份都不在这里 —— 全在 LocalMeetService, 本地和远端不可能
        //   算出两个结果。这里只负责收发。
        //   每次现取服务实例: 换赛事时库会重开, 缓存死了就指向旧库。
        private SwimmingScoreboard.Db.MeetServiceHost _meetRpcHost;

        private void HandleMeetRpc(JObject msg, IWebSocketConnection socket) {
            if (socket == null) return;
            try {
                if (_meetRpcHost == null) {
                    _meetRpcHost = new SwimmingScoreboard.Db.MeetServiceHost(
                        delegate { return (SwimmingScoreboard.Db.IMeetService)_meetDb.Service; },
                        delegate(string s) { try { Dispatcher.BeginInvoke(new Action(delegate { AddLog(s); })); } catch { } });
                }
                string reply = _meetRpcHost.Handle(msg);
                if (!string.IsNullOrEmpty(reply)) EnqueueToSocket(socket, reply);
            } catch (Exception ex) {
                // Handle 内部已经把业务异常打包了; 走到这里说明是收发本身出问题,
                // 也不能让一个客户端的坏请求把服务器搞崩。
                AddLog(Loc.F("Str_Log_CompetitionServiceFailedFmt", ex.Message));
            }
        }

        private void HandleTimingCommand(JObject msg, IWebSocketConnection socket = null) {
            string cmd = msg["command"] != null ? msg["command"].ToString() : "";
            var data = msg["data"];

            // 收到的远端命令统一写日志，便于排查"按了 HTML/EXE 按钮服务器没反应"问题
            AddLog(Loc.F("Str_Log_RemoteCommandFmt", (string.IsNullOrEmpty(cmd) ? "(empty)" : cmd)));

            // ── 2026-09-13 比赛控制的优先级: EXE > 网页 > 主服务器本机 ──────────
            //   同一场比赛只能有一处发令。定下来的次序是:
            //     1) 比赛控制程序(RemoteTimingControl.exe) —— 它接着硬件, 最高
            //     2) 比赛控制网页(race_control.html)
            //     3) 主服务器自己的「比赛控制」页 —— 最低, 有前两者在就锁灰
            //   这里挡的是第 2 层: EXE 在场时, 网页发来的计时命令一律不执行。
            //   【服务端硬拦】而不只是把网页按钮置灰 —— 灰按钮防不住旧版页面和缓存,
            //   而两处同时发令, 谁也说不清现在是什么状态。
            if (IsRaceControlTakenByExe() && socket != null && _timingWebSockets.Contains(socket)) {
                switch (cmd) {
                    case "READY": case "START_RACE": case "RESTART": case "TIMER_RESET":
                    case "CONFIRM_RESULT": case "MARK_DSQ": case "MARK_DNS": case "MARK_DNF":
                    case "MARK_TRI": case "CANCEL_NOTE": case "MANUAL_SPLIT": case "OVERRIDE_TIME":
                        AddLog(Loc.F("Str_Log_RaceControlHeldByExeRejectCmdFmt", cmd));
                        try {
                            EnqueueToSocket(socket, Newtonsoft.Json.JsonConvert.SerializeObject(new {
                                type = "TIMING_CMD_REJECTED", command = cmd,
                                reason = "比赛控制程序(EXE)正在接管 —— 计时请在那台机器上操作"
                            }));
                        } catch { }
                        return;
                }
            }

            // 主服务器角色: 比赛控制类命令一律拒绝, 明确回话, 别让操作员干等。
            // 其余命令(切项目/切组次/显示控制等)照常 —— 它管的是竞赛数据, 不是计时。
            if (IsScoringServerNoTiming) {
                switch (cmd) {
                    case "READY": case "START_RACE": case "RESTART": case "TIMER_RESET":
                    case "CONFIRM_RESULT": case "MARK_DSQ": case "MARK_DNS": case "MARK_DNF":
                    case "MANUAL_SPLIT":
                        AddLog(Loc.F("Str_Log_RoleServerRejectCmdFmt", cmd));
                        if (socket != null) {
                            try {
                                EnqueueToSocket(socket, Newtonsoft.Json.JsonConvert.SerializeObject(new {
                                    type = "TIMING_CMD_REJECTED", command = cmd,
                                    reason = "本机为主服务器，不承担计时，请在计时机上操作"
                                }));
                            } catch { }
                        }
                        return;
                }
            }

            switch (cmd) {
                case "READY":
                    if (_timingBridge != null && _timingBridge.IsConnected) _timingBridge.SendCommand(0x21);
                    Ready_Click(null, null);
                    break;
                case "START_RACE":
                    if (_timingBridge != null && _timingBridge.IsConnected) _timingBridge.SendCommand(0x1C);
                    StartRace_Click(null, null);
                    break;
                case "RESTART":
                case "TIMER_RESET":
                    // 与本地"计时复位"一致：0x20 → 0x7F → 0x43（重发缺道）
                    // 2026-05-26 (revised): 旧推断"0x20 清 0x41 d8 配置位"已证伪 —
                    //   硬件 swimplay.c Reset_Timer 不清 FinalPlace/StartFinalPlace/StartPlace/SwimmingPool_Arrage.
                    //   真正根因是 PC 端 D4→side 映射错位 (line 2619-2628 已修).
                    //   此补发保留为双保险, 防止将来 0x20 路径出现新副作用 — 无害.
                    if (_timingBridge != null && _timingBridge.IsConnected) {
                        _timingBridge.SendCommand(0x20);
                        _timingBridge.DelayBetweenFrames(20);
                        _timingBridge.SendCommand(0x7F);
                        _timingBridge.DelayBetweenFrames(20);
                        try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendSetMatchEventFailedFmt", ex.Message)); }
                        _timingBridge.DelayBetweenFrames(20);
                        try { SendTimingSettingsToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendParamsFailedFmt", ex.Message)); }
                        _timingBridge.DelayBetweenFrames(20);
                        try { SendStartPositionToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendStartPosFailedFmt", ex.Message)); }
                    }
                    Restart_Click(null, null);
                    break;
                case "CONFIRM_RESULT": ConfirmResult_Click(null, null); break;
                // 2026-06-18 race_control.html "公布项目总排名 (存盘)" — 远程触发 PC 端 PublishEventRanking_Click
                case "PUBLISH_EVENT_RANKING_STORE":
                    try { PublishEventRanking_Click(null, null); }
                    catch (Exception ex) { AddLog(Loc.F("Str_Log_RemotePublishRankingFailedFmt", ex.Message)); }
                    break;
                // 2026-06-18 race_control.html "手工补段" — data: lane (int), segNum (int), cumTime (string)
                case "MANUAL_SPLIT":
                    if (data != null) {
                        try {
                            int laneMs = data["lane"] != null ? (int)data["lane"] : -1;
                            int segMs = data["segNum"] != null ? (int)data["segNum"] : 0;
                            string cumMs = data["cumTime"] != null ? data["cumTime"].ToString() : "";
                            if (laneMs < 0 || segMs <= 0 || string.IsNullOrEmpty(cumMs)) {
                                AddLog(Loc.F("Str_Log_ManualSplitInvalidParamsFmt", laneMs, segMs, cumMs)); break;
                            }
                            double cumSec = TimeFormatter.Parse(cumMs);
                            if (cumSec <= 0) { AddLog(Loc.F("Str_Log_ManualSplitParseFailedFmt", cumMs)); break; }
                            var sw = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                                var sa2 = s2.GetAssignmentForStage(_currentStage);
                                return (sa2 != null ? sa2.Lane : s2.Lane) == laneMs;
                            });
                            if (sw == null) { AddLog(Loc.F("Str_Log_ManualSplitSwimmerNotFoundFmt", laneMs)); break; }
                            ApplyManualSplit(sw, segMs, cumSec);
                            AddLog(Loc.F("Str_Log_RemoteManualSplitFmt", laneMs, segMs, cumSec));
                        } catch (Exception ex) { AddLog(Loc.F("Str_Log_ManualSplitFailedFmt", ex.Message)); }
                    }
                    break;
                // 2026-06-02 race_control.html "打印成绩" 远程触发 -> 生成本组成绩 HTML 回送给请求端打印
                case "PRINT_HEAT_RESULT": {
                    if (socket == null) break;
                    try {
                        bool confirmed = _resultConfirmed
                            || _confirmedHeats.Contains(ConfirmedHeatKey(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat));
                        if (!confirmed) {
                            socket.Send(JsonConvert.SerializeObject(new { type = "PRINT_HEAT_RESULT_HTML", error = "当前组成绩未确认" }));
                            AddLog(Loc.T("Str_Log_RemotePrintRejectedNotConfirmed"));
                        } else {
                            string html = BuildHeatResultsHtml();
                            socket.Send(JsonConvert.SerializeObject(new { type = "PRINT_HEAT_RESULT_HTML", html = html, title = "分组成绩" }));
                            AddLog(Loc.T("Str_Log_RemotePrintSentHtml"));
                        }
                    } catch (Exception ex) {
                        try { socket.Send(JsonConvert.SerializeObject(new { type = "PRINT_HEAT_RESULT_HTML", error = ex.Message })); } catch { }
                        AddLog(Loc.F("Str_Log_RemotePrintHtmlFailedFmt", ex.Message));
                    }
                    break;
                }
                // 2026-05-27 远程台 (EXE/HTML) 触发"停表"切换
                case "PAUSE_CLOCK_TOGGLE": PauseClock_Click(null, null); break;
                // 2026-06-05 control.html "成绩 txt 输出" → 1) 拉已完赛列表 2) 选定后构建 txt 内容返回 (浏览器下载)
                case "EXPORT_RESULT_TXT_LIST": {
                    if (socket == null) break;
                    var heats = new List<object>();
                    foreach (var key in _confirmedHeats) {
                        var parts = key.Split('|');
                        if (parts.Length < 5) continue;
                        int hh; if (!int.TryParse(parts[4], out hh)) continue;
                        var sched = _schedule.FirstOrDefault(s =>
                            (s.AgeGroup ?? "") == parts[0] && s.Gender == parts[1]
                            && s.EventName == parts[2] && s.Stage == parts[3]);
                        int session = sched != null ? sched.SessionNumber : 0;
                        var evtMap2 = BuildEventNumberMap();
                        int eventNo2;
                        if (!evtMap2.TryGetValue(parts[1] + "|" + parts[2] + "|" + parts[0], out eventNo2))
                            evtMap2.TryGetValue(parts[1] + "|" + parts[2], out eventNo2);
                        string title = string.Format("{0}{1} {2} {3} 第{4}组",
                            string.IsNullOrEmpty(parts[0]) ? "" : (parts[0] + " "),
                            parts[1], parts[2], parts[3], hh);
                        heats.Add(new {
                            ageGroup = parts[0], gender = parts[1], eventName = parts[2], stage = parts[3], heat = hh,
                            session = session, eventNo = eventNo2,
                            fileName = string.Format("{0:D2}-{1:D2}-{2:D2}.txt", session, eventNo2, hh),
                            title = title
                        });
                    }
                    try { socket.Send(JsonConvert.SerializeObject(new { type = "EXPORT_RESULT_TXT_LIST_RESP", heats = heats })); } catch { }
                    break;
                }
                case "EXPORT_RESULT_TXT_BUILD": {
                    if (socket == null) break;
                    try {
                        var txtData = msg["data"];
                        string ag = txtData["ageGroup"] != null ? txtData["ageGroup"].ToString() : "";
                        string g = txtData["gender"] != null ? txtData["gender"].ToString() : "";
                        string ev = txtData["eventName"] != null ? txtData["eventName"].ToString() : "";
                        string st = txtData["stage"] != null ? txtData["stage"].ToString() : "";
                        int h = txtData["heat"] != null ? (int)txtData["heat"] : 0;
                        var sched = _schedule.FirstOrDefault(s => (s.AgeGroup ?? "") == ag && s.Gender == g && s.EventName == ev && s.Stage == st);
                        int session = sched != null ? sched.SessionNumber : 0;
                        var evtMap3 = BuildEventNumberMap();
                        int eventNo3;
                        if (!evtMap3.TryGetValue(g + "|" + ev + "|" + ag, out eventNo3))
                            evtMap3.TryGetValue(g + "|" + ev, out eventNo3);
                        string content = BuildResultTxtContent(ag, g, ev, st, h);
                        string fileName = string.Format("{0:D2}-{1:D2}-{2:D2}.txt", session, eventNo3, h);
                        socket.Send(JsonConvert.SerializeObject(new {
                            type = "EXPORT_RESULT_TXT_FILE", content = content, fileName = fileName
                        }));
                        AddLog(Loc.F("Str_Log_RemoteResultTxtSentFmt", fileName));
                    } catch (Exception ex) {
                        try { socket.Send(JsonConvert.SerializeObject(new { type = "EXPORT_RESULT_TXT_FILE", error = ex.Message })); } catch { }
                        AddLog(Loc.F("Str_Log_RemoteResultTxtFailedFmt", ex.Message));
                    }
                    break;
                }
                case "QUICK_CONNECT_SERIAL":
                    QuickConnectSerial_Click(null, null);
                    break;
                case "DEVICE_TEST_TOGGLE":
                    DeviceTest_Click(null, null);
                    break;
                //2026-05-19 RemoteTimingControl(远程 EXE) 转发的硬件参数上报 — 进入 ProcessTimingDataFromHardware 复用既有逻辑
                case "BATTERY_REPORT":
                case "TIMINGS_BUNDLE_REPORT":
                case "LANE_ORDER_REPORT":
                case "FINISH_POS_REPORT":
                case "POOL_SIDE_REPORT":
                case "LANE_OPEN_CLOSE_REPORT":
                    HandleHardwareReportForwarded(cmd, data as JObject);
                    break;
                case "UPDATE_SWIMMER":
                    HandleEditorUpdateSwimmer(data as JObject);
                    break;
                case "DELETE_SWIMMER":
                    HandleEditorDeleteSwimmer(data as JObject);
                    break;
                case "LIST_DOCUMENTS":
                    HandleEditorListDocuments();
                    break;
                case "CALCULATE_TEAM_SCORES":
                    HandleEditorCalculateTeamScores();
                    break;
                case "CANCEL_PROMOTION":
                    HandleEditorCancelPromotion(data as JObject);
                    break;
                case "UPDATE_RESULT":
                    HandleEditorUpdateResult(data as JObject);
                    break;
                case "MARK_STATUS":
                    HandleEditorMarkStatus(data as JObject);
                    break;
                case "UPDATE_RELAY":
                    HandleEditorUpdateRelay(data as JObject);
                    break;
                case "DELETE_RELAY":
                    HandleEditorDeleteRelay(data as JObject);
                    break;
                case "UPDATE_EVENT_LIST":
                    HandleEditorUpdateEventList(data as JObject);
                    break;
                case "UPDATE_AGE_GROUP_LIST":
                    HandleEditorUpdateAgeGroupList(data as JObject);
                    break;
                case "UPDATE_GENDER_LIST":
                    HandleEditorUpdateGenderList(data as JObject);
                    break;
                case "UPDATE_STAGE_LIST":
                    HandleEditorUpdateStageList(data as JObject);
                    break;
                case "ADD_SCHEDULE_ITEM":
                    HandleEditorAddScheduleItem(data as JObject);
                    break;
                case "UPDATE_SCHEDULE_ITEM":
                    HandleEditorUpdateScheduleItem(data as JObject);
                    break;
                case "DELETE_SCHEDULE_ITEM":
                    HandleEditorDeleteScheduleItem(data as JObject);
                    break;
                case "GENERATE_REPORT":
                    HandleEditorGenerateReport(data as JObject);
                    break;
                case "ADD_RECORD":
                    HandleEditorAddRecord(data as JObject);
                    break;
                case "UPDATE_RECORD":
                    HandleEditorAddRecord(data as JObject);   // find-or-create 语义
                    break;
                case "DELETE_RECORD":
                    HandleEditorDeleteRecord(data as JObject);
                    break;
                case "EXECUTE_PROMOTION":
                    if (data != null) {
                        // 2026-05-27 加 ageGroup 字段 (旧客户端不带则当不限组别处理 = 兼容)
                        string pAge = data["ageGroup"] != null ? data["ageGroup"].ToString() : "";
                        string pGender = data["gender"] != null ? data["gender"].ToString() : "";
                        string pEvent = data["eventName"] != null ? data["eventName"].ToString() : "";
                        string pFrom = data["fromStage"] != null ? data["fromStage"].ToString() : "";
                        string pNext = data["nextStage"] != null ? data["nextStage"].ToString() : "";
                        int pCount = data["promoCount"] != null ? (int)data["promoCount"] : 8;
                        ExecutePromotion(pAge, pGender, pEvent, pFrom, pNext, pCount);
                    }
                    break;
                case "PUBLISH_RESULT":
                    AddLog(Loc.T("Str_Log_ReceivedPublishResultCmd"));
                    if (data != null) {
                        // 2026-06-16 加 ageGroup 字段 (race_control.html 同步加 send) 修跨组别污染
                        string prAgeGroup = data["ageGroup"] != null ? data["ageGroup"].ToString() : "";
                        string prGender = data["gender"] != null ? data["gender"].ToString() : "";
                        string prEvent = data["eventName"] != null ? data["eventName"].ToString() : "";
                        string prStage = data["stage"] != null ? data["stage"].ToString() : "";
                        int prHeat = data["heat"] != null ? (int)data["heat"] : 1;
                        PublishResultToDisplay(prAgeGroup, prGender, prEvent, prStage, prHeat);
                    }
                    break;
                case "AUTO_GENERATE_HEATS": AutoGenerateHeats_Click(null, null); break;
                case "NEXT_HEAT":
                    if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) {
                        AddLog(Loc.T("Str_Log_CannotNextHeatRacing")); break;
                    }
                    NextHeat_Click(null, null); break;
                case "PREV_HEAT":
                    if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) {
                        AddLog(Loc.T("Str_Log_CannotPrevHeatRacing")); break;
                    }
                    PrevHeat_Click(null, null); break;
                case "SET_GENDER":
                    if (IsHeatSwitchBlocked("切换项目")) break;
                    if (data != null) {
                        _currentGender = data.ToString();
                        AddLog(Loc.F("Str_Log_SetGenderFmt", _currentGender));
                    }
                    break;
                case "SET_AGEGROUP":
                    if (IsHeatSwitchBlocked("切换组别")) break;
                    if (data != null) {
                        _currentAgeGroup = data.ToString() ?? "";
                        AddLog(Loc.F("Str_Log_SetAgeGroupFmt", (string.IsNullOrEmpty(_currentAgeGroup) ? "(any)" : _currentAgeGroup)));
                    }
                    break;
                case "SET_EVENT":
                    if (IsHeatSwitchBlocked("切换项目")) break;
                    if (data != null) SetCurrentEvent(data.ToString());
                    break;
                case "SET_STAGE":
                    if (IsHeatSwitchBlocked("切换赛次")) break;
                    if (data != null) SetCurrentStage(data.ToString());
                    break;
                case "SET_HEAT":
                    if (IsHeatSwitchBlocked("切换组次")) break;
                    if (data != null) SetCurrentHeat((int)data);
                    break;
                case "MARK_DNS":
                    if (data != null) MarkLaneStatus((int)data["lane"], "DNS");
                    break;
                case "MARK_DNF":
                    if (data != null) MarkLaneStatus((int)data["lane"], "DNF");
                    break;
                case "MARK_DSQ":
                    if (data != null) MarkLaneStatus((int)data["lane"], "DSQ");
                    break;
                case "CANCEL_NOTE":
                    if (data != null) CancelLaneNote((int)data["lane"]);
                    break;
                case "USE_BLIND_RESULT":
                    if (data != null) UseBlindResultForCurrentSegment((int)data["lane"]);
                    break;
                case "ADJUST_LAP_DISPLAY":
                    if (data != null) {
                        int aldLane = (int)data["lane"];
                        bool aldLeft = data["isLeft"] != null && (bool)data["isLeft"];
                        int aldDelta = data["delta"] != null ? (int)data["delta"] : 0;
                        if (aldDelta != 0) AdjustLapDisplay(aldLane, aldLeft, aldDelta);
                    }
                    break;
                case "OVERRIDE_TIME":
                    if (data != null) OverrideLaneTime((int)data["lane"], (double)data["time"]);
                    break;
                case "SET_DEVICE_STATUS":
                    if (data != null) SetDeviceStatus((int)data["lane"], data["device"].ToString(), data["status"].ToString());
                    break;
                case "SET_LANE_CLOSE_TIME":
                    if (data != null) {
                        int lane = (int)data["lane"];
                        double time = (double)data["time"];
                        var state = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                        if (state != null) state.LaneCloseTime = time;
                    }
                    break;
                case "SET_MANUAL_STATUS":
                    if (data != null) {
                        int msLane = (int)data["lane"];
                        bool msLeft = data["leftEnabled"] != null && (bool)data["leftEnabled"];
                        bool msRight = data["rightEnabled"] != null && (bool)data["rightEnabled"];
                        var msState = _laneDeviceStates.FirstOrDefault(s => s.Lane == msLane);
                        if (msState != null) {
                            msState.LeftManualEnabled = msLeft;
                            msState.RightManualEnabled = msRight;
                            if (!msLeft) msState.LeftManualStatus = DeviceStatus.Closed;
                            if (!msRight) msState.RightManualStatus = DeviceStatus.Closed;
                        }
                        AddLog(Loc.F("Str_Log_ManualKeyFmt", msLane, msLeft ? Loc.T("Str_Log_Enabled") : Loc.T("Str_Log_Disabled"), msRight ? Loc.T("Str_Log_Enabled") : Loc.T("Str_Log_Disabled")));
                        SaveDeviceStates();         // 远端改动也要持久化
                        UpdateLaneStatusDisplay();  // 刷新本地 UI
                    }
                    break;
                case "SET_LANE_CLOSE_SETTINGS":
                    if (data != null) {
                        if (data["laneCloseTime"] != null) _laneCloseSettings.LaneCloseTime = (double)data["laneCloseTime"];
                        if (data["startBlockCloseDelay"] != null) _laneCloseSettings.StartBlockCloseDelay = (double)data["startBlockCloseDelay"];
                        if (data["resultConfirmCloseDelay"] != null) _laneCloseSettings.ResultConfirmCloseDelay = (double)data["resultConfirmCloseDelay"];
                        if (data["falseStartThreshold"] != null) _laneCloseSettings.FalseStartThreshold = (double)data["falseStartThreshold"];
                        if (data["relayHandoffFalseStartThreshold"] != null) _laneCloseSettings.RelayHandoffFalseStartThreshold = (double)data["relayHandoffFalseStartThreshold"];
                        if (data["splitDisplayTime"] != null) _laneCloseSettings.SplitDisplayTime = (double)data["splitDisplayTime"];
                        if (data["startPosition"] != null) {
                            string pos = data["startPosition"].ToString();
                            _laneCloseSettings.FinishPosition = pos;  // 参数设置的是终点位置（固定）
                            _laneCloseSettings.StartPosition = pos;   // 默认发令位置=终点位置（非50米时）
                            AutoAdjustStartPosition();                // 根据当前项目自动调整
                            // 重置出发台状态到正确一端 (2026-06-14 仰泳改开触板)
                            if (_raceState == RaceState.Waiting || _raceState == RaceState.Ready) {
                                bool isBack1 = IsBackstrokeStartEvent(_currentEvent);
                                foreach (var st in _laneDeviceStates) st.ResetForNewRace(_laneCloseSettings.StartPosition, isBack1);
                            }
                        }
                        // 同步全局设置到所有泳道（清除每道独立值，使用全局值）
                        foreach (var st in _laneDeviceStates) st.LaneCloseTime = 0;
                        if (data["firstPlaceHoldTime"] != null) _laneCloseSettings.FirstPlaceHoldTime = (double)data["firstPlaceHoldTime"];
                        // 左右盲表数量（来自远程台）
                        if (data["leftBlindWatchCount"] != null) {
                            int v = (int)data["leftBlindWatchCount"];
                            if (v >= 0 && v <= 3) _laneCloseSettings.LeftBlindWatchCount = v;
                        }
                        if (data["rightBlindWatchCount"] != null) {
                            int v = (int)data["rightBlindWatchCount"];
                            if (v >= 0 && v <= 3) _laneCloseSettings.RightBlindWatchCount = v;
                        }
                        if (data["bigDisplayPageInterval"] != null) {
                            _laneCloseSettings.BigDisplayPageInterval = (double)data["bigDisplayPageInterval"];
                        }
                        if (data["reactionTimeEnabled"] != null) {
                            _laneCloseSettings.ReactionTimeEnabled = (bool)data["reactionTimeEnabled"];
                        }
                        if (data["laneOrder"] != null) {
                            _laneCloseSettings.LaneOrder = data["laneOrder"].ToString();
                        }
                        // 2026-06-18 race_control.html 远程修改 6 个新参数 (与 PC 端 ShowTimeParamsDialog / ShowPoolDeviceSettingsDialog 同步)
                        if (data["blindReplaceDelay"] != null) {
                            double v = (double)data["blindReplaceDelay"];
                            if (v < 0) v = 0; if (v > 9) v = 9;
                            _laneCloseSettings.BlindReplaceDelay = Math.Round(v, 0);
                        }
                        if (data["reactionEventWindowSec"] != null) {
                            double v = (double)data["reactionEventWindowSec"];
                            if (v < 1) v = 1; if (v > 10) v = 10;
                            _laneCloseSettings.ReactionEventWindowSec = v;
                        }
                        if (data["autoBlindReplaceTouchpad"] != null) _laneCloseSettings.AutoBlindReplaceTouchpad = (bool)data["autoBlindReplaceTouchpad"];
                        if (data["manualTpReplaceTp"] != null) _laneCloseSettings.ManualTpReplaceTp = (bool)data["manualTpReplaceTp"];
                        if (data["hardwareAlwaysOpen"] != null) _laneCloseSettings.HardwareAlwaysOpen = (bool)data["hardwareAlwaysOpen"];
                        if (data["startBoxEdgeFalling"] != null) _laneCloseSettings.StartBoxEdgeFalling = (bool)data["startBoxEdgeFalling"];
                        //2026-05-19 远程台修改"泳池触板单/两端"安装方式: poolSingleSide=true 单端, false 两端
                        if (data["poolSingleSide"] != null) {
                            bool isSingle = (bool)data["poolSingleSide"];
                            bool newHasRight = !isSingle;
                            if (_poolConfig != null && _poolConfig.HasRightStartBlock != newHasRight) {
                                _poolConfig.HasRightStartBlock = newHasRight;
                                _laneCloseSettings.HasRightStartBlock = newHasRight;   // 2026-05-26 持久化
                                try { ApplyTouchpadInstallModeToLanes(); } catch { }
                                try { SaveDeviceStates(); } catch { }                  // 计算后状态落盘
                                // 同步给硬件 (0x3A)
                                if (_timingBridge != null && _timingBridge.IsConnected) {
                                    try { _timingBridge.SendPoolSingleOrDoubleTP(isSingle); } catch { }
                                }
                                AddLog(Loc.F("Str_Log_RemoteChangeTouchpadFmt", isSingle ? Loc.T("Str_Log_Single") : Loc.T("Str_Log_BothEnds")));
                            }
                        }
                        AddLog(Loc.F("Str_Log_ParamsUpdatedFmt",
                            _laneCloseSettings.LaneCloseTime, _laneCloseSettings.StartBlockCloseDelay,
                            _laneCloseSettings.ResultConfirmCloseDelay, _laneCloseSettings.FalseStartThreshold,
                            _laneCloseSettings.SplitDisplayTime, _laneCloseSettings.FinishPosition == "left" ? "左端" : "右端",
                            _laneCloseSettings.LeftBlindWatchCount, _laneCloseSettings.RightBlindWatchCount,
                            _laneCloseSettings.BigDisplayPageInterval,
                            _laneCloseSettings.LaneOrder == "reverse" ? "逆序9→0" : "正序0→9"));
                        SaveTimingSettings();
                        // 2026-08-31 远端(计时端/网页)改了盲表数量, 这里也要把每道的
                        //   NotInstalled 重新套一遍并落盘 —— 否则服务器界面上还是旧的道数。
                        ApplyBlindWatchCountToLanes();
                        SaveDeviceStates();
                        // 2026-09-20 这里改的是 _laneCloseSettings(触板安装方式/盲表数量等
                        //   本机硬件计时参数)——编排端根本不关心也不消费这份数据, 用不着
                        //   为它推一次整包。改用 SaveWithoutPush(), 该有的轻量通知
                        //   (Broadcast() 给 EXE/Web 三端)照旧, 没丢任何该同步的东西。
                        SaveWithoutPush();
                        UpdateLaneStatusDisplay();
                        Broadcast();
                        SendTimingSettingsToHardware();   // 同步到硬件计时控制器
                        // 2026-09-18 【本机是 role=timing 连远端主服务器时补的一环】——
                        //   race_control.html 只能连"本机开着 WebSocket 服务"的那台机器,
                        //   RTC.exe 没有本机服务, race_control.html 连不上它, 原来这条链路
                        //   没人走过。但普通主程序当计时端(IsTimingClientMode)照常开本机
                        //   服务, race_control.html 完全可能连的是这台"计时站", 不是远端
                        //   那份真身主服务器——网页改的参数只在这台机器上生效, 远端主服务器
                        //   一无所知(同一个"改了本机没同步远端"的病根)。内部已按
                        //   IsTimingClientMode 判过, 非计时客户端这里静默跳过。
                        PushSettingsToServer();
                    }
                    break;
                case "OPEN_ALL_LANES":
                    foreach (var s in _laneDeviceStates) {
                        s.LeftTouchpadStatus = DeviceStatus.Open;
                        s.LeftBlindWatch1Status = DeviceStatus.Open; s.LeftBlindWatch2Status = DeviceStatus.Open; s.LeftBlindWatch3Status = DeviceStatus.Open;
                        s.RightTouchpadStatus = DeviceStatus.Open;
                        s.RightBlindWatch1Status = DeviceStatus.Open; s.RightBlindWatch2Status = DeviceStatus.Open; s.RightBlindWatch3Status = DeviceStatus.Open;
                    }
                    break;
                case "CLOSE_ALL_LANES":
                    foreach (var s in _laneDeviceStates) {
                        s.LeftTouchpadStatus = DeviceStatus.Closed;
                        s.LeftBlindWatch1Status = DeviceStatus.Closed; s.LeftBlindWatch2Status = DeviceStatus.Closed; s.LeftBlindWatch3Status = DeviceStatus.Closed;
                        s.RightTouchpadStatus = DeviceStatus.Closed;
                        s.RightBlindWatch1Status = DeviceStatus.Closed; s.RightBlindWatch2Status = DeviceStatus.Closed; s.RightBlindWatch3Status = DeviceStatus.Closed;
                    }
                    break;
                case "MANUAL_LANE_OPEN":
                    if (data != null) {
                        var st = _laneDeviceStates.FirstOrDefault(s => s.Lane == (int)data["lane"]);
                        if (st != null) {
                            st.LeftTouchpadStatus = DeviceStatus.Open;
                            st.LeftBlindWatch1Status = DeviceStatus.Open; st.LeftBlindWatch2Status = DeviceStatus.Open; st.LeftBlindWatch3Status = DeviceStatus.Open;
                            st.RightTouchpadStatus = DeviceStatus.Open;
                            st.RightBlindWatch1Status = DeviceStatus.Open; st.RightBlindWatch2Status = DeviceStatus.Open; st.RightBlindWatch3Status = DeviceStatus.Open;
                            st.LaneCloseCountdown = 0;
                        }
                    }
                    break;
                case "MANUAL_LANE_CLOSE":
                    if (data != null) {
                        var st = _laneDeviceStates.FirstOrDefault(s => s.Lane == (int)data["lane"]);
                        if (st != null) {
                            st.LeftTouchpadStatus = DeviceStatus.Closed;
                            st.LeftBlindWatch1Status = DeviceStatus.Closed; st.LeftBlindWatch2Status = DeviceStatus.Closed; st.LeftBlindWatch3Status = DeviceStatus.Closed;
                            st.RightTouchpadStatus = DeviceStatus.Closed;
                            st.RightBlindWatch1Status = DeviceStatus.Closed; st.RightBlindWatch2Status = DeviceStatus.Closed; st.RightBlindWatch3Status = DeviceStatus.Closed;
                        }
                    }
                    break;
                case "MANUAL_TOUCH_LEFT":
                    //2026-05-31 应急按键: 比赛中 (Racing/Finished) + LeftManualEnabled 就生效, 不看 LeftManualStatus
                    if (data != null && (_raceState == RaceState.Racing || _raceState == RaceState.Finished)) {
                        int laneNum = (int)data["lane"];
                        var lState = _laneDeviceStates.FirstOrDefault(s => s.Lane == laneNum);
                        if (lState != null && lState.LeftManualEnabled) {
                            // 2026-06-04 接力: 左手动 TP 只在当前棒预期完成侧=左时推进 (= 防误推进, 与硬件 TP/MB 守卫对齐)
                            if (_isRelay && _laneCloseSettings != null) {
                                int afterLapMl = lState.CurrentLap + 1;
                                string startMl = _laneCloseSettings.StartPosition;
                                string expectedSideMl = (afterLapMl % 2 == 0) ? startMl : (startMl == "left" ? "right" : "left");
                                if (expectedSideMl != "left") {
                                    AddLog(Loc.F("Str_Log_LeftManualIgnoredSideGuardFmt", laneNum, expectedSideMl == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                                    break;
                                }
                            }
                            lState.LeftManualTouchTime = _runningTime;
                            SaveManualTouchToSplit(laneNum, _runningTime, "left");
                            LogRawTimingData(laneNum, "ManualTouchLeft", _runningTime, "left");
                            AddLog(Loc.F("Str_Log_LeftManualTouchFmt", laneNum, TimeFormatter.Format(_runningTime)));
                            // 2026-06-03 喂入 RelayReactionCalculator (= 接力 SB reaction 14 条规则)
                            //   守卫: 接力交接段 (= afterLap N×perLegLaps) 且不是终点 (= afterLap<totalLaps)
                            //   棒次完成侧 = StartPosition if afterLap 偶 else 另一侧 (= 4×50m 棒次交替). Manual Left 仅当棒完成侧=left 时喂.
                            if (_relayReactionCalc != null && _isRelay && _laneCloseSettings != null) {
                                int tt = GetTotalLaps();
                                int pl = tt > 0 ? tt / 4 : 0;
                                int afterLap = lState.CurrentLap + 1;
                                string expectedSide = (afterLap % 2 == 0)
                                    ? _laneCloseSettings.StartPosition
                                    : (_laneCloseSettings.StartPosition == "left" ? "right" : "left");
                                if (pl > 0 && afterLap % pl == 0 && afterLap < tt && expectedSide == "left") {
                                    _relayReactionCalc.OnEvent(laneNum, "left", RelayReactionCalculator.EventKind.ManualTP, _runningTime);
                                }
                            }
                        } else if (lState != null) {
                            AddLog(Loc.F("Str_Log_LeftManualTouchDisabledFmt", laneNum));
                        }
                    }
                    break;
                case "MANUAL_TOUCH_RIGHT":
                    //2026-05-31 应急按键: 同上
                    if (data != null && (_raceState == RaceState.Racing || _raceState == RaceState.Finished)) {
                        int laneNum = (int)data["lane"];
                        var lState = _laneDeviceStates.FirstOrDefault(s => s.Lane == laneNum);
                        if (lState != null && lState.RightManualEnabled) {
                            // 2026-06-04 接力: 右手动 TP 只在当前棒预期完成侧=右时推进
                            if (_isRelay && _laneCloseSettings != null) {
                                int afterLapMr = lState.CurrentLap + 1;
                                string startMr = _laneCloseSettings.StartPosition;
                                string expectedSideMr = (afterLapMr % 2 == 0) ? startMr : (startMr == "left" ? "right" : "left");
                                if (expectedSideMr != "right") {
                                    AddLog(Loc.F("Str_Log_RightManualIgnoredSideGuardFmt", laneNum, expectedSideMr == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                                    break;
                                }
                            }
                            lState.RightManualTouchTime = _runningTime;
                            SaveManualTouchToSplit(laneNum, _runningTime, "right");
                            LogRawTimingData(laneNum, "ManualTouchRight", _runningTime, "right");
                            AddLog(Loc.F("Str_Log_RightManualTouchFmt", laneNum, TimeFormatter.Format(_runningTime)));
                            // 2026-06-03 喂入 RelayReactionCalculator (= 同上, 棒次完成侧由 afterLap 奇偶决定)
                            if (_relayReactionCalc != null && _isRelay && _laneCloseSettings != null) {
                                int tt = GetTotalLaps();
                                int pl = tt > 0 ? tt / 4 : 0;
                                int afterLap = lState.CurrentLap + 1;
                                string expectedSide = (afterLap % 2 == 0)
                                    ? _laneCloseSettings.StartPosition
                                    : (_laneCloseSettings.StartPosition == "left" ? "right" : "left");
                                if (pl > 0 && afterLap % pl == 0 && afterLap < tt && expectedSide == "right") {
                                    _relayReactionCalc.OnEvent(laneNum, "right", RelayReactionCalculator.EventKind.ManualTP, _runningTime);
                                }
                            }
                        } else if (lState != null) {
                            AddLog(Loc.F("Str_Log_RightManualTouchDisabledFmt", laneNum));
                        }
                    }
                    break;
            }
            Broadcast();
        }

        private void HandleTimingData(JObject msg) {
            // 处理来自远程TimingBridge转发的计时数据
            var data = msg["data"];
            if (data == null) return;
            int lane = (int)data["lane"];
            string cmdType = data["commandType"].ToString();
            double time = (double)data["time"];
            string side = data["side"] != null ? data["side"].ToString() : null;
            // 远程 TimingBridge 转发的抢跳标志（可选；缺省按时间符号判断）
            bool isFalseStart = data["isFalseStart"] != null
                ? (bool)data["isFalseStart"]
                : (cmdType == "StartingBlock" && time < 0);
            ProcessTimingData(lane, cmdType, time, side, isFalseStart);
        }

        private void HandleConnectHw(JObject msg) {
            var d = msg["data"];
            if (d == null) return;
            string mode = d["mode"] != null ? d["mode"].ToString() : "none";
            if (mode == "disconnect") {
                if (_timingBridge != null) { _timingBridge.Disconnect(); UpdateConnectionStatus(); Broadcast(); }
                return;
            }
            if (mode == "serial") {
                string port = d["port"] != null ? d["port"].ToString() : "COM3";
                _timingBridge.ConnectSerial(port);
            } else if (mode == "udp") {
                int udpPort = d["port"] != null ? (int)d["port"] : 5002;
                _timingBridge.ConnectUdp(udpPort);
            } else if (mode == "tcp") {
                string host = d["host"] != null ? d["host"].ToString() : "127.0.0.1";
                int port = d["port"] != null ? (int)d["port"] : 5555;
                _timingBridge.ConnectTcp(host, port);
            }
            UpdateConnectionStatus();
            Broadcast();
        }

        private void HandleRemoteControl(JObject msg, IWebSocketConnection socket) {
            string cmd = msg["command"] != null ? msg["command"].ToString() : "";
            switch (cmd) {
                case "SHOW_LIVE_RACE": BroadcastDisplayMode("SHOW_LIVE_RACE"); break;
                case "SHOW_START_LIST": BroadcastDisplayMode("SHOW_START_LIST"); break;
                case "SHOW_HEAT_RESULT": {
                    // 2026-06-05 计时复位 (=赛次结束) 把 _currentHeat 置 0 → GetCurrentHeatSwimmers 返回空 → 大屏组成绩页空
                    // 修复: 广播前临时回填最近一次已确认的 heat (取 _confirmedHeats 中匹配当前 event/age/gender/stage 的最大 heat)
                    int savedHeat = _currentHeat;
                    if (_currentHeat <= 0 && !string.IsNullOrEmpty(_currentEvent) && !string.IsNullOrEmpty(_currentStage)) {
                        int bestHeat = 0;
                        string ag = _currentAgeGroup ?? "", g = _currentGender ?? "", ev = _currentEvent, st = _currentStage;
                        foreach (var key in _confirmedHeats) {
                            var parts = key.Split('|');
                            if (parts.Length < 5) continue;
                            if (parts[0] != ag || parts[1] != g || parts[2] != ev || parts[3] != st) continue;
                            int hh; if (int.TryParse(parts[4], out hh) && hh > bestHeat) bestHeat = hh;
                        }
                        if (bestHeat > 0) _currentHeat = bestHeat;
                    }
                    BroadcastDisplayMode("SHOW_HEAT_RESULT");
                    _currentHeat = savedHeat;
                    break;
                }
                // 2026-09-27 远程客户端(control.html/RDC)选完项目后带着 4 个 key 字段发回来 —
                //   有就按选定项目回放(校验过, 见 FindConfirmedFinalEventFromMessage); 没带
                //   (老客户端/本机走 ShowEventRanking_Click 那条弹窗路径已经设过) 就保持原样。
                case "SHOW_EVENT_RANKING": {
                    if (msg["eventName"] != null) {
                        var picked = FindConfirmedFinalEventFromMessage(msg);
                        if (picked == null) { AddLog(Loc.T("Str_Msg_NoFinishedFinalsRanking")); break; }
                        _rankingSelection = picked;
                    }
                    BroadcastDisplayMode("SHOW_EVENT_RANKING");
                    break;
                }
                case "LIST_RANKING_CANDIDATES": SendRankingCandidatesListToClient(socket); break;
                case "SHOW_TEAM_STANDINGS": BroadcastDisplayMode("SHOW_TEAM_STANDINGS"); break;
                case "SHOW_RECORDS": BroadcastDisplayMode("SHOW_RECORDS"); break;
                case "SHOW_REFEREES": BroadcastDisplayMode("SHOW_REFEREES"); break;
                case "SHOW_AWARDS": {
                    if (msg["eventName"] != null) {
                        var picked = FindConfirmedFinalEventFromMessage(msg);
                        if (picked == null) { AddLog(Loc.T("Str_Msg_NoFinishedFinalsRanking")); break; }
                        _awardSelection = picked;
                    }
                    BroadcastDisplayMode("SHOW_AWARDS");
                    break;
                }
                // 2026-06-04 PPT 播放: 远端触发主控 PC 上弹 文件选择框 + 启动 PowerPoint /s 放映
                //   注意: 文件对话框只能在 UI 线程弹, 这里 Dispatcher.Invoke 切回 UI 线程
                case "PLAY_PPT":
                    Dispatcher.Invoke(new Action(() => { try { PlayPpt_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemotePptPlayFailedFmt", ex.Message)); } }));
                    break;
                // 2026-06-18 race_control.html "大屏样式" — 在 PC 端弹大屏样式控制窗口
                case "OPEN_DISPLAY_STYLE":
                    Dispatcher.Invoke(new Action(() => { try { OpenDisplayStyle_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteDisplayStyleFailedFmt", ex.Message)); } }));
                    break;
                // 2026-06-18 race_control.html 参数设置 hub 三项 — 远程触发 PC 端本机对话框
                case "OPEN_AUTOSAVE_PATH_DIALOG":
                    Dispatcher.Invoke(new Action(() => { try { AutoSaveTxtPathConfig_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteResultPathFailedFmt", ex.Message)); } }));
                    break;
                case "OPEN_THERMAL_PRINTER_DIALOG":
                    Dispatcher.Invoke(new Action(() => { try { ThermalPrinterConfig_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteThermalPrinterFailedFmt", ex.Message)); } }));
                    break;
                case "OPEN_CHANGE_PASSWORD_DIALOG":
                    Dispatcher.Invoke(new Action(() => { try { EditorChangePassword_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteChangePwdFailedFmt", ex.Message)); } }));
                    break;
                // 2026-06-20 远程释放内存 (race_control.html 顶栏 ♻ 按钮)
                case "RELEASE_MEMORY":
                    Dispatcher.Invoke(new Action(() => { try { ReleaseMemory_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteFreeMemFailedFmt", ex.Message)); } }));
                    break;
                // 2026-06-17 RDC/control.html 完全远程化: list/play 模式 (主控 PC 不弹框)
                // 文件目录: Media/ (图片视频) 和 Documents/PPT/ (PPT 文件), 相对 exe 路径或绝对路径
                case "TOGGLE_RECORDS_HIDDEN":
                    Dispatcher.Invoke(new Action(() => { try { ToggleRecordsHidden_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteToggleRecordsFailedFmt", ex.Message)); } }));
                    break;
                case "TOGGLE_REMARK_REACTION":
                    Dispatcher.Invoke(new Action(() => { try { ToggleRemarkReaction_Click(null, null); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteToggleRemarkFailedFmt", ex.Message)); } }));
                    break;
                case "LIST_MEDIA_FILES":
                    SendMediaFileListToClient(socket);
                    break;
                case "PLAY_MEDIA_FILE":
                    Dispatcher.Invoke(new Action(() => { try { RemotePlayMediaFile(msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemotePlayMediaFailedFmt", ex.Message)); } }));
                    break;
                case "STOP_MEDIA":
                    Dispatcher.Invoke(new Action(() => { try { BroadcastDisplayMode("SHOW_LIVE_RACE"); AddLog(Loc.T("Str_Log_RemoteStopMedia")); } catch { } }));
                    break;
                case "LIST_PPT_FILES":
                    SendPptFileListToClient(socket);
                    break;
                case "PLAY_PPT_FILE":
                    Dispatcher.Invoke(new Action(() => { try { RemotePlayPptFile(msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemotePptUploadFailedFmt", ex.Message)); } }));
                    break;
                case "LIST_SCHEDULE_SESSIONS":
                    SendScheduleSessionListToClient(socket);
                    break;
                case "SHOW_SCHEDULE_SESSION":
                    Dispatcher.Invoke(new Action(() => { try { RemoteShowScheduleSession(msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteShowScheduleFailedFmt", ex.Message)); } }));
                    break;
                // 2026-06-17 双模式: 本机上传 — 客户端把文件 base64 后上传, 主控转发或保存临播
                case "UPLOAD_AND_PLAY_MEDIA":
                    Dispatcher.Invoke(new Action(() => { try { RemoteUploadAndPlayMedia(msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteUploadMediaFailedFmt", ex.Message)); } }));
                    break;
                case "UPLOAD_AND_PLAY_PPT":
                    Dispatcher.Invoke(new Action(() => { try { RemoteUploadAndPlayPpt(msg); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RemoteUploadPptFailedFmt", ex.Message)); } }));
                    break;
                case "SHOW_WELCOME": BroadcastDisplayMode("SHOW_WELCOME"); break;
                case "SHOW_PAUSE": BroadcastDisplayMode("SHOW_PAUSE"); break;
                case "SHOW_EVENT_LIST": BroadcastDisplayMode("SHOW_EVENT_LIST"); break;
                case "SHOW_PROMOTION_LIST": BroadcastDisplayMode("SHOW_PROMOTION_LIST"); break;
            }
        }

        private void HandleFalseStartDetected(JObject msg) {
            // 关闭RT：完全跳过反应时检测/抢跳判定
            if (!_laneCloseSettings.ReactionTimeEnabled) return;
            var data = msg["data"];
            if (data == null) return;
            int lane = (int)data["lane"];
            double reactionTime = (double)data["reactionTime"];
            var state = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (state != null) {
                // 起跳犯规判罚改为人工：硬件检测到的"抢跳"只作为可疑标记（反应时标红），是否判罚由裁判手动 DSQ
                state.IsSuspectFalseStart = true;
                state.ReactionTime = reactionTime;
                AddLog(Loc.F("Str_Log_SuspiciousStartFmt", lane, reactionTime));
            }
            Broadcast();
        }

        /// <summary>
        /// 2026-09-13 比赛控制现在归 EXE 管吗 —— 这个值会广播给 race_control.html /
        /// query.html 等网页, 网页据此决定要不要把自己的操作按钮禁掉。
        /// 2026-09-14 改按【接没接硬件】判, 不再是"连接类型是不是 EXE 就算数":
        ///   · 本机是 RTC 时: 只有 RTC 自己也真接着硬件, 才有资格说"控制权在 EXE"——
        ///     RTC 还没接硬件(比如刚启动、线还没插)时说"控制权在我", 会把网页的按钮
        ///     平白无故禁掉, 而实际上谁都没在控制。
        ///   · 本机是主服务器时: 本机真接着硬件、且没有远程 EXE 也报告接了硬件,
        ///     控制权在本机自己, 不算"被 EXE 拿走"(即使凑巧有个不接硬件的远程 EXE 连着)。
        /// </summary>
        private bool IsRaceControlTakenByExe() {
            if (IsRemoteTimingControlMode) return LocalHasHardware();
            if (LocalHasHardware() && !AnyRemoteExeHasHardware()) return false;
            return _timingExeSockets.Count > 0;
        }

        // 2026-09-14 本机(主服务器)此刻是不是真接着硬件计时器在计时。
        private bool LocalHasHardware() {
            return _timingBridge != null && _timingBridge.IsConnected;
        }

        // 2026-09-14 有没有哪个远程"计时EXE"连接【真的】接着硬件(见 _timingExeInfo)。
        //   跟"_timingExeSockets.Count > 0"不是一回事 —— 后者只说明有个 EXE 连上来了,
        //   不说明它接了硬件(可能只是开着看、或者硬件还没接上)。
        private bool AnyRemoteExeHasHardware() {
            foreach (var kv in _timingExeInfo) { if (kv.Value != null && kv.Value.HwConnected) return true; }
            return false;
        }

        // 2026-09-14 哪台远程机器接着硬件 —— "连接状态"面板用, 明确标出是哪台电脑,
        //   不止是"有没有接"。多台同时报接硬件(误配置)时取第一个, 已经在
        //   UpdateScoringControlMode 里对这种情况单独报过警告。
        private string RemoteExeHardwareMachineName() {
            foreach (var kv in _timingExeInfo) {
                if (kv.Value != null && kv.Value.HwConnected)
                    return string.IsNullOrEmpty(kv.Value.MachineName) ? "(未知机器)" : kv.Value.MachineName;
            }
            return "";
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-09-14 【原则】哪台机器接着硬件计时器正在做比赛计时控制,
        //   哪台机器的"比赛控制"优先级最高 —— 判定依据是"接没接硬件",
        //   不是"连接类型是 EXE 还是网页"。
        //
        //   原来的判定完全按连接类型分 (EXE > Web > 本地): 本机(主服务器)只要
        //   一有远程 EXE/网页连上来就让权、把自己的「比赛控制」页锁上 —— 但如果
        //   本机自己才是那台真正接着硬件在计时的机器, 而对面连上来的 EXE 其实
        //   没接硬件(比如现场另开了一份 RTC.exe 只是看看, 或者硬件线还没插上),
        //   这就是本末倒置: 真正在计时的机器反而被挤下线。
        //
        //   现在改成: 本机有硬件、且没有任何远程 EXE 报告"我也接了硬件"时,
        //   本机稳坐"本地直连"不动, 不管有多少远程 EXE/网页连着——它们此刻
        //   顶多是旁观/待命, 不是真在计时。只有当远程那头明确报告接了硬件,
        //   才按原来的优先级把控制权让出去。
        // ══════════════════════════════════════════════════════════════
        private void UpdateScoringControlMode() {
            // 本机就是比赛控制程序 —— 对连上来的网页而言, 控制权在 EXE 手里
            if (IsRemoteTimingControlMode) {
                _scoringControlMode = "remote_exe";
                if (ControlModeText != null) {
                    ControlModeText.Text = Loc.T("Str_ScoringMode_LocalExe");
                    ControlModeText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B"));
                }
                UpdateRaceControlTabLock();
                return;
            }
            bool localHw = LocalHasHardware();
            bool remoteHw = AnyRemoteExeHasHardware();
            if (localHw && !remoteHw) {
                // 本机真接着硬件, 远程没人接 —— 本机说了算, 不理会挂着的远程连接数量
                _scoringControlMode = "local";
                ControlModeText.Text = Loc.T("Str_ScoringMode_LocalHw");
                ControlModeText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E"));
            } else if (_timingExeSockets.Count > 0) {
                _scoringControlMode = "remote_exe";
                ControlModeText.Text = Loc.T("Str_ScoringMode_RemoteExe");
                ControlModeText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B"));
                // 2026-09-14 两头都接着硬件是误配置(同一台计时器不该被两条线路同时读),
                //   默认仍让远程接管(避免忽左忽右), 但得在日志里喊一声让人去查现场接线。
                if (localHw && remoteHw)
                    AddLog(Loc.T("Str_Log_BothReportHwConnected"));
            } else if (_timingWebSockets.Count > 0) {
                _scoringControlMode = "remote_web";
                ControlModeText.Text = Loc.T("Str_ScoringMode_RemoteWeb");
                ControlModeText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6"));
            } else {
                _scoringControlMode = "local";
                ControlModeText.Text = Loc.T("Str_ScoringMode_Local");
                ControlModeText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E"));
            }
            UpdateRaceControlTabLock();   // 2026-09-13 有远程控制端接管时, 本机「比赛控制」页锁上
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-09-13 【比赛控制归谁, 界面上就得看得出来】
        //
        // 比赛控制程序(RemoteTimingControl.exe)或比赛控制网页(race_control.html)
        // 一连上来, 计时就在那台机器上操作了。这时本机「比赛控制」页里那一堆
        // 就位/发令/复位/判罚按钮全都不该再按 —— 两头同时按, 谁也说不清现在是什么状态。
        //
        // 做成【页签变灰、点不进去】, 不是把按钮一个个禁掉:
        //   · 灰页签一眼就看得出"这台机器现在不管计时", 不用猜
        //   · 按钮一个个禁, 总有漏网的; 页签一锁, 整页都进不去
        // 远程端断开后自动恢复 —— 不用重启, 也不用手动切回来。
        private void UpdateRaceControlTabLock() {
            if (RaceControlTab == null) return;
            // 比赛控制程序(RTC)自己【永远不锁自己】: 它才是接着硬件的那台, 站在它跟前的
            // 操作员必须随时能按。有人另开一个比赛控制网页连到它, 那是它的延伸, 不是接管。
            if (IsRemoteTimingControlMode) return;
            // 2026-09-14 本机真接着硬件、远程没人接硬件时, 不让远程的连接数量(哪怕是 EXE)
            // 把本机这一页锁掉 —— 见 UpdateScoringControlMode 顶上那段【原则】说明。
            bool localTakesPriority = LocalHasHardware() && !AnyRemoteExeHasHardware();
            bool remote = !localTakesPriority && (_timingExeSockets.Count > 0 || _timingWebSockets.Count > 0);
            if (RaceControlTab.IsEnabled == !remote) return;    // 状态没变, 不折腾也不刷日志
            RaceControlTab.IsEnabled = !remote;
            if (remote) {
                string who = Loc.T(_timingExeSockets.Count > 0 ? "Str_Label_TimingExeProgram" : "Str_Label_TimingWebPage");
                RaceControlTab.ToolTip = Loc.F("Str_Tooltip_RaceControlTakenOverFmt", who);
                // 正停在这一页上就先挪走: 页签灰了内容还杵在那儿, 看着像死机
                if (RaceControlTab.IsSelected) {
                    var tc = RaceControlTab.Parent as TabControl;
                    if (tc != null) {
                        foreach (var it in tc.Items) {
                            var t = it as TabItem;
                            if (t != null && !ReferenceEquals(t, RaceControlTab) && t.IsEnabled) { t.IsSelected = true; break; }
                        }
                    }
                }
                AddLog(Loc.F("Str_Log_RaceControlTakenOverFmt", who));
            } else {
                RaceControlTab.ToolTip = null;
                AddLog(Loc.T("Str_Log_RaceControlAllDisconnected"));
            }
        }

        private void UpdateConnectionStatus() {
            if (DisplayConnText == null) return;
            DisplayConnText.Text = _displaySockets.Count.ToString();
            DisplayConnText.Foreground = new SolidColorBrush(_displaySockets.Count > 0 ? Colors.Green : Colors.Red);
            LeaderboardConnText.Text = _leaderboardSockets.Count.ToString();
            LeaderboardConnText.Foreground = new SolidColorBrush(_leaderboardSockets.Count > 0 ? Colors.Green : Colors.Red);
            RegisterConnText.Text = _registerSockets.Count.ToString();
            RegisterConnText.Foreground = new SolidColorBrush(_registerSockets.Count > 0 ? Colors.Green : Colors.Red);
            CheckinConnText.Text = _checkinSockets.Count.ToString();
            CheckinConnText.Foreground = new SolidColorBrush(_checkinSockets.Count > 0 ? Colors.Green : Colors.Red);
            QueryConnText.Text = _querySockets.Count.ToString();
            QueryConnText.Foreground = new SolidColorBrush(_querySockets.Count > 0 ? Colors.Green : Colors.Red);
            DisplayControlConnText.Text = _displayControlSockets.Count.ToString();
            DisplayControlConnText.Foreground = new SolidColorBrush(_displayControlSockets.Count > 0 ? Colors.Green : Colors.Red);
            ScheduleEditorConnText.Text = _scheduleEditorSockets.Count.ToString();
            ScheduleEditorConnText.Foreground = new SolidColorBrush(_scheduleEditorSockets.Count > 0 ? Colors.Green : Colors.Red);
            TimingExeConnText.Text = _timingExeSockets.Count.ToString();
            TimingExeConnText.Foreground = new SolidColorBrush(_timingExeSockets.Count > 0 ? Colors.Green : Colors.Red);
            TimingWebConnText.Text = _timingWebSockets.Count.ToString();
            TimingWebConnText.Foreground = new SolidColorBrush(_timingWebSockets.Count > 0 ? Colors.Green : Colors.Red);
            // 2026-09-14 明确列明是【哪台电脑】接着硬件计时器, 不只是"连了没有"——
            //   本机(主服务器自己)真接着硬件时优先显示本机; 否则看有没有远程 EXE(RTC)
            //   报告接了硬件, 报了就把那台机器的名字亮出来; 都没有才是"未连接"。
            bool _localHwOn = LocalHasHardware();
            string _remoteHwMachine = RemoteExeHardwareMachineName();
            if (_localHwOn) {
                TimingHwConnText.Text = Loc.F("Str_HwConn_LocalMachineFmt", Environment.MachineName);
                TimingHwConnText.Foreground = new SolidColorBrush(Colors.Green);
            } else if (!string.IsNullOrEmpty(_remoteHwMachine)) {
                TimingHwConnText.Text = Loc.F("Str_HwConn_RemoteMachineFmt", _remoteHwMachine);
                TimingHwConnText.Foreground = new SolidColorBrush(Colors.Green);
            } else {
                TimingHwConnText.Text = Loc.T("Str_HwConn_NotConnected");
                TimingHwConnText.Foreground = new SolidColorBrush(Colors.Red);
            }
            //2026-05-19 顶部状态栏右侧的"硬件计时器"指示同步刷新
            bool _hwOn = _timingBridge != null && _timingBridge.IsConnected;
            // 2026-06-15 已连接 = 鲜艳红色(醒目, 比赛中一眼确认硬件在线); 未连接 = 橙色告警(与红区分)
            var _hwOnCol = (Color)ColorConverter.ConvertFromString("#FF1744");   // 鲜艳红
            var _hwOffCol = (Color)ColorConverter.ConvertFromString("#FF9800");  // 橙色告警
            if (HwConnDot != null) HwConnDot.Fill = new SolidColorBrush(_hwOn ? _hwOnCol : _hwOffCol);
            if (HwConnStatusText != null) {
                HwConnStatusText.Text = _hwOn ? Loc.T("Str_SyncStatus_Connected") : Loc.T("Str_HwConn_NotConnected");
                HwConnStatusText.Foreground = new SolidColorBrush(_hwOn ? _hwOnCol : _hwOffCol);
            }
            // 比赛控制面板上的快捷"连接串口"按钮跟随状态变化
            UpdateQuickConnectButton();
        }

        // ═══════════════════════════════════════════════════════════════
        // 广播
        // ═══════════════════════════════════════════════════════════════
        // 2026-06-06 P2-C: Broadcast 反射 SerializeObject 每次 ~1ms, 109 个调用点 + 500ms 心跳,
        //   6h 累积 ~86s UI 线程占用. 现 UI 线程仅快照 statusData (= 缓存的轻调用), 序列化 + Send
        //   扔后台. lock 串行化保证 客户端按调用顺序收到消息.
        private readonly object _broadcastSerialLock = new object();
        // 2026-06-17 方案 B: 主服务器缓存最近一次 RTC 推过来的完整 SHOW_LIVE_RACE 快照,
        //   新连接的 display/control 客户端 OnOpen 时直接 Send 这份, 避免显示空白等待下次事件.
        private string _lastRtcSnapshot;

        // 2026-06-17 方案 D: Broadcast 节流 — 100ms 内多次 Broadcast() 调用合并为 1 次真正执行.
        //   原因: 发令瞬间事件密集 (StartRace_Click 触发数次 Broadcast), 每次都在 UI 线程跑 GetStatusData
        //   (10 泳道 + 分段名次 + LINQ 查询, 单次 50-200ms), 串行 → UI 线程被卡 0.5-2s →
        //   硬件 0x7F 帧 BeginInvoke 排队等不到执行 → _runningTime 不更新 → 滚动时间跳跃.
        //   每帧 SHOW_LIVE_RACE 是全量快照, 100ms 内只看最后一帧已经足够正确, 人眼对 100ms 无感.
        private bool _broadcastPending;
        private DispatcherTimer _broadcastBatchTimer;

        // 2026-06-17 方案 B 统一出口: 已有 JSON 字符串的广播 (PUBLISH_RESULT / SHOW_SCHEDULE / SHOW_MEDIA 等).
        //   RTC 模式: 解析回 JToken 装入 RTC_FORWARD wrapper, 经 EditorSyncClient 推主服务器
        //   主服务器模式: 走原本地 _allSockets 分发 (后台线程串行化)
        /// <returns>这条消息实际发给了几个目标。0 = 一个都没发出去。</returns>
        private int BroadcastJsonToClients(string json) {
            if (IsRemoteTimingControlMode) {
                try {
                    JToken payloadObj = JToken.Parse(json);
                    var wrapper = new JObject { ["type"] = "RTC_FORWARD", ["payload"] = payloadObj };
                    string wrapped = wrapper.ToString(Newtonsoft.Json.Formatting.None);
                    bool up = (_editorSyncClient != null && _editorSyncClient.IsConnected);
                    System.Threading.Tasks.Task.Run(() => {
                        try {
                            if (_editorSyncClient != null && _editorSyncClient.IsConnected) {
                                _editorSyncClient.Send(wrapped);
                            }
                        } catch { }
                    });
                    // 计时端是把消息转给主服务器, 由主服务器再分发。
                    // 所以"送达 1 个"= 转给了主服务器, 不是"有 1 个大屏"。
                    return up ? 1 : 0;
                } catch { }
                return 0;
            }
            // 2026-06-18 per-socket 队列, 慢 socket 自己堵, 不拖快 socket
            int n = _allSockets.Count;
            EnqueueToAll(json);
            return n;
        }

        // 2026-06-17 方案 B 核心: RTC 模式下不发本地 _allSockets, 改通过 EditorSyncClient 推给主服务器,
        //   主服务器收到 RTC_FORWARD 后再分发给所有 display/control 客户端.
        //   返回 true = 已交给主服务器转发链, 调用者无需再走本地分发; false = 非 RTC 模式, 走本地分发.
        private bool TryForwardToMainServer(object payload) { return TryForwardToMainServer(payload, null); }

        /// <summary>
        /// 2026-09-13 to: null=发给所有客户端(老行为，给低频结构性消息兜底); "display"=只发大屏。
        /// 2026-09-15 【广播分级】"others"=只发比赛控制网页(_timingWebSockets, race_control.html)
        /// ——不再是"除大屏外所有人"; "display_control"=大屏∪比赛控制网页(滚动时间用);
        /// "style"=大屏∪比赛控制网页∪显示控制端(大屏样式推送用)。分发定义见服务端
        /// HandleMessage 的 RTC_FORWARD case。
        /// </summary>
        private bool TryForwardToMainServer(object payload, string to) {
            if (!IsRemoteTimingControlMode) return false;
            try {
                if (_editorSyncClient != null && _editorSyncClient.IsConnected) {
                    var wrapper = string.IsNullOrEmpty(to)
                        ? (object)new { type = "RTC_FORWARD", payload }
                        : (object)new { type = "RTC_FORWARD", payload, to };
                    System.Threading.Tasks.Task.Run(() => {
                        try {
                            string json = JsonConvert.SerializeObject(wrapper);
                            _editorSyncClient.Send(json);
                        } catch { }
                    });
                }
            } catch { }
            return true;
        }

        // 2026-06-17 节流入口: 所有调用方调 Broadcast() — 只设 flag + 启 100ms 计时器.
        //   真正执行在 BroadcastImmediate(), 由 BroadcastBatchTick 触发.
        private void Broadcast() {
            if (!_initialized) return;
            _broadcastPending = true;
            if (_broadcastBatchTimer == null) {
                _broadcastBatchTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
                _broadcastBatchTimer.Tick += BroadcastBatchTick;
            }
            if (!_broadcastBatchTimer.IsEnabled) _broadcastBatchTimer.Start();
        }

        private void BroadcastBatchTick(object sender, EventArgs e) {
            _broadcastBatchTimer.Stop();
            if (!_broadcastPending) return;
            _broadcastPending = false;
            BroadcastImmediate();
        }

        // 2026-08-25 比赛中完整包的最小间隔。比赛中静态数据(名单/赛程/下拉列表)
        //   根本不会变, 没必要每 100ms 推一遍 278 KB。
        //   实时那份走 SHOW_LIVE_RACE_LITE, 几 KB, 稳稳在 LOH 门槛(85KB)以下。
        //   完整包仍按这个间隔发, 是为了让还没迁移到 LITE 的客户端照常能用 ——
        //   它们只是刷新慢一点, 不会坏。等客户端全切过去, 这个间隔可以再拉长。
        private DateTime _lastFullBroadcast = DateTime.MinValue;
        //   display.html 和 race_control.html 已经吃 LITE 了; 还在等完整包的只剩
        //   query.html(它只用里面的名单/赛程等静态部分, 慢几秒完全没影响)。
        //   checkin / leaderboard / control / register 压根不消费这个消息。
        private static readonly TimeSpan FullBroadcastGapInRace = TimeSpan.FromSeconds(10);

        private void BroadcastImmediate() {
            if (!_initialized) return;

            bool inRace = (_raceState == RaceState.Ready || _raceState == RaceState.Racing);
            bool full = !inRace || (DateTime.Now - _lastFullBroadcast) >= FullBroadcastGapInRace;
            if (full) _lastFullBroadcast = DateTime.Now;

            // RTC 模式: GetStatusData 在 UI 线程取快照, 通过主服务器转发
            // 2026-09-13 同样只发精简帧。新客户端接进来时由主服务器用自己那份
            //   完整数据兜底(BroadcastSingle) —— 静态部分主服务器手里就是权威的,
            //   实况字段下一帧(100ms)就到, 不需要 RTC 定时重发 278KB。
            if (IsRemoteTimingControlMode) {
                try {
                    var msg = new { type = "SHOW_LIVE_RACE_LITE", data = GetStatusData(false) };
                    // 2026-09-15 【广播分级, 修正】这一路是 RTC 驱动比赛时, 大屏(display.html)
                    //   赖以刷新泳道行/分段成绩/触板成绩/比赛状态的【唯一】周期性来源
                    //   (display.html 收到 SHOW_LIVE_RACE_LITE 后按 staticOmitted 合并进
                    //   data.swimmers/raceState 等字段, 靠它才有实时画面)。
                    //   原来这里是不带 to 的 TryForwardToMainServer(msg)(单参数重载,
                    //   老逻辑落到 EnqueueToAll, 大屏在收件人之列)。上一版广播分级把它
                    //   错改成了 to="others" —— 而 "others" 这次被收窄成只发比赛控制网页
                    //   (_timingWebSockets), 大屏被排除在外了, 后果就是 RTC 驱动时
                    //   大屏的滚动时间/分段成绩/触板成绩全部停更(现场实拍到)。
                    //   改成 to="display_control"(大屏∪比赛控制网页), 大屏重新在收件人里;
                    //   检录台/信息查询/排名屏/报名终端/显示控制/编排端依然不收——它们
                    //   从来不处理这个类型, 这条才是本次分级真正要省的那一路。
                    TryForwardToMainServer(msg, "display_control");
                } catch { }
                return;
            }
            var displays = _displaySockets.ToList();
            // 2026-09-15 【广播分级】"其余客户端"原来是 _allSockets 减大屏 —— 检录台/
            //   信息查询/排名屏/报名终端/显示控制/编排端全在里面, 可它们的页面代码
            //   压根不处理 SHOW_LIVE_RACE_LITE, 收到即丢。真正的订阅者只有比赛控制
            //   网页(race_control.html, _timingWebSockets)。窄成这个集合后:
            //   · 现场只开检录台/查询终端、没人开比赛控制网页时, 这条 100ms 一次的
            //     GetStatusData(false) 计算 + 序列化【彻底不跑了】—— 这才是用户要的
            //     "主服务器省下来干别的事", 不只是省网络流量。
            var others = _timingWebSockets.ToList();
            if (displays.Count == 0 && others.Count == 0) return;   // 无相关客户端时连快照都省, 0 分配
            try {
                string type = full ? "SHOW_LIVE_RACE" : "SHOW_LIVE_RACE_LITE";

                // 2026-08-27 大屏走专用包。这是比赛中最费的一路(每 100ms 一帧),
                //   整包 249KB -> 专用包约 23KB。别的客户端读的字段跟大屏不是一套,
                //   照旧发整包/精简帧。
                if (displays.Count > 0) {
                    var vd = BuildDisplayPayload(type);
                    if (vd != null) {
                        string lite = JsonConvert.SerializeObject(new { type = type, data = vd });
                        foreach (var s in displays) EnqueueToSocket(s, lite);
                    }
                }

                if (others.Count > 0) {
                    // 2026-09-13 【整包不再按时间片发】
                    //   原来每 10 秒给非大屏客户端发一次 278KB 的完整包, 理由是"它们还没
                    //   迁到精简帧"。可整场下来那 278KB 里绝大多数字节从来没变过 ——
                    //   一场三小时的比赛光这一路就是上百 MB, 纯属定时重发。
                    //   现在: 这一路永远只发精简帧; 完整包改成【要才给】——
                    //     · 新客户端连上时发一次(OnOpen → BroadcastSingle)
                    //     · 数据真变了发一条几十字节的 DATA_CHANGED 通知
                    //     · 客户端需要时发 REQUEST_FULL_STATUS 来取
                    //   比赛中没人改数据, 这一路就是彻底的零流量。
                    var msg = new { type = "SHOW_LIVE_RACE_LITE", data = GetStatusData(false) };
                    // 2026-06-18 per-socket 队列, 序列化在主线程做一次, 入队 microsec 级
                    string json = JsonConvert.SerializeObject(msg);
                    foreach (var s in others) EnqueueToSocket(s, json);
                }
            } catch { }
        }

        // ── 2026-09-13 "数据变了"通知 (几十字节) ───────────────────────
        // 完整包不再定时重发, 改成: 数据真变了才吭一声, 客户端要用的时候自己来取
        // (REQUEST_FULL_STATUS)。查询页放在后台没人看时, 这一路一个字节都不走。
        private void PushDataChanged(string what) {
            if (!_initialized) return;
            try {
                if (_allSockets.Count == 0) return;
                var msg = new { type = "DATA_CHANGED", what = what ?? "" };
                string json = JsonConvert.SerializeObject(msg);
                var displays = _displaySockets.ToList();
                foreach (var s in _allSockets.ToList()) {
                    if (displays.Contains(s)) continue;   // 大屏有自己的专用包, 不用管
                    EnqueueToSocket(s, json);
                }
            } catch { }
        }

        private void BroadcastSingle(IWebSocketConnection socket) {
            if (!_initialized) return;
            if (IsRemoteTimingControlMode) return;   // RTC 无本地 socket 列表, 不存在 "Single" 概念
            try {
                var msg = new { type = "SHOW_LIVE_RACE", data = GetStatusData() };
                EnqueueToSocket(socket, JsonConvert.SerializeObject(msg));
            } catch { }
        }

        private void BroadcastDisplayMode(string mode) {
            // 2026-06-21 切到非 SHOW_AWARDS 时清掉 _awardSelection, 避免颁奖选定项目污染后续广播
            if (mode != "SHOW_AWARDS") _awardSelection = null;
            // 2026-06-21 同样守 _rankingSelection (总排名回放选定项目)
            if (mode != "SHOW_EVENT_RANKING") _rankingSelection = null;
            // 2026-06-17 方案 B: RTC 模式通过主服务器转发, 不开本地 Server.
            if (IsRemoteTimingControlMode) {
                // ── 2026-09-13 分开发, 别再一律甩 278KB ──────────────────────
                //   原来这里把 GetStatusData() 整包(实测 278KB)转给主服务器, 主服务器
                //   又原样发给【所有】客户端 —— 大屏切个视图要等那 278KB 传完再解析,
                //   现场感觉就是"按了半天才变"。非 RTC 那条路早就是大屏走专用包(约 23KB)了,
                //   RTC 这条一直没跟上。现在照着分:
                //     大屏  → BuildDisplayPayload(mode) 专用包
                //     其余  → 精简帧(静态部分他们本来就留着, 要整包会自己来取)
                try {
                    var vd = BuildDisplayPayload(mode);
                    if (vd != null)
                        TryForwardToMainServer(new { type = mode, data = vd, modeExplicit = true }, "display");
                    TryForwardToMainServer(
                        new { type = mode, data = GetStatusData(vd == null), modeExplicit = true },
                        vd == null ? null : "others");
                } catch { }
                return;
            }
            if (_allSockets.Count == 0) return;
            try {
                // 2026-08-27 大屏走【专用包】: 只算、只发这个视图要用的数据。
                //   其余客户端(控制页/检录台/成绩榜/查询页)照旧收整包 —— 它们读的字段
                //   跟大屏不是一套(比如 query.html 真在读 allSwimmers), 不能一起瘦。
                var viewData = BuildDisplayPayload(mode);
                var displays = _displaySockets.ToList();

                if (viewData != null && displays.Count > 0) {
                    string lite = JsonConvert.SerializeObject(new { type = mode, data = viewData, modeExplicit = true });
                    foreach (var s in displays) EnqueueToSocket(s, lite);
                }

                // 只有确实存在"非大屏"客户端时才去算整包 —— 没有就一次都不算
                var others = _allSockets.Where(s => viewData == null || !displays.Contains(s)).ToList();
                if (others.Count > 0) {
                    // 2026-05-25 modeExplicit=true 区分"操作员主动切显示模式" 与 "服务器状态心跳"
                    // 2026-06-18 per-socket 队列, 主线程序列化 + 入队后立即返回
                    string full = JsonConvert.SerializeObject(new { type = mode, data = GetStatusData(), modeExplicit = true });
                    foreach (var s in others) EnqueueToSocket(s, full);
                }
            } catch { }
        }

        // 轻量级滚动时间广播：硬件每 100ms 发一帧 0x7F，主服务器收到后立刻把当前
        // _runningTime 发给所有客户端（大屏 / 计时控制台）。只送 type+runningTime 两个字段，
        // 比 Broadcast() 全量状态轻得多，适合 10Hz 高频转发。
        // 2026-06-18 复位后阻断非零 RUNNING_TIME 广播标志:
        //   Reset_Click 设 true → 后续硬件残帧 (= 已在 TCP 缓冲 / 硬件 0x20 处理延迟内) 触发的
        //   BroadcastRunningTime 全部被拒, 大屏不再收到非零滚动时间;
        //   直到 ProcessTimingData 收到硬件真发 0x7F ≈ 0 时, BroadcastRunningTime 内自动解锁继续正常发送.
        //   Ready_Click 也清此标志, 避免上场残留影响新比赛.
        private bool _broadcastSuppressing = false;

        private void BroadcastRunningTime() {
            if (!_initialized) return;
            // 复位抑制窗口: 仅放行 ≈0 的帧, 拒发非零硬件残帧
            double _tt = _clockPaused ? _pausedRunningTime : _runningTime;
            if (_broadcastSuppressing) {
                if (_tt > 0.05) return;
                _broadcastSuppressing = false;   // 0 来了, 解锁后正常发送
            }
            // 2026-06-17 方案 B: RTC 模式通过主服务器转发. 这条 10Hz 高频帧不能阻塞 UI,
            //   TryForwardToMainServer 内部已经 Task.Run 后台发送.
            if (IsRemoteTimingControlMode) {
                try {
                    double tt = _clockPaused ? _pausedRunningTime : _runningTime;
                    var msg = new {
                        type = "RUNNING_TIME_UPDATE",
                        data = new {
                            runningTime = TimeFormatter.FormatRunning(tt),
                            clockPaused = _clockPaused
                        }
                    };
                    // 2026-09-15 【广播分级】滚动时间只有"大屏"和"比赛控制网页"要看,
                    //   检录台/信息查询/排名屏/报名终端/显示控制/编排端都不显示这个,
                    //   原来 10Hz 群发给所有人。带 to="display_control", 主服务器只转给
                    //   _displaySockets ∪ _timingWebSockets(定义见 RTC_FORWARD case)。
                    TryForwardToMainServer(msg, "display_control");
                } catch { }
                return;
            }
            // 2026-09-15 【广播分级】同上, 收件人从 _allSockets 收窄成"大屏 ∪ 比赛控制网页"。
            if (_displaySockets.Count == 0 && _timingWebSockets.Count == 0) return;
            try {
                // 2026-05-27 停表期间高频转发也用快照值, 防止冻结画面被 100ms 频率的真实时间覆盖
                double t = _clockPaused ? _pausedRunningTime : _runningTime;
                var msg = new {
                    type = "RUNNING_TIME_UPDATE",
                    data = new {
                        runningTime = TimeFormatter.FormatRunning(t),
                        clockPaused = _clockPaused
                    }
                };
                string json = JsonConvert.SerializeObject(msg);
                EnqueueToSet(_displaySockets.Concat(_timingWebSockets), json);
            } catch { }
        }

        private object GetStatusData() { return GetStatusData(true); }

        /// <summary>
        /// keepStatic=false 时, 名单/赛程/接力队/团体分/各下拉列表 一律给空数组,
        /// 只留"这一组正在发生的事"。这份精简包只走 SHOW_LIVE_RACE_LITE 这个新
        /// 消息类型, 老客户端按 type 分发, 根本收不到它, 所以置空不会影响谁。
        ///
        /// 为什么要拆: 完整包实测 278 KB, 而大对象堆的门槛是 85 KB —— 比赛中每
        /// 100ms 推一份, 每份都进 LOH 且大小各不相同, 空洞装不下新的只能开新段;
        /// LOH 又不压缩, 所以确认成绩后那两次强制 Gen2 GC 也回收不掉。
        /// 实测第 1~3 场 94 个组 + 5 个客户端: 推 15905 条 / 4.3 GB,
        /// 进程从 171 MB 涨到 2213 MB, 其中 1931 MB 是 LOH。
        /// 这就是现场"内存翻红、清内存也没用"的根。
        ///
        /// 用 Take(0) 而不是把字段删掉, 是为了让匿名类型的形状保持一致 ——
        /// 两条路共用同一个方法, 不会随时间漂移成两份。
        /// </summary>
        // ══════════════════════════════════════════════════════════════
        // 当前组的泳道数据。整包(GetStatusData)和大屏专用包(BuildDisplayPayload)
        // 都调这一个 —— 【只此一份】, 免得将来改了一处漏了另一处, 两边输出对不上。
        // ══════════════════════════════════════════════════════════════
        private List<object> BuildSwimmerPayload() {
            // 构建当前组运动员数据
            var swimmerData = new List<object>();
            var currentSwimmers = GetCurrentHeatSwimmers();
            // 实时分段名次（广播给客户端）
            var liveRanksForBroadcast = ComputeLiveRanks(currentSwimmers);
            foreach (var sw in currentSwimmers) {
                // 获取该赛次的泳道号（优先StageAssignment，不受晋级影响）
                var stageAssign = sw.GetAssignmentForStage(_currentStage);
                int displayLane = stageAssign != null ? stageAssign.Lane : sw.Lane;

                var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == displayLane);
                var result = sw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                var latestSplit = result != null && result.Splits.Count > 0 ? result.Splits.Last() : null;

                // 接力项目：name显示队员姓名
                string bcastName = sw.Name;
                if (_isRelay && !string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:")) {
                    bcastName = sw.Notes.Substring("接力队 棒次:".Length);
                }
                swimmerData.Add(new {
                    lane = displayLane,
                    name = bcastName,
                    country = sw.Country,
                    countryShort = sw.CountryShort ?? "",
                    ageGroup = sw.AgeCategory ?? "",
                    gender = sw.Gender ?? "",          // 2026-06-04 男女 并项时 display.html 用此字段分段
                    bibNumber = sw.BibNumber,
                    entryTime = sw.EntryTime ?? "",
                    direction = laneState != null ? laneState.Direction : (_laneCloseSettings.StartPosition == "right" ? "←" : "→"),
                    deviceStatus = new {
                        leftTouchpad = laneState != null ? laneState.LeftTouchpadStatus.ToString().ToLower() : "closed",
                        leftBlindWatch1 = laneState != null ? laneState.LeftBlindWatch1Status.ToString().ToLower() : "closed",
                        leftBlindWatch2 = laneState != null ? laneState.LeftBlindWatch2Status.ToString().ToLower() : "closed",
                        leftBlindWatch3 = laneState != null ? laneState.LeftBlindWatch3Status.ToString().ToLower() : "closed",
                        leftStartBlock = laneState != null ? laneState.LeftStartBlockStatus.ToString().ToLower() : "open",
                        rightTouchpad = laneState != null ? laneState.RightTouchpadStatus.ToString().ToLower() : "closed",
                        rightBlindWatch1 = laneState != null ? laneState.RightBlindWatch1Status.ToString().ToLower() : "closed",
                        rightBlindWatch2 = laneState != null ? laneState.RightBlindWatch2Status.ToString().ToLower() : "closed",
                        rightBlindWatch3 = laneState != null ? laneState.RightBlindWatch3Status.ToString().ToLower() : "closed",
                        rightStartBlock = laneState != null ? laneState.RightStartBlockStatus.ToString().ToLower() : "closed",
                        // 损坏标志
                        leftTouchpadBroken = laneState != null && laneState.LeftTouchpadBroken,
                        leftBlindWatch1Broken = laneState != null && laneState.LeftBlindWatch1Broken,
                        leftBlindWatch2Broken = laneState != null && laneState.LeftBlindWatch2Broken,
                        leftBlindWatch3Broken = laneState != null && laneState.LeftBlindWatch3Broken,
                        leftStartBlockBroken = laneState != null && laneState.LeftStartBlockBroken,
                        rightTouchpadBroken = laneState != null && laneState.RightTouchpadBroken,
                        rightBlindWatch1Broken = laneState != null && laneState.RightBlindWatch1Broken,
                        rightBlindWatch2Broken = laneState != null && laneState.RightBlindWatch2Broken,
                        rightBlindWatch3Broken = laneState != null && laneState.RightBlindWatch3Broken,
                        rightStartBlockBroken = laneState != null && laneState.RightStartBlockBroken,
                        // 2026-05-31 硬件颜色 (= 0x50/0x51/0x52 协议 newState 0-5), 跟 PC 控制端 StyleDotMixed 同源
                        hwLeftTouchpad = laneState != null ? laneState.HwLeftTouchpadColor : (byte)0,
                        hwLeftStartBlock = laneState != null ? laneState.HwLeftStartBlockColor : (byte)0,
                        hwLeftBlindWatch1 = laneState != null ? laneState.HwLeftBlindWatch1Color : (byte)0,
                        hwLeftBlindWatch2 = laneState != null ? laneState.HwLeftBlindWatch2Color : (byte)0,
                        hwLeftBlindWatch3 = laneState != null ? laneState.HwLeftBlindWatch3Color : (byte)0,
                        hwRightTouchpad = laneState != null ? laneState.HwRightTouchpadColor : (byte)0,
                        hwRightStartBlock = laneState != null ? laneState.HwRightStartBlockColor : (byte)0,
                        hwRightBlindWatch1 = laneState != null ? laneState.HwRightBlindWatch1Color : (byte)0,
                        hwRightBlindWatch2 = laneState != null ? laneState.HwRightBlindWatch2Color : (byte)0,
                        hwRightBlindWatch3 = laneState != null ? laneState.HwRightBlindWatch3Color : (byte)0
                    },
                    manualButton = new {
                        leftEnabled = laneState != null && laneState.LeftManualEnabled,
                        rightEnabled = laneState != null && laneState.RightManualEnabled,
                        leftStatus = laneState != null ? laneState.LeftManualStatus.ToString().ToLower() : "closed",
                        rightStatus = laneState != null ? laneState.RightManualStatus.ToString().ToLower() : "closed"
                    },
                    laneCloseCountdown = laneState != null ? laneState.LaneCloseCountdown : 0,
                    // 2026-06-04 接力比赛结束(Finished)后大屏/Web 不显反应时 (= 比赛中显当前棒)
                    // 2026-06-20 NaN = 反应时窗口超时未收到 SB → 显 "---" (硬件没接 / 信号未到时不报抢跳)
                    reactionTime = (_laneCloseSettings.ReactionTimeEnabled && laneState != null
                                     && !(_isRelay && _raceState == RaceState.Finished))
                        ? (double.IsNaN(laneState.ReactionTime) ? "---"
                            : (laneState.ReactionTime == 0 ? "" : laneState.ReactionTime.ToString("F2")))
                        : "",
                    // 反应时序号：每次 laneState.ReactionTime 写入即 +1，用于客户端识别"新一棒反应时"
                    // 触发大屏备注栏的反应时显示窗口（接力 4 棒共 4 个 seq）
                    reactionSeq = laneState != null ? laneState.ReactionSeq : 0,
                    splits = result != null ? result.Splits.Select(sp => new {
                        lap = sp.Lap, distance = sp.Distance,
                        time = TimeFormatter.Format(sp.Time), cumulative = TimeFormatter.Format(sp.CumulativeTime),
                        touchpad = TimeFormatter.Format(sp.TouchpadTime),
                        blind1 = TimeFormatter.Format(sp.PushButton1Time), blind2 = TimeFormatter.Format(sp.PushButton2Time), blind3 = TimeFormatter.Format(sp.PushButton3Time),
                        manual = TimeFormatter.Format(sp.ManualTouchTime), source = sp.TimingSource
                    }).ToList<object>() : new List<object>(),
                    // ══════════════════════════════════════════════════════
                    // 2026-09-01 判罚状态改用【有效状态】(成绩行优先, 否则运动员)。
                    //
                    // 原来这三个字段都只看 sw.Status(运动员级)。而计时端回推过来的
                    // 成绩里, 判罚是记在【成绩行】上的 —— HandleHeatConfirmedPush 只
                    // sw.Results.Add(lr), 从不设 sw.Status。于是主服务器上:
                    //   sw.Status = ""  =>  大屏照发 finalTime, status 空,
                    //   备注栏没有 DNS 可显, 就退回去显 recordNote = MR。
                    // 现场拍到的就是这个: 大屏"组成绩"里 DNF/DNS 的人有成绩、带着 MR。
                    //
                    // "成绩行优先"这条规矩 2026-08-19 已经在成绩与排名那边立过
                    // (GetEffectiveStatus), 广播这一处当时漏了。
                    // ══════════════════════════════════════════════════════
                    // 2026-06-04 TRI 正常显成绩 (finalTime), 但 rank=0 (= 不参与排名, 客户端按 0 渲染空白)
                    finalTime = ResultOrdering.IsJudged(GetEffectiveStatus(sw, result)) ? "" : (result != null ? TimeFormatter.Format(result.FinalTime) : ""),
                    // 实时分段名次：有则用 liveRank，否则回退到 result.Rank; TRI 强制 0
                    rank = (ResultOrdering.StatusOrder(GetEffectiveStatus(sw, result)) != 5) ? 0
                        : (liveRanksForBroadcast.ContainsKey(sw) ? liveRanksForBroadcast[sw]
                           : (result != null ? result.Rank : 0)),
                    status = GetEffectiveStatus(sw, result),
                    timingSources = result != null ? new {
                        touchpad = TimeFormatter.Format(result.TouchpadTime),
                        blindWatch1 = TimeFormatter.Format(result.PushButton1Time),
                        blindWatch2 = TimeFormatter.Format(result.PushButton2Time),
                        blindWatch3 = TimeFormatter.Format(result.PushButton3Time),
                        manualTouchLeft = laneState != null && laneState.LeftManualTouchTime > 0
                            ? TimeFormatter.Format(laneState.LeftManualTouchTime)
                            : "",
                        manualTouchRight = laneState != null && laneState.RightManualTouchTime > 0
                            ? TimeFormatter.Format(laneState.RightManualTouchTime)
                            : "",
                        manual = result.Splits.Count > 0 && result.Splits.Last().ManualTouchTime > 0
                            ? TimeFormatter.Format(result.Splits.Last().ManualTouchTime)
                            : (laneState != null ? TimeFormatter.Format(Math.Max(laneState.LeftManualTouchTime, laneState.RightManualTouchTime)) : "")
                    } : (object)null,
                    isFalseStart = laneState != null && laneState.IsFalseStart,
                    isSuspectFalseStart = laneState != null && laneState.IsSuspectFalseStart,
                    // 2026-09-01 判罚/弃权/试游都不发纪录标识 —— 他们的成绩不参与排名,
                    //   自然也不能算破纪录。现场拍到过: 大屏上 DNF 那一行成绩空着,
                    //   备注却是金色的 MR。(StatusOrder != 5 = TRI/DSQ/DQ/DNF/DNS)
                    isNewRecord = result != null && !string.IsNullOrEmpty(result.RecordNote)
                                  && ResultOrdering.StatusOrder(GetEffectiveStatus(sw, result)) == 5,
                    recordNote = (result != null && ResultOrdering.StatusOrder(GetEffectiveStatus(sw, result)) == 5)
                                 ? (result.RecordNote ?? "") : "",
                    // 2026-06-18 同步 PC 端 UI 关键字段给 race_control.html (HTML 端可显示同款信息)
                    finishTpMbDispute = laneState != null && laneState.FinishTpMbDispute,
                    // 2026-06-20 NaN → "---" (接力第 1 棒 SB 未收到时窗口超时标 NaN)
                    legReactionTimes = (_isRelay && result != null && result.LegReactionTimes != null)
                        ? result.LegReactionTimes.Select(rt => (object)(double.IsNaN(rt) ? "---" : rt.ToString("F2"))).ToList<object>()
                        : new List<object>(),
                    blindHistory = (_laneBlindHistory.ContainsKey(displayLane) && _laneBlindHistory[displayLane] != null)
                        ? _laneBlindHistory[displayLane].Take(20).Select(be => TimeFormatter.Format(be.TimeSeconds)).ToList<object>()
                        : new List<object>(),
                    currentLap = laneState != null ? laneState.CurrentLap : 0,
                    // 含 spinner 人工偏移的"显示用当前圈数" = 总圈数 − 左剩余显示 − 右剩余显示。
                    // 接力赛大屏 / 三端控制台据此推算"第N棒"，让加圈/减圈即时切换棒次显示。
                    displayedCurrentLap = laneState != null ? GetDisplayedCurrentLap(laneState) : 0,
                    // 已记录最终成绩的运动员（即便 LaneDeviceState.IsFinished 因切组被复位）也算作完赛
                    isFinished = (laneState != null && laneState.IsFinished) || (result != null && result.FinalTime > 0),
                    leftTouchRemain = GetDisplayedLapCount(laneState, true),
                    rightTouchRemain = GetDisplayedLapCount(laneState, false)
                });
            }

            // 为空泳道（无运动员或无当前组）添加占位，使客户端总能显示全部泳道
            var assignedLanes = new HashSet<int>();
            foreach (var o in swimmerData) {
                try { assignedLanes.Add((int)((dynamic)o).lane); } catch { }
            }
            if (_poolConfig.LaneNumbers != null) {
                foreach (int ln in _poolConfig.LaneNumbers) {
                    if (assignedLanes.Contains(ln)) continue;
                    var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == ln);
                    string testLeftEvt = (_testMode && _testLastEventLeft.ContainsKey(ln)) ? _testLastEventLeft[ln] : "";
                    string testRightEvt = (_testMode && _testLastEventRight.ContainsKey(ln)) ? _testLastEventRight[ln] : "";
                    swimmerData.Add(new {
                        lane = ln,
                        name = "", country = "", countryShort = "", ageGroup = "",
                        bibNumber = "", entryTime = "",
                        direction = ls != null ? ls.Direction : "",
                        // 真实设备状态（不再硬编码 "closed"）— 测试模式下客户端要看到 Open/Touched
                        deviceStatus = new {
                            leftTouchpad      = ls != null ? ls.LeftTouchpadStatus.ToString().ToLower()      : "closed",
                            leftBlindWatch1   = ls != null ? ls.LeftBlindWatch1Status.ToString().ToLower()   : "closed",
                            leftBlindWatch2   = ls != null ? ls.LeftBlindWatch2Status.ToString().ToLower()   : "closed",
                            leftBlindWatch3   = ls != null ? ls.LeftBlindWatch3Status.ToString().ToLower()   : "closed",
                            leftStartBlock    = ls != null ? ls.LeftStartBlockStatus.ToString().ToLower()    : "closed",
                            rightTouchpad     = ls != null ? ls.RightTouchpadStatus.ToString().ToLower()     : "closed",
                            rightBlindWatch1  = ls != null ? ls.RightBlindWatch1Status.ToString().ToLower()  : "closed",
                            rightBlindWatch2  = ls != null ? ls.RightBlindWatch2Status.ToString().ToLower()  : "closed",
                            rightBlindWatch3  = ls != null ? ls.RightBlindWatch3Status.ToString().ToLower()  : "closed",
                            rightStartBlock   = ls != null ? ls.RightStartBlockStatus.ToString().ToLower()   : "closed",
                            leftTouchpadBroken    = ls != null && ls.LeftTouchpadBroken,
                            leftBlindWatch1Broken = ls != null && ls.LeftBlindWatch1Broken,
                            leftBlindWatch2Broken = ls != null && ls.LeftBlindWatch2Broken,
                            leftBlindWatch3Broken = ls != null && ls.LeftBlindWatch3Broken,
                            leftStartBlockBroken  = ls != null && ls.LeftStartBlockBroken,
                            rightTouchpadBroken    = ls != null && ls.RightTouchpadBroken,
                            rightBlindWatch1Broken = ls != null && ls.RightBlindWatch1Broken,
                            rightBlindWatch2Broken = ls != null && ls.RightBlindWatch2Broken,
                            rightBlindWatch3Broken = ls != null && ls.RightBlindWatch3Broken,
                            rightStartBlockBroken  = ls != null && ls.RightStartBlockBroken,
                            // 2026-05-31 硬件颜色 (= 0x50/0x51/0x52 协议)
                            hwLeftTouchpad = ls != null ? ls.HwLeftTouchpadColor : (byte)0,
                            hwLeftStartBlock = ls != null ? ls.HwLeftStartBlockColor : (byte)0,
                            hwLeftBlindWatch1 = ls != null ? ls.HwLeftBlindWatch1Color : (byte)0,
                            hwLeftBlindWatch2 = ls != null ? ls.HwLeftBlindWatch2Color : (byte)0,
                            hwLeftBlindWatch3 = ls != null ? ls.HwLeftBlindWatch3Color : (byte)0,
                            hwRightTouchpad = ls != null ? ls.HwRightTouchpadColor : (byte)0,
                            hwRightStartBlock = ls != null ? ls.HwRightStartBlockColor : (byte)0,
                            hwRightBlindWatch1 = ls != null ? ls.HwRightBlindWatch1Color : (byte)0,
                            hwRightBlindWatch2 = ls != null ? ls.HwRightBlindWatch2Color : (byte)0,
                            hwRightBlindWatch3 = ls != null ? ls.HwRightBlindWatch3Color : (byte)0
                        },
                        manualButton = new {
                            leftEnabled = ls != null && ls.LeftManualEnabled,
                            rightEnabled = ls != null && ls.RightManualEnabled,
                            leftStatus  = ls != null ? ls.LeftManualStatus.ToString().ToLower()  : "closed",
                            rightStatus = ls != null ? ls.RightManualStatus.ToString().ToLower() : "closed"
                        },
                        laneCloseCountdown = 0.0,
                        reactionTime = "",
                        splits = new List<object>(),
                        finalTime = "",
                        rank = 0,
                        status = _testMode ? "" : "EMPTY",   // 测试模式不打 EMPTY 标记，避免客户端淡化
                        timingSources = (object)null,
                        isFalseStart = false,
                        isSuspectFalseStart = false,
                        isNewRecord = false,
                        recordNote = "",
                        currentLap = 0,
                        isFinished = false,
                        leftTouchRemain = "",
                        rightTouchRemain = "",
                        // 测试模式：左/右最近事件文字（"触 23.45" / "出发 0.42"）
                        testLeftEvent = testLeftEvt,
                        testRightEvent = testRightEvt
                    });
                }
            }
            // 按泳道号排序（空泳道正确插入对应位置）
            swimmerData = swimmerData.OrderBy(o => { try { return (int)((dynamic)o).lane; } catch { return 0; } }).ToList();
            return swimmerData;
        }

        private object GetStatusData(bool keepStatic) {
            int staticN = keepStatic ? int.MaxValue : 0;
            var swimmerData = BuildSwimmerPayload();

            int currentEventNumber = BuildCurrentEventNumber();

            // 项目总排名
            // 2026-08-25 这三块只有"总排名 / 组成绩 / 纪录"视图用得上, 比赛实况视图不看。
            //   放进每 100ms 的精简帧纯属浪费: 一是把帧撑大(撑过 LOH 门槛就前功尽弃),
            //   二是每秒白算十几次全项目排名。操作员切到总排名视图时, 低频的完整包
            //   会把它们带上, 慢几秒没有影响。
            var eventRanking = keepStatic ? GetEventRanking(_currentEvent, _currentGender) : new List<object>();
            // 2026-06-02 并项拆分: 按 (性别, 实际年龄) 切多张子表, 大屏 总排名 视图按子表翻页
            var eventRankingSplit = keepStatic ? GetEventRankingsSplit(_currentAgeGroup, _currentEvent, _currentGender) : new List<object>();
            // 2026-06-05 项目名称下 一行 显示 本项目所有组别 纪录 (大屏 比赛视图/组成绩/总排名 用)
            var applicableRecords = keepStatic ? BuildApplicableRecords(_currentEvent, _currentGender) : new List<object>();
            var teamScoresData = BuildTeamScoresPayload(staticN);

            // 2026-08-25 把"这一帧里哪些字段被置空了"随帧带过去。
            //   客户端照着这个合并, 就不用自己维护一张要跟这里一一对应的名单 ——
            //   前一版就是客户端漏列 applicableRecords, 比赛一开始项目名下那行
            //   纪录(MR)被空数组冲掉了。名单由产生方给出, 天然不会对不齐。
            var staticOmitted = keepStatic ? new List<string>() : new List<string> {
                "allSwimmers", "allRelayTeams", "schedule", "teamScores",
                "ageGroups", "ageGroupsDetail", "eventList", "genderList", "stageList",
                "eventRanking", "eventRankingSplit", "applicableRecords",
                "laneEventLogs",         // 2026-09-13 改走 LANE_EVENT_APPEND 增量追加
                "laneDevices"            // 2026-09-13 改走 DEVICE_STATES_UPDATE 变更即推
            };

            return new {
                staticOmitted = staticOmitted,
                // 2026-10-08 现场反馈: 主服务器切到 English 后, display.html(大屏)还是中文——
                //   网页端(webloc.js)原来是各自独立的 localStorage 语言选择, 故意不被服务器
                //   权威语言覆盖(给 query.html/register.html 等"操作员自己的工具"保留个人偏好
                //   是对的), 但大屏是纯展示给观众看的, 应该始终跟着当前赛事用的语言走, 不该
                //   自己另有主张。带上当前权威语言, display.html 收到后跟 webloc.js 同步。
                lang = Loc.CurrentLanguage,
                webAssetVersion = WEB_ASSET_VERSION,   // 2026-09-13 页面版本对不上时自查用
                competitionName = _competitionName,
                competitionMode = _competitionMode,
                currentEvent = _currentEvent,
                currentEventNumber = currentEventNumber,    // 2026-06-04 项次 (= BuildEventNumberMap 顺序号)
                currentGender = _currentGender,
                currentAgeGroup = _currentAgeGroup ?? "",
                currentStage = _currentStage,
                currentHeat = _currentHeat,
                totalHeats = _totalHeats,
                isRelay = _isRelay,
                poolConfig = BuildPoolConfigPayload(),
                //2026-05-19 推送当前"设备全开"集合 (含 -1 表示全道, 0..9 表示单道)
                forceAllOpenLanes = _forceAllOpenLanes.ToList(),
                forceAllOpenAll   = _forceAllOpenLanes.Contains(-1),
                raceState = _raceState.ToString().ToUpper(),
                runningTime = TimeFormatter.FormatRunning(_clockPaused ? _pausedRunningTime : _runningTime),
                // 2026-05-27 停表状态: clockPaused=true 时所有客户端冻结滚动时间显示 (硬件不受影响)
                clockPaused = _clockPaused,
                pausedRunningTime = _clockPaused ? TimeFormatter.FormatRunning(_pausedRunningTime) : "",
                // 2026-05-27 "比赛日志" tab 数据: per-lane 累积事件文本, EXE/HTML 按选定道次显示
                //
                // 2026-09-13 【只随低频完整帧走, 精简帧里不带】
                //   这一条是本次瘦身里最肥的一处: 每道上限 64KB(MAX_LANE_EVENT_LOG),
                //   十条道就是 640KB 文本 —— 而它原来每一帧都全量重发一遍, 比赛中
                //   100ms 一帧。ToDictionary + 每道 ToString() 还要现分配一整份副本,
                //   400 米那种事件多的比赛越比越肥, 正是"内存涨几个 G"的同一副形状。
                //   现在: 完整帧(10 秒一次)带全量兜底, 中间靠 LANE_EVENT_APPEND 增量追加
                //   (一条事件约 70 字节)。客户端照 staticOmitted 保留上一份, 不会被空表冲掉。
                laneEventLogs = keepStatic
                    ? _laneEventLog.ToDictionary(kv => kv.Key.ToString(), kv => kv.Value.ToString())
                    : new Dictionary<string, string>(),
                // 第1名成绩（由ProcessTouchpadHit设置，客户端直接显示）
                firstPlaceFinishTime = _firstPlaceFinishTime ?? "",
                firstPlaceActive = (_firstPlaceShowStart != DateTime.MinValue &&
                    (DateTime.Now - _firstPlaceShowStart).TotalSeconds <
                    (_laneCloseSettings.FirstPlaceHoldTime > 0 ? _laneCloseSettings.FirstPlaceHoldTime : 3)),
                // 设备测试：客户端用此标志切换测试 UI；事件文字按泳道左/右分组
                testMode = _testMode,
                testEvents = _testMode ? _laneDeviceStates.Select(s => new {
                    lane = s.Lane,
                    left  = _testLastEventLeft.ContainsKey(s.Lane)  ? _testLastEventLeft[s.Lane]  : "",
                    right = _testLastEventRight.ContainsKey(s.Lane) ? _testLastEventRight[s.Lane] : ""
                }).ToList() : null,
                laneCloseSettings = BuildLaneCloseSettingsPayload(),
                // 2026-06-19 race_control.html 顶端"内存监控"用 (跟 PC 端 MemoryStatusText 同源)
                memoryStatus = MemoryStatusText != null ? MemoryStatusText.Text : "",
                // 2026-06-19 race_control.html 顶端"电池电压"用 (跟 PC 端 BatteryVoltageText 同源)
                batteryVoltage = BatteryVoltageText != null ? BatteryVoltageText.Text : "",
                displayRecordLabel = string.IsNullOrEmpty(_displayRecordLabel) ? "WR" : _displayRecordLabel,
                displayRecordTypeName = string.IsNullOrEmpty(_displayRecordTypeName) ? "世界纪录" : _displayRecordTypeName,
                timingHwConnected = _timingBridge != null && _timingBridge.IsConnected,
                timingHwStatus = _timingBridge != null ? _timingBridge.StatusText : "未连接",
                //2026-05-19 把硬件电池电压推给客户端 (race_control.html 顶栏显示).
                // 30 秒内有效, 否则按 0 处理(客户端不显示).
                hwBatteryVoltage = (_hwBatteryVoltage > 0 && (DateTime.Now - _hwBatteryReceivedAt).TotalSeconds < 30) ? _hwBatteryVoltage : 0.0,
                // ── 2026-09-13 【现算, 不用缓存那个字段】────────────────────────
                //   _scoringControlMode 只在"有客户端连上/断开本机服务器"时才更新
                //   (UpdateScoringControlMode 的三个调用点)。而 RTC 的客户端是连
                //   【主服务器】的, 没人连 RTC 自己 —— 于是 RTC 那个字段【从开机起
                //   一直是 "local"】, 它转发出去的每一帧都在说"控制权在本地",
                //   比赛控制网页收到就把自己解禁了。
                //   现象正是: EXE 上一改比赛项目(触发一次 RTC 广播), 网页就解禁一次;
                //   主服务器自己的帧又说 remote_exe, 于是两边来回打架。
                //   改成发的时候现算 —— 谁发的帧都说同一句话。
                scoringControlMode = IsRaceControlTakenByExe() ? "remote_exe" : _scoringControlMode,
                resultConfirmed = _resultConfirmed,
                // 软件设置的组别/项目/性别/赛次列表 — 用于网页报名/检录端动态填充下拉
                ageGroups = _ageGroups.Take(staticN).Select(g => g.Name).ToList(),
                // ScheduleEditor 编辑端使用：完整组别信息（含 minAge/maxAge），用于配置 Tab 表格
                ageGroupsDetail = _ageGroups.Take(staticN).Select(g => new { name = g.Name, minAge = g.MinAge, maxAge = g.MaxAge }).ToList(),
                eventList = _events.Take(staticN).ToList(),
                genderList = _genders.Take(staticN).ToList(),
                stageList = _stages.Take(staticN).ToList(),
                schedule = _schedule.Take(staticN).Select(s => {
                    int hc = s.HeatCount > 0 ? s.HeatCount : 1;
                    string ag = s.AgeGroup ?? "";
                    var cancelledHeats = s.CancelledHeats ?? new List<CancelledHeat>();
                    var heatConfirmed = new List<bool>();
                    // 2026-09-18 heatCancelled 跟 heatConfirmed 逐一对应(同一条 hh 循环, 下标一致)——
                    //   query.html 拿组次号去这两个数组同一个下标查, 才能把"取消"和"没确认"分清楚。
                    var heatCancelled = new List<bool>();
                    // 2026-09-21 用户要求: 组次状态标注做"数字 -> 状态"对照表——网页端不再
                    //   收字符串自己猜, 直接发 HeatDisplayStatus 的数字编号(见 Swimmer.cs),
                    //   网页那边照抄同一份数字表(见各 html 里的 STATUS_LABEL), 保证两边永远
                    //   不会打架, 以后系统从中文转英文也只用改这一张表。已检录已经是
                    //   HeatStatus() 数字表里的一档状态, 不用再单独发 heatCheckedIn 了。
                    var heatStatus = new List<int>();
                    for (int hh = 1; hh <= hc; hh++) {
                        bool cancelled = cancelledHeats.Any(c => c.Heat == hh);
                        heatCancelled.Add(cancelled);
                        heatConfirmed.Add(!cancelled && IsHeatConfirmed(ag, s.Gender, s.EventName, s.Stage, hh));
                        heatStatus.Add((int)(cancelled ? HeatDisplayStatus.Cancelled : HeatStatusCode(HeatStatus(ag, s.Gender, s.EventName, s.Stage, hh))));
                    }
                    // 2026-09-18 跟 IsStageAllConfirmedFast/GetFullyConfirmedFinalEvents 同一个坑:
                    //   被取消(并组)的组次号永远不会被确认——allConfirmed 原来直接 All(x=>x),
                    //   只要项目里有一组被并组过就永远算不出"全部确认", 网页那边"项目已完成"
                    //   的标记就一直卡着。改成只看"活着"的那些组。
                    var liveConfirmed = new List<bool>();
                    for (int hh = 0; hh < hc; hh++) if (!heatCancelled[hh]) liveConfirmed.Add(heatConfirmed[hh]);
                    return new {
                        session = s.SessionNumber, sessionName = s.SessionName,
                        // 2026-09-15 漏发 evNum(项次) —— query.html"比赛日程"页那一列一直显示"-",
                        //   下拉排序(session*1000+evNum)也跟着失真。这里补上。
                        evNum = s.EvNum,
                        date = s.Date, time = s.Time,
                        ageGroup = ag,
                        eventName = s.EventName, gender = s.Gender,
                        stage = s.Stage, heatCount = s.HeatCount, isRelay = s.IsRelay,
                        heatConfirmed = heatConfirmed,
                        heatCancelled = heatCancelled,
                        heatStatus = heatStatus,
                        allConfirmed = liveConfirmed.Count > 0 && liveConfirmed.All(x => x)
                    };
                }).ToList(),
                swimmers = swimmerData,
                // ScheduleEditor 编辑端使用：全量运动员列表（不限当前组），用于赛事管理与报名/成绩与排名/文档打印
                allSwimmers = _swimmers.Take(staticN).Select(sw => new {
                    bibNumber = sw.BibNumber,
                    name = sw.Name,
                    gender = sw.Gender,
                    birthDate = sw.BirthDate,
                    age = sw.Age,
                    ageCategory = sw.AgeCategory,
                    country = sw.Country,
                    countryShort = sw.CountryShort ?? "",
                    eventName = sw.EventName,
                    currentStage = sw.CurrentStage,
                    heat = sw.Heat,
                    lane = sw.Lane,
                    entryTime = sw.EntryTime,
                    finalTime = sw.Results.Where(r => r.Stage == sw.CurrentStage)
                                          .Select(r => r.FinalTimeDisplay).FirstOrDefault() ?? "",
                    timingSource = sw.Results.Where(r => r.Stage == sw.CurrentStage)
                                             .Select(r => r.TimingSource).FirstOrDefault() ?? "",
                    //2026-05-12 != 0 而非 > 0：允许显示负值（抢跳/犯规时为负数，如 -0.020）
                    startingBlockTime = sw.Results.Where(r => r.Stage == sw.CurrentStage)
                                                  .Select(r => r.StartingBlockTime != 0 && !double.IsNaN(r.StartingBlockTime) ? r.StartingBlockTime.ToString("F3") : "").FirstOrDefault() ?? "",
                    recordNote = sw.Results.Where(r => r.Stage == sw.CurrentStage)
                                           .Select(r => r.RecordNote ?? "").FirstOrDefault() ?? "",
                    // 2026-06-19 query.html 需要按 stage+heat 查任意已完赛组的成绩, 加轻量 results 数组.
                    //   GetStatusData allSwimmers 只投影当前 stage 的标量 finalTime 不够用 (旧逻辑导致
                    //   query.html "有表格没成绩"). EDITOR_PACKAGE 的 Results 完整但被 SHOW_LIVE_RACE 覆盖.
                    //   只含展示字段, 不含分段/触板/反应时大对象, 千人赛会带宽可控.
                    results = sw.Results.Select(r => new {
                        stage = r.Stage,
                        heat = r.Heat,
                        // 2026-09-15 query.html 查"成绩"页按 stage+heat 从这个数组里找人时,
                        //   原来没带 lane —— 只能退回 sw.lane(运动员【当前】那个道次), 晋级/
                        //   重新分组后跟这一条历史成绩当初实际游的道次对不上, 显示就错了。
                        lane = r.Lane,
                        finalTime = r.FinalTimeDisplay,
                        rank = r.Rank,
                        // 2026-09-15 "总排名"页原来是拿到手的成绩自己重新按时间排一遍——
                        //   跟"成绩与排名"/大屏/打印那份权威的跨组名次(EventRank, 全场只算
                        //   一次那份)各算各的, 可能对不上号。带上它, 有定稿值就优先用。
                        eventRank = r.EventRank,
                        recordNote = r.RecordNote ?? "",
                        status = r.Status ?? ""
                    }).ToList(),
                    currentRank = sw.CurrentRank,
                    status = sw.Status ?? "",
                    idNumber = sw.IDNumber ?? "",
                    phone = sw.Phone ?? "",
                    notes = sw.Notes ?? ""
                }).ToList(),
                // ScheduleEditor 编辑端使用：全量接力队列表（队名 + 项目 + 性别 + 报名成绩 + 4 棒队员）
                allRelayTeams = _relayTeams.Take(staticN).Select(rt => new {
                    teamName = rt.TeamName ?? "",
                    eventName = rt.EventName ?? "",
                    gender = rt.Gender ?? "",
                    entryTime = rt.EntryTime ?? "",
                    stage = rt.Stage ?? "",
                    heat = rt.Heat,
                    lane = rt.Lane,
                    status = rt.Status ?? "",
                    legs = rt.Legs.Select(leg => new {
                        legOrder = leg.LegOrder,
                        swimmerName = leg.SwimmerName ?? "",
                        swimmerBibNumber = leg.SwimmerBibNumber ?? "",
                        swimmerIDNumber = leg.SwimmerIDNumber ?? "",
                        swimmerBirthDate = leg.SwimmerBirthDate ?? ""
                    }).ToList()
                }).ToList(),
                // 2026-06-20 race_control 设备状态管理 升级 4 态: 加 10 个 NotInstalled 字段 + endLocked
                //   endLocked='left'/'right'/'none' 表示哪端被单端配置锁定 (race_control 据此灰显该端 5 列)
                // 2026-09-13 设备状态改走【变一次推一次】(DEVICE_STATES_UPDATE) ——
                //   它是 10 道 × 23 个布尔, 每帧约 3-5KB, 而故障状态一整场也变不了几次,
                //   每 100ms 重发一遍纯属浪费。精简帧里不带(进 staticOmitted, 客户端保留上一份),
                //   完整帧仍带全量兜底。
                //   【实时性不降反升】: 原来要等下一帧(最多 100ms), 现在状态一变立刻推。
                laneDevices = keepStatic ? BuildLaneDevicesPayload() : null,
                eventRanking = eventRanking,
                eventRankingSplit = eventRankingSplit,
                applicableRecords = applicableRecords,   // 2026-06-05 大屏 项目名称下 inline 纪录行
                teamScores = teamScoresData,
                records = BuildRecordsPayload(),
                // 2026-06-03 裁判员名单 (大屏 "裁判介绍" 视图): 从 _staff 里挑 Group=裁判员 的成员
                refereeList = BuildRefereePayload(),
                // 2026-06-21 颁奖弹窗选定项目 (用户选 → SHOW_AWARDS), display.html 检测此字段优先用,
                //   没有则退回 _currentXxx + eventRanking (兼容远端命令直接推 SHOW_AWARDS). awardRanking 按
                //   "全项目总排名" 算 (多组决赛颁奖按总排名前 3, 非单组前 3).
                awardSelection = BuildAwardSelectionPayload(),
                awardRanking = BuildAwardRankingPayload(),
                // 2026-06-21 总排名回放: 用户从弹窗选定项目, display.html 检测后强制单表分页 (不走 split)
                rankingSelection = BuildRankingSelectionPayload(),
                rankingRanking = BuildRankingRankingPayload()
            };
        }

        // ══════════════════════════════════════════════════════════════
        // 以下都是【单一来源】的取数方法: 整包和大屏专用包共用同一份。
        // 抽出来的目的不是好看, 是防止两条路径各写一份、改一处漏一处 ——
        // 那样大屏上就会出现"跟整包对不上"的诡异差异, 而且极难查。
        // ══════════════════════════════════════════════════════════════
        private List<object> BuildTeamScoresPayload(int take) {
            return _teamScores.OrderBy(t => t.Rank).Take(take).Select(t => (object)new {
                teamName = t.TeamName, totalPoints = t.TotalPoints,
                individualPoints = t.IndividualPoints, relayPoints = t.RelayPoints,
                recordBonusPoints = t.RecordBonusPoints,
                gold = t.GoldCount, silver = t.SilverCount, bronze = t.BronzeCount, rank = t.Rank
            }).ToList();
        }

        private List<object> BuildRecordsPayload() {
            return _records.Select(r => (object)new {
                eventName = r.EventName, gender = r.Gender, ageGroup = r.AgeGroup ?? "",
                recordType = r.RecordType,
                holderName = r.HolderName, holderCountry = r.HolderCountry,
                time = TimeFormatter.Format(r.Time), timeInSeconds = r.Time,
                date = r.Date, location = r.Location
            }).ToList();
        }

        // 裁判员名单 (大屏 "裁判介绍" 视图): 从 _staff 里挑 Group=裁判员 的成员
        private List<object> BuildRefereePayload() {
            return _staff
                .Where(m => m != null && (m.Group ?? "") == StaffGroups.Referees)
                .Select(m => (object)new {
                    title = m.Title ?? "", name = m.Name ?? "",
                    country = m.Country ?? "", refereeLevel = m.RefereeLevel ?? "",
                    gender = m.Gender ?? ""
                }).ToList();
        }

        private object BuildAwardSelectionPayload() {
            return _awardSelection == null ? null : (object)new {
                gender = _awardSelection.Gender ?? "",
                ageGroup = _awardSelection.AgeGroup ?? "",
                eventName = _awardSelection.EventName ?? "",
                stage = _awardSelection.Stage ?? ""
            };
        }

        private object BuildAwardRankingPayload() {
            return _awardSelection == null ? new List<object>()
                : GetEventRankingForStage(_awardSelection.Gender ?? "", _awardSelection.EventName ?? "",
                                          _awardSelection.AgeGroup ?? "", _awardSelection.Stage ?? "");
        }

        private object BuildRankingSelectionPayload() {
            return _rankingSelection == null ? null : (object)new {
                gender = _rankingSelection.Gender ?? "",
                ageGroup = _rankingSelection.AgeGroup ?? "",
                eventName = _rankingSelection.EventName ?? "",
                stage = _rankingSelection.Stage ?? ""
            };
        }

        private object BuildRankingRankingPayload() {
            return _rankingSelection == null ? new List<object>()
                : GetEventRankingForStage(_rankingSelection.Gender ?? "", _rankingSelection.EventName ?? "",
                                          _rankingSelection.AgeGroup ?? "", _rankingSelection.Stage ?? "");
        }

        // 2026-06-04 当前项目的 项次 (= 赛程顺序号, 0=未查到/无项目)
        private int BuildCurrentEventNumber() {
            int n = 0;
            if (string.IsNullOrEmpty(_currentEvent)) return 0;
            try {
                var evtMap = BuildEventNumberMap();
                int no;
                // 2026-06-05 先按 性别|项目|年龄组 三部分 查, 找不到再降级到 性别|项目
                string k3 = (_currentGender ?? "") + "|" + _currentEvent + "|" + (_currentAgeGroup ?? "");
                string k2 = (_currentGender ?? "") + "|" + _currentEvent;
                if (evtMap.TryGetValue(k3, out no)) n = no;
                else if (evtMap.TryGetValue(k2, out no)) n = no;
            } catch { }
            return n;
        }

        // ══════════════════════════════════════════════════════════════
        // 大屏(display.html)专用取数 —— 每个视图只算、只发它自己要用的数据。
        //
        // 为什么不是"把整包过滤一遍": 那样服务端照样把 592 人的名单、全部赛程、
        // 全项目排名统统算一遍, 只是发之前扔掉 —— 内存和 CPU 一点没省。
        // 这里是【按需计算】: 切到"裁判介绍"就只跑 BuildRefereePayload(), 别的一律不碰。
        //
        // 字段清单是从 display.html 里把七个 render 函数用到的 data.xxx 逐个抠出来核的,
        // 不是照文档抄的 —— 文档漏了两处(EventRanking 的 applicableRecords/currentStage、
        // Records 的 refereeList), 照文档做会重演"比赛中纪录行被冲掉"那次事故。
        //
        // 公共标量每个视图都带: display.html 收到后是 data = payload 【整体替换】,
        // 少带一个页头就空。这几个都是标量, 加起来不到 1KB。
        // ══════════════════════════════════════════════════════════════
        private object BuildDisplayPayload(string mode) {
            // 用字典而不是匿名类: 公共标量要跟视图数据【平铺在同一层】,
            // display.html 读的是 data.competitionName, 套一层就取不到了。
            // C# 5 的匿名类没法展开合并, 字典是最直接的办法。
            var d = DisplayCommon();
            switch (mode) {
                case "SHOW_START_LIST":
                    d["swimmers"] = BuildSwimmerPayload();
                    break;
                case "SHOW_HEAT_RESULT":
                    d["swimmers"] = BuildSwimmerPayload();
                    d["applicableRecords"] = BuildApplicableRecords(_currentEvent, _currentGender);
                    break;
                case "SHOW_EVENT_RANKING":
                    d["eventRanking"] = GetEventRanking(_currentEvent, _currentGender);
                    d["eventRankingSplit"] = GetEventRankingsSplit(_currentAgeGroup, _currentEvent, _currentGender);
                    d["applicableRecords"] = BuildApplicableRecords(_currentEvent, _currentGender);
                    d["rankingSelection"] = BuildRankingSelectionPayload();
                    d["rankingRanking"] = BuildRankingRankingPayload();
                    break;
                case "SHOW_TEAM_STANDINGS":
                    d["teamScores"] = BuildTeamScoresPayload(int.MaxValue);
                    break;
                case "SHOW_RECORDS":
                    d["records"] = BuildRecordsPayload();
                    d["refereeList"] = BuildRefereePayload();   // 纪录视图也读裁判名单(文档漏了这条)
                    break;
                case "SHOW_REFEREES":
                    d["refereeList"] = BuildRefereePayload();
                    break;
                case "SHOW_AWARDS":
                    d["awardSelection"] = BuildAwardSelectionPayload();
                    d["awardRanking"] = BuildAwardRankingPayload();
                    d["eventRanking"] = GetEventRanking(_currentEvent, _currentGender);
                    break;
                // 2026-08-27 比赛实况 —— 这是【比赛中每 100ms 都在发】的那一路, 最费。
                //   实测: 整包 249KB / 精简帧 28KB, 而 renderRace 真正要用的只有下面这些。
                //   大屏不读的 laneDevices(5.5KB)、laneEventLogs、memoryStatus、
                //   timingHwStatus、forceAllOpenLanes… 一律不发。
                //   records 是 renderRace 要读的(项目名下那行纪录), 不能砍 ——
                //   砍了就是重演"比赛中纪录行被冲掉"那次事故。
                case "SHOW_LIVE_RACE":
                case "SHOW_LIVE_RACE_LITE":
                    d["swimmers"] = BuildSwimmerPayload();
                    d["records"] = BuildRecordsPayload();
                    d["applicableRecords"] = BuildApplicableRecords(_currentEvent, _currentGender);
                    d["laneCloseSettings"] = BuildLaneCloseSettingsPayload();
                    d["raceState"] = _raceState.ToString().ToUpper();
                    d["runningTime"] = TimeFormatter.FormatRunning(_clockPaused ? _pausedRunningTime : _runningTime);
                    d["clockPaused"] = _clockPaused;
                    break;
                // 欢迎屏 renderWelcome 只读 competitionName, 公共标量就够了。
                //   原来这里发的是 249KB 整包 —— 一场比赛每次复位都发一遍。
                case "SHOW_WELCOME":
                    break;
                default:
                    return null;   // 不认识的视图 -> 退回整包, 保证不会因为漏配而白屏
            }
            return d;
        }

        /// <summary>
        /// 每个大屏视图都要带的公共标量(页头、项目名、组次…)。
        /// display.html 收到后是 data = payload 整体替换, 少带一个页头就空 ——
        /// 所以宁可每次都带上。全是标量, 加起来不到 1KB。
        /// </summary>
        private Dictionary<string, object> DisplayCommon() {
            return new Dictionary<string, object> {
                // 2026-10-08 大屏跟着主服务器当前语言走 (见 GetStatusData 同一条说明)——
                //   这里才是 display.html 实际收到的那条路(BuildDisplayPayload/DisplayCommon),
                //   GetStatusData 那边的 lang 字段只有走整包兜底时才会被 display.html 用到。
                { "lang", Loc.CurrentLanguage },
                { "webAssetVersion", WEB_ASSET_VERSION },   // 2026-09-13 页面版本对不上时自查用
                { "competitionName", _competitionName },
                { "resultConfirmed", _resultConfirmed },
                { "currentEvent", _currentEvent },
                { "currentEventNumber", BuildCurrentEventNumber() },
                { "currentGender", _currentGender },
                { "currentAgeGroup", _currentAgeGroup ?? "" },
                { "currentStage", _currentStage },
                { "currentHeat", _currentHeat },
                { "totalHeats", _totalHeats },
                { "displayRecordLabel", string.IsNullOrEmpty(_displayRecordLabel) ? "WR" : _displayRecordLabel },
                { "displayRecordTypeName", string.IsNullOrEmpty(_displayRecordTypeName) ? "世界纪录" : _displayRecordTypeName },
                { "poolConfig", BuildPoolConfigPayload() }
            };
        }

        // 计时参数(大屏比赛实况视图也要读, 所以两边共用)
        private object BuildLaneCloseSettingsPayload() {
            return new {
                laneCloseTime = _laneCloseSettings.LaneCloseTime,
                startBlockCloseDelay = _laneCloseSettings.StartBlockCloseDelay,
                resultConfirmCloseDelay = _laneCloseSettings.ResultConfirmCloseDelay,
                falseStartThreshold = _laneCloseSettings.FalseStartThreshold,
                relayHandoffFalseStartThreshold = _laneCloseSettings.RelayHandoffFalseStartThreshold,
                splitDisplayTime = _laneCloseSettings.SplitDisplayTime,
                startPosition = _laneCloseSettings.StartPosition,
                finishPosition = _laneCloseSettings.FinishPosition,
                firstPlaceHoldTime = _laneCloseSettings.FirstPlaceHoldTime,
                leftBlindWatchCount = _laneCloseSettings.LeftBlindWatchCount,
                rightBlindWatchCount = _laneCloseSettings.RightBlindWatchCount,
                bigDisplayPageInterval = _laneCloseSettings.BigDisplayPageInterval,
                reactionTimeEnabled = _laneCloseSettings.ReactionTimeEnabled,
                laneOrder = _laneCloseSettings.LaneOrder,
                hardwareAlwaysOpen = _laneCloseSettings.HardwareAlwaysOpen,
                // 2026-06-18 race_control.html 参数设置弹窗用 (与 PC 端同步)
                blindReplaceDelay = _laneCloseSettings.BlindReplaceDelay,
                reactionEventWindowSec = _laneCloseSettings.ReactionEventWindowSec,
                autoBlindReplaceTouchpad = _laneCloseSettings.AutoBlindReplaceTouchpad,
                manualTpReplaceTp = _laneCloseSettings.ManualTpReplaceTp,
                startBoxEdgeFalling = _laneCloseSettings.StartBoxEdgeFalling
            };
        }

        private object BuildPoolConfigPayload() {
            return new {
                length = _poolConfig.Length,
                lanes = _poolConfig.LaneCount,
                laneNumbers = _poolConfig.LaneNumbers,
                //2026-05-19 推送泳池触板"两端/单端"安装方式给所有客户端 (race_control/RemoteTimingControl)
                hasRightStartBlock = _poolConfig.HasRightStartBlock
            };
        }

        // 判断泳道是否参赛：有运动员 且 状态不是 DNS/DNF/DSQ（用于排名/积分等"算成绩"决策）
        private bool IsLaneParticipating(int lane) {
            var swimmers = GetCurrentHeatSwimmers();
            var sw = swimmers.FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (sw == null) return false;
            string st = sw.Status ?? "";
            return st != "DNS" && st != "DNF" && st != "DSQ";
        }

        // 判断泳道是否仍需接收/保存原始计时数据：
        // DSQ（含抢跳取消资格）运动员仍在水中继续完成比赛，触板/盲表/分段/反应时数据应继续接收并保存以便日后查询；
        // 仅大屏排名/最终成绩侧把它排除（由 IsLaneParticipating 控制）。
        // DNS / DNF / 空泳道则没有数据可期，直接丢弃。
        private bool IsLaneReceivingData(int lane) {
            var swimmers = GetCurrentHeatSwimmers();
            var sw = swimmers.FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (sw == null) return false;
            string st = sw.Status ?? "";
            return st != "DNS" && st != "DNF";
        }

        // 2026-06-06 P1-C 缓存, 2026-10-08 改成按 key 严格缓存(不再限时 50ms)——见
        //   GetCurrentHeatSwimmers() 开头那段详细说明: RemoteTimingControl 联网时查一次
        //   是网络 RPC, 不能当轮询接口 50ms 打一次。
        //   注意: 返回的 List 现在【允许】被两处"空道试游占位运动员"增删代码直接
        //   .Add/.Remove(这两处改的是真实同一份缓存, 不是另外拷贝一份)——除此之外的
        //   调用方仍然只读使用。
        private List<Swimmer> _currentHeatSwimmersCache = null;
        private string _currentHeatSwimmersCacheKey = null;
        // ══════════════════════════════════════════════════════════════
        // 2026-08-24 【分组名单唯一入口】"这一组有谁"
        //
        // 由来：原来大屏、成绩 txt、成绩册、总排名、检录台各自拿
        //   (项目 + 性别 + 组别 + 赛次 + 组次) 去 _swimmers 里重新筛一遍，
        //   42 处筛法、42 份略有差异的性别判断 —— 甘肃省十六运"男女"混合接力
        //   连着三轮修不干净就是这么来的(见 29acacc / 1d219d0 / a46e87c)。
        //   现在收敛成这一个函数, 所有消费方都调它。
        //
        // 两条判定规则,与原 GetCurrentHeatSwimmers 相比有一处**行为修正**：
        //   · 该赛次有分组记录(StageAssignment) → 以它为准, 不再退回顶层 s.Heat。
        //     原来 sa.Heat 不匹配时还会用顶层 s.Heat 再判一次, 分组重排(并组/取消组)
        //     后顶层字段若是旧的, 同一个人会同时出现在新旧两组。
        //   · 完全没有分组记录 → 才退回顶层 CurrentStage/Heat, 兼容老档案。
        //
        // 返回按泳道排好的名单; 泳道相同(异常数据)按姓名兜底, 保证任何调用方顺序一致。
        // 2026-10-08 用户明确要求(一次性从根本解决): "分组表数据库就是基准...调出分组
        //   表数据库内容就直接显示（不要再进行比较，也不要自己造，没有就不显）"——
        //   本方法现在只服务"看一眼"的场合(检录/大屏/总排名/赛程状态): 库里查得到就
        //   直接用库的(GetHeatRosterFromDb, 每条库行照抄一个全新对象, 不跟内存比较、
        //   不往内存里塞东西); 库里查不到(这个赛次还没分组过 / meetDb 还没打开 / 单机
        //   测试没建过库)才退回内存那条路径兜底(同样只认 StageAssignment, 不退回顶层
        //   字段瞎猜)。
        //   实时比赛控制(计时过程中要持续记录数据的场合)不走这个函数, 走单独的
        //   EnsureCurrentHeatSwimmersFromDb——那条路要的是"建好之后能一直用下去的
        //   同一个对象", 跟这里"只读、每次都给新对象"的用途不一样。
        private List<Swimmer> GetHeatEntries(string ageGroup, string gender, string eventName, string stage, int heat) {
            var list = new List<Swimmer>();
            if (string.IsNullOrEmpty(eventName) || heat <= 0) return list;

            bool isRelay = eventName.Contains("接力");
            bool hasMixed = HasExplicitMixedEntry(eventName, ageGroup);

            var dbList = GetHeatRosterFromDb(ageGroup, gender, eventName, stage, heat, isRelay, hasMixed);
            if (dbList != null) return dbList;

            foreach (var s in _swimmers) {
                if (s.EventName != eventName) continue;
                if (!GenderMatchEx(s.Gender, gender, hasMixed)) continue;
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                if (isRelay && IsRelayMemberNote(s.Notes)) continue;   // 接力只取代表队条目

                var sa = s.GetAssignmentForStage(stage);
                if (sa == null || sa.Heat != heat) continue;
                list.Add(s);
            }

            list.Sort(delegate(Swimmer a, Swimmer b) {
                int la = LaneOfStage(a, stage), lb = LaneOfStage(b, stage);
                if (la != lb) return la.CompareTo(lb);
                return string.Compare(a.Name ?? "", b.Name ?? "", StringComparison.Ordinal);
            });
            return list;
        }

        // 2026-10-08 用户现场实拍到的严重问题: RemoteTimingControl 联网后点比赛控制
        // 面板按钮要卡好几秒。根因之一: HeatStatus()/GetEventRankingForStage() 等多处
        // 都经 GetHeatEntries() 走到这里查一次分组表数据库——HeatStatus() 还是在
        // GetStatusData() 的赛程循环里【每个项目每一组都查一次】这种用法, 一场比赛
        // 四五十个项目、每项目两三组, 一次整包状态刷新就是上百次。在主服务器本机,
        // _meetDb 背后是 LocalMeetService, 一条本地 SQL, 上百次也感觉不出来；但
        // RemoteTimingControl 联网时背后是 RemoteMeetService——每一次都是一趟同步阻塞
        // 的网络 RPC(SendAndWait), UI 线程被这么多趟网络往返的队伍堵死, 鼠标点按钮
        // 自然要排到最后才轮到处理。
        //
        // 这里加一层短时缓存(2 秒)——同一个(组别,性别,项目,赛次,组次)2 秒内无论被
        // 问多少次, 只真正查一次库/网络, 把"每次都查"摊薄成"大多数时候用缓存"。2 秒
        // 这个量级跟分组表数据库写入防抖(0.5秒)、SHOW_LIVE_RACE 10Hz 刷新比起来足够
        // 新鲜(远没到"看着像没更新"的程度), 但对多处热路径的调用量能砍掉绝大部分。
        private Dictionary<string, object[]> _readBackHeatCache = new Dictionary<string, object[]>();
        private List<SwimmingScoreboard.Db.LaneRow> ReadBackHeatCached(string ageGroup, string gender, string eventName, string stage, int heat) {
            string key = (ageGroup ?? "") + "|" + (gender ?? "") + "|" + (eventName ?? "") + "|" + (stage ?? "") + "|" + heat;
            object[] cached;
            if (_readBackHeatCache.TryGetValue(key, out cached) && (DateTime.Now - (DateTime)cached[0]).TotalSeconds < 2) {
                return (List<SwimmingScoreboard.Db.LaneRow>)cached[1];
            }
            List<SwimmingScoreboard.Db.LaneRow> rows = null;
            try { rows = _meetDb.ReadBackHeat(ageGroup, gender, eventName, stage, heat); } catch { rows = null; }
            _readBackHeatCache[key] = new object[] { DateTime.Now, rows };
            return rows;
        }

        // 2026-10-08 用户最终订正, 定调: "分组表数据库就是基准...调出分组表数据库内容
        // 就直接显示（不要再进行比较，也不要自己造，没有就不显）"——前几版在这里跟
        // 内存 _swimmers 做参赛号/姓名/单位/道次的多级匹配, 本身就是多余的复杂度:
        // 库里这一行本来就自带姓名/单位/参赛号/成绩/名次等全部字段, 不需要先"找出
        // 内存里对应哪个对象"才能显示。本方法只给"看一眼"的场合用(检录/大屏/总排名/
        // 赛程状态)——这些地方只读, 不会往返回的对象上写新东西, 所以每次照着库的数据
        // 现搭一份全新对象、完全不碰 _swimmers, 没有副作用也没有"认错人"的风险。
        // 需要在计时过程中持续记录的实时比赛控制走 EnsureCurrentHeatSwimmersFromDb,
        // 那条路要的是"建好之后能一直用下去的同一个对象", 跟这里的用途不一样。
        //
        // 返回 null = 库里查不到(调用方退回内存兜底, 比如单机测试没建过库); 返回
        // 空列表 = 库里查到了但这一组确实没人(替补除外, 替补不站道)。
        private List<Swimmer> GetHeatRosterFromDb(string ageGroup, string gender, string eventName, string stage,
                                                    int heat, bool isRelay, bool hasMixed) {
            if (_meetDb == null) return null;
            List<SwimmingScoreboard.Db.LaneRow> dbRows = ReadBackHeatCached(ageGroup, gender, eventName, stage, heat);
            if (dbRows == null || dbRows.Count == 0) return null;

            var list = new List<Swimmer>();
            foreach (var row in dbRows) {
                if (row.Lane == null) continue;   // 替补没有道次, 不站道, 大屏/检录都不该列进泳道表
                list.Add(SwimmerFromLaneRow(row, eventName, gender, ageGroup, stage, heat));
            }
            return list;   // dbRows 已经按道次排好序(ORDER BY 道次), 不用再排一次
        }

        // 把一条分组表数据库行直接转成"只读显示用"的运动员对象——字段照抄数据库,
        // 不比较、不猜、缺了就留空; 不加入 _swimmers, 不参与计时/确认成绩那条链路。
        private static Swimmer SwimmerFromLaneRow(SwimmingScoreboard.Db.LaneRow row, string eventName,
                                                    string gender, string ageGroup, string stage, int heat) {
            // 接力队 4 位队员姓名(Notes="接力队 棒次:张三,李四,...")这条查询拿不到
            // (那是 relay_legs 表, LaneRow.Legs 这里没按需带上)——宁可留空让下游退回
            // 显示队名(sw.Name), 也不编一个假的 Notes 出来。
            var sw = new Swimmer {
                Name = row.Name ?? "", Country = row.UnitName ?? "", BibNumber = row.BibNumber ?? "",
                EventName = eventName, Gender = gender ?? "", AgeCategory = ageGroup ?? "",
                EntryTime = row.SeedTime ?? "", EntryTimeSeconds = row.SeedTimeSeconds,
                Status = row.Status ?? ""
            };
            sw.SetStageAssignment(stage, row.Heat ?? heat, row.Lane.Value, row.SeedTimeSeconds, row.SeedTime);
            if (row.FinalTime > 0 || row.Rank > 0 || !string.IsNullOrEmpty(row.Status)) {
                sw.Results.Add(new LaneResult {
                    EventName = eventName, Stage = stage, Heat = row.Heat ?? heat, Lane = row.Lane.Value,
                    FinalTime = row.FinalTime, TimeInSeconds = row.FinalTime,
                    Rank = row.HeatRank > 0 ? row.HeatRank : row.Rank, EventRank = row.Rank,
                    Gap = row.Gap, IsTie = row.IsTie, PromotionMark = row.PromotionMark ?? "",
                    Status = row.Status ?? "", RecordNote = row.RecordNote ?? "",
                    TimingSource = row.TimingSource ?? "",
                    StartingBlockTime = row.ReactionTime, FromDb = true
                });
            }
            return sw;
        }

        // 该赛次的泳道号: 有分组记录用分组记录的, 否则用顶层字段
        private static int LaneOfStage(Swimmer s, string stage) {
            var sa = s.GetAssignmentForStage(stage);
            return (sa != null && sa.Heat > 0) ? sa.Lane : s.Lane;
        }

        private List<Swimmer> GetCurrentHeatSwimmers() {
            string key = (_currentEvent ?? "") + "|" + (_currentGender ?? "") + "|" + (_currentAgeGroup ?? "") + "|" + _currentStage + "|" + _currentHeat;
            // 2026-10-08 用户现场实拍到的严重问题: RemoteTimingControl 连上主服务器后,
            // 点比赛控制面板按钮要卡好几秒才有反应, 主服务器本机的比赛控制完全正常。
            //
            // 根因: 这条缓存原来只按 50ms 限时, 同一个 key 过了 50ms 也会重新调
            // EnsureCurrentHeatSwimmersFromDb() → _meetDb.ReadBackHeat()。在主服务器
            // 本机, _meetDb 背后是 LocalMeetService, 就是一条本地 SQL, 50ms 查一次毫无
            // 感觉；但 RemoteTimingControl 联网时 _meetDb 背后是 RemoteMeetService——
            // 见该类自己的文档: "真正走网络的只有: 选组时 OpenHeat 取一次名单; 确认时
            // CommitHeat 回写一次成绩", 不该被当成轮询接口用。这里卡 50ms 就重新算一次,
            // 等于把"这组开赛前查一次库"变成了"只要还显示着这组, 每秒重查约20次网络
            // RPC"——UI 线程(SendAndWait 是同步阻塞调用)被这些排队的网络往返堵死,
            // 鼠标点按钮自然要等好几秒才轮到处理。
            //
            // 改成按 key 严格缓存(不再限时)——同一个 key(同一组)不管隔多久再调用,
            // 只要上次真的建到了人(Count>0)就直接用那份对象(这正是用户最初要的"开始
            // 计时前建好、之后一直用这组对象"); 只有 key 变了(真的切组了)或者上次
            // 确实一个人都没建到(库里当时还没数据, 留着机会等分组同步过来后再试一次)
            // 才会再查一次库/网络。
            if (_currentHeatSwimmersCache != null
                && _currentHeatSwimmersCacheKey == key
                && _currentHeatSwimmersCache.Count > 0) {
                return _currentHeatSwimmersCache;
            }
            if (string.IsNullOrEmpty(_currentEvent) || _currentHeat <= 0) {
                _currentHeatSwimmersCache = new List<Swimmer>();
                _currentHeatSwimmersCacheKey = key;
                return _currentHeatSwimmersCache;
            }
            var ordered = EnsureCurrentHeatSwimmersFromDb(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat);
            _currentHeatSwimmersCache = ordered;
            _currentHeatSwimmersCacheKey = key;
            return ordered;
        }

        // 建好/拿到"这一组"要用来计时的运动员对象——建好之后这些对象会留在 _swimmers
        // 里持续使用(供触板/手动时间记录、确认本组成绩), 不是每次调用都现查现造。
        //
        // 2026-10-08 用户现场实拍到的真实 bug: 原来"内存里已经有就直接信、按性别
        // 字符串在 _swimmers 里筛"这条捷径, 在同一 EventName 下"男"/"男女"两个并列
        // 子项目都被浏览过一遍之后(两边运动员各自都已经进了 _swimmers、各自都有本
        // 赛次 StageAssignment)不再可靠——两边对象同时在内存里, 性别过滤一旦有
        // 时序/判定上的松动(hasMixed 算的时候还没看到"男女"那边的对象), 就会把
        // 两个不同赛次的人混进同一组(张掖市和平凉市同时出现在"男女"组的3道, 跟
        // display.html 最早报的那个 bug一模一样, 只是这条由 SHOW_LIVE_RACE/
        // GetCurrentHeatSwimmers 这条独立路径触发, 没跟着 GetHeatEntries 那次一起改)。
        //
        // 改成跟 GetHeatEntries 完全一致的原则: 库(heat_entries, 按 round_id 物理
        // 隔离, 天然不会混)才是权威名单; 内存只负责"这库里一行对应的是不是已经在
        // 跟踪的某个对象"(按参赛号认——找到了复用, 计时数据不丢; 没找到才新建),
        // 不再用内存自己去筛"这一组有谁"。
        private List<Swimmer> EnsureCurrentHeatSwimmersFromDb(string ageGroup, string gender, string eventName, string stage, int heat) {
            List<SwimmingScoreboard.Db.LaneRow> dbRows = null;
            if (_meetDb != null) dbRows = ReadBackHeatCached(ageGroup, gender, eventName, stage, heat);

            if (dbRows != null && dbRows.Count > 0) {
                var byBib = new Dictionary<string, Swimmer>();
                foreach (var s in _swimmers) {
                    if (s.EventName != eventName) continue;
                    if (string.IsNullOrEmpty(s.BibNumber)) continue;
                    if (!byBib.ContainsKey(s.BibNumber)) byBib[s.BibNumber] = s;
                }
                var built = new List<Swimmer>();
                foreach (var row in dbRows) {
                    if (row.Lane == null) continue;   // 替补没有道次, 不上道, 不参与计时
                    Swimmer sw = null;
                    if (!string.IsNullOrEmpty(row.BibNumber)) byBib.TryGetValue(row.BibNumber, out sw);
                    if (sw == null) {
                        sw = SwimmerFromLaneRow(row, eventName, gender, ageGroup, stage, heat);
                        _swimmers.Add(sw);
                    } else {
                        // 已经在跟踪的对象——保留它身上积累的 Results/计时数据, 只把
                        // 分组表的权威赛次/组次/道次刷新上去。
                        sw.SetStageAssignment(stage, row.Heat ?? heat, row.Lane.Value, row.SeedTimeSeconds, row.SeedTime);
                    }
                    built.Add(sw);
                }
                return built;   // dbRows 已按道次排好序(ORDER BY 道次)
            }

            // 库里查不到(这个赛次还没分组过 / meetDb 还没打开 / 单机测试没建过库)——
            // 退回内存兜底, 同样只认 StageAssignment, 不退回顶层字段瞎猜。
            bool isRelay = eventName.Contains("接力");
            bool hasMixed = HasExplicitMixedEntry(eventName, ageGroup);
            var fromMemory = new List<Swimmer>();
            foreach (var s in _swimmers) {
                if (s.EventName != eventName) continue;
                if (!GenderMatchEx(s.Gender, gender, hasMixed)) continue;
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                if (isRelay && IsRelayMemberNote(s.Notes)) continue;
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat == heat) fromMemory.Add(s);
            }
            fromMemory.Sort(delegate(Swimmer a, Swimmer b) {
                int la = LaneOfStage(a, stage), lb = LaneOfStage(b, stage);
                if (la != lb) return la.CompareTo(lb);
                return string.Compare(a.Name ?? "", b.Name ?? "", StringComparison.Ordinal);
            });
            return fromMemory;
        }

        // 2026-05-27 BUG 修复 #3: 加 ageGroup 维度. 之前只按 gender + eventName 排名,
        //   导致 (甲) 男 50m 自由泳 和 (乙) 男 50m 自由泳 的总排名混到一起.
        //   旧 2-arg 签名保留为转发, 默认按 _currentAgeGroup 过滤.
        private List<object> GetEventRanking(string eventName, string gender) {
            return GetEventRanking(_currentAgeGroup, eventName, gender);
        }

        // 2026-06-02 并项拆分: 一个赛程项目可能跨"性别+实际年龄" (例: "男女 9-11岁 50米自由泳"),
        // 总排名 / 批量公布 要按 (实际性别, 实际年龄) 各出一张子表. 此方法返回 List< {gender, age, title, items[]} >,
        // 每个 sub-ranking 内部用 1-2-2-4 并列名次, 与原 GetEventRanking 同款. 接力赛 (无个人 Age) 只按 gender 拆.
        private List<object> GetEventRankingsSplit(string ageGroup, string eventName, string gender) {
            var result = new List<object>();
            if (string.IsNullOrEmpty(eventName)) return result;
            bool rankRelay = eventName.Contains("接力");

            // 收集所有候选 swimmers (与 GetEventRanking 同源, 但放宽 gender 过滤到 "GenderMatchesIncludingMixed",
            //   并按 "已确认 heat" 逐 heat 拉取). 接力运动员行 (Notes 以 "接力队员" 开头) 排除.
            var schedItem = _schedule.FirstOrDefault(s => SgMatch(s.Gender, gender) && s.EventName == eventName
                                                          && s.Stage == _currentStage
                                                          && (s.AgeGroup ?? "") == (ageGroup ?? ""));
            int heatCount = schedItem != null && schedItem.HeatCount > 0 ? schedItem.HeatCount : _totalHeats;

            var stageSwimmers = new List<Swimmer>();
            for (int h = 1; h <= Math.Max(heatCount, _currentHeat); h++) {
                // 2026-08-24 被取消(并组)的组直接跳过 —— 人已经并到别组去了
                if (IsHeatCancelled(ageGroup, gender, eventName, _currentStage, h)) continue;
                bool confirmed = IsHeatConfirmed(ageGroup, gender, eventName, _currentStage, h);
                if (!confirmed && h == _currentHeat && _resultConfirmed) confirmed = true;
                if (!confirmed) continue;
                // 2026-08-24 改调分组名单唯一入口
                stageSwimmers.AddRange(GetHeatEntries(ageGroup, gender, eventName, _currentStage, h));
            }
            if (stageSwimmers.Count == 0) return result;

            // 2026-06-04 改: 按 (性别, 注册组别 AgeCategory) 分组, 不再按 实际年龄 逐岁切.
            //   例: "9-11岁" 组 不再拆 9/10/11 三张子表, 一张表显示全部. 接力赛只按 性别.
            //   注册组别 取 swimmer.AgeCategory (与 _ageGroups 注册名一致, 比赛档案配置).
            var ageOrderMap = new Dictionary<string, int>();
            for (int aoi = 0; aoi < _ageGroups.Count; aoi++) ageOrderMap[_ageGroups[aoi].Name] = aoi;
            var groups = stageSwimmers.GroupBy(s => rankRelay
                    ? new { G = s.Gender ?? "", AG = "" }
                    : new { G = s.Gender ?? "", AG = s.AgeCategory ?? "" })
                .OrderBy(g => g.Key.G == "男" ? 0 : g.Key.G == "女" ? 1 : 2)
                .ThenBy(g => {
                    int o; return ageOrderMap.TryGetValue(g.Key.AG, out o) ? o : 9999;
                });

            foreach (var grp in groups) {
                string subGender = grp.Key.G;
                string subAgeGroup = grp.Key.AG;
                var subList = grp.ToList();

                var withTimes = subList.Where(s => {
                    // 2026-06-04 TRI 同 DSQ/DNS/DNF, 不进 withTimes (= 不参与排名)
                    // 2026-09-01 判罚/弃权要看【成绩行】的状态, 不能只看运动员对象上的。
                    //   DNF 通常标在成绩行(r.Status)上, 只查 s.Status 会把他放进总排名 ——
                    //   大屏上就出现过"王朝辉 DNF 却排名第1、还显示 42.28"。
                    { var _r0 = s.GetResultForStage(_currentStage);
                      string _st0 = GetEffectiveStatus(s, _r0);
                      if (ResultOrdering.IsJudged(_st0) || _st0 == "TRI") return false; }
                    var rr = s.GetResultForStage(_currentStage);
                    return rr != null && rr.FinalTime > 0;
                }).OrderBy(s => s.GetResultForStage(_currentStage).FinalTime).ToList();

                var items = new List<object>();
                // 2026-09-01 名次【从库里读】, 这里不算(EventRank 是确认成绩时竞赛库算好
                //   回读进内存的; 项目定稿后是 event_rankings 的值)。
                withTimes = withTimes.OrderBy(s => { int k0 = s.EventRankFor(_currentStage); return k0 > 0 ? k0 : int.MaxValue; })
                                     .ThenBy(s => { var rr = s.GetResultForStage(_currentStage); return rr != null ? rr.FinalTime : 0; })
                                     .ToList();
                var rkList = withTimes.Select(s => s.EventRankFor(_currentStage)).ToList();
                int idx = 0;
                foreach (var sw in withTimes) {
                    var r = sw.GetResultForStage(_currentStage);
                    int rank = rkList[idx];
                    idx++;
                    string rkName = sw.Name;
                    if (rankRelay && !string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:"))
                        rkName = sw.Notes.Substring("接力队 棒次:".Length);
                    var sa = sw.GetAssignmentForStage(_currentStage);
                    int heatR = (sa != null && sa.Heat > 0) ? sa.Heat : sw.Heat;
                    items.Add(new {
                        rank = rank, heat = heatR, lane = sw.Lane,
                        bibNumber = sw.BibNumber, name = rkName, country = sw.Country,
                        gender = sw.Gender ?? "", ageGroup = sw.AgeCategory ?? "",
                        finalTime = r != null ? TimeFormatter.Format(r.FinalTime) : "",
                        status = sw.Status ?? "",
                        resultStatus = r != null ? (r.Status ?? "") : "",
                        recordNote = r != null ? (r.RecordNote ?? "") : "",
                        qualifiedToNext = IsQualifiedToNext(sw, _currentStage)
                    });
                }
                // DSQ/DNS/DNF/无成绩 追加, 无名次. TRI 不进总排名 (= 仅展示)
                // 2026-06-22 按 DSQ → DNF → DNS → 其他 排序 (用户要求 DSQ 在 DNS 上面)
                // 2026-09-01 TRI 判定看【有效状态】—— 试游是记在成绩行上的,
                //   只看 s.Status 会让 TRI 混进总排名末尾(规则是总排名不显示 TRI)。
                foreach (var sw in subList.Where(s => !withTimes.Contains(s)
                             && GetEffectiveStatus(s, s.GetResultForStage(_currentStage)) != "TRI")
                    .OrderBy(s => GetStatusSortOrder(GetEffectiveStatus(s, s.GetResultForStage(_currentStage))))) {
                    var r = sw.GetResultForStage(_currentStage);
                    string rkName = sw.Name;
                    if (rankRelay && !string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:"))
                        rkName = sw.Notes.Substring("接力队 棒次:".Length);
                    string remark = "";
                    if (r != null && !string.IsNullOrEmpty(r.Status)) remark = r.Status;
                    else if (!string.IsNullOrEmpty(sw.Status)) remark = sw.Status;
                    var sa = sw.GetAssignmentForStage(_currentStage);
                    int heatO = (sa != null && sa.Heat > 0) ? sa.Heat : sw.Heat;
                    items.Add(new {
                        rank = 0, heat = heatO, lane = sw.Lane,
                        bibNumber = sw.BibNumber, name = rkName, country = sw.Country,
                        gender = sw.Gender ?? "", ageGroup = sw.AgeCategory ?? "",
                        finalTime = "", status = remark, resultStatus = remark,
                        recordNote = "", qualifiedToNext = false
                    });
                }

                // 子分组标题: "男子 9-11岁" / "女子 12-13岁" / 接力则只 "男子" 等
                // 2026-06-04 顺序统一: 性别 在前, 组别 在后
                string genderLabel = (subGender == "男" || subGender == "女") ? (subGender + "子") : subGender;
                string title = rankRelay || string.IsNullOrEmpty(subAgeGroup)
                    ? genderLabel
                    : string.Format("{0} {1}", genderLabel, subAgeGroup);
                result.Add(new {
                    gender = subGender, ageGroup = subAgeGroup, title = title, items = items
                });
            }
            return result;
        }

        // 2026-06-22 (S1 源头重构) 大排名计算去重: 此 3-arg wrapper 转调 GetEventRankingForStage,
        //   后者是唯一实现 (含 DSQ/DNS/DNF 追加+排序, 兼容当前比赛 _resultConfirmed 补丁, qualifiedToNext 算).
        //   原 ~100 行复制实现已删, 避免改一边漏另一边 (2026-06-21 / 22 已发生过 2 次同步漏 bug).
        private List<object> GetEventRanking(string ageGroup, string eventName, string gender) {
            return GetEventRankingForStage(gender, eventName, ageGroup, _currentStage);
        }

        // ═══ 2026-06-21 颁奖弹窗选项目用 ═══
        // 列出已完赛 (Stage="决赛" + 全部组都 _confirmedHeats) 的项目, 供用户从中选 1 项颁奖
        private List<ScheduleItem> GetFullyConfirmedFinalEvents() {
            var result = new List<ScheduleItem>();
            foreach (var s in _schedule) {
                if (s == null || (s.Stage ?? "") != "决赛") continue;
                int hc = s.HeatCount > 0 ? s.HeatCount : 1;
                // 2026-09-18 跟 IsStageAllConfirmedFast(2026-08-24 已修的同一个问题, 见那边的
                //   说明)一样的坑: 被取消(并组)的组次号永远不会有人去点"确认本组成绩",
                //   这里原来没跳过它, 导致只要一个项目里有任何一组被并组过, 整个项目就
                //   永远进不了"颁奖"弹窗的候选名单——即使剩下真正在比的那些组早都确认完了。
                var cancelled = (s.CancelledHeats != null) ? s.CancelledHeats : new List<CancelledHeat>();
                bool allConfirmed = true; int live = 0;
                for (int h = 1; h <= hc; h++) {
                    if (cancelled.Any(x => x.Heat == h)) continue;
                    live++;
                    if (!IsHeatConfirmed(s.AgeGroup ?? "", s.Gender ?? "", s.EventName ?? "", s.Stage ?? "", h)) {
                        allConfirmed = false; break;
                    }
                }
                if (allConfirmed && live > 0) result.Add(s);
            }
            return result;
        }

        // 颁奖按钮选定的项目 (null = 未选, GetStatusData 不附加 awardSelection 字段, display.html 退回 _currentXxx)
        private ScheduleItem _awardSelection = null;
        // 2026-06-21 总排名按钮选定的项目 (回放任意已完赛项目, 与 _awardSelection 完全对称)
        private ScheduleItem _rankingSelection = null;

        // GetEventRanking 的参数化版本: stage 来自参数, 不依赖 _currentStage. 颁奖用 (stage=决赛).
        //   其余逻辑跟 GetEventRanking 保持一致 (并列名次 / TRI 排除 / 接力队员处理 / DSQ/DNS/DNF 追加).
        // 2026-06-21 (+ 2026-06-22 S1 重构: 此方法是大排名计算的唯一实现, GetEventRanking 3-arg 版改为 wrapper 调本方法).
        //   合并的兼容点:
        //   - heatCount 兜底用 _totalHeats (当前比赛 schedule 缺时), 不是 1
        //   - heat 循环到 Math.Max(heatCount, _currentHeat) (兼容当前比赛超 schedule 设置的偶发情况)
        //   - confirmed 判定加 stage==_currentStage && h==_currentHeat && _resultConfirmed 补丁
        //     (让"刚确认的最后一组"立刻进总排名, 不等下一帧广播; 仅当前比赛阶段生效, 颁奖回放无副作用)
        //   - qualifiedToNext 算 IsQualifiedToNext(sw, stage) (决赛 stage 无下阶段自然返 false)
        private List<object> GetEventRankingForStage(string gender, string eventName, string ageGroup, string stage) {
            if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(stage)) return new List<object>();
            bool rankRelay = eventName.Contains("接力");
            var schedItem = _schedule.FirstOrDefault(s => SgMatch(s.Gender, gender) && s.EventName == eventName
                                                          && s.Stage == stage
                                                          && (s.AgeGroup ?? "") == (ageGroup ?? ""));
            int heatCount = schedItem != null && schedItem.HeatCount > 0 ? schedItem.HeatCount : _totalHeats;
            var stageSwimmers = new List<Swimmer>();
            for (int h = 1; h <= Math.Max(heatCount, _currentHeat); h++) {
                bool confirmed = IsHeatConfirmed(ageGroup ?? "", gender, eventName, stage, h);
                if (!confirmed && stage == _currentStage && h == _currentHeat && _resultConfirmed) confirmed = true;
                if (!confirmed) continue;
                // 2026-10-08 用户明确要求: 总排名(大屏/颁奖回放都读这个方法)一律以分组表
                // 数据库为准, 不再自己重算谁在这一组——改成直接调 GetHeatEntries() (唯一
                // 权威入口, 已经是先查 heat_entries 库、查不到才退回内存 StageAssignment),
                // 不再在这里另开一份名单判定逻辑(两处各算一次正是用户点名的根因)。
                stageSwimmers.AddRange(GetHeatEntries(ageGroup ?? "", gender, eventName, stage, h));
            }
            var ranked = new List<object>();
            var withTimes = stageSwimmers.Where(s => {
                // 2026-09-01 同上: 判罚/弃权看【成绩行】的状态
                { var _r1 = s.GetResultForStage(stage);
                  string _st1 = GetEffectiveStatus(s, _r1);
                  if (ResultOrdering.IsJudged(_st1) || _st1 == "TRI") return false; }
                var r = s.GetResultForStage(stage);
                return r != null && r.FinalTime > 0;
            }).OrderBy(s => s.GetResultForStage(stage).FinalTime).ToList();
            // 2026-08-31 大屏总排名【读已定稿的组排名表】, 不再自己算。
            //   EventRankFor 取的是 event_rankings 灌回内存的定稿名次(见 ApplyEventRankingsFromDb)。
            //   项目还没全部比完 / 还没定稿时, 它退回按成绩现算 —— 那时本来就只是过程值。
            //   大屏的显示格式和内容一个字没动, 变的只是这些数字从哪来。
            // 2026-09-01 名次【只从库里读】, 这里一个字都不算。
            //   EventRank 是确认成绩时由竞赛库算好、回读进内存的(heat_entries.rank);
            //   项目全部比完定稿后, 又会被 event_rankings 的定稿值覆盖。
            //   库里没有(还没确认)就是没名次, 显示留空 —— 不许在这里现算一个出来,
            //   现算就会和成绩单、项目成绩各算各的, 三个地方三个答案(用户实拍到过)。
            withTimes = withTimes.OrderBy(s => { int rk0 = s.EventRankFor(stage); return rk0 > 0 ? rk0 : int.MaxValue; })
                                 .ThenBy(s => { var rr = s.GetResultForStage(stage); return rr != null ? rr.FinalTime : 0; })
                                 .ToList();
            var rkListER = withTimes.Select(s => s.EventRankFor(stage)).ToList();
            int idxER = 0;
            foreach (var sw in withTimes) {
                var r = sw.GetResultForStage(stage);
                int rank = rkListER[idxER];
                idxER++;
                string rkName = sw.Name;
                if (rankRelay && !string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:"))
                    rkName = sw.Notes.Substring("接力队 棒次:".Length);
                var saR = sw.GetAssignmentForStage(stage);
                int heatR = (saR != null && saR.Heat > 0) ? saR.Heat : sw.Heat;
                ranked.Add(new {
                    rank = rank, heat = heatR, lane = sw.Lane,
                    bibNumber = sw.BibNumber, name = rkName, country = sw.Country,
                    entryTime = sw.EntryTime ?? "",
                    finalTime = r != null ? TimeFormatter.Format(r.FinalTime) : "",
                    timingSource = r != null ? r.TimingSource : "",
                    status = sw.Status ?? "", resultStatus = r != null ? (r.Status ?? "") : "",
                    recordNote = r != null ? (r.RecordNote ?? "") : "",
                    qualifiedToNext = IsQualifiedToNext(sw, stage)
                });
            }

            // 2026-06-21 追加 DSQ/DNS/DNF/无成绩 运动员到末尾 (rank=0, 大屏总排名/颁奖回放都需显示).
            //   TRI 不进总排名 (与 GetEventRanking 一致).
            // 2026-06-22 按 DSQ → DNF → DNS → 其他 排序 (用户要求 DSQ 在 DNS 上面)
            // 2026-09-01 同上: TRI 判定和排序都走有效状态(成绩行优先)
            var othersFS = stageSwimmers.Where(s => !withTimes.Contains(s)
                    && GetEffectiveStatus(s, s.GetResultForStage(stage)) != "TRI")
                .OrderBy(s => GetStatusSortOrder(GetEffectiveStatus(s, s.GetResultForStage(stage))))
                .ToList();
            foreach (var sw in othersFS) {
                var r = sw.GetResultForStage(stage);
                string rkName = sw.Name;
                if (rankRelay && !string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:"))
                    rkName = sw.Notes.Substring("接力队 棒次:".Length);
                string remark = "";
                if (r != null && !string.IsNullOrEmpty(r.Status)) remark = r.Status;
                else if (!string.IsNullOrEmpty(sw.Status)) remark = sw.Status;
                var saO = sw.GetAssignmentForStage(stage);
                int heatO = (saO != null && saO.Heat > 0) ? saO.Heat : sw.Heat;
                ranked.Add(new {
                    rank = 0, heat = heatO, lane = sw.Lane,
                    bibNumber = sw.BibNumber, name = rkName, country = sw.Country,
                    entryTime = sw.EntryTime ?? "",
                    finalTime = "", timingSource = "",
                    status = remark, resultStatus = remark,
                    recordNote = "", qualifiedToNext = false
                });
            }
            return ranked;
        }

        // ═══════════════════════════════════════════════════════════════
        // 计时硬件
        // ═══════════════════════════════════════════════════════════════
        private void InitializeTimingBridge() {
            _timingBridge = new TimingBridge();
            // 2026-05-30 步骤 1: Dispatcher.Invoke → BeginInvoke 异步派发
            //   原同步 Invoke 让 SerialReceiveLoop/TcpReceiveLoop 接收线程在 UI 线程忙时整段阻塞,
            //   导致硬件→PC 延迟可达秒级 (UI 重绘 / Broadcast / AddLog 慢时).
            //   改 BeginInvoke 后: 接收线程 raise 事件 → 排队后立刻返回继续读下一帧,
            //   UI 线程空闲时按 FIFO 顺序消费. 帧间顺序保留, 接收线程不再被 UI 拖慢.
            // 2026-09-14 RTC 界面 TP/MB 状态灯比硬件自己的屏幕慢半拍 —— 根就在这条
            //   排队顺序上。RTC 比主服务器多一路排队: EditorSyncClient.OnMessage 收到
            //   主服务器转发回来的东西, 也是同样 Normal 优先级 BeginInvoke 到这同一个
            //   UI 线程。两路谁先排上谁先跑, 网络那路消息一多/一密, 后到的硬件触板帧
            //   就排在后面, 状态灯跟着晚刷 —— 这条本来就在上面注释里写过("间接导致
            //   硬件计时帧 backlog → 中间面板触板成绩/状态灯刷新不及时"), 一直没配优先级。
            //   硬件帧(触板/盲表/出发台/状态灯)是实时性要求最高的一路, 给它 Send
            //   优先级(WPF Dispatcher 里最高一档), 排到所有 Normal 优先级的网络消息前面,
            //   不用等排在它前面的那堆 EditorSync 消息处理完。
            _timingBridge.OnTimingData += delegate(TimingData data) {
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Send, (Action)delegate() {
                    ProcessTimingDataFromHardware(data);
                });
            };
            _timingBridge.OnStatusChanged += delegate(string status) {
                Dispatcher.BeginInvoke((Action)delegate() {
                    TimingStatusText.Text = status;
                    UpdateConnectionStatus();
                    // 2026-09-14 原则: 谁接着硬件计时器, 谁的"比赛控制"最高优先级 ——
                    //   不是"谁是 EXE 谁是网页"。RTC 硬件连接状态一变(连上/断开),
                    //   立刻把这个事实告诉主服务器, 主服务器据此决定该让谁说了算
                    //   (见 UpdateScoringControlMode / UpdateRaceControlTabLock)。
                    if (IsTimingClientMode) PushHwConnStatusToMainServer();
                    // 2026-09-14 本机(主服务器)自己的硬件连接状态变了, 也得重新评一遍
                    //   "比赛控制"该不该锁 —— 不然本机硬件刚插上那一刻, 页签还锁着,
                    //   要等下一次有远程连接数变化才会刷新, 现场感觉像"接上了也没用"。
                    //   (InitializeTimingBridge 只在非编排端模式下才会跑到这里, 这个分支
                    //   跑到的就是"主服务器本机", RTC 已经在上面 if 分支里单独处理过了)
                    else UpdateScoringControlMode();
                    // 硬件刚连上时，把当前参数/设备状态/比赛距离/发令点下发一次（以服务器为准）
                    if (_timingBridge != null && _timingBridge.IsConnected) {
                        // 2026-05-30 v2: 重连后清"不再提醒" 抑制标志, 让用户重新收到通知
                        if (_suppressHwDisconnectWarning) {
                            _suppressHwDisconnectWarning = false;
                            AddLog(Loc.T("Str_Log_HwReconnectedSuppressCleared"));
                        }
                        //2026-05-12 一上线就发送当前PC的日期+时间，让硬件RTC自动校时
                        try { _timingBridge.SendDateTimeSync(); } catch { }
                        SendTimingSettingsToHardware();
                        SendDeviceStatusesToHardware();
                        SendSetMatchEventToHardware();   // 0x43 — 总圈数+左右触板次数+空泳道位图
                        SendStartPositionToHardware();   // 0x10 0x42 — 发令点
                        //2026-05-12 同步当前"泳池单边/两端安装触板"配置到硬件
                        try {
                            if (_poolConfig != null) {
                                bool isSingle = !_poolConfig.HasRightStartBlock;
                                _timingBridge.SendPoolSingleOrDoubleTP(isSingle);
                            }
                        } catch { }
                        //2026-05-16 启动周期性时间同步定时器（每 30 分钟把 PC 时间再下发一次）
                        StartClockSyncTimer();
                    } else {
                        //2026-05-16 硬件断开 → 停止周期性时间同步
                        StopClockSyncTimer();
                    }
                });
            };
            _timingBridge.OnLog += delegate(string msg) {
                Dispatcher.BeginInvoke((Action)delegate() {
                    AddLog(msg);
                });
            };
            // 2026-06-10 事件备份接收: 累积到 _pendingBackupEvents, 末帧弹窗显示
            _timingBridge.OnBackupEvent += delegate(BackupEventInfo evt) {
                Dispatcher.BeginInvoke((Action)delegate() {
                    _pendingBackupEvents.Add(evt);
                    // 2026-06-14 发令事件诊断: 收到 EvtType=10 时立即 log, 让用户看到固件 v6 push 的发令时刻确实到了 PC
                    if (evt.IsGunEvent) {
                        AddLog(Loc.F("Str_Log_GunPreStartBackupFmt",
                            evt.Minute, evt.Second, evt.Msecond, evt.EvtType, evt.Lane, evt.Side));
                    }
                });
            };
            _timingBridge.OnBackupQueryComplete += delegate() {
                Dispatcher.BeginInvoke((Action)delegate() {
                    AddLog(Loc.F("Str_Log_EventBackupQueryDoneFmt", _pendingBackupEvents.Count));
                    ShowBackupEventDialog();
                });
            };
        }

        //2026-05-16 周期性把 PC 时间下发到硬件 RTC（30 min）
        //   触发: 硬件 IsConnected 变 true 时启动；变 false 或退出时停止
        //   第一次校时已在 OnStatusChanged 内立即调用 SendDateTimeSync()，本定时器只管后续周期触发
        private void StartClockSyncTimer() {
            if (_clockSyncTimer == null) {
                _clockSyncTimer = new DispatcherTimer { Interval = TimeSpan.FromMinutes(30) };
                _clockSyncTimer.Tick += delegate {
                    if (_timingBridge != null && _timingBridge.IsConnected) {
                        try { _timingBridge.SendDateTimeSync(); } catch { }
                    }
                };
            }
            if (!_clockSyncTimer.IsEnabled) _clockSyncTimer.Start();
        }

        private void StopClockSyncTimer() {
            if (_clockSyncTimer != null && _clockSyncTimer.IsEnabled) _clockSyncTimer.Stop();
        }

        // 2026-06-10 事件备份功能 (= 跟硬件 EventBackup ring buffer + NAND eventlog.bin 配合)
        //   裁判/操作员发现成绩争议时 → 查备份 → 找到漏掉的按键时间补录
        //   比赛结束确认无问题后 → 清空备份
        public void QueryBackupLog() {
            if (_timingBridge == null || !_timingBridge.IsConnected) {
                AppMessageBox.Show(Loc.T("Str_Msg_HwNotConnected"), Loc.T("Str_MsgTitle_CheckEventBackup"));
                return;
            }
            _pendingBackupEvents.Clear();
            _timingBridge.SendCommand(0x66);   // Query_BackupLog_Command (0x56) + 0x10
            AddLog(Loc.T("Str_Log_EventBackupQuerySent"));
        }

        public void ClearBackupLog() {
            if (_timingBridge == null || !_timingBridge.IsConnected) {
                AppMessageBox.Show(Loc.T("Str_Msg_HwNotConnected"), Loc.T("Str_MsgTitle_ClearEventBackup"));
                return;
            }
            var r = AppMessageBox.Show(Loc.T("Str_Msg_ClearHwBackupConfirm"), Loc.T("Str_MsgTitle_ClearConfirm"),
                MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (r != MessageBoxResult.Yes) return;
            _timingBridge.SendCommand(0x68);   // Clear_BackupLog_Command (0x58) + 0x10
            AddLog(Loc.T("Str_Log_EventBackupCleared"));
        }

        private void ShowBackupEventDialog() {
            if (_pendingBackupEvents.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_EventBackupEmpty"), Loc.T("Str_MsgTitle_EventBackup"));
                return;
            }
            // 2026-06-10 格式: 道N侧 出/触/盲X = 设备按下瞬间硬件时间 (= 跟比赛日志 = 后 SB/TP/MB 成绩同源)
            // 按键电路上拉到 1, 按下变 0 → 1→0 下降沿 = 按下 = 成绩瞬间. 硬件 OnSendSWData 帧也在此时刻发
            // 2026-06-10 lines 按当前泳道筛选动态生成. laneFilter = -1 表示全部, 0..9 表示只看道N
            //   存盘/打印/复制 均使用当前筛选后的 lines, 故反复重赋值 (闭包按引用捕获 lines 变量)
            var lines = new List<string>();
            Func<int, List<string>> buildLines = delegate(int laneFilter) {
                var ls = new List<string>();
                int pc = 0;
                // 2026-06-13 (晚) 调试用: 显示全部事件 (按下+松开), 不再过滤. 用于诊断"前 17 秒缺数据"等问题
                // 2026-06-14 发令事件 (IsGunEvent) 不受泳道筛选影响, 永远计入
                foreach (var e in _pendingBackupEvents) if (laneFilter < 0 || e.IsGunEvent || e.Lane == laneFilter) pc++;
                string scope = laneFilter < 0 ? "全部道次" : ("道" + laneFilter);
                // 2026-06-14 加发令事件统计: 让用户立即知道固件 v6 (EventBackup 发令 push) 是否生效
                int gunCount = 0;
                foreach (var e in _pendingBackupEvents) if (e.IsGunEvent) gunCount++;
                ls.Add(string.Format("==== 事件备份 [{0}] ({1} 条 [按下+松开 全部], 共 {2} 条原始, 含 {3} 条发令时刻) ====", scope, pc, _pendingBackupEvents.Count, gunCount));
                ls.Add("说明: '按下' = 下降沿 (= 成绩瞬间, 跟比赛日志 '= XX.XX' 同源); '松开' = 上升沿");
                if (gunCount == 0) {
                    ls.Add("⚠ 未收到发令时刻记录: 确认固件已烧录 2026-06-14 v6 版本 (StartTiming 末尾应有 EvtType=10 push); 或本场未真正按发令键");
                } else {
                    // 2026-06-14 把所有发令时刻汇总在顶部, 方便用户对比反应时
                    ls.Add("---- 发令时刻摘要 ----");
                    foreach (var e in _pendingBackupEvents) {
                        if (!e.IsGunEvent) continue;
                        string tsG;
                        if (e.Hour > 0)        tsG = string.Format("{0}:{1:00}:{2:00}.{3:00}", e.Hour, e.Minute, e.Second, e.Msecond);
                        else if (e.Minute > 0) tsG = string.Format("{0}:{1:00}.{2:00}", e.Minute, e.Second, e.Msecond);
                        else                   tsG = string.Format("{0}.{1:00}", e.Second, e.Msecond);
                        ls.Add(string.Format("  [发令] PreStart 计数器 = {0}", tsG));
                    }
                }
                ls.Add("");
                // 2026-06-23 Δ 算法重写: 维护 currentGunPs (= 当前 Ready/Reset 区间内最近一次发令时刻).
                //   遇 RangeMarker (Ready/Reset) 重置 currentGunPs=null, 遇 IsGunEvent 更新, 普通事件用它算 Δ.
                //   旧算法 break 取第 1 个发令时刻 → 跨组取错. 新算法每组独立, 抢跳重发也取最后一次.
                // 2026-06-24 仅"每 lane × 每 gun 段最后一个反应时锚点" 显示 Δ (= 一组运动员只一个反应时).
                //   pre-pass 扫一遍标记锚点 idx, render-pass 用集合判定. gun 之前的事件 + 非锚点设备类型 + 非最后锚点 → 仅 (P) 不显示 Δ.
                var anchorIdxSet = new HashSet<int>();
                {
                    double? prePassGun = null;
                    var lastAnchorIdxPerLane = new Dictionary<int, int>();
                    Action commitLastAnchors = () => {
                        foreach (var v in lastAnchorIdxPerLane.Values) anchorIdxSet.Add(v);
                        lastAnchorIdxPerLane.Clear();
                    };
                    for (int i = 0; i < _pendingBackupEvents.Count; i++) {
                        var ev = _pendingBackupEvents[i];
                        if (ev.IsRangeMarker) { commitLastAnchors(); prePassGun = null; continue; }
                        if (ev.IsGunEvent)    { commitLastAnchors(); prePassGun = ev.Hour * 3600.0 + ev.Minute * 60.0 + ev.Second + ev.Msecond / 100.0; continue; }
                        if (!ev.IsPreStartTime || !prePassGun.HasValue) continue;   // gun 前 / 非 PreStart 跳过
                        int bt = ev.EvtType & 0x7F;
                        bool isAnc = false;
                        if (bt == 0 || bt == 1) {
                            bool sbFalling = _laneCloseSettings == null || _laneCloseSettings.StartBoxEdgeFalling;
                            if (sbFalling && bt == 0) isAnc = true;
                            else if (!sbFalling && bt == 1) isAnc = true;
                        } else if (bt == 3) {
                            isAnc = true;
                        }
                        if (isAnc) lastAnchorIdxPerLane[ev.Lane] = i;
                    }
                    commitLastAnchors();  // 收尾: 最后一组的最后锚点
                }
                double? currentGunPs = null;
                int evtIdx = -1;
                foreach (var evt in _pendingBackupEvents) {
                    evtIdx++;
                    // 2026-06-14 发令事件 (EvtType=10) lane/side=0xFF 表全场, 不受泳道筛选过滤
                    // 2026-06-23 RangeMarker (EvtType=11/12) 同样全场, 不受筛选过滤
                    if (laneFilter >= 0 && !evt.IsGunEvent && !evt.IsRangeMarker && evt.Lane != laneFilter) continue;
                    string ts;
                    if (evt.Hour > 0)        ts = string.Format("{0}:{1:00}:{2:00}.{3:00}", evt.Hour, evt.Minute, evt.Second, evt.Msecond);
                    else if (evt.Minute > 0) ts = string.Format("{0}:{1:00}.{2:00}", evt.Minute, evt.Second, evt.Msecond);
                    else                     ts = string.Format("{0}.{1:00}", evt.Second, evt.Msecond);
                    if (evt.IsRangeMarker) {
                        // 2026-06-23 组分隔: 比赛就绪 / 计时复位 — 重置 currentGunPs (新组开始)
                        ls.Add(string.Format("---- {0} ----", evt.RangeMarkerLabel));
                        currentGunPs = null;
                    }
                    else if (evt.IsGunEvent) {
                        // 2026-06-14 发令时刻特殊格式: 时间是 Gun_PreStart_* (= 反应时核对参考点)
                        // 2026-06-23 同时更新 currentGunPs, 后续本组 PreStart 事件用它算 Δ
                        currentGunPs = evt.Hour * 3600.0 + evt.Minute * 60.0 + evt.Second + evt.Msecond / 100.0;
                        ls.Add(string.Format("[发令时刻] = {0,8} (PreStart 计数器值, 后续 TP/SB 反应时 = 该 TP 时间 - 此处)", ts));
                    } else {
                        // 2026-06-14 IsPreStartTime: 固件设了 EvtType bit7 表示时间字段是 PreStart 计数器值 (= 发令前/开门窗口内事件),
                        //   不是 race timer. 加 " (P)" 标志, 避免操作员把出发反应时段的时间当成 race timer 比较.
                        // 2026-06-15 PreStart 事件附加 Δ (差值) = PreStart 时间 - 发令时刻 PreStart, 直接读出反应时, 跟硬件 LCD 显示一致
                        // 2026-06-23 用 currentGunPs (本组最近一次发令时刻), 没有则显示 Δ=?
                        string pFlag = "";
                        if (evt.IsPreStartTime) {
                            // 2026-06-24 仅"每 lane × gun 段最后一个反应时锚点"显示 Δ (= pre-pass 标记的 anchorIdxSet).
                            //   gun 前事件 + 非锚点设备 (TP 按下/MB) + 非最后锚点 → 仅显示 (P) 不算 Δ.
                            if (anchorIdxSet.Contains(evtIdx) && currentGunPs.HasValue) {
                                double evtPs = evt.Hour * 3600.0 + evt.Minute * 60.0 + evt.Second + evt.Msecond / 100.0;
                                double delta = evtPs - currentGunPs.Value;
                                pFlag = string.Format(" (P, Δ={0:+0.00;-0.00}s)", delta);
                            } else {
                                pFlag = " (P)";
                            }
                        }
                        ls.Add(string.Format("道{0}{1} {2} {3} = {4,8}{5} 硬件状态={6}",
                            evt.Lane, evt.SideLabel, evt.EventLabel, evt.ActionLabel, ts, pFlag, evt.DevState));
                    }
                }
                if (pc == 0) ls.Add(laneFilter < 0 ? Loc.T("Str_Win_EventBackup_NoEvents") : Loc.F("Str_Win_EventBackup_NoEventsLaneFmt", laneFilter));
                return ls;
            };

            // 滚动窗口
            var wnd = new Window {
                Title = Loc.F("Str_Win_EventBackup_TitleFmt", _pendingBackupEvents.Count),
                Width = 900, Height = 600,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this
            };
            var grid = new Grid();
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                       // 行0: 泳道查询
            grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });  // 行1: 滚动列表
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                       // 行2: 按钮

            // 2026-06-10 泳道查询: 选 道0..道9 只看该道, 选 全部 看所有道
            var filterPanel = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(10, 8, 10, 0), VerticalAlignment = VerticalAlignment.Center };
            filterPanel.Children.Add(new TextBlock { Text = Loc.T("Str_Win_EventBackup_LaneQueryLabel"), VerticalAlignment = VerticalAlignment.Center, FontSize = 13, Margin = new Thickness(0, 0, 8, 0) });
            var laneCombo = new ComboBox { Width = 120, FontSize = 13 };
            laneCombo.Items.Add(Loc.T("Str_Common_All"));
            for (int i = 0; i <= 9; i++) laneCombo.Items.Add(Loc.T("Str_Win_EventBackup_LanePrefix") + i);
            laneCombo.SelectedIndex = 0;
            filterPanel.Children.Add(laneCombo);
            Grid.SetRow(filterPanel, 0);
            grid.Children.Add(filterPanel);

            var listBox = new ListBox {
                FontFamily = new System.Windows.Media.FontFamily("Consolas"),
                FontSize = 13
            };
            ScrollViewer.SetHorizontalScrollBarVisibility(listBox, ScrollBarVisibility.Auto);
            ScrollViewer.SetVerticalScrollBarVisibility(listBox, ScrollBarVisibility.Auto);
            Grid.SetRow(listBox, 1);
            grid.Children.Add(listBox);

            // 2026-06-10 按下拉选择重建列表. SelectedIndex: 0=全部, 1..10 → 道0..道9
            Action refreshList = delegate {
                int sel = laneCombo.SelectedIndex;
                int laneFilter = sel <= 0 ? -1 : sel - 1;
                lines = buildLines(laneFilter);
                listBox.Items.Clear();
                foreach (var line in lines) listBox.Items.Add(line);
            };
            laneCombo.SelectionChanged += delegate { refreshList(); };
            refreshList();   // 初始显示 全部

            // 按钮: 存盘 / 打印 / 复制 / 关闭
            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(10) };

            var btnSave = new Button { Content = Loc.T("Str_Btn_Save"), Width = 80, Height = 30, Margin = new Thickness(5) };
            btnSave.Click += delegate(object s, RoutedEventArgs e) {
                var dlg = new Microsoft.Win32.SaveFileDialog {
                    FileName = string.Format("{0}_{1:yyyyMMdd_HHmmss}.txt", Loc.T("Str_MsgTitle_EventBackup"), DateTime.Now),
                    Filter = Loc.T("Str_Filter_TextFile"),
                    Title = Loc.T("Str_MsgTitle_EventBackup")
                };
                if (dlg.ShowDialog() == true) {
                    try {
                        System.IO.File.WriteAllLines(dlg.FileName, lines, System.Text.Encoding.UTF8);
                        AppMessageBox.Show(Loc.F("Str_Msg_SavedAsFmt", dlg.FileName), Loc.T("Str_MsgTitle_SaveToDisk"), MessageBoxButton.OK, MessageBoxImage.Information);
                    } catch (Exception ex) {
                        AppMessageBox.Show(Loc.F("Str_Msg_SaveFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Save"), MessageBoxButton.OK, MessageBoxImage.Error);
                    }
                }
            };
            btnPanel.Children.Add(btnSave);

            var btnPrint = new Button { Content = Loc.T("Str_Win_DocPreview_PrintBtn"), Width = 80, Height = 30, Margin = new Thickness(5) };
            btnPrint.Click += delegate(object s, RoutedEventArgs e) {
                try {
                    var pd = new System.Windows.Controls.PrintDialog();
                    if (pd.ShowDialog() == true) {
                        var flowDoc = new System.Windows.Documents.FlowDocument();
                        flowDoc.FontFamily = new System.Windows.Media.FontFamily("Consolas");
                        flowDoc.FontSize = 11;
                        flowDoc.PageWidth = pd.PrintableAreaWidth;
                        flowDoc.PagePadding = new Thickness(40);
                        foreach (var line in lines) {
                            flowDoc.Blocks.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run(line)) { Margin = new Thickness(0) });
                        }
                        var paginator = ((System.Windows.Documents.IDocumentPaginatorSource)flowDoc).DocumentPaginator;
                        pd.PrintDocument(paginator, Loc.T("Str_Win_EventBackup_PrintDocName"));
                    }
                } catch (Exception ex) {
                    AppMessageBox.Show(Loc.F("Str_Msg_PrintFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Print"), MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };
            btnPanel.Children.Add(btnPrint);

            var btnCopy = new Button { Content = Loc.T("Str_Btn_Copy"), Width = 80, Height = 30, Margin = new Thickness(5) };
            btnCopy.Click += delegate(object s, RoutedEventArgs e) {
                try {
                    System.Windows.Clipboard.SetText(string.Join("\r\n", lines));
                    AppMessageBox.Show(Loc.T("Str_Msg_CopiedToClipboard"), Loc.T("Str_MsgTitle_Copy"));
                } catch (Exception ex) {
                    AppMessageBox.Show(Loc.F("Str_Msg_CopyFailedFmt", ex.Message));
                }
            };
            btnPanel.Children.Add(btnCopy);

            var btnClose = new Button { Content = Loc.T("Str_Btn_Close"), Width = 80, Height = 30, Margin = new Thickness(5) };
            btnClose.Click += delegate(object s, RoutedEventArgs e) { wnd.Close(); };
            btnPanel.Children.Add(btnClose);

            Grid.SetRow(btnPanel, 2);
            grid.Children.Add(btnPanel);

            // 快捷键: Ctrl+S 存盘, Ctrl+P 打印, Ctrl+C 复制, Esc 关闭
            wnd.PreviewKeyDown += delegate(object s, System.Windows.Input.KeyEventArgs e) {
                bool ctrl = (System.Windows.Input.Keyboard.Modifiers & System.Windows.Input.ModifierKeys.Control) != 0;
                if (ctrl && e.Key == System.Windows.Input.Key.S) { btnSave.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); e.Handled = true; }
                else if (ctrl && e.Key == System.Windows.Input.Key.P) { btnPrint.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); e.Handled = true; }
                else if (ctrl && e.Key == System.Windows.Input.Key.C) { btnCopy.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); e.Handled = true; }
                else if (e.Key == System.Windows.Input.Key.Escape) { wnd.Close(); e.Handled = true; }
            };

            wnd.Content = grid;
            wnd.ShowDialog();

            _pendingBackupEvents.Clear();
        }

        private void ProcessTimingDataFromHardware(TimingData data) {
            // 双保险: 就算有帧从别处进来(手工连了硬件/遥控转发), 主服务器也不处理
            if (IsScoringServerNoTiming) return;
            // 硬件下发的参数设置帧：不走运动员计时路径，走双向同步
            if (data.CommandType == TimingCommandType.PoolConfig ||
                data.CommandType == TimingCommandType.RaceConfig ||
                data.CommandType == TimingCommandType.SetCommand) {
                ApplyHardwareSettingFrame(data);
                return;
            }
            // 2026-05-13 硬件计时器电池电压上报：D3:D4 高低字节 = mV，仅做显示，不进计时路径
            if (data.CommandType == TimingCommandType.BatteryVoltage) {
                int mv = (data.Param1 << 8) | data.RawD4;
                double volts = mv / 1000.0;
                _hwBatteryVoltage = volts;
                _hwBatteryReceivedAt = DateTime.Now;
                UpdateBatteryVoltageDisplay();
                Broadcast();   // 推给所有客户端（编排端/大屏可同步显示）
                return;
            }
            // 2026-05-17 硬件→PC: 5 项时间数据 (0x64)
            //   触发场景: 硬件 net_test 子界面退出，把 5 个时间编辑框的值刷入硬件变量后
            //   D3=泳道封闭时间 D4=触板延迟关闭时间 D5=出发台延迟关闭时间 D6=盲表代替延迟时间 D7=成绩显示时间
            //   单位均为秒（硬件内部 0.1s 单位发送时已经 /10）
            if (data.CommandType == TimingCommandType.TimingsBundle) {
                if (_laneCloseSettings != null) {
                    bool changed = false;
                    double v;
                    v = data.Param1;             if (Math.Abs(_laneCloseSettings.LaneCloseTime - v) > 0.001)           { _laneCloseSettings.LaneCloseTime = v; changed = true; }
                    v = data.RawD4;              if (Math.Abs(_laneCloseSettings.ResultConfirmCloseDelay - v) > 0.001) { _laneCloseSettings.ResultConfirmCloseDelay = v; changed = true; }
                    v = data.Param5;             if (Math.Abs(_laneCloseSettings.StartBlockCloseDelay - v) > 0.001)    { _laneCloseSettings.StartBlockCloseDelay = v; changed = true; }
                    v = data.Param6;             if (Math.Abs(_laneCloseSettings.BlindReplaceDelay - v) > 0.001)       { _laneCloseSettings.BlindReplaceDelay = v; changed = true; }
                    v = data.Param7;             if (Math.Abs(_laneCloseSettings.SplitDisplayTime - v) > 0.001)        { _laneCloseSettings.SplitDisplayTime = v; changed = true; }
                    if (changed) {
                        AddLog(Loc.F("Str_Log_HwParamsFmt",
                            _laneCloseSettings.LaneCloseTime, _laneCloseSettings.ResultConfirmCloseDelay,
                            _laneCloseSettings.StartBlockCloseDelay, _laneCloseSettings.BlindReplaceDelay,
                            _laneCloseSettings.SplitDisplayTime));
                        UpdateLaneStatusDisplay();
                        Broadcast();
                    }
                }
                return;
            }
            // 2026-05-17 硬件→PC: 道次顺序 (0x62)
            //   触发场景: 硬件"参数设置→道次顺序"按钮切换后返回主控
            //   D3 = 0 正向 (forward) / 1 反向 (reverse)
            if (data.CommandType == TimingCommandType.LaneOrder) {
                string newOrder = (data.Param1 != 0) ? "reverse" : "forward";
                if (_laneCloseSettings != null && _laneCloseSettings.LaneOrder != newOrder) {
                    _laneCloseSettings.LaneOrder = newOrder;
                    AddLog(Loc.F("Str_Log_HwLaneOrderFmt", newOrder == "reverse" ? Loc.T("Str_Frag_Reverse90") : Loc.T("Str_Frag_Forward09")));
                    UpdateLaneStatusDisplay();
                    Broadcast();
                }
                return;
            }
            // 2026-05-17 硬件→PC: 终点位置 (0x63)
            //   触发场景: 硬件"参数设置→终点位置"按钮切换后返回主控
            //   D3 = 0 终点左端 (left) / 1 终点右端 (right)
            if (data.CommandType == TimingCommandType.FinishPosition) {
                string newFinish = (data.Param1 != 0) ? "right" : "left";
                if (_laneCloseSettings != null && _laneCloseSettings.FinishPosition != newFinish) {
                    _laneCloseSettings.FinishPosition = newFinish;
                    _laneCloseSettings.StartPosition = newFinish;
                    try { AutoAdjustStartPosition(); } catch { }
                    //2026-05-18 单端模式下"非终点端"由 FinishPosition 决定；
                    //   终点位置切换后必须刷新各道 NotInstalled 标记，让原非终点端恢复、新非终点端置位
                    try { ApplyTouchpadInstallModeToLanes(); } catch { }
                    // 2026-05-26 计算后的 NotInstalled 落盘 + 参数本身落盘
                    try { SaveDeviceStates(); } catch { }
                    try { SaveTimingSettings(); } catch { }
                    AddLog(Loc.F("Str_Log_HwFinishPosFmt", newFinish == "left" ? Loc.T("Str_Frag_LeftEnd") : Loc.T("Str_Frag_RightEnd")));
                    UpdateLaneStatusDisplay();
                    Broadcast();
                }
                return;
            }
            // 2026-05-16 硬件→PC: 泳池触板安装方式 (0x3A)
            //   触发场景: 硬件"参数设置→单/两端安装触板"切换后返回主控。
            //   D3 = 0 两端 (HasRightStartBlock=true) / 1 单端 (HasRightStartBlock=false)
            //   等价于 PC 自身切换两端/单端按钮的处理，但不回发 0x3A 防回环。
            if (data.CommandType == TimingCommandType.PoolSingleOrDouble) {
                bool newHasRight = (data.Param1 == 0);
                if (_poolConfig != null && _poolConfig.HasRightStartBlock != newHasRight) {
                    _poolConfig.HasRightStartBlock = newHasRight;
                    _laneCloseSettings.HasRightStartBlock = newHasRight;   // 2026-05-26 持久化
                    ApplyTouchpadInstallModeToLanes();
                    // 2026-05-26 计算后的 NotInstalled 落盘 + 参数本身落盘
                    try { SaveDeviceStates(); } catch { }
                    try { SaveTimingSettings(); } catch { }
                    UpdateLaneStatusDisplay();
                    AddLog(Loc.F("Str_Log_HwTouchpadModeFmt", newHasRight ? Loc.T("Str_Log_BothEnds") : Loc.T("Str_Log_Single")));
                    Broadcast();
                }
                return;
            }
            // 2026-05-16 硬件→PC: 道次开关上报 (0x47)
            //   触发场景: 硬件计时器在"参数设置→封闭/不封闭TP"切换后返回主控时，
            //             用此命令把 Open_State 同步给 PC，使主控里"全部打开/全部关闭"按钮状态对齐。
            //   D3 = 0xFF 全部泳道 / 0..9 单道；D4 = 1 打开 / 0 关闭
            //   实现等价于 OpenAll_Click / CloseAll_Click 但不回发 0x47（防回环）。
            // 2026-05-31 硬件颜色 → PC Hw*Color 字段同步 (= 0x50/0x51/0x52 协议)
            //   协议: D3=side (0=左/1=右), D4=lane (0-9), D5=newState (0-5), D6=mb_idx (MB only)
            //   只更新独立的 Hw*Color 字段, **不动业务 Status 字段** (= LeftTouchpadStatus 等),
            //   防止再次污染 PC 内部 Open→Touched→Closed 状态机 (= 之前的 N+1 圈 bug 根因).
            //   PC UI 控制端"泳道实时状态" 圆点 StyleDot 改用 Hw*Color 渲染, 反映硬件实际 LCD 颜色.
            if (data.CommandType == TimingCommandType.StartblockStateChange ||
                data.CommandType == TimingCommandType.TPStateChange ||
                data.CommandType == TimingCommandType.MBStateChange) {
                int hwLane = data.Lane;
                if (hwLane < 0 || hwLane >= _laneDeviceStates.Count) return;
                byte hwSide = data.Param1;   // D3: 0=左 / 1=右 (硬件新约定独立字段)
                byte hwNewState = data.Param5; // D5: 0-5
                byte hwMbIdx = data.Param6;  // D6: MB 0/1/2 (= BlindWatch 1/2/3)
                var hwLs = _laneDeviceStates[hwLane];
                bool hwIsLeft = (hwSide == 0);
                switch (data.CommandType) {
                    case TimingCommandType.StartblockStateChange:
                        if (hwIsLeft) hwLs.HwLeftStartBlockColor = hwNewState;
                        else hwLs.HwRightStartBlockColor = hwNewState;
                        break;
                    case TimingCommandType.TPStateChange: {
                        // 2026-06-06 配套 PC 端 MB 代触拦截: 若 1s 内刚因开关=关 丢过该侧 MB 代触 Touchpad 包,
                        //   紧跟到达的 TP 颜色变更也压制 — 否则硬件 LCD 自动变红会通过 Hw*Color 传到 PC UI 圆点.
                        DateTime supUntil;
                        int supKey = hwLane * 2 + (hwIsLeft ? 0 : 1);
                        if (_mbSubTpSuppressUntil.TryGetValue(supKey, out supUntil) && supUntil > DateTime.Now) {
                            AddLog(Loc.F("Str_Log_TpColorSuppressedFmt", hwLane, hwIsLeft ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                            break;
                        }
                        if (hwIsLeft) hwLs.HwLeftTouchpadColor = hwNewState;
                        else hwLs.HwRightTouchpadColor = hwNewState;
                        break;
                    }
                    case TimingCommandType.MBStateChange:
                        if (hwIsLeft) {
                            if (hwMbIdx == 0) hwLs.HwLeftBlindWatch1Color = hwNewState;
                            else if (hwMbIdx == 1) hwLs.HwLeftBlindWatch2Color = hwNewState;
                            else if (hwMbIdx == 2) hwLs.HwLeftBlindWatch3Color = hwNewState;
                        } else {
                            if (hwMbIdx == 0) hwLs.HwRightBlindWatch1Color = hwNewState;
                            else if (hwMbIdx == 1) hwLs.HwRightBlindWatch2Color = hwNewState;
                            else if (hwMbIdx == 2) hwLs.HwRightBlindWatch3Color = hwNewState;
                        }
                        break;
                }
                UpdateLaneStatusDisplay();   // 触发 UI 重绘
                Broadcast();                  // JSON 同步给 web 端
                return;
            }

            if (data.CommandType == TimingCommandType.LaneOpenClose) {
                byte d3 = data.Param1;
                bool laneOpen = (data.RawD4 == 1);
                DeviceStatus ds = laneOpen ? DeviceStatus.Open : DeviceStatus.Closed;
                if (d3 == 0xFF) {
                    foreach (var s in _laneDeviceStates) {
                        s.LeftTouchpadStatus = ds;
                        s.LeftBlindWatch1Status = ds;
                        s.LeftBlindWatch2Status = ds;
                        s.LeftBlindWatch3Status = ds;
                        s.RightTouchpadStatus = ds;
                        s.RightBlindWatch1Status = ds;
                        s.RightBlindWatch2Status = ds;
                        s.RightBlindWatch3Status = ds;
                        s.LaneCloseCountdown = 0;
                    }
                    UpdateLaneStatusDisplay();
                    AddLog(laneOpen ? Loc.T("Str_Log_HwAllLanesOpen") : Loc.T("Str_Log_HwAllLanesClosed"));
                    Broadcast();
                } else if (d3 < 10 && d3 < _laneDeviceStates.Count) {
                    var s = _laneDeviceStates[d3];
                    s.LeftTouchpadStatus = ds;
                    s.LeftBlindWatch1Status = ds;
                    s.LeftBlindWatch2Status = ds;
                    s.LeftBlindWatch3Status = ds;
                    s.RightTouchpadStatus = ds;
                    s.RightBlindWatch1Status = ds;
                    s.RightBlindWatch2Status = ds;
                    s.RightBlindWatch3Status = ds;
                    s.LaneCloseCountdown = 0;
                    UpdateLaneStatusDisplay();
                    AddLog(Loc.F("Str_Log_HwLaneToggleFmt", d3, laneOpen ? Loc.T("Str_Frag_Open") : Loc.T("Str_Frag_Close")));
                    Broadcast();
                }
                return;
            }

            string cmdType = data.CommandType.ToString();
            //2026-05-26 修复: 硬件 D4 字段是物理硬编码 (swimplay.c Lane_NoTbl 表):
            //   D4 0-9   = 物理【左端】泳道号 (Lane_NoTbl[i],   i=0-9)
            //   D4 10-19 = 物理【右端】泳道号 (Lane_NoTbl[i+10], 实际道次 = D4-10)
            //   LaneDir 正/逆序只翻转值的排列, 不改变"低段属左端、高段属右端"的物理映射.
            //   与 FinalPlace / FinishPosition 完全无关.
            // 原代码用 FinishPosition 做翻转是历史错位: 默认 FinishPosition=left 时左端恰好=finish端,
            //   两层错位互相抵消才看起来对. FinishPosition=right 时 50m+100m 完赛触板查错 side
            //   → 数据被 LeftTouchpadStatus=Closed 丢弃, PC 端无显示 (PDF v2026.05.26 §1 报告的现象).
            // 注: TimingBridge.cs 里 IsFinishEnd 这个字段名是历史遗留, 真实语义是"物理左端"(D4<10).
            string side = data.IsFinishEnd ? "left" : "right";
            //2026-05-31 cmd=0x16 (Touchpad) 且 d3=Pushbutton_Result(=1) 表示"硬件用盲表代替触板", PC 强制接受
            //2026-06-14 重构: 区分由 TimingBridge 解析时完成, ManualTouchpad 枚举值已合成了 0x16+Param1==1 这一情况
            bool isMbSubstitute = (data.CommandType == TimingCommandType.ManualTouchpad);
            // 2026-06-06 修复 "开关=关 但盲表仍代替触板" — 硬件按 BlindReplaceDelay 超时后会自行发 cmd=0x16 d3=1 代触,
            //   PC 之前不论开关都强制接受 (3651 处守卫旁路). 现按开关在 PC 接收侧拦截: 盲表自身的 PushButton 帧
            //   已被其他路径记录, 丢弃这一包不丢盲表数据, 只是拒绝把它转成 Touchpad. 硬件 mbDelay 不变 (按用户要求).
            //   同时标记 1s 抑制窗口: 紧跟的 TPStateChange (0x51) 颜色变更帧也丢, 否则 PC UI 圆点会跟着变红.
            if (isMbSubstitute && _laneCloseSettings != null && !_laneCloseSettings.AutoBlindReplaceTouchpad) {
                AddLog(Loc.F("Str_Log_BwSubTouchDroppedFmt", data.Lane));
                bool dropIsLeft = (side == "left");
                _mbSubTpSuppressUntil[data.Lane * 2 + (dropIsLeft ? 0 : 1)] = DateTime.Now.AddSeconds(1);
                return;
            }
            // 2026-06-06 跳圈抑制: PC 右键 T 已推进 lap, 紧跟操作员按硬件手动 TP 键发的 0x16 在窗口内丢, 避免二次推进.
            // 2026-06-14 真触板和手动 TP 键(MB 代触)两种都要应用抑制窗口 (注释说的"操作员按硬件手动 TP 键" 主要就是 MB 代触场景).
            if (data.CommandType == TimingCommandType.Touchpad || data.CommandType == TimingCommandType.ManualTouchpad) {
                DateTime skipUntil;
                if (_skipNextHwTpUntil.TryGetValue(data.Lane, out skipUntil) && skipUntil > DateTime.Now) {
                    AddLog(Loc.F("Str_Log_TpInLapSuppressFmt", data.Lane));
                    _skipNextHwTpUntil.Remove(data.Lane);
                    return;
                }
            }
            //2026-05-31 cmd=0x1A d10=2 表示"接力 SB 超时无 TP/MB", cmdType 改 "StartingBlockTimeout", 日志显示 "出---"
            if (data.IsTimeoutNoReaction) cmdType = "StartingBlockTimeout";
            // 2026-05-12 协议扩展：StartingBlock 命令 D10≠0 表示抢跳，TimeInSeconds 已被解析器取反为负值
            ProcessTimingData(data.Lane, cmdType, data.TimeInSeconds, side, data.IsFalseStart, isMbSubstitute);
        }

        // 2026-05-19 接收 RemoteTimingControl(远程 EXE) 转发的硬件参数上报
        // 远程 EXE 充当"硬件 ↔ 主服务器"桥, 把硬件→PC 的扩展命令(电池/道次顺序/终点位置/单两端/道次开关/5项时间)
        // 拆为具体的 *_REPORT TIMING_CMD 子命令转给主服务器, 这里把它们还原为 TimingData 后走 ProcessTimingDataFromHardware
        // 复用同一套状态更新逻辑(更新 _laneCloseSettings/_poolConfig/_laneDeviceStates + AddLog + Broadcast), 避免代码重复
        private void HandleHardwareReportForwarded(string cmd, JObject data) {
            if (data == null) { AddLog(Loc.F("Str_Log_DataNullFmt", cmd)); return; }
            try {
                var td = new TimingData {
                    Lane = 0,
                    Minutes = 0, Seconds = 0, Centiseconds = 0, Milliseconds = 0,
                    ReceivedAt = DateTime.Now,
                    IsFinishEnd = false,
                    IsFalseStart = false
                };
                switch (cmd) {
                    case "BATTERY_REPORT": {
                        double v = data["voltage"] != null ? (double)data["voltage"] : 0.0;
                        int mv = (int)Math.Round(v * 1000.0);
                        td.CommandType = TimingCommandType.BatteryVoltage;
                        td.Param1 = (byte)((mv >> 8) & 0xFF);  // d3 = mV 高字节 (BIG-ENDIAN)
                        td.RawD4  = (byte)(mv & 0xFF);          // d4 = mV 低字节
                        td.BatteryVoltage = v;
                        break;
                    }
                    case "TIMINGS_BUNDLE_REPORT": {
                        td.CommandType = TimingCommandType.TimingsBundle;
                        td.Param1 = (byte)(data["laneCloseTime"]            != null ? Math.Min(255, Math.Max(0, (int)data["laneCloseTime"])) : 0);
                        td.RawD4  = (byte)(data["resultConfirmCloseDelay"] != null ? Math.Min(255, Math.Max(0, (int)data["resultConfirmCloseDelay"])) : 0);
                        td.Param5 = (byte)(data["startBlockCloseDelay"]    != null ? Math.Min(255, Math.Max(0, (int)data["startBlockCloseDelay"])) : 0);
                        td.Param6 = (byte)(data["blindReplaceDelay"]       != null ? Math.Min(255, Math.Max(0, (int)data["blindReplaceDelay"])) : 0);
                        td.Param7 = (byte)(data["splitDisplayTime"]        != null ? Math.Min(255, Math.Max(0, (int)data["splitDisplayTime"])) : 0);
                        break;
                    }
                    case "LANE_ORDER_REPORT": {
                        string order = data["order"] != null ? data["order"].ToString() : "forward";
                        td.CommandType = TimingCommandType.LaneOrder;
                        td.Param1 = (byte)(order == "reverse" ? 1 : 0);
                        break;
                    }
                    case "FINISH_POS_REPORT": {
                        string pos = data["pos"] != null ? data["pos"].ToString() : "left";
                        td.CommandType = TimingCommandType.FinishPosition;
                        td.Param1 = (byte)(pos == "right" ? 1 : 0);
                        break;
                    }
                    case "POOL_SIDE_REPORT": {
                        bool single = data["single"] != null && (bool)data["single"];
                        td.CommandType = TimingCommandType.PoolSingleOrDouble;
                        td.Param1 = (byte)(single ? 1 : 0);   // d3=0 两端 / 1 单端
                        break;
                    }
                    case "LANE_OPEN_CLOSE_REPORT": {
                        int lane = data["lane"] != null ? (int)data["lane"] : -1;
                        bool open = data["open"] != null && (bool)data["open"];
                        td.CommandType = TimingCommandType.LaneOpenClose;
                        td.Param1 = (byte)(lane < 0 || lane >= 10 ? 0xFF : lane);
                        td.RawD4  = (byte)(open ? 1 : 0);
                        break;
                    }
                    default:
                        AddLog(Loc.F("Str_Log_UnknownCmdFmt", cmd));
                        return;
                }
                // 复用与"硬件直连模式"完全一致的处理路径
                ProcessTimingDataFromHardware(td);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_CmdHandleFailedFmt", cmd, ex.Message));
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 硬件计时控制器参数下发（按参考程序 C:\2024年11月2日PM SWIM串口通讯程序Server）
        //
        // 之前用的"0x42 + 子码"逐项发送方式硬件并不识别（用户实测无效）。改为
        // 与参考程序完全一致的命令编号 + 单帧打包格式：
        //
        // 0x41 Set_ArmDelay_Time — 触板/盲表/出发台 各项延迟全部装一帧（位置 3..10 全用）
        //   d3  ArmDelayNormalTime       触板正常关闭时间(s)        ← LaneCloseTime
        //   d4  ArmDelayAfterStartTime   触板抢跳后关闭时间(s)      ← LaneCloseTime（暂复用同值）
        //   d5  MBDelayTime              盲表等待时间(s)            ← 50（参考默认值）
        //   d6  Result_Display_Time      成绩显示时间(s)            ← SplitDisplayTime
        //   d7  StartboxEdgeBit          出发信号边沿(0=下降,1=上升) ← 0
        //   d8  LaneDir<<4 | SP50M<<1 | FinalPlace                  ← 道次方向 + 50米单程位 + 终点端(硬件称 FinalPlace, 0=左/1=右)
        //   注意 d8 bit 0 语义是"终点位置"而非"起点位置"(2026-05-26 修复)
        //   硬件 swimplay.c line 1081 注释明确: FinalPlace=0 终点在左, =1 终点在右
        //   sp50m=0 时 StartPosition==FinishPosition, 两种发法逐位相同, 100m+ 比赛行为不变
        //   d9  TPDelayTime              触板延迟(s)                ← ResultConfirmCloseDelay
        //   d10 SBDelayTime              出发台延迟(s)              ← StartBlockCloseDelay
        //
        // 0x44 Set_PoolConfiguration_Com1 — 泳池参数
        //   d3 泳道数 (8-10)   d4 泳池长度 (25/50)
        //
        // 0x45 Set_MB_Num — 盲表数量
        //   d3 左端 (1-3)      d4 右端 (1-3)
        //
        // 接收侧仍兼容老的 0x40 / 0x42（如果硬件继续上报这些）。
        // ═══════════════════════════════════════════════════════════════
        private bool _applyingHardwareSettings = false;

        private void SendTimingSettingsToHardware() {
            if (_applyingHardwareSettings) return;                // 来自硬件的回环，不要再发
            if (_timingBridge == null || !_timingBridge.IsConnected) return;
            try {
                // ── 0x41 Set_ArmDelay_Time（一帧 8 个数据字节）──
                byte armNorm   = ByteClamp(_laneCloseSettings.LaneCloseTime);
                byte armAfter  = ByteClamp(_laneCloseSettings.LaneCloseTime);
                //2026-05-18 盲表代替成绩延迟时间统一为整秒(与 d3/d4/d6/d9/d10 一致)；硬件 case 端 ×10 转 0.1s 单位
                byte mbDelay   = ByteClamp((int)Math.Round(_laneCloseSettings.BlindReplaceDelay));
                byte resultDsp = ByteClamp(_laneCloseSettings.SplitDisplayTime);
                // 2026-06-03 出发信号边沿: 硬件定义 1=下降沿 / 0=上升沿 (= swimplay.c L37 StartBox_Edge_Bit), PC 从 setting 读
                byte edgeBit   = _laneCloseSettings.StartBoxEdgeFalling ? (byte)1 : (byte)0;
                byte laneDir   = (byte)(_laneCloseSettings.LaneOrder == "reverse" ? 1 : 0);
                //2026-05-26 修复: d8 bit 0 硬件端语义是 FinalPlace(终点位置) 而非 StartPlace(起点位置)
                //  之前发 StartPosition, 50m 单程比赛 (sp50m=1, Start≠Finish) 时出发台开错端
                //  100m+ 双程 (sp50m=0, Start==Finish) 时两种算法值相同, 行为不退化
                byte finalPl   = (byte)(_laneCloseSettings.FinishPosition == "right" ? 1 : 0);
                byte sp50m     = (byte)(_laneCloseSettings.StartPosition != _laneCloseSettings.FinishPosition ? 1 : 0);
                byte placeDir  = (byte)(((laneDir & 0x01) << 4) | ((sp50m & 0x01) << 1) | (finalPl & 0x01));
                byte tpDelay   = ByteClamp(_laneCloseSettings.ResultConfirmCloseDelay);
                byte sbDelay   = ByteClamp(_laneCloseSettings.StartBlockCloseDelay);
                _timingBridge.SendFullFrame(0x41, armNorm, armAfter, mbDelay, resultDsp, edgeBit, placeDir, tpDelay, sbDelay);
                _timingBridge.DelayBetweenFrames(50);

                // ── 0x44 Set_PoolConfiguration_Com1 ──
                byte lanes  = (byte)Math.Max(0, Math.Min(255, _poolConfig.LaneCount));
                byte length = (byte)Math.Max(0, Math.Min(255, _poolConfig.Length));
                _timingBridge.SendFullFrame(0x44, lanes, length);
                _timingBridge.DelayBetweenFrames(50);

                // ── 0x45 Set_MB_Num ──
                int lc = _laneCloseSettings.LeftBlindWatchCount, rc = _laneCloseSettings.RightBlindWatchCount;
                if (lc < 0) lc = 0; if (lc > 3) lc = 3;
                if (rc < 0) rc = 0; if (rc > 3) rc = 3;
                _timingBridge.SendFullFrame(0x45, (byte)lc, (byte)rc);
                _timingBridge.DelayBetweenFrames(50);

                AddLog(Loc.F("Str_Log_HwParamsSyncedFmt",
                    _poolConfig.Length, _poolConfig.LaneCount,
                    _laneCloseSettings.LaneCloseTime, _laneCloseSettings.StartBlockCloseDelay,
                    _laneCloseSettings.ResultConfirmCloseDelay, _laneCloseSettings.SplitDisplayTime,
                    _laneCloseSettings.FinishPosition == "left" ? "左端" : "右端",
                    _laneCloseSettings.LaneOrder == "reverse" ? "逆序9→0" : "正序0→9",
                    lc, rc));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ParamsSendHwFailedFmt", ex.Message));
            }
        }

        // 仅同步盲表数量到硬件（避免重发整组参数）— 0x45 Set_MB_Num: D3=左端 D4=右端
        private void SendBlindWatchCountToHardware() {
            if (_applyingHardwareSettings) return;
            if (_timingBridge == null || !_timingBridge.IsConnected) return;
            try {
                int lc = _laneCloseSettings.LeftBlindWatchCount, rc = _laneCloseSettings.RightBlindWatchCount;
                if (lc < 0) lc = 0; if (lc > 3) lc = 3;
                if (rc < 0) rc = 0; if (rc > 3) rc = 3;
                _timingBridge.SendFullFrame(0x45, (byte)lc, (byte)rc);
                AddLog(Loc.F("Str_Log_BwCountSyncedFmt", lc, rc));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_BwCountSendFailedFmt", ex.Message));
            }
        }

        private static byte ByteClamp(double v) {
            int n = (int)Math.Round(v);
            if (n < 0) n = 0;
            if (n > 255) n = 255;
            return (byte)n;
        }

        // 设备损坏位图编码（2023-11-13 协议扩展：0x42 D3=0x10 子码）
        //   D4 = 泳道号（0-9）
        //   D5 = 左端损坏位图   D6 = 右端损坏位图
        //   bit0=触板  bit1=盲表1  bit2=盲表2  bit3=盲表3  bit4=出发台   （1=损坏）
        private const byte DEVSTAT_SUBCODE = 0x10;

        // 比赛距离子码（2023-11-13 协议扩展：0x42 D3=0x20）
        //   D4 = 趟数 (totalLaps, 1-255)
        //   D5 = 左端触板总次数       D6 = 右端触板总次数
        //   D7 = 距离高字节 (米/256)  D8 = 距离低字节 (米%256)
        //   发送时机：当前项目变更（SetCurrentEvent / SetCurrentHeat）、硬件刚连上
        private const byte RACEDIST_SUBCODE = 0x20;

        // 计算某项目当前出发方向下的左/右触板总次数
        private void GetRaceTouchTotals(int totalLaps, out int leftTotal, out int rightTotal) {
            int startSideTotal, farSideTotal;
            if (totalLaps <= 1) { startSideTotal = 0; farSideTotal = 1; }
            else { startSideTotal = totalLaps / 2; farSideTotal = (totalLaps + 1) / 2; }
            bool startFromLeft = _laneCloseSettings.StartPosition != "right";
            if (startFromLeft) { leftTotal = startSideTotal; rightTotal = farSideTotal; }
            else               { leftTotal = farSideTotal;   rightTotal = startSideTotal; }
        }

        private int GetRaceDistanceMeters() {
            string ev = _currentEvent ?? "";
            if (ev.Contains("x") || ev.Contains("×")) {
                var m = System.Text.RegularExpressions.Regex.Match(ev, @"(\d+)\s*[x×]\s*(\d+)");
                if (m.Success) return int.Parse(m.Groups[1].Value) * int.Parse(m.Groups[2].Value);
            }
            var d = System.Text.RegularExpressions.Regex.Match(ev, @"(\d+)米");
            if (d.Success) return int.Parse(d.Groups[1].Value);
            return 0;
        }

        // 0x10 0x42 [position]：Set_SwStartingPosition — 告诉硬件发令点（左/右）。
        // 参考 C:\2024年11月2日PM SWIM串口通讯程序Server\OnBnClickedSetSwStartingPositionButton：
        //   TCPIP_SendCommand(TCPIP_Con_command=0x10, Set_SwStartingPosition=0x42, StartingPosition, 0, ...)
        //   → 帧 F1 53 [0x10] [0x42] [pos] 00 00 00 00 00 00 F4
        // 这与我们 SendTimingSettingsToHardware 里的 0x42 0x07 (FinishPosition) 是不同的命令体系。
        private void SendStartPositionToHardware() {
            if (_applyingHardwareSettings) return;
            if (_timingBridge == null || !_timingBridge.IsConnected) return;
            try {
                byte pos = _laneCloseSettings.StartPosition == "right" ? (byte)1 : (byte)0;
                _timingBridge.SendCommand(0x10, 0x42, pos);
                _timingBridge.DelayBetweenFrames(20);
                AddLog(Loc.F("Str_Log_StartPosSentFmt", pos == 1 ? Loc.T("Str_Frag_RightEnd") : Loc.T("Str_Frag_LeftEnd")));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_StartPosSendFailedFmt", ex.Message));
            }
        }

        // 2026-05-18 把 PC 内部的"实际道次号"转换为硬件期望的"屏幕位置索引"。
        // 背景：硬件 cmdLbtn[i] / CloseLanebtn[i] 按屏幕第 i 行创建（坐标依 i 算），
        //       但 PC 内部 swimmer.Lane / _laneDeviceStates.Lane 是"实际道次号 0..9"。
        //       正序模式两者一致；逆序模式屏幕位置 = 9 - 实际道次，需转换。
        //       所有单道命令的 D3 在发送前都过这个函数，0x43 位图也按屏幕位置编码。
        private int LaneToHwIndex(int lane) {
            if (lane < 0 || lane > 9) return lane;
            if (_laneCloseSettings != null && _laneCloseSettings.LaneOrder == "reverse")
                return 9 - lane;
            return lane;
        }

        // 0x43 Set_MatchEvent: 告诉硬件本场比赛的总圈数 + 左右两侧期望触板次数 + 泳道开关位图。
        // 参考程序（C:\2024年11月2日PM SWIM串口通讯程序Server）每次按"准备就绪"前必发此帧；
        // 否则硬件不知道比赛结构，后续 0x21 / 0x1C 都不会进入 Ready / 开始计时。
        //
        // 帧布局：F1 53 43 [D3=All_Lap] [D4=RightExpected] [D5=LeftExpected] [D6=LaneOpen0_4] [D7=LaneOpen5_9] 0 0 0 F4
        //
        // 泳道开关位图（修正后协议含义，2026-05-08）：
        //   bit i = 1 → 第 i 道【有运动员 / 打开】
        //   bit i = 0 → 第 i 道【空道 / 关闭】
        //   位 0..4 装在 D6，位 5..9 装在 D7（D7 的 bit 0 对应第 5 道，依此类推）
        // 早期实现按"空道=1"反向编码，导致硬件实际开关与软件意图相反，已修正。
        private void SendSetMatchEventToHardware() {
            if (_applyingHardwareSettings) return;
            if (_timingBridge == null || !_timingBridge.IsConnected) return;
            if (string.IsNullOrEmpty(_currentEvent)) return;
            try {
                int totalLaps = GetTotalLaps();
                int leftTotal, rightTotal;
                GetRaceTouchTotals(totalLaps, out leftTotal, out rightTotal);
                // 泳道开关位图：本组有运动员的泳道置 1，空道置 0
                //2026-05-18 位图按"硬件屏幕位置"编码（不是按实际道次号）
                //   硬件 CloseLanebtn[i] / cmdLbtn[i] 是屏幕第 i 行，逆序模式下屏幕第 i 行显示道次 9-i
                //   所以"屏幕位置 i 是否占用"= "道次 LaneToHwIndex^-1(i) 是否占用"，但 9-(9-x)=x，
                //   函数自身是反函数，直接用 LaneToHwIndex 即可。
                var swimmers = GetCurrentHeatSwimmers();
                var occupiedPositions = new HashSet<int>();
                foreach (var sw in swimmers) {
                    var sa = sw.GetAssignmentForStage(_currentStage);
                    int ln = sa != null ? sa.Lane : sw.Lane;
                    if (ln >= 0 && ln <= 9) occupiedPositions.Add(LaneToHwIndex(ln));
                }
                byte laneOpen0_4 = 0, laneOpen5_9 = 0;
                for (int i = 0; i <= 4; i++) {
                    if (occupiedPositions.Contains(i)) laneOpen0_4 |= (byte)(1 << i);
                }
                for (int i = 5; i <= 9; i++) {
                    if (occupiedPositions.Contains(i)) laneOpen5_9 |= (byte)(1 << (i - 5));
                }
                // 2026-05-13 D8 = IsRelay 标志：硬件据此判断是否为每棒测接力反应时
                byte isRelayByte = (byte)(_isRelay ? 1 : 0);
                // 2026-06-02 D9 = HardwareAlwaysOpen 标志: 硬件 TP/SB/MB 按键路径"一直处于打开状态"模式 (=1: 忽略关闭判定, 只跳过 ==3 坏 / ==4 未装; =0: 原比赛流程)
                byte hwAlwaysOpenByte = (byte)(_laneCloseSettings.HardwareAlwaysOpen ? 1 : 0);
                // 2026-06-14 D10 = Backstroke 标志: 仰泳项目时硬件 EventBackup 把 TP 松开也存 (用于算反应时, 因为仰泳运动员踩 TP 等发令, 松开 TP 是出发瞬间)
                // 2026-06-26 扩展: 包括混合泳接力第 1 棒. 详见 IsBackstrokeStartEvent helper.
                bool isBackstroke = IsBackstrokeStartEvent(_currentEvent);
                byte backstrokeByte = (byte)(isBackstroke ? 1 : 0);
                _timingBridge.SendFullFrame(0x43,
                    (byte)Math.Min(255, totalLaps),
                    (byte)Math.Min(255, rightTotal),
                    (byte)Math.Min(255, leftTotal),
                    laneOpen0_4, laneOpen5_9, isRelayByte, hwAlwaysOpenByte, backstrokeByte);
                _timingBridge.DelayBetweenFrames(20);     // 给硬件处理本帧的时间，防止下一条命令被吞
                AddLog(Loc.F("Str_Log_SetMatchEventSentFmt",
                    totalLaps, rightTotal, leftTotal, laneOpen0_4, laneOpen5_9, _isRelay ? "是" : "否", _laneCloseSettings.HardwareAlwaysOpen ? "是" : "否", isBackstroke ? "是" : "否"));

                // 2026-06-15 跟 0x43 一起发 0x46 Set_StrokeType: 硬件 UI 第 2 行 +1 键左侧显示泳姿名称
                byte strokeTypeByte = GetStrokeTypeFromEventName(_currentEvent);
                _timingBridge.SendSetStrokeType(strokeTypeByte);
                _timingBridge.DelayBetweenFrames(20);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_SetMatchEventFailedFmt", ex.Message));
            }
        }

        // 2026-06-26 判断项目"出发方式是否仰泳" (= 跟 register 仰泳反应时算法保持一致):
        //   纯仰泳 (50/100/200m): 全程仰泳出发
        //   混合泳接力 (4×50/4×100m): 第 1 棒仰泳出发
        //   个人混合泳 (200/400m): 第 1 棒蝶泳, 不算
        private bool IsBackstrokeStartEvent(string eventName) {
            return !string.IsNullOrEmpty(eventName) &&
                   (eventName.Contains("仰泳") || eventName.Contains("混合泳接力"));
        }

        // 2026-06-15 把项目名映射到硬件 StrokeType 编码 (0=自由 1=蝶 2=蛙 3=仰 4=混合 5=空白/未知)
        // 注意顺序: "混合泳"必须在"蝶/蛙/仰/自由"之前判断, 否则混合接力会被误判.
        private byte GetStrokeTypeFromEventName(string eventName) {
            if (string.IsNullOrEmpty(eventName)) return 5;
            if (eventName.Contains("混合")) return 4;   // 混合泳 / 混合接力
            if (eventName.Contains("仰泳")) return 3;
            if (eventName.Contains("蛙泳")) return 2;
            if (eventName.Contains("蝶泳")) return 1;
            if (eventName.Contains("自由泳")) return 0;
            return 5;   // 未知项目 → 硬件显示空白
        }

        private void SendRaceDistanceToHardware() {
            if (_applyingHardwareSettings) return;
            if (_timingBridge == null || !_timingBridge.IsConnected) return;
            if (string.IsNullOrEmpty(_currentEvent)) return;
            try {
                int totalLaps = GetTotalLaps();
                int distance = GetRaceDistanceMeters();
                int leftTotal, rightTotal;
                GetRaceTouchTotals(totalLaps, out leftTotal, out rightTotal);
                byte distHi = (byte)((distance >> 8) & 0xFF);
                byte distLo = (byte)(distance & 0xFF);
                _timingBridge.SendFullFrame(0x42, RACEDIST_SUBCODE,
                    (byte)Math.Min(255, totalLaps),
                    (byte)Math.Min(255, leftTotal),
                    (byte)Math.Min(255, rightTotal),
                    distHi, distLo);
                AddLog(Loc.F("Str_Log_DistanceSyncedFmt",
                    _currentEvent, distance, totalLaps, leftTotal, rightTotal));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_DistanceSendFailedFmt", ex.Message));
            }
        }

        private static byte EncodeBrokenMask(bool touchpad, bool bw1, bool bw2, bool bw3, bool startBlock) {
            byte v = 0;
            if (touchpad) v |= 0x01;
            if (bw1) v |= 0x02;
            if (bw2) v |= 0x04;
            if (bw3) v |= 0x08;
            if (startBlock) v |= 0x10;
            return v;
        }

        // 0x46 Set_TPSBMB_State — 与参考程序 BadTP_SB_MBProg 同格式：触板/出发台/盲表(1) 启用状态
        // 一帧打包发送全部 20 个泳道(左 0-9 + 右 0-9)的启用位（1=启用，0=未用/损坏）。
        // 帧布局：F1 53 46 [TP_lo] [TP_mid] [TP_hi] [SB_lo] [SB_hi] [MB_lo] [MB_hi] [SB_MB_top] F4
        //   TP/SB/MB 三段位流均为 20 位；State[7] 高 4 位=SB[16..19]，低 4 位=MB[16..19]
        //   位序与参考一致：bit i = lane (i<10 ? 左i : 右(i-10))
        //
        // 参考硬件每端每道只有 1 个盲表槽 → 0x46 的 MB 段对应我们的"盲表 1"。
        // 我们另有盲表 2 / 盲表 3，硬件目前没有对应槽位 —— 用扩展命令 0x49 / 0x4A 单独发出
        // （沿用 SB/MB 同样的 3 字节 × 20 位编排），等硬件计时器固件升级后即可识别。
        private void SendDeviceStatusesToHardware() {
            if (_applyingHardwareSettings) return;
            if (_timingBridge == null || !_timingBridge.IsConnected) return;
            try {
                int tpVal = 0, sbVal = 0, mb1Val = 0, mb2Val = 0, mb3Val = 0;
                foreach (var st in _laneDeviceStates) {
                    int ln = st.Lane;
                    if (ln < 0 || ln > 9) continue;
                    int leftBit = 1 << ln;
                    int rightBit = 1 << (ln + 10);
                    // 2026-05-13 触板 / 出发台未安装也视为"硬件无此设备"，位图必须为 0，
                    // 否则单端模式下硬件仍以为右端触板存在，会持续期待信号。
                    bool leftTpInstalled = (st.LeftTouchpadStatus != DeviceStatus.NotInstalled);
                    bool rightTpInstalled = (st.RightTouchpadStatus != DeviceStatus.NotInstalled);
                    bool leftSbInstalled = (st.LeftStartBlockStatus != DeviceStatus.NotInstalled);
                    bool rightSbInstalled = (st.RightStartBlockStatus != DeviceStatus.NotInstalled);
                    if (!st.LeftTouchpadBroken  && leftTpInstalled)  tpVal |= leftBit;
                    if (!st.RightTouchpadBroken && rightTpInstalled) tpVal |= rightBit;
                    if (!st.LeftStartBlockBroken  && leftSbInstalled)  sbVal |= leftBit;
                    if (!st.RightStartBlockBroken && rightSbInstalled) sbVal |= rightBit;
                    // 盲表 1 — 对应硬件 0x46 MB 槽
                    if (!st.LeftBlindWatch1Broken && !st.LeftBlindWatch1NotInstalled)   mb1Val |= leftBit;
                    if (!st.RightBlindWatch1Broken && !st.RightBlindWatch1NotInstalled) mb1Val |= rightBit;
                    // 盲表 2 / 盲表 3 — 用扩展帧 0x49 / 0x4A 发出（硬件待升级）
                    if (!st.LeftBlindWatch2Broken && !st.LeftBlindWatch2NotInstalled)   mb2Val |= leftBit;
                    if (!st.RightBlindWatch2Broken && !st.RightBlindWatch2NotInstalled) mb2Val |= rightBit;
                    if (!st.LeftBlindWatch3Broken && !st.LeftBlindWatch3NotInstalled)   mb3Val |= leftBit;
                    if (!st.RightBlindWatch3Broken && !st.RightBlindWatch3NotInstalled) mb3Val |= rightBit;
                }

                // ── 0x46 Set_TPSBMB_State (TP + SB + MB1) ──
                byte s0 = (byte)(tpVal & 0xFF);
                byte s1 = (byte)((tpVal >> 8) & 0xFF);
                byte s2 = (byte)((tpVal >> 16) & 0x0F);
                byte s3 = (byte)(sbVal & 0xFF);
                byte s4 = (byte)((sbVal >> 8) & 0xFF);
                byte s5 = (byte)(mb1Val & 0xFF);
                byte s6 = (byte)((mb1Val >> 8) & 0xFF);
                byte s7 = (byte)((((sbVal >> 16) & 0x0F) << 4) | ((mb1Val >> 16) & 0x0F));
                _timingBridge.SendFullFrame(0x46, s0, s1, s2, s3, s4, s5, s6, s7);
                _timingBridge.DelayBetweenFrames(50);

                // 2026-05-13(2) 关键 BUG 修复：原 0x49 / 0x4A "盲表 2/3 扩展位图"与硬件
                // dispatcher 的 D2-0x10 映射冲突 ——
                //   wire 0x49 → 0x39 = Set_DateTime（被当成日期帧解析，年份越界丢弃）
                //   wire 0x4A → 0x3A = Set_PoolSingleOrDoubleTP（D3≠0 时切到单端模式）
                // 同步设备状态时大概率把硬件误切到"单端"→ 屏蔽右端全部信号。
                // 在硬件正式分配新命令码（建议 ≥0x60 段）之前，PC 端不能再发这两帧。
                // 盲表 2/3 的"未安装/损坏"软件仍记录在 _laneDeviceStates，等硬件支持后再启用。
                //
                // 历史代码（保留供将来恢复时参考）：
                //   _timingBridge.SendFullFrame(0x49, mb2Val_bytes...);
                //   _timingBridge.SendFullFrame(0x4A, mb3Val_bytes...);

                AddLog(Loc.F("Str_Log_DeviceStateSyncedFmt",
                    tpVal & 0xFFFFF, sbVal & 0xFFFFF, mb1Val & 0xFFFFF));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_DeviceStateSendFailedFmt", ex.Message));
            }
        }

        private void ApplyDeviceStatusFromHardware(TimingData data) {
            int lane = data.RawD4;
            byte left = data.Param5;
            byte right = data.Param6;
            var st = _laneDeviceStates.FirstOrDefault(x => x.Lane == lane);
            if (st == null) return;
            bool changed = false;
            Action<Func<bool>, Action<bool>, bool> maybeSet = (getter, setter, target) => {
                if (getter() != target) { setter(target); changed = true; }
            };
            maybeSet(() => st.LeftTouchpadBroken,   b => st.LeftTouchpadBroken = b,   (left & 0x01) != 0);
            maybeSet(() => st.LeftBlindWatch1Broken, b => st.LeftBlindWatch1Broken = b, (left & 0x02) != 0);
            maybeSet(() => st.LeftBlindWatch2Broken, b => st.LeftBlindWatch2Broken = b, (left & 0x04) != 0);
            maybeSet(() => st.LeftBlindWatch3Broken, b => st.LeftBlindWatch3Broken = b, (left & 0x08) != 0);
            maybeSet(() => st.LeftStartBlockBroken,  b => st.LeftStartBlockBroken = b, (left & 0x10) != 0);
            maybeSet(() => st.RightTouchpadBroken,   b => st.RightTouchpadBroken = b,   (right & 0x01) != 0);
            maybeSet(() => st.RightBlindWatch1Broken, b => st.RightBlindWatch1Broken = b, (right & 0x02) != 0);
            maybeSet(() => st.RightBlindWatch2Broken, b => st.RightBlindWatch2Broken = b, (right & 0x04) != 0);
            maybeSet(() => st.RightBlindWatch3Broken, b => st.RightBlindWatch3Broken = b, (right & 0x08) != 0);
            maybeSet(() => st.RightStartBlockBroken,  b => st.RightStartBlockBroken = b, (right & 0x10) != 0);
            if (changed) {
                AddLog(Loc.F("Str_Log_HwDeviceStateReportFmt", lane, left, right));
                // 2026-09-13 这里原来调的是 AutoSaveData() —— 两处不对:
                //   一是【坏表标志根本不存在赛事包里】(它存 device_states.json), 为一个
                //     布尔位去序列化整个 1.2MB 的包, 纯属白干, 比赛中更是那条老毛病;
                //   二是它【不推设备状态】, 而比赛日志/设备状态现在是按变化推的 ——
                //     结果就是"硬件报了故障, 比赛控制页面上那盏灯不亮", 而且看不出根由。
                //   SaveDeviceStates() 两件事一起办: 写那个几 KB 的 json, 并立刻推给客户端。
                SaveDeviceStates();
                UpdateLaneStatusDisplay();
                Broadcast();
            }
        }

        private void ApplyHardwareSettingFrame(TimingData data) {
            _applyingHardwareSettings = true;
            try {
                bool changed = false;
                switch (data.CommandType) {
                    case TimingCommandType.PoolConfig: {
                        int lanes = data.Param1;
                        int length = data.RawD4;
                        if (lanes >= 6 && lanes <= 10 && _poolConfig.LaneCount != lanes) {
                            _poolConfig.SetLaneCount(lanes);
                            if (LaneCountCombo != null) LaneCountCombo.SelectedIndex = lanes == 8 ? 1 : (lanes == 6 ? 2 : 0);
                            InitLaneDeviceStates();
                            ApplyPersistedDeviceStates();   // 重建后还原持久化的设备状态
                            changed = true;
                        }
                        if ((length == 25 || length == 50) && _poolConfig.Length != length) {
                            _poolConfig.Length = length;
                            if (PoolLengthCombo != null) PoolLengthCombo.SelectedIndex = length == 25 ? 1 : 0;
                            changed = true;
                        }
                        if (changed) AddLog(Loc.F("Str_Log_HwPoolParamsReportFmt", _poolConfig.Length, _poolConfig.LaneCount));
                        break;
                    }
                    case TimingCommandType.SetCommand: {
                        // 子码 0x10：设备状态帧（D4=泳道 D5=左位图 D6=右位图）
                        if (data.Param1 == DEVSTAT_SUBCODE) {
                            ApplyDeviceStatusFromHardware(data);
                            break;
                        }
                        // 子码 0x20：比赛距离回报（仅日志；比赛项目由主服务器决定，硬件下发不更改项目）
                        if (data.Param1 == RACEDIST_SUBCODE) {
                            int laps = data.RawD4;          // D4
                            int leftN = data.Param5;        // D5
                            int rightN = data.Param6;       // D6
                            int dist = (data.Param7 << 8) | data.Param8;   // D7:D8
                            AddLog(Loc.F("Str_Log_HwDistanceReportFmt",
                                dist, laps, leftN, rightN));
                            break;
                        }
                        double vOld, vNew;
                        switch (data.Param1) {
                            case 0x01: vOld = _laneCloseSettings.LaneCloseTime;           vNew = data.RawD4;           if (Math.Abs(vOld - vNew) > 0.001) { _laneCloseSettings.LaneCloseTime = vNew; changed = true; } break;
                            case 0x02: vOld = _laneCloseSettings.StartBlockCloseDelay;    vNew = data.RawD4 / 10.0;    if (Math.Abs(vOld - vNew) > 0.001) { _laneCloseSettings.StartBlockCloseDelay = vNew; changed = true; } break;
                            case 0x03: vOld = _laneCloseSettings.ResultConfirmCloseDelay; vNew = data.RawD4 / 10.0;    if (Math.Abs(vOld - vNew) > 0.001) { _laneCloseSettings.ResultConfirmCloseDelay = vNew; changed = true; } break;
                            case 0x04: vOld = _laneCloseSettings.FalseStartThreshold;     vNew = data.RawD4 / 100.0;   if (Math.Abs(vOld - vNew) > 0.0001) { _laneCloseSettings.FalseStartThreshold = vNew; changed = true; } break;
                            case 0x05: vOld = _laneCloseSettings.SplitDisplayTime;        vNew = data.RawD4;           if (Math.Abs(vOld - vNew) > 0.001) { _laneCloseSettings.SplitDisplayTime = vNew; changed = true; } break;
                            //2026-05-13 子码 0x09：盲表代替成绩延迟时间（0.1秒单位）
                            case 0x09: vOld = _laneCloseSettings.BlindReplaceDelay;       vNew = data.RawD4;            if (Math.Abs(vOld - vNew) > 0.001) { _laneCloseSettings.BlindReplaceDelay = vNew; changed = true; } break; //2026-05-18 改为整秒，与 d3/d4/d6/d9/d10 一致
                            case 0x06: vOld = _laneCloseSettings.FirstPlaceHoldTime;      vNew = data.RawD4;           if (Math.Abs(vOld - vNew) > 0.001) { _laneCloseSettings.FirstPlaceHoldTime = vNew; changed = true; } break;
                            case 0x07: {
                                string newFin = data.RawD4 == 0 ? "left" : "right";
                                if (_laneCloseSettings.FinishPosition != newFin) {
                                    _laneCloseSettings.FinishPosition = newFin;
                                    _laneCloseSettings.StartPosition = newFin;
                                    AutoAdjustStartPosition();
                                    if (_raceState == RaceState.Waiting || _raceState == RaceState.Ready) {
                                        bool isBack2 = IsBackstrokeStartEvent(_currentEvent);
                                        foreach (var st in _laneDeviceStates) st.ResetForNewRace(_laneCloseSettings.StartPosition, isBack2);
                                    }
                                    changed = true;
                                }
                                break;
                            }
                            case 0x08: {
                                // 盲表数量（D4 高 4 位=左 0-3，低 4 位=右 0-3）
                                int newLeft = (data.RawD4 >> 4) & 0x0F;
                                int newRight = data.RawD4 & 0x0F;
                                if (newLeft >= 0 && newLeft <= 3 && newRight >= 0 && newRight <= 3) {
                                    if (_laneCloseSettings.LeftBlindWatchCount != newLeft) {
                                        _laneCloseSettings.LeftBlindWatchCount = newLeft; changed = true;
                                    }
                                    if (_laneCloseSettings.RightBlindWatchCount != newRight) {
                                        _laneCloseSettings.RightBlindWatchCount = newRight; changed = true;
                                    }
                                    if (changed) AddLog(Loc.F("Str_Log_HwBwCountReportFmt", newLeft, newRight));
                                } else {
                                    AddLog(Loc.F("Str_Log_HwBwCountInvalidFmt", data.RawD4));
                                }
                                break;
                            }
                            default:
                                AddLog(Loc.F("Str_Log_HwParamUnknownSubcodeFmt", data.Param1, data.RawD4));
                                break;
                        }
                        if (changed) AddLog(Loc.F("Str_Log_HwParamReportFmt", data.Param1, data.RawD4));
                        break;
                    }
                    case TimingCommandType.RaceConfig:
                        // 0x41 比赛距离+空道位图，当前仅记录日志，由操作员自行确认
                        AddLog(Loc.F("Str_Log_HwRaceParamsFmt",
                            data.RawD4, data.Param6, data.Param7));
                        break;
                }

                if (changed) {
                    SaveTimingSettings();
                    // 2026-09-20 同 HandleTimingCommand 的参数更新分支: 硬件回报的这几个
                    //   计时参数(盲表数量等)是本机硬件状态, 编排端用不上, 不必为它推整包。
                    SaveWithoutPush();
                    UpdateLaneStatusDisplay();
                    UpdateRaceStateDisplay();
                    Broadcast();   // 同步到 EXE/Web 三端
                }
            } finally {
                _applyingHardwareSettings = false;
            }
        }

        //2026-05-31 isMbSubstitute: 硬件用盲表成绩代替触板成绩 (= cmd=0x16 d3=Pushbutton_Result=1) 时强制接受, 跳过 TP 状态守卫
        private void ProcessTimingData(int lane, string cmdType, double timeInSeconds, string side = null, bool isFalseStart = false, bool isMbSubstitute = false) {
            // 硬件 0x7F 滚动时间：硬件计时器是【唯一】权威时间源。
            // 软件不再用本地 DateTime 自算时间，也不按 race state 过滤：收到什么显示什么。
            // 这样硬件清零后只要它发 0x7F=0，软件立刻同步；硬件继续走时则软件也跟着；
            // 唯一保留 0 的场景是从未连接到硬件 / 硬件未发任何 0x7F。
            if (cmdType == "RunningTime") {
                // 2026-05-25 移除 1.5 秒抑制窗口 (原修复 #6):
                //   硬件 PDF 必修 #2 修复完成 - case Timer_Reset_Command 入口立即清 timer_bit
                //   并发 0x7F=0, 不会再有 1-2 秒残余非零 0x7F。PC 端可直接信任硬件 0x7F 值。
                _hwRunningTimeSec = timeInSeconds;
                _hwRunningTimeReceivedAt = DateTime.Now;
                _hwRunningTimeAvailable = true;
                _runningTime = timeInSeconds;
                // 2026-05-26 移除此处对 RunningTimeText.Text 的直接覆盖: 它每 100ms 触发,
                //   会无视"1 名成绩停留显示"窗口直接抹掉 _firstPlaceFinishTime, 表现为用户报告的
                //   "停留时间被冲掉/每次触板都闪一下"。统一由 RaceTimer_Tick (同样 100ms 节拍)
                //   按 _firstPlaceShowStart + FirstPlaceHoldTime 窗口决定显示 leader 成绩还是 _runningTime.
                // 立刻把硬件时间转发给大屏 / EXE / HTML 计时控制台 — 硬件 100ms 节拍
                BroadcastRunningTime();
                return;
            }
            // 硬件触发的比赛控制命令：直接联动到本地状态机；不做去抖（信任硬件按键发出的是干净的单条命令）
            switch (cmdType) {
                case "TimerReady":
                    AddLog(Loc.T("Str_Log_HwTriggerReady"));
                    Ready_Click(null, null);
                    return;
                case "StartCommand":
                    AddLog(Loc.T("Str_Log_HwTriggerStart"));
                    if (_raceState == RaceState.Waiting) Ready_Click(null, null);
                    StartRace_Click(null, null);
                    return;
                case "GunPreStart":
                    // 2026-06-14 PreStart 重设计: 固件发令瞬间广播枪响时刻 PreStart 计数器值
                    //   = 个人/接力第1棒反应时的减数. 暂存到 _gunPreStartSec, 抢跳 TP/SB 等待此值后回算反应时.
                    _gunPreStartSec = timeInSeconds;
                    _gunArrivedAt   = DateTime.Now;   // 2026-06-23 仰泳窗口起算基准 (= 本地时刻)
                    AddLog(Loc.F("Str_Log_HwTriggerGunFmt", timeInSeconds));
                    FlushPendingPreStartReactions();
                    StartBackstrokeWindowsAfterGun();   // 2026-06-23 启动 gun 前已暂存的仰泳窗口 timer
                    StartDirectStartSbWindowsAfterGun();   // 2026-07-13 启动 gun 前已暂存的直通正常出发 SB 窗口 timer
                    // 2026-07-13 v8-rev6: 出发段直接照搬主路径立即算 rt = SB - gun, 不再对 lane 启 v8 timer.
                    return;
                case "TimerReset":
                    AddLog(Loc.T("Str_Log_HwTriggerReset"));
                    // 2026-06-14 新一场比赛: 清掉枪响 PreStart 锚点和待算反应时缓存
                    _gunPreStartSec = null;
                    _pendingPreStartReactions.Clear();
                    ClearBackstrokeReleaseWindows();   // 2026-06-23 同步清仰泳出发反应时窗口
                    ClearDirectSbWindows();            // 2026-07-08 同步清直通模式 SB 窗口
                    ClearDirectStartSbWindows();       // 2026-07-13 同步清直通正常出发 SB 窗口
                    Restart_Click(null, null);
                    return;
            }

            // 设备测试模式：硬件来什么数据都接收并显示，跳过"比赛状态/空泳道"过滤；
            // 不计入分段/成绩，但在对应设备点上闪一下红色（Touched），让操作员看到哪个设备触发了。
            if (_testMode) {
                LogRawTimingData(lane, cmdType, timeInSeconds);
                AddLog(Loc.F("Str_Log_TestModeLaneEventFmt",
                    lane, cmdType,
                    string.IsNullOrEmpty(side) ? "" : ("[" + side + "] "),
                    TimeFormatter.Format(timeInSeconds)));
                // 把"最近事件"文字写到对应端的 Remain 文本框，让操作员能看到时间值
                string evtText = string.Format("{0} {1}", TestModeShortName(cmdType), TimeFormatter.Format(timeInSeconds));
                if (side == "right") _testLastEventRight[lane] = evtText;
                else _testLastEventLeft[lane] = evtText;
                FlashDeviceInTestMode(lane, cmdType, side);
                Broadcast();
                return;
            }

            // Racing状态或Finished状态（延迟关闭期内盲表/手动仍有效）都接收数据
            // 2026-06-14 BackstrokeRelease 跟 StartCommand 一样豁免: 仰泳松开可能略早于 PC 切到 Racing (固件 0x16 D3=3 帧紧跟 0x1C 发送, PC 处理顺序不保证), 不应被 Ready 状态丢弃
            if (_raceState != RaceState.Racing && _raceState != RaceState.Finished && cmdType != "StartCommand" && cmdType != "BackstrokeRelease") return;

            // 空泳道或 DNS/DNF：整条泳道关闭，不记录也不处理任何计时数据。
            // 抢跳 DSQ 运动员仍在水中继续比赛，触板/盲表/分段数据应继续接收并保存（仅大屏不显示成绩）。
            if (!IsLaneReceivingData(lane)) {
                AddLog(Loc.F("Str_Log_DataDroppedEmptyLaneFmt", lane, cmdType));
                return;
            }

            // 记录原始数据 (2026-05-31: 硬件用盲表代替触板成绩 → 比赛日志显示"触代")
            // 2026-06-14 cmdType 已经在 TimingBridge.cs 里区分: "Touchpad"=真触板, "ManualTouchpad"=MB 代触. 不需要这里再合成 "TouchpadMb" 字符串.
            // 2026-06-15 仰泳松开 (BackstrokeRelease): timeInSeconds 是 PreStart 计数器绝对值 (= 9.13), 比赛日志显示反应时 = release_PreStart - Gun_PreStart (= 1.37s) 跟硬件 LCD 显示一致
            double timeForLog = (cmdType == "BackstrokeRelease" && _gunPreStartSec.HasValue)
                ? timeInSeconds - _gunPreStartSec.Value
                : timeInSeconds;
            LogRawTimingData(lane, cmdType, timeForLog, side);

            // 2026-06-03 比完赛 (_raceState==Finished) 后, 硬件再有数据只记录 (= 上面 LogRaw 含比赛日志) 不处理
            //   = 不喂 calculator, 不动 SplitTime / 状态机 / 反应时, 不刷 UI 状态
            // 2026-06-17 例外: PushButton1/2/3 (盲表) 完赛后仍要进 ProcessBlindWatchData 存储,
            //   场景: 最后一名 TP 先到 → _raceState 立即变 Finished → MB 后到被 4595 丢掉, 用户在 UI 看不到也存不进 result.
            //   盲表自身仍有 bwStatus(Open/Touched/Closed) ResultConfirmCloseDelay 秒窗口控制, 窗口过期 bwStatus=Closed
            //   走 RecordBackupBlind 备用记录; 状态机副作用安全 (ScheduleMbSubstitute 有 !IsFinished 守卫).
            if (_raceState == RaceState.Finished
                && cmdType != "PushButton1" && cmdType != "PushButton2" && cmdType != "PushButton3") return;

            // 2026-06-03 喂事件到 RelayReactionCalculator (= 接力 SB reaction 14 条规则). 第 1 棒发令不喂 (= 不算接力交接)
            // 守卫: 只对"接力交接段 + 棒次完成侧 TP"喂入. 非交接段 / 非棒完成侧 (= 中点 TP) 都不算 SB reaction
            //   2026-06-03 排除"终点 TP (= 棒 4 完成)" — 终点后无下棒 SB, 不该启动 calculator window
            //   2026-06-03 棒次完成侧 = StartPosition if afterLap 偶 else 另一侧 (= 4×50m perLeg=1 时棒次交替)
            if (_relayReactionCalc != null && _isRelay && !string.IsNullOrEmpty(side)) {
                var lsForHook = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                // 2026-07-13 按侧化: 是否交接段 TP/MB 由按侧锚点决定 (HandoffMode 倒计时=0 设, 免疫 CurrentLap 的 ++ 时序).
                //   该侧处未结算交接窗口 (HandoffMode && !SbReactionRecorded) → 本 TP/MB 即交接基准. 替代原 CurrentLap%perLeg 奇偶反推.
                bool isHandoffTpSeg = false;
                if (lsForHook != null && (side == "left" || side == "right")) {
                    bool hmTp  = (side == "left") ? lsForHook.HandoffModeLeft        : lsForHook.HandoffModeRight;
                    bool recTp = (side == "left") ? lsForHook.SbReactionRecordedLeft : lsForHook.SbReactionRecordedRight;
                    isHandoffTpSeg = hmTp && !recTp;
                }
                if (isHandoffTpSeg) {
                    // 2026-07-13 直通模式 (HardwareAlwaysOpen): PC 用 DirectSbWindow 自算反应时, 不喂旧的 14 规则 _relayReactionCalc.
                    //   否则它只拿到 TP/MB、拿不到 SB (SB 走 HandleStartingBlock_AlwaysOpen 不喂它) → 窗口到期
                    //   OnRelayReactionNone 吐冗余 "出[N]=---*". 仅按比赛流程模式才喂.
                    if (_laneCloseSettings == null || !_laneCloseSettings.HardwareAlwaysOpen) {
                        // 2026-06-14 重构: cmdType 已区分, 真触板 = "Touchpad", MB 代触 = "ManualTouchpad", 不再依赖 isMbSubstitute 内嵌分支
                        if (cmdType == "Touchpad") {
                            _relayReactionCalc.OnEvent(lane, side, RelayReactionCalculator.EventKind.TP, timeInSeconds);
                        } else if (cmdType == "ManualTouchpad") {
                            _relayReactionCalc.OnEvent(lane, side, RelayReactionCalculator.EventKind.MB_Final, timeInSeconds);
                        } else if (cmdType == "PushButton1" || cmdType == "PushButton2" || cmdType == "PushButton3") {
                            _relayReactionCalc.OnEvent(lane, side, RelayReactionCalculator.EventKind.MB_FirstPress, timeInSeconds);
                        }
                    }
                    // 2026-07-13 v8-rev5 用户 3 规则:
                    //   规则 1: 只 Open/Touched/FalseStart 时接收 (Closed/Broken/NotInstalled 拒).
                    //   规则 2: TP 存在就用 TP; MB_Final 只在无 TP 时代替. MB_FirstPress 只启 timer, 不作 basis.
                    //   规则 3: GUN 在 case "GunPreStart" 单独 dispatch (仰泳出发段跳过).
                    if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen && lsForHook != null) {
                        DeviceStatus tpSt = (side == "left") ? lsForHook.LeftTouchpadStatus : lsForHook.RightTouchpadStatus;
                        DeviceStatus bwSt = DeviceStatus.NotInstalled;
                        if (cmdType == "PushButton1") bwSt = (side == "left") ? lsForHook.LeftBlindWatch1Status : lsForHook.RightBlindWatch1Status;
                        else if (cmdType == "PushButton2") bwSt = (side == "left") ? lsForHook.LeftBlindWatch2Status : lsForHook.RightBlindWatch2Status;
                        else if (cmdType == "PushButton3") bwSt = (side == "left") ? lsForHook.LeftBlindWatch3Status : lsForHook.RightBlindWatch3Status;
                        bool tpAccept = tpSt != DeviceStatus.Closed && tpSt != DeviceStatus.Broken && tpSt != DeviceStatus.NotInstalled;
                        bool bwAccept = bwSt != DeviceStatus.Closed && bwSt != DeviceStatus.Broken && bwSt != DeviceStatus.NotInstalled;
                        if (cmdType == "Touchpad" && tpAccept) {
                            RecordDirectSbBasis(lane, side, timeInSeconds, "TP");
                        } else if (cmdType == "ManualTouchpad" && tpAccept) {
                            RecordDirectSbBasis(lane, side, timeInSeconds, "MB_Final");
                        } else if ((cmdType == "PushButton1" || cmdType == "PushButton2" || cmdType == "PushButton3") && bwAccept) {
                            int mbBtn = cmdType == "PushButton1" ? 1 : (cmdType == "PushButton2" ? 2 : 3);
                            RecordDirectSbBasis(lane, side, timeInSeconds, "MB_FirstPress", mbBtn);
                        } else {
                            AddLog(Loc.F("Str_Log_DirectBasisIgnoredFmt",
                                lane, cmdType, side == "left" ? "左" : "右", tpSt, bwSt));
                        }
                    }
                }
                // SB 在 case "StartingBlock" 接力分支内单独喂 (= 因为发令第 1 棒 SB 不喂)
            }

            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;

            switch (cmdType) {
                case "StartCommand":
                    // 发令信号（兼容旧协议）
                    break;

                case "BackstrokeRelease":
                    // 2026-06-23 仰泳出发反应时帧 → 走专用子程序 ProcessBackstrokeReleaseFrame (与正常 case 隔离, 跟固件 TouchPad_BackstrokeStart_Process 对称).
                    ProcessBackstrokeReleaseFrame(lane, side, timeInSeconds, laneState);
                    break;

                case "StartingBlock":
                    // 2026-07-08 直通模式独立子程序 (跟原按比赛流程 case 隔离, 完整移植硬件 SBCloseDelay 屏蔽机制).
                    //   按比赛流程: 硬件推 0x50 SB 状态帧 → PC 更新 shadow state → 用状态守卫过滤.
                    //   直通模式:   硬件不推状态帧, 所有 SB 事件都上报. PC 需自主屏蔽 (= "首次记录, 之后备用").
                    if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen) {
                        HandleStartingBlock_AlwaysOpen(lane, side, timeInSeconds, isFalseStart, laneState);
                        break;
                    }
                    // 出发台状态机（与触板对称）：
                    //   Open / FalseStart → 作为正式反应时处理，再切到 Touched（红）保持 StartBlockCloseDelay 秒
                    //   Touched           → 已记录正式反应时；本次记日志并写入"备用反应时"
                    //   其它              → 仅记日志
                    {
                        // 2026-06-02 协议规约: side 必须由硬件发来, PC 不自判. side 缺失 = 协议错误, 跳过
                        DeviceStatus sbStatus;
                        string sbSideForClose = side;
                        if (side == "left") sbStatus = laneState.LeftStartBlockStatus;
                        else if (side == "right") sbStatus = laneState.RightStartBlockStatus;
                        else {
                            AddLog(Loc.F("Str_Log_SbSideMissingFmt", lane));
                            break;
                        }

                        // 2026-06-20 守卫 A: 出发台未安装 → 直接丢弃, 不计算反应时.
                        //   用户报: 没接出发台硬件, PC 仍算 reactionTime = 0 - GunPreStart = -142s.
                        if (sbStatus == DeviceStatus.NotInstalled) {
                            AddLog(Loc.F("Str_Log_SbNotInstalledFmt", lane));
                            break;
                        }
                        // 2026-06-20 守卫 B: 帧时间字段 ≈ 0 → 硬件没真实信号 (上报空帧 / 通讯污染).
                        //   原代码 reactionTime = 0 - GunPreStart 得到大负值, 误报抢跳. 留给反应时窗口 timer 兜底标 ---.
                        if (Math.Abs(timeInSeconds) < 0.001) {
                            AddLog(Loc.F("Str_Log_SbTimeZeroFmt", lane));
                            break;
                        }

                        bool sbOpen = (sbStatus == DeviceStatus.Open || sbStatus == DeviceStatus.FalseStart);
                        // 2026-05-13 硬件 D10≠0 已确认抢跳：不论出发台软件状态如何（Closed/Touched/Broken），
                        // 都强制走主反应时记录路径。否则当出发台还在 Closed 状态时硬件抢跳数据会被丢弃，
                        // 表现为"测了几十次只显示一次"。
                        if (isFalseStart) sbOpen = true;
                        // 2026-05-13 全开模式：该泳道处于"全开"覆盖时，无视状态机直接记录
                        if (IsLaneForceAllOpen(lane)) sbOpen = true;
                        // 2026-05-13 正常出发反应时也总是记录：
                        // 硬件 0x1A 一旦上报就是有效反应时（不论 D10 符号），软件状态机的 Closed 是常态
                        // （比赛开始前 / 出发台还没切到 Open），不应当作过滤门槛。仅在 Touched 状态下保留
                        // "已记录过一次 → 走备用"的原语义。
                        if (sbStatus != DeviceStatus.Touched) sbOpen = true;
                        if (!sbOpen && sbStatus == DeviceStatus.Touched) {
                            // 2026-06-03 接力赛多次 SB (= Touched 状态下又按) 也喂 calculator — LastSbSwim 取最近一次.
                            //   同主路径用 side 反推 handoffLap. 允许 currentLap=0 + 非 StartPosition (= 4×50m 棒 2 抢跳).
                            // 2026-07-13 按侧化: Touched 状态下接力多次 SB 也喂 calculator (LastSbSwim 取最近一次).
                            //   判据 = 该侧未结算交接窗口 (HandoffMode 倒计时=0 设, 免疫 CurrentLap++ 时序). 替代 CurrentLap%perLeg 反推.
                            if (_isRelay && _laneCloseSettings != null && _laneCloseSettings.ReactionTimeEnabled
                                && _relayReactionCalc != null && (side == "left" || side == "right")) {
                                bool hmSbB  = (side == "left") ? laneState.HandoffModeLeft        : laneState.HandoffModeRight;
                                bool recSbB = (side == "left") ? laneState.SbReactionRecordedLeft : laneState.SbReactionRecordedRight;
                                if (hmSbB && !recSbB) {
                                    _relayReactionCalc.OnEvent(lane, side, RelayReactionCalculator.EventKind.SB, timeInSeconds);
                                }
                            }
                            RecordBackupReaction(lane, timeInSeconds, sbSideForClose);
                            break;
                        }
                        if (sbOpen) {

                        if (!_laneCloseSettings.ReactionTimeEnabled) {
                            // 关闭RT：不进行反应时/抢跳判定，仅记录出发台动作日志
                            AddLog(Loc.F("Str_Log_SbTriggeredRtOffFmt", lane));
                        } else if (_isRelay && _laneCloseSettings != null && (side == "left" || side == "right")
                                   && ((side == "left") ? laneState.HandoffModeLeft : laneState.HandoffModeRight)
                                   && !((side == "left") ? laneState.SbReactionRecordedLeft : laneState.SbReactionRecordedRight)) {
                            // 2026-07-13 按侧化: 接力交接 SB 喂入 RelayReactionCalculator. 判据 = 该侧未结算交接窗口
                            //   (HandoffMode 倒计时=0 设, 免疫 CurrentLap 的 ++ 时序; 抢跳 SB 早于到达触板也已由锚点覆盖).
                            //   替代原 CurrentLap%perLeg 奇偶反推 handoffLap. 棒 1 发令 SB: HandoffMode=false → 落到下方 else 出发段.
                            if (_relayReactionCalc != null && !string.IsNullOrEmpty(side)) {
                                _relayReactionCalc.OnEvent(lane, side, RelayReactionCalculator.EventKind.SB, timeInSeconds);
                            }
                        } else if (laneState.CurrentLap > 0) {
                            // 2026-06-03 非接力 + 已起跳 (CurrentLap>0): 比赛进行中的 SB 数据, 不算反应时, 仅记日志
                            AddLog(Loc.F("Str_Log_SbTriggeredAfterStartFmt", lane));
                        } else {
                            // 比赛发令出发 (= CurrentLap==0, 个人赛起跳 OR 接力第 1 棒).
                            // 2026-06-14 PreStart 重设计: 固件送来的 timeInSeconds 是 SB 触发时刻的 PreStart 计数器值(不是反应时),
                            //   PC 这里减去枪响时刻 PreStart (= _gunPreStartSec) 得到反应时. 抢跳时为负.
                            //   _gunPreStartSec == null 说明枪还没响 (= 抢跳 SB 早于 0x22), 暂存待算.
                            double reactionTime;
                            if (_gunPreStartSec.HasValue) {
                                reactionTime = timeInSeconds - _gunPreStartSec.Value;
                            } else {
                                _pendingPreStartReactions.Add(new PendingPreStartReaction {
                                    Lane = lane, DeviceKind = "SB", Side = side,
                                    RawPreStartSec = timeInSeconds, IsRelayLeg1 = _isRelay
                                });
                                AddLog(Loc.F("Str_Log_SbBeforeGunFmt", lane, timeInSeconds));
                                // 反应时未知, 暂不更新 laneState.ReactionTime / LegReactionTimes (留待 Flush 回填)
                                EnterStartBlockTouchedThenClose(laneState, sbSideForClose, lane);
                                break;
                            }
                            laneState.ReactionTime = reactionTime;
                            // 接力第 1 棒：把出发反应时写入 LegReactionTimes[0]（覆盖式，重复触发只保留最近一次）
                            if (_isRelay) {
                                var swForLane0 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                                    var sa2 = s2.GetAssignmentForStage(_currentStage);
                                    return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
                                });
                                if (swForLane0 != null) {
                                    var res0 = EnsureRelayLaneResult(swForLane0, lane);
                                    if (res0 != null) {
                                        EnsureLegReactionSlots(res0);
                                        if (res0.LegReactionTimes.Count > 0) res0.LegReactionTimes[0] = reactionTime;
                                    }
                                }
                            }
                            if (isFalseStart || reactionTime < 0) {
                                // 2026-05-12 硬件以 D10 符号位明确上报抢跳; 2026-06-14 PC 端 reaction<0 (SB 早于枪响) 也算抢跳
                                laneState.IsSuspectFalseStart = true;
                                AddLog(Loc.F("Str_Log_FalseStartHwConfirmedFmt", lane, reactionTime));
                            } else if (reactionTime <= _laneCloseSettings.FalseStartThreshold) {
                                // 仅作可疑提示（反应时标红），是否判罚由裁判手动决定
                                laneState.IsSuspectFalseStart = true;
                                AddLog(Loc.F("Str_Log_SuspiciousStartFmt", lane, reactionTime));
                            } else {
                                AddLog(Loc.F("Str_Log_ReactionTimeFmt", lane, reactionTime));
                            }
                            // 2026-06-15 主动写比赛日志: 显示计算后的反应时 (= sb_PreStart - _gunPreStartSec), 不是原始 PreStart 数据
                            {
                                var sw_sb_log = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                                    var sa2 = s2.GetAssignmentForStage(_currentStage);
                                    return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
                                });
                                string swName_sb_log = sw_sb_log != null ? (sw_sb_log.Name ?? "") : "";
                                AppendToLaneEventLog(lane, "StartingBlock", reactionTime, swName_sb_log, side, -1);
                            }
                        }
                        // 正式反应时已记录，把该端出发台切到"已触板（红）"，StartBlockCloseDelay 秒后转 Closed
                        EnterStartBlockTouchedThenClose(laneState, sbSideForClose, lane);
                    }
                    }
                    break;

                case "Touchpad":
                case "ManualTouchpad":   // 2026-06-14 MB 代触 (硬件 d3=Pushbutton_Result=1) 走同一处理路径, 内部仍用 isMbSubstitute 区分细节
                    // 触板状态机：
                    //   Open       → 作为正式成绩送进 ProcessTouchpadHit，再把该端切到 Touched（红）保持 ResultConfirmCloseDelay 秒
                    //   Touched    → 已有正式成绩；本次记日志并写入"备用成绩"（争议时使用）
                    //   其它（Closed/Broken/NotInstalled）→ 仅记日志，不作为成绩
                    {
                        // 2026-06-21 仰泳出发端守卫 (现为冗余防御 - 2026-06-22 固件 swimplay.c 已修协议:
                        //   TP 松开发 D3=3 BackstrokeRelease 走 case "BackstrokeRelease" 路径不会到这里;
                        //   TP 按下 if(0) 禁用不发任何帧. 此守卫保留作 defense-in-depth, 防固件回滚 / 老固件兼容.
                        //   原 bug 描述: 固件未正确标 D3=3 时, 仰泳出发 TP 帧走 case "Touchpad" 错占第 1 段
                        //   → 100m+ 仰泳终点提前关闭, 没成绩. 4 条件守卫: 仰泳 + 出发端 + CurrentLap=0 + 非 MB 代触.
                        {
                            bool isBack_g = IsBackstrokeStartEvent(_currentEvent);
                            bool startFromLeft_g = _laneCloseSettings == null || _laneCloseSettings.StartPosition != "right";
                            string startSideName_g = startFromLeft_g ? "left" : "right";
                            if (isBack_g && side == startSideName_g && laneState.CurrentLap == 0 && !isMbSubstitute) {
                                AddLog(Loc.F("Str_Log_BackstrokeStartTpFmt",
                                    lane, side == "left" ? "左" : "右"));
                                break;
                            }
                        }
                        // 2026-06-02 协议规约: side 必须由硬件 frame[4]=Lane_NoTbl 解析得来, PC 不自判. side 缺失 = 协议错误, 跳过
                        DeviceStatus tpStatus;
                        string sideForClose = side;
                        if (side == "left") tpStatus = laneState.LeftTouchpadStatus;
                        else if (side == "right") tpStatus = laneState.RightTouchpadStatus;
                        else {
                            AddLog(Loc.F("Str_Log_TpSideMissingFmt", lane));
                            break;
                        }

                        // 2026-06-04 接力赛: TP 和 MB substitute 必须在当前棒预期完成侧 (= 防右 MB 误代替左 TP 导致错位).
                        //   棒次完成侧 = StartPosition if afterLap 偶 else 另一侧 (4×50m perLeg=1 棒次交替, 4×100m 不变).
                        if (_isRelay && _laneCloseSettings != null) {
                            int afterLapTp = laneState.CurrentLap + 1;
                            string startSideTpG = _laneCloseSettings.StartPosition;
                            string expectedSideTpG = (afterLapTp % 2 == 0)
                                ? startSideTpG
                                : (startSideTpG == "left" ? "right" : "left");
                            if (side != expectedSideTpG) {
                                AddLog(Loc.F("Str_Log_SideIgnoredGuardFmt",
                                    lane,
                                    side == "left" ? "左" : "右",
                                    isMbSubstitute ? "MB代替" : "触板",
                                    expectedSideTpG == "left" ? "左" : "右"));
                                break;
                            }
                        }

                        // 2026-05-13 全开模式：所有触板信号都认可为正式成绩，绕过状态机
                        // 2026-05-26 撤回上一版 Closed-accept 改动: 该改动导致段间的杂散触板帧被
                        //   误记为新分段 → 触发 Direction flip → 倒计时结束后开错端设备.
                        //   保留原 Open→记录 / Touched→备用 / 其它→丢弃 的状态机 (与硬件期望一致).
                        if (tpStatus == DeviceStatus.Open || IsLaneForceAllOpen(lane) || isMbSubstitute) {
                            // 2026-06-16 盲表成绩历史: isMbSubstitute=true (= 真盲表代触) 即时 append + 刷下拉
                            if (isMbSubstitute) AppendBlindResult(lane, timeInSeconds);
                            ProcessTouchpadHit(lane, timeInSeconds, laneState, side, isMbSubstitute);
                            // 已记录正式成绩，把该端切到"已触板（红）"，到点再 Closed
                            EnterTouchedThenClose(laneState, sideForClose, lane);
                        } else if (tpStatus == DeviceStatus.Touched) {
                            // 备用成绩：写入运动员当前组的成绩记录 + 日志
                            RecordBackupTouch(lane, timeInSeconds);
                        } else {
                            AddLog(Loc.F("Str_Log_TpRecordedNotResultFmt",
                                lane, side ?? "", tpStatus));
                        }
                    }
                    break;

                case "PushButton1":
                case "PushButton2":
                case "PushButton3":
                    // 盲表状态机（按【单个盲表】粒度，每个盲表独立计时）：
                    //   Open    → 作为正式分段计时数据送 ProcessBlindWatchData，再切到 Touched（红）保持 ResultConfirmCloseDelay 秒
                    //   Touched → 已记录正式成绩；本次记日志并写入"备用盲表成绩"
                    //   其它    → 仅记日志
                    {
                        int blindNum = (cmdType == "PushButton1") ? 1 : (cmdType == "PushButton2" ? 2 : 3);
                        DeviceStatus bwStatus;
                        string bwSideForClose = side;
                        if (side == "left") bwStatus = GetBlindStatusByNum(laneState, true, blindNum);
                        else if (side == "right") bwStatus = GetBlindStatusByNum(laneState, false, blindNum);
                        else {
                            DeviceStatus lst = GetBlindStatusByNum(laneState, true, blindNum);
                            DeviceStatus rst = GetBlindStatusByNum(laneState, false, blindNum);
                            if (lst == DeviceStatus.Open) { bwStatus = lst; bwSideForClose = "left"; }
                            else if (rst == DeviceStatus.Open) { bwStatus = rst; bwSideForClose = "right"; }
                            else if (lst == DeviceStatus.Touched) { bwStatus = lst; bwSideForClose = "left"; }
                            else if (rst == DeviceStatus.Touched) { bwStatus = rst; bwSideForClose = "right"; }
                            else { bwStatus = lst; bwSideForClose = "left"; }
                        }

                        // 2026-05-13 全开模式：所有盲表信号都认可为正式分段
                        // 2026-05-26 撤回 Closed-accept 改动 (副作用见 Touchpad 分支注释)
                        if (bwStatus == DeviceStatus.Open || IsLaneForceAllOpen(lane)) {
                            // 2026-06-16 盲表成绩历史 (PushButton1/2/3 = 真盲表分段事件) → 即时 append + 刷下拉
                            AppendBlindResult(lane, timeInSeconds);
                            ProcessBlindWatchData(lane, cmdType, timeInSeconds, bwSideForClose);
                            EnterBlindTouchedThenClose(laneState, bwSideForClose, blindNum, lane);
                        } else if (bwStatus == DeviceStatus.Touched) {
                            // 备用盲表也一起加入历史 (Touched 状态下重复的盲表)
                            AppendBlindResult(lane, timeInSeconds);
                            RecordBackupBlind(lane, blindNum, timeInSeconds);
                        } else {
                            AddLog(Loc.F("Str_Log_BwRecordedNotResultFmt",
                                lane, blindNum, side ?? "", bwStatus));
                        }
                    }
                    break;
            }

            UpdateLaneStatusDisplay();
            Broadcast();
            // 2026-05-13 #6 比赛过程数据（触板/盲表/反应时）也要立刻持久化+同步给编排端。
            // 滚动时间 0x7F 已在前面 if(cmdType=="RunningTime") return; 提前返回，不会落到这里。
            //
            // 2026-08-24 迁移第2步：这里原来每次触板都 AutoSaveData()，也就是
            // BuildCurrentPackage + 序列化整个 1.2MB 的包再写盘。400 米一组上百次
            // 事件，每次约 20MB 分配，1.2MB 的字符串还直接进大对象堆(LOH 不压缩)
            // —— 那次内存涨到几 GB、清内存也降不下来，根就在这一行。
            // 改成只写当前组库那几行；JSON 仍留一条低频兜底(见 SaveHeatProgress)。
            try { SaveHeatProgress(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResultPersistFailedFmt", ex.Message)); }
        }

        /// <summary>
        /// 记录原始计时数据到当前比赛日志
        /// </summary>
        private void LogRawTimingData(int lane, string cmdType, double time, string side = null) {
            string elapsed = _raceStartTime > DateTime.MinValue
                ? (DateTime.Now - _raceStartTime).TotalSeconds.ToString("F3")
                : "0.000";
            // 查找运动员
            string swimmerName = "";
            var sw = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (sw != null) swimmerName = sw.Name ?? "";

            //2026-05-31 lookup laneState 算"剩余触板次数" 给日志加 [N] 标注
            var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            int lapRemain = -1;
            if (ls != null && side != null) {
                lapRemain = GetTouchRemain(ls, side == "left");
            }

            _rawTimingLog.AppendFormat("{0}\t道{1}\t{2}\t{3}\t{4}\r\n",
                DateTime.Now.ToString("HH:mm:ss.fff"), lane, cmdType,
                TimeFormatter.Format(time), swimmerName);
            TrimSbIfOver(_rawTimingLog, MAX_RAW_TIMING_LOG);

            // 2026-05-27 同步追加到"比赛日志" tab 的 per-lane 缓冲
            // 2026-06-15 反应时类事件 (StartingBlock / BackstrokeRelease) 跳过这里, 由反应时计算路径 (case "StartingBlock"/"BackstrokeRelease" / FlushPendingPreStartReactions / OnRelayReactionReady) 主动写计算后的反应时, 避免比赛日志显示原始 PreStart 数据.
            if (cmdType == "StartingBlock" || cmdType == "BackstrokeRelease") return;
            // 2026-07-09 仰泳出发端出发段 (CurrentLap=0) 的 Touchpad 帧不写日志.
            //   用户诉求: 出发时只记录"触板放开" (触放), 触板按下 (触) 不记.
            //   case "Touchpad" 已有守卫 (line 5207-5214) 视为反应时副产物, 日志同步过滤.
            //   折返回起点端 (CurrentLap > 0) 走另一侧到边逻辑, 不受影响.
            if (cmdType == "Touchpad" && side != null && _currentEvent != null && IsBackstrokeStartEvent(_currentEvent)) {
                var lsFilter = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (lsFilter != null) {
                    bool startLeftFilter = _laneCloseSettings == null || _laneCloseSettings.StartPosition != "right";
                    string startSideFilter = startLeftFilter ? "left" : "right";
                    if (side == startSideFilter && lsFilter.CurrentLap == 0) return;
                }
            }
            // 2026-07-09 直通模式 (HardwareAlwaysOpen): TP/MB = Closed 时的帧不写日志.
            //   用户诉求: 触板后 ResultConfirmCloseDelay=0 关闭到下次 LaneCloseCountdown=0 打开之间不记.
            //   按比赛流程模式硬件已过滤, 此 filter 不启用.
            //   Touched 状态 (触板刚触未回 Closed) 不 filter, 保留 RecordBackupTouch 备用触发.
            if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen && side != null) {
                var lsHw = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (lsHw != null) {
                    DeviceStatus devSt = DeviceStatus.Open;
                    bool checkClose = false;
                    if (cmdType == "Touchpad") {
                        devSt = (side == "left") ? lsHw.LeftTouchpadStatus : lsHw.RightTouchpadStatus;
                        checkClose = true;
                    } else if (cmdType == "PushButton1") {
                        devSt = (side == "left") ? lsHw.LeftBlindWatch1Status : lsHw.RightBlindWatch1Status;
                        checkClose = true;
                    } else if (cmdType == "PushButton2") {
                        devSt = (side == "left") ? lsHw.LeftBlindWatch2Status : lsHw.RightBlindWatch2Status;
                        checkClose = true;
                    } else if (cmdType == "PushButton3") {
                        devSt = (side == "left") ? lsHw.LeftBlindWatch3Status : lsHw.RightBlindWatch3Status;
                        checkClose = true;
                    }
                    if (checkClose && devSt == DeviceStatus.Closed) return;
                }
            }
            AppendToLaneEventLog(lane, cmdType, time, swimmerName, side, lapRemain);
        }

        // 2026-05-27 "比赛日志" tab: 按 per-lane 累积事件 (出发反应时 / 触板 / 盲表 / 手动触板).
        //   只挑跟运动员"成绩相关"的事件类型, 跳过 RunningTime/TimerReady/StartCommand 等控制帧.
        //   缓冲存活范围 = 一组比赛 (Restart/Ready 时清空).
        private void AppendToLaneEventLog(int lane, string cmdType, double time, string swimmerName, string side = null, int lapRemain = -1) {
            // 2026-07-13 直通模式: PC 自算反应时, 硬件"SB 超时无反应"帧 (StartingBlockTimeout = 出[N]=---) 冗余 → 不入日志/不打印.
            if (cmdType == "StartingBlockTimeout" && _laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen) return;
            // 2026-05-27 用户要求简化显示文字
            string label;
            switch (cmdType) {
                case "StartingBlock":     label = "出";   break;
                case "StartingBlockTimeout": label = "出";   break;   //2026-05-31 接力 SB 超时无 TP/MB (d10=2), time 字段统一显示 "---"
                case "Touchpad":          label = "触";   break;
                case "ManualTouchpad":    label = "触代"; break;   //2026-05-31 硬件用盲表成绩代替触板 (cmd=0x16 D3=Pushbutton_Result=1); 2026-06-14 cmdType 由 "TouchpadMb" 改为 "ManualTouchpad" (= 跟 enum 一致)
                case "BackstrokeRelease": label = "触放"; break;   //2026-06-14 仰泳出发松开 TP (= 反应时锚点, 时间字段为 PreStart 计数器值)
                case "PushButton1":       label = "盲1";  break;
                case "PushButton2":       label = "盲2";  break;
                case "PushButton3":       label = "盲3";  break;
                case "ManualTouchLeft":   label = "手左"; break;
                case "ManualTouchRight":  label = "手右"; break;
                default: return;   // 其它类型跳过
            }
            string elapsed = _raceStartTime > DateTime.MinValue
                ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds)
                : "—";
            //2026-05-31 加左/右标志 + 圈数 [N] 标注 (N = 该侧剩余触板次数, 跟 PC UI 一致)
            string sideLabel = side == "left" ? "左" : (side == "right" ? "右" : "");
            string lapLabel = lapRemain >= 0 ? string.Format("[{0}]", lapRemain) : "";
            //2026-05-31 v2: 没数据 (= 接力 SB 超时 d10=2) 显示 "---"; 其他场景 0/正/负 都显示数值 (= 0 → "0.00", 负 → "-X.XX")
            string timeStr;
            if (cmdType == "StartingBlockTimeout") timeStr = "---";
            else if (time == 0) timeStr = "0.00";
            else if (time < 0) timeStr = "-" + TimeFormatter.Format(-time);   // TimeFormatter 对 <=0 返空, 用 abs+前缀
            else timeStr = TimeFormatter.Format(time);
            // 2026-06-16 简化日志格式: 去掉 "[T=" 和 "]", 直接显示时间值. 原 `[T=    3.06]` → `   3.06`
            AppendLaneEventLog(lane, string.Format("{0,8} 道{1}{2} {3}{4}={5}{6}\r\n",
                elapsed, lane, sideLabel, label, lapLabel, timeStr,
                string.IsNullOrEmpty(swimmerName) ? "" : (" (" + swimmerName + ")")));
            // 2026-06-12 USB 热敏打印机 实时打印: 仅 TP/SB/MB 三类 (出/触/盲1-3), 不含 手动触板/触代.
            //   打印同一行 = 跟比赛日志一致 (现场纸质流水留底). 入队即返回, 不阻塞 UI.
            if (_thermalPrinter != null && _thermalPrinter.Enabled) {
                bool printable = cmdType == "StartingBlock" || cmdType == "StartingBlockTimeout"
                    || cmdType == "Touchpad" || cmdType == "ManualTouchpad"    // 2026-06-14 真触板 + MB 代触都要打小票
                    || cmdType == "PushButton1" || cmdType == "PushButton2" || cmdType == "PushButton3";
                if (printable) {
                    // 2026-06-12 格式: 道4左 触[1] = 23.43 (无 T= 前缀, 无姓名)
                    _thermalPrinter.PrintLine(string.Format("道{0}{1} {2}{3} = {4}",
                        lane, sideLabel, label, lapLabel, timeStr));
                }
            }
            // 若当前显示的就是这道, 立刻刷新可见 TextBox
            if (lane == _selectedLane) RefreshLaneEventLogView();
        }

        // 2026-07-13 反应时热敏打印 (每棒一行, 跟比赛日志"反应时="同源; 用户要求必须打印). rtText = 数值/******/------.
        private void PrintReactionToThermal(int lane, string sideLabel, string legLabel, string rtText) {
            if (_thermalPrinter != null && _thermalPrinter.Enabled)
                _thermalPrinter.PrintLine(string.Format("道{0}{1}{2} 反应时 = {3}", lane, sideLabel, legLabel, rtText));
        }

        // 切换当前选中道次时调一次, 把 _laneEventLog[lane] 完整刷到 TextBox
        // ── 2026-09-13 比赛日志的增量追加 ──────────────────────────────
        // 一条事件约 70 字节, 直接推给客户端让它自己往后接。
        // 对比原来的做法: 每帧把十条道 640KB 的累积文本全量重发一遍。
        // 完整帧(10 秒一次)仍带全量, 客户端断线重连/漏了一条也能对齐。
        // 2026-09-15 【广播分级】泳道事件日志只有"比赛控制网页"(race_control.html) 的
        //   日志面板在读; 大屏不读(BuildDisplayPayload 本来就不带这个字段), 检录台/
        //   信息查询/排名屏/报名终端/显示控制/编排端更用不上。原来 EnqueueToAll 全员群发。
        private void PushLaneEventAppend(int lane, string line) {
            if (string.IsNullOrEmpty(line)) return;
            try {
                var msg = new { type = "LANE_EVENT_APPEND", data = new { lane = lane, text = line } };
                if (IsRemoteTimingControlMode) { TryForwardToMainServer(msg, "others"); return; }
                if (_timingWebSockets.Count == 0) return;
                string json = JsonConvert.SerializeObject(msg);
                EnqueueToSet(_timingWebSockets, json);
            } catch { }
        }

        /// <summary>往某道的比赛日志追加一行: 存本地 + 刷本机视图 + 增量推客户端。</summary>
        private void AppendLaneEventLog(int lane, string line) {
            if (string.IsNullOrEmpty(line)) return;
            if (!_laneEventLog.ContainsKey(lane)) _laneEventLog[lane] = new StringBuilder();
            _laneEventLog[lane].Append(line);
            TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
            if (lane == _selectedLane) RefreshLaneEventLogView();
            PushLaneEventAppend(lane, line);
        }

        private void RefreshLaneEventLogView() {
            if (LaneEventLogText == null) return;
            string content;
            if (_selectedLane < 0) {
                content = "(请先点击或输入泳道号)";
            } else if (!_laneEventLog.ContainsKey(_selectedLane) || _laneEventLog[_selectedLane].Length == 0) {
                content = string.Format("道{0}: 本组暂无事件记录", _selectedLane);
            } else {
                content = _laneEventLog[_selectedLane].ToString();
            }
            LaneEventLogText.Text = content;
            try { if (LaneEventLogScroller != null) LaneEventLogScroller.ScrollToEnd(); } catch { }
        }

        // 用户在"泳道操作"输入框改泳道号 → 立即切换"比赛日志"显示的道次
        private void LaneInputBox_TextChanged(object sender, System.Windows.Controls.TextChangedEventArgs e) {
            if (LaneInputBox == null) return;
            int lane;
            if (int.TryParse(LaneInputBox.Text, out lane)) {
                if (_selectedLane != lane) {
                    _selectedLane = lane;
                    _lastTsSplitCount = -1;
                    try { UpdateTimingSourceInfo(); } catch { }
                    try { RefreshLaneEventLogView(); } catch { }
                }
            }
        }

        /// <summary>
        /// 保存当前比赛的原始计时数据到文件
        /// </summary>
        private void SaveRawTimingLog() {
            if (_rawTimingLog.Length == 0) return;
            if (string.IsNullOrEmpty(_currentEvent) || _currentHeat <= 0) return;
            try {
                string dir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database", "RawData");
                if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);

                // 文件名：[组别_]性别_项目_赛次_第N组.txt
                string agName = string.IsNullOrEmpty(_currentAgeGroup) ? "" : (_currentAgeGroup + "_");
                string safeName = string.Format("{0}{1}_{2}_{3}_第{4}组",
                    agName, _currentGender, _currentEvent, _currentStage, _currentHeat)
                    .Replace("×", "x").Replace("/", "_");
                string path = IOPath.Combine(dir, safeName + ".txt");

                // 写入文件头 + 数据
                var sb = new StringBuilder();
                sb.AppendFormat("═══ 原始计时数据 ═══\r\n");
                sb.AppendFormat("赛事: {0}\r\n", _competitionName);
                sb.AppendFormat("项目: {0}{1} {2}\r\n",
                    string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] "),
                    _currentGender, _currentEvent);
                sb.AppendFormat("赛次: {0}  第{1}组\r\n", _currentStage, _currentHeat);
                sb.AppendFormat("比赛时间: {0}\r\n", _raceStartTime > DateTime.MinValue ? _raceStartTime.ToString("yyyy-MM-dd HH:mm:ss") : "未开始");
                sb.AppendFormat("终点位置: {0}端  发令位置: {1}端\r\n",
                    _laneCloseSettings.FinishPosition == "left" ? "左" : "右",
                    _laneCloseSettings.StartPosition == "left" ? "左" : "右");

                // 运动员名单 — 接力赛 s.Name 实为队名，4 位队员姓名存于 s.Notes（"接力队 棒次:张三,李四,..."）
                sb.AppendFormat("\r\n--- 出场名单 ---\r\n");
                foreach (var s in GetCurrentHeatSwimmers()) {
                    var sa = s.GetAssignmentForStage(_currentStage);
                    int sLane = sa != null ? sa.Lane : s.Lane;
                    string athletes = s.Name ?? "";
                    if (_isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:"))
                        athletes = s.Notes.Substring("接力队 棒次:".Length);
                    sb.AppendFormat("道{0}\t代表队:{1}\t运动员:{2}\t报名:{3}\r\n", sLane, s.Country, athletes, s.EntryTime);
                }

                // 原始数据
                sb.AppendFormat("\r\n--- 原始数据 (时刻/泳道/类型/时间/运动员) ---\r\n");
                sb.Append(_rawTimingLog.ToString());

                // 最终成绩汇总
                sb.AppendFormat("\r\n--- 最终成绩 ---\r\n");
                foreach (var s in GetCurrentHeatSwimmers().OrderBy(s2 => s2.CurrentRank > 0 ? s2.CurrentRank : int.MaxValue)) {
                    var r = s.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                    var sa = s.GetAssignmentForStage(_currentStage);
                    int sLane = sa != null ? sa.Lane : s.Lane;
                    string status = !string.IsNullOrEmpty(s.Status) ? s.Status : "";
                    string finalTime = r != null && r.FinalTime > 0 ? TimeFormatter.Format(r.FinalTime) : "";
                    string source = r != null ? (r.TimingSource ?? "") : "";
                    // 接力赛反应时按棒展开"第1棒:0.45 / 第2棒:0.30 ..."；个人赛仍是 StartingBlockTime 单值
                    //   2026-06-04 D 最终成绩显 1-4 棒
                    string reaction = "";
                    if (_isRelay && r != null && r.LegReactionTimes != null && r.LegReactionTimes.Count > 0) {
                        var rtParts = new List<string>();
                        for (int li = 0; li < r.LegReactionTimes.Count; li++) {
                            double rt = r.LegReactionTimes[li];
                            rtParts.Add(string.Format("第{0}棒:{1}", li + 1, (rt != 0 && !double.IsNaN(rt)) ? rt.ToString("F3") : "—"));
                        }
                        reaction = string.Join(" / ", rtParts.ToArray());
                    } else if (r != null && r.StartingBlockTime != 0 && !double.IsNaN(r.StartingBlockTime)) {
                        reaction = r.StartingBlockTime.ToString("F3");
                    }
                    string athletesFr = s.Name ?? "";
                    if (_isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:"))
                        athletesFr = s.Notes.Substring("接力队 棒次:".Length);
                    sb.AppendFormat("名次:{0}\t道{1}\t代表队:{2}\t运动员:{3}\t成绩:{4}\t计时源:{5}\t反应:{6}\t{7}\r\n",
                        s.CurrentRank > 0 ? s.CurrentRank.ToString() : "-", sLane, s.Country, athletesFr,
                        !string.IsNullOrEmpty(status) ? status : finalTime, source, reaction, status);

                    // 各计时设备最终成绩
                    if (r != null) {
                        sb.AppendFormat("  终点成绩: 触板:{0}  盲表1:{1}  盲表2:{2}  盲表3:{3}\r\n",
                            TimeFormatter.Format(r.TouchpadTime),
                            TimeFormatter.Format(r.PushButton1Time),
                            TimeFormatter.Format(r.PushButton2Time),
                            TimeFormatter.Format(r.PushButton3Time));
                    }

                    // 分段明细
                    if (r != null && r.Splits.Count > 0) {
                        foreach (var sp in r.Splits) {
                            sb.AppendFormat("  分段{0}({1}m): 触板:{2}  盲1:{3}  盲2:{4}  盲3:{5}  手动:{6}  累计:{7}  源:{8}\r\n",
                                sp.Lap, sp.Distance,
                                TimeFormatter.Format(sp.TouchpadTime),
                                TimeFormatter.Format(sp.PushButton1Time),
                                TimeFormatter.Format(sp.PushButton2Time),
                                TimeFormatter.Format(sp.PushButton3Time),
                                TimeFormatter.Format(sp.ManualTouchTime),
                                TimeFormatter.Format(sp.CumulativeTime), sp.TimingSource);
                        }
                    }

                    // 备用成绩 — Touched（已触板红色）窗口期内捕获的额外计时事件，争议裁定时使用
                    if (r != null && (
                        (r.BackupTouchTimes != null && r.BackupTouchTimes.Count > 0) ||
                        (r.BackupBlindTimes != null && r.BackupBlindTimes.Count > 0) ||
                        (r.BackupReactionTimes != null && r.BackupReactionTimes.Count > 0))) {
                        sb.Append("  ★备用成绩(争议时使用):");
                        if (r.BackupTouchTimes != null && r.BackupTouchTimes.Count > 0) {
                            var touchStrs = new List<string>();
                            foreach (double t in r.BackupTouchTimes) touchStrs.Add(TimeFormatter.Format(t));
                            sb.AppendFormat("  触板[{0}]", string.Join(", ", touchStrs.ToArray()));
                        }
                        if (r.BackupBlindTimes != null && r.BackupBlindTimes.Count > 0) {
                            sb.AppendFormat("  盲表[{0}]", string.Join(", ", r.BackupBlindTimes.ToArray()));
                        }
                        if (r.BackupReactionTimes != null && r.BackupReactionTimes.Count > 0) {
                            sb.AppendFormat("  出发台[{0}]", string.Join(", ", r.BackupReactionTimes.ToArray()));
                        }
                        sb.Append("\r\n");
                    }
                }

                sb.AppendFormat("\r\n保存时间: {0}\r\n", DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff"));
                WriteFileAsync(path, sb.ToString(), Encoding.UTF8, null, Loc.T("Str_Log_SaveRawTimingTxtFailedPrefix"));

                // 同时生成HTML版本（可用浏览器打印为PDF，不可编辑）
                string htmlPath = IOPath.Combine(dir, safeName + ".html");
                SaveRawTimingHtml(htmlPath, safeName);

                AddLog(Loc.F("Str_Log_RawDataSavedFmt", safeName));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_SaveRawDataFailedFmt", ex.Message));
            }
        }

        private void SaveRawTimingHtml(string htmlPath, string title) {
            var h = new StringBuilder();
            h.Append("<!DOCTYPE html><html><head><meta charset='UTF-8'>");
            h.AppendFormat("<title>{0} - 原始计时数据</title>", title);
            h.Append("<style>");
            h.Append("@page { size: A4; margin: 15mm; }");
            h.Append("body { font-family: 'Microsoft YaHei', sans-serif; font-size: 12px; color: #1e293b; margin: 0; padding: 20px; -webkit-user-select: none; user-select: none; }");
            h.Append("h1 { font-size: 18px; text-align: center; margin-bottom: 4px; }");
            h.Append("h2 { font-size: 14px; text-align: center; color: #475569; margin-bottom: 16px; }");
            h.Append(".info { margin-bottom: 12px; }");
            h.Append(".info td { padding: 2px 12px 2px 0; font-size: 12px; }");
            h.Append(".info .label { color: #64748b; }");
            h.Append(".section { font-size: 13px; font-weight: bold; color: #3b82f6; margin: 14px 0 6px; border-bottom: 1px solid #e2e8f0; padding-bottom: 2px; }");
            h.Append("table.data { width: 100%; border-collapse: collapse; font-size: 11px; margin-bottom: 10px; }");
            h.Append("table.data th { background: #f1f5f9; border: 1px solid #cbd5e1; padding: 3px 6px; text-align: center; font-size: 11px; }");
            h.Append("table.data td { border: 1px solid #e2e8f0; padding: 2px 6px; }");
            h.Append("table.data tr:nth-child(even) { background: #f8fafc; }");
            h.Append(".mono { font-family: Consolas, 'Courier New', monospace; }");
            h.Append(".raw-data { font-family: Consolas, 'Courier New', monospace; font-size: 11px; white-space: pre; background: #f8fafc; border: 1px solid #e2e8f0; padding: 8px; overflow-x: auto; }");
            h.Append(".footer { text-align: right; color: #94a3b8; font-size: 10px; margin-top: 12px; }");
            h.Append(".watermark { text-align: center; color: #cbd5e1; font-size: 10px; margin-top: 6px; }");
            h.Append("@media print { .no-print { display: none; } }");
            h.Append("</style></head><body>");

            // 标题
            h.AppendFormat("<h1>{0}</h1>", _competitionName);
            h.AppendFormat("<h2>{0}{1} {2}　{3}　第{4}组　—　原始计时数据</h2>",
                string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] "),
                _currentGender, _currentEvent, _currentStage, _currentHeat);

            // 赛事信息
            h.Append("<table class='info'>");
            h.AppendFormat("<tr><td class='label'>比赛时间:</td><td>{0}</td><td class='label'>终点位置:</td><td>{1}端</td></tr>",
                _raceStartTime > DateTime.MinValue ? _raceStartTime.ToString("yyyy-MM-dd HH:mm:ss") : "未开始",
                _laneCloseSettings.FinishPosition == "left" ? "左" : "右");
            h.AppendFormat("<tr><td class='label'>发令位置:</td><td>{0}端</td><td class='label'>泳道数:</td><td>{1}道</td></tr>",
                _laneCloseSettings.StartPosition == "left" ? "左" : "右", _poolConfig.LaneCount);
            h.Append("</table>");

            // 出场名单 — 接力赛 s.Name 是队名，队员姓名在 s.Notes("接力队 棒次:...") 里
            h.Append("<div class='section'>出场名单</div>");
            h.Append("<table class='data'><tr align='center'><th>道次</th><th>代表队</th><th>运动员姓名</th><th>报名成绩</th></tr>");
            foreach (var s in GetCurrentHeatSwimmers()) {
                var sa = s.GetAssignmentForStage(_currentStage);
                int sLane = sa != null ? sa.Lane : s.Lane;
                string athletesH = s.Name ?? "";
                if (_isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:"))
                    athletesH = s.Notes.Substring("接力队 棒次:".Length);
                h.AppendFormat("<tr><td style='text-align:center;'>{0}</td><td>{1}</td><td><b>{2}</b></td><td class='mono' style='text-align:center;'>{3}</td></tr>",
                    sLane, s.Country, athletesH, s.EntryTime);
            }
            h.Append("</table>");

            // 原始数据流
            h.Append("<div class='section'>原始计时数据</div>");
            h.Append("<table class='data'><tr align='center'><th>时刻</th><th>泳道</th><th>类型</th><th>时间</th><th>运动员</th></tr>");
            string[] rawLines = _rawTimingLog.ToString().Split(new[] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries);
            foreach (string line in rawLines) {
                string[] cols = line.Split('\t');
                if (cols.Length >= 4) {
                    h.AppendFormat("<tr><td class='mono'>{0}</td><td style='text-align:center;'>{1}</td><td>{2}</td><td class='mono' style='text-align:center;'>{3}</td><td>{4}</td></tr>",
                        cols[0], cols[1], cols[2], cols[3], cols.Length > 4 ? cols[4] : "");
                }
            }
            h.Append("</table>");

            // 最终成绩 — 接力赛分别给"代表队"和"运动员姓名"列；反应时按棒展开
            h.Append("<div class='section'>最终成绩</div>");
            h.Append("<table class='data'><tr align='center'><th>名次</th><th>道</th><th>代表队</th><th>运动员姓名</th><th>成绩</th><th>计时源</th><th>反应时间</th><th>触板</th><th>盲表1</th><th>盲表2</th><th>盲表3</th><th>状态</th></tr>");
            foreach (var s in GetCurrentHeatSwimmers().OrderBy(s2 => s2.CurrentRank > 0 ? s2.CurrentRank : int.MaxValue)) {
                var r = s.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                var sa = s.GetAssignmentForStage(_currentStage);
                int sLane = sa != null ? sa.Lane : s.Lane;
                string status = s.Status ?? "";
                bool isDQ = status == "DSQ" || status == "DNS" || status == "DNF";
                string finalTime = !isDQ && r != null && r.FinalTime > 0 ? TimeFormatter.Format(r.FinalTime) : "";
                string athletesFh = s.Name ?? "";
                if (_isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:"))
                    athletesFh = s.Notes.Substring("接力队 棒次:".Length);
                // 2026-06-04 D 最终成绩 HTML 显 1-4 棒
                string reactionHtml = "";
                if (_isRelay && r != null && r.LegReactionTimes != null && r.LegReactionTimes.Count > 0) {
                    var rtParts2 = new List<string>();
                    for (int li = 0; li < r.LegReactionTimes.Count; li++) {
                        double rt2 = r.LegReactionTimes[li];
                        rtParts2.Add(string.Format("第{0}棒:{1}", li + 1, (rt2 != 0 && !double.IsNaN(rt2)) ? rt2.ToString("F3") : "—"));
                    }
                    reactionHtml = string.Join("<br>", rtParts2.ToArray());
                } else if (r != null && r.StartingBlockTime != 0 && !double.IsNaN(r.StartingBlockTime)) {
                    reactionHtml = r.StartingBlockTime.ToString("F3");
                }
                h.AppendFormat("<tr><td style='text-align:center;font-weight:bold;'>{0}</td><td style='text-align:center;'>{1}</td><td>{2}</td><td><b>{3}</b></td>" +
                    "<td class='mono' style='text-align:center;font-weight:bold;'>{4}</td><td style='text-align:center;'>{5}</td><td class='mono' style='text-align:center;font-size:10px;'>{6}</td>" +
                    "<td class='mono' style='text-align:center;'>{7}</td><td class='mono' style='text-align:center;'>{8}</td><td class='mono' style='text-align:center;'>{9}</td><td class='mono' style='text-align:center;'>{10}</td>" +
                    "<td style='text-align:center;color:#dc2626;font-weight:bold;'>{11}</td></tr>",
                    s.CurrentRank > 0 ? s.CurrentRank.ToString() : (isDQ ? "-" : ""),
                    sLane, s.Country, athletesFh, isDQ ? status : finalTime,
                    r != null ? (r.TimingSource ?? "") : "",
                    reactionHtml,
                    r != null ? TimeFormatter.Format(r.TouchpadTime) : "",
                    r != null ? TimeFormatter.Format(r.PushButton1Time) : "",
                    r != null ? TimeFormatter.Format(r.PushButton2Time) : "",
                    r != null ? TimeFormatter.Format(r.PushButton3Time) : "",
                    isDQ ? status : "");

                // 分段明细
                if (r != null && r.Splits.Count > 1) {
                    h.AppendFormat("<tr><td colspan='12' style='padding-left:30px;font-size:10px;color:#64748b;'>");
                    foreach (var sp in r.Splits) {
                        h.AppendFormat("分段{0}({1}m): 触板:<b>{2}</b> 盲1:{3} 盲2:{4} 盲3:{5} 累计:{6}　",
                            sp.Lap, sp.Distance,
                            TimeFormatter.Format(sp.TouchpadTime),
                            TimeFormatter.Format(sp.PushButton1Time),
                            TimeFormatter.Format(sp.PushButton2Time),
                            TimeFormatter.Format(sp.PushButton3Time),
                            TimeFormatter.Format(sp.CumulativeTime));
                    }
                    h.Append("</td></tr>");
                }

                // 备用成绩（争议时使用）— Touched 窗口期内捕获的额外触板/盲表/出发台事件
                if (r != null && (
                    (r.BackupTouchTimes != null && r.BackupTouchTimes.Count > 0) ||
                    (r.BackupBlindTimes != null && r.BackupBlindTimes.Count > 0) ||
                    (r.BackupReactionTimes != null && r.BackupReactionTimes.Count > 0))) {
                    h.Append("<tr><td colspan='12' style='padding-left:30px;font-size:10px;color:#dc2626;background:#fef2f2;'>");
                    h.Append("<b>★备用成绩(争议时使用):</b>");
                    if (r.BackupTouchTimes != null && r.BackupTouchTimes.Count > 0) {
                        var touchStrs = new List<string>();
                        foreach (double t in r.BackupTouchTimes) touchStrs.Add(TimeFormatter.Format(t));
                        h.AppendFormat(" 触板[<span class='mono'>{0}</span>]", string.Join(", ", touchStrs.ToArray()));
                    }
                    if (r.BackupBlindTimes != null && r.BackupBlindTimes.Count > 0) {
                        h.AppendFormat(" 盲表[<span class='mono'>{0}</span>]", string.Join(", ", r.BackupBlindTimes.ToArray()));
                    }
                    if (r.BackupReactionTimes != null && r.BackupReactionTimes.Count > 0) {
                        h.AppendFormat(" 出发台[<span class='mono'>{0}</span>]", string.Join(", ", r.BackupReactionTimes.ToArray()));
                    }
                    h.Append("</td></tr>");
                }
            }
            h.Append("</table>");

            h.AppendFormat("<div class='footer'>保存时间：{0}</div>", DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            h.Append("<div class='watermark'>本文档由竞赛管理系统自动生成 - 请使用浏览器 打印-另存为PDF 导出只读PDF文件</div>");
            h.Append("</body></html>");

            WriteFileAsync(htmlPath, h.ToString(), Encoding.UTF8, null, Loc.T("Str_Log_SaveRawTimingHtmlFailedPrefix"));
        }

        /// <summary>
        /// 触板打开时预创建空分段，确保后续的触板/盲表/手动数据都能写入
        /// </summary>
        private void PreCreateSplit(int lane) {
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null || laneState.IsFinished) return;
            int nextLap = laneState.CurrentLap + 1;

            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) return;

            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                result = new LaneResult {
                    EventName = _currentEvent,
                    Stage = _currentStage,
                    Heat = _currentHeat,
                    Lane = lane
                };
                swimmer.Results.Add(result);
            }

            // 检查是否已有该段的split（避免重复创建）
            bool exists = false;
            foreach (var sp in result.Splits) {
                if (sp.Lap == nextLap) { exists = true; break; }
            }
            if (!exists) {
                result.Splits.Add(new SplitTime {
                    Lap = nextLap,
                    Distance = nextLap * _poolConfig.Length
                });
            }
        }

        // 把触板从 Open → Touched（红色），ResultConfirmCloseDelay 秒后再 → Closed。
        // 期间硬件上来的额外触板事件会被 RecordBackupTouch 写为"备用成绩"。
        private void EnterTouchedThenClose(LaneDeviceState laneState, string side, int lane) {
            if (laneState == null) return;
            if (side == "right") {
                if (laneState.RightTouchpadBroken) return;
                laneState.RightTouchpadStatus = DeviceStatus.Touched;
            } else {
                if (laneState.LeftTouchpadBroken) return;
                laneState.LeftTouchpadStatus = DeviceStatus.Touched;
            }

            double holdSec = _laneCloseSettings.ResultConfirmCloseDelay > 0 ? _laneCloseSettings.ResultConfirmCloseDelay : 3;
            int capLane = lane;
            string capSide = side;
            var closeTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(holdSec) };
            closeTimer.Tick += delegate {
                closeTimer.Stop();
                var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == capLane);
                if (ls == null) return;
                if (capSide == "right") {
                    if (ls.RightTouchpadStatus == DeviceStatus.Touched) ls.RightTouchpadStatus = DeviceStatus.Closed;
                } else {
                    if (ls.LeftTouchpadStatus == DeviceStatus.Touched) ls.LeftTouchpadStatus = DeviceStatus.Closed;
                }
                Broadcast();
            };
            closeTimer.Start();
        }

        // 出发台 Open/FalseStart → Touched（红色）→ StartBlockCloseDelay 秒后 → Closed。
        // 期间额外的出发台事件作为"备用反应时"记录（争议时使用）。
        private void EnterStartBlockTouchedThenClose(LaneDeviceState laneState, string side, int lane) {
            if (laneState == null) return;
            if (side == "right") {
                if (laneState.RightStartBlockBroken) return;
                laneState.RightStartBlockStatus = DeviceStatus.Touched;
            } else {
                if (laneState.LeftStartBlockBroken) return;
                laneState.LeftStartBlockStatus = DeviceStatus.Touched;
            }

            double holdSec = _laneCloseSettings.StartBlockCloseDelay > 0 ? _laneCloseSettings.StartBlockCloseDelay : 3;
            int capLane = lane;
            string capSide = side;
            var t = new DispatcherTimer { Interval = TimeSpan.FromSeconds(holdSec) };
            t.Tick += delegate {
                t.Stop();
                var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == capLane);
                if (ls == null) return;
                if (capSide == "right") {
                    if (ls.RightStartBlockStatus == DeviceStatus.Touched) ls.RightStartBlockStatus = DeviceStatus.Closed;
                } else {
                    if (ls.LeftStartBlockStatus == DeviceStatus.Touched) ls.LeftStartBlockStatus = DeviceStatus.Closed;
                }
                Broadcast();
            };
            t.Start();
        }

        // 盲表 Open → Touched（红色）→ ResultConfirmCloseDelay 秒后 → Closed。
        // 每个盲表（左/右 × 1/2/3）独立计时，不影响其它盲表。
        private void EnterBlindTouchedThenClose(LaneDeviceState laneState, string side, int blindNum, int lane) {
            if (laneState == null) return;
            bool isLeft = side != "right";
            if (isLeft) {
                if (blindNum == 1) { if (laneState.LeftBlindWatch1Broken || laneState.LeftBlindWatch1NotInstalled) return; laneState.LeftBlindWatch1Status = DeviceStatus.Touched; }
                else if (blindNum == 2) { if (laneState.LeftBlindWatch2Broken || laneState.LeftBlindWatch2NotInstalled) return; laneState.LeftBlindWatch2Status = DeviceStatus.Touched; }
                else if (blindNum == 3) { if (laneState.LeftBlindWatch3Broken || laneState.LeftBlindWatch3NotInstalled) return; laneState.LeftBlindWatch3Status = DeviceStatus.Touched; }
                else return;
            } else {
                if (blindNum == 1) { if (laneState.RightBlindWatch1Broken || laneState.RightBlindWatch1NotInstalled) return; laneState.RightBlindWatch1Status = DeviceStatus.Touched; }
                else if (blindNum == 2) { if (laneState.RightBlindWatch2Broken || laneState.RightBlindWatch2NotInstalled) return; laneState.RightBlindWatch2Status = DeviceStatus.Touched; }
                else if (blindNum == 3) { if (laneState.RightBlindWatch3Broken || laneState.RightBlindWatch3NotInstalled) return; laneState.RightBlindWatch3Status = DeviceStatus.Touched; }
                else return;
            }

            double holdSec = _laneCloseSettings.ResultConfirmCloseDelay > 0 ? _laneCloseSettings.ResultConfirmCloseDelay : 3;
            int capLane = lane;
            bool capLeft = isLeft;
            int capNum = blindNum;
            var t = new DispatcherTimer { Interval = TimeSpan.FromSeconds(holdSec) };
            t.Tick += delegate {
                t.Stop();
                var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == capLane);
                if (ls == null) return;
                if (capLeft) {
                    if (capNum == 1 && ls.LeftBlindWatch1Status == DeviceStatus.Touched) ls.LeftBlindWatch1Status = DeviceStatus.Closed;
                    else if (capNum == 2 && ls.LeftBlindWatch2Status == DeviceStatus.Touched) ls.LeftBlindWatch2Status = DeviceStatus.Closed;
                    else if (capNum == 3 && ls.LeftBlindWatch3Status == DeviceStatus.Touched) ls.LeftBlindWatch3Status = DeviceStatus.Closed;
                } else {
                    if (capNum == 1 && ls.RightBlindWatch1Status == DeviceStatus.Touched) ls.RightBlindWatch1Status = DeviceStatus.Closed;
                    else if (capNum == 2 && ls.RightBlindWatch2Status == DeviceStatus.Touched) ls.RightBlindWatch2Status = DeviceStatus.Closed;
                    else if (capNum == 3 && ls.RightBlindWatch3Status == DeviceStatus.Touched) ls.RightBlindWatch3Status = DeviceStatus.Closed;
                }
                Broadcast();
            };
            t.Start();
        }

        // 读取指定盲表当前状态（getter 本身屏蔽 Broken / NotInstalled）。
        private static DeviceStatus GetBlindStatusByNum(LaneDeviceState ls, bool isLeft, int blindNum) {
            if (isLeft) {
                if (blindNum == 1) return ls.LeftBlindWatch1Status;
                if (blindNum == 2) return ls.LeftBlindWatch2Status;
                return ls.LeftBlindWatch3Status;
            } else {
                if (blindNum == 1) return ls.RightBlindWatch1Status;
                if (blindNum == 2) return ls.RightBlindWatch2Status;
                return ls.RightBlindWatch3Status;
            }
        }

        // 出发台已 Touched 期间又来事件 → 备用反应时（写日志 + 持久到 LaneResult.BackupReactionTimes）
        private void RecordBackupReaction(int lane, double time, string side) {
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer != null) {
                var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                if (result != null) result.BackupReactionTimes.Add((side ?? "?") + ":" + time.ToString("F3"));
            }
            AddLog(Loc.F("Str_Log_SbBackupReactionFmt",
                lane, side ?? "?", time));
        }

        // 盲表已 Touched 期间又来事件 → 备用盲表（写日志 + 持久到 LaneResult.BackupBlindTimes）
        private void RecordBackupBlind(int lane, int blindNum, double time) {
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer != null) {
                var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                if (result != null) result.BackupBlindTimes.Add(blindNum + ":" + time.ToString("F3"));
            }
            AddLog(Loc.F("Str_Log_BwBackupResultFmt",
                lane, blindNum, time));
        }

        // 触板"已触板（红）"窗口期内的额外触板：写日志 + 保存到 LaneResult.BackupTouchTimes（争议成绩）。
        private void RecordBackupTouch(int lane, double time) {
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) {
                AddLog(Loc.F("Str_Log_BackupResultNoSwimmerFmt", lane, TimeFormatter.Format(time)));
                return;
            }
            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                AddLog(Loc.F("Str_Log_BackupResultNoRecordFmt", lane, TimeFormatter.Format(time)));
                return;
            }
            result.BackupTouchTimes.Add(time);
            AddLog(Loc.F("Str_Log_TpBackupResultFmt",
                lane, swimmer.Name ?? "", TimeFormatter.Format(time),
                result.FinalTime > 0 ? TimeFormatter.Format(result.FinalTime) : "—"));
        }

        // 2026-06-06 跳圈 (= 操作员按 T 按钮右键): PC 立即推进 lap + 翻转 Direction, 不记任何时间.
        //   场景: 硬件无 TP/MB 信号 卡住状态机, 操作员按硬件控制盒手动 TP 按钮把硬件推进, 但 PC 不应记这"无成绩".
        //   行为: split.Time/CumulativeTime/TouchpadTime/ManualTouchTime 全 0, TimingSource = "Skipped".
        //         随后 10s 内到达的硬件 0x16 Touchpad 会被 ProcessTimingDataFromHardware 入口处丢弃 (=
        //         避免硬件控制盒手动键发的 0x16 再二次推进 PC).
        //         末段跳圈则 IsFinished=true 但 FinalTime=0, 等用户手工到 成绩与排名 页面补时间.
        private void ProcessSkipLapAdvanceOnly(int lane) {
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;
            if (laneState.IsFinished) {
                AddLog(Loc.F("Str_Log_LapSkipFinishedFmt", lane));
                return;
            }
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) { AddLog(Loc.F("Str_Log_LapSkipNoSwimmerFmt", lane)); return; }

            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                result = new LaneResult { EventName = _currentEvent, Stage = _currentStage, Heat = _currentHeat, Lane = lane };
                swimmer.Results.Add(result);
            }
            int totalLaps = GetTotalLaps();
            int currentLap = laneState.CurrentLap + 1;
            laneState.CurrentLap = currentLap;
            // 2026-06-14 跳圈也按侧计圈: 按本段奇偶推断该侧并 +1 (无硬件 side), 方向由该侧决定 (LapSideLogic)
            string skSide = LapSideLogic.InferSide(currentLap, _laneCloseSettings.StartPosition != "right");
            if (skSide == "left") laneState.LeftTouchDone++; else laneState.RightTouchDone++;

            SplitTime split = null;
            foreach (var sp in result.Splits) { if (sp.Lap == currentLap) { split = sp; break; } }
            if (split == null) {
                split = new SplitTime { Lap = currentLap, Distance = currentLap * _poolConfig.Length };
                result.Splits.Add(split);
            }
            split.Time = 0; split.CumulativeTime = 0;
            split.TouchpadTime = 0; split.ManualTouchTime = 0;
            split.PushButton1Time = 0; split.PushButton2Time = 0; split.PushButton3Time = 0;
            split.TimingSource = "Skipped";   // UI/导出 据此识别 "等手工输入"

            // 切方向 (= 由该侧决定, 与分段触板逻辑一致)
            laneState.Direction = LapSideLogic.DirectionFor(skSide);

            if (currentLap >= totalLaps) {
                laneState.IsFinished = true;
                result.FinalTime = 0; result.TimeInSeconds = 0; result.TimingSource = "Skipped";
                AddLog(Loc.F("Str_Log_LapSkipFinishNoTimeFmt", lane));
            } else {
                // 启动 LaneClose 倒计时 (= 分段触板路径一致)
                double targetSec = laneState.LaneCloseTime > 0 ? laneState.LaneCloseTime : _laneCloseSettings.LaneCloseTime;
                laneState.LaneCloseCountdown = targetSec;
                laneState.CountdownStartedAt = DateTime.Now;
                laneState.CountdownTargetSec = targetSec;
                AddLog(Loc.F("Str_Log_LapSkipNoSplitTimeFmt", lane, currentLap));
            }

            // 抑制窗口: 操作员紧跟按硬件手动 TP → 硬件发 0x16 → 在窗口内丢, 不二次推进 PC
            _skipNextHwTpUntil[lane] = DateTime.Now.AddSeconds(SKIP_HW_TP_WINDOW_SEC);

            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // 2026-06-06 终点 TP/MB 差异检测: 末段 TouchpadTime 与 PushButton1/2/3 中位数 差 > 0.5s 时,
        //   置 LaneDeviceState.FinishTpMbDispute=true → 终点端 TP + 3 MB 圆点全部标红, 直到 计时复位
        //   (ResetForNewRace) 才清. 该检测在 TP 入或 MB 入 后都要重复调用 (= 两边都到齐才能比较).
        //   Helper 自身幂等: 已经判定过 dispute 直接返回, 不重复刷日志.
        private const double FINISH_TP_MB_DISPUTE_THRESHOLD = 0.5;
        private void CheckFinalTpMbDispute(int lane) {
            try {
                var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (laneState == null || !laneState.IsFinished) return;
                if (laneState.FinishTpMbDispute) return;
                var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                    var sa = s.GetAssignmentForStage(_currentStage);
                    return (sa != null ? sa.Lane : s.Lane) == lane;
                });
                if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
                if (swimmer == null) return;
                var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                if (result == null) return;
                int totalLaps = GetTotalLaps();
                SplitTime finalSplit = null;
                foreach (var sp in result.Splits) {
                    if (sp.Lap == totalLaps) { finalSplit = sp; break; }
                }
                if (finalSplit == null || finalSplit.TouchpadTime <= 0) return;
                var blinds = new List<double>();
                if (finalSplit.PushButton1Time > 0) blinds.Add(finalSplit.PushButton1Time);
                if (finalSplit.PushButton2Time > 0) blinds.Add(finalSplit.PushButton2Time);
                if (finalSplit.PushButton3Time > 0) blinds.Add(finalSplit.PushButton3Time);
                if (blinds.Count == 0) return;
                blinds.Sort();
                // 2026-06-24 MB 算法: 1 个=自己, 2 个=平均 (千分位 floor), 3 个=真中位 (跟 DoMbSubstitute 一致)
                double mb;
                if (blinds.Count == 2) mb = Math.Floor((blinds[0] + blinds[1]) * 50.0) / 100.0;
                else                   mb = blinds[blinds.Count / 2];
                double diff = Math.Abs(finalSplit.TouchpadTime - mb);
                if (diff > FINISH_TP_MB_DISPUTE_THRESHOLD) {
                    laneState.FinishTpMbDispute = true;
                    AddLog(Loc.F("Str_Log_FinishTpMbDiffFmt",
                        lane, TimeFormatter.Format(finalSplit.TouchpadTime), TimeFormatter.Format(mb), diff, FINISH_TP_MB_DISPUTE_THRESHOLD));
                    UpdateLaneStatusDisplay();
                    Broadcast();
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_FinishTpMbDiffCheckFailedFmt", ex.Message)); }
        }

        private void ProcessTouchpadHit(int lane, double time, LaneDeviceState laneState, string side = null, bool isMbSubstitute = false, string forceSource = null) {
            // 2026-05-25 修复 #7: 移除"hold 过期就当新的 1 名"逻辑(会把 2/3 名触板时间也显示).
            // 1 名检测改到 split 保存后做 (见本函数末尾): 只在此泳道触板后是 当前 lap 最快 才更新滚动时间.

            // 2026-05-30 漂移补丁: 物理触板入口处清前一次 +/- 残留的 SB
            //   场景: 用户按 R▲ 让 SB=Open, 然后做物理触板, 物理触板路径不动 SB → SB 残留打开
            //   修法: 触板时立即关两端 SB. 后续 LaneCloseCountdown tick (5170+) 在交接点会重开 startPosition SB
            //   2026-06-04 接力赛跳过该补丁: 棒次倒计时 5743 已打开下棒 SB (= 绿),
            //     若触板时强制关会让交接前 SB 短暂变灰; 个人赛保留补丁.
            if (laneState != null && !_isRelay) {
                if (laneState.LeftStartBlockStatus != DeviceStatus.Broken && laneState.LeftStartBlockStatus != DeviceStatus.NotInstalled)
                    laneState.LeftStartBlockStatus = DeviceStatus.Closed;
                if (laneState.RightStartBlockStatus != DeviceStatus.Broken && laneState.RightStartBlockStatus != DeviceStatus.NotInstalled)
                    laneState.RightStartBlockStatus = DeviceStatus.Closed;
            }

            // 获取当前运动员（优先StageAssignment泳道号，兼容sw.Lane）
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) return;

            // 获取或创建成绩记录
            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                result = new LaneResult {
                    EventName = _currentEvent,
                    Stage = _currentStage,
                    Heat = _currentHeat,
                    Lane = lane
                };
                swimmer.Results.Add(result);
            }

            // 2026-06-14 成绩以触板为准: 真 TP 进入处理 → 取消该道待决的"盲表代替"宽限计时 (TP 优先于 MB)
            if (!isMbSubstitute) CancelPendingMbSubstitute(lane);

            // 计算分段
            int totalLaps = GetTotalLaps();
            // 2026-06-14 先定本次触板侧(不改状态), 用于封闭时间去抖. side 缺失(手动/盲代)按"下一段"奇偶推算.
            string touchSide = (side == "left" || side == "right") ? side
                : LapSideLogic.InferSide(laneState.CurrentLap + 1, _laneCloseSettings.StartPosition != "right");
            // 2026-06-14 同侧去抖 (学习硬件): 硬件对"串板/坏TP"(TP_Open_Close_State==3) 要求同侧距上次触板 ≥ Close_Time
            //   才算有效 (swimplay.c L2599/L2656); 正常触板则靠"已触板保持 ResultConfirmCloseDelay 秒"期间重复=备份.
            //   PC 用现有这两个参数(泳道关闭时间 / 成绩确认关闭延迟)取较大者作窗口: 窗口内同侧重复触板记备份不计圈.
            double closeWin = LapSideLogic.DebounceWindow(
                laneState.LaneCloseTime > 0 ? laneState.LaneCloseTime : _laneCloseSettings.LaneCloseTime,
                _laneCloseSettings.ResultConfirmCloseDelay);
            double prevSideT = (touchSide == "left") ? laneState.LeftLastTouchTime : laneState.RightLastTouchTime;
            if (LapSideLogic.IsRepeatWithinClose(time, prevSideT, closeWin)) {
                RecordBackupTouch(lane, time);
                // 2026-06-14 成绩以触板为准: 真 TP 落在去抖窗口内, 若当前段成绩源是 MB(自动盲表代替先占住),
                //   则用 TP 覆盖该段成绩(同段, 不推进圈数=不多计圈)。坏TP 同侧重复(段已是 TP)仍丢弃。
                if (!isMbSubstitute && laneState.CurrentLap > 0) {
                    SplitTime curSp = null;
                    foreach (var sp in result.Splits) { if (sp.Lap == laneState.CurrentLap) { curSp = sp; break; } }
                    if (curSp != null && curSp.TimingSource == "MB") {
                        double prevCumU = 0;
                        foreach (var sp in result.Splits) { if (sp.Lap == laneState.CurrentLap - 1) { prevCumU = sp.CumulativeTime; break; } }
                        curSp.TouchpadTime = time;
                        curSp.Time = time - prevCumU;
                        curSp.CumulativeTime = time;
                        curSp.TimingSource = "TP";
                        AddLog(Loc.F("Str_Log_TpOverridesMbFmt",
                            lane, laneState.CurrentLap, TimeFormatter.Format(time)));
                        if (laneState.IsFinished && laneState.CurrentLap >= totalLaps) {
                            result.TouchpadTime = time;
                            result.FinalTime = time;
                            result.TimeInSeconds = time;
                            result.TimingSource = "TP";
                            AddLog(Loc.F("Str_Log_FinishUsesTpFmt", lane, TimeFormatter.Format(time)));
                            UpdateHeatRanking();
                            CheckFinalTpMbDispute(lane);
                        }
                        UpdateLaneStatusDisplay();
                        Broadcast();
                        return;
                    }
                }
                AddLog(Loc.F("Str_Log_DuplicateTouchFmt",
                    lane, touchSide == "left" ? "左" : "右", time - prevSideT, closeWin));
                return;
            }
            int currentLap = laneState.CurrentLap + 1;
            laneState.CurrentLap = currentLap;
            // 严格按侧计圈: 只给本次实际触板侧 +1, 并记本侧计圈时刻(去抖用)
            if (touchSide == "left") { laneState.LeftTouchDone++; laneState.LeftLastTouchTime = time; }
            else { laneState.RightTouchDone++; laneState.RightLastTouchTime = time; }

            // 查找预创建的split（由PreCreateSplit在触板打开时创建）
            SplitTime split = null;
            foreach (var sp in result.Splits) {
                if (sp.Lap == currentLap) { split = sp; break; }
            }
            if (split == null) {
                // 兼容：如果没有预创建（比如50米第1段出发后直接触板），创建新的
                split = new SplitTime { Lap = currentLap, Distance = currentLap * _poolConfig.Length };
                result.Splits.Add(split);
            }

            // 计算上一段累计时间
            double prevCumulative = 0;
            foreach (var sp in result.Splits) {
                if (sp.Lap == currentLap - 1) { prevCumulative = sp.CumulativeTime; break; }
            }

            // 2026-06-03 优先级守卫: TP > MB > Manual > Input
            //   TP 来 → 总覆盖 (= 最高优先级)
            //   MB final 来 (isMbSubstitute=true) → 仅当 TimingSource != "TP" 时覆盖, 否则只存 MbFinalTime 留痕 + 回退 CurrentLap (= 防双增)
            if (isMbSubstitute && split.TimingSource == "TP") {
                // 已有 TP 主成绩, MB final 仅留痕到 MbFinalTime 字段
                split.MbFinalTime = time;
                laneState.CurrentLap = currentLap - 1;  // reverse 4319 行的 ++ (= 同段不再 increment)
                // 2026-06-14 撤销按侧 ++ 与去抖时刻 (本次未真正计圈)
                if (touchSide == "left") { laneState.LeftTouchDone--; laneState.LeftLastTouchTime = prevSideT; }
                else { laneState.RightTouchDone--; laneState.RightLastTouchTime = prevSideT; }
                AddLog(Loc.F("Str_Log_MbArrivesKeepsTpFmt", lane, currentLap, TimeFormatter.Format(time)));
                return;
            }
            // 填入触板数据到预创建的split中（盲表和手动可能已经写入了）
            split.Time = time - prevCumulative;
            split.CumulativeTime = time;
            split.TouchpadTime = time;
            // 2026-06-03 forceSource 优先 (= 手动 TP 当主成绩走此路径, 标 "Manual" 而非 "TP")
            split.TimingSource = forceSource ?? (isMbSubstitute ? "MB" : "TP");
            if (isMbSubstitute) split.MbFinalTime = time;
            // 如果手动/盲表还没写入split（在触板之前存到了laneState），补充写入
            if (split.ManualTouchTime <= 0) {
                double manualTime = Math.Max(laneState.LeftManualTouchTime, laneState.RightManualTouchTime);
                if (manualTime > prevCumulative) split.ManualTouchTime = manualTime;
            }
            if (split.PushButton1Time <= 0 && laneState.PendingBlind1Time > prevCumulative)
                split.PushButton1Time = laneState.PendingBlind1Time;
            if (split.PushButton2Time <= 0 && laneState.PendingBlind2Time > prevCumulative)
                split.PushButton2Time = laneState.PendingBlind2Time;
            if (split.PushButton3Time <= 0 && laneState.PendingBlind3Time > prevCumulative)
                split.PushButton3Time = laneState.PendingBlind3Time;

            // 清除暂存
            laneState.LeftManualTouchTime = 0;
            laneState.RightManualTouchTime = 0;
            laneState.PendingBlind1Time = 0;
            laneState.PendingBlind2Time = 0;
            laneState.PendingBlind3Time = 0;
            AddLog(Loc.F("Str_Log_LapSplitFmt", lane, currentLap,
                TimeFormatter.Format(split.Time), TimeFormatter.Format(time)));

            if (currentLap >= totalLaps) {
                // 最终到达 — 同步最终段的各计时源到LaneResult终点汇总
                laneState.IsFinished = true;
                result.TouchpadTime = split.TouchpadTime;
                result.PushButton1Time = split.PushButton1Time;
                result.PushButton2Time = split.PushButton2Time;
                result.PushButton3Time = split.PushButton3Time;
                result.FinalTime = time;
                result.TimeInSeconds = time;
                // 保存反应时间到成绩记录（关闭RT时不写入；抢跳为负值，0 表示未记录）
                if (_laneCloseSettings.ReactionTimeEnabled && laneState.ReactionTime != 0) {
                    result.StartingBlockTime = laneState.ReactionTime;
                }

                // 计时源裁定（使用最终段的各计时源数据）
                var judgement = TimingBridge.JudgeTimingSource(
                    split.TouchpadTime, split.PushButton1Time, split.PushButton2Time, split.PushButton3Time,
                    split.ManualTouchTime);
                result.FinalTime = judgement.FinalTime;
                result.TimingSource = judgement.Source;
                split.TimingSource = judgement.Source;

                // 终点圈：先把两端都置 Closed（清场），后面 EnterTouchedThenClose 会把
                // 真正"触板那一端"覆盖为 Touched（红）→ ResultConfirmCloseDelay 秒后再回到 Closed。
                laneState.LeftTouchpadStatus = DeviceStatus.Closed;
                laneState.RightTouchpadStatus = DeviceStatus.Closed;
                laneState.LaneCloseCountdown = 0;

                // 延迟关闭盲表（ResultConfirmCloseDelay秒后）
                int capLane3 = lane;
                var finishCloseTimer = new DispatcherTimer();
                finishCloseTimer.Interval = TimeSpan.FromSeconds(_laneCloseSettings.ResultConfirmCloseDelay);
                finishCloseTimer.Tick += delegate(object s3, EventArgs a3) {
                    finishCloseTimer.Stop();
                    var ls3 = _laneDeviceStates.FirstOrDefault(st => st.Lane == capLane3);
                    if (ls3 == null) return;
                    ls3.LeftBlindWatch1Status = DeviceStatus.Closed; ls3.LeftBlindWatch2Status = DeviceStatus.Closed; ls3.LeftBlindWatch3Status = DeviceStatus.Closed;
                    ls3.RightBlindWatch1Status = DeviceStatus.Closed; ls3.RightBlindWatch2Status = DeviceStatus.Closed; ls3.RightBlindWatch3Status = DeviceStatus.Closed;
                    ls3.LeftManualStatus = DeviceStatus.Closed; ls3.RightManualStatus = DeviceStatus.Closed;
                    Broadcast();
                };
                finishCloseTimer.Start();
                RegisterLaneCloseTimer(lane, finishCloseTimer);   // 2026-05-30 +/- 撤销时可取消

                AddLog(Loc.F("Str_Log_FinishedFmt", lane, TimeFormatter.Format(result.FinalTime), result.TimingSource));
                UpdateHeatRanking();
                CheckRecords(swimmer, result);
                // 注意：仅在 ConfirmResult_Click 才落盘，让裁判有机会修改/取消成绩

                // 2026-06-06 终点 TP/MB 差异检测 (TP 已到 → 若已收 MB 立刻标红; 没收齐 MB 时, 后续 ProcessBlindWatchData 再检)
                CheckFinalTpMbDispute(lane);

                // 检查是否所有泳道都完赛
                if (_laneDeviceStates.All(s => s.IsFinished || GetCurrentHeatSwimmers().All(sw => sw.Lane != s.Lane || sw.Status == "DNS"))) {
                    _raceState = RaceState.Finished;
                    UpdateRaceStateDisplay();
                    AddLog(Loc.T("Str_Log_HeatEnded"));
                }
            } else {
                // 分段触碰 — 方向由实际触板侧决定 (触左→朝右"→" / 触右→朝左"←"), 不再盲翻转; 开始新倒计时
                laneState.Direction = LapSideLogic.DirectionFor(touchSide);
                // 2026-05-25 修复时间漂移: 用 DateTime 锚点
                double targetSec = laneState.LaneCloseTime > 0 ? laneState.LaneCloseTime : _laneCloseSettings.LaneCloseTime;
                laneState.LaneCloseCountdown = targetSec;
                laneState.CountdownStartedAt = DateTime.Now;
                laneState.CountdownTargetSec = targetSec;

                // 接力项目：交接棒触板触碰后，延迟关闭出发台
                if (_isRelay) {
                    int totalLapsVal2 = GetTotalLaps();
                    int legCnt2 = 4;
                    var rlMatch2 = System.Text.RegularExpressions.Regex.Match(_currentEvent, @"(\d+)\s*[x×]");
                    if (rlMatch2.Success) legCnt2 = int.Parse(rlMatch2.Groups[1].Value);
                    int lapsPerLeg2 = totalLapsVal2 > 0 ? totalLapsVal2 / legCnt2 : 1;
                    bool isExchange = (lapsPerLeg2 > 0) && (currentLap % lapsPerLeg2 == 0) && (currentLap < totalLapsVal2);

                    if (isExchange) {
                        // 交接棒触板已触碰，延迟后关闭出发台
                        //   2026-06-03 关哪侧 SB: 触板后 Direction 已反转, 用反转后判 (= "→" 表示刚到 left, 即下棒在 left 起跳, 关 LeftSB).
                        //   适用 4×50m 棒次交替, 4×100m 时到达侧总=StartPosition 行为不变.
                        bool capCloseLeft = laneState.Direction == "→";
                        int capLane2 = lane;
                        var sbCloseTimer = new DispatcherTimer();
                        sbCloseTimer.Interval = TimeSpan.FromSeconds(_laneCloseSettings.StartBlockCloseDelay);
                        sbCloseTimer.Tick += delegate(object s4, EventArgs a4) {
                            sbCloseTimer.Stop();
                            var ls2 = _laneDeviceStates.FirstOrDefault(st => st.Lane == capLane2);
                            if (ls2 == null || ls2.IsFinished) return;
                            if (capCloseLeft) ls2.LeftStartBlockStatus = DeviceStatus.Closed;
                            else ls2.RightStartBlockStatus = DeviceStatus.Closed;
                            Broadcast();
                        };
                        sbCloseTimer.Start();
                        RegisterLaneCloseTimer(lane, sbCloseTimer);   // 2026-05-30 +/- 撤销时可取消
                        AddLog(Loc.F("Str_Log_RelayTakeoverTouchFmt", lane, _laneCloseSettings.StartBlockCloseDelay));
                    }
                }

                // 触板：由调用方 EnterTouchedThenClose 把到达端切到"已触板（红）"，
                // 到点 ResultConfirmCloseDelay 后再转 Closed。这里只处理"该端的盲表/手动按钮"延迟关闭。
                string arrivedEnd = touchSide;   // 2026-06-14 用实际触板侧 (= 关该侧盲表/手动)
                var closeTimer = new DispatcherTimer();
                closeTimer.Interval = TimeSpan.FromSeconds(_laneCloseSettings.ResultConfirmCloseDelay);
                closeTimer.Tick += delegate(object s2, EventArgs a2) {
                    closeTimer.Stop();
                    if (laneState.IsFinished) return;
                    if (arrivedEnd == "right") {
                        laneState.RightBlindWatch1Status = DeviceStatus.Closed; laneState.RightBlindWatch2Status = DeviceStatus.Closed; laneState.RightBlindWatch3Status = DeviceStatus.Closed;
                        laneState.RightManualStatus = DeviceStatus.Closed;
                    } else {
                        laneState.LeftBlindWatch1Status = DeviceStatus.Closed; laneState.LeftBlindWatch2Status = DeviceStatus.Closed; laneState.LeftBlindWatch3Status = DeviceStatus.Closed;
                        laneState.LeftManualStatus = DeviceStatus.Closed;
                    }
                    Broadcast();
                };
                closeTimer.Start();
            }

            // 2026-05-26 v3 修复: 用户明确"只有第1名运动员触板，其成绩才要停留显示".
            //   1 名判定: count desc + finished=9999 + rank 小 tiebreak + lastCum 小兜底 (与 display.html 同算).
            //   触发条件: 触板这条道 == 1 名 swimmer 所在道 → 更新, 显示该 1 名自己的最新累计时间.
            //   非 1 名触板 → 不动 _firstPlaceShowStart, 让 RaceTimer_Tick 继续按 holdSec 窗口显示上次 1 名时间 / 滚动时间.
            //   停留时长 = FirstPlaceHoldTime (参数: 第 1 名成绩显示时间).
            try {
                Swimmer leaderSw = null;
                int leaderCount = 0;
                double leaderLastCum = 0;
                int leaderRank = int.MaxValue;
                foreach (var sw in GetCurrentHeatSwimmers()) {
                    if (sw.Status == "DSQ" || sw.Status == "DNS" || sw.Status == "DNF") continue;
                    var rs = sw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                    if (rs == null) continue;
                    int cnt = 0;
                    double lastCum = 0;
                    foreach (var sp in rs.Splits) {
                        if (sp.CumulativeTime > 0) { cnt++; if (sp.CumulativeTime > lastCum) lastCum = sp.CumulativeTime; }
                    }
                    if (cnt == 0) continue;
                    bool isFinished = rs.FinalTime > 0;
                    int effCount = isFinished ? 9999 : cnt;
                    int rk = rs.Rank > 0 ? rs.Rank : int.MaxValue;
                    bool better;
                    if (leaderSw == null) better = true;
                    else if (effCount > leaderCount) better = true;
                    else if (effCount == leaderCount) {
                        if (rk < leaderRank) better = true;
                        else if (rk == leaderRank && lastCum > 0 && (leaderLastCum == 0 || lastCum < leaderLastCum)) better = true;
                        else better = false;
                    } else better = false;
                    if (better) {
                        leaderSw = sw;
                        leaderCount = effCount;
                        leaderLastCum = isFinished ? rs.FinalTime : lastCum;
                        leaderRank = rk;
                    }
                }
                if (leaderSw != null && leaderLastCum > 0) {
                    var saLeader = leaderSw.GetAssignmentForStage(_currentStage);
                    int leaderLaneNum = (saLeader != null && saLeader.Lane > 0) ? saLeader.Lane : leaderSw.Lane;
                    // 只有 1 名触板才更新; 非 1 名触板完全不动滚动时间区
                    if (leaderLaneNum == lane) {
                        _firstPlaceFinishTime = TimeFormatter.Format(leaderLastCum);
                        _firstPlaceShowStart = DateTime.Now;
                        if (RunningTimeText != null) {
                            RunningTimeText.Text = _firstPlaceFinishTime;
                            RunningTimeText.Foreground = _firstPlaceBrush;
                        }
                    }
                }
            } catch { }
        }

        /// <summary>
        /// 查找当前段的split记录（预创建的或已完成的）
        /// 触板打开后、触板触碰前：targetLap = CurrentLap + 1（预创建的空split）
        /// 触板触碰后：targetLap = CurrentLap（已填入触板数据的split）
        /// </summary>
        private SplitTime FindCurrentSplit(int lane) {
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return null;

            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) return null;

            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null || result.Splits.Count == 0) return null;

            // 返回最后一个split（预创建的或最近完成的）
            // 因为预创建的split总是在最后面，且是当前段
            return result.Splits.Last();
        }

        private void SaveManualTouchToSplit(int lane, double time, string side = null) {
            // 2026-06-03 手动 TP 应急规则:
            //   - 当前段已有 TP/MB → 仅记 split.ManualTouchTime 备份, 不动主成绩
            //   - 当前段没 TP/MB → 走 ProcessTouchpadHit 完整流程 (= 推 currentLap + 减 laps + 完赛检查 + 切 Lane_Display_State), 让比赛进行下去
            // 2026-06-14 "手动TP代替真TP"开关(ManualTpReplaceTp): 开 → 即使该段已有真 TP, 手动 TP 也覆盖之 (用手动时间改写该段主成绩为 TP);
            //   关(默认) → 维持上述应急规则 (已有 TP/MB 时手动 TP 只记备份)。
            var existingSplit = FindCurrentSplit(lane);
            bool manualReplaceTp = _laneCloseSettings != null && _laneCloseSettings.ManualTpReplaceTp;
            // 开关开启 且 该段已是真 TP 主成绩 → 用手动 TP 覆盖该段 (同段, 不推进圈数)
            if (manualReplaceTp && existingSplit != null && existingSplit.TimingSource == "TP") {
                double prevCum = 0;
                var swR = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                    var sa = s.GetAssignmentForStage(_currentStage);
                    return (sa != null ? sa.Lane : s.Lane) == lane;
                });
                if (swR == null) swR = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
                var resR = swR != null ? swR.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat) : null;
                if (resR != null) {
                    foreach (var sp in resR.Splits) { if (sp.Lap == existingSplit.Lap - 1) { prevCum = sp.CumulativeTime; break; } }
                }
                existingSplit.TouchpadTime = time;
                existingSplit.ManualTouchTime = time;
                existingSplit.Time = time - prevCum;
                existingSplit.CumulativeTime = time;
                existingSplit.TimingSource = "Manual";
                AddLog(Loc.F("Str_Log_ManualTpOverrideFmt", lane, existingSplit.Lap, TimeFormatter.Format(time)));
                var lsR = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (lsR != null && lsR.IsFinished && resR != null) {
                    int totalLapsR = GetTotalLaps();
                    if (existingSplit.Lap >= totalLapsR) {
                        resR.TouchpadTime = time; resR.FinalTime = time; resR.TimeInSeconds = time; resR.TimingSource = "Manual";
                        UpdateHeatRanking();
                    }
                }
                UpdateLaneStatusDisplay();
                Broadcast();
                return;
            }
            bool alreadyHasMainResult = existingSplit != null && !string.IsNullOrEmpty(existingSplit.TimingSource)
                && (existingSplit.TimingSource == "TP" || existingSplit.TimingSource == "MB");
            if (alreadyHasMainResult) {
                // 已有 TP/MB 主成绩, 手动 TP 仅记备份
                existingSplit.ManualTouchTime = time;
                SyncSplitToResultIfFinished(lane, existingSplit);
                return;
            }
            // 没 TP/MB → 走完整触板流程, 让比赛进行
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;
            ProcessTouchpadHit(lane, time, laneState, side, false, "Manual");   // 2026-06-14 手动应急: 传真实左/右侧按侧计圈
            // ManualTouchTime 也存 (= 兼容现有 UI 显示)
            var newSplit = FindCurrentSplit(lane);
            if (newSplit != null) {
                newSplit.ManualTouchTime = time;
                SyncSplitToResultIfFinished(lane, newSplit);
            }
        }

        /// <summary>
        /// 已完赛时，将最终段split的计时数据同步到result终点汇总
        /// </summary>
        private void SyncSplitToResultIfFinished(int lane, SplitTime split) {
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null || !laneState.IsFinished) return;

            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) return;

            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) return;

            // 同步最终段的各计时源到result
            if (split.TouchpadTime > 0) result.TouchpadTime = split.TouchpadTime;
            if (split.PushButton1Time > 0) result.PushButton1Time = split.PushButton1Time;
            if (split.PushButton2Time > 0) result.PushButton2Time = split.PushButton2Time;
            if (split.PushButton3Time > 0) result.PushButton3Time = split.PushButton3Time;
        }

        private void ProcessBlindWatchData(int lane, string cmdType, double time, string side = null) {
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) return;

            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                result = new LaneResult {
                    EventName = _currentEvent,
                    Stage = _currentStage,
                    Heat = _currentHeat,
                    Lane = lane
                };
                swimmer.Results.Add(result);
            }

            // 保存到LaneResult总记录（终点汇总）
            switch (cmdType) {
                case "PushButton1": result.PushButton1Time = time; break;
                case "PushButton2": result.PushButton2Time = time; break;
                case "PushButton3": result.PushButton3Time = time; break;
            }

            // 保存到当前段的split（预创建的split在触板打开时已存在）
            var targetSplit = FindCurrentSplit(lane);
            if (targetSplit != null) {
                switch (cmdType) {
                    case "PushButton1": targetSplit.PushButton1Time = time; break;
                    case "PushButton2": targetSplit.PushButton2Time = time; break;
                    case "PushButton3": targetSplit.PushButton3Time = time; break;
                }
                // 如果已完赛，同步到result终点汇总
                SyncSplitToResultIfFinished(lane, targetSplit);
                // 2026-06-06 终点 TP/MB 差异检测 (MB 后到的场景: TP 先到时还无 MB, 此处补检)
                CheckFinalTpMbDispute(lane);
            } else {
                // 备用：预创建split不存在时暂存到laneState
                var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (laneState != null) {
                    switch (cmdType) {
                        case "PushButton1": laneState.PendingBlind1Time = time; break;
                        case "PushButton2": laneState.PendingBlind2Time = time; break;
                        case "PushButton3": laneState.PendingBlind3Time = time; break;
                    }
                }
            }
            AddLog(Loc.F("Str_Log_LaneCmdTimeFmt", lane, cmdType, TimeFormatter.Format(time)));

            // 2026-06-14 PC 端 "盲表代替触板" 开关 — 按硬件模型: 成绩以触板为准。
            //   MB 到达不立即代替, 而是启动"成绩确认关闭延迟"宽限计时; 窗口内 TP 到达 → 记 TP 并取消代替(TP 优先);
            //   窗口到期仍无 TP → 用盲表中位数代替。延迟=0 时近乎立即代替。(旧版 MB 一到就立即代替, 会抢在 TP 前面)
            if (_laneCloseSettings != null && _laneCloseSettings.AutoBlindReplaceTouchpad) {
                try {
                    var stateA = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                    var splitA = FindCurrentSplit(lane);
                    if (stateA != null && !stateA.IsFinished && splitA != null && splitA.TouchpadTime <= 0
                        && (splitA.PushButton1Time > 0 || splitA.PushButton2Time > 0 || splitA.PushButton3Time > 0)) {
                        // 2026-06-14 接力: 仅在当前棒预期完成侧才安排代替 (= 与 Touchpad case 4297 守卫一致, 防右 MB 误代替左棒)
                        bool relaySideOk = true;
                        if (_isRelay && _laneCloseSettings != null && (side == "left" || side == "right")) {
                            int afterLapMb = stateA.CurrentLap + 1;
                            string startSideMb = _laneCloseSettings.StartPosition;
                            string expectedSideMb = (afterLapMb % 2 == 0) ? startSideMb : (startSideMb == "left" ? "right" : "left");
                            relaySideOk = (side == expectedSideMb);
                        }
                        if (relaySideOk) ScheduleMbSubstitute(lane, side);
                    }
                } catch (Exception exA) { AddLog(Loc.F("Str_Log_BwAutoSubFailedFmt", exA.Message)); }
            }
        }

        // 2026-06-14 成绩以触板为准 — "盲表代替触板"宽限计时 (= 硬件"成绩确认关闭延迟"模型):
        //   首个盲表(或SB)到达即起计时 (谁先到谁起, 已在计时则不重启); 窗口内 TP 到达由 ProcessTouchpadHit
        //   取消本计时 → 以 TP 为准; 到期仍无 TP 才用盲表中位代替。延迟参数=0 时近乎立即代替。
        private void ScheduleMbSubstitute(int lane, string side) {
            if (_pendingMbSubTimers.ContainsKey(lane)) return;   // 已在计时 → 以首个信号为起点, 不重启
            double grace = _laneCloseSettings != null ? _laneCloseSettings.ResultConfirmCloseDelay : 3;
            if (grace < 0) grace = 0;
            var t = new DispatcherTimer { Interval = TimeSpan.FromSeconds(grace) };
            string capSide = side;
            int capLane = lane;
            t.Tick += delegate(object s, EventArgs e) {
                t.Stop();
                _pendingMbSubTimers.Remove(capLane);
                try { DoMbSubstitute(capLane, capSide); } catch (Exception ex) { AddLog(Loc.F("Str_Log_MbSubFailedFmt", ex.Message)); }
            };
            _pendingMbSubTimers[lane] = t;
            t.Start();
        }

        // 取消该道待决的"盲表代替"宽限计时 (= 该道真 TP 已到, TP 优先)
        private void CancelPendingMbSubstitute(int lane) {
            DispatcherTimer t;
            if (_pendingMbSubTimers.TryGetValue(lane, out t)) { try { t.Stop(); } catch { } _pendingMbSubTimers.Remove(lane); }
        }

        // 宽限到期回调: 若该段仍无 TP 且有盲表 → 取盲表中位数代替触板 (标 MB)。期间 TP 已到则不代替。
        private void DoMbSubstitute(int lane, string side) {
            var state = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (state == null || state.IsFinished) return;
            var split = FindCurrentSplit(lane);
            if (split == null || split.TouchpadTime > 0) return;   // 期间 TP 已到 → 不代替 (TP 优先)
            var blinds = new List<double>();
            if (split.PushButton1Time > 0) blinds.Add(split.PushButton1Time);
            if (split.PushButton2Time > 0) blinds.Add(split.PushButton2Time);
            if (split.PushButton3Time > 0) blinds.Add(split.PushButton3Time);
            if (blinds.Count == 0) return;
            blinds.Sort();
            // 2026-06-24 MB 代 TP 算法: 1 个=自己, 2 个=平均, 3 个=真中位 (含两同自然取相同值).
            //   2 个时 (a+b)/2 会引入千分位 → 按硬规则 floor 到百分位 (= 禁止四舍五入).
            double med;
            string algo;
            if (blinds.Count == 2) { med = Math.Floor((blinds[0] + blinds[1]) * 50.0) / 100.0; algo = "平均"; }
            else                   { med = blinds[blinds.Count / 2];                              algo = "中位"; }
            AddLog(Loc.F("Str_Log_ConfirmDelayMbSubFmt", lane, algo, TimeFormatter.Format(med), blinds.Count));
            ProcessTouchpadHit(lane, med, state, side, true);   // isMbSubstitute=true, 标 MB
        }

        // 2026-06-06 P2-A: 热路径 (ProcessTouchpadHit / CountdownTimer_Tick / GetLapDisplayMaxForSide …)
        //   每秒调 10-15 次 GetTotalLaps. 原 static Regex.Match 走默认 cache (≤15 条), 但每次都构造
        //   Match 对象 + 解析字符串. 改 static readonly Compiled Regex 复用 + 加入参 → 结果 1-tick 缓存,
        //   省 95% 的 Match 调用.
        private static readonly System.Text.RegularExpressions.Regex _relayDistanceRegex =
            new System.Text.RegularExpressions.Regex(@"(\d+)\s*[x×]\s*(\d+)", System.Text.RegularExpressions.RegexOptions.Compiled);
        private static readonly System.Text.RegularExpressions.Regex _singleDistanceRegex =
            new System.Text.RegularExpressions.Regex(@"(\d+)米", System.Text.RegularExpressions.RegexOptions.Compiled);
        private string _totalLapsCacheKey = null;
        private int _totalLapsCacheVal = 1;
        private int GetTotalLaps() {
            string ev = _currentEvent ?? "";
            int poolLen = _poolConfig != null ? _poolConfig.Length : 50;
            string key = ev + "|" + poolLen;
            if (key == _totalLapsCacheKey) return _totalLapsCacheVal;

            int distance = 0;
            // 接力项目：4x100米 → 总距离 = 4 * 100 = 400
            if (ev.IndexOf('x') >= 0 || ev.IndexOf('×') >= 0) {
                var relayMatch = _relayDistanceRegex.Match(ev);
                if (relayMatch.Success) {
                    int legs = int.Parse(relayMatch.Groups[1].Value);
                    int legDist = int.Parse(relayMatch.Groups[2].Value);
                    distance = legs * legDist;
                }
            }
            // 个人项目：直接取第一个数字
            if (distance == 0) {
                var distMatch = _singleDistanceRegex.Match(ev);
                if (distMatch.Success) distance = int.Parse(distMatch.Groups[1].Value);
            }
            if (distance == 0) distance = 50;
            int laps = Math.Max(1, distance / poolLen);
            _totalLapsCacheKey = key;
            _totalLapsCacheVal = laps;
            return laps;
        }

        /// <summary>
        /// 计算某道左/右触板剩余次数
        /// isLeft=true: 出发端(左端)触板剩余; isLeft=false: 到达端(右端)触板剩余
        /// 出发方向由设置决定，这里假设startPosition决定出发端
        /// </summary>
        // 圈数显示上限：按比赛项目实际设定的"该侧触板次数"。
        // 50m(1 段)：出发端 0 次，到达端 1 次；100m(2 段)：双侧各 1 次；
        // 150m(3 段)：出发端 1、到达端 2；200m(4 段)：双侧各 2 次；以此类推。
        private int GetLapDisplayMaxForSide(bool isLeft) {
            int totalLaps = GetTotalLaps();
            if (totalLaps <= 0) return int.MaxValue;
            int startSideTotal, farSideTotal;
            if (totalLaps == 1) { startSideTotal = 0; farSideTotal = 1; }
            else { startSideTotal = totalLaps / 2; farSideTotal = (totalLaps + 1) / 2; }
            bool startFromLeft = _laneCloseSettings.StartPosition != "right";
            if (startFromLeft) return isLeft ? startSideTotal : farSideTotal;
            return isLeft ? farSideTotal : startSideTotal;
        }

        //2026-05-29 手动调整某道圈数 — 容错版 D (4 道防线 + 接力 SB 推算)
        //  规则:
        //   ▼ (delta=-1, 剩余 -1) = 模拟一次触板 (漏触补救): 物理上 = 完成第 newCur 圈触板
        //   ▲ (delta=+1, 剩余 +1) = 撤销一次触板 (误触回退): 物理上 = 撤销第 oldCur 圈触板
        //  4 道防线 (任一失败 → 弹窗 + 拒绝执行, 保证状态永远跟物理一致):
        //   防线 1: 该侧剩余范围 [0, maxDisp]
        //   防线 2: CurrentLap 范围 [0, totalLaps]
        //   防线 3: isLeft 一致性 (用户按的 spinner 端 = 物理触板端 = (StartPosition + 圈号奇偶) 推算)
        //   防线 4: 比赛进行中圈数清零二次确认
        //  通过后:
        //   - 5/27 落地: CurrentLap += -actualDelta, Direction 翻转, LapManualAdjust 归零
        //   - TP+MB+T:  ▼ 关 userSide / 开 otherSide;  ▲ 开 userSide / 关 otherSide  (T 不动 — 用户要求)
        //   - SB:  接力 + newCur 是棒次切换点 → 开 isLeft 侧 (已 verify = 物理触板端);  否则不动
        //   - Split: ▲ 软删最近
        //   - 倒计时清零
        //   - 发硬件 0x61 (d3/d4/d5 + d6=1/2 + d7=0/1/2)
        private void AdjustLapDisplay(int lane, bool isLeft, int delta) {
            var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (ls == null) return;

            // 2026-05-30 硬件未连接弹窗 (圈数 +/- spinner)
            if (!EnsureHardwareConnected(Loc.F("Str_Action_LaneLapDeltaFmt", lane, delta > 0 ? "+" : "-"))) return;

            // 2026-05-29 重构: 防线 1-4 / SB / TP+MB / direction 推算全部下放给 LapAdjustLogic.Compute,
            // 跟 LapTestSim 测试程序同源. 这里只负责: 收集输入 → 弹窗 / 落地 UI / 发硬件.
            int totalLaps = GetTotalLaps();
            var input = new LapAdjustInput {
                TotalLaps = totalLaps,
                StartPosition = _laneCloseSettings.StartPosition,
                IsRelay = _isRelay,
                LapsPerLeg = _isRelay ? (totalLaps / 4) : 0,
                RaceIsRacing = (_raceState == RaceState.Racing),
                OldCurrentLap = ls.CurrentLap,
                OldLeftRemain = GetDisplayedLapCount(ls, true),
                OldRightRemain = GetDisplayedLapCount(ls, false),
                LeftMaxDisp = GetLapDisplayMaxForSide(true),
                RightMaxDisp = GetLapDisplayMaxForSide(false),
                IsLeft = isLeft,
                Delta = delta,
                ConfirmAfterRacingZero = false,
            };
            var result = LapAdjustLogic.Compute(input);

            // 防线 4: 弹 YesNo, 通过则用 ConfirmAfterRacingZero=true 重算
            if (result.Verdict == LapAdjustVerdict.Defense4_NeedConfirm) {
                int oldCur = ls.CurrentLap;
                var r = AppMessageBox.Show(
                    Loc.F("Str_Msg_LaneErrorFmt", lane, result.ErrorMessage),
                    result.ErrorTitle,
                    MessageBoxButton.YesNo, MessageBoxImage.Warning);
                if (r != MessageBoxResult.Yes) {
                    AddLog(Loc.F("Str_Log_LapClearCancelledFmt", lane, oldCur));
                    return;
                }
                AddLog(Loc.F("Str_Log_LapClearConfirmedFmt", lane, oldCur));
                input.ConfirmAfterRacingZero = true;
                result = LapAdjustLogic.Compute(input);
            }

            // 防线 1/2/3: 弹窗 + 日志 + 取消
            if (result.Verdict == LapAdjustVerdict.Defense1_DispOutOfRange
                || result.Verdict == LapAdjustVerdict.Defense2_LapOutOfRange
                || result.Verdict == LapAdjustVerdict.Defense3_WrongSpinner) {
                AppMessageBox.Show(
                    Loc.F("Str_Msg_LaneErrorFmt", lane, result.ErrorMessage),
                    result.ErrorTitle,
                    MessageBoxButton.OK, MessageBoxImage.Warning);
                AddLog(Loc.F("Str_Log_LaneMsgFmt", lane, result.LogMessage));
                return;
            }
            if (result.Verdict == LapAdjustVerdict.NoChange) return;

            // ===== Ok: 落地 =====
            int oldCurForRollback = ls.CurrentLap;
            ls.CurrentLap = result.NewCurrentLap;
            // 2026-06-14 同步按侧计数: 该侧已触次数 -= actualDelta (剩余变化=actualDelta → 已触变化=-actualDelta), 保持与按侧剩余一致
            if (isLeft) ls.LeftTouchDone -= result.ActualDelta;
            else ls.RightTouchDone -= result.ActualDelta;
            if (ls.LeftTouchDone < 0) ls.LeftTouchDone = 0;
            if (ls.RightTouchDone < 0) ls.RightTouchDone = 0;
            ls.Direction = result.Direction;   // 2026-05-30: 派生于 open_side (= 物理游动方向, 跟 web sw.direction 一致, 跟硬件 ">>>/<<<" 反向)
            ls.LeftLapManualAdjust = 0;
            ls.RightLapManualAdjust = 0;

            ForceOpenSideTpMb(ls, result.OpenTpMbSide);
            ForceCloseSideTpMb(ls, result.CloseTpMbSide);

            // SB: result.SbOpenSide 0=都关 / 1=开左 / 2=开右 (个人赛恒 0)
            if (result.SbOpenSide == 1) {
                SetSideStartBlock(ls, "left",  DeviceStatus.Open);
                SetSideStartBlock(ls, "right", DeviceStatus.Closed);
            } else if (result.SbOpenSide == 2) {
                SetSideStartBlock(ls, "right", DeviceStatus.Open);
                SetSideStartBlock(ls, "left",  DeviceStatus.Closed);
            } else {
                SetSideStartBlock(ls, "left",  DeviceStatus.Closed);
                SetSideStartBlock(ls, "right", DeviceStatus.Closed);
            }

            if (result.ShouldDeleteLastSplit) MarkLastSplitDeleted(lane);

            ls.LaneCloseCountdown = 0;
            ls.CountdownStartedAt = default(DateTime);
            ls.CountdownTargetSec = 0;

            //2026-05-30 漂移补丁:
            //   #5 Cancel finishCloseTimer / sbCloseTimer 防 fire 关掉刚 open 的设备
            //   #3 清 PendingBlind1/2/3Time 跟硬件 MB_Result 清同源 (case Set_LapRemaining 6422-6429)
            //   #1 IsFinished 回退 (▲ 撤销 oldCur=totalLaps 时), 同步把 _raceState 拉回 Racing
            //   #4 ReactionTime 清 (newCur=0 起跑前)
            CancelLaneCloseTimers(lane);
            ls.PendingBlind1Time = 0;
            ls.PendingBlind2Time = 0;
            ls.PendingBlind3Time = 0;
            if (oldCurForRollback == input.TotalLaps && result.NewCurrentLap < input.TotalLaps) {
                if (ls.IsFinished) {
                    ls.IsFinished = false;
                    AddLog(Loc.F("Str_Log_RevertFinishFmt", lane, oldCurForRollback, result.NewCurrentLap));
                }
                if (_raceState == RaceState.Finished) {
                    _raceState = RaceState.Racing;
                    UpdateRaceStateDisplay();
                    AddLog(Loc.T("Str_Log_RevertFinishToRacing"));
                }
            }
            if (result.NewCurrentLap == 0) {
                ls.ReactionTime = 0;
                ls.IsSuspectFalseStart = false;
                ls.IsFalseStart = false;
            }

            AddLog(Loc.F("Str_Log_LaneMsgFmt", lane, result.LogMessage));
            UpdateLaneStatusDisplay();
            try {
                if (_timingBridge != null && _timingBridge.IsConnected)
                    _timingBridge.SendLapRemaining(LaneToHwIndex(lane), isLeft, result.NewDispThis, result.OpenAction, result.SbOpenSide);
            } catch { }
            Broadcast();
        }

        //2026-05-29 强制打开某端 TP + 盲表 1/2/3 (跳过 Broken/NotInstalled), 不动 T 手动按键, 不动 SB
        private void ForceOpenSideTpMb(LaneDeviceState ls, string side) {
            if (ls == null || string.IsNullOrEmpty(side)) return;
            System.Action<System.Func<DeviceStatus>, System.Action<DeviceStatus>> setOpen = (getter, setter) => {
                var s = getter();
                if (s != DeviceStatus.Broken && s != DeviceStatus.NotInstalled) setter(DeviceStatus.Open);
            };
            if (side == "left") {
                setOpen(() => ls.LeftTouchpadStatus,    v => ls.LeftTouchpadStatus = v);
                setOpen(() => ls.LeftBlindWatch1Status, v => ls.LeftBlindWatch1Status = v);
                setOpen(() => ls.LeftBlindWatch2Status, v => ls.LeftBlindWatch2Status = v);
                setOpen(() => ls.LeftBlindWatch3Status, v => ls.LeftBlindWatch3Status = v);
                // LeftManualStatus / LeftStartBlockStatus 不动
            } else if (side == "right") {
                setOpen(() => ls.RightTouchpadStatus,    v => ls.RightTouchpadStatus = v);
                setOpen(() => ls.RightBlindWatch1Status, v => ls.RightBlindWatch1Status = v);
                setOpen(() => ls.RightBlindWatch2Status, v => ls.RightBlindWatch2Status = v);
                setOpen(() => ls.RightBlindWatch3Status, v => ls.RightBlindWatch3Status = v);
                // RightManualStatus / RightStartBlockStatus 不动
            }
        }

        //2026-05-29 强制关闭某端 TP + 盲表 1/2/3 (跳过 Broken/NotInstalled), 不动 T, 不动 SB
        private void ForceCloseSideTpMb(LaneDeviceState ls, string side) {
            if (ls == null || string.IsNullOrEmpty(side)) return;
            System.Action<System.Func<DeviceStatus>, System.Action<DeviceStatus>> setClosed = (getter, setter) => {
                var s = getter();
                if (s != DeviceStatus.Broken && s != DeviceStatus.NotInstalled) setter(DeviceStatus.Closed);
            };
            if (side == "left") {
                setClosed(() => ls.LeftTouchpadStatus,    v => ls.LeftTouchpadStatus = v);
                setClosed(() => ls.LeftBlindWatch1Status, v => ls.LeftBlindWatch1Status = v);
                setClosed(() => ls.LeftBlindWatch2Status, v => ls.LeftBlindWatch2Status = v);
                setClosed(() => ls.LeftBlindWatch3Status, v => ls.LeftBlindWatch3Status = v);
            } else if (side == "right") {
                setClosed(() => ls.RightTouchpadStatus,    v => ls.RightTouchpadStatus = v);
                setClosed(() => ls.RightBlindWatch1Status, v => ls.RightBlindWatch1Status = v);
                setClosed(() => ls.RightBlindWatch2Status, v => ls.RightBlindWatch2Status = v);
                setClosed(() => ls.RightBlindWatch3Status, v => ls.RightBlindWatch3Status = v);
            }
        }

        //2026-05-29 单独设某侧 StartBlock 状态 (Open / Closed), 跳过 Broken / NotInstalled
        private void SetSideStartBlock(LaneDeviceState ls, string side, DeviceStatus status) {
            if (ls == null || string.IsNullOrEmpty(side)) return;
            if (side == "left") {
                if (ls.LeftStartBlockStatus != DeviceStatus.Broken && ls.LeftStartBlockStatus != DeviceStatus.NotInstalled)
                    ls.LeftStartBlockStatus = status;
            } else if (side == "right") {
                if (ls.RightStartBlockStatus != DeviceStatus.Broken && ls.RightStartBlockStatus != DeviceStatus.NotInstalled)
                    ls.RightStartBlockStatus = status;
            }
        }

        //2026-05-30 硬件未连接弹窗提示 (用户主动操作时调用)
        //   v2: 加 "本次会话不再提醒" CheckBox, 重连后自动清抑制
        //   严格版 EnsureHardwareConnected: 没连接 → 返回 false (调用方 return) — 用于 A 类比赛控制按钮
        //   软版 WarnIfHardwareNotConnected: 没连接 → 弹软警告, 不影响流程 — 用于 TimingSettings 等可离线场景
        private bool _suppressHwDisconnectWarning = false;

        //2026-05-30 v2 自定义弹窗, 含 "不再提醒" CheckBox
        //   抑制标志 _suppressHwDisconnectWarning = true 时不再弹窗 (但 EnsureHardwareConnected 仍返回 false)
        //   OnStatusChanged 检测硬件重连时清抑制 (= 用户重新需要看到提醒)
        private void ShowHwDisconnectWarning(string actionName, bool isStrict) {
            if (_suppressHwDisconnectWarning) return;
            try {
                var win = new Window {
                    Title = Loc.T("Str_MsgTitle_HwNotConnectedPopup"),
                    Width = 480, Height = 220,
                    WindowStartupLocation = WindowStartupLocation.CenterOwner,
                    Owner = this,
                    ResizeMode = ResizeMode.NoResize,
                    ShowInTaskbar = false
                };
                var panel = new System.Windows.Controls.StackPanel { Margin = new Thickness(16) };
                panel.Children.Add(new System.Windows.Controls.TextBlock {
                    Text = Loc.F("Str_Msg_HwNotConnectedFmt", actionName,
                        isStrict
                            ? Loc.T("Str_Msg_HwNotConnectedStrict")
                            : Loc.T("Str_Msg_HwNotConnectedSoft")),
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 0, 0, 12)
                });
                var cb = new System.Windows.Controls.CheckBox {
                    Content = Loc.T("Str_Msg_HwWarnDontShowAgain"),
                    Margin = new Thickness(0, 0, 0, 12)
                };
                panel.Children.Add(cb);
                var btnOk = new System.Windows.Controls.Button {
                    Content = Loc.T("Str_Btn_OK"), Width = 80, Height = 28,
                    HorizontalAlignment = HorizontalAlignment.Right,
                    IsDefault = true
                };
                btnOk.Click += delegate { win.DialogResult = true; };
                panel.Children.Add(btnOk);
                win.Content = panel;
                win.ShowDialog();
                if (cb.IsChecked == true) {
                    _suppressHwDisconnectWarning = true;
                    AddLog(Loc.T("Str_Log_HwWarnSuppressedBySession"));
                }
            } catch { }
        }

        //2026-05-30 严格版: 比赛控制按钮 (Ready/Start/Reset/圈数等)
        private bool EnsureHardwareConnected(string actionName) {
            if (_timingBridge != null && _timingBridge.IsConnected) return true;
            ShowHwDisconnectWarning(actionName, true);
            AddLog(Loc.F("Str_Log_HwNotConnStrictFmt", actionName));
            return false;
        }

        //2026-05-30 软版: TimingSettings 等可离线场景 (= 警告但允许保存 PC 本地)
        //   不返回 bool, 调用方继续往下走 PC 本地逻辑
        private void WarnIfHardwareNotConnected(string actionName) {
            if (_timingBridge != null && _timingBridge.IsConnected) return;
            ShowHwDisconnectWarning(actionName, false);
            AddLog(Loc.F("Str_Log_HwNotConnSoftFmt", actionName));
        }

        //2026-05-30 注册 / 取消该 lane 上活跃的 DispatcherTimer (finishCloseTimer / sbCloseTimer)
        //   解决 +/- 后旧 timer 还会 fire 关掉刚 open 的设备的问题
        // 2026-06-06 P1-A: Tick 后自动从字典移除 (= 已失活的 timer 不再被引用, delegate 闭包能被 GC).
        //   长跑下 _laneCloseTimers 不再单调增长. 这些都是 "一次性 fire" timer (Tick 第一行 .Stop()).
        private void RegisterLaneCloseTimer(int lane, DispatcherTimer timer) {
            if (!_laneCloseTimers.ContainsKey(lane)) _laneCloseTimers[lane] = new List<DispatcherTimer>();
            _laneCloseTimers[lane].Add(timer);
            DispatcherTimer cap = timer;
            int capLane = lane;
            EventHandler cleanup = null;
            cleanup = delegate(object s, EventArgs e) {
                cap.Tick -= cleanup;
                List<DispatcherTimer> list2;
                if (_laneCloseTimers.TryGetValue(capLane, out list2)) list2.Remove(cap);
            };
            timer.Tick += cleanup;
        }
        private void CancelLaneCloseTimers(int lane) {
            List<DispatcherTimer> list;
            if (_laneCloseTimers.TryGetValue(lane, out list)) {
                foreach (var t in list) try { t.Stop(); } catch { }
                list.Clear();
            }
            CancelPendingMbSubstitute(lane);   // 2026-06-14 同时取消待决的盲表代替宽限计时
        }
        // 2026-06-06 P1-A: 进程退出前全局停止所有 lane 关闭 timer, 防止 Window_Closing 路径上还有 Tick 跑.
        private void CancelAllLaneCloseTimers() {
            foreach (var kv in _laneCloseTimers) {
                foreach (var t in kv.Value) try { t.Stop(); } catch { }
                kv.Value.Clear();
            }
            _laneCloseTimers.Clear();
            // 2026-06-14 一并停止所有待决的盲表代替宽限计时
            foreach (var kv in _pendingMbSubTimers) try { kv.Value.Stop(); } catch { }
            _pendingMbSubTimers.Clear();
        }

        //2026-05-29 软删该道最近一个未删的分段 (IsDeleted=true, 保留留痕)
        //  用于 ▲ 误触回退: 清除被误触自动写入的错段
        private void MarkLastSplitDeleted(int lane) {
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) return;
            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null || result.Splits == null || result.Splits.Count == 0) return;
            for (int k = result.Splits.Count - 1; k >= 0; k--) {
                var sp = result.Splits[k];
                if (sp.IsDeleted) continue;
                sp.IsDeleted = true;
                AddLog(Loc.F("Str_Log_SoftDeleteSplitFmt",
                    lane, sp.Lap, sp.CumulativeTimeDisplay));
                return;
            }
        }

        //2026-05-29 "📝 手工补段成绩"按钮 click handler — 弹对话框输入道次/段次/累计时间
        private void ManualSplit_Click(object sender, RoutedEventArgs e) {
            if (string.IsNullOrEmpty(_currentEvent) || _currentHeat <= 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectCurrentHeatFirst"), Loc.T("Str_MsgTitle_ManualSplitEntry"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            var swimmers = GetCurrentHeatSwimmers()
                .Where(s => !(s.Status == "DSQ" || s.Status == "DNS" || s.Status == "DNF"))
                .ToList();
            if (swimmers.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoSwimmerToSplit"), Loc.T("Str_MsgTitle_ManualSplitEntry"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            int totalLaps = GetTotalLaps();
            if (totalLaps <= 0) totalLaps = 1;
            ShowManualSplitDialog(totalLaps, swimmers);
        }

        //2026-05-29 手工补段对话框: 道次下拉 + 段次输入 (1..totalLaps) + 累计时间 mm:ss.xxx
        //  分段时间 = 从出发到此段触板的累计时间 (200m: 50m/100m/150m/200m 时刻)
        //  接力赛: 补的是某一棒终点时刻, 不动 LegReactionTimes
        private void ShowManualSplitDialog(int totalLaps, List<Swimmer> swimmers) {
            var dlg = new Window {
                Title = Loc.T("Str_Win_ManualSplit_Title"),
                Width = 480,
                Height = 340,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this,
                ResizeMode = ResizeMode.NoResize,
                Background = new SolidColorBrush(Color.FromRgb(0xF8, 0xFA, 0xFC))
            };
            var grid = new Grid { Margin = new Thickness(20) };
            for (int rr = 0; rr < 6; rr++) grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            grid.RowDefinitions[4].Height = new GridLength(8);
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(140) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            var tip = new TextBlock {
                Text = Loc.T("Str_Win_ManualSplit_Tip"),
                FontSize = 12,
                Foreground = new SolidColorBrush(Color.FromRgb(0x64, 0x74, 0x8B)),
                Margin = new Thickness(0, 0, 0, 16),
                TextWrapping = TextWrapping.Wrap
            };
            Grid.SetColumnSpan(tip, 2);
            Grid.SetRow(tip, 0);
            grid.Children.Add(tip);

            var laneLabel = new TextBlock { Text = Loc.T("Str_Win_ManualSplit_LaneLabel"), FontSize = 14, VerticalAlignment = VerticalAlignment.Center };
            var laneCombo = new ComboBox { Height = 28, Margin = new Thickness(0, 0, 0, 8) };
            // 2026-06-04 按场地道次列 (= 8 道场地 8 项, 10 道场地 10 项), 不基于 swimmer, 不去重.
            //   每道显示对应运动员/接力队名, 空道显示 "(空)"
            int laneCount = _poolConfig != null && _poolConfig.LaneCount > 0 ? _poolConfig.LaneCount : 10;
            Func<Swimmer, int> getLane = s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return sa != null ? sa.Lane : s.Lane;
            };
            for (int laneNo = 1; laneNo <= laneCount; laneNo++) {
                var swInLane = swimmers.FirstOrDefault(s => getLane(s) == laneNo);
                string laneName = swInLane != null ? (swInLane.Name ?? "") : Loc.T("Str_Win_ManualSplit_EmptyLane");
                laneCombo.Items.Add(Loc.F("Str_Win_ManualSplit_LaneItemFmt", laneNo, laneName));
            }
            laneCombo.SelectedIndex = 0;
            Grid.SetRow(laneLabel, 1); Grid.SetColumn(laneLabel, 0);
            Grid.SetRow(laneCombo, 1); Grid.SetColumn(laneCombo, 1);
            grid.Children.Add(laneLabel); grid.Children.Add(laneCombo);

            var segLabel = new TextBlock { Text = Loc.F("Str_Win_ManualSplit_SegLabelFmt", totalLaps), FontSize = 14, VerticalAlignment = VerticalAlignment.Center };
            var segBox = new TextBox { Height = 28, Margin = new Thickness(0, 0, 0, 8), Text = "1", FontSize = 14 };
            Grid.SetRow(segLabel, 2); Grid.SetColumn(segLabel, 0);
            Grid.SetRow(segBox, 2);   Grid.SetColumn(segBox, 1);
            grid.Children.Add(segLabel); grid.Children.Add(segBox);

            var timeLabel = new TextBlock { Text = Loc.T("Str_Win_ManualSplit_TimeLabel"), FontSize = 14, VerticalAlignment = VerticalAlignment.Center };
            var timePanel = new StackPanel { Orientation = Orientation.Vertical, Margin = new Thickness(0, 0, 0, 8) };
            var timeBox = new TextBox { Height = 28, Text = "0:00.000", FontSize = 14 };
            var timeHint = new TextBlock {
                Text = Loc.T("Str_Win_ManualSplit_TimeHint"),
                FontSize = 11, Foreground = new SolidColorBrush(Color.FromRgb(0x94, 0xA3, 0xB8)),
                Margin = new Thickness(0, 4, 0, 0)
            };
            timePanel.Children.Add(timeBox);
            timePanel.Children.Add(timeHint);
            Grid.SetRow(timeLabel, 3); Grid.SetColumn(timeLabel, 0);
            Grid.SetRow(timePanel, 3); Grid.SetColumn(timePanel, 1);
            grid.Children.Add(timeLabel); grid.Children.Add(timePanel);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            var okBtn = new Button {
                Content = Loc.T("Str_Win_ManualSplit_OkBtn"), Width = 110, Height = 36, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush(Color.FromRgb(0x06, 0xB6, 0xD4)),
                Foreground = Brushes.White, FontWeight = FontWeights.Bold, BorderThickness = new Thickness(0), FontSize = 14
            };
            var cancelBtn = new Button {
                Content = Loc.T("Str_Btn_Cancel"), Width = 80, Height = 36,
                Background = new SolidColorBrush(Color.FromRgb(0xCB, 0xD5, 0xE1)),
                BorderThickness = new Thickness(0), FontSize = 14
            };
            btnPanel.Children.Add(okBtn); btnPanel.Children.Add(cancelBtn);
            Grid.SetRow(btnPanel, 5); Grid.SetColumnSpan(btnPanel, 2);
            grid.Children.Add(btnPanel);

            okBtn.Click += (s, ea) => {
                int segNum;
                if (!int.TryParse(segBox.Text.Trim(), out segNum) || segNum < 1 || segNum > totalLaps) {
                    AppMessageBox.Show(Loc.F("Str_Msg_LapRangeFmt", totalLaps), Loc.T("Str_MsgTitle_FormatError"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                double cumSec;
                if (!ParseMmSsXxx(timeBox.Text.Trim(), out cumSec) || cumSec <= 0) {
                    AppMessageBox.Show(Loc.T("Str_Msg_TimeFormatHint"), Loc.T("Str_MsgTitle_FormatError"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                if (laneCombo.SelectedIndex < 0 || laneCombo.SelectedIndex >= laneCount) {
                    AppMessageBox.Show(Loc.T("Str_Msg_SelectLaneFirst"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                int selectedLane = laneCombo.SelectedIndex + 1;
                var swimmer = swimmers.FirstOrDefault(x => getLane(x) == selectedLane);
                if (swimmer == null) {
                    AppMessageBox.Show(Loc.F("Str_Msg_LaneNoSwimmerFmt", selectedLane), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                ApplyManualSplit(swimmer, segNum, cumSec);
                dlg.DialogResult = true;
                dlg.Close();
            };
            cancelBtn.Click += (s, ea) => { dlg.DialogResult = false; dlg.Close(); };
            dlg.Content = grid;
            dlg.ShowDialog();
        }

        //2026-05-29 解析时间字符串 "mm:ss.xxx" / "m:ss.xxx" / "ss.xxx" → 总秒数 (double)
        private bool ParseMmSsXxx(string text, out double seconds) {
            seconds = 0;
            if (string.IsNullOrWhiteSpace(text)) return false;
            text = text.Trim();
            int colon = text.IndexOf(':');
            try {
                if (colon < 0) {
                    seconds = double.Parse(text, System.Globalization.CultureInfo.InvariantCulture);
                } else {
                    int minutes = int.Parse(text.Substring(0, colon), System.Globalization.CultureInfo.InvariantCulture);
                    double secPart = double.Parse(text.Substring(colon + 1), System.Globalization.CultureInfo.InvariantCulture);
                    seconds = minutes * 60 + secPart;
                }
                return seconds >= 0;
            } catch { return false; }
        }

        //2026-05-29 应用手工补段: 写到 LaneResult.Splits[Lap=segNum] (CumulativeTime + IsManual=true)
        private void ApplyManualSplit(Swimmer swimmer, int segNum, double cumSec) {
            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                result = new LaneResult {
                    EventName = _currentEvent,
                    Stage = _currentStage,
                    Heat = _currentHeat,
                    Lane = swimmer.Lane
                };
                swimmer.Results.Add(result);
            }
            SplitTime sp = null;
            foreach (var s2 in result.Splits) {
                if (s2.Lap == segNum) { sp = s2; break; }
            }
            if (sp == null) {
                int poolLen = _poolConfig != null ? _poolConfig.Length : 50;
                sp = new SplitTime { Lap = segNum, Distance = poolLen * segNum };
                result.Splits.Add(sp);
                var sorted = result.Splits.OrderBy(x => x.Lap).ToList();
                result.Splits.Clear();
                foreach (var x in sorted) result.Splits.Add(x);
            }
            // 2026-06-03 优先级守卫: 手工输入是最低优先级, 已有 TP/MB/Manual 时弹确认对话框
            if (!string.IsNullOrEmpty(sp.TimingSource) && (sp.TimingSource == "TP" || sp.TimingSource == "MB" || sp.TimingSource == "Manual")) {
                string srcLabel = sp.TimingSource == "TP" ? "触板(TP)" : (sp.TimingSource == "MB" ? "盲表代替(MB)" : "手动 TP");
                var confirm = AppMessageBox.Show(
                    Loc.F("Str_Msg_SplitOverwriteFmt", swimmer.Lane, segNum, srcLabel, sp.CumulativeTime),
                    Loc.T("Str_MsgTitle_OverwriteConfirm"), MessageBoxButton.YesNo, MessageBoxImage.Warning);
                if (confirm != MessageBoxResult.Yes) {
                    AddLog(Loc.F("Str_Log_ManualSplitCancelledFmt", swimmer.Lane, segNum, srcLabel));
                    return;
                }
            }
            sp.CumulativeTime = cumSec;
            sp.IsManual = true;
            sp.IsDeleted = false;
            SplitTime prev = null;
            foreach (var s2 in result.Splits) {
                if (s2.Lap < segNum && !s2.IsDeleted && s2.CumulativeTime > 0
                    && (prev == null || s2.Lap > prev.Lap)) prev = s2;
            }
            sp.Time = (prev != null) ? (cumSec - prev.CumulativeTime) : cumSec;
            // 2026-06-03 TimingSource="Input" 表示用户手工输入 (= 最低优先级), 区别 "Manual" (= 手动 T 按钮)
            sp.TimingSource = "Input";
            AddLog(Loc.F("Str_Log_ManualSplitAppliedFmt",
                swimmer.Lane, swimmer.Name, segNum, cumSec, sp.Time));
            AutoSaveData();
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // 含 spinner 偏移的"显示用当前圈数"：
        // = 总圈数 − 左剩余显示 − 右剩余显示
        // 用于接力赛"第N棒"的实时切换：用户 ▲ 加圈 → 剩余降低 → 当前圈数升高 → 棒次自动前进。
        private int GetDisplayedCurrentLap(LaneDeviceState ls) {
            if (ls == null) return 0;
            int totalLaps = GetTotalLaps();
            int leftRemain = GetDisplayedLapCount(ls, true);
            int rightRemain = GetDisplayedLapCount(ls, false);
            int v = totalLaps - leftRemain - rightRemain;
            if (v < 0) v = 0;
            if (v > totalLaps) v = totalLaps;
            return v;
        }

        // 显示用的"该侧剩余圈数" = GetTouchRemain(自动推算) + 人工 spinner 偏移；钳到 [0, 该侧触板总次数]。
        private int GetDisplayedLapCount(LaneDeviceState ls, bool isLeft) {
            if (ls == null) return 0;
            int baseVal = GetTouchRemain(ls, isLeft);
            int adj = isLeft ? ls.LeftLapManualAdjust : ls.RightLapManualAdjust;
            int v = baseVal + adj;
            int maxDisp = GetLapDisplayMaxForSide(isLeft);
            if (v < 0) v = 0;
            if (v > maxDisp) v = maxDisp;
            return v;
        }

        // 2026-06-14 该侧总触板次数 (→ LapSideLogic 纯逻辑, 与自动化测试同源)
        private int GetSideTouchTotal(bool isLeft) {
            return LapSideLogic.SideTouchTotal(GetTotalLaps(), _laneCloseSettings.StartPosition != "right", isLeft);
        }

        // 2026-06-14 严格按侧: 该侧剩余 = 该侧总次数 − 该侧实际已触次数 (LeftTouchDone/RightTouchDone),
        //   两侧完全独立, 不再用单 CurrentLap 奇偶推算 → 某侧多/少触板不会牵连另一侧 (与硬件按侧一致).
        private int GetTouchRemain(LaneDeviceState laneState, bool isLeft) {
            int done = laneState == null ? 0 : (isLeft ? laneState.LeftTouchDone : laneState.RightTouchDone);
            return LapSideLogic.Remain(GetTotalLaps(), _laneCloseSettings.StartPosition != "right", isLeft, done);
        }

        private void UpdateHeatRanking() {
            var swimmers = GetCurrentHeatSwimmers();

            // 先清零所有运动员的排名（防止DSQ等运动员保留旧排名）
            foreach (var sw in swimmers) {
                sw.CurrentRank = 0;
                var r = sw.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r != null) r.Rank = 0;
            }

            // 2026-06-05 U 系列规则: 组内只按时间排单一名次 (不分性别 / 组别)
            RankHeatGroup(swimmers);
            // 名次重算后同步处理"只有本组第 1 名保留破/平纪录标识"，
            // 覆盖 DSQ 取消/晋级把更慢成绩拽到第 1 等场景
            EnforceOnlyLeaderRecordNote();
        }

        // 2026-06-04 提出 UpdateHeatRanking 内的核心排名循环
        private void RankHeatGroup(IEnumerable<Swimmer> swimmers) {
            var withResults = swimmers.Where(s => {
                var r = s.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                // 2026-06-04 TRI 不参与本组排名 (= 与 DSQ/DNS/DNF 同款排除)
                // 2026-09-01 判罚/试游看【有效状态】(成绩行优先): 回推/导入进来的成绩
                //   把状态记在成绩行上, 只看 s.Status 会把他们排进本组名次。
                string es = GetEffectiveStatus(s, r);
                return r != null && r.FinalTime > 0 && !ResultOrdering.IsJudged(es) && es != "TRI";
            }).OrderBy(s => {
                var r = s.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                return r.FinalTime;
            }).ToList();

            // 2026-08-30 并列名次的算法只有 ResultOrdering.ComputeRanks 一份。
            //   原来这套"idx/rank/prevTime 三件套"在程序里各写各的有 5 处。
            var hgRanks = ResultOrdering.ComputeRanks(withResults, s => {
                var rr = s.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                return rr != null ? rr.FinalTime : 0;
            });
            for (int i = 0; i < withResults.Count; i++) {
                var sw = withResults[i];
                var r = sw.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r != null) r.Rank = hgRanks[i];
                sw.CurrentRank = hgRanks[i];
            }
        }

        // 纪录类型 → 简写标识（用于备注栏/打印/大屏 BREAK/TIE 提示）
        // 破纪录用 "WR"，平纪录用 "=WR"
        private string RecordTypeToTag(string type) {
            if (string.IsNullOrEmpty(type)) return "REC";
            // 2026-07-09 优先查用户自定义映射 (= "大屏显示与纪录设置" 里维护的 Label / TypeName).
            //   用户新增 "WJ / 世界青少年纪录" 后, 走此路径匹配, 不再被 hardcode 的 Contains("世界") 误命中返 "WR".
            if (_displayRecordOptions != null) {
                foreach (var o in _displayRecordOptions) {
                    if (o != null && !string.IsNullOrEmpty(o.Label) && o.TypeName == type) return o.Label;
                }
            }
            string t = type;
            if (t.Contains("世界")) return "WR";
            if (t.Contains("奥运")) return "OR";
            if (t.Contains("亚洲青年")) return "AJR";
            if (t.Contains("亚洲")) return "AR";
            if (t.Contains("全国")) return "NR";
            if (t.Contains("省")) return "MR";
            if (t.Contains("市")) return "市R";
            if (t.Contains("赛会") || t.Contains("大会")) return "CR";
            // 兜底：取首字母
            return t.Length <= 4 ? t : t.Substring(0, 4);
        }

        // 比对成绩与所有匹配该项目+性别(+组别)的记录条目，写 result.RecordNote 并记日志。
        // 返回值：是否写入了任何破/平纪录标识（用于触发广播/确认时的通知）。
        private bool CheckRecords(Swimmer swimmer, LaneResult result) {
            if (result == null || swimmer == null || result.FinalTime <= 0) {
                if (result != null) result.RecordNote = "";
                return false;
            }
            string ageGroup = swimmer.AgeCategory ?? "";
            // 2026-06-05 男女并项 修复: 用 swimmer.Gender (单一性别) 对比 record.Gender,
            //   不是 _currentGender (= "男女" 时永远不匹配任何 男/女 record)
            string swGender = swimmer.Gender ?? "";
            var tags = new List<string>();
            // 2026-09-16 tag 对应的旧纪录快照(纪录证书要印"原记录成绩/原记录保持者/原
            //   记录时间")——UpdateRecordsAfterConfirm 紧跟着就会把 _records 覆盖成新
            //   持有者, 这里是唯一还能拿到"破之前"数据的地方, 跟 tag 一起存, 免得多个
            //   record 同时被破时张冠李戴。
            var tagSnaps = new Dictionary<string, SwimmingRecord>();
            foreach (var record in _records) {
                if (record == null || record.Time <= 0) continue;                      // 记录库无数据则不比较
                if (record.Gender != swGender) continue;
                if (record.EventName != _currentEvent) continue;
                // 组别：记录条目 AgeGroup 为空表示不限组别；否则需匹配
                string rg = record.AgeGroup ?? "";
                if (!string.IsNullOrEmpty(rg) && rg != ageGroup) continue;

                string tag = RecordTypeToTag(record.RecordType);
                if (result.FinalTime < record.Time) {
                    tags.Add(tag);
                    tagSnaps[tag] = record;
                    AddLog(Loc.F("Str_Log_RecordBrokenFmt",
                        record.RecordType, swimmer.Name,
                        TimeFormatter.Format(result.FinalTime), TimeFormatter.Format(record.Time),
                        record.HolderName ?? "", record.HolderCountry ?? ""));
                } else if (Math.Abs(result.FinalTime - record.Time) < 0.005) {
                    tags.Add("=" + tag);
                    tagSnaps["=" + tag] = record;
                    AddLog(Loc.F("Str_Log_RecordTiedFmt",
                        record.RecordType, swimmer.Name,
                        TimeFormatter.Format(result.FinalTime), TimeFormatter.Format(record.Time)));
                }
            }
            // 去重并按 WR > OR > AR > AJR > NR > MR > 市R > CR 的顺序排序展示 (MR = 省级 Meet Record)
            var order = new Dictionary<string, int> { {"WR",1},{"OR",2},{"AR",3},{"AJR",4},{"NR",5},{"MR",6},{"市R",7},{"CR",8} };
            tags = tags.Distinct().OrderBy(s => {
                string key = s.StartsWith("=") ? s.Substring(1) : s;
                int v;
                return order.TryGetValue(key, out v) ? v : 99;
            }).ToList();
            // 2026-07-09 用户诉求: 只显示优先级最高的标识 (原 "WR/AR/NR" 拼接 → "WR").
            string note = tags.Count > 0 ? tags[0] : "";
            result.RecordNote = note;
            SwimmingRecord noteSnap;
            if (!string.IsNullOrEmpty(note) && tagSnaps.TryGetValue(note, out noteSnap) && noteSnap != null) {
                result.OldRecordHolder = noteSnap.HolderName ?? "";
                result.OldRecordCountry = noteSnap.HolderCountry ?? "";
                result.OldRecordTime = noteSnap.Time;
                result.OldRecordDate = noteSnap.Date ?? "";
            }
            // 一组多人同时打破纪录时，仅保留本组成绩最佳者（含并列）的标识；其余清除。
            // FINA 惯例：纪录归本组最快者所有；慢于他的同组选手即便也好于历史纪录，也不计破纪录。
            EnforceOnlyLeaderRecordNote();
            return tags.Count > 0;
        }

        // 判断该项目从 fromStage 出发的下一赛次（"预赛" → "半决赛"或"决赛"，"半决赛" → "决赛"）
        // 用于打印预赛/半决赛成绩单时给晋级者标 Q
        // 2026-06-18 加 ageGroup 参数: 修跨年龄段半决赛误判 (甲组无半决但乙组有 → 甲组也错认有)
        private string GetNextStageFor(string ageGroup, string gender, string eventName, string fromStage) {
            if (fromStage == "预赛") {
                if (_schedule.Any(s => SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == "半决赛"
                    && (string.IsNullOrEmpty(ageGroup) || (s.AgeGroup ?? "") == ageGroup)))
                    return "半决赛";
                return "决赛";
            }
            if (fromStage == "半决赛") return "决赛";
            return null;     // 决赛及其它无下一赛次
        }

        // 该运动员是否已晋级到下一赛次（StageAssignments 含下一赛次 → 已被分组）
        // 2026-06-22 (S2) DSQ/DNS/DNF 排序统一 helper. 用户要求 DSQ 在 DNS 上面.
        //   DSQ/DQ=1 (最优先) → DNF=2 → DNS=3 → 其他=9. 所有显示视图必须用此 helper, 杜绝 inline 不一致.
        private static int GetStatusSortOrder(string status) {
            if (status == "DSQ" || status == "DQ") return 1;
            if (status == "DNF") return 2;
            if (status == "DNS") return 3;
            return 9;
        }

        // 2026-08-19 单组成绩 (组成绩 / 本组成绩单) 排序 helper.
        //   总排名 (GetStatusSortOrder) 里 TRI 整个被剔除, 不需要位置; 单组成绩 TRI 要显示 (有成绩不排名),
        //   规则: 有名次者按名次 → TRI(试游) → DSQ/DQ → DNF → DNS → 其他(无成绩无状态).
        //   与 display.html 的 _hrStatusOrder / _hrCompare 完全同口径.
        private static int GetHeatStatusOrder(string status) { return ResultOrdering.StatusOrder(status); }

        // 2026-08-30 本组名次一律以【成绩行 r.Rank】为准。
        //   sw.CurrentRank 只是"最近一次算名次"留下的临时字段: 它每人只有一个值,
        //   而且【计时端回推 / 文件导入的成绩根本不会设它】。谁拿它排序或显示,
        //   谁就把有名次的人当成没名次的 —— 打印成绩单时 DNF 被排到并列第一之前,
        //   就是这么来的(显示读 r.Rank 显示成"1", 排序读 CurrentRank 当成 0)。
        private static int HeatRankOf(Swimmer sw, LaneResult r) {
            return ResultOrdering.RankOf(r != null ? r.Rank : 0, sw != null ? sw.CurrentRank : 0);
        }

        // 取该运动员在指定 stage/heat 的"有效状态" (成绩行 Status 优先, 否则运动员 Status)
        private static string GetEffectiveStatus(Swimmer sw, LaneResult r) {
            if (r != null && !string.IsNullOrEmpty(r.Status)) return r.Status;
            return sw != null ? (sw.Status ?? "") : "";
        }

        // 按上述规则排序单组运动员. 同类内: 有成绩的按成绩快慢 (多名 TRI 时), 无成绩的按道次.
        private List<Swimmer> OrderHeatResultSwimmers(IEnumerable<Swimmer> swimmers, string stage, int heat) {
            Func<Swimmer, LaneResult> getRes = sw =>
                sw.Results.FirstOrDefault(lr => lr.Stage == stage && lr.Heat == heat) ?? sw.GetResultForStage(stage);
            // 2026-08-30 顺序规则只有 ResultOrdering.OrderForHeat 一份, 这里只负责取值。
            return ResultOrdering.OrderForHeat(swimmers,
                sw => GetEffectiveStatus(sw, getRes(sw)),
                sw => HeatRankOf(sw, getRes(sw)),
                sw => { var r = getRes(sw); return r != null ? r.FinalTime : 0; },
                sw => sw.Lane);
        }

        private bool IsQualifiedToNext(Swimmer sw, string fromStage) {
            if (sw == null) return false;
            string next = GetNextStageFor(sw.AgeCategory ?? "", sw.Gender, sw.EventName, fromStage);
            if (string.IsNullOrEmpty(next)) return false;
            return sw.GetAssignmentForStage(next) != null;
        }

        // 备注栏渲染：判罚（DSQ/DNS/DNF/DQ）红色，晋级 Q 绿色，其它空白。
        // 集中在一处，让所有打印路径（本组成绩单 / 赛事级公告 等）共用样式。
        private string RenderRemarkCellHtml(Swimmer sw, LaneResult r, string fromStage) {
            string status = "";
            if (r != null && !string.IsNullOrEmpty(r.Status)) status = r.Status;
            // 2026-06-04 TRI 也要在备注栏显 'TRI' (= 试游, 与 DSQ/DNS/DNF 同款标签, 但 TRI 仍显成绩)
            else if (sw != null && !string.IsNullOrEmpty(sw.Status) &&
                     (sw.Status == "DNS" || sw.Status == "DNF" || sw.Status == "DSQ" || sw.Status == "DQ" || sw.Status == "TRI"))
                status = sw.Status;
            if (!string.IsNullOrEmpty(status))
                return string.Format("<span style='color:#dc2626;'>{0}</span>", status);
            if (IsQualifiedToNext(sw, fromStage))
                return "<span style='color:#16a34a;font-weight:bold;'>Q</span>";
            return "";
        }

        // 并列名次比较：硬件计时控制器以 1/100 秒精度（单字节）发送成绩，
        // 软件侧 FinalTime 是 double，存储 0.5468 这样的值时由于 IEEE 754 表达
        // 会有微小尾差（54.68 实际为 54.68000000000000682…），不同计时源裁定后
        // "本应并列"的两条成绩用 == 比较常常失败。
        // 因此先按硬件精度四舍五入到 1/100 秒整数（百分秒），再做 int 相等比较：
        // 两条都 round 到 5468 → 视为并列；硬件上一致即并列，与精度直接对齐。
        // 5 处排名计算（UpdateHeatRanking / GetEventRanking / ComputeLiveRanks / 两处打印）统一调用此方法。
        // 2026-08-30 实现搬到 ResultOrdering, 这里只留一层壳给老调用点。
        //   规则只允许在 ResultOrdering.cs 里写一次 —— 见那个文件开头的说明。
        private static bool IsTieTime(double a, double b) { return ResultOrdering.IsTie(a, b); }

        // 仅本组最快成绩（含并列）的 LaneResult.RecordNote 保留；其它人 RecordNote 清空。
        // 用于"一组多人破纪录只显示第 1 名记录"的展示+持久化逻辑。
        // 对 DSQ/DNS/DNF：成绩无效，本就不参与"最快"判定（也不会有 RecordNote 留存）。
        // 2026-06-01 DSQ/DNS/DNF 后, 老的本组第1名 RecordNote 已清空, 新晋第1名 (原#2/#3)
        //   在之前作为非 leader 时被 EnforceOnlyLeader 也清掉了 RecordNote, 现在需要重比纪录库
        //   把它的破/平纪录标识"补回来"; EnforceOnlyLeader 只做减法 (清非 leader), 不会做加法.
        //   适用场景: 前 3 名都破纪录, #1 判罚 DSQ → WR 标识应自动转到 #2; #1 #2 都 DSQ → 转到 #3.
        private void RecheckHeatRecordsForNewLeader() {
            var heatSwimmers = GetCurrentHeatSwimmers();
            double leaderTime = double.MaxValue;
            foreach (var sw in heatSwimmers) {
                if (sw.Status == "DSQ" || sw.Status == "DNS" || sw.Status == "DNF") continue;
                var r = sw.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r == null || r.FinalTime <= 0) continue;
                if (r.FinalTime < leaderTime) leaderTime = r.FinalTime;
            }
            if (leaderTime == double.MaxValue) return;
            long leaderH = (long)Math.Round(leaderTime * 100.0, MidpointRounding.AwayFromZero);
            // 给所有 leader (含并列) 重新比对; CheckRecords 末尾会触发 EnforceOnlyLeader, 非 leader 自然被清
            foreach (var sw in heatSwimmers) {
                if (sw.Status == "DSQ" || sw.Status == "DNS" || sw.Status == "DNF") continue;
                var r = sw.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r == null || r.FinalTime <= 0) continue;
                long curH = (long)Math.Round(r.FinalTime * 100.0, MidpointRounding.AwayFromZero);
                if (curH == leaderH) {
                    try { CheckRecords(sw, r); } catch { }
                }
            }
        }

        // 2026-08-22 用户要求改回"本组中有多人破纪录的都在备注栏标注"。
        //   (2026-06 之前就是这样, 中途改成只标第 1 名, 现在改回来。)
        //   保留本函数壳子和调用点, 直接返回 —— 万一以后又要按 FINA 惯例
        //   "纪录归本组最快者", 把下面这个 return 去掉即可恢复。
        private void EnforceOnlyLeaderRecordNote() {
            if (true) return;
#pragma warning disable 0162
            var swimmers = GetCurrentHeatSwimmers();
            double leaderTime = double.MaxValue;
            foreach (var sw in swimmers) {
                if (sw.Status == "DSQ" || sw.Status == "DNS" || sw.Status == "DNF") continue;
                var r = sw.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r == null || r.FinalTime <= 0) continue;
                if (r.FinalTime < leaderTime) leaderTime = r.FinalTime;
            }
            if (leaderTime == double.MaxValue) return;
            // 与 IsTieTime 同精度：按硬件 1/100 秒整数比较，避免浮点尾差
            long leaderHundredths = (long)Math.Round(leaderTime * 100.0, MidpointRounding.AwayFromZero);
            foreach (var sw in swimmers) {
                var r = sw.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r == null || string.IsNullOrEmpty(r.RecordNote)) continue;
                long curH = (long)Math.Round(r.FinalTime * 100.0, MidpointRounding.AwayFromZero);
                if (curH > leaderHundredths) {
                    AddLog(Loc.F("Str_Log_RecordClearedNot1stFmt",
                        sw.Lane, sw.Name, TimeFormatter.Format(r.FinalTime), TimeFormatter.Format(leaderTime), r.RecordNote));
                    r.RecordNote = "";
                }
            }
#pragma warning restore 0162
        }

        // 裁判确认成绩后调用：把本组中所有 RecordNote 含"破纪录"标签（不带=前缀）的成绩
        // 用于刷新对应 SwimmingRecord 条目（保持者/时间/日期/地点同步更新）
        private void UpdateRecordsAfterConfirm() {
            // 2026-09-20 跟 ApplyRecordBreaksToLocalState 同一个道理: 纪录表就这么大一份,
            //   改完用 PushChangedRecords 按条(upsert)同步, 不用为几条破纪录推整包。
            var before = SnapshotRecords();
            var heatSwimmers = GetCurrentHeatSwimmers();
            string today = DateTime.Now.ToString("yyyy-MM-dd");
            int updated = 0;
            foreach (var sw in heatSwimmers) {
                var res = sw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                if (res == null || res.FinalTime <= 0) continue;
                if (string.IsNullOrEmpty(res.RecordNote)) continue;
                if (sw.Status == "DSQ" || sw.Status == "DNS" || sw.Status == "DNF") continue;
                string ageGroup = sw.AgeCategory ?? "";
                // 2026-06-05 男女并项 修复: 用 sw.Gender 单一性别 对比 record.Gender, 不是 _currentGender
                string swGender = sw.Gender ?? "";
                foreach (var record in _records.Where(r => r.Time > 0 && r.Gender == swGender && r.EventName == _currentEvent).ToList()) {
                    string rg = record.AgeGroup ?? "";
                    if (!string.IsNullOrEmpty(rg) && rg != ageGroup) continue;
                    if (res.FinalTime < record.Time) {
                        record.HolderName = sw.Name ?? "";
                        record.HolderCountry = sw.Country ?? "";
                        record.Time = res.FinalTime;
                        record.TimeInSeconds = res.FinalTime;
                        record.Date = today;
                        record.Location = _competitionName ?? "";
                        AddLog(Loc.F("Str_Log_RecordUpdatedFmt",
                            record.RecordType, record.HolderName, record.HolderCountry,
                            TimeFormatter.Format(record.Time), today));
                        updated++;
                    }
                }
            }
            if (updated > 0) {
                SaveWithoutPush();
                PushChangedRecords(before);
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 计时器
        // ═══════════════════════════════════════════════════════════════
        private void InitializeTimers() {
            _raceTimer = new DispatcherTimer();
            _raceTimer.Interval = TimeSpan.FromMilliseconds(100);
            _raceTimer.Tick += RaceTimer_Tick;

            _countdownTimer = new DispatcherTimer();
            _countdownTimer.Interval = TimeSpan.FromMilliseconds(100);
            _countdownTimer.Tick += CountdownTimer_Tick;

            // 2026-06-03 接力 SB reaction 计算器 + 100ms tick (= 检查 window 超时)
            _relayReactionCalc = new RelayReactionCalculator(
                // 2026-06-18 改用 ResultConfirmCloseDelay 作窗口时长 + 抢跳 SB 暂存等基准事件触发 (修复抢跳 SB<TP 算不出 bug)
                windowSecGetter: () => _laneCloseSettings != null ? _laneCloseSettings.ResultConfirmCloseDelay : 3.0,
                onReaction: OnRelayReactionReady,
                onNoReaction: OnRelayReactionNone);
            _relayReactionTickTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
            _relayReactionTickTimer.Tick += RelayReactionTick;
            _relayReactionTickTimer.Start();
        }

        private void RelayReactionTick(object sender, EventArgs e) {
            if (_relayReactionCalc == null) return;
            _relayReactionCalc.Tick(_runningTime);
        }

        // 2026-06-03 RelayReactionCalculator 输出回调: window 算出 reaction
        private void OnRelayReactionReady(int lane, string side, double reaction, string basisKind) {
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;
            laneState.ReactionTime = reaction;
            // 写比赛日志 — 用"出"标签 + 加 basisKind 注释
            string label = "出";
            string sideLabel = side == "left" ? "左" : (side == "right" ? "右" : "");
            int lapRemain = GetTouchRemain(laneState, side == "left");
            string lapLabel = lapRemain >= 0 ? string.Format("[{0}]", lapRemain) : "";
            string timeStr;
            if (reaction == 0) timeStr = "0.00";
            else if (reaction < 0) timeStr = "-" + TimeFormatter.Format(-reaction);
            else timeStr = TimeFormatter.Format(reaction);
            // 加 basis 注释 (= TP / MB / HandTP)
            string basisNote = basisKind == "TP" ? "" : (basisKind == "MB" ? " (基准:MB)" : (basisKind == "HandTP" ? " (基准:手动)" : ""));
            string elapsed = _raceStartTime > DateTime.MinValue
                ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds)
                : "—";
            string swimmerName = "";
            var sw2 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                var sa2 = s2.GetAssignmentForStage(_currentStage);
                return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
            });
            if (sw2 != null) swimmerName = sw2.Name ?? "";
            // 2026-06-03 计算数据 (= 14 条规则算出) time 后加 "*" 与原始 SB 数据区分
            // 2026-06-16 简化日志格式: 去掉 "[T=" 和 "]"
            AppendLaneEventLog(lane, string.Format("{0,8} 道{1}{2} {3}{4}={5}*{6}{7}\r\n",
                elapsed, lane, sideLabel, label, lapLabel, timeStr, basisNote,
                string.IsNullOrEmpty(swimmerName) ? "" : (" (" + swimmerName + ")")));
            // 写到接力 LegReactionTimes (= 棒次反应时表)
            if (_isRelay) {
                var swForLane = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                    var sa2 = s2.GetAssignmentForStage(_currentStage);
                    return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
                });
                if (swForLane != null) {
                    var relayRes = EnsureRelayLaneResult(swForLane, lane);
                    if (relayRes != null) {
                        // 2026-07-13 按侧化: 棒次索引优先读该侧倒计时=0 盖的印章 (免疫 CurrentLap++ 时序); 缺印章才回退 CurrentLap 推算.
                        int legIdx = (side == "left") ? laneState.HandoffLegIdxLeft
                                   : (side == "right") ? laneState.HandoffLegIdxRight : -1;
                        if (legIdx < 0) legIdx = ComputeRelayLegIndex(laneState.CurrentLap);
                        EnsureLegReactionSlots(relayRes);
                        if (legIdx >= 0 && legIdx < relayRes.LegReactionTimes.Count)
                            relayRes.LegReactionTimes[legIdx] = reaction;
                    }
                }
            }
            // 抢跳标记
            if (reaction < 0) {
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_RelayFalseStartFmt", lane, sideLabel, reaction, basisNote));
            }
            // 2026-07-13 按侧化: 本侧本棒反应时已结算 → 置 SbReactionRecorded, 锚点复位 (后续同侧 SB 走备用, 直到下棒倒计时=0 清回).
            if (side == "left") laneState.SbReactionRecordedLeft = true;
            else if (side == "right") laneState.SbReactionRecordedRight = true;
        }

        private void OnRelayReactionNone(int lane, string side) {
            // window 内没 SB 或没基准 → "---"
            string label = "出";
            string sideLabel = side == "left" ? "左" : (side == "right" ? "右" : "");
            var ls2 = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            int lapRemain = ls2 != null ? GetTouchRemain(ls2, side == "left") : -1;
            string lapLabel = lapRemain >= 0 ? string.Format("[{0}]", lapRemain) : "";
            string elapsed = _raceStartTime > DateTime.MinValue
                ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds)
                : "—";
            string swimmerName = "";
            var sw2 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                var sa2 = s2.GetAssignmentForStage(_currentStage);
                return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
            });
            if (sw2 != null) swimmerName = sw2.Name ?? "";
            if (!_laneEventLog.ContainsKey(lane)) _laneEventLog[lane] = new StringBuilder();
            // 2026-06-03 计算数据 (= 14 条规则算出) time 后加 "*" 与原始 SB 数据区分
            // 2026-06-16 简化日志格式: 去掉 "[T=" 和 "]"
            _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2} {3}{4}=---*{5}\r\n",
                elapsed, lane, sideLabel, label, lapLabel,
                string.IsNullOrEmpty(swimmerName) ? "" : (" (" + swimmerName + ")"));
            TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
            if (lane == _selectedLane) RefreshLaneEventLogView();
            // 2026-07-13 按侧化: 本侧本棒交接窗口已结算 (无反应=---) → 置 SbReactionRecorded, 锚点复位, 防迟到 SB 重开窗口.
            if (ls2 != null) {
                if (side == "left") ls2.SbReactionRecordedLeft = true;
                else if (side == "right") ls2.SbReactionRecordedRight = true;
            }
        }


        private int _raceTickCount = 0;
        private static readonly SolidColorBrush _firstPlaceBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E"));
        private static readonly SolidColorBrush _runningTimeBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B"));

        // 2026-06-20 反应时收集窗口: 发令时启动. ReactionEventWindowSec 秒到期后, 仍是 0 的 laneState.ReactionTime
        //   标 double.NaN → ReactionTimeDisplay/SHOW_LIVE_RACE 投影都翻译为 "---". 裁判可手动覆盖.
        //   只检查参赛泳道 (IsLaneReceivingData); 已写入合法反应时的 (ReactionTime != 0) 不动.
        private void StartReactionWindowTimer() {
            try { if (_reactionWindowTimer != null) _reactionWindowTimer.Stop(); } catch { }
            if (_laneCloseSettings == null || !_laneCloseSettings.ReactionTimeEnabled) return;
            double winSec = _laneCloseSettings.ReactionEventWindowSec > 0 ? _laneCloseSettings.ReactionEventWindowSec : 3.0;
            _reactionWindowTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(winSec) };
            _reactionWindowTimer.Tick += ReactionWindowTimer_Tick;
            _reactionWindowTimer.Start();
        }

        private void StopReactionWindowTimer() {
            try { if (_reactionWindowTimer != null) { _reactionWindowTimer.Stop(); _reactionWindowTimer = null; } } catch { }
        }

        private void ReactionWindowTimer_Tick(object sender, EventArgs e) {
            try { if (_reactionWindowTimer != null) _reactionWindowTimer.Stop(); } catch { }
            foreach (var laneState in _laneDeviceStates) {
                if (laneState == null) continue;
                if (!IsLaneReceivingData(laneState.Lane)) continue;          // 空泳道 / DNS/DNF 不动
                if (laneState.ReactionTime != 0) continue;                   // 已有真实反应时 (包含负值/抢跳), 不动
                if (double.IsNaN(laneState.ReactionTime)) continue;          // 已标过 NaN
                laneState.ReactionTime = double.NaN;
                AddLog(Loc.F("Str_Log_ReactionWindowTimeoutFmt", laneState.Lane, _laneCloseSettings.ReactionEventWindowSec));
                // 接力第 1 棒同步标 LegReactionTimes[0] = NaN
                if (_isRelay) {
                    var sw = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                        var sa2 = s2.GetAssignmentForStage(_currentStage);
                        return (sa2 != null ? sa2.Lane : s2.Lane) == laneState.Lane;
                    });
                    if (sw != null) {
                        var res = EnsureRelayLaneResult(sw, laneState.Lane);
                        if (res != null) {
                            EnsureLegReactionSlots(res);
                            if (res.LegReactionTimes.Count > 0) res.LegReactionTimes[0] = double.NaN;
                        }
                    }
                }
            }
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        private void RaceTimer_Tick(object sender, EventArgs e) {
            // 发令后一直计时，不因比赛结束而停止，直到复位信号
            if (_raceStartTime != DateTime.MinValue) {
                // _runningTime 完全由硬件 0x7F 帧驱动（见 ProcessTimingData 早期分支），
                // 此处不再用本地 DateTime 自算时间：硬件是唯一权威时间源。
                _raceTickCount++;

                // 第1名成绩显示（轻量操作，每次tick都执行）
                double holdSec = _laneCloseSettings.FirstPlaceHoldTime > 0 ? _laneCloseSettings.FirstPlaceHoldTime : 3;
                if (_firstPlaceShowStart != DateTime.MinValue &&
                    (DateTime.Now - _firstPlaceShowStart).TotalSeconds < holdSec &&
                    !string.IsNullOrEmpty(_firstPlaceFinishTime)) {
                    if (RunningTimeText != null) {
                        RunningTimeText.Text = _firstPlaceFinishTime;
                        RunningTimeText.Foreground = _firstPlaceBrush;
                    }
                } else {
                    if (RunningTimeText != null) {
                        // 2026-05-27 停表: 显示冻结快照, 硬件继续走 _runningTime 内部仍更新但不显示.
                        double showT = _clockPaused ? _pausedRunningTime : _runningTime;
                        RunningTimeText.Text = TimeFormatter.FormatRunning(showT);
                        RunningTimeText.Foreground = _runningTimeBrush;
                    }
                }

                // 每100ms刷新泳道动态内容（增量更新，不重建UI）
                UpdateLaneStatusDisplay();

                // 2026-06-17 删除 500ms 心跳 Broadcast: 改纯事件驱动.
                //   - 触板成绩 / 状态灯 / 倒计时 / 选组 / 比赛开始结束等真实变化都各自调 Broadcast()
                //   - 滚动时间另有 BroadcastRunningTime 10Hz 高频帧 (极小, 不阻塞 UI)
                //   - 新连客户端在 OnOpen 时 BroadcastSingle (主服务器侧还会优先送 _lastRtcSnapshot)
                //   原 500ms 心跳是冗余兜底, 在 RTC 模式下尤其昂贵 (GetStatusData + 转发主服务器).
                // if (_raceTickCount % 5 == 0) Broadcast();
            }
        }

        private void CountdownTimer_Tick(object sender, EventArgs e) {
            bool changed = false;
            DateTime now = DateTime.Now;
            foreach (var state in _laneDeviceStates) {
                // 2026-05-26 修复"封闭时间到了泳道不开"BUG:
                //   旧版用 state.LaneCloseCountdown > 0 当唯一开关, 而 Math.Round(remaining*10)/10
                //   在 remaining<0.05 时会把 LaneCloseCountdown 提前**四舍五入为 0**, 此时下次 tick
                //   外层 `> 0` 为 false → 整个分支被跳过, else 里的"开设备"逻辑永远不执行.
                //   新版改用 CountdownStartedAt + CountdownTargetSec 作真正的时间锚, LaneCloseCountdown
                //   降级为纯 UI 显示值; 倒计时一过, 锚点清空防止重复打开.
                if (state.IsFinished) continue;
                if (state.CountdownStartedAt == default(DateTime)) continue;   // 没有正在跑的倒计时
                if (state.CountdownTargetSec <= 0) continue;                   // 目标 <=0 视为没有倒计时
                double elapsed = (now - state.CountdownStartedAt).TotalSeconds;
                double remaining = state.CountdownTargetSec - elapsed;
                if (remaining > 0) {
                    // 显示剩余 (保持 0.1 步进的视觉效果, 避免 UI 文本快速抖动);
                    // 即便 rounded 提前落到 0 也不会影响开门判断 (因为已不用它当 gate)
                    double rounded = Math.Round(remaining * 10) / 10.0;
                    if (rounded != state.LaneCloseCountdown) state.LaneCloseCountdown = rounded;
                    changed = true;
                } else {
                    // 倒计时跨过 0 → 开到达端设备 (一次性, 然后清锚防止重入)
                    state.LaneCloseCountdown = 0;
                    state.CountdownStartedAt = default(DateTime);
                    state.CountdownTargetSec = 0;
                    // 空泳道或 DNS/DNF 运动员：不自动打开任何设备；
                    // 抢跳 DSQ 仍继续比赛，下一段触板/盲表照常打开以接收原始数据
                    if (!IsLaneReceivingData(state.Lane)) { changed = true; continue; }
                        // 打开运动员即将到达端的触板和盲表
                        bool arriveRight = state.Direction == "→";
                        if (arriveRight) {
                            if (!state.RightTouchpadBroken) state.RightTouchpadStatus = DeviceStatus.Open;
                            if (!state.RightBlindWatch1Broken) state.RightBlindWatch1Status = DeviceStatus.Open;
                            if (!state.RightBlindWatch2Broken) state.RightBlindWatch2Status = DeviceStatus.Open;
                            if (!state.RightBlindWatch3Broken) state.RightBlindWatch3Status = DeviceStatus.Open;
                            if (state.RightManualEnabled) state.RightManualStatus = DeviceStatus.Open;
                        } else {
                            if (!state.LeftTouchpadBroken) state.LeftTouchpadStatus = DeviceStatus.Open;
                            if (!state.LeftBlindWatch1Broken) state.LeftBlindWatch1Status = DeviceStatus.Open;
                            if (!state.LeftBlindWatch2Broken) state.LeftBlindWatch2Status = DeviceStatus.Open;
                            if (!state.LeftBlindWatch3Broken) state.LeftBlindWatch3Status = DeviceStatus.Open;
                            if (state.LeftManualEnabled) state.LeftManualStatus = DeviceStatus.Open;
                        }

                        // 触板打开 = 新分段开始：预创建空分段，后续触板/盲表/手动都写入此分段
                        PreCreateSplit(state.Lane);

                        // 接力项目：只在交接棒段打开出发端出发台
                        // 交接棒 = 每棒最后一段（运动员游回出发端触板）
                        //   2026-06-03 去掉 state.CurrentLap > 0 守卫: 对 4×50m perLeg=1 时, 棒 1 第 1 段 currentLap=0
                        //   也是交接段, 之前守卫拦下导致棒 2 SB 没打开. 4×100m perLeg=2 时棒 1 第 1 段 nextLap=1, 1%2=1
                        //   自然 isNextExchange=false, 不进分支, 守卫冗余, 去掉无害.
                        bool relayStartBlockOpened = false;
                        if (_isRelay) {
                            int totalLapsVal = GetTotalLaps();
                            int legCnt = 4;
                            var rlMatch = System.Text.RegularExpressions.Regex.Match(_currentEvent, @"(\d+)\s*[x×]");
                            if (rlMatch.Success) legCnt = int.Parse(rlMatch.Groups[1].Value);
                            int lapsPerLegVal = totalLapsVal > 0 ? totalLapsVal / legCnt : 1;
                            // 2026-07-13 按左右侧: 已完成段数 = 两侧实际触板数之和. 倒计时=0 时到达触板尚未落,
                            //   该值稳定 (=CurrentLap 但不依赖其 ++ 时序). 下一段是否交接棒 = 下一段为每棒末段且非最后一棒末段.
                            int completedSegs = state.LeftTouchDone + state.RightTouchDone;
                            int nextLap = completedSegs + 1;
                            bool isNextExchange = (lapsPerLegVal > 0) && (nextLap % lapsPerLegVal == 0) && (nextLap < totalLapsVal);
                            if (isNextExchange) {
                                // 2026-06-03 SB 打开侧 = 选手即将到达侧 (= 棒次终点侧 = 下棒起跳侧).
                                //   适用于 4×50m perLeg=1 棒次交替 (棒 1 右终 → 棒 2 左起; 棒 2 左终 → 棒 3 右起 ...).
                                //   4×100m perLeg=2 时到达侧总等于 StartPosition, 行为不变.
                                if (arriveRight) {
                                    if (!state.RightStartBlockBroken) state.RightStartBlockStatus = DeviceStatus.Open;
                                } else {
                                    if (!state.LeftStartBlockBroken) state.LeftStartBlockStatus = DeviceStatus.Open;
                                }
                                relayStartBlockOpened = true;
                                // 2026-07-13 按侧: 泳道倒计时=0 → 交接棒 SB 打开 → 设该侧 HandoffMode + 盖起跳棒次印章 (两模式共用锚点).
                                //   直通: 额外建自算 window (内部已调 MarkHandoffSide). 流程: 只设锚点, 反应时仍走 _relayReactionCalc.
                                int legIdx = lapsPerLegVal > 0 ? nextLap / lapsPerLegVal : 0;   // 0-indexed 起跳棒
                                string handoffSide = arriveRight ? "right" : "left";
                                if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen) {
                                    CreateOrResetDirectSbWindow(state.Lane, handoffSide, legIdx);
                                } else {
                                    MarkHandoffSide(state.Lane, handoffSide, legIdx);
                                }
                            }
                        }

                    AddLog(Loc.F("Str_Log_CountdownDoneDeviceOpenFmt", state.Lane, arriveRight ? Loc.T("Str_Frag_Right") : Loc.T("Str_Frag_Left"),
                        relayStartBlockOpened ? "（含出发台-交接棒检测）" : ""));
                    changed = true;
                }
            }
            if (changed) Broadcast();
        }

        // ═══════════════════════════════════════════════════════════════
        // 比赛控制按钮
        // ═══════════════════════════════════════════════════════════════
        private void Ready_Click(object sender, RoutedEventArgs e) {
            if (BlockIfNoTiming(Loc.T("Str_Action_ReadyPlain"))) return;
            // 状态守卫 → 改本地状态 → 送 0x21；硬件参数在每次 Ready 时由 SendSetMatchEventToHardware 一同下发
            // 2026-05-30 本地点击 (sender!=null) 时检查硬件连接; 硬件回报/WebSocket 远程 (sender==null) 跳过弹窗
            if (sender != null && !EnsureHardwareConnected(Loc.T("Str_RC_Ready"))) return;
            if (_raceState != RaceState.Waiting) {
                // 2026-08-27 原来这里是静默 return —— 现场按了没反应, 操作员不知道为什么,
                //   只能反复按。现在把当前状态和该怎么办说清楚。
                //   本地点击弹窗(操作员正盯着屏幕); 远程调用只写日志, 不能弹窗阻塞服务端。
                string stName = _raceState == RaceState.Ready  ? "已就位"
                              : _raceState == RaceState.Racing ? "比赛进行中"
                                                               : "本组已完赛";
                AddLog(Loc.F("Str_Log_ReadyNotExecutedFmt", stName));
                if (sender != null) {
                    AppMessageBox.Show(
                        Loc.F("Str_Msg_CannotReReadyFmt", stName),
                        Loc.T("Str_MsgTitle_Ready"), MessageBoxButton.OK, MessageBoxImage.Information);
                }
                return;
            }
            // 2026-06-18 新组就位, 清复位抑制 (上一场可能残留)
            _broadcastSuppressing = false;
            // 已确认成绩的组：禁止再次开始比赛
            if (!string.IsNullOrEmpty(_currentEvent) && _currentHeat > 0
                && IsHeatConfirmed(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat)) {
                AddLog(Loc.T("Str_Log_CurrentHeatConfirmedCannotStart"));
                return;
            }
            // 本地点击弹确认；硬件触发或 WebSocket 远程调用（sender==null）跳过
            if (sender != null) {
                string info = string.Format("{0} {1} {2} 第{3}组",
                    _currentGender ?? "", _currentEvent ?? "", _currentStage ?? "", _currentHeat);
                var r = AppMessageBox.Show(
                    Loc.F("Str_Msg_ReadyConfirmFmt", info),
                    Loc.T("Str_MsgTitle_ReadyConfirm"), MessageBoxButton.YesNo, MessageBoxImage.Question);
                if (r != MessageBoxResult.Yes) return;
            }
            // 实际进 Ready 状态 + 推送 0x43 + 0x21 给硬件（仅本地点击时；硬件回流路径 sender==null 不回送）
            EnterReadyStateInternal(pushToHardware: sender != null);
        }

        // Ready 内部入口：状态机更新 + 可选硬件命令推送。
        // - Ready_Click 弹完确认对话框后调用（pushToHardware=本地点击）。
        // - StartRace_Click 自动就位时调用（pushToHardware=true，让硬件先收到 0x43+0x21 进入 Ready，
        //   随后的 0x1C 才会被硬件接受），不弹对话框（用户按发令已明确表示要开始）。
        private void EnterReadyStateInternal(bool pushToHardware) {
            // 2026-05-26 在进 Ready 状态前先把"计时复位"的关键复位动作做一遍, 兼容
            //   用户跳过"计时复位"直接按"准备就绪"的场景 — 此时旧组的滚动时间/leader 显示/
            //   分段跟踪/硬件锚点都可能残留, 后续比赛参数会不对.
            //   注意: 不删除任何 Swimmer.Results (那是"丢弃成绩"语义, 属于 Restart_Click 的
            //   非确认重赛分支, 不应该在 Ready 路径上做).
            _raceTimer.Stop();
            _countdownTimer.Stop();
            // 2026-06-20 进 Ready 前停反应时窗口 timer (上一组未触发的窗口若残留, 进新组会误标 NaN)
            StopReactionWindowTimer();
            _runningTime = 0;
            _raceStartTime = DateTime.MinValue;
            _hwRunningTimeAvailable = false;
            _hwRunningTimeReceivedAt = DateTime.MinValue;
            _hwRunningTimeSec = 0;
            // 2026-06-15 防御性: 清接力 reaction window + 枪响 PreStart 锚点 + pending 反应时缓存
            //   (跟 Restart_Click 7071-7074 对称, 防上场未 Emitted 窗口跨场触发污染新一场比赛日志).
            //   场景: 用户跳过"计时复位"直接按"准备就绪" → calc 残留 → 新一场 OnEvent 复用旧窗口 → 异常 elapsed → 误 Emit.
            if (_relayReactionCalc != null) _relayReactionCalc.Reset();
            _gunPreStartSec = null;
            _pendingPreStartReactions.Clear();
            ClearBackstrokeReleaseWindows();   // 2026-06-23 同步清仰泳出发反应时窗口
            ClearDirectSbWindows();            // 2026-07-13 v8 直通模式 Ready 时同步清 SB window
            ClearDirectStartSbWindows();       // 2026-07-13 直通正常出发 SB 窗口 Ready 时同步清
            _resultConfirmed = false;
            _firstPlaceFinishTime = "";
            _firstPlaceShowStart = DateTime.MinValue;
            _lastLeaderSplitCount = 0;
            _laneSplitCount.Clear();
            _laneSplitShowTime.Clear();
            _laneReactionLastValue.Clear();
            _laneReactionShowTime.Clear();
            // 2026-05-27 "比赛日志" tab: 进 Ready 也清掉 per-lane 事件缓冲 (与 Restart_Click 对称)
            _laneEventLog.Clear();
            try { RefreshLaneEventLogView(); } catch { }
            if (RunningTimeText != null) RunningTimeText.Text = "0.00";
            if (_rawTimingLog != null) _rawTimingLog.Clear();
            // 把硬件也复位到 0 时间, 否则硬件仍在跑上一组的滚动时间; 同时重发 Set_MatchEvent
            // 让硬件用本组的"缺道位图 / 总圈数"重新初始化 (与 Restart_Click 的硬件复位段一致).
            if (pushToHardware && _timingBridge != null && _timingBridge.IsConnected) {
                try { _timingBridge.SendCommand(0x20); } catch { }
                _timingBridge.DelayBetweenFrames(20);
                try { _timingBridge.SendCommand(0x7F); } catch { }
                _timingBridge.DelayBetweenFrames(20);
                try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendSetMatchEventFailedFmt", ex.Message)); }
                _timingBridge.DelayBetweenFrames(20);
                // 2026-05-26 (revised): 上一版"0x20 清 d8 配置位"推断已证伪 —
                //   硬件源码 swimplay.c Reset_Timer (line 4663-4854) / case Timer_Reset_Command (line 5754-5768)
                //   完整调查显示不清 StartFinalPlace/FinalPlace/StartPlace/SwimmingPool_Arrage.
                //   真正根因: PC 端 D4→side 映射错位 (TimingBridge.cs IsFinishEnd 历史命名误导, 应是 isLeftEnd).
                //   已在 line 2619-2628 改成固定物理映射, 此补发保留为双保险, 防止将来 0x20 出新副作用 — 无害.
                try { SendTimingSettingsToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendParamsFailedFmt", ex.Message)); }
                _timingBridge.DelayBetweenFrames(20);
                try { SendStartPositionToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendStartPosFailedFmt", ex.Message)); }
                _timingBridge.DelayBetweenFrames(20);
            }

            _raceState = RaceState.Ready;
            OpenLiveHeat();               // 2026-08-24 迁移第2步: 本组改走当前组库
            // 2026-09-18 OpenLiveHeat() 刚把 heats.state 写成 'racing', 但本机 10 秒
            //   轮询(DbPoll_Tick) 一进 Ready/Racing 就直接跳过不刷 —— 见那边的
            //   "比赛中不动" 注释, 这是刻意的, 保护正在写的当前组。所以本机的"赛程导航"
            //   只能靠这里主动补一次, 不然要等到"确认本组成绩"才会重建, 用户实拍到的
            //   正是这个空档。
            try { RebuildBothNavTrees(); } catch { }
            try { NotifyRemoteDataChanged("racing"); } catch { }
            UpdateRaceStateDisplay();
            // ResetForNewRace 把"出发端"的 Open 状态给对应设备:
            //   普通泳姿: 出发台 Open (= 运动员站台等枪响)
            //   仰泳    : 触板 Open  (= 运动员脚踩触板等枪响)
            bool isBack3 = IsBackstrokeStartEvent(_currentEvent);
            foreach (var state in _laneDeviceStates) {
                state.ResetForNewRace(_laneCloseSettings.StartPosition, isBack3);
            }
            // 立刻刷新泳道状态 UI — 此时 _raceTimer 还没启动（要发令后才启动），
            // 100ms tick 不会自动重绘，必须显式调一次让发令端出发台立即变成打开
            UpdateLaneStatusDisplay();
            AddLog(Loc.T("Str_RC_Ready"));
            PrintRaceHeaderToThermal();   // 2026-06-12 热敏小票表头: 当前项目 + 比赛日期/当前时间 + 分隔线
            // Set_MatchEvent (0x43) 和 发令点已经在 SetCurrentEvent / SetCurrentHeat 同步过了，
            // 这里只送 0x21 准备就绪，硬件据此打开出发台。
            if (pushToHardware && _timingBridge != null && _timingBridge.IsConnected) {
                _timingBridge.SendCommand(0x21);
                AddLog(Loc.T("Str_Log_HwSent0x21"));
            }
            // 2026-08-27 就位 = 这一组马上开赛, 大屏必须回到比赛画面。
            //   原来这里只发 Broadcast() 心跳(不带 modeExplicit), 而 display.html 的
            //   LOCKABLE_MODES 规则是"操作员切过去的视图会锁住, 心跳切不回来" ——
            //   只要中途看过一次 组成绩/出发表/纪录/颁奖, 后面每一组就位大屏都还停在
            //   上一组那个画面。现场跑四组 400 米就是这么撞上的。
            //   BroadcastDisplayMode 带 modeExplicit=true, 会解锁并切回比赛实况。
            //   注意: 这只改【什么时候切】, 不改显示格式和内容。
            //   保留上面的 Broadcast() 不动 —— 它是 100ms 去抖的状态心跳, 别的客户端
            //   (控制页/计时端)靠它更新, 不能拿这条一次性的显示切换去顶替。
            Broadcast();
            BroadcastDisplayMode("SHOW_LIVE_RACE");
        }

        private void StartRace_Click(object sender, RoutedEventArgs e) {
            if (BlockIfNoTiming(Loc.T("Str_Action_ManualStartPlain"))) return;
            // 计时复位后状态会回到 Waiting；点"发令"前用户可能没点"就位"，此时自动先就位再发令。
            // 走 EnterReadyStateInternal 跳过 Ready_Click 的确认对话框（用户按"发令"已明确开始意图），
            // 同时仍把 0x43+0x21 推给硬件，让硬件先进 Ready 再接受 0x1C。
            // 2026-05-30 本地点击 (sender!=null) 时检查硬件连接
            if (sender != null && !EnsureHardwareConnected(Loc.T("Str_Action_ManualStartPlain"))) return;
            if (_raceState == RaceState.Waiting) {
                // 已确认组守卫
                if (!string.IsNullOrEmpty(_currentEvent) && _currentHeat > 0
                    && IsHeatConfirmed(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat)) {
                    AddLog(Loc.T("Str_Log_CurrentHeatConfirmedCannotStart"));
                    return;
                }
                EnterReadyStateInternal(pushToHardware: sender != null);
            }
            if (_raceState != RaceState.Ready) return;
            _raceState = RaceState.Racing;
            _raceStartTime = DateTime.Now;
            _runningTime = 0;
            // 清掉旧硬件锚点：等下一个 0x7F 帧重新对齐到硬件
            _hwRunningTimeAvailable = false;
            _hwRunningTimeReceivedAt = DateTime.MinValue;
            _hwRunningTimeSec = 0;
            // 开始新的原始数据记录
            _rawTimingLog.Clear();
            _rawTimingLog.AppendFormat("{0}\t---\tSTART\t0.000\t发令\r\n", DateTime.Now.ToString("HH:mm:ss.fff"));
            UpdateRaceStateDisplay();

            // 启动计时器
            _raceTimer.Start();
            _countdownTimer.Start();

            // 泳道设备状态：发令后
            // 非仰泳: 所有触板和盲表关闭，出发端的出发台打开 (= 起跳台反应时)
            // 2026-07-03 仰泳: 出发端触板打开 (运动员抓 TP), 出发台关闭 (水中出发不用起跳台).
            //   之前 hardcode 走非仰泳逻辑, 让"泳道实时状态" UI 在仰泳发令后错误切成"出发台打开"
            //   (发令前 EnterReadyStateInternal 走 ResetForNewRace(isBack) 是对的, 但发令 StartRace_Click 覆盖).
            bool startLeft = _laneCloseSettings.StartPosition != "right";
            bool isBackstrokeStart = IsBackstrokeStartEvent(_currentEvent);
            foreach (var state in _laneDeviceStates) {
                state.LeftBlindWatch1Status = DeviceStatus.Closed; state.LeftBlindWatch2Status = DeviceStatus.Closed; state.LeftBlindWatch3Status = DeviceStatus.Closed;
                state.RightBlindWatch1Status = DeviceStatus.Closed; state.RightBlindWatch2Status = DeviceStatus.Closed; state.RightBlindWatch3Status = DeviceStatus.Closed;
                if (isBackstrokeStart) {
                    // 仰泳: 出发端 TP 打开, SB 关闭
                    state.LeftTouchpadStatus = startLeft ? DeviceStatus.Open : DeviceStatus.Closed;
                    state.RightTouchpadStatus = startLeft ? DeviceStatus.Closed : DeviceStatus.Open;
                    state.LeftStartBlockStatus = DeviceStatus.Closed;
                    state.RightStartBlockStatus = DeviceStatus.Closed;
                } else {
                    // 非仰泳: 出发端 SB 打开, TP 关闭
                    state.LeftTouchpadStatus = DeviceStatus.Closed;
                    state.RightTouchpadStatus = DeviceStatus.Closed;
                    state.LeftStartBlockStatus = startLeft ? DeviceStatus.Open : DeviceStatus.Closed;
                    state.RightStartBlockStatus = startLeft ? DeviceStatus.Closed : DeviceStatus.Open;
                }
                // 2026-05-25 修复时间漂移: 用 DateTime 锚点
                double targetSec2 = state.LaneCloseTime > 0 ? state.LaneCloseTime : _laneCloseSettings.LaneCloseTime;
                state.LaneCloseCountdown = targetSec2;
                state.CountdownStartedAt = DateTime.Now;
                state.CountdownTargetSec = targetSec2;
            }

            // 延迟关闭出发台 (仰泳: 关出发端 TP; 非仰泳: 关出发端 SB)
            //   2026-07-09 用户诉求: 仰泳 TP 在 Ready 时打开, 枪响后 StartBlockCloseDelay=0 时关闭 (变灰).
            //   运动员折返回起点端时 LaneCloseCountdown 到 0 自动 Open (line 7666-7677), 循环成立无误伤.
            var sbTimer = new DispatcherTimer();
            sbTimer.Interval = TimeSpan.FromSeconds(_laneCloseSettings.StartBlockCloseDelay);
            sbTimer.Tick += delegate(object s, EventArgs args) {
                sbTimer.Stop();
                foreach (var state in _laneDeviceStates) {
                    if (!state.IsFalseStart) {
                        if (isBackstrokeStart) {
                            if (startLeft) state.LeftTouchpadStatus = DeviceStatus.Closed;
                            else state.RightTouchpadStatus = DeviceStatus.Closed;
                        } else {
                            if (startLeft) state.LeftStartBlockStatus = DeviceStatus.Closed;
                            else state.RightStartBlockStatus = DeviceStatus.Closed;
                        }
                    }
                }
                Broadcast();
            };
            sbTimer.Start();

            // 2026-06-20 反应时收集窗口: 发令后 ReactionEventWindowSec 秒内还没收到合法 SB,
            //   把仍是 0 的 laneState.ReactionTime 标 NaN → 显示 "---", 避免出现 -142.200s 这类错误数据.
            //   裁判仍可手动输入覆盖. 接力第 1 棒同步把 LegReactionTimes[0] 标 NaN.
            StartReactionWindowTimer();

            AddLog(Loc.T("Str_Log_StartRaceBegins"));
            // 发令必须瞬时 — 参数已经在"就位"时同步给硬件了，这里只送 0x1C，硬件立刻启动计时
            if (sender != null && _timingBridge != null && _timingBridge.IsConnected) {
                _timingBridge.SendCommand(0x1C);
                AddLog(Loc.T("Str_Log_HwSent0x1C"));
            }
            // 2026-06-14 手动发令也算发令: PC 端本地补一条"发令时刻" EventBackup 记录
            //   sender != null = 用户本地按发令键 (含硬件回流走的 sender=null 路径排除, 避免双条)
            //   时间用 _gunPreStartSec (若已收到固件 0x22) 或 PC 端 _runningTime (= 0 刚发令)
            //   即使硬件不在线 / 固件版本没烧 v6 / 0x67 查询路径绕过, 本地都有一条发令时刻可对照
            if (sender != null) {
                double gunSec = _gunPreStartSec.HasValue ? _gunPreStartSec.Value : 0.0;
                int gunMin = (int)(gunSec / 60);
                int gunS   = (int)(gunSec % 60);
                int gunCs  = (int)((gunSec - Math.Floor(gunSec)) * 100);
                var gunEvt = new BackupEventInfo {
                    EvtType  = 10,    // 跟固件 v6 push 用同一 EvtType, IsGunEvent=true
                    Lane     = 0xFF,
                    Side     = 0xFF,
                    Hour     = 0,
                    Minute   = (byte)gunMin,
                    Second   = (byte)gunS,
                    Msecond  = (byte)gunCs,
                    DevState = 0,
                    TimeInSeconds = gunSec
                };
                _pendingBackupEvents.Add(gunEvt);
                AddLog(Loc.F("Str_Log_PcBackupGunTimeFmt", gunSec, gunMin, gunS, gunCs));
            }
            Broadcast();
        }

        private void OpenAll_Click(object sender, RoutedEventArgs e) {
            // 2026-05-30 硬件未连接弹窗
            if (!EnsureHardwareConnected(Loc.T("Str_Action_OpenAllLanes"))) return;
            foreach (var s in _laneDeviceStates) {
                s.LeftTouchpadStatus = DeviceStatus.Open;
                s.LeftBlindWatch1Status = DeviceStatus.Open;
                s.LeftBlindWatch2Status = DeviceStatus.Open;
                s.LeftBlindWatch3Status = DeviceStatus.Open;
                s.RightTouchpadStatus = DeviceStatus.Open;
                s.RightBlindWatch1Status = DeviceStatus.Open;
                s.RightBlindWatch2Status = DeviceStatus.Open;
                s.RightBlindWatch3Status = DeviceStatus.Open;
                s.LaneCloseCountdown = 0;
            }
            UpdateLaneStatusDisplay();
            AddLog(Loc.T("Str_Log_AllLanesOpenedPlain"));
            //2026-05-14 同步下发硬件：0x47 D3=0xFF D4=1 全部泳道纳入比赛
            try { if (_timingBridge != null && _timingBridge.IsConnected) _timingBridge.SendLaneOpenClose(-1, true); } catch { }
            Broadcast();
        }

        private void CloseAll_Click(object sender, RoutedEventArgs e) {
            // 2026-05-30 硬件未连接弹窗
            if (!EnsureHardwareConnected(Loc.T("Str_Action_CloseAllLanes"))) return;
            foreach (var s in _laneDeviceStates) {
                s.LeftTouchpadStatus = DeviceStatus.Closed;
                s.LeftBlindWatch1Status = DeviceStatus.Closed;
                s.LeftBlindWatch2Status = DeviceStatus.Closed;
                s.LeftBlindWatch3Status = DeviceStatus.Closed;
                s.RightTouchpadStatus = DeviceStatus.Closed;
                s.RightBlindWatch1Status = DeviceStatus.Closed;
                s.RightBlindWatch2Status = DeviceStatus.Closed;
                s.RightBlindWatch3Status = DeviceStatus.Closed;
                s.LaneCloseCountdown = 0;
            }
            UpdateLaneStatusDisplay();
            AddLog(Loc.T("Str_Log_AllLanesClosedPlain"));
            //2026-05-14 同步下发硬件：0x47 D3=0xFF D4=0 全部泳道移出比赛（屏蔽信号）
            try { if (_timingBridge != null && _timingBridge.IsConnected) _timingBridge.SendLaneOpenClose(-1, false); } catch { }
            Broadcast();
        }

        private void Restart_Click(object sender, RoutedEventArgs e) {
            if (BlockIfNoTiming(Loc.T("Str_RC_ClockReset"))) return;
            // 本地点击"计时复位"先弹确认，避免误按导致丢失计时数据；
            // 硬件触发或 WebSocket 远程调用（sender==null）跳过对话框
            // 2026-05-30 本地点击 (sender!=null) 时检查硬件连接
            if (sender != null && !EnsureHardwareConnected(Loc.T("Str_RC_ClockReset"))) return;
            // 2026-06-03 比赛复位 → 清接力 reaction window (= 防上场残留)
            if (_relayReactionCalc != null) _relayReactionCalc.Reset();
            // 2026-06-14 PreStart 重设计: 复位也清掉枪响 PreStart 锚点和待算反应时缓存 (= 新一场比赛干净状态)
            _gunPreStartSec = null;
            _pendingPreStartReactions.Clear();
            ClearBackstrokeReleaseWindows();   // 2026-06-23 同步清仰泳出发反应时窗口
            ClearDirectStartSbWindows();       // 2026-07-13 同步清直通正常出发 SB 窗口
            // 2026-06-20 复位停反应时窗口 timer (= 跨场不能残留)
            StopReactionWindowTimer();
            // 2026-06-16 盲表成绩历史清空 (每组开始干净状态) + 刷各泳道 ComboBox
            _laneBlindHistory.Clear();
            foreach (var rowUI in _laneRowUIs) {
                if (rowUI.BlindCombo != null) {
                    rowUI.BlindCombo.Items.Clear();
                    rowUI.BlindCombo.SelectedItem = null;
                    rowUI.BlindCombo.Text = "";
                }
            }
            if (sender != null) {
                var r = AppMessageBox.Show(Loc.T("Str_Msg_ClockResetConfirm"), Loc.T("Str_MsgTitle_ClockResetConfirm"), MessageBoxButton.YesNo, MessageBoxImage.Warning);
                if (r != MessageBoxResult.Yes) return;
            }
            // 没当前组（_currentHeat <= 0）也要把状态机硬复位，避免按键静默失效。
            if (_currentHeat <= 0) {
                _raceState = RaceState.Waiting;
            DiscardLiveHeat();            // 2026-08-24 复位=本组作废: 解锁并清当前组库, 不回写
            ClearLiveHeatProgressFile();  // 2026-09-13 本组作废, 进度小文件跟着清
                FlushDeferredSync();          // 2026-08-24 补推比赛中暂存的同步
                if (_raceTimer != null) _raceTimer.Stop();
                if (_countdownTimer != null) _countdownTimer.Stop();
                _runningTime = 0;
                _raceStartTime = DateTime.MinValue;
                _hwRunningTimeAvailable = false;
                _hwRunningTimeReceivedAt = DateTime.MinValue;
                _hwRunningTimeSec = 0;
                // 2026-05-25 移除 _lastResetAt 标记 (原修复 #6): 硬件 PDF 必修 #2 修复完成
                if (RunningTimeText != null) RunningTimeText.Text = "0.00";
                try { UpdateRaceStateDisplay(); } catch { }
                if (sender == null) {
                    try { BroadcastDisplayMode("SHOW_WELCOME"); } catch { Broadcast(); }
                } else if (_timingBridge != null && _timingBridge.IsConnected) {
                    _timingBridge.SendCommand(0x20);
                    _timingBridge.DelayBetweenFrames(20);
                    _timingBridge.SendCommand(0x7F);
                    // 复位也要重发 0x43 Set_MatchEvent，否则硬件清空了"缺道"位图，
                    // 与主服务器实际的本组运动员名单不一致
                    _timingBridge.DelayBetweenFrames(20);
                    try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendSetMatchEventFailedFmt", ex.Message)); }
                    // 2026-05-26 双保险: "0x20 清 0x41 d8" 推断已证伪 (真正根因是 line 2619-2628 D4→side 映射错位, 已修).
                    //   此补发保留, 防止将来 0x20 路径出现新副作用 — 无害.
                    _timingBridge.DelayBetweenFrames(20);
                    try { SendTimingSettingsToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendParamsFailedFmt", ex.Message)); }
                    _timingBridge.DelayBetweenFrames(20);
                    try { SendStartPositionToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendStartPosFailedFmt", ex.Message)); }
                }
                // 2026-06-18 (_currentHeat<=0 分支) 同样推 0 + 阻断硬件残帧
                try { BroadcastRunningTime(); } catch { }
                _broadcastSuppressing = true;
                return;
            }

            // 区分两种"计时器清零"语义：
            //  A) 本组已确认成绩（赛程导航已 [已完赛]）：彻底复位 UI，自动跳到下一组准备开赛。
            //     已确认成绩永久锁定（_confirmedHeats + Swimmer.Results 已落盘），不再受任何影响。
            //  B) 本组未确认成绩（如抢跳召回重赛）：只清当前组的时间数据；备注栏（DSQ/DNS/DNF）保留。
            bool currentHeatConfirmed = !string.IsNullOrEmpty(_currentEvent) && _currentHeat > 0 &&
                _confirmedHeats.Contains(ConfirmedHeatKey(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat));

            // 与硬件"复位"按键语义对齐：按下即生效，不再弹确认对话框（已在函数入口把 0x20 推给硬件）。
            // 已确认成绩的组：成绩在 _confirmedHeats / Swimmer.Results 中已落盘，本次复位不会丢；
            // 未确认的组：当前组的时间/分段数据会被清掉，DSQ/DNS/DNF 状态保留（与之前一致）。

            // ═══ 公共复位：计时器 / 状态 / 显示 ═══
            _raceState = RaceState.Waiting;
            FlushDeferredSync();              // 2026-08-24 补推比赛中暂存的同步
            ClearLiveHeatProgressFile();      // 2026-09-13 复位=本组收尾, 进度小文件清掉, 免得下次启动误恢复
            _raceTimer.Stop();
            _countdownTimer.Stop();
            _runningTime = 0;
            _raceStartTime = DateTime.MinValue;
            // 清掉硬件时间锚点；如果硬件没复位继续发 0x7F，UI 仍会被新帧立刻对齐
            _hwRunningTimeAvailable = false;
            _hwRunningTimeReceivedAt = DateTime.MinValue;
            _hwRunningTimeSec = 0;
            // 2026-05-25 移除 _lastResetAt 标记 (原修复 #6 - 1.5 秒抑制窗口): 硬件 PDF 必修 #2 修复完成
            _resultConfirmed = false;

            _firstPlaceFinishTime = "";
            _firstPlaceShowStart = DateTime.MinValue;
            _lastLeaderSplitCount = 0;   // 2026-05-26 与 display.html 的 _dspFirstDetected 对应
            // 2026-05-27 计时复位时清除"停表"状态, 按钮文字也复位
            _clockPaused = false;
            _pausedRunningTime = 0;
            if (PauseClockBtnText != null) PauseClockBtnText.Text = Loc.T("Str_RC_PauseClock");
            _laneSplitCount.Clear();
            _laneSplitShowTime.Clear();
            _laneReactionLastValue.Clear();
            _laneReactionShowTime.Clear();
            // 2026-05-27 "比赛日志" tab: 清掉所有 per-lane 事件缓冲, 准备下一组接收新数据
            _laneEventLog.Clear();
            try { RefreshLaneEventLogView(); } catch { }
            if (RunningTimeText != null) RunningTimeText.Text = "0.00";

            if (_rawTimingLog != null) _rawTimingLog.Clear();

            AutoAdjustStartPosition();
            // 计时复位：所有泳道全部回到"未开赛/全关闭"状态。
            // ResetForNewRace 会自动把发令端出发台打开（为下一场预备），但复位语义是"全部关闭"，
            // 等用户按"就绪"才打开。这里立即覆盖回 Closed。
            foreach (var state in _laneDeviceStates) {
                state.ResetForNewRace(_laneCloseSettings.StartPosition);
                state.LeftStartBlockStatus = DeviceStatus.Closed;
                state.RightStartBlockStatus = DeviceStatus.Closed;
                //2026-05-31 SB 业务两侧都 Closed, 硬件颜色也跟着清 0 (= 灰), 覆盖 ResetForNewRace 里发令侧 SB Hw=1
                state.HwLeftStartBlockColor = 0;
                state.HwRightStartBlockColor = 0;
            }

            bool stageDoneSwitchToWelcome = false;
            if (currentHeatConfirmed) {
                // A) 已确认：成绩锁定，UI彻底归零；优先自动切到下一组开赛
                int totalHeats = CountHeatsForEvent(_currentAgeGroup, _currentGender, _currentEvent, _currentStage);
                if (_currentHeat < totalHeats) {
                    AddLog(Loc.F("Str_Log_ClockResetAutoNextFmt", _currentHeat, _currentHeat + 1));
                    SetCurrentHeat(_currentHeat + 1);
                } else {
                    // 已是本赛次最后一组：完全清空泳道行（不显示已完赛数据），等待操作员从赛程导航选下一项
                    AddLog(Loc.F("Str_Log_ClockResetStageDoneFmt", _currentHeat));
                    int oldHeat = _currentHeat;
                    _currentHeat = 0;        // 让 GetCurrentHeatSwimmers 返回空，泳道行整体置为"（空泳道）"
                    if (CurrentHeatText != null) CurrentHeatText.Text = Loc.F("Str_Fmt_HeatDoneOfTotal", oldHeat, totalHeats);
                    // 2026-06-04 顺序统一: 性别 组别 项目 赛次
                    if (PoolCurrentEventText != null) PoolCurrentEventText.Text = Loc.F("Str_Fmt_PoolEventDoneFmt",
                        Loc.GenderDisplay(_currentGender),
                        string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] "),
                        _currentEvent, _currentStage);
                    UpdateRaceStateDisplay();
                    UpdateLaneStatusDisplay();
                    stageDoneSwitchToWelcome = true;   // 末尾用 SHOW_WELCOME 取代 SHOW_LIVE_RACE，避免被覆盖
                }
            } else {
                // B) 未确认（抢跳重赛）：清当前组的时间/分段数据，保留备注（DSQ/DNS/DNF/TRI）；停留在当前组
                // 2026-06-04 TRI 加入 keepStatus, 计时复位 不再清掉 TRI 标记 (用户要求: 只 取消备注 能清)
                var currentSwimmers = GetCurrentHeatSwimmers();
                foreach (var sw in currentSwimmers) {
                    bool keepStatus = sw.Status == "DSQ" || sw.Status == "DNS" || sw.Status == "DNF" || sw.Status == "TRI";
                    var result = sw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                    if (result != null) sw.Results.Remove(result);
                    if (!keepStatus) sw.Status = "";
                }
                AddLog(Loc.T("Str_Log_ClockResetRestart"));
                UpdateRaceStateDisplay();
                UpdateLaneStatusDisplay();
            }

            // 仅在用户本地点击复位（sender != null）时把 0x20 + 0x7F 推给硬件，
            // 之后再补发一次 0x43 Set_MatchEvent —— 硬件 0x20 复位会顺带清掉"缺道"位图，
            // 不重发的话主服务器的本组缺道与硬件就不一致了
            // 2026-05-26 双保险: "0x20 清 0x41 d8" 推断已证伪 (真正根因是 line 2619-2628 D4→side 映射错位, 已修).
            //   此补发保留, 防止将来 0x20 路径出现新副作用 — 无害.
            if (sender != null && _timingBridge != null && _timingBridge.IsConnected) {
                _timingBridge.SendCommand(0x20);
                _timingBridge.DelayBetweenFrames(20);
                _timingBridge.SendCommand(0x7F);
                _timingBridge.DelayBetweenFrames(20);
                try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendSetMatchEventFailedFmt", ex.Message)); }
                _timingBridge.DelayBetweenFrames(20);
                try { SendTimingSettingsToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendParamsFailedFmt", ex.Message)); }
                _timingBridge.DelayBetweenFrames(20);
                try { SendStartPositionToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendStartPosFailedFmt", ex.Message)); }
            }
            try { BuildScheduleTree(); } catch { }
            // 最后一次广播：若赛次已结束就直接发 SHOW_WELCOME（包含本次 GetStatusData），
            // 否则发 SHOW_LIVE_RACE。两者只发一次，避免后发的覆盖前发的。
            if (stageDoneSwitchToWelcome) {
                try { BroadcastDisplayMode("SHOW_WELCOME"); } catch { Broadcast(); }
            } else {
                Broadcast();
            }
            // 2026-06-18 复位结束: 立即推 RUNNING_TIME = 0 给大屏 (绕过 100ms 节流), 配合 display _rtAnchor < 0.05 强制清零;
            //   再设阻断标志, 后续硬件 TCP 缓冲里的非零 0x7F 残帧不再推送给大屏 (= 修"大屏 11 秒才清零"bug).
            //   等下次 ProcessTimingData 收到硬件真发 0x7F ≈ 0 时自动解锁.
            try { BroadcastRunningTime(); } catch { }
            _broadcastSuppressing = true;
        }

        /// <summary>
        /// 计时端把【刚确认的这一组】的成绩行推给主服务器, 让主服务器的内存模型跟上。
        /// 成绩对象整体序列化再还原, 不做字段映射 —— 少一个字段就是一处对不上。
        /// </summary>
        /// <summary>
        /// 2026-08-31 操作员在计时端确认"生成组成绩"之后, 通知主服务器也生成它那份。
        /// 不确认就不发 —— 两边要么都有、要么都没有, 不会一边定了稿另一边没有。
        /// </summary>
        // 2026-09-01 通知主服务器生成组成绩 —— 【跟回推成绩一样先落盘再发】。
        //
        //   原来是"没连上就记一行日志然后算了"。后果很实在: 最后一组正好赶上断线,
        //   主服务器就【永远】没有这个项目的组排名表 —— 而它是"文档编辑/输出/打印 →
        //   项目成绩"的数据源。计时端上一切正常, 主服务器上那张表是空的, 谁也想不到
        //   是那一瞬间的断线造成的。
        //
        //   现在走跟 HEAT_CONFIRMED_PUSH 同一套待补传: 落盘 → 能发就发 → 收到回执才删。
        //   重复生成是安全的(整表 DELETE 后重插), 所以宁可多补一次。
        private void PushGenerateEventRanking(string ag, string gd, string ev, string st) {
            try {
                var d = new JObject();
                d["ageGroup"] = ag ?? ""; d["gender"] = gd ?? "";
                d["eventName"] = ev ?? ""; d["stage"] = st ?? "";
                // heat 传 0: 组排名是整个项目一份, 不属于某一组
                string id = "gen_" + PendingPushId(ag, gd, ev, st, 0);
                var env = new JObject();
                env["type"] = "GENERATE_EVENT_RANKING";
                env["id"]   = id;
                env["data"] = d;
                QueuePendingPush(id, env);
                if (_editorSyncClient != null && _editorSyncClient.IsConnected) {
                    _editorSyncClient.Send(env.ToString(Formatting.None));
                    AddLog(Loc.F("Str_Log_NotifiedMainGenRankingFmt", ag, gd, ev, st));
                } else {
                    AddLog(Loc.F("Str_Log_GenRankingNotifyQueuedFmt",
                        ag, gd, ev, st));
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_NotifyGenRankingFailedFmt", ex.Message)); }
        }

        // 2026-09-01 主服务器收到"生成组成绩"的通知。
        //
        //   为什么不是收到就一定能生成: 生成的前提是【本机库里这个项目所有组都已确认】。
        //   最后一组的 HEAT_CONFIRMED_PUSH 和这条通知是先后两条消息, 万一这条先落地
        //   (或者那一组因为道次对不上没写成), 这里就会 pending>0 而生成不出来。
        //   原来的写法是: 生成不出来就算了, 一声不吭 —— 那张表就永远缺一块。
        //
        //   现在生成不出来就【记下来挂着】, 每次再收到回推、每次库轮询, 都重试一遍。
        //   只有真生成出来了才回执, 计时端那边的待补传文件也才会删掉。
        private readonly List<string[]> _pendingEventRankGen = new List<string[]>();

        private void HandleGenerateEventRanking(IWebSocketConnection socket, string msgId,
                                                string ag, string gd, string ev, string st) {
            int made = 0;
            try { made = _meetDb.GenerateEventRankingIfComplete(ag, gd, ev, st, "计时端"); }
            catch (Exception ex) { AddLog(Loc.F("Str_Log_GenEventRankingFailedFmt", ex.Message)); }

            if (made > 0) {
                RemovePendingEventRankGen(ag, gd, ev, st);
                AppendTriPlaceholdersToEventRanking(ag, gd, ev, st);
                try { ApplyEventRankingsFromDb(); } catch { }
                try {
                    if (socket != null && !string.IsNullOrEmpty(msgId)) {
                        var ack = new JObject();
                        ack["type"] = "HEAT_CONFIRMED_ACK";
                        ack["id"] = msgId;
                        socket.Send(ack.ToString(Formatting.None));
                    }
                } catch { }
                return;
            }

            // 生成不出来 —— 挂起等重试, 并且不回执(计时端会再补一次)
            bool exists = _pendingEventRankGen.Any(x =>
                x[0] == (ag ?? "") && x[1] == (gd ?? "") && x[2] == (ev ?? "") && x[3] == (st ?? ""));
            if (!exists) {
                _pendingEventRankGen.Add(new string[] { ag ?? "", gd ?? "", ev ?? "", st ?? "" });
                AddLog(Loc.F("Str_Log_RankingPendingFmt",
                    ag, gd, ev, st));
            }
        }

        private void RemovePendingEventRankGen(string ag, string gd, string ev, string st) {
            _pendingEventRankGen.RemoveAll(x =>
                x[0] == (ag ?? "") && x[1] == (gd ?? "") && x[2] == (ev ?? "") && x[3] == (st ?? ""));
        }

        /// <summary>2026-09-01 把挂起的"生成组成绩"再试一遍。收到回推之后、库轮询时各调一次。</summary>
        private void RetryPendingEventRankGen() {
            if (_pendingEventRankGen.Count == 0) return;
            var todo = _pendingEventRankGen.ToList();
            foreach (var x in todo) {
                int made = 0;
                try { made = _meetDb.GenerateEventRankingIfComplete(x[0], x[1], x[2], x[3], "计时端(补)"); }
                catch { }
                if (made > 0) {
                    RemovePendingEventRankGen(x[0], x[1], x[2], x[3]);
                    AddLog(Loc.F("Str_Log_PendingRankingDoneFmt", x[0], x[1], x[2], x[3]));
                    AppendTriPlaceholdersToEventRanking(x[0], x[1], x[2], x[3]);
                    try { ApplyEventRankingsFromDb(); } catch { }
                }
            }
        }

        private void PushHeatConfirmedToServer() {
            var rows = new JArray();
            foreach (var sw in GetCurrentHeatSwimmers()) {
                var r = sw.Results.FirstOrDefault(x => x.Stage == _currentStage && x.Heat == _currentHeat);
                if (r == null) continue;
                rows.Add(JObject.Parse(JsonConvert.SerializeObject(r)));
            }
            var d = new JObject();
            d["ageGroup"]  = _currentAgeGroup ?? "";
            d["gender"]    = _currentGender ?? "";
            d["eventName"] = _currentEvent ?? "";
            d["stage"]     = _currentStage ?? "";
            d["heat"]      = _currentHeat;
            d["results"]   = rows;
            // 2026-08-29 断线补传: 把当前组库的整份快照一起带上, 服务器拿它写自己的 meet.db。
            //   必须在 CommitLiveHeat() 之前取 —— 确认流程里本方法确实排在它前面(见 ConfirmResult_Click),
            //   提交之后当前组库就被清空了。
            //   取不到也不致命: 内存模型照样补得上, 只是服务器的 meet.db 补不了, 所以要喊一声。
            try {
                var live = _meetDb.PeekLiveHeat();
                // 2026-09-14 当前组库关着时(解锁后再确认就是这种), 快照取不到 ——
                //   原来只喊一声就算了, 结果主服务器那份库补不上, 它自己的 10 秒回读
                //   又会拿旧值把内存盖回去, 于是主服务器上"改完过一会儿变回去"。
                //   现在拿内存现搭一份, 带的成绩就是刚改完的那份。
                if (live == null) {
                    live = new SwimmingScoreboard.Db.LiveHeat {
                        AgeGroup = _currentAgeGroup ?? "", Gender = _currentGender ?? "",
                        EventName = _currentEvent ?? "", Stage = _currentStage ?? "",
                        Heat = _currentHeat, TotalHeats = _totalHeats,
                        RaceState = "confirmed", ResultConfirmed = true,
                        Lanes = BuildLiveLanes()
                    };
                    AddLog(Loc.T("Str_Log_SnapshotEmptyRebuilt"));
                }
                if (live != null) d["liveHeat"] = JObject.Parse(JsonConvert.SerializeObject(live));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_SnapshotFailedFmt", ex.Message)); }

            string id = PendingPushId(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat);
            var env = new JObject();
            env["type"] = "HEAT_CONFIRMED_PUSH";
            env["id"]   = id;
            env["data"] = d;

            // 【先落盘, 再发送】—— 顺序不能反。
            //   发送失败、发送途中断线、服务器没起来, 成绩都还在待补传目录里躺着,
            //   下次连上自动补。收到服务器回执才删。
            QueuePendingPush(id, env);
            if (_editorSyncClient != null && _editorSyncClient.IsConnected) {
                _editorSyncClient.Send(env.ToString(Formatting.None));
                AddLog(Loc.F("Str_Log_PushedResultToMainFmt", _currentHeat, rows.Count));
            } else {
                AddLog(Loc.F("Str_Log_ResultQueuedFmt",
                    _currentHeat, rows.Count));
            }
        }

        // ══════════════════════════════════════════════════════════════════
        // 离线摆渡 (2026-08-29)
        //
        // 没有网的时候怎么办: 计时端把成绩导成一个文件, U盘拿到主服务器导进去。
        // 导出的每一组, 内容跟联机回推(HEAT_CONFIRMED_PUSH)【完全一样】——
        // 导入就是把这些组挨个喂给同一个处理函数。一套接收代码, 两条路进来,
        // 不可能出现"联机对、离线不对"这种事。
        // 重复导入是安全的: 成绩全是按 (项目|赛次|组次|道次) 覆盖写。
        // ══════════════════════════════════════════════════════════════════

        private void ExportResultsFile_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var heats = _meetDb.ListConfirmedHeats();
                if (heats.Count == 0)
                {
                    AppMessageBox.Show(Loc.T("Str_Msg_NoConfirmedToExport"),
                        Loc.T("Str_MsgTitle_ExportResults"), MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                var dlg = new Microsoft.Win32.SaveFileDialog();
                dlg.Filter = Loc.T("Str_Filter_ResultJson");
                dlg.Title = Loc.T("Str_MsgTitle_ExportResults");
                dlg.FileName = (_competitionName ?? Loc.T("Str_FileName_Results")) + "_" + Loc.T("Str_FileName_Results") + "_" +
                               DateTime.Now.ToString("yyyyMMdd_HHmm") + ".json";
                if (dlg.ShowDialog() != true) return;

                var arr = new JArray();
                int withDb = 0;
                foreach (var h in heats)
                {
                    string ag = h[0], gd = h[1], ev = h[2], st = h[3];
                    int ht = int.Parse(h[4]);

                    // 内存模型那份(主服务器拿它刷赛程树和项目成绩)
                    var rows = new JArray();
                    foreach (var sw in GetHeatEntries(ag, gd, ev, st, ht))
                    {
                        var r = sw.Results.FirstOrDefault(x => x.Stage == st && x.Heat == ht);
                        if (r != null) rows.Add(JObject.Parse(JsonConvert.SerializeObject(r)));
                    }
                    var d = new JObject();
                    d["ageGroup"] = ag; d["gender"] = gd; d["eventName"] = ev;
                    d["stage"] = st; d["heat"] = ht; d["results"] = rows;

                    // 竞赛库那份(主服务器拿它写自己的 meet.db)
                    var live = _meetDb.BuildLiveHeatFromDb(ag, gd, ev, st, ht);
                    if (live != null) { d["liveHeat"] = JObject.Parse(JsonConvert.SerializeObject(live)); withDb++; }
                    arr.Add(d);
                }

                var root = new JObject();
                root["type"] = "RESULTS_EXPORT";
                root["competition"] = _competitionName ?? "";
                root["exportedAt"] = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                root["exportedBy"] = Environment.MachineName;
                root["heats"] = arr;
                File.WriteAllText(dlg.FileName, root.ToString(Formatting.Indented), Encoding.UTF8);

                AddLog(Loc.F("Str_Log_ResultExportedFmt",
                    arr.Count, withDb, IOPath.GetFileName(dlg.FileName)));
                AppMessageBox.Show(
                    Loc.F("Str_Msg_ExportedHeatsFmt", arr.Count), Loc.T("Str_MsgTitle_ExportResults"), MessageBoxButton.OK, MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                AddLog(Loc.F("Str_Log_ResultExportFailedFmt", ex.Message));
                AppMessageBox.Show(Loc.F("Str_Msg_ExportResultsFailedFmt", ex.Message), Loc.T("Str_MsgTitle_ExportResults"),
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void ImportResultsFile_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var dlg = new Microsoft.Win32.OpenFileDialog();
                dlg.Filter = Loc.T("Str_Filter_ResultJson");
                dlg.Title = Loc.T("Str_MsgTitle_ImportResults");
                if (dlg.ShowDialog() != true) return;

                var root = JObject.Parse(File.ReadAllText(dlg.FileName, Encoding.UTF8));
                if (root["type"] == null || root["type"].ToString() != "RESULTS_EXPORT")
                { AppMessageBox.Show(Loc.T("Str_Msg_NotAResultsFile"), Loc.T("Str_MsgTitle_ImportResults"), MessageBoxButton.OK, MessageBoxImage.Warning); return; }

                string fromMeet = root["competition"] != null ? root["competition"].ToString() : "";
                if (!string.IsNullOrEmpty(fromMeet) && !string.IsNullOrEmpty(_competitionName)
                    && fromMeet != _competitionName)
                {
                    // 赛事对不上还导进去, 就是把别的比赛的成绩灌进本场 —— 必须拦。
                    var yn = AppMessageBox.Show(Loc.F("Str_Msg_MeetMismatchConfirmFmt",
                        fromMeet, _competitionName), Loc.T("Str_MsgTitle_MeetMismatch"),
                        MessageBoxButton.YesNo, MessageBoxImage.Warning);
                    if (yn != MessageBoxResult.Yes) return;
                }

                var arr = root["heats"] as JArray;
                if (arr == null || arr.Count == 0)
                { AppMessageBox.Show(Loc.T("Str_Msg_FileHasNoResults"), Loc.T("Str_MsgTitle_ImportResults"), MessageBoxButton.OK, MessageBoxImage.Information); return; }

                int ok = 0, bad = 0, lockedSkip = 0;
                var lockedList = new List<string>();
                // 2026-09-01 导进来的组涉及哪些 (组别|性别|项目|赛次) —— 导完要按项目补生成组排名表
                var touched = new List<string[]>();
                foreach (var t in arr)
                {
                    var d = t as JObject;
                    if (d == null) { bad++; continue; }
                    // 2026-09-12 本机已经标注已完赛的组不许被覆盖 —— 已完赛的组不在修改范围。
                    //   摆渡文件里装的都是别处确认过的成绩, 灌进来就是把本机那份盖掉。
                    {
                        string lag = d["ageGroup"] != null ? d["ageGroup"].ToString() : "";
                        string lgd = d["gender"]   != null ? d["gender"].ToString()   : "";
                        string lev = d["eventName"]!= null ? d["eventName"].ToString(): "";
                        string lst = d["stage"]    != null ? d["stage"].ToString()    : "";
                        int lht = 0;
                        if (d["heat"] != null) int.TryParse(d["heat"].ToString(), out lht);
                        if (ResultLockedWhy(lag, lgd, lev, lst, lht) != null) {
                            lockedSkip++;
                            string one = string.Format("{0} {1} {2} 第{3}组", lgd, lev, lst, lht);
                            if (!lockedList.Contains(one)) lockedList.Add(one);
                            AddLog(Loc.F("Str_Log_ImportResultSkippedFmt", one));
                            continue;
                        }
                    }
                    // 走的是跟联机回推【一模一样】的入口, socket 传 null(不用回执)
                    var msg = new JObject();
                    msg["type"] = "HEAT_CONFIRMED_PUSH";
                    msg["data"] = d;
                    try {
                        HandleHeatConfirmedPush(null, msg); ok++;
                        string kag = d["ageGroup"] != null ? d["ageGroup"].ToString() : "";
                        string kgd = d["gender"]   != null ? d["gender"].ToString()   : "";
                        string kev = d["eventName"]!= null ? d["eventName"].ToString(): "";
                        string kst = d["stage"]    != null ? d["stage"].ToString()    : "";
                        if (!string.IsNullOrEmpty(kev) &&
                            !touched.Any(x => x[0]==kag && x[1]==kgd && x[2]==kev && x[3]==kst))
                            touched.Add(new string[] { kag, kgd, kev, kst });
                    }
                    catch (Exception ex) { bad++; AddLog(Loc.F("Str_Log_ImportHeatFailedFmt", ex.Message)); }
                }

                // 2026-09-01 【离线摆渡也要定稿】。
                //   原来这条路只把成绩灌进库, 从不生成组排名表 —— 而"文档编辑/输出/打印 →
                //   项目成绩"读的就是那张表。U盘导完, 库里成绩齐全, 那张表却一行没有,
                //   于是"确认过的成绩查不到", 还看不出原因。
                //   这里不弹窗(confirm 传 null): 该问的已经在计时端确认那一刻问过了,
                //   导入的都是【已确认】的组。全部组齐了才会真生成, 不齐就什么都不做。
                int gen = 0;
                foreach (var k in touched) {
                    try {
                        int made = _meetDb.GenerateEventRankingIfComplete(k[0], k[1], k[2], k[3], "文件导入");
                        if (made > 0) {
                            gen++;
                            AddLog(Loc.F("Str_Log_RankingGeneratedFmt", k[0], k[1], k[2], k[3], made));
                            AppendTriPlaceholdersToEventRanking(k[0], k[1], k[2], k[3]);
                        }
                    } catch (Exception ex) { AddLog(Loc.F("Str_Log_PostImportRankingFailedFmt", ex.Message)); }
                }
                if (gen > 0) { try { ApplyEventRankingsFromDb(); } catch { } }

                try { BuildScheduleTree(); } catch { }
                try { CalculateTeamScores(); } catch { }
                try { RefreshOverviewStats(); } catch { }
                // 2026-09-20 每一组都是经 HandleHeatConfirmedPush 灌的(见上面那句调用)——
                // 那条路自己已经 SaveWithoutPush+PushDataChanged 过了, 这里再退回
                // AutoSaveData() 反而是把已经省下来的整包又推一次, 一样改成轻量收尾。
                try { SaveWithoutPush(); PushDataChanged("meet"); } catch { }
                try { Broadcast(); } catch { }

                AddLog(Loc.F("Str_Log_ImportedFromFileFmt",
                    ok, bad > 0 ? "，" + bad + " 个失败" : "",
                    lockedSkip > 0 ? "，" + lockedSkip + " 个本机已完赛跳过" : ""));
                string lockNote = lockedSkip == 0 ? ""
                    : ("\n\n有 " + lockedSkip + " 个组本机已经标注已完赛，没有覆盖：\n  · "
                       + string.Join("\n  · ", lockedList.Take(20).ToArray()));
                AppMessageBox.Show(Loc.F("Str_Msg_ImportedHeatsFmt", ok,
                    bad > 0 ? Loc.F("Str_Msg_ImportedHeatsBadNoteFmt", bad) : "", lockNote),
                    Loc.T("Str_MsgTitle_ImportResults"), MessageBoxButton.OK,
                    (bad > 0 || lockedSkip > 0) ? MessageBoxImage.Warning : MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                AddLog(Loc.F("Str_Log_ImportResultFailedFmt", ex.Message));
                AppMessageBox.Show(Loc.F("Str_Msg_ImportResultsFailedFmt", ex.Message), Loc.T("Str_MsgTitle_ImportResults"),
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        // ══════════ 待补传队列 ══════════
        // 主服务器停了照样比赛, 成绩先存本机; 服务器回来了自动补上去。
        // 队列就是一个目录、一组 json 文件 —— 断电、崩溃、强杀都不会丢, 内存队列做不到这点。
        // 文件名用"赛次+组次", 所以同一组重confirm 会覆盖同一个文件, 不会堆出重复。

        private string PendingPushDir() {
            string d = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database", "pending_push");
            if (!Directory.Exists(d)) Directory.CreateDirectory(d);
            return d;
        }

        private static string PendingPushId(string ag, string gd, string ev, string st, int heat) {
            string s = string.Format("{0}_{1}_{2}_{3}_h{4}", ag ?? "", gd ?? "", ev ?? "", st ?? "", heat);
            foreach (char c in IOPath.GetInvalidFileNameChars()) s = s.Replace(c, '_');
            return s;
        }

        private void QueuePendingPush(string id, JObject env) {
            try {
                File.WriteAllText(IOPath.Combine(PendingPushDir(), id + ".json"),
                                  env.ToString(Formatting.None), Encoding.UTF8);
            } catch (Exception ex) {
                // 这里失败意味着断线后这一组真会丢, 必须喊出来, 不能吞。
                AddLog(Loc.F("Str_Log_QueueSaveFailedFmt", ex.Message));
            }
        }

        /// <summary>连上主服务器时调一次: 把断线期间攒下的组按时间顺序补上去。</summary>
        private void DrainPendingPush() {
            if (_editorSyncClient == null || !_editorSyncClient.IsConnected) return;
            try {
                var files = new DirectoryInfo(PendingPushDir()).GetFiles("*.json")
                                .OrderBy(f => f.LastWriteTimeUtc).ToList();
                if (files.Count == 0) return;
                AddLog(Loc.F("Str_Log_ResendQueueStartFmt", files.Count));
                foreach (var f in files) {
                    try { _editorSyncClient.Send(File.ReadAllText(f.FullName, Encoding.UTF8)); }
                    catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendItemFailedFmt", f.Name, ex.Message)); }
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ScanResendDirFailedFmt", ex.Message)); }
        }

        /// <summary>收到服务器回执 → 这一组确实进库了, 删掉待补传文件。</summary>
        private void HandleHeatConfirmedAck(JObject msg) {
            string id = msg["id"] != null ? msg["id"].ToString() : "";
            if (string.IsNullOrEmpty(id)) return;
            try {
                string p = IOPath.Combine(PendingPushDir(), id + ".json");
                if (File.Exists(p)) { File.Delete(p); AddLog(Loc.F("Str_Log_MainServerReceivedFmt", id)); }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_CleanupResendFailedFmt", ex.Message)); }
        }

        /// <summary>
        /// 主服务器收到计时端推来的"本组已确认": 写进内存模型 + 落盘 + 刷界面。
        /// 按泳道号对上人 —— 跟 GetHeatEntries 是同一套口径。
        /// </summary>
        private void HandleHeatConfirmedPush(IWebSocketConnection socket, JObject msg) {
            var d = msg["data"] as JObject;
            if (d == null) return;
            string ag = d["ageGroup"] != null ? d["ageGroup"].ToString() : "";
            string gd = d["gender"] != null ? d["gender"].ToString() : "";
            string ev = d["eventName"] != null ? d["eventName"].ToString() : "";
            string st = d["stage"] != null ? d["stage"].ToString() : "";
            int ht = d["heat"] != null ? (int)d["heat"] : 0;
            if (string.IsNullOrEmpty(ev) || ht <= 0) return;

            var swimmers = GetHeatEntries(ag, gd, ev, st, ht);
            var arr = d["results"] as JArray;
            int applied = 0;
            if (arr != null) {
                foreach (var t in arr) {
                    LaneResult lr;
                    try { lr = JsonConvert.DeserializeObject<LaneResult>(t.ToString(Formatting.None)); }
                    catch { continue; }
                    if (lr == null) continue;
                    var sw = swimmers.FirstOrDefault(s => {
                        var sa = s.GetAssignmentForStage(st);
                        int ln = sa != null ? sa.Lane : s.Lane;
                        return ln == lr.Lane;
                    });
                    if (sw == null) continue;
                    var old = sw.Results.FirstOrDefault(x => x.Stage == st && x.Heat == ht);
                    if (old != null) sw.Results.Remove(old);
                    sw.Results.Add(lr);
                    // 2026-08-30 名次还要落到 CurrentRank —— 团体总分(CalculateTeamScores)
                    //   取分读的是它。本机跑的组由 RankHeatGroup 顺手设上了, 而回推/文件
                    //   导入进来的成绩没人设 => 计时端跑出来的成绩【一分都不计】, 还不报错。
                    if (lr.Rank > 0) sw.CurrentRank = lr.Rank;
                    // ══════════════════════════════════════════════════════
                    // 2026-09-01 判罚状态也要【镜像到运动员对象】上。
                    //
                    // 计时端标 DNS 时改的是两处: swimmer.Status 和 成绩行 res.Status。
                    // 回推过来的只有成绩行那一份 —— 这里原来只 Results.Add(lr), 从不设
                    // sw.Status。而程序里有十几处是看 sw.Status 判"这人被判罚了没":
                    // 大屏 payload、打印成绩、团体总分、破纪录复核…… 于是主服务器上
                    // 判罚的人被当成正常人: 大屏照显成绩、还挂着 MR、成绩单上占着名次。
                    //
                    // 与其把那十几处一处一处改成"成绩行优先", 不如在【入口】就把两份
                    // 对齐 —— 少一处漏改的机会。
                    // 撤销判罚时推过来的是空状态, 这里也要跟着清掉, 否则撤了还留着。
                    {
                        string pushedStatus = lr.Status ?? "";
                        string memStatus = sw.Status ?? "";
                        if (pushedStatus.Length > 0
                            || ResultOrdering.IsJudged(memStatus) || memStatus == "TRI")
                            sw.Status = pushedStatus;
                        if (ResultOrdering.IsJudged(pushedStatus)) sw.CurrentRank = 0;
                    }
                    applied++;
                }
            }
            _confirmedHeats.Add(ConfirmedHeatKey(ag, gd, ev, st, ht));
            ClearUnlockMark(ag, gd, ev, st, ht);   // 2026-09-13 重新确认 = 解锁标记作废

            // 2026-08-29 把成绩写进主服务器【自己的】竞赛库。
            //   联机时计时端已经通过 RPC 写过一次, 这里再写一次是幂等的(全是 UPDATE ... WHERE id);
            //   而断线期间跑的组, 成绩只在计时端库里, 全靠这里补进来。
            var lh = d["liveHeat"] as JObject;
            if (lh != null) {
                try {
                    var live = JsonConvert.DeserializeObject<SwimmingScoreboard.Db.LiveHeat>(lh.ToString(Formatting.None));
                    if (live != null) _meetDb.CommitHeatFromWire(live, "计时端");
                } catch (Exception ex) { AddLog(Loc.F("Str_Log_WriteTimingResultFailedFmt", ex.Message)); }
            }

            // 2026-08-30 成绩已经进了【本机这份】竞赛库 —— 名次以它为准, 回读覆盖内存。
            //   计时端推过来的那份是它确认【之前】的(推送排在 CommitLiveHeat 之前),
            //   不带项目名次; 而且两台机器各有各的库, 本机显示当然要以本机库为准。
            //   这样主服务器上看到的名次 = 主服务器库里的名次, 不存在第二个真相。
            ApplyHeatFromDb(ag, gd, ev, st, ht);

            // 2026-08-31 服务器【不在这里自动生成】组成绩。
            //   生成是定稿动作, 要由操作员在计时端弹窗确认。确认之后计时端会发
            //   GENERATE_EVENT_RANKING 过来, 那时才生成 —— 保证两边要么都有、要么都没有。
            // 2026-09-01 但如果那条通知【先到了】(那会儿这一组还没写进来, 生成不出来),
            //   它就挂在 _pendingEventRankGen 里等着。这一组刚写完, 正是重试的时候。
            try { RetryPendingEventRankGen(); } catch { }

            // 回执: 计时端据此删掉待补传文件。没有回执它就一直留着, 下次连上再补 ——
            // 宁可重复补传(幂等、安全), 也不能悄悄丢一组成绩。
            try {
                if (socket != null) {
                    var ack = new JObject();
                    ack["type"] = "HEAT_CONFIRMED_ACK";
                    ack["id"] = msg["id"] != null ? msg["id"].ToString() : "";
                    socket.Send(ack.ToString(Formatting.None));
                }
            } catch { }
            // 2026-08-28 团体总分是从 _swimmers 现算的。本机确认成绩时由
            //   ScoringConfigCore/CalcTeamScore 触发重算, 但计时端回推这条路
            //   原来谁都不触发 —— 主服务器上的团体总分会一直停在旧值。
            try { CalculateTeamScores(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RecalcTeamScoreFailedFmt", ex.Message)); }
            try { BuildScheduleTree(); } catch { }
            try { RefreshOverviewStats(); } catch { }
            // 2026-09-20 CalculateTeamScores() 内部已经落盘+按需整包推送过一次(团体总分是
            //   package-only 字段, 确实要让编排端看到); 这里落的成绩本身是 meetDb 里的东西
            //   (CommitHeatFromWire 已经写过库), 编排端能靠 DATA_CHANGED→DbPoll_Tick 的
            //   RefreshChangedFromDb 追上, 不用再重复推一次整包(等于省掉一次多余的整包序列化)。
            try { SaveWithoutPush(); PushDataChanged("meet"); } catch (Exception ex) { AddLog(Loc.F("Str_Log_PushbackSaveFailedFmt", ex.Message)); }
            try { Broadcast(); } catch { }
            AddLog(Loc.F("Str_Log_TimingPushbackReceivedFmt",
                ag, gd, ev, ht, applied));
        }

        // 2026-05-27 "停表" 按钮 - 切换 _clockPaused 状态:
        //   关 → 开: 快照当前 _runningTime, 之后 RaceTimer_Tick 显示快照值;
        //              GetStatusData 广播 clockPaused=true + pausedRunningTime, EXE/HTML/大屏冻结显示.
        //   开 → 关: 清快照, 显示恢复实时. 硬件全程不受影响(没发任何命令给硬件).
        private void PauseClock_Click(object sender, RoutedEventArgs e) {
            _clockPaused = !_clockPaused;
            if (_clockPaused) {
                _pausedRunningTime = _runningTime;
                if (PauseClockBtnText != null) PauseClockBtnText.Text = Loc.T("Str_RC_ResumeClock");
                AddLog(Loc.F("Str_Log_ClockPausedFmt", TimeFormatter.FormatRunning(_pausedRunningTime)));
            } else {
                if (PauseClockBtnText != null) PauseClockBtnText.Text = Loc.T("Str_RC_PauseClock");
                AddLog(Loc.F("Str_Log_ClockResumedFmt", TimeFormatter.FormatRunning(_runningTime)));
            }
            // 立刻刷新 RunningTimeText 一次, 不等下个 100ms tick
            try {
                if (RunningTimeText != null) {
                    double showT = _clockPaused ? _pausedRunningTime : _runningTime;
                    RunningTimeText.Text = TimeFormatter.FormatRunning(showT);
                }
            } catch { }
            Broadcast();
        }

        private void ConfirmResult_Click(object sender, RoutedEventArgs e) {
            if (BlockIfNoTiming(Loc.T("Str_MsgTitle_ConfirmResult"))) return;
            // 本地按钮点击时弹确认对话框，WebSocket远程调用时(sender==null)跳过
            if (sender != null) {
                string info = Loc.F("Str_Fmt_ConfirmResultInfo", Loc.GenderDisplay(_currentGender), _currentEvent, _currentStage, _currentHeat);
                var r = AppMessageBox.Show(
                    Loc.F("Str_Msg_ConfirmResultFmt", info),
                    Loc.T("Str_MsgTitle_ConfirmResult"), MessageBoxButton.YesNo, MessageBoxImage.Question);
                if (r != MessageBoxResult.Yes) return;
            }
            _countdownTimer.Stop();
            _raceState = RaceState.Finished;
            _resultConfirmed = true;
            FlushDeferredSync();              // 2026-08-24 补推比赛中暂存的同步

            // 起跳犯规判罚改为人工：硬件检测到的抢跳/可疑只标红反应时（IsSuspectFalseStart），
            // 不再在确认时自动 DSQ。裁判要判罚需在控制台手动按 DSQ 按钮 (MARK_DSQ)。

            // 把当前组锁定到 _confirmedHeats（先于其它 UI 步骤，避免任何异常导致锁定状态没生效）
            _confirmedHeats.Add(ConfirmedHeatKey(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat));
            // 2026-09-13 解锁改完再确认 → 解锁标记作废, 这一组重新锁上
            ClearUnlockMark(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat);
            ClearLiveHeatProgressFile();   // 2026-09-13 本组收尾, 进度小文件没用了
            // 2026-08-28 计时端确认成绩后, 必须把这一组【回推给主服务器】。
            //   之前只写进了主服务器的 meet.db, 但主服务器【内存里的模型没变】——
            //   赛程树的"已完赛"读 _confirmedHeats, 项目成绩读 _swimmers[].Results,
            //   两样都没更新, 所以主服务器上看不到任何已完赛的痕迹。
            //   只推这一组的行, 不推整包。
            if (IsTimingClientMode) { try { PushHeatConfirmedToServer(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_PushHeatConfirmedFailedFmt", ex.Message)); } }

            // 立即重建赛程树：哪怕下面 UpdateHeatRanking/AutoSaveData/SaveRawTimingLog 偶发异常，
            // "已完赛"标记也不会丢；之前用 try{}catch{} 把异常吞掉，"偶尔不打标记"就源于此。
            try { BuildScheduleTree(); }
            catch (Exception ex) { AddLog(Loc.F("Str_Log_NavRefreshFailedEarlyFmt", ex.Message)); }

            try { UpdateHeatRanking(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RankingCalcFailedFmt", ex.Message)); }
            try { UpdateRecordsAfterConfirm(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_UpdateRecordsFailedFmt", ex.Message)); }
            try { AutoSaveData(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_AutoSaveFailedFmt", ex.Message)); }
            try { CommitLiveHeat(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_MeetDbCommitFailedFmt", ex.Message)); }
            try { UpdateLaneStatusDisplay(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_LaneStatusRefreshFailedFmt", ex.Message)); }
            try { UpdateRaceStateDisplay(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RaceStateRefreshFailedFmt", ex.Message)); }

            AddLog(Loc.F("Str_Log_HeatResultConfirmedFmt",
                string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] "),
                _currentGender, _currentEvent, _currentStage, _currentHeat));

            try { SaveRawTimingLog(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_SaveRawDataFailedFmt", ex.Message)); }

            // 刷新成绩与排名页面
            try { UpdateResultHeatCombo(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResultHeatComboFailedFmt", ex.Message)); }
            try { RefreshResultGrid(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResultGridRefreshFailedFmt", ex.Message)); }

            // 末尾再刷一次赛程导航，吸收期间任何异步 UI 状态变化
            try { BuildScheduleTree(); }
            catch (Exception ex) { AddLog(Loc.F("Str_Log_NavRefreshFailedLateFmt", ex.Message)); }

            // 检查该项目该阶段是否所有组都已完赛（广播给HTML控制端）
            try { CheckStageComplete(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_StageCompleteCheckFailedFmt", ex.Message)); }

            // EXE本地也弹晋级确认（当从EXE按钮触发时）
            if (sender != null) {
                try { CheckStageCompleteLocal(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_StageCompleteCheckLocalFailedFmt", ex.Message)); }
            }

            Broadcast();

            // 确认成绩后大屏自动从"比赛视图"切换到"本组成绩"
            try { BroadcastDisplayMode("SHOW_HEAT_RESULT"); } catch (Exception ex) { AddLog(Loc.F("Str_Log_SwitchDisplayHeatResultFailedFmt", ex.Message)); }

            // 2026-06-05 全部 UI/数据/广播 流程完成后, 自动写本组成绩 txt 到配置目录
            try { AutoSaveCurrentHeatTxt(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_AutoSaveTxtFailedFmt", ex.Message)); }
            // 2026-06-05 自动写本组 比赛日志 PDF (HTML + Edge headless 转 PDF; 失败保留 HTML)
            try { AutoSaveCurrentHeatLog(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_AutoSaveHeatLogFailedFmt", ex.Message)); }
            // 2026-06-08 P3-A: 每组确认成绩后强制 Gen2 GC. 这是长时间运行 30+ 组后变慢的兜底:
            //   不管是 WPF 视觉树残留 / Newtonsoft 反射缓存 / Fleck 队列 / ObservableCollection 订阅链,
            //   只要理论上可回收, 这里都能扫掉. 用户此刻正在等下一组准备, 200ms GC 暂停可接受.
            try {
                GC.Collect(2, GCCollectionMode.Forced, blocking: true);
                GC.WaitForPendingFinalizers();
                GC.Collect(2, GCCollectionMode.Forced, blocking: true);
                AddLog(Loc.F("Str_Log_GcReclaimedFmt",
                    System.Diagnostics.Process.GetCurrentProcess().WorkingSet64 / 1048576.0));
            } catch { }
        }

        /// <summary>
        /// EXE本地的赛次完赛晋级确认（仅EXE界面操作时弹出）
        /// </summary>
        private void CheckStageCompleteLocal() {
            if (string.IsNullOrEmpty(_currentEvent) || string.IsNullOrEmpty(_currentStage)) return;
            if (_currentStage == "决赛") return;

            // 2026-05-27 BUG 修复 #3: 之前 stageSwimmers 只按 Gender + EventName 过滤,
            //   导致 (甲) 男 50m 自由泳 预赛全部完赛后 allDone=false (要等 (乙) 也全部完赛),
            //   总排名 + 自动晋级都把 甲乙 混在一起处理. 加 MatchesAgeGroup 过滤后, 甲组独立判定/晋级.
            var stageSwimmers = _swimmers.Where(s =>
                s.EventName == _currentEvent && SgMatch(s.Gender, _currentGender) && s.CurrentStage == _currentStage &&
                MatchesAgeGroup(s, _currentAgeGroup) &&
                !(_isRelay && s.Notes != null && s.Notes.StartsWith("接力队员"))
            ).ToList();
            if (stageSwimmers.Count == 0) return;

            bool allDone = true;
            foreach (var sw in stageSwimmers) {
                if (sw.Status == "DNS" || sw.Status == "DNF" || sw.Status == "DSQ") continue;
                var result = sw.GetResultForStage(_currentStage);
                if (result == null || result.FinalTime <= 0) { allDone = false; break; }
            }
            if (!allDone) return;

            string nextStage = null;
            if (_currentStage == "预赛") {
                // 2026-05-27 半决赛存在性也要按 AgeGroup 过滤; 否则 (甲) 没排半决赛但 (乙) 排了, (甲) 也被误认要走半决赛
                if (_schedule.Any(s => s.Gender == _currentGender && s.EventName == _currentEvent && s.Stage == "半决赛"
                                       && (s.AgeGroup ?? "") == (_currentAgeGroup ?? "")))
                    nextStage = "半决赛";
                else
                    nextStage = "决赛";
            } else if (_currentStage == "半决赛") {
                nextStage = "决赛";
            }
            if (nextStage == null) return;

            int promoCount = HeatScheduler.GetPromotionCount(_currentStage, nextStage);
            string agLabel = string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] ");
            var answer = AppMessageBox.Show(
                Loc.F("Str_Msg_AutoPromotionFmt",
                    agLabel, Loc.GenderDisplay(_currentGender), _currentEvent, Loc.StageDisplay(_currentStage), stageSwimmers.Count, promoCount, Loc.StageDisplay(nextStage)),
                Loc.T("Str_MsgTitle_AutoPromotion"), MessageBoxButton.YesNo, MessageBoxImage.Question);

            if (answer == MessageBoxResult.Yes) {
                ExecutePromotion(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, nextStage, promoCount);
            }
        }

        private void CheckStageComplete() {
            if (string.IsNullOrEmpty(_currentEvent) || string.IsNullOrEmpty(_currentStage)) return;
            if (_currentStage == "决赛") return;

            // 2026-05-27 BUG 修复 #3: 加 AgeGroup 过滤, 甲/乙 组独立检测 stage-complete + 广播 STAGE_COMPLETE
            var stageSwimmers = _swimmers.Where(s =>
                s.EventName == _currentEvent &&
                s.Gender == _currentGender &&
                s.CurrentStage == _currentStage &&
                MatchesAgeGroup(s, _currentAgeGroup) &&
                !(_isRelay && s.Notes != null && s.Notes.StartsWith("接力队员"))
            ).ToList();

            if (stageSwimmers.Count == 0) return;

            bool allDone = true;
            foreach (var sw in stageSwimmers) {
                if (sw.Status == "DNS" || sw.Status == "DNF" || sw.Status == "DSQ") continue;
                var result = sw.GetResultForStage(_currentStage);
                if (result == null || result.FinalTime <= 0) { allDone = false; break; }
            }

            if (allDone) {
                string nextStage = null;
                if (_currentStage == "预赛") {
                    if (_schedule.Any(s => s.Gender == _currentGender && s.EventName == _currentEvent && s.Stage == "半决赛"
                                           && (s.AgeGroup ?? "") == (_currentAgeGroup ?? "")))
                        nextStage = "半决赛";
                    else
                        nextStage = "决赛";
                } else if (_currentStage == "半决赛") {
                    nextStage = "决赛";
                }

                if (nextStage != null) {
                    int promoCount = HeatScheduler.GetPromotionCount(_currentStage, nextStage);
                    string agLog = string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] ");
                    AddLog(Loc.F("Str_Log_AllFinishedCanPromoteFmt", agLog, Loc.GenderDisplay(_currentGender), _currentEvent, Loc.StageDisplay(_currentStage), promoCount, Loc.StageDisplay(nextStage)));

                    // 向所有控制端广播赛次完成通知（控制端弹出晋级确认）
                    var stageCompleteData = new {
                        type = "STAGE_COMPLETE",
                        ageGroup = _currentAgeGroup ?? "",   // 2026-05-27 加 ageGroup 字段, 客户端确认晋级时回传
                        gender = _currentGender,
                        eventName = _currentEvent,
                        fromStage = _currentStage,
                        nextStage = nextStage,
                        totalSwimmers = stageSwimmers.Count,
                        promoCount = promoCount
                    };
                    string json = Newtonsoft.Json.JsonConvert.SerializeObject(stageCompleteData);
                    BroadcastJsonToClients(json);
                }
            } else {
                AddLog(Loc.T("Str_Log_PleaseSelectNextHeat"));
            }
        }

        /// <summary>
        /// 执行晋级处理（由控制端确认后调用）
        /// 2026-05-27 加 ageGroup 参数, 只晋级该组的运动员; 之前混合所有组的 bug 已修.
        /// </summary>
        private void ExecutePromotion(string ageGroup, string gender, string eventName, string fromStage, string nextStage, int promoCount) {
            // 2026-10-08 用户要求全系统排查同类问题后发现: SgMatch 靠全局缓存判断
            // "是不是混合接力", 跟本项目自己的真实情况可能脱节——晋级是会实际写新
            // 分组数据的操作, 筛错人会把别的并列子项目的运动员晋级进下一轮。改用
            // 本项目+本组别精确判定。
            bool hasMixedPromo = HasExplicitMixedEntry(eventName, ageGroup);
            var filtered = _swimmers.Where(s => GenderMatchEx(s.Gender, gender, hasMixedPromo) && s.EventName == eventName
                                                && MatchesAgeGroup(s, ageGroup)).ToList();
            var promoted = HeatScheduler.GetPromotedSwimmers(filtered, eventName, fromStage, promoCount);

            if (promoted.Count > 0) {
                var assignments = HeatScheduler.GenerateHeatsFromResults(promoted, _poolConfig, eventName, nextStage, fromStage);
                int heatCount = assignments.Count > 0 ? assignments.Max(a => a.Heat) : 0;

                // 2026-06-18 加 ageGroup 过滤, 修晋级后跨年龄段误更 HeatCount 的 bug
                bool scheduleExists = _schedule.Any(s => SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == nextStage
                    && (string.IsNullOrEmpty(ageGroup) || (s.AgeGroup ?? "") == ageGroup));
                if (!scheduleExists) {
                    _schedule.Add(new ScheduleItem {
                        SessionNumber = _schedule.Count > 0 ? _schedule.Max(s => s.SessionNumber) + 1 : 1,
                        AgeGroup = ageGroup ?? "",
                        Gender = gender,
                        EventName = eventName,
                        Stage = nextStage,
                        HeatCount = heatCount
                    });
                } else {
                    var schedItem = _schedule.FirstOrDefault(s => SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == nextStage
                        && (string.IsNullOrEmpty(ageGroup) || (s.AgeGroup ?? "") == ageGroup));
                    if (schedItem != null) schedItem.HeatCount = heatCount;
                }

                BuildScheduleTree();
                UpdateResultHeatCombo();
                RefreshResultGrid();
                UpdateEditHeatCombo();
                SyncRelayHeatInfo();
                AutoSaveData();
                AddLog(Loc.F("Str_Log_AutoPromotedFmt", promoted.Count, Loc.StageDisplay(nextStage), heatCount));

                // 通知所有客户端晋级完成
                var resultData = new {
                    type = "PROMOTION_DONE",
                    gender = gender,
                    eventName = eventName,
                    nextStage = nextStage,
                    promotedCount = promoted.Count,
                    heatCount = heatCount
                };
                string json = Newtonsoft.Json.JsonConvert.SerializeObject(resultData);
                BroadcastJsonToClients(json);
                Broadcast();
            }
        }

        // 切换主标签页：不影响"比赛控制"后台运行，也不强行落盘（避免覆盖未确认的成绩）
        // 进入"成绩与排名"页时按当前内存重建下拉/网格，让操作员能即时看到已确认的组次
        private void MainTabControl_SelectionChanged(object sender, SelectionChangedEventArgs e) {
            if (!_initialized) return;
            if (e.OriginalSource != MainTabControl) return;   // 仅顶层 Tab 切换才处理（跳过子标签事件冒泡）
            var selected = MainTabControl.SelectedItem as TabItem;
            if (selected == null || selected.Header == null) return;
            string header = selected.Header.ToString();
            // 2026-10-06 同一类坑: Header 跟硬编码中文字面量比, English 模式下比不中——切到"成绩
            //   与排名"/"比赛控制"页时, 下面这两段自动刷新/自动推送参数的逻辑在 English 模式下
            //   全部不触发。
            if (header == Loc.TChinese("Str_Tab_Results") || header == Loc.TEnglish("Str_Tab_Results")) {
                try { RefreshAllAgeGroupFilterCombos(); } catch { }
                try { UpdateResultHeatCombo(); } catch { }
                try { RefreshResultGrid(); } catch { }
            }
            // 2026-05-25 修复 #5 + 需求 #17: 进入「比赛控制」Tab 时, 若硬件已连接, 自动把当前已加载的
            //   完整参数包推给硬件 + 广播给所有客户端, 免去用户每次都要手动打开「参数设置」对话框点保存才能生效。
            //   2026-05-25 (需求 #17) 完整对齐 OnStatusChanged 段: 加入 SetMatchEvent / DeviceStatuses /
            //   PoolSingleOrDoubleTP, 让"重启 + 进比赛控制"等价于硬件初次连接的完整初始化, 不再遗漏任一字段
            if ((header == Loc.TChinese("Str_Tab_RaceControl") || header == Loc.TEnglish("Str_Tab_RaceControl")) && _timingBridge != null && _timingBridge.IsConnected) {
                try {
                    SendTimingSettingsToHardware();            // 0x41 / 0x44 / 0x45
                    SendDeviceStatusesToHardware();            // 0x46 / 0x49 / 0x4A
                    SendSetMatchEventToHardware();             // 0x43 — 总圈数+左右触板次数+泳道位图+接力标志
                    SendStartPositionToHardware();             // 0x10 0x42 — 发令点
                    if (_poolConfig != null) {
                        bool isSingle = !_poolConfig.HasRightStartBlock;
                        try { _timingBridge.SendPoolSingleOrDoubleTP(isSingle); } catch { }
                    }
                    Broadcast();
                    AddLog(Loc.T("Str_Log_EnterRaceControlAutoPush"));
                } catch (Exception ex) {
                    AddLog(Loc.F("Str_Log_AutoPushParamsFailedFmt", ex.Message));
                }
            }
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-08-24 【组的取消状态】并组 / 取消组
        //
        // 组次号保留空号：第2组并入第1组后, 第2组仍占 2 号只是标记取消。
        // HeatCount 不减 —— 减了会让后面的组次号整体前移, 而秩序册已经印发。
        // 大屏/赛程树/导航/打印遇到被取消的组要跳过或标注, 别显示成一个空组。
        private ScheduleItem FindScheduleItem(string ageGroup, string gender, string eventName, string stage) {
            return _schedule.FirstOrDefault(s => s.EventName == eventName && s.Stage == stage
                && SgMatch(s.Gender, gender) && (s.AgeGroup ?? "") == (ageGroup ?? ""));
        }

        private CancelledHeat GetCancelledHeat(string ageGroup, string gender, string eventName, string stage, int heat) {
            var it = FindScheduleItem(ageGroup, gender, eventName, stage);
            if (it == null || it.CancelledHeats == null) return null;
            return it.CancelledHeats.FirstOrDefault(c => c.Heat == heat);
        }

        private bool IsHeatCancelled(string ageGroup, string gender, string eventName, string stage, int heat) {
            return GetCancelledHeat(ageGroup, gender, eventName, stage, heat) != null;
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-09-12 【正在比的那一组不许动】
        //
        // 要支持的事: 比赛进行中照样能对**别的项目 / 别的组**做并组、调道次
        // 这些编排操作, 而完全不碰正在计时的这一组和大屏。
        // 所以门禁必须精确到"是哪一组" —— 不能像整包推送那样"比赛中一律拒",
        // 那等于把这件事本身否掉。
        //
        // 判"这一组动不得"只有两种情形:
        //   · 它就是当前装载的那一组, 且已就位 / 正在计时 —— 改它, 计时中的
        //     泳道归属和大屏名单当场错位。
        //   · 它已经游完、成绩录进来了但还没点「确认本组成绩」—— 这时候改分组,
        //     成绩会挂到别人身上。
        // 除此之外一律放行。
        //
        // 注意别和上面的 NextLiveHeat 混了: 那个 "Live" 说的是"没被取消",
        // 这里的 Racing 说的是"正在比"。
        /// <summary>这一组动不得的原因; 动得了返回 null。</summary>
        private string HeatLockedWhy(string ageGroup, string gender, string eventName, string stage, int heat) {
            if (heat <= 0) return null;
            // 2026-09-12 【已完赛的组不在编辑范围】—— 定下来的规矩。
            //   成绩确认过、公告贴出去了, 这会儿再动分组或道次, 成绩就挂到别人身上。
            //
            // 2026-09-13 "已完赛"就是【操作员点过「确认本组成绩」、赛程树上标了 [已完赛]】
            //   这一个意思, 认 _confirmedHeats 这个集合 —— 不再用 IsHeatConfirmed 那个
            //   "全员有成绩就算完赛"的推断(推断会把还没确认的组也说成已完赛)。
            //   这一条两端都认: _confirmedHeats 跟着整包同步, 编排端手里那份是准的。
            if (IsHeatMarkedFinished(ageGroup, gender, eventName, stage, heat)) return Loc.T("Str_Why_Finished");
            // 还没确认、但已经录进成绩的组也不能动分组 —— 道次一换, 成绩就挂错人。
            // (这跟"已完赛"是两回事, 所以分开说, 免得看日志的人以为确认过了。)
            if (HeatHasResult(ageGroup, gender, eventName, stage, heat)) return Loc.T("Str_Why_ResultNotConfirmed");
            // 编排端自己不计时 —— 它那份 _raceState/_resultConfirmed 是跟着整包同步过来的影子,
            // 拿它拦人会误伤(主服务器早确认完了, 编排端这边还是"未确认")。
            // 编排端一律交给主服务器判: 补丁发过去, 真撞上正在比的组会被明确回绝。
            if (IsScheduleEditorMode) return null;
            // RTC 当主控时主服务器自己是空闲的, 得看计时端开着哪一组 (见 NoteRtcRaceState)
            if (IsRtcBusyHeat(ageGroup, gender, eventName, stage, heat)) return Loc.T("Str_Why_RtcBusy");
            if (_currentHeat != heat) return null;
            if (!SameLoadedEvent(ageGroup, gender, eventName, stage)) return null;
            if (_raceState == RaceState.Ready) return Loc.T("Str_Why_Ready");
            if (_raceState == RaceState.Racing) return Loc.T("Str_Why_Racing");
            if (_resultConfirmed) return null;
            foreach (var sw in GetCurrentHeatSwimmers()) {
                var r = sw.Results.FirstOrDefault(x => x.Stage == _currentStage && x.Heat == _currentHeat);
                if (r != null && (r.FinalTime > 0 || !string.IsNullOrEmpty(r.Status)))
                    return Loc.T("Str_Why_ResultPending");
            }
            return null;
        }

        private bool IsHeatLocked(string ageGroup, string gender, string eventName, string stage, int heat) {
            return HeatLockedWhy(ageGroup, gender, eventName, stage, heat) != null;
        }

        // ── RTC(计时端)正开着哪一组 ─────────────────────────────── 2026-09-12
        // RTC 当主控时, 主服务器自己的 _raceState 一直是空闲的 —— 它只是条消息总线。
        // 这时候光看本机状态就会把编排端的补丁痛快收下, 而 RTC 那边正计着时。
        // RTC 每 100ms 转发一帧状态过来, 顺手记下它开的是哪一组就够了。
        //
        // 判定故意做得粗: 只要 RTC 现在开着这一组, 不管就位没就位, 一律不许动。
        // 理由是"精细"在这儿没有好处 —— 主服务器和 RTC 各判各的一旦结论不同,
        // 就是主服务器改了、RTC 不认, 两边分叉; 而分叉在现场查不出来。
        private string _rtcEvent = "", _rtcGender = "", _rtcAgeGroup = "", _rtcStage = "";
        private int _rtcHeat = 0;
        private DateTime _rtcSeenAt = DateTime.MinValue;
        // 2026-09-19 见 IsPackageApplyBlocked 里的说明: 原始 READY/RACING/FINISHED 字符串,
        //   之前只用来刷"当前比赛"那行显示文字, 没存下来——现在要拿它判"计时端是不是
        //   正在比", 不能只有显示用的中文标签。
        private string _rtcRaceState = "";

        // 2026-09-13 「当前比赛」那块现在是计时端在驱动 —— 计时端一退出就得清掉,
        //   否则屏幕上永远停在它最后那一组, 看的人以为还在比。
        private bool _rtcDrivesCurrentRaceText;

        /// <summary>计时端退出/失联 → 把"当前比赛"从它的数据切回本机自己的(本机没有就显 "-")。</summary>
        private void ClearRtcRaceDisplay(string why) {
            if (!_rtcDrivesCurrentRaceText) return;
            _rtcDrivesCurrentRaceText = false;
            _rtcEvent = ""; _rtcGender = ""; _rtcAgeGroup = ""; _rtcStage = "";
            _rtcHeat = 0; _rtcSeenAt = DateTime.MinValue; _rtcRaceState = "";
            bool hasLocal = !string.IsNullOrEmpty(_currentEvent);
            if (CurrentEventText != null)
                CurrentEventText.Text = hasLocal
                    ? (Loc.GenderDisplay(_currentGender) + (string.IsNullOrEmpty(_currentAgeGroup) ? " " : (" [" + _currentAgeGroup + "] ")) + _currentEvent)
                    : "-";
            if (CurrentStageText != null)
                CurrentStageText.Text = (hasLocal && !string.IsNullOrEmpty(_currentStage)) ? _currentStage : "-";
            if (CurrentHeatText != null)
                CurrentHeatText.Text = (hasLocal && _currentHeat > 0)
                    ? string.Format("第{0}组 / 共{1}组", _currentHeat, _totalHeats) : "-";
            try { UpdateRaceStateDisplay(); } catch { }   // 状态框回到本机自己的 _raceState
            AddLog(Loc.F("Str_Log_CurrentRaceClearedFmt", why));
        }

        private void NoteRtcRaceState(JObject payload) {
            try {
                if (payload == null) return;
                var d = payload["data"] as JObject;
                if (d == null) return;
                _rtcEvent    = d["currentEvent"]    != null ? d["currentEvent"].ToString()    : "";
                _rtcGender   = d["currentGender"]   != null ? d["currentGender"].ToString()   : "";
                _rtcAgeGroup = d["currentAgeGroup"] != null ? d["currentAgeGroup"].ToString() : "";
                _rtcStage    = d["currentStage"]    != null ? d["currentStage"].ToString()    : "";
                _rtcHeat     = d["currentHeat"]     != null ? (int)d["currentHeat"]           : 0;
                _rtcSeenAt   = DateTime.Now;
                // ── 2026-09-13 主服务器"当前比赛"跟着计时端走 ────────────────────
                //   RTC 当主控时, 主服务器只是条总线: 它自己的 _currentEvent/_currentHeat
                //   一直是空的, 于是「系统工作状态」页那块"当前比赛"从头到尾显示 "-" ——
                //   场上明明在比, 主服务器这台却什么都看不出来。
                //   这里【只刷显示】, 不去动 _currentEvent 那些字段: 那些字段还牵着
                //   取名单、切组门禁、广播内容一大串, 动了会牵出别的事。
                //   括号里标明是计时端的, 免得有人以为这台机器在计时。
                int total = 0;
                try { if (d["totalHeats"] != null) total = (int)d["totalHeats"]; } catch { }
                string rs = d["raceState"] != null ? d["raceState"].ToString() : "";
                _rtcRaceState = rs;
                if (CurrentEventText != null)
                    CurrentEventText.Text = string.IsNullOrEmpty(_rtcEvent) ? "-"
                        : ((string.IsNullOrEmpty(_rtcAgeGroup) ? "" : "[" + _rtcAgeGroup + "] ") + _rtcGender + " " + _rtcEvent);
                if (CurrentStageText != null) CurrentStageText.Text = string.IsNullOrEmpty(_rtcStage) ? "-" : _rtcStage;
                if (CurrentHeatText != null)
                    CurrentHeatText.Text = _rtcHeat > 0
                        ? ("第" + _rtcHeat + "组" + (total > 0 ? " / 共" + total + "组" : "") + "（计时端）") : "-";
                _rtcDrivesCurrentRaceText = true;   // 2026-09-13 记一笔: 这块现在归计时端驱动
                if (RaceStateText != null && !string.IsNullOrEmpty(rs)) {
                    string label; string bg;
                    switch (rs) {
                        case "READY":    label = "已就位（计时端）";   bg = "#F59E0B"; break;
                        case "RACING":   label = "比赛中（计时端）";   bg = "#EF4444"; break;
                        case "FINISHED": label = "本组已完赛（计时端）"; bg = "#64748B"; break;
                        default:         label = "等待（计时端）";     bg = "#3B82F6"; break;
                    }
                    RaceStateText.Text = label;
                    RaceStateText.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString(bg));
                }
            } catch { }
        }

        /// <summary>RTC 现在开着的就是这一组吗。RTC 半分钟没动静就不算数了。</summary>
        private bool IsRtcBusyHeat(string ageGroup, string gender, string eventName, string stage, int heat) {
            if (_rtcHeat <= 0 || _rtcHeat != heat) return false;
            if (_rtcSeenAt == DateTime.MinValue || (DateTime.Now - _rtcSeenAt).TotalSeconds > 30) return false;
            if (ageGroup == Loc.T("Str_Common_All") || ageGroup == "不限") ageGroup = "";
            if ((eventName ?? "") != (_rtcEvent ?? "")) return false;
            if (!string.IsNullOrEmpty(stage) && !string.IsNullOrEmpty(_rtcStage) && stage != _rtcStage) return false;
            if (!string.IsNullOrEmpty(gender) && !string.IsNullOrEmpty(_rtcGender) && !SgMatch(gender, _rtcGender)) return false;
            if (!string.IsNullOrEmpty(ageGroup) && !string.IsNullOrEmpty(_rtcAgeGroup) && ageGroup != _rtcAgeGroup) return false;
            return true;
        }

        // 编排界面选的这四个字段, 是不是就是当前装载的那一项。
        // 组别/性别 任一侧为空(= "全部"/"不限")时不拿它做否定判断 ——
        // 宁可多拦一次, 也不能漏拦正在比的那一组。
        private bool SameLoadedEvent(string ageGroup, string gender, string eventName, string stage) {
            if (string.IsNullOrEmpty(_currentEvent)) return false;
            if (ageGroup == Loc.T("Str_Common_All") || ageGroup == "不限") ageGroup = "";   // 各调用点传的有原文有已归一的, 在这儿统一
            if ((eventName ?? "") != _currentEvent) return false;
            if (!string.IsNullOrEmpty(stage) && !string.IsNullOrEmpty(_currentStage) && stage != _currentStage) return false;
            if (!string.IsNullOrEmpty(gender) && !string.IsNullOrEmpty(_currentGender) && !SgMatch(gender, _currentGender)) return false;
            if (!string.IsNullOrEmpty(ageGroup) && !string.IsNullOrEmpty(_currentAgeGroup) && ageGroup != _currentAgeGroup) return false;
            return true;
        }

        /// <summary>正在比的那一组 → 弹窗 + 记日志, 返回 true 表示已拦下。</summary>
        private bool BlockIfHeatLocked(string ageGroup, string gender, string eventName, string stage,
                                       int heat, string actionLabel) {
            string why = HeatLockedWhy(ageGroup, gender, eventName, stage, heat);
            if (why == null) return false;
            AppMessageBox.Show(Loc.F("Str_Msg_HeatLockedFmt",
                heat, actionLabel, why), Loc.T("Str_MsgTitle_HeatLocked"), MessageBoxButton.OK, MessageBoxImage.Warning);
            AddLog(Loc.F("Str_Log_BlockedHeatActionFmt", heat, why, actionLabel));
            return true;
        }

        /// <summary>不弹窗的版本, 给远端补丁和 ApplyMergeHeats 用 —— 原因写进 reason。</summary>
        private bool HeatLockedReason(string ageGroup, string gender, string eventName, string stage,
                                      int heat, out string reason) {
            string why = HeatLockedWhy(ageGroup, gender, eventName, stage, heat);
            reason = why == null ? null : string.Format("第{0}组动不了: {1}", heat, why);
            return why != null;
        }

        // 整项重排(手动分组 / 追加分组)之前用: 这一项这一赛次里只要有一个组锁着,
        // 整项就不能重排 —— 重排会把所有人的组次道次重来一遍, 锁着的那组也跑不掉。
        private string EventLockedWhy(string ageGroup, string gender, string eventName, string stage,
                                      out int lockedHeat) {
            lockedHeat = 0;
            var heats = new HashSet<int>();
            var sched = FindScheduleItem(ageGroup, gender, eventName, stage);
            if (sched != null) for (int h = 1; h <= sched.HeatCount; h++) heats.Add(h);
            bool isRelay = eventName != null && eventName.Contains("接力");
            foreach (var s in _swimmers) {
                if (s == null || s.EventName != eventName) continue;
                if (!MatchesAgeGroup(s, ageGroup) || !SgMatch(s.Gender, gender)) continue;
                if (isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                var sa = s.GetAssignmentForStage(stage);
                int h = (sa != null && sa.Heat > 0) ? sa.Heat : (s.CurrentStage == stage ? s.Heat : 0);
                if (h > 0) heats.Add(h);
            }
            foreach (int h in heats) {
                string why = HeatLockedWhy(ageGroup, gender, eventName, stage, h);
                if (why != null) { lockedHeat = h; return why; }
            }
            return null;
        }

        private bool BlockIfEventLocked(string ageGroup, string gender, string eventName, string stage,
                                        string actionLabel) {
            int h;
            string why = EventLockedWhy(ageGroup, gender, eventName, stage, out h);
            if (why == null) return false;
            AppMessageBox.Show(Loc.F("Str_Msg_EventLockedFmt",
                Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage), actionLabel, h, why),
                Loc.T("Str_MsgTitle_EventLocked"), MessageBoxButton.OK, MessageBoxImage.Warning);
            AddLog(Loc.F("Str_Log_BlockedEventActionFmt", gender, eventName, stage, h, why, actionLabel));
            return true;
        }

        // ── 2026-09-12 【已完赛的组, 成绩也不许改】────────────────────────
        //
        // 判定跟上面分组那把锁【故意不一样】: 这里只认"标注已完赛"
        // (= _confirmedHeats, 操作员点过「确认本组成绩」、赛程树上带 [已完赛] 的),
        // 不用 IsHeatConfirmed 那个"全员有成绩就算完赛"的推断。
        // 因为刚游完、还没点确认的那一会儿, 恰恰是最常要改成绩的时候
        // (某道明显不对, 改完再确认) —— 拿推断来锁就把正常流程堵死了。
        //
        // 组别的比对要松: _confirmedHeats 的 key 里记的是赛程项的组别(可能是
        // "12-15岁组"这种并项), 而调用方手上常常是运动员自己的"12-13岁组"。
        // 两边能对上(相等或区间包含)就算同一组。
        private static bool AgeGroupCompatible(string a, string b) {
            a = a ?? ""; b = b ?? "";
            if (a == b) return true;
            if (a.Length == 0 || b.Length == 0) return true;    // 有一边没说, 不拿它做否定
            int aLo, aHi, bLo, bHi;
            if (TryParseAgeRange(a, out aLo, out aHi) && TryParseAgeRange(b, out bLo, out bHi))
                return (aLo <= bLo && bHi <= aHi) || (bLo <= aLo && aHi <= bHi);
            return false;
        }

        /// <summary>
        /// 一条 "<组别>|<性别>|<项目>|<赛次>|<组次>" 的 key 说的是不是这一组。
        /// 松着比: 组别/性别哪边没写就不拿它否定, 组别允许并项(区间包含) ——
        /// 因为 key 里记的是赛程项的组别, 调用方手上常是运动员自己的那个。
        /// </summary>
        private bool HeatKeyMatches(string key, string ageGroup, string gender, string eventName, string stage, int heat) {
            var p = key.Split('|');          // ag|gd|ev|st|heat
            if (p.Length != 5) return false;
            int h;
            if (!int.TryParse(p[4], out h) || h != heat) return false;
            if ((p[2] ?? "") != (eventName ?? "")) return false;
            if (!string.IsNullOrEmpty(p[3]) && !string.IsNullOrEmpty(stage) && p[3] != stage) return false;
            if (!string.IsNullOrEmpty(p[1]) && !string.IsNullOrEmpty(gender) && !SgMatch(gender, p[1])) return false;
            if (!AgeGroupCompatible(p[0], ageGroup)) return false;
            return true;
        }

        /// <summary>这一组是不是已经"标注已完赛"了(= 点过「确认本组成绩」)。</summary>
        private bool IsHeatMarkedFinished(string ageGroup, string gender, string eventName, string stage, int heat) {
            if (heat <= 0 || _confirmedHeats == null || _confirmedHeats.Count == 0) return false;
            if (_confirmedHeats.Contains(ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat))) return true;
            foreach (string key in _confirmedHeats)
                if (HeatKeyMatches(key, ageGroup, gender, eventName, stage, heat)) return true;
            return false;
        }

        /// <summary>这一组是不是被显式解锁过。</summary>
        private bool IsHeatUnlocked(string ageGroup, string gender, string eventName, string stage, int heat) {
            if (heat <= 0 || _unlockedHeats == null || _unlockedHeats.Count == 0) return false;
            if (_unlockedHeats.Contains(ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat))) return true;
            foreach (string key in _unlockedHeats)
                if (HeatKeyMatches(key, ageGroup, gender, eventName, stage, heat)) return true;
            return false;
        }

        /// <summary>重新确认时把解锁标记摘掉 —— 不然那条"全员有成绩"的推断一直被压着。</summary>
        private void ClearUnlockMark(string ageGroup, string gender, string eventName, string stage, int heat) {
            if (_unlockedHeats == null || _unlockedHeats.Count == 0) return;
            var gone = new List<string>();
            string exact = ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat);
            foreach (string key in _unlockedHeats)
                if (key == exact || HeatKeyMatches(key, ageGroup, gender, eventName, stage, heat)) gone.Add(key);
            foreach (string k in gone) _unlockedHeats.Remove(k);
        }

        /// <summary>成绩改不得就返回原因; 能改返回 null。</summary>
        private string ResultLockedWhy(string ageGroup, string gender, string eventName, string stage, int heat) {
            return IsHeatMarkedFinished(ageGroup, gender, eventName, stage, heat)
                 ? Loc.T("Str_Why_Finished") : null;
        }

        /// <summary>成绩改不得 → 弹窗 + 记日志, 返回 true 表示已拦下。</summary>
        private bool BlockIfResultLocked(string ageGroup, string gender, string eventName, string stage,
                                         int heat, string actionLabel) {
            string why = ResultLockedWhy(ageGroup, gender, eventName, stage, heat);
            if (why == null) return false;
            AppMessageBox.Show(Loc.F("Str_Msg_ResultLockedFmt",
                heat, actionLabel, why), Loc.T("Str_MsgTitle_ResultLocked"), MessageBoxButton.OK, MessageBoxImage.Warning);
            AddLog(Loc.F("Str_Log_BlockedHeatActionFmt", heat, why, actionLabel));
            return true;
        }

        /// <summary>当前装载的这一组成绩改不得 → 拦下。计时面板上那几个按钮用。</summary>
        private bool BlockIfCurrentResultLocked(string actionLabel) {
            return BlockIfResultLocked(_currentAgeGroup, _currentGender, _currentEvent, _currentStage,
                                       _currentHeat, actionLabel);
        }

        /// <summary>这一组有没有录进成绩(含判 DSQ 之类只有状态没有时间的)。</summary>
        private bool HeatHasResult(string ageGroup, string gender, string eventName, string stage, int heat) {
            foreach (var s in GetHeatEntries(ageGroup, gender, eventName, stage, heat)) {
                var r = s.Results.FirstOrDefault(x => x.Stage == stage && x.Heat == heat);
                if (r != null && (r.FinalTime > 0 || !string.IsNullOrEmpty(r.Status))) return true;
            }
            return false;
        }

        // 给大屏/赛程树用的一句话说明: "已取消(并入第1组)" / "已取消(弃权)"
        private string CancelledHeatLabel(string ageGroup, string gender, string eventName, string stage, int heat) {
            var c = GetCancelledHeat(ageGroup, gender, eventName, stage, heat);
            if (c == null) return "";
            if (c.MergedInto > 0) return string.Format("已取消(并入第{0}组)", c.MergedInto);
            return string.IsNullOrEmpty(c.Reason) ? "已取消" : string.Format("已取消({0})", c.Reason);
        }

        // 从 fromHeat 往 dir 方向找下一个"没被取消"的组; 找不到返回 0
        private int NextLiveHeat(int fromHeat, int dir) {
            int total = _totalHeats > 0 ? _totalHeats : 1;
            for (int h = fromHeat; h >= 1 && h <= total; h += dir) {
                if (!IsHeatCancelled(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, h)) return h;
            }
            return 0;
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-08-24 【并组 / 取消组】
        //
        // 场景: 检录后、开赛前发现某组人不够(如第2组只来 2 人), 把它整组并入第1组。
        // 三条已定的规则:
        //   · 组次号**保留空号** —— 第2组并入第1组后仍占 2 号、标记已取消。
        //     秩序册已印到运动员手上, 把原第3组改叫第2组会现场大乱。HeatCount 也不减。
        //   · 道次采用**填空道** —— 目标组原有的人道次不动, 并过来的人按报名成绩
        //     由快到慢填入空道(空道按 靠中间优先 的顺序取)。之后可用 上移/下移/交换泳道 人工调整。
        //   · 只允许在**没有成绩之前**并组。任一组已录成绩就拒绝, 避免把已比完的组搅乱。
        // 2026-09-18 用户报告按"并组/取消组"程序直接闪退退出、机器上连 error.log
        //   都没留下——说明那次很可能不是一次普通的、C# try/catch 接得住的异常
        //   (大概率是原生层面的东西, 常规 catch 到不了)。这个按钮本身已经按代码
        //   审查修了一个真实的道次冲突 bug(见 ApplyMergeHeats 里的说明), 但既然
        //   没有现场堆栈能 100% 咬死"就是这一个"、也不能排除还有别的路能走到崩溃,
        //   这里索性把整个点击处理包一层保险: 万一 Core 里冒出任何 C# 能接住的
        //   异常(哪怕是我没想到的那一种), 都在这里挡下来, 弹一个正常的错误框,
        //   不再让它有机会变成一次"什么都不说就退出"的崩溃。
        //   真正接不住的(原生崩溃/栈溢出), 这层也无能为力——但那类问题不该出现在
        //   这么一段纯内存/纯 UI 的逻辑里, 大概率是别的地方(硬件/数据库驱动)的事。
        private void MergeHeats_Click(object sender, RoutedEventArgs e) {
            try {
                MergeHeats_ClickCore(sender, e);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_MergeUnexpectedExceptionFmt", ex));
                AppMessageBox.Show(
                    Loc.F("Str_Msg_MergeHeatsCrashFmt", ex.Message),
                    Loc.T("Str_MsgTitle_MergeHeatsFailed"), MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void MergeHeats_ClickCore(object sender, RoutedEventArgs e) {
            // 取法与 RefreshEditPreview 保持一致
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            string gender   = EditGenderCombo != null && EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
            string eventName= EditEventCombo != null && EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
            string stage    = EditStageCombo != null && EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";
            if (ageGroup == Loc.T("Str_Common_All") || ageGroup == "不限") ageGroup = "";
            if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(stage)) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectFiltersFirst"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            var sched = FindScheduleItem(ageGroup, gender, eventName, stage);
            int heatCount = sched != null && sched.HeatCount > 0 ? sched.HeatCount : 1;
            if (heatCount < 2) {
                AppMessageBox.Show(Loc.T("Str_Msg_OnlyOneHeatNoMerge"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            // ── 各组现状 ──
            var live = new List<int>();
            var cnt  = new Dictionary<int, int>();
            var hasResult = new Dictionary<int, bool>();
            var lockedWhy = new Dictionary<int, string>();  // 2026-09-12 动不得的组(正在比 / 已完赛), null=能动
            // 2026-09-18 【订正】上一版这里改成过"不限组别地数占道"(GetHeatEntries("",...))，
            //   当时的判断依据是 schema 里"多个组别可以混在同一组下水"那句话——但那句话
            //   说的是【同一个 ScheduleItem 的组别本身是个年龄区间】(比如"12-17岁组"覆盖
            //   "12-15岁组"/"15-17岁组"两个子组，这种情况 MatchesAgeGroup 本来就认得出来，
            //   ageGroup 筛选并不会漏人)。用户实拍验证后发现是另一种情况：青年组和少年组
            //   压根是两个【互相独立】的 ScheduleItem，各自有各自从 1 开始的组次编号，
            //   "青年组第1组"和"少年组第2组"只是编号凑巧不同、彼此毫不相干的两场比赛，
            //   不共用任何泳道。GetHeatEntries("",...) 分不清"同一个 ScheduleItem 内部真的
            //   混了年龄段"和"两个独立 ScheduleItem 恰好编号相同"这两种情况，后者远比前者
            //   常见，硬去掉 ageGroup 过滤反而是把两场不相关的比赛错认成"抢道"，弄出一堆
            //   看着吓人但其实不存在的"另有 N 人"提示。改回按 ageGroup 筛选——这本来就是
            //   对的：ApplyMergeHeats 操作的 srcHeat/dstHeat 从头到尾都在【当前这一个
            //   ScheduleItem】范围内，它自己的组别筛选(包含区间匹配)已经把"这个 ScheduleItem
            //   该有的所有人"都圈全了，用不着再跨到别的 ScheduleItem 去查。
            for (int h = 1; h <= heatCount; h++) {
                if (IsHeatCancelled(ageGroup, gender, eventName, stage, h)) continue;
                live.Add(h);
                var entries = GetHeatEntries(ageGroup, gender, eventName, stage, h);
                cnt[h] = entries.Count;
                hasResult[h] = HeatHasResult(ageGroup, gender, eventName, stage, h);
                lockedWhy[h] = HeatLockedWhy(ageGroup, gender, eventName, stage, h);
            }
            if (live.Count < 2) {
                AppMessageBox.Show(Loc.T("Str_Msg_FewerThan2Heats"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            // ── 弹窗 ──
            var win = new Window {
                Title = Loc.T("Str_Win_MergeHeats_Title"), Width = 560, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, ResizeMode = ResizeMode.NoResize, Owner = this
            };
            var root = new StackPanel { Margin = new Thickness(18) };
            root.Children.Add(new TextBlock {
                Text = string.Format("{0} {1} {2} {3}", gender, string.IsNullOrEmpty(ageGroup) ? "" : ageGroup, eventName, stage),
                FontSize = 15, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 10)
            });
            var status = new StringBuilder();
            foreach (int h in live)
                status.AppendFormat("{0}    ", Loc.F("Str_Win_MergeHeats_HeatStatusFmt", h, cnt[h],
                    lockedWhy[h] != null ? Loc.T("Str_Win_MergeHeats_Locked") : hasResult[h] ? Loc.T("Str_Win_MergeHeats_HasResult") : ""));
            root.Children.Add(new TextBlock { Text = status.ToString().Trim(), Margin = new Thickness(0, 0, 0, 12),
                Foreground = System.Windows.Media.Brushes.DimGray, TextWrapping = TextWrapping.Wrap });

            var g1 = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 8) };
            g1.Children.Add(new TextBlock { Text = Loc.T("Str_Win_MergeHeats_MoveHeatLabel"), VerticalAlignment = VerticalAlignment.Center, FontSize = 14 });
            var srcBox = new ComboBox { Width = 70, Margin = new Thickness(4, 0, 4, 0) };
            foreach (int h in live) srcBox.Items.Add(h);
            srcBox.SelectedIndex = live.Count - 1;                       // 默认取最后一组(通常人最少)
            g1.Children.Add(srcBox);
            g1.Children.Add(new TextBlock { Text = Loc.T("Str_Win_MergeHeats_IntoHeatLabel"), VerticalAlignment = VerticalAlignment.Center, FontSize = 14 });
            var dstBox = new ComboBox { Width = 90, Margin = new Thickness(4, 0, 4, 0) };
            g1.Children.Add(dstBox);
            g1.Children.Add(new TextBlock { Text = Loc.T("Str_Win_MergeHeats_HeatSuffix"), VerticalAlignment = VerticalAlignment.Center, FontSize = 14 });
            root.Children.Add(g1);

            var reasonRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 6) };
            reasonRow.Children.Add(new TextBlock { Text = Loc.T("Str_Win_MergeHeats_ReasonLabel"), VerticalAlignment = VerticalAlignment.Center, FontSize = 13 });
            var reasonBox = new TextBox { Width = 380, Margin = new Thickness(6, 0, 0, 0), Text = Loc.T("Str_Win_MergeHeats_DefaultReason") };
            reasonRow.Children.Add(reasonBox);
            root.Children.Add(reasonRow);

            var hint = new TextBlock { TextWrapping = TextWrapping.Wrap, FontSize = 12,
                Foreground = System.Windows.Media.Brushes.DimGray, Margin = new Thickness(0, 6, 0, 0) };
            root.Children.Add(hint);

            // 2026-09-18 【重写这一段】旧版 refresh() 同时挂在 srcBox 和 dstBox 的
            //   SelectionChanged 上, 但函数体里自己又去 Clear()/重新 Add()/重新赋值
            //   dstBox.SelectedItem —— 这几步本身就会再触发一次 dstBox.SelectionChanged,
            //   于是 refresh() 在自己的事件回调里把自己调用了一遍, 一路递归下去。
            //   用户实测: 按这个按钮程序直接闪退, 连 error.log、Windows 事件查看器
            //   都没留下痕迹——这个特征只有 StackOverflowException 才有(调用栈涨爆,
            //   .NET 里唯一连包多少层 try/catch 都接不住、连异常日志都来不及写的一类
            //   崩溃), 跟这段代码的写法完全对得上。
            //   新写法把"要不要重建 dstBox 候选列表"和"刷新提示文字"拆成两件事:
            //   dstBox 自己的选择变了, 只更新提示文字, 绝不再碰 dstBox 的 Items/
            //   SelectedItem(它自己的候选列表不需要因为自己被选中而重建); 只有
            //   srcBox 变了才需要重建 dstBox 的候选(排除掉新选的 src)。这样 dstBox
            //   的 SelectionChanged 处理函数里就没有任何会反过来触发它自己的代码,
            //   结构上就切断了递归的可能——再加一道 updating 重入锁, 双重保险。
            bool updating = false;
            Action<int> rebuildDstItems = delegate(int src) {
                object keep = dstBox.SelectedItem;
                dstBox.Items.Clear();
                dstBox.Items.Add(Loc.T("Str_Win_MergeHeats_CancelOnlyOption"));
                foreach (int h in live) if (h != src) dstBox.Items.Add(h);
                dstBox.SelectedItem = (keep != null && dstBox.Items.Contains(keep)) ? keep : dstBox.Items[dstBox.Items.Count > 1 ? 1 : 0];
            };
            Action refreshHint = delegate {
                int src = srcBox.SelectedItem is int ? (int)srcBox.SelectedItem : 0;
                int dst = dstBox.SelectedItem is int ? (int)dstBox.SelectedItem : 0;
                var sb = new StringBuilder();
                if (src > 0 && lockedWhy.ContainsKey(src) && lockedWhy[src] != null)
                    sb.Append(Loc.F("Str_Win_MergeHeats_HintSrcLockedFmt", src, lockedWhy[src]));
                else if (src > 0 && hasResult.ContainsKey(src) && hasResult[src]) sb.Append(Loc.F("Str_Win_MergeHeats_HintSrcHasResultFmt", src));
                if (dst > 0) {
                    if (lockedWhy.ContainsKey(dst) && lockedWhy[dst] != null)
                        sb.Append(Loc.F("Str_Win_MergeHeats_HintDstLockedFmt", dst, lockedWhy[dst]));
                    else if (hasResult.ContainsKey(dst) && hasResult[dst]) sb.Append(Loc.F("Str_Win_MergeHeats_HintDstHasResultFmt", dst));
                    int free = LaneCapacity() - cnt[dst];
                    sb.Append(Loc.F("Str_Win_MergeHeats_HintCapacityFmt",
                        dst, cnt[dst], free, src, cnt[src]));
                    if (free < cnt[src]) sb.Append(Loc.F("Str_Win_MergeHeats_HintNotEnoughFmt", cnt[src] - free));
                    else sb.Append(Loc.T("Str_Win_MergeHeats_HintOkTip"));
                } else {
                    sb.Append(Loc.F("Str_Win_MergeHeats_HintCancelOnlyFmt", src, src > 0 ? cnt[src] : 0));
                }
                hint.Text = sb.ToString();
            };
            srcBox.SelectionChanged += delegate {
                if (updating) return;
                updating = true;
                try { rebuildDstItems(srcBox.SelectedItem is int ? (int)srcBox.SelectedItem : 0); }
                finally { updating = false; }
                refreshHint();
            };
            dstBox.SelectionChanged += delegate {
                if (updating) return;   // rebuildDstItems 改 dstBox.SelectedItem 时会重入触发到这里, 直接吞掉
                refreshHint();           // dstBox 自己被选中: 只刷新文字, 绝不碰它自己的 Items/SelectedItem
            };
            updating = true;
            try { rebuildDstItems(srcBox.SelectedItem is int ? (int)srcBox.SelectedItem : 0); }
            finally { updating = false; }
            refreshHint();

            var btns = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            bool go = false;
            var ok = new Button { Content = Loc.T("Str_Win_MergeHeats_ExecuteBtn"), Width = 90, Height = 30, Margin = new Thickness(0, 0, 8, 0), IsDefault = true };
            var cancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Width = 80, Height = 30, IsCancel = true };
            ok.Click += delegate { go = true; win.DialogResult = true; };
            btns.Children.Add(ok); btns.Children.Add(cancel);
            root.Children.Add(btns);
            win.Content = root;
            if (win.ShowDialog() != true || !go) return;

            int srcHeat = (int)srcBox.SelectedItem;
            int dstHeat = (dstBox.SelectedItem is int) ? (int)dstBox.SelectedItem : 0;
            string reason = (reasonBox.Text ?? "").Trim();

            // 2026-09-12 正在比的那一组, 谁也动不了 (别的组照常放行)
            if (BlockIfHeatLocked(ageGroup, gender, eventName, stage, srcHeat, Loc.T("Str_Action_MergeHeats"))) return;
            if (dstHeat > 0 && BlockIfHeatLocked(ageGroup, gender, eventName, stage, dstHeat, Loc.T("Str_Action_MergeTarget"))) return;

            // ── 2026-09-12 联网编排端: 走【增量补丁】, 不推整包 ──────────────
            //   老路 EDITOR_PUSH_PACKAGE 是"推整包 → 主服务器整库重载", 主服务器
            //   计时中一律拒收(见 IsPackageApplyBlocked), 于是"比赛中改别的项目"
            //   这件事根本做不成。补丁只描述一次操作, 主服务器照着改那几个人,
            //   不重载、不换对象, 正在计时的那一组一个字节都不碰。
            //   先问主服务器再动本机 —— 只有它知道自己正在比哪一组; 拿到 ok 才改,
            //   免得两边分叉。被拒就原样不动, 让操作员看见原因。
            bool serverAccepted = false;
            if (IsScheduleEditorMode && _editorSyncClient != null && _editorSyncClient.IsConnected) {
                string perr;
                if (!SendMergeHeatsPatch(ageGroup, gender, eventName, stage, srcHeat, dstHeat, reason, out perr)) {
                    AppMessageBox.Show(Loc.F("Str_Msg_MergeRejectedFmt", perr),
                        Loc.T("Str_MsgTitle_MergeNotDone"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    AddLog(Loc.F("Str_Log_MergeRejectedByMainFmt", perr));
                    return;
                }
                serverAccepted = true;
            }

            string error;
            List<string> moved;
            if (!ApplyMergeHeats(ageGroup, gender, eventName, stage, srcHeat, dstHeat, reason,
                                 Environment.MachineName, out moved, out error)) {
                // 主服务器已经改了、本机却没改成 —— 只可能是本机这份数据是旧的。
                // 这种分叉必须让人看见, 不能只记一行日志。
                if (serverAccepted) {
                    AppMessageBox.Show(Loc.F("Str_Msg_MergeServerAheadFmt", error),
                        Loc.T("Str_MsgTitle_ServerMismatch"), MessageBoxButton.OK, MessageBoxImage.Error);
                    AddLog(Loc.F("Str_Log_MergeAppliedLocalFailFmt", error));
                } else {
                    AppMessageBox.Show(error, Loc.T("Str_MsgTitle_CannotProceed"), MessageBoxButton.OK, MessageBoxImage.Warning);
                }
                return;
            }

            // 本机是主服务器: 把这次改动以补丁形式发给所有在线编排端 (同样不推整包)
            if (!IsScheduleEditorMode)
                BroadcastMergePatch(ageGroup, gender, eventName, stage, srcHeat, dstHeat, reason,
                                    Environment.MachineName, null);

            AppMessageBox.Show(Loc.F("Str_Msg_MergeDoneFmt",
                srcHeat, dstHeat > 0 ? Loc.F("Str_Frag_MergedIntoFmt", dstHeat) : Loc.T("Str_Frag_Cancelled"), moved.Count),
                Loc.T("Str_MsgTitle_MergeDone"), MessageBoxButton.OK, MessageBoxImage.Information);
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-09-12 并组的实际执行 —— 本机点按钮、收到远端补丁, 走的都是这一份。
        //
        // 为什么要单拆出来: 两条路必须字字一致, 否则主服务器和编排端的分组会分叉,
        // 而分叉在现场是查不出来的(两边界面各显各的, 谁也不知道该信哪一份)。
        //
        // 失败返回 false, 原因写进 error, 内存一个字不动 —— 半路失败比拒绝更糟。
        private bool ApplyMergeHeats(string ageGroup, string gender, string eventName, string stage,
                                     int srcHeat, int dstHeat, string reason, string op,
                                     out List<string> moved, out string error) {
            moved = new List<string>();
            error = null;
            if (srcHeat <= 0) { error = "源组号不对"; return false; }
            if (dstHeat == srcHeat) { error = "并组的两个组不能是同一组"; return false; }

            // 门禁: 正在比的那一组 + 已录成绩的组
            string why;
            if (HeatLockedReason(ageGroup, gender, eventName, stage, srcHeat, out why)) { error = why; return false; }
            if (dstHeat > 0 && HeatLockedReason(ageGroup, gender, eventName, stage, dstHeat, out why)) { error = why; return false; }
            if (HeatHasResult(ageGroup, gender, eventName, stage, srcHeat)) {
                error = string.Format("第{0}组已录入成绩，不能并组。", srcHeat); return false;
            }
            if (dstHeat > 0 && HeatHasResult(ageGroup, gender, eventName, stage, dstHeat)) {
                error = string.Format("第{0}组已录入成绩，不能作为并入目标。", dstHeat); return false;
            }

            var sched = FindScheduleItem(ageGroup, gender, eventName, stage);
            var srcList = GetHeatEntries(ageGroup, gender, eventName, stage, srcHeat);
            var laneMoves = new Dictionary<int, int>();       // 原道次 → 新道次, 落库时要用

            if (dstHeat > 0) {
                // 2026-09-18 【订正】这里曾经改成不带组别过滤地查 dstHeat 占了哪几道
                //   (GetHeatEntries("",...))，当时怀疑是混编项目里别的年龄组占道没数进去。
                //   用户实拍验证后确认：像"青年组第1组"和"少年组第2组"这种情况，是两个
                //   【互相独立】的 ScheduleItem 各自从 1 开始编号，编号凑巧撞上而已，
                //   压根不是同一场比赛、不共用泳道——不带组别过滤反而会把两场毫不相干的
                //   比赛错认成"抢道"，白白拒掉本来合法的并组。ApplyMergeHeats 从 srcHeat
                //   到 dstHeat 全程都在【当前这一个 ScheduleItem】范围内, ageGroup 筛选
                //   (本来就认得区间形式的组别, 见 MatchesAgeGroup)已经把这个 ScheduleItem
                //   该有的人全圈出来了, 改回按 ageGroup 查才是对的。
                var dstList = GetHeatEntries(ageGroup, gender, eventName, stage, dstHeat);
                var used = new HashSet<int>();
                foreach (var s in dstList) used.Add(LaneOfStage(s, stage));
                var freeLanes = FreeLanesCenterFirst(used);
                if (freeLanes.Count < srcList.Count) {
                    error = string.Format("第{0}组空道只有 {1} 条，装不下第{2}组的 {3} 人。",
                        dstHeat, freeLanes.Count, srcHeat, srcList.Count);
                    return false;
                }
                // 并过来的人按报名成绩由快到慢, 依次填 靠中间优先 的空道
                var ordered = srcList.OrderBy(s => {
                    var sa = s.GetAssignmentForStage(stage);
                    double t = sa != null ? sa.EntryTimeSeconds : s.EntryTimeSeconds;
                    return t > 0 ? t : double.MaxValue;
                }).ToList();
                for (int i = 0; i < ordered.Count; i++) {
                    var s = ordered[i];
                    int lane = freeLanes[i];
                    // 最后一道保险: 万一上面的占道统计还是漏了(比如极端边界情况), 这里
                    //   现查一遍那条道当下真的空着——查到有人就直接失败退出, 绝不硬塞出
                    //   一道两人。内存到这一步还什么都没改, 直接 return false 不会留下
                    //   半截数据。这里同样只在当前 ScheduleItem(按 ageGroup 筛选)范围内查,
                    //   不跨到别的独立 ScheduleItem 去。
                    if (GetHeatEntries(ageGroup, gender, eventName, stage, dstHeat).Any(x => LaneOfStage(x, stage) == lane)) {
                        error = string.Format("第{0}组{1}道其实已经有人, 为避免顶号已取消这次并组。", dstHeat, lane);
                        return false;
                    }
                    int oldLane = LaneOfStage(s, stage);
                    var sa = s.GetAssignmentForStage(stage);
                    double et = sa != null ? sa.EntryTimeSeconds : s.EntryTimeSeconds;
                    string ets = sa != null ? sa.EntryTime : s.EntryTime;
                    s.SetStageAssignment(stage, dstHeat, lane, et, ets);
                    if (s.CurrentStage == stage) { s.Heat = dstHeat; s.Lane = lane; }   // 顶层字段同步, 免得留下旧值
                    if (oldLane > 0 && !laneMoves.ContainsKey(oldLane)) laneMoves[oldLane] = lane;
                    moved.Add(string.Format("{0} → 第{1}组{2}道", s.Name, dstHeat, lane));
                }
            } else {
                // 仅取消: 把人移出该组 (清掉该赛次的分组记录), 不动别的赛次
                foreach (var s in srcList) {
                    s.StageAssignments.Remove(stage);
                    if (s.CurrentStage == stage) { s.Heat = 0; s.Lane = 0; }
                    moved.Add(string.Format("{0} 已移出", s.Name));
                }
            }

            // 记录取消
            if (sched != null) {
                if (sched.CancelledHeats == null) sched.CancelledHeats = new List<CancelledHeat>();
                sched.CancelledHeats.RemoveAll(x => x.Heat == srcHeat);
                sched.CancelledHeats.Add(new CancelledHeat {
                    Heat = srcHeat, MergedInto = dstHeat,
                    Reason = string.IsNullOrEmpty(reason) ? (dstHeat > 0 ? "并组" : "取消") : reason,
                    Time = DateTime.Now.ToString("yyyy-MM-dd HH:mm"), Operator = op ?? ""
                });
            }

            FinishPatchApply(ageGroup, gender, eventName, stage);

            // 落进竞赛库。比赛中不碰库 —— 规矩见 InRaceNoDbWrite。
            try {
                _meetDb.MergeHeatsInDb(ageGroup, gender, eventName, stage, srcHeat, dstHeat,
                                       laneMoves, reason, op, InRaceNoDbWrite());
            } catch { }

            AddLog(Loc.F("Str_Log_MergeDoneLogFmt",
                gender, ageGroup, eventName, stage, srcHeat,
                dstHeat > 0 ? ("并入第" + dstHeat + "组") : "直接取消", reason));
            foreach (var m in moved) AddLog(Loc.F("Str_Log_IndentedLineFmt", m));
            return true;
        }

        // ── 2026-09-12 并组增量补丁 (编排端 ↔ 主服务器) ────────────────
        // 这是那句"治本是改成发增量消息, 不重载整库"的兑现。
        //
        // 两种补丁:
        //   op:"MergeHeats"  并组 / 取消组
        //     { ageGroup, gender, eventName, stage, srcHeat, dstHeat, reason }
        //   op:"Assign"      一个项目一个赛次的【分组泳道表快照】
        //     { ageGroup, gender, eventName, stage, heatCount,
        //       rows:[{bib,heat,lane,entryTime,entryTimeSeconds}],
        //       swimmers:[整条 Swimmer] }
        // 回执统一是 { type:"EDITOR_PATCH_ACK", corrId, ok, reason }
        //
        // 两种补丁的时序不一样, 是故意的:
        //   并组【先问后改】—— 它要重排道次, 失败了不好回头;
        //   Assign【先改后报】—— 编排端本地已经改完(那些编辑函数是就地改内存的),
        //     报上去万一撞上锁着的组被拒, 就拉一次整包把本机盖回去, 不手工回滚。
        private bool _patchInFlight = false;

        /// <summary>编排端: 发补丁并等主服务器回执。ok 才返回 true。</summary>
        private bool SendPatchAndWait(JObject patch, out string error) {
            error = null;
            if (_editorSyncClient == null || !_editorSyncClient.IsConnected) { error = "没连主服务器"; return false; }
            string corrId = Guid.NewGuid().ToString("N");
            var evt = new System.Threading.ManualResetEventSlim(false);
            lock (_lockSync) { _lockWaiters[corrId] = evt; }
            try {
                patch["corrId"] = corrId;
                _editorSyncClient.Send(patch.ToString(Formatting.None));
                bool got = evt.Wait(5000);
                JObject reply = null;
                lock (_lockSync) {
                    _lockWaiters.Remove(corrId);
                    if (_lockReplies.TryGetValue(corrId, out reply)) _lockReplies.Remove(corrId);
                }
                if (!got || reply == null) { error = "主服务器 5 秒内没有回应"; return false; }
                bool ok = reply["ok"] != null && (bool)reply["ok"];
                if (!ok) error = reply["reason"] != null ? reply["reason"].ToString() : "主服务器拒绝了这次改动";
                return ok;
            } catch (Exception ex) {
                lock (_lockSync) { _lockWaiters.Remove(corrId); _lockReplies.Remove(corrId); }
                error = ex.Message;
                return false;
            }
        }

        /// <summary>主服务器: 把一条补丁发给在线编排端/RTC(except 那个除外)。</summary>
        private void BroadcastPatch(JObject patch, IWebSocketConnection except) {
            try {
                if (patch == null || _editorSockets == null || _editorSockets.Count == 0) return;
                string json = patch.ToString(Formatting.None);
                foreach (var sock in _editorSockets.ToList()) {
                    if (sock == except) continue;
                    EnqueueToSocket(sock, json);
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ForwardPatchFailedFmt", ex.Message)); }
        }

        private JObject NewPatch(string op, string ageGroup, string gender, string eventName, string stage,
                                 string clientName) {
            var p = new JObject();
            p["type"] = "EDITOR_PATCH";
            p["op"] = op;
            p["clientName"] = clientName ?? "";
            p["ageGroup"] = ageGroup ?? "";
            p["gender"] = gender ?? "";
            p["eventName"] = eventName ?? "";
            p["stage"] = stage ?? "";
            return p;
        }

        private JObject BuildMergePatch(string ageGroup, string gender, string eventName, string stage,
                                        int srcHeat, int dstHeat, string reason, string clientName) {
            var p = NewPatch("MergeHeats", ageGroup, gender, eventName, stage, clientName);
            p["srcHeat"] = srcHeat;
            p["dstHeat"] = dstHeat;
            p["reason"] = reason ?? "";
            return p;
        }

        /// <summary>编排端: 发并组补丁(先问后改)。</summary>
        private bool SendMergeHeatsPatch(string ageGroup, string gender, string eventName, string stage,
                                         int srcHeat, int dstHeat, string reason, out string error) {
            return SendPatchAndWait(BuildMergePatch(ageGroup, gender, eventName, stage, srcHeat, dstHeat,
                                                    reason, ClientLabel()), out error);
        }

        /// <summary>主服务器本机做了并组 → 以补丁形式发给各编排端。</summary>
        private void BroadcastMergePatch(string ageGroup, string gender, string eventName, string stage,
                                         int srcHeat, int dstHeat, string reason, string clientName,
                                         IWebSocketConnection except) {
            BroadcastPatch(BuildMergePatch(ageGroup, gender, eventName, stage, srcHeat, dstHeat,
                                           reason, clientName), except);
        }

        // ── op:"Assign" 分组泳道表快照 ──────────────────────────────────
        //
        // 覆盖: 上移/下移、交换泳道、移到空道、增加到本组、移出本组、临时加人、
        //       手动分组、追加分组。
        //
        // 为什么发【整项快照】而不是"谁挪到了哪一道"这种逐条增量:
        //   一次编排常常同时动好几个人(手动分组是整项重排), 逐条增量既难拼又怕漏;
        //   而一个项目一个赛次的名单就几十行, 比整包(实测 278KB)小一到两个数量级,
        //   更要紧的是它【不会让对端重载整库】—— 当初出事的是重载, 不是字节数。
        //   快照还有个好处: 重发一次结果一样, 网络抖动重试不会叠加出错。
        //
        // swimmers 里带整条人, 是为了"临时加人"和接力队员 —— 对端可能压根没有这个人。
        // 收方只拿它补自己没有的人, 【绝不覆盖已有的】(覆盖就是把人家的成绩冲掉)。
        private JObject BuildAssignPatch(string ageGroup, string gender, string eventName, string stage,
                                         string clientName) {
            var p = NewPatch("Assign", ageGroup, gender, eventName, stage, clientName);
            bool isRelay = eventName != null && eventName.Contains("接力");
            var rows = new JArray();
            var people = new JArray();
            int maxHeat = 0;
            foreach (var s in _swimmers) {
                if (s == null || s.EventName != eventName) continue;
                bool isLeg = isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员");
                // 队员条目不带组别、混合接力里男女都有 —— 别拿筛选条件把它们漏掉,
                // 漏了对端就只拿到一个没有棒次的空接力队。
                if (!isLeg && (!MatchesAgeGroup(s, ageGroup) || !SgMatch(s.Gender, gender))) continue;
                try { people.Add(JObject.FromObject(s)); } catch { }
                // 接力队员只随 swimmers 过去(对端可能没有), 不占泳道行
                if (isLeg) continue;
                int h = 0, ln = 0;
                double et = s.EntryTimeSeconds;
                string ets = s.EntryTime;
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat > 0) { h = sa.Heat; ln = sa.Lane; et = sa.EntryTimeSeconds; ets = sa.EntryTime; }
                else if (s.CurrentStage == stage && s.Heat > 0) { h = s.Heat; ln = s.Lane; }
                if (h <= 0) continue;                       // 没分组的人不进快照(对端照着清掉就是"移出")
                if (h > maxHeat) maxHeat = h;
                var r = new JObject();
                r["bib"] = s.BibNumber ?? "";
                r["heat"] = h;
                r["lane"] = ln;
                r["entryTime"] = ets ?? "";
                r["entryTimeSeconds"] = et;
                rows.Add(r);
            }
            // 接力队记录(棒次在这里面)也得跟过去, 否则对端只有一个代表队条目、没有棒次
            var teams = new JArray();
            if (isRelay && _relayTeams != null) {
                foreach (var t in _relayTeams) {
                    if (t == null || t.EventName != eventName) continue;
                    try { teams.Add(JObject.FromObject(t)); } catch { }
                }
            }
            var sched = FindScheduleItem(ageGroup, gender, eventName, stage);
            p["heatCount"] = sched != null && sched.HeatCount > maxHeat ? sched.HeatCount : maxHeat;
            p["rows"] = rows;
            p["swimmers"] = people;
            p["relayTeams"] = teams;
            return p;
        }

        /// <summary>收到 Assign 快照, 照着改本机这一项的分组。整条要么全成要么全不动。</summary>
        private bool ApplyAssignPatch(JObject msg, out string error) {
            error = null;
            string ag = msg["ageGroup"] != null ? msg["ageGroup"].ToString() : "";
            string gd = msg["gender"] != null ? msg["gender"].ToString() : "";
            string ev = msg["eventName"] != null ? msg["eventName"].ToString() : "";
            string st = msg["stage"] != null ? msg["stage"].ToString() : "";
            var rows = msg["rows"] as JArray;
            if (rows == null) { error = "补丁里没有分组表"; return false; }
            if (string.IsNullOrEmpty(ev) || string.IsNullOrEmpty(st)) { error = "补丁没说是哪个项目/赛次"; return false; }
            bool isRelay = ev.Contains("接力");

            // 表里要的分组
            var want = new Dictionary<string, JObject>(StringComparer.Ordinal);
            var touched = new HashSet<int>();
            foreach (var t in rows) {
                var r = t as JObject;
                if (r == null) continue;
                string bib = r["bib"] != null ? r["bib"].ToString() : "";
                if (string.IsNullOrEmpty(bib)) continue;
                want[bib] = r;
                int h = 0;
                try { if (r["heat"] != null) h = (int)r["heat"]; } catch { }
                if (h > 0) touched.Add(h);
            }

            // 本机现在挂着的组也算"动到了" —— 有人被移出的那一组同样不能是锁着的
            foreach (var s in _swimmers) {
                if (s == null || !MatchesAgeGroup(s, ag) || !SgMatch(s.Gender, gd) || s.EventName != ev) continue;
                if (isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                var sa = s.GetAssignmentForStage(st);
                int h = (sa != null && sa.Heat > 0) ? sa.Heat : (s.CurrentStage == st ? s.Heat : 0);
                if (h > 0) touched.Add(h);
            }

            // 任何一个受影响的组锁着 → 整条拒, 一个字不动
            foreach (int h in touched) {
                string why = HeatLockedWhy(ag, gd, ev, st, h);
                if (why != null) { error = string.Format("第{0}组动不了: {1}", h, why); return false; }
            }

            // 补上本机没有的人(临时加人 / 接力队员)。已有的一律不碰 —— 覆盖会冲掉成绩。
            int added = 0;
            var people = msg["swimmers"] as JArray;
            if (people != null) {
                foreach (var t in people) {
                    var jo = t as JObject;
                    if (jo == null) continue;
                    string bib = jo["BibNumber"] != null ? jo["BibNumber"].ToString() : "";
                    if (string.IsNullOrEmpty(bib)) continue;
                    if (_swimmers.Any(x => x != null && x.BibNumber == bib && x.EventName == ev)) continue;
                    try {
                        var nw = jo.ToObject<Swimmer>();
                        if (nw != null) { _swimmers.Add(nw); added++; }
                    } catch { }
                }
            }
            // 接力队记录同理: 缺的补上, 有的不动
            int addedTeams = 0;
            var teams = msg["relayTeams"] as JArray;
            if (teams != null && _relayTeams != null) {
                foreach (var t in teams) {
                    var jo = t as JObject;
                    if (jo == null) continue;
                    string tn = jo["TeamName"] != null ? jo["TeamName"].ToString() : "";
                    if (string.IsNullOrEmpty(tn)) continue;
                    if (_relayTeams.Any(x => x != null && x.TeamName == tn && x.EventName == ev)) continue;
                    try {
                        var nt = jo.ToObject<RelayTeam>();
                        if (nt != null) { _relayTeams.Add(nt); addedTeams++; }
                    } catch { }
                }
                if (addedTeams > 0) { try { RebuildRelayGroupedView(); } catch { } }
            }

            // 套用: 表里有的照着设, 表里没有的把这个赛次的分组清掉(= 被移出了)
            int setN = 0, clrN = 0;
            foreach (var s in _swimmers.ToList()) {
                if (s == null || !MatchesAgeGroup(s, ag) || !SgMatch(s.Gender, gd) || s.EventName != ev) continue;
                if (isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                JObject r;
                if (want.TryGetValue(s.BibNumber ?? "", out r)) {
                    int h = 0, ln = 0;
                    try { if (r["heat"] != null) h = (int)r["heat"]; } catch { }
                    try { if (r["lane"] != null) ln = (int)r["lane"]; } catch { }
                    if (h <= 0) continue;
                    double et = s.EntryTimeSeconds;
                    string ets = s.EntryTime;
                    try { if (r["entryTimeSeconds"] != null) et = (double)r["entryTimeSeconds"]; } catch { }
                    try { if (r["entryTime"] != null) ets = r["entryTime"].ToString(); } catch { }
                    s.SetStageAssignment(st, h, ln, et, ets);
                    if (s.CurrentStage == st) { s.Heat = h; s.Lane = ln; }
                    setN++;
                } else {
                    if (s.StageAssignments != null && s.StageAssignments.ContainsKey(st)) { s.StageAssignments.Remove(st); clrN++; }
                    if (s.CurrentStage == st && s.Heat > 0) { s.Heat = 0; s.Lane = 0; }
                }
            }

            // 组数跟着走 —— 否则对端赛程树上"共几组"和大屏的"第x/y组"会对不上。
            // 对端连这个赛程项都没有(手动分组/追加分组会现建新项), 就照样建一个。
            try {
                int hc = msg["heatCount"] != null ? (int)msg["heatCount"] : 0;
                var sched = FindScheduleItem(ag, gd, ev, st);
                if (sched != null) { if (hc > 0) sched.HeatCount = hc; }
                else if (hc > 0) {
                    _schedule.Add(new ScheduleItem {
                        SessionNumber = _schedule.Count > 0 ? _schedule.Max(x => x.SessionNumber) : 1,
                        AgeGroup = ag, Gender = gd, EventName = ev, Stage = st, HeatCount = hc
                    });
                    AddLog(Loc.F("Str_Log_PatchNewScheduleItemFmt", ag, Loc.GenderDisplay(gd), ev, Loc.StageDisplay(st), hc));
                }
            } catch { }

            FinishPatchApply(ag, gd, ev, st);
            AddLog(Loc.F("Str_Log_AssignPatchFmt",
                gd, ag, ev, st, setN, clrN,
                added > 0 ? (", 新增 " + added + " 人") : "",
                addedTeams > 0 ? (", 新增 " + addedTeams + " 支接力队") : ""));
            return true;
        }

        /// <summary>补丁应用完的统一收尾(并组和 Assign 共用)。</summary>
        private void FinishPatchApply(string ageGroup, string gender, string eventName, string stage) {
            // _patchInFlight: 这次改动已经由补丁送到对端了, 别再推一次整包
            // (整包那条路比赛中本来就会被拒, 还要弹一个吓人的"未保存"对话框)
            _patchInFlight = true;
            bool raceLive;
            try {
                InvalidateMixedCache();
                _currentHeatSwimmersCacheKey = null;      // 让 50ms 缓存立即失效
                // 2026-09-21 【订正, 见 FlushPatchDeferred 上面的说明】原来只按本机
                //   InRaceNoDbWrite()(本机自己的 _raceState)判断要不要押后, RTC 当主控时
                //   本机的 _raceState 从头到尾是空闲, 这个判断形同虚设。改用
                //   _meetDb.LiveActive——不管这一刻是谁在计时, 这个信号都权威(整包那道闸
                //   用的也是它), 三步(落盘/赛程树/广播)统一押后, 不再各按各的判断。
                raceLive = _meetDb.LiveActive;
                if (raceLive) {
                    _patchSaveDirty = true;
                    _scheduleTreeDirty = true;
                    _patchBroadcastDirty = true;
                } else {
                    AutoSaveData();
                    try { BuildScheduleTree(); } catch { }
                }
                RefreshEditPreview();       // 操作员就盯着这张表, 必须当场刷新——纯本机 UI, 不牵扯广播, 不押后
            } finally { _patchInFlight = false; }
            if (!raceLive) {
                Broadcast();                // 100ms 批量去抖, 大屏那一路不受影响
                PushDataChanged("assign");  // 2026-09-13 吭一声, 查询页要用时自己来取
            }
        }

        // ── 编排改动收尾: 落盘 + 用补丁同步给对端(不推整包) ─────────────
        // 那些编辑函数原来最后一句是 AutoSaveData(), 换成这个就行。
        private void SaveAndPushAssign(string ageGroup, string gender, string eventName, string stage) {
            _patchInFlight = true;
            try { AutoSaveData(); } finally { _patchInFlight = false; }
            PushAssignPatch(ageGroup, gender, eventName, stage);
            // 2026-09-18 HandleEditorPatch 里那处同步(见其说明)只在【主服务器收到远端
            //   推来的补丁】那一刻触发——单机版(没有任何远端连接)、或者就是在主服务器
            //   自己身上做"手动分组"这类编辑, 补丁压根没有机会被"收到", 那条路一次都不会跑,
            //   meet.db 永远停在导入那一刻的旧分组。RebuildFromPackage 只对着 _local 操作,
            //   只有这台机器自己就是真身(不是远端客户端)时调它才有意义——远端客户端调了
            //   也是白调, 重建的是它自己那份不算数的空副本, 不能帮到真身那份库。
            if (!_meetDb.IsRemote) ScheduleMeetDbSyncFromPatch();
        }

        /// <summary>补丁上署的名: 让对面日志里看得出是谁改的。</summary>
        private string ClientLabel() {
            if (IsScheduleEditorMode) return "编排端 " + Environment.MachineName;
            if (IsTimingClientMode) return "计时端 " + Environment.MachineName;
            return Environment.MachineName;
        }

        /// <summary>
        /// 2026-09-13 把补丁送出去 —— 【上下游都送】。
        ///   编排端只有上游(连着主服务器), 主服务器只有下游(挂着编排端/计时端),
        ///   RTC 计时端两头都有: 它既是主控, 又挂着自己的大屏客户端。
        /// 原来只按 IsScheduleEditorMode 二选一, RTC 那一路改完谁也不知道。
        /// 返回 false = 上游明确拒了(下游是广播, 无所谓成不成)。
        /// </summary>
        private bool SpreadPatch(JObject p, out string error) {
            error = null;
            bool ok = true;
            if (_editorSyncClient != null && _editorSyncClient.IsConnected)
                ok = SendPatchAndWait(p, out error);
            if (_editorSockets != null && _editorSockets.Count > 0) BroadcastPatch(p, null);
            return ok;
        }

        private bool PushAssignPatch(string ageGroup, string gender, string eventName, string stage) {
            if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(stage)) return true;
            try {
                string err;
                var patch = BuildAssignPatch(ageGroup, gender, eventName, stage, ClientLabel());
                if (SpreadPatch(patch, out err)) return true;
                // 上游拒了(多半是撞上正在比 / 已完赛的组)。本机已经改了, 不手工回滚 ——
                // 编排端拉一次整包, 让主服务器那份把本机盖回去, 省得两边分叉还没人知道。
                if (IsScheduleEditorMode) {
                    AppMessageBox.Show(Loc.F("Str_Msg_AssignRejectedFmt", err),
                        Loc.T("Str_MsgTitle_NotSavedToServer"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    AddLog(Loc.F("Str_Log_EditorPatchRejectedRefetchFmt", err));
                    try {
                        var pull = new JObject();
                        pull["type"] = "EDITOR_PULL_PACKAGE";
                        _editorSyncClient.Send(pull.ToString(Formatting.None));
                    } catch { }
                } else {
                    // 计时端不拉整包 —— 比赛中重载整库正是当初出事的那条路。只喊一声。
                    AddLog(Loc.F("Str_Log_EditorPatchRejectedDivergedFmt", err));
                }
                return false;
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_SendEditorPatchFailedFmt", ex.Message)); }
            return true;
        }

        // ── 2026-09-12 "窗口关了之后看哪几项变了" ──────────────────────
        // 晋级处理、导入分组表这类操作在独立窗口/一大段解析里直接改内存, 不好在
        // 里面一处处插补丁。干脆在外面拍两张快照一比: 哪个(组别|性别|项目|赛次)
        // 的分组变了, 就发哪个的补丁。改一处就覆盖所有这类入口。
        private static void AddSig(Dictionary<string, List<string>> map, string key, string one) {
            List<string> lst;
            if (!map.TryGetValue(key, out lst)) { lst = new List<string>(); map[key] = lst; }
            lst.Add(one);
        }

        private Dictionary<string, string> SnapshotAssignments() {
            var map = new Dictionary<string, List<string>>(StringComparer.Ordinal);
            foreach (var s in _swimmers) {
                if (s == null || string.IsNullOrEmpty(s.EventName)) continue;
                if (!string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                string head = (s.AgeCategory ?? "") + "|" + (s.Gender ?? "") + "|" + s.EventName + "|";
                bool anyStage = false;
                if (s.StageAssignments != null) {
                    foreach (var kv in s.StageAssignments) {
                        if (kv.Value == null || kv.Value.Heat <= 0) continue;
                        anyStage = true;
                        AddSig(map, head + kv.Key, (s.BibNumber ?? "") + ":" + kv.Value.Heat + ":" + kv.Value.Lane);
                    }
                }
                // 没有 StageAssignment 但顶层字段挂着的老数据也算上
                if (!anyStage && s.Heat > 0 && !string.IsNullOrEmpty(s.CurrentStage))
                    AddSig(map, head + s.CurrentStage, (s.BibNumber ?? "") + ":" + s.Heat + ":" + s.Lane);
            }
            var sig = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (var kv in map) {
                kv.Value.Sort(StringComparer.Ordinal);
                sig[kv.Key] = string.Join(",", kv.Value.ToArray());
            }
            return sig;
        }

        /// <summary>和之前那张快照比, 变了的项目逐项发补丁。before 用 SnapshotAssignments() 拍。</summary>
        private void PushChangedAssignments(Dictionary<string, string> before) {
            try {
                var after = SnapshotAssignments();
                var keys = new HashSet<string>(StringComparer.Ordinal);
                foreach (var k in before.Keys) keys.Add(k);
                foreach (var k in after.Keys) keys.Add(k);
                int n = 0;
                foreach (string k in keys) {
                    string b = null, a = null;
                    before.TryGetValue(k, out b);
                    after.TryGetValue(k, out a);
                    if ((b ?? "") == (a ?? "")) continue;
                    var p = k.Split('|');
                    if (p.Length != 4) continue;
                    n++;
                    // 一次失败就打住: 那边已经拒了, 本机马上要整包重来一遍,
                    // 再挨个发下去只会一连串弹窗、一连串 5 秒超时。
                    if (!PushAssignPatch(p[0], p[1], p[2], p[3])) {
                        AddLog(Loc.T("Str_Log_PatchRejectedStopSending"));
                        return;
                    }
                }
                if (n > 0) AddLog(Loc.F("Str_Log_AssignChangesSyncedFmt", n));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_DiffAssignFailedFmt", ex.Message)); }
        }

        // ── 2026-09-12 纪录表补丁 op:"Records" ──────────────────────────
        // 这里【不发整张表】, 只发"改了哪几条 / 删了哪几条"。
        // 原因是那次事故的形状: 比赛中一份旧的纪录表盖过去, 就把刚刚破掉的新纪录
        // 冲没了。按条 upsert 就不会 —— 补丁没提到的行一个字不动。
        private static string RecordKey(SwimmingRecord r) {
            if (r == null) return "";
            return (r.AgeGroup ?? "") + "|" + (r.Gender ?? "") + "|" + (r.EventName ?? "") + "|" + (r.RecordType ?? "");
        }

        private Dictionary<string, string> SnapshotRecords() {
            var d = new Dictionary<string, string>(StringComparer.Ordinal);
            if (_records == null) return d;
            foreach (var r in _records) {
                if (r == null) continue;
                d[RecordKey(r)] = r.TimeInSeconds.ToString("F3") + "|" + (r.HolderName ?? "") + "|"
                                + (r.HolderCountry ?? "") + "|" + (r.Date ?? "") + "|" + (r.Location ?? "");
            }
            return d;
        }

        // 就地编辑那张表用的基准线: 上一次保存/同步时纪录长什么样。
        // 表格是直接改对象的, 没有基准线就不知道"改了哪几条"。
        private Dictionary<string, string> _recordsBaseline;
        private void ResetRecordsBaseline() { try { _recordsBaseline = SnapshotRecords(); } catch { } }

        /// <summary>和之前那张快照比, 改过/删掉的纪录发一条补丁出去。返回变动条数。</summary>
        private int PushChangedRecords(Dictionary<string, string> before) {
            try {
                var after = SnapshotRecords();
                var ups = new JArray();
                var dels = new JArray();
                foreach (var r in _records) {
                    if (r == null) continue;
                    if (string.IsNullOrWhiteSpace(r.EventName)) continue;   // 空白行(刚点"添加纪录"还没填)不外发
                    string k = RecordKey(r);
                    string b;
                    if (before.TryGetValue(k, out b) && b == after[k]) continue;   // 没变
                    try { ups.Add(JObject.FromObject(r)); } catch { }
                }
                foreach (var kv in before) if (!after.ContainsKey(kv.Key)) dels.Add(kv.Key);
                if (ups.Count == 0 && dels.Count == 0) { ResetRecordsBaseline(); return 0; }

                var p = NewPatch("Records", "", "", "", "", ClientLabel());
                p["upserts"] = ups;
                p["deletes"] = dels;
                string rerr;
                if (!SpreadPatch(p, out rerr))
                    AddLog(Loc.F("Str_Log_RecordsPatchNotSentFmt", rerr));
                AddLog(Loc.F("Str_Log_RecordsChangedFmt", ups.Count, dels.Count));
                // 2026-09-18 补丁只同步了内存/JSON, 竞赛库(meet.db)另外补一步——见
                // SyncRecordsPatchToMeetDb 的说明。在【编辑发生的这台机器】上做, 不管
                // 是不是联机: _meetDb 单机时直接写本机, 联机时经 _meet RPC 写到真身
                // 那台, 不依赖 SpreadPatch 那条 WebSocket 通道是否连着/成不成功。
                try { SyncRecordsPatchToMeetDb(p); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RecordsSyncMeetDbFailedFmt", ex.Message)); }
                ResetRecordsBaseline();
                return ups.Count + dels.Count;
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_DiffRecordsFailedFmt", ex.Message)); return 0; }
        }

        /// <summary>
        /// 2026-09-18 手工编辑纪录(ApplyRecordsPatch)原来只改了内存 _records 和 JSON 存档,
        /// 从没写进过主服务器的竞赛库(meet.db 的 records 表)——SaveRecord/DeleteRecord 这两个
        /// IMeetService 方法早就实现完整, 只是没人调用过。这个 gap 很隐蔽但后果不小:
        /// 确认成绩时自动"破没破纪录"的判定(CheckRecordBreak)直接查 meet.db 里的 records 表,
        /// 手工订正过的纪录(比如赛前发现原记录抄错了)如果没同步进去, 现场判定用的还是
        /// 错误的旧纪录, 会错判"破纪录"或者漏判。
        /// 只在【主服务器自己】这台机器上调(见 HandleEditorPatch 里的调用点)——_meetDb 在
        /// 别的机器上不是真身, 而这里最终写的是 IMeetService(_meet), 单机时就是本机直接写,
        /// 联机时是 RPC 写到真身那台, 不需要每台收到补丁的机器都各写一遍。
        /// </summary>
        private void SyncRecordsPatchToMeetDb(JObject msg) {
            if (_meetDb == null || !_meetDb.IsOpen) return;
            try {
                int savedN = 0, delN = 0;
                var ups = msg["upserts"] as JArray;
                if (ups != null) {
                    foreach (var t in ups) {
                        var jo = t as JObject;
                        if (jo == null) continue;
                        SwimmingRecord sr = null;
                        try { sr = jo.ToObject<SwimmingRecord>(); } catch { }
                        if (sr == null || string.IsNullOrWhiteSpace(sr.EventName)) continue;
                        int dist, legs; string stroke;
                        SwimmingScoreboard.Db.PackageImporter.ParseEventName(sr.EventName, out dist, out stroke, out legs);
                        long existingId = 0;
                        try {
                            var existing = _meetDb.GetRecords(sr.AgeGroup ?? "", sr.Gender, dist, stroke, legs);
                            var hit = existing.FirstOrDefault(x => x.RecordType == sr.RecordType);
                            if (hit != null) existingId = hit.Id;
                        } catch { }
                        var dto = new SwimmingScoreboard.Db.RecordDto {
                            Id = existingId,
                            Abbr = SwimmingScoreboard.Db.PackageImporter.AbbrOf(sr.RecordType),
                            RecordType = sr.RecordType,
                            AgeGroup = sr.AgeGroup ?? "",
                            Gender = sr.Gender,
                            Distance = dist,
                            Stroke = stroke,
                            RelayLegs = legs,
                            EventName = sr.EventName,
                            TimeSeconds = sr.TimeInSeconds > 0 ? sr.TimeInSeconds : sr.Time,
                            HolderName = sr.HolderName,
                            HolderCountry = sr.HolderCountry,
                            Date = sr.Date,
                            Location = sr.Location,
                            IsCurrent = true
                        };
                        if (_meetDb.SaveRecord(dto, ClientLabel()) > 0 || existingId > 0) savedN++;
                    }
                }
                var dels = msg["deletes"] as JArray;
                if (dels != null) {
                    foreach (var t in dels) {
                        string k = t != null ? t.ToString() : "";
                        var parts = (k ?? "").Split('|');
                        if (parts.Length < 4) continue;
                        int dist, legs; string stroke;
                        SwimmingScoreboard.Db.PackageImporter.ParseEventName(parts[2], out dist, out stroke, out legs);
                        try {
                            var existing = _meetDb.GetRecords(parts[0], parts[1], dist, stroke, legs);
                            var hit = existing.FirstOrDefault(x => x.RecordType == parts[3]);
                            if (hit != null) { _meetDb.DeleteRecord(hit.Id, ClientLabel()); delN++; }
                        } catch { }
                    }
                }
                if (savedN > 0 || delN > 0)
                    AddLog(Loc.F("Str_Log_RecordsMeetDbSyncedFmt", savedN, delN));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_RecordsPatchMeetDbFailedFmt", ex.Message)); }
        }

        /// <summary>收到纪录补丁: 按条 upsert / 删除。没提到的行一个字不动。</summary>
        private bool ApplyRecordsPatch(JObject msg, out string error) {
            error = null;
            int up = 0, del = 0;
            var ups = msg["upserts"] as JArray;
            if (ups != null) {
                foreach (var t in ups) {
                    var jo = t as JObject;
                    if (jo == null) continue;
                    SwimmingRecord nr = null;
                    try { nr = jo.ToObject<SwimmingRecord>(); } catch { }
                    if (nr == null) continue;
                    string k = RecordKey(nr);
                    var cur = _records.FirstOrDefault(x => x != null && RecordKey(x) == k);
                    if (cur == null) { _records.Add(nr); up++; continue; }
                    cur.HolderName = nr.HolderName; cur.HolderCountry = nr.HolderCountry;
                    cur.Time = nr.Time; cur.TimeInSeconds = nr.TimeInSeconds;
                    cur.Date = nr.Date; cur.Location = nr.Location;
                    up++;
                }
            }
            var dels = msg["deletes"] as JArray;
            if (dels != null) {
                foreach (var t in dels) {
                    string k = t != null ? t.ToString() : "";
                    if (string.IsNullOrEmpty(k)) continue;
                    var cur = _records.FirstOrDefault(x => x != null && RecordKey(x) == k);
                    if (cur != null) { _records.Remove(cur); del++; }
                }
            }
            _patchInFlight = true;
            try {
                AutoSaveData();
                try { RefreshRecordFilterCombos(); ApplyRecordFilter(); } catch { }
                Broadcast();
            } finally { _patchInFlight = false; }
            ResetRecordsBaseline();   // 2026-09-12 远端改过了, 基准线跟着走
            PushDataChanged("records");
            AddLog(Loc.F("Str_Log_RecordsPatchAppliedFmt", up, del));
            return true;
        }

        /// <summary>落盘但不推整包 —— 后面会用补丁同步。</summary>
        private void SaveWithoutPush() {
            _patchInFlight = true;
            try { AutoSaveData(); } finally { _patchInFlight = false; }
        }

        /// <summary>整场里有没有已完赛的组 / 正在比。整批重写分组的操作(导入整本分组表)之前问一句。</summary>
        private bool MeetHasLockedHeats(out string what) {
            what = null;
            if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) {
                what = "正在计时(" + (_raceState == RaceState.Ready ? "已就位" : "比赛中") + ")";
                return true;
            }
            if (_confirmedHeats != null && _confirmedHeats.Count > 0) {
                what = "已经有 " + _confirmedHeats.Count + " 个组完赛";
                return true;
            }
            return false;
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-09-13 【解锁本组成绩】
        //
        // 为什么要有这个口子: 「确认本组成绩」一按, 这一组就进 _confirmedHeats,
        // 赛程树标 [已完赛], 成绩从此不许改。可现场常有的事是 —— 按错了,
        // 或者按下去之后才发现某道成绩不对。没有解锁, 那条错成绩就永远钉在那儿了。
        //
        // 三条规矩:
        //   · 正在计时/已就位时不许解锁 —— 那会儿这一组还没比完, 谈不上解锁。
        //   · 二次确认: 先看清楚要解哪一组(第一道), 再手输组号 + 写明原因(第二道)。
        //     手输组号是防手滑的老办法 —— 看一眼弹窗就点"是"的人, 输不出那个数。
        //   · 必须留痕: 系统日志 + 竞赛库 audit_log 各记一条, 记谁、几点、为什么。
        //
        // 解开之后这一组回到"有成绩但没确认"的状态: 成绩能改, 改完【再点一次
        // 「确认本组成绩」重新锁上】—— 不重新确认, 赛程树上就一直是没完赛。
        private void UnlockHeatResult_Click(object sender, RoutedEventArgs e) {
            string ag = _currentAgeGroup, gd = _currentGender, ev = _currentEvent, st = _currentStage;
            int heat = _currentHeat;

            if (string.IsNullOrEmpty(ev) || heat <= 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoHeatLoaded"),
                    Loc.T("Str_RC_UnlockResult"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) {
                AppMessageBox.Show(Loc.F("Str_Msg_CannotUnlockRacingFmt",
                    _raceState == RaceState.Ready ? Loc.T("Str_Msg_Ready2") : Loc.T("Str_Msg_Racing")),
                    Loc.T("Str_RC_UnlockResult"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            if (!IsHeatMarkedFinished(ag, gd, ev, st, heat)) {
                AppMessageBox.Show(Loc.F("Str_Msg_HeatNotLockedFmt", heat),
                    Loc.T("Str_MsgTitle_NoNeedToUnlock"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            string head = Loc.F("Str_Frag_HeatHeaderFmt",
                Loc.GenderDisplay(gd), string.IsNullOrEmpty(ag) ? "" : ag, ev, Loc.StageDisplay(st), heat);

            // ── 第一道: 看清楚要解哪一组 ──
            if (AppMessageBox.Show(
                Loc.F("Str_Msg_UnlockStep1Fmt", head),
                Loc.T("Str_MsgTitle_UnlockStep1"), MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes)
                return;

            // ── 第二道: 手输组号 + 写原因 ──
            string reason;
            if (!AskUnlockConfirm(head, heat, out reason)) {
                AddLog(Loc.F("Str_Log_UnlockCancelledFmt", head));
                return;
            }

            UnlockHeatResult(ag, gd, ev, st, heat, reason, Environment.MachineName, true);
        }

        /// <summary>解锁的第二道确认窗: 手输组号 + 必填原因。两样都对才返回 true。</summary>
        private bool AskUnlockConfirm(string head, int heat, out string reason) {
            reason = "";
            var win = new Window {
                Title = Loc.T("Str_MsgTitle_UnlockStep2"), Width = 520, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, ResizeMode = ResizeMode.NoResize, Owner = this
            };
            var root = new StackPanel { Margin = new Thickness(18) };
            root.Children.Add(new TextBlock {
                Text = head, FontSize = 15, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 10)
            });
            root.Children.Add(new TextBlock {
                Text = Loc.T("Str_Win_UnlockConfirm_Body"),
                TextWrapping = TextWrapping.Wrap, Foreground = System.Windows.Media.Brushes.DimGray,
                Margin = new Thickness(0, 0, 0, 12)
            });

            var r1 = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 8) };
            r1.Children.Add(new TextBlock { Text = Loc.T("Str_Win_MergeHeats_ReasonLabel"), VerticalAlignment = VerticalAlignment.Center, FontSize = 14, Width = 100 });
            var reasonBox = new TextBox { Width = 380, FontSize = 14, Padding = new Thickness(4) };
            r1.Children.Add(reasonBox);
            root.Children.Add(r1);
            root.Children.Add(new TextBlock {
                Text = Loc.T("Str_Win_UnlockConfirm_ReasonExample"),
                Foreground = System.Windows.Media.Brushes.DimGray, FontSize = 12, Margin = new Thickness(100, 0, 0, 10)
            });

            var r2 = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 6) };
            r2.Children.Add(new TextBlock { Text = Loc.F("Str_Win_UnlockConfirm_HeatInputLabelFmt", heat), VerticalAlignment = VerticalAlignment.Center, FontSize = 14, Width = 100 });
            var heatBox = new TextBox { Width = 80, FontSize = 14, Padding = new Thickness(4) };
            r2.Children.Add(heatBox);
            root.Children.Add(r2);

            var tip = new TextBlock { TextWrapping = TextWrapping.Wrap, FontSize = 12,
                Foreground = System.Windows.Media.Brushes.Firebrick, Margin = new Thickness(0, 6, 0, 0) };
            root.Children.Add(tip);

            var btns = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 14, 0, 0) };
            bool go = false;
            var ok = new Button { Content = Loc.T("Str_Win_UnlockConfirm_OkBtn"), Width = 100, Height = 30, Margin = new Thickness(0, 0, 8, 0), IsDefault = true };
            var cancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Width = 80, Height = 30, IsCancel = true };
            ok.Click += delegate {
                string rs = (reasonBox.Text ?? "").Trim();
                int typed;
                if (rs.Length < 2) { tip.Text = Loc.T("Str_Win_UnlockConfirm_MsgReasonTooShort"); reasonBox.Focus(); return; }
                if (!int.TryParse((heatBox.Text ?? "").Trim(), out typed) || typed != heat) {
                    tip.Text = Loc.F("Str_Win_UnlockConfirm_MsgHeatMismatchFmt", heat); heatBox.Focus(); return;
                }
                go = true; win.DialogResult = true;
            };
            btns.Children.Add(ok); btns.Children.Add(cancel);
            root.Children.Add(btns);
            win.Content = root;
            reasonBox.Focus();
            if (win.ShowDialog() != true || !go) return false;
            reason = (reasonBox.Text ?? "").Trim();
            return true;
        }

        /// <summary>
        /// 真正解锁。本机点按钮和收到远端补丁走同一份 —— 两边必须一致。
        /// spread=true 时把这件事以补丁形式扩散给对端。
        /// </summary>
        private bool UnlockHeatResult(string ageGroup, string gender, string eventName, string stage,
                                      int heat, string reason, string op, bool spread) {
            if (heat <= 0 || string.IsNullOrEmpty(eventName)) return false;

            // _confirmedHeats 里可能是用别的组别写法记的(并项组别), 把对得上的都摘掉,
            // 只摘一个 key 会出现"解了还显示已完赛"。
            var toRemove = new List<string>();
            string exact = ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat);
            foreach (string key in _confirmedHeats)
                if (key == exact || HeatKeyMatches(key, ageGroup, gender, eventName, stage, heat)) toRemove.Add(key);
            foreach (string k in toRemove) _confirmedHeats.Remove(k);
            if (toRemove.Count == 0) return false;
            // 记一笔"这组是被解开的" —— 压住那条"全员有成绩就算完赛"的推断,
            // 否则赛程树立刻又标回 [已完赛], 也不让重赛。
            _unlockedHeats.Add(exact);
            foreach (string k in toRemove) _unlockedHeats.Add(k);

            // 解的就是当前装载的这一组 → UI 状态跟着回到"未确认"
            if (heat == _currentHeat && SameLoadedEvent(ageGroup, gender, eventName, stage))
                _resultConfirmed = false;

            string head = string.Format("{0} {1} {2} {3} 第{4}组",
                gender, string.IsNullOrEmpty(ageGroup) ? "" : ageGroup, eventName, stage, heat);
            AddLog(Loc.F("Str_Log_UnlockDoneFmt",
                head, op ?? Environment.MachineName, string.IsNullOrEmpty(reason) ? "(未写)" : reason));

            // 竞赛库审计表也记一条 —— 系统日志是会滚掉的, 审计表不会
            try {
                _meetDb.LogAudit("解锁本组成绩", "heats", "已完赛", "未确认",
                                 head + " 原因: " + (string.IsNullOrEmpty(reason) ? "(未写)" : reason),
                                 op ?? Environment.MachineName);
            } catch { }

            _patchInFlight = true;
            try {
                AutoSaveData();
                try { BuildScheduleTree(); } catch { }
                try { UpdateResultHeatCombo(); RefreshResultGrid(); } catch { }
                try { UpdateRaceStateDisplay(); UpdateLaneStatusDisplay(); } catch { }
                Broadcast();
            } finally { _patchInFlight = false; }

            if (spread) {
                var p2 = NewPatch("Unlock", ageGroup, gender, eventName, stage, ClientLabel());
                p2["heat"] = heat;
                p2["reason"] = reason ?? "";
                string uerr;
                if (!SpreadPatch(p2, out uerr))
                    AddLog(Loc.F("Str_Log_UnlockNotSyncedFmt", uerr));
            }
            return true;
        }

        // 2026-09-21 检录状态改动的唯一落地点——本机点"确认检录"(HandleSaveCheckin)
        //   和收到远端转发来的"CheckIn"补丁(ApplyCheckInPatch)都走这一份, 保证两条路
        //   对"标已检录"这件事的理解(加到 _checkedInHeats + 重画树)完全一致。
        private void MarkHeatCheckedInCore(string ageGroup, string gender, string eventName, string stage, int heat) {
            _checkedInHeats.Add(ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat));
            try { BuildScheduleTree(); } catch { }   // 重画"比赛控制"树, 顺带联动赛程管理/成绩与排名/出场编排微调三棵
        }

        /// <summary>收到检录补丁——本机(主服务器/比赛控制exe/编排端)同步别处检录台刚交的表。</summary>
        private bool ApplyCheckInPatch(JObject msg, out string error) {
            error = null;
            string ag = msg["ageGroup"] != null ? msg["ageGroup"].ToString() : "";
            string gd = msg["gender"] != null ? msg["gender"].ToString() : "";
            string ev = msg["eventName"] != null ? msg["eventName"].ToString() : "";
            string st = msg["stage"] != null ? msg["stage"].ToString() : "";
            int heat = 0;
            try { if (msg["heat"] != null) heat = (int)msg["heat"]; } catch { }
            if (heat <= 0) { error = "补丁没说检录的是哪一组"; return false; }
            MarkHeatCheckedInCore(ag, gd, ev, st, heat);
            return true;
        }

        /// <summary>收到解锁补丁。</summary>
        private bool ApplyUnlockPatch(JObject msg, out string error) {
            error = null;
            string ag = msg["ageGroup"] != null ? msg["ageGroup"].ToString() : "";
            string gd = msg["gender"] != null ? msg["gender"].ToString() : "";
            string ev = msg["eventName"] != null ? msg["eventName"].ToString() : "";
            string st = msg["stage"] != null ? msg["stage"].ToString() : "";
            string rs = msg["reason"] != null ? msg["reason"].ToString() : "";
            string who = msg["clientName"] != null ? msg["clientName"].ToString() : "远端";
            int heat = 0;
            try { if (msg["heat"] != null) heat = (int)msg["heat"]; } catch { }
            if (heat <= 0) { error = "补丁没说解哪一组"; return false; }
            // 正在比那一组不许被远端解 —— 解了就等于允许改正在比的成绩
            if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) {
                if (heat == _currentHeat && SameLoadedEvent(ag, gd, ev, st)) {
                    error = string.Format("第{0}组正在计时, 不解锁", heat);
                    return false;
                }
            }
            if (!UnlockHeatResult(ag, gd, ev, st, heat, rs, who, false)) {
                error = string.Format("第{0}组本机没标已完赛, 不用解", heat);
                return false;
            }
            return true;
        }

        // 2026-09-19 用户明确要求: "没必要进行整包, 应该分包——改哪部分就是哪个包,
        //   这样影响最小"。编辑接力队信息(EditRelay_Click)一直是本文件里少数还没
        //   搬过来的老路之一, 走的是 AutoSaveData()→整包推送——现场事故(TP/MB 计时中
        //   被冲成关闭)的诱因正是这条路。这里补一个跟 Assign/MergeHeats 同一套写法的
        //   小补丁: 只带"这一支接力队改了什么", 不碰任何跟硬件、跟别的项目相关的数据。
        //   ApplyRelayEditCore 是发起端(EditRelay_Click)和接收端(ApplyRelayEditPatch)
        //   共用的唯一一份改法, 两条路必须字字一致, 否则两边的接力队信息会分叉。
        private bool ApplyRelayEditCore(string oldTeamName, string oldEvent, string oldGender,
                                        List<string> oldLegNames,
                                        string newTeamName, string newCountry, string newEvent, string newGender,
                                        string newEntryTime, double newEntryTimeSeconds, List<string> legNames,
                                        out string error) {
            error = null;
            oldLegNames = oldLegNames ?? new List<string>();
            var proxy = _swimmers.FirstOrDefault(s =>
                s.Name == oldTeamName && s.EventName == oldEvent && s.Gender == oldGender
                && !IsRelayMemberNote(s.Notes));
            if (proxy == null) { error = "本机找不到这支接力队(可能数据已不一致)"; return false; }

            proxy.Name = newTeamName;
            proxy.Country = newCountry;
            proxy.EventName = newEvent;
            proxy.Gender = newGender;
            proxy.EntryTime = newEntryTime;
            proxy.EntryTimeSeconds = newEntryTimeSeconds;
            string legNamesStr = string.Join(",", (legNames ?? new List<string>()).ToArray());
            proxy.Notes = "接力队 棒次:" + legNamesStr;

            for (int i = 0; i < Math.Min(4, legNames != null ? legNames.Count : 0); i++) {
                string oldLegName = i < oldLegNames.Count ? oldLegNames[i] : "";
                string newLegName = legNames[i] ?? "";
                if (string.IsNullOrEmpty(oldLegName) && string.IsNullOrEmpty(newLegName)) continue;
                var memEntry = _swimmers.FirstOrDefault(s =>
                    s.Notes != null && s.Notes.StartsWith("接力队员")
                    && s.Country == oldTeamName && s.EventName == oldEvent
                    && s.Name == oldLegName);
                if (memEntry != null) {
                    memEntry.Name = newLegName;
                    memEntry.Country = newTeamName;
                    memEntry.EventName = newEvent;
                    memEntry.Gender = newGender == "混合" ? memEntry.Gender : newGender;
                    memEntry.Notes = string.Format("接力队员 {0} 第{1}棒", newEvent, i + 1);
                } else if (!string.IsNullOrEmpty(newLegName)) {
                    string memBib = proxy.BibNumber + "-" + (i + 1);
                    if (!_swimmers.Any(s => s.BibNumber == memBib)) {
                        _swimmers.Add(new Swimmer {
                            BibNumber = memBib, Name = newLegName,
                            Gender = newGender == "混合" ? "男" : newGender,
                            Country = newTeamName, EventName = newEvent,
                            Notes = string.Format("接力队员 {0} 第{1}棒", newEvent, i + 1)
                        });
                    }
                }
            }
            return true;
        }

        private JObject BuildRelayEditPatch(string oldTeamName, string oldEvent, string oldGender, List<string> oldLegNames,
                                            string newTeamName, string newCountry, string newEvent, string newGender,
                                            string newEntryTime, double newEntryTimeSeconds, List<string> legNames,
                                            string clientName) {
            var p = NewPatch("RelayEdit", "", newGender, newEvent, "", clientName);
            p["oldTeamName"] = oldTeamName ?? ""; p["oldEvent"] = oldEvent ?? ""; p["oldGender"] = oldGender ?? "";
            // 2026-09-19 旧棒次姓名必须跟着补丁一起传——接收端没有发起端那份 RelayTeam UI
            //   对象可以现取"改之前是什么", 只能靠补丁自己带全, 否则两边各按各的猜, 对不上号。
            p["oldLegNames"] = JArray.FromObject(oldLegNames ?? new List<string>());
            p["newTeamName"] = newTeamName ?? ""; p["newCountry"] = newCountry ?? "";
            p["newEvent"] = newEvent ?? ""; p["newGender"] = newGender ?? "";
            p["newEntryTime"] = newEntryTime ?? ""; p["newEntryTimeSeconds"] = newEntryTimeSeconds;
            p["legNames"] = JArray.FromObject(legNames ?? new List<string>());
            return p;
        }

        /// <summary>编排端: 发接力队编辑补丁(先问后改, 跟并组同一个待遇——万一撞上正在比的组要能拒)。</summary>
        private bool SendRelayEditPatch(string oldTeamName, string oldEvent, string oldGender, List<string> oldLegNames,
                                        string newTeamName, string newCountry, string newEvent, string newGender,
                                        string newEntryTime, double newEntryTimeSeconds, List<string> legNames,
                                        out string error) {
            return SendPatchAndWait(BuildRelayEditPatch(oldTeamName, oldEvent, oldGender, oldLegNames, newTeamName,
                newCountry, newEvent, newGender, newEntryTime, newEntryTimeSeconds, legNames, ClientLabel()), out error);
        }

        /// <summary>主服务器本机改的接力队信息 → 以补丁形式发给各编排端(同样不推整包)。</summary>
        private void BroadcastRelayEditPatch(string oldTeamName, string oldEvent, string oldGender, List<string> oldLegNames,
                                             string newTeamName, string newCountry, string newEvent, string newGender,
                                             string newEntryTime, double newEntryTimeSeconds, List<string> legNames,
                                             string clientName, IWebSocketConnection except) {
            BroadcastPatch(BuildRelayEditPatch(oldTeamName, oldEvent, oldGender, oldLegNames, newTeamName, newCountry,
                newEvent, newGender, newEntryTime, newEntryTimeSeconds, legNames, clientName), except);
        }

        private static List<string> ReadJArrayStrings(JObject msg, string key) {
            var list = new List<string>();
            var arr = msg[key] as JArray;
            if (arr != null) foreach (var t in arr) list.Add(t != null ? t.ToString() : "");
            return list;
        }

        private bool ApplyRelayEditPatch(JObject msg, out string error) {
            string oldTeamName = msg["oldTeamName"] != null ? msg["oldTeamName"].ToString() : "";
            string oldEvent = msg["oldEvent"] != null ? msg["oldEvent"].ToString() : "";
            string oldGender = msg["oldGender"] != null ? msg["oldGender"].ToString() : "";
            string newTeamName = msg["newTeamName"] != null ? msg["newTeamName"].ToString() : "";
            string newCountry = msg["newCountry"] != null ? msg["newCountry"].ToString() : "";
            string newEvent = msg["newEvent"] != null ? msg["newEvent"].ToString() : "";
            string newGender = msg["newGender"] != null ? msg["newGender"].ToString() : "";
            string newEntryTime = msg["newEntryTime"] != null ? msg["newEntryTime"].ToString() : "";
            double newEntryTimeSeconds = 0;
            try { if (msg["newEntryTimeSeconds"] != null) newEntryTimeSeconds = (double)msg["newEntryTimeSeconds"]; } catch { }
            var oldLegNames = ReadJArrayStrings(msg, "oldLegNames");
            var legNames = ReadJArrayStrings(msg, "legNames");
            return ApplyRelayEditCore(oldTeamName, oldEvent, oldGender, oldLegNames, newTeamName, newCountry, newEvent,
                newGender, newEntryTime, newEntryTimeSeconds, legNames, out error);
        }

        // 2026-09-19 接力队编辑收尾——跟 FinishPatchApply(Assign 那条路用的)同一个道理,
        //   但不需要重建赛程树(接力队信息不影响道次/组次), 更轻。
        private void FinishRelayEditPatchApply() {
            _patchInFlight = true;
            try {
                RebuildRelayGroupedView();
                AutoSaveData();
                Broadcast();
            } finally { _patchInFlight = false; }
            PushDataChanged("relay");
        }

        // 2026-09-19 用户明确要求: "编排记录（除接力队外还有单人比赛等）信息编辑改走
        //   小补丁, 不要推整包"。这里是"修改运动员信息"那条路的核心改法——发起端
        //   (EditSwimmer_Click)和接收端(ApplySwimmerEditPatch)共用同一份, 校验(参赛号
        //   查重)、赋值、"同一参赛号级联到其它项目记录+接力棒次"这三步原样从
        //   OpenSwimmerEditor 搬过来, 一字不差, 只是改成按 (oldBib, oldEventName)
        //   在【当前这台机器的 _swimmers】里现查 target, 不再依赖调用方传一个对象引用
        //   过来(补丁走网络, 传不了对象引用)。
        private bool ApplySwimmerEditCore(PendingSwimmerEdit f, out string error) {
            error = null;
            var target = _swimmers.FirstOrDefault(s => s.BibNumber == f.OldBib && s.EventName == f.OldEventName);
            if (target == null) { error = "本机找不到这条运动员项目记录(可能数据已不一致)"; return false; }

            string oldBib = f.OldBib, newBib = f.NewBib;
            if (newBib != oldBib) {
                var others = _swimmers.Where(s => s != target && s.BibNumber == newBib).ToList();
                if (others.Any(s => s.Name != f.Name ||
                    (!string.IsNullOrEmpty(s.IDNumber) && !string.IsNullOrEmpty(f.IDNumber) && s.IDNumber != f.IDNumber))) {
                    error = string.Format("参赛号 {0} 已被其他运动员使用，请换一个号码。", newBib);
                    return false;
                }
            }

            target.Name = f.Name;
            target.Gender = f.Gender;
            target.BirthDate = f.BirthDate;
            target.Age = f.Age;
            target.IDNumber = f.IDNumber;
            target.Country = f.Country;
            target.CountryShort = f.CountryShort;
            target.Phone = f.Phone;
            target.CSANumber = f.CSANumber;
            target.EventName = f.EventName;
            target.EntryTime = f.EntryTime;
            target.EntryTimeSeconds = f.EntryTimeSeconds;
            target.CurrentStage = f.CurrentStage;
            target.AgeCategory = f.AgeCategory;
            target.Notes = f.Notes;

            // 号码变更：级联更新同一人的其它项目记录 + 接力棒次
            if (newBib != oldBib) {
                foreach (var s in _swimmers) { if (s != target && s.BibNumber == oldBib) s.BibNumber = newBib; }
                if (_relayTeams != null) {
                    foreach (var team in _relayTeams)
                        foreach (var leg in team.Legs)
                            if (!string.IsNullOrEmpty(leg.SwimmerBibNumber) && leg.SwimmerBibNumber == oldBib)
                                leg.SwimmerBibNumber = newBib;
                }
                AddLog(Loc.F("Str_Log_BibChangedFmt", oldBib, newBib, target.Name));
            } else {
                target.BibNumber = newBib;
            }

            // 同步同一参赛号其它项目记录
            foreach (var s in _swimmers) {
                if (s != target && s.BibNumber == target.BibNumber) {
                    s.Name = target.Name; s.Gender = target.Gender; s.BirthDate = target.BirthDate;
                    s.Age = target.Age; s.IDNumber = target.IDNumber; s.Country = target.Country;
                    s.CountryShort = target.CountryShort; s.Phone = target.Phone; s.CSANumber = target.CSANumber;
                }
            }
            return true;
        }

        private JObject BuildSwimmerEditPatch(PendingSwimmerEdit f, string clientName) {
            var p = NewPatch("SwimmerEdit", "", f.Gender, f.EventName, "", clientName);
            p["oldBib"] = f.OldBib ?? ""; p["oldEventName"] = f.OldEventName ?? ""; p["newBib"] = f.NewBib ?? "";
            p["name"] = f.Name ?? ""; p["gender"] = f.Gender ?? ""; p["birthDate"] = f.BirthDate ?? "";
            p["age"] = f.Age; p["idNumber"] = f.IDNumber ?? ""; p["country"] = f.Country ?? "";
            p["countryShort"] = f.CountryShort ?? ""; p["phone"] = f.Phone ?? ""; p["csaNumber"] = f.CSANumber ?? "";
            p["eventName"] = f.EventName ?? ""; p["entryTime"] = f.EntryTime ?? ""; p["entryTimeSeconds"] = f.EntryTimeSeconds;
            p["currentStage"] = f.CurrentStage ?? ""; p["ageCategory"] = f.AgeCategory ?? ""; p["notes"] = f.Notes ?? "";
            return p;
        }

        /// <summary>编排端: 发运动员编辑补丁(先问后改)。</summary>
        private bool SendSwimmerEditPatch(PendingSwimmerEdit f, out string error) {
            return SendPatchAndWait(BuildSwimmerEditPatch(f, ClientLabel()), out error);
        }

        /// <summary>主服务器本机改的运动员信息 → 以补丁形式发给各编排端(同样不推整包)。</summary>
        private void BroadcastSwimmerEditPatch(PendingSwimmerEdit f, string clientName, IWebSocketConnection except) {
            BroadcastPatch(BuildSwimmerEditPatch(f, clientName), except);
        }

        private bool ApplySwimmerEditPatch(JObject msg, out string error) {
            var f = new PendingSwimmerEdit {
                OldBib = msg["oldBib"] != null ? msg["oldBib"].ToString() : "",
                OldEventName = msg["oldEventName"] != null ? msg["oldEventName"].ToString() : "",
                NewBib = msg["newBib"] != null ? msg["newBib"].ToString() : "",
                Name = msg["name"] != null ? msg["name"].ToString() : "",
                Gender = msg["gender"] != null ? msg["gender"].ToString() : "",
                BirthDate = msg["birthDate"] != null ? msg["birthDate"].ToString() : "",
                IDNumber = msg["idNumber"] != null ? msg["idNumber"].ToString() : "",
                Country = msg["country"] != null ? msg["country"].ToString() : "",
                CountryShort = msg["countryShort"] != null ? msg["countryShort"].ToString() : "",
                Phone = msg["phone"] != null ? msg["phone"].ToString() : "",
                CSANumber = msg["csaNumber"] != null ? msg["csaNumber"].ToString() : "",
                EventName = msg["eventName"] != null ? msg["eventName"].ToString() : "",
                EntryTime = msg["entryTime"] != null ? msg["entryTime"].ToString() : "",
                CurrentStage = msg["currentStage"] != null ? msg["currentStage"].ToString() : "",
                AgeCategory = msg["ageCategory"] != null ? msg["ageCategory"].ToString() : "",
                Notes = msg["notes"] != null ? msg["notes"].ToString() : ""
            };
            try { if (msg["age"] != null) f.Age = (int)msg["age"]; } catch { }
            try { if (msg["entryTimeSeconds"] != null) f.EntryTimeSeconds = (double)msg["entryTimeSeconds"]; } catch { }
            return ApplySwimmerEditCore(f, out error);
        }

        // 2026-09-19 收尾——跟 FinishRelayEditPatchApply 同一个道理, 运动员信息不影响
        //   道次/组次, 不需要重建赛程树。
        private void FinishSwimmerEditPatchApply() {
            _patchInFlight = true;
            try {
                AutoSaveData();
                Broadcast();
            } finally { _patchInFlight = false; }
            PushDataChanged("swimmer");
        }

        // 2026-09-19 删接力队/删运动员——跟编辑同一个道理, 一并搬过来。
        private bool ApplyRelayDeleteCore(string teamName, string eventName, string gender, out string error) {
            error = null;
            var team = _relayTeams.FirstOrDefault(t => t.TeamName == teamName && t.EventName == eventName && t.Gender == gender);
            if (team == null) { error = "本机找不到这支接力队(可能已被删除)"; return false; }
            var proxy = _swimmers.FirstOrDefault(s => s.Name == teamName && s.EventName == eventName && s.Gender == gender
                && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队"));
            if (proxy != null) _swimmers.Remove(proxy);
            _relayTeams.Remove(team);
            return true;
        }
        private JObject BuildRelayDeletePatch(string teamName, string eventName, string gender, string clientName) {
            var p = NewPatch("RelayDelete", "", gender, eventName, "", clientName);
            p["teamName"] = teamName ?? ""; return p;
        }
        private bool SendRelayDeletePatch(string teamName, string eventName, string gender, out string error) {
            return SendPatchAndWait(BuildRelayDeletePatch(teamName, eventName, gender, ClientLabel()), out error);
        }
        private void BroadcastRelayDeletePatch(string teamName, string eventName, string gender, string clientName, IWebSocketConnection except) {
            BroadcastPatch(BuildRelayDeletePatch(teamName, eventName, gender, clientName), except);
        }
        private bool ApplyRelayDeletePatch(JObject msg, out string error) {
            string teamName = msg["teamName"] != null ? msg["teamName"].ToString() : "";
            string eventName = msg["eventName"] != null ? msg["eventName"].ToString() : "";
            string gender = msg["gender"] != null ? msg["gender"].ToString() : "";
            return ApplyRelayDeleteCore(teamName, eventName, gender, out error);
        }

        // 运动员删除: 一次可能删好几条(多选), 补丁里带一份清单。
        private class SwimmerDeleteKey { public string BibNumber, Name, EventName; }
        private bool ApplySwimmerDeleteCore(List<SwimmerDeleteKey> keys, out int removed, out string error) {
            error = null; removed = 0;
            foreach (var k in keys ?? new List<SwimmerDeleteKey>()) {
                var sw = _swimmers.FirstOrDefault(s => s.BibNumber == k.BibNumber && s.Name == k.Name && s.EventName == k.EventName);
                if (sw != null) { _swimmers.Remove(sw); removed++; }
            }
            return true;   // 找不到的条目跳过, 不当失败(可能对面已经删过了)
        }
        private JObject BuildSwimmerDeletePatch(List<SwimmerDeleteKey> keys, string clientName) {
            var p = NewPatch("SwimmerDelete", "", "", "", "", clientName);
            p["keys"] = JArray.FromObject((keys ?? new List<SwimmerDeleteKey>())
                .Select(k => new { bibNumber = k.BibNumber, name = k.Name, eventName = k.EventName }));
            return p;
        }
        private bool SendSwimmerDeletePatch(List<SwimmerDeleteKey> keys, out string error) {
            return SendPatchAndWait(BuildSwimmerDeletePatch(keys, ClientLabel()), out error);
        }
        private void BroadcastSwimmerDeletePatch(List<SwimmerDeleteKey> keys, string clientName, IWebSocketConnection except) {
            BroadcastPatch(BuildSwimmerDeletePatch(keys, clientName), except);
        }
        private bool ApplySwimmerDeletePatch(JObject msg, out string error) {
            var keys = new List<SwimmerDeleteKey>();
            var arr = msg["keys"] as JArray;
            if (arr != null) foreach (JObject o in arr)
                keys.Add(new SwimmerDeleteKey {
                    BibNumber = o["bibNumber"] != null ? o["bibNumber"].ToString() : "",
                    Name = o["name"] != null ? o["name"].ToString() : "",
                    EventName = o["eventName"] != null ? o["eventName"].ToString() : ""
                });
            int removed;
            return ApplySwimmerDeleteCore(keys, out removed, out error);
        }

        // ── 2026-09-20 【剩下那批"改完就推整包"逐处排查, 按数据归属建两类通用补丁】────
        //   排查发现两大类高频命中: (1) 新增运动员/接力队(接力队本质是几条 Swimmer 行,
        //   见 AddRelayCore)——网页报名/手工新增/CSV批量导入, 只【新增】行, 不碰任何
        //   已有记录; (2) 性别/赛次/组数/比赛项目/组别/号码段/参赛单位/工作人员/赛程
        //   这几张"整表编辑"配置——表不大(几条到几十条), 但只是这一张表, 不该带着
        //   运动员名单/成绩/记录这些完全没变的东西一起打包送出去。
        //   两类都是"本机已经直接改了内存(先改后报), 需要把这次改动告诉对端"这同一个
        //   收尾动作, 抽成一个共用函数, 不为每个 op 各写一份。

        /// <summary>本机刚做完一次新增/整表替换类的编辑(内存已经改完), 用补丁把这次改动
        /// 告诉对端, 不再为它推整包。编排端"先改后报"(问服务器, 被拒就留在本机, 等下次
        /// 联网/整体保存时自然补上——跟 Assign 补丁同一个道理); 服务器就地改完直接广播
        /// 给在线编排端(没有"先问"这一步, 本来就是权威)。</summary>
        private void FinishAndSyncPatch(JObject patch, string pushTopic) {
            SaveWithoutPush();
            try {
                if (IsScheduleEditorMode) {
                    string err;
                    if (!SendPatchAndWait(patch, out err))
                        AddLog(Loc.F("Str_Log_ChangeNotSyncedFmt", err));
                } else {
                    BroadcastPatch(patch, null);
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_SyncChangeFailedFmt", ex.Message)); }
            Broadcast();
            if (!string.IsNullOrEmpty(pushTopic)) PushDataChanged(pushTopic);
        }

        private JObject BuildSwimmerRowsAddPatch(List<Swimmer> rows, string clientName) {
            return BuildSwimmerRowsAddPatch(rows, null, null, clientName);
        }
        private JObject BuildSwimmerRowsAddPatch(List<Swimmer> rows, List<RelayTeam> teams, string clientName) {
            return BuildSwimmerRowsAddPatch(rows, teams, null, clientName);
        }
        /// <summary>teams 可选——接力队新增除了几条 Swimmer 行(代表+队员), 还有一份
        /// _relayTeams 里的 RelayTeam(棒次详情/生日等), 不带上它接收端的 _relayTeams
        /// 会跟 _swimmers 脱节。removeKeys 可选——"重新提交报名"先删旧记录再加新的,
        /// 跟 SwimmerDelete 补丁共用同一份 key 结构, 接收端按"先删后加"的顺序应用。</summary>
        private JObject BuildSwimmerRowsAddPatch(List<Swimmer> rows, List<RelayTeam> teams, List<SwimmerDeleteKey> removeKeys, string clientName) {
            var p = NewPatch("SwimmerRowsAdd", "", "", "", "", clientName);
            p["rows"] = JArray.FromObject(rows ?? new List<Swimmer>());
            if (teams != null && teams.Count > 0) p["teams"] = JArray.FromObject(teams);
            if (removeKeys != null && removeKeys.Count > 0)
                p["removeKeys"] = JArray.FromObject(removeKeys.Select(k => new { bibNumber = k.BibNumber, name = k.Name, eventName = k.EventName }));
            return p;
        }
        /// <summary>把新增的这几行(可能是单个运动员, 也可能是一支接力队的代表+队员条目,
        /// 也可能是一批CSV/网页报名)按 BibNumber 去重后追加——已经存在的跳过, 不当失败
        /// (可能是补丁被重放/两边都已经加过了)。</summary>
        private int ApplySwimmerRowsAddCore(List<Swimmer> rows) {
            int added = 0;
            foreach (var r in rows ?? new List<Swimmer>()) {
                if (r == null || string.IsNullOrEmpty(r.BibNumber)) continue;
                // 2026-09-20 去重键是(号码+项目), 不是号码——一人报几个项目, 每个项目一条
                // Swimmer 行, 号码相同但项目不同, 按号码单独去重会把后面几项全部当"已存在"漏掉。
                if (_swimmers.Any(s => s.BibNumber == r.BibNumber && s.EventName == r.EventName)) continue;
                _swimmers.Add(r);
                added++;
            }
            return added;
        }
        private int ApplyRelayTeamsAddCore(List<RelayTeam> teams) {
            int added = 0;
            foreach (var t in teams ?? new List<RelayTeam>()) {
                if (t == null || string.IsNullOrEmpty(t.TeamName)) continue;
                if (_relayTeams.Any(x => x.TeamName == t.TeamName && x.EventName == t.EventName && x.Gender == t.Gender)) continue;
                _relayTeams.Add(t);
                added++;
            }
            return added;
        }
        private bool ApplySwimmerRowsAddPatch(JObject msg, out string error) {
            error = null;
            var removeArr = msg["removeKeys"] as JArray;
            if (removeArr != null) {
                foreach (JObject o in removeArr) {
                    string bib = o["bibNumber"] != null ? o["bibNumber"].ToString() : "";
                    if (string.IsNullOrEmpty(bib)) continue;
                    foreach (var sw in _swimmers.Where(s => s.BibNumber == bib).ToList()) _swimmers.Remove(sw);
                }
            }
            var rows = new List<Swimmer>();
            var arr = msg["rows"] as JArray;
            if (arr != null) foreach (var t in arr) {
                try { var sw = t.ToObject<Swimmer>(); if (sw != null) rows.Add(sw); } catch { }
            }
            ApplySwimmerRowsAddCore(rows);
            var teamsArr = msg["teams"] as JArray;
            if (teamsArr != null) {
                var teams = new List<RelayTeam>();
                foreach (var t in teamsArr) {
                    try { var rt = t.ToObject<RelayTeam>(); if (rt != null) teams.Add(rt); } catch { }
                }
                ApplyRelayTeamsAddCore(teams);
            }
            return true;
        }

        // 2026-09-20 【用户明确要求: CSV/Excel 批量导入那几处也建个 upsert 型补丁】——
        //   这几处导入是"新增"和"更新已有记录"混在一起的批量操作(ImportOneSwimmerEvent
        //   就是典型: 身份证号+项目匹配上就地覆盖字段, 匹配不上才新建一行), SwimmerRowsAdd
        //   那套"按(号码+项目)去重、已存在就跳过"的语义在这里不对——已存在的那些行本该
        //   被"覆盖"而不是"跳过", 用 SwimmerRowsAdd 会把更新悄悄丢掉。这里单独建一条
        //   "upsert"语义的补丁: 优先按身份证号+项目匹配(跟 ImportOneSwimmerEvent 同一个
        //   优先级), 找不到再退回号码+项目匹配, 都没有就当新增——接收端和发起端用的是
        //   同一套匹配规则, 不会出现"发起端更新了第3行, 接收端却把第3行当新增"这种分叉。
        private JObject BuildSwimmerRowsUpsertPatch(List<Swimmer> rows, List<SwimmerDeleteKey> removeKeys, string clientName) {
            return BuildSwimmerRowsUpsertPatch(rows, null, removeKeys, clientName);
        }
        /// <summary>teams 可选——接力棒次表导入这类场景会就地改现有 RelayTeam 的 Legs,
        /// 同 SwimmerRowsAdd 的 teams: 按队名+项目+性别匹配上就整队替换, 匹配不上才新增。</summary>
        private JObject BuildSwimmerRowsUpsertPatch(List<Swimmer> rows, List<RelayTeam> teams, List<SwimmerDeleteKey> removeKeys, string clientName) {
            var p = NewPatch("SwimmerRowsUpsert", "", "", "", "", clientName);
            p["rows"] = JArray.FromObject(rows ?? new List<Swimmer>());
            if (teams != null && teams.Count > 0) p["teams"] = JArray.FromObject(teams);
            if (removeKeys != null && removeKeys.Count > 0)
                p["removeKeys"] = JArray.FromObject(removeKeys.Select(k => new { bibNumber = k.BibNumber, name = k.Name, eventName = k.EventName }));
            return p;
        }
        private void ApplyRelayTeamsUpsertCore(List<RelayTeam> teams) {
            foreach (var t in teams ?? new List<RelayTeam>()) {
                if (t == null || string.IsNullOrEmpty(t.TeamName)) continue;
                var existing = _relayTeams.FirstOrDefault(x => x.TeamName == t.TeamName && x.EventName == t.EventName && x.Gender == t.Gender);
                if (existing != null) {
                    // 2026-09-20 RelayTeam 自己也带着实时成绩/分段(FinalTime/LegSplits等)——
                    //   跟 ApplySwimmerRowsUpsertCore 同一道理, 正在比的这支队跳过不碰。
                    if (_meetDb.LiveActive && existing.EventName == _currentEvent && existing.Heat == _currentHeat) {
                        AddLog(Loc.F("Str_Log_BatchImportRelaySkippedFmt", existing.TeamName));
                        continue;
                    }
                    _relayTeams[_relayTeams.IndexOf(existing)] = t;
                } else {
                    _relayTeams.Add(t);
                }
            }
        }
        private void ApplySwimmerRowsUpsertCore(List<Swimmer> rows, out int added, out int updated) {
            added = 0; updated = 0;
            foreach (var r in rows ?? new List<Swimmer>()) {
                if (r == null) continue;
                Swimmer existing = null;
                if (!string.IsNullOrEmpty(r.IDNumber))
                    existing = _swimmers.FirstOrDefault(s => !string.IsNullOrEmpty(s.IDNumber) && s.IDNumber == r.IDNumber && s.EventName == r.EventName);
                if (existing == null && !string.IsNullOrEmpty(r.BibNumber))
                    existing = _swimmers.FirstOrDefault(s => s.BibNumber == r.BibNumber && s.EventName == r.EventName);
                if (existing != null) {
                    // 2026-09-20 【同一条命根子, 用户明确要求过】upsert 是整行覆盖(见下面注释),
                    //   对端那份没有正在计时这台机器刚触板出来的分段/成绩——如果这一行正好是
                    //   当前组临时数据库(current_heat.db)在用的那个人, 覆盖等于把刚打上去的
                    //   成绩冲掉。跟整包同一个道理: LiveActive 期间这一行原样不动、跳过,
                    //   等这一组确认/取消(临时数据库使命完成)后由下一次批量导入/补丁自然覆盖。
                    if (_meetDb.LiveActive && existing.EventName == _currentEvent
                        && (existing.GetAssignmentForStage(_currentStage) != null
                            ? existing.GetAssignmentForStage(_currentStage).Heat == _currentHeat
                            : existing.Heat == _currentHeat)) {
                        AddLog(Loc.F("Str_Log_BatchImportSwimmerSkippedFmt",
                            existing.Name, existing.BibNumber));
                        continue;
                    }
                    int idx = _swimmers.IndexOf(existing);
                    _swimmers[idx] = r;   // 整行换成对端那份最终值, 字段级 diff 没必要——本来就是"这一行现在长这样"
                    updated++;
                } else {
                    _swimmers.Add(r);
                    added++;
                }
            }
        }
        private bool ApplySwimmerRowsUpsertPatch(JObject msg, out string error) {
            error = null;
            var removeArr = msg["removeKeys"] as JArray;
            if (removeArr != null) {
                foreach (JObject o in removeArr) {
                    string bib = o["bibNumber"] != null ? o["bibNumber"].ToString() : "";
                    if (string.IsNullOrEmpty(bib)) continue;
                    foreach (var sw in _swimmers.Where(s => s.BibNumber == bib).ToList()) _swimmers.Remove(sw);
                }
            }
            var rows = new List<Swimmer>();
            var arr = msg["rows"] as JArray;
            if (arr != null) foreach (var t in arr) {
                try { var sw = t.ToObject<Swimmer>(); if (sw != null) rows.Add(sw); } catch { }
            }
            int added, updated;
            ApplySwimmerRowsUpsertCore(rows, out added, out updated);
            var teamsArr = msg["teams"] as JArray;
            if (teamsArr != null) {
                var teams = new List<RelayTeam>();
                foreach (var t in teamsArr) {
                    try { var rt = t.ToObject<RelayTeam>(); if (rt != null) teams.Add(rt); } catch { }
                }
                ApplyRelayTeamsUpsertCore(teams);
            }
            return true;
        }

        private JObject BuildListSetPatch(string target, JToken items, string clientName) {
            var p = NewPatch("ListSet", "", "", "", "", clientName);
            p["target"] = target ?? "";
            p["items"] = items ?? new JArray();
            return p;
        }
        /// <summary>target 认哪张表就整表替换哪张——这几张表都不大, 编辑本来就是"整表改完
        /// 再保存", 按条 diff 不划算, 直接送整张表比 Records 那种"高频、单条改"划算得多。</summary>
        private bool ApplyListSetCore(string target, JArray items, out string error) {
            error = null;
            items = items ?? new JArray();
            switch (target) {
                case "genders": _genders = items.Select(t => t.ToString()).ToList(); RefreshGendersPreview(); break;
                case "stages": _stages = items.Select(t => t.ToString()).ToList(); RefreshStagesPreview(); break;
                case "heatCounts": _heatCounts = items.Select(t => t.ToString()).ToList(); RefreshHeatCountsPreview(); break;
                case "events": _events = items.Select(t => t.ToString()).ToList(); RefreshEventsPreview(); break;
                case "ageGroups":
                    _ageGroups = items.Select(t => { try { return t.ToObject<AgeGroup>(); } catch { return null; } })
                        .Where(x => x != null).ToList();
                    AgeGroupRegistry.Set(_ageGroups);   // 2026-09-20 见 EditAgeGroupsListCore: 静态注册表也要跟着换
                    RefreshAgeGroupsPreview();
                    RefreshGendersPreview();
                    RefreshStagesPreview();
                    RefreshHeatCountsPreview();
                    break;
                case "bibRanges":
                    _bibRanges = items.Select(t => { try { return t.ToObject<BibRange>(); } catch { return null; } })
                        .Where(x => x != null).ToList();
                    break;
                case "units":
                    _units.Clear();
                    foreach (var t in items) { try { var u = t.ToObject<Unit>(); if (u != null) _units.Add(u); } catch { } }
                    RefreshUnitComboBox();
                    break;
                case "staff":
                    _staff.Clear();
                    foreach (var t in items) { try { var s = t.ToObject<StaffMember>(); if (s != null) _staff.Add(s); } catch { } }
                    break;
                case "schedule":
                    _schedule.Clear();
                    foreach (var t in items) { try { var s = t.ToObject<ScheduleItem>(); if (s != null) _schedule.Add(s); } catch { } }
                    try { BuildScheduleTree(); } catch { }
                    break;
                default: error = "不认识的列表类型: " + target; return false;
            }
            try { NotifyMetadataChanged(); } catch { }
            return true;
        }
        private bool ApplyListSetPatch(JObject msg, out string error) {
            string target = msg["target"] != null ? msg["target"].ToString() : "";
            var items = msg["items"] as JArray ?? new JArray();
            return ApplyListSetCore(target, items, out error);
        }

        /// <summary>收到别人发来的补丁, 照着改本机内存。</summary>
        private bool ApplyPatch(JObject msg, out string error) {
            error = null;
            string op = msg["op"] != null ? msg["op"].ToString() : "";
            if (op == "Assign") return ApplyAssignPatch(msg, out error);
            if (op == "Records") return ApplyRecordsPatch(msg, out error);
            if (op == "Unlock")  return ApplyUnlockPatch(msg, out error);
            if (op == "CheckIn") return ApplyCheckInPatch(msg, out error);
            if (op == "RelayEdit") return ApplyRelayEditPatch(msg, out error);
            if (op == "SwimmerEdit") return ApplySwimmerEditPatch(msg, out error);
            if (op == "RelayDelete") return ApplyRelayDeletePatch(msg, out error);
            if (op == "SwimmerDelete") return ApplySwimmerDeletePatch(msg, out error);
            if (op == "SwimmerRowsAdd") return ApplySwimmerRowsAddPatch(msg, out error);
            if (op == "SwimmerRowsUpsert") return ApplySwimmerRowsUpsertPatch(msg, out error);
            if (op == "ListSet") return ApplyListSetPatch(msg, out error);
            if (op != "MergeHeats") { error = "不认识的补丁类型: " + op; return false; }

            string ag = msg["ageGroup"] != null ? msg["ageGroup"].ToString() : "";
            string gd = msg["gender"] != null ? msg["gender"].ToString() : "";
            string ev = msg["eventName"] != null ? msg["eventName"].ToString() : "";
            string st = msg["stage"] != null ? msg["stage"].ToString() : "";
            string rs = msg["reason"] != null ? msg["reason"].ToString() : "";
            string who = msg["clientName"] != null ? msg["clientName"].ToString() : "远端";
            int src = 0, dst = 0;
            try { if (msg["srcHeat"] != null) src = (int)msg["srcHeat"]; } catch { }
            try { if (msg["dstHeat"] != null) dst = (int)msg["dstHeat"]; } catch { }
            List<string> moved;
            return ApplyMergeHeats(ag, gd, ev, st, src, dst, rs, who, out moved, out error);
        }

        /// <summary>主服务器: 收到编排端的增量补丁。比赛中照收 —— 挡的只有锁着的那一组。</summary>
        private void HandleEditorPatch(IWebSocketConnection sender, JObject msg) {
            string corrId = msg["corrId"] != null ? msg["corrId"].ToString() : "";
            string op = msg["op"] != null ? msg["op"].ToString() : "";
            bool ok = false;
            string reason = null;
            try { ok = ApplyPatch(msg, out reason); }
            catch (Exception ex) { ok = false; reason = ex.Message; }

            var rep = new JObject();
            rep["type"] = "EDITOR_PATCH_ACK";
            rep["corrId"] = corrId;
            rep["ok"] = ok;
            if (!ok) rep["reason"] = string.IsNullOrEmpty(reason) ? "未知原因" : reason;
            try { if (sender != null) sender.Send(rep.ToString(Formatting.None)); } catch { }

            if (ok) {
                // 转给其它在线编排端 —— 同样是补丁, 不是整包
                foreach (var sock in _editorSockets.ToList()) {
                    if (sock == sender) continue;
                    try { EnqueueToSocket(sock, msg.ToString(Formatting.None)); } catch { }
                }
                AddLog(Loc.F("Str_Log_EditorPatchAppliedFwdFmt", op));
                // 2026-09-18 【这里一直漏了写 meet.db】——"Assign"(手动分组/自动分组/临时加人/
                //   接力棒次等)这批补丁 2026-09-12 起改成"走补丁, 不推整包"以后, ApplyAssignPatch/
                //   ApplyMergeHeats 里只有并组那一条真的调了 _meetDb.MergeHeatsInDb, 其余全部只改了
                //   内存 _swimmers, 从没写过 meet.db。这几轮改的一大串"读 _meet 才对"的地方
                //   (GetHeat/GetRacingHeats/项目名次……)读到的还是编排端改之前那份旧分组——
                //   补丁本身在编排端/主服务器之间是同步的, 但那份"真身"库没跟上, 计时端拿到的
                //   道次/名单就可能是过时的。用户明确要求"修改并确认后立刻存进主服务器数据库
                //   并立刻轮询一次"——用已有的、结果保留式的 RebuildFromPackage(同 SyncToMeetDb
                //   加载整包时那一条, 已经是验证过的安全路径, 不新写一套 SQL), 防抖 2 秒
                //   (编辑经常是连续几条补丁一起来, 逐条重建太重), 写完再吭一声 DATA_CHANGED。
                // 2026-09-18 "Records" 补丁不用在这里(接收端)再同步一次——发送方
                //   (PushChangedRecords, 见其说明)已经直接经 _meet RPC 写过真身那份
                //   meet.db 了, 不依赖这条 WebSocket 补丁通道转不转发。这里只处理
                //   "Assign"/"MergeHeats" 这类 SelfCheck 认得出的赛程差异。
                if (op != "Records") ScheduleMeetDbSyncFromPatch();
            } else {
                AddLog(Loc.F("Str_Log_EditorPatchRejectedFmt", op, reason));
            }
        }

        // 2026-09-18 见 HandleEditorPatch 里的说明: 补丁只改了内存, 没写 meet.db,
        //   这里补一条防抖同步。防抖而不是逐条同步: 编排端一次编辑动作常常连着
        //   发好几条补丁(比如手动分组一次拖了好几个人), 逐条都重建库既没必要又费时间。
        private DispatcherTimer _meetDbSyncDebounceTimer;
        private void ScheduleMeetDbSyncFromPatch() {
            try {
                if (_meetDbSyncDebounceTimer == null) {
                    // 2026-10-08 用户明确要求缩短: 2 秒太长——分组表数据库现在是检录/
                    //   大屏/总排名等的直接显示来源(不再退回内存比较), 修改后数据库
                    //   多久才更新, 这些地方就有多久看不到最新分组。缩到 0.5 秒, 仍然
                    //   够合并同一次连续编辑动作(比如一次拖拽调整发出的好几条补丁),
                    //   但不会让看数据库的人等太久。
                    _meetDbSyncDebounceTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(0.5) };
                    _meetDbSyncDebounceTimer.Tick += MeetDbSyncDebounceTick;
                }
                _meetDbSyncDebounceTimer.Stop();
                _meetDbSyncDebounceTimer.Start();
            } catch { }
        }

        private void MeetDbSyncDebounceTick(object sender, EventArgs e) {
            _meetDbSyncDebounceTimer.Stop();
            try {
                // 跟 SyncToMeetDb(整包加载时那条)一个道理: 正在计时/成绩未确认时不动库,
                // 不然重建瞬间 _swimmers 整批换对象, 正在广播的当前组数据引用到旧对象。
                string why;
                if (IsPackageApplyBlocked(out why)) {
                    AddLog(Loc.F("Str_Log_EditorPatchDeferredMeetDbFmt", why));
                    return;
                }
                var package = BuildCurrentPackage();
                var chk = _meetDb.SelfCheck(package);
                if (chk.Diffs.Count == 0) return;   // 没差异, 不用白重建一次
                AddLog(Loc.F("Str_Log_EditorPatchMeetDbDiffFmt",
                    chk.Diffs.Count));
                if (_meetDb.RebuildFromPackage(package)) {
                    var again = _meetDb.SelfCheck(package);
                    AddLog(Loc.F("Str_Log_RebuildSelfCheckFmt", again.ToString()));
                    try { PushDataChanged("assign"); } catch { }   // 让挂着的其它客户端立刻多轮询一次
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_EditorPatchMeetDbFailedFmt", ex.Message)); }
        }

        // 本池可用泳道数
        // 2026-09-18 【0 是真泳道】——全运会式泳池是 0~9 共 10 道(见 MeetSchema.cs/
        //   LiveHeatSchema.cs 里"注意 0 是真泳道"那几处说明), 别处用 LaneNumbers
        //   全都不过滤 0(见那几十处 _poolConfig.LaneNumbers.ToList() 之类的直接用法),
        //   只有这两个函数原来写的是 l > 0——0~9 十道的池子会被这里少数成 9 道,
        //   0 道永远排不进"空道"候选, 白白浪费一条真实存在的道。改成 l >= 0
        //   跟其余几十处用法保持同一个口径。
        private int LaneCapacity() {
            if (_poolConfig != null && _poolConfig.LaneNumbers != null && _poolConfig.LaneNumbers.Count > 0)
                return _poolConfig.LaneNumbers.Count(l => l >= 0);
            return _poolConfig != null && _poolConfig.LaneCount > 0 ? _poolConfig.LaneCount : 8;
        }

        // 空着的泳道, 按"靠中间优先"排序 (4-5-3-6-2-7-1-8 那种顺序)
        private List<int> FreeLanesCenterFirst(HashSet<int> used) {
            var all = (_poolConfig != null && _poolConfig.LaneNumbers != null && _poolConfig.LaneNumbers.Count > 0)
                ? _poolConfig.LaneNumbers.Where(l => l >= 0).ToList()
                : Enumerable.Range(1, LaneCapacity()).ToList();
            double mid = (all.Count > 0) ? (all.Min() + all.Max()) / 2.0 : 0;
            return all.Where(l => !used.Contains(l))
                      .OrderBy(l => Math.Abs(l - mid))
                      .ThenBy(l => l)
                      .ToList();
        }

        private void PrevHeat_Click(object sender, RoutedEventArgs e) {
            // 2026-08-24 跳过已取消(并组)的组, 否则会停在一个空组上
            int target = NextLiveHeat(_currentHeat - 1, -1);
            if (target >= 1) {
                if (!CanLeaveCurrentHeat(target)) return;
                SetCurrentHeat(target);
            }
        }

        private void NextHeat_Click(object sender, RoutedEventArgs e) {
            // 2026-08-24 跳过已取消(并组)的组
            int target = NextLiveHeat(_currentHeat + 1, +1);
            if (target >= 1) {
                if (!CanLeaveCurrentHeat(target)) return;
                SetCurrentHeat(target);
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 赛事导航
        // ═══════════════════════════════════════════════════════════════
        private void SetCurrentEvent(string eventName) {
            // 支持两种格式：
            // 1. 带性别前缀："男子100米自由泳"（旧格式，兼容EXE端赛程树）
            // 2. 纯项目名："4x100米自由泳接力"（新格式，HTML端单独发SET_GENDER）
            // 2026-06-04 男女 并项 (e.g. "男女200米仰泳") 必须比 "男" / "女" 单字符分支更早匹配
            if (eventName.StartsWith("男女")) {
                _currentGender = "男女";
                _currentEvent = eventName.Substring(2);
            } else if (eventName.StartsWith("男子") || eventName.StartsWith("女子")) {
                _currentGender = eventName.Substring(0, 1);
                _currentEvent = eventName.Substring(2);
            } else if (eventName.StartsWith("混合子")) {
                _currentGender = "混合";
                _currentEvent = eventName.Substring(3);
            } else if (eventName.StartsWith("男") && !eventName.StartsWith("男子") && eventName.Length > 1 && !char.IsDigit(eventName[1])) {
                _currentGender = "男";
                _currentEvent = eventName.Substring(1);
            } else if (eventName.StartsWith("女") && !eventName.StartsWith("女子") && eventName.Length > 1 && !char.IsDigit(eventName[1])) {
                _currentGender = "女";
                _currentEvent = eventName.Substring(1);
            } else {
                // 纯项目名（性别已通过SET_GENDER设置）
                _currentEvent = eventName;
            }
            _isRelay = _currentEvent.Contains("接力");
            // 2026-06-04 顺序统一: 性别 组别 项目
            CurrentEventText.Text = Loc.GenderDisplay(_currentGender) + (string.IsNullOrEmpty(_currentAgeGroup) ? " " : (" [" + _currentAgeGroup + "] ")) + _currentEvent;
            UpdateRecordDisplay();
            UpdateLaneStatusDisplay();   // 主服务器本机泳道占用显示
            // 选项目时把比赛配置 / 发令点同步给硬件（出发台仍由 0x21 Ready 控制是否打开）：
            //   1) Set_MatchEvent (0x43) — 总圈数、左右预期触板次数、泳道开关位图
            //   2) Set_SwStartingPosition (0x10 0x42 [pos]) — 发令点
            //   3) Set_ArmDelay_Time (0x41) — d8 的 SP50M 位 (50米发令在终点对面) ← 2026-05-26 修复:
            //      之前不发 0x41, 硬件用上一帧的 sp50m=0 当 50m 项目处理, 0x21 Ready 时打开的出发台
            //      落在终点端而非对面, 后续触板/盲表方向都跟着错位.
            if (_timingBridge != null && _timingBridge.IsConnected) {
                try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_SetMatchEventSyncFailedFmt", ex.Message)); }
                try { SendStartPositionToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_StartPosSyncFailedFmt", ex.Message)); }
                try { SendTimingSettingsToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ParamsSyncFailedSp50mFmt", ex.Message)); }
            }
        }

        private void SetCurrentStage(string stage) {
            _currentStage = stage;
            CurrentStageText.Text = stage;

            // 计算该阶段总组数
            // 2026-08-21 两处修正：
            //   1) 性别改用 GenderMatchEx（原来的 StartsWith 会把混合接力算进男子项）；
            //   2) 补上组别过滤 —— 原来少年组和青年组的同名项目被算到一起，
            //      大屏"第X/Y组"的 Y 会偏大（本届 45 项里有 23 项受影响）。
            bool hasMixedStage = HasExplicitMixedEntry(_currentEvent, _currentAgeGroup);
            _totalHeats = _swimmers.Count(s =>
                s.EventName == _currentEvent &&
                GenderMatchEx(s.Gender, _currentGender, hasMixedStage) &&
                MatchesAgeGroup(s, _currentAgeGroup) &&
                s.CurrentStage == _currentStage
            );
            if (_totalHeats > 0 && _poolConfig.LaneCount > 0) {
                _totalHeats = (int)Math.Ceiling((double)_totalHeats / _poolConfig.LaneCount);
            }
            // 2026-08-24 赛程项里若已登记组数, 以它为准(手工分组比按人数估算准);
            //   再扣掉被取消(并组)的组 —— 否则大屏"第1/2组"里那个 2 是个已经不存在的组。
            var schedNow = FindScheduleItem(_currentAgeGroup, _currentGender, _currentEvent, _currentStage);
            if (schedNow != null && schedNow.HeatCount > 0) {
                int liveHeats = schedNow.HeatCount;
                if (schedNow.CancelledHeats != null) liveHeats -= schedNow.CancelledHeats.Count;
                if (liveHeats > 0) _totalHeats = liveHeats;
            }
        }

        /// <summary>
        /// 根据比赛项目自动调整发令位置：
        /// 50米项目（单程）→ 发令在终点对面端
        /// 其他项目（多程）→ 发令在终点同侧端
        /// </summary>
        private void AutoAdjustStartPosition() {
            string finish = _laneCloseSettings.FinishPosition;
            if (string.IsNullOrEmpty(finish)) finish = _laneCloseSettings.StartPosition;
            bool is50m = !string.IsNullOrEmpty(_currentEvent) && _currentEvent.StartsWith("50米");
            string newStart;
            if (is50m) {
                // 50米：出发在终点对面
                newStart = finish == "left" ? "right" : "left";
            } else {
                // 其他项目：出发在终点同侧
                newStart = finish;
            }
            if (_laneCloseSettings.StartPosition != newStart) {
                _laneCloseSettings.StartPosition = newStart;
                AddLog(Loc.F("Str_Log_StartPosAutoSwitchFmt",
                    newStart == "left" ? "左端" : "右端", is50m ? "50米单程" : "多程", finish == "left" ? "左" : "右"));
            }
        }

        // 2026-09-21 【用户订正】上一版去翻成绩表猜"有没有真实计时数据", 想复杂了——
        //   用户点破: 检录只是看人到没到(到=正常, 没到=备注 DNS), 这跟"未开始"/"已检录"/
        //   "进行中"/"已确认"是同一条状态线上的事, 压根不该去看成绩表。一组的生命周期
        //   就是: 未开始/已检录(_raceState==Waiting) → 按"准备就绪"进入进行中
        //   (_raceState==Ready/Racing/已完赛未确认) → 确认成绩(_resultConfirmed==true)。
        //   能不能离开这组, 直接问这条状态线, 不问成绩表。
        private bool CurrentHeatInProgress() {
            if (_resultConfirmed) return false;
            return _raceState == RaceState.Ready || _raceState == RaceState.Racing || _raceState == RaceState.Finished;
        }

        // 服务端门禁（处理来自 HTML/EXE 远程台的 SET_* 指令）：
        // - 比赛准备/进行中：拒
        // - 比赛已结束但成绩还未确认：拒
        // 拒绝时记日志（HTML/EXE 也会同步看到现有 currentXxx 不变）
        private bool IsHeatSwitchBlocked(string actionLabel) {
            if (string.IsNullOrEmpty(_currentEvent) || _currentHeat <= 0) return false;
            if (CurrentHeatInProgress()) {
                AddLog((_raceState == RaceState.Ready || _raceState == RaceState.Racing ? Loc.T("Str_Frag_CannotWhileRacing") : Loc.T("Str_Frag_CannotUnconfirmed")) + actionLabel);
                return true;
            }
            return false;
        }

        // 当前组"进行中"(已按准备就绪/正在比/已完赛但未确认)时禁止切组：
        // 返回 true 表示放行，false 表示拦截。
        // （未开始/已检录 —— 还没按准备就绪 —— 和 已确认 都允许切换）
        private bool CanLeaveCurrentHeat(int targetHeat) {
            if (string.IsNullOrEmpty(_currentEvent) || _currentHeat <= 0) return true;
            if (targetHeat == _currentHeat) return true;
            if (!CurrentHeatInProgress()) return true;
            AppMessageBox.Show(
                Loc.F("Str_Msg_CannotLeaveHeatFmt", Loc.GenderDisplay(_currentGender), _currentEvent, _currentHeat),
                Loc.T("Str_MsgTitle_ActionBlocked"), MessageBoxButton.OK, MessageBoxImage.Warning);
            AddLog(Loc.T("Str_Log_HeatSwitchBlockedUnconfirmed"));
            return false;
        }

        private void SetCurrentHeat(int heat) {
            _currentHeat = heat;
            CurrentHeatText.Text = Loc.F("Str_Fmt_HeatOfTotal", heat, _totalHeats);
            // 2026-06-04 顺序统一: 性别 组别 项目 赛次 第N组
            if (PoolCurrentEventText != null)
                PoolCurrentEventText.Text = Loc.F("Str_Fmt_PoolEventHeatFmt",
                    Loc.GenderDisplay(_currentGender),
                    string.IsNullOrEmpty(_currentAgeGroup) ? "" : ("[" + _currentAgeGroup + "] "),
                    _currentEvent, _currentStage, heat);

            // 判断该组是否已有确认成绩；若是则保留 Finished 状态，避免覆盖已确认的成绩显示
            bool heatAlreadyConfirmed = !string.IsNullOrEmpty(_currentEvent) && _currentHeat > 0
                && IsHeatConfirmed(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat);

            _raceState = heatAlreadyConfirmed ? RaceState.Finished : RaceState.Waiting;
            _resultConfirmed = heatAlreadyConfirmed;
            _laneSplitCount.Clear();
            _laneSplitShowTime.Clear();
            _laneReactionLastValue.Clear();
            _laneReactionShowTime.Clear();
            _firstPlaceFinishTime = "";
            _firstPlaceShowStart = DateTime.MinValue;
            _lastLeaderSplitCount = 0;   // 2026-05-26 切组时 1 名 split-count 跟踪同步清零
            // 切换组次 = 复位计时器
            _runningTime = 0;
            _raceStartTime = DateTime.MinValue;
            _raceTimer.Stop();
            _countdownTimer.Stop();
            if (RunningTimeText != null) RunningTimeText.Text = "0.00";

            // 根据项目自动调整发令位置（50米项目切换到对面端）
            AutoAdjustStartPosition();
            UpdateRaceStateDisplay();

            // 复位所有泳道设备状态。注意：选项目/切组次时出发台必须保持【关闭】，
            // 等操作员按"就绪"按键确认后才打开 — 因此 ResetForNewRace 之后立即把
            // 两端出发台都置为 Closed（覆盖 ResetForNewRace 自动把发令端置 Open 的行为）。
            foreach (var state in _laneDeviceStates) {
                state.ResetForNewRace(_laneCloseSettings.StartPosition);
                state.LeftStartBlockStatus = DeviceStatus.Closed;
                state.RightStartBlockStatus = DeviceStatus.Closed;
                //2026-05-31 SB 业务两侧都 Closed, 硬件颜色也跟着清 0 (= 灰), 覆盖 ResetForNewRace 里发令侧 SB Hw=1
                state.HwLeftStartBlockColor = 0;
                state.HwRightStartBlockColor = 0;
            }
            // 若该组已确认成绩：把每位完赛运动员对应泳道的 IsFinished 置回 true，
            // 让广播/UI 把对应运动员显示为已完赛（保留 finalTime 显示）
            if (heatAlreadyConfirmed) {
                foreach (var sw in GetCurrentHeatSwimmers()) {
                    var sa = sw.GetAssignmentForStage(_currentStage);
                    int swLane = sa != null ? sa.Lane : sw.Lane;
                    var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == swLane);
                    if (ls == null) continue;
                    var rr = sw.Results.FirstOrDefault(rx => rx.Stage == _currentStage && rx.Heat == _currentHeat);
                    if (rr != null && rr.FinalTime > 0) {
                        ls.IsFinished = true;
                    }
                }
            }

            UpdateLaneStatusDisplay();
            UpdateRecordDisplay();
            Broadcast();
            // 组次变更 → 重新同步 0x43（不同组的空泳道位图不同）+ 发令点 + 0x41(含 sp50m)
            // 2026-05-26 补 SendTimingSettingsToHardware: AutoAdjustStartPosition 把 StartPosition 切到对面后,
            //   sp50m 位 (= StartPosition != FinishPosition) 必须通过 0x41 帧告诉硬件, 否则 50m 出发台开错端.
            if (_timingBridge != null && _timingBridge.IsConnected) {
                try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_SetMatchEventSyncFailedFmt", ex.Message)); }
                try { SendStartPositionToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_StartPosSyncFailedFmt", ex.Message)); }
                try { SendTimingSettingsToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ParamsSyncFailedSp50mFmt", ex.Message)); }
            }
        }

        private void ScheduleTree_Selected(object sender, RoutedPropertyChangedEventArgs<object> e) {
            var item = ScheduleTree.SelectedItem as TreeViewItem;
            if (item == null || item.Tag == null) return;

            string tag = item.Tag.ToString();
            // 比赛进行中禁止切换项目/组次（防止误操作导致参数复位）
            if ((_raceState == RaceState.Ready || _raceState == RaceState.Racing) &&
                (tag.StartsWith("heat:") || tag.StartsWith("event:"))) {
                AppMessageBox.Show(
                    Loc.T("Str_Msg_CannotReselectEvent"),
                    Loc.T("Str_MsgTitle_ActionBlocked"), MessageBoxButton.OK, MessageBoxImage.Warning);
                AddLog(Loc.T("Str_Log_CannotSwitchEventWhileRacing"));
                return;
            }
            // 2026-09-16 只有【已确认】(真点过"确认本组成绩")的组才锁 —— 标 [已完赛] 但没点
            //   过确认按钮的组不会走到这条 done: 分支(见 BuildScheduleTree), 能正常点开重装,
            //   点完再补"确认本组成绩"。灰色可见但不能选择开始比赛。
            if (tag.StartsWith("done:")) {
                AddLog(Loc.T("Str_Log_CannotReselectConfirmed"));
                return;
            }
            // 格式: "heat:组别|性别|项目|阶段|组次"  （组别可空）
            if (tag.StartsWith("heat:")) {
                string[] parts = tag.Substring(5).Split('|');
                if (parts.Length >= 5) {
                    int heat;
                    if (!int.TryParse(parts[4], out heat)) return;
                    // 当前组未确认成绩时禁止切换
                    if (!CanLeaveCurrentHeat(heat)) return;
                    _currentAgeGroup = parts[0];
                    _currentGender = parts[1];
                    _currentEvent = parts[2];
                    _currentStage = parts[3];
                    _isRelay = _currentEvent.Contains("接力");

                    _totalHeats = CountHeatsForEvent(_currentAgeGroup, _currentGender, _currentEvent, _currentStage);
                    // 2026-06-04 顺序统一: 性别 组别 项目
                    CurrentEventText.Text = Loc.GenderDisplay(_currentGender) + (string.IsNullOrEmpty(_currentAgeGroup) ? " " : (" [" + _currentAgeGroup + "] ")) + _currentEvent;
                    CurrentStageText.Text = _currentStage;
                    SetCurrentHeat(heat);
                }
            }
        }

        private int CountHeatsForEvent(string gender, string eventName, string stage) {
            return CountHeatsForEvent("", gender, eventName, stage);
        }

        private int CountHeatsForEvent(string ageGroup, string gender, string eventName, string stage) {
            // 优先用赛程项的 HeatCount（手动分组后更准确）
            var sched = _schedule.FirstOrDefault(s =>
                (s.AgeGroup ?? "") == (ageGroup ?? "") &&
                SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == stage);
            if (sched != null && sched.HeatCount > 0) return sched.HeatCount;

            bool hasMixedCnt = HasExplicitMixedEntry(eventName, ageGroup);
            var q = _swimmers.Where(s =>
                s.EventName == eventName &&
                GenderMatchEx(s.Gender, gender, hasMixedCnt) &&
                MatchesAgeGroup(s, ageGroup) &&
                s.CurrentStage == stage &&
                s.Heat > 0);
            return q.Any() ? q.Max(s => s.Heat) : 1;
        }

        private void BuildScheduleTree() {
            ScheduleTree.Items.Clear();
            var sessions = _schedule.GroupBy(s => s.SessionNumber).OrderBy(g => g.Key);

            // 2026-06-05 性能: 1122 人 × 78 项 时 BuildScheduleTree 每次 BuildScheduleTree O(N×M),
            //   预构建 swimmer by EventName 索引, IsHeatConfirmedFast / IsStageAllConfirmedFast 用此索引
            var swIdx = new Dictionary<string, List<Swimmer>>(StringComparer.Ordinal);
            foreach (var s in _swimmers) {
                if (string.IsNullOrEmpty(s.EventName)) continue;
                List<Swimmer> lst;
                if (!swIdx.TryGetValue(s.EventName, out lst)) { lst = new List<Swimmer>(); swIdx[s.EventName] = lst; }
                lst.Add(s);
            }

            foreach (var session in sessions) {
                bool sessionAllDone = true;
                var sessionItem = new TreeViewItem {
                    Header = session.First().SessionName ?? string.Format("第{0}场", session.Key)
                };

                int evSeq = 0;
                foreach (var ev in session) {
                    evSeq++;
                    int seqNum = (ev.EvNum > 0) ? ev.EvNum : evSeq;   // 2026-06-12 比赛项目序号: 有项次用项次, 否则按场顺序号(重置1)
                    string ag = ev.AgeGroup ?? "";
                    string header = string.Format("{0}. ", seqNum)
                                  + (string.IsNullOrEmpty(ag) ? "" : ("[" + ag + "] "))
                                  + string.Format("{0} {1} {2}", ev.Gender, ev.EventName, ev.Stage);
                    // 2026-09-16 拆成两条: “已完赛”(数据齐, 仍可点开重装)和“已确认”(真点过
                    //   确认按钮, 锁定不让再点开) —— 用户提出的区分, 解开了下面这个死结:
                    //   中途关程序漏点"确认本组成绩", 数据其实全收到了, 旧逻辑一条推断就把
                    //   这组标成"已完赛"锁死, 连点开补确认的入口都没有。
                    bool allHeatsTrulyConfirmed = IsStageAllTrulyConfirmed(ag, ev.Gender, ev.EventName, ev.Stage);
                    if (!allHeatsTrulyConfirmed) sessionAllDone = false;

                    int heatCount = ev.HeatCount > 0 ? ev.HeatCount : 1;
                    // 2026-08-24 本项目被取消的组
                    var cancelLabels = new Dictionary<int, string>();
                    if (ev.CancelledHeats != null) {
                        foreach (var cc in ev.CancelledHeats) {
                            cancelLabels[cc.Heat] = cc.MergedInto > 0
                                ? string.Format("已取消 并入第{0}组", cc.MergedInto)
                                : (string.IsNullOrEmpty(cc.Reason) ? "已取消" : "已取消 " + cc.Reason);
                        }
                    }
                    // Tag 扩展：event:AgeGroup|Gender|Event|Stage  或  heat/done:AgeGroup|Gender|Event|Stage|Heat
                    var eventItem = new TreeViewItem {
                        Tag = string.Format("event:{0}|{1}|{2}|{3}", ag, ev.Gender, ev.EventName, ev.Stage),
                        IsExpanded = !allHeatsTrulyConfirmed
                    };

                    // 2026-09-21 这棵树("比赛控制" Tab 专用, RaceControlTab)用的是【数字状态表】
                    //   (HeatDisplayStatus, 见 Swimmer.cs)——跟 RebuildNavTree 那三棵共用同一张
                    //   表和同一套颜色, 这里只是数据来源不同(这棵走的是性能优化过的 Fast 索引,
                    //   不查"进行中", 所以不会出现 Running)。已检录同一张 _checkedInHeats 表。
                    var heatStatuses = new List<HeatDisplayStatus>();
                    for (int h = 1; h <= heatCount; h++) {
                        // 2026-09-16 heatConfirmed(数据齐, 展示用) 和 heatTrulyConfirmed(真确认过,
                        //   决定 Tag 是不是 "done:"、能不能点开) 分开 —— 只有后者才锁, 前者只是
                        //   换个颜色提醒操作员"这组数据齐了、该点确认了", 点得开。
                        bool heatConfirmed = IsHeatConfirmedFast(ag, ev.Gender, ev.EventName, ev.Stage, h, swIdx);
                        bool heatTrulyConfirmed = IsHeatTrulyConfirmed(ag, ev.Gender, ev.EventName, ev.Stage, h);
                        bool cancelled = cancelLabels.ContainsKey(h);
                        HeatDisplayStatus hStatus =
                            cancelled ? HeatDisplayStatus.Cancelled :
                            heatTrulyConfirmed ? HeatDisplayStatus.Confirmed :
                            heatConfirmed ? HeatDisplayStatus.Done :
                            _checkedInHeats.Contains(ConfirmedHeatKey(ag, ev.Gender ?? "", ev.EventName ?? "", ev.Stage ?? "", h)) ? HeatDisplayStatus.CheckedIn :
                            HeatDisplayStatus.Pending;
                        heatStatuses.Add(hStatus);
                        var heatItem = new TreeViewItem {
                            Tag = string.Format("{0}:{1}|{2}|{3}|{4}|{5}", heatTrulyConfirmed ? "done" : "heat", ag, ev.Gender, ev.EventName, ev.Stage, h),
                            // 2026-08-24 已取消(并组)的组要标出来, 不然是个点进去空白的组——保留
                            //   "并入第X组"这层细节, 不走通用的 StatusLabel(那边只会说"[已取消]")。
                            Header = cancelled
                                ? string.Format("第{0}组 [{1}]", h, cancelLabels[h])
                                : (hStatus == HeatDisplayStatus.Pending ? string.Format("第{0}组 (共{1}组)", h, heatCount) : string.Format("第{0}组 {1}", h, StatusLabel(hStatus))),
                            Foreground = StatusBrush(hStatus)
                        };
                        eventItem.Items.Add(heatItem);
                    }
                    // 2026-09-21 已取消(并组)的组不算数——同 IsStageAllTrulyConfirmed 的口径,
                    //   全场都在等的那个Loc.T("Str_MsgTitle_Confirm")状态只看还"活着"的组次, 被并走的空号不该
                    //   拖着整个项目显示不出"已确认"。
                    var liveHeatStatuses = heatStatuses.Where(s => s != HeatDisplayStatus.Cancelled).ToList();
                    HeatDisplayStatus evStatus = liveHeatStatuses.Count > 0 ? AggregateStatus(liveHeatStatuses) : HeatDisplayStatus.Cancelled;
                    eventItem.Header = (evStatus == HeatDisplayStatus.Pending || evStatus == HeatDisplayStatus.Cancelled) ? header : (header + " " + StatusLabel(evStatus));
                    eventItem.Foreground = StatusBrush(evStatus);
                    sessionItem.Items.Add(eventItem);
                }

                // 场内所有项目都完赛时收起，否则展开
                sessionItem.IsExpanded = !sessionAllDone;
                if (sessionAllDone) {
                    sessionItem.Header = (session.First().SessionName ?? string.Format("第{0}场", session.Key)) + " " + StatusLabel(HeatDisplayStatus.Done);
                    sessionItem.Foreground = new SolidColorBrush(Colors.Gray);
                }

                ScheduleTree.Items.Add(sessionItem);
            }
            RebuildScheduleGroupedView();

            // 2026-05-24 同步刷新赛程管理+成绩与排名两个 Tab 的左侧 3 级导航
            RebuildBothNavTrees();
            // 2026-05-25 阶段列刷新：日程生成后 → 按 _schedule 填回每位运动员的 CurrentStage
            RefreshSwimmerStages();
        }

        // 2026-05-25 按当前 _schedule 给每个 swimmer 填阶段:
        //   有对应 (event+gender+ageGroup) 的 ScheduleItem → 取项目最早赛次 (预赛 > 半决赛 > 决赛)
        //   没匹配的 ScheduleItem → 阶段清空（新报名/未生成日程时显示为空）
        //   已晋级到非预赛的 swimmer (StageAssignments 含 半决赛/决赛) → 不回退
        private void RefreshSwimmerStages() {
            if (_schedule == null) return;
            // 2026-06-05 性能: 1122 人 × 78 项 → 87K 次 schedule 扫. 预构建 schedule by EventName 索引
            var schedIdx = new Dictionary<string, List<ScheduleItem>>(StringComparer.Ordinal);
            foreach (var s in _schedule) {
                if (string.IsNullOrEmpty(s.EventName)) continue;
                List<ScheduleItem> lst;
                if (!schedIdx.TryGetValue(s.EventName, out lst)) { lst = new List<ScheduleItem>(); schedIdx[s.EventName] = lst; }
                lst.Add(s);
            }
            foreach (var sw in _swimmers) {
                if (string.IsNullOrEmpty(sw.EventName)) { sw.CurrentStage = ""; continue; }
                if (sw.Notes != null && sw.Notes.StartsWith("接力队员")) continue;   // 队员条目跟随队伍
                if (sw.StageAssignments != null) {
                    bool hasAdvanced = false;
                    foreach (var k in sw.StageAssignments.Keys) {
                        if (k == "半决赛" || k == "决赛" || k == "次复赛" || k == "B组决赛") { hasAdvanced = true; break; }
                    }
                    if (hasAdvanced) continue;
                }
                List<ScheduleItem> evSched;
                if (!schedIdx.TryGetValue(sw.EventName, out evSched)) { sw.CurrentStage = ""; continue; }
                var stages = new List<string>();
                foreach (var s in evSched) {
                    if (!SgMatch(sw.Gender, s.Gender)) continue;
                    if (!MatchesAgeGroup(sw, s.AgeGroup ?? "")) continue;
                    if (!stages.Contains(s.Stage ?? "")) stages.Add(s.Stage ?? "");
                }
                if (stages.Count == 0) { sw.CurrentStage = ""; continue; }
                string firstStage;
                if (stages.Contains("预赛")) firstStage = "预赛";
                else if (stages.Contains("次复赛")) firstStage = "次复赛";
                else if (stages.Contains("半决赛")) firstStage = "半决赛";
                else if (stages.Contains("决赛")) firstStage = "决赛";
                else firstStage = stages[0] ?? "";
                sw.CurrentStage = firstStage;
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 2026-05-24 左侧赛程导航 (3 级: 项目 → 组别 → 该场开始时间)
        // 用于 赛程管理 / 成绩与排名 两个 Tab
        // ═══════════════════════════════════════════════════════════════
        // 当前 status 筛选 (per-tree)
        private string _navSchedFilter = "all";
        private string _navResultFilter = "all";
        // 2026-09-21 "出场编排微调" Tab 也要有同一棵赛程导航树。
        private string _navEditFilter = "all";

        private void RebuildBothNavTrees() {
            if (NavSchedTree != null) RebuildNavTree(NavSchedTree, NavSchedSearchBox != null ? NavSchedSearchBox.Text : "", _navSchedFilter);
            if (NavResultTree != null) RebuildNavTree(NavResultTree, NavResultSearchBox != null ? NavResultSearchBox.Text : "", _navResultFilter);
            if (NavEditTree != null) RebuildNavTree(NavEditTree, NavEditSearchBox != null ? NavEditSearchBox.Text : "", _navEditFilter);
        }

        // 2026-09-16 一个 leaf 节点的状态：未开始 / 进行中 / 已完赛(数据齐但未点确认) /
        //   已确认(真点过"确认本组成绩") / 已取消。
        //   跟"比赛控制"赛程树那次修改同一个道理拆开: 这里原来的 "done" 是【两条路径合一】——
        //   IsHeatConfirmed(内部也带着"全员有成绩就算完赛"那条兜底推断)先判一次, 判不出来
        //   下面又用同一条推断再判一次, 于是"数据齐但没点确认"和"真点过确认"在这棵树上
        //   一直是同一个状态、同一个"[已结束]"标签, 分不出来。用户点名要求这几棵"赛程导航"
        //   树都按"比赛控制"那次改法统一: 数据齐≠锁定, 只有真点过确认才算锁定。
        // 2026-09-18 RebuildNavTree 每次重建整棵树前刷新一次(见该函数开头), HeatStatus
        //   对每个 leaf 节点只做一次成员判断, 不再各自去问库——一棵树几十上百个组, 不能
        //   每判一组的状态就发一次 RPC。
        private HashSet<string> _racingHeatKeys;
        private static string RacingHeatKey(string ageGroup, string gender, string eventName, string stage, int heat) {
            return (ageGroup ?? "") + "|" + (gender ?? "") + "|" + (eventName ?? "") + "|" + (stage ?? "") + "|" + heat;
        }

        // 2026-09-21 用户明确要求: 组次状态标注做成"数字 -> 状态"对照表, 这样以后整个
        //   系统从中文转英文时只用改这一张表。唯一的中文文本来源, 其它地方一律只传
        //   HeatDisplayStatus 这个数字, 不再比较/拼接字符串。
        // 2026-09-21 【中文/English 第五阶段】这张表原来是死的静态字典, 现在真的要转英文了——
        //   改成从 Loc.T() 查表(键 Str_HeatStatus_*, 见 Localization.cs), 中文/English 两条
        //   跟着"设置"页那个按钮活切换。BuildScheduleTree() 在 LanguageToggle_Click 里补了一次
        //   调用(见该处说明), 已经渲染好的树节点才会跟着重画成新语言, 不然这些标签是烤进
        //   TreeViewItem.Header 字符串里的, 不会像 DynamicResource 那样自己活刷新。

        private string HeatStatus(string ageGroup, string gender, string eventName, string stage, int heat) {
            if (IsHeatTrulyConfirmed(ageGroup, gender, eventName, stage, heat)) return "confirmed";
            // 2026-10-08 用户明确要求: 判断"这组有谁"一律调分组表唯一入口 GetHeatEntries()
            // (先查 heat_entries 数据库, 查不到才退回内存 StageAssignment)——不再在这里
            // 自己另开一份"谁在这组"的判定逻辑, 两处各算一次正是用户点名的根因。
            var inHeat = GetHeatEntries(ageGroup, gender, eventName, stage, heat);
            if (inHeat.Count == 0) return "pending";
            // 全部 DNS/DNF/DSQ → 已取消
            bool allCancelled = inHeat.All(s => s.Status == "DNS" || s.Status == "DNF" || s.Status == "DSQ" || s.Status == "SCR");
            if (allCancelled) return "cancelled";
            int withResult = inHeat.Count(s => s.Results.Any(r => r.Stage == stage && r.Heat == heat && r.FinalTime > 0));
            if (withResult == 0) {
                // 2026-09-18 本机"当前选中的组"是纯本地状态, 从没同步给别的机器——用户
                //   实拍到: 从"准备就绪"到出成绩这一整段, 计时端/主服务器/编排端的赛程
                //   导航树全都停在【未开始】, 没有一处显示过【正在计时】, 根子就在这句
                //   只认本机 _currentXxx。heats.state='racing' 这张实时状态一直有(开组
                //   那一刻就写库了), 换成读它才是跨机器都认的同一份真相。
                if (ageGroup == _currentAgeGroup && gender == _currentGender && eventName == _currentEvent && stage == _currentStage && heat == _currentHeat) return "running";
                if (_racingHeatKeys != null && _racingHeatKeys.Contains(RacingHeatKey(ageGroup, gender, eventName, stage, heat))) return "running";
                // 2026-09-21 用户明确要求: 检录只是"到没到场", 跟"未开始/已检录/进行中/
                //   已确认"是同一条状态线上的事——还没按准备就绪(走不到上面 running 那两
                //   条分支)但检录台已经交过表的组, 标"已检录", 不是笼统的"未开始"。
                if (_checkedInHeats.Contains(ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat))) return "checkedIn";
                return "pending";
            }
            if (withResult < inHeat.Count) return "running";
            return "done";   // 全有成绩, 但还没真正点过"确认本组成绩"
        }

        // 字符串状态码(pending/checkedIn/running/done/confirmed/cancelled) → 数字对照表。
        // HeatStatus() 内部逻辑较复杂(读 _swimmers/_racingHeatKeys/_checkedInHeats), 保留
        // 字符串返回值不动, 这里只做"翻译成数字"这一层, 数字表本身是唯一权威。
        private static HeatDisplayStatus HeatStatusCode(string s) {
            switch (s) {
                case "checkedIn": return HeatDisplayStatus.CheckedIn;
                case "running": return HeatDisplayStatus.Running;
                case "done": return HeatDisplayStatus.Done;
                case "confirmed": return HeatDisplayStatus.Confirmed;
                case "cancelled": return HeatDisplayStatus.Cancelled;
                default: return HeatDisplayStatus.Pending;
            }
        }

        // 节点级聚合：所有子节点里最需要操作员关注的那个状态
        // (进行中 > 已检录 > 未开始 > 已完赛/已确认(全体一致才算) > 已取消)
        // 2026-09-16 confirmed 和 done 分开聚合: 子节点全部真"已确认"才算父节点"已确认",
        //   混着数据齐但未确认的, 父节点只能算"已完赛"(还没能收尾)。
        private static HeatDisplayStatus AggregateStatus(IEnumerable<HeatDisplayStatus> children) {
            var list = children.ToList();
            if (list.Count == 0) return HeatDisplayStatus.Pending;
            if (list.Contains(HeatDisplayStatus.Running)) return HeatDisplayStatus.Running;
            if (list.Contains(HeatDisplayStatus.CheckedIn)) return HeatDisplayStatus.CheckedIn;
            if (list.Contains(HeatDisplayStatus.Pending)) return HeatDisplayStatus.Pending;
            if (list.All(x => x == HeatDisplayStatus.Confirmed)) return HeatDisplayStatus.Confirmed;
            if (list.All(x => x == HeatDisplayStatus.Done || x == HeatDisplayStatus.Confirmed)) return HeatDisplayStatus.Done;
            if (list.All(x => x == HeatDisplayStatus.Cancelled)) return HeatDisplayStatus.Cancelled;
            return list[0];
        }

        private static string HeatStatusText(HeatDisplayStatus s) {
            switch (s) {
                case HeatDisplayStatus.CheckedIn: return Loc.T("Str_HeatStatus_CheckedIn");
                case HeatDisplayStatus.Running:   return Loc.T("Str_HeatStatus_Running");
                case HeatDisplayStatus.Done:      return Loc.T("Str_HeatStatus_Done");
                case HeatDisplayStatus.Confirmed: return Loc.T("Str_HeatStatus_Confirmed");
                case HeatDisplayStatus.Cancelled: return Loc.T("Str_HeatStatus_Cancelled");
                default: return Loc.T("Str_HeatStatus_Pending");
            }
        }
        private static string StatusLabel(HeatDisplayStatus s) { return "[" + HeatStatusText(s) + "]"; }
        private static string StatusLabel(string s) { return StatusLabel(HeatStatusCode(s)); }
        private static SolidColorBrush StatusBrush(HeatDisplayStatus s) {
            switch (s) {
                case HeatDisplayStatus.Confirmed: return new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E"));
                case HeatDisplayStatus.Done: return new SolidColorBrush((Color)ColorConverter.ConvertFromString("#CA8A04"));
                case HeatDisplayStatus.Running: return new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6"));
                case HeatDisplayStatus.CheckedIn: return new SolidColorBrush((Color)ColorConverter.ConvertFromString("#06B6D4"));
                case HeatDisplayStatus.Cancelled: return new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444"));
                default: return new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8"));
            }
        }
        private static SolidColorBrush StatusBrush(string s) { return StatusBrush(HeatStatusCode(s)); }
        // HeatStatusCode 的反函数——RebuildNavTree 内部大量用 pending/checkedIn/running/...
        // 这几个既有字符串键做 == 比较, 保持不动; 聚合改走数字表算完再翻回字符串。
        private static string HeatStatusString(HeatDisplayStatus s) {
            switch (s) {
                case HeatDisplayStatus.CheckedIn: return "checkedIn";
                case HeatDisplayStatus.Running: return "running";
                case HeatDisplayStatus.Done: return "done";
                case HeatDisplayStatus.Confirmed: return "confirmed";
                case HeatDisplayStatus.Cancelled: return "cancelled";
                default: return "pending";
            }
        }
        private static string AggregateStatus(IEnumerable<string> children) {
            return HeatStatusString(AggregateStatus(children.Select(HeatStatusCode)));
        }

        // Tag 格式: "nav:AgeGroup|Gender|Event|Stage|Heat"  (level-3 = heat 节点)
        // 上级节点 Tag 用 "navL2:Event|AgeGroup" 和 "navL1:Event"
        private void RebuildNavTree(TreeView tv, string searchText, string statusFilter) {
            tv.Items.Clear();
            string q = (searchText ?? "").Trim().ToLower();
            // 2026-09-18 每次重建树只问一次"全场哪组正在计时"(正常情况下最多一行), 下面
            //   逐组判状态时直接查这个内存集合, 不再每判一组的状态就发一次 RPC。
            //   查询失败(联机没连上/库暂时不可用)不影响树的其余部分, 静默退回"只信本机"。
            try {
                var racingKeys = new HashSet<string>();
                foreach (var r in _meetDb.GetRacingHeats() ?? new List<string[]>()) {
                    if (r == null || r.Length < 5) continue;
                    int hh;
                    if (!int.TryParse(r[4], out hh)) continue;
                    racingKeys.Add(RacingHeatKey(r[0], r[1], r[2], r[3], hh));
                }
                _racingHeatKeys = racingKeys;
            } catch { _racingHeatKeys = null; }
            // 拆出每个 heat 的状态(用于 leaf 节点+聚合)
            // 数据来源: _schedule + ScheduleItem.HeatCount
            // 2026-06-12 改为 场次(场) → 项目(序号) → 组 结构 (同 比赛控制 ScheduleTree),
            //   保留 状态筛选(statusFilter) / 搜索高亮(q) / 状态标签颜色 / leaf nav: Tag (供选中处理)
            var sessions = _schedule.GroupBy(s => s.SessionNumber).OrderBy(g => g.Key);
            foreach (var session in sessions) {
                var sessChildren = new List<TreeViewItem>();
                var sessChildStatuses = new List<string>();
                int evSeq = 0;
                foreach (var ev in session) {
                    evSeq++;
                    int seqNum = (ev.EvNum > 0) ? ev.EvNum : evSeq;   // 项目序号: 有项次用项次, 否则按场顺序号
                    string ag = ev.AgeGroup ?? "";
                    int hc = ev.HeatCount > 0 ? ev.HeatCount : 1;
                    var heatItems = new List<TreeViewItem>();
                    var heatStatuses = new List<string>();
                    for (int h = 1; h <= hc; h++) {
                        // 2026-09-18 用户实测: 并组/取消组之后, "比赛控制"这棵赛程导航树
                        //   没有更新——这棵树从来没真的查过 IsHeatCancelled/GetCancelledHeat,
                        //   一直是把 1..HeatCount 每个组次号都当成正常在比的组画出来, 并组
                        //   过的那个组次号照样显示"[未开始]"。跟 BuildScheduleTree("赛程管理"
                        //   Tab 自己那棵树)保持同一个待遇: 不隐藏(组次号本来就是保留空号,
                        //   点开也该看得到"这号去哪了"), 但要标成"[已取消 并入第X组]"。
                        var cancelled = GetCancelledHeat(ag, ev.Gender ?? "", ev.EventName ?? "", ev.Stage ?? "", h);
                        string status;
                        string heatLabel;
                        if (cancelled != null) {
                            status = "cancelled";
                            string cancelTag = cancelled.MergedInto > 0
                                ? "已取消 并入第" + cancelled.MergedInto + "组"
                                : (string.IsNullOrEmpty(cancelled.Reason) ? "已取消" : "已取消 " + cancelled.Reason);
                            heatLabel = string.Format("{0} 第{1}组 [{2}]", ev.Stage ?? "", h, cancelTag).Trim();
                        } else {
                            status = HeatStatus(ag, ev.Gender ?? "", ev.EventName ?? "", ev.Stage ?? "", h);
                            // 2026-06-19 去掉 ev.Date + ev.Time: 父节点 "第X场（YYYY-MM-DD 上午）" 已含日期+时段,
                            //   子节点 第X组 再拼一次重复. 只保留 阶段 + 组次 + 状态.
                            // 2026-09-21 "已检录"现在是 HeatStatus() 数字表里的一档状态(见
                            //   HeatDisplayStatus.CheckedIn), 不再是外挂的字符串拼接——
                            //   StatusLabel(status) 已经会打印"[已检录]"。
                            heatLabel = string.Format("{0} 第{1}组 {2}", ev.Stage ?? "", h, StatusLabel(status)).Trim();
                        }
                        // 2026-09-16 筛选按钮上"已结束"(Tag="done")一直是粗筛——不管这组是数据齐
                        //   (done)还是真点过确认(confirmed), 都算"比完了", 所以这里 done 桶要把
                        //   confirmed 也接进来, 不然点"已结束"筛选按钮, 已确认的组全部消失。
                        // 2026-09-21 同理, "未开始"(Tag="pending")桶也把"已检录"(checkedIn)接进来——
                        //   检录只是"到没到场", 没按准备就绪之前都算没开赛。
                        bool passFilter = statusFilter == "all" || status == statusFilter
                                        || (statusFilter == "done" && status == "confirmed")
                                        || (statusFilter == "pending" && status == "checkedIn");
                        if (!passFilter) continue;
                        var l3 = new TreeViewItem {
                            Header = heatLabel,
                            Foreground = StatusBrush(status),
                            Tag = string.Format("nav:{0}|{1}|{2}|{3}|{4}", ag, ev.Gender, ev.EventName, ev.Stage, h)
                        };
                        ApplySearchHighlight(l3, heatLabel, q);
                        heatItems.Add(l3);
                        heatStatuses.Add(status);
                    }
                    if (heatItems.Count == 0) continue;
                    string evStatus = AggregateStatus(heatStatuses);
                    string evHeader = string.Format("{0}. ", seqNum)
                                    + (string.IsNullOrEmpty(ag) ? "" : ("[" + ag + "] "))
                                    + string.Format("{0} {1} {2} {3}", ev.Gender, ev.EventName, ev.Stage, StatusLabel(evStatus));
                    var evNode = new TreeViewItem {
                        Header = evHeader,
                        Foreground = StatusBrush(evStatus),
                        Tag = string.Format("event:{0}|{1}|{2}|{3}", ag, ev.Gender, ev.EventName, ev.Stage),
                        IsExpanded = (!string.IsNullOrEmpty(q) && (((ev.EventName ?? "").ToLower().Contains(q)) || ag.ToLower().Contains(q))) || evStatus == "running"
                    };
                    foreach (var c in heatItems) evNode.Items.Add(c);
                    ApplySearchHighlight(evNode, evHeader, q);
                    sessChildren.Add(evNode);
                    sessChildStatuses.Add(evStatus);
                }
                if (sessChildren.Count == 0) continue;
                string sessStatus = AggregateStatus(sessChildStatuses);
                string sessName = session.First().SessionName ?? string.Format("第{0}场", session.Key);
                var sessNode = new TreeViewItem {
                    Header = string.Format("{0} {1}", sessName, StatusLabel(sessStatus)),
                    Foreground = StatusBrush(sessStatus),
                    FontWeight = FontWeights.Bold,
                    Tag = "navSession:" + session.Key,
                    IsExpanded = !string.IsNullOrEmpty(q) || sessStatus == "running"
                };
                foreach (var c in sessChildren) sessNode.Items.Add(c);
                tv.Items.Add(sessNode);
            }

            if (tv.Items.Count == 0) {
                tv.Items.Add(new TreeViewItem {
                    Header = string.IsNullOrEmpty(q) ? "(无符合筛选的赛程节点)" : "(搜索无匹配)",
                    Foreground = new SolidColorBrush(Colors.Gray)
                });
            }
        }

        // 搜索匹配高亮: 命中时把 Header 包装成 TextBlock + 黄色背景
        private static void ApplySearchHighlight(TreeViewItem item, string text, string q) {
            if (string.IsNullOrEmpty(q)) return;
            if (text == null || !text.ToLower().Contains(q)) return;
            item.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#FEF3C7"));
        }

        // FINA 项目顺序：50 自/100 自/...
        private static int EventDisplayOrder(string ev) {
            if (string.IsNullOrEmpty(ev)) return 99999;
            int strokeOrder = 99;
            if (ev.Contains("自由泳")) strokeOrder = 1;
            else if (ev.Contains("仰泳")) strokeOrder = 2;
            else if (ev.Contains("蛙泳")) strokeOrder = 3;
            else if (ev.Contains("蝶泳")) strokeOrder = 4;
            else if (ev.Contains("混合泳") || ev.Contains("个人混")) strokeOrder = 5;
            if (ev.Contains("接力")) strokeOrder = 6;
            int dist = 0;
            foreach (var d in new[] { 50, 100, 200, 400, 800, 1500 }) {
                if (ev.Contains(d + "米")) { dist = d; break; }
            }
            return strokeOrder * 10000 + dist;
        }
        private static int StageOrder(string st) {
            if (st == "预赛") return 1;
            if (st == "次复赛") return 2;
            if (st == "半决赛") return 3;
            if (st == "决赛") return 4;
            if (st == "B组决赛") return 5;
            return 9;
        }

