            RebuildNavTree(NavEditTree, NavEditSearchBox.Text, _navEditFilter);
        }
        private void NavEditTree_Selected(object sender, RoutedPropertyChangedEventArgs<object> e) {
            var item = e.NewValue as TreeViewItem;
            if (item == null || !(item.Tag is string)) return;
            string tag = item.Tag as string;
            string ag, gd, ev, st; int heat = 0;
            if (tag.StartsWith("event:")) {
                var p = tag.Substring(6).Split('|');
                if (p.Length < 4) return;
                ag = p[0]; gd = p[1]; ev = p[2]; st = p[3];
            } else if (tag.StartsWith("nav:")) {
                var p = tag.Substring(4).Split('|');
                if (p.Length < 5) return;
                ag = p[0]; gd = p[1]; ev = p[2]; st = p[3];
                int.TryParse(p[4], out heat);
            } else return;   // 场次节点: 不动

            if (heat > 0) {
                string hs = HeatStatus(ag, gd, ev, st, heat);
                if (hs == "running" || hs == "confirmed") {
                    AppMessageBox.Show(Loc.F("Str_Msg_CannotFineTuneFmt",
                        ev, heat, hs == "running" ? Loc.T("Str_Frag_HeatRunning") : Loc.T("Str_Frag_HeatConfirmed")),
                        Loc.T("Str_MsgTitle_CannotFineTune"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
            }

            _editUpdating = true;
            try {
                SetComboValue(EditAgeGroupCombo, string.IsNullOrEmpty(ag) ? Loc.T("Str_Common_All") : ag);
                SetComboValue(EditGenderCombo, gd);
                SetComboValue(EditStageCombo, st);
            } finally { _editUpdating = false; }
            UpdateEditHeatCombo();   // 按新的 组别/性别/赛次 重建 项目/组次 下拉(内部已调用一次 RefreshEditPreview)
            SetComboValue(EditEventCombo, ev);
            SetComboValue(EditHeatCombo, heat > 0 ? ("第" + heat + "组") : Loc.T("Str_Common_All"));
            try { RefreshEditPreview(); } catch { }
        }

        private static void SetComboValue(System.Windows.Controls.ComboBox cb, string val) {
            if (cb == null) return;
            for (int i = 0; i < cb.Items.Count; i++) {
                var it = cb.Items[i];
                string content = it is ComboBoxItem ? ((ComboBoxItem)it).Content as string : it as string;
                if ((content ?? "") == (val ?? "")) { cb.SelectedIndex = i; return; }
            }
        }
        private void ScrollScheduleGroupedToHeat(string tagPayload) {
            // 简单兜底：暂时只把焦点切到对应那张子表的位置（数据已绑定在 ScheduleGroupedPanel 内）
            // 后续可以增加更精细的高亮
            if (ScheduleGroupedPanel == null) return;
            try {
                // 找标题含 EventName 的子元素并滚动可见
                var parts = tagPayload.Split('|');
                if (parts.Length < 3) return;
                string ev = parts[2];
                foreach (var child in ScheduleGroupedPanel.Children) {
                    var fe = child as FrameworkElement;
                    if (fe == null) continue;
                    if (fe is TextBlock && (((TextBlock)fe).Text ?? "").Contains(ev)) {
                        fe.BringIntoView();
                        return;
                    }
                }
            } catch { }
        }

        private class NavLeaf {
            public string EventName, AgeGroup, Gender, Stage, Date, Time, SessionName, Status;
            public int Heat;
        }

        /// <summary>
        /// 检查某组比赛是否已有成绩（所有运动员都有成绩或标记为DNS/DNF/DSQ）
        /// </summary>
        private bool IsHeatConfirmed(string gender, string eventName, string stage, int heat) {
            return IsHeatConfirmed("", gender, eventName, stage, heat);
        }

        private bool IsHeatConfirmed(string ageGroup, string gender, string eventName, string stage, int heat) {
            return IsHeatConfirmedFast(ageGroup, gender, eventName, stage, heat, null);
        }

        // 2026-06-05 性能优化重载: idx 是预构建的 swimmer-by-EventName 索引 (传 null 时回退到 _swimmers 全扫)
        private bool IsHeatConfirmedFast(string ageGroup, string gender, string eventName, string stage, int heat,
                                          Dictionary<string, List<Swimmer>> idx) {
            if (_confirmedHeats.Contains(ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat))) return true;
            // 2026-09-13 显式解锁过的组: 底下那条"全员有成绩就算完赛"的推断一律不算数,
            //   否则刚解完锁, 推断立刻又把它说成已完赛。(正常情况这张表是空的, 零开销)
            if (_unlockedHeats.Count > 0 && IsHeatUnlocked(ageGroup, gender, eventName, stage, heat)) return false;

            bool isRelay = eventName.Contains("接力");
            IEnumerable<Swimmer> source;
            if (idx != null) {
                List<Swimmer> lst;
                if (!idx.TryGetValue(eventName, out lst) || lst == null) return false;
                source = lst;
            } else {
                source = _swimmers;
            }
            var heatSwimmers = source.Where(s =>
                SgMatch(s.Gender, gender) && s.EventName == eventName &&
                MatchesAgeGroup(s, ageGroup) &&
                !(isRelay && s.Notes != null && s.Notes.StartsWith("接力队员"))
            ).ToList();

            // 2026-10-08 用户明确要求: 判断"这组有谁"一律以分组表为准, 不再退回顶层字段猜。
            // 这里特意不改成调 GetHeatEntries()(它会先查 heat_entries 数据库)——本方法
            // 是赛程导航树状态刷新的性能特化版(swIdx 预索引 + 对全部项目全部组逐组调用,
            // 一次刷新可能跑上百次), 真去查库会把这条热路径变成"每组一次 SQL"。
            // StageAssignment 本身已经是权威记录(20 处分组/改组路径全都会写它), 保留
            // "sa != null && sa.Heat == heat"这条已修好的严格判定就足够正确, 只是不再
            // 多绕一次数据库——GetHeatEntries 侧的 DB 校验已经覆盖了显示/排名这些真正
            // 需要防"内存脏了也不知道"的地方。
            var inHeat = new List<Swimmer>();
            foreach (var s in heatSwimmers) {
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat == heat) inHeat.Add(s);
            }

            if (inHeat.Count == 0) return false;

            foreach (var sw in inHeat) {
                if (sw.Status == "DNS" || sw.Status == "DNF" || sw.Status == "DSQ") continue;
                // 必须按 (Stage, Heat) 精确查找该组的成绩，否则当运动员在多个组（如晋级前后）有成绩时
                // GetResultForStage 仅返回首条会误判（如检查第2组时拿到第1组成绩）
                var r = sw.Results.FirstOrDefault(rx => rx.Stage == stage && rx.Heat == heat);
                if (r == null || r.FinalTime <= 0) return false;
            }
            return true;
        }

        /// <summary>
        /// 检查某项目某赛次是否全部组都已完赛
        /// </summary>
        private bool IsStageAllConfirmed(string gender, string eventName, string stage) {
            return IsStageAllConfirmed("", gender, eventName, stage);
        }

        private bool IsStageAllConfirmed(string ageGroup, string gender, string eventName, string stage) {
            return IsStageAllConfirmedFast(ageGroup, gender, eventName, stage, null);
        }

        // 2026-06-05 性能优化重载: idx 是预构建的 swimmer-by-EventName 索引
        private bool IsStageAllConfirmedFast(string ageGroup, string gender, string eventName, string stage,
                                              Dictionary<string, List<Swimmer>> idx) {
            var schedItem = _schedule.FirstOrDefault(s =>
                (s.AgeGroup ?? "") == (ageGroup ?? "") &&
                SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == stage);
            int heatCount = schedItem != null && schedItem.HeatCount > 0 ? schedItem.HeatCount : 0;
            if (heatCount == 0) return false;
            // 2026-08-24 被取消(并组)的组永远不会有人去确认成绩。
            //   不跳过的话该项目永远不显示"已完赛", 颁奖/总排名等依赖"全部确认"的流程会卡住。
            var cancelled = (schedItem != null && schedItem.CancelledHeats != null)
                ? schedItem.CancelledHeats : new List<CancelledHeat>();
            int live = 0;
            for (int h = 1; h <= heatCount; h++) {
                if (cancelled.Any(x => x.Heat == h)) continue;
                live++;
                if (!IsHeatConfirmedFast(ageGroup, gender, eventName, stage, h, idx)) return false;
            }
            return live > 0;
        }

        /// <summary>
        /// 2026-09-16 【严格版, 只认真正点过"确认本组成绩"】——不看 IsHeatConfirmedFast 那条
        /// "全员都有成绩就算完赛"的兜底推断。
        ///
        /// 为什么要分出这一份: 赛程树"能不能点开重新装载这一组"原来直接用 IsHeatConfirmedFast
        /// 的结果(→"done:"标签, 点了什么都不做)。程序中途被关掉、操作员没来得及点"确认本组
        /// 成绩", 但硬件数据其实已经全部收到 —— 那条兜底推断照样判定"已完赛", 这一组就被
        /// 锁死在赛程树里点不开, 连重新装载、补点"确认本组成绩"的入口都没有, 成了死结
        /// (用户实拍到)。
        /// "能不能点开"只应该看【真的确认过没有】, "看起来数据是不是齐了"只是个展示上的
        /// 提示, 不该拿来当锁的依据 —— 这就是用户提出的"已完赛"(数据齐, 能再点开)和
        /// "已确认"(真锁定, 点不开)该分成两个状态。
        /// </summary>
        private bool IsHeatTrulyConfirmed(string ageGroup, string gender, string eventName, string stage, int heat) {
            return _confirmedHeats.Contains(ConfirmedHeatKey(ageGroup, gender, eventName, stage, heat));
        }

        private bool IsStageAllTrulyConfirmed(string ageGroup, string gender, string eventName, string stage) {
            var schedItem = _schedule.FirstOrDefault(s =>
                (s.AgeGroup ?? "") == (ageGroup ?? "") &&
                SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == stage);
            int heatCount = schedItem != null && schedItem.HeatCount > 0 ? schedItem.HeatCount : 0;
            if (heatCount == 0) return false;
            var cancelled = (schedItem != null && schedItem.CancelledHeats != null)
                ? schedItem.CancelledHeats : new List<CancelledHeat>();
            int live = 0;
            for (int h = 1; h <= heatCount; h++) {
                if (cancelled.Any(x => x.Heat == h)) continue;
                live++;
                if (!IsHeatTrulyConfirmed(ageGroup, gender, eventName, stage, h)) return false;
            }
            return live > 0;
        }

