        private void RenderPoolHeader() {
            if (PoolHeader == null) return;
            PoolHeader.Children.Clear();
            PoolHeader.ColumnDefinitions.Clear();

            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(32) });   // 道次
            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(8) });    // 左发令
            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(264) });  // 左设备（+24，容纳圈数 spinner）
            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); // 姓名+进度
            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(264) });  // 右设备（+24，容纳圈数 spinner）
            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(8) });    // 右发令
            PoolHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(284) });  // 成绩信息 (反应时/盲表 列加宽到 90 容纳 1:25:42.78)

            Action<int, string, double> addLabel = (col, text, width) => {
                var tb = new TextBlock { Text = text, Width = width, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12, TextAlignment = TextAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                Grid.SetColumn(tb, col);
                PoolHeader.Children.Add(tb);
            };
            // 2026-10-10 英文模式下这几处窄列表头原来硬编码中文, 从未随语言切换——用户要求
            //   缩写英文(RT/TP/MB1.../St/Lap), 字不要多, 列宽不变。
            bool enLbl = Loc.CurrentLanguage == Loc.En;
            addLabel(0, Loc.T("Str_Col_Lane"), 32);

            // 左发令标志
            var leftHdrInd = new Border { Width = 8, CornerRadius = new CornerRadius(2), Background = _laneCloseSettings.StartPosition == "left" ? new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")) : Brushes.Transparent, Margin = new Thickness(0, 4, 0, 4) };
            Grid.SetColumn(leftHdrInd, 1); PoolHeader.Children.Add(leftHdrInd);

            // 左端表头与右端对称：[T] 盲3 盲2 盲1 出发 触板 圈
            // 2026-06-16 列宽与下方指示灯一致 + 5 个设备标签都两行显示
            // 2026-06-16 加 Margin(2,0,0,0) 跟下方 leftDev 对齐. 圈 50→44 = leftRemainText(26)+leftSpinner(18)
            // 当 LeftBlindWatchCount<3 时，最外侧的 盲3/盲2 标签使用 Hidden 保留位置
            var leftLabels = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(2, 0, 0, 0) };
            string[] leftLabelDefs = enLbl
                ? new[] { "[T]:80", "MB3:22", "MB2:22", "MB1:22", "St:26", "TP:11", "Lap:44" }
                : new[] { "[T]:80", "盲\n3:22", "盲\n2:22", "盲\n1:22", "出\n发:26", "触\n板:11", "圈:44" };
            int leftBwc = _laneCloseSettings.LeftBlindWatchCount;
            for (int li = 0; li < leftLabelDefs.Length; li++) {
                string[] p = leftLabelDefs[li].Split(':');
                var tb = new TextBlock { Text = p[0], Width = double.Parse(p[1]), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12, TextAlignment = TextAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                // 设备标签 (含 \n 换行符) 统一两行显示, 字号小一号
                if (p[0].Contains("\n")) { tb.TextWrapping = TextWrapping.Wrap; tb.FontSize = 10; tb.LineHeight = 13; }
                // li=1 是 盲3（数量>=3 才显示），li=2 是 盲2（数量>=2），li=3 是 盲1（数量>=1）
                if (li == 1) tb.Visibility = leftBwc >= 3 ? Visibility.Visible : Visibility.Hidden;
                else if (li == 2) tb.Visibility = leftBwc >= 2 ? Visibility.Visible : Visibility.Hidden;
                else if (li == 3) tb.Visibility = leftBwc >= 1 ? Visibility.Visible : Visibility.Hidden;
                leftLabels.Children.Add(tb);
            }
            Grid.SetColumn(leftLabels, 2); PoolHeader.Children.Add(leftLabels);

            var midLabels = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(6, 0, 6, 0) };
            midLabels.Children.Add(new TextBlock { Text = Loc.T("Str_Col_NameTeam"), Width = 120, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12, VerticalAlignment = VerticalAlignment.Center });
            midLabels.Children.Add(new TextBlock { Text = Loc.T("Str_Col_DirectionProgress"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12, VerticalAlignment = VerticalAlignment.Center });
            Grid.SetColumn(midLabels, 3); PoolHeader.Children.Add(midLabels);

            // 右端表头：圈 触板 出发 盲1 盲2 盲3 [T]（盲表数量减少时盲2/盲3 用 Hidden 保留位置）
            // 2026-06-16 列宽与下方指示灯一致 + 5 个设备标签都两行显示
            // 2026-06-16 圈 50→44 = rightSpinner(18)+rightRemainText(26), 跟下方 rightDev 对齐
            var rightLabels = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
            string[] rightLabelDefs = enLbl
                ? new[] { "Lap:44", "TP:11", "St:26", "MB1:22", "MB2:22", "MB3:22", "[T]:80" }
                : new[] { "圈:44", "触\n板:11", "出\n发:26", "盲\n1:22", "盲\n2:22", "盲\n3:22", "[T]:80" };
            int rightBwc = _laneCloseSettings.RightBlindWatchCount;
            for (int ri = 0; ri < rightLabelDefs.Length; ri++) {
                string[] p = rightLabelDefs[ri].Split(':');
                var tb = new TextBlock { Text = p[0], Width = double.Parse(p[1]), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12, TextAlignment = TextAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                // 设备标签 (含 \n 换行符) 统一两行显示, 字号小一号
                if (p[0].Contains("\n")) { tb.TextWrapping = TextWrapping.Wrap; tb.FontSize = 10; tb.LineHeight = 13; }
                // ri=3 是 盲1（数量>=1），ri=4 是 盲2（数量>=2），ri=5 是 盲3（数量>=3）
                if (ri == 3) tb.Visibility = rightBwc >= 1 ? Visibility.Visible : Visibility.Hidden;
                else if (ri == 4) tb.Visibility = rightBwc >= 2 ? Visibility.Visible : Visibility.Hidden;
                else if (ri == 5) tb.Visibility = rightBwc >= 3 ? Visibility.Visible : Visibility.Hidden;
                rightLabels.Children.Add(tb);
            }
            Grid.SetColumn(rightLabels, 4); PoolHeader.Children.Add(rightLabels);

            // 右发令标志
            var rightHdrInd = new Border { Width = 8, CornerRadius = new CornerRadius(2), Background = _laneCloseSettings.StartPosition == "right" ? new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")) : Brushes.Transparent, Margin = new Thickness(0, 4, 0, 4) };
            Grid.SetColumn(rightHdrInd, 5); PoolHeader.Children.Add(rightHdrInd);

            var infoLabels = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
            // 2026-06-16 "反应" 列改成两行 "反应/盲表" 跟下方上下两行对齐. 宽度 55→90 容纳 "1:25:42.78"
            string[] infoLabelDefs = enLbl
                ? new[] { "RT/MB:90", "Result:110", "Rank:44", "Note:40" }
                : new[] { "反应\n盲表:90", "成绩:110", "名次:44", "备注:40" };
            foreach (string s in infoLabelDefs) {
                string[] p = s.Split(':');
                var tb = new TextBlock { Text = p[0], Width = double.Parse(p[1]), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12, TextAlignment = TextAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                if (p[0].Contains("\n")) { tb.TextWrapping = TextWrapping.Wrap; tb.FontSize = 10; tb.LineHeight = 13; }
                infoLabels.Children.Add(tb);
            }
            Grid.SetColumn(infoLabels, 6); PoolHeader.Children.Add(infoLabels);
        }

        // 画刷缓存：避免每次tick重复创建
        private static readonly SolidColorBrush _brushGreen = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E"));
        private static readonly SolidColorBrush _brushRed = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444"));
        private static readonly SolidColorBrush _brushAmber = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B"));
        private static readonly SolidColorBrush _brushSlate = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569"));
        private static readonly SolidColorBrush _brushBlack = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#000000"));
        //2026-05-31 暗红 = 硬件 Delay_Color RGB565 0xD000 (= R=26/31, G=0, B=0 ≈ #D00000)
        private static readonly SolidColorBrush _brushDarkRed = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#D00000"));
        private static readonly SolidColorBrush _brushDark = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"));
        private static readonly SolidColorBrush _brushBlue = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6"));
        private static readonly SolidColorBrush _brushSilver = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#C0C0C0"));
        private static readonly SolidColorBrush _brushBronze = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#CD7F32"));
        private static readonly SolidColorBrush _brushGray = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B"));
        private static readonly SolidColorBrush _brushMutedText = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8"));

        // 2026-06-06 P1-D: 热路径 (RefreshLaneRows 每 100ms × 8 道) 反复 new Thickness 是 Gen0 压力源.
        //   复用 immutable Thickness 单例.
        private static readonly Thickness _thickness0 = new Thickness(0);
        private static readonly Thickness _thickness2 = new Thickness(2);

        private static SolidColorBrush GetDeviceBrush(DeviceStatus status) {
            switch (status) {
                case DeviceStatus.Open: return _brushGreen;
                case DeviceStatus.Broken: return _brushBlack;    // 黑色 = 损坏（与活的红色 Touched 区分）
                case DeviceStatus.Touched: return _brushRed;     // 红色 = 已触板（窗口期内）
                case DeviceStatus.FalseStart: return _brushAmber;
                default: return _brushSlate;
            }
        }

        // 2026-05-13 设备圆点统一样式：NotInstalled → 透明填充 + 灰色虚线描边（"未安装"的虚线框），
        // 其它状态 → 正常实色填充无描边。比赛控制行刷新时调用，所有 RightDots / LeftDots 都用它。
        private static readonly DoubleCollection _dotDashArray = new DoubleCollection(new double[] { 2, 1.5 });
        // 2026-06-16 dot shape: Ellipse → Shape 基类, 支持 Rectangle (出发台正方形 + 触板长条)
        private static void StyleDot(Shape dot, DeviceStatus status) {
            if (dot == null) return;
            if (status == DeviceStatus.NotInstalled) {
                dot.Fill = Brushes.Transparent;
                dot.Stroke = _brushSlate;
                dot.StrokeThickness = 1.5;
                dot.StrokeDashArray = _dotDashArray;
            } else {
                dot.Fill = GetDeviceBrush(status);
                dot.Stroke = null;
                dot.StrokeThickness = 0;
            }
        }

        //2026-05-31 硬件颜色 (= 0x50/0x51/0x52 协议 newState 0-5) → Brush 映射, 跟硬件 swimplay.c LCD 颜色一致:
        //   swimplay.c 第 305-313: Close_Color=GRAY(灰), Open_TP_Color=YELLOW, Open_SB_Color=GREEN, Open_MB_Color=YELLOW,
        //                          Delay_Color=0xD000(暗红), Bad_Color=BLACK, UnInstall_Color=BLACK (2025-1-6), Valid_Color=RED
        //   newState: 0=Close 灰 / 1=Open (TP/MB 黄, SB 绿) / 2=Delay 暗红 / 3=Bad 黑 / 4=UnInstall 黑 / 5=Pressed 红
        //   PC 端业务字段优先于硬件颜色 (保留现有视觉, 业务驱动):
        //     - 业务 NotInstalled → 透明虚线 (PC 特殊视觉, 跟硬件黑色 UnInstall_Color 区分)
        //     - 业务 Broken → 黑
        //     - 业务 Touched → 红 (= 触板红色窗口期, 跟之前 GetDeviceBrush 一致)
        //     - 业务 FalseStart → 黄
        //     - 否则 → 用 Hw*Color 渲染 (= 反映硬件 LCD 实时颜色, 含 SB Open=绿 vs TP/MB Open=黄 的区分)
        //   注: 硬件 newState=5 (Pressed 红色按下) 待 swimplay.c Process_*StateChange 扩展 KeyState
        //       综合后才会真上报; 当前未上报时 PC UI 触板红色仍由业务 Touched 触发, 视觉跟之前一致.
        private enum DotDeviceType { Tp, Sb, Mb }
        private void StyleDotMixed(Shape dot, byte hwColor, DeviceStatus businessStatus, DotDeviceType deviceType) {
            if (dot == null) return;
            // 业务字段优先
            if (businessStatus == DeviceStatus.NotInstalled) {
                dot.Fill = Brushes.Transparent;
                dot.Stroke = _brushSlate;
                dot.StrokeThickness = 1.5;
                dot.StrokeDashArray = _dotDashArray;
                return;
            }
            dot.Stroke = null;
            dot.StrokeThickness = 0;
            if (businessStatus == DeviceStatus.Broken) { dot.Fill = _brushBlack; return; }
            if (businessStatus == DeviceStatus.Touched) { dot.Fill = _brushRed; return; }
            if (businessStatus == DeviceStatus.FalseStart) { dot.Fill = _brushAmber; return; }
            //2026-05-31 业务 Closed 优先于 Hw*Color (= PC 业务关 → UI 立即变灰, 不等 0x52 上报的 100-200ms)
            if (businessStatus == DeviceStatus.Closed) { dot.Fill = _brushSlate; return; }
            //2026-06-09 业务 Open 也优先 (= 跟 Closed 对称): 比赛开始前硬件未报 0x51, hwColor=0 灰, PC 该按业务 Open 显绿 (SB) / 黄 (TP/MB)
            if (businessStatus == DeviceStatus.Open) {
                dot.Fill = (deviceType == DotDeviceType.Sb) ? _brushGreen : _brushAmber;
                return;
            }
            //2026-06-02 HardwareAlwaysOpen 模式: 硬件 cmd 0x50/0x51/0x52 不发, 完全靠业务字段; hwColor 字段失效
            if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen) {
                if (businessStatus == DeviceStatus.Open) {
                    dot.Fill = (deviceType == DotDeviceType.Sb) ? _brushGreen : _brushAmber;
                } else {
                    dot.Fill = _brushSlate;
                }
                return;
            }
            // 否则按 hwColor 渲染 (= 硬件 LCD 颜色)
            switch (hwColor) {
                case 0: dot.Fill = _brushSlate; break;                                   // Close 灰 (= 硬件 Close_Color=GRAY)
                case 1: dot.Fill = (deviceType == DotDeviceType.Sb) ? _brushGreen : _brushAmber; break;  // Open: SB=绿 / TP-MB=黄
                case 2: dot.Fill = _brushDarkRed; break;                                 // Delay 暗红 (= 硬件 Delay_Color=0xD000)
                case 3: dot.Fill = _brushBlack; break;                                   // Bad 黑 (= 硬件 Bad_Color=BLACK)
                case 4: dot.Fill = _brushBlack; break;                                   // UnInstall 黑 (= 硬件 UnInstall_Color=BLACK, 2025-1-6)
                case 5: dot.Fill = _brushRed; break;                                     // Pressed 红 (= 硬件 Valid_Color=RED)
                default: dot.Fill = _brushSlate; break;
            }
        }

        private Ellipse MakeLaneDot(DeviceStatus status) {
            var e = new Ellipse { Width = 22, Height = 22, Margin = new Thickness(2, 0, 2, 0) };
            StyleDot(e, status);
            return e;
        }

