        private List<LaneRowUI> _laneRowUIs = new List<LaneRowUI>();

        // 2026-06-16 盲表成绩历史: 每泳道一条 List, 时间降序 (最新在 [0]). 容量按 1500m x 6 设备估算 (~180 条/道).
        private class BlindResultEntry {
            public double TimeSeconds;
            public DateTime ArriveAt;
            // 2026-06-16 格式 时:分:秒.1/100秒, 左零自动消隐
            //   34.78s → "34.78"; 105.78s → "1:45.78"; 5045.78s → "1:24:05.78"
            public override string ToString() {
                double t = TimeSeconds;
                if (t < 0) t = 0;
                int h = (int)(t / 3600);
                int m = (int)((t - h * 3600) / 60);
                double remSec = t - h * 3600 - m * 60;
                if (h > 0) return string.Format("{0}:{1:00}:{2:00.00}", h, m, remSec);
                if (m > 0) return string.Format("{0}:{1:00.00}", m, remSec);
                return remSec.ToString("0.00");
            }
        }
        private Dictionary<int, List<BlindResultEntry>> _laneBlindHistory = new Dictionary<int, List<BlindResultEntry>>();

        // 2026-06-16 盲表事件到达: append per-lane history (降序 Insert 到 [0]) + 刷该泳道 ComboBox
        //   下拉打开时不强制刷 SelectedIndex, 避免操作员看历史时被新数据强制跳转.
        private void AppendBlindResult(int lane, double timeSec) {
            List<BlindResultEntry> hist;
            if (!_laneBlindHistory.TryGetValue(lane, out hist)) {
                hist = new List<BlindResultEntry>();
                _laneBlindHistory[lane] = hist;
            }
            var entry = new BlindResultEntry { TimeSeconds = timeSec, ArriveAt = DateTime.Now };
            hist.Insert(0, entry);
            LaneRowUI rowUI = null;
            foreach (var r in _laneRowUIs) { if (r.Lane == lane) { rowUI = r; break; } }
            if (rowUI != null && rowUI.BlindCombo != null) {
                var combo = rowUI.BlindCombo;
                bool wasOpen = combo.IsDropDownOpen;
                combo.Items.Insert(0, entry);
                if (!wasOpen) combo.SelectedIndex = 0;
            }
        }
        private string _laneRowsBuiltKey = "";

        // 接力项目：根据当前段数计算正在游的棒次，返回 "第N棒: 队员姓名"。
        // 与 race_control.html / RemoteTimingControl 的算法一致：lapsPerLeg = 单棒距离 / 泳池长度。
        private string ComputeRelayCurrentLegLabel(Swimmer sw, int currentLap, bool isFinished) {
            if (sw == null) return "";
            string legNames = "";
            if (!string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:"))
                legNames = sw.Notes.Substring("接力队 棒次:".Length);
            if (string.IsNullOrEmpty(legNames)) return sw.Country ?? "";
            string[] parts = legNames.Split(',');
            if (parts.Length <= 1) return parts.Length > 0 ? parts[0].Trim() : "";

            string ev = _currentEvent ?? "";
            var m = System.Text.RegularExpressions.Regex.Match(ev, @"(\d+)\s*[x×]\s*(\d+)");
            int legCount = m.Success ? int.Parse(m.Groups[1].Value) : 4;
            int legDist = m.Success ? int.Parse(m.Groups[2].Value) : 100;
            int poolLen = _poolConfig != null && _poolConfig.Length > 0 ? _poolConfig.Length : 50;
            int lapsPerLeg = Math.Max(1, legDist / poolLen);
            int currentLeg = currentLap / lapsPerLeg;
            if (currentLeg >= legCount) currentLeg = legCount - 1;
            if (currentLeg < 0) currentLeg = 0;
            if (isFinished) currentLeg = legCount - 1;
            string legName = currentLeg < parts.Length ? parts[currentLeg].Trim() : parts[0].Trim();
            return string.Format("第{0}棒: {1}", currentLeg + 1, legName);
        }

        // 解析 _currentEvent (如 "4×100米自由泳接力") → (legCount, lapsPerLeg)；解析失败回退 (4, 2)
        private void ParseRelayLayout(out int legCount, out int lapsPerLeg) {
            legCount = 4; lapsPerLeg = 2;
            var ev = _currentEvent ?? "";
            var m = System.Text.RegularExpressions.Regex.Match(ev, @"(\d+)\s*[x×]\s*(\d+)");
            if (m.Success) {
                int n;
                if (int.TryParse(m.Groups[1].Value, out n) && n > 0 && n <= 10) legCount = n;
                int d;
                if (int.TryParse(m.Groups[2].Value, out d) && d > 0) {
                    int poolLen = (_poolConfig != null && _poolConfig.Length > 0) ? _poolConfig.Length : 50;
                    lapsPerLeg = Math.Max(1, d / poolLen);
                }
            }
        }

        // 由 currentLap 计算"出发台事件属于第几棒"（0-based）。
        //   leg-1 出发台触发时 currentLap=0 → 0
        //   leg-2 交接时 currentLap=lapsPerLeg → 1
        //   依次类推；越界时夹到 [0, legCount-1]
        private int ComputeRelayLegIndex(int currentLap) {
            int legCount, lapsPerLeg;
            ParseRelayLayout(out legCount, out lapsPerLeg);
            int idx = currentLap / lapsPerLeg;
            if (idx < 0) idx = 0;
            if (idx > legCount - 1) idx = legCount - 1;
            return idx;
        }

        // 找/建当前 stage+heat 对应的 LaneResult（用于接力反应时写入；避免事件早于触板创建 LaneResult 导致丢写）
        private LaneResult EnsureRelayLaneResult(Swimmer sw, int lane) {
            if (sw == null) return null;
            var res = sw.Results.FirstOrDefault(r2 => r2.Stage == _currentStage && r2.Heat == _currentHeat);
            if (res == null) {
                res = new LaneResult {
                    EventName = _currentEvent, Stage = _currentStage,
                    Heat = _currentHeat, Lane = lane
                };
                sw.Results.Add(res);
            }
            return res;
        }

        // 把 LegReactionTimes 预填到 legCount 个 0 占位槽位。
        // 0 表示该棒尚未记录到反应时；打印端看到 0 显示 "—"。
        private void EnsureLegReactionSlots(LaneResult res) {
            if (res == null) return;
            int legCount, lapsPerLeg;
            ParseRelayLayout(out legCount, out lapsPerLeg);
            if (res.LegReactionTimes == null) res.LegReactionTimes = new List<double>();
            while (res.LegReactionTimes.Count < legCount) res.LegReactionTimes.Add(0);
        }

        // 2026-06-14 PreStart 重设计: 收到 0x22 (GunPreStart) 后回算所有抢跳事件的反应时.
        //   抢跳 SB: 固件已延迟到 GunFired_PostOpenDoneBit=1 才发, 故几乎不会进这里; 留作健壮性兜底.
        //   抢跳 TP (= 触板按下早于枪响): 固件 keyscan 即触即送, 必然先到, 用本表回算.
        private void FlushPendingPreStartReactions() {
            if (!_gunPreStartSec.HasValue) return;
            double gun = _gunPreStartSec.Value;
            foreach (var pr in _pendingPreStartReactions) {
                double reactionTime = pr.RawPreStartSec - gun;
                var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == pr.Lane);
                if (laneState == null) continue;
                if (pr.DeviceKind == "SB") {
                    laneState.ReactionTime = reactionTime;
                    if (pr.IsRelayLeg1) {
                        var swForLane0 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                            var sa2 = s2.GetAssignmentForStage(_currentStage);
                            return (sa2 != null ? sa2.Lane : s2.Lane) == pr.Lane;
                        });
                        if (swForLane0 != null) {
                            var res0 = EnsureRelayLaneResult(swForLane0, pr.Lane);
                            if (res0 != null) {
                                EnsureLegReactionSlots(res0);
                                if (res0.LegReactionTimes.Count > 0) res0.LegReactionTimes[0] = reactionTime;
                            }
                        }
                    }
                    laneState.IsSuspectFalseStart = (reactionTime < 0);
                    AddLog(Loc.F("Str_Log_RecalcSbReactionFmt",
                        pr.Lane, reactionTime, reactionTime < 0 ? " ⚠抢跳" : ""));
                    // 2026-06-15 Flush 回算后主动写比赛日志 (计算后的反应时, 替代 LogRawTimingData 跳过的那次)
                    {
                        var sw_flush_sb = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                            var sa2 = s2.GetAssignmentForStage(_currentStage);
                            return (sa2 != null ? sa2.Lane : s2.Lane) == pr.Lane;
                        });
                        string swName_flush_sb = sw_flush_sb != null ? (sw_flush_sb.Name ?? "") : "";
                        AppendToLaneEventLog(pr.Lane, "StartingBlock", reactionTime, swName_flush_sb, pr.Side, -1);
                    }
                }
                else if (pr.DeviceKind == "TP") {
                    // 2026-06-14 仰泳 TP 松开抢跳兜底: 实际不应到这里 (release 必晚于枪响), 留作健壮性处理
                    laneState.ReactionTime = reactionTime;
                    if (pr.IsRelayLeg1) {
                        var swForLane0 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                            var sa2 = s2.GetAssignmentForStage(_currentStage);
                            return (sa2 != null ? sa2.Lane : s2.Lane) == pr.Lane;
                        });
                        if (swForLane0 != null) {
                            var res0 = EnsureRelayLaneResult(swForLane0, pr.Lane);
                            if (res0 != null) {
                                EnsureLegReactionSlots(res0);
                                if (res0.LegReactionTimes.Count > 0) res0.LegReactionTimes[0] = reactionTime;
                            }
                        }
                    }
                    laneState.IsSuspectFalseStart = (reactionTime < 0);
                    AddLog(Loc.F("Str_Log_RecalcTpReactionFmt",
                        pr.Lane, reactionTime, reactionTime < 0 ? " ⚠抢跳" : ""));
                    // 2026-06-15 Flush 回算后主动写比赛日志 (仰泳抢跳计算后的反应时)
                    {
                        var sw_flush_tp = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                            var sa2 = s2.GetAssignmentForStage(_currentStage);
                            return (sa2 != null ? sa2.Lane : s2.Lane) == pr.Lane;
                        });
                        string swName_flush_tp = sw_flush_tp != null ? (sw_flush_tp.Name ?? "") : "";
                        AppendToLaneEventLog(pr.Lane, "BackstrokeRelease", reactionTime, swName_flush_tp, pr.Side, -1);
                    }
                }
            }
            _pendingPreStartReactions.Clear();
        }

        // 2026-06-23 仰泳出发反应时专用方法群 (= 与正常 case 隔离, 跟固件 TouchPad_BackstrokeStart_Process 对称).
        //   case "BackstrokeRelease" → ProcessBackstrokeReleaseFrame: 入口处理 D3=3 帧 (= 暂存 + 启 timer)
        //   case "GunPreStart"      → StartBackstrokeWindowsAfterGun: gun 到达时启动暂存 lane 的 timer (= StartBlockCloseDelay 全部)
        //   timer 到期               → OnBackstrokeWindowExpired: 用最后一次的 LastRawPreStartSec 算反应时, 锁定 + 1 条比赛日志
        //   Reset 路径               → ClearBackstrokeReleaseWindows: stop timer + clear dict + 清 _gunArrivedAt

        // 2026-06-23 case "BackstrokeRelease" 帧的专用入口: 暂存 + 启 timer (覆盖式, 取最后一次松开).
        //   守卫: 接力非出发棒 (CurrentLap>0) → 走 RelayReactionCalculator 现有路径, 不进此窗口.
        //   时序: gun 已响 → 启 timer = max(0.05, StartBlockCloseDelay - (now - _gunArrivedAt))
        //          gun 未响 → 仅暂存, 等 StartBackstrokeWindowsAfterGun 启动 timer = StartBlockCloseDelay 全部
        //   不立即写 laneState.ReactionTime, 不立即 AppendToLaneEventLog. 等 OnBackstrokeWindowExpired 锁定.
        // 2026-07-08 (v2) 直通模式 SB 独立子程序 (跟按比赛流程 case StartingBlock 隔离).
        //   按比赛流程: 硬件推 0x50 SB 状态帧 (Open→Touched→Closed), PC 端用 sbStatus 守卫过滤.
        //   直通模式:   硬件不推状态帧, 每次 SB 触发都上报. PC 需自主复刻硬件按比赛流程 SBCloseDelay 屏蔽 (用户指出根因):
        //     - 窗口内 (gun 后 SBCloseDelay 时间内): 每次 SB 触发都覆盖 LastPreStartSec (迭代模式, 去干扰信号)
        //     - 窗口到期 (SBCloseDelay 到=0): 用最后一次 LastPreStartSec 算反应时 + 写 laneState.ReactionTime + Broadcast
        //       + 置 SbReactionRecorded flag → 之后 SB 不再进窗口
        //     - Flag 置后再来 SB: RecordBackupReaction (= 备用反应时, 跟主路径 Touched 分支一致), 不覆盖主反应时
        //     - Gun 前 SB: 也进窗口 (暂存 LastPreStartSec), timer 由 StartDirectSbWindowsAfterGun 在 gun 到时启动
        //   TimerReset 时 ClearDirectSbWindows 清所有 window; ResetForNewRace 清 SbReactionRecorded flag.
        private void HandleStartingBlock_AlwaysOpen(int lane, string side, double timeInSeconds, bool isFalseStart, LaneDeviceState laneState) {
            // 2026-07-13 v8 诊断: 入口 log, 便于追踪 SB 帧是否到达+ 各守卫拦哪
            AddLog(Loc.F("Str_Log_DirectSbFrameReceivedFmt",
                lane, side == "left" ? "左" : (side == "right" ? "右" : "?"),
                timeInSeconds, laneState.CurrentLap, isFalseStart));
            // 守卫 A: side 缺失 (= 协议错误, 跟主路径 line 5012-5015 一致). 前移: 后续判据全按 side.
            if (side != "left" && side != "right") {
                AddLog(Loc.F("Str_Log_DirectSbSideMissingFmt", lane));
                return;
            }
            // 2026-07-13 按侧出发/交接判据: HandoffMode[side] 由倒计时=0 (CreateOrResetDirectSbWindow) 置位.
            //   false = 该侧仍出发段 (基准=gun); true = 该侧已进入交接处理 (基准=TP/MB). 不再看 CurrentLap.
            bool handoffMode = (side == "left") ? laneState.HandoffModeLeft : laneState.HandoffModeRight;
            // 2026-07-09 仰泳出发 (含混合泳接力第 1 棒仰泳) 反应时走 TP (BackstrokeRelease) 路径 → 出发段 SB 忽略.
            //   仅出发段 (!handoffMode) 忽略; 混合接力棒 2/3/4 常规泳姿的 SB 交接反应时仍需处理.
            if (IsBackstrokeStartEvent(_currentEvent) && !handoffMode) {
                AddLog(Loc.F("Str_Log_DirectSbStartIgnoredBackstrokeFmt",
                    lane, side == "left" ? "左" : "右"));
                return;
            }
            // 2026-07-13 规则 1 (修正): Broken/NotInstalled 物理无设备 → 两段都拒.
            //   Closed 仅【交接段】拒 (支持锁定后 Closed → 备用); 【出发段】不受 sbStatus gate
            //   (= 删补丁1, 直通独立子程序不用主路径 sbStatus; 出发段 SB 一律进 _directStartSbWindows 自管窗口,
            //    相当于该段 SB 恒 Open, 修棒1 "SB 被 sbTimer 关闭后规则1 拒收 → 反应时全丢").
            {
                DeviceStatus sbSt = (side == "left") ? laneState.LeftStartBlockStatus : laneState.RightStartBlockStatus;
                if (sbSt == DeviceStatus.Broken || sbSt == DeviceStatus.NotInstalled) {
                    AddLog(Loc.F("Str_Log_DirectSbStatusRejectedFmt", lane, side == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right"), sbSt));
                    return;
                }
                if (handoffMode && sbSt == DeviceStatus.Closed) {
                    AddLog(Loc.F("Str_Log_DirectSbHandoffClosedRejectedFmt", lane, side == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                    return;
                }
            }
            // 2026-07-09 守卫: 出发段 (!handoffMode) 只允许出发端 SB, 非出发端 (= 硬件误触/杂帧) 忽略.
            //   否则左右两侧各自建立 window 各到期算 rt → laneState.ReactionTime 被覆盖, display.html 显示错值.
            //   交接段 (handoffMode) 不加此守卫 — 4×50m 棒 2/4 SB 在对端.
            if (!handoffMode) {
                bool startLeftSb = _laneCloseSettings == null || _laneCloseSettings.StartPosition != "right";
                string startSideSb = startLeftSb ? "left" : "right";
                if (side != startSideSb) {
                    AddLog(Loc.F("Str_Log_DirectSbNotStartSideFmt",
                        lane, side == "left" ? "左" : "右", startSideSb == "left" ? "左" : "右"));
                    return;
                }
            }
            // 守卫 B: 时间≈0 (= 硬件无有效信号, 跟主路径 line 5023-5027 一致)
            if (Math.Abs(timeInSeconds) < 0.001) {
                AddLog(Loc.F("Str_Log_DirectSbZeroTimeIgnoredFmt", lane));
                return;
            }
            // 2026-07-13 直通【正常出发】迭代窗口 (跟仰泳出发/交接段一致, 修正 rev6 "取第一次 SB"):
            //   硬件"各就位"会发多次原始 SB → 每次覆盖 LastPreStartSec; 枪响后 StartBlockCloseDelay 到期取最后一次(=真起跳) − 枪.
            //   枪未响(抢跳): 仅暂存, 由 StartDirectStartSbWindowsAfterGun 在枪响时启窗口. rt/抢跳/日志 都在 OnDirectStartSbExpired.
            if (!handoffMode) {
                if (!_laneCloseSettings.ReactionTimeEnabled) {
                    AddLog(Loc.F("Str_Log_DirectSbStartTriggeredNoRtFmt", lane));
                    EnterStartBlockTouchedThenClose(laneState, side, lane);
                    return;
                }
                // 2026-07-13 参考比赛模式 Touched 分支: 本侧出发窗口已到期锁定官方 rt → 之后来的 SB 走备用反应时,
                //   不再新建窗口重算 (窗口已取最后一次=真起跳, 锁定后不该被覆盖).
                bool startAlreadyRec = (side == "left") ? laneState.SbReactionRecordedLeft : laneState.SbReactionRecordedRight;
                if (startAlreadyRec) {
                    RecordBackupReaction(lane, timeInSeconds, side);
                    AddLog(Loc.F("Str_Log_DirectSbStartLockedBackupFmt", lane, side == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                    return;
                }
                DirectSbWindow swin;
                if (!_directStartSbWindows.TryGetValue(lane, out swin)) {
                    swin = new DirectSbWindow { Lane = lane, Side = side };
                    _directStartSbWindows[lane] = swin;
                }
                swin.Side = side;
                swin.LastPreStartSec = timeInSeconds;      // 迭代覆盖 = 最后一次(=真起跳)
                swin.LastIsFalseStart = isFalseStart;
                swin.AllRawTimes.Add(timeInSeconds);
                EnterStartBlockTouchedThenClose(laneState, side, lane);   // 视觉 Touched(红), StartBlockCloseDelay 后 Closed
                // 启窗口 timer (仅枪已响且未启): 从枪响算 StartBlockCloseDelay, 到期锁定最后一次
                if (!swin.TimerStarted && _gunPreStartSec.HasValue && _gunArrivedAt.HasValue) {
                    double delay = (_laneCloseSettings != null && _laneCloseSettings.StartBlockCloseDelay > 0) ? _laneCloseSettings.StartBlockCloseDelay : 2.0;
                    double remaining = Math.Max(0.05, delay - (DateTime.Now - _gunArrivedAt.Value).TotalSeconds);
                    int laneCopy = lane;
                    swin.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(remaining) };
                    swin.Timer.Tick += (s, e) => OnDirectStartSbExpired(laneCopy);
                    swin.Timer.Start();
                    swin.TimerStarted = true;
                    AddLog(Loc.F("Str_Log_DirectSbStartWindowStartedFmt", lane, remaining));
                } else if (!_gunPreStartSec.HasValue) {
                    AddLog(Loc.F("Str_Log_DirectSbStartPreGunFmt", lane, timeInSeconds));
                }
                return;
            }
            // ── 以下仅交接段 (handoffMode) 走 v8 DirectSbWindow ──
            // 守卫 C: 本棒已锁定反应时 → 之后来的 SB 走备用反应时 (= 复刻 Touched 状态).
            //   "新交接清 flag 允许新 window"已移至 CreateOrResetDirectSbWindow (倒计时=0), 不再靠 CurrentLap 比较.
            bool alreadyRecorded = (side == "left") ? laneState.SbReactionRecordedLeft : laneState.SbReactionRecordedRight;
            if (alreadyRecorded) {
                RecordBackupReaction(lane, timeInSeconds, side);
                AddLog(Loc.F("Str_Log_DirectSbLegLockedBackupFmt", lane, side == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                return;
            }
            // 找/建 window (= per lane per side)
            string wkey = lane + "|" + side;
            DirectSbWindow win;
            if (!_directSbWindows.TryGetValue(wkey, out win)) {
                win = new DirectSbWindow { Lane = lane, Side = side };
                _directSbWindows[wkey] = win;
            }
            // 覆盖 LastPreStartSec (= 用于最终锁定的"最后一次") + 累加 AllRawTimes (= 用于逐条日志的"全部历史").
            win.LastPreStartSec = timeInSeconds;
            win.LastIsFalseStart = isFalseStart;
            win.AllRawTimes.Add(timeInSeconds);
            AddLog(Loc.F("Str_Log_DirectSbInWindowTriggeredFmt",
                lane, side == "left" ? "左" : "右", win.AllRawTimes.Count, timeInSeconds, isFalseStart ? " 抢跳" : ""));
            // 2026-07-11 补丁 3: 每次触发都写比赛日志 "出(第N次)=X.XXX" (raw PreStart 秒), 不算 rt.
            //   用户诉求: 窗口内每次 SB 都留痕以防误出发追溯. rt 计算+推 UI 仅在窗口锁定时做 1 次.
            {
                var swForLog = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                    var sa2 = s2.GetAssignmentForStage(_currentStage);
                    return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
                });
                string swNameForLog = swForLog != null ? (swForLog.Name ?? "") : "";
                if (!_laneEventLog.ContainsKey(lane)) _laneEventLog[lane] = new StringBuilder();
                string elapsedForLog = _raceStartTime > DateTime.MinValue
                    ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds)
                    : "—";
                string sideLabelForLog = side == "left" ? "左" : "右";
                _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2} 出(第{3}次)={4:F3}{5}\r\n",
                    elapsedForLog, lane, sideLabelForLog, win.AllRawTimes.Count, timeInSeconds,
                    string.IsNullOrEmpty(swNameForLog) ? "" : (" (" + swNameForLog + ")"));
                TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
            }
            // 2026-07-12 直通模式 SB 状态转换 (对应硬件 swimplay.c line 4308-4319 松开→state=2 延迟关中):
            //   sbStatus Open → Touched (红). UI 立即视觉反馈"按下".
            //   与主路径 EnterStartBlockTouchedThenClose 隔离, 直通模式独立子程序自维护 (不共用).
            if (side == "left") {
                if (!laneState.LeftStartBlockBroken && laneState.LeftStartBlockStatus != DeviceStatus.NotInstalled)
                    laneState.LeftStartBlockStatus = DeviceStatus.Touched;
            } else {
                if (!laneState.RightStartBlockBroken && laneState.RightStartBlockStatus != DeviceStatus.NotInstalled)
                    laneState.RightStartBlockStatus = DeviceStatus.Touched;
            }
            // 2026-07-13 v8: SB 帧到达只累加, 不启 timer. Timer 由 TP/MB/GUN 帧触发 (参照用户规则).
        }

        // 2026-07-13 按侧交接锚点 (两模式共用, 倒计时=0 设): 置该侧 HandoffMode + 起跳棒次印章 + 清上一棒锁定标志.
        //   锚点早于到达触板, 不依赖 CurrentLap 的 ++ 时序. 出发/交接判据从此只看 HandoffMode[side] && !SbReactionRecorded[side].
        //   流程模式单独调此 (反应时仍由 _relayReactionCalc 算, 不建自算窗口); 直通模式由 CreateOrResetDirectSbWindow 内部调.
        private void MarkHandoffSide(int lane, string side, int legIndex) {
            var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (ls == null) return;
            if (side == "left")       { ls.HandoffModeLeft = true;  ls.SbReactionRecordedLeft = false;  ls.HandoffLegIdxLeft = legIndex; }
            else if (side == "right") { ls.HandoffModeRight = true; ls.SbReactionRecordedRight = false; ls.HandoffLegIdxRight = legIndex; }
        }

        // 2026-07-13 v8: 创建/重置直通 window (清 SB 数据). 由主路径调用 (Ready 时对出发端, 触板+倒计时结束时对交接端).
        private void CreateOrResetDirectSbWindow(int lane, string side, int legIndex) {
            if (side != "left" && side != "right") return;
            string wkey = lane + "|" + side;
            var w = new DirectSbWindow { Lane = lane, Side = side, LegIndex = legIndex };
            _directSbWindows[wkey] = w;
            MarkHandoffSide(lane, side, legIndex);   // 置 HandoffMode + 棒次印章 + 清锁定标志 (两模式共用锚点)
            AddLog(Loc.F("Str_Log_DirectSbWindowClearedFmt",
                lane, side == "left" ? "左" : "右", legIndex + 1));
        }

        // 2026-07-13 记录交接段 basis 信号 (仅交接段用, 出发段不进 v8). 用户规则:
        //   "TP"            → 真触板 = 基准 (最优先). 从 TP 起 ReactionEventWindowSec 收尾 SB; 若 timer 已启则覆盖重启.
        //   "MB_FirstPress" → 盲表 first-press (mbButton=1/2/3). 存 Mb1/2/3 供 1/2/3 取值; MB 先到且无 TP → 启
        //                     "盲表代替延迟" BlindReplaceDelay 宽限等 TP (已启则不重启).
        //   "MB_Final"      → 硬件 MB 代触 final. 决定(b): 不作 basis, 仅留痕; 若无 TP 无 timer 也启同款宽限等 TP.
        //   到期 (OnDirectSbHandoffExpired): 基准 TP > MB(1/2/3 first-press); 无二者 → ****** (MB_Final 不算).
        private void RecordDirectSbBasis(int lane, string side, double time, string kind, int mbButton = 0) {
            if (side != "left" && side != "right") return;
            string wkey = lane + "|" + side;
            DirectSbWindow win;
            if (!_directSbWindows.TryGetValue(wkey, out win)) {
                win = new DirectSbWindow { Lane = lane, Side = side };
                _directSbWindows[wkey] = win;
            }
            // 1) 记录信号
            bool isTp = false;
            switch (kind) {
                case "TP":            win.HasTp = true; win.TpTime = time; isTp = true; break;
                case "MB_Final":      win.HasMbFinal = true; win.MbFinalTime = time; break;   // (b): 不作 basis, 仅留痕
                case "MB_FirstPress":
                    if      (mbButton == 1 && win.Mb1 <= 0) win.Mb1 = time;   // 只取每个盲表首次按下
                    else if (mbButton == 2 && win.Mb2 <= 0) win.Mb2 = time;
                    else if (mbButton == 3 && win.Mb3 <= 0) win.Mb3 = time;
                    break;
                default: return;
            }
            // 2) 决定 timer: TP → ReactionEventWindowSec 收尾 (覆盖重启); MB 先到无 TP → BlindReplaceDelay 宽限 (不重启)
            double delay; bool restart;
            if (isTp) {
                delay = (_laneCloseSettings != null) ? _laneCloseSettings.ReactionEventWindowSec : 3.0;
                restart = win.TimerStarted;   // TP 到 → 从 TP 起重新计
            } else {
                delay = (_laneCloseSettings != null) ? _laneCloseSettings.BlindReplaceDelay : 3.0;
                restart = false;              // MB 不打断已启的 timer
            }
            bool startNow = !win.TimerStarted;
            if (startNow || restart) {
                int laneCopy = lane;
                string sideCopy = side;
                if (win.Timer != null) { try { win.Timer.Stop(); } catch { } }
                win.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(delay) };
                win.Timer.Tick += (s, e) => OnDirectSbHandoffExpired(laneCopy, sideCopy);
                win.Timer.Start();
                win.TimerStarted = true;
                win.TimerStartKind = kind;
                AddLog(Loc.F("Str_Log_DirectSbBasisTimerStartedFmt",
                    lane, side == "left" ? "左" : "右", kind, time,
                    restart ? "覆盖并重" : "", delay, isTp ? " 后按 TP 锁定" : " 盲表代替延迟宽限", win.AllRawTimes.Count));
            } else {
                AddLog(Loc.F("Str_Log_DirectSbBasisRecordedFmt",
                    lane, side == "left" ? "左" : "右", kind, time, win.TimerStartKind));
            }
        }

        // 2026-07-13 交接段 MB 代 TP 基准取值 (= 照搬主路径 DoMbSubstitute 规则):
        //   1 个盲表 first-press = 自己; 2 个 = 平均后千分位 floor 到百分位 (禁四舍五入); 3 个 = 真中位.
        //   特例(用户 2026-07-13): 3 个里有两个时间相同 → 排序后中位[1] 天然=该相同值, 无需特判.
        //   无任何 first-press → false (由调用方判 ******). 数据源 = win.Mb1/Mb2/Mb3.
        private bool TryComputeDirectMbBasis(DirectSbWindow win, out double basis) {
            var blinds = new List<double>();
            if (win.Mb1 > 0) blinds.Add(win.Mb1);
            if (win.Mb2 > 0) blinds.Add(win.Mb2);
            if (win.Mb3 > 0) blinds.Add(win.Mb3);
            if (blinds.Count == 0) { basis = 0; return false; }
            blinds.Sort();
            basis = (blinds.Count == 2)
                ? Math.Floor((blinds[0] + blinds[1]) * 50.0) / 100.0   // 2 个: floor 到百分位
                : blinds[blinds.Count / 2];                            // 1 个=自己; 3 个=中位[1] (两同→自然取相同值)
            return true;
        }

        // 2026-07-08 gun 到时启动所有已暂存 DirectSb window 的 timer (= 跟 StartBackstrokeWindowsAfterGun 同款)
        // 2026-07-12 直通模式改用"每次 SB 触发 refresh timer", gun 到时无需特殊启动. 此方法保留但仅记日志, 不再启 timer.
        private void StartDirectSbWindowsAfterGun() {
            if (!_gunPreStartSec.HasValue) return;
            double delay = (_laneCloseSettings != null) ? _laneCloseSettings.StartBlockCloseDelay : 2.0;
            var keysToStart = new List<string>();
            foreach (var kv in _directSbWindows) {
                if (!kv.Value.TimerStarted) keysToStart.Add(kv.Key);
            }
            foreach (var wkey in keysToStart) {
                var win = _directSbWindows[wkey];
                int laneCopy = win.Lane;
                string sideCopy = win.Side;
                // 2026-07-09 (v4) gun 到只启 timer, 不再 flush 写日志.
                //   所有 SB (gun 前 + gun 后) 都在 win.AllRawTimes 累加, 到 OnDirectSbWindowExpired 统一逐条写.
                win.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(delay) };
                win.Timer.Tick += (s, e) => OnDirectSbHandoffExpired(laneCopy, sideCopy);
                win.Timer.Start();
                win.TimerStarted = true;
                AddLog(Loc.F("Str_Log_DirectSbWindowStartedGunFmt",
                    laneCopy, sideCopy == "left" ? "左" : "右", delay, win.AllRawTimes.Count));
            }
        }

        // 2026-07-13 直通模式交接段 SB 反应时窗口到期 (仅交接段; 出发段走主路径立即算 rt, 不到此).
        //   基准由 RecordDirectSbBasis 设定 (TP / MB 1/2/3 first-press), 到期算 rt = LastSb - 基准.
        //   基准优先级 TP > MB(1/2/3); 二者皆无 → ****** (MB_Final 不算, 决定 b).
        private void OnDirectSbHandoffExpired(int lane, string side) {
            string wkey = lane + "|" + side;
            DirectSbWindow win;
            if (!_directSbWindows.TryGetValue(wkey, out win)) return;   // 幂等: 已处理过
            if (win.Timer != null) { try { win.Timer.Stop(); } catch { } }
            _directSbWindows.Remove(wkey);

            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;

            // 2026-07-12 sbStatus Touched → Closed (对应硬件 state=2→0 Process_StartBox_DelayClose 到期)
            if (side == "left") {
                if (laneState.LeftStartBlockStatus == DeviceStatus.Touched)
                    laneState.LeftStartBlockStatus = DeviceStatus.Closed;
            } else if (side == "right") {
                if (laneState.RightStartBlockStatus == DeviceStatus.Touched)
                    laneState.RightStartBlockStatus = DeviceStatus.Closed;
            }

            // 2026-07-13 交接段 basis 优先级: TP > MB(1/2/3 first-press). 出发段不到此.
            //   - 有 SB + 有 basis → rt = LastPreStart - basisTime
            //   - 有 basis 无 SB → "------"
            //   - 无 basis (无 TP 且无盲表 first-press; 只有硬件 MB_Final 也算无 → 决定(b)) → "******"
            double basisTime = 0; string basisKind = null;
            if (win.HasTp) { basisTime = win.TpTime; basisKind = "TP"; }
            else {
                double mbBasis;
                if (TryComputeDirectMbBasis(win, out mbBasis)) { basisTime = mbBasis; basisKind = "MB"; }
                // (b): 只有硬件 MB_Final、无 TP 无 first-press → basisKind 保持 null → ******
            }
            bool hasBasis = basisKind != null;

            var swForLog = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                var sa2 = s2.GetAssignmentForStage(_currentStage);
                return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
            });
            string swNameForLog = swForLog != null ? (swForLog.Name ?? "") : "";
            string elapsedForLog = _raceStartTime > DateTime.MinValue
                ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds)
                : "—";
            string sideLabelForLog = side == "left" ? "左" : "右";
            if (!_laneEventLog.ContainsKey(lane)) _laneEventLog[lane] = new StringBuilder();

            // 接力棒次索引 = 倒计时=0 建窗口时盖的印章 (win.LegIndex), 不再用 CurrentLap 现推 (避免 ++ 时序错位)
            int legIndex = _isRelay ? win.LegIndex : 0;
            string legLabel = _isRelay ? string.Format(" 第{0}棒", legIndex + 1) : "";

            // 情形 A: 无基准 → "******"
            if (!hasBasis) {
                _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2}{3} 反应时=****** (无基准 TP/MB){4}\r\n",
                    elapsedForLog, lane, sideLabelForLog, legLabel,
                    string.IsNullOrEmpty(swNameForLog) ? "" : (" (" + swNameForLog + ")"));
                TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
                PrintReactionToThermal(lane, sideLabelForLog, legLabel, "******");
                AddLog(Loc.F("Str_Log_DirectSbNoBasisFmt", lane, legLabel, sideLabelForLog, win.AllRawTimes.Count));
                // 标 NaN → 显当前棒 "---" (setter 自动 ReactionSeq++, 客户端显示+消隐)
                laneState.ReactionTime = double.NaN;
                if (_isRelay && swForLog != null) {
                    var res0 = EnsureRelayLaneResult(swForLog, lane);
                    if (res0 != null) {
                        EnsureLegReactionSlots(res0);
                        if (res0.LegReactionTimes.Count > legIndex) res0.LegReactionTimes[legIndex] = double.NaN;
                    }
                }
                if (side == "left") { laneState.SbReactionRecordedLeft = true; }
                else                { laneState.SbReactionRecordedRight = true; }
                UpdateLaneStatusDisplay();
                Broadcast();
                return;
            }

            // 情形 B: 有基准 无 SB → "------"
            if (win.AllRawTimes.Count == 0) {
                _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2}{3} 反应时=------ (无 SB, 基准 {4}={5:F3}s){6}\r\n",
                    elapsedForLog, lane, sideLabelForLog, legLabel, basisKind, basisTime,
                    string.IsNullOrEmpty(swNameForLog) ? "" : (" (" + swNameForLog + ")"));
                TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
                PrintReactionToThermal(lane, sideLabelForLog, legLabel, "------");
                AddLog(Loc.F("Str_Log_DirectSbNoSbFmt", lane, legLabel, sideLabelForLog, basisKind, basisTime));
                laneState.ReactionTime = double.NaN;
                if (_isRelay && swForLog != null) {
                    var res0 = EnsureRelayLaneResult(swForLog, lane);
                    if (res0 != null) {
                        EnsureLegReactionSlots(res0);
                        if (res0.LegReactionTimes.Count > legIndex) res0.LegReactionTimes[legIndex] = double.NaN;
                    }
                }
                if (side == "left") { laneState.SbReactionRecordedLeft = true; }
                else                { laneState.SbReactionRecordedRight = true; }
                UpdateLaneStatusDisplay();
                Broadcast();
                return;
            }

            // 情形 C: 有基准 有 SB → rt = LastSb - basisTime
            double reactionTime = win.LastPreStartSec - basisTime;
            laneState.ReactionTime = reactionTime;   // 显当前棒 (setter 自动 ReactionSeq++, 客户端显示+消隐; 接力成绩另存 LegReactionTimes)
            if (side == "left") { laneState.SbReactionRecordedLeft = true; }
            else                { laneState.SbReactionRecordedRight = true; }
            if (_isRelay && swForLog != null) {
                var res0 = EnsureRelayLaneResult(swForLog, lane);
                if (res0 != null) {
                    EnsureLegReactionSlots(res0);
                    if (res0.LegReactionTimes.Count > legIndex) res0.LegReactionTimes[legIndex] = reactionTime;
                }
            }
            // 2026-09-22 交接棒抢跳判定改用专用阀值(默认 -0.03s), 不再是严格 <0 就判抢跳 ——
            //   触板/SB 本身有毫秒级测量误差, 接棒者在触板前一点点起跳属物理正常范围,
            //   只有 早于阀值 才真的算抢跳。
            if (win.LastIsFalseStart || reactionTime < _laneCloseSettings.RelayHandoffFalseStartThreshold) {
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_DirectSbFalseStartV8Fmt", lane, legLabel, sideLabelForLog, reactionTime, basisKind, basisTime));
            } else if (reactionTime <= _laneCloseSettings.FalseStartThreshold) {
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_DirectSbSuspectV8Fmt", lane, legLabel, sideLabelForLog, reactionTime));
            } else {
                AddLog(Loc.F("Str_Log_DirectSbReactionV8Fmt", lane, legLabel, sideLabelForLog, reactionTime, basisKind, basisTime));
            }
            _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2}{3} 反应时={4:F2}{5}\r\n",
                elapsedForLog, lane, sideLabelForLog, legLabel, reactionTime,
                string.IsNullOrEmpty(swNameForLog) ? "" : (" (" + swNameForLog + ")"));
            TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
            PrintReactionToThermal(lane, sideLabelForLog, legLabel, string.Format("{0:F2}", reactionTime));
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // 2026-07-11 直通模式接力交接: 打开交接棒 SB 时调用, 启动 v4 handoff window timer.
        //   与 HandleStartingBlock_AlwaysOpen 内的 timer 启动逻辑对应, 但**时机是触板到边+倒计时结束** (对应用户选的 2B),
        //   不是等首次 SB 触发. 时长 = StartBlockCloseDelay 秒, 到期由 OnDirectSbWindowExpired 交接段分岔 feed relayCalc.
        private void StartDirectSbHandoffWindow(int lane, string side) {
            string wkey = lane + "|" + side;
            DirectSbWindow win;
            if (!_directSbWindows.TryGetValue(wkey, out win)) {
                win = new DirectSbWindow { Lane = lane, Side = side };
                _directSbWindows[wkey] = win;
            }
            if (win.TimerStarted) return;
            double delay = (_laneCloseSettings != null) ? _laneCloseSettings.StartBlockCloseDelay : 2.0;
            int laneCopy = lane;
            string sideCopy = side;
            win.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(delay) };
            win.Timer.Tick += (s, e) => OnDirectSbHandoffExpired(laneCopy, sideCopy);
            win.Timer.Start();
            win.TimerStarted = true;
            AddLog(Loc.F("Str_Log_DirectSbHandoffWindowStartedFmt",
                lane, side == "left" ? "左" : "右", delay));
        }

        // 2026-07-08 计时复位: 清所有 DirectSb window + 停 timer
        private void ClearDirectSbWindows() {
            foreach (var kv in _directSbWindows) {
                if (kv.Value.Timer != null) { try { kv.Value.Timer.Stop(); } catch { } }
            }
            _directSbWindows.Clear();
        }

        private void ProcessBackstrokeReleaseFrame(int lane, string side, double timeInSeconds, LaneDeviceState laneState) {
            // 守卫: 接力非出发棒 → 不进此窗口
            if (_isRelay && laneState.CurrentLap > 0) {
                AddLog(Loc.F("Str_Log_BackstrokeReleaseNonStartLegFmt", lane, laneState.CurrentLap));
                return;
            }
            // 2026-07-09 守卫: 出发端 TP 已 Closed (= 变灰, StartBlockCloseDelay 后 sbTimer 关闭) → 不再保存 BackstrokeRelease 数据.
            //   用户诉求: 仰泳 TP 变灰后, 比赛日志不再累积出发端 TP 数据.
            DeviceStatus tpSt = (side == "left") ? laneState.LeftTouchpadStatus
                              : (side == "right") ? laneState.RightTouchpadStatus
                              : DeviceStatus.Closed;
            if (tpSt == DeviceStatus.Closed) {
                AddLog(Loc.F("Str_Log_BackstrokeReleaseTpClosedFmt", lane, side == "left" ? Loc.T("Str_Frag_Left") : Loc.T("Str_Frag_Right")));
                return;
            }
            // 找/建 window, 覆盖暂存 (= 最后一次 TP 松开覆盖)
            BackstrokeReleaseWindow win;
            if (!_backstrokeWindows.TryGetValue(lane, out win)) {
                win = new BackstrokeReleaseWindow { Lane = lane };
                _backstrokeWindows[lane] = win;
            }
            win.Side = side;
            win.LastRawPreStartSec = timeInSeconds;
            // 2026-07-09 (v4) 直通模式下累加所有 raw TP 松开时刻, 到期逐条写日志 (= 用户明确要求"仰泳出发 TP 数据也保存").
            //   按比赛流程模式不 Add, 保持原有"窗口结束才写 1 条"行为.
            if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen) {
                win.AllRawTimes.Add(timeInSeconds);
            }
            // 启动 timer (仅 gun 已响且未启动)
            if (!win.TimerStarted && _gunPreStartSec.HasValue && _gunArrivedAt.HasValue) {
                double delay = (_laneCloseSettings != null) ? _laneCloseSettings.StartBlockCloseDelay : 2.0;
                double elapsedSinceGun = (DateTime.Now - _gunArrivedAt.Value).TotalSeconds;
                double remaining = Math.Max(0.05, delay - elapsedSinceGun);
                int laneCopy = lane;
                win.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(remaining) };
                win.Timer.Tick += (s, e) => OnBackstrokeWindowExpired(laneCopy);
                win.Timer.Start();
                win.TimerStarted = true;
                AddLog(Loc.F("Str_Log_BackstrokeWindowStartedFmt", lane, remaining));
            }
        }

        private void StartBackstrokeWindowsAfterGun() {
            if (!_gunPreStartSec.HasValue) return;
            double delay = (_laneCloseSettings != null) ? _laneCloseSettings.StartBlockCloseDelay : 2.0;
            var lanesToStart = new List<int>();
            foreach (var kv in _backstrokeWindows) {
                if (!kv.Value.TimerStarted) lanesToStart.Add(kv.Key);
            }
            foreach (var ln in lanesToStart) {
                var win = _backstrokeWindows[ln];
                int laneCopy = ln;
                win.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(delay) };
                win.Timer.Tick += (s, e) => OnBackstrokeWindowExpired(laneCopy);
                win.Timer.Start();
                win.TimerStarted = true;
                AddLog(Loc.F("Str_Log_BackstrokeWindowStartedGunFmt", ln, delay));
            }
        }

        private void OnBackstrokeWindowExpired(int lane) {
            BackstrokeReleaseWindow win;
            if (!_backstrokeWindows.TryGetValue(lane, out win)) return;
            if (win.Timer != null) { try { win.Timer.Stop(); } catch { } }
            _backstrokeWindows.Remove(lane);

            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;

            if (!_gunPreStartSec.HasValue) {
                // 窗口到期但 gun 仍未响 (= 极罕见, 抢跳长时间未发令) → 暂存 pending 等 gun 来 Flush
                AddLog(Loc.F("Str_Log_BackstrokeWindowExpiredNoGunFmt", lane));
                _pendingPreStartReactions.Add(new PendingPreStartReaction {
                    Lane = lane, DeviceKind = "TP", Side = win.Side,
                    RawPreStartSec = win.LastRawPreStartSec, IsRelayLeg1 = _isRelay
                });
                laneState.IsSuspectFalseStart = true;
                return;
            }

            double reactionTime = win.LastRawPreStartSec - _gunPreStartSec.Value;
            laneState.ReactionTime = reactionTime;

            // 接力第 1 棒: 写 LegReactionTimes[0]
            if (_isRelay) {
                var swForLane0 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                    var sa2 = s2.GetAssignmentForStage(_currentStage);
                    return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
                });
                if (swForLane0 != null) {
                    var res0 = EnsureRelayLaneResult(swForLane0, lane);
                    if (res0 != null) {
                        EnsureLegReactionSlots(res0);
                        if (res0.LegReactionTimes.Count > 0) res0.LegReactionTimes[0] = reactionTime;
                    }
                }
            }

            if (reactionTime < 0) {
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_BackstrokeFalseStartFmt", lane, reactionTime));
            } else {
                AddLog(Loc.F("Str_Log_BackstrokeReactionFmt", lane, reactionTime));
            }

            // 2026-07-09 (v4) 直通模式: 逐条写窗口内所有 TP 松开日志 (= 用户要求"以防误出发找不到真实数据"); 按比赛流程模式: 仅写 1 条锁定值.
            var sw = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                var sa2 = s2.GetAssignmentForStage(_currentStage);
                return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
            });
            string swName = sw != null ? (sw.Name ?? "") : "";
            if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen && win.AllRawTimes.Count > 0) {
                foreach (double t in win.AllRawTimes) {
                    double rt = t - _gunPreStartSec.Value;
                    AppendToLaneEventLog(lane, "BackstrokeRelease", rt, swName, win.Side, -1);
                }
                AddLog(Loc.F("Str_Log_BackstrokeWindowDumpedFmt", lane, win.AllRawTimes.Count));
            } else {
                AppendToLaneEventLog(lane, "BackstrokeRelease", reactionTime, swName, win.Side, -1);
            }
            // 2026-07-13 仰泳直通出发反应时汇总行 + 热敏打印 (跟 OnDirectStartSbExpired 对称; 之前直通分支只 dump 了 raw 触放, 漏了汇总/打印/刷新).
            if (_laneCloseSettings != null && _laneCloseSettings.HardwareAlwaysOpen) {
                string bkSideLabel = win.Side == "left" ? "左" : "右";
                string bkLegLabel = _isRelay ? " 第1棒" : "";
                string bkElapsed = _raceStartTime > DateTime.MinValue ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds) : "—";
                if (!_laneEventLog.ContainsKey(lane)) _laneEventLog[lane] = new StringBuilder();
                _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2}{3} 反应时={4:F2}{5}\r\n",
                    bkElapsed, lane, bkSideLabel, bkLegLabel, reactionTime,
                    string.IsNullOrEmpty(swName) ? "" : (" (" + swName + ")"));
                TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
                PrintReactionToThermal(lane, bkSideLabel, bkLegLabel, string.Format("{0:F2}", reactionTime));
                UpdateLaneStatusDisplay();
                Broadcast();
            }
        }

        private void ClearBackstrokeReleaseWindows() {
            foreach (var kv in _backstrokeWindows) {
                if (kv.Value.Timer != null) {
                    try { kv.Value.Timer.Stop(); } catch { }
                }
            }
            _backstrokeWindows.Clear();
            _gunArrivedAt = null;
        }

        // 2026-07-13 直通【正常出发】SB 窗口到期: 取窗口内最后一次 SB(=真起跳) − 枪响 = 反应时 (跟仰泳出发窗口同款).
        //   接力第 1 棒写 LegReactionTimes[0]; 抢跳(硬件 flag 或 rt<0) / 可疑(≤阈值) 判定同主路径 case "StartingBlock".
        private void OnDirectStartSbExpired(int lane) {
            DirectSbWindow swin;
            if (!_directStartSbWindows.TryGetValue(lane, out swin)) return;   // 幂等: 已处理过
            if (swin.Timer != null) { try { swin.Timer.Stop(); } catch { } }
            _directStartSbWindows.Remove(lane);
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) return;
            string side = swin.Side;

            if (!_gunPreStartSec.HasValue) {
                // 窗口到期但枪未响 (极罕见, 长时间未发令) → 暂存 pending 待枪回算
                _pendingPreStartReactions.Add(new PendingPreStartReaction {
                    Lane = lane, DeviceKind = "SB", Side = side,
                    RawPreStartSec = swin.LastPreStartSec, IsRelayLeg1 = _isRelay
                });
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_DirectStartSbExpiredNoGunFmt", lane));
                return;
            }

            double reactionTime = swin.LastPreStartSec - _gunPreStartSec.Value;
            laneState.ReactionTime = reactionTime;
            // 接力第 1 棒: LegReactionTimes[0] (覆盖式)
            if (_isRelay) {
                var swForLane0 = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                    var sa2 = s2.GetAssignmentForStage(_currentStage);
                    return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
                });
                if (swForLane0 != null) {
                    var res0 = EnsureRelayLaneResult(swForLane0, lane);
                    if (res0 != null) {
                        EnsureLegReactionSlots(res0);
                        if (res0.LegReactionTimes.Count > 0) res0.LegReactionTimes[0] = reactionTime;
                    }
                }
            }
            if (swin.LastIsFalseStart || reactionTime < 0) {
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_DirectStartSbFalseStartFmt", lane, reactionTime));
            } else if (reactionTime <= _laneCloseSettings.FalseStartThreshold) {
                laneState.IsSuspectFalseStart = true;
                AddLog(Loc.F("Str_Log_DirectStartSbSuspectFmt", lane, reactionTime));
            } else {
                AddLog(Loc.F("Str_Log_DirectStartSbReactionFmt", lane, reactionTime));
            }
            // 逐条写窗口内所有原始 SB 日志 (= 防误出发追溯, 跟仰泳窗口一致); 仅 1 条时写锁定值
            var sw = GetCurrentHeatSwimmers().FirstOrDefault(s2 => {
                var sa2 = s2.GetAssignmentForStage(_currentStage);
                return (sa2 != null ? sa2.Lane : s2.Lane) == lane;
            });
            string swName = sw != null ? (sw.Name ?? "") : "";
            if (swin.AllRawTimes.Count > 1) {
                foreach (double t in swin.AllRawTimes)
                    AppendToLaneEventLog(lane, "StartingBlock", t - _gunPreStartSec.Value, swName, side, -1);
            } else {
                AppendToLaneEventLog(lane, "StartingBlock", reactionTime, swName, side, -1);
            }
            // 2026-07-13 出发反应时汇总行 + 热敏打印 (跟交接段"反应时="一致). 显示已由 laneState.ReactionTime setter 触发.
            {
                string startSideLabel = side == "left" ? "左" : "右";
                string startLegLabel = _isRelay ? " 第1棒" : "";
                string startElapsed = _raceStartTime > DateTime.MinValue ? FormatElapsedMSS((DateTime.Now - _raceStartTime).TotalSeconds) : "—";
                if (!_laneEventLog.ContainsKey(lane)) _laneEventLog[lane] = new StringBuilder();
                _laneEventLog[lane].AppendFormat("{0,8} 道{1}{2}{3} 反应时={4:F2}{5}\r\n",
                    startElapsed, lane, startSideLabel, startLegLabel, reactionTime,
                    string.IsNullOrEmpty(swName) ? "" : (" (" + swName + ")"));
                TrimSbIfOver(_laneEventLog[lane], MAX_LANE_EVENT_LOG);
                PrintReactionToThermal(lane, startSideLabel, startLegLabel, string.Format("{0:F2}", reactionTime));
            }
            if (side == "left") { laneState.SbReactionRecordedLeft = true; }
            else if (side == "right") { laneState.SbReactionRecordedRight = true; }
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // 2026-07-13 枪响时启动所有已暂存 (抢跳) 的直通正常出发 SB 窗口 (= 跟 StartBackstrokeWindowsAfterGun 同款).
        private void StartDirectStartSbWindowsAfterGun() {
            if (!_gunPreStartSec.HasValue) return;
            double delay = (_laneCloseSettings != null && _laneCloseSettings.StartBlockCloseDelay > 0) ? _laneCloseSettings.StartBlockCloseDelay : 2.0;
            var lanesToStart = new List<int>();
            foreach (var kv in _directStartSbWindows) {
                if (!kv.Value.TimerStarted) lanesToStart.Add(kv.Key);
            }
            foreach (var ln in lanesToStart) {
                var swin = _directStartSbWindows[ln];
                int laneCopy = ln;
                swin.Timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(delay) };
                swin.Timer.Tick += (s, e) => OnDirectStartSbExpired(laneCopy);
                swin.Timer.Start();
                swin.TimerStarted = true;
                AddLog(Loc.F("Str_Log_DirectStartSbWindowStartedGunFmt", ln, delay));
            }
        }

        // 2026-07-13 清直通正常出发 SB 窗口 (Reset / 新一场).
        private void ClearDirectStartSbWindows() {
            foreach (var kv in _directStartSbWindows) {
                if (kv.Value.Timer != null) { try { kv.Value.Timer.Stop(); } catch { } }
            }
            _directStartSbWindows.Clear();
        }

        private void UpdateLaneStatusDisplay() {
            if (LanePanel == null || PoolHeader == null) return;

            var currentSwimmers = GetCurrentHeatSwimmers();

            // 为所有泳道建立 lane→swimmer 映射（空泳道 swimmer 为 null）
            var laneSwimmerMap = new Dictionary<int, Swimmer>();
            foreach (var sw in currentSwimmers) {
                var sa = sw.GetAssignmentForStage(_currentStage);
                int ln = sa != null ? sa.Lane : sw.Lane;
                if (!laneSwimmerMap.ContainsKey(ln)) laneSwimmerMap[ln] = sw;
            }
            var allPoolLanes = (_poolConfig.LaneNumbers ?? new List<int>()).ToList();
            // 道次顺序：正序=升序 0→9（顶到底）；逆序=降序 9→0
            allPoolLanes.Sort();
            if (_laneCloseSettings.LaneOrder == "reverse") allPoolLanes.Reverse();

            // 构造本次数据的key（运动员列表或泳道集合变化时需要重建UI；盲表数量变更也要重建）
            // 2026-05-26 修复: 发令位置 (StartPosition) 加入 key, 否则
            //   AutoAdjustStartPosition (50米发令切到终点对面) 或参数面板改发令位置后,
            //   PoolHeader 顶部左右"发令位置"绿色徽章 + 空泳道行的左右指示灯不刷新.
            string key = _currentGender + "|" + _currentEvent + "|" + _currentStage + "|" + _currentHeat
                + "|" + allPoolLanes.Count + "|" + currentSwimmers.Count
                + "|bw:" + _laneCloseSettings.LeftBlindWatchCount + "/" + _laneCloseSettings.RightBlindWatchCount
                + "|sp:" + (_laneCloseSettings.StartPosition ?? "");
            foreach (int ln in allPoolLanes) {
                Swimmer lsw;
                laneSwimmerMap.TryGetValue(ln, out lsw);
                key += "|" + ln + ":" + (lsw != null ? lsw.Name : "(empty)");
            }

            if (key != _laneRowsBuiltKey) {
                RenderPoolHeader();
                BuildLaneRows(allPoolLanes, laneSwimmerMap);
                _laneRowsBuiltKey = key;
            }
            // ── 2026-09-13 泳道行里存的 Swimmer 引用可能已经作废 ──────────────
            //   RefreshLaneRows 画的是 rowUI.Swimmer, 那是 BuildLaneRows 那一刻抓住的对象。
            //   而收到整包(EDITOR_PACKAGE)时 ApplyPackageInMemory 会把 _swimmers 整批换成
            //   新对象 —— 姓名没变, 上面那个 key 就没变, 于是行不重建, 里头攥着的还是
            //   一批孤儿对象。后果: 之后所有改动(判 DSQ/DNS/TRI、改成绩)都改在新对象上,
            //   而中间这块面板画的是旧对象 —— 界面上【一点反应都没有】, 大屏却是对的。
            //   现场就是这么撞出来的: 确认成绩(回推主服务器→主服务器推整包回来)之后
            //   再判罚, 面板不标注, 大屏要等下一次确认才显示。
            //   这里按道次重新认一遍人, 便宜(十来个引用赋值), 且把这类问题一次性了结。
            foreach (var rowUI in _laneRowUIs) {
                Swimmer cur;
                laneSwimmerMap.TryGetValue(rowUI.Lane, out cur);
                if (!ReferenceEquals(rowUI.Swimmer, cur)) rowUI.Swimmer = cur;
            }
            RefreshLaneRows(currentSwimmers);
            UpdateTimingSourceInfo();
        }

        private void BuildLaneRows(List<int> allPoolLanes, Dictionary<int, Swimmer> laneSwimmerMap) {
            LanePanel.Children.Clear();
            _laneRowUIs.Clear();
            bool isRelay = _isRelay;

            foreach (int ln in allPoolLanes) {
                int lane = ln;
                Swimmer sw;
                laneSwimmerMap.TryGetValue(lane, out sw);
                var rowUI = new LaneRowUI { Lane = lane, Swimmer = sw };

                var row = new Border {
                    Background = _brushDark,
                    CornerRadius = new CornerRadius(4), Margin = new Thickness(0, 0, 0, 4),
                    Height = 48, BorderThickness = new Thickness(0)
                };
                rowUI.Row = row;

                var grid = new Grid();
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(32) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(8) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(264) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(264) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(8) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(284) });

                // Col 0: 道次（静态）
                var laneNum = new TextBlock { Text = lane.ToString(), FontSize = 18, FontWeight = FontWeights.Bold, Foreground = _brushGray, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                Grid.SetColumn(laneNum, 0); grid.Children.Add(laneNum);

                // Col 1: 左发令指示（动态：背景色）
                var leftInd = new Border { Width = 8, CornerRadius = new CornerRadius(2), Margin = new Thickness(0, 2, 0, 2) };
                Grid.SetColumn(leftInd, 1); grid.Children.Add(leftInd);
                rowUI.LeftSignalInd = leftInd;

                // Col 2: 左设备（T按钮 + 5圆点 + 剩余秒数）
                var leftDev = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(2, 0, 0, 0) };
                var touchL = new Button { Content = "T", Width = 80, Height = 26, FontSize = 14, BorderThickness = new Thickness(0),
                    ToolTip = Loc.T("Str_Tooltip_TouchLane") };
                int capLane = lane;
                // 2026-06-06 防误操作: T 按钮左键禁用, 改为右键触发手动 TP
                touchL.PreviewMouseLeftButtonDown += delegate(object s1, System.Windows.Input.MouseButtonEventArgs e1) {
                    e1.Handled = true;
                };
                touchL.PreviewMouseRightButtonDown += delegate(object sR1, System.Windows.Input.MouseButtonEventArgs eR1) {
                    eR1.Handled = true;
                    //2026-05-31 应急按键守卫: 仅看 LeftManualEnabled (参数设置), 不受 TP 状态/比赛流程影响
                    if (capLane >= 0 && capLane < _laneDeviceStates.Count && !_laneDeviceStates[capLane].LeftManualEnabled) return;
                    HandleTimingCommand(Newtonsoft.Json.Linq.JObject.FromObject(new { command = "MANUAL_TOUCH_LEFT", data = new { lane = capLane } }));
                };
                leftDev.Children.Add(touchL);
                rowUI.TouchL = touchL;

                // 左端 5 指示灯：[0]=盲3, [1]=盲2, [2]=盲1, [3]=出发, [4]=触板（与右端对称）
                // 2026-06-16 形状区分: 盲表=圆 (18), 出发台=正方形 (22x22 圆角4), 触板=竖向窄条 (7x36)
                // 创建时即按当前 LeftBlindWatchCount 设置 Visibility，避免初始一闪而过
                int initLbc = _laneCloseSettings.LeftBlindWatchCount;
                rowUI.LeftDots = new Shape[5];
                for (int i = 0; i < 5; i++) {
                    Shape dot;
                    if (i == 3) {
                        // 出发台: 22x22 圆角正方形
                        dot = new Rectangle { Width = 22, Height = 22, RadiusX = 4, RadiusY = 4, Margin = new Thickness(2, 0, 2, 0) };
                    } else if (i == 4) {
                        // 触板: 7x36 竖向窄条
                        dot = new Rectangle { Width = 7, Height = 36, Margin = new Thickness(2, 0, 2, 0) };
                    } else {
                        // 盲表: 直径 18 圆形
                        dot = new Ellipse { Width = 18, Height = 18, Margin = new Thickness(2, 0, 2, 0) };
                    }
                    if (i == 0) dot.Visibility = initLbc >= 3 ? Visibility.Visible : Visibility.Hidden;
                    else if (i == 1) dot.Visibility = initLbc >= 2 ? Visibility.Visible : Visibility.Hidden;
                    else if (i == 2) dot.Visibility = initLbc >= 1 ? Visibility.Visible : Visibility.Hidden;
                    rowUI.LeftDots[i] = dot;
                    leftDev.Children.Add(dot);
                }

                // 圈数 [数字 + ▲▼ 微调]：左端（spinner 风格，更简洁美观）
