                leftDev.Children.Add(leftRemainText);
                rowUI.LeftRemainText = leftRemainText;
                var leftSpinner = new StackPanel { Orientation = Orientation.Vertical, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 0, 0) };
                var leftLapUp = new Button { Content = "▲", Width = 18, Height = 13, FontSize = 9, BorderThickness = new Thickness(0), Background = _brushSlate, Foreground = Brushes.White, Padding = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand };
                leftLapUp.PreviewMouseLeftButtonDown += delegate(object s1, System.Windows.Input.MouseButtonEventArgs e1) { e1.Handled = true; AdjustLapDisplay(capLane, true, +1); };
                var leftLapDown = new Button { Content = "▼", Width = 18, Height = 13, FontSize = 9, BorderThickness = new Thickness(0), Background = _brushSlate, Foreground = Brushes.White, Padding = new Thickness(0), Margin = new Thickness(0, 1, 0, 0), Cursor = System.Windows.Input.Cursors.Hand };
                leftLapDown.PreviewMouseLeftButtonDown += delegate(object s1, System.Windows.Input.MouseButtonEventArgs e1) { e1.Handled = true; AdjustLapDisplay(capLane, true, -1); };
                leftSpinner.Children.Add(leftLapUp);
                leftSpinner.Children.Add(leftLapDown);
                leftDev.Children.Add(leftSpinner);
                Grid.SetColumn(leftDev, 2); grid.Children.Add(leftDev);

                // Col 3: 姓名 + 进度条
                var midPanel = new DockPanel { VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(6, 0, 6, 0) };
                var infoStack = new StackPanel { Width = 120 };
                if (sw == null) row.Opacity = 0.35;
                // 姓名 + 队伍/棒次 两行 — 真实文字在 RefreshLaneRows 中按当前棒次实时更新
                var nameTb = new TextBlock { Text = "", FontWeight = FontWeights.Bold, Foreground = Brushes.White, FontSize = 14 };
                var teamTb = new TextBlock { Text = "", Foreground = _brushMutedText, FontSize = 12 };
                infoStack.Children.Add(nameTb);
                infoStack.Children.Add(teamTb);
                rowUI.NameText = nameTb;
                rowUI.TeamText = teamTb;
                DockPanel.SetDock(infoStack, Dock.Left); midPanel.Children.Add(infoStack);

                var trackBorder = new Border { Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1A2332")), CornerRadius = new CornerRadius(4), Height = 22, Padding = new Thickness(4, 0, 4, 0), MinWidth = 60 };
                var trackText = new TextBlock { FontFamily = new FontFamily("Consolas"), FontSize = 14, VerticalAlignment = VerticalAlignment.Center };
                trackBorder.Child = trackText;
                midPanel.Children.Add(trackBorder);
                rowUI.TrackText = trackText;
                Grid.SetColumn(midPanel, 3); grid.Children.Add(midPanel);

                // Col 4: 右设备
                var rightDev = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                // 圈数 [▲▼ 微调 + 数字]：右端（spinner 风格）
                var rightSpinner = new StackPanel { Orientation = Orientation.Vertical, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 0, 0) };
                var rightLapUp = new Button { Content = "▲", Width = 18, Height = 13, FontSize = 9, BorderThickness = new Thickness(0), Background = _brushSlate, Foreground = Brushes.White, Padding = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand };
                rightLapUp.PreviewMouseLeftButtonDown += delegate(object s1, System.Windows.Input.MouseButtonEventArgs e1) { e1.Handled = true; AdjustLapDisplay(capLane, false, +1); };
                var rightLapDown = new Button { Content = "▼", Width = 18, Height = 13, FontSize = 9, BorderThickness = new Thickness(0), Background = _brushSlate, Foreground = Brushes.White, Padding = new Thickness(0), Margin = new Thickness(0, 1, 0, 0), Cursor = System.Windows.Input.Cursors.Hand };
                rightLapDown.PreviewMouseLeftButtonDown += delegate(object s2, System.Windows.Input.MouseButtonEventArgs e2) { e2.Handled = true; AdjustLapDisplay(capLane, false, -1); };
                rightSpinner.Children.Add(rightLapUp);
                rightSpinner.Children.Add(rightLapDown);
                rightDev.Children.Add(rightSpinner);
                var rightRemainText = new TextBlock { Width = 26, FontSize = 18, FontWeight = FontWeights.Bold, TextAlignment = TextAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                rightDev.Children.Add(rightRemainText);
                rowUI.RightRemainText = rightRemainText;

                // 右端 5 指示灯：[0]=触板, [1]=出发, [2]=盲1, [3]=盲2, [4]=盲3
                // 2026-06-16 形状区分: 触板=竖向窄条 (7x36), 出发台=正方形 (22x22 圆角4), 盲表=圆 (18)
                int initRbc = _laneCloseSettings.RightBlindWatchCount;
                rowUI.RightDots = new Shape[5];
                for (int i = 0; i < 5; i++) {
                    Shape dot;
                    if (i == 0) {
                        // 触板: 7x36 竖向窄条
                        dot = new Rectangle { Width = 7, Height = 36, Margin = new Thickness(2, 0, 2, 0) };
                    } else if (i == 1) {
                        // 出发台: 22x22 圆角正方形
                        dot = new Rectangle { Width = 22, Height = 22, RadiusX = 4, RadiusY = 4, Margin = new Thickness(2, 0, 2, 0) };
                    } else {
                        // 盲表: 直径 18 圆形
                        dot = new Ellipse { Width = 18, Height = 18, Margin = new Thickness(2, 0, 2, 0) };
                    }
                    if (i == 2) dot.Visibility = initRbc >= 1 ? Visibility.Visible : Visibility.Hidden;
                    else if (i == 3) dot.Visibility = initRbc >= 2 ? Visibility.Visible : Visibility.Hidden;
                    else if (i == 4) dot.Visibility = initRbc >= 3 ? Visibility.Visible : Visibility.Hidden;
                    rowUI.RightDots[i] = dot;
                    rightDev.Children.Add(dot);
                }

                var touchR = new Button { Content = "T", Width = 80, Height = 26, FontSize = 14, BorderThickness = new Thickness(0),
                    ToolTip = Loc.T("Str_Tooltip_TouchLane") };
                // 2026-06-06 防误操作: T 按钮左键禁用, 改为右键触发手动 TP
                touchR.PreviewMouseLeftButtonDown += delegate(object s2, System.Windows.Input.MouseButtonEventArgs e2) {
                    e2.Handled = true;
                };
                touchR.PreviewMouseRightButtonDown += delegate(object sR2, System.Windows.Input.MouseButtonEventArgs eR2) {
                    eR2.Handled = true;
                    //2026-05-31 应急按键守卫: 仅看 RightManualEnabled
                    if (capLane >= 0 && capLane < _laneDeviceStates.Count && !_laneDeviceStates[capLane].RightManualEnabled) return;
                    HandleTimingCommand(Newtonsoft.Json.Linq.JObject.FromObject(new { command = "MANUAL_TOUCH_RIGHT", data = new { lane = capLane } }));
                };
                rightDev.Children.Add(touchR);
                rowUI.TouchR = touchR;
                Grid.SetColumn(rightDev, 4); grid.Children.Add(rightDev);

                // Col 5: 右发令指示
                var rightInd = new Border { Width = 8, CornerRadius = new CornerRadius(2), Margin = new Thickness(0, 2, 0, 2) };
                Grid.SetColumn(rightInd, 5); grid.Children.Add(rightInd);
                rowUI.RightSignalInd = rightInd;

                // Col 6: 成绩信息（反应时/盲表 + 成绩 + 名次 + 备注）
                var infoArea = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                // 2026-06-16 反应时改上下两行: 上行反应时(保留) + 下行盲表历史 ComboBox(最新在顶)
                // 宽度 55→90 容纳盲表时分秒格式 "1:25:42.78"
                var reactionStack = new StackPanel { Orientation = Orientation.Vertical, Width = 90, VerticalAlignment = VerticalAlignment.Center };
                var reactionText = new TextBlock { FontSize = 13, Foreground = Brushes.White, TextAlignment = TextAlignment.Center, FontFamily = new FontFamily("Consolas"), Height = 20 };
                reactionStack.Children.Add(reactionText);
                // 2026-06-18 黑底 + 白字 (用户指定)
                //   WPF Aero ComboBox 默认 Template 会覆盖 Background, 这里注入极简自定义 Template:
                //     主体 = 黑 Border + ToggleButton (覆盖打开/关闭), 显示选中项 = ContentPresenter,
                //     下拉 = Popup 黑底 ScrollViewer 包 ItemsHost
                var _brushBlindBg = (Brush)Brushes.Black;
                var _brushBlindFg = (Brush)Brushes.White;
                var blindCombo = new ComboBox { Height = 20, FontSize = 11, FontFamily = new FontFamily("Consolas"), Foreground = _brushBlindFg, BorderThickness = new Thickness(0), Padding = new Thickness(0), Margin = new Thickness(0), HorizontalContentAlignment = HorizontalAlignment.Center, Background = _brushBlindBg };
                try {
                    string tplXaml = "<ControlTemplate TargetType='ComboBox' xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'>"
                        + "<Grid>"
                        + "<ToggleButton x:Name='Tb' Focusable='False' ClickMode='Press' Background='Black' IsChecked='{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}'>"
                            + "<ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border Background='Black' BorderThickness='0'/></ControlTemplate></ToggleButton.Template>"
                        + "</ToggleButton>"
                        + "<ContentPresenter IsHitTestVisible='False' HorizontalAlignment='Center' VerticalAlignment='Center' Margin='4,1,4,1' Content='{TemplateBinding SelectionBoxItem}' ContentTemplate='{TemplateBinding SelectionBoxItemTemplate}' ContentTemplateSelector='{TemplateBinding ItemTemplateSelector}' TextBlock.Foreground='White'/>"
                        + "<Popup IsOpen='{TemplateBinding IsDropDownOpen}' Placement='Bottom' Focusable='False' AllowsTransparency='True' PopupAnimation='Slide'>"
                            + "<Border Background='Black' BorderBrush='#475569' BorderThickness='1' MinWidth='{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}' MaxHeight='{TemplateBinding MaxDropDownHeight}'>"
                                + "<ScrollViewer><StackPanel IsItemsHost='True' Background='Black'/></ScrollViewer>"
                            + "</Border>"
                        + "</Popup>"
                        + "</Grid>"
                        + "</ControlTemplate>";
                    blindCombo.Template = (ControlTemplate)System.Windows.Markup.XamlReader.Parse(tplXaml);
                } catch { }
                {
                    var itemDt = new DataTemplate();
                    var tbFactory = new FrameworkElementFactory(typeof(TextBlock));
                    tbFactory.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("."));
                    tbFactory.SetValue(TextBlock.ForegroundProperty, _brushBlindFg);
                    tbFactory.SetValue(TextBlock.HorizontalAlignmentProperty, HorizontalAlignment.Center);
                    itemDt.VisualTree = tbFactory;
                    blindCombo.ItemTemplate = itemDt;
                    var itemStyle = new Style(typeof(ComboBoxItem));
                    itemStyle.Setters.Add(new Setter(ComboBoxItem.ForegroundProperty, _brushBlindFg));
                    itemStyle.Setters.Add(new Setter(ComboBoxItem.BackgroundProperty, _brushBlindBg));
                    itemStyle.Setters.Add(new Setter(ComboBoxItem.PaddingProperty, new Thickness(4, 1, 4, 1)));
                    blindCombo.ItemContainerStyle = itemStyle;
                }
                reactionStack.Children.Add(blindCombo);
                infoArea.Children.Add(reactionStack);
                rowUI.ReactionText = reactionText;
                rowUI.BlindCombo = blindCombo;

                var displayTimeText = new TextBlock { Width = 110, FontSize = 17, FontWeight = FontWeights.Bold, Foreground = Brushes.White, TextAlignment = TextAlignment.Center, FontFamily = new FontFamily("Consolas") };
                infoArea.Children.Add(displayTimeText);
                rowUI.DisplayTimeText = displayTimeText;

                var rankText = new TextBlock { Width = 44, FontSize = 18, FontWeight = FontWeights.Bold, TextAlignment = TextAlignment.Center };
                infoArea.Children.Add(rankText);
                rowUI.RankText = rankText;

                var remarkText = new TextBlock { Width = 40, FontSize = 13, FontWeight = FontWeights.Bold, Foreground = _brushRed, TextAlignment = TextAlignment.Center };
                infoArea.Children.Add(remarkText);
                rowUI.RemarkText = remarkText;

                Grid.SetColumn(infoArea, 6); grid.Children.Add(infoArea);

                row.Child = grid;
                int clickLane = lane;
                row.MouseLeftButtonDown += delegate {
                    _selectedLane = clickLane;
                    _lastTsSplitCount = -1;
                    if (LaneInputBox != null) LaneInputBox.Text = clickLane.ToString();
                    UpdateTimingSourceInfo();
                    RefreshLaneRows(GetCurrentHeatSwimmers());
                    try { RefreshLaneEventLogView(); } catch { }   // 2026-05-27 同步"比赛日志" tab
                };
                LanePanel.Children.Add(row);
                _laneRowUIs.Add(rowUI);
            }
        }

        /// <summary>
        /// 计算当前组运动员的实时分段名次
        /// 规则：DSQ/DNS/DNF 无名次；已完赛按 FinalTime；未完赛按 (有效分段数 DESC, 最后累计时间 ASC)
        /// </summary>
        // 2026-06-05 U 系列规则: 组内只按时间排单一名次 (不再按性别拆), 总排名才按 性别×组别 拆.
        // (回退 2026-06-04 同组双 1 名次的设计, 避免 大屏出现 两个第1名 / 两个第2名)
        // 2026-06-06 P1-B: 50ms 单帧缓存 — RefreshLaneRows + GetStatusData 同一 Tick 都调一次,
        //   两次入参 swimmers 实际相同, 复用结果可少一次 O(N log N) 排序 + List<Tuple> 分配.
        private Dictionary<Swimmer, int> _liveRanksCache = null;
        private DateTime _liveRanksCacheAt = DateTime.MinValue;
        private const int LIVE_RANKS_CACHE_TTL_MS = 50;
        private Dictionary<Swimmer, int> ComputeLiveRanks(IEnumerable<Swimmer> swimmers) {
            if (_liveRanksCache != null && (DateTime.Now - _liveRanksCacheAt).TotalMilliseconds < LIVE_RANKS_CACHE_TTL_MS) {
                return _liveRanksCache;
            }
            var liveRanks = new Dictionary<Swimmer, int>();
            var rankables = new List<Tuple<Swimmer, int, double, bool>>(); // (swimmer, splitCount, cumTime/FinalTime, finished)
            foreach (var sw2 in swimmers) {
                string st = sw2.Status ?? "";
                // 2026-06-04 TRI 不参与排名 (= 不进 rankables, 也不影响其他人 rank)
                if (st == "DSQ" || st == "DNS" || st == "DNF" || st == "TRI") continue;
                var r2 = sw2.Results.FirstOrDefault(lr => lr.Stage == _currentStage && lr.Heat == _currentHeat);
                if (r2 == null) continue;

                // 查找最后一个有效分段（CumulativeTime > 0）
                int validSplits = 0;
                double lastCum = 0;
                for (int i = r2.Splits.Count - 1; i >= 0; i--) {
                    if (r2.Splits[i].CumulativeTime > 0) {
                        validSplits = r2.Splits[i].Lap;
                        lastCum = r2.Splits[i].CumulativeTime;
                        break;
                    }
                }
                bool fin = r2.FinalTime > 0;
                double sortTime = fin ? r2.FinalTime : lastCum;
                if (validSplits == 0 && !fin) continue; // 无任何分段数据
                rankables.Add(Tuple.Create(sw2, validSplits, sortTime, fin));
            }
            rankables.Sort((a, b) => {
                if (a.Item4 != b.Item4) return a.Item4 ? -1 : 1; // 已完赛优先
                if (a.Item4) return a.Item3.CompareTo(b.Item3);  // 都完赛：FinalTime升序
                int c = b.Item2.CompareTo(a.Item2);              // 分段数降序
                if (c != 0) return c;
                return a.Item3.CompareTo(b.Item3);               // 累计时间升序
            });
            // 并列名次（competition ranking 1-2-2-4 标准）:
            //   已完赛 vs 已完赛: FinalTime 相同则并列
            //   未完赛 vs 未完赛: 同样分段数且累计时间相同则并列 (2026-06-01 新增, 之前只判完赛)
            //   一完一未完: 永不并列
            int rank = 1;
            for (int i = 0; i < rankables.Count; i++) {
                if (i > 0) {
                    var prev = rankables[i - 1];
                    var cur = rankables[i];
                    bool tieEligible;
                    if (prev.Item4 && cur.Item4) {
                        tieEligible = IsTieTime(prev.Item3, cur.Item3);
                    } else if (!prev.Item4 && !cur.Item4) {
                        tieEligible = (prev.Item2 == cur.Item2) && IsTieTime(prev.Item3, cur.Item3);
                    } else {
                        tieEligible = false;
                    }
                    if (!tieEligible) rank = i + 1;
                }
                liveRanks[rankables[i].Item1] = rank;
            }
            _liveRanksCache = liveRanks;
            _liveRanksCacheAt = DateTime.Now;
            return liveRanks;
        }

        private void RefreshLaneRows(List<Swimmer> currentSwimmers) {
            double splitDisplaySec = _laneCloseSettings.SplitDisplayTime > 0 ? _laneCloseSettings.SplitDisplayTime : 5;
            bool leftStart = _laneCloseSettings.StartPosition == "left";

            // 实时分段名次
            var liveRanks = ComputeLiveRanks(_laneRowUIs.Select(r => r.Swimmer).Where(s => s != null));

            foreach (var rowUI in _laneRowUIs) {
                var sw = rowUI.Swimmer;
                int lane = rowUI.Lane;
                var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                // 空泳道：仅保留淡化效果，所有状态/成绩字段清空
                // 例外：设备测试模式下要按真实设备状态涂色，否则用户看不到 Open / Touched
                if (sw == null) {
                    rowUI.Row.BorderThickness = _thickness0;
                    // 测试模式：左端事件贴到姓名栏，右端事件贴到成绩栏（比 Remain 框宽很多）
                    if (_testMode) {
                        string leftEvtName = _testLastEventLeft.ContainsKey(lane) ? _testLastEventLeft[lane] : "";
                        if (rowUI.NameText != null) {
                            rowUI.NameText.Text = leftEvtName;
                            rowUI.NameText.Foreground = leftEvtName.Length > 0 ? (Brush)_brushAmber : (Brush)_brushMutedText;
                        }
                    } else {
                        if (rowUI.NameText != null) {
                            rowUI.NameText.Text = Loc.T("Str_Label_EmptyLaneParen");
                            rowUI.NameText.Foreground = _brushMutedText;
                        }
                    }
                    if (rowUI.TeamText != null) rowUI.TeamText.Text = "";
                    // 测试模式下按真实状态涂色，正常空道全部置灰
                    if (rowUI.LeftDots != null && ls != null) {
                        if (_testMode) {
                            // 2026-05-31 改用 StyleDotMixed: 业务 NotInstalled/Broken 优先, 否则 Hw*Color 渲染
                            StyleDotMixed(rowUI.LeftDots[0], ls.HwLeftBlindWatch3Color, ls.LeftBlindWatch3Status, DotDeviceType.Mb);
                            StyleDotMixed(rowUI.LeftDots[1], ls.HwLeftBlindWatch2Color, ls.LeftBlindWatch2Status, DotDeviceType.Mb);
                            StyleDotMixed(rowUI.LeftDots[2], ls.HwLeftBlindWatch1Color, ls.LeftBlindWatch1Status, DotDeviceType.Mb);
                            StyleDotMixed(rowUI.LeftDots[3], ls.HwLeftStartBlockColor, ls.LeftStartBlockStatus, DotDeviceType.Sb);
                            StyleDotMixed(rowUI.LeftDots[4], ls.HwLeftTouchpadColor, ls.LeftTouchpadStatus, DotDeviceType.Tp);
                        } else {
                            for (int i = 0; i < rowUI.LeftDots.Length; i++) rowUI.LeftDots[i].Fill = _brushSlate;
                        }
                    }
                    if (rowUI.RightDots != null && ls != null) {
                        if (_testMode) {
                            StyleDotMixed(rowUI.RightDots[0], ls.HwRightTouchpadColor, ls.RightTouchpadStatus, DotDeviceType.Tp);
                            StyleDotMixed(rowUI.RightDots[1], ls.HwRightStartBlockColor, ls.RightStartBlockStatus, DotDeviceType.Sb);
                            StyleDotMixed(rowUI.RightDots[2], ls.HwRightBlindWatch1Color, ls.RightBlindWatch1Status, DotDeviceType.Mb);
                            StyleDotMixed(rowUI.RightDots[3], ls.HwRightBlindWatch2Color, ls.RightBlindWatch2Status, DotDeviceType.Mb);
                            StyleDotMixed(rowUI.RightDots[4], ls.HwRightBlindWatch3Color, ls.RightBlindWatch3Status, DotDeviceType.Mb);
                        } else {
                            for (int i = 0; i < rowUI.RightDots.Length; i++) rowUI.RightDots[i].Fill = _brushSlate;
                        }
                    }
                    // 空泳道也要按当前盲表数量隐藏多余圆点
                    if (rowUI.LeftDots != null) {
                        int lbc0 = _laneCloseSettings.LeftBlindWatchCount;
                        rowUI.LeftDots[0].Visibility = lbc0 >= 3 ? Visibility.Visible : Visibility.Hidden; // 盲3
                        rowUI.LeftDots[1].Visibility = lbc0 >= 2 ? Visibility.Visible : Visibility.Hidden; // 盲2
                        rowUI.LeftDots[2].Visibility = lbc0 >= 1 ? Visibility.Visible : Visibility.Hidden; // 盲1
                    }
                    if (rowUI.RightDots != null) {
                        int rbc0 = _laneCloseSettings.RightBlindWatchCount;
                        rowUI.RightDots[2].Visibility = rbc0 >= 1 ? Visibility.Visible : Visibility.Hidden; // 盲1
                        rowUI.RightDots[3].Visibility = rbc0 >= 2 ? Visibility.Visible : Visibility.Hidden; // 盲2
                        rowUI.RightDots[4].Visibility = rbc0 >= 3 ? Visibility.Visible : Visibility.Hidden; // 盲3
                    }
                    // Remain 框（赛中倒计时位置）测试模式下不再用，统一清空
                    if (rowUI.LeftRemainText != null) rowUI.LeftRemainText.Text = "";
                    if (rowUI.RightRemainText != null) rowUI.RightRemainText.Text = "";
                    if (rowUI.ReactionText != null) rowUI.ReactionText.Text = "";
                    // 测试模式：右端事件贴到成绩栏（DisplayTimeText）；正常空道清空
                    if (rowUI.DisplayTimeText != null) {
                        if (_testMode) {
                            string rightEvtTime = _testLastEventRight.ContainsKey(lane) ? _testLastEventRight[lane] : "";
                            rowUI.DisplayTimeText.Text = rightEvtTime;
                            rowUI.DisplayTimeText.Foreground = rightEvtTime.Length > 0 ? (Brush)_brushAmber : (Brush)_brushMutedText;
                        } else {
                            rowUI.DisplayTimeText.Text = "";
                        }
                    }
                    if (rowUI.RankText != null) rowUI.RankText.Text = "";
                    if (rowUI.RemarkText != null) rowUI.RemarkText.Text = "";
                    if (rowUI.TrackText != null) rowUI.TrackText.Text = "";
                    if (rowUI.TouchL != null) { rowUI.TouchL.Background = _brushDark; rowUI.TouchL.Foreground = _brushSlate; }
                    if (rowUI.TouchR != null) { rowUI.TouchR.Background = _brushDark; rowUI.TouchR.Foreground = _brushSlate; }
                    // 2026-05-26 空泳道也要按当前 StartPosition 更新左右发令指示灯 (此前只占用 lane 的行会更新, 空道会停在 BuildLaneRows 时的初值)
                    if (rowUI.LeftSignalInd != null) rowUI.LeftSignalInd.Background = leftStart ? (Brush)_brushGreen : Brushes.Transparent;
                    if (rowUI.RightSignalInd != null) rowUI.RightSignalInd.Background = !leftStart ? (Brush)_brushGreen : Brushes.Transparent;
                    continue;
                }
                var result = sw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                // 已记录最终成绩的运动员（即便 LaneDeviceState.IsFinished 因切组被复位）也算作完赛
                bool isFinished = (ls != null && ls.IsFinished) || (result != null && result.FinalTime > 0);
                // 2026-09-13 备注栏改用 GetEffectiveStatus(成绩行优先, 退回运动员那份)。
                //   判罚状态在内存里存了两处(运动员 sw.Status + 成绩行 r.Status), 而这块面板
                //   原来只认 sw.Status —— 某条回填路径只写了成绩行那一份时, 备注栏就空了
                //   (现场: 确认成绩之后再看, 成绩名次都在, DNS/DNF/DSQ/TRI 没了)。
                //   大屏那条路(BuildSwimmerPayload)早就用这个helper了, 面板一直没跟上。
                string status = GetEffectiveStatus(sw, result);
                bool isDQ = status == "DSQ" || status == "DNS" || status == "DNF";

                // 姓名/队伍 — 个人项目: 姓名+代表队；接力项目: 代表队 + 第N棒:运动员
                if (rowUI.NameText != null && rowUI.TeamText != null) {
                    if (_isRelay) {
                        rowUI.NameText.Text = sw.Country ?? "";
                        // 用 spinner 偏移后的圈数，让"加圈/减圈"即时切换棒次显示
                        rowUI.TeamText.Text = ComputeRelayCurrentLegLabel(sw, GetDisplayedCurrentLap(ls), isFinished);
                    } else {
                        rowUI.NameText.Text = sw.Name ?? "";
                        rowUI.TeamText.Text = sw.Country ?? "";
                    }
                }
                // DSQ/DNS/DNF 行淡化
                rowUI.Row.Opacity = isDQ ? 0.45 : 1.0;

                // 行边框（已判罚抢跳=DSQ高亮，疑似抢跳=琥珀色提示，选中=蓝色）
                if (ls != null && ls.IsFalseStart) {
                    rowUI.Row.BorderBrush = _brushAmber;
                    rowUI.Row.BorderThickness = _thickness2;
                } else if (ls != null && ls.IsSuspectFalseStart) {
                    rowUI.Row.BorderBrush = _brushAmber;
                    rowUI.Row.BorderThickness = _thickness2;
                } else if (lane == _selectedLane) {
                    rowUI.Row.BorderBrush = _brushBlue;
                    rowUI.Row.BorderThickness = _thickness2;
                } else {
                    rowUI.Row.BorderThickness = _thickness0;
                }

                // 左右发令指示
                rowUI.LeftSignalInd.Background = leftStart ? (Brush)_brushGreen : Brushes.Transparent;
                rowUI.RightSignalInd.Background = !leftStart ? (Brush)_brushGreen : Brushes.Transparent;

                // 左T按钮 — 2026-05-31 应急按键设计:
                //   "参数设置" LeftManualEnabled=true  → 始终绿, 始终可点 (应急用, 不受 TP 状态/比赛流程影响)
                //   LeftManualEnabled=false → 始终灰禁用
                bool leftManualOn = ls == null || ls.LeftManualEnabled;
                if (leftManualOn) {
                    rowUI.TouchL.Background = _brushGreen;
                    rowUI.TouchL.Foreground = Brushes.White;
                } else {
                    rowUI.TouchL.Background = _brushDark;
                    rowUI.TouchL.Foreground = _brushSlate;
                }

                // 左设备5个圆点（与右端对称）：盲表3 / 盲表2 / 盲表1 / 出发台 / 触板
                if (ls != null) {
                    // 2026-05-31 正常行渲染也改用 StyleDotMixed
                    StyleDotMixed(rowUI.LeftDots[0], ls.HwLeftBlindWatch3Color, ls.LeftBlindWatch3Status, DotDeviceType.Mb);
                    StyleDotMixed(rowUI.LeftDots[1], ls.HwLeftBlindWatch2Color, ls.LeftBlindWatch2Status, DotDeviceType.Mb);
                    StyleDotMixed(rowUI.LeftDots[2], ls.HwLeftBlindWatch1Color, ls.LeftBlindWatch1Status, DotDeviceType.Mb);
                    StyleDotMixed(rowUI.LeftDots[3], ls.HwLeftStartBlockColor, ls.LeftStartBlockStatus, DotDeviceType.Sb);
                    StyleDotMixed(rowUI.LeftDots[4], ls.HwLeftTouchpadColor, ls.LeftTouchpadStatus, DotDeviceType.Tp);
                    // 2026-06-06 终点 TP/MB 差 > 0.5s — 终点端 TP + 3 MB 强制涂红 (索引 0/1/2 = MB3/2/1, 4 = TP)
                    if (ls.FinishTpMbDispute && _laneCloseSettings != null && _laneCloseSettings.FinishPosition == "left") {
                        rowUI.LeftDots[0].Fill = _brushRed;
                        rowUI.LeftDots[1].Fill = _brushRed;
                        rowUI.LeftDots[2].Fill = _brushRed;
                        rowUI.LeftDots[4].Fill = _brushRed;
                    }
                } else {
                    for (int i = 0; i < 5; i++) rowUI.LeftDots[i].Fill = _brushSlate;
                }
                // 按当前设置的左盲表数量隐藏多余圆点（保留位置：用 Hidden 而非 Collapsed
                // 这样盲1 / 出发台 / 触板的位置固定不变）
                int leftBwCount = _laneCloseSettings.LeftBlindWatchCount;
                rowUI.LeftDots[0].Visibility = leftBwCount >= 3 ? Visibility.Visible : Visibility.Hidden; // 盲3
                rowUI.LeftDots[1].Visibility = leftBwCount >= 2 ? Visibility.Visible : Visibility.Hidden; // 盲2
                rowUI.LeftDots[2].Visibility = leftBwCount >= 1 ? Visibility.Visible : Visibility.Hidden; // 盲1

                // 左剩余圈数（含 spinner 人工偏移）
                int leftRemain = GetDisplayedLapCount(ls, true);
                rowUI.LeftRemainText.Text = leftRemain > 0 ? leftRemain.ToString() : "0";
                rowUI.LeftRemainText.Foreground = leftRemain > 0 ? (Brush)_brushAmber : (Brush)_brushSlate;

                // 右T按钮
                // 右T按钮 — 应急按键, 同左
                bool rightManualOn = ls == null || ls.RightManualEnabled;
                if (rightManualOn) {
                    rowUI.TouchR.Background = _brushGreen;
                    rowUI.TouchR.Foreground = Brushes.White;
                } else {
                    rowUI.TouchR.Background = _brushDark;
                    rowUI.TouchR.Foreground = _brushSlate;
                }

                // 右设备5个圆点：Touchpad, StartBlock, BlindWatch1/2/3
                if (ls != null) {
                    StyleDotMixed(rowUI.RightDots[0], ls.HwRightTouchpadColor, ls.RightTouchpadStatus, DotDeviceType.Tp);
                    StyleDotMixed(rowUI.RightDots[1], ls.HwRightStartBlockColor, ls.RightStartBlockStatus, DotDeviceType.Sb);
                    StyleDotMixed(rowUI.RightDots[2], ls.HwRightBlindWatch1Color, ls.RightBlindWatch1Status, DotDeviceType.Mb);
                    StyleDotMixed(rowUI.RightDots[3], ls.HwRightBlindWatch2Color, ls.RightBlindWatch2Status, DotDeviceType.Mb);
                    StyleDotMixed(rowUI.RightDots[4], ls.HwRightBlindWatch3Color, ls.RightBlindWatch3Status, DotDeviceType.Mb);
                    // 2026-06-06 终点 TP/MB 差 > 0.5s — 终点端 TP + 3 MB 强制涂红 (索引 0 = TP, 2/3/4 = MB1/2/3)
                    if (ls.FinishTpMbDispute && _laneCloseSettings != null && _laneCloseSettings.FinishPosition == "right") {
                        rowUI.RightDots[0].Fill = _brushRed;
                        rowUI.RightDots[2].Fill = _brushRed;
                        rowUI.RightDots[3].Fill = _brushRed;
                        rowUI.RightDots[4].Fill = _brushRed;
                    }
                } else {
                    for (int i = 0; i < 5; i++) rowUI.RightDots[i].Fill = _brushSlate;
                }
                // 按当前设置的右盲表数量隐藏多余圆点（保留位置）
                int rightBwCount = _laneCloseSettings.RightBlindWatchCount;
                rowUI.RightDots[2].Visibility = rightBwCount >= 1 ? Visibility.Visible : Visibility.Hidden;
                rowUI.RightDots[3].Visibility = rightBwCount >= 2 ? Visibility.Visible : Visibility.Hidden;
                rowUI.RightDots[4].Visibility = rightBwCount >= 3 ? Visibility.Visible : Visibility.Hidden;

                // 右剩余圈数（含 spinner 人工偏移）
                int rightRemain = GetDisplayedLapCount(ls, false);
                rowUI.RightRemainText.Text = rightRemain > 0 ? rightRemain.ToString() : "0";
                rowUI.RightRemainText.Foreground = rightRemain > 0 ? (Brush)_brushAmber : (Brush)_brushSlate;

                // 方向/进度文本
                string dir = ls != null ? ls.Direction : "→";
                rowUI.TrackText.HorizontalAlignment = dir == "←" ? HorizontalAlignment.Right : HorizontalAlignment.Left;
                string arrow = dir == "←" ? "◀" : "▶";
                int maxArrows = 8;
                if (isFinished && result != null) {
                    rowUI.TrackText.Text = "== " + TimeFormatter.Format(result.FinalTime) + " ==";
                    rowUI.TrackText.Foreground = _brushAmber;
                } else if (isDQ) {
                    rowUI.TrackText.Text = status;
                    rowUI.TrackText.Foreground = _brushAmber;
                } else if (ls != null && ls.LaneCloseCountdown > 0) {
                    double closeTime = _laneCloseSettings.LaneCloseTime > 0 ? _laneCloseSettings.LaneCloseTime : 20;
                    double elapsed = closeTime - ls.LaneCloseCountdown;
                    double progress = closeTime > 0 ? elapsed / closeTime : 1;
                    int arrowCount = Math.Max(1, (int)Math.Round(progress * maxArrows));
                    if (arrowCount > maxArrows) arrowCount = maxArrows;
                    // 格式：第1个箭头 + 倒计时时间 + 尾部箭头（尾部箭头数量随进度增长）
                    int tailCount = arrowCount > 0 ? arrowCount - 1 : 0;
                    string tailArrows = new string(arrow[0], tailCount);
                    string cdText = string.Format("({0:F1}s)", ls.LaneCloseCountdown);
                    rowUI.TrackText.Text = dir == "←"
                        ? tailArrows + " " + cdText + " " + arrow
                        : arrow + " " + cdText + " " + tailArrows;
                    rowUI.TrackText.Foreground = _brushBlue;
                } else if (ls != null && (ls.CurrentLap > 0 || _raceState == RaceState.Racing)) {
                    rowUI.TrackText.Text = new string(arrow[0], maxArrows);
                    rowUI.TrackText.Foreground = dir == "←" ? (Brush)_brushGreen : (Brush)_brushBlue;
                } else {
                    rowUI.TrackText.Text = "";
                }

                // 分段/成绩显示（带停留时长）
                // 只统计有效分段（CumulativeTime > 0），跳过 PreCreateSplit 创建的空段
                SplitTime lastValidSplit = null;
                int validSplitCount = 0;
                if (result != null) {
                    for (int i = result.Splits.Count - 1; i >= 0; i--) {
                        if (result.Splits[i].CumulativeTime > 0) {
                            lastValidSplit = result.Splits[i];
                            validSplitCount = lastValidSplit.Lap;
                            break;
                        }
                    }
                }
                if (!_laneSplitCount.ContainsKey(lane)) _laneSplitCount[lane] = 0;
                if (!_laneSplitShowTime.ContainsKey(lane)) _laneSplitShowTime[lane] = DateTime.MinValue;
                if (validSplitCount > _laneSplitCount[lane]) {
                    _laneSplitCount[lane] = validSplitCount;
                    _laneSplitShowTime[lane] = DateTime.Now;
                }
                // splitVisible：分段成绩是否在显示时间窗口内（已完赛则一直显示）
                bool splitVisible = (isFinished && result != null && !isDQ) ||
                                    (!isDQ && lastValidSplit != null &&
                                     (DateTime.Now - _laneSplitShowTime[lane]).TotalSeconds < splitDisplaySec);
                string displayTime = "";
                if (splitVisible) {
                    displayTime = (isFinished && result != null && !isDQ)
                        ? TimeFormatter.Format(result.FinalTime)
                        : TimeFormatter.Format(lastValidSplit.CumulativeTime);
                }
                rowUI.DisplayTimeText.Text = displayTime;

                // 名次：与分段成绩同步显示/消隐
                int rank = 0;
                if (splitVisible) {
                    if (liveRanks.ContainsKey(sw)) rank = liveRanks[sw];
                    else if (result != null && result.Rank > 0) rank = result.Rank;
                }
                rowUI.RankText.Text = rank > 0 ? rank.ToString() : "";
                if (rank == 1) rowUI.RankText.Foreground = _brushAmber;
                else if (rank == 2) rowUI.RankText.Foreground = _brushSilver;
                else if (rank == 3) rowUI.RankText.Foreground = _brushBronze;
                else rowUI.RankText.Foreground = Brushes.White;

                // 反应时：首次显示后 splitDisplaySec 秒后消隐，已完赛则一直显示
                // 关闭RT：始终隐藏反应时
                //   2026-06-04 接力赛比赛结束(Finished)后实时 UI 不显 (= 比赛中显当前棒, 结束后只 D 显)
                double reactionVal = (_laneCloseSettings.ReactionTimeEnabled && ls != null
                                       && !(_isRelay && _raceState == RaceState.Finished)) ? ls.ReactionTime : 0;
                // 2026-06-20 NaN 不进 last value 字典 (NaN != NaN 恒 true, 否则每帧都误触发 "新值"; UI 那边也已守 NaN)
                if (_laneCloseSettings.ReactionTimeEnabled && reactionVal != 0 && !double.IsNaN(reactionVal)) {
                    if (!_laneReactionLastValue.ContainsKey(lane) || _laneReactionLastValue[lane] != reactionVal) {
                        _laneReactionLastValue[lane] = reactionVal;
                        _laneReactionShowTime[lane] = DateTime.Now;
                    }
                }
                // 2026-06-20 NaN = 反应时窗口超时未收到 SB → 控制界面"完全不显示"
                //   注意 NaN != 0 返 true (NaN 与任何数比较都返 false), 不加 !IsNaN 守卫会显 "NaN" 文字.
                bool reactionVisible = _laneCloseSettings.ReactionTimeEnabled && reactionVal != 0 && !double.IsNaN(reactionVal) && (
                    isFinished ||
                    (_laneReactionShowTime.ContainsKey(lane) &&
                     (DateTime.Now - _laneReactionShowTime[lane]).TotalSeconds < splitDisplaySec));
                rowUI.ReactionText.Text = reactionVisible ? reactionVal.ToString("F2") : "";
                // 起跳可疑/已判罚：反应时标红
                bool rtRed = _laneCloseSettings.ReactionTimeEnabled && ls != null && (ls.IsSuspectFalseStart || ls.IsFalseStart);
                rowUI.ReactionText.Foreground = rtRed ? _brushRed : Brushes.White;

                // 备注
                // 备注栏：DSQ/DNS/DNF 优先显示；TRI 试游 同款显示；否则显示破/平纪录标识（如 WR / =AR / WR/NR）
                // 2026-06-04 TRI 状态下 备注栏显 "TRI" (红色, 与 DSQ 同款); 但 TRI 不进 isDQ, swimmer 仍正常显成绩
                string remark;
                if (isDQ) remark = status;
                else if (status == "TRI") remark = "TRI";
                else if (result != null && !string.IsNullOrEmpty(result.RecordNote)) remark = result.RecordNote;
                else remark = "";
                rowUI.RemarkText.Text = remark;
                // 破纪录金色高亮; 其它 (DSQ/DNS/DNF/TRI) 红色
                bool hasRecordNote = !isDQ && status != "TRI" && result != null && !string.IsNullOrEmpty(result.RecordNote);
                rowUI.RemarkText.Foreground = hasRecordNote ? _brushAmber : _brushRed;

                // 2026-05-13 设备测试模式：所有泳道（不论是否有运动员）都把每端最近触发的设备时间贴到行上，
                // 左端事件覆盖到 NameText，右端事件覆盖到 DisplayTimeText（与"空泳道"分支同步），
                // 让操作员能在主服务器实时看到"哪条道哪个设备在什么时刻被触发"。
                if (_testMode) {
                    string lEvt = _testLastEventLeft.ContainsKey(lane) ? _testLastEventLeft[lane] : "";
                    string rEvt = _testLastEventRight.ContainsKey(lane) ? _testLastEventRight[lane] : "";
                    if (rowUI.NameText != null && lEvt.Length > 0) {
                        rowUI.NameText.Text = lEvt;
                        rowUI.NameText.Foreground = _brushAmber;
                    }
                    if (rowUI.DisplayTimeText != null && rEvt.Length > 0) {
                        rowUI.DisplayTimeText.Text = rEvt;
                        rowUI.DisplayTimeText.Foreground = _brushAmber;
                    }
                }
            }
        }

        // ═══════ 计时源对比 ═══════
        private void SplitSelect_Changed(object sender, SelectionChangedEventArgs e) {
            if (TimingSourceInfo == null) return;
            ShowTimingSourceData();
        }

        private void UpdateTimingSourceInfo() {
            if (TimingSourceInfo == null || SplitSelectCombo == null) return;
            if (_selectedLane < 0) { TimingSourceInfo.Text = Loc.T("Str_RC_TimingSourceHint"); return; }

            var currentSwimmers = GetCurrentHeatSwimmers();
            Swimmer targetSw = null;
            int targetLane = _selectedLane;
            foreach (var s in currentSwimmers) {
                var sa = s.GetAssignmentForStage(_currentStage);
                int sLane = sa != null ? sa.Lane : s.Lane;
                if (sLane == targetLane) { targetSw = s; break; }
            }
            if (targetSw == null) { TimingSourceInfo.Text = ""; return; }

            var result = targetSw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            int splitCount = result != null ? result.Splits.Count : 0;

            if (splitCount != _lastTsSplitCount) {
                _lastTsSplitCount = splitCount;
                int prevIdx = SplitSelectCombo.SelectedIndex;
                SplitSelectCombo.SelectionChanged -= SplitSelect_Changed;
                SplitSelectCombo.Items.Clear();
                SplitSelectCombo.Items.Add(Loc.T("Str_RC_SplitFinish"));
                if (result != null) {
                    foreach (var sp in result.Splits) {
                        SplitSelectCombo.Items.Add(Loc.F("Str_RC_TSSplitItemFmt", sp.Lap, sp.Distance));
                    }
                }
                if (prevIdx >= 0 && prevIdx < SplitSelectCombo.Items.Count)
                    SplitSelectCombo.SelectedIndex = prevIdx;
                else
                    SplitSelectCombo.SelectedIndex = 0;
                SplitSelectCombo.SelectionChanged += SplitSelect_Changed;
            }
            ShowTimingSourceData();
        }

        private void ShowTimingSourceData() {
            if (TimingSourceInfo == null || _selectedLane < 0) return;

            var currentSwimmers = GetCurrentHeatSwimmers();
            Swimmer targetSw = null;
            foreach (var s in currentSwimmers) {
                var sa = s.GetAssignmentForStage(_currentStage);
                int sLane = sa != null ? sa.Lane : s.Lane;
                if (sLane == _selectedLane) { targetSw = s; break; }
            }
            if (targetSw == null) { TimingSourceInfo.Text = ""; return; }

            var result = targetSw.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            var ls = _laneDeviceStates.FirstOrDefault(st => st.Lane == _selectedLane);
            int selIdx = SplitSelectCombo != null ? SplitSelectCombo.SelectedIndex : 0;

            var sb = new StringBuilder();
            sb.AppendFormat(Loc.T("Str_RC_TSLaneNameFmt") + "\n", _selectedLane, targetSw.Name ?? "");

            if (selIdx <= 0) {
                sb.Append(Loc.T("Str_RC_TSFinishHeader") + "\n");
                if (_laneCloseSettings.ReactionTimeEnabled) {
                    string rt = ls != null && ls.ReactionTime != 0 ? ls.ReactionTime.ToString("F2") : "-";
                    sb.AppendFormat(Loc.T("Str_RC_TSReactionFmt") + "\n", rt);
                } else {
                    sb.Append(Loc.T("Str_RC_TSReactionOff") + "\n");
                }
                sb.AppendFormat(Loc.T("Str_RC_TSTouchpadFmt") + "\n", result != null && result.TouchpadTime > 0 ? TimeFormatter.Format(result.TouchpadTime) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSBlind1Fmt") + "\n", result != null && result.PushButton1Time > 0 ? TimeFormatter.Format(result.PushButton1Time) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSBlind2Fmt") + "\n", result != null && result.PushButton2Time > 0 ? TimeFormatter.Format(result.PushButton2Time) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSBlind3Fmt") + "\n", result != null && result.PushButton3Time > 0 ? TimeFormatter.Format(result.PushButton3Time) : "-");
                string manual = "";
                if (result != null && result.Splits.Count > 0 && result.Splits.Last().ManualTouchTime > 0)
                    manual = TimeFormatter.Format(result.Splits.Last().ManualTouchTime);
                else if (ls != null) {
                    double m = _laneCloseSettings.FinishPosition == "right" ? ls.RightManualTouchTime : ls.LeftManualTouchTime;
                    if (m > 0) manual = TimeFormatter.Format(m);
                }
                sb.AppendFormat(Loc.T("Str_RC_TSManualFmt") + "\n", !string.IsNullOrEmpty(manual) ? manual : "-");
            } else if (result != null && selIdx - 1 < result.Splits.Count) {
                var sp = result.Splits[selIdx - 1];
                sb.AppendFormat(Loc.T("Str_RC_TSSplitHeaderFmt") + "\n", sp.Lap, sp.Distance);
                if (_laneCloseSettings.ReactionTimeEnabled && ls != null && ls.ReactionTime != 0)
                    sb.AppendFormat(Loc.T("Str_RC_TSReactionFmt") + "\n", ls.ReactionTime.ToString("F2"));
                sb.AppendFormat(Loc.T("Str_RC_TSTouchpadFmt") + "\n", sp.TouchpadTime > 0 ? TimeFormatter.Format(sp.TouchpadTime) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSBlind1Fmt") + "\n", sp.PushButton1Time > 0 ? TimeFormatter.Format(sp.PushButton1Time) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSBlind2Fmt") + "\n", sp.PushButton2Time > 0 ? TimeFormatter.Format(sp.PushButton2Time) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSBlind3Fmt") + "\n", sp.PushButton3Time > 0 ? TimeFormatter.Format(sp.PushButton3Time) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSManualFmt") + "\n", sp.ManualTouchTime > 0 ? TimeFormatter.Format(sp.ManualTouchTime) : "-");
                sb.AppendFormat(Loc.T("Str_RC_TSSourceFmt") + "\n", !string.IsNullOrEmpty(sp.TimingSource) ? sp.TimingSource : "-");
            }
            TimingSourceInfo.Text = sb.ToString();
        }

        private void UpdateRecordDisplay() {
            if (RecordDisplayText == null) return;
            string label = string.IsNullOrEmpty(_displayRecordLabel) ? "WR" : _displayRecordLabel;
            string typeName = string.IsNullOrEmpty(_displayRecordTypeName) ? "世界纪录" : _displayRecordTypeName;
            if (string.IsNullOrEmpty(_currentEvent)) { RecordDisplayText.Text = string.Format("{0}: ---    CR: ---", label); return; }
            string mainTime = "", crTime = "";
            string evClean = _currentEvent.Replace(" ", "").Trim();
            string genClean = (_currentGender ?? "").Trim();
            foreach (var r in _records) {
                if (string.IsNullOrEmpty(r.EventName) || string.IsNullOrEmpty(r.Gender)) continue;
                string rGender = r.Gender.Trim();
                string rEvent = r.EventName.Replace(" ", "").Trim();
                // 2026-08-22 原来是前缀互相匹配 —— "男女".StartsWith("男") 成立,
                //   男子项会显示男女接力的纪录、男女项会显示男子的纪录(取决于遍历顺序)。
                //   改成归一后精确比。
                bool genderMatch = NormGender(rGender) == NormGender(genClean);
                if (!genderMatch || rEvent != evClean) continue;
                if (r.RecordType == null || r.Time <= 0) continue;
                string rt = r.RecordType;
                if (rt == typeName || rt.Contains(typeName)) mainTime = TimeFormatter.Format(r.Time);
                if (rt.Contains("赛会") || rt.Contains("省运会")) crTime = TimeFormatter.Format(r.Time);
            }
            RecordDisplayText.Text = string.Format("{0}: {1}    CR: {2}",
                label,
                !string.IsNullOrEmpty(mainTime) ? mainTime : "---",
                !string.IsNullOrEmpty(crTime) ? crTime : "---");
        }

        private void RefreshDisplayRecordLabelText() {
            if (DisplayRecordLabelText == null) return;
            // 2026-09-21 这里的记录类型名(_displayRecordTypeName)是操作员在"设置..."弹窗里
            // 自由编辑/新增的数据(可以是"市记录"/"行业纪录"这类任意文字), 不是固定 UI 文案,
            // 没法走翻译表——只有两个默认兜底值("WR"/"世界纪录", 用户从没设置过时用)值得查表,
            // 真选了别的纪录类型时原样显示操作员填的字, 跟 TimingStatusText 那类"动态数据不翻译"
            // 是同一个道理。
            DisplayRecordLabelText.Text = string.Format("{0} ({1})",
                string.IsNullOrEmpty(_displayRecordLabel) ? "WR" : _displayRecordLabel,
                string.IsNullOrEmpty(_displayRecordTypeName) ? Loc.T("Str_Col_RecordType_World") : _displayRecordTypeName);
        }

        private void DisplayRecordTypeSetting_Click(object sender, RoutedEventArgs e) {
            var dlg = new Window {
                Title = Loc.T("Str_Win_DisplayRecordSetting_Title"),
                Width = 520, Height = 480,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.CanResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC"))
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock {
                Text = Loc.T("Str_Win_DisplayRecordSetting_Title"),
                FontSize = 16, FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B")),
                Margin = new Thickness(0, 0, 0, 6)
            });
            sp.Children.Add(new TextBlock {
                Text = Loc.T("Str_Win_DisplayRecordSetting_Desc"),
                TextWrapping = TextWrapping.Wrap,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                FontSize = 12, Margin = new Thickness(0, 0, 0, 12)
            });

            var working = new System.Collections.ObjectModel.ObservableCollection<DisplayRecordOption>();
            foreach (var o in _displayRecordOptions) working.Add(new DisplayRecordOption { Label = o.Label, TypeName = o.TypeName });

            var grid = new DataGrid {
                AutoGenerateColumns = false, CanUserAddRows = false, IsReadOnly = false,
                SelectionMode = DataGridSelectionMode.Single, Height = 250,
                AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F1F5F9")),
                HeadersVisibility = DataGridHeadersVisibility.All, RowHeaderWidth = 50
            };
            grid.LoadingRow += delegate(object _s, DataGridRowEventArgs _ev) { _ev.Row.Header = (_ev.Row.GetIndex() + 1).ToString(); };
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Abbr"), Width = new DataGridLength(100),
                Binding = new System.Windows.Data.Binding("Label") { Mode = System.Windows.Data.BindingMode.TwoWay, UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged } });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Win_DisplayRecordSetting_ColFullName"), Width = new DataGridLength(1, DataGridLengthUnitType.Star),
                Binding = new System.Windows.Data.Binding("TypeName") { Mode = System.Windows.Data.BindingMode.TwoWay, UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged } });
            grid.ItemsSource = working;
            // 选中当前生效项
            for (int i = 0; i < working.Count; i++) {
                if (working[i].Label == _displayRecordLabel && working[i].TypeName == _displayRecordTypeName) {
                    grid.SelectedIndex = i; break;
                }
            }
            sp.Children.Add(grid);

            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            var btnAdd = new Button { Content = Loc.T("Str_Win_UnitMgmt_AddBtn"), Padding = new Thickness(12, 6, 12, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnAdd.Click += delegate { working.Add(new DisplayRecordOption { Label = Loc.T("Str_Win_DisplayRecordSetting_NewLabel"), TypeName = Loc.T("Str_Win_DisplayRecordSetting_NewTypeName") }); };
            var btnDel = new Button { Content = Loc.T("Str_Win_UnitMgmt_DeleteBtn"), Padding = new Thickness(12, 6, 12, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnDel.Click += delegate {
                var sel = grid.SelectedItem as DisplayRecordOption;
                if (sel != null) working.Remove(sel); else AppMessageBox.Show(Loc.T("Str_Msg_SelectRowFirst"));
            };
            btnRow.Children.Add(btnAdd);
            btnRow.Children.Add(btnDel);
            sp.Children.Add(btnRow);

            var okRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            var btnOk = new Button { Content = Loc.T("Str_Win_DisplayRecordSetting_OkBtn"), Padding = new Thickness(16, 6, 16, 6), FontWeight = FontWeights.Bold,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnOk.Click += delegate {
                try { grid.CommitEdit(DataGridEditingUnit.Cell, true); grid.CommitEdit(DataGridEditingUnit.Row, true); } catch { }
                var sel = grid.SelectedItem as DisplayRecordOption;
                if (sel == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRecordTypeRow")); return; }
                if (string.IsNullOrWhiteSpace(sel.Label) || string.IsNullOrWhiteSpace(sel.TypeName)) {
                    AppMessageBox.Show(Loc.T("Str_Msg_LabelAndNameRequired")); return;
                }
                var finalList = new List<DisplayRecordOption>();
                var seen = new HashSet<string>();
                foreach (var r in working) {
                    string lab = (r.Label ?? "").Trim();
                    string tn = (r.TypeName ?? "").Trim();
                    if (string.IsNullOrEmpty(lab) || string.IsNullOrEmpty(tn)) continue;
                    string key = lab + "|" + tn;
                    if (seen.Contains(key)) continue;
                    seen.Add(key);
                    finalList.Add(new DisplayRecordOption { Label = lab, TypeName = tn });
                }
                _displayRecordOptions = finalList;
                _displayRecordLabel = (sel.Label ?? "").Trim();
                _displayRecordTypeName = (sel.TypeName ?? "").Trim();
                dlg.DialogResult = true;
            };
            okRow.Children.Add(btnCancel);
            okRow.Children.Add(btnOk);
            sp.Children.Add(okRow);

            dlg.Content = sp;
            if (dlg.ShowDialog() == true) {
                RefreshDisplayRecordLabelText();
                UpdateRecordDisplay();
                AutoSaveData();
                Broadcast();
                AddLog(Loc.F("Str_Log_DisplayRecordSwitchedFmt", _displayRecordLabel, _displayRecordTypeName));
            }
        }

        private void UpdateRaceStateDisplay() {
            // "泳道实时状态"右上的状态徽章 + 顶部信息栏的状态文本，统一用同一组配色：
            //   等待   蓝 #3B82F6（白字）
            //   就位   黄 #F59E0B（黑字，黄底白字对比差）
            //   比赛中 红 #EF4444（白字）
            //   已完赛 灰 #475569（白字 — 与进行中三状态区分）
            string label;
            string bgHex, fgHex;
            switch (_raceState) {
                case RaceState.Ready:
                    label = Loc.T("Str_RC_Ready"); bgHex = "#F59E0B"; fgHex = "#000000"; break;
                case RaceState.Racing:
                    label = Loc.T("Str_Msg_Racing"); bgHex = "#EF4444"; fgHex = "#FFFFFF"; break;
                case RaceState.Finished:
                    label = Loc.T("Str_HeatStatus_Done"); bgHex = "#475569"; fgHex = "#FFFFFF"; break;
                default:
                    label = Loc.T("Str_RC_StateWaiting"); bgHex = "#3B82F6"; fgHex = "#FFFFFF"; break;
            }
            var bgBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(bgHex));
            var fgBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(fgHex));

            // 顶部信息栏的状态文本（彩底白/黑字）
            RaceStateText.Text = label;
            RaceStateText.Background = bgBrush;
            RaceStateText.Foreground = fgBrush;

            // 泳道实时状态右上角徽章：整框底色随状态走，圆点 + 文字保持白色
            if (RaceStateBox != null) RaceStateBox.Background = bgBrush;
            RaceStateIndicator.Fill = new SolidColorBrush(Colors.White);
            RaceStateLabel.Text = label;
            RaceStateLabel.Foreground = fgBrush;

            CompModeText.Text = Loc.T(_competitionMode == "domestic" ? "Str_CompMode_Domestic" : "Str_CompMode_International");
            PoolInfoText.Text = Loc.F("Str_Fmt_PoolInfo", _poolConfig.Length, _poolConfig.LaneCount);

            // 2026-05-30 v2: 只有 Waiting 状态 (= 按"计时复位" 后) 才允许这些操作
            //   Ready / Racing / Finished 都禁用 (= 灰色, 不可点)
            //   防止误操作丢失实时数据; 比完赛后也必须按计时复位才能再断开/测试 (用户要求)
            bool blockHwOps = (_raceState != RaceState.Waiting);
            try {
                if (DisconnectTimingButton != null) DisconnectTimingButton.IsEnabled = !blockHwOps;
                if (QuickConnectSerialButton != null) QuickConnectSerialButton.IsEnabled = !blockHwOps;
                if (DeviceTestButton != null) DeviceTestButton.IsEnabled = !blockHwOps;
            } catch { }
        }

        // ═══════════════════════════════════════════════════════════════
        // 泳道操作
        // ═══════════════════════════════════════════════════════════════

        // 取消备注：清除 DNS/DNF/DSQ 等状态，使运动员回到正常参赛状态
        private void CancelLaneNote(int lane) {
            // 2026-09-12 已完赛的组成绩不许再改 —— 撤销 DSQ 会把备份成绩恢复回去, 同样是改成绩
            if (BlockIfCurrentResultLocked(Loc.T("Str_Action_ClearStatusMark"))) return;
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) { AddLog(Loc.F("Str_Log_LaneSwimmerNotFoundFmt", lane)); return; }

            // 2026-06-12 空道试游 占位运动员: 取消备注 = 整条移除 (无报名信息, 不应残留空行)
            if (swimmer.Notes == EmptyTriMarker) {
                _swimmers.Remove(swimmer);
                // 2026-10-08 直接从已建好的缓存名单里摘掉这个对象, 不整体invalidate——
                // 整体失效会逼 GetCurrentHeatSwimmers() 下次重新查库/走网络(RemoteTimingControl
                // 联网时是 RPC), 而且空道试游占位运动员本来就没有分组表数据库那一行,
                // 查库重建反而会把这个"本机本地加的人"凭空吞掉(库里压根没有这一条)。
                if (_currentHeatSwimmersCache != null) _currentHeatSwimmersCache.Remove(swimmer);
                var lsTri = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (lsTri != null) lsTri.IsFinished = false;
                if (_timingBridge != null && _timingBridge.IsConnected) {
                    try { SendSetMatchEventToHardware(); } catch { }
                }
                LogRawTimingData(lane, "CANCEL_EMPTY_TRI", 0);
                AddLog(Loc.F("Str_Log_EmptyLaneTriCancelledFmt", lane));
                try { UpdateHeatRanking(); } catch { }
                UpdateLaneStatusDisplay();
                try { RefreshResultGrid(); } catch { }
                AutoSaveData();
                Broadcast();
                return;
            }

            string oldStatus = swimmer.Status ?? "";
            swimmer.Status = "";
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            // 取消 DSQ/DNS/DNF/TRI 后：若该运动员有有效成绩，按需重新比对纪录 + 更新本组排名
            var resCN = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (resCN != null) {
                // 2026-06-04 TRI 也走 wasDQ 路径: 取消后 r.Status 清掉, finalTime 仍在 → 重新评纪录
                bool wasDQ = (oldStatus == "DSQ" || oldStatus == "DNS" || oldStatus == "DNF" || oldStatus == "TRI");
                if (wasDQ) {
                    if (resCN.Status == oldStatus) resCN.Status = "";
                    // 2026-07-05 撤销 DSQ 时从备份恢复成绩 (= 防误操作). DNS/DNF/TRI 从未清成绩, 无需恢复.
                    if (oldStatus == "DSQ" && resCN.DsqBackupFinalTime > 0) {
                        resCN.FinalTime = resCN.DsqBackupFinalTime;
                        resCN.TimeInSeconds = resCN.DsqBackupTimeInSeconds;
                        resCN.StartingBlockTime = resCN.DsqBackupStartingBlockTime;
                        if (resCN.DsqBackupSplits != null) {
                            resCN.Splits.Clear();
                            foreach (var sp in resCN.DsqBackupSplits) resCN.Splits.Add(sp);
                        }
                        if (resCN.DsqBackupLegReactionTimes != null) {
                            resCN.LegReactionTimes = new List<double>(resCN.DsqBackupLegReactionTimes);
                        }
                        // 清备份 (一次性使用)
                        resCN.DsqBackupFinalTime = 0;
                        resCN.DsqBackupTimeInSeconds = 0;
                        resCN.DsqBackupStartingBlockTime = 0;
                        resCN.DsqBackupSplits = null;
                        resCN.DsqBackupLegReactionTimes = null;
                        AddLog(Loc.F("Str_Log_DsqRevokedRestoredFmt", lane, TimeFormatter.Format(resCN.FinalTime)));
                    }
                    if (resCN.FinalTime > 0) {
                        // 复算破/平纪录标识
                        try { CheckRecords(swimmer, resCN); } catch { }
                    }
                }
            }
            if (laneState != null) {
                // 若比赛尚未结束/未有最终成绩，重置完成标志，使其继续参赛
                bool hasFinalTime = resCN != null && resCN.FinalTime > 0;
                if (!hasFinalTime) laneState.IsFinished = false;
            }
            LogRawTimingData(lane, "CANCEL_NOTE", 0);
            AddLog(Loc.F("Str_Log_NoteCancelledRestoredFmt",
                lane, swimmer.Name, string.IsNullOrEmpty(oldStatus) ? Loc.T("Str_Frag_None") : oldStatus));
            try { UpdateHeatRanking(); } catch { }
            UpdateLaneStatusDisplay();
            // 2026-09-01 同 MarkLaneStatus: 撤销判罚也要落当前组库, 否则撤销只在内存里生效,
            //   确认成绩时又按当前组库里那份旧的写回去 —— 撤了等于没撤。
            try { SaveHeatProgress(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_CancelNoteSaveFailedFmt", ex.Message)); }
            AutoSaveData();
            Broadcast();
        }

        // 盲表成绩：当前分段若无触板时间，使用盲表时间作为该段正式成绩
        // 逻辑：在 laneState.PendingBlind*Time 中选择一个最早的有效盲表时间，
        //       按触板到达处理（ProcessTouchpadHit 会把盲表时间清理并完成分段）
        private void UseBlindResultForCurrentSegment(int lane) {
            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState == null) { AddLog(Loc.F("Str_Log_LaneStateNotFoundFmt", lane)); return; }

            // 当前 split 上可能已经记录了盲表时间（预创建 split 时盲表会写入 split.PushButton*Time），
            // 这是正常的工作路径；laneState.PendingBlind*Time 只是无 split 时的备用暂存。
            // 这里把两处都纳入候选，避免按下"盲表成绩"时找不到数据。
            var curSplit = FindCurrentSplit(lane);

            var blinds = new List<double>();
            if (laneState.PendingBlind1Time > 0) blinds.Add(laneState.PendingBlind1Time);
            if (laneState.PendingBlind2Time > 0) blinds.Add(laneState.PendingBlind2Time);
            if (laneState.PendingBlind3Time > 0) blinds.Add(laneState.PendingBlind3Time);
            if (curSplit != null) {
                if (curSplit.PushButton1Time > 0 && !blinds.Contains(curSplit.PushButton1Time)) blinds.Add(curSplit.PushButton1Time);
                if (curSplit.PushButton2Time > 0 && !blinds.Contains(curSplit.PushButton2Time)) blinds.Add(curSplit.PushButton2Time);
                if (curSplit.PushButton3Time > 0 && !blinds.Contains(curSplit.PushButton3Time)) blinds.Add(curSplit.PushButton3Time);
            }
            if (blinds.Count == 0) {
                AddLog(Loc.F("Str_Log_NoBlindDataFmt", lane));
                return;
            }
            blinds.Sort();
            // 2026-06-24 MB 算法: 1 个=自己, 2 个=平均 (千分位 floor), 3 个=真中位
            double blindTime;
            if (blinds.Count == 2) blindTime = Math.Floor((blinds[0] + blinds[1]) * 50.0) / 100.0;
            else                   blindTime = blinds[blinds.Count / 2];

            // 检查当前段是否已有触板时间（若有则不覆盖）
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer != null) {
                var res = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                int curLap = laneState.CurrentLap + 1;
                if (res != null) {
                    var sp = res.Splits.FirstOrDefault(x => x.Lap == curLap);
                    if (sp != null && sp.TouchpadTime > 0) {
                        AddLog(Loc.F("Str_Log_SplitAlreadyHasTpSkippedFmt", lane));
                        return;
                    }
                }
            }

            AddLog(Loc.F("Str_Log_UseBlindAsOfficialFmt",
                lane, TimeFormatter.Format(blindTime)));
            LogRawTimingData(lane, "USE_BLIND_RESULT", blindTime);

            // 按触板处理（ProcessTouchpadHit 会把 PendingBlind 写入分段后清空）
            ProcessTouchpadHit(lane, blindTime, laneState);
            // 恢复泳道到正常参赛状态：不自动关闭
            laneState.LaneCloseCountdown = 0;
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // 道次打开 / 道次关闭：只对指定泳道生效（单道版本的 OpenAll/CloseAll）
        private void SetSingleLaneOpen(int lane, bool open) {
            var s = _laneDeviceStates.FirstOrDefault(x => x.Lane == lane);
            if (s == null) { AddLog(Loc.F("Str_Log_LaneStateNotFoundFmt", lane)); return; }
            DeviceStatus st = open ? DeviceStatus.Open : DeviceStatus.Closed;
            s.LeftTouchpadStatus = st;
            s.LeftBlindWatch1Status = st; s.LeftBlindWatch2Status = st; s.LeftBlindWatch3Status = st;
            s.LeftStartBlockStatus = st;
            s.RightTouchpadStatus = st;
            s.RightBlindWatch1Status = st; s.RightBlindWatch2Status = st; s.RightBlindWatch3Status = st;
            s.RightStartBlockStatus = st;
            s.LaneCloseCountdown = 0;
            AddLog(Loc.F("Str_Log_LaneSetOpenClosedFmt", lane, open ? Loc.T("Str_Frag_Open") : Loc.T("Str_Frag_Close")));
            //2026-05-14 单道也同步下发硬件：0x47 D3=lane D4=1/0
            //2026-05-18 lane 按屏幕位置编码（逆序模式下转换）
            try { if (_timingBridge != null && _timingBridge.IsConnected) _timingBridge.SendLaneOpenClose(LaneToHwIndex(lane), open); } catch { }
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // 2026-06-05 大屏 项目名称下 inline 纪录行 数据源 (本 event + gender 匹配的纪录):
        //   gender="男女" → 男 + 女 + 男女 三类记录都列
        //   ageGroup 非空 → 只列对应组别 (含子区间, 如 schedule '12~15岁组' 覆盖 12-13 + 14-15)
        //   返回 [{tag, ageGroup, gender, time, holderName}, ...] 按 RecordType 优先级 + 年龄组顺序
        // 2026-06-05 默认无 ageGroup 限制 (兼容调用): 用 _currentAgeGroup
        private List<object> BuildApplicableRecords(string eventName, string gender) {
            return BuildApplicableRecords(eventName, gender, _currentAgeGroup);
        }
        private List<object> BuildApplicableRecords(string eventName, string gender, string ageGroup) {
            var list = new List<object>();
            if (string.IsNullOrEmpty(eventName) || _records == null || _records.Count == 0) return list;
            // 2026-08-21 混合接力只列它自己那条纪录。
            //   原来 gender=="男女" 无条件把 男 + 女 + 男女 三类都列出来，那是给
            //   "男女并项"(男女同场比、分开排名) 用的；用在混合接力上会把同名的
            //   男子项、女子项的纪录也列进去 —— 现场大屏 男女少年组4x50 纪录条
            //   同时出现 1:58.98(女) / 1:49.30(男) / 1:52.98(男女) 三条就是这个。
            //   判据同 GenderMatchEx：该项目的报名条目里有没有 Gender 本身是"男女"的。
            Func<string, bool> gOk;
            if (NormGender(gender) == "男女") {
                if (HasExplicitMixedEntry(eventName, ageGroup)) gOk = g => NormGender(g) == "男女";
                else gOk = g => { string n = NormGender(g); return n == "男" || n == "女" || n == "男女"; };
            }
            else if (string.IsNullOrEmpty(gender)) gOk = g => true;
            else gOk = g => NormGender(g) == NormGender(gender);
            // 年龄过滤: 优先用 ageGroup, 用 MatchesAgeGroup 处理区间 (12~15 覆盖 12-13 + 14-15);
            //   ageGroup 为空 / "全部" / "不限" → 不限
            Func<string, bool> aOk;
            if (string.IsNullOrEmpty(ageGroup) || ageGroup == Loc.T("Str_Common_All") || ageGroup == "不限") aOk = a => true;
            else aOk = a => {
                if (string.IsNullOrEmpty(a)) return false;
                if (a == ageGroup) return true;
                int sLo, sHi, gLo, gHi;
                if (TryParseAgeRange(ageGroup, out gLo, out gHi) && TryParseAgeRange(a, out sLo, out sHi))
                    return gLo <= sLo && sHi <= gHi;
                return false;
            };
            // 年龄顺序 (按 _ageGroups 注册顺序)
            var ageOrder = new Dictionary<string, int>();
            for (int i = 0; i < _ageGroups.Count; i++) ageOrder[_ageGroups[i].Name] = i;
            // RecordType 优先级
            var typeOrder = new Dictionary<string, int> { {"世界纪录",1},{"奥运纪录",2},{"亚洲纪录",3},{"亚洲青年纪录",4},{"全国纪录",5},{"甘肃省纪录",6},{"省纪录",6} };
            var filtered = _records.Where(r => r != null && r.Time > 0 && r.EventName == eventName && gOk(r.Gender ?? "") && aOk(r.AgeGroup ?? "")).ToList();
            // 排序: 按 RecordType 优先级 + 年龄组顺序
            filtered.Sort((a, b) => {
                int ta = 99, tb = 99;
                typeOrder.TryGetValue(a.RecordType ?? "", out ta);
                typeOrder.TryGetValue(b.RecordType ?? "", out tb);
                if (ta != tb) return ta - tb;
                int aa = 99, ab = 99;
                ageOrder.TryGetValue(a.AgeGroup ?? "", out aa);
                ageOrder.TryGetValue(b.AgeGroup ?? "", out ab);
                if (aa != ab) return aa - ab;
                return string.Compare(a.Gender ?? "", b.Gender ?? "", StringComparison.Ordinal);
            });
            foreach (var r in filtered) {
                list.Add(new {
                    tag = RecordTypeToTag(r.RecordType),
                    ageGroup = r.AgeGroup ?? "",
                    gender = r.Gender ?? "",
                    time = TimeFormatter.Format(r.Time),
                    holderName = r.HolderName ?? ""
                });
            }
            return list;
        }

        // 2026-06-05 一键公布项目总排名: 按 性别×组别 拆 txt 写到 存盘路径
        // 2026-06-06 用户要求: 仅存盘, 不再切大屏 (原 BroadcastDisplayMode("SHOW_EVENT_RANKING") 已删).
        //   要大屏切总排名 → race_control.html "总排名" 按钮 / 比赛控制界面 ShowEventRanking_Click 单独触发.
        private void PublishEventRanking_Click(object sender, RoutedEventArgs e) {
            // 2026-08-31 公布总排名到大屏前先从库【增量】刷新 —— 别的计算机写的成绩才看得到。
            //   开销是一条轻查询; 没变动就一行成绩都不读。
            try { RefreshChangedFromDb(); } catch { }
            if (string.IsNullOrEmpty(_currentEvent) || string.IsNullOrEmpty(_currentStage)) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectEventInTreeFirst"), Loc.T("Str_MsgTitle_ActionTip"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            // 验证至少有一组已确认
            var subList = GetEventRankingsSplit(_currentAgeGroup, _currentEvent, _currentGender);
            if (subList == null || subList.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoConfirmedResultsYet"), Loc.T("Str_MsgTitle_ActionTip"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // 2) 自动写 txt (按 性别×组别 一文件)
            string dir = GetAutoSaveTxtDir();
            if (string.IsNullOrWhiteSpace(dir)) {
                AddLog(Loc.T("Str_Log_ResultSavePathNotConfigured"));
                return;
            }
            WarnIfLocalSaveDirOnTimingStation(dir);
            try {
                if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
                var sched = _schedule.FirstOrDefault(s => s.Gender == _currentGender && s.EventName == _currentEvent
                    && s.Stage == _currentStage && (s.AgeGroup ?? "") == (_currentAgeGroup ?? ""));
                int session = sched != null ? sched.SessionNumber : 0;
                var evtMap = BuildEventNumberMap();
                int eventNo = 0;
                if (!evtMap.TryGetValue((_currentGender ?? "") + "|" + (_currentEvent ?? "") + "|" + (_currentAgeGroup ?? ""), out eventNo))
                    evtMap.TryGetValue((_currentGender ?? "") + "|" + (_currentEvent ?? ""), out eventNo);
                int saved = 0;
                foreach (dynamic sub in subList) {
                    string subGender = sub.gender; string subAge = sub.ageGroup;
                    var items = sub.items as System.Collections.IEnumerable;
                    if (items == null) continue;
                    var sb = new StringBuilder();
                    sb.AppendFormat("{0} {1} {2} {3} 总排名\r\n",
                        subGender, string.IsNullOrEmpty(subAge) ? "" : subAge, _currentEvent, _currentStage);
                    sb.Append("排名 道 姓名 代表队 最终成绩\r\n");
                    foreach (dynamic it in items) {
                        sb.AppendFormat("{0} {1} {2} {3} {4}\r\n",
                            it.rank, it.lane, it.name ?? "", it.country ?? "",
                            it.finalTime ?? "");
                    }
                    string safeAge = (subAge ?? "").Replace('/', '_').Replace('\\', '_').Replace('岁', 'y');
                    string fileName = string.Format("{0:D2}-{1:D2}-总排名-{2}-{3}.txt", session, eventNo, subGender, safeAge);
                    foreach (char c in IOPath.GetInvalidFileNameChars()) fileName = fileName.Replace(c, '_');
                    string fullPath = IOPath.Combine(dir, fileName);
                    WriteFileAsync(fullPath, sb.ToString(), new UTF8Encoding(false), null, Loc.T("Str_Log_RankingTxtWriteFailedPrefix"));
                    saved++;
                }
                AddLog(Loc.F("Str_Log_RankingTxtWrittenFmt", saved, dir));
                AddLog(Loc.T("Str_Log_PrintRankingHint"));
            } catch (Exception ex) {
                AddLog(Loc.T("Str_Log_RankingTxtWriteFailedPrefix") + ex.Message);
            }
        }

        // 2026-06-05 接力 DSQ 时 弹窗问 犯规棒次 (1..legCount; 0 = 用户取消, 不打 DSQ)
        private int AskRelayViolationLeg(int lane, string swimmerName, int legCount) {
            int chosen = 0;
            var dlg = new Window {
                Title = Loc.F("Str_Win_RelayViolation_TitleFmt", lane, swimmerName),
                Width = 380, Height = 200,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(20) };
            sp.Children.Add(new TextBlock {
                Text = Loc.T("Str_Win_RelayViolation_Body"),
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 12)
            });
            var legRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Center };
            for (int i = 1; i <= legCount; i++) {
                int leg = i;
                var b = new Button { Content = Loc.F("Str_Win_RelayViolation_LegBtnFmt", leg), Padding = new Thickness(14, 6, 14, 6), Margin = new Thickness(4),
                    Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")), Foreground = Brushes.White, BorderThickness = new Thickness(0), FontSize = 13 };
                b.Click += delegate { chosen = leg; dlg.DialogResult = true; };
                legRow.Children.Add(b);
            }
            sp.Children.Add(legRow);
            var btnCancel = new Button { Content = Loc.T("Str_Win_RelayViolation_CancelBtn"), Padding = new Thickness(14, 5, 14, 5), Margin = new Thickness(0, 12, 0, 0),
                HorizontalAlignment = HorizontalAlignment.Center,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { chosen = 0; dlg.DialogResult = false; };
            sp.Children.Add(btnCancel);
            dlg.Content = sp;
            dlg.ShowDialog();
            return chosen;
        }

        private void MarkLaneStatus(int lane, string status) {
            // 2026-09-12 已完赛的组成绩不许再改 —— 判 DSQ/DNS/DNF 也是改成绩
            if (BlockIfCurrentResultLocked(Loc.F("Str_Action_JudgeStatusFmt", status))) return;
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer != null) {
                // 2026-06-05 DSQ 接力: 先弹窗问犯规棒次, 取消则完全不打 DSQ (不改任何状态)
                int relayViolationLeg = 0;
                if (status == "DSQ") {
                    bool isRelay = !string.IsNullOrEmpty(_currentEvent) && _currentEvent.Contains("接力");
                    if (isRelay) {
                        int legCount = GetLegCountForEvent(_currentEvent);
                        relayViolationLeg = AskRelayViolationLeg(lane, swimmer.Name, legCount);
                        if (relayViolationLeg <= 0) {
                            AddLog(Loc.F("Str_Log_RelayDsqCancelledNoLegFmt", lane, swimmer.Name));
                            return;
                        }
                    }
                }

                swimmer.Status = status;
                // ══════════════════════════════════════════════════════════
                // 2026-09-01 TRI(试游) 也必须写到【成绩行】上。
                //
                // 原来 res.Status 只在 DSQ/DNS/DNF 那个分支里赋值, TRI 只改了
                // swimmer.Status。后果是一条链子全断:
                //   · SaveHeatProgress 写当前组库时 ln.Status = res.Status = "" → 库里没有 TRI
                //   · 确认成绩入库, 竞赛库里这一行是"正常人" → 照样占名次
                //   · 回推给主服务器的 lr.Status 也是空的 → 主服务器完全不知道有 TRI,
                //     "成绩与排名"和"文档编辑/输出/打印"里都不显示 TRI 标注
                // 只有计时端本机的 swimmer.Status 还留着, 所以【确认那一刻】大屏是对的,
                // 之后换个视图、换台机器就全没了 —— 用户实测到的就是这个。
                //
                // TRI 与判罚的区别: 成绩正常显示, 只是不排名、不计分、不算纪录。
                // 所以这里只清名次和纪录标识, 不动 FinalTime/分段。
                // ══════════════════════════════════════════════════════════
                if (status == "TRI") {
                    var resTri = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                    if (resTri != null) {
                        if (!string.IsNullOrEmpty(resTri.RecordNote)) {
                            AddLog(Loc.F("Str_Log_TriRecordFlagClearedFmt",
                                lane, swimmer.Name, resTri.RecordNote));
                            resTri.RecordNote = "";
                        }
                        resTri.Status = "TRI";
                        resTri.Rank = 0;
                    }
                    swimmer.CurrentRank = 0;
                }
                // DSQ/DNS/DNF：成绩无效，必须清除 RecordNote（否则破/平纪录标识仍残留），
                // 同时重新计算本组排名 + 复算其它运动员的破/平纪录（被取消的人不再占名次/不再当纪录候选）
                if (status == "DSQ" || status == "DNS" || status == "DNF") {
                    var res = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
                    if (res != null) {
                        if (!string.IsNullOrEmpty(res.RecordNote)) {
                            AddLog(Loc.F("Str_Log_InvalidRecordFlagClearedFmt", lane, swimmer.Name, res.RecordNote));
                            res.RecordNote = "";
                        }
                        res.Status = status;
                        res.Rank = 0;
                        // 2026-06-05 DSQ 分类清除规则:
                        //   个人项目 DSQ → 清 最终成绩 + 所有分段 + 反应时
                        //   接力项目 DSQ → 保留 1~(N-1) 棒分段, 清 第N棒起的分段 + FinalTime
                        if (status == "DSQ") {
                            // 2026-07-05 DSQ 备份原成绩到 res.DsqBackup* 字段, 防误操作 CancelLaneNote 撤销时可恢复
                            res.DsqBackupFinalTime = res.FinalTime;
                            res.DsqBackupTimeInSeconds = res.TimeInSeconds;
                            res.DsqBackupStartingBlockTime = res.StartingBlockTime;
                            res.DsqBackupSplits = new List<SplitTime>(res.Splits);
                            res.DsqBackupLegReactionTimes = res.LegReactionTimes != null ? new List<double>(res.LegReactionTimes) : null;
                            if (relayViolationLeg > 0) {
                                // 解析每棒距离 (e.g. "4x50米..." → 50)
                                var mLeg = System.Text.RegularExpressions.Regex.Match(_currentEvent ?? "", @"\d+\s*[xX×]\s*(\d+)\s*米");
                                int perLegMeters;
                                if (!mLeg.Success || !int.TryParse(mLeg.Groups[1].Value, out perLegMeters)) perLegMeters = 50;
                                int keepDist = (relayViolationLeg - 1) * perLegMeters;
                                var toRemove = res.Splits.Where(sp => sp.Distance > keepDist).ToList();
                                foreach (var sp in toRemove) res.Splits.Remove(sp);
                                if (res.LegReactionTimes != null && res.LegReactionTimes.Count > relayViolationLeg - 1) {
                                    for (int li = relayViolationLeg - 1; li < res.LegReactionTimes.Count; li++) {
                                        res.LegReactionTimes[li] = 0;
                                    }
                                }
                                res.FinalTime = 0;
                                res.TimeInSeconds = 0;
                                AddLog(Loc.F("Str_Log_RelayDsqLegPartialClearFmt",
                                    relayViolationLeg, relayViolationLeg - 1));
                            } else {
                                // 2026-09-16 个人 DSQ: 只清最终成绩 + 反应时, 【不再清分段成绩】。
                                //   原来连分段一起清掉 —— 但判 DSQ 多数是技术犯规(单手触壁/转身
                                //   提前登边之类), 运动员本来就游完了全程, 中途的分段计时是硬件
                                //   实测到的真实数据, 不该因为最后判罚就把它抹掉。成绩册"成绩公告"
                                //   一直是拿 r.Splits 现算分段列的, 之前 DSQ 那一行分段栏一直是空的,
                                //   跟同一张表里 DNF/DNS/TRI 都还留着分段对不上号(用户实拍到)。
                                //   "成绩"这一列是否显示，由显示层的 dq? "" 那道判断挡着, 不靠这里
                                //   把数据删空来实现 —— 数据和"要不要显示"是两件事。
                                res.FinalTime = 0;
                                res.TimeInSeconds = 0;
                                res.StartingBlockTime = 0;
                                AddLog(Loc.T("Str_Log_IndividualDsqClearedKeepSplits"));
                            }
                        }
                    }
                    swimmer.CurrentRank = 0;
                }
                LogRawTimingData(lane, "MARK_" + status, 0);
                AddLog(Loc.F("Str_Log_LaneMarkedStatusFmt", lane, swimmer.Name, status));
                // ── 2026-09-13 TRI 不能标"已完赛" ────────────────────────────
                //   IsFinished 是整条计时链的总闸: 触板(6641)、分段、盲表、
                //   设备开关循环(8630) 一律先看它, 为 true 就直接 return/continue。
                //   原来这里不分状态一律置 true —— 于是赛前把某道标成 TRI,
                //   那道整场收不到任何数据, 触板盲表全是空的。
                //   可 TRI 是【试游】: 人要下水、要计时、成绩照常出, 只是不排名、
                //   不计分、不算纪录。把闸门关了就把规则弄反了。
                //   DNS/DNF/DSQ 照旧置 true(他们确实不再产生成绩)。
                var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                if (laneState != null && status != "TRI") laneState.IsFinished = true;
                // 重新计算本组排名（被取消的运动员让出名次）
                try { UpdateHeatRanking(); } catch { }
                // 2026-06-01 DSQ/DNS/DNF 后, 给新晋 leader 重新比对纪录库, 让 WR/CR 等
                //   标识自动转到新的本组第 1 名 (UpdateHeatRanking → EnforceOnlyLeader 只清不补)
                // 2026-09-01 TRI 也要走这一步: 试游的人本来是本组最快、拿着纪录标识,
                //   标成试游之后他不再是排名里的第 1, 标识得转给真正的第 1 名。
                if (status == "DSQ" || status == "DNS" || status == "DNF" || status == "TRI") {
                    try { RecheckHeatRecordsForNewLeader(); } catch { }
                }
                UpdateLaneStatusDisplay();
                // ══════════════════════════════════════════════════════════
                // 2026-09-01 判罚必须【落进当前组库】, 不能只改内存。
                //
                // 原来这里只有 AutoSaveData()(写 JSON) + Broadcast()。而确认成绩时
                // LiveCommit 取的是【当前组库】的快照 —— 内存里标了 DNS, 当前组库里
                // 那一道还是"有成绩的正常人", 于是写进竞赛库的就是:
                //   有成绩、占名次、还带着 MR 破纪录标识。
                //
                // 现场实测: 泳道4 宗佳田 界面上标了 DNS, 日志也打了"取消破/平纪录标识",
                // 确认之后库里 status 是空的、成绩 20.10、名次 9、record_note=MR,
                // 而且大屏和成绩单都照着库显示 —— 判罚等于没打。
                // 全库 592 行里只有 8 行有判罚状态, 就是这么丢的。
                // ══════════════════════════════════════════════════════════
                try { SaveHeatProgress(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_JudgmentSaveFailedFmt", ex.Message)); }
                AutoSaveData();
                Broadcast();
            }
        }

        private void OverrideLaneTime(int lane, double time) {
            // 2026-09-12 已完赛的组成绩不许再改
            if (BlockIfCurrentResultLocked(Loc.T("Str_Action_ManualEditResult"))) return;
            LogRawTimingData(lane, "ManualOverride", time);
            var swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => {
                var sa = s.GetAssignmentForStage(_currentStage);
                return (sa != null ? sa.Lane : s.Lane) == lane;
            });
            if (swimmer == null) swimmer = GetCurrentHeatSwimmers().FirstOrDefault(s => s.Lane == lane);
            if (swimmer == null) return;

            var result = swimmer.Results.FirstOrDefault(r => r.Stage == _currentStage && r.Heat == _currentHeat);
            if (result == null) {
                result = new LaneResult {
                    EventName = _currentEvent,
                    Stage = _currentStage,
                    Heat = _currentHeat,
                    Lane = lane
                };
                swimmer.Results.Add(result);
            }
            result.FinalTime = time;
            result.TimeInSeconds = time;
            result.TimingSource = "MAN";

            var laneState = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (laneState != null) {
                // 保存反应时间到成绩记录（关闭RT时不写入；抢跳为负值，0 表示未记录）
                if (_laneCloseSettings.ReactionTimeEnabled && laneState.ReactionTime != 0) {
                    result.StartingBlockTime = laneState.ReactionTime;
                }
                laneState.IsFinished = true;
            }

            AddLog(Loc.F("Str_Log_ManualResultEnteredFmt", lane, TimeFormatter.Format(time)));
            UpdateHeatRanking();
            CheckRecords(swimmer, result);
            UpdateLaneStatusDisplay();
            // 2026-09-01 同 MarkLaneStatus: 手动输入的成绩也必须落当前组库,
            //   否则确认成绩时 LiveCommit 取到的还是没改过的那一份, 手输白输。
            try { SaveHeatProgress(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ManualResultSaveFailedFmt", ex.Message)); }
            AutoSaveData();
            Broadcast();
        }

        private void SetDeviceStatus(int lane, string device, string status) {
            var state = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (state == null) return;

            // 2026-06-20 4 态: installed (= 已安装好) / not_installed / good / broken
            //   兼容旧 2 态: "good" / "broken" 仅改 Broken (与 race_control 老协议一致)
            //   "installed" / "not_installed" 改 NotInstalled, 未安装时清 Broken
            //   未安装设备拒绝 good/broken (与 UI 锁定逻辑对齐).
            bool isNotInstalled = (status == "not_installed");
            bool isInstalled = (status == "installed");
            bool isGood = (status == "good");
            bool isBroken = (status == "broken");

            // 检查是否在锁定列 (单端模式下非终点端)
            bool dualEnd = _poolConfig != null && _poolConfig.HasRightStartBlock;
            bool finishIsLeft = _laneCloseSettings == null || _laneCloseSettings.FinishPosition != "right";
            bool lockLeft  = !dualEnd && !finishIsLeft;
            bool lockRight = !dualEnd && finishIsLeft;
            bool isLeftDev = device != null && device.StartsWith("left");
            bool isRightDev = device != null && device.StartsWith("right");
            if ((isLeftDev && lockLeft) || (isRightDev && lockRight)) {
                AddLog(Loc.F("Str_Log_DeviceLockedRemoteRejectedFmt", lane, device));
                return;
            }

            // 当前 NotInstalled 状态 (good/broken 命令必须在已安装下生效)
            bool currentNotInstalled = false;
            switch (device) {
                case "leftTouchpad":    currentNotInstalled = state.LeftTouchpadNotInstalled; break;
                case "leftStartBlock":  currentNotInstalled = state.LeftStartBlockNotInstalled; break;
                case "leftBlindWatch1": currentNotInstalled = state.LeftBlindWatch1NotInstalled; break;
                case "leftBlindWatch2": currentNotInstalled = state.LeftBlindWatch2NotInstalled; break;
                case "leftBlindWatch3": currentNotInstalled = state.LeftBlindWatch3NotInstalled; break;
                case "rightTouchpad":   currentNotInstalled = state.RightTouchpadNotInstalled; break;
                case "rightStartBlock": currentNotInstalled = state.RightStartBlockNotInstalled; break;
                case "rightBlindWatch1": currentNotInstalled = state.RightBlindWatch1NotInstalled; break;
                case "rightBlindWatch2": currentNotInstalled = state.RightBlindWatch2NotInstalled; break;
                case "rightBlindWatch3": currentNotInstalled = state.RightBlindWatch3NotInstalled; break;
            }
            if ((isGood || isBroken) && currentNotInstalled) {
                AddLog(Loc.F("Str_Log_DeviceNotInstalledCannotSetFmt", lane, device));
                return;
            }

            switch (device) {
                case "leftTouchpad":
                    if (isNotInstalled) { state.LeftTouchpadNotInstalled = true; state.LeftTouchpadBroken = false; }
                    else if (isInstalled) { state.LeftTouchpadNotInstalled = false; state.LeftTouchpadBroken = false; }
                    else state.LeftTouchpadBroken = isBroken; break;
                case "leftStartBlock":
                    if (isNotInstalled) { state.LeftStartBlockNotInstalled = true; state.LeftStartBlockBroken = false; }
                    else if (isInstalled) { state.LeftStartBlockNotInstalled = false; state.LeftStartBlockBroken = false; }
                    else state.LeftStartBlockBroken = isBroken; break;
                case "leftBlindWatch1":
                    if (isNotInstalled) { state.LeftBlindWatch1NotInstalled = true; state.LeftBlindWatch1Broken = false; }
                    else if (isInstalled) { state.LeftBlindWatch1NotInstalled = false; state.LeftBlindWatch1Broken = false; }
                    else state.LeftBlindWatch1Broken = isBroken; break;
                case "leftBlindWatch2":
                    if (isNotInstalled) { state.LeftBlindWatch2NotInstalled = true; state.LeftBlindWatch2Broken = false; }
                    else if (isInstalled) { state.LeftBlindWatch2NotInstalled = false; state.LeftBlindWatch2Broken = false; }
                    else state.LeftBlindWatch2Broken = isBroken; break;
                case "leftBlindWatch3":
                    if (isNotInstalled) { state.LeftBlindWatch3NotInstalled = true; state.LeftBlindWatch3Broken = false; }
                    else if (isInstalled) { state.LeftBlindWatch3NotInstalled = false; state.LeftBlindWatch3Broken = false; }
                    else state.LeftBlindWatch3Broken = isBroken; break;
                case "rightTouchpad":
                    if (isNotInstalled) { state.RightTouchpadNotInstalled = true; state.RightTouchpadBroken = false; }
                    else if (isInstalled) { state.RightTouchpadNotInstalled = false; state.RightTouchpadBroken = false; }
                    else state.RightTouchpadBroken = isBroken; break;
                case "rightStartBlock":
                    if (isNotInstalled) { state.RightStartBlockNotInstalled = true; state.RightStartBlockBroken = false; }
                    else if (isInstalled) { state.RightStartBlockNotInstalled = false; state.RightStartBlockBroken = false; }
                    else state.RightStartBlockBroken = isBroken; break;
                case "rightBlindWatch1":
                    if (isNotInstalled) { state.RightBlindWatch1NotInstalled = true; state.RightBlindWatch1Broken = false; }
                    else if (isInstalled) { state.RightBlindWatch1NotInstalled = false; state.RightBlindWatch1Broken = false; }
                    else state.RightBlindWatch1Broken = isBroken; break;
                case "rightBlindWatch2":
                    if (isNotInstalled) { state.RightBlindWatch2NotInstalled = true; state.RightBlindWatch2Broken = false; }
                    else if (isInstalled) { state.RightBlindWatch2NotInstalled = false; state.RightBlindWatch2Broken = false; }
                    else state.RightBlindWatch2Broken = isBroken; break;
                case "rightBlindWatch3":
                    if (isNotInstalled) { state.RightBlindWatch3NotInstalled = true; state.RightBlindWatch3Broken = false; }
                    else if (isInstalled) { state.RightBlindWatch3NotInstalled = false; state.RightBlindWatch3Broken = false; }
                    else state.RightBlindWatch3Broken = isBroken; break;
            }
            string desc = isNotInstalled ? "未安装" : isInstalled ? "已安装" : isBroken ? "损坏" : "正常";
            AddLog(Loc.F("Str_Log_DeviceSetToFmt", lane, device, desc));
            SaveDeviceStates();               // 远端 HTML/EXE 改的也要持久化，下次启动还原
            UpdateLaneStatusDisplay();        // 立即刷新本地泳道实时状态 UI
            Broadcast();
            SendDeviceStatusesToHardware();   // 同步该泳道的设备状态到硬件
        }

        // ═══════════════════════════════════════════════════════════════
        // ScheduleEditor 编辑端 — WebSocket 命令处理
        // ═══════════════════════════════════════════════════════════════
        private void HandleEditorUpdateSwimmer(JObject data) {
            if (data == null) { AddLog(Loc.T("Str_Log_UpdateSwimmerNoData")); return; }
            string bib = data["bibNumber"] != null ? data["bibNumber"].ToString() : "";
            string name = data["name"] != null ? data["name"].ToString() : "";
            string ev = data["eventName"] != null ? data["eventName"].ToString() : "";
            // 按 (bibNumber + eventName) 或 (name + eventName) 定位记录
            var sw = _swimmers.FirstOrDefault(s =>
                !string.IsNullOrEmpty(bib) && s.BibNumber == bib && s.EventName == ev);
            if (sw == null) sw = _swimmers.FirstOrDefault(s => s.Name == name && s.EventName == ev);
            if (sw == null) {
                AddLog(Loc.F("Str_Log_UpdateSwimmerNotFoundFmt", name, bib, ev));
                return;
            }
            // 应用字段
            if (data["name"] != null) sw.Name = data["name"].ToString();
            if (data["gender"] != null) sw.Gender = data["gender"].ToString();
            if (data["birthDate"] != null) sw.BirthDate = data["birthDate"].ToString();
            int ageVal;
            if (data["age"] != null && int.TryParse(data["age"].ToString(), out ageVal)) sw.Age = ageVal;
            if (data["country"] != null) sw.Country = data["country"].ToString();
            if (data["currentStage"] != null) sw.CurrentStage = data["currentStage"].ToString();
            if (data["entryTime"] != null) {
                sw.EntryTime = data["entryTime"].ToString();
                sw.EntryTimeSeconds = TimeFormatter.Parse(sw.EntryTime);
            }
            if (data["idNumber"] != null) sw.IDNumber = data["idNumber"].ToString();
            if (data["phone"] != null) sw.Phone = data["phone"].ToString();
            if (data["notes"] != null) sw.Notes = data["notes"].ToString();
            // 2026-09-19 【用户明确要求, 不止接力队/单人编辑, 这类"编辑端"命令处理函数
            //   全部一样要治】——这一整个 HandleEditor* 家族(UPDATE_SWIMMER 等命令)收到的
            //   本来就是【已经很小的定向数据】(就这一个人的这几个字段), 不是问题所在;
            //   问题出在结尾这句 AutoSaveData()——它会经 PropagateSyncAfterSave 顺带
            //   把整个竞赛包打包推给所有连着的编排端/计时端, 把一次"改一个人"的动作
            //   放大成一次整库同步。改用 SaveWithoutPush()(落盘但不触发那次整包推送,
            //   跟接力队/运动员编辑补丁最终收尾用的是同一个函数), 只留 Broadcast()
            //   那条本来就是轻量的 100ms 批量精简帧广播。
            SaveWithoutPush();
            RefreshOverviewStats();
            RefreshSwimmerFilter();
            Broadcast();
            PushDataChanged("swimmer");
            AddLog(Loc.F("Str_Log_EditorUpdatedSwimmerFmt", sw.Name, sw.BibNumber, sw.EventName));
        }

        private void HandleEditorDeleteSwimmer(JObject data) {
            if (data == null) { AddLog(Loc.T("Str_Log_DeleteSwimmerNoData")); return; }
            string bib = data["bibNumber"] != null ? data["bibNumber"].ToString() : "";
            string name = data["name"] != null ? data["name"].ToString() : "";
            string ev = data["eventName"] != null ? data["eventName"].ToString() : "";
            var sw = _swimmers.FirstOrDefault(s =>
                !string.IsNullOrEmpty(bib) && s.BibNumber == bib && s.EventName == ev);
            if (sw == null) sw = _swimmers.FirstOrDefault(s => s.Name == name && s.EventName == ev);
            if (sw == null) {
                AddLog(Loc.F("Str_Log_DeleteSwimmerNotFoundFmt", name, bib, ev));
                return;
            }
            _swimmers.Remove(sw);
            SaveWithoutPush();   // 2026-09-19 见 HandleEditorUpdateSwimmer 的说明
            RefreshOverviewStats();
            RefreshSwimmerFilter();
            Broadcast();
            PushDataChanged("swimmer");
            AddLog(Loc.F("Str_Log_EditorDeletedSwimmerFmt", sw.Name, sw.BibNumber, sw.EventName));
        }

        private void HandleEditorListDocuments() {
            // 列出 Documents/ 和 Database/RawData/ 下所有报告文件
            var list = new List<object>();
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            ScanDocDir(list, IOPath.Combine(baseDir, "Documents"), "Documents");
            ScanDocDir(list, IOPath.Combine(baseDir, "Database", "RawData"), "原始数据");
            string json = JsonConvert.SerializeObject(new { type = "DOC_LIST_RESULT", data = list });
            BroadcastJsonToClients(json);
        }

        private void ScanDocDir(List<object> list, string dir, string category) {
            try {
                if (!Directory.Exists(dir)) return;
                foreach (string path in Directory.GetFiles(dir)) {
                    var fi = new FileInfo(path);
                    list.Add(new {
                        category = category,
                        fileName = fi.Name,
                        path = path,
                        time = fi.LastWriteTime.ToString("yyyy-MM-dd HH:mm:ss"),
                        size = FormatFileSize(fi.Length)
                    });
                }
            } catch { }
        }

        private static string FormatFileSize(long bytes) {
            if (bytes < 1024) return bytes + " B";
            if (bytes < 1024 * 1024) return (bytes / 1024.0).ToString("F1") + " KB";
            return (bytes / 1024.0 / 1024.0).ToString("F2") + " MB";
        }

