        private void ManualTime_Click(object sender, RoutedEventArgs e) {
            int lane;
            if (!int.TryParse(LaneInputBox.Text, out lane)) { AddLog(Loc.T("Str_Log_PleaseEnterLaneNumber")); return; }
            var dlg = new Window {
                Title = Loc.F("Str_Win_ManualTime_TitleFmt", lane), Width = 320, Height = 170,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_Win_ManualTime_Prompt") });
            var tb = new TextBox { Margin = new Thickness(0, 8, 0, 8), Padding = new Thickness(4), FontSize = 14 };
            sp.Children.Add(tb);
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            var btnOK = new Button { Content = Loc.T("Str_Btn_OK"), Padding = new Thickness(16, 4, 16, 4), Margin = new Thickness(0, 0, 6, 0) };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 4, 16, 4) };
            btnOK.Click += delegate { dlg.DialogResult = true; };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnRow.Children.Add(btnOK);
            btnRow.Children.Add(btnCancel);
            sp.Children.Add(btnRow);
            dlg.Content = sp;
            tb.Focus();
            if (dlg.ShowDialog() == true && !string.IsNullOrEmpty(tb.Text)) {
                double time = TimeFormatter.Parse(tb.Text.Trim());
                if (time <= 0) {
                    AppMessageBox.Show(Loc.T("Str_Msg_InvalidTimeFormat"), Loc.T("Str_MsgTitle_Error"), MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }
                // 确认对话框
                var r = AppMessageBox.Show(
                    Loc.F("Str_Msg_ConfirmManualTimeFmt", lane, TimeFormatter.Format(time)),
                    Loc.T("Str_MsgTitle_ConfirmManualTime"), MessageBoxButton.YesNo, MessageBoxImage.Question);
                if (r != MessageBoxResult.Yes) return;
                OverrideLaneTime(lane, time);
            }
        }

        // 2026-06-05 成绩存盘路径 配置 (确认本组成绩 后 自动写 成绩 txt 到此目录)
        private string GetAutoSaveTxtDir() {
            if (!string.IsNullOrWhiteSpace(_autoSaveTxtPath)) return _autoSaveTxtPath;
            return IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Documents", "成绩txt");
        }

        /// <summary>
        /// 2026-08-28 防呆: 比赛控制转移到计时端之后, 操作员在【计时端】点"公布项目总排名(存盘)",
        /// txt 就落在计时端这台机器上, 不在主服务器 —— 赛后去主服务器找文件会扑空。
        /// 约定的做法是把计时端的存盘路径配成主服务器的共享目录(\\主服务器\成绩txt)。
        /// 这里只提示不拦截: 现场可能就是有意存本机, 不该把人挡住。
        /// </summary>
        private void WarnIfLocalSaveDirOnTimingStation(string dir) {
            if (!IsTimingClientMode) return;
            if (string.IsNullOrWhiteSpace(dir)) return;
            if (dir.StartsWith("\\")) return;                      // 已经是共享目录, 正常
            AddLog(Loc.F("Str_Log_ResultTxtLocalOnlyFmt", dir));
        }
        private void LoadAutoSaveTxtPath() {
            try {
                string cfgFile = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Documents", "autosave_path.txt");
                if (File.Exists(cfgFile)) _autoSaveTxtPath = File.ReadAllText(cfgFile, new UTF8Encoding(false)).Trim();
            } catch { }
        }
        private void SaveAutoSaveTxtPath() {
            try {
                string docDir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Documents");
                if (!Directory.Exists(docDir)) Directory.CreateDirectory(docDir);
                string cfgFile = IOPath.Combine(docDir, "autosave_path.txt");
                WriteFileAsync(cfgFile, _autoSaveTxtPath ?? "", new UTF8Encoding(false), null, Loc.T("Str_Log_SaveAutoSavePathFailedPrefix"));
            } catch (Exception ex) { AddLog(Loc.T("Str_Log_SaveAutoSavePathFailedPrefix") + ex.Message); }
        }
