            WarnIfHardwareNotConnected(Loc.T("Str_Entity_TimingSettingsPlain"));
            RunWithEditLock("timing-settings", Loc.T("Str_Entity_TimingSettingsPlain"), delegate { TimingSettingsCore(); });
