        // 2026-06-17 硬件计时器连接 子窗口 — 从"系统工作状态 → 设置 tab"独立出来的弹框入口.
        //   场景: ScheduleEditor/RTC 模式下"设置" tab 被隐藏, 通过"参数设置 → 硬件计时器连接"访问.
        //   功能: 串口/TCP/UDP 三种连接方式 + 状态显示 + 断开按钮. 不复用 xaml ComPortCombo, 独立控件.
        private void ShowHardwareConnectionDialog() {
            var dlg = new Window {
                Title = Loc.T("Str_Win_ParamsHub_HwConnBtn"), Width = 520, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"))
            };
            var sp = new StackPanel { Margin = new Thickness(20) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_Win_ParamsHub_HwConnBtn"), FontSize = 17, FontWeight = FontWeights.Bold, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 10) });
            // 当前状态行
            var statusRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 14) };
            statusRow.Children.Add(new TextBlock { Text = Loc.T("Str_Win_HwConn_CurrentStatusLabel"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), VerticalAlignment = VerticalAlignment.Center });
            var statusText = new TextBlock { FontSize = 14, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center };
            Action refreshStatus = delegate {
                bool conn = _timingBridge != null && _timingBridge.IsConnected;
                statusText.Text = conn ? Loc.T("Str_Win_HwConn_Connected") : Loc.T("Str_Win_HwConn_NotConnected");
                statusText.Foreground = new SolidColorBrush(conn ? Colors.LimeGreen : Colors.OrangeRed);
            };
            refreshStatus();
            statusRow.Children.Add(statusText);
            sp.Children.Add(statusRow);
            // 通用 Grid
            var grid = new Grid();
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(70) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            for (int i = 0; i < 4; i++) grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(38) });
            Brush brushLabel = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8"));
            Brush brushBoxBg = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155"));
            Brush brushBoxBorder = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569"));
            // Row 0: 串口
            var lblSerial = new TextBlock { Text = Loc.T("Str_Win_HwConn_SerialLabel"), Foreground = brushLabel, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lblSerial, 0); Grid.SetColumn(lblSerial, 0); grid.Children.Add(lblSerial);
            var serialRow = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
            var cbCom = new ComboBox { Width = 120, Background = brushBoxBg, Foreground = Brushes.White, BorderBrush = brushBoxBorder };
            foreach (var p in System.IO.Ports.SerialPort.GetPortNames()) cbCom.Items.Add(p);
            if (_timingConn != null && !string.IsNullOrEmpty(_timingConn.SerialPort) && cbCom.Items.Contains(_timingConn.SerialPort)) cbCom.SelectedItem = _timingConn.SerialPort;
            else if (cbCom.Items.Count > 0) cbCom.SelectedIndex = 0;
            serialRow.Children.Add(cbCom);
            serialRow.Children.Add(new TextBlock { Text = Loc.T("Str_Win_HwConn_BaudLabel"), Foreground = brushLabel, VerticalAlignment = VerticalAlignment.Center });
            var cbBaud = new ComboBox { Width = 90, Background = brushBoxBg, Foreground = Brushes.White, BorderBrush = brushBoxBorder };
            foreach (var b in new[] { "9600", "19200", "38400", "57600", "115200" }) cbBaud.Items.Add(b);
            int curBaud = (_timingConn != null && _timingConn.SerialBaudRate > 0) ? _timingConn.SerialBaudRate : 9600;
            cbBaud.SelectedItem = curBaud.ToString();
            if (cbBaud.SelectedItem == null) cbBaud.SelectedIndex = 0;
            serialRow.Children.Add(cbBaud);
            Grid.SetRow(serialRow, 0); Grid.SetColumn(serialRow, 1); grid.Children.Add(serialRow);
            var btnSerial = new Button { Content = Loc.T("Str_Win_HwConn_ConnectSerialBtn"), Padding = new Thickness(12, 4, 12, 4), Margin = new Thickness(8, 0, 0, 0), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnSerial.Click += delegate {
                if (cbCom.SelectedItem == null) { AddLog(Loc.T("Str_Log_PleaseSelectSerialPort")); return; }
                string port = cbCom.SelectedItem.ToString();
                int baud; if (!int.TryParse((cbBaud.SelectedItem ?? "9600").ToString(), out baud)) baud = 9600;
                if (_timingBridge == null) { AddLog(Loc.T("Str_Log_TimingBridgeNotInitialized")); return; }
                _timingBridge.ConnectSerial(port, baud);
                if (_timingConn != null) { _timingConn.SerialPort = port; _timingConn.SerialBaudRate = baud; _timingConn.LastType = "serial"; SaveTimingConnectionConfig(); }
                UpdateConnectionStatus();
                AddLog(Loc.F("Str_Log_SerialConnectedFmt", port, baud));
                refreshStatus();
            };
            Grid.SetRow(btnSerial, 0); Grid.SetColumn(btnSerial, 2); grid.Children.Add(btnSerial);
            // Row 1: TCP
            var lblTcp = new TextBlock { Text = Loc.T("Str_Win_HwConn_TcpLabel"), Foreground = brushLabel, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lblTcp, 1); Grid.SetColumn(lblTcp, 0); grid.Children.Add(lblTcp);
            string tcpDefault = (_timingConn != null && !string.IsNullOrEmpty(_timingConn.TcpHost)) ? (_timingConn.TcpHost + ":" + (_timingConn.TcpPort > 0 ? _timingConn.TcpPort : 5000)) : "127.0.0.1:5000";
            var tbTcp = new TextBox { Text = tcpDefault, Padding = new Thickness(4), Background = brushBoxBg, Foreground = Brushes.White, BorderBrush = brushBoxBorder, VerticalContentAlignment = VerticalAlignment.Center };
            Grid.SetRow(tbTcp, 1); Grid.SetColumn(tbTcp, 1); grid.Children.Add(tbTcp);
            var btnTcp = new Button { Content = Loc.T("Str_Win_HwConn_ConnectTcpBtn"), Padding = new Thickness(12, 4, 12, 4), Margin = new Thickness(8, 0, 0, 0), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnTcp.Click += delegate {
                string addr = tbTcp.Text.Trim();
                string[] parts = addr.Split(':');
                string host = parts[0]; int port = 5000;
                if (parts.Length > 1) int.TryParse(parts[1], out port);
                if (_timingBridge == null) { AddLog(Loc.T("Str_Log_TimingBridgeNotInitialized")); return; }
                _timingBridge.ConnectTcp(host, port);
                if (_timingConn != null) { _timingConn.TcpHost = host; _timingConn.TcpPort = port; _timingConn.LastType = "tcp"; SaveTimingConnectionConfig(); }
                UpdateConnectionStatus();
                AddLog(Loc.F("Str_Log_TcpConnectedFmt", host, port));
                refreshStatus();
            };
            Grid.SetRow(btnTcp, 1); Grid.SetColumn(btnTcp, 2); grid.Children.Add(btnTcp);
            // Row 2: UDP 监听
            var lblUdp = new TextBlock { Text = Loc.T("Str_Win_HwConn_UdpRecvLabel"), Foreground = brushLabel, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lblUdp, 2); Grid.SetColumn(lblUdp, 0); grid.Children.Add(lblUdp);
            string udpDefault = (_timingConn != null && _timingConn.UdpListenPort > 0) ? _timingConn.UdpListenPort.ToString() : "5001";
            var tbUdp = new TextBox { Text = udpDefault, Padding = new Thickness(4), Background = brushBoxBg, Foreground = Brushes.White, BorderBrush = brushBoxBorder, VerticalContentAlignment = VerticalAlignment.Center };
            Grid.SetRow(tbUdp, 2); Grid.SetColumn(tbUdp, 1); grid.Children.Add(tbUdp);
            var btnUdp = new Button { Content = Loc.T("Str_Win_HwConn_ListenUdpBtn"), Padding = new Thickness(12, 4, 12, 4), Margin = new Thickness(8, 0, 0, 0), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            // Row 3: UDP 发送 (放下面)
            var lblUdpSend = new TextBlock { Text = Loc.T("Str_Win_HwConn_UdpSendLabel"), Foreground = brushLabel, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lblUdpSend, 3); Grid.SetColumn(lblUdpSend, 0); grid.Children.Add(lblUdpSend);
            string udpSendDefault = (_timingConn != null && !string.IsNullOrEmpty(_timingConn.UdpSendHost)) ? (_timingConn.UdpSendHost + ":" + _timingConn.UdpSendPort) : "127.0.0.1:5002";
            var tbUdpSend = new TextBox { Text = udpSendDefault, Padding = new Thickness(4), Background = brushBoxBg, Foreground = Brushes.White, BorderBrush = brushBoxBorder, VerticalContentAlignment = VerticalAlignment.Center };
            Grid.SetRow(tbUdpSend, 3); Grid.SetColumn(tbUdpSend, 1); grid.Children.Add(tbUdpSend);
            btnUdp.Click += delegate {
                int listenPort; if (!int.TryParse(tbUdp.Text.Trim(), out listenPort)) listenPort = 5001;
                string sendHost = null; int sendPort = 0;
                string sendText = tbUdpSend.Text.Trim();
                if (!string.IsNullOrEmpty(sendText)) {
                    var ps = sendText.Split(':');
                    if (ps.Length == 2) { sendHost = ps[0]; int.TryParse(ps[1], out sendPort); }
                }
                if (_timingBridge == null) { AddLog(Loc.T("Str_Log_TimingBridgeNotInitialized")); return; }
                _timingBridge.ConnectUdp(listenPort, sendHost, sendPort);
                if (_timingConn != null) { _timingConn.UdpListenPort = listenPort; _timingConn.UdpSendHost = sendHost ?? ""; _timingConn.UdpSendPort = sendPort; _timingConn.LastType = "udp"; SaveTimingConnectionConfig(); }
                UpdateConnectionStatus();
                AddLog(Loc.F("Str_Log_UdpListeningFmt", listenPort, sendHost ?? "-", sendPort));
                refreshStatus();
            };
            Grid.SetRow(btnUdp, 2); Grid.SetColumn(btnUdp, 2); grid.Children.Add(btnUdp);
            sp.Children.Add(grid);
            // 底部按钮: 断开 / 关闭
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            var btnDisc = new Button { Content = Loc.T("Str_Win_HwConn_DisconnectBtn"), Padding = new Thickness(14, 6, 14, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")), Foreground = Brushes.White, BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            btnDisc.Click += delegate {
                if (_raceState != RaceState.Waiting) { AppMessageBox.Show(Loc.T("Str_Msg_CannotDisconnectNotWaiting"), Loc.T("Str_MsgTitle_Info")); return; }
                if (_timingBridge != null) _timingBridge.Disconnect();
                UpdateConnectionStatus();
                try { UpdateQuickConnectButton(); } catch { }
                AddLog(Loc.T("Str_Log_HwDisconnected"));
                try { Broadcast(); } catch { }
                refreshStatus();
            };
            btnRow.Children.Add(btnDisc);
            var btnClose = new Button { Content = Loc.T("Str_Btn_Close"), Padding = new Thickness(14, 6, 14, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnClose.Click += delegate { dlg.DialogResult = true; };
            btnRow.Children.Add(btnClose);
            sp.Children.Add(btnRow);
            dlg.Content = sp;
            dlg.ShowDialog();
        }

        // 2026-06-12 时间参数设置 子窗口 (从 参数设置 拆出 9 个时间参数). 确认=应用并同步硬件; 取消=不改.
        private void ShowTimeParamsDialog() {
            var dlg = new Window {
                Title = Loc.T("Str_Win_TimeParams_Title"),
                Width = 420,
                SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this, ResizeMode = ResizeMode.NoResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"))
            };
            var sp = new StackPanel { Margin = new Thickness(20) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_Win_TimeParams_Title"), FontSize = 17, FontWeight = FontWeights.Bold, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 14) });

            var tbCloseTime = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_LaneCloseTime"), _laneCloseSettings.LaneCloseTime.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            var tbSBDelay = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_StartBlockCloseDelay"), _laneCloseSettings.StartBlockCloseDelay.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            var tbConfDelay = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_ResultConfirmCloseDelay"), _laneCloseSettings.ResultConfirmCloseDelay.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            var tbFSThresh = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_FalseStartThreshold"), _laneCloseSettings.FalseStartThreshold.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            var tbRelayFSThresh = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_RelayHandoffFalseStartThreshold"), _laneCloseSettings.RelayHandoffFalseStartThreshold.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            var tbSplitDisp = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_SplitDisplayTime"), _laneCloseSettings.SplitDisplayTime.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            //2026-05-18 盲表代替成绩延迟时间统一为整秒(与其它字段一致)；硬件 case 端 ×10 转 0.1s 单位
            double blindDispl = _laneCloseSettings.BlindReplaceDelay;
            if (blindDispl < 0) blindDispl = 0;
            if (blindDispl > 9) blindDispl = 9;
            var tbBlindReplace = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_BlindReplaceDelay"), ((int)Math.Round(blindDispl)).ToString(), Loc.T("Str_Win_TimeParams_UnitSec0to9"));
            // 2026-06-03 接力 reaction 事件窗口 — 第一个事件 (TP/SB/MB/手动 TP) 到达起 N 秒倒计时, 收集相关事件算 SB 反应时
            var tbReactionWin = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_ReactionEventWindow"), _laneCloseSettings.ReactionEventWindowSec.ToString("F1"), Loc.T("Str_Win_TimeParams_UnitSec1to10"));
            var tbFirstHold = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_FirstPlaceHoldTime"), _laneCloseSettings.FirstPlaceHoldTime.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));
            var tbBigPage = AddSettingsRow(sp, Loc.T("Str_Win_TimeParams_BigDisplayPageInterval"), _laneCloseSettings.BigDisplayPageInterval.ToString(), Loc.T("Str_Win_TimeParams_UnitSec"));

            var timeBtnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            var timeCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")), Foreground = Brushes.White, BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            timeCancel.Click += delegate { dlg.DialogResult = false; };
            var timeOk = new Button { Content = Loc.T("Str_MsgTitle_Confirm"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = Brushes.White, BorderThickness = new Thickness(0), FontWeight = FontWeights.Bold };
            timeOk.Click += delegate { dlg.DialogResult = true; };
            timeBtnPanel.Children.Add(timeCancel);
            timeBtnPanel.Children.Add(timeOk);
            sp.Children.Add(timeBtnPanel);
            dlg.Content = sp;

            if (dlg.ShowDialog() == true) {
                double v;
                if (double.TryParse(tbCloseTime.Text, out v)) _laneCloseSettings.LaneCloseTime = v;
                if (double.TryParse(tbSBDelay.Text, out v)) _laneCloseSettings.StartBlockCloseDelay = v;
                if (double.TryParse(tbConfDelay.Text, out v)) _laneCloseSettings.ResultConfirmCloseDelay = v;
                if (double.TryParse(tbFSThresh.Text, out v)) _laneCloseSettings.FalseStartThreshold = v;
                if (double.TryParse(tbRelayFSThresh.Text, out v)) _laneCloseSettings.RelayHandoffFalseStartThreshold = v;
                if (double.TryParse(tbSplitDisp.Text, out v)) _laneCloseSettings.SplitDisplayTime = v;
                //2026-05-18 盲表代替成绩延迟统一为整秒, 限定 0-9
                if (double.TryParse(tbBlindReplace.Text, out v)) {
                    if (v < 0) v = 0;
                    if (v > 9) v = 9;
                    _laneCloseSettings.BlindReplaceDelay = Math.Round(v, 0);
                }
                if (double.TryParse(tbReactionWin.Text, out v)) {
                    if (v < 1.0) v = 1.0;
                    if (v > 10.0) v = 10.0;
                    _laneCloseSettings.ReactionEventWindowSec = v;
                }
                if (double.TryParse(tbFirstHold.Text, out v)) _laneCloseSettings.FirstPlaceHoldTime = v;
                if (double.TryParse(tbBigPage.Text, out v)) _laneCloseSettings.BigDisplayPageInterval = v;
                foreach (var st in _laneDeviceStates) st.LaneCloseTime = 0;
                SaveTimingSettings();
                // 2026-09-20 _laneCloseSettings 已经有 PushSettingsToServer() 这条专用的轻量
                // 同步通道了, 不需要 AutoSaveData() 再顺带推一次整包。
                SaveWithoutPush();
                UpdateLaneStatusDisplay();
                Broadcast();
                SendTimingSettingsToHardware();   // 同步时间参数到硬件计时器
                PushSettingsToServer();           // 2026-08-31 让主服务器也应用
                WriteConfigToDbNow();             // 2026-08-31 参数设置按确认 = 立即入库(成绩才等确认本组成绩)
                AddLog(Loc.F("Str_Log_TimeParamsUpdatedFmt",
                    _laneCloseSettings.LaneCloseTime, _laneCloseSettings.StartBlockCloseDelay,
                    _laneCloseSettings.ResultConfirmCloseDelay, _laneCloseSettings.FalseStartThreshold,
                    _laneCloseSettings.SplitDisplayTime, _laneCloseSettings.BlindReplaceDelay,
                    _laneCloseSettings.ReactionEventWindowSec, _laneCloseSettings.FirstPlaceHoldTime,
                    _laneCloseSettings.BigDisplayPageInterval));
            }
        }

        // 2026-06-12 比赛泳池、设备状态设置 子窗口 (从 参数设置 拆出 终点位置/反应时/盲表代触板/硬件设备/出发边沿/道次顺序/泳池触板 + 设备管理按钮). 确认=应用并同步; 取消=不改.
        private void ShowPoolDeviceSettingsDialog() {
            var dlg = new Window {
                Title = Loc.T("Str_Win_PoolDevice_Title"),
                Width = 440,
                SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this, ResizeMode = ResizeMode.NoResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"))
            };
            var sp = new StackPanel { Margin = new Thickness(20) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_Win_PoolDevice_Title"), FontSize = 17, FontWeight = FontWeights.Bold, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 14) });

            // 终点位置
            var finishRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            finishRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_FinishPos"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbLeft = new RadioButton { Content = Loc.T("Str_Radio_FinishLeft"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.FinishPosition == "left", GroupName = "FinPos", Margin = new Thickness(0, 0, 12, 0) };
            var rbRight = new RadioButton { Content = Loc.T("Str_Radio_FinishRight"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.FinishPosition == "right", GroupName = "FinPos" };
            finishRow.Children.Add(rbLeft);
            finishRow.Children.Add(rbRight);
            sp.Children.Add(finishRow);

            // 反应时检测（RT）开关：关闭后所有出发反应时相关处理跳过
            var rtRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            rtRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_ReactionTime"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbRtOn = new RadioButton { Content = Loc.T("Str_Radio_On"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.ReactionTimeEnabled, GroupName = "RTSwitch", Margin = new Thickness(0, 0, 12, 0) };
            var rbRtOff = new RadioButton { Content = Loc.T("Str_Radio_Off"), Foreground = Brushes.White, FontSize = 14, IsChecked = !_laneCloseSettings.ReactionTimeEnabled, GroupName = "RTSwitch" };
            rtRow.Children.Add(rbRtOn);
            rtRow.Children.Add(rbRtOff);
            sp.Children.Add(rtRow);

            // 2026-06-06 盲表代替触板 (PC 端自动用盲表中位数补当前段缺失的触板成绩)
            var blindRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            blindRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_BlindReplace"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbBlindOn = new RadioButton { Content = Loc.T("Str_Radio_BlindOn"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.AutoBlindReplaceTouchpad, GroupName = "BlindReplace", Margin = new Thickness(0, 0, 12, 0) };
            var rbBlindOff = new RadioButton { Content = Loc.T("Str_Radio_BlindOff"), Foreground = Brushes.White, FontSize = 14, IsChecked = !_laneCloseSettings.AutoBlindReplaceTouchpad, GroupName = "BlindReplace" };
            blindRow.Children.Add(rbBlindOn);
            blindRow.Children.Add(rbBlindOff);
            sp.Children.Add(blindRow);

            // 2026-06-14 手动 TP 代替真 TP: 开=手动 TP 即使该段已有真触板也覆盖; 关=仅无 TP 时应急, 已有真 TP 只记备份
            var manualTpRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            manualTpRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_ManualTpReplace"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbManualTpOn = new RadioButton { Content = Loc.T("Str_Radio_ManualTpOn"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.ManualTpReplaceTp, GroupName = "ManualTpReplace", Margin = new Thickness(0, 0, 12, 0) };
            var rbManualTpOff = new RadioButton { Content = Loc.T("Str_Radio_ManualTpOff"), Foreground = Brushes.White, FontSize = 14, IsChecked = !_laneCloseSettings.ManualTpReplaceTp, GroupName = "ManualTpReplace" };
            manualTpRow.Children.Add(rbManualTpOn);
            manualTpRow.Children.Add(rbManualTpOff);
            sp.Children.Add(manualTpRow);

            // 2026-06-02 硬件设备状态: 一直打开 / 按比赛流程
            //   "一直打开" = 硬件 TP/SB/MB 按键路径忽略 *_Open_Close_State 关闭状态, 只跳过 ==3 坏 / ==4 未装. 让 PC 端拿到所有按键事件
            //   "按流程"   = 原行为 (硬件按比赛流程时序自动开/关设备)
            var hwOpenRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            hwOpenRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_HwDevice"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbHwAlwaysOpen = new RadioButton { Content = Loc.T("Str_Radio_HwAlwaysOpen"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.HardwareAlwaysOpen, GroupName = "HwOpenMode", Margin = new Thickness(0, 0, 12, 0) };
            var rbHwFlow = new RadioButton { Content = Loc.T("Str_Radio_HwFlow"), Foreground = Brushes.White, FontSize = 14, IsChecked = !_laneCloseSettings.HardwareAlwaysOpen, GroupName = "HwOpenMode" };
            hwOpenRow.Children.Add(rbHwAlwaysOpen);
            hwOpenRow.Children.Add(rbHwFlow);
            sp.Children.Add(hwOpenRow);

            // 2026-06-03 出发信号边沿 — 硬件 SB 按键有效边沿 (下降沿 / 上升沿), 0x41 帧 d7 下发硬件
            var edgeRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            edgeRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_StartEdge"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbEdgeFall = new RadioButton { Content = Loc.T("Str_Radio_EdgeFall"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.StartBoxEdgeFalling, GroupName = "SBEdge", Margin = new Thickness(0, 0, 12, 0) };
            var rbEdgeRise = new RadioButton { Content = Loc.T("Str_Radio_EdgeRise"), Foreground = Brushes.White, FontSize = 14, IsChecked = !_laneCloseSettings.StartBoxEdgeFalling, GroupName = "SBEdge" };
            edgeRow.Children.Add(rbEdgeFall);
            edgeRow.Children.Add(rbEdgeRise);
            sp.Children.Add(edgeRow);

            // 道次显示顺序：正序=顶到底为 0→9；逆序=顶到底为 9→0（同步给硬件计时器及所有 UI）
            var orderRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            orderRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_LaneOrder"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbOrderFwd = new RadioButton { Content = Loc.T("Str_Radio_OrderFwd"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.LaneOrder != "reverse", GroupName = "LaneOrder", Margin = new Thickness(0, 0, 12, 0) };
            var rbOrderRev = new RadioButton { Content = Loc.T("Str_Radio_OrderRev"), Foreground = Brushes.White, FontSize = 14, IsChecked = _laneCloseSettings.LaneOrder == "reverse", GroupName = "LaneOrder" };
            orderRow.Children.Add(rbOrderFwd);
            orderRow.Children.Add(rbOrderRev);
            sp.Children.Add(orderRow);

            //2026-05-12 新增：泳池触板安装方式（单边/两端）
            //  HasRightStartBlock=true  -> 两端都有触板
            //  HasRightStartBlock=false -> 只有一端有触板（单边）
            var poolTpRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
            poolTpRow.Children.Add(new TextBlock { Text = Loc.T("Str_PoolDevice_PoolTp"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center, Width = 140 });
            var rbTpBoth = new RadioButton { Content = Loc.T("Str_Radio_TpBoth"), Foreground = Brushes.White, FontSize = 14, IsChecked = _poolConfig != null && _poolConfig.HasRightStartBlock, GroupName = "PoolTP", Margin = new Thickness(0, 0, 12, 0) };
            var rbTpSingle = new RadioButton { Content = Loc.T("Str_Radio_TpSingle"), Foreground = Brushes.White, FontSize = 14, IsChecked = _poolConfig != null && !_poolConfig.HasRightStartBlock, GroupName = "PoolTP" };
            poolTpRow.Children.Add(rbTpBoth);
            poolTpRow.Children.Add(rbTpSingle);
            sp.Children.Add(poolTpRow);

            // 设备状态管理按钮
            var deviceSep = new Border { BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")), BorderThickness = new Thickness(0, 1, 0, 0), Margin = new Thickness(0, 10, 0, 0), Padding = new Thickness(0, 10, 0, 0) };
            var btnDeviceMgr = new Button { Content = Loc.T("Str_Btn_DeviceStatusMgr"), Padding = new Thickness(0, 8, 0, 8), FontSize = 14, FontWeight = FontWeights.Bold, Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#8B5CF6")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnDeviceMgr.Click += delegate { dlg.DialogResult = false; DeviceStatus_Click(null, null); };
            var btnBlindMgr = new Button { Content = Loc.T("Str_Win_BlindWatchCount_Title"), Padding = new Thickness(0, 8, 0, 8), FontSize = 14, FontWeight = FontWeights.Bold, Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")), Foreground = Brushes.Black, BorderThickness = new Thickness(0), Margin = new Thickness(0, 6, 0, 0) };
            btnBlindMgr.Click += delegate { dlg.DialogResult = false; OpenBlindWatchCountDialog(); };

            //2026-05-14 删除"全部道设备：全开 / 恢复正常关闭流程"两个按钮 —— 改由
            // 比赛控制 → 泳道控制 → "全部打开 / 全部关闭" 直接调用同一硬件命令，
            // 同时增加"道次打开 / 道次关闭"对选定单道的硬件控制（新增 0x47 协议命令）。

            var deviceStack = new StackPanel();
            deviceStack.Children.Add(btnDeviceMgr);
            deviceStack.Children.Add(btnBlindMgr);
            deviceSep.Child = deviceStack;
            sp.Children.Add(deviceSep);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")), Foreground = Brushes.White, BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            var btnOk = new Button { Content = Loc.T("Str_MsgTitle_Confirm"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = Brushes.White, BorderThickness = new Thickness(0), FontWeight = FontWeights.Bold };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            btnPanel.Children.Add(btnCancel);
            btnPanel.Children.Add(btnOk);
            sp.Children.Add(btnPanel);

            // 高度自适应内容，无滚动条
            dlg.Content = sp;

            //2026-05-18 进入对话框前保存"非参数"状态（IsFinished + 左右剩余圈数手动偏移）
            //   这些字段会被对话框确定时的 ResetForNewRace(StartPosition) 清零，但它们与参数设置无关
            //   保存进入前的值，确定后恢复。用户取消时无副作用。
            var savedLaneSnap = new System.Collections.Generic.List<int[]>();
            foreach (var st in _laneDeviceStates) {
                savedLaneSnap.Add(new int[] {
                    st.IsFinished ? 1 : 0,
                    st.LeftLapManualAdjust,
                    st.RightLapManualAdjust
                });
            }

            if (dlg.ShowDialog() == true) {
                //2026-05-18 记下 FinishPosition 的旧值，对话框 OK 后判断是否变化以决定是否刷新 NotInstalled
                string oldFinishForInstall = _laneCloseSettings != null ? _laneCloseSettings.FinishPosition : "left";
                _laneCloseSettings.ReactionTimeEnabled = rbRtOn.IsChecked == true;
                _laneCloseSettings.AutoBlindReplaceTouchpad = rbBlindOn.IsChecked == true;   // 2026-06-06
                _laneCloseSettings.ManualTpReplaceTp = rbManualTpOn.IsChecked == true;       // 2026-06-14 手动TP代替真TP
                _laneCloseSettings.HardwareAlwaysOpen = rbHwAlwaysOpen.IsChecked == true;
                _laneCloseSettings.StartBoxEdgeFalling = rbEdgeFall.IsChecked == true;
                _laneCloseSettings.LaneOrder = rbOrderRev.IsChecked == true ? "reverse" : "forward";
                string newFinish = rbRight.IsChecked == true ? "right" : "left";
                _laneCloseSettings.FinishPosition = newFinish;
                _laneCloseSettings.StartPosition = newFinish;
                AutoAdjustStartPosition();
                if (_raceState == RaceState.Waiting || _raceState == RaceState.Ready) {
                    bool isBack4 = IsBackstrokeStartEvent(_currentEvent);
                    foreach (var st in _laneDeviceStates) st.ResetForNewRace(_laneCloseSettings.StartPosition, isBack4);
                }
                foreach (var st in _laneDeviceStates) st.LaneCloseTime = 0;

                //2026-05-12 应用并同步新的"泳池触板安装方式"
                bool newHasRight = rbTpBoth.IsChecked == true;
                bool poolTpChanged = (_poolConfig != null) && (_poolConfig.HasRightStartBlock != newHasRight);
                if (_poolConfig != null) _poolConfig.HasRightStartBlock = newHasRight;
                _laneCloseSettings.HasRightStartBlock = newHasRight;   // 2026-05-26 持久化到 timing_settings.json
                //2026-05-13 新增：切换后立即把每条泳道右端触板/出发台/盲表的"未安装"标记翻转，
                // 否则现场看到的设备图标不会跟着改变；同时立刻下发硬件位图，让硬件不再期待右端信号
                //2026-05-18 扩展: 终点位置切换 (finishChanged) 也要重刷 NotInstalled ——
                //   单端模式下"非终点端"由 FinishPosition 决定，FinishPosition 变了之后非终点端要跟着翻转
                bool finishChanged = (oldFinishForInstall != newFinish);
                if (poolTpChanged || finishChanged) {
                    ApplyTouchpadInstallModeToLanes();
                    SendDeviceStatusesToHardware();   // 0x46/0x49/0x4A 把"未安装"反映成硬件 bit=0
                    try { SaveDeviceStates(); } catch { }   // 2026-05-26 计算后的 NotInstalled 立即落盘
                }

                SaveTimingSettings();
                SaveWithoutPush();   // 2026-09-20 同 ShowTimeParamsDialog: 有 PushSettingsToServer() 专用通道
                UpdateLaneStatusDisplay();
                Broadcast();
                SendTimingSettingsToHardware();   // 同步到硬件计时控制器
                //2026-05-18 LaneOrder 切换后位图编码方向变了，必须重发 0x43 让硬件按新屏幕位置布局显示空泳道
                try { SendSetMatchEventToHardware(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_ResendSetMatchEventFailedFmt", ex.Message)); }
                //2026-05-12 把泳池触板安装方式下发到硬件（0x3A Set_PoolSingleOrDoubleTP）
                if (_timingBridge != null && _timingBridge.IsConnected) {
                    try { _timingBridge.SendPoolSingleOrDoubleTP(!newHasRight); } catch { }
                }
                PushSettingsToServer();           // 2026-08-31 让主服务器也应用, 不只是转发
                WriteConfigToDbNow();             // 2026-08-31 参数设置按确认 = 立即入库(成绩才等确认本组成绩)
                AddLog(Loc.F("Str_Log_PoolDeviceParamsUpdatedFmt",
                    _laneCloseSettings.FinishPosition == "left" ? "左端" : "右端",
                    _laneCloseSettings.ReactionTimeEnabled ? "打开" : "关闭",
                    _laneCloseSettings.LaneOrder == "reverse" ? "逆序9→0" : "正序0→9",
                    newHasRight ? "两端" : "单边",
                    _laneCloseSettings.StartBoxEdgeFalling ? "下降沿" : "上升沿",
                    _laneCloseSettings.AutoBlindReplaceTouchpad ? "开" : "关",
                    _laneCloseSettings.HardwareAlwaysOpen ? "一直打开" : "按流程",
                    _laneCloseSettings.ManualTpReplaceTp ? "开" : "关"));
                if (poolTpChanged) AddLog(Loc.T("Str_Log_PoolTpMountChangedSynced"));

                //2026-05-18 恢复"非参数"状态 + 刷新硬件主控显示
                //   ResetForNewRace 会清掉 IsFinished / LeftLapManualAdjust / RightLapManualAdjust，
                //   但这三个字段与参数设置无关，应保留进入对话框前的值。
                for (int i = 0; i < _laneDeviceStates.Count && i < savedLaneSnap.Count; i++) {
                    _laneDeviceStates[i].IsFinished           = savedLaneSnap[i][0] != 0;
                    _laneDeviceStates[i].LeftLapManualAdjust  = savedLaneSnap[i][1];
                    _laneDeviceStates[i].RightLapManualAdjust = savedLaneSnap[i][2];
                }
                UpdateLaneStatusDisplay();
                //2026-05-18 让硬件主控按新参数完整重画一遍。
                //2026-05-25 硬件 PDF 必修 #1 修复完成: 0x65 case 不再调 SwimControl_init,
                //   改为只做局部 UI 重画, 所有业务字段保留, 不会丢失 race distance / All_Lap /
                //   LAll_Lap / RAll_Lap / RelayBit / Pool50mOr25mbit 等。
                //   ＊原"RefreshDisplay 后补发 RaceDistance"补救已移除＊
                try { if (_timingBridge != null && _timingBridge.IsConnected) _timingBridge.SendRefreshDisplay(); } catch { }
            }
        }

        private void OpenBlindWatchCountDialog() {
            var dlg = new Window {
                Title = Loc.T("Str_Win_BlindWatchCount_Title"),
                Width = 400, Height = 280,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this, ResizeMode = ResizeMode.NoResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"))
            };
            var sp = new StackPanel { Margin = new Thickness(20) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_Win_BlindWatchCount_Title"), FontSize = 17, FontWeight = FontWeights.Bold, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 6) });
            sp.Children.Add(new TextBlock {
                Text = Loc.T("Str_BlindWatch_Desc"),
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")),
                FontSize = 12, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 14)
            });

            Func<string, int, ComboBox> mkRow = delegate (string label, int sel) {
                var row = new Grid { Margin = new Thickness(0, 0, 0, 10) };
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(120) });
                row.Children.Add(new TextBlock {
                    Text = label, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")),
                    FontSize = 15, VerticalAlignment = VerticalAlignment.Center
                });
                var cb = new ComboBox {
                    Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155")),
                    Foreground = Brushes.Black, FontSize = 15, FontWeight = FontWeights.Bold
                };
                cb.Items.Add("0"); cb.Items.Add("1"); cb.Items.Add("2"); cb.Items.Add("3");
                cb.SelectedIndex = (sel < 0 ? 0 : (sel > 3 ? 3 : sel));   // 2026-06-13 0-3 (索引=数量)
                Grid.SetColumn(cb, 1);
                row.Children.Add(cb);
                sp.Children.Add(row);
                return cb;
            };
            var cbLeft = mkRow("左边 盲表数量", _laneCloseSettings.LeftBlindWatchCount);
            var cbRight = mkRow("右边 盲表数量", _laneCloseSettings.RightBlindWatchCount);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            var btnCancel = new Button {
                Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")),
                Foreground = Brushes.White, BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0)
            };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            var btnOk = new Button {
                Content = Loc.T("Str_Btn_OK"), Padding = new Thickness(16, 6, 16, 6),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")),
                Foreground = Brushes.White, BorderThickness = new Thickness(0), FontWeight = FontWeights.Bold
            };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            btnPanel.Children.Add(btnCancel);
            btnPanel.Children.Add(btnOk);
            sp.Children.Add(btnPanel);

            dlg.Content = sp;
            if (dlg.ShowDialog() == true) {
                int newLeft = cbLeft.SelectedIndex;      // 2026-06-13 0-3: 索引即数量
                int newRight = cbRight.SelectedIndex;
                bool changed = (_laneCloseSettings.LeftBlindWatchCount != newLeft) || (_laneCloseSettings.RightBlindWatchCount != newRight);
                _laneCloseSettings.LeftBlindWatchCount = newLeft;
                _laneCloseSettings.RightBlindWatchCount = newRight;
                // 2026-06-16 (方案 C) 改盲表数量同时重置每道 LaneDeviceState 的 Broken/NotInstalled 状态:
                //   < newLeft → 安装好 (NotInstalled=false, Broken=false); >= newLeft → 未装 (NotInstalled=true).
                //   用户既然把数量改成 N, 意味着这 N 个现在可用 — 清掉之前的 Broken/NotInstalled 标记.
                //   跟硬件 Set_MB_Num case 重置 Bad(=3)→Close(=0) 语义一致, 防止 0x46 把旧 Broken 状态发回硬件覆盖.
                foreach (var st in _laneDeviceStates) {
                    st.LeftBlindWatch1Broken = false;
                    st.LeftBlindWatch2Broken = false;
                    st.LeftBlindWatch3Broken = false;
                    st.LeftBlindWatch1NotInstalled = (newLeft < 1);
                    st.LeftBlindWatch2NotInstalled = (newLeft < 2);
                    st.LeftBlindWatch3NotInstalled = (newLeft < 3);
                    st.RightBlindWatch1Broken = false;
                    st.RightBlindWatch2Broken = false;
                    st.RightBlindWatch3Broken = false;
                    st.RightBlindWatch1NotInstalled = (newRight < 1);
                    st.RightBlindWatch2NotInstalled = (newRight < 2);
                    st.RightBlindWatch3NotInstalled = (newRight < 3);
                }
                // 2026-05-26 用户要求"点确认就存", 不再用 if(changed) 跳过 IO
                SaveTimingSettings();
                // 2026-08-31 上面那个 foreach 改的是【设备状态】(NotInstalled/Broken),
                //   它存在 device_states.json 里, 不归 SaveTimingSettings 管 ——
                //   原来漏了这一句, 所以改完不落盘: 下次 ApplyPersistedDeviceStates
                //   从文件读回来的还是旧的, 换组重建界面就变回去了。
                SaveDeviceStates();
                SaveWithoutPush();   // 2026-09-20 同 ShowTimeParamsDialog: 有 PushSettingsToServer() 专用通道
                UpdateLaneStatusDisplay();
                if (changed) {
                    Broadcast();                       // 同步到 Web/Remote 控制台
                    SendBlindWatchCountToHardware();   // 0x45 Set_MB_Num
                    // 2026-06-16 (方案 B) 跟 0x45 一起发 0x46 同步 MB1 状态. 之前只发 0x45 不发 0x46, 硬件 MB[0][i]=Bad
                    // 状态保留 → UI 显示黑色. 现在先重置 LaneDeviceState (上面 foreach), 再发 0x46 → 硬件清掉 Bad.
                    SendDeviceStatusesToHardware();    // 0x46 把"非 Broken/NotInstalled"状态推到硬件
                    PushSettingsToServer();            // 2026-08-31 让主服务器也应用, 不只是转发
                    WriteConfigToDbNow();             // 2026-08-31 参数设置按确认 = 立即入库(成绩才等确认本组成绩)
                    AddLog(Loc.F("Str_Log_BlindCountUpdatedFmt", newLeft, newRight));
                }
            }
        }

        private TextBox AddSettingsRow(StackPanel parent, string label, string value, string unit) {
            var row = new Grid { Margin = new Thickness(0, 0, 0, 10) };
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(70) });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(24) });
            var lbl = new TextBlock { Text = label, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 15, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetColumn(lbl, 0);
            var tb = new TextBox { Text = value, Padding = new Thickness(4), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155")), Foreground = Brushes.White, BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")), FontSize = 15, TextAlignment = TextAlignment.Center };
            Grid.SetColumn(tb, 1);
            var unitTb = new TextBlock { Text = unit, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 13, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(4, 0, 0, 0) };
            Grid.SetColumn(unitTb, 2);
            row.Children.Add(lbl);
            row.Children.Add(tb);
            row.Children.Add(unitTb);
            parent.Children.Add(row);
            return tb;
        }

