            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Auto) });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Auto) });

            mainGrid.Children.Add(new TextBlock { Text = Loc.T("Str_Win_ManualButtonsUse_Title"), FontSize = 17, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 12) });

            var dataGrid = new DataGrid {
                AutoGenerateColumns = false, CanUserAddRows = false,
                IsReadOnly = false, FontSize = 14, RowHeight = 30,
                AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                HeadersVisibility = DataGridHeadersVisibility.Column
            };

            dataGrid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_LaneNo"), Binding = new System.Windows.Data.Binding("Lane"), Width = new DataGridLength(60), IsReadOnly = true });
            dataGrid.Columns.Add(new DataGridCheckBoxColumn { Header = Loc.T("Str_Col_LeftManualUse"), Binding = new System.Windows.Data.Binding("LeftEnabled"), Width = new DataGridLength(100) });
            dataGrid.Columns.Add(new DataGridCheckBoxColumn { Header = Loc.T("Str_Col_RightManualUse"), Binding = new System.Windows.Data.Binding("RightEnabled"), Width = new DataGridLength(100) });

            var items = new List<ManualBtnItem>();
            foreach (var ls in _laneDeviceStates) {
                items.Add(new ManualBtnItem { Lane = ls.Lane, LeftEnabled = ls.LeftManualEnabled, RightEnabled = ls.RightManualEnabled });
            }
            dataGrid.ItemsSource = items;
            Grid.SetRow(dataGrid, 1);
            mainGrid.Children.Add(dataGrid);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var btnAllOn = new Button { Content = Loc.T("Str_Btn_SetAllUse"), Padding = new Thickness(16, 6, 16, 6), Margin = new Thickness(0, 0, 8, 0) };
            btnAllOn.Click += delegate { foreach (var it in items) { it.LeftEnabled = true; it.RightEnabled = true; } dataGrid.Items.Refresh(); };
            var btnAllOff = new Button { Content = Loc.T("Str_Btn_SetAllNotUse"), Padding = new Thickness(16, 6, 16, 6), Margin = new Thickness(0, 0, 16, 0) };
            btnAllOff.Click += delegate { foreach (var it in items) { it.LeftEnabled = false; it.RightEnabled = false; } dataGrid.Items.Refresh(); };
            var btnOK = new Button { Content = Loc.T("Str_MsgTitle_Confirm"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = Brushes.White, BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            btnOK.Click += delegate {
                for (int i = 0; i < items.Count && i < _laneDeviceStates.Count; i++) {
                    _laneDeviceStates[i].LeftManualEnabled = items[i].LeftEnabled;
                    _laneDeviceStates[i].RightManualEnabled = items[i].RightEnabled;
                    if (!items[i].LeftEnabled) _laneDeviceStates[i].LeftManualStatus = DeviceStatus.Closed;
                    if (!items[i].RightEnabled) _laneDeviceStates[i].RightManualStatus = DeviceStatus.Closed;
                }
                SaveDeviceStates();              // 同 device_states.json 持久化
                UpdateLaneStatusDisplay();
                Broadcast();
                AddLog(Loc.T("Str_Log_ManualButtonSettingsUpdated"));
                dlg.Close();
            };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6) };
            btnCancel.Click += delegate { dlg.Close(); };
            btnPanel.Children.Add(btnAllOn); btnPanel.Children.Add(btnAllOff);
            btnPanel.Children.Add(btnOK); btnPanel.Children.Add(btnCancel);
            Grid.SetRow(btnPanel, 2);
            mainGrid.Children.Add(btnPanel);

            dlg.Content = mainGrid;
            dlg.ShowDialog();
        }

