        /// <summary>
        /// 检查运动员是否重复（同姓名+同性别+同项目视为重复）
        /// 返回重复的运动员，无重复返回null
        /// </summary>
        private Swimmer FindDuplicate(string name, string gender, string eventName, string bibNumber, string idNumber = "", string country = "") {
            foreach (var s in _swimmers) {
                // 1. 身份证号相同且非空 + 同项目 = 重复（最高优先级 — 唯一权威标识）
                if (!string.IsNullOrEmpty(idNumber) && !string.IsNullOrEmpty(s.IDNumber) && s.IDNumber == idNumber && s.EventName == eventName) return s;
                // 2. 号码牌相同且非空 + 同项目 = 重复
                if (!string.IsNullOrEmpty(bibNumber) && !string.IsNullOrEmpty(s.BibNumber) && s.BibNumber == bibNumber && s.EventName == eventName) return s;
                // 3. 同姓名 + 同性别 + 同代表队 + 同项目 = 重复
                //    2026-05-21 修复"同名同姓不同人被错误拦截"：当任一方有身份证号时，
                //    规则 1 已做过权威判定（命中即返回；未命中即 ID 不同 → 不同人），
                //    规则 3 必须收紧为"双方都无 ID 时"才退化到姓名匹配，否则会把同名
                //    但不同 ID 的真不同人误判为重复，导致无法导入。
                //    接力队调用 FindDuplicate(idNumber="")，规则 3 仍按队名+性别+项目正常生效。
                bool bothMissId = string.IsNullOrEmpty(idNumber) && string.IsNullOrEmpty(s.IDNumber);
                if (bothMissId && !string.IsNullOrEmpty(name) && s.Name == name && SgMatch(s.Gender, gender)
                    && (s.Country ?? "") == (country ?? "") && s.EventName == eventName) return s;
            }
            return null;
        }

        // 生成下一个参赛号：若该代表队配置了号码段，则在段内取最小未用号码；
        // 否则回退到全局 (max+1) 逻辑。
        // 2026-09-22 gender 可选: 传了性别且该号码段配了男/女单独子范围时, 优先用子范围
        //   (参赛单位及号码分配新功能); 不传/没配子范围时行为与之前完全一致(合用 Start/End)。
        private string GenerateNextBibNumber(string country = null, string gender = null) {
            BibRange range = null;
            if (!string.IsNullOrEmpty(country)) {
                range = _bibRanges.FirstOrDefault(r => r.Country == country && r.Start > 0 && r.End >= r.Start);
            }
            int rStart = range != null ? range.Start : 0;
            int rEnd = range != null ? range.End : 0;
            if (range != null && !string.IsNullOrEmpty(gender)) {
                if (gender.Contains("男") && range.MaleStart > 0 && range.MaleEnd >= range.MaleStart) { rStart = range.MaleStart; rEnd = range.MaleEnd; }
                else if (gender.Contains("女") && range.FemaleStart > 0 && range.FemaleEnd >= range.FemaleStart) { rStart = range.FemaleStart; rEnd = range.FemaleEnd; }
            }
            var usedNums = new HashSet<int>();
            foreach (var s in _swimmers) {
                int n;
                if (!string.IsNullOrEmpty(s.BibNumber) && int.TryParse(s.BibNumber, out n)) usedNums.Add(n);
            }
            if (range != null && rStart > 0 && rEnd >= rStart) {
                int width = range.Width > 0 ? range.Width : 3;
                for (int i = rStart; i <= rEnd; i++) {
                    if (!usedNums.Contains(i)) return i.ToString("D" + width);
                }
                AddLog(Loc.F("Str_Log_TeamBibRangeExhaustedFmt", country, rStart, rEnd));
            }
            int max = 0;
            foreach (int n in usedNums) if (n > max) max = n;
            int defaultWidth = (range != null && range.Width > 0) ? range.Width : 3;
            return (max + 1).ToString("D" + defaultWidth);
        }

        // 2026-07-09 一次性修复: 补齐所有空 BibNumber (= 修 2026-07-03 之前旧数据里空 bib,
        //   会导致 EditSwapLane_Click 用 BibNumber 查找时 FirstOrDefault 撞第 1 个空 bib).
        //   由 EditSwapLane_Click 等入口静默调用: 有空 bib → 一次性补齐 + AutoSave; 无空 bib → 立即返回不做事.
        private void EnsureAllSwimmerBibs() {
            int fixCount = 0;
            foreach (var s in _swimmers) {
                if (s == null) continue;
                if (string.IsNullOrEmpty(s.BibNumber)) {
                    s.BibNumber = GenerateNextBibNumber(s.Country ?? "");
                    fixCount++;
                }
            }
            if (fixCount > 0) {
                AutoSaveData();
                AddLog(Loc.F("Str_Log_FixedEmptyBibFmt", fixCount));
            }
        }

        private void AddSwimmer_Click(object sender, RoutedEventArgs e) {
            // 新增需要全局唯一参赛号 → 占"新增"位锁，避免两端同时新增冲突
            string holder;
            if (!TryAcquireEditLock("swimmer-add", out holder)) {
                AppMessageBox.Show(Loc.F("Str_Msg_SwimmerAddingBusyFmt", holder),
                    Loc.T("Str_MsgTitle_CannotAdd"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                // 弹出与"修改选中"一致的对话框，要求一次填齐运动员信息
                var sw = new Swimmer {
                    BibNumber = GenerateNextBibNumber(),
                    Gender = "男",
                    CurrentStage = "决赛"
                };
                if (OpenSwimmerEditor(sw, isNew: true)) {
                    _swimmers.Add(sw);
                    RefreshOverviewStats();
                    RefreshSwimmerFilter();
                    FinishAndSyncPatch(BuildSwimmerRowsAddPatch(new List<Swimmer> { sw }, ClientLabel()), "swimmer");
                    AddLog(Loc.F("Str_Log_AddedSwimmerFmt", sw.Name, sw.BibNumber, sw.EventName));
                }
            } finally {
                ReleaseEditLock("swimmer-add");
            }
        }

        private void DeleteSwimmer_Click(object sender, RoutedEventArgs e) {
            // 先从 DataGrid 拿多选；如果为空再退回 SelectedItem（兼容单行场景）
            var toDelete = new List<Swimmer>();
            if (SwimmerGrid.SelectedItems != null) {
                foreach (var item in SwimmerGrid.SelectedItems) {
                    var sw = item as Swimmer;
                    if (sw != null && !toDelete.Contains(sw)) toDelete.Add(sw);
                }
            }
            if (toDelete.Count == 0) {
                var single = SwimmerGrid.SelectedItem as Swimmer;
                if (single != null) toDelete.Add(single);
            }
            if (toDelete.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectRowsToDeleteMulti"), Loc.T("Str_MsgTitle_Info"),
                    MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            string confirmMsg;
            if (toDelete.Count == 1) {
                var s = toDelete[0];
                confirmMsg = Loc.F("Str_Msg_ConfirmDeleteOneSwimmerFmt", s.Name, s.BibNumber, s.EventName);
            } else {
                var preview = string.Join("\n", toDelete.Take(8).Select(s => string.Format("· {0}({1}) {2}", s.Name, s.BibNumber, s.EventName)));
                if (toDelete.Count > 8) preview += Loc.F("Str_Msg_AndOthersFmt", toDelete.Count - 8);
                confirmMsg = Loc.F("Str_Msg_ConfirmDeleteMultiSwimmersFmt", toDelete.Count, preview);
            }
            if (AppMessageBox.Show(confirmMsg, Loc.T("Str_MsgTitle_ConfirmDelete"), MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) return;

            // 删除前批量申请锁；任何一条被人占用 → 整批取消
            var acquired = new List<string>();
            foreach (var sw in toDelete) {
                string k0 = "swimmer:" + (!string.IsNullOrEmpty(sw.IDNumber) ? sw.IDNumber : (sw.BibNumber ?? sw.Name ?? ""));
                string h0;
                if (!TryAcquireEditLock(k0, out h0)) {
                    foreach (var k in acquired) ReleaseEditLock(k);
                    AppMessageBox.Show(
                        Loc.F("Str_Msg_SwimmerBeingEditedFmt", sw.BibNumber, sw.Name, h0),
                        Loc.T("Str_MsgTitle_CannotDelete"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                acquired.Add(k0);
            }

            try {
                var keys = toDelete.Select(sw => new SwimmerDeleteKey {
                    BibNumber = sw.BibNumber, Name = sw.Name, EventName = sw.EventName
                }).ToList();

                bool serverAccepted = false;
                if (IsScheduleEditorMode && _editorSyncClient != null && _editorSyncClient.IsConnected) {
                    string perr;
                    if (!SendSwimmerDeletePatch(keys, out perr)) {
                        AppMessageBox.Show(Loc.F("Str_Msg_DeleteRejectedFmt", perr), Loc.T("Str_MsgTitle_DeleteNotDone"), MessageBoxButton.OK, MessageBoxImage.Warning);
                        AddLog(Loc.F("Str_Log_SwimmerDeleteRejectedFmt", perr));
                        return;
                    }
                    serverAccepted = true;
                }

                int removed; string applyError;
                if (!ApplySwimmerDeleteCore(keys, out removed, out applyError)) {
                    if (serverAccepted) {
                        AppMessageBox.Show(Loc.F("Str_Msg_DeleteServerAheadFmt", applyError),
                            Loc.T("Str_MsgTitle_ServerMismatch"), MessageBoxButton.OK, MessageBoxImage.Error);
                    } else {
                        AppMessageBox.Show(applyError, Loc.T("Str_MsgTitle_CannotDelete"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                    return;
                }
                if (!IsScheduleEditorMode) BroadcastSwimmerDeletePatch(keys, Environment.MachineName, null);

                int notFound = keys.Count - removed;
                RefreshOverviewStats();
                RefreshSwimmerFilter();
                FinishSwimmerEditPatchApply();
                AddLog(Loc.F("Str_Log_SwimmerDeletedFmt", removed, notFound > 0 ? Loc.F("Str_Log_NotFoundInListFmt", notFound) : ""));
                if (notFound > 0) {
                    AppMessageBox.Show(Loc.F("Str_Msg_DeletePartialNotFoundFmt", removed, notFound),
                        Loc.T("Str_MsgTitle_DeleteResult"), MessageBoxButton.OK, MessageBoxImage.Warning);
                }
            } finally {
                foreach (var k in acquired) ReleaseEditLock(k);
            }
        }

        private void SwimmerGrid_PreviewKeyDown(object sender, System.Windows.Input.KeyEventArgs e) {
            if (e.Key == System.Windows.Input.Key.Delete) {
                e.Handled = true;
                DeleteSwimmer_Click(sender, null);
            }
        }

        private void EditSwimmer_Click(object sender, RoutedEventArgs e) {
            var selected = SwimmerGrid.SelectedItem as Swimmer;
            if (selected == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectSwimmerToEdit")); return; }
            // 联机时申请编辑锁；锁键用身份证号优先，没有则参赛号兜底。
            // 同一运动员被人占用 → 弹窗提示，不打开编辑窗口
            string lockKey = "swimmer:" + (!string.IsNullOrEmpty(selected.IDNumber) ? selected.IDNumber
                                                                                    : (selected.BibNumber ?? selected.Name ?? ""));
            string holder;
            if (!TryAcquireEditLock(lockKey, out holder)) {
                AppMessageBox.Show(
                    Loc.F("Str_Msg_SwimmerBeingEditedByFmt", selected.BibNumber, selected.Name, holder),
                    Loc.T("Str_MsgTitle_CannotEdit"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                _pendingSwimmerEdit = null;
                if (!OpenSwimmerEditor(selected, isNew: false)) return;
                var f = _pendingSwimmerEdit;
                _pendingSwimmerEdit = null;
                if (f == null) return;   // 理论上走不到——isNew:false 时 OpenSwimmerEditor 确认必收集

                // 2026-09-19 【改走小补丁, 不再推整包】——原来这里改完直接 AutoSaveData()
                //   触发整包推送, 是用户点名要求整改的那条老路(不止接力队, 单人比赛信息
                //   编辑同样归在"编排记录信息编辑"这一类)。跟并组/接力队编辑同一个待遇:
                //   联着主服务器的编排端先问一句、等回执再改本机。
                bool serverAccepted = false;
                if (IsScheduleEditorMode && _editorSyncClient != null && _editorSyncClient.IsConnected) {
                    string perr;
                    if (!SendSwimmerEditPatch(f, out perr)) {
                        AppMessageBox.Show(Loc.F("Str_Msg_SwimmerEditRejectedFmt", perr),
                            Loc.T("Str_MsgTitle_SaveNotDone"), MessageBoxButton.OK, MessageBoxImage.Warning);
                        AddLog(Loc.F("Str_Log_SwimmerEditRejectedFmt", perr));
                        return;
                    }
                    serverAccepted = true;
                }

                string applyError;
                if (!ApplySwimmerEditCore(f, out applyError)) {
                    if (serverAccepted) {
                        AppMessageBox.Show(Loc.F("Str_Msg_SwimmerEditServerAheadFmt", applyError),
                            Loc.T("Str_MsgTitle_ServerMismatch"), MessageBoxButton.OK, MessageBoxImage.Error);
                        AddLog(Loc.F("Str_Log_SwimmerEditApplyFailedFmt", applyError));
                    } else {
                        AppMessageBox.Show(applyError, Loc.T("Str_MsgTitle_CannotSave"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                    return;
                }

                if (!IsScheduleEditorMode)
                    BroadcastSwimmerEditPatch(f, Environment.MachineName, null);

                RefreshSwimmerFilter();
                FinishSwimmerEditPatchApply();
                AddLog(Loc.F("Str_Log_SwimmerEditedFmt", f.Name, f.NewBib, f.EventName));
            } finally {
                ReleaseEditLock(lockKey);
            }
        }

        // 新增 / 修改运动员共用对话框。参数 target 是将被写入的 Swimmer 实例。
        // 返回 true 表示用户确认了修改。
        private bool OpenSwimmerEditor(Swimmer target, bool isNew) {
            var dlg = new Window {
                Title = isNew ? Loc.T("Str_Win_SwimmerEdit_TitleAdd") : Loc.F("Str_Win_SwimmerEdit_TitleEditFmt", target.Name, target.BibNumber),
                Width = 520, Height = 540,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this, ResizeMode = ResizeMode.NoResize
            };

            var sp = new StackPanel { Margin = new Thickness(20) };

            // 参赛号
            var bibRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 10) };
            bibRow.Children.Add(new TextBlock { Text = Loc.T("Str_Label_BibColon"), Width = 60, VerticalAlignment = VerticalAlignment.Center, FontWeight = FontWeights.Bold });
            var tbBib = new TextBox { Text = target.BibNumber ?? "", Width = 150, Padding = new Thickness(4), VerticalAlignment = VerticalAlignment.Center };
            bibRow.Children.Add(tbBib);
            bibRow.Children.Add(new TextBlock {
                Text = isNew ? "（可手动修改；默认已按代表队号码段取号）" : "（可手动修改；更改后将同步到该运动员的所有项目记录）",
                Margin = new Thickness(10, 0, 0, 0), VerticalAlignment = VerticalAlignment.Center,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), FontSize = 12 });
            sp.Children.Add(bibRow);

            var grid = new Grid();
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(80) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(80) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            for (int i = 0; i < 8; i++) grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(32) });

            // Row 0: 姓名 + 性别
            var tbName = AddEditField(grid, 0, 0, "姓名:", target.Name);
            var cbGender = new ComboBox { VerticalAlignment = VerticalAlignment.Center };
            cbGender.Items.Add("男"); cbGender.Items.Add("女"); cbGender.Items.Add("混合");
            cbGender.SelectedItem = target.Gender ?? "男";
            AddEditLabel(grid, 0, 2, "性别:");
            Grid.SetRow(cbGender, 0); Grid.SetColumn(cbGender, 3);
            grid.Children.Add(cbGender);

            // Row 1: 出生日期 + 年龄
            // 2026-05-21 出生日期改为 DatePicker（与 register.html 一致：可直接输入 yyyy-MM-dd，也可点日历选择）
            var dpBirth = AddEditDatePicker(grid, 1, 0, "出生日期:", target.BirthDate);
            var tbAge = AddEditField(grid, 1, 2, "年龄:", isNew && target.Age == 0 ? "" : target.Age.ToString());

            // Row 2: 身份证号 + 代表队
            var tbID = AddEditField(grid, 2, 0, "身份证号:", target.IDNumber);
            var tbCountry = AddEditField(grid, 2, 2, "代表队:", target.Country);

            // Row 3: 电话 + 协会注册号
            var tbPhone = AddEditField(grid, 3, 0, "联系电话:", target.Phone);
            var tbCSA = AddEditField(grid, 3, 2, "协会注册号:", target.CSANumber);


            // Row 4: 项目（下拉） + 报名成绩
            AddEditLabel(grid, 4, 0, "项目:");
            var cbEvent = new ComboBox { VerticalAlignment = VerticalAlignment.Center, IsEditable = true };
            foreach (var ev in _events) cbEvent.Items.Add(ev);
            if (!string.IsNullOrEmpty(target.EventName)) {
                if (!cbEvent.Items.Contains(target.EventName)) cbEvent.Items.Add(target.EventName);
                cbEvent.SelectedItem = target.EventName;
            } else if (cbEvent.Items.Count > 0) {
                cbEvent.SelectedIndex = 0;
            }
            Grid.SetRow(cbEvent, 4); Grid.SetColumn(cbEvent, 1);
            grid.Children.Add(cbEvent);
            var tbEntry = AddEditField(grid, 4, 2, "报名成绩:", target.EntryTime);

            // Row 5: 赛次（下拉，手动）+ 组别（下拉，选自组别）
            AddEditLabel(grid, 5, 0, "赛次:");
            var cbStage = new ComboBox { VerticalAlignment = VerticalAlignment.Center };
            cbStage.Items.Add("决赛"); cbStage.Items.Add("预赛"); cbStage.Items.Add("半决赛");
            cbStage.SelectedItem = string.IsNullOrEmpty(target.CurrentStage) ? "决赛" : target.CurrentStage;
            Grid.SetRow(cbStage, 5); Grid.SetColumn(cbStage, 1);
            grid.Children.Add(cbStage);
            AddEditLabel(grid, 5, 2, "组别:");
            var cbGroup = new ComboBox { VerticalAlignment = VerticalAlignment.Center, IsEditable = true };
            cbGroup.Items.Add("");   // 空 = 不分组
            foreach (var g in _ageGroups) cbGroup.Items.Add(g.Name);
            // 若运动员当前 AgeCategory 不在列表里（手动输入），加入
            if (!string.IsNullOrEmpty(target.AgeCategory) && !cbGroup.Items.Contains(target.AgeCategory))
                cbGroup.Items.Add(target.AgeCategory);
            cbGroup.SelectedItem = target.AgeCategory ?? "";
            Grid.SetRow(cbGroup, 5); Grid.SetColumn(cbGroup, 3);
            grid.Children.Add(cbGroup);

            // Row 6: 单位简称（左列整行跨到右）
            var tbCountryShort = AddEditField(grid, 6, 0, "单位简称:", target.CountryShort);

            // Row 7: 备注
            var tbNotes = AddEditField(grid, 7, 0, "备注:", target.Notes);

            sp.Children.Add(grid);

            // 按钮
            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(20, 6, 20, 6), Margin = new Thickness(0, 0, 8, 0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            var btnOk = new Button {
                Content = isNew ? "确认添加" : "确认修改",
                Padding = new Thickness(20, 6, 20, 6),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")),
                Foreground = Brushes.White, FontWeight = FontWeights.Bold, BorderThickness = new Thickness(0)
            };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            btnPanel.Children.Add(btnCancel);
            btnPanel.Children.Add(btnOk);
            sp.Children.Add(btnPanel);

            dlg.Content = sp;
            if (dlg.ShowDialog() != true) return false;

            // 参赛号校验(新增流程用的快速本机校验; 修改流程的权威校验挪到了
            // ApplySwimmerEditCore, 联机时要在【真正落子的那台机器】上查重才作数)
            string oldBib = target.BibNumber ?? "";
            string newBib = (tbBib.Text ?? "").Trim();
            if (string.IsNullOrEmpty(newBib)) { AppMessageBox.Show(Loc.T("Str_Msg_BibRequired")); return false; }
            if (isNew && _swimmers.Any(s => s.BibNumber == newBib)) {
                AppMessageBox.Show(Loc.F("Str_Msg_BibAlreadyExistsFmt", newBib));
                return false;
            }

            string bdErr;
            string bdVal = ReadBirthDateFromPicker(dpBirth, out bdErr);
            if (bdErr != null) { AppMessageBox.Show(bdErr); return false; }
            int ageVal = target.Age; int.TryParse((tbAge.Text ?? "").Trim(), out ageVal);
            string manualGroup = cbGroup.SelectedItem != null ? cbGroup.SelectedItem.ToString() : ((cbGroup.Text ?? "").Trim());
            string newAgeCategory = !string.IsNullOrEmpty(manualGroup) ? manualGroup : (target.AgeCategory ?? "");
            string newEventName = cbEvent.SelectedItem != null ? cbEvent.SelectedItem.ToString().Trim() : ((cbEvent.Text ?? "").Trim());
            string newEntryTime = (tbEntry.Text ?? "").Trim();

            // 2026-09-19 【用户明确要求: 编排记录的每一处编辑都要改走小补丁, 不许推整包】
            //   isNew=true(新增运动员)时 target 还是个游离对象, 没有"级联同名人其它项目"
            //   这回事, 直接写 target 让调用方自己 Add 进 _swimmers 即可, 沿用原逻辑。
            //   isNew=false(修改)才是这次真正要治的那条路——不直接碰 target/_swimmers,
            //   把收集到的新值交给 EditSwimmer_Click 走 SwimmerEdit 补丁(先问后改,
            //   核对/级联逻辑挪到 ApplySwimmerEditCore, 发起端/接收端共用同一份, 跟
            //   接力队编辑那次改法一模一样)。
            if (isNew) {
                target.Name = (tbName.Text ?? "").Trim();
                target.Gender = cbGender.SelectedItem != null ? cbGender.SelectedItem.ToString() : "男";
                target.BirthDate = bdVal;
                target.Age = ageVal;
                target.IDNumber = (tbID.Text ?? "").Trim();
                target.Country = (tbCountry.Text ?? "").Trim();
                target.CountryShort = (tbCountryShort.Text ?? "").Trim();
                target.Phone = (tbPhone.Text ?? "").Trim();
                target.CSANumber = (tbCSA.Text ?? "").Trim();
                target.EventName = newEventName;
                target.EntryTime = newEntryTime;
                target.EntryTimeSeconds = TimeFormatter.Parse(newEntryTime);
                target.CurrentStage = cbStage.SelectedItem != null ? cbStage.SelectedItem.ToString() : "决赛";
                target.AgeCategory = newAgeCategory;
                target.Notes = (tbNotes.Text ?? "").Trim();
                target.BibNumber = newBib;
                return true;
            }

            _pendingSwimmerEdit = new PendingSwimmerEdit {
                OldBib = oldBib, OldEventName = target.EventName ?? "",
                NewBib = newBib,
                Name = (tbName.Text ?? "").Trim(),
                Gender = cbGender.SelectedItem != null ? cbGender.SelectedItem.ToString() : "男",
                BirthDate = bdVal, Age = ageVal,
                IDNumber = (tbID.Text ?? "").Trim(), Country = (tbCountry.Text ?? "").Trim(),
                CountryShort = (tbCountryShort.Text ?? "").Trim(), Phone = (tbPhone.Text ?? "").Trim(),
                CSANumber = (tbCSA.Text ?? "").Trim(),
                EventName = newEventName, EntryTime = newEntryTime,
                EntryTimeSeconds = TimeFormatter.Parse(newEntryTime),
                CurrentStage = cbStage.SelectedItem != null ? cbStage.SelectedItem.ToString() : "决赛",
                AgeCategory = newAgeCategory, Notes = (tbNotes.Text ?? "").Trim()
            };
            return true;
        }

        // 2026-09-19 OpenSwimmerEditor(isNew:false) 收集到的新值——跟 target 分开放,
        //   不直接写进 _swimmers, 等 EditSwimmer_Click 走完补丁流程再落地。
        //   用字段而不是 out 参数, 是因为 OpenSwimmerEditor 这个大函数中途有好几个
        //   "校验不过直接 return false" 的分支, out 参数在 C# 里每个 return 都得赋值,
        //   反而让校验分支的代码噪音变大。
        private class PendingSwimmerEdit {
            public string OldBib, OldEventName, NewBib;
            public string Name, Gender, BirthDate, IDNumber, Country, CountryShort, Phone, CSANumber;
            public string EventName, EntryTime, CurrentStage, AgeCategory, Notes;
            public int Age; public double EntryTimeSeconds;
        }
        private PendingSwimmerEdit _pendingSwimmerEdit;

        private TextBox AddEditField(Grid grid, int row, int col, string label, string value) {
            AddEditLabel(grid, row, col, label);
            var tb = new TextBox { Text = value ?? "", Padding = new Thickness(4), VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(tb, row); Grid.SetColumn(tb, col + 1);
            grid.Children.Add(tb);
            return tb;
        }

        private void AddEditLabel(Grid grid, int row, int col, string text) {
            var lbl = new TextBlock { Text = text, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lbl, row); Grid.SetColumn(lbl, col);
            grid.Children.Add(lbl);
        }

        // 2026-05-21 与 register.html 的 <input type="date"> 行为对齐：
        //   - 既能直接输入"yyyy-MM-dd"（en-CA 短日期），也能点日历图标选择
        //   - 初值若是已存储的 "yyyy-MM-dd" 字符串，自动转成 SelectedDate
        //   - 初值若解析不出来（旧数据格式异常），原样放进 Text 供用户修正
        private DatePicker AddEditDatePicker(Grid grid, int row, int col, string label, string value) {
            AddEditLabel(grid, row, col, label);
            var dp = new DatePicker {
                VerticalAlignment = VerticalAlignment.Center,
                SelectedDateFormat = DatePickerFormat.Short
            };
            dp.SetValue(System.Windows.FrameworkElement.LanguageProperty,
                        System.Windows.Markup.XmlLanguage.GetLanguage("en-CA"));
            dp.ToolTip = Loc.T("Str_Tooltip_DateFormatHint");
            if (!string.IsNullOrEmpty(value)) {
                DateTime d;
                if (DateTime.TryParseExact(value.Trim(), "yyyy-MM-dd",
                        System.Globalization.CultureInfo.InvariantCulture,
                        System.Globalization.DateTimeStyles.None, out d))
                    dp.SelectedDate = d;
                else
                    dp.Text = value;
            }
            Grid.SetRow(dp, row); Grid.SetColumn(dp, col + 1);
            grid.Children.Add(dp);
            return dp;
        }

        // 从 DatePicker 读取出生日期，返回标准化的 "yyyy-MM-dd" 或 ""；
        // 若用户输入了无法解析的文本，返回 null 并把错误信息写入 error。
        internal static string ReadBirthDateFromPicker(DatePicker dp, out string error) {
            error = null;
            if (dp == null) return "";
            if (dp.SelectedDate.HasValue)
                return dp.SelectedDate.Value.ToString("yyyy-MM-dd");
            string text = (dp.Text ?? "").Trim();
            if (string.IsNullOrEmpty(text)) return "";
            DateTime d;
            // 优先严格 yyyy-MM-dd（与 HTML <input type="date"> 一致）
            if (DateTime.TryParseExact(text, "yyyy-MM-dd",
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out d))
                return d.ToString("yyyy-MM-dd");
            // 兜底：en-CA 短日期（DatePicker 失焦解析路径），仍输出 yyyy-MM-dd
            if (DateTime.TryParse(text, System.Globalization.CultureInfo.GetCultureInfo("en-CA"),
                    System.Globalization.DateTimeStyles.None, out d))
                return d.ToString("yyyy-MM-dd");
            error = "出生日期格式不正确，请填 yyyy-MM-dd（4 位年份），或点日历选择：" + text;
            return null;
        }

