        // 把 _units 的名称灌进报名界面的"代表队"下拉
        private void RefreshUnitComboBox() {
            if (RegCountryBox == null) return;
            string prev = RegCountryBox.Text;
            RegCountryBox.Items.Clear();
            var distinctNames = new HashSet<string>();
            foreach (var u in _units) if (u != null && !string.IsNullOrEmpty(u.Name)) distinctNames.Add(u.Name);
            foreach (var s in _swimmers) if (!string.IsNullOrEmpty(s.Country)) distinctNames.Add(s.Country);
            foreach (var n in distinctNames.OrderBy(x => x)) RegCountryBox.Items.Add(n);
            RegCountryBox.Text = prev ?? "";
        }

        // 选中已知单位时自动带出"简称"字段
        private void RegCountryBox_SelectionChanged(object sender, SelectionChangedEventArgs e) {
            string name = RegCountryBox.SelectedItem as string;
            if (string.IsNullOrEmpty(name)) return;
            var u = _units.FirstOrDefault(x => x != null && x.Name == name);
            if (u != null && !string.IsNullOrEmpty(u.ShortName) && RegCountryShortBox != null
                && string.IsNullOrEmpty(RegCountryShortBox.Text.Trim())) {
                RegCountryShortBox.Text = u.ShortName;
            }
        }

        private void BibRangeConfigCore() {
            // 汇总候选代表队列表：已有 BibRanges 中的 + 已注册运动员中出现的
            var countries = new List<string>();
            foreach (var r in _bibRanges) if (!countries.Contains(r.Country) && !string.IsNullOrEmpty(r.Country)) countries.Add(r.Country);
            foreach (var s in _swimmers) if (!string.IsNullOrEmpty(s.Country) && !countries.Contains(s.Country)) countries.Add(s.Country);

            // 编辑副本，取消时不保存
            var working = new System.Collections.ObjectModel.ObservableCollection<BibRange>();
            foreach (var c in countries) {
                var existing = _bibRanges.FirstOrDefault(r => r.Country == c);
                if (existing != null) working.Add(new BibRange { Country = existing.Country, Start = existing.Start, End = existing.End, Width = existing.Width > 0 ? existing.Width : 3 });
                else working.Add(new BibRange { Country = c, Start = 0, End = 0, Width = 3 });
            }

            var dlg = new Window {
                Title = Loc.T("Str_Win_BibRangeByTeam_Title"),
                Width = 600, Height = 460,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.CanResize
            };
            var mainGrid = new Grid { Margin = new Thickness(16) };
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            mainGrid.Children.Add(new TextBlock {
                Text = Loc.T("Str_BibRange_Desc"),
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 8), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155"))
            });

            var grid = new DataGrid {
                AutoGenerateColumns = false, CanUserAddRows = false, IsReadOnly = false,
                SelectionMode = DataGridSelectionMode.Single,
                AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC"))
            };
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Team"), Binding = new System.Windows.Data.Binding("Country") { Mode = System.Windows.Data.BindingMode.TwoWay, UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged }, Width = new DataGridLength(180) });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_StartNo"), Binding = new System.Windows.Data.Binding("Start") { Mode = System.Windows.Data.BindingMode.TwoWay }, Width = new DataGridLength(80) });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_EndNo"), Binding = new System.Windows.Data.Binding("End") { Mode = System.Windows.Data.BindingMode.TwoWay }, Width = new DataGridLength(80) });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_PadWidth"), Binding = new System.Windows.Data.Binding("Width") { Mode = System.Windows.Data.BindingMode.TwoWay }, Width = new DataGridLength(80) });
            // 动态计算使用状态
            var usageCol = new DataGridTextColumn { Header = Loc.T("Str_Col_UsedRange"), Width = new DataGridLength(120), IsReadOnly = true };
            usageCol.Binding = new System.Windows.Data.Binding(".") { Converter = new BibRangeUsageConverter(_swimmers) };
            grid.Columns.Add(usageCol);
            grid.ItemsSource = working;
            Grid.SetRow(grid, 1);
            mainGrid.Children.Add(grid);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) };
            Grid.SetRow(btnPanel, 2);
            var btnAdd = new Button { Content = Loc.T("Str_Btn_AddRow"), Padding = new Thickness(12, 6, 12, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnAdd.Click += delegate { working.Add(new BibRange { Country = "", Start = 0, End = 0, Width = 3 }); };
            var btnDel = new Button { Content = Loc.T("Str_Btn_DeleteSelected"), Padding = new Thickness(12, 6, 12, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnDel.Click += delegate {
                var sel = grid.SelectedItem as BibRange;
                if (sel != null) working.Remove(sel);
            };
            var btnOk = new Button { Content = Loc.T("Str_Btn_Save"), Padding = new Thickness(16, 6, 16, 6), Margin = new Thickness(0, 0, 8, 0), FontWeight = FontWeights.Bold,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate {
                // 提交正在编辑的单元格
                var fe = System.Windows.Input.Keyboard.FocusedElement as FrameworkElement;
                if (fe is TextBox) {
                    var be = fe.GetBindingExpression(TextBox.TextProperty);
                    if (be != null) be.UpdateSource();
                }
                try { grid.CommitEdit(DataGridEditingUnit.Cell, true); grid.CommitEdit(DataGridEditingUnit.Row, true); } catch { }

                // 校验 & 检测区间冲突
                var finalList = new List<BibRange>();
                var seenCountries = new HashSet<string>();
                foreach (var r in working) {
                    if (string.IsNullOrWhiteSpace(r.Country)) continue;
                    r.Country = r.Country.Trim();
                    if (r.Width <= 0) r.Width = 3;
                    if (seenCountries.Contains(r.Country)) {
                        AppMessageBox.Show(Loc.F("Str_Msg_TeamDuplicateFmt", r.Country), Loc.T("Str_MsgTitle_Info")); return;
                    }
                    seenCountries.Add(r.Country);
                    if (r.Start != 0 || r.End != 0) {
                        if (r.Start <= 0 || r.End < r.Start) {
                            AppMessageBox.Show(Loc.F("Str_Msg_TeamRangeInvalidFmt", r.Country), Loc.T("Str_MsgTitle_Info")); return;
                        }
                    }
                    finalList.Add(r);
                }
                // 检查区间重叠
                for (int i = 0; i < finalList.Count; i++) {
                    for (int j = i + 1; j < finalList.Count; j++) {
                        var a = finalList[i]; var b = finalList[j];
                        if (a.Start <= 0 || b.Start <= 0) continue;
                        if (a.End >= b.Start && b.End >= a.Start) {
                            AppMessageBox.Show(Loc.F("Str_Msg_TeamRangeOverlapFmt", a.Country, a.Start, a.End, b.Country, b.Start, b.End), Loc.T("Str_MsgTitle_Info")); return;
                        }
                    }
                }
                _bibRanges = finalList;
                FinishAndSyncPatch(BuildListSetPatch("bibRanges", JArray.FromObject(_bibRanges), ClientLabel()), "meet");
                AddLog(Loc.F("Str_Log_BibRangesUpdatedFmt", _bibRanges.Count));
                dlg.DialogResult = true;
            };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnAdd);
            btnPanel.Children.Add(btnDel);
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            mainGrid.Children.Add(btnPanel);

            dlg.Content = mainGrid;
            dlg.ShowDialog();
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-09-22 参赛单位及号码分配 —— 现场需求, 参考第三方软件(SOFTMAY)界面设计。
        //   内嵌 tab（不是弹窗），在 _bibRanges 基础上扩展 AgeGroup + 男/女子号码段,
        //   与旧的 BibRangeConfigCore()(单键 Country, 无组别/无性别拆分)共用同一份数据,
        //   AgeGroup="" 的行对旧逻辑完全透明。
        //   2026-09-28 第十一阶段 Step2 接入 Loc —— 这个 tab 是代码生成(不是 XAML 静态绑定),
        //   靠 LanguageToggle_Click 里挂的 BuildUnitBibAllocTab() 整体重建来跟随语言切换,
        //   不是 live DynamicResource。
        // ══════════════════════════════════════════════════════════════
        private bool _bibAllocAutoMode = false;   // false=手工分配(自定义), true=自动分配(平均分布)
        private ObservableCollection<BibRange> _bibAllocWorking;
        private DataGrid _bibAllocGrid;
        private TextBox _baCountryBox, _baMaleStart, _baMaleEnd, _baFemaleStart, _baFemaleEnd, _baStart, _baEnd, _baWidth;
        private ComboBox _baAgeGroupCombo;
        private TextBlock _baLockHint;
        private RadioButton _baAutoRadio, _baManualRadio;

        private void BuildUnitBibAllocTab() {
            if (UnitBibAllocRoot == null) return;
            UnitBibAllocRoot.Children.Clear();
            UnitBibAllocRoot.ColumnDefinitions.Clear();
            UnitBibAllocRoot.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(320) });
            UnitBibAllocRoot.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            _bibAllocWorking = new ObservableCollection<BibRange>(_bibRanges);

            // ── 左侧: 单位/组别 列表 ──
            var leftPanel = new DockPanel { Margin = new Thickness(0, 0, 10, 0) };
            var leftTitle = new TextBlock { Text = Loc.T("Str_UnitBibAlloc_LeftTitle"), FontSize = 15, FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B")), Margin = new Thickness(0, 0, 0, 8) };
            DockPanel.SetDock(leftTitle, Dock.Top);
            leftPanel.Children.Add(leftTitle);

            _bibAllocGrid = new DataGrid {
                AutoGenerateColumns = false, CanUserAddRows = false, IsReadOnly = true,
                SelectionMode = DataGridSelectionMode.Single,
                HeadersVisibility = DataGridHeadersVisibility.All, RowHeaderWidth = 34,
                AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                ItemsSource = _bibAllocWorking
            };
            _bibAllocGrid.LoadingRow += delegate (object s, DataGridRowEventArgs e) { e.Row.Header = (e.Row.GetIndex() + 1).ToString(); };
