            sb.Append("</table>");
            GenerateAndOpenDocument(Loc.T("Str_UnitBibAlloc_ReportTitle"), sb.ToString());
        }

        private void BibAllocSaveAll_Click(object sender, RoutedEventArgs e) {
            var seen = new HashSet<string>();
            var finalList = new List<BibRange>();
            foreach (var r in _bibAllocWorking) {
                if (string.IsNullOrWhiteSpace(r.Country)) continue;
                r.Country = r.Country.Trim();
                if (r.Width <= 0) r.Width = 3;
                string key = r.Country + "|" + (r.AgeGroup ?? "");
                if (seen.Contains(key)) { AppMessageBox.Show(Loc.F("Str_UnitBibAlloc_MsgDupUnitFmt", r.Country, string.IsNullOrEmpty(r.AgeGroup) ? Loc.T("Str_UnitBibAlloc_Unlimited") : r.AgeGroup), Loc.T("Str_MsgTitle_Info")); return; }
                seen.Add(key);
                finalList.Add(r);
            }
            // 区间重叠检查(合并范围 + 男女子范围一起比较, 不比较自己)
            Func<BibRange, List<Tuple<int, int>>> spans = delegate (BibRange r) {
                var list = new List<Tuple<int, int>>();
                if (r.MaleStart > 0 && r.MaleEnd >= r.MaleStart) list.Add(Tuple.Create(r.MaleStart, r.MaleEnd));
                if (r.FemaleStart > 0 && r.FemaleEnd >= r.FemaleStart) list.Add(Tuple.Create(r.FemaleStart, r.FemaleEnd));
                if (list.Count == 0 && r.Start > 0 && r.End >= r.Start) list.Add(Tuple.Create(r.Start, r.End));
                return list;
            };
            for (int i = 0; i < finalList.Count; i++) {
                var spansA = spans(finalList[i]);
                for (int j = i + 1; j < finalList.Count; j++) {
                    var spansB = spans(finalList[j]);
                    foreach (var a in spansA) foreach (var b in spansB) {
                        if (a.Item2 >= b.Item1 && b.Item2 >= a.Item1) {
                            AppMessageBox.Show(Loc.F("Str_UnitBibAlloc_MsgOverlapFmt",
                                finalList[i].Country, a.Item1, a.Item2, finalList[j].Country, b.Item1, b.Item2), Loc.T("Str_MsgTitle_Info"));
                            return;
                        }
                    }
                }
            }
            _bibRanges = finalList;
            FinishAndSyncPatch(BuildListSetPatch("bibRanges", JArray.FromObject(_bibRanges), ClientLabel()), "meet");
            AddLog(Loc.F("Str_UnitBibAlloc_SaveLogFmt", _bibRanges.Count));
            AppMessageBox.Show(Loc.T("Str_UnitBibAlloc_SaveSuccessMsg"), Loc.T("Str_EM_Tab_UnitBibAlloc"));
        }

        // 把完整的 BibRange 行渲染成 "x/区间大小" 已用统计
        private class BibRangeUsageConverter : System.Windows.Data.IValueConverter
        {
            private readonly System.Collections.ObjectModel.ObservableCollection<Swimmer> _list;
            public BibRangeUsageConverter(System.Collections.ObjectModel.ObservableCollection<Swimmer> list) { _list = list; }
            public object Convert(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture) {
                var r = value as BibRange; if (r == null) return "";
                if (r.Start <= 0 || r.End < r.Start) return "未配置";
                int total = r.End - r.Start + 1;
                int used = 0;
                foreach (var s in _list) {
                    int n;
                    if (s != null && s.Country == r.Country && !string.IsNullOrEmpty(s.BibNumber) && int.TryParse(s.BibNumber, out n)) {
                        if (n >= r.Start && n <= r.End) used++;
                    }
                }
                return string.Format("{0}/{1}", used, total);
            }
            public object ConvertBack(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture) { throw new NotImplementedException(); }
        }

        // ─── 运动员报名 CSV 表头（导出/导入/模板共用） ───────────────────
        // 与 ImportCSV_Click 兼容：前 11 列保持原顺序，组别/单位简称作为附加列追加在后
        // 顺序: 号码,姓名,性别,代表队,项目,报名成绩,年龄,出生日期,身份证号,电话,备注,组别,单位简称
        // 2026-09-30 现场反馈: English模式导出的CSV/模板表头还是中文——原来是 static readonly
        //   字段(类型第一次用到时就定死, 不跟 CurrentLanguage 走), 改成"按语言现取"。
        //   中文列名与 Loc.Table 里的中文原文逐一对得上, 老用户已导出的中文CSV原样可再导入。
        private static readonly string[] SwimmerCsvHeaderKeys = new[] {
            "Str_Col_Bib","Str_Col_Name","Str_DocC_ColGender","Str_Col_Team","Str_Col_Event","Str_Col_Entry",
            "Str_Col_Age","Str_Col_BirthDate","Str_Col_IDNum","Str_Col_Phone","Str_Col_Notes","Str_Col_Group","Str_Col_Abbr"
        };
        private static string[] SwimmerCsvHeaders { get { return SwimmerCsvHeaderKeys.Select(Loc.T).ToArray(); } }

        private void ExportSwimmersCSV_Click(object sender, RoutedEventArgs e) {
            // 导出当前所有已报名运动员（含接力代表条目和接力队员个人条目）
            var rows = _swimmers.ToList();
            if (rows.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRegDataToExport"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            string defaultName = string.IsNullOrEmpty(_competitionName)
                ? Loc.T("Str_FileName_SwimmerRoster") + ".csv"
                : (_competitionName + "_" + Loc.T("Str_FileName_SwimmerRoster") + ".csv");
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_Csv"),
                Title = Loc.T("Str_Win_ExportSwimmers_Title"),
                FileName = defaultName
            };
            if (dlg.ShowDialog() != true) return;
            try {
                var sb = new StringBuilder();
                // 2026-05-21 已移除显式 sb.Append('﻿'); — Encoding.UTF8 在 File.WriteAllText 时
                // 自带写入 3 字节 BOM 前导，再加这一行就是双 BOM，会让首字段挂一个 ﻿ 不可见字符
                sb.AppendLine(string.Join(",", SwimmerCsvHeaders));
                foreach (var s in rows) {
                    sb.AppendLine(string.Join(",", new[] {
                        CsvEscape(s.BibNumber ?? ""),
                        CsvEscape(s.Name ?? ""),
                        CsvEscape(s.Gender ?? ""),
                        CsvEscape(s.Country ?? ""),
                        CsvEscape(s.EventName ?? ""),
                        CsvEscape(s.EntryTime ?? ""),
                        CsvEscape(s.Age > 0 ? s.Age.ToString() : ""),
                        CsvEscape(s.BirthDate ?? ""),
                        CsvEscape(s.IDNumber ?? ""),
                        CsvEscape(s.Phone ?? ""),
                        CsvEscape(s.Notes ?? ""),
                        CsvEscape(s.AgeCategory ?? ""),
                        CsvEscape(s.CountryShort ?? "")
                    }));
                }
                File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
                AddLog(Loc.F("Str_Log_SwimmerDataExportedFmt", rows.Count));
                AppMessageBox.Show(Loc.F("Str_Msg_ExportedSwimmersFmt", rows.Count, dlg.FileName), Loc.T("Str_MsgTitle_Done"));
            } catch (Exception ex) {
                AppMessageBox.Show(Loc.F("Str_Msg_ExportFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"));
            }
        }

        // 2026-05-24 个人报名 CSV 模板表头 — 严格匹配 (27 列 = 11 基础 + 8 × 2 项目成绩对)
        // 2026-09-30 现场反馈: English模式下模板/导入还是中文表头——SwimmerCsvTemplateHeader()
        //   改成按当前语言现取; 另加 Zh/En 两个固定语言版本, 导入校验时两个都认(谁导出的都能导回)。
        private static readonly string[] SwimmerCsvBaseHeaderKeys = new[] {
            "Str_Col_Bib","Str_Col_Name","Str_DocC_ColGender","Str_Col_Team","Str_Col_Age","Str_Col_BirthDate",
            "Str_Col_IDNum","Str_Col_Phone","Str_Col_Notes","Str_Col_Group","Str_Col_Abbr"
        };
        private const int SwimmerCsvEventSlots = 8;
        private static string[] BuildSwimmerCsvTemplateHeader(Func<string, string> tr) {
            var list = new List<string>(SwimmerCsvBaseHeaderKeys.Select(tr));
            string evLabel = tr("Str_Col_Event"), resLabel = tr("Str_Col_RecordTime");
            for (int n = 1; n <= SwimmerCsvEventSlots; n++) { list.Add(evLabel + n); list.Add(resLabel + n); }
            return list.ToArray();
        }
        private static string[] SwimmerCsvTemplateHeader { get { return BuildSwimmerCsvTemplateHeader(Loc.T); } }
        private static string[] SwimmerCsvTemplateHeaderZh { get { return BuildSwimmerCsvTemplateHeader(Loc.TChinese); } }
        private static string[] SwimmerCsvTemplateHeaderEn { get { return BuildSwimmerCsvTemplateHeader(Loc.TEnglish); } }

        private void DownloadSwimmersTemplateCSV_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_Csv"),
                Title = Loc.T("Str_Win_SaveSwimmersTemplate_Title"),
                FileName = Loc.T("Str_FileName_SwimmerTemplate") + ".csv"
            };
            if (dlg.ShowDialog() != true) return;
            try {
                // 2026-05-21 升级为"多项目"模板：一名运动员一行，最多 8 个个人项目并列填。
                // 2026-05-24 「导入CSV」严格按本模板表头校验，不匹配的整文件拒绝；逐行校验失败的跳过并汇总。
                int eventSlots = SwimmerCsvEventSlots;
                var headers = new List<string>(SwimmerCsvTemplateHeader);
                var sb = new StringBuilder();
                sb.AppendLine(string.Join(",", headers));

                // 示例 1：张三 报 3 个个人项目
                var ex1 = new List<string> {
                    "001","张三","男","北京队","18","2007-05-12","110101200705120011","13800000001","","青年","京"
                };
                ex1.Add("100米自由泳"); ex1.Add("52.30");
                ex1.Add("200米自由泳"); ex1.Add("1:55.00");
                ex1.Add("100米仰泳");   ex1.Add("1:00.50");
                for (int n = 4; n <= eventSlots; n++) { ex1.Add(""); ex1.Add(""); }
                sb.AppendLine(string.Join(",", ex1.ConvertAll<string>(CsvEscape)));

                // 示例 2：李四 报 1 个个人项目
                var ex2 = new List<string> {
                    "002","李四","女","上海队","22","2003-08-21","310101200308210022","13800000002","","成年","沪"
                };
                ex2.Add("50米蛙泳"); ex2.Add("34.85");
                for (int n = 2; n <= eventSlots; n++) { ex2.Add(""); ex2.Add(""); }
                sb.AppendLine(string.Join(",", ex2.ConvertAll<string>(CsvEscape)));

                File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
                AppMessageBox.Show(Loc.T("Str_Msg_SwimmerTemplateSaved"), Loc.T("Str_MsgTitle_Done"));
            } catch (Exception ex) {
                AppMessageBox.Show(Loc.F("Str_Msg_SaveFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"));
            }
        }

        private void ImportCSV_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.OpenFileDialog {
                Filter = Loc.T("Str_Filter_CsvAll"),
                Title = Loc.T("Str_Win_ImportSwimmersCsv_Title")
            };
            if (dlg.ShowDialog() != true) return;
            try {
                // 2026-05-24 严格按「导出个人报名模板」表头校验。
                //   表头列数/列名/列序与模板任意不符 → 整文件拒绝并提示偏差列
                //   逐行校验：姓名必填 / 性别男女混合 / 出生日期 yyyy-MM-dd / 项目非接力 / 至少 1 个项目
                //   失败行跳过+理由汇总；接力项目仍走「接力队管理」Tab
                var rows = ReadCsvLines(dlg.FileName);
                if (rows.Count < 2) {
                    AppMessageBox.Show(Loc.T("Str_Msg_CsvNoDataRows"), Loc.T("Str_MsgTitle_ImportFailed"),
                        MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }

                string[] header = rows[0];
                // ── 严格表头校验 ── 2026-09-30 中英文模板都认——文件是哪个语言导出的都能导回，
                //   不看导入时的当前 UI 语言。两个参照表按位置逐列比，命中任一个就算通过。
                string[] refZh = SwimmerCsvTemplateHeaderZh, refEn = SwimmerCsvTemplateHeaderEn;
                if (header.Length != refZh.Length) {
                    AppMessageBox.Show(Loc.F("Str_Msg_CsvHeaderColCountFmt",
                        refZh.Length, header.Length), Loc.T("Str_MsgTitle_FormatError"),
                        MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }
                bool matchesZh = true, matchesEn = true;
                for (int hi = 0; hi < refZh.Length; hi++) {
                    string actual = (header[hi] ?? "").Trim();
                    if (actual != refZh[hi]) matchesZh = false;
                    if (actual != refEn[hi]) matchesEn = false;
                }
                if (!matchesZh && !matchesEn) {
                    // 先找"两个参照表都对不上"的那一列；找不到说明是中英文混着填的怪文件
                    // (每列单看都合法, 但前后语言不一致)——兜底按中文参照表报第一处不一致列,
                    // 保证这里一定会弹窗, 不会啥提示都没有就悄悄退出。
                    int badHi = -1;
                    for (int hi = 0; hi < refZh.Length; hi++) {
                        string actual = (header[hi] ?? "").Trim();
                        if (actual != refZh[hi] && actual != refEn[hi]) { badHi = hi; break; }
                    }
                    if (badHi < 0) { for (int hi = 0; hi < refZh.Length; hi++) { if ((header[hi] ?? "").Trim() != refZh[hi]) { badHi = hi; break; } } }
                    string actualBad = (header[badHi] ?? "").Trim();
                    AppMessageBox.Show(Loc.F("Str_Msg_CsvHeaderColMismatchFmt", badHi + 1, SwimmerCsvTemplateHeader[badHi], actualBad),
                        Loc.T("Str_MsgTitle_FormatError"),
                        MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }

                // 表头通过 → 按列名建索引（统一按中文原名建，不管这份文件是哪个语言导出的，
                //   下面 colIdx["姓名"] 这类查表全部继续沿用中文 key，不用动）
                var colIdx = new Dictionary<string, int>();
                for (int hi = 0; hi < refZh.Length; hi++) colIdx[refZh[hi]] = hi;
                var pairs = new List<int[]>();
                for (int n = 1; n <= SwimmerCsvEventSlots; n++) {
                    pairs.Add(new int[] { colIdx["项目" + n], colIdx["成绩" + n] });
                }

                int imported = 0, updated = 0, skipped = 0;
                var skipReasons = new List<string>();
                var touchedRows = new List<Swimmer>();

                for (int i = 1; i < rows.Count; i++) {
                    string[] cols = rows[i];
                    // 空行跳过（不计入 skipped）
                    bool blank = true;
                    for (int k = 0; k < cols.Length; k++) if (!string.IsNullOrWhiteSpace(cols[k])) { blank = false; break; }
                    if (blank) continue;

                    string name = ReadCsvCol(cols, colIdx, "姓名");
                    string gender = ReadCsvCol(cols, colIdx, "性别");
                    string birthDate = ReadCsvCol(cols, colIdx, "出生日期");
                    string idNumber = ReadCsvCol(cols, colIdx, "身份证号");
                    string country = ReadCsvCol(cols, colIdx, "代表队");
                    string countryShort = ReadCsvCol(cols, colIdx, "单位简称");
                    int age = ParseIntOr0(ReadCsvCol(cols, colIdx, "年龄"));
                    string phone = ReadCsvCol(cols, colIdx, "电话");
                    string notes = ReadCsvCol(cols, colIdx, "备注");
                    string ageCategory = ReadCsvCol(cols, colIdx, "组别");
                    string bibFromRow = ReadCsvCol(cols, colIdx, "号码");

                    // 行级必填校验
                    var rowErr = new List<string>();
                    if (string.IsNullOrEmpty(name)) rowErr.Add("姓名");
                    if (gender != "男" && gender != "女" && gender != "混合") rowErr.Add("性别须为 男/女/混合");
                    if (!string.IsNullOrEmpty(birthDate) && !System.Text.RegularExpressions.Regex.IsMatch(birthDate, @"^\d{4}-\d{2}-\d{2}$"))
                        rowErr.Add("出生日期应为 yyyy-MM-dd");
                    if (!string.IsNullOrEmpty(idNumber) && idNumber.Length != 15 && idNumber.Length != 18)
                        rowErr.Add("身份证号长度应为 15 或 18");

                    // 收集本行的有效项目对（并过滤接力）
                    var validPairs = new List<string[]>();   // {eventName, entryTime}
                    foreach (var pair in pairs) {
                        string evName = (pair[0] < cols.Length) ? (cols[pair[0]] ?? "").Trim() : "";
                        if (string.IsNullOrEmpty(evName)) continue;
                        if (evName.Contains("接力")) {
                            rowErr.Add(string.Format("项目「{0}」属于接力，请改在「接力队管理」报名", evName));
                            continue;
                        }
                        string et = (pair[1] < cols.Length) ? (cols[pair[1]] ?? "").Trim() : "";
                        validPairs.Add(new[] { evName, et });
                    }
                    if (rowErr.Count == 0 && validPairs.Count == 0) rowErr.Add("至少需填写 1 个项目");

                    if (rowErr.Count > 0) {
                        skipped++;
                        skipReasons.Add(string.Format("第 {0} 行 [{1}]: {2}",
                            i + 1, string.IsNullOrEmpty(name) ? "(无姓名)" : name, string.Join("; ", rowErr)));
                        continue;
                    }

                    // 通过 → 写入(每项目一条 Upsert)
                    foreach (var p in validPairs) {
                        Swimmer touched;
                        ImportOneSwimmerEvent(bibFromRow, name, gender, country, countryShort,
                            p[0], p[1], age, birthDate, idNumber, phone, notes, ageCategory,
                            i + 1, ref imported, ref updated, ref skipped, skipReasons, out touched);
                        if (touched != null) touchedRows.Add(touched);
                    }
                }

                AddLog(Loc.F("Str_Log_CsvImportDoneFmt",
                    imported, updated, skipped));
                RefreshOverviewStats();
                RefreshSwimmerFilter();
                FinishAndSyncPatch(BuildSwimmerRowsUpsertPatch(touchedRows, null, ClientLabel()), "swimmer");

                // 汇总弹窗 — 全量列出便于管理员定位
                var sb = new StringBuilder();
                sb.AppendFormat(Loc.T("Str_Msg_CsvImportSummaryFmt"), imported, updated, skipped);
                if (skipReasons.Count > 0) {
                    sb.AppendLine(Loc.T("Str_Msg_SkipDetailsHeader"));
                    int show = Math.Min(skipReasons.Count, 100);
                    for (int k = 0; k < show; k++) sb.AppendLine("• " + skipReasons[k]);
                    if (skipReasons.Count > show) sb.AppendFormat(Loc.T("Str_Msg_MoreNotShownFmt"), skipReasons.Count - show);
                }
                AppMessageBox.Show(sb.ToString(), Loc.T("Str_MsgTitle_ImportSwimmerCsvDone"),
                    MessageBoxButton.OK, skipped > 0 ? MessageBoxImage.Warning : MessageBoxImage.Information);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_CsvImportFailedFmt", ex.Message));
                AppMessageBox.Show(Loc.F("Str_Msg_CsvImportFailedFmt", ex.Message), Loc.T("Str_MsgTitle_ImportFailed"),
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        // 辅助：按表头名取列；列不存在或行不够长 → 返回 ""
        private static string ReadCsvCol(string[] cols, Dictionary<string, int> colIdx, string headerName) {
            int idx;
            if (!colIdx.TryGetValue(headerName, out idx)) return "";
            return (idx >= 0 && idx < cols.Length) ? cols[idx].Trim() : "";
        }

        // 辅助：null / 非数字 → 0
        private static int ParseIntOr0(string s) {
            int n;
            return int.TryParse(s, out n) ? n : 0;
        }

        // 辅助：导入一名运动员的一个项目（共用 Upsert 逻辑给新老两种 CSV 格式）
        // 同一人多项目时，第 2 个起会从已生成的 Swimmer 复用 bib（按身份证号匹配），
        // 避免一人多号。
        private void ImportOneSwimmerEvent(
            string bibNum, string name, string gender, string country, string countryShort,
            string eventName, string entryTime, int age, string birthDate, string idNumber,
            string phone, string notes, string ageCategory,
            int rowIdx, ref int imported, ref int updated, ref int skipped, List<string> skipReasons,
            out Swimmer touched) {
            touched = null;
            double entrySec = TimeFormatter.Parse(entryTime);

            // ★ Upsert：身份证号 + 项目 双匹配 → 覆盖现有记录
            if (!string.IsNullOrEmpty(idNumber)) {
                var existing = _swimmers.FirstOrDefault(s =>
                    !string.IsNullOrEmpty(s.IDNumber)
                    && s.IDNumber == idNumber
                    && s.EventName == eventName);
                if (existing != null) {
                    existing.Name             = name;
                    existing.Gender           = gender;
                    existing.Country          = country;
                    existing.CountryShort     = countryShort;
                    existing.EntryTime        = entryTime;
                    existing.EntryTimeSeconds = entrySec;
                    if (age > 0)                            existing.Age = age;
                    existing.BirthDate        = birthDate;
                    existing.Phone            = phone;
                    existing.Notes            = notes;
                    if (!string.IsNullOrEmpty(ageCategory)) existing.AgeCategory = ageCategory;
                    if (!string.IsNullOrEmpty(bibNum))      existing.BibNumber   = bibNum;
                    updated++;
                    touched = existing;
                    return;
                }
            }

            // ID 不匹配 → 走 FindDuplicate 检查号码牌/同名无 ID 冲突
            var dupOther = FindDuplicate(name, gender, eventName, bibNum, idNumber, country);
            if (dupOther != null) {
                skipped++;
                string reason = !string.IsNullOrEmpty(dupOther.BibNumber)
                    ? Loc.F("Str_Msg_CsvDupBibConflictFmt", rowIdx, name, eventName, dupOther.BibNumber)
                    : Loc.F("Str_Msg_CsvDupConflictFmt", rowIdx, name, eventName);
                if (skipReasons.Count < 20) skipReasons.Add(reason);
                return;
            }

            // 全新条目：同一人多项目时复用已生成的 bib
            string actualBib = bibNum;
            if (string.IsNullOrEmpty(actualBib) && !string.IsNullOrEmpty(idNumber)) {
                var any = _swimmers.FirstOrDefault(s =>
                    !string.IsNullOrEmpty(s.IDNumber) && s.IDNumber == idNumber);
                if (any != null) actualBib = any.BibNumber;
            }
            if (string.IsNullOrEmpty(actualBib)) actualBib = GenerateNextBibNumber(country);

            var sw = new Swimmer {
                BibNumber    = actualBib,
                Name         = name,
                Gender       = gender,
                Country      = country,
                CountryShort = countryShort,
                EventName    = eventName,
                EntryTime    = entryTime,
                EntryTimeSeconds = entrySec,
                Age          = age,
                BirthDate    = birthDate,
                IDNumber     = idNumber,
                Phone        = phone,
                Notes        = notes,
            };
            if (!string.IsNullOrEmpty(ageCategory)) sw.AgeCategory = ageCategory;
            _swimmers.Add(sw);
            imported++;
            touched = sw;
        }

        private void AddRelay_Click(object sender, RoutedEventArgs e) {
            // 新增接力队：占"新增"位锁，避免两端同时新增同名队
            string addHolder;
            if (!TryAcquireEditLock("relay-add", out addHolder)) {
                AppMessageBox.Show(Loc.F("Str_Msg_RelayAddingBusyFmt", addHolder),
                    Loc.T("Str_MsgTitle_CannotAdd"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                AddRelayCore();
            } finally {
                ReleaseEditLock("relay-add");
            }
        }

        private void AddRelayCore() {
            // 弹出对话框，让用户填写队名/项目/性别/报名成绩/各棒队员，
            // 确认后完整创建 RelayTeam + _swimmers 代表条目 + 队员子条目
            var relayEvents = _events.Where(ev => ev.Contains("接力")).ToList();
            if (relayEvents.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRelayEventsAvailable"), Loc.T("Str_MsgTitle_Info")); return;
            }

            var dlg = new Window {
                Title = Loc.T("Str_Win_AddRelay_Title"), Width = 480, Height = 540,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.CanResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_RelayForm_Header"), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 8) });

            // 项目
            var rowEvent = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
            rowEvent.Children.Add(new TextBlock { Text = Loc.T("Str_EM_RegEventLabel"), Width = 80, VerticalAlignment = VerticalAlignment.Center });
            var cbEvent = new ComboBox { Width = 320 };
            foreach (var ev in relayEvents) cbEvent.Items.Add(ev);
            cbEvent.SelectedIndex = 0;
            rowEvent.Children.Add(cbEvent);
            sp.Children.Add(rowEvent);

            // 性别
            var rowGender = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
            rowGender.Children.Add(new TextBlock { Text = Loc.T("Str_Common_Gender"), Width = 80, VerticalAlignment = VerticalAlignment.Center });
            var cbGender = new ComboBox { Width = 320 };
            cbGender.Items.Add("男"); cbGender.Items.Add("女"); cbGender.Items.Add("混合");
            cbGender.SelectedIndex = 0;
            rowGender.Children.Add(cbGender);
            sp.Children.Add(rowGender);

            // 2026-05-25 组别 (来自主程序 _ageGroups, 用户报名时必选)
            var rowAge = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
            rowAge.Children.Add(new TextBlock { Text = Loc.T("Str_Common_AgeGroup"), Width = 80, VerticalAlignment = VerticalAlignment.Center });
            var cbAge = new ComboBox { Width = 320 };
            cbAge.Items.Add("");   // 允许不指定 (向后兼容旧数据)
            foreach (var g in _ageGroups) cbAge.Items.Add(g.Name);
            cbAge.SelectedIndex = _ageGroups.Count > 0 ? 1 : 0;
            rowAge.Children.Add(cbAge);
            sp.Children.Add(rowAge);

            // 队名
            var rowTeam = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
            rowTeam.Children.Add(new TextBlock { Text = Loc.T("Str_Label_TeamNameColon"), Width = 80, VerticalAlignment = VerticalAlignment.Center });
            var tbTeam = new TextBox { Width = 320, Padding = new Thickness(4) };
            rowTeam.Children.Add(tbTeam);
            sp.Children.Add(rowTeam);

            // 报名成绩
            var rowEntry = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
            rowEntry.Children.Add(new TextBlock { Text = Loc.T("Str_Label_EntryTimeColon"), Width = 80, VerticalAlignment = VerticalAlignment.Center });
            var tbEntryTime = new TextBox { Width = 320, Padding = new Thickness(4), ToolTip = Loc.T("Str_Tooltip_EntryTimeOptionalHint") };
            rowEntry.Children.Add(tbEntryTime);
            sp.Children.Add(rowEntry);

            // 棒次行容器（根据项目名自动调整棒数）
            var legsTitle = new TextBlock { Margin = new Thickness(0, 10, 0, 4), FontSize = 13, FontWeight = FontWeights.Bold };
            sp.Children.Add(legsTitle);
            var legsPanel = new StackPanel();
            sp.Children.Add(legsPanel);

            var legNameBoxes = new List<TextBox>();
            var legBibBoxes = new List<TextBox>();
            var legBirthPickers = new List<DatePicker>();

            Action rebuildLegs = delegate {
                legsPanel.Children.Clear();
                legNameBoxes.Clear();
                legBibBoxes.Clear();
                legBirthPickers.Clear();
                string evName = cbEvent.SelectedItem != null ? cbEvent.SelectedItem.ToString() : "";
                int legCount = 4;
                var mm = System.Text.RegularExpressions.Regex.Match(evName, @"(\d+)\s*[x×*]");
                if (mm.Success) { int n; if (int.TryParse(mm.Groups[1].Value, out n) && n > 0 && n <= 10) legCount = n; }
                legsTitle.Text = string.Format("队员（共{0}棒，可留空，后续再补）:", legCount);
                for (int i = 0; i < legCount; i++) {
                    var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 0) };
                    row.Children.Add(new TextBlock { Text = string.Format("第{0}棒:", i + 1), Width = 55, VerticalAlignment = VerticalAlignment.Center });
                    var tbLegName = new TextBox { Width = 130, Padding = new Thickness(4) };
                    var dpLegBirth = new DatePicker { Width = 130, Margin = new Thickness(8, 0, 0, 0) };
                    dpLegBirth.SetValue(System.Windows.FrameworkElement.LanguageProperty, System.Windows.Markup.XmlLanguage.GetLanguage("en-CA"));
                    dpLegBirth.SelectedDateFormat = DatePickerFormat.Short;
                    // 2026-05-21 与 register.html / 其它 EXE 一致：可输入 yyyy-MM-dd 也可点日历
                    dpLegBirth.ToolTip = Loc.T("Str_Tooltip_DateFormatHint");
                    var tbLegBib = new TextBox { Width = 90, Padding = new Thickness(4), Margin = new Thickness(8, 0, 0, 0), ToolTip = Loc.T("Str_Tooltip_BibOptionalHint") };
                    row.Children.Add(new TextBlock { Text = Loc.T("Str_Col_Name"), Margin = new Thickness(0, 0, 4, 0), VerticalAlignment = VerticalAlignment.Center });
                    row.Children.Add(tbLegName);
                    row.Children.Add(new TextBlock { Text = Loc.T("Str_Col_BirthDate"), Margin = new Thickness(8, 0, 4, 0), VerticalAlignment = VerticalAlignment.Center });
                    row.Children.Add(dpLegBirth);
                    row.Children.Add(new TextBlock { Text = Loc.T("Str_Col_Bib"), Margin = new Thickness(8, 0, 4, 0), VerticalAlignment = VerticalAlignment.Center });
                    row.Children.Add(tbLegBib);
                    legsPanel.Children.Add(row);
                    legNameBoxes.Add(tbLegName);
                    legBibBoxes.Add(tbLegBib);
                    legBirthPickers.Add(dpLegBirth);
                }
            };
            cbEvent.SelectionChanged += delegate { rebuildLegs(); };
            rebuildLegs();

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 14, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmAdd"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            sp.Children.Add(btnPanel);

            dlg.Content = new ScrollViewer { Content = sp, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };

            if (dlg.ShowDialog() != true) return;

            string eventName = cbEvent.SelectedItem != null ? cbEvent.SelectedItem.ToString() : "";
            string gender = cbGender.SelectedItem != null ? cbGender.SelectedItem.ToString() : "男";
            string ageGroup = cbAge.SelectedItem != null ? cbAge.SelectedItem.ToString() : "";
            string teamName = (tbTeam.Text ?? "").Trim();
            string entryTimeStr = (tbEntryTime.Text ?? "").Trim();

            if (string.IsNullOrEmpty(eventName)) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayEvent")); return; }
            if (string.IsNullOrEmpty(teamName)) { AppMessageBox.Show(Loc.T("Str_Msg_TeamNameRequired")); return; }
            if (_relayTeams.Any(t => t.EventName == eventName && t.TeamName == teamName
                                    && t.Gender == gender && (t.AgeGroup ?? "") == ageGroup)) {
                AppMessageBox.Show(Loc.F("Str_Msg_RelayTeamAlreadyRegisteredFmt", teamName, ageGroup, gender, eventName)); return;
            }

            double entrySec = 0;
            if (!string.IsNullOrEmpty(entryTimeStr)) entrySec = TimeFormatter.Parse(entryTimeStr);

            var team = new RelayTeam {
                TeamName = teamName, EventName = eventName, Gender = gender, AgeGroup = ageGroup,
                EntryTime = entryTimeStr, EntryTimeSeconds = entrySec
            };
            // 2026-05-21 棒次出生日期同样支持手动输入 yyyy-MM-dd（与 HTML 一致）；
            // 第 N 棒输入无法识别 → 报错而不是静默丢弃后再写入空字符串。
            for (int i = 0; i < legNameBoxes.Count; i++) {
                string ln = (legNameBoxes[i].Text ?? "").Trim();
                string lb = (legBibBoxes[i].Text ?? "").Trim();
                string lbdErr;
                string lbd = ReadBirthDateFromPicker(legBirthPickers[i], out lbdErr);
                if (lbdErr != null) {
                    AppMessageBox.Show(Loc.F("Str_Msg_RelayLegErrorFmt", i + 1, lbdErr), Loc.T("Str_MsgTitle_RelayRegistration"),
                        MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                team.Legs.Add(new RelayLeg {
                    LegOrder = i + 1,
                    SwimmerName = ln,
                    SwimmerBibNumber = lb,
                    SwimmerIDNumber = "",
                    SwimmerBirthDate = lbd
                });
            }
            _relayTeams.Add(team);

            // 代表队条目（用于分组/成绩流程）
            string legNames = "";
            foreach (var leg in team.Legs) legNames += (legNames.Length > 0 ? "," : "") + (leg.SwimmerName ?? "");
            string teamBib = "R" + (_relayTeams.Count).ToString("D3");
            while (_swimmers.Any(s => s.BibNumber == teamBib)) teamBib = "R" + DateTime.Now.Ticks.ToString().Substring(10);

            // 2026-05-25 代表条目带上 AgeCategory, 否则秩序册向导按组别×性别×项目筛 _swimmers 时接力项目漏出
            var addedRows = new List<Swimmer>();
            var proxyRow = new Swimmer {
                BibNumber = teamBib, Name = teamName, Gender = gender, Country = teamName,
                EventName = eventName, AgeCategory = ageGroup,
                EntryTime = entryTimeStr, EntryTimeSeconds = entrySec,
                Notes = string.Format("接力队 棒次:{0}", legNames)
            };
            _swimmers.Add(proxyRow);
            addedRows.Add(proxyRow);

            // 队员子条目
            foreach (var leg in team.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName)) continue;
                string memBib = !string.IsNullOrEmpty(leg.SwimmerBibNumber) ? leg.SwimmerBibNumber : (teamBib + "-" + leg.LegOrder);
                if (_swimmers.Any(s => s.BibNumber == memBib)) continue;
                var memberRow = new Swimmer {
                    BibNumber = memBib, Name = leg.SwimmerName,
                    Gender = gender == "混合" ? "男" : gender, Country = teamName,
                    IDNumber = leg.SwimmerIDNumber ?? "",
                    BirthDate = leg.SwimmerBirthDate ?? "",
                    EventName = eventName,
                    Notes = string.Format("接力队员 {0} 第{1}棒", eventName, leg.LegOrder)
                };
                _swimmers.Add(memberRow);
                addedRows.Add(memberRow);
            }

            // 2026-09-20 接力队本质是几条 Swimmer 行(代表+队员), 新增的这几行用补丁带过去,
            //   不为一支接力队推一次整包。
            FinishAndSyncPatch(BuildSwimmerRowsAddPatch(addedRows, new List<RelayTeam> { team }, ClientLabel()), "swimmer");
            RebuildRelayGroupedView();
            AddLog(Loc.F("Str_Log_ManualAddRelayTeamFmt", teamName, Loc.GenderDisplay(gender), eventName, team.Legs.Count));
        }

        // 2026-05-24 接力队 CSV 模板表头 — 导出/导入必须严格匹配
        // 2026-05-25 增加「组别」列, 总列数 17→18
        // 2026-09-30 现场反馈: English模式导出还是中文表头——改成按当前语言现取, 同时保留
        //   固定中/英两版供导入校验(谁导出的都能导回, 不看导入时当前UI语言)。
        private static string[] BuildRelayCsvHeader(Func<string, string> tr, bool spaceSep) {
            var list = new List<string> {
                tr("Str_EM_Relay_ColTeamName"), tr("Str_Col_Group"), tr("Str_Col_Event"), tr("Str_DocC_ColGender"), tr("Str_Col_Entry")
            };
            string sep = spaceSep ? " " : "";
            for (int n = 1; n <= 4; n++) {
                string leg = tr("Str_RegTool_Leg" + n);
                list.Add(leg + sep + tr("Str_Col_Name"));
                list.Add(leg + sep + tr("Str_Col_IDCard"));
                list.Add(leg + sep + tr("Str_Col_Birthday"));
            }
            list.Add(tr("Str_Col_Notes"));
            return list.ToArray();
        }
        private static string[] RelayCsvHeader { get { return BuildRelayCsvHeader(Loc.T, Loc.CurrentLanguage == Loc.En); } }
        private static string[] RelayCsvHeaderZh { get { return BuildRelayCsvHeader(Loc.TChinese, false); } }
        private static string[] RelayCsvHeaderEn { get { return BuildRelayCsvHeader(Loc.TEnglish, true); } }

        private void ExportRelayTemplate_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_Csv"), Title = Loc.T("Str_Win_ExportRelayTemplate_Title"),
                FileName = Loc.T("Str_FileName_RelayTemplate") + "_" + DateTime.Now.ToString("yyyyMMdd_HHmm") + ".csv"
            };
            if (dlg.ShowDialog() != true) return;
            var sb = new StringBuilder();
            sb.AppendLine(string.Join(",", RelayCsvHeader));
            // 1 行示例（用户编辑前可参考）
            sb.AppendLine("绵阳蓝鲸A队,少年组,4x100米自由泳接力,男,3:42.50," +
                          "张三,510102200505010001,2005-05-01," +
                          "李四,510102200505010002,2005-05-02," +
                          "王五,510102200505010003,2005-05-03," +
                          "赵六,510102200505010004,2005-05-04,示例（删除本行后填真数据）");
            File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
            AppMessageBox.Show(Loc.F("Str_Msg_ExportedRelayTemplateFmt", dlg.FileName),
                Loc.T("Str_MsgTitle_Done"));
        }

        private void ExportRelayCSV_Click(object sender, RoutedEventArgs e) {
            if (_relayTeams.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRelayTeamsToExport"), Loc.T("Str_MsgTitle_Info")); return;
            }
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_Csv"), Title = Loc.T("Str_Win_ExportRelayTeams_Title"),
                FileName = Loc.T("Str_DocC_ColRelayCount") + "_" + DateTime.Now.ToString("yyyyMMdd_HHmm") + ".csv"
            };
            if (dlg.ShowDialog() != true) return;
            var sb = new StringBuilder();
            sb.AppendLine(string.Join(",", RelayCsvHeader));
            foreach (var t in _relayTeams) {
                var legs = new RelayLeg[4];
                for (int i = 0; i < t.Legs.Count && i < 4; i++) legs[i] = t.Legs[i];
                sb.AppendLine(string.Join(",", new[] {
                    CsvEsc(t.TeamName), CsvEsc(t.AgeGroup ?? ""), CsvEsc(t.EventName), CsvEsc(t.Gender), CsvEsc(t.EntryTime),
                    CsvEsc(legs[0] != null ? legs[0].SwimmerName : ""), CsvEsc(legs[0] != null ? legs[0].SwimmerIDNumber : ""), CsvEsc(legs[0] != null ? legs[0].SwimmerBirthDate : ""),
                    CsvEsc(legs[1] != null ? legs[1].SwimmerName : ""), CsvEsc(legs[1] != null ? legs[1].SwimmerIDNumber : ""), CsvEsc(legs[1] != null ? legs[1].SwimmerBirthDate : ""),
                    CsvEsc(legs[2] != null ? legs[2].SwimmerName : ""), CsvEsc(legs[2] != null ? legs[2].SwimmerIDNumber : ""), CsvEsc(legs[2] != null ? legs[2].SwimmerBirthDate : ""),
                    CsvEsc(legs[3] != null ? legs[3].SwimmerName : ""), CsvEsc(legs[3] != null ? legs[3].SwimmerIDNumber : ""), CsvEsc(legs[3] != null ? legs[3].SwimmerBirthDate : ""),
                    CsvEsc(t.AgeCategoryPending ? Loc.T("Str_EM_Relay_AgeGroupPending") : "")
                }));
            }
            File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
            AppMessageBox.Show(Loc.F("Str_Msg_ExportedRelayTeamsFmt", _relayTeams.Count, dlg.FileName), Loc.T("Str_MsgTitle_Done"));
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-08-21 接力棒次填报表 —— 导出/读入
        //
        // 由来: 接力名单赛前一小时才发下来, 31 支队 124 个名字手工敲既来不及也容易串行。
        // 用法: 赛前「导出棒次填报表」→ 队名/组次/泳道都已填好, 只有 4 棒是空的 →
        //       拿到名单照着填 → 「读入棒次名单」一键灌进去。
        // 与已有「导入CSV」的区别: 那个只**新建**接力队(key 已存在就跳过),
        //   本届 31 支队都已在档案里, 用它一支也进不去; 这个只给已有队伍**填姓名**,
        //   不新建、不删除、不改队名/项目/泳道。
        private static readonly string[] RelayLegSheetHeader = new[] {
            "场次", "项次", "组次", "泳道", "项目", "性别", "组别", "代表队",
            "第1棒", "第2棒", "第3棒", "第4棒"
        };

        // CSV 用 Excel 另存时在中文 Windows 上默认是 GBK, 不是 UTF-8。
        // 有 BOM 按 BOM 走; 没 BOM 先严格试 UTF-8, 不合法再退回本机默认(GBK)。
        private static string[] ReadCsvLinesSmart(string path) {
            var bytes = File.ReadAllBytes(path);
            if (bytes.Length >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF)
                return new UTF8Encoding(false).GetString(bytes, 3, bytes.Length - 3)
                       .Split(new[] { "\r\n", "\n", "\r" }, StringSplitOptions.None);
            try {
                var strict = new UTF8Encoding(false, true);
                return strict.GetString(bytes).Split(new[] { "\r\n", "\n", "\r" }, StringSplitOptions.None);
            } catch {
                return Encoding.Default.GetString(bytes).Split(new[] { "\r\n", "\n", "\r" }, StringSplitOptions.None);
            }
        }

        private static string CsvCell(string s) {
            s = s ?? "";
            if (s.IndexOf(',') >= 0 || s.IndexOf('"') >= 0 || s.IndexOf('\n') >= 0)
                return "\"" + s.Replace("\"", "\"\"") + "\"";
            return s;
        }

        private void ExportRelayLegSheet_Click(object sender, RoutedEventArgs e) {
            if (_relayTeams == null || _relayTeams.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRelayTeamsYet"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_ExcelXlsx"),
                FileName = Loc.T("Str_FileName_RelayLegSheet") + ".xlsx",
                Title = Loc.T("Str_Win_ExportRelayLegSheet_Title")
            };
            if (dlg.ShowDialog() != true) return;

            // 按 场次 → 项次 → 泳道 排, 和秩序册顺序一致, 现场好对
            // 2026-09-30 现场反馈"没有第0场，但导出第0场"——找不到匹配日程(项目+性别+组别)
            //   的接力队，原来会用 ses=0 兜底，冒充出一个根本不存在的"第0场"文件。
            //   改成直接跳过这些队，汇总数量另外提示，不再塞进假场次。
            var rows = new List<string[]>();
            int unscheduledRelayCount = 0;
            foreach (var t in _relayTeams) {
                var sc = _schedule.FirstOrDefault(s => s.EventName == t.EventName
                    && s.Gender == t.Gender && (s.AgeGroup ?? "") == (t.AgeGroup ?? ""));
                if (sc == null) { unscheduledRelayCount++; continue; }
                int ses = sc.SessionNumber;
                int evn = sc.EvNum;
                var legs = new string[4];
                for (int i = 0; i < 4; i++) legs[i] = (t.Legs != null && i < t.Legs.Count) ? (t.Legs[i].SwimmerName ?? "") : "";
                rows.Add(new[] {
                    ses.ToString(), evn.ToString(), t.Heat.ToString(), t.Lane.ToString(),
                    t.EventName ?? "", t.Gender ?? "", t.AgeGroup ?? "", t.TeamName ?? "",
                    legs[0], legs[1], legs[2], legs[3]
                });
            }
            if (rows.Count == 0) {
                AppMessageBox.Show(Loc.F("Str_Msg_RelayAllUnscheduledFmt", unscheduledRelayCount),
                    Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            rows.Sort(delegate(string[] a, string[] b) {
                int r = int.Parse(a[0]).CompareTo(int.Parse(b[0])); if (r != 0) return r;
                r = int.Parse(a[1]).CompareTo(int.Parse(b[1]));     if (r != 0) return r;
                r = int.Parse(a[2]).CompareTo(int.Parse(b[2]));     if (r != 0) return r;
                return int.Parse(a[3]).CompareTo(int.Parse(b[3]));
            });

            // 2026-08-21 一场一个 Excel 文件。接力名单是按场次陆续发下来的
            //   (如 22 日上午只拿到第1场的), 一张 31 行的大表反而容易填错行。
            //   文件名 <你起的名>_第N场.xlsx, 文件内按项目分块, 现场只打开当场那个填。
            string dir = System.IO.Path.GetDirectoryName(dlg.FileName);
            string baseName = System.IO.Path.GetFileNameWithoutExtension(dlg.FileName);
            var sessions = new List<int>();
            foreach (var r in rows) { int s = int.Parse(r[0]); if (!sessions.Contains(s)) sessions.Add(s); }
            sessions.Sort();

            var written = new List<string>();
            try {
                foreach (int ses in sessions) {
                    var legRows = new List<RelayLegSheetService.LegRow>();
                    foreach (var r in rows) {
                        if (int.Parse(r[0]) != ses) continue;
                        var lr = new RelayLegSheetService.LegRow {
                            Session = int.Parse(r[0]), EvNum = int.Parse(r[1]),
                            Heat = int.Parse(r[2]), Lane = int.Parse(r[3]),
                            EventName = r[4], Gender = r[5], AgeGroup = r[6], TeamName = r[7]
                        };
                        for (int i = 0; i < 4; i++) lr.Legs[i] = r[8 + i];
                        legRows.Add(lr);
                    }
                    if (legRows.Count == 0) continue;
                    var sc = _schedule.FirstOrDefault(s => s.SessionNumber == ses);
                    string fn = System.IO.Path.Combine(dir, baseName + "_" + Loc.F("Str_DocC_SessionNoFmt", ses) + ".xlsx");
                    RelayLegSheetService.ExportSession(fn, _competitionName, ses,
                        sc != null ? sc.SessionName : "", sc != null ? sc.Date : "", sc != null ? sc.Time : "",
                        legRows);
                    written.Add(Loc.F("Str_Msg_RelaySessionSummaryLineFmt", Loc.F("Str_DocC_SessionNoFmt", ses), legRows.Count, System.IO.Path.GetFileName(fn)));
                }
                string summary = Loc.F("Str_Msg_ExportedLegSheetsFmt", written.Count, dir, string.Join("\n", written.ToArray()));
                if (unscheduledRelayCount > 0) summary += "\n\n" + Loc.F("Str_Msg_RelayUnscheduledTeamsFmt", unscheduledRelayCount);
                AppMessageBox.Show(summary,
                    Loc.T("Str_MsgTitle_ExportSuccess"), MessageBoxButton.OK, MessageBoxImage.Information);
                AddLog(Loc.F("Str_Log_ExportedRelayLegSheetFmt", rows.Count, written.Count, dir));
            } catch (Exception ex) {
                AppMessageBox.Show(Loc.F("Str_Msg_WriteFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"), MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        // 2026-08-21 读入棒次名单前先选场次。
        //   接力名单是分场次陆续发下来的, 比第1场时手边可能同时躺着三个文件,
        //   选错了虽然不会写坏数据(对不上的行会被跳过), 但会让人以为"读进去了"。
        //   先选场次 → 只认该场次的行 → 其它场次的行明确报出来, 一眼看出是不是拿错文件。
        // 返回选中的场次号; 取消返回 -1。
        private int AskRelaySession() {
            var sessions = new List<int>();
            foreach (var t in _relayTeams) {
                var sc = _schedule.FirstOrDefault(s => s.EventName == t.EventName
                    && s.Gender == t.Gender && (s.AgeGroup ?? "") == (t.AgeGroup ?? ""));
                // 2026-09-30 没排上日程的队没有真实场次号，不再用 0 冒充一个可选的"第0场"
                if (sc == null) continue;
                int ses = sc.SessionNumber;
                if (!sessions.Contains(ses)) sessions.Add(ses);
            }
            sessions.Sort();
            if (sessions.Count == 0) return -1;
            if (sessions.Count == 1) return sessions[0];   // 只有一个场次就不用问了

            var win = new Window {
                Title = Loc.T("Str_Win_ImportRelayLegs_PickSession_Title"),
                Width = 470, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.NoResize, Owner = this
            };
            var root = new StackPanel { Margin = new Thickness(18) };
            root.Children.Add(new TextBlock {
                Text = Loc.T("Str_ImportRelay_WhichSession"), FontSize = 15, FontWeight = FontWeights.Bold,
                Margin = new Thickness(0, 0, 0, 4)
            });
            root.Children.Add(new TextBlock {
                Text = Loc.T("Str_ImportRelay_SessionOnlyHint"),
                FontSize = 12, Foreground = System.Windows.Media.Brushes.Gray,
                Margin = new Thickness(0, 0, 0, 12), TextWrapping = TextWrapping.Wrap
            });

            var radios = new List<RadioButton>();
            foreach (int ses in sessions) {
                var sc = _schedule.FirstOrDefault(s => s.SessionNumber == ses);
                int total = 0, filled = 0;
                foreach (var t in _relayTeams) {
                    var s2 = _schedule.FirstOrDefault(s => s.EventName == t.EventName
                        && s.Gender == t.Gender && (s.AgeGroup ?? "") == (t.AgeGroup ?? ""));
                    if ((s2 != null ? s2.SessionNumber : 0) != ses) continue;
                    total++;
                    bool has = false;
                    if (t.Legs != null) foreach (var lg in t.Legs) if (!string.IsNullOrEmpty(lg.SwimmerName)) { has = true; break; }
                    if (has) filled++;
                }
                var rb = new RadioButton {
                    Content = string.Format("第{0}场    {1} {2}    共 {3} 支队    已填 {4}/{3}",
                        ses, sc != null ? sc.Date : "", sc != null ? sc.Time : "", total, filled),
                    Tag = ses, FontSize = 14, Margin = new Thickness(0, 5, 0, 5), Padding = new Thickness(4, 0, 0, 0)
                };
                radios.Add(rb);
                root.Children.Add(rb);
            }
            radios[0].IsChecked = true;

            var btns = new StackPanel {
                Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 16, 0, 0)
            };
            int picked = -1;
            var ok = new Button { Content = Loc.T("Str_Btn_NextChooseFile"), Width = 120, Height = 30, Margin = new Thickness(0, 0, 8, 0), IsDefault = true };
            var cancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Width = 80, Height = 30, IsCancel = true };
            ok.Click += delegate {
                foreach (var rb in radios) if (rb.IsChecked == true) { picked = (int)rb.Tag; break; }
                win.DialogResult = true;
            };
            btns.Children.Add(ok); btns.Children.Add(cancel);
            root.Children.Add(btns);
            win.Content = root;
            if (win.ShowDialog() != true) return -1;
            return picked;
        }

        private void ImportRelayLegSheet_Click(object sender, RoutedEventArgs e) {
            if (_relayTeams == null || _relayTeams.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRelayTeamsYet"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            int wantSession = AskRelaySession();
            if (wantSession < 0) return;

            var dlg = new Microsoft.Win32.OpenFileDialog {
                Filter = Loc.T("Str_Filter_ExcelXlsxXlsAll"),
                Title = Loc.F("Str_Win_ImportRelayLegListFmt", wantSession)
            };
            if (dlg.ShowDialog() != true) return;

            List<RelayLegSheetService.LegRow> sheetRows;
            string warn;
            try { sheetRows = RelayLegSheetService.Import(dlg.FileName, out warn); }
            catch (Exception ex) { AppMessageBox.Show(Loc.F("Str_Msg_ReadFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"), MessageBoxButton.OK, MessageBoxImage.Error); return; }
            if (!string.IsNullOrEmpty(warn)) {
                AppMessageBox.Show(warn + Loc.T("Str_Msg_ReexportLegSheetSuffix"), Loc.T("Str_MsgTitle_FormatError"),
                    MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            if (sheetRows.Count == 0) { AppMessageBox.Show(Loc.T("Str_Msg_NoDataRowsInSheet"), Loc.T("Str_MsgTitle_Info")); return; }

            int updated = 0, blank = 0, otherSession = 0;
            var otherSet = new List<int>();
            var perSession = new Dictionary<int, int>();   // 2026-08-21 按场次分别汇报, 现场一眼看出读的是哪一场
            var notFound = new List<string>();
            var changeLog = new List<string>();
            var touchedTeams = new List<RelayTeam>();
            var touchedRows = new List<Swimmer>();

            foreach (var d in sheetRows) {
                // 2026-08-21 只读选中的那一场; 别场的行原样不动, 但要计数报出来
                if (d.Session != wantSession) {
                    otherSession++;
                    if (!otherSet.Contains(d.Session)) otherSet.Add(d.Session);
                    continue;
                }
                string evName = d.EventName ?? "";
                string gender = d.Gender ?? "";
                string ageGrp = d.AgeGroup ?? "";
                string team   = d.TeamName ?? "";

                var names = new string[4];
                bool any = false;
                for (int i = 0; i < 4; i++) {
                    names[i] = d.Legs[i] ?? "";
                    if (!string.IsNullOrEmpty(names[i])) any = true;
                }
                if (!any) { blank++; continue; }      // 这一行还没填, 跳过

                var t = _relayTeams.FirstOrDefault(x => (x.TeamName ?? "") == team
                    && (x.EventName ?? "") == evName
                    && (x.Gender ?? "") == gender
                    && (x.AgeGroup ?? "") == ageGrp);
                if (t == null) {
                    notFound.Add(string.Format("第 {0} 行: {1} {2} {3} {4}", d.ExcelRow, team, gender, ageGrp, evName));
                    continue;
                }

                var oldNames = new List<string>();
                for (int i = 0; i < 4; i++) oldNames.Add((t.Legs != null && i < t.Legs.Count) ? (t.Legs[i].SwimmerName ?? "") : "");

                // 和「编辑队伍信息」保存时写法一致
                while (t.Legs.Count < 4) t.Legs.Add(new RelayLeg { LegOrder = t.Legs.Count + 1 });
                for (int i = 0; i < 4; i++) { t.Legs[i].LegOrder = i + 1; t.Legs[i].SwimmerName = names[i]; }

                List<Swimmer> syncTouched;
                SyncRelayLegsToSwimmers(t, oldNames, out syncTouched);
                touchedTeams.Add(t);
                touchedRows.AddRange(syncTouched);
                updated++;
                int sesNo = d.Session;
                if (!perSession.ContainsKey(sesNo)) perSession[sesNo] = 0;
                perSession[sesNo]++;
                changeLog.Add(string.Format("第{0}场 {1} {2} {3}: {4}", sesNo, t.TeamName, t.Gender, t.EventName, string.Join(",", names)));
            }

            if (updated > 0) {
                RebuildRelayGroupedView();
                FinishAndSyncPatch(BuildSwimmerRowsUpsertPatch(touchedRows, touchedTeams, null, ClientLabel()), "swimmer");
            }

            // 选的场次在文件里一行都没有 —— 多半是文件拿错了
            if (updated == 0 && blank == 0 && otherSession > 0) {
                otherSet.Sort();
                var names = new List<string>();
                foreach (int s in otherSet) names.Add("第" + s + "场");
                AppMessageBox.Show(Loc.F("Str_Msg_SessionFileMismatchFmt",
                    wantSession, string.Join(" / ", names.ToArray()), otherSession),
                    Loc.T("Str_MsgTitle_SessionFileMismatch"), MessageBoxButton.OK, MessageBoxImage.Warning);
                AddLog(Loc.F("Str_Log_ImportRelayLegWrongSessionFmt", wantSession));
                return;
            }

            var msg = new StringBuilder();
            msg.AppendFormat(Loc.T("Str_Msg_LegImportDoneFmt"), wantSession, updated);
            foreach (var kv in perSession.OrderBy(x => x.Key))
                msg.AppendFormat(Loc.T("Str_Msg_LegImportPerSessionFmt"), kv.Key, kv.Value);
            if (blank > 0)         msg.AppendFormat(Loc.T("Str_Msg_LegImportBlankFmt"), blank);
            if (otherSession > 0)  msg.AppendFormat(Loc.T("Str_Msg_LegImportOtherSessionFmt"), otherSession, wantSession);
            if (notFound.Count > 0) {
                msg.AppendFormat(Loc.T("Str_Msg_LegImportNotFoundHeaderFmt"), notFound.Count);
                int show = Math.Min(8, notFound.Count);
                for (int i = 0; i < show; i++) msg.AppendFormat("      {0}\n", notFound[i]);
                if (notFound.Count > show) msg.AppendFormat(Loc.T("Str_Msg_LegImportMoreRowsFmt"), notFound.Count - show);
                msg.Append(Loc.T("Str_Msg_LegImportMismatchHint"));
            }
            AppMessageBox.Show(msg.ToString(), updated > 0 ? Loc.T("Str_MsgTitle_ImportSuccess") : Loc.T("Str_MsgTitle_NoDataImported"),
                MessageBoxButton.OK, updated > 0 ? MessageBoxImage.Information : MessageBoxImage.Warning);
            AddLog(Loc.F("Str_Log_ImportRelayLegDoneFmt",
                wantSession, updated, blank, otherSession, notFound.Count));
            foreach (var s in changeLog) AddLog(Loc.F("Str_Log_Indented4Fmt", s));
        }

        // 把接力队的 4 棒姓名同步到 _swimmers —— 大屏「姓名」列取的是代表条目的
        // Notes("接力队 棒次:甲,乙,丙,丁"), 不同步的话名单填了大屏也不显示。
        // 与 EditRelay_Click 里的同步逻辑保持一致。
        private void SyncRelayLegsToSwimmers(RelayTeam t, List<string> oldNames) {
            List<Swimmer> touched;
            SyncRelayLegsToSwimmers(t, oldNames, out touched);
        }
        private void SyncRelayLegsToSwimmers(RelayTeam t, List<string> oldNames, out List<Swimmer> touched) {
            touched = new List<Swimmer>();
            string legNamesStr = string.Join(",", t.Legs.Select(l => l.SwimmerName ?? "").ToArray());
            // 代表条目: 按 队名+项目+性别 定位, 不依赖 Notes 的具体写法
            // (本届档案里没填棒次时 Notes 只有"接力队"三个字, 用 StartsWith("接力队 棒次:") 找不到)
            var proxy = _swimmers.FirstOrDefault(s =>
                (s.Name ?? "") == (t.TeamName ?? "") && (s.EventName ?? "") == (t.EventName ?? "")
                && (s.Gender ?? "") == (t.Gender ?? "") && !IsRelayMemberNote(s.Notes));
            if (proxy != null) { proxy.Notes = "接力队 棒次:" + legNamesStr; touched.Add(proxy); }

            for (int i = 0; i < Math.Min(4, t.Legs.Count); i++) {
                string oldName = (oldNames != null && i < oldNames.Count) ? oldNames[i] : "";
                string newName = t.Legs[i].SwimmerName ?? "";
                if (string.IsNullOrEmpty(oldName) && string.IsNullOrEmpty(newName)) continue;
                var mem = _swimmers.FirstOrDefault(s => IsRelayMemberNote(s.Notes)
                    && (s.Country ?? "") == (t.TeamName ?? "") && (s.EventName ?? "") == (t.EventName ?? "")
                    && (s.Name ?? "") == oldName);
                if (mem != null) {
                    mem.Name = newName;
                    mem.Notes = string.Format("接力队员 {0} 第{1}棒", t.EventName, i + 1);
                    touched.Add(mem);
                } else if (!string.IsNullOrEmpty(newName)) {
                    string memBib = (proxy != null ? proxy.BibNumber : "R???") + "-" + (i + 1);
                    if (!_swimmers.Any(s => s.BibNumber == memBib)) {
                        var newMem = new Swimmer {
                            BibNumber = memBib, Name = newName,
                            Gender = (t.Gender == "混合" || t.Gender == "男女") ? "男" : t.Gender,
                            Country = t.TeamName, EventName = t.EventName,
                            AgeCategory = t.AgeGroup,
                            Notes = string.Format("接力队员 {0} 第{1}棒", t.EventName, i + 1)
                        };
                        _swimmers.Add(newMem);
                        touched.Add(newMem);
                    }
                }
            }
        }

        private void ImportRelayCSV_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.OpenFileDialog {
                Filter = Loc.T("Str_Filter_Csv"), Title = Loc.T("Str_Win_ImportRelayCsv_Title")
            };
            if (dlg.ShowDialog() != true) return;

            string[] lines;
            try { lines = File.ReadAllLines(dlg.FileName, Encoding.UTF8); }
            catch (Exception ex) { AppMessageBox.Show(Loc.F("Str_Msg_ReadFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error")); return; }

            if (lines.Length < 1) { AppMessageBox.Show(Loc.T("Str_Msg_FileIsEmpty"), Loc.T("Str_MsgTitle_Info")); return; }

            // 表头校验 —— 2026-09-30 中英文模板都认（数据行本身全按列位置解析，不靠列名，
            //   所以这里只要挑一个参照表验过位置数对得上即可，不用再改下面任何一行）
            var headerCols = ParseCsvLine(lines[0]);
            string[] rZh = RelayCsvHeaderZh, rEn = RelayCsvHeaderEn;
            if (headerCols.Length != rZh.Length) {
                AppMessageBox.Show(Loc.F("Str_Msg_RelayHeaderCountMismatchFmt",
                    rZh.Length, headerCols.Length), Loc.T("Str_MsgTitle_FormatError"));
                return;
            }
            bool relayMatchesZh = true, relayMatchesEn = true;
            for (int i = 0; i < rZh.Length; i++) {
                string actual = (headerCols[i] ?? "").Trim();
                if (actual != rZh[i]) relayMatchesZh = false;
                if (actual != rEn[i]) relayMatchesEn = false;
            }
            if (!relayMatchesZh && !relayMatchesEn) {
                // 兜底: 两个参照表都对不上的列优先报; 找不到(中英文混填的怪文件)就按中文表报第一处不一致
                int badI = -1;
                for (int i = 0; i < rZh.Length; i++) {
                    string actual = (headerCols[i] ?? "").Trim();
                    if (actual != rZh[i] && actual != rEn[i]) { badI = i; break; }
                }
                if (badI < 0) { for (int i = 0; i < rZh.Length; i++) { if ((headerCols[i] ?? "").Trim() != rZh[i]) { badI = i; break; } } }
                AppMessageBox.Show(Loc.F("Str_Msg_RelayHeaderColMismatchFmt",
                    badI + 1, RelayCsvHeader[badI], (headerCols[badI] ?? "").Trim()), Loc.T("Str_MsgTitle_FormatError"));
                return;
            }

            // 接力项目名单
            var relayEvents = new HashSet<string>(_events.Where(ev => ev != null && ev.Contains("接力")));
            // 现有队伍 (避免重复)
            var existingKeys = new HashSet<string>();
            foreach (var t in _relayTeams) existingKeys.Add((t.TeamName ?? "") + "|" + (t.EventName ?? "") + "|" + (t.Gender ?? "") + "|" + (t.AgeGroup ?? ""));

            int importedCount = 0, pendingCount = 0;
            var skipped = new List<string>();
            var addedRows = new List<Swimmer>();
            var addedTeams = new List<RelayTeam>();

            for (int li = 1; li < lines.Length; li++) {
                string raw = lines[li];
                if (string.IsNullOrWhiteSpace(raw)) continue;
                var c = ParseCsvLine(raw);
                if (c.Length < RelayCsvHeader.Length) {
                    skipped.Add(Loc.F("Str_Msg_RelayCsvColCountFmt", li + 1, c.Length, RelayCsvHeader.Length));
                    continue;
                }
                string teamName = (c[0] ?? "").Trim();
                string ageGrp   = (c[1] ?? "").Trim();   // 2026-05-25 新增组别列
                string evName   = (c[2] ?? "").Trim();
                string gender   = (c[3] ?? "").Trim();
                string entryTime = (c[4] ?? "").Trim();

                if (string.IsNullOrEmpty(teamName)) { skipped.Add(Loc.F("Str_Msg_RelayCsvMissingTeamFmt", li + 1)); continue; }
                if (string.IsNullOrEmpty(evName))   { skipped.Add(Loc.F("Str_Msg_RelayCsvMissingEventFmt", li + 1, teamName)); continue; }
                if (!evName.Contains("接力"))       { skipped.Add(Loc.F("Str_Msg_RelayCsvNotRelayEventFmt", li + 1, teamName, evName)); continue; }
                if (relayEvents.Count > 0 && !relayEvents.Contains(evName)) {
                    skipped.Add(Loc.F("Str_Msg_RelayCsvEventNotInListFmt", li + 1, teamName, evName));
                    continue;
                }
                if (gender != "男" && gender != "女" && gender != "混合") {
                    skipped.Add(Loc.F("Str_Msg_RelayCsvInvalidGenderFmt", li + 1, teamName, gender));
                    continue;
                }
                string dedupKey = teamName + "|" + evName + "|" + gender + "|" + ageGrp;
                if (existingKeys.Contains(dedupKey)) {
                    skipped.Add(Loc.F("Str_Msg_RelayCsvDuplicateFmt", li + 1, teamName));
                    continue;
                }

                // 4 棒 (列起始位移 +1 因为组别插入)
                var legNames = new string[4];
                var legIds = new string[4];
                var legBirths = new string[4];
                bool missingLegName = false;
                int legBirthMissing = 0;
                for (int k = 0; k < 4; k++) {
                    legNames[k] = (c[5 + k * 3] ?? "").Trim();
                    legIds[k]   = (c[6 + k * 3] ?? "").Trim();
                    legBirths[k]= (c[7 + k * 3] ?? "").Trim();
                    if (string.IsNullOrEmpty(legNames[k])) missingLegName = true;
                    if (string.IsNullOrEmpty(legBirths[k])) legBirthMissing++;
                }
                if (missingLegName) {
                    skipped.Add(Loc.F("Str_Msg_RelayCsvMissingLegNamesFmt", li + 1, teamName));
                    continue;
                }

                // 通过校验，建队
                var team = new RelayTeam {
                    TeamName = teamName, EventName = evName, Gender = gender, AgeGroup = ageGrp,
                    EntryTime = entryTime,
                    EntryTimeSeconds = string.IsNullOrEmpty(entryTime) ? 0 : TimeFormatter.Parse(entryTime),
                    AgeCategoryPending = legBirthMissing > 0
                };
                for (int k = 0; k < 4; k++) {
                    team.Legs.Add(new RelayLeg {
                        LegOrder = k + 1,
                        SwimmerName = legNames[k],
                        SwimmerIDNumber = legIds[k],
                        SwimmerBirthDate = legBirths[k],
                        SwimmerBibNumber = ""
                    });
                }
                _relayTeams.Add(team);
                addedTeams.Add(team);
                existingKeys.Add(dedupKey);
                if (team.AgeCategoryPending) pendingCount++;
                importedCount++;

                // 写代表条目 + 队员条目（与 AddRelayCore 一致）
                string legNamesStr = string.Join(",", legNames);
                string teamBib = "R" + _relayTeams.Count.ToString("D3");
                while (_swimmers.Any(s => s.BibNumber == teamBib)) teamBib = "R" + DateTime.Now.Ticks.ToString().Substring(10);
                var proxyRow = new Swimmer {
                    BibNumber = teamBib, Name = teamName, Gender = gender, Country = teamName,
                    EventName = evName, AgeCategory = ageGrp,
                    EntryTime = entryTime, EntryTimeSeconds = team.EntryTimeSeconds,
                    Notes = string.Format("接力队 棒次:{0}", legNamesStr)
                };
                _swimmers.Add(proxyRow);
                addedRows.Add(proxyRow);
                for (int k = 0; k < 4; k++) {
                    string memBib = teamBib + "-" + (k + 1);
                    if (_swimmers.Any(s => s.BibNumber == memBib)) continue;
                    var memberRow = new Swimmer {
                        BibNumber = memBib, Name = legNames[k],
                        Gender = gender == "混合" ? "男" : gender, Country = teamName,
                        IDNumber = legIds[k] ?? "",
                        BirthDate = legBirths[k] ?? "",
                        EventName = evName,
                        Notes = string.Format("接力队员 {0} 第{1}棒", evName, k + 1)
                    };
                    _swimmers.Add(memberRow);
                    addedRows.Add(memberRow);
                }
            }

            RebuildRelayGroupedView();
            FinishAndSyncPatch(BuildSwimmerRowsAddPatch(addedRows, addedTeams, ClientLabel()), "swimmer");
            AddLog(Loc.F("Str_Log_RelayCsvImportFmt",
                importedCount, skipped.Count, pendingCount));

            // 汇总弹窗
            var sb = new StringBuilder();
            sb.AppendFormat(Loc.T("Str_Msg_RelayCsvImportSummaryFmt"),
                importedCount, skipped.Count, pendingCount);
            if (skipped.Count > 0) {
                sb.AppendLine(Loc.T("Str_Msg_SkipRecordsHeader"));
                int show = Math.Min(skipped.Count, 30);
                for (int i = 0; i < show; i++) sb.AppendLine("• " + skipped[i]);
                if (skipped.Count > show) sb.AppendFormat(Loc.T("Str_Msg_MoreNotShownFmt"), skipped.Count - show);
            }
            AppMessageBox.Show(sb.ToString(), Loc.T("Str_MsgTitle_RelayCsvImportResult"), MessageBoxButton.OK, MessageBoxImage.Information);
        }

        // CSV 工具
        private static string CsvEsc(string s) {
            if (s == null) return "";
            if (s.IndexOfAny(new[] { ',', '"', '\n', '\r' }) >= 0) return "\"" + s.Replace("\"", "\"\"") + "\"";
            return s;
        }
        private static string[] ParseCsvLine(string line) {
            var result = new List<string>();
            var sb = new StringBuilder();
            bool inQuotes = false;
            for (int i = 0; i < line.Length; i++) {
                char c = line[i];
                if (inQuotes) {
                    if (c == '"') {
                        if (i + 1 < line.Length && line[i + 1] == '"') { sb.Append('"'); i++; }
                        else inQuotes = false;
                    } else sb.Append(c);
                } else {
                    if (c == ',') { result.Add(sb.ToString()); sb.Length = 0; }
                    else if (c == '"') inQuotes = true;
                    else sb.Append(c);
                }
            }
            result.Add(sb.ToString());
            return result.ToArray();
        }

        // 2026-05-24 编辑接力队（队名/单位/项目/性别/4 棒姓名/报名成绩）+ 二次确认 + 校验
        private void EditRelay_Click(object sender, RoutedEventArgs e) {
            var sel = _selectedRelayTeam;
            if (sel == null) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayToEdit"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            string lockKey = "relay:" + (sel.TeamName ?? "") + "|" + (sel.EventName ?? "");
            string holder;
            if (!TryAcquireEditLock(lockKey, out holder)) {
                AppMessageBox.Show(Loc.F("Str_Msg_RelayBeingEditedFmt", sel.TeamName, holder),
                    Loc.T("Str_MsgTitle_CannotEdit"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                // 旧标识用于在 _swimmers 中找代表/队员条目
                string oldTeamName = sel.TeamName;
                string oldEvent = sel.EventName;
                string oldGender = sel.Gender;
                var oldLegNames = sel.Legs.Select(l => l.SwimmerName ?? "").ToList();

                var dlg = new EditRelayTeamWindow(sel, _events, _units, _ageGroups.Select(g => g.Name), _genders) { Owner = this };
                bool? r = dlg.ShowDialog();
                if (r != true || !dlg.Confirmed) return;

                string newTeamName = sel.TeamName, newCountry = sel.Country, newEvent = sel.EventName, newGender = sel.Gender;
                string newEntryTime = sel.EntryTime; double newEntryTimeSeconds = sel.EntryTimeSeconds;
                var legNames = sel.Legs.Select(l => l.SwimmerName ?? "").ToList();

                // 2026-09-19 【改走小补丁, 不再推整包】——这个功能之前一直是本文件仅剩的
                //   老路之一(AutoSaveData() 直接触发整包推送), 现场事故(计时中 TP/MB 被
                //   整包重载冲成关闭, 见当时的说明)的诱因就是它。跟并组同一个待遇:
                //   联着主服务器的编排端先问一句、等回执再改本机; 拒了就原样不动、弹窗
                //   说明原因, 不吞不改。
                bool serverAccepted = false;
                if (IsScheduleEditorMode && _editorSyncClient != null && _editorSyncClient.IsConnected) {
                    string perr;
                    if (!SendRelayEditPatch(oldTeamName, oldEvent, oldGender, oldLegNames,
                            newTeamName, newCountry, newEvent, newGender, newEntryTime, newEntryTimeSeconds, legNames,
                            out perr)) {
                        AppMessageBox.Show(Loc.F("Str_Msg_RelayEditRejectedFmt", perr),
                            Loc.T("Str_MsgTitle_SaveNotDone"), MessageBoxButton.OK, MessageBoxImage.Warning);
                        AddLog(Loc.F("Str_Log_RelayEditRejectedFmt", perr));
                        return;
                    }
                    serverAccepted = true;
                }

                string applyError;
                if (!ApplyRelayEditCore(oldTeamName, oldEvent, oldGender, oldLegNames,
                        newTeamName, newCountry, newEvent, newGender, newEntryTime, newEntryTimeSeconds, legNames,
                        out applyError)) {
                    if (serverAccepted) {
                        AppMessageBox.Show(Loc.F("Str_Msg_RelayEditServerAheadFmt", applyError),
                            Loc.T("Str_MsgTitle_ServerMismatch"), MessageBoxButton.OK, MessageBoxImage.Error);
                        AddLog(Loc.F("Str_Log_RelayEditApplyFailedFmt", applyError));
                    } else {
                        AppMessageBox.Show(applyError, Loc.T("Str_MsgTitle_CannotSave"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                    return;
                }

                if (!IsScheduleEditorMode)
                    BroadcastRelayEditPatch(oldTeamName, oldEvent, oldGender, oldLegNames,
                        newTeamName, newCountry, newEvent, newGender, newEntryTime, newEntryTimeSeconds, legNames,
                        Environment.MachineName, null);

                FinishRelayEditPatchApply();
                AddLog(Loc.F("Str_Log_RelayEditedFmt", newTeamName, Loc.GenderDisplay(newGender), newEvent));
            } finally {
                ReleaseEditLock(lockKey);
            }
        }

        private void DeleteRelay_Click(object sender, RoutedEventArgs e) {
            var selected = _selectedRelayTeam;
            if (selected == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayFirst")); return; }
            string lockKey = "relay:" + (selected.TeamName ?? "") + "|" + (selected.EventName ?? "");
            string holder;
            if (!TryAcquireEditLock(lockKey, out holder)) {
                AppMessageBox.Show(
                    Loc.F("Str_Msg_RelayBeingEditedCannotDeleteFmt", selected.TeamName, holder),
                    Loc.T("Str_MsgTitle_CannotDelete"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                if (AppMessageBox.Show(Loc.F("Str_Msg_ConfirmDeleteRelayFmt", selected.TeamName, selected.EventName), Loc.T("Str_MsgTitle_Confirm"), MessageBoxButton.YesNo) != MessageBoxResult.Yes) return;

                string teamName = selected.TeamName, eventName = selected.EventName, gender = selected.Gender;
                bool serverAccepted = false;
                if (IsScheduleEditorMode && _editorSyncClient != null && _editorSyncClient.IsConnected) {
                    string perr;
                    if (!SendRelayDeletePatch(teamName, eventName, gender, out perr)) {
                        AppMessageBox.Show(Loc.F("Str_Msg_DeleteRejectedFmt", perr), Loc.T("Str_MsgTitle_DeleteNotDone"), MessageBoxButton.OK, MessageBoxImage.Warning);
                        AddLog(Loc.F("Str_Log_RelayDeleteRejectedFmt", perr));
                        return;
                    }
                    serverAccepted = true;
                }
                string applyError;
                if (!ApplyRelayDeleteCore(teamName, eventName, gender, out applyError)) {
                    if (serverAccepted) {
                        AppMessageBox.Show(Loc.F("Str_Msg_DeleteServerAheadFmt", applyError),
                            Loc.T("Str_MsgTitle_ServerMismatch"), MessageBoxButton.OK, MessageBoxImage.Error);
                    } else {
                        AppMessageBox.Show(applyError, Loc.T("Str_MsgTitle_CannotDelete"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                    return;
                }
                if (!IsScheduleEditorMode) BroadcastRelayDeletePatch(teamName, eventName, gender, Environment.MachineName, null);

                _selectedRelayTeam = null;
                if (RelayLegGrid != null) RelayLegGrid.ItemsSource = null;
                RelayLegTitle.Text = Loc.T("Str_RelayLeg_SelectTeamHint");
                FinishRelayEditPatchApply();
                AddLog(Loc.F("Str_Log_RelayDeletedFmt", teamName, eventName));
            } finally {
                ReleaseEditLock(lockKey);
            }
        }

        private void RelayGrid_SelectionChanged(object sender, SelectionChangedEventArgs e) {
            var selected = _selectedRelayTeam;
            if (selected == null) {
                if (RelayLegGrid != null) RelayLegGrid.ItemsSource = null;
                RelayLegTitle.Text = Loc.T("Str_RelayLeg_SelectTeamHint");
                return;
            }
            // 自动补全队员号码 / 身份证号
            foreach (var leg in selected.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName)) continue;
                var match = _swimmers.FirstOrDefault(s => s.Name == leg.SwimmerName && s.Country == selected.TeamName);
                if (match == null) continue;
                if (string.IsNullOrEmpty(leg.SwimmerBibNumber) && !string.IsNullOrEmpty(match.BibNumber))
                    leg.SwimmerBibNumber = match.BibNumber;
                if (string.IsNullOrEmpty(leg.SwimmerIDNumber) && !string.IsNullOrEmpty(match.IDNumber))
                    leg.SwimmerIDNumber = match.IDNumber;
            }
            RelayLegTitle.Text = string.Format("{0} — {1} 棒次安排（{2}人）", selected.TeamName, selected.EventName, selected.Legs.Count);
            RelayLegGrid.ItemsSource = selected.Legs;
        }

        private void RelayLegUp_Click(object sender, RoutedEventArgs e) {
            var team = _selectedRelayTeam;
            if (team == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayFirst")); return; }
            int idx = RelayLegGrid.SelectedIndex;
            if (idx <= 0) return;
            // 交换棒次
            var leg1 = team.Legs[idx];
            var leg2 = team.Legs[idx - 1];
            int tmpOrder = leg1.LegOrder;
            leg1.LegOrder = leg2.LegOrder;
            leg2.LegOrder = tmpOrder;
            team.Legs.Move(idx, idx - 1);
            RelayLegGrid.SelectedIndex = idx - 1;
        }

        private void RelayLegDown_Click(object sender, RoutedEventArgs e) {
            var team = _selectedRelayTeam;
            if (team == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayFirst")); return; }
            int idx = RelayLegGrid.SelectedIndex;
            if (idx < 0 || idx >= team.Legs.Count - 1) return;
            var leg1 = team.Legs[idx];
            var leg2 = team.Legs[idx + 1];
            int tmpOrder = leg1.LegOrder;
            leg1.LegOrder = leg2.LegOrder;
            leg2.LegOrder = tmpOrder;
            team.Legs.Move(idx, idx + 1);
            RelayLegGrid.SelectedIndex = idx + 1;
        }

        private void RelayLegReplace_Click(object sender, RoutedEventArgs e) {
            var team = _selectedRelayTeam;
            if (team == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayFirst")); return; }
            var leg = RelayLegGrid.SelectedItem as RelayLeg;
            if (leg == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectLegToReplace")); return; }
