        private void RelayLegReplaceCore(RelayTeam team, RelayLeg leg) {

            // 确定被更换队员的性别
            string legGender = "";
            if (!string.IsNullOrEmpty(leg.SwimmerName)) {
                var currentMember = _swimmers.FirstOrDefault(s => s.Name == leg.SwimmerName && s.Country == team.TeamName);
                if (currentMember != null) legGender = currentMember.Gender;
            }
            // 非混合接力：性别和队伍一致
            if (team.Gender != "混合") legGender = team.Gender;

            // 查找该代表队的可替换运动员（同队名、同性别，排除已在棒次中的）
            var existingNames = new HashSet<string>();
            foreach (var l in team.Legs) {
                if (!string.IsNullOrEmpty(l.SwimmerName)) existingNames.Add(l.SwimmerName);
            }
            var teamMembers = _swimmers.Where(s =>
                (s.Country == team.TeamName || s.Name == team.TeamName) &&
                !string.IsNullOrEmpty(s.Name) &&
                !existingNames.Contains(s.Name) &&
                (string.IsNullOrEmpty(s.Notes) || !s.Notes.StartsWith("接力队 ")) &&
                (string.IsNullOrEmpty(legGender) || s.Gender == legGender)
            ).ToList();

            string genderLabel = !string.IsNullOrEmpty(legGender) ? "（" + Loc.GenderDisplay(legGender) + "）" : "";

            var dlg = new Window {
                Title = Loc.F("Str_Win_SwapRelayLeg_TitleFmt", leg.LegOrder, genderLabel, team.TeamName),
                Width = 400, Height = 380,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock {
                Text = string.Format("当前第{0}棒: {1} {2}", leg.LegOrder, leg.SwimmerName, genderLabel),
                FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 10)
            });

            // 从本队运动员中选择
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_RelayLeg_PickFromTeam"), FontSize = 13, Margin = new Thickness(0, 0, 0, 4) });
            var memberList = new ListBox { Height = 120, FontSize = 13 };
            foreach (var m in teamMembers) {
                memberList.Items.Add(string.Format("{0}  ({1})  {2}", m.Name, m.BibNumber ?? "", m.Gender));
            }
            if (teamMembers.Count == 0) {
                memberList.Items.Add("（无可选队员，请手动输入）");
                memberList.IsEnabled = false;
            }
            sp.Children.Add(memberList);

            // 分隔线
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_RelayLeg_OrManualEntry"), HorizontalAlignment = HorizontalAlignment.Center,
                Foreground = new SolidColorBrush(Colors.Gray), Margin = new Thickness(0, 8, 0, 4) });

            var inputPanel = new Grid();
            inputPanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            inputPanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(180) });
            inputPanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(80) });
            var tbName = new TextBox { Padding = new Thickness(4), Margin = new Thickness(0, 0, 4, 0) };
            tbName.SetValue(Grid.ColumnProperty, 0);
            var tbID = new TextBox { Padding = new Thickness(4), Margin = new Thickness(0, 0, 4, 0) };
            tbID.SetValue(Grid.ColumnProperty, 1);
            var tbBib = new TextBox { Padding = new Thickness(4) };
            tbBib.SetValue(Grid.ColumnProperty, 2);
            inputPanel.Children.Add(tbName);
            inputPanel.Children.Add(tbID);
            inputPanel.Children.Add(tbBib);

            var labelPanel = new Grid();
            labelPanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            labelPanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(180) });
            labelPanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(80) });
            var lb1 = new TextBlock { Text = Loc.T("Str_Label_NameColon"), FontSize = 12, Foreground = new SolidColorBrush(Colors.Gray) };
            lb1.SetValue(Grid.ColumnProperty, 0);
            var lb2 = new TextBlock { Text = Loc.T("Str_Label_IdNumberColon"), FontSize = 12, Foreground = new SolidColorBrush(Colors.Gray) };
            lb2.SetValue(Grid.ColumnProperty, 1);
            var lb3 = new TextBlock { Text = Loc.T("Str_Label_BibColon"), FontSize = 12, Foreground = new SolidColorBrush(Colors.Gray) };
            lb3.SetValue(Grid.ColumnProperty, 2);
            labelPanel.Children.Add(lb1);
            labelPanel.Children.Add(lb2);
            labelPanel.Children.Add(lb3);
            sp.Children.Add(labelPanel);
            sp.Children.Add(inputPanel);

            // 提示条
            var hintBorder = new Border {
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#FEF3C7")),
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")),
                BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(4),
                Padding = new Thickness(8, 4, 8, 4), Margin = new Thickness(0, 6, 0, 0)
            };
            hintBorder.Child = new TextBlock {
                Text = Loc.T("Str_RelayLeg_ManualHint"),
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#92400E")),
                FontSize = 11, TextWrapping = TextWrapping.Wrap
            };
            sp.Children.Add(hintBorder);

            // 选择列表项时自动填入
            memberList.SelectionChanged += delegate {
                int selIdx = memberList.SelectedIndex;
                if (selIdx >= 0 && selIdx < teamMembers.Count) {
                    tbName.Text = teamMembers[selIdx].Name;
                    tbBib.Text = teamMembers[selIdx].BibNumber ?? "";
                    tbID.Text = teamMembers[selIdx].IDNumber ?? "";
                }
            };

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) };
            var btnOk = new Button {
                Content = Loc.T("Str_Btn_ConfirmReplace"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0)
            };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnCancel = new Button {
                Content = Loc.T("Str_Btn_Close"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0)
            };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            sp.Children.Add(btnPanel);
            dlg.Content = sp;

            if (dlg.ShowDialog() == true && !string.IsNullOrEmpty(tbName.Text.Trim())) {
                string oldName = leg.SwimmerName;
                leg.SwimmerName = tbName.Text.Trim();
                leg.SwimmerBibNumber = tbBib.Text.Trim();
                leg.SwimmerIDNumber = tbID.Text.Trim();
                RelayLegGrid.Items.Refresh();
                AddLog(Loc.F("Str_Log_RelayLegChangedFmt", team.TeamName, leg.LegOrder, oldName, leg.SwimmerName));
            }
        }

        private void RelayLegSave_Click(object sender, RoutedEventArgs e) {
            var team = _selectedRelayTeam;
            if (team == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRelayFirst")); return; }
            string lockKey = "relay:" + (team.TeamName ?? "") + "|" + (team.EventName ?? "");
            string holder;
            if (!TryAcquireEditLock(lockKey, out holder)) {
                AppMessageBox.Show(
                    Loc.F("Str_Msg_RelayBeingEditedFmt", team.TeamName, holder),
                    Loc.T("Str_MsgTitle_CannotSave"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                RelayLegSaveCore(team);
            } finally {
                ReleaseEditLock(lockKey);
            }
        }

        private void RelayLegSaveCore(RelayTeam team) {
            // 更新_swimmers中代表条目的Notes
            var proxy = _swimmers.FirstOrDefault(s => s.Name == team.TeamName && s.EventName == team.EventName && s.Gender == team.Gender && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队"));
            if (proxy != null) {
                string legNames = "";
                foreach (var leg in team.Legs) legNames += (legNames.Length > 0 ? "," : "") + leg.SwimmerName;
                proxy.Notes = string.Format("接力队 棒次:{0}", legNames);
            }
            // 同步每位队员的 Swimmer 子条目：身份证号/号码
            string teamBib = proxy != null ? (proxy.BibNumber ?? "") : "";
            foreach (var leg in team.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName)) continue;
                string memBib = !string.IsNullOrEmpty(leg.SwimmerBibNumber) ? leg.SwimmerBibNumber : teamBib + "-" + leg.LegOrder;
                var memExisting = _swimmers.FirstOrDefault(s =>
                    s.Notes != null && s.Notes.StartsWith("接力队员")
                    && s.EventName == team.EventName && s.Country == team.TeamName
                    && (s.Name == leg.SwimmerName || s.BibNumber == memBib));
                if (memExisting != null) {
                    if (!string.IsNullOrEmpty(leg.SwimmerIDNumber)) memExisting.IDNumber = leg.SwimmerIDNumber;
                    if (!string.IsNullOrEmpty(leg.SwimmerBibNumber)) memExisting.BibNumber = leg.SwimmerBibNumber;
                    if (!string.IsNullOrEmpty(leg.SwimmerName)) memExisting.Name = leg.SwimmerName;
                } else {
                    _swimmers.Add(new Swimmer {
                        BibNumber = memBib,
                        Name = leg.SwimmerName,
                        Gender = team.Gender == "混合" ? "男" : team.Gender,
                        Country = team.TeamName,
                        IDNumber = leg.SwimmerIDNumber ?? "",
                        EventName = team.EventName,
                        Notes = string.Format("接力队员 {0} 第{1}棒", team.EventName, leg.LegOrder)
                    });
                }
            }
            // 同步队员条目的生日（管理员补录后写回 Swimmer.BirthDate）
            foreach (var leg in team.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName) || string.IsNullOrEmpty(leg.SwimmerBirthDate)) continue;
                var memEntry = _swimmers.FirstOrDefault(s =>
                    s.Notes != null && s.Notes.StartsWith("接力队员")
                    && s.EventName == team.EventName && s.Country == team.TeamName
                    && s.Name == leg.SwimmerName);
                if (memEntry != null) memEntry.BirthDate = leg.SwimmerBirthDate;
            }

            // 2026-05-24 CSV 导入校验联动：4 棒生日补全后自动锁定分组（清除 AgeCategoryPending）
            if (team.AgeCategoryPending) {
                bool allFilled = team.Legs.Count >= 4
                    && team.Legs.All(l => !string.IsNullOrEmpty(l.SwimmerBirthDate));
                if (allFilled) {
                    team.AgeCategoryPending = false;
                    AddLog(Loc.F("Str_Log_RelayBirthdatesCompletedFmt", team.TeamName));
                }
            }

            // 刷新上方分组视图
            RebuildRelayGroupedView();
            AutoSaveData();
            Broadcast();
            AppMessageBox.Show(Loc.T("Str_Msg_RelayLegsSaved"), Loc.T("Str_MsgTitle_SaveSuccess"));
        }

        /// <summary>
        /// 同步接力队的分组信息：从_swimmers代表条目同步Heat/Lane/Stage到_relayTeams
        /// </summary>
        private void SyncRelayHeatInfo_Click(object sender, RoutedEventArgs e) {
            SyncRelayHeatInfo();
            RebuildRelayGroupedView();
            AppMessageBox.Show(Loc.T("Str_Msg_RelayHeatInfoSynced"), Loc.T("Str_MsgTitle_SyncDone"));
        }

        /// <summary>
        /// 同步接力队的分组信息：从_swimmers代表条目同步Heat/Lane/Stage到_relayTeams
        /// </summary>
        private void SyncRelayHeatInfo() {
            int synced = 0;
            foreach (var team in _relayTeams) {
                var proxy = _swimmers.FirstOrDefault(s => s.Name == team.TeamName && s.EventName == team.EventName && s.Gender == team.Gender && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队"));
                if (proxy != null) {
                    team.Heat = proxy.Heat;
                    team.Lane = proxy.Lane;
                    team.Stage = proxy.CurrentStage;
                    synced++;
                }
            }
            if (RelayGrid != null) RelayGrid.Items.Refresh();
            RebuildRelayGroupedView();
            if (synced > 0) AddLog(Loc.F("Str_Log_RelayAssignSyncedFmt", synced));
        }

        private RelayTeam _selectedRelayTeam;

        /// <summary>
        /// 按接力项目分组显示接力队列表（类似赛程管理的场分组）
        /// </summary>
        private void RebuildRelayGroupedView() {
            if (RelayGroupedPanel == null) return;
            RelayGroupedPanel.Children.Clear();

            if (_relayTeams.Count == 0) {
                RelayGroupedPanel.Children.Add(new TextBlock {
                    Text = Loc.T("Str_EM_Relay_NoTeams"),
                    Foreground = new SolidColorBrush(Colors.Gray), Margin = new Thickness(10), FontSize = 13
                });
                return;
            }

            // 2026-05-25 按 组别+性别+项目 三键分组 (原只按 性别+项目, 不同组别会合并到同一面板)
            var groups = _relayTeams.GroupBy(t => new { AgeGroup = t.AgeGroup ?? "", t.Gender, t.EventName })
                .OrderBy(g => g.Key.AgeGroup).ThenBy(g => g.Key.Gender).ThenBy(g => g.Key.EventName);

            foreach (var group in groups) {
                string ageTag = string.IsNullOrEmpty(group.Key.AgeGroup) ? "" : "[" + group.Key.AgeGroup + "] ";
                string title = string.Format(Loc.T("Str_EM_Relay_GroupTitleFmt"), ageTag, group.Key.Gender, group.Key.EventName, group.Count());
                var header = new TextBlock {
                    Text = title,
                    FontWeight = FontWeights.Bold, FontSize = 15,
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E40AF")),
                    Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#DBEAFE")),
                    Padding = new Thickness(10, 5, 10, 5),
                    Margin = new Thickness(0, 6, 0, 4)
                };
                RelayGroupedPanel.Children.Add(header);

                // 该项目下的接力队DataGrid
                var grid = new DataGrid {
                    AutoGenerateColumns = false, CanUserAddRows = false,
                    SelectionMode = DataGridSelectionMode.Single,
                    IsReadOnly = true,
                    HeadersVisibility = DataGridHeadersVisibility.Column,
                    AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                    MinHeight = 30,
                    BorderThickness = new Thickness(1),
                    BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E2E8F0"))
                };
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Relay_ColTeamName"), Binding = new System.Windows.Data.Binding("TeamName"), Width = new DataGridLength(100) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColAgeGroup"), Binding = new System.Windows.Data.Binding("AgeGroup"), Width = new DataGridLength(60) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_LT_SeedEntry"), Binding = new System.Windows.Data.Binding("EntryTime"), Width = new DataGridLength(80) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Relay_ColLegs"), Binding = new System.Windows.Data.Binding("LegOrderDisplay"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Relay_ColStage"), Binding = new System.Windows.Data.Binding("Stage"), Width = new DataGridLength(50) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Relay_ColHeat"), Binding = new System.Windows.Data.Binding("Heat"), Width = new DataGridLength(35) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColLane"), Binding = new System.Windows.Data.Binding("Lane"), Width = new DataGridLength(35) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColStatus"), Binding = new System.Windows.Data.Binding("Status"), Width = new DataGridLength(50) });

                // 2026-05-24 CSV 导入校验 — AgeCategoryPending 高亮黄色 + 弹出提示气泡
                var rowStyle = new Style(typeof(DataGridRow));
                var trigger = new System.Windows.DataTrigger {
                    Binding = new System.Windows.Data.Binding("AgeCategoryPending"),
                    Value = true
                };
                trigger.Setters.Add(new Setter(DataGridRow.BackgroundProperty,
                    new SolidColorBrush((Color)ColorConverter.ConvertFromString("#FEF3C7"))));
                trigger.Setters.Add(new Setter(DataGridRow.ToolTipProperty,
                    (object)Loc.T("Str_EM_Relay_AgeCategoryPendingTip")));
                rowStyle.Triggers.Add(trigger);
                grid.RowStyle = rowStyle;

                var teamList = group.OrderBy(t => t.Heat).ThenBy(t => t.Lane).ToList();
                grid.ItemsSource = teamList;

                // 选中行时更新棒次详情
                grid.SelectionChanged += delegate {
                    var sel = grid.SelectedItem as RelayTeam;
                    if (sel != null) {
                        _selectedRelayTeam = sel;
                        // 自动补全队员号码
                        foreach (var leg in sel.Legs) {
                            if (string.IsNullOrEmpty(leg.SwimmerBibNumber) && !string.IsNullOrEmpty(leg.SwimmerName)) {
                                var match = _swimmers.FirstOrDefault(s => s.Name == leg.SwimmerName && s.Country == sel.TeamName);
                                if (match != null && !string.IsNullOrEmpty(match.BibNumber))
                                    leg.SwimmerBibNumber = match.BibNumber;
                            }
                        }
                        RelayLegTitle.Text = string.Format(Loc.T("Str_EM_Relay_LegTitleFmt"), sel.TeamName, sel.EventName, sel.Legs.Count);
                        RelayLegGrid.ItemsSource = sel.Legs;
                    }
                };

                RelayGroupedPanel.Children.Add(grid);
            }
        }

        // 本地注册项目列表
        private List<Tuple<string, string>> _regEventList = new List<Tuple<string, string>>(); // eventName, entryTime

        private void RegAddEvent_Click(object sender, RoutedEventArgs e) {
            string eventName = RegEventCombo.SelectedItem != null ? ((ComboBoxItem)RegEventCombo.SelectedItem).Content.ToString() : "";
            if (string.IsNullOrEmpty(eventName)) { RegStatusText.Text = Loc.T("Str_Msg_PleaseSelectEvent"); return; }

            foreach (var ev in _regEventList) {
                if (ev.Item1 == eventName) {
                    AppMessageBox.Show(Loc.T("Str_Msg_EventAlreadyAdded"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
            }
            _regEventList.Add(new Tuple<string, string>(eventName, RegEntryTimeBox.Text.Trim()));
            RegEntryTimeBox.Clear();
            RefreshRegEventList();
        }

        private void RegRemoveEvent_Click(object sender, RoutedEventArgs e) {
            int idx = RegEventListBox.SelectedIndex;
            if (idx < 0 || idx >= _regEventList.Count) { AppMessageBox.Show(Loc.T("Str_Msg_SelectEventToDelete")); return; }
            _regEventList.RemoveAt(idx);
            RefreshRegEventList();
        }

        private void RefreshRegEventList() {
            RegEventListBox.Items.Clear();
            foreach (var ev in _regEventList) {
                string display = string.IsNullOrEmpty(ev.Item2) ? ev.Item1 : string.Format("{0}  (报名: {1})", ev.Item1, ev.Item2);
                RegEventListBox.Items.Add(display);
            }
        }

        private void RegSubmitAll_Click(object sender, RoutedEventArgs e) {
            // 2026-06-25 必填项校验 (= 跟 register.html 同款规范: 收集所有缺项一次性弹窗, 阻止提交)
            //   必填: 姓名 / 性别 / 组别 / 出生日期 / 身份证号 (15 或 18 位) / 代表队 / 参赛项目 (>=1)
            var errors = new List<string>();
            string name = RegNameBox.Text.Trim();
            if (string.IsNullOrEmpty(name)) errors.Add("请填写姓名");

            string gender = RegGenderCombo.SelectedItem != null ? ((ComboBoxItem)RegGenderCombo.SelectedItem).Tag.ToString() : "";
            if (string.IsNullOrEmpty(gender)) errors.Add("请选择性别");

            // 报名时直接选择组别 (必填, 跟 register.html 一致)
            string regGroup = RegGroupCombo != null
                ? (RegGroupCombo.SelectedItem != null
                    ? RegGroupCombo.SelectedItem.ToString()
                    : (RegGroupCombo.Text ?? "").Trim())
                : "";
            if (string.IsNullOrEmpty(regGroup)) errors.Add("请选择组别");

            // 出生日期 (必填 + 格式校验)
            string bdErr;
            string birthDate = ReadBirthDateFromPicker(RegBirthDatePicker, out bdErr);
            if (bdErr != null) errors.Add(bdErr);
            else if (string.IsNullOrEmpty(birthDate)) errors.Add("请填写出生日期");

            // 身份证号 必填 + 15/18 位校验 (= 跟 register.html line 671 一致)
            string regIdNumber = RegIDNumberBox.Text.Trim();
            if (string.IsNullOrEmpty(regIdNumber)) errors.Add("请填写身份证号");
            else if (regIdNumber.Length != 15 && regIdNumber.Length != 18) errors.Add("身份证号应为 15 或 18 位");

            string regCountry = RegCountryBox != null ? RegCountryBox.Text.Trim() : "";
            if (string.IsNullOrEmpty(regCountry)) errors.Add("请填写代表队");

            if (_regEventList.Count == 0) errors.Add("请至少添加一个参赛项目");

            if (errors.Count > 0) {
                string vmsg = "表单未通过校验，请补全以下字段：\n\n  • " + string.Join("\n  • ", errors);
                AppMessageBox.Show(this, vmsg, Loc.T("Str_MsgTitle_RequiredMissing"), MessageBoxButton.OK, MessageBoxImage.Warning);
                RegStatusText.Text = Loc.T("Str_Label_ValidationFailedColon") + string.Join(" / ", errors);
                RegStatusText.Foreground = new SolidColorBrush(Colors.Red);
                return;
            }

            // 2026-05-24 自动把新代表队加进 Unit 列表（用户在下拉里手输新单位时）
            if (!_units.Any(u => u != null && u.Name == regCountry)) {
                string shortName = RegCountryShortBox != null ? RegCountryShortBox.Text.Trim() : "";
                _units.Add(new Unit { Name = regCountry, ShortName = shortName });
                RefreshUnitComboBox();
                AddLog(Loc.F("Str_Log_AutoAddedNewUnitFmt", regCountry));
            }

            // 2026-05-21 Upsert：若同身份证号已在 DB 中 → 复用其 bib，避免一个人因为
            // 多次报名拿到多个不同号码牌；否则按代表队号码段生成新号。
            // 校验通过后 regIdNumber 一定非空 (= 必填)
            string bibNumber = null;
            var anyExisting = _swimmers.FirstOrDefault(s =>
                !string.IsNullOrEmpty(s.IDNumber) && s.IDNumber == regIdNumber);
            if (anyExisting != null) bibNumber = anyExisting.BibNumber;
            if (string.IsNullOrEmpty(bibNumber)) bibNumber = GenerateNextBibNumber(regCountry);

            // 2026-05-21 支持手动输入 yyyy-MM-dd（与 HTML <input type="date"> 一致）；
            // 输入了但解析不出来 → 报错而不是静默清空。
            // 校验通过后 birthDate 一定非空且格式正确
            int age = 0;
            DateTime bdDt;
            if (DateTime.TryParseExact(birthDate, "yyyy-MM-dd",
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out bdDt)) {
                var today = DateTime.Today;
                age = today.Year - bdDt.Year;
                if (bdDt.Date > today.AddYears(-age)) age--;
            }

            string regCountryShort = RegCountryShortBox != null ? RegCountryShortBox.Text.Trim() : "";
            string regPhone = RegPhoneBox.Text.Trim();
            string regCSA = RegCSABox != null ? RegCSABox.Text.Trim() : "";
            string regNotes = RegNotesBox.Text.Trim();

            // 2026-05-21 Upsert：身份证号 + 项目 双匹配 → 覆盖现有记录；
            // 否则走原 dup check；其余情况新增。
            int added = 0, updated = 0, skipped = 0;
            foreach (var ev in _regEventList) {
                string eventName = ev.Item1;
                string entryTime = ev.Item2;
                double entrySec = TimeFormatter.Parse(entryTime);

                // ★ Upsert 路径
                if (!string.IsNullOrEmpty(regIdNumber)) {
                    var existing = _swimmers.FirstOrDefault(s =>
                        !string.IsNullOrEmpty(s.IDNumber)
                        && s.IDNumber == regIdNumber
                        && s.EventName == eventName);
                    if (existing != null) {
                        existing.Name             = name;
                        existing.Gender           = gender;
                        existing.Country          = regCountry;
                        existing.CountryShort     = regCountryShort;
                        existing.Phone            = regPhone;
                        existing.CSANumber        = regCSA;
                        existing.BirthDate        = birthDate;
                        if (age > 0)                            existing.Age = age;
                        existing.EntryTime        = entryTime;
                        existing.EntryTimeSeconds = entrySec;
                        existing.Notes            = regNotes;
                        if (!string.IsNullOrEmpty(regGroup))    existing.AgeCategory = regGroup;
                        updated++;
                        continue;
                    }
                }

                var dup = FindDuplicate(name, gender, eventName, bibNumber, regIdNumber, regCountry);
                if (dup != null) { skipped++; continue; }

                var sw = new Swimmer {
                    BibNumber    = bibNumber,
                    Name         = name,
                    Gender       = gender,
                    Country      = regCountry,
                    CountryShort = regCountryShort,
                    IDNumber     = regIdNumber,
                    Phone        = regPhone,
                    CSANumber    = regCSA,
                    EventName    = eventName,
                    EntryTime    = entryTime,
                    EntryTimeSeconds = entrySec,
                    BirthDate    = birthDate,
                    Age          = age,
                    Notes        = regNotes
                };
                // 手动组别优先于 AgeGroupRegistry 自动推断
                if (!string.IsNullOrEmpty(regGroup)) sw.AgeCategory = regGroup;
                _swimmers.Add(sw);
                added++;
            }

            AddLog(Loc.F("Str_Log_RegisterSwimmerFmt",
                name, bibNumber, added, updated, skipped));
            if (added > 0 || updated > 0) {
                string text = string.Format("处理完成！参赛号: {0}，新增 {1} 项", bibNumber, added);
                if (updated > 0) text += string.Format("，更新 {0} 项", updated);
                if (skipped > 0) text += string.Format("，跳过 {0} 项冲突", skipped);
                RegStatusText.Text = text;
                RegStatusText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E"));
            } else if (skipped > 0) {
                RegStatusText.Text = string.Format("全部 {0} 项均与现有记录冲突，未入库", skipped);
                RegStatusText.Foreground = new SolidColorBrush(Colors.Red);
            } else {
                RegStatusText.Text = Loc.T("Str_Msg_NoEventsProcessed");
                RegStatusText.Foreground = new SolidColorBrush(Colors.Gray);
            }

            // 清空表单准备下一位
            RegNameBox.Clear();
            RegIDNumberBox.Clear();
            RegCountryBox.Text = ""; RegCountryBox.SelectedItem = null;
            if (RegCountryShortBox != null) RegCountryShortBox.Clear();
            if (RegGroupCombo != null) RegGroupCombo.SelectedItem = null;
            RegPhoneBox.Clear();
            if (RegCSABox != null) RegCSABox.Clear();
            RegNotesBox.Clear();
            RegBirthDatePicker.SelectedDate = null;
            RegEntryTimeBox.Clear();
            _regEventList.Clear();
            RefreshRegEventList();

            AutoSaveData();
            RefreshOverviewStats();
            RefreshSwimmerFilter();
            Broadcast();
        }

        private void FilterEvent_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized) RefreshSwimmerFilter(); }

        // 2026-06-05 比赛规则 选择: 写入 _competitionRule + 描述提示
        private void CompRuleCombo_Changed(object sender, SelectionChangedEventArgs e) {
            if (CompRuleCombo == null || CompRuleCombo.SelectedIndex < 0) return;
            // 2026-10-10 加第4项"地区级比赛"(省/市/区/校运动会等)——没有统一官方规则文件,
            //   但跟前三项一样预置一套模板(内容来自真实赛事数据 tools\fenzu_parsed.json,
            //   甘肃某地区运动会游泳比赛的实际项目/组别/性别/赛次设置, 含"男女"同组同赛
            //   和纯决赛制), 行为跟其它三项完全一样: 切换时问是否自动导入, 不满足用户
            //   自己在下方五张表改, 改完照常存进这份赛事存档, 不是改模板本身——下次新建
            //   赛事再选这条规则, 还是加载这份出厂预置, 不会记住上次的修改(跟另外三条
            //   规则的既有行为一致)。
            string[] rules = { "国际比赛", "国内大赛", "U系列青少年游泳比赛", "地区级比赛" };
            // 2026-10-10 四条说明文案原来是硬编码中文数组, 英文模式下切规则时说明文字纹丝不动
            //   (只有 Str_EM_RuleUDesc 建过 key 却没接上用)——改成全部走 Loc, 顺手补齐。
            string[] descKeys = { "Str_EM_RuleIntlDesc", "Str_EM_RuleDomesticDesc", "Str_EM_RuleUDesc", "Str_EM_RuleRegionalDesc" };
            int i = CompRuleCombo.SelectedIndex;
            if (i >= 0 && i < rules.Length) {
                _competitionRule = rules[i];
                if (CompRuleDescText != null) CompRuleDescText.Text = Loc.T(descKeys[i]);
                if (_initialized) AddLog(Loc.F("Str_Log_CompetitionRuleSwitchedFmt", _competitionRule));
                // 2026-10-10 用户手动切规则(不是加载存档时程序化设置)才问要不要自动导入
                //   对应的五张表——这是替换性操作, 跟五个"导入XX表"按钮一样先问一句。
                if (_initialized && !_suppressCompRuleAutoLoad) {
                    string ruleLabelForPrompt = (sender as ComboBox) != null
                        ? (((ComboBox)sender).SelectedItem as ComboBoxItem)?.Content?.ToString() ?? _competitionRule
                        : _competitionRule;
                    if (AppMessageBox.Show(Loc.F("Str_Msg_ConfirmAutoLoadCompParamsFmt", ruleLabelForPrompt),
                        Loc.T("Str_MsgTitle_ConfirmAutoLoadCompParams"), MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes) {
                        AutoLoadCompetitionParamsForRule(i);
                    }
                }
            }
        }

        // 2026-10-10 "比赛规则"下拉切换后, 把对应规则(国际FINA/国内CSA/U系列/地区级)在当前
        //   界面语言下的"比赛项目/组别/性别/赛次/组数"五张表从安装包自带的
        //   CompetitionParamsTemplates\ 读进来, 省得用户自己点五次"导入XX表"再挑文件。
        //   五张表各自的解析逻辑照搬对应 Import*CSV_Click 里已经在用的那一套
        //   (表头跳过/去重/CsvEscape 兼容), 只是文件来源从"用户选的路径"换成
        //   "装机自带模板的固定路径"。
        private void AutoLoadCompetitionParamsForRule(int ruleIndex) {
            string[] folders = { "国际比赛(FINA)", "国内大赛(中国泳协)", "U系列青少年游泳比赛", "地区级比赛" };
            string[] suffixZh = { "国际比赛(FINA)_中文", "国内大赛(中国泳协)_中文", "U系列青少年游泳比赛_中文", "地区级比赛_中文" };
            string[] suffixEn = { "International (FINA)_English", "Domestic (CSA)_English", "U-Series Youth Meet_English", "Regional Meet_English" };
            if (ruleIndex < 0 || ruleIndex >= folders.Length) return;
            string folder = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "CompetitionParamsTemplates", folders[ruleIndex]);
            if (!Directory.Exists(folder)) {
                AddLog(Loc.F("Str_Log_CompRuleTemplateFolderMissingFmt", folders[ruleIndex]));
                return;
            }
            string suffix = (Loc.CurrentLanguage == Loc.En) ? suffixEn[ruleIndex] : suffixZh[ruleIndex];

            Func<string, List<string>> readSimpleList = delegate(string path) {
                if (!File.Exists(path)) return null;
                var rows = ReadCsvLines(path);
                var finalList = new List<string>(); var seen = new HashSet<string>();
                for (int r = 0; r < rows.Count; r++) {
                    var c = rows[r]; if (c.Length == 0) continue;
                    string v = (c[0] ?? "").Trim(); if (string.IsNullOrEmpty(v)) continue;
                    if (r == 0) continue;   // 模板第一行固定是表头
                    if (seen.Contains(v)) continue;
                    seen.Add(v); finalList.Add(v);
                }
                return finalList.Count > 0 ? finalList : null;
            };

            int loadedTables = 0;

            var events = readSimpleList(IOPath.Combine(folder, "比赛项目_" + suffix + ".csv"));
            if (events != null) {
                var cleaned = new List<string>();
                foreach (var name in events) cleaned.Add(System.Text.RegularExpressions.Regex.Replace(name, @"\s+", " ").Trim());
                _events = cleaned; RefreshEventsPreview(); loadedTables++;
            }

            string agPath = IOPath.Combine(folder, "组别_" + suffix + ".csv");
            if (File.Exists(agPath)) {
                var rows = ReadCsvLines(agPath);
                var finalList = new List<AgeGroup>(); var seen = new HashSet<string>();
                for (int r = 0; r < rows.Count; r++) {
                    var c = rows[r]; if (c.Length == 0) continue;
                    string name = (c[0] ?? "").Trim(); if (string.IsNullOrEmpty(name)) continue;
                    if (r == 0) continue;
                    if (seen.Contains(name)) continue; seen.Add(name);
                    int minA = 0, maxA = 0;
                    if (c.Length > 1) int.TryParse((c[1] ?? "").Trim(), out minA);
                    if (c.Length > 2) int.TryParse((c[2] ?? "").Trim(), out maxA);
                    finalList.Add(new AgeGroup { Name = name, MinAge = minA, MaxAge = maxA });
                }
                if (finalList.Count > 0) {
                    _ageGroups = finalList; AgeGroupRegistry.Set(_ageGroups);
                    RefreshAgeGroupsPreview(); RecomputeAllAgeCategories();
                    loadedTables++;
                }
            }

            var genders = readSimpleList(IOPath.Combine(folder, "性别_" + suffix + ".csv"));
            if (genders != null) { _genders = genders; RefreshGendersPreview(); loadedTables++; }

            var stages = readSimpleList(IOPath.Combine(folder, "赛次_" + suffix + ".csv"));
            if (stages != null) { _stages = stages; RefreshStagesPreview(); loadedTables++; }

            var heatCounts = readSimpleList(IOPath.Combine(folder, "组数_" + suffix + ".csv"));
            if (heatCounts != null) { _heatCounts = heatCounts; RefreshHeatCountsPreview(); loadedTables++; }

            if (loadedTables > 0) {
                FinishAndSyncPatch(BuildListSetPatch("events", JArray.FromObject(_events), ClientLabel()), "meet");
                FinishAndSyncPatch(BuildListSetPatch("ageGroups", JArray.FromObject(_ageGroups), ClientLabel()), "meet");
                FinishAndSyncPatch(BuildListSetPatch("genders", JArray.FromObject(_genders), ClientLabel()), "meet");
                FinishAndSyncPatch(BuildListSetPatch("stages", JArray.FromObject(_stages), ClientLabel()), "meet");
                FinishAndSyncPatch(BuildListSetPatch("heatCounts", JArray.FromObject(_heatCounts), ClientLabel()), "meet");
                NotifyMetadataChanged();
                AddLog(Loc.F("Str_Log_CompRuleAutoLoadedFmt", folders[ruleIndex], loadedTables));
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 出场编排微调
        // ═══════════════════════════════════════════════════════════════
        private bool _editUpdating = false;
        private DataGrid _editSelectedGrid = null;

        private void EditFilter_Changed(object sender, SelectionChangedEventArgs e) {
            if (!_initialized || _editUpdating) return;
            UpdateEditHeatCombo();
        }

        private void EditHeat_Changed(object sender, SelectionChangedEventArgs e) {
            if (!_initialized || _editUpdating) return;
            // 使用Dispatcher延迟执行，确保SelectedItem已更新
            Dispatcher.BeginInvoke((Action)delegate() {
                RefreshEditPreview();
            }, System.Windows.Threading.DispatcherPriority.Background);
        }

        private void UpdateEditHeatCombo() {
            if (_editUpdating) return;
            if (EditHeatCombo == null || EditGenderCombo == null || EditEventCombo == null || EditStageCombo == null) return;
            _editUpdating = true;
            try {
                string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
                string gender = EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "男";

                // 按当前性别+组别过滤项目列表（排除接力队员个人条目）
                // 2026-06-01 男/女 选择时也包含"混合"性别项目 (接力混合赛 FINA 惯例都对男女开放),
                //   不然组别=全部 + 性别=男 时 项目下拉看不到 4x50米接力, 用户找不到接力项目编排
                string prevEvent = EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
                EditEventCombo.Items.Clear();
                var evSet = new HashSet<string>();
                foreach (var s in _swimmers) {
                    if (string.IsNullOrEmpty(s.EventName)) continue;
                    if (!GenderMatchesIncludingMixed(s.Gender, gender)) continue;
                    if (!MatchesAgeGroup(s, ageGroup)) continue;
                    if (s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                    evSet.Add(s.EventName);
                }
                foreach (string ev in evSet.OrderBy(x => x)) EditEventCombo.Items.Add(ev);
                if (!string.IsNullOrEmpty(prevEvent) && EditEventCombo.Items.Contains(prevEvent))
                    EditEventCombo.SelectedItem = prevEvent;
                else if (EditEventCombo.Items.Count > 0)
                    EditEventCombo.SelectedIndex = 0;

                string eventName = EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
                string stage = EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "预赛";

                int prevHeatIndex = EditHeatCombo.SelectedIndex;
                EditHeatCombo.Items.Clear();
                EditHeatCombo.Items.Add(Loc.T("Str_Common_All"));
                // 从运动员数据获取有人的组号（接力项目只看代表队条目）
                bool isRelayEv = eventName.Contains("接力");
                var heatNumbers = new HashSet<int>();
                foreach (var s in _swimmers) {
                    if (s.EventName != eventName) continue;
                    if (!GenderMatchesIncludingMixed(s.Gender, gender)) continue;   // 2026-06-01 接力混合性别也算
                    if (!MatchesAgeGroup(s, ageGroup)) continue;
                    if (isRelayEv && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                    // 当前赛次匹配
                    if (s.CurrentStage == stage && s.Heat > 0)
                        heatNumbers.Add(s.Heat);
                    // 历史赛次记录
                    var sa = s.GetAssignmentForStage(stage);
                    if (sa != null && sa.Heat > 0)
                        heatNumbers.Add(sa.Heat);
                }
                foreach (int h in heatNumbers.OrderBy(x => x)) {
                    EditHeatCombo.Items.Add(string.Format("第{0}组", h));
                }
                // 恢复之前选中的组别索引
                if (prevHeatIndex >= 0 && prevHeatIndex < EditHeatCombo.Items.Count)
                    EditHeatCombo.SelectedIndex = prevHeatIndex;
                else if (EditHeatCombo.Items.Count > 0)
                    EditHeatCombo.SelectedIndex = 0;
            } finally {
                _editUpdating = false;
            }
            RefreshEditPreview();
        }

        private void RebuildEditEventCombo() {
            // 重建项目下拉框（按组别+性别过滤，保留当前选择）
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            string gender = EditGenderCombo != null && EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "男";
            int prevIndex = EditEventCombo.SelectedIndex;
            EditEventCombo.Items.Clear();
            var evSet = new HashSet<string>();
            foreach (var s in _swimmers) {
                if (string.IsNullOrEmpty(s.EventName) || !SgMatch(s.Gender, gender)) continue;
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                if (s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                evSet.Add(s.EventName);
            }
            foreach (string ev in evSet.OrderBy(x => x)) EditEventCombo.Items.Add(ev);
            if (prevIndex >= 0 && prevIndex < EditEventCombo.Items.Count)
                EditEventCombo.SelectedIndex = prevIndex;
            else if (EditEventCombo.Items.Count > 0)
                EditEventCombo.SelectedIndex = 0;
        }

        // 填充"出场编排微调"里的组别下拉（首项=全部），当组别列表变化时调用
        // 2026-06-24 加 "(无组别)" 项: 当报名数据里存在 AgeCategory 为空的运动员 (= 无组别比赛) 时显示,
        //   让用户专门筛"无组别比赛"做出场编排微调; 没有无组别 swimmer 则不显示该项, 避免空选项
        private void RefreshEditAgeGroupCombo() {
            if (EditAgeGroupCombo == null) return;
            string prev = EditAgeGroupCombo.SelectedItem as string;
            EditAgeGroupCombo.Items.Clear();
            EditAgeGroupCombo.Items.Add(Loc.T("Str_Common_All"));
            bool hasNoGroup = _swimmers.Any(s => !string.IsNullOrEmpty(s.EventName) && string.IsNullOrEmpty(s.AgeCategory));
            if (hasNoGroup) EditAgeGroupCombo.Items.Add("(无组别)");
            foreach (var g in _ageGroups) EditAgeGroupCombo.Items.Add(g.Name);
            if (!string.IsNullOrEmpty(prev) && EditAgeGroupCombo.Items.Contains(prev))
                EditAgeGroupCombo.SelectedItem = prev;
            else EditAgeGroupCombo.SelectedIndex = 0;
        }

        // 其它组别过滤下拉（运动员管理/记录管理/成绩与排名）
        private void FillAgeGroupFilterCombo(ComboBox cb) {
            if (cb == null) return;
            string prev = cb.SelectedItem as string;
            cb.Items.Clear();
            cb.Items.Add(Loc.T("Str_Common_All"));
            // 主列表 _ageGroups + 已报运动员里出现的组别（兼容历史导入数据中存在但未维护到主列表的组别）
            var seen = new HashSet<string>();
            foreach (var g in _ageGroups) {
                if (!string.IsNullOrEmpty(g.Name) && seen.Add(g.Name)) cb.Items.Add(g.Name);
            }
            foreach (var s in _swimmers) {
                string ag = s.AgeCategory;
                if (!string.IsNullOrEmpty(ag) && seen.Add(ag)) cb.Items.Add(ag);
            }
            if (!string.IsNullOrEmpty(prev) && cb.Items.Contains(prev)) cb.SelectedItem = prev;
            else cb.SelectedIndex = 0;
        }

        private void RefreshAllAgeGroupFilterCombos() {
            RefreshEditAgeGroupCombo();
            FillAgeGroupFilterCombo(FilterAgeGroupCombo);
            FillAgeGroupFilterCombo(RecordFilterAgeGroup);
            FillAgeGroupFilterCombo(ResultAgeGroupCombo);
            // 右侧注册面板的组别下拉（只列具体组别，不带"全部"）
            if (RegGroupCombo != null) {
                string prev = RegGroupCombo.SelectedItem as string ?? RegGroupCombo.Text;
                RegGroupCombo.Items.Clear();
                foreach (var g in _ageGroups) RegGroupCombo.Items.Add(g.Name);
                if (!string.IsNullOrEmpty(prev) && RegGroupCombo.Items.Contains(prev))
                    RegGroupCombo.SelectedItem = prev;
            }
        }

        // 比赛参数设置管理（组别/项目/性别/赛次/组数 等）保存后统一调用：
        // 同步刷新本机所有依赖下拉，并通过 Broadcast 把新配置推送给所有网页/远程端
        private void NotifyMetadataChanged() {
            // 2026-09-03 先刷静态表, 再刷下拉 —— 弹窗(项目成绩/批量公布…)和别的 exe
            //   都只能通过这几张静态表拿到最新配置, 漏了它们就是"设置改了、弹窗没跟着变"。
            try { GenderRegistry.Set(_genders); } catch { }
            try { StageRegistry.Set(_stages); } catch { }
            try { AgeGroupRegistry.Set(_ageGroups); } catch { }
            try { HeatCountRegistry.Set(_heatCounts); } catch { }
            // 本机各 WPF 下拉
            try { RefreshEventComboBoxes(); } catch { }
            try { RefreshAllAgeGroupFilterCombos(); } catch { }
            try { RefillGenderCombos(); } catch { }
            try { RefillStageCombos(); } catch { }
            // 2026-09-03 注册终端是另一个 exe, 收不到上面这些 —— 单独把配置表推给它
            try { PushMetaListsToRegisterTerminals(); } catch { }
            // 推送到所有网页/远程端
            try { Broadcast(); } catch { }
        }

        /// <summary>
        /// 2026-09-03 把【比赛参数设置管理】里的五张表推给注册终端(独立 exe)。
        ///
        /// 它原来的性别/组别下拉是 XAML 里写死的 男/女/混合/男女 —— 源码里那条注释
        /// 自己也写着"本程序没有配置推送通道，暂时写死；治本要加 genderList 下发"。
        /// 现在补上这条通道: 终端一上线(REGISTER_TERMINAL_IDENTITY)推一次, 参数改了再推一次。
        /// </summary>
        private void PushMetaListsToRegisterTerminals() {
            if (_registerSockets == null || _registerSockets.Count == 0) return;
            string json = BuildMetaListsJson();
            foreach (var s in _registerSockets.ToList()) {
                try { if (s != null && s.IsAvailable) s.Send(json); } catch { }
            }
        }

        private string BuildMetaListsJson() {
            var d = new JObject();
            d["genders"] = new JArray(_genders ?? new List<string>());
            d["stages"] = new JArray(_stages ?? new List<string>());
            d["heatCounts"] = new JArray(_heatCounts ?? new List<string>());
            var ags = new JArray();
            if (_ageGroups != null) foreach (var g in _ageGroups) if (g != null && !string.IsNullOrEmpty(g.Name)) ags.Add(g.Name);
            d["ageGroups"] = ags;
            d["events"] = new JArray(_events ?? new List<string>());
            var env = new JObject();
            env["type"] = "META_LISTS";
            env["data"] = d;
            return env.ToString(Formatting.None);
        }

        // 2026-10-05 现场反馈: 性别下拉(筛选/编辑/成绩/报名/纪录)English模式下还是"男/女/混合"——
        //   Content 原来直接存中文哨兵值(既当比较值又当展示文字)。改成 Tag=中文哨兵(比较用),
        //   Content=Loc.GenderDisplay()展示翻译。对应全部 .Content.ToString() 读取点改 .Tag。
        private void RefillGenderCombos() {
            ComboBox[] genderCombos = new ComboBox[] { FilterGenderCombo, EditGenderCombo, ResultGenderCombo, RegGenderCombo, RecordFilterGender };
            foreach (var cb in genderCombos) {
                if (cb == null) continue;
                string prev = "";
                var sel = cb.SelectedItem as ComboBoxItem;
                if (sel != null && sel.Tag != null) prev = sel.Tag.ToString();
                else if (cb.SelectedItem is string) prev = (string)cb.SelectedItem;
                bool hasAll = false;
                foreach (var it in cb.Items) {
                    var ci = it as ComboBoxItem;
                    if (ci != null && ci.Tag != null && ci.Tag.ToString() == "全部") { hasAll = true; break; }
                }
                cb.Items.Clear();
                if (hasAll) cb.Items.Add(new ComboBoxItem { Tag = "全部", Content = Loc.T("Str_Common_All") });
                foreach (var g in _genders) cb.Items.Add(new ComboBoxItem { Tag = g, Content = Loc.GenderDisplay(g) });
                int restored = -1;
                for (int i = 0; i < cb.Items.Count; i++) {
                    var ci = cb.Items[i] as ComboBoxItem;
                    if (ci != null && ci.Tag != null && ci.Tag.ToString() == prev) { restored = i; break; }
                }
                cb.SelectedIndex = restored >= 0 ? restored : 0;
            }
        }

        private void RefillStageCombos() {
            ComboBox[] stageCombos = new ComboBox[] { EditStageCombo, ResultStageCombo };
            foreach (var cb in stageCombos) {
                if (cb == null) continue;
                string prev = "";
                var sel = cb.SelectedItem as ComboBoxItem;
                if (sel != null && sel.Content != null) prev = sel.Content.ToString();
                cb.Items.Clear();
                foreach (var s in _stages) cb.Items.Add(new ComboBoxItem { Content = s });
                int restored = -1;
                for (int i = 0; i < cb.Items.Count; i++) {
                    var ci = cb.Items[i] as ComboBoxItem;
                    if (ci != null && ci.Content != null && ci.Content.ToString() == prev) { restored = i; break; }
                }
                cb.SelectedIndex = restored >= 0 ? restored : 0;
            }
        }

        private void RefreshEditPreview_Click(object sender, RoutedEventArgs e) {
            // 刷新按钮：重建项目列表（可能有新导入的项目），然后刷新组别和数据
            _editUpdating = true;
            try {
                RebuildEditEventCombo();
            } finally {
                _editUpdating = false;
            }
            UpdateEditHeatCombo();
        }

        private string GetPreviousStage(string stage) {
            switch (stage) {
                case "半决赛": return "预赛";
                case "决赛": return "半决赛";
                default: return "";
            }
        }

        private void RefreshEditPreview() {
            if (EditPreviewGrid == null) return;
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            string gender = EditGenderCombo != null && EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
            string eventName = EditEventCombo != null && EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
            string stage = EditStageCombo != null && EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";

            string heatStr = EditHeatCombo != null && EditHeatCombo.SelectedItem != null ? EditHeatCombo.SelectedItem.ToString() : "";
            bool showAll = (heatStr == Loc.T("Str_Common_All"));
            int heat = 0;
            if (!showAll) {
                var m = System.Text.RegularExpressions.Regex.Match(heatStr, @"\d+");
                if (m.Success) heat = int.Parse(m.Value);
            }

            string prevStage = GetPreviousStage(stage);
            if (EditSeedTimeColumn != null) {
                EditSeedTimeColumn.Header = stage == "预赛" ? Loc.T("Str_EM_LT_SeedEntry") : string.Format(Loc.T("Str_EM_LT_SeedSuffixFmt"), Loc.StageDisplay(prevStage));
            }

            // 查找该赛次的运动员（接力项目只显示代表队条目，不显示个人队员）
            bool isRelay = eventName.Contains("接力");
            var matchedSwimmers = new List<Tuple<Swimmer, int, int>>();
            foreach (var s in _swimmers) {
                if (s.EventName != eventName) continue;
                if (!GenderMatchesIncludingMixed(s.Gender, gender)) continue;   // 2026-06-01 男/女 也包含混合
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                // 接力项目：跳过个人队员条目（Notes以"接力队员"开头），只保留代表队条目
                if (isRelay && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                // 2026-10-08 用户要求全系统排查同类问题后发现: 这里 sa==null 时退回
                // 顶层 CurrentStage/Heat 瞎猜, 跟最初那个"张掖市幻影三道"是同一个坑——
                // 同一项目"男"/"男女"两个并列子项目的运动员都在内存里时, 顶层字段
                // 可能是旧赛次残留。这个列表是按下标 swap/编辑用的, 要是混进不该在
                // 这组的人, 轻则预览显示多了个幻影, 重则按下标改道次改错对象。
                // 改成只认 StageAssignment, 没有就不算这组的。
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat > 0) {
                    if (showAll || sa.Heat == heat)
                        matchedSwimmers.Add(Tuple.Create(s, sa.Heat, sa.Lane));
                }
            }
            matchedSwimmers.Sort((a, b) => {
                int c = a.Item2.CompareTo(b.Item2);
                return c != 0 ? c : a.Item3.CompareTo(b.Item3);
            });

            if (showAll)
                AddLog(Loc.F("Str_Log_AssignPreviewAllFmt", Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage), matchedSwimmers.Count));
            else
                AddLog(Loc.F("Str_Log_AssignPreviewHeatFmt", Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage), heat, matchedSwimmers.Count));

            if (showAll) {
                // ═══ 全部模式：按组分隔显示，每组一个标题+DataGrid ═══
                EditPreviewGrid.Visibility = System.Windows.Visibility.Collapsed;
                EditAllGroupsScroll.Visibility = System.Windows.Visibility.Visible;
                EditAllGroupsPanel.Children.Clear();

                // 2026-06-01 组别=全部 时按 (AgeCategory, Heat) 分组, 否则不同组别的"第1组"会被合并到一张表
                //   ageGroup 选了具体值时仍按单一 Heat 分组 (原行为)
                bool splitByAge = (string.IsNullOrEmpty(ageGroup) || ageGroup == Loc.T("Str_Common_All") || ageGroup == "不限");
                // 按 CompetitionPackage.AgeGroups 的顺序排; 不在列表中的组别按字符串排到最后
                var ageOrder = new Dictionary<string, int>();
                for (int i = 0; i < _ageGroups.Count; i++) ageOrder[_ageGroups[i].Name] = i;
                var groupsKeyed = matchedSwimmers
                    .GroupBy(t => splitByAge ? ((t.Item1.AgeCategory ?? "") + "|" + t.Item2.ToString("D3")) : ("|" + t.Item2.ToString("D3")))
                    .OrderBy(g => {
                        var first = g.First();
                        string ag = first.Item1.AgeCategory ?? "";
                        int agi; if (!ageOrder.TryGetValue(ag, out agi)) agi = 999;
                        return agi * 10000 + first.Item2;
                    });
                string seedColHeader = stage == "预赛" ? Loc.T("Str_EM_LT_SeedEntry") : string.Format(Loc.T("Str_EM_LT_SeedSuffixFmt"), Loc.StageDisplay(prevStage));

                foreach (var grp in groupsKeyed) {
                    var first = grp.First();
                    string ageLabel = first.Item1.AgeCategory ?? "";
                    string headerText = splitByAge && !string.IsNullOrEmpty(ageLabel)
                        ? string.Format(Loc.T("Str_EM_LT_GroupHeaderWithAge"), ageLabel, first.Item2, grp.Count())
                        : string.Format(Loc.T("Str_EM_LT_GroupHeader"), first.Item2, grp.Count());
                    // 组标题
                    var header = new TextBlock {
                        Text = headerText,
                        FontWeight = FontWeights.Bold,
                        FontSize = 15,
                        Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E40AF")),
                        Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#DBEAFE")),
                        Padding = new Thickness(10, 5, 10, 5),
                        Margin = new Thickness(0, 8, 0, 4)
                    };
                    EditAllGroupsPanel.Children.Add(header);

                    // 组内DataGrid
                    var grid = new DataGrid {
                        AutoGenerateColumns = false,
                        CanUserAddRows = false,
                        IsReadOnly = true,
                        SelectionMode = DataGridSelectionMode.Single,
                        HeadersVisibility = DataGridHeadersVisibility.Column,
                        AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                        MinHeight = 30,
                        BorderThickness = new Thickness(1),
                        BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E2E8F0"))
                    };
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColLane"), Binding = new System.Windows.Data.Binding("Lane"), Width = new DataGridLength(40) });
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColBib"), Binding = new System.Windows.Data.Binding("BibNumber"), Width = new DataGridLength(60) });
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColName"), Binding = new System.Windows.Data.Binding("Name"), Width = new DataGridLength(80) });
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_ColGender"), Binding = new System.Windows.Data.Binding("Gender"), Width = new DataGridLength(40) });
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColCountry"), Binding = new System.Windows.Data.Binding("Country"), Width = new DataGridLength(80) });
                    grid.Columns.Add(new DataGridTextColumn { Header = seedColHeader, Binding = new System.Windows.Data.Binding("SeedTime"), Width = new DataGridLength(80) });
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColAgeGroup"), Binding = new System.Windows.Data.Binding("AgeCategory"), Width = new DataGridLength(60) });
                    grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColStatus"), Binding = new System.Windows.Data.Binding("Status"), Width = new DataGridLength(50) });

                    var grpData = grp.OrderBy(t => t.Item3).Select(t => {
                        var s = t.Item1;
                        string seedTime = "";
                        if (stage == "预赛") {
                            var sa2 = s.GetAssignmentForStage(stage);
                            seedTime = sa2 != null && !string.IsNullOrEmpty(sa2.EntryTime) ? sa2.EntryTime : (s.EntryTime ?? "");
                        } else {
                            var prevResult = s.GetResultForStage(prevStage);
                            seedTime = prevResult != null && prevResult.FinalTime > 0 ? TimeFormatter.Format(prevResult.FinalTime) : "";
                        }
                        return new {
                            Lane = t.Item3,
                            BibNumber = s.BibNumber ?? "",
                            Name = s.Name ?? "",
                            Gender = s.Gender ?? "",
                            Country = s.Country ?? "",
                            SeedTime = seedTime,
                            AgeCategory = s.AgeCategory ?? "",
                            Status = s.Status ?? ""
                        };
                    }).ToList();
                    grid.SelectionChanged += delegate { _editSelectedGrid = grid; };
                    grid.ItemsSource = grpData;
                    EditAllGroupsPanel.Children.Add(grid);
                }

                if (matchedSwimmers.Count == 0) {
                    EditAllGroupsPanel.Children.Add(new TextBlock {
                        Text = Loc.T("Str_EM_LT_NoGroupData"),
                        Foreground = new SolidColorBrush(Colors.Gray),
                        Margin = new Thickness(10),
                        FontSize = 14
                    });
                }
            } else {
                // ═══ 单组模式：同样用蓝底标题+DataGrid风格 ═══
                EditPreviewGrid.Visibility = System.Windows.Visibility.Collapsed;
                EditAllGroupsScroll.Visibility = System.Windows.Visibility.Visible;
                EditAllGroupsPanel.Children.Clear();

                string seedColHeader = stage == "预赛" ? Loc.T("Str_EM_LT_SeedEntry") : string.Format(Loc.T("Str_EM_LT_SeedSuffixFmt"), Loc.StageDisplay(prevStage));

                // 组标题
                var header = new TextBlock {
                    Text = string.Format(Loc.T("Str_EM_LT_GroupHeader"), heat, matchedSwimmers.Count),
                    FontWeight = FontWeights.Bold,
                    FontSize = 15,
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E40AF")),
                    Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#DBEAFE")),
                    Padding = new Thickness(10, 5, 10, 5),
                    Margin = new Thickness(0, 8, 0, 4)
                };
                EditAllGroupsPanel.Children.Add(header);

                var grid = new DataGrid {
                    AutoGenerateColumns = false,
                    CanUserAddRows = false,
                    IsReadOnly = true,
                    SelectionMode = DataGridSelectionMode.Single,
                    HeadersVisibility = DataGridHeadersVisibility.Column,
                    AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                    MinHeight = 30,
                    BorderThickness = new Thickness(1),
                    BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E2E8F0"))
                };
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColLane"), Binding = new System.Windows.Data.Binding("Lane"), Width = new DataGridLength(40) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColBib"), Binding = new System.Windows.Data.Binding("BibNumber"), Width = new DataGridLength(60) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColName"), Binding = new System.Windows.Data.Binding("Name"), Width = new DataGridLength(80) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_ColGender"), Binding = new System.Windows.Data.Binding("Gender"), Width = new DataGridLength(40) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColCountry"), Binding = new System.Windows.Data.Binding("Country"), Width = new DataGridLength(80) });
                grid.Columns.Add(new DataGridTextColumn { Header = seedColHeader, Binding = new System.Windows.Data.Binding("SeedTime"), Width = new DataGridLength(80) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColAgeGroup"), Binding = new System.Windows.Data.Binding("AgeCategory"), Width = new DataGridLength(60) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColStatus"), Binding = new System.Windows.Data.Binding("Status"), Width = new DataGridLength(50) });

                // 选中行跟踪（用于上移/下移操作）
                grid.SelectionChanged += delegate { _editSelectedGrid = grid; };

                var displayData = matchedSwimmers.Select(t => {
                    var s = t.Item1;
                    string seedTime = "";
                    if (stage == "预赛") {
                        var sa = s.GetAssignmentForStage(stage);
                        seedTime = sa != null && !string.IsNullOrEmpty(sa.EntryTime) ? sa.EntryTime : (s.EntryTime ?? "");
                    } else {
                        var prevResult = s.GetResultForStage(prevStage);
                        seedTime = prevResult != null && prevResult.FinalTime > 0 ? TimeFormatter.Format(prevResult.FinalTime) : "";
                    }
                    return new {
                        Lane = t.Item3,
                        BibNumber = s.BibNumber ?? "",
                        Name = s.Name ?? "",
                        Gender = s.Gender ?? "",
                        Country = s.Country ?? "",
                        SeedTime = seedTime,
                        AgeCategory = s.AgeCategory ?? "",
                        Status = s.Status ?? ""
                    };
                }).ToList();
                grid.ItemsSource = displayData;
                EditAllGroupsPanel.Children.Add(grid);

                if (matchedSwimmers.Count == 0) {
                    EditAllGroupsPanel.Children.Add(new TextBlock {
                        Text = Loc.T("Str_EM_LT_NoGroupData"),
                        Foreground = new SolidColorBrush(Colors.Gray),
                        Margin = new Thickness(10),
                        FontSize = 14
                    });
                }
            }
        }

        private DataGrid GetActiveEditGrid() {
            // 优先使用动态生成的grid（全部模式和单组模式都用它）
            if (_editSelectedGrid != null && _editSelectedGrid.SelectedIndex >= 0)
                return _editSelectedGrid;
            return EditPreviewGrid;
        }

        // 2026-09-21 用户明确要求: 正在比赛"进行中"、"已确认"的组不能再微调——出场编排
        //   微调这几个按钮(上移/下移/交换泳道/增加到本组/移出本组/保存修改)原来一个都不
        //   挡, 点了就直接改内存, 现在统一在动手之前查一次当前选中的具体组次状态。
        //   "全部组"总览视图(没定位到具体组次)不挡——真正落到某一组时才判。
        private bool CheckEditHeatNotLocked() {
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            if (ageGroup == Loc.T("Str_Common_All") || ageGroup == "(无组别)") ageGroup = "";
            string gender = EditGenderCombo != null && EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
            string eventName = EditEventCombo != null && EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
            string stage = EditStageCombo != null && EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";
            string heatStr = EditHeatCombo != null && EditHeatCombo.SelectedItem != null ? EditHeatCombo.SelectedItem.ToString() : "";
            if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(heatStr) || heatStr == Loc.T("Str_Common_All")) return true;
            var m = System.Text.RegularExpressions.Regex.Match(heatStr, @"\d+");
            int heat;
            if (!m.Success || !int.TryParse(m.Value, out heat) || heat <= 0) return true;
            string hs = HeatStatus(ageGroup, gender, eventName, stage, heat);
            if (hs == "running" || hs == "confirmed") {
                AppMessageBox.Show(Loc.F("Str_Msg_CannotFineTuneFmt",
                    eventName, heat, hs == "running" ? Loc.T("Str_Frag_HeatRunning") : Loc.T("Str_Frag_HeatConfirmed")),
                    Loc.T("Str_MsgTitle_CannotFineTune"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return false;
            }
            return true;
        }

        private void EditMoveUp_Click(object sender, RoutedEventArgs e) {
            if (!CheckEditHeatNotLocked()) return;
            var grid = GetActiveEditGrid();
            int idx = grid.SelectedIndex;
            if (idx <= 0) return;
            SwapLanes(idx, idx - 1);
        }

        private void EditMoveDown_Click(object sender, RoutedEventArgs e) {
            if (!CheckEditHeatNotLocked()) return;
            var grid = GetActiveEditGrid();
            int idx = grid.SelectedIndex;
            if (idx < 0 || idx >= grid.Items.Count - 1) return;
            SwapLanes(idx, idx + 1);
        }

        private void EditSwapLane_Click(object sender, RoutedEventArgs e) {
            if (!CheckEditHeatNotLocked()) return;
            // 2026-07-09 先补齐旧数据里的空 BibNumber (= 2026-07-03 之前的临时加人可能空 bib),
            //   避免下面用 BibNumber 定位 sw1 时 FirstOrDefault 撞第 1 个空 bib.
            EnsureAllSwimmerBibs();
            var grid = GetActiveEditGrid();
            var selected = grid.SelectedItem;
            if (selected == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectSwimmerToSwap")); return; }
            string bib = selected.GetType().GetProperty("BibNumber").GetValue(selected, null).ToString();
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            string gender = EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
            string eventName = EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
            string stage = EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";
            bool isRelay = eventName.Contains("接力");

            var sw1 = _swimmers.FirstOrDefault(s => s.BibNumber == bib);
            if (sw1 == null) return;
            var sa1 = sw1.GetAssignmentForStage(stage);
            int heat1 = sa1 != null ? sa1.Heat : sw1.Heat;
            int lane1 = sa1 != null ? sa1.Lane : sw1.Lane;

            // 候选目标 = 同项目/同赛次的其它运动员（可交换） + 空道（可移动），按组别过滤
            // 使用 Tuple<Swimmer, int, int>：Swimmer==null 表示空道；Heat, Lane 为目标组/道
            var candidates = new List<Tuple<Swimmer, int, int>>();
            var occupiedHeatLane = new HashSet<string>(); // "heat|lane" 占用记录（用于计算空道）
            var heatSet = new HashSet<int>();             // 该项目该赛次出现过的组号

            foreach (var s in _swimmers) {
                if (!SgMatch(s.Gender, gender) || s.EventName != eventName) continue;
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                if (isRelay && s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                int h = 0, ln = 0;
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat > 0) { h = sa.Heat; ln = sa.Lane; }
                else if (s.CurrentStage == stage && s.Heat > 0) { h = s.Heat; ln = s.Lane; }
                if (h <= 0) continue;
                heatSet.Add(h);
                occupiedHeatLane.Add(h + "|" + ln);
                if (s.BibNumber == bib) continue;
                candidates.Add(Tuple.Create(s, h, ln));
            }

            // 补充空道候选：泳池所有泳道 × 所有出现过的组，剔除已占用
            var poolLanes = (_poolConfig != null && _poolConfig.LaneNumbers != null)
                ? _poolConfig.LaneNumbers.ToList() : new List<int>();
            foreach (int h in heatSet) {
                foreach (int ln in poolLanes) {
                    if (occupiedHeatLane.Contains(h + "|" + ln)) continue;
                    candidates.Add(Tuple.Create<Swimmer, int, int>(null, h, ln));
                }
            }

            candidates.Sort((a, b) => { int c = a.Item2.CompareTo(b.Item2); return c != 0 ? c : a.Item3.CompareTo(b.Item3); });

            if (candidates.Count == 0) { AppMessageBox.Show(Loc.T("Str_Msg_NoSwapCandidates")); return; }

            var dlg = new Window {
                Title = Loc.F("Str_Win_SwapLane_TitleFmt", sw1.Name, heat1, lane1),
                Width = 500, Height = 500, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock { Text = string.Format("当前: {0} — 第{1}组 第{2}道", sw1.Name, heat1, lane1), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 8) });
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_SwapLane_Hint"), Margin = new Thickness(0, 0, 0, 4), TextWrapping = TextWrapping.Wrap });

            var listBox = new ListBox { Height = 240, FontSize = 13 };
            foreach (var c in candidates) {
                string label;
                if (c.Item1 == null)
                    label = string.Format("第{0}组 第{1}道 — [空道]", c.Item2, c.Item3);
                else
                    label = string.Format("第{0}组 第{1}道 — {2}（{3}）", c.Item2, c.Item3, c.Item1.Name, c.Item1.Country);
                listBox.Items.Add(label);
            }
            sp.Children.Add(listBox);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmSwap"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnClose = new Button { Content = Loc.T("Str_Btn_Close"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnClose.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnClose);
            sp.Children.Add(btnPanel);
            dlg.Content = sp;

            if (dlg.ShowDialog() == true && listBox.SelectedIndex >= 0 && listBox.SelectedIndex < candidates.Count) {
                var target = candidates[listBox.SelectedIndex];
                var sw2 = target.Item1;

                // 2026-09-12 正在比的那一组不许动 —— 源、目标两头都要看
                if (BlockIfHeatLocked(ageGroup, gender, eventName, stage, heat1, Loc.T("Str_Action_SwapLane"))) return;
                if (BlockIfHeatLocked(ageGroup, gender, eventName, stage, target.Item2, Loc.T("Str_Action_SwapTarget"))) return;

                if (sw2 == null) {
                    // 目标是空道：直接把 sw1 移到目标组/道
                    int newHeat = target.Item2, newLane = target.Item3;
                    if (sa1 != null) { sa1.Heat = newHeat; sa1.Lane = newLane; }
                    else {
                        sw1.SetStageAssignment(stage, newHeat, newLane, sw1.EntryTimeSeconds, sw1.EntryTime);
                    }
                    if (sw1.CurrentStage == stage) { sw1.Heat = newHeat; sw1.Lane = newLane; }
                    SaveAndPushAssign(ageGroup, gender, eventName, stage);   // 2026-09-12 走补丁, 不推整包
                    RefreshEditPreview();
                    AddLog(Loc.F("Str_Log_MovedToEmptyLaneFmt", sw1.Name, heat1, lane1, newHeat, newLane));
                } else {
                    var sa2 = sw2.GetAssignmentForStage(stage);
                    // 2026-06-03 修复: 旧逻辑要求 sa1+sa2 同时非空 才换 assignment;
                    //   sw1.CurrentStage 和 sw2.CurrentStage 都 == stage 才换 live 字段.
                    //   导致 一端 sa==null 或 CurrentStage 不一致 时 全分支 skip — 用户看就是 "确认了没反应".
                    //   现在改成: 各自独立判断, 用对方的 (sa优先, sw兜底) 值作为目标.
                    int h1 = sa1 != null ? sa1.Heat : sw1.Heat;
                    int l1 = sa1 != null ? sa1.Lane : sw1.Lane;
                    int h2 = sa2 != null ? sa2.Heat : sw2.Heat;
                    int l2 = sa2 != null ? sa2.Lane : sw2.Lane;
                    // 任一侧 没 assignment 给它现场补一个, 保证 这个 stage 下两人都有 sa 记录可被后续读到
                    if (sa1 != null) { sa1.Heat = h2; sa1.Lane = l2; }
                    else sw1.SetStageAssignment(stage, h2, l2, sw1.EntryTimeSeconds, sw1.EntryTime);
                    if (sa2 != null) { sa2.Heat = h1; sa2.Lane = l1; }
                    else sw2.SetStageAssignment(stage, h1, l1, sw2.EntryTimeSeconds, sw2.EntryTime);
                    if (sw1.CurrentStage == stage) { sw1.Heat = h2; sw1.Lane = l2; }
                    if (sw2.CurrentStage == stage) { sw2.Heat = h1; sw2.Lane = l1; }
                    SaveAndPushAssign(ageGroup, gender, eventName, stage);   // 2026-09-12 走补丁, 不推整包
                    RefreshEditPreview();
                    AddLog(Loc.F("Str_Log_LaneSwappedFmt", sw1.Name, h2, l2, sw2.Name, h1, l1));
                }
            }
        }

        private void EditAddToHeat_Click(object sender, RoutedEventArgs e) {
            if (!CheckEditHeatNotLocked()) return;
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            string gender = EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
            string eventName = EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
            string stage = EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";
            string heatStr = EditHeatCombo.SelectedItem != null ? EditHeatCombo.SelectedItem.ToString() : "";
            bool isRelay = eventName.Contains("接力");

            if (heatStr == Loc.T("Str_Common_All") || string.IsNullOrEmpty(heatStr)) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectSpecificHeatNotAll"), Loc.T("Str_MsgTitle_Info")); return;
            }
            int heat = 0;
            var m = System.Text.RegularExpressions.Regex.Match(heatStr, @"\d+");
            if (m.Success) heat = int.Parse(m.Value);
            if (heat <= 0) return;
            // 2026-09-12 正在比的那一组不许往里加人
            if (BlockIfHeatLocked(ageGroup, gender, eventName, stage, heat, Loc.T("Str_Action_AddToHeat"))) return;

            // 查找未分组的运动员（同组别同性别同项目同赛次，Heat=0或无StageAssignment）
            var unassigned = new List<Swimmer>();
            foreach (var s in _swimmers) {
                if (!SgMatch(s.Gender, gender) || s.EventName != eventName) continue;
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                if (isRelay && s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                var sa = s.GetAssignmentForStage(stage);
                bool hasAssignment = (sa != null && sa.Heat > 0) || (s.CurrentStage == stage && s.Heat > 0);
                if (!hasAssignment) unassigned.Add(s);
            }

            if (unassigned.Count == 0) { AppMessageBox.Show(Loc.T("Str_Msg_NoUnassignedSwimmers"), Loc.T("Str_MsgTitle_Info")); return; }

            var dlg = new Window {
                Title = Loc.F("Str_Win_AddToHeat_TitleFmt", heat, Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage)),
                Width = 450, Height = 480, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock { Text = string.Format("选择要加入第{0}组的运动员:", heat), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 8) });

            var listBox = new ListBox { Height = 200, FontSize = 13, SelectionMode = SelectionMode.Extended };
            foreach (var s in unassigned) {
                listBox.Items.Add(string.Format("{0}（{1}）{2}", s.Name, s.BibNumber ?? "", !string.IsNullOrEmpty(s.EntryTime) ? " 成绩:" + s.EntryTime : ""));
            }
            sp.Children.Add(listBox);

            // 泳道号输入
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_Label_StartLaneAutoIncrement"), FontSize = 12, Foreground = new SolidColorBrush(Colors.Gray), Margin = new Thickness(0, 8, 0, 2) });
            var tbLane = new TextBox { Text = "0", Width = 60, Padding = new Thickness(4), HorizontalAlignment = HorizontalAlignment.Left };
            sp.Children.Add(tbLane);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmAdd"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnClose = new Button { Content = Loc.T("Str_Btn_Close"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnClose.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnClose);
            sp.Children.Add(btnPanel);
            dlg.Content = sp;

            if (dlg.ShowDialog() == true && listBox.SelectedItems.Count > 0) {
                int startLane = 0;
                int.TryParse(tbLane.Text.Trim(), out startLane);
                int added = 0;
                foreach (var item in listBox.SelectedItems) {
                    int idx = listBox.Items.IndexOf(item);
                    if (idx >= 0 && idx < unassigned.Count) {
                        var sw = unassigned[idx];
                        int lane = startLane + added;
                        sw.SetStageAssignment(stage, heat, lane, sw.EntryTimeSeconds, sw.EntryTime);
                        if (sw.CurrentStage == stage) { sw.Heat = heat; sw.Lane = lane; }
                        added++;
                        AddLog(Loc.F("Str_Log_AddedToHeatLaneFmt", sw.Name, heat, lane));
                    }
                }
                SaveAndPushAssign(ageGroup, gender, eventName, stage);   // 2026-09-12 走补丁, 不推整包
                RefreshEditPreview();
                UpdateEditHeatCombo();
            }
        }

        private void SwapLanes(int idx1, int idx2) {
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            string gender = ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString();
            string eventName = EditEventCombo.SelectedItem.ToString();
            string stage = ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString();
            string heatStr = EditHeatCombo.SelectedItem != null ? EditHeatCombo.SelectedItem.ToString() : "";
            bool showAll = (heatStr == Loc.T("Str_Common_All"));
            int heat = 0;
            if (!showAll) {
                var m = System.Text.RegularExpressions.Regex.Match(heatStr, @"\d+");
                if (m.Success) heat = int.Parse(m.Value);
            }

            // 查找运动员列表（同RefreshEditPreview逻辑，接力项目只看代表队；按组别过滤）
            bool isRelaySwap = eventName.Contains("接力");
            var matchedSwimmers = new List<Tuple<Swimmer, int, int>>();
            foreach (var s in _swimmers) {
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                if (!SgMatch(s.Gender, gender) || s.EventName != eventName) continue;
                if (isRelaySwap && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队员")) continue;
                // 2026-10-08 用户要求全系统排查同类问题后发现: 这里 sa==null 时退回
                // 顶层 CurrentStage/Heat 瞎猜, 跟最初那个"张掖市幻影三道"是同一个坑——
                // 同一项目"男"/"男女"两个并列子项目的运动员都在内存里时, 顶层字段
                // 可能是旧赛次残留。这个列表是按下标 swap/编辑用的, 要是混进不该在
                // 这组的人, 轻则预览显示多了个幻影, 重则按下标改道次改错对象。
                // 改成只认 StageAssignment, 没有就不算这组的。
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat > 0) {
                    if (showAll || sa.Heat == heat)
                        matchedSwimmers.Add(Tuple.Create(s, sa.Heat, sa.Lane));
                }
            }
            matchedSwimmers.Sort((a, b) => {
                int c = a.Item2.CompareTo(b.Item2);
                return c != 0 ? c : a.Item3.CompareTo(b.Item3);
            });

            if (idx1 >= 0 && idx1 < matchedSwimmers.Count && idx2 >= 0 && idx2 < matchedSwimmers.Count) {
                var sw1 = matchedSwimmers[idx1];
                var sw2 = matchedSwimmers[idx2];
                // 只允许同组内交换泳道
                if (sw1.Item2 != sw2.Item2) {
                    AppMessageBox.Show(Loc.T("Str_Msg_SwapSameHeatOnly"), Loc.T("Str_MsgTitle_Info"));
                    return;
                }
                // 2026-09-12 正在比的那一组不许调道次 (别的组照常)
                if (BlockIfHeatLocked(ageGroup, gender, eventName, stage, sw1.Item2, Loc.T("Str_Action_ReorderLane"))) return;
                int lane1 = sw1.Item3, lane2 = sw2.Item3;
                var sa1 = sw1.Item1.GetAssignmentForStage(stage);
                var sa2 = sw2.Item1.GetAssignmentForStage(stage);
                // 2026-06-03 修复: 旧逻辑要求 sa1+sa2 同时非空 才换 assignment, 一端为 null 则跳过.
                //   现在各侧独立处理: 有 sa 改 sa, 没 sa 现场补一条; CurrentStage 独立判断同步 live.
                int swapHeat = sw1.Item2;
                if (sa1 != null) sa1.Lane = lane2;
                else sw1.Item1.SetStageAssignment(stage, swapHeat, lane2, sw1.Item1.EntryTimeSeconds, sw1.Item1.EntryTime);
                if (sa2 != null) sa2.Lane = lane1;
                else sw2.Item1.SetStageAssignment(stage, swapHeat, lane1, sw2.Item1.EntryTimeSeconds, sw2.Item1.EntryTime);
                if (sw1.Item1.CurrentStage == stage) sw1.Item1.Lane = lane2;
                if (sw2.Item1.CurrentStage == stage) sw2.Item1.Lane = lane1;
                SaveAndPushAssign(ageGroup, gender, eventName, stage);   // 2026-09-12 走补丁, 不推整包
                RefreshEditPreview();
            }
        }

        private void EditRemoveFromHeat_Click(object sender, RoutedEventArgs e) {
            if (!CheckEditHeatNotLocked()) return;
            var grid = GetActiveEditGrid();
            var selected = grid.SelectedItem;
            if (selected == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectSwimmerFirst")); return; }
            string bib = selected.GetType().GetProperty("BibNumber").GetValue(selected, null).ToString();
            string stage = EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";
            var sw = _swimmers.FirstOrDefault(s => s.BibNumber == bib);
            if (sw != null) {
                // 2026-09-12 正在比的那一组不许把人抽走 —— 抽走了大屏和计时器就对不上了
                var saRm = sw.GetAssignmentForStage(stage);
                int heatRm = saRm != null ? saRm.Heat : (sw.CurrentStage == stage ? sw.Heat : 0);
                string agRm = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
                string gdRm = EditGenderCombo != null && EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
                string evRm = EditEventCombo != null && EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
                if (BlockIfHeatLocked(agRm, gdRm, evRm, stage, heatRm, Loc.T("Str_Action_RemoveFromHeat"))) return;
                if (AppMessageBox.Show(Loc.F("Str_Msg_RemoveFromHeatConfirmFmt", sw.Name), Loc.T("Str_MsgTitle_Confirm"), MessageBoxButton.YesNo) == MessageBoxResult.Yes) {
                    // 清除StageAssignments中的记录
                    if (sw.StageAssignments.ContainsKey(stage))
                        sw.StageAssignments.Remove(stage);
                    // 如果是当前赛次，也清除当前属性
                    if (sw.CurrentStage == stage) {
                        sw.Heat = 0;
                        sw.Lane = 0;
                    }
                    SaveAndPushAssign(agRm, gdRm, evRm, stage);   // 2026-09-12 走补丁, 不推整包
                    RefreshEditPreview();
                    AddLog(Loc.F("Str_Log_RemovedFromAssignFmt", sw.Name));
                }
            }
        }

        private void EditAddTempSwimmer_Click(object sender, RoutedEventArgs e) {
            // 临时加人：在当前项目/赛次新增个人运动员或接力队，不自动重新编排全部分组；
            // 新增对象默认未分组，需通过"增加到本组"或"交换泳道→空道"手动放入组/道
            string gender = EditGenderCombo != null && EditGenderCombo.SelectedItem != null ? ((ComboBoxItem)EditGenderCombo.SelectedItem).Tag.ToString() : "";
            string eventName = EditEventCombo != null && EditEventCombo.SelectedItem != null ? EditEventCombo.SelectedItem.ToString() : "";
            string stage = EditStageCombo != null && EditStageCombo.SelectedItem != null ? ((ComboBoxItem)EditStageCombo.SelectedItem).Content.ToString() : "";
            // 2026-06-18 加"组别"传递, 修临时加人 AgeCategory 丢失
            string ageGroup = EditAgeGroupCombo != null && EditAgeGroupCombo.SelectedItem != null ? EditAgeGroupCombo.SelectedItem.ToString() : "";
            if (string.IsNullOrEmpty(gender) || string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(stage)) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectFiltersBeforeTempAdd"), Loc.T("Str_MsgTitle_Info")); return;
            }

            bool isRelay = eventName.Contains("接力");
            if (isRelay) AddTempRelayTeam(ageGroup, gender, eventName, stage);
            else AddTempIndividualSwimmer(ageGroup, gender, eventName, stage);
        }

        private void AddTempIndividualSwimmer(string ageGroup, string gender, string eventName, string stage) {
            var dlg = new Window {
                Title = Loc.F("Str_Win_TempAddSwimmer_TitleFmt", Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage)),
                Width = 420, Height = 400, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock {
                Text = string.Format("新增到: {0} {1} {2}（确认后请使用“增加到本组”或“交换泳道”手动放入组/道，不会自动重新分组）", gender, eventName, stage),
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 10), FontSize = 13
            });

            Func<string, TextBox, StackPanel> addRow = delegate(string label, TextBox tb) {
                var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
                row.Children.Add(new TextBlock { Text = label, Width = 80, VerticalAlignment = VerticalAlignment.Center });
                tb.Width = 280; tb.Padding = new Thickness(4);
                row.Children.Add(tb);
                sp.Children.Add(row);
                return row;
            };

            var tbName = new TextBox();
            var tbBib = new TextBox();
            var tbCountry = new TextBox();
            var tbAge = new TextBox();
            var tbEntryTime = new TextBox { ToolTip = Loc.T("Str_Tooltip_EntryTimeFmtShort") };
            addRow("姓名:", tbName);
            addRow("号码:", tbBib);
            addRow("代表队:", tbCountry);
            addRow("年龄:", tbAge);
            addRow("报名成绩:", tbEntryTime);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 14, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmAdd"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#8B5CF6")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            sp.Children.Add(btnPanel);
            dlg.Content = sp;

            if (dlg.ShowDialog() != true) return;

            string name = (tbName.Text ?? "").Trim();
            string bib = (tbBib.Text ?? "").Trim();
            string country = (tbCountry.Text ?? "").Trim();
            string entryTimeStr = (tbEntryTime.Text ?? "").Trim();
            int ageVal = 0; int.TryParse((tbAge.Text ?? "").Trim(), out ageVal);

            if (string.IsNullOrEmpty(name)) { AppMessageBox.Show(Loc.T("Str_Msg_NameRequired")); return; }
            // 2026-07-03 空 bib 自动分配唯一号 (= 修 EditSwapLane_Click 用 BibNumber 查找致
            //   多个空 bib 临时加人 FirstOrDefault 永远匹配第 1 个, 无法交换第 2+ 个泳道)
            if (string.IsNullOrEmpty(bib)) bib = GenerateNextBibNumber(country);
            if (!string.IsNullOrEmpty(bib) && _swimmers.Any(s => s.BibNumber == bib)) {
                AppMessageBox.Show(Loc.F("Str_Msg_BibAlreadyExistsFmt", bib)); return;
            }

            double entrySec = 0;
            if (!string.IsNullOrEmpty(entryTimeStr)) entrySec = TimeFormatter.Parse(entryTimeStr);

            var sw = new Swimmer {
                Name = name, BibNumber = bib, Gender = gender, Country = country, Age = ageVal,
                AgeCategory = ageGroup ?? "",   // 2026-06-18 修临时加人 AgeCategory 丢失
                EventName = eventName, CurrentStage = stage,
                EntryTime = entryTimeStr, EntryTimeSeconds = entrySec,
                Heat = 0, Lane = 0, Notes = "临时加人"
            };
            _swimmers.Add(sw);
            SaveAndPushAssign(ageGroup, gender, eventName, stage);   // 2026-09-12 走补丁, 人随补丁过去
            UpdateEditHeatCombo();
            RefreshEditPreview();
            AddLog(Loc.F("Str_Log_TempAddedSwimmerFmt", name, Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage)));
            AppMessageBox.Show(Loc.F("Str_Msg_TempAddedSwimmerFmt", name), Loc.T("Str_MsgTitle_TempAddDone"));
        }

        private void AddTempRelayTeam(string ageGroup, string gender, string eventName, string stage) {
            // 从项目名解析棒数（如 "4×100米自由泳接力" → 4 棒），解析失败默认 4
            int legCount = 4;
            var mm = System.Text.RegularExpressions.Regex.Match(eventName, @"(\d+)\s*[x×*]");
            if (mm.Success) { int n; if (int.TryParse(mm.Groups[1].Value, out n) && n > 0 && n <= 10) legCount = n; }

            var dlg = new Window {
                Title = Loc.F("Str_Win_TempAddRelay_TitleFmt", Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage)),
                Width = 460, Height = 140 + legCount * 34 + 160,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock {
                Text = string.Format("新增接力队到: {0} {1} {2}（确认后请用“增加到本组”或“交换泳道→空道”手动放入组/道，不会自动重新分组）", gender, eventName, stage),
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 10), FontSize = 13
            });

            Func<string, TextBox, double, StackPanel> addRow = delegate(string label, TextBox tb, double labelWidth) {
                var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
                row.Children.Add(new TextBlock { Text = label, Width = labelWidth, VerticalAlignment = VerticalAlignment.Center });
                tb.Padding = new Thickness(4);
                row.Children.Add(tb);
                sp.Children.Add(row);
                return row;
            };

            var tbTeam = new TextBox { Width = 320 };
            var tbEntryTime = new TextBox { Width = 320, ToolTip = Loc.T("Str_Tooltip_EntryTimeFmtLong") };
            addRow("队名（代表队）:", tbTeam, 110);
            addRow("报名成绩:", tbEntryTime, 110);

            sp.Children.Add(new TextBlock { Text = string.Format("队员（共{0}棒，可留空，后续再补）:", legCount),
                Margin = new Thickness(0, 10, 0, 4), FontSize = 13, FontWeight = FontWeights.Bold });

            var legNameBoxes = new List<TextBox>();
            var legBibBoxes = new List<TextBox>();
            for (int i = 0; i < legCount; i++) {
                var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 0) };
                row.Children.Add(new TextBlock { Text = string.Format("第{0}棒:", i + 1), Width = 55, VerticalAlignment = VerticalAlignment.Center });
                var tbLegName = new TextBox { Width = 180, Padding = new Thickness(4) };
                var tbLegBib = new TextBox { Width = 100, Padding = new Thickness(4), Margin = new Thickness(8, 0, 0, 0), ToolTip = Loc.T("Str_Tooltip_BibOptionalHint") };
                row.Children.Add(new TextBlock { Text = Loc.T("Str_Col_Name"), Margin = new Thickness(0, 0, 4, 0), VerticalAlignment = VerticalAlignment.Center });
                row.Children.Add(tbLegName);
                row.Children.Add(new TextBlock { Text = Loc.T("Str_Col_Bib"), Margin = new Thickness(8, 0, 4, 0), VerticalAlignment = VerticalAlignment.Center });
                row.Children.Add(tbLegBib);
                sp.Children.Add(row);
                legNameBoxes.Add(tbLegName);
                legBibBoxes.Add(tbLegBib);
            }

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 14, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmAdd"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#8B5CF6")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            sp.Children.Add(btnPanel);
            dlg.Content = new ScrollViewer { Content = sp, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };

            if (dlg.ShowDialog() != true) return;

            string teamName = (tbTeam.Text ?? "").Trim();
            string entryTimeStr = (tbEntryTime.Text ?? "").Trim();
            if (string.IsNullOrEmpty(teamName)) { AppMessageBox.Show(Loc.T("Str_Msg_TeamNameRequired")); return; }
            if (_swimmers.Any(s => s.EventName == eventName && s.Country == teamName && s.Notes != null && s.Notes.StartsWith("接力队 棒次:"))) {
                AppMessageBox.Show(Loc.F("Str_Msg_TeamAlreadyInEventFmt", teamName)); return;
            }

            double entrySec = 0;
            if (!string.IsNullOrEmpty(entryTimeStr)) entrySec = TimeFormatter.Parse(entryTimeStr);

            // 构造 RelayTeam
            // 2026-06-18 加 AgeGroup 字段, 修临时加接力队 跨年龄段污染
            var team = new RelayTeam {
                TeamName = teamName, EventName = eventName, Gender = gender,
                AgeGroup = ageGroup ?? "",
                EntryTime = entryTimeStr, EntryTimeSeconds = entrySec
            };
            for (int i = 0; i < legCount; i++) {
                string ln = (legNameBoxes[i].Text ?? "").Trim();
                string lb = (legBibBoxes[i].Text ?? "").Trim();
                team.Legs.Add(new RelayLeg { LegOrder = i + 1, SwimmerName = ln, SwimmerBibNumber = lb, SwimmerIDNumber = "" });
            }
            _relayTeams.Add(team);

            // 代表队条目（统一走分组/成绩流程）
            string legNames = "";
            foreach (var leg in team.Legs) legNames += (legNames.Length > 0 ? "," : "") + (leg.SwimmerName ?? "");
            string teamBib = "R" + (_relayTeams.Count).ToString("D3");
            while (_swimmers.Any(s => s.BibNumber == teamBib)) teamBib = "R" + DateTime.Now.Ticks.ToString().Substring(10);

            _swimmers.Add(new Swimmer {
                BibNumber = teamBib, Name = teamName, Gender = gender, Country = teamName,
                AgeCategory = ageGroup ?? "",   // 2026-06-18 接力代理条目也带 AgeCategory
                EventName = eventName, CurrentStage = stage,
                EntryTime = entryTimeStr, EntryTimeSeconds = entrySec,
                Heat = 0, Lane = 0,
                Notes = string.Format("接力队 棒次:{0}", legNames)
            });

            // 队员子条目（号码为空时自动生成 teamBib-legN）
            foreach (var leg in team.Legs) {
                if (string.IsNullOrEmpty(leg.SwimmerName)) continue;
                string memBib = !string.IsNullOrEmpty(leg.SwimmerBibNumber) ? leg.SwimmerBibNumber : (teamBib + "-" + leg.LegOrder);
                if (_swimmers.Any(s => s.BibNumber == memBib)) continue;
                _swimmers.Add(new Swimmer {
                    BibNumber = memBib, Name = leg.SwimmerName,
                    Gender = gender == "混合" ? "男" : gender, Country = teamName,
                    IDNumber = leg.SwimmerIDNumber ?? "",
                    EventName = eventName,
                    Notes = string.Format("接力队员 {0} 第{1}棒", eventName, leg.LegOrder)
                });
            }

            SaveAndPushAssign(ageGroup, gender, eventName, stage);   // 2026-09-12 走补丁, 队和棒次随补丁过去
            RebuildRelayGroupedView();
            UpdateEditHeatCombo();
            RefreshEditPreview();
            AddLog(Loc.F("Str_Log_TempAddedRelayTeamFmt", teamName, eventName, Loc.GenderDisplay(gender), Loc.StageDisplay(stage)));
            AppMessageBox.Show(Loc.F("Str_Msg_TempAddedRelayFmt", teamName), Loc.T("Str_MsgTitle_TempAddDone"));
        }

        private void EditSaveChanges_Click(object sender, RoutedEventArgs e) {
            if (!CheckEditHeatNotLocked()) return;
            AutoSaveData();
            Broadcast();
            BuildScheduleTree();
            AppMessageBox.Show(Loc.T("Str_Msg_LineupChangesSaved"), Loc.T("Str_MsgTitle_SaveSuccess"));
            AddLog(Loc.T("Str_Log_AssignChangesSaved"));
        }
        private void FilterGender_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized) RefreshSwimmerFilter(); }
        private void FilterAgeGroup_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized) RefreshSwimmerFilter(); }
        private void FilterText_Changed(object sender, TextChangedEventArgs e) { if (_initialized) RefreshSwimmerFilter(); }

        private void FilterReset_Click(object sender, RoutedEventArgs e) {
            if (FilterEventCombo != null && FilterEventCombo.Items.Count > 0) FilterEventCombo.SelectedIndex = 0;
            if (FilterAgeGroupCombo != null && FilterAgeGroupCombo.Items.Count > 0) FilterAgeGroupCombo.SelectedIndex = 0;
            if (FilterGenderCombo != null && FilterGenderCombo.Items.Count > 0) FilterGenderCombo.SelectedIndex = 0;
            if (FilterNameBox != null) FilterNameBox.Text = "";
            if (FilterBibBox != null) FilterBibBox.Text = "";
            RefreshSwimmerFilter();
        }

        private void RefreshSwimmerFilter() {
            if (FilterEventCombo == null || FilterGenderCombo == null || SwimmerGrid == null) return;
            string eventFilter = FilterEventCombo.SelectedItem != null ? ((ComboBoxItem)FilterEventCombo.SelectedItem).Content.ToString() : Loc.T("Str_Common_All");
            // 2026-10-05 FilterGenderCombo 用 Tag 存中文哨兵值(展示走 Loc.GenderDisplay)，
            // 这里跟着读 Tag，下面两处比较也固定用原始"全部"(不随语言变)
            string genderFilter = FilterGenderCombo.SelectedItem != null ? ((ComboBoxItem)FilterGenderCombo.SelectedItem).Tag.ToString() : "全部";
            string ageFilter = FilterAgeGroupCombo != null && FilterAgeGroupCombo.SelectedItem != null ? FilterAgeGroupCombo.SelectedItem.ToString() : Loc.T("Str_Common_All");
            string nameFilter = FilterNameBox != null ? (FilterNameBox.Text ?? "").Trim() : "";
            string bibFilter = FilterBibBox != null ? (FilterBibBox.Text ?? "").Trim() : "";

            // 2026-05-22 翻转过滤逻辑（用户明确要求）：
            //   ★ 接力代表条目（Notes 以"接力队 棒次:"开头，Name=队名）只在「接力队管理」Tab
            //     展示；运动员管理大表里 *隐藏*，因为它不是一个真实运动员，只是日程/分组/计时
            //     占位用的聚合条目。
            //   ★ 接力队员条目（Notes 以"接力队员"开头，Name=队员真名）现在 *显示*，让接力
            //     棒次队员和个人项目运动员一视同仁——有自己的参赛号、姓名、出生日期、身份证号，
            //     项目列显示该接力项目名，新增"棒次"列显示"第N棒"。
            //   旧版正好是反的（隐藏队员、显示代表），导致用户看到的运动员管理里出现 R001-江西
            //   这种诡异条目（姓名等于队名、单位简称是某队员姓名、组别字段塞了非标准值）。
            var visibleSwimmers = _swimmers.Where(s => !(s.Notes != null && s.Notes.StartsWith("接力队 棒次:"))).ToList();

            // 全部筛选条件都为"默认值"时直接展示（仅去掉接力队员条目）
            bool allDefault = eventFilter == Loc.T("Str_Common_All") && genderFilter == "全部"
                           && (ageFilter == Loc.T("Str_Common_All") || string.IsNullOrEmpty(ageFilter))
                           && string.IsNullOrEmpty(nameFilter) && string.IsNullOrEmpty(bibFilter);
            if (allDefault) {
                SwimmerGrid.ItemsSource = visibleSwimmers;
                return;
            }

            var filtered = visibleSwimmers.Where(s => {
                if (eventFilter != Loc.T("Str_Common_All") && s.EventName != eventFilter) return false;
                if (genderFilter != "全部" && s.Gender != genderFilter) return false;
                if (!MatchesAgeGroup(s, ageFilter)) return false;
                if (!string.IsNullOrEmpty(nameFilter) && (s.Name == null || s.Name.IndexOf(nameFilter, StringComparison.OrdinalIgnoreCase) < 0)) return false;
                if (!string.IsNullOrEmpty(bibFilter) && (s.BibNumber == null || s.BibNumber.IndexOf(bibFilter, StringComparison.OrdinalIgnoreCase) < 0)) return false;
                return true;
            }).ToList();

            SwimmerGrid.ItemsSource = filtered;
        }

