        private ScheduleItem _selectedScheduleItem;

        private void AddSchedule_Click(object sender, RoutedEventArgs e) {
            if (AppMessageBox.Show(Loc.T("Str_Msg_ConfirmAddScheduleItem"), Loc.T("Str_MsgTitle_Confirm"), MessageBoxButton.YesNo) != MessageBoxResult.Yes) return;

            // 根据选中行确定插入位置和场号
            int insertIndex = _schedule.Count;
            int sessionNum = _schedule.Count > 0 ? _schedule.Max(s => s.SessionNumber) : 1;
            string date = GetDatePickerText(StartDatePicker);

            // 没选中行时，时间设为当前最后一条的时间+1分钟
            string time = "";
            if (_schedule.Count > 0) {
                var last = _schedule.OrderBy(s => s.Date).ThenBy(s => s.Time).LastOrDefault();
                if (last != null) {
                    if (!string.IsNullOrEmpty(last.Date)) date = last.Date;
                    sessionNum = last.SessionNumber;
                    if (!string.IsNullOrEmpty(last.Time)) {
                        var p = last.Time.Split(':');
                        int hh = 9, mm = 0;
                        if (p.Length >= 1) int.TryParse(p[0], out hh);
                        if (p.Length >= 2) int.TryParse(p[1], out mm);
                        mm++;
                        if (mm >= 60) { mm = 0; hh++; }
                        time = string.Format("{0:D2}:{1:D2}", hh, mm);
                    }
                }
            }

            if (_selectedScheduleItem != null) {
                insertIndex = _schedule.IndexOf(_selectedScheduleItem) + 1;
                sessionNum = _selectedScheduleItem.SessionNumber;
                if (!string.IsNullOrEmpty(_selectedScheduleItem.Date)) date = _selectedScheduleItem.Date;
                // 时间设为选中行时间+1分钟，确保排在后面
                if (!string.IsNullOrEmpty(_selectedScheduleItem.Time)) {
                    var parts = _selectedScheduleItem.Time.Split(':');
                    int h = 9, mi = 0;
                    if (parts.Length >= 1) int.TryParse(parts[0], out h);
                    if (parts.Length >= 2) int.TryParse(parts[1], out mi);
                    mi++;
                    if (mi >= 60) { mi = 0; h++; }
                    time = string.Format("{0:D2}:{1:D2}", h, mi);
                }
            }

            var newItem = new ScheduleItem {
                SessionNumber = sessionNum,
                SessionName = string.Format("第{0}场", sessionNum),
                Date = date,
                Time = time
            };
            _schedule.Insert(insertIndex, newItem);
            BuildScheduleTree();
            FinishAndSyncPatch(BuildListSetPatch("schedule", JArray.FromObject(_schedule), ClientLabel()), "meet");
        }

        private void EditSchedule_Click(object sender, RoutedEventArgs e) {
            // 赛程是整表编辑，锁键为常量 "schedule"
            string holder;
            if (!TryAcquireEditLock("schedule", out holder)) {
                AppMessageBox.Show(
                    Loc.F("Str_Msg_ScheduleBeingEditedFmt", holder),
                    Loc.T("Str_MsgTitle_CannotEdit"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try {
                EditScheduleCore();
            } finally {
                ReleaseEditLock("schedule");
            }
        }

        private void EditScheduleCore() {
            // 复制一份赛程用于编辑（取消时不影响原数据）
            // 2026-05-27 修复: 之前漏复制 AgeGroup, 导致打开"修改赛程"时所有项的组别都显示为空,
            //   "确认修改"后写回 _schedule 会覆盖掉原本的组别 → 所有项变"不限组别".
            var editList = new ObservableCollection<ScheduleItem>();
            foreach (var s in _schedule) {
                editList.Add(new ScheduleItem {
                    SessionNumber = s.SessionNumber, SessionName = s.SessionName,
                    Date = s.Date, Time = s.Time,
                    AgeGroup = s.AgeGroup,
                    Gender = s.Gender, EventName = s.EventName,
                    Stage = s.Stage, HeatCount = s.HeatCount,
                    IsRelay = s.IsRelay
                });
            }

            var dlg = new Window {
                Title = Loc.T("Str_Win_EditSchedule_Title"), Width = 800, Height = 600,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.CanResize
            };

            var mainGrid = new Grid { Margin = new Thickness(16) };
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            // 按场分组显示（可编辑），和主界面风格一致
            var scrollViewer = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
            var editPanel = new StackPanel();
            ScheduleItem _editSelected = null;

            Action rebuildEditPanel = null;
            rebuildEditPanel = delegate {
                editPanel.Children.Clear();
                // 归一化日期和时间（2026-4-21 -> 2026-04-21；9:5 -> 09:05），使不同写法视为同一天
                foreach (var it in editList) {
                    it.Date = NormalizeDate(it.Date);
                    it.Time = NormalizeTime(it.Time);
                }
                // 推断场：按 editList 自然顺序遍历，首次出现的 (日期+时段) 组合分配新场号
                var sMap = new Dictionary<string, int>();
                int sNum = 1;
                foreach (var it in editList) {
                    string per = InferTimePeriod(it.Time);
                    string k = (it.Date ?? "") + "|" + per;
                    if (!sMap.ContainsKey(k)) { sMap[k] = sNum; sNum++; }
                    it.SessionNumber = sMap[k];
                    it.SessionName = string.Format("第{0}场（{1}{2}）", sMap[k], it.Date ?? "", per);
                }
                var grps = editList.GroupBy(s2 => s2.SessionNumber).OrderBy(g2 => g2.Key);
                foreach (var grp in grps) {
                    var hdr = new TextBlock {
                        Text = grp.First().SessionName ?? string.Format("第{0}场", grp.Key),
                        FontWeight = FontWeights.Bold, FontSize = 15,
                        Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1A5FB4")),
                        Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E8F0FE")),
                        Padding = new Thickness(8, 4, 8, 4), Margin = new Thickness(0, 5, 0, 6)
                    };
                    editPanel.Children.Add(hdr);

                    var eg = new DataGrid {
                        AutoGenerateColumns = false, CanUserAddRows = false, IsReadOnly = false,
                        MinHeight = 30, SelectionMode = DataGridSelectionMode.Single,
                        AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC"))
                    };
                    // 2026-09-21 用户要求: 最左边加"顺序号"列(每场从1开始), 跟"赛程管理"
                    //   主表(RebuildScheduleGroupedView)用同一个字段(SeqInSession), 只读。
                    eg.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Sched_ColSeq"), Binding = new System.Windows.Data.Binding("SeqInSession"), Width = new DataGridLength(55), IsReadOnly = true });
                    eg.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Date"), Binding = new System.Windows.Data.Binding("Date"), Width = new DataGridLength(100) });
                    eg.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Sched_ColTime"), Binding = new System.Windows.Data.Binding("Time"), Width = new DataGridLength(70) });
                    // 组别（空串=不限）
                    var agCol = new DataGridComboBoxColumn { Header = Loc.T("Str_Col_Group"), Width = new DataGridLength(80), SelectedItemBinding = new System.Windows.Data.Binding("AgeGroup") };
                    var agItems = new List<string> { "" };
                    foreach (var g in _ageGroups) agItems.Add(g.Name);
                    // 2026-07-09 Bug 修: 补齐 editList 里已出现但 _ageGroups 未列出的组别名,
                    //   否则 ComboBoxColumn 匹配失败 → 组别列显示为空 (即使数据有值).
                    foreach (var it in editList) {
                        string ag = it.AgeGroup ?? "";
                        if (!string.IsNullOrEmpty(ag) && !agItems.Contains(ag)) agItems.Add(ag);
                    }
                    agCol.ItemsSource = agItems; eg.Columns.Add(agCol);
                    var gc = new DataGridComboBoxColumn { Header = Loc.T("Str_Col_Sex"), Width = new DataGridLength(55), SelectedItemBinding = new System.Windows.Data.Binding("Gender") };
                    // 2026-09-03 性别/赛次一律取【比赛参数设置管理】里的表, 不写死 ——
                    //   写死的话, 用户在设置里新加的性别或赛次, 在赛程编辑这张表里根本选不到。
                    gc.ItemsSource = new List<string>(_genders); eg.Columns.Add(gc);
                    var ec = new DataGridComboBoxColumn { Header = Loc.T("Str_Col_Event"), Width = new DataGridLength(160), SelectedItemBinding = new System.Windows.Data.Binding("EventName") };
                    ec.ItemsSource = _events; eg.Columns.Add(ec);
                    var sc = new DataGridComboBoxColumn { Header = Loc.T("Str_Col_Stage"), Width = new DataGridLength(70), SelectedItemBinding = new System.Windows.Data.Binding("Stage") };
                    sc.ItemsSource = new List<string>(_stages); eg.Columns.Add(sc);
                    // 2026-09-03 组数: 参数设置里配了组数表(如 "1组".."8组")就给下拉选,
                    //   没配就仍旧手输 —— 这是"组数"那张表唯一真正用得上的地方。
                    if (_heatCounts != null && _heatCounts.Count > 0) {
                        var hcCol = new DataGridComboBoxColumn {
                            Header = Loc.T("Str_Col_HeatCount"), Width = new DataGridLength(60),
                            SelectedItemBinding = new System.Windows.Data.Binding("HeatCountText")
                        };
                        hcCol.ItemsSource = new List<string>(_heatCounts);
                        eg.Columns.Add(hcCol);
                    } else {
                        eg.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_HeatCount"), Binding = new System.Windows.Data.Binding("HeatCount"), Width = new DataGridLength(50) });
                    }

                    // 保留 editList 自然顺序（不再按时间排序），便于用户自定义比赛顺序
                    int seq = 0;
                    foreach (var it in grp) it.SeqInSession = ++seq;
                    eg.ItemsSource = new ObservableCollection<ScheduleItem>(grp);
                    eg.SelectionChanged += delegate { _editSelected = eg.SelectedItem as ScheduleItem; };
                    editPanel.Children.Add(eg);
                }
                if (editList.Count == 0) {
                    editPanel.Children.Add(new TextBlock { Text = Loc.T("Str_Schedule_NoItemsHint"), Foreground = new SolidColorBrush(Colors.Gray), Margin = new Thickness(10) });
                }
            };
            rebuildEditPanel();
            scrollViewer.Content = editPanel;
            mainGrid.Children.Add(scrollViewer);

            // 按钮栏
            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) };
            btnPanel.SetValue(Grid.RowProperty, 1);

            // 插入赛程项的公共方法
            Action<bool> insertScheduleItem = delegate(bool before) {
                var refItem = _editSelected != null ? _editSelected : (editList.Count > 0 ? editList[editList.Count - 1] : null);
                int insertIdx = _editSelected != null ? editList.IndexOf(_editSelected) : editList.Count;
                if (!before) insertIdx++;
                string newTime = "";
                if (refItem != null && !string.IsNullOrEmpty(refItem.Time)) {
                    var tp = refItem.Time.Split(':'); int hh = 9, mm = 0;
                    if (tp.Length >= 1) int.TryParse(tp[0], out hh);
                    if (tp.Length >= 2) int.TryParse(tp[1], out mm);
                    if (before) { mm--; if (mm < 0) { mm = 59; hh--; } }
                    else { mm++; if (mm >= 60) { mm = 0; hh++; } }
                    if (hh < 0) hh = 0;
                    newTime = string.Format("{0:D2}:{1:D2}", hh, mm);
                }
                editList.Insert(insertIdx, new ScheduleItem {
                    Date = refItem != null ? refItem.Date : GetDatePickerText(StartDatePicker),
                    Time = newTime, SessionNumber = refItem != null ? refItem.SessionNumber : 1
                });
                rebuildEditPanel();
            };

            var btnAddBefore = new Button { Content = Loc.T("Str_Btn_InsertBefore"), Padding = new Thickness(10, 6, 10, 6), Margin = new Thickness(0, 0, 4, 0), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnAddBefore.Click += delegate { insertScheduleItem(true); };

            var btnAddAfter = new Button { Content = Loc.T("Str_Btn_InsertAfter"), Padding = new Thickness(10, 6, 10, 6), Margin = new Thickness(0, 0, 8, 0), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#2563EB")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnAddAfter.Click += delegate { insertScheduleItem(false); };

            var btnDel = new Button { Content = Loc.T("Str_Btn_DeleteSelected"), Padding = new Thickness(12, 6, 12, 6), Margin = new Thickness(0, 0, 8, 0), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnDel.Click += delegate {
                if (_editSelected != null) { editList.Remove(_editSelected); _editSelected = null; rebuildEditPanel(); }
                else AppMessageBox.Show(Loc.T("Str_Msg_SelectRowToDelete"));
            };

            // 上移/下移：在 editList 中交换选中项与相邻项的位置
            Action<int> moveSelected = delegate(int delta) {
                if (_editSelected == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRowToMove")); return; }
                int idx = editList.IndexOf(_editSelected);
                int newIdx = idx + delta;
                if (idx < 0 || newIdx < 0 || newIdx >= editList.Count) return;
                var sel = _editSelected;
                editList.Move(idx, newIdx);
                rebuildEditPanel();
                _editSelected = sel;
            };

            var btnMoveUp = new Button { Content = Loc.T("Str_Btn_MoveUp"), Padding = new Thickness(10, 6, 10, 6), Margin = new Thickness(0, 0, 4, 0), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#0EA5E9")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnMoveUp.Click += delegate { moveSelected(-1); };

            var btnMoveDown = new Button { Content = Loc.T("Str_Btn_MoveDown"), Padding = new Thickness(10, 6, 10, 6), Margin = new Thickness(0, 0, 8, 0), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#0284C7")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnMoveDown.Click += delegate { moveSelected(1); };

            // 将当前 DataGrid 里正在编辑的单元格提交回绑定源，防止未失焦的输入被丢弃
            Action flushPendingEdits = delegate {
                var fe = System.Windows.Input.Keyboard.FocusedElement as FrameworkElement;
                if (fe is TextBox) {
                    var be = fe.GetBindingExpression(TextBox.TextProperty);
                    if (be != null) be.UpdateSource();
                }
                foreach (var child in editPanel.Children) {
                    var g = child as DataGrid;
                    if (g != null) {
                        try { g.CommitEdit(DataGridEditingUnit.Cell, true); g.CommitEdit(DataGridEditingUnit.Row, true); } catch { }
                    }
                }
            };

            // 按 (日期, 时间) 对 editList 整体重排
            Action sortEditListByDateTime = delegate {
                var sorted = editList.OrderBy(s2 => s2.Date ?? "").ThenBy(s2 => s2.Time ?? "").ToList();
                editList.Clear();
                foreach (var it in sorted) editList.Add(it);
            };

            // 刷新按钮：flush + 归一化 + 按日期/时间重排 + 重建面板
            var btnRefresh = new Button { Content = Loc.T("Str_Btn_Refresh"), Padding = new Thickness(12, 6, 12, 6), Margin = new Thickness(0, 0, 8, 0), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnRefresh.Click += delegate {
                flushPendingEdits();
                foreach (var it in editList) { it.Date = NormalizeDate(it.Date); it.Time = NormalizeTime(it.Time); }
                sortEditListByDateTime();
                _editSelected = null;
                rebuildEditPanel();
            };

            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmModify"), Padding = new Thickness(16, 6, 16, 6), Margin = new Thickness(0, 0, 8, 0), FontSize = 13, FontWeight = FontWeights.Bold,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnOk.Click += delegate {
                flushPendingEdits();
                // 归一化 + 按日期、时间重排
                foreach (var it in editList) { it.Date = NormalizeDate(it.Date); it.Time = NormalizeTime(it.Time); }
                sortEditListByDateTime();
                dlg.DialogResult = true;
            };

            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };

            btnPanel.Children.Add(btnAddBefore);
            btnPanel.Children.Add(btnAddAfter);
            btnPanel.Children.Add(btnMoveUp);
            btnPanel.Children.Add(btnMoveDown);
            btnPanel.Children.Add(btnDel);
            btnPanel.Children.Add(btnRefresh);
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            mainGrid.Children.Add(btnPanel);
            dlg.Content = mainGrid;

            if (dlg.ShowDialog() == true) {
                // 根据最终的 editList 顺序，重新推断场编号（日期+时段 首次出现分配新场号）
                var sMap2 = new Dictionary<string, int>();
                int sNum2 = 1;
                foreach (var it in editList) {
                    string per = InferTimePeriod(it.Time);
                    string k = (it.Date ?? "") + "|" + per;
                    if (!sMap2.ContainsKey(k)) { sMap2[k] = sNum2; sNum2++; }
                    it.SessionNumber = sMap2[k];
                    it.SessionName = string.Format("第{0}场（{1}{2}）", sMap2[k], it.Date ?? "", per);
                }
                // 用编辑后的数据替换原赛程（保留用户自定义顺序）
                _schedule.Clear();
                foreach (var item in editList) _schedule.Add(item);
                BuildScheduleTree();  // 刷新日程树 & 赛程管理面板
                FinishAndSyncPatch(BuildListSetPatch("schedule", JArray.FromObject(_schedule), ClientLabel()), "meet");
                AddLog(Loc.F("Str_Log_ScheduleModifiedFmt", _schedule.Count));
            }
        }

        private void DeleteSchedule_Click(object sender, RoutedEventArgs e) {
            if (_selectedScheduleItem == null) { AppMessageBox.Show(Loc.T("Str_Msg_SelectRowInScheduleToDelete")); return; }
            string desc = string.Format("{0} {1} {2}", _selectedScheduleItem.Gender, _selectedScheduleItem.EventName, _selectedScheduleItem.Stage);
            if (AppMessageBox.Show(Loc.F("Str_Msg_ConfirmDeleteScheduleItemFmt", desc), Loc.T("Str_MsgTitle_ConfirmDelete"), MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes) return;
            _schedule.Remove(_selectedScheduleItem);
            _selectedScheduleItem = null;
            BuildScheduleTree();
            FinishAndSyncPatch(BuildListSetPatch("schedule", JArray.FromObject(_schedule), ClientLabel()), "meet");
        }

        // 将用户输入的日期归一化为 yyyy-MM-dd 格式（支持 2026-4-21、2026/4/21、2026.4.21 等）
        private string NormalizeDate(string input) {
            if (string.IsNullOrWhiteSpace(input)) return input;
            string s = input.Trim().Replace('/', '-').Replace('.', '-');
            DateTime dt;
            if (DateTime.TryParseExact(s, new[] { "yyyy-M-d", "yyyy-MM-dd", "yyyy-M-dd", "yyyy-MM-d" },
                System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out dt)) {
                return dt.ToString("yyyy-MM-dd");
            }
            if (DateTime.TryParse(s, System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.None, out dt)) {
                return dt.ToString("yyyy-MM-dd");
            }
            return input;
        }

        // 将用户输入的时间归一化为 HH:mm 格式（支持 9:5、09:05、9:05 等）
        private string NormalizeTime(string input) {
            if (string.IsNullOrWhiteSpace(input)) return input;
            string s = input.Trim();
            DateTime dt;
            if (DateTime.TryParseExact(s, new[] { "H:m", "HH:mm", "H:mm", "HH:m" },
                System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out dt)) {
                return dt.ToString("HH:mm");
            }
            if (DateTime.TryParse(s, System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.None, out dt)) {
                return dt.ToString("HH:mm");
            }
            return input;
        }

        private string InferTimePeriod(string time) {
            if (string.IsNullOrEmpty(time)) return "上午";
            int hour = 9;
            var parts = time.Split(':');
            if (parts.Length >= 1) int.TryParse(parts[0], out hour);
            if (hour >= 18) return "晚上";
            if (hour >= 12) return "下午";
            return "上午";
        }

        private void RebuildScheduleGroupedView() {
            if (ScheduleGroupedPanel == null) return;
            ScheduleGroupedPanel.Children.Clear();

            // 归一化日期/时间，避免 2026-4-21 与 2026-04-21 被视为不同日期
            foreach (var item in _schedule) {
                item.Date = NormalizeDate(item.Date);
                item.Time = NormalizeTime(item.Time);
            }

            // 自动推断场编号：按 _schedule 自然顺序遍历，首次出现的(日期+时段)分配新场号
            var sessionMap = new Dictionary<string, int>();
            int sessionNum = 1;
            foreach (var item in _schedule) {
                string period = InferTimePeriod(item.Time);
                string key = (item.Date ?? "") + "|" + period;
                if (!sessionMap.ContainsKey(key)) {
                    sessionMap[key] = sessionNum;
                    sessionNum++;
                }
                item.SessionNumber = sessionMap[key];
                item.SessionName = string.Format("第{0}场（{1}{2}）", sessionMap[key], item.Date ?? "", period);
            }

            // 按场分组只读显示
            var groups = _schedule.GroupBy(s => s.SessionNumber).OrderBy(g => g.Key);
            foreach (var group in groups) {
                string label = group.First().SessionName ?? string.Format("第{0}场", group.Key);

                var header = new TextBlock {
                    Text = label,
                    FontWeight = FontWeights.Bold, FontSize = 15,
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1A5FB4")),
                    Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E8F0FE")),
                    Padding = new Thickness(8, 4, 8, 4),
                    Margin = new Thickness(0, 5, 0, 6)
                };
                ScheduleGroupedPanel.Children.Add(header);

                var grid = new DataGrid {
                    AutoGenerateColumns = false, CanUserAddRows = false,
                    HeadersVisibility = DataGridHeadersVisibility.Column,
                    MinHeight = 30,
                    AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                    IsReadOnly = true,
                    SelectionMode = DataGridSelectionMode.Single
                };
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Sched_ColSeq"), Binding = new System.Windows.Data.Binding("SeqInSession"), Width = new DataGridLength(55) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Sched_ColTime"), Binding = new System.Windows.Data.Binding("Time"), Width = new DataGridLength(70) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColAgeGroup"), Binding = new System.Windows.Data.Binding("AgeGroup"), Width = new DataGridLength(70) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_ColGender"), Binding = new System.Windows.Data.Binding("Gender"), Width = new DataGridLength(40) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Sched_ColEvent"), Binding = new System.Windows.Data.Binding("EventName"), Width = new DataGridLength(160) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Relay_ColStage"), Binding = new System.Windows.Data.Binding("Stage"), Width = new DataGridLength(60) });
                // 2026-06-21 加 "人(队)数" 列 (按 CountParticipants 算, 写入 ScheduleItem.ParticipantCount 供 Binding)
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_EM_Sched_ColParticipants"), Binding = new System.Windows.Data.Binding("ParticipantCount"), Width = new DataGridLength(70) });
                grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Results_ColHeatText"), Binding = new System.Windows.Data.Binding("HeatCount"), Width = new DataGridLength(50) });

                // 保留 _schedule 自然顺序（支持用户自定义的比赛顺序）
                int seq = 0;
                foreach (var item in group) {
                    item.ParticipantCount = CountParticipants(item);
                    item.SeqInSession = ++seq;   // 2026-09-21 每场从1开始计数
                }
                grid.ItemsSource = new ObservableCollection<ScheduleItem>(group);
                ScheduleGroupedPanel.Children.Add(grid);
            }

            if (_schedule.Count == 0) {
                ScheduleGroupedPanel.Children.Add(new TextBlock {
                    Text = Loc.T("Str_EM_Sched_NoSchedule"),
                    Foreground = new SolidColorBrush(Colors.Gray),
                    Margin = new Thickness(10)
                });
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 一键生成日程（只生成赛程安排和预估组数，不分配具体运动员）
        // ═══════════════════════════════════════════════════════════════
        // 2026-05-24 秩序册生成向导入口（索美式 5 步工作流）
        private void OpenSchedulingWizard_Click(object sender, RoutedEventArgs e) {
            var wnd = new SchedulingWizardWindow(_swimmers, _events, _ageGroups, _genders, _poolConfig, _scoringConfig, _durationConfig, _units, _staff) {
                Owner = this
            };
            // 2026-05-25 草稿: 中途关窗时存到 _wizardDraft, 下次再打开自动恢复
            wnd.InitialDraft = _wizardDraft;
            wnd.SaveDraftCallback = draft => { _wizardDraft = draft; AutoSaveData(); };
            wnd.HasExistingScheduleProbe = () => _schedule != null && _schedule.Any(s => !string.IsNullOrEmpty(s.EventName));
            // 2026-05-25 提供比赛元信息给「编辑/打印 封面 / 仲裁裁判员名单」等模板用
            wnd.CompetitionNameInfo = _competitionName;
            // 2026-06-16 注入比赛规则 — 群众赛/U系列触发"决赛多组直接录取"分支 (HeatScheduler.IsDirectFinalRule)
            wnd.CompetitionRule = _competitionRule ?? "";
            wnd.CompetitionLocation = LocationBox != null ? LocationBox.Text : "";
            wnd.CompetitionStartDate = GetDatePickerText(StartDatePicker);
            wnd.CompetitionEndDate = GetDatePickerText(EndDatePicker);
            wnd.CompetitionOrganizer = OrganizerBox != null ? OrganizerBox.Text : "";
            wnd.ExistingSchedule = _schedule;
            bool? ok = wnd.ShowDialog();
            // Tab 3 "应用编排到主程序赛程" 后写回 _schedule
            if (wnd.ApplyToMainSchedule && wnd.AssignedItems != null && wnd.AssignedItems.Count > 0) {
                _schedule.Clear();
                // 2026-05-25 按日期+时段重新分配 SessionNumber
                // 修复: 中文 OrderBy 默认按拼音排序 (s<w<x → 上午<晚上<下午), 必须用显式数值序避免错位
                Func<string, int> sessionRank = s => s == "上午" ? 0 : s == "下午" ? 1 : s == "晚上" ? 2 : 9;
                var bySession = wnd.AssignedItems
                    .GroupBy(a => (a.Date ?? "") + "|" + (a.Session ?? ""))
                    .OrderBy(g => g.First().Date ?? "")
                    .ThenBy(g => sessionRank(g.First().Session ?? ""))
                    .ToList();
                int sessionNum = 1;
                foreach (var grp in bySession) {
                    foreach (var a in grp.OrderBy(x => x.Time)) {
                        // 2026-05-24 C5 长距离快慢组：SessionName 标注 · 慢组 / · 快组
                        string sessionTag = string.IsNullOrEmpty(a.HeatRange) ? "" : (" · " + a.HeatRange);
                        _schedule.Add(new ScheduleItem {
                            SessionNumber = sessionNum,
                            SessionName = string.Format("第{0}场（{1} {2}{3}）", sessionNum, a.Date, a.Session, sessionTag),
                            Date = a.Date,
                            Time = a.Time,
                            AgeGroup = a.AgeGroup,
                            EventName = a.EventName,
                            Gender = a.Gender,
                            Stage = a.Stage,
                            HeatCount = a.HeatCount,
                            IsRelay = a.EventName != null && a.EventName.Contains("接力")
                        });
                    }
                    sessionNum++;
                }
                AutoSaveData();
                // 2026-05-25 存盘后立刻刷新整个系统的 UI: 赛程树 / 3 级导航 / 各 Tab combo / 大屏广播
                BuildScheduleTree();         // 同时触发 RebuildBothNavTrees + RefreshSwimmerStages
                UpdateResultHeatCombo();
                RefreshResultGrid();
                UpdateEditHeatCombo();
                RefreshEventComboBoxes();
                Broadcast();
                AddLog(Loc.F("Str_Log_ProgramWizardDoneFmt", wnd.AssignedItems.Count, sessionNum - 1));
                AppMessageBox.Show(Loc.F("Str_Msg_LineupWrittenBackFmt", wnd.AssignedItems.Count), Loc.T("Str_MsgTitle_Done"));
            }
        }

        // 2026-05-25 「一键生成日程」按钮 + AutoBuildSchedule_Click + PromptStagePlan 已删除
        // 与「秩序册生成向导」功能重复且有问题（按 _swimmers 字符串匹配项目；时段硬编码 09:00/14:30/19:30；
        // 不写入项目用时配置；不支持长距离快慢组拆场次）。改用 OpenSchedulingWizard_Click → 一键全自动。
        // AutoBuildSchedule(List<string>) 核心函数也已删除，无其它调用方

        // ═══════════════════════════════════════════════════════════════
        // 预赛自动分组（只对第一赛次的运动员进行蛇形分组）
        // 后续赛次（半决赛/决赛）需等上一轮成绩出来后通过晋级处理分组
        // ═══════════════════════════════════════════════════════════════
        private void AutoGenerateHeats_Click(object sender, RoutedEventArgs e) {
            if (_swimmers.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRegisteredSwimmersForHeats"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            if (_schedule.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_GenerateScheduleFirst"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            // 检测是否已有分组
            bool hasExistingAssignment = _swimmers.Any(s =>
                !string.IsNullOrEmpty(s.EventName) && s.Heat > 0 &&
                !(s.Notes != null && s.Notes.StartsWith("接力队员")));
            string confirmMsg = Loc.T("Str_Msg_ConfirmAutoGenHeats");
            if (hasExistingAssignment)
                confirmMsg = Loc.T("Str_Msg_WarnReassignHeats");
            if (AppMessageBox.Show(confirmMsg, Loc.T("Str_MsgTitle_Confirm"), MessageBoxButton.YesNo, hasExistingAssignment ? MessageBoxImage.Warning : MessageBoxImage.Question) != MessageBoxResult.Yes) return;

            // 统一对所有项目（个人+接力）的第一赛次进行蛇形分组，按组别隔离
            int generated = 0;
            var skippedAuto = new List<string>();   // 2026-09-12 里面有动不得的组, 这次跳过的项目
            foreach (var item in _schedule) {
                string fullEvent = item.EventName;
                string stage = item.Stage;
                string gender = item.Gender;
                string ageGroup = item.AgeGroup ?? "";

                // 过滤：仅本 ScheduleItem 对应的组别
                var eventSwimmers = _swimmers.Where(s =>
                    s.EventName == fullEvent && SgMatch(s.Gender, gender) && s.CurrentStage == stage &&
                    MatchesAgeGroup(s, ageGroup) &&
                    !(s.Notes != null && s.Notes.StartsWith("接力队员"))
                ).ToList();

                if (eventSwimmers.Count == 0) continue;

                // 2026-09-12 这一项里有锁着的组(正在比 / 已完赛)就跳过, 别的项照分。
                //   蛇形重排会把全项的组次道次重来一遍, 锁着那组同样跑不掉。
                int lockedHeat0;
                string lockedWhy0 = EventLockedWhy(ageGroup, gender, fullEvent, stage, out lockedHeat0);
                if (lockedWhy0 != null) {
                    skippedAuto.Add(string.Format("{0} {1} {2}(第{3}组{4})", gender, fullEvent, stage, lockedHeat0, lockedWhy0));
                    AddLog(Loc.F("Str_Log_AutoAssignSkippedFmt", Loc.GenderDisplay(gender), fullEvent, Loc.StageDisplay(stage), lockedHeat0, lockedWhy0));
                    continue;
                }

                // 2026-05-23 传入用户配置的种子组数（默认 3 短 / 2 长；可在 名次分设置 改）
                int seedS = _scoringConfig != null && _scoringConfig.SeedHeatsCountShort > 0 ? _scoringConfig.SeedHeatsCountShort : 3;
                int seedL = _scoringConfig != null && _scoringConfig.SeedHeatsCountLong  > 0 ? _scoringConfig.SeedHeatsCountLong  : 2;
                var assignments = HeatScheduler.GenerateHeats(eventSwimmers, _poolConfig, fullEvent, stage, seedS, seedL);
                item.HeatCount = assignments.Count > 0 ? assignments.Max(a => a.Heat) : 0;
                generated += assignments.Count;
                string typeLabel = fullEvent.Contains("接力") ? "队" : "人";
                AddLog(Loc.F("Str_Log_AutoAssignEventDoneFmt",
                    string.IsNullOrEmpty(ageGroup) ? "" : ("[" + ageGroup + "] "),
                    gender, fullEvent, stage, eventSwimmers.Count, typeLabel, item.HeatCount));
                // 编排警告（每组 < 3 人、同单位同组无法消除）一并写入日志
                foreach (var w in HeatScheduler.LastWarnings) AddLog(w);
            }

            BuildScheduleTree();
            SyncRelayHeatInfo();
            string skipAutoNote = skippedAuto.Count == 0 ? ""
                : ("\n\n以下项目这次跳过了(里面有动不得的组):\n  " + string.Join("\n  ", skippedAuto.ToArray()));
            if (generated > 0) {
                AddLog(Loc.F("Str_Log_AutoAssignCompletedFmt", generated));
                AppMessageBox.Show(Loc.F("Str_Msg_AutoHeatsDoneFmt", generated, skipAutoNote),
                    Loc.T("Str_MsgTitle_HeatsDone"), MessageBoxButton.OK, MessageBoxImage.Information);
            } else if (skippedAuto.Count > 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoEventsAssigned") + skipAutoNote, Loc.T("Str_MsgTitle_HeatsNotDone"), MessageBoxButton.OK, MessageBoxImage.Information);
            } else {
                AppMessageBox.Show(Loc.T("Str_Msg_NoSwimmersAssignedCheck"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
            }
            AutoSaveData();
            Broadcast();
            UpdateEditHeatCombo();
        }

        // ═══════════════════════════════════════════════════════════════
        // 手动分组：按项目选人员 → 可一键均分到 N 组，或直接编辑 组/道次
        // 解决自动分组"第一组满道，后面组缺很多"的不均衡问题
        // ═══════════════════════════════════════════════════════════════
        private void ManualHeatAssign_Click(object sender, RoutedEventArgs e) {
            if (_swimmers.Count == 0) { AppMessageBox.Show(Loc.T("Str_Msg_NoRegisteredSwimmers")); return; }

            // 收集有效 (组别, gender, event) 组合 — 以组别为第一维，男甲/男乙单独成条
            var combos = _swimmers
                .Where(s => !string.IsNullOrEmpty(s.Gender) && !string.IsNullOrEmpty(s.EventName) &&
                            !(s.Notes != null && s.Notes.StartsWith("接力队员")))
                .GroupBy(s => new { AgeGroup = s.AgeCategory ?? "", s.Gender, s.EventName })
                .OrderBy(g => g.Key.AgeGroup).ThenBy(g => g.Key.Gender).ThenBy(g => g.Key.EventName)
                .Select(g => g.Key)
                .ToList();
            if (combos.Count == 0) { AppMessageBox.Show(Loc.T("Str_Msg_NoSwimmersToGroup")); return; }

            var dlg = new Window {
                Title = Loc.T("Str_Win_ManualGroup_Title"), Width = 900, Height = 620,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.CanResize
            };
            var mainGrid = new Grid { Margin = new Thickness(14) };
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            // ─ 选择条 ─
            var pickRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 8) };
            pickRow.Children.Add(new TextBlock { Text = Loc.T("Str_EM_RegEventLabel"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 4, 0) });
            var cbEvent = new ComboBox { Width = 280 };
            foreach (var c in combos) {
                string label = (string.IsNullOrEmpty(c.AgeGroup) ? "" : c.AgeGroup + " ") + c.Gender + " " + c.EventName;
                cbEvent.Items.Add(label);
            }
            cbEvent.SelectedIndex = 0;
            pickRow.Children.Add(cbEvent);

            pickRow.Children.Add(new TextBlock { Text = Loc.T("Str_Label_StageColonIndent"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 4, 0) });
            var cbStage = new ComboBox { Width = 90 };
            cbStage.Items.Add("预赛"); cbStage.Items.Add("半决赛"); cbStage.Items.Add("决赛");
            cbStage.SelectedIndex = 0;
            pickRow.Children.Add(cbStage);

            pickRow.Children.Add(new TextBlock { Text = Loc.T("Str_Label_PerHeatCountColon"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 4, 0) });
            var tbPerHeat = new TextBox { Width = 50, Padding = new Thickness(4), Text = _poolConfig.LaneCount.ToString() };
            pickRow.Children.Add(tbPerHeat);

            pickRow.Children.Add(new TextBlock { Text = Loc.T("Str_Label_GroupingMethodColon"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 4, 0) });
            var cbMode = new ComboBox { Width = 130 };
            cbMode.Items.Add("蛇形(强↔弱交替)");
            cbMode.Items.Add("顺序(按成绩依次)");
            cbMode.Items.Add("按注册顺序");
            cbMode.SelectedIndex = 0;
            pickRow.Children.Add(cbMode);
            Grid.SetRow(pickRow, 0);
            mainGrid.Children.Add(pickRow);

            // ─ 操作按钮行 ─
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 8) };
            var btnEvenSplit = new Button { Content = Loc.T("Str_Btn_EvenSplit"), Padding = new Thickness(12, 5, 12, 5),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0),
                ToolTip = Loc.T("Str_Tooltip_EvenSplit")};
            btnRow.Children.Add(btnEvenSplit);
            var btnClear = new Button { Content = Loc.T("Str_Btn_ClearEventGrouping"), Padding = new Thickness(12, 5, 12, 5),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EF4444")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            btnRow.Children.Add(btnClear);
            // 2026-05-24 分组结果导出
            var btnExportXlsx = new Button { Content = Loc.T("Str_Btn_ExportGroupingExcel"), Padding = new Thickness(12, 5, 12, 5),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#16A34A")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0),
                ToolTip = Loc.T("Str_Tooltip_ExportGroupingExcel") };
            btnRow.Children.Add(btnExportXlsx);
            var btnExportCsv = new Button { Content = Loc.T("Str_Btn_ExportCsvEmoji"), Padding = new Thickness(12, 5, 12, 5),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#0EA5E9")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0),
                ToolTip = Loc.T("Str_Tooltip_ExportGroupingCsv") };
            btnRow.Children.Add(btnExportCsv);
            btnRow.Children.Add(new TextBlock { Text = Loc.T("Str_HeatGrid_EditHint"),
                VerticalAlignment = VerticalAlignment.Center,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")) });
            Grid.SetRow(btnRow, 1);
            mainGrid.Children.Add(btnRow);

            // ─ 表格 ─
            var rowSource = new System.Collections.ObjectModel.ObservableCollection<ManualHeatRow>();
            var grid = new DataGrid {
                AutoGenerateColumns = false, CanUserAddRows = false, IsReadOnly = false,
                SelectionMode = DataGridSelectionMode.Extended,
                AlternatingRowBackground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC"))
            };
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Bib"), Binding = new System.Windows.Data.Binding("BibNumber") { Mode = System.Windows.Data.BindingMode.OneWay }, Width = new DataGridLength(70), IsReadOnly = true });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Name"), Binding = new System.Windows.Data.Binding("Name") { Mode = System.Windows.Data.BindingMode.OneWay }, Width = new DataGridLength(100), IsReadOnly = true });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Team"), Binding = new System.Windows.Data.Binding("Country") { Mode = System.Windows.Data.BindingMode.OneWay }, Width = new DataGridLength(120), IsReadOnly = true });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Group"), Binding = new System.Windows.Data.Binding("AgeCategory") { Mode = System.Windows.Data.BindingMode.OneWay }, Width = new DataGridLength(70), IsReadOnly = true });
            var seedCol = new DataGridTextColumn { Header = Loc.T("Str_Col_Entry"), Binding = new System.Windows.Data.Binding("SeedTime") { Mode = System.Windows.Data.BindingMode.OneWay }, Width = new DataGridLength(90), IsReadOnly = true };
            grid.Columns.Add(seedCol);
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Heat"), Binding = new System.Windows.Data.Binding("Heat") { Mode = System.Windows.Data.BindingMode.TwoWay, UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged }, Width = new DataGridLength(60) });
            grid.Columns.Add(new DataGridTextColumn { Header = Loc.T("Str_Col_Lane"), Binding = new System.Windows.Data.Binding("Lane") { Mode = System.Windows.Data.BindingMode.TwoWay, UpdateSourceTrigger = System.Windows.Data.UpdateSourceTrigger.PropertyChanged }, Width = new DataGridLength(60) });
            grid.ItemsSource = rowSource;
            Grid.SetRow(grid, 2);
            mainGrid.Children.Add(grid);

            // ─ 确认 / 取消 ─
            var okRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 8, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_ConfirmSave"), Padding = new Thickness(18, 6, 18, 6), FontWeight = FontWeights.Bold,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(18, 6, 18, 6),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            okRow.Children.Add(btnOk);
            okRow.Children.Add(btnCancel);
            Grid.SetRow(okRow, 3);
            mainGrid.Children.Add(okRow);
            dlg.Content = mainGrid;

            // ─ 事件绑定 ─
            Action reloadRows = delegate {
                rowSource.Clear();
                if (cbEvent.SelectedIndex < 0) return;
                var combo = combos[cbEvent.SelectedIndex];
                string stage = cbStage.SelectedItem as string ?? "预赛";
                string prevStage = GetPreviousStage(stage);
                // 列标题随阶段切换：预赛=报名成绩，半决赛/决赛=上一赛次成绩
                seedCol.Header = stage == "预赛" ? "报名成绩" : (prevStage + "成绩");
                bool isRelay = combo.EventName.Contains("接力");
                var matched = _swimmers.Where(s =>
                    s.Gender == combo.Gender && s.EventName == combo.EventName &&
                    MatchesAgeGroup(s, combo.AgeGroup) &&
                    !(isRelay && s.Notes != null && s.Notes.StartsWith("接力队员"))).ToList();
                foreach (var s in matched) {
                    int h = 0, ln = 0;
                    var sa = s.GetAssignmentForStage(stage);
                    if (sa != null) { h = sa.Heat; ln = sa.Lane; }
                    else if (s.CurrentStage == stage) { h = s.Heat; ln = s.Lane; }
                    rowSource.Add(new ManualHeatRow(s, h, ln, stage, prevStage));
                }
            };
            cbEvent.SelectionChanged += delegate { reloadRows(); };
            cbStage.SelectionChanged += delegate { reloadRows(); };
            reloadRows();

            btnEvenSplit.Click += delegate {
                // 提交正在编辑的场
                try { grid.CommitEdit(DataGridEditingUnit.Cell, true); grid.CommitEdit(DataGridEditingUnit.Row, true); } catch { }

                int perHeat = 0;
                int.TryParse((tbPerHeat.Text ?? "").Trim(), out perHeat);
                if (perHeat <= 0) perHeat = _poolConfig.LaneCount;

                var targets = grid.SelectedItems.Cast<ManualHeatRow>().ToList();
                if (targets.Count == 0) targets = rowSource.ToList();
                if (targets.Count == 0) return;

                // 排序：预赛按报名成绩；半决赛/决赛按上一赛次成绩；无成绩放最后
                string sortStage = cbStage.SelectedItem as string ?? "预赛";
                string sortPrev = GetPreviousStage(sortStage);
                Func<ManualHeatRow, double> seedSeconds = delegate(ManualHeatRow r) {
                    if (sortStage != "预赛") {
                        var pr = r.Swimmer.GetResultForStage(sortPrev);
                        if (pr != null && pr.FinalTime > 0) return pr.FinalTime;
                        return double.MaxValue;
                    }
                    double t = TimeFormatter.Parse(r.Swimmer.EntryTime ?? "");
                    return t > 0 ? t : double.MaxValue;
                };
                if (cbMode.SelectedIndex == 0 || cbMode.SelectedIndex == 1) {
                    targets = targets.OrderBy(r => seedSeconds(r)).ToList();
                }
                // cbMode == 2 按注册顺序（也就是当前 rowSource 顺序），保持不变即可
                if (cbMode.SelectedIndex == 2) {
                    targets = rowSource.Where(targets.Contains).ToList();
                }

                int total = targets.Count;
                int heatCount = (int)Math.Ceiling((double)total / perHeat);
                if (heatCount < 1) heatCount = 1;

                // 均分：各组尽量相等（多出的人数依序加到前面组）
                int baseSize = total / heatCount;
                int extra = total % heatCount;
                // lane 优先顺序：中间道次优先（快者在中）
                int[] lanePrio = HeatScheduler.GetLanePriority(_poolConfig);

                if (cbMode.SelectedIndex == 0) {
                    // 蛇形：把 sorted[i] 放到 heat index = SnakeHeat(i) —— 每组各 k 人，按蛇形交替
                    int idx = 0;
                    // 先按 "每组大小" 把 heats 准备好
                    var heatBuckets = new List<ManualHeatRow>[heatCount];
                    for (int h = 0; h < heatCount; h++) heatBuckets[h] = new List<ManualHeatRow>();
                    int[] heatSizes = new int[heatCount];
                    for (int h = 0; h < heatCount; h++) heatSizes[h] = baseSize + (h < extra ? 1 : 0);
                    // 蛇形放：第 1 轮 h=0,1,2,...,heatCount-1；第 2 轮逆序；如此循环
                    int round = 0;
                    int[] remain = (int[])heatSizes.Clone();
                    while (idx < total) {
                        bool leftToRight = (round % 2) == 0;
                        for (int j = 0; j < heatCount && idx < total; j++) {
                            int h = leftToRight ? j : heatCount - 1 - j;
                            if (remain[h] <= 0) continue;
                            heatBuckets[h].Add(targets[idx++]);
                            remain[h]--;
                        }
                        round++;
                    }
                    // 分道次：每组内按成绩由快到慢映射到 lanePrio（预赛=报名成绩，否则=上一赛次成绩）
                    for (int h = 0; h < heatCount; h++) {
                        var bucket = heatBuckets[h].OrderBy(r => seedSeconds(r)).ToList();
                        for (int k = 0; k < bucket.Count; k++) {
                            bucket[k].Heat = (heatCount - h).ToString();   // 速度最快的人放"最后一组"(正式比赛惯例)
                            bucket[k].Lane = (k < lanePrio.Length ? lanePrio[k] : k + 1).ToString();
                        }
                    }
                } else {
                    // 顺序/按注册顺序：按 targets 顺序填满每组
                    int idx = 0;
                    for (int h = 0; h < heatCount && idx < total; h++) {
                        int size = baseSize + (h < extra ? 1 : 0);
                        for (int k = 0; k < size && idx < total; k++) {
                            targets[idx].Heat = (h + 1).ToString();
                            targets[idx].Lane = (k < lanePrio.Length ? lanePrio[k] : k + 1).ToString();
                            idx++;
                        }
                    }
                }
                grid.Items.Refresh();
            };

            btnClear.Click += delegate {
                foreach (var r in rowSource) { r.Heat = "0"; r.Lane = "0"; }
                grid.Items.Refresh();
            };

            // 2026-05-24 导出全量分组结果 (Excel)
            btnExportXlsx.Click += delegate {
                try { grid.CommitEdit(DataGridEditingUnit.Cell, true); grid.CommitEdit(DataGridEditingUnit.Row, true); } catch { }
                ExportHeatAssignmentsExcel_Click(null, null);
            };
            // 2026-05-24 导出当前表格的分组 (CSV)
            btnExportCsv.Click += delegate {
                try { grid.CommitEdit(DataGridEditingUnit.Cell, true); grid.CommitEdit(DataGridEditingUnit.Row, true); } catch { }
                if (cbEvent.SelectedIndex < 0) { AppMessageBox.Show(Loc.T("Str_Msg_SelectEventFirst")); return; }
                var combo = combos[cbEvent.SelectedIndex];
                string stage = cbStage.SelectedItem as string ?? "预赛";
                var saveDlg = new Microsoft.Win32.SaveFileDialog {
                    Filter = Loc.T("Str_Filter_Csv"),
                    Title = Loc.T("Str_Win_ManualSeed_ExportCsvTitle"),
                    FileName = string.Format("{0}_{1}_{2}_{3}_{4}.csv", Loc.T("Str_DocTitle_HeatAssignments"),
                        string.IsNullOrEmpty(combo.AgeGroup) ? Loc.T("Str_UnitBibAlloc_Unlimited") : combo.AgeGroup,
                        combo.Gender, combo.EventName, stage)
                };
                if (saveDlg.ShowDialog() != true) return;
                var sb = new System.Text.StringBuilder();
                sb.AppendLine(string.Join(",", new[] { Loc.T("Str_Col_Group"), Loc.T("Str_DocC_ColGender"), Loc.T("Str_Col_Event"), Loc.T("Str_DocC_ColStage"), Loc.T("Str_EM_Relay_ColHeat"), Loc.T("Str_Col_Lane"), Loc.T("Str_Col_Bib"), Loc.T("Str_Col_Name"), Loc.T("Str_Col_Team"), Loc.T("Str_Col_SeedTime") }));
                foreach (var r in rowSource) {
                    sb.AppendLine(string.Join(",", new[] {
                        CsvEsc(combo.AgeGroup ?? ""), CsvEsc(combo.Gender ?? ""), CsvEsc(combo.EventName ?? ""), CsvEsc(stage),
                        r.Heat ?? "0", r.Lane ?? "0",
                        CsvEsc(r.BibNumber), CsvEsc(r.Name), CsvEsc(r.Country), CsvEsc(r.SeedTime)
                    }));
                }
                System.IO.File.WriteAllText(saveDlg.FileName, sb.ToString(), System.Text.Encoding.UTF8);
                AppMessageBox.Show(Loc.F("Str_Msg_ExportedToFmt", saveDlg.FileName), Loc.T("Str_MsgTitle_Done"));
            };

            btnOk.Click += delegate {
                try { grid.CommitEdit(DataGridEditingUnit.Cell, true); grid.CommitEdit(DataGridEditingUnit.Row, true); } catch { }
                dlg.DialogResult = true;
            };
            btnCancel.Click += delegate { dlg.DialogResult = false; };

            if (dlg.ShowDialog() == true) {
                if (cbEvent.SelectedIndex < 0) return;
                var combo = combos[cbEvent.SelectedIndex];
                string stage = cbStage.SelectedItem as string ?? "预赛";

                // 2026-09-12 整项重排, 里面有锁着的组(正在比/已完赛)就整项挡下
                if (BlockIfEventLocked(combo.AgeGroup, combo.Gender, combo.EventName, stage, Loc.T("Str_Action_Regroup"))) return;

                int maxHeat = 0, assigned = 0;
                foreach (var r in rowSource) {
                    int h = 0, ln = 0;
                    int.TryParse(r.Heat ?? "", out h);
                    int.TryParse(r.Lane ?? "", out ln);
                    if (h > 0) {
                        r.Swimmer.SetStageAssignment(stage, h, ln, r.Swimmer.EntryTimeSeconds, r.Swimmer.EntryTime);
                        if (r.Swimmer.CurrentStage == stage) { r.Swimmer.Heat = h; r.Swimmer.Lane = ln; }
                        if (h > maxHeat) maxHeat = h;
                        assigned++;
                    } else {
                        if (r.Swimmer.StageAssignments.ContainsKey(stage)) r.Swimmer.StageAssignments.Remove(stage);
                        if (r.Swimmer.CurrentStage == stage) { r.Swimmer.Heat = 0; r.Swimmer.Lane = 0; }
                    }
                }

                // 更新/新建 Schedule 项（按 AgeGroup+Gender+Event+Stage 唯一）
                var sched = _schedule.FirstOrDefault(s =>
                    (s.AgeGroup ?? "") == combo.AgeGroup &&
                    s.Gender == combo.Gender && s.EventName == combo.EventName && s.Stage == stage);
                if (sched == null && maxHeat > 0) {
                    _schedule.Add(new ScheduleItem {
                        SessionNumber = _schedule.Count > 0 ? _schedule.Max(s => s.SessionNumber) : 1,
                        AgeGroup = combo.AgeGroup,
                        Gender = combo.Gender, EventName = combo.EventName, Stage = stage, HeatCount = maxHeat
                    });
                } else if (sched != null) {
                    sched.HeatCount = maxHeat;
                }

                SaveAndPushAssign(combo.AgeGroup, combo.Gender, combo.EventName, stage);   // 2026-09-12 走补丁
                BuildScheduleTree();
                SyncRelayHeatInfo();
                UpdateEditHeatCombo();
                Broadcast();
                AddLog(Loc.F("Str_Log_ManualAssignDoneFmt",
                    string.IsNullOrEmpty(combo.AgeGroup) ? "" : ("[" + combo.AgeGroup + "] "),
                    combo.Gender, combo.EventName, stage, assigned, maxHeat));
            }
        }

        // 手动分组对话框的行绑定对象
        private class ManualHeatRow : INotifyPropertyChanged
        {
            private string _heat, _lane;
            private string _stage, _prevStage;
            public Swimmer Swimmer { get; private set; }
            public string BibNumber { get { return Swimmer.BibNumber ?? ""; } }
            public string Name { get { return Swimmer.Name ?? ""; } }
            public string Country { get { return Swimmer.Country ?? ""; } }
            public string AgeCategory { get { return Swimmer.AgeCategory ?? ""; } }
            public string EntryTime { get { return Swimmer.EntryTime ?? ""; } }
            // 种子成绩：预赛取报名成绩；半决赛/决赛取上一赛次最终成绩
            public string SeedTime {
                get {
                    if (_stage != "预赛" && !string.IsNullOrEmpty(_prevStage)) {
                        var pr = Swimmer.GetResultForStage(_prevStage);
                        if (pr != null && pr.FinalTime > 0) return TimeFormatter.Format(pr.FinalTime);
                        return "";
                    }
                    return Swimmer.EntryTime ?? "";
                }
            }
            public string Heat { get { return _heat; } set { _heat = value; Raise("Heat"); } }
            public string Lane { get { return _lane; } set { _lane = value; Raise("Lane"); } }
            public ManualHeatRow(Swimmer s, int h, int l) : this(s, h, l, "预赛", "") { }
            public ManualHeatRow(Swimmer s, int h, int l, string stage, string prevStage) {
                // 2026-05-24 道次/组次为 0 也显式显示 '0'，避免与空白混淆
                Swimmer = s; _heat = h.ToString(); _lane = l.ToString();
                _stage = stage ?? "预赛"; _prevStage = prevStage ?? "";
            }
            public event PropertyChangedEventHandler PropertyChanged;
            void Raise(string n) { if (PropertyChanged != null) PropertyChanged(this, new PropertyChangedEventArgs(n)); }
        }

        // ═══════════════════════════════════════════════════════════════
        // 追加分组：只对新增的未分组运动员进行分组，已分好组的不变
        // ═══════════════════════════════════════════════════════════════
        private void SupplementHeats_Click(object sender, RoutedEventArgs e) {
            if (_schedule.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_GenerateScheduleAndHeatsFirst"), Loc.T("Str_MsgTitle_Info")); return;
            }

            // 收集所有未分组的运动员（按项目分组）
            // 2026-06-16 key 加 ageGroup, 修跨组别污染 bug — 不同组别同 (gender,event,stage) 不应混分到同一组
            var unassigned = new Dictionary<string, List<Swimmer>>(); // key: "ageGroup|gender|eventName|stage"
            foreach (var s in _swimmers) {
                if (string.IsNullOrEmpty(s.EventName) || string.IsNullOrEmpty(s.Gender)) continue;
                if (s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                string stage = s.CurrentStage ?? "预赛";
                var sa = s.GetAssignmentForStage(stage);
                bool assigned = (sa != null && sa.Heat > 0) || (s.Heat > 0 && s.CurrentStage == stage);
                if (!assigned) {
                    string key = (s.AgeCategory ?? "") + "|" + s.Gender + "|" + s.EventName + "|" + stage;
                    if (!unassigned.ContainsKey(key)) unassigned[key] = new List<Swimmer>();
                    unassigned[key].Add(s);
                }
            }

            if (unassigned.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_AllSwimmersAssigned"), Loc.T("Str_MsgTitle_Info")); return;
            }

            // 弹窗显示未分组运动员
            var dlg = new Window {
                Title = Loc.T("Str_Win_AppendGroup_Title"), Width = 600, Height = 500,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.CanResize
            };
            var mainPanel = new Grid { Margin = new Thickness(16) };
            mainPanel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            mainPanel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            mainPanel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var infoText = new TextBlock {
                Text = string.Format("以下 {0} 个项目有未分组运动员，点击\"确认追加\"将自动分配到新增组：",
                    unassigned.Count),
                FontSize = 14, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 10)
            };
            mainPanel.Children.Add(infoText);

            // 列表
            var listBox = new ListBox { FontSize = 13, Margin = new Thickness(0, 0, 0, 10) };
            listBox.SetValue(Grid.RowProperty, 1);
            foreach (var kv in unassigned) {
                var parts = kv.Key.Split('|');
                string label = string.Format("{0} {1} {2}: {3}{4}未分组",
                    parts[0], parts[1], parts[2], kv.Value.Count,
                    parts[1].Contains("接力") ? "队" : "人");
                // 显示每个人的名字
                var names = new List<string>();
                foreach (var s in kv.Value) names.Add(s.Name);
                label += " (" + string.Join(", ", names.ToArray()) + ")";
                listBox.Items.Add(label);
            }
            mainPanel.Children.Add(listBox);

            // 按钮
            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            btnPanel.SetValue(Grid.RowProperty, 2);
            var btnOk = new Button {
                Content = Loc.T("Str_Btn_ConfirmAppend"), Padding = new Thickness(16, 6, 16, 6), FontSize = 14, FontWeight = FontWeights.Bold,
                Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#0EA5E9")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0)
            };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnCancel = new Button {
                Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), FontSize = 14,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0)
            };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnCancel);
            mainPanel.Children.Add(btnPanel);
            dlg.Content = mainPanel;

            if (dlg.ShowDialog() != true) return;

            // 执行追加分组
            int totalAdded = 0;
            int laneCount = _poolConfig.LaneCount;
            int[] lanePriority = HeatScheduler.GetLanePriority(_poolConfig);
            // 2026-09-12 改动过的项目, 循环完一项发一条补丁
            var touchedEvents = new List<string[]>();
            var skippedEvents = new List<string>();

            foreach (var kv in unassigned) {
                var parts = kv.Key.Split('|');
                // 2026-06-16 key 是 ageGroup|gender|eventName|stage (4 段, 上面同步改)
                string ageGroup = parts[0];
                string gender = parts[1];
                string eventName = parts[2];
                string stage = parts[3];
                var newSwimmers = kv.Value;

                // 2026-09-12 追加会往最后一组里塞人 —— 那一组正在比或已完赛就跳过这一项,
                //   别的项目照常追加。不弹窗打断整批, 最后一并报。
                int lockedHeat;
                string lockedWhy = EventLockedWhy(ageGroup, gender, eventName, stage, out lockedHeat);
                if (lockedWhy != null) {
                    skippedEvents.Add(string.Format("{0} {1} {2}(第{3}组{4})", gender, eventName, stage, lockedHeat, lockedWhy));
                    AddLog(Loc.F("Str_Log_AppendAssignSkippedFmt", Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage), lockedHeat, lockedWhy));
                    continue;
                }
                touchedEvents.Add(new string[] { ageGroup, gender, eventName, stage });

                // 找该项目当前最大组号
                // 2026-10-08 用户要求全系统排查同类问题后发现: 这里原来 sa==null 时
                // 退回顶层 CurrentStage/Heat 瞎猜——同一项目"男"/"男女"两个并列子
                // 项目的运动员都在内存里时, 顶层字段可能是旧赛次残留, 会把另一个
                // 子项目的人算进 maxHeat/lastHeatCount, 导致追加分组算错"最后一组
                // 还有几个空位", 把新人塞错道或塞错组。改成只认 StageAssignment。
                int maxHeat = 0;
                foreach (var s in _swimmers) {
                    if (!SgMatch(s.Gender, gender) || s.EventName != eventName) continue;
                    if (s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                    var sa = s.GetAssignmentForStage(stage);
                    if (sa != null && sa.Heat > maxHeat) maxHeat = sa.Heat;
                }

                // 检查最后一组是否还有空位
                int lastHeatCount = 0;
                if (maxHeat > 0) {
                    foreach (var s in _swimmers) {
                        if (!SgMatch(s.Gender, gender) || s.EventName != eventName) continue;
                        if (s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                        var sa = s.GetAssignmentForStage(stage);
                        if (sa != null && sa.Heat == maxHeat) lastHeatCount++;
                    }
                }

                int availableInLast = (maxHeat > 0) ? (laneCount - lastHeatCount) : 0;
                int idx = 0;

                // 先填满最后一组的空位
                if (availableInLast > 0 && maxHeat > 0) {
                    int startLane = lastHeatCount; // 已有几人，从下一个泳道开始
                    while (idx < newSwimmers.Count && availableInLast > 0) {
                        int lane = startLane < lanePriority.Length ? lanePriority[startLane] : startLane;
                        var sw = newSwimmers[idx];
                        sw.Heat = maxHeat;
                        sw.Lane = lane;
                        sw.CurrentStage = stage;
                        sw.SetStageAssignment(stage, maxHeat, lane, sw.EntryTimeSeconds, sw.EntryTime);
                        AddLog(Loc.F("Str_Log_AppendAssignedFmt", sw.Name, maxHeat, lane));
                        startLane++;
                        availableInLast--;
                        idx++;
                        totalAdded++;
                    }
                }

                // 剩余的分配到新组
                while (idx < newSwimmers.Count) {
                    maxHeat++;
                    int heatSize = Math.Min(laneCount, newSwimmers.Count - idx);
                    for (int j = 0; j < heatSize; j++) {
                        int lane = j < lanePriority.Length ? lanePriority[j] : j;
                        var sw = newSwimmers[idx];
                        sw.Heat = maxHeat;
                        sw.Lane = lane;
                        sw.CurrentStage = stage;
                        sw.SetStageAssignment(stage, maxHeat, lane, sw.EntryTimeSeconds, sw.EntryTime);
                        AddLog(Loc.F("Str_Log_AppendAssignedFmt", sw.Name, maxHeat, lane));
                        idx++;
                        totalAdded++;
                    }
                }

                // 更新赛程表中的组数（不存在则新建）
                // 2026-06-16 加 AgeGroup 筛选, 不再误改其他组别的 HeatCount
                var schedItem = _schedule.FirstOrDefault(s => SgMatch(s.Gender, gender) && s.EventName == eventName
                    && s.Stage == stage && (s.AgeGroup ?? "") == ageGroup);
                if (schedItem != null) {
                    if (maxHeat > schedItem.HeatCount) schedItem.HeatCount = maxHeat;
                } else {
                    // 新项目：在赛程表中新建条目
                    _schedule.Add(new ScheduleItem {
                        SessionNumber = _schedule.Count > 0 ? _schedule.Max(s => s.SessionNumber) : 1,
                        AgeGroup = ageGroup,
                        Gender = gender,
                        EventName = eventName,
                        Stage = stage,
                        HeatCount = maxHeat
                    });
                    AddLog(Loc.F("Str_Log_AppendNewScheduleFmt", ageGroup, Loc.GenderDisplay(gender), eventName, Loc.StageDisplay(stage), maxHeat));
                }
            }

            BuildScheduleTree();
            SyncRelayHeatInfo();
            UpdateEditHeatCombo();
            // 2026-09-12 改过的项目逐项发补丁(第一条里已经带上落盘), 不推整包
            if (touchedEvents.Count == 0) AutoSaveData();
            else foreach (var te in touchedEvents) SaveAndPushAssign(te[0], te[1], te[2], te[3]);
            Broadcast();
            AddLog(Loc.F("Str_Log_AppendAssignCompletedFmt", totalAdded));
            string skipNote = skippedEvents.Count == 0 ? ""
                : Loc.F("Str_Msg_AppendGroupingSkippedFmt", string.Join("\n  ", skippedEvents.ToArray()));
            AppMessageBox.Show(Loc.F("Str_Msg_AppendGroupingDoneFmt", totalAdded, skipNote),
                Loc.T("Str_MsgTitle_AppendGroupingDone"), MessageBoxButton.OK, MessageBoxImage.Information);
        }

        /// <summary>
        /// 自动生成赛程和日程安排
        /// 根据报名人数确定赛次和预估组数，按游泳比赛惯例安排时间
        /// 上午预赛，下午半决赛，晚上决赛
        /// </summary>

        /// <summary>
        /// 根据项目名称估算每组比赛所需分钟数（含运动员检录出场、上道准备、比赛、间歇）
        /// 参考世界纪录成绩，考虑普通运动员较慢，加上赛间流程时间
        /// </summary>
        private static int EstimateMinutesPerHeat(string eventName) {
            bool isRelay = eventName.Contains("接力");
            // 解析距离：匹配 "50米"、"100米"、"1500米"、"4×100米" 等
            int distance = 0;
            var match = System.Text.RegularExpressions.Regex.Match(eventName, @"(\d+)米");
            if (match.Success) distance = int.Parse(match.Groups[1].Value);

            // 接力：实际比赛距离 = 单人距离 × 4
            int effectiveDistance = isRelay ? distance * 4 : distance;

            // 每组用时（分钟）= 预估比赛时间 + 赛间流程时间(检录、出场、上道、间歇约4分钟)
            // 50米:  ~35秒比赛 + 4分钟流程 ≈ 5分钟
            // 100米: ~1分15秒 + 4分钟 ≈ 6分钟
            // 200米: ~2分30秒 + 4分钟 ≈ 7分钟
            // 400米(含4×100接力): ~5分钟 + 5分钟 ≈ 10分钟
            // 800米(含4×200接力): ~10分钟 + 5分钟 ≈ 15分钟
            // 1500米: ~18分钟 + 4分钟 ≈ 22分钟
            if (effectiveDistance <= 50) return 5;
            if (effectiveDistance <= 100) return 6;
            if (effectiveDistance <= 200) return 7;
            if (effectiveDistance <= 400) return 10;
            if (effectiveDistance <= 800) return 15;
            return 22; // 1500米及以上
        }

        // ═══════════════════════════════════════════════════════════════
        // 成绩与排名
        // ═══════════════════════════════════════════════════════════════
        private bool _resultUpdating = false;
        private void ResultAgeGroup_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized && !_resultUpdating) { UpdateResultHeatCombo(); RefreshResultGrid(); } }
        private void ResultEvent_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized && !_resultUpdating) { UpdateResultHeatCombo(); RefreshResultGrid(); } }
        private void ResultStage_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized && !_resultUpdating) { UpdateResultHeatCombo(); RefreshResultGrid(); } }
        private void ResultGender_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized && !_resultUpdating) { UpdateResultHeatCombo(); RefreshResultGrid(); } }
        private void ResultHeat_Changed(object sender, SelectionChangedEventArgs e) { if (_initialized && !_resultUpdating) RefreshResultGrid(); }

        /// <summary>
        /// 2026-09-03 本项目这个赛次【一共几组】—— 组数列 "第X组/总组数" 的分母。
        /// 先问竞赛库(最准, 取消的组不算), 库里问不到再退回赛程上的名义组数。
        /// 拿"当前筛选看得见几组"当分母是错的: 选了第2组时那是 1, 会印成 "2/1"。
        /// </summary>
        private int TotalHeatsOfEvent(string ageFilter, string gender, string eventName, string stage) {
            if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(stage)) return 0;
            try {
                var ages = new List<string>();
                if (!string.IsNullOrEmpty(ageFilter) && ageFilter != Loc.T("Str_Common_All")) ages.Add(ageFilter);
                else {
                    foreach (var s in _swimmers) {
                        if (s.EventName != eventName) continue;
                        string a = s.AgeCategory ?? "";
                        if (!ages.Contains(a)) ages.Add(a);
                    }
                }
                int best = 0;
                foreach (string ag in ages) {
                    int t, p, r;
                    _meetDb.GetEventRankingProgress(ag, gender, eventName, stage, out t, out p, out r);
                    if (t > best) best = t;
                }
                if (best > 0) return best;
            } catch { }
            // 库不可用: 退回赛程上写的组数
            int hc = 0;
            try {
                foreach (var s in _schedule) {
                    if (s == null || s.EventName != eventName || s.Stage != stage) continue;
                    if (!SgMatch(s.Gender, gender)) continue;
                    if (!string.IsNullOrEmpty(ageFilter) && ageFilter != Loc.T("Str_Common_All") && (s.AgeGroup ?? "") != ageFilter) continue;
                    if (s.HeatCount > hc) hc = s.HeatCount;
                }
            } catch { }
            return hc;
        }

        private void UpdateResultHeatCombo() {
            if (ResultHeatCombo == null || _resultUpdating) return;
            _resultUpdating = true;
            try {
            // 记住当前选中的组号文本（如 "第2组" 或 "全部"），在重建下拉后尽量恢复
            string prevHeat = null;
            var prevHeatItem = ResultHeatCombo.SelectedItem as ComboBoxItem;
            if (prevHeatItem != null && prevHeatItem.Content != null) prevHeat = prevHeatItem.Content.ToString();

            // 刷新项目列表：只显示有运动员/运动队注册的项目（过滤接力队员个人条目）
            string prevEvent = ResultEventCombo.SelectedItem != null ? ResultEventCombo.SelectedItem.ToString() : "";
            string ageFilter = ResultAgeGroupCombo != null && ResultAgeGroupCombo.SelectedItem != null ? ResultAgeGroupCombo.SelectedItem.ToString() : Loc.T("Str_Common_All");
            string gender = ResultGenderCombo.SelectedItem != null ? ((ComboBoxItem)ResultGenderCombo.SelectedItem).Tag.ToString() : "男";
            ResultEventCombo.Items.Clear();
            var eventSet = new HashSet<string>();
            // 2026-06-01 男/女 选择时也包含混合性别接力项目, 与"出场编排微调"逻辑一致
            foreach (var s in _swimmers) {
                if (GenderMatchesIncludingMixed(s.Gender, gender) && !string.IsNullOrEmpty(s.EventName) &&
                    MatchesAgeGroup(s, ageFilter) &&
                    !(s.Notes != null && s.Notes.StartsWith("接力队员")))
                    eventSet.Add(s.EventName);
            }
            foreach (string ev in eventSet.OrderBy(x => x)) ResultEventCombo.Items.Add(ev);
            // 恢复之前选中的项目
            if (!string.IsNullOrEmpty(prevEvent) && ResultEventCombo.Items.Contains(prevEvent))
                ResultEventCombo.SelectedItem = prevEvent;
            else if (ResultEventCombo.Items.Count > 0)
                ResultEventCombo.SelectedIndex = 0;

            string eventName = ResultEventCombo.SelectedItem != null ? ResultEventCombo.SelectedItem.ToString() : "";
            string stage = ResultStageCombo.SelectedItem != null ? ((ComboBoxItem)ResultStageCombo.SelectedItem).Content.ToString() : "预赛";

            ResultHeatCombo.Items.Clear();
            ResultHeatCombo.Items.Add(new ComboBoxItem { Content = Loc.T("Str_Common_All") });

            // 只列出"已确认成绩"的组次：未确认（含正在比赛）的组在此不出现
            var heats = new HashSet<int>();
            string agForCheck = ageFilter == Loc.T("Str_Common_All") ? "" : ageFilter;
            foreach (var s in _swimmers) {
                if (!string.IsNullOrEmpty(eventName) && s.EventName != eventName) continue;
                if (!GenderMatchesIncludingMixed(s.Gender, gender)) continue;   // 2026-06-01 含混合
                if (!MatchesAgeGroup(s, ageFilter)) continue;
                if (s.Notes != null && s.Notes.StartsWith("接力队员")) continue;
                int candHeat = 0;
                var saH = s.GetAssignmentForStage(stage);
                if (saH != null && saH.Heat > 0) candHeat = saH.Heat;
                else if (s.CurrentStage == stage && s.Heat > 0) candHeat = s.Heat;
                if (candHeat <= 0) continue;
                if (heats.Contains(candHeat)) continue;
                if (IsHeatConfirmed(agForCheck, gender, eventName, stage, candHeat))
                    heats.Add(candHeat);
            }
            foreach (int h in heats.OrderBy(x => x)) {
                ResultHeatCombo.Items.Add(new ComboBoxItem { Content = string.Format("第{0}组", h) });
            }

            // 恢复之前选中的组号；找不到则回退到"全部"
            int restored = -1;
            if (!string.IsNullOrEmpty(prevHeat)) {
                for (int i = 0; i < ResultHeatCombo.Items.Count; i++) {
                    var ci = ResultHeatCombo.Items[i] as ComboBoxItem;
                    if (ci != null && ci.Content != null && ci.Content.ToString() == prevHeat) { restored = i; break; }
                }
            }
            ResultHeatCombo.SelectedIndex = restored >= 0 ? restored : 0;
            } finally {
                _resultUpdating = false;
            }
        }

        private void RefreshResultGrid() {
            // 2026-08-31 成绩与排名列表前先从库【增量】刷新 —— 别的计算机写的成绩才看得到。
            //   开销是一条轻查询; 没变动就一行成绩都不读。
            try { RefreshChangedFromDb(); } catch { }
            if (ResultEventCombo == null || ResultStageCombo == null || ResultGenderCombo == null || ResultGrid == null) return;
            string ageFilter = ResultAgeGroupCombo != null && ResultAgeGroupCombo.SelectedItem != null ? ResultAgeGroupCombo.SelectedItem.ToString() : Loc.T("Str_Common_All");
            string gender = ResultGenderCombo.SelectedItem != null ? ((ComboBoxItem)ResultGenderCombo.SelectedItem).Tag.ToString() : "男";
            string eventName = ResultEventCombo.SelectedItem != null ? ResultEventCombo.SelectedItem.ToString() : "";
            string stage = ResultStageCombo.SelectedItem != null ? ((ComboBoxItem)ResultStageCombo.SelectedItem).Content.ToString() : "预赛";
            string heatFilter = ResultHeatCombo != null && ResultHeatCombo.SelectedItem != null ? ((ComboBoxItem)ResultHeatCombo.SelectedItem).Content.ToString() : Loc.T("Str_Common_All");
            int filterHeat = 0;
            if (heatFilter != Loc.T("Str_Common_All")) {
                var m = System.Text.RegularExpressions.Regex.Match(heatFilter, @"\d+");
                if (m.Success) filterHeat = int.Parse(m.Value);
            }

            if (string.IsNullOrEmpty(eventName)) {
                ResultGrid.ItemsSource = null;
                return;
            }

            // 按组别/性别和项目筛选（接力项目只查代表队，不查个人队员）
            // 2026-06-01 男/女 选择时也匹配混合性别接力项目
            var allMatched = _swimmers.Where(s =>
                s.EventName == eventName && GenderMatchesIncludingMixed(s.Gender, gender) &&
                MatchesAgeGroup(s, ageFilter) &&
                !(s.Notes != null && s.Notes.StartsWith("接力队员"))
            ).ToList();

            // 按阶段筛选：有该阶段成绩，或有该阶段分组记录
            var results = allMatched.Where(s =>
                s.GetResultForStage(stage) != null ||
                s.GetAssignmentForStage(stage) != null ||
                s.CurrentStage == stage
            ).ToList();

            // 按组筛选：优先按"分组记录"判断该运动员属于哪组（同 stage 多个 result 时 GetResultForStage 不可靠）
            if (filterHeat > 0) {
                results = results.Where(s => {
                    var sa = s.GetAssignmentForStage(stage);
                    if (sa != null && sa.Heat > 0) return sa.Heat == filterHeat;
                    if (s.CurrentStage == stage && s.Heat > 0) return s.Heat == filterHeat;
                    // 兜底：按成绩里的 Heat 字段
                    var r = s.Results.FirstOrDefault(rx => rx.Stage == stage && rx.Heat == filterHeat);
                    return r != null;
                }).ToList();
            }

            // 只展示已确认成绩的组次：未确认的组（如正在比赛中）不在此处显示，
            // 等"确认成绩"按下后才会出现。这样裁判判罚/取消成绩时不会被提前看到。
            results = results.Where(s => {
                int hh = 0;
                var sa = s.GetAssignmentForStage(stage);
                if (sa != null && sa.Heat > 0) hh = sa.Heat;
                else if (s.CurrentStage == stage && s.Heat > 0) hh = s.Heat;
                if (hh <= 0) return false;
                return IsHeatConfirmed(ageFilter == Loc.T("Str_Common_All") ? "" : ageFilter, gender, eventName, stage, hh);
            }).ToList();

            // 2026-09-01 TRI(试游)按视图决定显不显:
            //   选【第X组】= 本组成绩单 -> 显成绩 + 备注 TRI + 无名次
            //   选【全部】 = 项目总排名 -> 这一行不出现(规则: 总排名列表中不显示 TRI)
            if (filterHeat <= 0) {
                results = results.Where(s =>
                    GetEffectiveStatus(s, s.GetResultForStage(stage)) != "TRI").ToList();
            }

            bool isRelayEvent = eventName.Contains("接力");
            // 接力赛棒次数：用于反应时按棒展开
            int rgLegCount = 4;
            if (isRelayEvent) {
                var mLeg = System.Text.RegularExpressions.Regex.Match(eventName, @"(\d+)\s*[x×]\s*\d+");
                if (mLeg.Success) {
                    int n; if (int.TryParse(mLeg.Groups[1].Value, out n) && n > 0 && n <= 10) rgLegCount = n;
                }
            }
            var rawResultRows = results.Select(s => {
                // 按运动员所属的组精确查找该组成绩（避免在 stage 内多组场景下取错）
                int swHeat = 0;
                var swSa = s.GetAssignmentForStage(stage);
                if (swSa != null && swSa.Heat > 0) swHeat = swSa.Heat;
                else if (s.CurrentStage == stage && s.Heat > 0) swHeat = s.Heat;
                LaneResult r = swHeat > 0
                    ? s.Results.FirstOrDefault(rx => rx.Stage == stage && rx.Heat == swHeat)
                    : s.GetResultForStage(stage);
                int lane = 0;
                if (r != null) lane = r.Lane;
                else {
                    var sa = s.GetAssignmentForStage(stage);
                    lane = sa != null ? sa.Lane : s.Lane;
                }
                // 2026-08-19 状态判定改用"有效状态" (成绩行 Status 优先, 否则运动员 Status),
                //   修 只在成绩行标了 DSQ (s.Status 空) 时 备注显 DSQ 但仍显成绩+占名次 的不一致.
                string effStatus = GetEffectiveStatus(s, r);
                bool isDQ = effStatus == "DSQ" || effStatus == "DNS" || effStatus == "DNF" || effStatus == "DQ";
                // 2026-08-19 TRI(试游) 正常显成绩但不排名次 (与大屏"组成绩"/成绩单一致);
                //   GetHeatStatusOrder != 5 = TRI/DSQ/DQ/DNF/DNS, 一律 SortTime=MaxValue → 名次列显 "-"
                int heatStatusOrder = GetHeatStatusOrder(effStatus);
                bool noRank = heatStatusOrder != 5;
                double sortTime = (!noRank && r != null && r.FinalTime > 0) ? r.FinalTime : double.MaxValue;
                double timeKey = (r != null && r.FinalTime > 0) ? r.FinalTime : double.MaxValue;
                // 接力项目：姓名显示四位队员姓名
                string displayName = s.Name ?? "";
                if (isRelayEvent && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:")) {
                    displayName = s.Notes.Substring("接力队 棒次:".Length);
                }
                string remark = "";
                if (r != null && !string.IsNullOrEmpty(r.Status)) remark = r.Status;
                else if (isDQ) remark = s.Status;
                // 2026-06-04 D 最终成绩 DataGrid 显 1-4 棒
                string reactionStr = "";
                // 2026-09-03 接力这一支原来漏了判罚守卫(个人项目那半边有 !isDQ)。
                //   DNF 的接力队成绩空着、名次是 "-", 反应时却还印着四棒数字。
                if (isRelayEvent && !isDQ) {
                    var rtParts = new List<string>();
                    for (int li = 0; li < rgLegCount; li++) {
                        double rt = (r != null && r.LegReactionTimes != null && li < r.LegReactionTimes.Count) ? r.LegReactionTimes[li] : 0;
                        rtParts.Add(string.Format("第{0}棒:{1}", li + 1, (rt != 0 && !double.IsNaN(rt)) ? rt.ToString("F2") : "—"));
                    }
                    reactionStr = string.Join("  ", rtParts.ToArray());
                } else if (r != null && r.StartingBlockTime != 0 && !double.IsNaN(r.StartingBlockTime) && !isDQ) {
                    // 2026-08-31 判罚/弃权不显示反应时间(与成绩单、项目成绩同口径)
                    reactionStr = r.StartingBlockTime.ToString("F2");
                }
                return new {
                    // 2026-09-01 名次【从库里读】: r.EventRank 是确认成绩时竞赛库算好、
                    //   回读进内存的(heat_entries.rank); 项目定稿后会被 event_rankings 覆盖。
                    //   这里不算名次, 只是把它带出去。
                    // 2026-09-01 【本组名次】和【项目总排名】是两回事, 不能混:
                    //   选了具体某一组 -> 显示【本组名次】(r.Rank, 库里 GetHeat 现算的组内名次)
                    //   选"全部"      -> 显示【项目总排名】(r.EventRank, 库里 heat_entries.rank)
                    //   上一版一律给了总排名, 于是按组看时名次成了总排名的名次(用户报的)。
                    //   两个值都来自竞赛库(确认成绩时回读进内存的), 这里仍然不算任何东西。
                    DbRank = (r == null ? 0 : (filterHeat > 0 ? r.Rank : r.EventRank)),
                    SortTime = sortTime,
                    StatusOrder = heatStatusOrder,        // 2026-08-19 无名次者之间的次序 (TRI→DSQ→DNF→DNS→其他)
                    TimeKey = timeKey,                    // 2026-08-19 同类内按成绩快慢 (多名 TRI 时)
                    Lane = lane,
                    BibNumber = s.BibNumber ?? "",
                    Name = displayName,                  // 接力时为 4 名队员姓名（逗号分隔）
                    Country = s.Country ?? "",            // 代表队/队名
                    // 2026-09-02 补 组别/组数/成绩差 三列(与"项目成绩"同款)。
                    //   一张表跨多个组次时, 原来看不出某一行是第几组的, 也看不出属于哪个组别。
                    AgeGroup = s.AgeCategory ?? "",
                    HeatNo = swHeat,
                    // 成绩差的基准只认【有名次的有效成绩】: 判罚/弃权/试游不参与, 也不当基准
                    RawTime = (isDQ || heatStatusOrder != 5 || r == null) ? 0 : r.FinalTime,
                    FinalTime = isDQ ? "" : (r != null && r.FinalTime > 0 ? TimeFormatter.Format(r.FinalTime) : ""),
                    TimingSource = r != null ? (r.TimingSource ?? "") : "",
                    ReactionTime = reactionStr,
                    Status = !string.IsNullOrEmpty(remark) ? remark : (s.Status ?? ""),
                    RecordNote = r != null ? (r.RecordNote ?? "") : ""
                };
            }).ToList();

            // 2026-09-16 "全部"(项目总排名) 改调统一入口 ResultOrdering.RankForTotalView ——
            //   跟成绩册名次公告(GetEventFinalRanking)/项目成绩打印"全部"视图是同一份规则、
            //   同一处维护, 不再在这里单独写一遍排序链。
            //   "第X组"(本组名次)不是总排名, 维持原来那条排序链不动:
            //   2026-06-22 次级排序: 同 SortTime (= 都是 DSQ/DNS/DNF 的 MaxValue) 时按 DSQ→DNF→DNS→其他 排
            //   2026-08-19 改用 GetHeatStatusOrder: TRI 插到 DSQ 之前 (TRI 有成绩只是不排名),
            //   与大屏"组成绩"(display.html _hrCompare) / 本组成绩单 完全同口径.
            List<int> dispRanks = new List<int>();
            var displayData = rawResultRows;
            if (filterHeat <= 0) {
                displayData = ResultOrdering.RankForTotalView(rawResultRows,
                    x => x.Status, x => x.DbRank, x => x.SortTime, out dispRanks);
            } else {
                displayData = rawResultRows.OrderBy(x => x.SortTime)
                    .ThenBy(x => x.DbRank > 0 ? x.DbRank : int.MaxValue)   // 2026-09-01 先按库里的名次
                    .ThenBy(x => x.StatusOrder)
                    .ThenBy(x => x.TimeKey)
                    .ThenBy(x => x.Lane)
                    .ToList();
                dispRanks = displayData.Select(x => x.DbRank).ToList();
            }

            // 重新计算排名（TRI/DSQ/DNS/DNF 无名次, SortTime 已置 MaxValue）；列与表头一一对应：
            //   "姓名"列 -> Name（接力时即 4 棒队员姓名）
            //   "代表队"列 -> Country（队名）
            // 2026-09-01 原来这里是【行号】当名次(rankNum++), 成绩相同的两人被排成 1 和 2 ——
            //   用户在"成绩与排名"里实拍到的 1,2,3...11 就是它, 而同一份成绩在项目成绩里
            //   是 1,1,1,4,4... 三个地方三个答案。
            //   现在一律读库里的名次(DbRank), 库里没有就显示 "-" —— 这里不再算任何东西。
            // 2026-09-03 组数列是"第几组/【本项目总组数】"。
            //   原来拿的是"当前筛选看得见几组" —— 选了"第2组"时那是 1, 印成 "2/1"。
            int totalHeatsInView = TotalHeatsOfEvent(ageFilter, gender, eventName, stage);
            if (totalHeatsInView <= 0) {
                try {
                    var hset = new HashSet<int>();
                    foreach (var x in displayData) if (x.HeatNo > 0) hset.Add(x.HeatNo);
                    totalHeatsInView = hset.Count;
                } catch { }
            }
            // 成绩差按【组别】各算各的: 选"全部"时几个组别混在一张表里,
            //   拿全表最快当基准就等于把别的组别的人当成了自己的第一名。
            var leaderByAge = new Dictionary<string, double>();
            foreach (var x in displayData) {
                if (x.RawTime <= 0) continue;
                string k = x.AgeGroup ?? "";
                double cur;
                if (!leaderByAge.TryGetValue(k, out cur) || x.RawTime < cur) leaderByAge[k] = x.RawTime;
            }

            var rankedData = new List<object>();
            for (int riIdx = 0; riIdx < displayData.Count; riIdx++) {
                var item = displayData[riIdx];
                int itemRank = (riIdx < dispRanks.Count) ? dispRanks[riIdx] : item.DbRank;
                string rankStr = itemRank > 0 ? itemRank.ToString() : "-";
                string heatText = item.HeatNo > 0
                    ? (totalHeatsInView > 0 ? item.HeatNo + "/" + totalHeatsInView : item.HeatNo.ToString())
                    : "";
                string diffText = "";
                double lead;
                if (item.RawTime > 0 && leaderByAge.TryGetValue(item.AgeGroup ?? "", out lead)
                    && item.RawTime > lead)
                    diffText = (item.RawTime - lead).ToString("F2");
                rankedData.Add(new {
                    Rank = rankStr,
                    item.Lane, item.BibNumber,
                    item.Name, item.Country,
                    item.AgeGroup,
                    HeatText = heatText,
                    item.FinalTime,
                    Diff = diffText,
                    item.TimingSource, item.ReactionTime, item.Status, item.RecordNote
                });
            }

            ResultGrid.ItemsSource = rankedData;
        }

        private void PublishResult_Click(object sender, RoutedEventArgs e) {
            // 2026-08-31 公布成绩到大屏前先从库【增量】刷新 —— 别的计算机写的成绩才看得到。
            //   开销是一条轻查询; 没变动就一行成绩都不读。
            try { RefreshChangedFromDb(); } catch { }
            // 弹出窗口选择已完赛项目的组成绩发布到大屏
            var dlg = new Window {
                Title = Loc.T("Str_Win_PublishResult_Title"), Width = 500, Height = 420,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize
            };
            var sp = new StackPanel { Margin = new Thickness(16) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_PublishResult_Hint"), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 10) });

            // 收集所有已完赛的组
            var completedHeats = new List<object>();
            var completedLabels = new List<string>();
            foreach (var schedItem in _schedule) {
                int hc = schedItem.HeatCount > 0 ? schedItem.HeatCount : 1;
                // 2026-06-01 IsHeatConfirmed 必须带 AgeGroup, 否则跨年龄组同 Heat# 会误判 (本次决赛-only 多组别共用 EventName 时尤甚)
                string ageG = schedItem.AgeGroup ?? "";
                for (int h = 1; h <= hc; h++) {
                    if (IsHeatConfirmed(ageG, schedItem.Gender, schedItem.EventName, schedItem.Stage, h)) {
                        completedHeats.Add(new { AgeGroup = ageG, Gender = schedItem.Gender, EventName = schedItem.EventName, Stage = schedItem.Stage, Heat = h, HeatCount = hc });
                        bool showHeat = (hc > 1) || schedItem.Stage.Contains("预赛") || schedItem.Stage.Contains("半决赛");
                        string heatLabel = showHeat ? string.Format(" 第{0}组", h) : "";
                        string ageHead = string.IsNullOrEmpty(ageG) ? "" : (ageG + " ");
                        completedLabels.Add(string.Format("{0}{1} {2} {3}{4}", ageHead, schedItem.Gender, schedItem.EventName, schedItem.Stage, heatLabel));
                    }
                }
            }

            var listBox = new ListBox { Height = 250, FontSize = 14 };
            if (completedHeats.Count == 0) {
                listBox.Items.Add("（暂无已完赛的比赛）");
                listBox.IsEnabled = false;
            } else {
                foreach (string label in completedLabels) listBox.Items.Add(label);
            }
            sp.Children.Add(listBox);

            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var btnOk = new Button { Content = Loc.T("Str_Btn_PublishToScreen"), Padding = new Thickness(16, 6, 16, 6), FontSize = 14, Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")), Foreground = new SolidColorBrush(Colors.White), FontWeight = FontWeights.Bold, BorderThickness = new Thickness(0) };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            var btnClose = new Button { Content = Loc.T("Str_Btn_Close"), Padding = new Thickness(16, 6, 16, 6), FontSize = 14,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = new SolidColorBrush(Colors.White), BorderThickness = new Thickness(0) };
            btnClose.Click += delegate { dlg.DialogResult = false; };
            btnPanel.Children.Add(btnOk);
            btnPanel.Children.Add(btnClose);
            sp.Children.Add(btnPanel);
            dlg.Content = sp;

            if (dlg.ShowDialog() == true && listBox.SelectedIndex >= 0 && listBox.SelectedIndex < completedHeats.Count) {
                dynamic sel = completedHeats[listBox.SelectedIndex];
                // 2026-06-16 fix: 传 AgeGroup 修跨组别污染
                PublishResultToDisplay((string)sel.AgeGroup, (string)sel.Gender, (string)sel.EventName, (string)sel.Stage, (int)sel.Heat);
            }
        }

        // 2026-06-04 PublishResult / Broadcast 用: 接力赛拼 1-4 棒, 个人单值
        private static string BuildReactionFieldForPublish(string eventName, LaneResult r) {
            if (r == null) return "";
            // 2026-09-03 判罚/弃权一律不发反应时 —— 这一句原来在接力分支【后面】,
            //   于是个人项目挡住了、接力没挡住, 大屏上 DNF 的接力队照样显示四棒反应时。
            if (r.Status == "DSQ" || r.Status == "DQ" || r.Status == "DNF" || r.Status == "DNS") return "";
            bool isRelay = !string.IsNullOrEmpty(eventName) && eventName.Contains("接力");
            if (isRelay) {
                if (r.LegReactionTimes == null || r.LegReactionTimes.Count == 0) return "";
                var parts = new List<string>();
                for (int li = 0; li < r.LegReactionTimes.Count; li++) {
                    double rt = r.LegReactionTimes[li];
                    parts.Add(string.Format("第{0}棒:{1}", li + 1, (rt != 0 && !double.IsNaN(rt)) ? rt.ToString("F2") : "—"));
                }
                return string.Join(" ", parts.ToArray());
            }
            return r.StartingBlockTime != 0 && !double.IsNaN(r.StartingBlockTime) ? r.StartingBlockTime.ToString("F2") : "";
        }

        /// <summary>
        /// 将指定组的成绩发布到大屏（供EXE按钮和HTML远程调用）
        /// </summary>
        // 2026-06-16 加 ageGroup 参数: 修发布成绩跨组别污染 bug (PublishResult_Click 选中明明是某组别,
        //   但调用 PublishResultToDisplay 漏传 → 内部按 gender+eventName+stage+heat 筛选会命中所有 AgeGroup,
        //   导致 display.html 显示超过 8/10 个运动员且部分不属于本组).
        //   传 ageGroup="" 时退回兼容 (不按组别过滤, 用于不分组的赛事).
        private void PublishResultToDisplay(string ageGroup, string gender, string eventName, string stage, int heat) {
            var heatSwimmers = new List<object>();
            var schedItem = _schedule.FirstOrDefault(s => SgMatch(s.Gender, gender) && s.EventName == eventName && s.Stage == stage
                && (string.IsNullOrEmpty(ageGroup) || (s.AgeGroup ?? "") == ageGroup));
            int heatCount = schedItem != null ? schedItem.HeatCount : 1;

            // 2026-10-08 用户明确要求: 发布到大屏的成绩(不分个人/接力)一律以分组表数据库
            // 为准——改成直接调 GetHeatEntries()(唯一权威入口: 先查 heat_entries 库,
            // 查不到才退回内存 StageAssignment), 不再在这里自己另开一份"谁在这组"的
            // 判定逻辑, 两处各算一次正是用户点名的根因。
            foreach (var s in GetHeatEntries(ageGroup, gender, eventName, stage, heat)) {
                var sa = s.GetAssignmentForStage(stage);
                var r = s.GetResultForStage(stage);
                int lane = sa != null ? sa.Lane : s.Lane;
                // 接力项目：name显示队员姓名
                string dispName = s.Name ?? "";
                if (eventName.Contains("接力") && !string.IsNullOrEmpty(s.Notes) && s.Notes.StartsWith("接力队 棒次:")) {
                    dispName = s.Notes.Substring("接力队 棒次:".Length);
                }
                bool isDQ = s.Status == "DSQ" || s.Status == "DNS" || s.Status == "DNF";
                heatSwimmers.Add(new {
                    lane = lane,
                    name = dispName,
                    country = s.Country ?? "",
                    bibNumber = s.BibNumber ?? "",
                    finalTime = !isDQ && r != null && r.FinalTime > 0 ? TimeFormatter.Format(r.FinalTime) : "",
                    rank = isDQ ? 0 : (r != null ? r.Rank : 0),
                    status = s.Status ?? "",
                    resultStatus = r != null ? (r.Status ?? "") : "",
                    gender = s.Gender ?? "",                   // 2026-06-04 男女 并项 display.html 用
                    ageGroup = s.AgeCategory ?? "",
                    recordNote = r != null ? (r.RecordNote ?? "") : "",
                    // 2026-06-04 PublishResult 接力赛发 4 棒拼接 (= 显 1-4), 个人发单值
                    reactionTime = BuildReactionFieldForPublish(eventName, r)
                });
            }

            bool showHeatNum = (heatCount > 1) || stage.Contains("预赛") || stage.Contains("半决赛");
            string heatDisplay = showHeatNum ? string.Format(" 第{0}组", heat) : "";

            var publishData = new {
                type = "SHOW_PUBLISHED_RESULT",
                data = new {
                    competitionName = _competitionName,
                    gender = gender,
                    eventName = eventName,
                    stage = stage,
                    heat = heat,
                    heatDisplay = heatDisplay,
                    swimmers = heatSwimmers,
                    poolConfig = new { lanes = _poolConfig.LaneCount },
                    applicableRecords = BuildApplicableRecords(eventName, gender, !string.IsNullOrEmpty(ageGroup) ? ageGroup : (schedItem != null ? schedItem.AgeGroup : null))   // 2026-06-16 按传入 ageGroup 过滤纪录, 兜底用 schedItem.AgeGroup
                }
            };
            string json = Newtonsoft.Json.JsonConvert.SerializeObject(publishData);
            AddLog(Loc.F("Str_Log_PublishedResultFmt",
                gender, eventName, stage, heatDisplay, heatSwimmers.Count,
                IsRemoteTimingControlMode ? " (经主服务器转发)" : (", 发送到" + _allSockets.Count + "个连接")));
            BroadcastJsonToClients(json);
        }

        private void Promotion_Click(object sender, RoutedEventArgs e) {
            RefreshChangedFromDb();   // 2026-08-31 开报表前先从库刷新, 别的计算机写的成绩才看得到
            // 2026-09-12 晋级窗口是直接改内存的, 关了之后拍照一比, 变了哪几项发哪几项的补丁。
            //   半决赛/决赛分组恰恰是比赛中最常做的事 —— 这条路必须不推整包。
            var before = SnapshotAssignments();
            var win = new PromotionQueryWindow(_swimmers, _events, _poolConfig, _schedule);
            win.Owner = this;
            win.ShowDialog();
            // 晋级处理后刷新相关界面
            BuildScheduleTree();
            UpdateResultHeatCombo();
            RefreshResultGrid();
            UpdateEditHeatCombo();
            SaveWithoutPush();
            PushChangedAssignments(before);
            Broadcast();
        }

