        // 2026-05-24 项目用时设置
        private void DurationConfig_Click(object sender, RoutedEventArgs e) {
            var wnd = new EventDurationConfigWindow(_durationConfig) { Owner = this };
            if (wnd.ShowDialog() == true) {
                AutoSaveData();
                AddLog(Loc.T("Str_Log_EventDurationConfigUpdated"));
            }
        }

        private void ScoringConfigCore() {
            var dlg = new Window {
                Title = Loc.T("Str_Win_ScoringConfig_Title2"),
                Width = 720, Height = 560,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this,
                ResizeMode = ResizeMode.CanResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F1F5F9"))
            };
            var root = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Padding = new Thickness(14) };
            var sp = new StackPanel { Orientation = Orientation.Vertical };

            sp.Children.Add(new TextBlock {
                Text = Loc.T("Str_TeamScore_Desc"),
                FontSize = 12, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")),
                Margin = new Thickness(0, 0, 0, 12), TextWrapping = TextWrapping.Wrap
            });

            // 取分人数 + 破纪录加分（顶部一行）
            var topRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 12) };
            topRow.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_TopNLabel"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 6, 0) });
            var cutoffBox = new TextBox { Text = _scoringConfig.RankCutoff.ToString(), Width = 60, VerticalAlignment = VerticalAlignment.Center };
            topRow.Children.Add(cutoffBox);
            topRow.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_RecordBonusLabel"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(20, 0, 6, 0) });
            var bonusBox = new TextBox { Text = _scoringConfig.RecordBreakBonus.ToString("0.##"), Width = 60, VerticalAlignment = VerticalAlignment.Center };
            topRow.Children.Add(bonusBox);
            sp.Children.Add(topRow);

            // 2026-05-23 编排种子组数（FINA SW 3.1.1.4/3.1.1.5）— 用户可配置
            sp.Children.Add(new TextBlock {
                Text = Loc.T("Str_TeamScore_SeedingParamsHeader"),
                FontSize = 14, FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E40AF")),
                Margin = new Thickness(0, 4, 0, 4)
            });
            var seedHintBox = new TextBlock {
                Text = Loc.T("Str_TeamScore_FinaStandardDesc"),
                FontSize = 11, Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 4)
            };
            sp.Children.Add(seedHintBox);
            var seedRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 12) };
            seedRow.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_ShortDistSeedLabel"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 6, 0) });
            int sShort = _scoringConfig.SeedHeatsCountShort > 0 ? _scoringConfig.SeedHeatsCountShort : 3;
            var seedShortBox = new TextBox { Text = sShort.ToString(), Width = 50, VerticalAlignment = VerticalAlignment.Center };
            seedRow.Children.Add(seedShortBox);
            seedRow.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_LongDistSeedLabel"), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(20, 0, 6, 0) });
            int sLong = _scoringConfig.SeedHeatsCountLong > 0 ? _scoringConfig.SeedHeatsCountLong : 2;
            var seedLongBox = new TextBox { Text = sLong.ToString(), Width = 50, VerticalAlignment = VerticalAlignment.Center };
            seedRow.Children.Add(seedLongBox);
            sp.Children.Add(seedRow);

            // 个人项目名次分（每名次一个 TextBox，按取分人数限定个数；多于 cutoff 时仍允许编辑保留历史值）
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_IndividualPointsHeader"), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 8, 0, 4) });
            var indPanel = new WrapPanel { Margin = new Thickness(0, 0, 0, 12) };
            var indBoxes = new List<TextBox>();
            int maxRanks = Math.Max(8, Math.Max(_scoringConfig.IndividualPoints.Count, _scoringConfig.RelayPoints.Count));
            for (int i = 0; i < maxRanks; i++) {
                var item = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 12, 6) };
                item.Children.Add(new TextBlock { Text = Loc.F("Str_Fmt_RankColonLabel", i + 1), VerticalAlignment = VerticalAlignment.Center, Width = 56, TextAlign​ment = TextAlignment.Right });
                double v = i < _scoringConfig.IndividualPoints.Count ? _scoringConfig.IndividualPoints[i] : 0;
                var tb = new TextBox { Text = v.ToString("0.##"), Width = 60, VerticalAlignment = VerticalAlignment.Center };
                indBoxes.Add(tb);
                item.Children.Add(tb);
                indPanel.Children.Add(item);
            }
            sp.Children.Add(indPanel);

            // 接力项目名次分
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_RelayPointsHeader"), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 8, 0, 4) });
            var relayPanel = new WrapPanel { Margin = new Thickness(0, 0, 0, 12) };
            var relayBoxes = new List<TextBox>();
            for (int i = 0; i < maxRanks; i++) {
                var item = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 12, 6) };
                item.Children.Add(new TextBlock { Text = Loc.F("Str_Fmt_RankColonLabel", i + 1), VerticalAlignment = VerticalAlignment.Center, Width = 56, TextAlignment = TextAlignment.Right });
                double v = i < _scoringConfig.RelayPoints.Count ? _scoringConfig.RelayPoints[i] : 0;
                var tb = new TextBox { Text = v.ToString("0.##"), Width = 60, VerticalAlignment = VerticalAlignment.Center };
                relayBoxes.Add(tb);
                item.Children.Add(tb);
                relayPanel.Children.Add(item);
            }
            sp.Children.Add(relayPanel);

            // 组别系数（含已有的 + 当前比赛实际出现的所有 AgeCategory）
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_TeamScore_GroupCoefficientHeader"), FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 8, 0, 4) });
            var ageGroupKeys = new SortedSet<string>(_scoringConfig.AgeGroupCoefficients.Keys);
            foreach (var s in _swimmers) if (!string.IsNullOrEmpty(s.AgeCategory)) ageGroupKeys.Add(s.AgeCategory);
            var coeffPanel = new WrapPanel { Margin = new Thickness(0, 0, 0, 12) };
            var coeffBoxes = new Dictionary<string, TextBox>();
            foreach (var key in ageGroupKeys) {
                var item = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 12, 6) };
                item.Children.Add(new TextBlock { Text = key + "：", VerticalAlignment = VerticalAlignment.Center, MinWidth = 60, TextAlignment = TextAlignment.Right });
                double v = _scoringConfig.GetAgeCoefficient(key);
                var tb = new TextBox { Text = v.ToString("0.##"), Width = 60, VerticalAlignment = VerticalAlignment.Center };
                coeffBoxes[key] = tb;
                item.Children.Add(tb);
                coeffPanel.Children.Add(item);
            }
            sp.Children.Add(coeffPanel);

            // 按钮行
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var btnReset = new Button { Content = Loc.T("Str_Btn_ResetDefault"), Padding = new Thickness(16, 6, 16, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnReset.Click += delegate {
                if (AppMessageBox.Show(Loc.T("Str_Msg_ConfirmResetScoringDefaults"),
                    Loc.T("Str_MsgTitle_ResetDefaults"), MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes) {
                    _scoringConfig.ResetToDefaults();
                    dlg.DialogResult = false;
                    dlg.Close();
                    ScoringConfigCore();   // 重新打开载入默认值（直接 Core 复用外层已占的锁）
                }
            };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(20, 6, 20, 6), Margin = new Thickness(0, 0, 8, 0),
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            var btnOK = new Button { Content = Loc.T("Str_Btn_SaveRecalc"), Padding = new Thickness(20, 6, 20, 6), FontWeight = FontWeights.Bold,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#22C55E")), Foreground = Brushes.White, BorderThickness = new Thickness(0) };
            btnOK.Click += delegate {
                int cutoff;
                if (!int.TryParse(cutoffBox.Text.Trim(), out cutoff) || cutoff < 1 || cutoff > 50) {
                    AppMessageBox.Show(Loc.T("Str_Msg_RankCutoffRange"), Loc.T("Str_MsgTitle_InputError"), MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                double bonus;
                if (!double.TryParse(bonusBox.Text.Trim(), out bonus) || bonus < 0) bonus = 0;

                var indPoints = new List<double>();
                foreach (var tb in indBoxes) { double p; double.TryParse(tb.Text.Trim(), out p); indPoints.Add(p); }
                var relayPoints = new List<double>();
                foreach (var tb in relayBoxes) { double p; double.TryParse(tb.Text.Trim(), out p); relayPoints.Add(p); }
                var coeffs = new Dictionary<string, double>();
                foreach (var kv in coeffBoxes) { double c; if (double.TryParse(kv.Value.Text.Trim(), out c) && c > 0) coeffs[kv.Key] = c; }

                // 2026-05-23 种子组数（FINA SW 3.1.1.4）— 1..10 范围安全保护
                int seedSh, seedLo;
                if (!int.TryParse(seedShortBox.Text.Trim(), out seedSh) || seedSh < 1 || seedSh > 10) seedSh = 3;
                if (!int.TryParse(seedLongBox.Text.Trim(), out seedLo)  || seedLo < 1 || seedLo > 10) seedLo = 2;

                _scoringConfig.RankCutoff = cutoff;
                _scoringConfig.RecordBreakBonus = bonus;
                _scoringConfig.IndividualPoints = indPoints;
                _scoringConfig.RelayPoints = relayPoints;
                _scoringConfig.AgeGroupCoefficients = coeffs;
                _scoringConfig.SeedHeatsCountShort = seedSh;
                _scoringConfig.SeedHeatsCountLong  = seedLo;

                CalculateTeamScores();
                AutoSaveData();
                AddLog(Loc.F("Str_Log_PointsConfigUpdatedFmt",
                    cutoff, string.Join(",", indPoints.Take(cutoff).ToArray()), string.Join(",", relayPoints.Take(cutoff).ToArray()),
                    seedSh, seedLo));
                dlg.DialogResult = true;
            };
            btnRow.Children.Add(btnReset); btnRow.Children.Add(btnCancel); btnRow.Children.Add(btnOK);
            sp.Children.Add(btnRow);

            root.Content = sp;
            dlg.Content = root;
            dlg.ShowDialog();
        }

        // ═══════════════════════════════════════════════════════════════
        // 团体计分
        // ═══════════════════════════════════════════════════════════════
        /// <summary>
        /// 2026-09-16 "裁判长改成绩" —— 最高权限、跳过「解锁本组成绩」状态检查的最后一道口子。
        ///
        /// 起因: 一个几周前(08-22/23)就已经[已完赛]的历史项目, 现在重新装载档案后点
        /// 「解锁本组成绩」被挡住(内存里的 _confirmedHeats 快照跟赛程树显示的[已完赛]
        /// 状态对不上, 走不到能改成绩那一步)。用户明确要求: 在"成绩与排名"界面加一个
        /// 裁判长专用、进入要密码的窗口, 能直接改选定项目第X组的成绩, 确认写库/取消不存。
        ///
        /// 用当前"成绩与排名"筛选框里已经选好的 组别/性别/项目/阶段/组, 跟这个 Tab
        /// 平时查成绩用的是同一份筛选状态, 不用再建一套选择器。
        /// </summary>
        private void ChiefJudgeOverride_Click(object sender, RoutedEventArgs e) {
            if (ResultEventCombo == null || ResultStageCombo == null || ResultGenderCombo == null) return;
            string ageFilter = ResultAgeGroupCombo != null && ResultAgeGroupCombo.SelectedItem != null ? ResultAgeGroupCombo.SelectedItem.ToString() : Loc.T("Str_Common_All");
            string gender = ResultGenderCombo.SelectedItem != null ? ((ComboBoxItem)ResultGenderCombo.SelectedItem).Tag.ToString() : "男";
            string eventName = ResultEventCombo.SelectedItem != null ? ResultEventCombo.SelectedItem.ToString() : "";
            string stage = ResultStageCombo.SelectedItem != null ? ((ComboBoxItem)ResultStageCombo.SelectedItem).Content.ToString() : "预赛";
            string heatFilter = ResultHeatCombo != null && ResultHeatCombo.SelectedItem != null ? ((ComboBoxItem)ResultHeatCombo.SelectedItem).Content.ToString() : Loc.T("Str_Common_All");

            if (string.IsNullOrEmpty(eventName)) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectFiltersForChiefJudge"), Loc.T("Str_MsgTitle_ChiefJudgeEdit"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            int heat = 0;
            if (heatFilter != Loc.T("Str_Common_All")) {
                var m = System.Text.RegularExpressions.Regex.Match(heatFilter, @"\d+");
                if (m.Success) heat = int.Parse(m.Value);
            }
            if (heat <= 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_SelectSpecificHeatForChiefJudge"),
                    Loc.T("Str_MsgTitle_ChiefJudgeEdit"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            if (!PromptChiefJudgePassword()) return;

            string ag2 = (ageFilter == Loc.T("Str_Common_All")) ? "" : ageFilter;
            var win = new JudgeOverrideWindow(_meetDb, ag2, gender, eventName, stage, heat) { Owner = this };
            win.AfterSaved = delegate(string ag3, string gd3, string ev3, string st3, int heat3) {
                // 2026-09-16 先把这一组从竞赛库强制刷新回内存(不带"只加不删"防抖) ——
                //   顺序很重要: 必须在下面重新生成组排名表之前刷, 不然"组排名表"是拿着
                //   内存里没刷新的旧状态(比如还是 TRI)去生成的, 生成完了名次还是错的。
                try { ForceRefreshHeatAfterJudgeOverride(ag3, gd3, ev3, st3, heat3); } catch (Exception ex) { AddLog(Loc.F("Str_Log_RefereeOverrideRefreshFailedFmt", ex.Message)); }
                try {
                    // 项目已经全部组确认过的话, 这次改动要同步进"组排名表"(定稿) ——
                    // 跟正常确认路径同一份逻辑, 不弹窗(裁判长刚在上一个窗口点头确认过了)。
                    int made = _meetDb.GenerateEventRankingIfComplete(ag3, gd3, ev3, st3, Environment.MachineName + "(裁判长改成绩)", null);
                    if (made > 0) AppendTriPlaceholdersToEventRanking(ag3, gd3, ev3, st3);
                } catch (Exception ex) { AddLog(Loc.F("Str_Log_RefereeOverrideRankingFailedFmt", ex.Message)); }
                try { ApplyEventRankingsFromDb(); } catch { }
                try { BuildScheduleTree(); } catch { }
                try { RefreshResultGrid(); } catch { }
                try { Broadcast(); } catch { }
            };
            win.ShowDialog();
        }

        /// <summary>裁判长改成绩的密码门 —— 跟 query.html/register.html 用同一套系统账号密码(AuthHelper)。</summary>
        private bool PromptChiefJudgePassword() {
            var win = new Window {
                Title = Loc.T("Str_Win_ChiefJudgeAuth_Title"), Width = 380, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, ResizeMode = ResizeMode.NoResize, Owner = this
            };
            var root = new StackPanel { Margin = new Thickness(18) };
            root.Children.Add(new TextBlock {
                // 2026-09-16 这个密码是"裁判长改成绩"专用的一套(chief_judge_credentials.json),
                //   跟系统账号密码(admin/xxx)是分开的两套 —— 用同一套的话就等于知道系统密码
                //   的人(现场好几台机器的操作员)都能直接改库了, 达不到"只给裁判长用"的要求。
                Text = Loc.T("Str_ChiefJudge_AuthDesc"),
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 12)
            });
            var pwdBox = new PasswordBox { FontSize = 14, Padding = new Thickness(4) };
            root.Children.Add(pwdBox);
            var tip = new TextBlock { Foreground = Brushes.Firebrick, Margin = new Thickness(0, 8, 0, 0), TextWrapping = TextWrapping.Wrap };
            root.Children.Add(tip);
            var btns = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 14, 0, 0) };
            bool ok2 = false;
            var okBtn = new Button { Content = Loc.T("Str_Btn_OK"), Width = 90, Height = 30, Margin = new Thickness(0, 0, 8, 0), IsDefault = true };
            var cancelBtn = new Button { Content = Loc.T("Str_Btn_Cancel"), Width = 80, Height = 30, IsCancel = true };
            okBtn.Click += delegate {
                if (!AuthHelper.VerifyChiefJudgePassword(pwdBox.Password)) {
                    tip.Text = Loc.T("Str_ChiefJudge_WrongPassword");
                    pwdBox.Password = ""; pwdBox.Focus();
                    return;
                }
                ok2 = true; win.DialogResult = true;
            };
            btns.Children.Add(okBtn); btns.Children.Add(cancelBtn);
            root.Children.Add(btns);
            win.Content = root;
            pwdBox.Focus();
            win.ShowDialog();
            return ok2;
        }

        /// <summary>"设置"标签页→"裁判长权限"→"设置/修改 裁判长改成绩密码"。</summary>
        private void ChiefJudgePassword_Click(object sender, RoutedEventArgs e) {
            var win = new ChiefJudgePasswordWindow { Owner = this };
            win.ShowDialog();
        }

        // 2026-09-21 "设置"页中文/English按钮——第一阶段：只切标签页标题和"设置"页本身
        // (走 DynamicResource, 立即生效, 见 Localization.cs 顶部说明)。系统日志/弹窗等
        // 仍是硬编码中文, 不受这个按钮影响, 这里补一条日志说明白, 别让人以为按了没反应。
        private void LanguageToggle_Click(object sender, RoutedEventArgs e) {
            Loc.Toggle();
            RefreshAllForLanguageChange();
            // 2026-09-21 这条日志本身就是随每个阶段的翻译范围在扩大——写成"已覆盖到第几阶段"
            // 而不是逐页罗列，省得每加一个页面又要来改一遍这行文字。
            AddLog(Loc.CurrentLanguage == Loc.En
                ? "界面语言已切换为 English（标签页/设置页/比赛控制页/赛事管理与报名/成绩与排名/文档编辑输出打印/系统日志与数据 页面及赛程导航状态标签已生效；系统日志正文/弹窗提示仍为中文，后续阶段逐步覆盖）"
                : "界面语言已切换为中文");
            // 2026-09-28【跨客户端语言同步】只有真身主服务器点这个按钮才是权威指令, 要广播给
            //   ScheduleEditor.exe/RemoteTimingControl.exe/RegistrationTool.exe/RemoteDisplayControl.exe
            //   这几个桌面客户端跟随; 这两个"编排/计时"模式的实例本身也共用这份代码、同样能点到
            //   这个按钮, 但那只是操作员在这台机器上顺手切一下本机显示, 不代表权威指令, 不广播——
            //   避免编排端/计时端随手一点就把全场其它客户端的语言带偏。
            if (!IsScheduleEditorMode && !IsRemoteTimingControlMode) {
                BroadcastLanguageSync();
            }
        }

        /// <summary>2026-09-21 起沿用的"切语言后本机要重刷的东西"级联——原来只有
        /// LanguageToggle_Click 一处调用, 2026-09-28【跨客户端语言同步】加了第二处调用者
        /// (ScheduleEditor.exe/RemoteTimingControl.exe 收到主服务器 LANGUAGE_SYNC 推送时), 抽成
        /// 独立方法, 两处共用, 不用维护两份重复的"点了什么按钮该刷新什么"清单。</summary>
        private void RefreshAllForLanguageChange() {
            // "比赛控制"页几个按钮的文字是跟着状态变的(停表/继续走表、记录显示/已隐藏、
            // RT On/Off、网络连接/断开、设备测试/退出测试)——它们的刷新函数会直接赋值 .Text,
            // 一旦赋值就把 XAML 里的 DynamicResource 绑定冲掉了, 光调 Loc.Apply() 追不上这几个,
            // 这里主动按当前状态重刷一遍, 语言按钮点下去才能做到"立刻全部生效"而不是要等
            // 下次连接/测试状态变化才顺带更新。
            try { RefreshRecordsHiddenBtn(); } catch { }
            try { RefreshRemarkReactionBtn(); } catch { }
            try { UpdateQuickConnectButton(); } catch { }
            try { UpdateDeviceTestButton(); } catch { }
            try { UpdateScoringControlMode(); } catch { }
            try { UpdateConnectionStatus(); } catch { }
            try { if (PauseClockBtnText != null) PauseClockBtnText.Text = Loc.T(_clockPaused ? "Str_RC_ResumeClock" : "Str_RC_PauseClock"); } catch { }
            try { UpdateRaceStateDisplay(); } catch { }
            // 2026-09-21 赛程导航树上的 [已确认] 这类状态标签是拼进 TreeViewItem.Header 的
            // 静态字符串, 不会跟着 DynamicResource 自己变——重建一次树(顺带联动
            // RebuildBothNavTrees() 那三棵), 已经在屏幕上的标签才会立刻换成新语言。
            try { BuildScheduleTree(); } catch { }   // 顺带联动 RebuildScheduleGroupedView()(赛程管理分组视图)
            try { RefreshOverviewStats(); } catch { }
            try { RebuildRelayGroupedView(); } catch { }
            try { RefreshEditPreview(); } catch { }
            // 2026-09-28 第十一阶段 Step2: "参赛单位及号码分配"是代码生成的 tab(不是 XAML 静态绑定),
            // 重建一次让它的按钮/标签/DataGrid列头跟着换语言(会连带重置 _bibAllocWorking = 当前 _bibRanges,
            // 丢弃未保存的编辑——跟本方法里其它几个 RebuildXxx() 一个道理, 属于"切语言=重建视图"的既有代价)。
            try { BuildUnitBibAllocTab(); } catch { }
            // 2026-10-10 现场反馈: "纪录管理" tab 的性别筛选下拉("全部"那一项)和下方"共N条/总N条"
            //   计数文字切语言不跟着变——这两处都是"数据变化时才刷"的程序化赋值(RefillGenderCombos/
            //   ApplyRecordFilter), 不在原有的语言切换级联里, 得跟 BuildUnitBibAllocTab 一样补进来。
            try { RefillGenderCombos(); } catch { }
            try { RefreshRecordFilterCombos(); ApplyRecordFilter(); } catch { }
            // 2026-09-28【跨客户端语言同步】实机联调时发现: ScheduleEditor.exe/RemoteTimingControl.exe
            // 顶部状态栏"主服务器: [IP] [连接/断开]"那个连接按钮是 EditorSyncToggle_Click/
            // OnEditorSyncConnected/OnEditorSyncDisconnected 直接赋值 .Content, 不在原有刷新级联里,
            // 语言切换/同步到达时会停在切换前那一刻的文字。_editorSyncClient.IsConnected 是活的,
            // 不用额外记状态, 直接按它现查现刷。
            try {
                if (_editorSyncConnectButton != null) {
                    bool connected = _editorSyncClient != null && _editorSyncClient.IsConnected;
                    _editorSyncConnectButton.Content = Loc.T(connected ? "Str_Btn_Disconnect" : "Str_Btn_Connect");
                }
                if (_editorSyncHwConnButton != null) _editorSyncHwConnButton.Content = Loc.T("Str_Btn_HwConnLabel");
                if (_editorSyncMainServerLabel != null) _editorSyncMainServerLabel.Text = Loc.T("Str_Label_MainServerColon");
                // 2026-09-28 ServerAddressText("远程计时控制 — ..."/"编排记录及成绩处理 — ...")
                // 同样是 InitializeData() 启动时赋值一次就不再变, 按当前模式重算一遍。
                if (ServerAddressText != null) {
                    if (IsRemoteTimingControlMode) ServerAddressText.Text = Loc.T("Str_Mode_RtcDesc");
                    else if (IsScheduleEditorMode) ServerAddressText.Text = Loc.T("Str_Mode_ScheduleEditorDesc");
                    else ServerAddressText.Text = Loc.F("Str_Mode_MainServerAddrFmt", GetLocalIP());
                }
            } catch { }
        }

        /// <summary>2026-09-28【跨客户端语言同步】拼一条 LANGUAGE_SYNC 消息, 带当前权威语言。
        /// 服务端广播用、也用于新连接补发单条。</summary>
        private string BuildLanguageSyncJson() {
            var msg = new JObject();
            msg["type"] = "LANGUAGE_SYNC";
            msg["lang"] = Loc.CurrentLanguage;
            return msg.ToString(Newtonsoft.Json.Formatting.None);
        }

        /// <summary>2026-09-28【跨客户端语言同步】只发给"桌面 exe"这个子集——ScheduleEditor.exe/
        /// RemoteTimingControl.exe(_scheduleEditorSockets/_timingExeSockets)、RegistrationTool.exe
        /// (_registrationToolSockets)、RemoteDisplayControl.exe(_rdcSockets)。故意不对
        /// _editorSockets/_registerSockets/_displayControlSockets 整体广播——那几个列表混着
        /// query.html/register.html/control.html 这些网页端, 网页端已经有自己独立的 localStorage
        /// 语言选择(第十二阶段 webloc.js), 不该被服务器权威语言覆盖。
        /// 2026-10-08 _displaySockets(display.html, 大屏) 是这条规则唯一的例外——用户明确要求
        /// 大屏不该有自己的语言主张, 必须跟主服务器当前语言一致。常规状态广播里也带了 lang
        /// 字段(GetStatusData/DisplayCommon), 但那条路只在"下一次有数据变化"时才会把新语言
        /// 带过去; 这里额外立刻推一次, 不用等——否则切语言按钮点下去, 大屏要等到下次比赛/
        /// 状态变化才会跟着变, 现场体验是"按了跟没按一样"。</summary>
        private void BroadcastLanguageSync() {
            try {
                string json = BuildLanguageSyncJson();
                var targets = _scheduleEditorSockets
                    .Concat(_timingExeSockets)
                    .Concat(_registrationToolSockets)
                    .Concat(_rdcSockets)
                    .Concat(_displaySockets)
                    .Distinct().ToList();
                foreach (var s in targets) EnqueueToSocket(s, json);
            } catch { }
        }

        private void ViewRawData_Click(object sender, RoutedEventArgs e) {
            string dir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database", "RawData");
            if (!Directory.Exists(dir)) {
                AppMessageBox.Show(Loc.F("Str_Msg_NoRawDataFilesDirFmt", dir), Loc.T("Str_MsgTitle_Info"));
                return;
            }
            var files = Directory.GetFiles(dir, "*.txt").OrderByDescending(f => File.GetLastWriteTime(f)).ToArray();
            if (files.Length == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRawDataFiles"), Loc.T("Str_MsgTitle_Info"));
                return;
            }

            var dlg = new Window {
                Title = Loc.T("Str_Win_RawDataQuery_Title"),
                Width = 900, Height = 650,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC"))
            };
            var mainGrid = new Grid();
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Auto) });
            mainGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });

            var topPanel = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(12, 10, 12, 6) };
            topPanel.Children.Add(new TextBlock {
                Text = Loc.T("Str_Label_SelectCompetitionColon"), VerticalAlignment = VerticalAlignment.Center,
                FontSize = 14, Margin = new Thickness(0, 0, 8, 0)
            });
            var combo = new ComboBox { Width = 500, FontSize = 14 };
            foreach (string f in files) {
                string name = IOPath.GetFileNameWithoutExtension(f);
                string time = File.GetLastWriteTime(f).ToString("MM-dd HH:mm");
                combo.Items.Add(new ComboBoxItem { Content = name + "  (" + time + ")", Tag = f });
            }
            var textBox = new TextBox {
                IsReadOnly = true,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Auto,
                FontFamily = new System.Windows.Media.FontFamily("Consolas, Microsoft YaHei"),
                FontSize = 13, Margin = new Thickness(12, 0, 12, 12),
                Background = new SolidColorBrush(Colors.White),
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")),
                Padding = new Thickness(10),
                AcceptsReturn = true, TextWrapping = TextWrapping.NoWrap
            };
            combo.SelectionChanged += delegate {
                var sel = combo.SelectedItem as ComboBoxItem;
                if (sel != null && sel.Tag != null) {
                    try {
                        textBox.Text = File.ReadAllText(sel.Tag.ToString(), Encoding.UTF8);
                        textBox.ScrollToHome();
                    } catch (Exception ex) {
                        textBox.Text = Loc.F("Str_Msg_ReadFailedFmt", ex.Message);
                    }
                }
            };
            var pdfBtn = new Button {
                Content = Loc.T("Str_Btn_ExportPdf"), Padding = new Thickness(14, 5, 14, 5), FontSize = 13,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B")),
                Foreground = new SolidColorBrush(Colors.White), FontWeight = FontWeights.Bold,
                BorderThickness = new Thickness(0), Margin = new Thickness(12, 0, 0, 0),
                VerticalAlignment = VerticalAlignment.Center
            };
            pdfBtn.Click += delegate {
                var sel = combo.SelectedItem as ComboBoxItem;
                if (sel == null || sel.Tag == null) return;
                string txtFile = sel.Tag.ToString();
                string htmlFile = IOPath.ChangeExtension(txtFile, ".html");
                if (File.Exists(htmlFile)) {
                    try { Process.Start(htmlFile); } catch (Exception ex2) { AppMessageBox.Show(Loc.F("Str_Msg_OpenFailedFmt", ex2.Message)); }
                } else {
                    AppMessageBox.Show(Loc.T("Str_Msg_HtmlFileMissing"), Loc.T("Str_MsgTitle_Info"));
                }
            };
            topPanel.Children.Add(combo);
            topPanel.Children.Add(pdfBtn);
            Grid.SetRow(topPanel, 0);
            mainGrid.Children.Add(topPanel);
            Grid.SetRow(textBox, 1);
            mainGrid.Children.Add(textBox);

            dlg.Content = mainGrid;
            if (combo.Items.Count > 0) combo.SelectedIndex = 0;
            dlg.ShowDialog();
        }

        /// <summary>
        /// 取分/奖牌用的名次 —— 【项目内】跨组大排名, 由竞赛库算好入库, 这里只读。
        /// 优先 EventRank(确认成绩后从库回读的); 库还没回读过就退回组内名次,
        /// 保证老档案照样能算, 但那种情况下多组项目会偏高, 所以回读那条路要保证通。
        /// </summary>
        private static int ScoringRankOf(Swimmer sw) {
            return sw == null ? 0 : sw.EventRankFor(ScoringStageOf(sw));
        }

        /// <summary>
        /// 取分看哪个赛次。原来写死 "决赛" —— 一旦赛程里用的是"计时决赛"之类的名字,
        /// 整场比赛一分都算不上, 而且不报错。改成: 有决赛用决赛, 没有就用这个人最后
        /// 实际比的那个赛次。
        /// </summary>
        private static string ScoringStageOf(Swimmer sw) {
            if (sw == null) return "决赛";
            if (sw.Results.Any(x => x.Stage == "决赛")) return "决赛";
            var last = sw.Results.LastOrDefault(x => !string.IsNullOrEmpty(x.Stage) && x.Stage.Contains("决赛"));
            if (last != null) return last.Stage;
            return sw.CurrentStage ?? "决赛";
        }

        private void CalculateTeamScores() {
            var teamDict = new Dictionary<string, TeamScore>();

            // 取分范围由配置控制（默认前 8 名）
            int cutoff = _scoringConfig != null && _scoringConfig.RankCutoff > 0 ? _scoringConfig.RankCutoff : 8;
            // 2026-08-30 取分必须用【项目内】名次, 不是组内名次。
            //   本场 45 个决赛里有 31 个是多组的 —— 按组内名次算, 每组都会出一个"第1名",
            //   金牌和分数都会多算。项目名次由竞赛库在确认成绩时算好并入库,
            //   这里只读不算(ScoringRankOf)。
            var finalSwimmers = _swimmers.Where(s => {
                // 2026-08-30 原来卡死 CurrentStage=="决赛"。CurrentStage 是"这个人当前在哪一轮"
                //   的计划字段, 不是"他比完了哪一轮" —— 用它当取分条件本来就不对。
                //   改成: 他在取分赛次上有名次就算数。
                string st = ScoringStageOf(s);
                if (!s.Results.Any(x => x.Stage == st && x.FinalTime > 0)) return false;
                int rk = ScoringRankOf(s);
                return rk > 0 && rk <= cutoff;
            }).ToList();

            foreach (var sw in finalSwimmers) {
                if (string.IsNullOrEmpty(sw.Country)) continue;
                if (!teamDict.ContainsKey(sw.Country)) {
                    teamDict[sw.Country] = new TeamScore { TeamName = sw.Country };
                }
                var ts = teamDict[sw.Country];

                bool isRelay = sw.EventName.Contains("接力");
                int scRank = ScoringRankOf(sw);
                double points = isRelay
                    ? _scoringConfig.GetRelayPoint(scRank)
                    : _scoringConfig.GetIndividualPoint(scRank);

                // 组别系数：从配置读，找不到按 1.0
                double coeff = _scoringConfig.GetAgeCoefficient(sw.AgeCategory);
                if (coeff != 1.0) points = Math.Round(points * coeff);

                if (isRelay) ts.RelayPoints += points;
                else ts.IndividualPoints += points;

                // 奖牌
                if (scRank == 1) ts.GoldCount++;
                else if (scRank == 2) ts.SilverCount++;
                else if (scRank == 3) ts.BronzeCount++;
            }

            // 破纪录加分
            foreach (var record in _records) {
                // TODO: 检查是否有新纪录打破
            }

            // 计算总分和排名
            foreach (var ts in teamDict.Values) {
                ts.TotalPoints = ts.IndividualPoints + ts.RelayPoints + ts.RecordBonusPoints;
            }

            var sorted = teamDict.Values.OrderByDescending(t => t.TotalPoints)
                .ThenByDescending(t => t.GoldCount)
                .ThenByDescending(t => t.SilverCount)
                .ThenByDescending(t => t.BronzeCount).ToList();

            int rank = 1;
            foreach (var ts in sorted) {
                ts.Rank = rank++;
            }

            _teamScores.Clear();
            foreach (var ts in sorted) _teamScores.Add(ts);

            AutoSaveData();
            AddLog(Loc.T("Str_Log_TeamScoreUpdated"));
        }

