        // 2026-06-12 显示比赛日程: 选场次(或全部) → 大屏翻页显示该场次/全部日程
        private void ShowSchedule_Click(object sender, RoutedEventArgs e) {
            if (_schedule == null || _schedule.Count == 0) { AppMessageBox.Show(Loc.T("Str_Msg_NoScheduleData"), Loc.T("Str_RC_ShowSchedule")); return; }
            var dlg = new Window {
                Title = Loc.T("Str_MsgTitle_ShowSchedule"), Width = 420, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = this, ResizeMode = ResizeMode.NoResize,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"))
            };
            var sp = new StackPanel { Margin = new Thickness(20) };
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_MsgTitle_ShowSchedule"), FontSize = 17, FontWeight = FontWeights.Bold, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 6) });
            sp.Children.Add(new TextBlock { Text = Loc.T("Str_ScheduleDisplay_Hint"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")), FontSize = 13, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 12) });
            var combo = new ComboBox { FontSize = 14, Margin = new Thickness(0, 0, 0, 6) };
            combo.Items.Add(new ComboBoxItem { Content = Loc.T("Str_All_Sessions"), Tag = -1 });
            foreach (var sn in _schedule.Select(s => s.SessionNumber).Distinct().OrderBy(n => n)) {
                var first = _schedule.FirstOrDefault(s => s.SessionNumber == sn);
                string nm = "";
                if (first != null && !string.IsNullOrWhiteSpace(first.SessionName)) {
                    // 2026-06-16 SessionName 持久化可能含 "第N场" 或旧版 "第N单元" 前缀, 跟此处 "第{0}场" 重复 → 去掉前缀, 只保留附加部分
                    string sname = System.Text.RegularExpressions.Regex.Replace(first.SessionName.Trim(), @"^\s*第\d+(场|单元)\s*", "");
                    if (!string.IsNullOrWhiteSpace(sname)) nm = " " + sname;
                }
                string dt = (first != null && !string.IsNullOrWhiteSpace(first.Date)) ? ("  " + first.Date) : "";
                combo.Items.Add(new ComboBoxItem { Content = string.Format("第{0}场{1}{2}", sn, nm, dt), Tag = sn });
            }
            combo.SelectedIndex = 0;
            sp.Children.Add(combo);
            var btnPanel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 14, 0, 0) };
            var btnCancel = new Button { Content = Loc.T("Str_Btn_Cancel"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")), Foreground = Brushes.White, BorderThickness = new Thickness(0), Margin = new Thickness(0, 0, 8, 0) };
            btnCancel.Click += delegate { dlg.DialogResult = false; };
            var btnOk = new Button { Content = Loc.T("Str_MsgTitle_Confirm"), Padding = new Thickness(16, 6, 16, 6), Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#3B82F6")), Foreground = Brushes.White, BorderThickness = new Thickness(0), FontWeight = FontWeights.Bold };
            btnOk.Click += delegate { dlg.DialogResult = true; };
            btnPanel.Children.Add(btnCancel); btnPanel.Children.Add(btnOk);
            sp.Children.Add(btnPanel);
            dlg.Content = sp;
            if (dlg.ShowDialog() == true) {
                int sessionFilter = -1;
                var item = combo.SelectedItem as ComboBoxItem;
                if (item != null && item.Tag is int) sessionFilter = (int)item.Tag;
                BroadcastSchedule(sessionFilter);
                AddLog(sessionFilter < 0 ? Loc.T("Str_Log_DisplayScheduleAllSessions") : Loc.F("Str_Log_DisplayScheduleSessionFmt", sessionFilter));
            }
        }

        // 2026-06-12 把赛程(按场次过滤或全部)推给大屏 (SHOW_SCHEDULE 模式, 独立负载, 不进常规心跳)
        private void BroadcastSchedule(int sessionFilter) {
            // 2026-08-28 【不再预判"有没有大屏"】。
            //   原来这里是 if (_allSockets.Count == 0) 就拦下来报"没有已连接的大屏"。
            //   计时端根本不开本地 WebSocket 服务, 这个集合永远是空的 —— 必然误报,
            //   现场表现就是: 大屏明明连着, 计时端按【比赛日程】却说没有大屏。
            //   改成【先发, 再按实际送达数判断】: 送达数由发送函数返回, 两种模式
            //   各自数各自的(计时端数"转给主服务器成功没有", 主服务器数本地客户端),
            //   不再依赖任何模式判定, 也就不会因为判错模式而误报。
            try {
                var items = _schedule.OrderBy(s => s.SessionNumber).ThenBy(s => s.EvNum).Select(s => new {
                    session = s.SessionNumber, sessionName = s.SessionName ?? "", date = s.Date ?? "", time = s.Time ?? "",
                    evNum = s.EvNum, gender = s.Gender ?? "", ageGroup = s.AgeGroup ?? "", eventName = s.EventName ?? "",
                    stage = s.Stage ?? "", heatCount = s.HeatCount, isRelay = s.IsRelay
                }).ToList();
                var payload = new { competitionName = _competitionName ?? "", session = sessionFilter, items = items };
                var msg = new { type = "SHOW_SCHEDULE", data = payload, modeExplicit = true };
                int sent = BroadcastJsonToClients(JsonConvert.SerializeObject(msg));
                if (sent <= 0) {
                    AddLog(Loc.T("Str_Log_DisplayScheduleNotSent"));
                    AppMessageBox.Show(
                        IsRemoteTimingControlMode
                            ? Loc.T("Str_Msg_ScheduleNotSentRtc")
                            : Loc.T("Str_Msg_ScheduleNotSentNoClients"),
                        Loc.T("Str_MsgTitle_ShowSchedule"));
                } else {
                    AddLog(Loc.F("Str_Log_DisplayScheduleSentFmt", sent));
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_DisplayScheduleFailedFmt", ex.Message)); }
        }

        // 2026-06-17 远程化辅助: 列文件 / 触发播放, 让 RDC/control.html 完全独立控制大屏 (不用主控 PC 弹框)
        //   媒体目录: <exe>\Media\ (创建于第一次启动); PPT 目录: <exe>\Documents\PPT\
        private string GetRemoteMediaDir() {
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            string dir = IOPath.Combine(baseDir, "Media");
            try { if (!Directory.Exists(dir)) Directory.CreateDirectory(dir); } catch { }
            return dir;
        }
        private string GetRemotePptDir() {
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            string dir = IOPath.Combine(baseDir, "Documents", "PPT");
            try { if (!Directory.Exists(dir)) Directory.CreateDirectory(dir); } catch { }
            return dir;
        }
        private void SendMediaFileListToClient(IWebSocketConnection socket) {
            try {
                var dir = GetRemoteMediaDir();
                var exts = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { ".png", ".jpg", ".jpeg", ".bmp", ".gif", ".webp", ".mp4", ".webm", ".ogg", ".m4v" };
                var files = Directory.EnumerateFiles(dir).Where(f => exts.Contains(IOPath.GetExtension(f) ?? ""))
                    .Select(f => new { name = IOPath.GetFileName(f), sizeMB = Math.Round(new FileInfo(f).Length / 1048576.0, 2) }).ToList();
                var reply = new { type = "MEDIA_FILE_LIST", data = new { dir = dir, files = files } };
                socket.Send(JsonConvert.SerializeObject(reply));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ListMediaFilesFailedFmt", ex.Message)); }
        }
        private void RemotePlayMediaFile(JObject message) {
            string fileName = message["fileName"] != null ? message["fileName"].ToString() : "";
            string fit = message["fit"] != null ? message["fit"].ToString() : "contain";
            bool loop = message["loop"] != null ? (bool)message["loop"] : true;
            bool muted = message["muted"] != null ? (bool)message["muted"] : false;
            bool autoplay = message["autoplay"] != null ? (bool)message["autoplay"] : true;
            if (string.IsNullOrEmpty(fileName)) { AddLog(Loc.T("Str_Log_PlayMediaMissingFileName")); return; }
            string full = IOPath.Combine(GetRemoteMediaDir(), fileName);
            if (!File.Exists(full)) { AddLog(Loc.F("Str_Log_PlayMediaNotExistFmt", full)); return; }
            string ext = (IOPath.GetExtension(full) ?? "").ToLower();
            string kind, mime;
            if (ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".bmp" || ext == ".gif" || ext == ".webp") {
                kind = "image";
                mime = ext == ".jpg" || ext == ".jpeg" ? "image/jpeg" : ext == ".bmp" ? "image/bmp" : ext == ".gif" ? "image/gif" : ext == ".webp" ? "image/webp" : "image/png";
            } else if (ext == ".mp4" || ext == ".webm" || ext == ".ogg" || ext == ".m4v") {
                kind = "video";
                mime = ext == ".webm" ? "video/webm" : ext == ".ogg" ? "video/ogg" : "video/mp4";
            } else { AddLog(Loc.F("Str_Log_PlayMediaUnsupportedTypeFmt", ext)); return; }
            BroadcastMediaToDisplay(full, kind, mime, fit, loop, muted, autoplay);
        }
        private void SendPptFileListToClient(IWebSocketConnection socket) {
            try {
                var dir = GetRemotePptDir();
                var exts = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { ".ppt", ".pptx", ".pps", ".ppsx" };
                var files = Directory.EnumerateFiles(dir).Where(f => exts.Contains(IOPath.GetExtension(f) ?? ""))
                    .Select(f => new { name = IOPath.GetFileName(f) }).ToList();
                var reply = new { type = "PPT_FILE_LIST", data = new { dir = dir, files = files } };
                socket.Send(JsonConvert.SerializeObject(reply));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ListPptFilesFailedFmt", ex.Message)); }
        }
        private void RemotePlayPptFile(JObject message) {
            string fileName = message["fileName"] != null ? message["fileName"].ToString() : "";
            if (string.IsNullOrEmpty(fileName)) { AddLog(Loc.T("Str_Log_PlayPptMissingFileName")); return; }
            string full = IOPath.Combine(GetRemotePptDir(), fileName);
            if (!File.Exists(full)) { AddLog(Loc.F("Str_Log_PlayPptNotExistFmt", full)); return; }
            // 调原 PPT 转换 + 翻页 Window. 翻页控制只能在主控 PC. RDC/control.html 只能选文件 + 触发.
            string outDir = IOPath.Combine(IOPath.GetTempPath(), "swim_ppt_" + DateTime.Now.Ticks);
            try { Directory.CreateDirectory(outDir); } catch { }
            List<string> slides;
            try { slides = ConvertPptToPngSlides(full, outDir); }
            catch (Exception ex) { AddLog(Loc.F("Str_Log_PptConvertFailedFmt", ex.Message)); return; }
            if (slides == null || slides.Count == 0) { AddLog(Loc.T("Str_Log_PptNoSlidesExtracted")); return; }
            AddLog(Loc.F("Str_Log_RemotePptConvertedFmt", slides.Count));
            OpenPptSlideControlWindow(slides, fileName);
        }
        private void SendScheduleSessionListToClient(IWebSocketConnection socket) {
            try {
                var sessions = _schedule.Select(s => s.SessionNumber).Distinct().OrderBy(n => n)
                    .Select(sn => {
                        var first = _schedule.FirstOrDefault(s => s.SessionNumber == sn);
                        string nm = "";
                        if (first != null && !string.IsNullOrWhiteSpace(first.SessionName)) {
                            string sname = System.Text.RegularExpressions.Regex.Replace(first.SessionName.Trim(), @"^\s*第\d+(场|单元)\s*", "");
                            if (!string.IsNullOrWhiteSpace(sname)) nm = " " + sname;
                        }
                        string dt = (first != null && !string.IsNullOrWhiteSpace(first.Date)) ? ("  " + first.Date) : "";
                        return new { session = sn, label = string.Format("第{0}场{1}{2}", sn, nm, dt) };
                    }).ToList();
                var reply = new { type = "SCHEDULE_SESSION_LIST", data = new { sessions = sessions } };
                socket.Send(JsonConvert.SerializeObject(reply));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ListScheduleSessionsFailedFmt", ex.Message)); }
        }
        // 2026-09-27 现场反馈: control.html/RemoteDisplayControl.exe 的"总排名"/"颁奖"按键点了没反应——
        //   根因是本机(PC)那两个按键点击后会先弹窗选定 _rankingSelection/_awardSelection 再广播,
        //   而远程客户端一直是直接发 REMOTE_CONTROL SHOW_EVENT_RANKING/SHOW_AWARDS, 没有选定项目这一步,
        //   服务端用的是当时(很可能是 null)的 _rankingSelection/_awardSelection, 大屏自然什么都不显示。
        //   补一对"列候选项目"+"按选定项目广播"的远程命令, 跟 LIST_SCHEDULE_SESSIONS/SHOW_SCHEDULE_SESSION
        //   同一个模式: 远程客户端自己弹选择框(不用挤到 PC 本机弹), 选完把 4 个 key 字段发回来。
        private void SendRankingCandidatesListToClient(IWebSocketConnection socket) {
            try {
                var candidates = GetFullyConfirmedFinalEvents().Select(item => {
                    int hc = item.HeatCount > 0 ? item.HeatCount : 1;
                    int n = _swimmers.Count(s => (s.Gender ?? "") == (item.Gender ?? "")
                        && (s.EventName ?? "") == (item.EventName ?? "")
                        && (s.AgeCategory ?? "") == (item.AgeGroup ?? ""));
                    string label = string.Format("{0}{1} {2} {3}  ({4} 人 {5} 组 全部已确认)",
                        string.IsNullOrEmpty(item.AgeGroup) ? "" : ("[" + item.AgeGroup + "] "),
                        item.Gender ?? "", item.EventName ?? "", item.Stage ?? "", n, hc);
                    return new {
                        ageGroup = item.AgeGroup ?? "", gender = item.Gender ?? "",
                        eventName = item.EventName ?? "", stage = item.Stage ?? "", label = label
                    };
                }).ToList();
                var reply = new { type = "RANKING_CANDIDATES_LIST", data = new { candidates = candidates } };
                socket.Send(JsonConvert.SerializeObject(reply));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_ListScheduleSessionsFailedFmt", ex.Message)); }
        }
        // 按 4 个 key 字段在"已完赛候选名单"里查——不直接信任远端传来的整条数据, 只认服务端
        // 自己认可的候选项, 避免远端传个还没确认完的项目把 _rankingSelection/_awardSelection 指过去。
        private ScheduleItem FindConfirmedFinalEventFromMessage(JObject message) {
            string ageGroup = message["ageGroup"] != null ? message["ageGroup"].ToString() : "";
            string gender = message["gender"] != null ? message["gender"].ToString() : "";
            string eventName = message["eventName"] != null ? message["eventName"].ToString() : "";
            string stage = message["stage"] != null ? message["stage"].ToString() : "";
            if (string.IsNullOrEmpty(eventName)) return null;
            return GetFullyConfirmedFinalEvents().FirstOrDefault(it =>
                (it.AgeGroup ?? "") == ageGroup && (it.Gender ?? "") == gender &&
                (it.EventName ?? "") == eventName && (it.Stage ?? "") == stage);
        }
        private void RemoteShowScheduleSession(JObject message) {
            int sessionFilter = message["session"] != null ? (int)message["session"] : -1;
            BroadcastSchedule(sessionFilter);
            AddLog(sessionFilter < 0 ? Loc.T("Str_Log_RemoteDisplayScheduleAllSessions") : Loc.F("Str_Log_RemoteDisplayScheduleSessionFmt", sessionFilter));
        }
        // 2026-06-17 双模式 — 本机上传媒体 (客户端已 base64, 主控只转发给大屏, 不落盘)
        //   message 字段: fileName, kind ("image"|"video"), mime, dataUrl, fit, loop, muted, autoplay
        private void RemoteUploadAndPlayMedia(JObject message) {
            string fileName = message["fileName"] != null ? message["fileName"].ToString() : "uploaded";
            string kind = message["kind"] != null ? message["kind"].ToString() : "";
            string mime = message["mime"] != null ? message["mime"].ToString() : "";
            string dataUrl = message["dataUrl"] != null ? message["dataUrl"].ToString() : "";
            string fit = message["fit"] != null ? message["fit"].ToString() : "contain";
            bool loop = message["loop"] != null ? (bool)message["loop"] : true;
            bool muted = message["muted"] != null ? (bool)message["muted"] : false;
            bool autoplay = message["autoplay"] != null ? (bool)message["autoplay"] : true;
            if (string.IsNullOrEmpty(dataUrl) || string.IsNullOrEmpty(kind)) { AddLog(Loc.T("Str_Log_UploadPlayMediaMissingFields")); return; }
            // 直接转发 dataUrl 给大屏 (跟 BroadcastMediaToDisplay 同 payload, 但跳过读文件)
            var payload = new {
                type = "SHOW_MEDIA",
                data = new { kind = kind, mime = mime, fileName = fileName, dataUrl = dataUrl, fit = fit, loop = loop, muted = muted, autoplay = autoplay, sizeBytes = (long)dataUrl.Length }
            };
            string json = JsonConvert.SerializeObject(payload);
            BroadcastJsonToClients(json);
            AddLog(Loc.F("Str_Log_RemoteUploadedMediaForwardedFmt", fileName, kind,
                IsRemoteTimingControlMode ? ", 经主服务器" : ", " + _allSockets.Count + " 个客户端"));
        }
        // 2026-06-17 双模式 — 本机上传 PPT (客户端 base64 后写临时文件, 转换 + 翻页 Window 仍在主控)
        //   message 字段: fileName, base64
        private void RemoteUploadAndPlayPpt(JObject message) {
            string fileName = message["fileName"] != null ? message["fileName"].ToString() : "uploaded.ppt";
            string base64 = message["base64"] != null ? message["base64"].ToString() : "";
            if (string.IsNullOrEmpty(base64)) { AddLog(Loc.T("Str_Log_UploadPlayPptMissingBase64")); return; }
            string tmpDir = IOPath.Combine(IOPath.GetTempPath(), "swim_ppt_upload_" + DateTime.Now.Ticks);
            try { Directory.CreateDirectory(tmpDir); } catch { }
            string tmpFile = IOPath.Combine(tmpDir, fileName);
            try {
                byte[] bytes = Convert.FromBase64String(base64);
                File.WriteAllBytes(tmpFile, bytes);
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_PptSaveTempFailedFmt", ex.Message)); return; }
            string outDir = IOPath.Combine(tmpDir, "slides");
            try { Directory.CreateDirectory(outDir); } catch { }
            List<string> slides;
            try { slides = ConvertPptToPngSlides(tmpFile, outDir); }
            catch (Exception ex) { AddLog(Loc.F("Str_Log_PptConvertFailedFmt", ex.Message)); return; }
            if (slides == null || slides.Count == 0) { AddLog(Loc.T("Str_Log_PptNoSlidesExtracted")); return; }
            AddLog(Loc.F("Str_Log_RemoteUploadedPptConvertedFmt", slides.Count));
            OpenPptSlideControlWindow(slides, fileName);
        }

