        private void SaveCompetitionInfo_Click(object sender, RoutedEventArgs e) {
            string newName = CompNameBox.Text.Trim();
            if (string.IsNullOrEmpty(newName)) {
                AppMessageBox.Show(Loc.T("Str_Msg_EnterCompName"), Loc.T("Str_MsgTitle_Info"));
                return;
            }

            // 2026-06-24 "保存赛事信息" 仅更新基本信息 (允许改名), 不清数据.
            //   清数据请用 "新建赛事" 按钮 (NewCompetition_Click), 加载存档请用 "加载赛事" (LoadCompetition_Click).
            //   旧逻辑把"改名"误判成"切换新赛事 → ClearAllDataAndUI", 用户改个错字就丢光报名/成绩.
            if (!string.IsNullOrEmpty(_competitionName) && _competitionName != newName) {
                AddLog(Loc.F("Str_Log_CompetitionNameChangedFmt", _competitionName, newName));
            }

            _competitionName = newName;
            _competitionMode = CompModeCombo.SelectedIndex == 0 ? "domestic" : "international";

            int poolLength = 50;
            if (PoolLengthCombo.SelectedIndex == 1) poolLength = 25;
            _poolConfig.Length = poolLength;

            int laneCount = 10;
            if (LaneCountCombo.SelectedIndex == 1) laneCount = 8;
            else if (LaneCountCombo.SelectedIndex == 2) laneCount = 6;
            _poolConfig.SetLaneCount(laneCount);

            InitLaneDeviceStates();
            ApplyPersistedDeviceStates();   // 改泳道数后还原已记录的设备状态
            UpdateRaceStateDisplay();
            AutoSaveData();
            RefreshBackupList();
            RefreshOverviewStats();
            Broadcast();
            SendTimingSettingsToHardware();   // 泳池参数可能变更，同步给硬件
            AddLog(Loc.F("Str_Log_CompetitionInfoSavedFmt", _competitionName));
        }

