        // ═══════════════════════════════════════════════════════════════
        // 2026-06-01 大屏样式持久化 + WebSocket 集中托管
        //   存 bg (CSS background) / fs (字号倍数 0.8~3.0) / textStyle (9 处颜色+字体 JSON map)
        //   任意控制端 SET_DISPLAY_STYLE 推送 → 服务器合并 → DISPLAY_STYLE_PUSH 广播给所有连接
        // ═══════════════════════════════════════════════════════════════
        private string DisplayStylePath {
            get { return IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "display_style.json"); }
        }

        private void LoadDisplayStyleFromDisk() {
            try {
                if (File.Exists(DisplayStylePath)) {
                    var j = JObject.Parse(File.ReadAllText(DisplayStylePath, Encoding.UTF8));
                    if (j["bg"] != null) _displayStyleBg = j["bg"].ToString();
                    if (j["fs"] != null) {
                        double v;
                        if (double.TryParse(j["fs"].ToString(), out v) && v > 0) _displayStyleFs = v;
                    }
                    if (j["textStyle"] != null) _displayStyleTextStyleJson = j["textStyle"].ToString(Newtonsoft.Json.Formatting.None);
                    if (j["fsParts"] != null) _displayStyleFsPartsJson = j["fsParts"].ToString(Newtonsoft.Json.Formatting.None);
                    if (j["recordsHidden"] != null) _displayStyleRecordsHidden = (bool)j["recordsHidden"];
                    if (j["remarkShowReaction"] != null) _displayStyleRemarkShowReaction = (bool)j["remarkShowReaction"];
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_LoadDisplayStyleFailedFmt", ex.Message)); }
        }

        private void SaveDisplayStyleToDisk() {
            try {
                JObject ts;
                try { ts = JObject.Parse(_displayStyleTextStyleJson); } catch { ts = new JObject(); }
                JObject fp;
                try { fp = JObject.Parse(_displayStyleFsPartsJson); } catch { fp = new JObject(); }
                var j = new JObject {
                    ["bg"] = _displayStyleBg,
                    ["fs"] = _displayStyleFs,
                    ["textStyle"] = ts,
                    ["fsParts"] = fp,
                    ["recordsHidden"] = _displayStyleRecordsHidden,
                    ["remarkShowReaction"] = _displayStyleRemarkShowReaction
                };
                File.WriteAllText(DisplayStylePath, j.ToString(Newtonsoft.Json.Formatting.Indented), Encoding.UTF8);
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_SaveDisplayStyleFailedFmt", ex.Message)); }
        }

        private void HandleSetDisplayStyle(JObject msg) {
            var data = msg["data"] as JObject;
            if (data == null) return;
            bool changed = false;
            if (data["bg"] != null) {
                var v = data["bg"].ToString();
                if (!string.IsNullOrEmpty(v) && v.IndexOf("javascript:", StringComparison.OrdinalIgnoreCase) < 0
                    && v.IndexOf("expression(", StringComparison.OrdinalIgnoreCase) < 0) {
                    _displayStyleBg = v;
                    changed = true;
                }
            }
            if (data["fs"] != null) {
                double v;
                if (double.TryParse(data["fs"].ToString(), out v) && v >= 0.5 && v <= 5.0) {
                    _displayStyleFs = Math.Round(v * 10) / 10.0;
                    changed = true;
                }
            }
            if (data["textStyle"] != null) {
                // textStyle 可以是完整替换或局部合并 (data.textStyleMerge=true)
                var newTs = data["textStyle"];
                bool merge = data["textStyleMerge"] != null && (bool)data["textStyleMerge"];
                if (merge) {
                    JObject cur;
                    try { cur = JObject.Parse(_displayStyleTextStyleJson); } catch { cur = new JObject(); }
                    var add = newTs as JObject;
                    if (add != null) {
                        foreach (var kv in add) {
                            cur[kv.Key] = kv.Value;
                        }
                        _displayStyleTextStyleJson = cur.ToString(Newtonsoft.Json.Formatting.None);
                        changed = true;
                    }
                } else {
                    _displayStyleTextStyleJson = newTs.ToString(Newtonsoft.Json.Formatting.None);
                    changed = true;
                }
            }
            // 2026-06-02 fsParts: 4 类独立字号. 同样支持局部合并 (fsPartsMerge=true) 或整体替换
            if (data["fsParts"] != null) {
                var newFp = data["fsParts"];
                bool mergeFp = data["fsPartsMerge"] != null && (bool)data["fsPartsMerge"];
                if (mergeFp) {
                    JObject cur;
                    try { cur = JObject.Parse(_displayStyleFsPartsJson); } catch { cur = new JObject(); }
                    var add = newFp as JObject;
                    if (add != null) {
                        foreach (var kv in add) {
                            cur[kv.Key] = kv.Value;
                        }
                        _displayStyleFsPartsJson = cur.ToString(Newtonsoft.Json.Formatting.None);
                        changed = true;
                    }
                } else {
                    _displayStyleFsPartsJson = newFp.ToString(Newtonsoft.Json.Formatting.None);
                    changed = true;
                }
            }
            // 2026-06-03 recordsHidden (= 大屏右上角 WR/CR 横条 显示/隐藏 开关)
            if (data["recordsHidden"] != null) {
                bool v = (bool)data["recordsHidden"];
                if (_displayStyleRecordsHidden != v) { _displayStyleRecordsHidden = v; changed = true; }
            }
            // 2026-06-04 remarkShowReaction (= 备注栏 是否显示 出发反应时, 默认 true)
            if (data["remarkShowReaction"] != null) {
                bool v = (bool)data["remarkShowReaction"];
                if (_displayStyleRemarkShowReaction != v) { _displayStyleRemarkShowReaction = v; changed = true; }
            }
            if (changed) {
                SaveDisplayStyleToDisk();
                BroadcastDisplayStyle();
            }
        }

        private string BuildDisplayStyleJson() {
            JObject ts;
            try { ts = JObject.Parse(_displayStyleTextStyleJson); } catch { ts = new JObject(); }
            JObject fp;
            try { fp = JObject.Parse(_displayStyleFsPartsJson); } catch { fp = new JObject(); }
            var msg = new JObject {
                ["type"] = "DISPLAY_STYLE_PUSH",
                ["data"] = new JObject {
                    ["bg"] = _displayStyleBg,
                    ["fs"] = _displayStyleFs,
                    ["textStyle"] = ts,
                    ["fsParts"] = fp,
                    ["recordsHidden"] = _displayStyleRecordsHidden,
                    ["remarkShowReaction"] = _displayStyleRemarkShowReaction
                }
            };
            return msg.ToString(Newtonsoft.Json.Formatting.None);
        }

        private void BroadcastDisplayStyle() {
            // 2026-06-17 方案 B: RTC 模式无本机 _allSockets, 经主服务器转发给 display
            if (IsRemoteTimingControlMode) {
                try {
                    JObject ts2; try { ts2 = JObject.Parse(_displayStyleTextStyleJson); } catch { ts2 = new JObject(); }
                    JObject fp2; try { fp2 = JObject.Parse(_displayStyleFsPartsJson); } catch { fp2 = new JObject(); }
                    var payload = new JObject {
                        ["type"] = "DISPLAY_STYLE_PUSH",
                        ["data"] = new JObject {
                            ["bg"] = _displayStyleBg,
                            ["fs"] = _displayStyleFs,
                            ["textStyle"] = ts2,
                            ["fsParts"] = fp2,
                            ["recordsHidden"] = _displayStyleRecordsHidden,
                            ["remarkShowReaction"] = _displayStyleRemarkShowReaction
                        }
                    };
                    // 2026-09-15 【广播分级】大屏样式只有大屏本身、比赛控制网页(同步
                    //   "记录显示/显反应时"按钮态)、显示控制端(control.html/RDC, 编辑
                    //   这份样式的地方本身)要看, 检录台/信息查询/排名屏/报名终端/编排端
                    //   都用不上。to="style", 主服务器转给三者并集(定义见 RTC_FORWARD case)。
                    TryForwardToMainServer(payload, "style");
                } catch { }
                return;
            }
            string json = BuildDisplayStyleJson();
            EnqueueToSet(_displaySockets.Concat(_timingWebSockets).Concat(_displayControlSockets), json);   // 2026-06-18 per-socket 队列
            // 主控 PC 端打开的"大屏样式"窗口同步 UI (其它客户端通过 WebSocket 推送同步)
            if (_displayStyleWin != null && _displayStyleWin.IsLoaded) {
                try {
                    JObject ts;
                    try { ts = JObject.Parse(_displayStyleTextStyleJson); } catch { ts = new JObject(); }
                    var data = new JObject {
                        ["bg"] = _displayStyleBg,
                        ["fs"] = _displayStyleFs,
                        ["textStyle"] = ts
                    };
                    _displayStyleWin.ApplyRemoteStyle(data);
                } catch { }
            }
        }

        private void SendDisplayStyleTo(IWebSocketConnection sock) {
            try { sock.Send(BuildDisplayStyleJson()); } catch { }
        }

        // ═══════════════════════════════════════════════════════════════
        // 计时参数独立存储（不依赖比赛数据）
        // ═══════════════════════════════════════════════════════════════
        private string TimingSettingsPath {
            get { return IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "timing_settings.json"); }
        }

        // 2026-08-31 参数的【权威】是竞赛库的 settings 表, 本地 json 只当断线/降级
        //   时的后备。联机时 _meet 就是主服务器, 所以计时端一存, 主服务器那份库里
        //   立刻就是新值 —— 不再是"两份数据靠消息同步"(那样一定有分叉的时候)。
        // 2026-09-01 竞赛库打不开的告警每次加载只弹一次
        private bool _meetDbFailWarned;

        private const string CFG_TIMING = "timing_settings";
        private const string CFG_DEVICE = "device_states";

        // ── 2026-08-31 比赛进行中【不往主服务器的库写任何东西】 ──────────────
        //   规矩: 比赛过程中的触板/盲表/出发反应时这些实时数据, 只留在计时端本机
        //   和大屏上; 只有按下"确认本组成绩"之后, 才一次性写进主服务器的库。
        //
        //   参数和设备状态也一样。设备状态在比赛中是会变的(某块触板报故障、
        //   盲表状态回报), 原来我让它一变就 SaveConfig —— 联机时 _meet 就是
        //   主服务器, 那等于比赛中不停地往主服务器的库里写, 还都过网络。
        //   现在: 比赛中只写本机 json, 记个"欠着", 确认成绩时一并补进库。
        private bool _cfgDbPending;

        /// <summary>比赛进行中(就位/比赛中)不许碰主服务器的库。</summary>
        private bool InRaceNoDbWrite() {
            return _raceState == RaceState.Ready || _raceState == RaceState.Racing;
        }

        /// <summary>
        /// 2026-08-31 参数设置窗口按【确认】时立即写库 —— 不受"比赛中不写库"的限制。
        ///
        /// 要分清两件事:
        ///   成绩   —— 比赛过程中的触板/盲表/反应时只留在计时端和大屏,
        ///             只有"确认本组成绩"那一下才一次性写库。
        ///   参数   —— 操作员在参数设置窗口点了确认, 那就是一次明确的人工动作,
        ///             必须马上生效并入库(否则别的机器和硬件用的还是旧参数)。
        ///             它是零星操作, 不会像成绩那样每秒往库里灌。
        /// </summary>
        private void WriteConfigToDbNow() {
            try {
                string j1 = JsonConvert.SerializeObject(_laneCloseSettings, Formatting.Indented);
                _meetDb.SaveConfig(CFG_TIMING, j1, Environment.MachineName);
            } catch { }
            try {
                if (File.Exists(DeviceStatesPath))
                    _meetDb.SaveConfig(CFG_DEVICE, File.ReadAllText(DeviceStatesPath, Encoding.UTF8),
                                       Environment.MachineName);
            } catch { }
            _cfgDbPending = false;   // 刚全写过, 不欠了
            AddLog(Loc.T("Str_Log_ParamsWrittenToMeetDb"));
        }

        /// <summary>把比赛期间欠下的参数/设备状态一次性写进库。确认成绩后调。</summary>
        private void FlushConfigToDb() {
            if (!_cfgDbPending) return;
            _cfgDbPending = false;
            try {
                string j1 = JsonConvert.SerializeObject(_laneCloseSettings, Formatting.Indented);
                _meetDb.SaveConfig(CFG_TIMING, j1, Environment.MachineName);
            } catch { }
            try {
                if (File.Exists(DeviceStatesPath))
                    _meetDb.SaveConfig(CFG_DEVICE, File.ReadAllText(DeviceStatesPath, Encoding.UTF8),
                                       Environment.MachineName);
            } catch { }
            AddLog(Loc.T("Str_Log_RaceParamsDeviceStateWritten"));
        }

        private void SaveTimingSettings() {
            string json = null;
            try {
                json = JsonConvert.SerializeObject(_laneCloseSettings, Formatting.Indented);
                File.WriteAllText(TimingSettingsPath, json, Encoding.UTF8);
            } catch { }
            // 2026-09-13 泳道面板上"哪一端锁着"(endLocked)是按终点位置算出来的, 就在
            //   laneDevices 里带着走 —— 参数一改就得推一次, 不然比赛控制页面上那一端
            //   一直显示着旧的。
            PushDeviceStates();
            // 比赛进行中只写本机 json, 不碰主服务器的库(见 InRaceNoDbWrite)
            if (InRaceNoDbWrite()) { _cfgDbPending = true; return; }
            try { if (json != null) _meetDb.SaveConfig(CFG_TIMING, json, Environment.MachineName); } catch { }
        }

        private void LoadTimingSettings() {
            try {
                // 2026-08-31 库里有就以库为准(联机时那是主服务器那份), 没有再退回本地 json。
                //   第一次从 json 读上来之后, 下一次 SaveTimingSettings 就会写进库, 之后两端统一。
                string dbJson = null;
                try { dbJson = _meetDb.LoadConfig(CFG_TIMING); } catch { }
                if (!string.IsNullOrWhiteSpace(dbJson)) {
                    var fromDb = JsonConvert.DeserializeObject<LaneCloseSettings>(dbJson);
                    if (fromDb != null) {
                        _laneCloseSettings = fromDb;
                        if (_poolConfig != null) _poolConfig.HasRightStartBlock = _laneCloseSettings.HasRightStartBlock;
                        AddLog(Loc.T("Str_Log_TimingParamsLoadedFromDb"));
                        return;
                    }
                }
                if (File.Exists(TimingSettingsPath)) {
                    string json = File.ReadAllText(TimingSettingsPath, Encoding.UTF8);
                    var loaded = JsonConvert.DeserializeObject<LaneCloseSettings>(json);
                    if (loaded != null) {
                        _laneCloseSettings = loaded;
                        // 2026-05-26 把持久化的 HasRightStartBlock 同步回 _poolConfig (运行时主存源)
                        if (_poolConfig != null) _poolConfig.HasRightStartBlock = _laneCloseSettings.HasRightStartBlock;
                        AddLog(Loc.F("Str_Log_TimingParamsLoadedFmt",
                            _laneCloseSettings.LaneCloseTime, _laneCloseSettings.StartBlockCloseDelay,
                            _laneCloseSettings.ResultConfirmCloseDelay, _laneCloseSettings.FalseStartThreshold,
                            _laneCloseSettings.SplitDisplayTime, _laneCloseSettings.FirstPlaceHoldTime,
                            _laneCloseSettings.FinishPosition == "left" ? "左端" : "右端",
                            _laneCloseSettings.HasRightStartBlock ? "两端" : "单端",
                            _laneCloseSettings.HardwareAlwaysOpen ? "打开" : "比赛流程",
                            _laneCloseSettings.ReactionEventWindowSec.ToString("F1"),
                            _laneCloseSettings.StartBoxEdgeFalling ? "下降沿" : "上升沿"));
                    }
                }
            } catch { }
        }

        // ═══════════════════════════════════════════════════════════════
        // 设备状态持久化 — 设备状态管理 / 手动按键管理 修改的标志位
        //   保存内容：每道左右两端的 触板/盲表1-3/出发台 损坏 + 盲表1-3 未安装 + 手动按键启用
        //   不保存运行状态（Open/Closed/Touched/FalseStart/CurrentLap/ReactionTime 等）
        // ═══════════════════════════════════════════════════════════════
        private string DeviceStatesPath {
            get { return IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "device_states.json"); }
        }

        // 2026-09-13 设备状态载荷: 完整帧带全量, 平时靠 DEVICE_STATES_UPDATE 变更即推。
        private object BuildLaneDevicesPayload() {
            return _laneDeviceStates.Select(s => new {
                lane = s.Lane,
                leftTouchpadBroken = s.LeftTouchpadBroken,
                leftStartBlockBroken = s.LeftStartBlockBroken,
                leftBlindWatch1Broken = s.LeftBlindWatch1Broken,
                leftBlindWatch2Broken = s.LeftBlindWatch2Broken,
                leftBlindWatch3Broken = s.LeftBlindWatch3Broken,
                rightTouchpadBroken = s.RightTouchpadBroken,
                rightStartBlockBroken = s.RightStartBlockBroken,
                rightBlindWatch1Broken = s.RightBlindWatch1Broken,
                rightBlindWatch2Broken = s.RightBlindWatch2Broken,
                rightBlindWatch3Broken = s.RightBlindWatch3Broken,
                leftTouchpadNotInstalled = s.LeftTouchpadNotInstalled,
                leftStartBlockNotInstalled = s.LeftStartBlockNotInstalled,
                leftBlindWatch1NotInstalled = s.LeftBlindWatch1NotInstalled,
                leftBlindWatch2NotInstalled = s.LeftBlindWatch2NotInstalled,
                leftBlindWatch3NotInstalled = s.LeftBlindWatch3NotInstalled,
                rightTouchpadNotInstalled = s.RightTouchpadNotInstalled,
                rightStartBlockNotInstalled = s.RightStartBlockNotInstalled,
                rightBlindWatch1NotInstalled = s.RightBlindWatch1NotInstalled,
                rightBlindWatch2NotInstalled = s.RightBlindWatch2NotInstalled,
                rightBlindWatch3NotInstalled = s.RightBlindWatch3NotInstalled,
                endLocked = (_poolConfig != null && _poolConfig.HasRightStartBlock) ? "none"
                          : ((_laneCloseSettings == null || _laneCloseSettings.FinishPosition != "right") ? "right" : "left")
            }).ToList();
        }

        /// <summary>设备状态一变就推 —— 一次几 KB, 一场也就几次, 比每帧重发划算得多。</summary>
        // 2026-09-15 【广播分级】TP/SB/MB 设备状态只有"比赛控制网页"(race_control.html)
        //   的状态灯面板在读; 大屏不读(同 laneEventLogs, BuildDisplayPayload 本就不带),
        //   检录台/信息查询/排名屏/报名终端/显示控制/编排端更用不上。原来 EnqueueToAll
        //   全员群发, 现在连 BuildLaneDevicesPayload() 这份计算都先看有没有人要再做。
        private void PushDeviceStates() {
            if (!_initialized) return;
            try {
                if (IsRemoteTimingControlMode) {
                    var msgR = new { type = "DEVICE_STATES_UPDATE", data = BuildLaneDevicesPayload() };
                    TryForwardToMainServer(msgR, "others");
                    return;
                }
                if (_timingWebSockets.Count == 0) return;
                var msg = new { type = "DEVICE_STATES_UPDATE", data = BuildLaneDevicesPayload() };
                EnqueueToSet(_timingWebSockets, JsonConvert.SerializeObject(msg));
            } catch { }
        }

        private void SaveDeviceStates() {
            try {
                var arr = new JArray();
                foreach (var st in _laneDeviceStates) {
                    var o = new JObject();
                    o["lane"] = st.Lane;
                    o["leftTouchpadBroken"]    = st.LeftTouchpadBroken;
                    o["leftBlindWatch1Broken"] = st.LeftBlindWatch1Broken;
                    o["leftBlindWatch2Broken"] = st.LeftBlindWatch2Broken;
                    o["leftBlindWatch3Broken"] = st.LeftBlindWatch3Broken;
                    o["leftStartBlockBroken"]  = st.LeftStartBlockBroken;
                    o["rightTouchpadBroken"]    = st.RightTouchpadBroken;
                    o["rightBlindWatch1Broken"] = st.RightBlindWatch1Broken;
                    o["rightBlindWatch2Broken"] = st.RightBlindWatch2Broken;
                    o["rightBlindWatch3Broken"] = st.RightBlindWatch3Broken;
                    o["rightStartBlockBroken"]  = st.RightStartBlockBroken;
                    // 2026-05-26 持久化所有"计算后"的 NotInstalled 标志 (12 个 = 触板2 + 出发台2 + 盲表6):
                    //   每次 ApplyTouchpadInstallModeToLanes 跑完都 SaveDeviceStates, 开机后直接读盘还原,
                    //   不再依赖开机时根据 HasRightStartBlock + FinishPosition 即时重算.
                    o["leftTouchpadNotInstalled"]   = st.LeftTouchpadNotInstalled;
                    o["rightTouchpadNotInstalled"]  = st.RightTouchpadNotInstalled;
                    o["leftStartBlockNotInstalled"] = st.LeftStartBlockNotInstalled;
                    o["rightStartBlockNotInstalled"] = st.RightStartBlockNotInstalled;
                    o["leftBlindWatch1NotInstalled"] = st.LeftBlindWatch1NotInstalled;
                    o["leftBlindWatch2NotInstalled"] = st.LeftBlindWatch2NotInstalled;
                    o["leftBlindWatch3NotInstalled"] = st.LeftBlindWatch3NotInstalled;
                    o["rightBlindWatch1NotInstalled"] = st.RightBlindWatch1NotInstalled;
                    o["rightBlindWatch2NotInstalled"] = st.RightBlindWatch2NotInstalled;
                    o["rightBlindWatch3NotInstalled"] = st.RightBlindWatch3NotInstalled;
                    o["leftManualEnabled"]  = st.LeftManualEnabled;
                    o["rightManualEnabled"] = st.RightManualEnabled;
                    arr.Add(o);
                }
                string dsJson = arr.ToString(Formatting.Indented);
                File.WriteAllText(DeviceStatesPath, dsJson, Encoding.UTF8);
                // 2026-08-31 同时写进竞赛库 settings 表。联机时写的就是主服务器那份库,
                //   所以"哪几个盲表装了/坏了"两端看到的是同一份, 不再各存各的。
                //   但比赛进行中不写 —— 设备状态在比赛中会变(触板报故障、盲表回报),
                //   一变就写等于比赛中不停往主服务器库里写, 还过网络。欠着, 确认后补。
                if (InRaceNoDbWrite()) { _cfgDbPending = true; }
                else { try { _meetDb.SaveConfig(CFG_DEVICE, dsJson, Environment.MachineName); } catch { } }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_SaveDeviceStateFailedFmt", ex.Message));
            }
            // 2026-09-13 状态一变立刻推给客户端(几 KB)。所有改设备状态的地方都会走到
            //   这个函数, 所以这一处挂上就够, 不用到十几个调用点各加一遍。
            PushDeviceStates();
        }

        // 把磁盘上的设备状态贴回到当前 _laneDeviceStates；
        // 任何 InitLaneDeviceStates 之后调用一次即可让用户上次的"损坏/未安装/手动按键"配置生效。
        private void ApplyPersistedDeviceStates() {
            try {
                // 2026-08-31 库里有就以库为准(联机时那是主服务器那份), 没有再退回本地 json。
                string json = null;
                try { json = _meetDb.LoadConfig(CFG_DEVICE); } catch { }
                if (string.IsNullOrWhiteSpace(json)) {
                    if (!File.Exists(DeviceStatesPath)) return;
                    json = File.ReadAllText(DeviceStatesPath, Encoding.UTF8);
                }
                var arr = JArray.Parse(json);
                int hits = 0;
                foreach (JObject o in arr) {
                    if (o["lane"] == null) continue;
                    int lane = (int)o["lane"];
                    var st = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
                    if (st == null) continue;
                    if (o["leftTouchpadBroken"]    != null) st.LeftTouchpadBroken    = (bool)o["leftTouchpadBroken"];
                    if (o["leftBlindWatch1Broken"] != null) st.LeftBlindWatch1Broken = (bool)o["leftBlindWatch1Broken"];
                    if (o["leftBlindWatch2Broken"] != null) st.LeftBlindWatch2Broken = (bool)o["leftBlindWatch2Broken"];
                    if (o["leftBlindWatch3Broken"] != null) st.LeftBlindWatch3Broken = (bool)o["leftBlindWatch3Broken"];
                    if (o["leftStartBlockBroken"]  != null) st.LeftStartBlockBroken  = (bool)o["leftStartBlockBroken"];
                    if (o["rightTouchpadBroken"]    != null) st.RightTouchpadBroken    = (bool)o["rightTouchpadBroken"];
                    if (o["rightBlindWatch1Broken"] != null) st.RightBlindWatch1Broken = (bool)o["rightBlindWatch1Broken"];
                    if (o["rightBlindWatch2Broken"] != null) st.RightBlindWatch2Broken = (bool)o["rightBlindWatch2Broken"];
                    if (o["rightBlindWatch3Broken"] != null) st.RightBlindWatch3Broken = (bool)o["rightBlindWatch3Broken"];
                    if (o["rightStartBlockBroken"]  != null) st.RightStartBlockBroken  = (bool)o["rightStartBlockBroken"];
                    // 2026-05-26 还原所有"计算后"的 NotInstalled 标志 (含触板/出发台/盲表 12 个).
                    //   旧版本只持久化盲表 6 个 → 新版本统一持久化全部 → 这里都还原以保持完整.
                    if (o["leftTouchpadNotInstalled"]    != null) st.LeftTouchpadNotInstalled    = (bool)o["leftTouchpadNotInstalled"];
                    if (o["rightTouchpadNotInstalled"]   != null) st.RightTouchpadNotInstalled   = (bool)o["rightTouchpadNotInstalled"];
                    if (o["leftStartBlockNotInstalled"]  != null) st.LeftStartBlockNotInstalled  = (bool)o["leftStartBlockNotInstalled"];
                    if (o["rightStartBlockNotInstalled"] != null) st.RightStartBlockNotInstalled = (bool)o["rightStartBlockNotInstalled"];
                    if (o["leftBlindWatch1NotInstalled"]  != null) st.LeftBlindWatch1NotInstalled  = (bool)o["leftBlindWatch1NotInstalled"];
                    if (o["leftBlindWatch2NotInstalled"]  != null) st.LeftBlindWatch2NotInstalled  = (bool)o["leftBlindWatch2NotInstalled"];
                    if (o["leftBlindWatch3NotInstalled"]  != null) st.LeftBlindWatch3NotInstalled  = (bool)o["leftBlindWatch3NotInstalled"];
                    if (o["rightBlindWatch1NotInstalled"] != null) st.RightBlindWatch1NotInstalled = (bool)o["rightBlindWatch1NotInstalled"];
                    if (o["rightBlindWatch2NotInstalled"] != null) st.RightBlindWatch2NotInstalled = (bool)o["rightBlindWatch2NotInstalled"];
                    if (o["rightBlindWatch3NotInstalled"] != null) st.RightBlindWatch3NotInstalled = (bool)o["rightBlindWatch3NotInstalled"];
                    if (o["leftManualEnabled"]  != null) st.LeftManualEnabled  = (bool)o["leftManualEnabled"];
                    if (o["rightManualEnabled"] != null) st.RightManualEnabled = (bool)o["rightManualEnabled"];
                    hits++;
                }
                if (hits > 0) AddLog(Loc.F("Str_Log_DeviceStateLoadedFmt", hits));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_LoadDeviceStateFailedFmt", ex.Message));
            }
            // 2026-09-13 换赛事包/改泳道数会重建这张表, 重建完推一次, 别让客户端拿着旧的
            PushDeviceStates();
        }

        // 计时硬件通讯参数（串口 / TCP / UDP）持久化路径
        private string TimingConnectionPath {
            get { return IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "timing_connection.json"); }
        }

        private void SaveTimingConnectionConfig() {
            try {
                string json = JsonConvert.SerializeObject(_timingConn, Formatting.Indented);
                File.WriteAllText(TimingConnectionPath, json, Encoding.UTF8);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_SaveCommParamsFailedFmt", ex.Message));
            }
        }

        private void LoadTimingConnectionConfig() {
            try {
                if (!File.Exists(TimingConnectionPath)) return;
                string json = File.ReadAllText(TimingConnectionPath, Encoding.UTF8);
                var loaded = JsonConvert.DeserializeObject<TimingConnectionConfig>(json);
                if (loaded != null) {
                    _timingConn = loaded;
                    AddLog(Loc.F("Str_Log_CommParamsLoadedFmt",
                        string.IsNullOrEmpty(_timingConn.LastType) ? "未连接过" : _timingConn.LastType,
                        string.IsNullOrEmpty(_timingConn.SerialPort) ? "—" : _timingConn.SerialPort,
                        _timingConn.TcpHost ?? "—", _timingConn.TcpPort,
                        _timingConn.UdpListenPort,
                        _timingConn.UdpSendHost ?? "—", _timingConn.UdpSendPort));
                }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_LoadCommParamsFailedFmt", ex.Message));
            }
        }

        // 把 _timingConn 还原到 UI 控件（在 PopulateComPorts 之后调用，确保 ComboBox 已有可选项）
        private void ApplyTimingConnectionToUi() {
            if (_timingConn == null) return;
            // 串口：若保存的端口仍存在于当前可选列表中，自动选中
            if (!string.IsNullOrEmpty(_timingConn.SerialPort) && ComPortCombo != null) {
                foreach (var item in ComPortCombo.Items) {
                    if (item != null && item.ToString() == _timingConn.SerialPort) {
                        ComPortCombo.SelectedItem = item;
                        break;
                    }
                }
            }
            // 波特率：在下拉里找匹配项；找不到就保持默认（9600）
            if (BaudRateCombo != null && _timingConn.SerialBaudRate > 0) {
                string want = _timingConn.SerialBaudRate.ToString();
                foreach (var item in BaudRateCombo.Items) {
                    var ci = item as ComboBoxItem;
                    string txt = ci != null ? ci.Content.ToString() : (item != null ? item.ToString() : "");
                    if (txt == want) {
                        BaudRateCombo.SelectedItem = item;
                        break;
                    }
                }
            }
            if (TcpHostBox != null && _timingConn.TcpPort > 0)
                TcpHostBox.Text = string.Format("{0}:{1}",
                    string.IsNullOrEmpty(_timingConn.TcpHost) ? "127.0.0.1" : _timingConn.TcpHost,
                    _timingConn.TcpPort);
            if (UdpPortBox != null && _timingConn.UdpListenPort > 0)
                UdpPortBox.Text = _timingConn.UdpListenPort.ToString();
            if (UdpSendBox != null && _timingConn.UdpSendPort > 0)
                UdpSendBox.Text = string.Format("{0}:{1}",
                    string.IsNullOrEmpty(_timingConn.UdpSendHost) ? "127.0.0.1" : _timingConn.UdpSendHost,
                    _timingConn.UdpSendPort);
        }

        // 启动时自动重连（仅当 AutoReconnectOnStartup=true）
        private void TryAutoReconnectTiming() {
            // 主服务器角色: 根本不碰计时硬件, 免得跟计时机抢同一台设备
            if (IsScoringServerNoTiming) {
                AddLog(Loc.T("Str_Log_MainServerSkipTimingHw"));
                return;
            }
            if (_timingConn == null || !_timingConn.AutoReconnectOnStartup) return;
            try {
                if (_timingConn.LastType == "serial" && !string.IsNullOrEmpty(_timingConn.SerialPort)) {
                    int baud = _timingConn.SerialBaudRate > 0 ? _timingConn.SerialBaudRate : 9600;
                    _timingBridge.ConnectSerial(_timingConn.SerialPort, baud);
                    UpdateConnectionStatus();
                    AddLog(Loc.F("Str_Log_AutoReconnectSerialFmt", _timingConn.SerialPort, baud));
                } else if (_timingConn.LastType == "tcp" && !string.IsNullOrEmpty(_timingConn.TcpHost) && _timingConn.TcpPort > 0) {
                    _timingBridge.ConnectTcp(_timingConn.TcpHost, _timingConn.TcpPort);
                    UpdateConnectionStatus();
                    AddLog(Loc.F("Str_Log_AutoReconnectTcpFmt", _timingConn.TcpHost, _timingConn.TcpPort));
                } else if (_timingConn.LastType == "udp" && _timingConn.UdpListenPort > 0) {
                    _timingBridge.ConnectUdp(_timingConn.UdpListenPort, _timingConn.UdpSendHost, _timingConn.UdpSendPort);
                    UpdateConnectionStatus();
                    AddLog(Loc.F("Str_Log_AutoReconnectUdpFmt",
                        _timingConn.UdpListenPort, _timingConn.UdpSendHost ?? "—", _timingConn.UdpSendPort));
                }
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_AutoReconnectFailedFmt", ex.Message)); }
        }

        // ═══════════════════════════════════════════════════════════════
        // JSON 持久化
        // ═══════════════════════════════════════════════════════════════
        // 2026-06-06 P2-B: BuildCurrentPackage 必须 UI 线程 (= 读 ObservableCollection),
        //   JsonConvert (1110+ 泳将 Indented 50-200ms) + File.WriteAllText 全扔后台.
        //   AutoSaveData 被多处密集触发 (确认成绩 / 编辑泳将 / 切组 …), 同步会让 UI 间歇卡顿.
        private readonly object _autoSaveBgLock = new object();
        private void AutoSaveData() {
            if (string.IsNullOrEmpty(_competitionName)) return;
            CompetitionPackage package;
            string compName, dbDir, baseDir;
            try {
                baseDir = AppDomain.CurrentDomain.BaseDirectory;
                dbDir = IOPath.Combine(baseDir, "Database");
                if (!Directory.Exists(dbDir)) Directory.CreateDirectory(dbDir);
                compName = _competitionName;
                package = BuildCurrentPackage();
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_AutoSavePackagingFailedFmt", ex.Message));
                return;
            }
            string lastCompPath = IOPath.Combine(baseDir, "last_competition.txt");
            string jsonPath = IOPath.Combine(dbDir, compName + ".json");
            System.Threading.Tasks.Task.Run(() => {
                lock (_autoSaveBgLock) {   // 串行化, 防 AutoSaveData 短时间内多次触发 时同名文件竞争
                    try {
                        File.WriteAllText(lastCompPath, compName, Encoding.UTF8);
                        // 2026-08-25 不要 SerializeObject 再 WriteAllText:
                        //   那样会先在内存里生成一个 1.2MB 的字符串。超过 85KB 就进大对象堆,
                        //   而 LOH 不压缩; 一组存一次, 堆就一格一格往上爬 —— 实测连跑 25 组
                        //   从 174MB 涨到 715MB(约 22MB/组), 整场 94 组推出来就是 2GB 量级,
                        //   跟现场报的"内存翻红"对得上。
                        //   改成直接往文件流里写, 中间不落大字符串。
                        //   顺带先写 .tmp 再替换: 原来 WriteAllText 会先把正式档案截断,
                        //   写一半崩了档案就毁了。
                        string tmpPath = jsonPath + ".tmp";
                        // 缓冲区故意用小的(16KB): 再大就自己变成大对象堆分配了,
                        // 而 LOH 正是这次要治的东西, 别一边治一边添。
                        using (var fs = new FileStream(tmpPath, FileMode.Create, FileAccess.Write, FileShare.None, 16 * 1024))
                        using (var sw2 = new StreamWriter(fs, new UTF8Encoding(false), 16 * 1024))
                        using (var jw = new JsonTextWriter(sw2)) {
                            jw.Formatting = Formatting.Indented;
                            JsonSerializer.CreateDefault().Serialize(jw, package);
                            jw.Flush();
                        }
                        if (File.Exists(jsonPath)) File.Replace(tmpPath, jsonPath, null);
                        else File.Move(tmpPath, jsonPath);
                    } catch (Exception ex) {
                        try { Dispatcher.BeginInvoke(new Action(() => AddLog(Loc.F("Str_Log_AutoSaveGenericFailedFmt", ex.Message)))); } catch { }
                    }
                }
            });

            // 联机同步：服务器 → 编排端 / 编排端 → 服务器；_applyingRemoteSync 防回环
            try { PropagateSyncAfterSave(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_OnlineSyncExceptionFmt", ex.Message)); }

            // 2026-10-08 用户明确要求: 分组数据要落到竞赛库(heat_entries, "分组表")里,
            //   大屏/总排名/成绩发布改成直接查这张表, 不再靠内存对象自己算。
            //   ScheduleMeetDbSyncFromPatch() 原来只在【收到远端编排端推来的补丁】
            //   (HandleEditorPatch) 和 SaveAndPushAssign(只覆盖了泳道互换/接力棒次
            //   /部分追加分组等 9 处调用点)两条路上触发——"项目自动分组"
            //   (AutoGenerateHeats_Click, 现场多半是用这个建的分组)等相当一部分
            //   编辑函数结尾还停在旧版"只调 AutoSaveData()", 从没走到这条同步, heat_entries
            //   永远停在赛事包【导入那一刻】的旧分组, 这正是"张掖市"那种旧数据漏出来的根源
            //   之一。AutoSaveData() 是全系统唯一"存一次档"的公共收尾点(36 处调用), 把同步
            //   钩子挂在这里一次性覆盖所有调用方, 不用再挨个找漏网的编辑函数。
            //   ScheduleMeetDbSyncFromPatch() 自带 2 秒防抖 + SelfCheck 先比对再决定要不要
            //   真重建(没差异就是一次很便宜的查询), 高频调用 AutoSaveData() 不会造成重复重建。
            if (!_meetDb.IsRemote) ScheduleMeetDbSyncFromPatch();
        }

        // 把当前内存状态打包成 CompetitionPackage（AutoSaveData 与同步推送共用）
        private CompetitionPackage BuildCurrentPackage() {
            return new CompetitionPackage {
                CompetitionName = _competitionName,
                CompetitionMode = _competitionMode,
                CompetitionRule = _competitionRule,
                StartDate = GetDatePickerText(StartDatePicker),
                EndDate = GetDatePickerText(EndDatePicker),
                Location = LocationBox.Text,
                PoolLength = _poolConfig.Length,
                LaneCount = _poolConfig.LaneCount,
                Organizer = OrganizerBox.Text,
                Host = HostBox.Text,
                CertCommittee = _certCommitteeText,
                AwardCertRankLimit = _awardCertRankLimit,
                TechnicalDelegate = TechDelegateBox.Text,
                Referee = RefereeBox.Text,
                Starter = "",                 // 2026-05-26 UI 已删除发令员
                Arbiter = ArbiterBox.Text,    // 2026-05-26 仲裁委员（多人逗号分隔）
                ChiefJudge = ChiefJudgeBox.Text,
                Swimmers = _swimmers.ToList(),
                RelayTeams = _relayTeams.ToList(),
                Records = _records.ToList(),
                TeamScores = _teamScores.ToList(),
                Schedule = _schedule.ToList(),
                Events = _events,
                AgeGroups = _ageGroups,
                Genders = _genders,
                Stages = _stages,
                HeatCounts = _heatCounts,
                BibRanges = _bibRanges,
                Units = _units.ToList(),
                StaffList = _staff.ToList(),
                WizardDraft = _wizardDraft,
                LaneCloseSettings = _laneCloseSettings,
                ScoringConfig = _scoringConfig,
                DurationConfig = _durationConfig,
                ProgramBook = _programBook,
                ResultBook = _resultBook,
                DisplayRecordLabel = _displayRecordLabel,
                DisplayRecordTypeName = _displayRecordTypeName,
                DisplayRecordOptions = _displayRecordOptions,
                ConfirmedHeats = _confirmedHeats.ToList(),
                UnlockedHeats = _unlockedHeats.ToList(),    // 2026-09-13 解锁标记也要存, 否则重开档案又锁上
                CheckedInHeats = _checkedInHeats.ToList()
            };
        }

        // AutoSaveData 调用：把整包推给对端（编排↔主服务器双向）
        // _applyingRemoteSync 为 true 时表示当前 Save 正是因为收到了远端推送而触发，不再回推
        // 2026-06-06 P2-B: BuildCurrentPackage 在 UI 线程 (= ObservableCollection 安全读),
        //   JsonConvert + JObject.Parse (反射 50-200ms) + sock.Send (网络 IO) 全扔后台.
        // 2026-08-24 现场事故：400 米比赛中内存突然涨几 GB，清内存也降不下来。
        //   根因在这里 —— ProcessTimingData() 每收到一次触板/盲表/反应时都调 AutoSaveData()，
        //   而本函数会把【整个比赛包】序列化再推给编排端：
        //       BuildCurrentPackage() → JsonConvert.SerializeObject (1.2 MB 字符串)
        //       → JObject.Parse (十几 MB 对象树) → Send
        //   每次触板约 20 MB 分配，1.2 MB 的字符串远超 85 KB 直接进大对象堆(LOH)。
        //   400 米每人 8 次触板 × 8 道 + 盲表/反应时 = 一组上百次事件 ≈ 2 GB。
        //   LOH 默认不压缩，GC 回收了也不还给系统，所以"清内存"看不出效果。
        //   （原注释只算了写盘 IO，没算序列化开销。）
        //
        //   对策：计时中(就位/比赛中)只写盘不推送，攒一个待推标志；
        //   计时复位 / 确认成绩后补推一次完整的。比赛中编排端本来就被禁止改数据
        //   (见 IsPackageApplyBlocked)，不推给它没有任何损失。
        private bool _syncDeferredDuringRace = false;

        // 2026-09-12 比赛中攒下的赛程树重建, 结束后补一次
        private bool _scheduleTreeDirty = false;
        private void FlushScheduleTree() {
            if (!_scheduleTreeDirty) return;
            _scheduleTreeDirty = false;
            try { BuildScheduleTree(); AddLog(Loc.T("Str_Log_ScheduleTreeRebuiltCaughtUp")); } catch { }
        }

        // 2026-09-21 【现场实测到的问题】FinishPatchApply(Assign/MergeHeats 补丁收尾)里的
        //   AutoSaveData()/Broadcast()/PushDataChanged() 原来不管三七二十一, 不管是本机自己
        //   在计时、还是 RTC 当主控本机只是条总线, 一律照做——AutoSaveData() 在 UI 线程上
        //   同步打一次整包快照(慢), Broadcast() 用本机的 _currentEvent/_currentHeat 现算一
        //   帧塞进跟 RTC 共用的那条大屏/计时网页 socket 流。RTC 当主控时本机这两个字段是
        //   刻意留空的(见 NoteRtcRaceState 的说明), 于是编排端随手改一个跟当前比赛无关的
        //   项目, 主服务器就会往 RTC 正确的实时帧中间硬插一帧"空/别的组"的数据——大屏/RTC
        //   画面因此闪一下、瞬间冒出不该有的分段成绩。跟 _meetDb.LiveActive 早前堵住的那个
        //   整包漏洞是同一类问题, 但这条路走的是补丁(EDITOR_PATCH), 不受那道闸门管——这里
        //   补上同一道闸: 只要临时数据库还在用(不管是谁在用), 这三步全部押后, 比赛结束
        //   (临时数据库释放)后由 FlushPatchDeferred 补上。
        private bool _patchSaveDirty = false;
        private bool _patchBroadcastDirty = false;
        private void FlushPatchDeferred() {
            if (_meetDb.LiveActive) return;   // 还在比, 不该现在补
            FlushScheduleTree();
            bool save = _patchSaveDirty, bcast = _patchBroadcastDirty;
            _patchSaveDirty = false; _patchBroadcastDirty = false;
            if (save) { try { AutoSaveData(); } catch (Exception ex) { AddLog(Loc.F("Str_Log_DeferredAssignSaveFailedFmt", ex.Message)); } }
            if (bcast) {
                try {
                    Broadcast();
                    PushDataChanged("assign");
                    AddLog(Loc.T("Str_Log_DeferredAssignPushedCaughtUp"));
                } catch (Exception ex) { AddLog(Loc.F("Str_Log_DeferredAssignPushFailedFmt", ex.Message)); }
            }
        }

        // 2026-08-24 比赛中攒下的同步, 结束后补推一次完整的
        private void FlushDeferredSync() {
            FlushScheduleTree();          // 2026-09-12 顺带把欠的赛程树重建补上
            FlushPatchDeferred();         // 2026-09-21 顺带把攒下的编排补丁广播/落盘也补上
            if (!_syncDeferredDuringRace) return;
            _syncDeferredDuringRace = false;
            if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) return;
            try {
                PropagateSyncAfterSave();
                AddLog(Loc.T("Str_Log_DeferredDataSyncPushedCaughtUp"));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_DeferredSyncPushFailedFmt", ex.Message));
            }
        }

        private void PropagateSyncAfterSave() {
            if (_applyingRemoteSync) return;
            // 2026-09-12 这次改动正走【增量补丁】那条路, 对端已经收到了 ——
            //   再推一次整包是白费, 而且比赛中整包必被拒, 还要弹"未保存"吓操作员一跳。
            if (_patchInFlight) return;
            if (string.IsNullOrEmpty(_competitionName)) return;
            if (!IsScheduleEditorMode &&
                (_raceState == RaceState.Ready || _raceState == RaceState.Racing)) {
                _syncDeferredDuringRace = true;   // 比赛结束后补推
                return;
            }

            if (IsScheduleEditorMode) {
                if (_editorSyncClient != null && _editorSyncClient.IsConnected) {
                    var pkg = BuildCurrentPackage();
                    var clientCap = _editorSyncClient;
                    System.Threading.Tasks.Task.Run(() => {
                        try {
                            string pkgJson = JsonConvert.SerializeObject(pkg);
                            var envelope = new JObject();
                            envelope["type"] = "EDITOR_PUSH_PACKAGE";
                            envelope["package"] = JObject.Parse(pkgJson);
                            clientCap.Send(envelope.ToString(Formatting.None));
                        } catch (Exception ex) {
                            try { Dispatcher.BeginInvoke(new Action(() => AddLog(Loc.F("Str_Log_EditorPushPackageSendFailedFmt", ex.Message)))); } catch { }
                        }
                    });
                }
            } else {
                PushDataChanged("meet");    // 2026-09-13 本机数据变了, 通知非大屏客户端(几十字节)
                if (_editorSockets.Count > 0) {
                    try {
                        var pkg = BuildCurrentPackage();
                        string pkgJson = JsonConvert.SerializeObject(pkg);
                        var env = new JObject();
                        env["type"] = "EDITOR_PACKAGE";
                        env["package"] = JObject.Parse(pkgJson);
                        string envStr = env.ToString(Formatting.None);
                        // 2026-06-18 per-socket 队列, 不再 Task.Run + 同步 send 串行
                        foreach (var sock in _editorSockets.ToList()) {
                            EnqueueToSocket(sock, envStr);
                        }
                    } catch (Exception ex) {
                        AddLog(Loc.F("Str_Log_EditorPackageBroadcastFailedFmt", ex.Message));
                    }
                }
            }
        }

        // 主服务器侧：把当前 CompetitionPackage 包成 EDITOR_PACKAGE 消息
        private string BuildEditorPackageMessage() {
            var package = BuildCurrentPackage();
            string pkgJson = JsonConvert.SerializeObject(package);
            var env = new JObject();
            env["type"] = "EDITOR_PACKAGE";
            env["package"] = JObject.Parse(pkgJson);
            return env.ToString(Formatting.None);
        }

        // 主服务器侧：响应 EDITOR_IDENTITY / EDITOR_PULL_PACKAGE，把当前整包发给指定 socket
        private void SendEditorPackageTo(IWebSocketConnection socket) {
            try {
                if (string.IsNullOrEmpty(_competitionName)) return;   // 服务器还没加载比赛，没法推
                EnqueueToSocket(socket, BuildEditorPackageMessage());   // 2026-06-18 per-socket 队列
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_PushEditorPackageFailedFmt", ex.Message));
            }
        }

        // 主服务器侧：收到编排端 EDITOR_PUSH_PACKAGE，覆盖本地并广播给其它客户端
        // 2026-08-24 现场事故：主服务器正在计时时，另一台机器上的编排端保存修改，
        //   走的是"推整包 → 主服务器 ApplyPackageInMemory → LoadCompetitionFromFile"这条路，
        //   等于**在比赛中把主服务器整库重载**。后果有三：
        //     · 编排端改的东西存不住（主服务器随后又用自己内存里那份推回去，把它覆盖）
        //     · 重载瞬间 _swimmers/_relayTeams 整批换成新对象，正在广播的当前组数据
        //       引用到旧对象 → 广播出残缺 JSON → display.html 抛异常黑屏
        //     · 正在计时那一组的成绩有被冲掉的风险
        //   现在把这个窗口关上：计时中、或成绩已录但未确认时，一律拒绝并回执告知。
        //
        // 2026-09-12 "治本是改成发增量消息" —— 已经动工了, 见 EDITOR_PATCH / HandleEditorPatch。
        //   并组走补丁那条路, 主服务器只改补丁点名的那几个人, 不重载整库,
        //   所以【比赛中照收】, 挡的只有正在比的那一组(ApplyMergeHeats 里判)。
        //   这里这个一刀切只管【整包】那条老路 —— 整包一来就是整库重载, 比赛中
        //   照旧绝对不能收。其余编排操作还在整包上, 以后一项一项搬成补丁。
        private bool IsPackageApplyBlocked(out string why) {
            why = null;
            // 2026-09-19【用户明确要求】正在比的这一组用的是当前组临时数据库(current_heat.db,
            //   _meetDb.LiveActive 就是这个库"还在用"的信号)——这是本机判断"这一组是否
            //   还没了结"的最权威依据, 比下面的 _raceState/_resultConfirmed 更早一步就该拦。
            //   典型缝隙: ConfirmResult_Click 里 _raceState 先变成 Finished、_resultConfirmed
            //   先置 true, 过几步才真正调用 CommitLiveHeat() 把临时库提交进 meet.db 并释放——
            //   这几步之间 _raceState 那道检查已经放行了, 但临时库其实还没交完, 这里单独补
            //   一道最前置的拦, 不跟其它检查共用一套"像不像在比"的推断逻辑。
            if (_meetDb.LiveActive) {
                why = "本机当前组临时数据库使用中（比赛未确认/未提交）";
                return true;
            }
            // ── 2026-09-13 本机自己不计时时, 原来这里整个放行 ──────────────────
            //   本意是: 比赛控制安排在另一台机器上独立进行, 主服务器这台只管竞赛数据,
            //   它自己不计时, 就没有"正在广播的当前组数据被换掉"这回事。
            // 2026-09-19【订正, 现场事故】——这个前提只想到了"本机不计时"这一半, 漏了
            //   "但那台真正计时的机器(RTC/role=timing 的普通 exe)可能正在比"这一半。
            //   用户实拍到: 编排端存了一次接力队信息(走的还是整包这条老路, 没搬成补丁),
            //   主服务器自己确实空闲、照单全收 → ApplyPackageInMemory 整库重载 →
            //   HandleEditorPushPackage 末尾 Broadcast() 把这份重载后的数据广播出去 ——
            //   计时端收到这一帧, 它自己会话内的硬件按钮状态(TP/MB 开关等, 压根不在
            //   "竞赛包"这份数据里, 是那台机器自己进程内的现场状态)被这次广播带的副作用
            //   冲乱了, 现场直接看到"TP/MB 从打开变成关闭, 收不到成绩了", 而当时正在
            //   比赛中。这里补上第二道拦：本机不计时不假, 但只要计时端(RTC 每 100ms
            //   转发一次状态, 见 NoteRtcRaceState)半分钟内报的是"已就位/比赛中",
            //   同样不能收整包——跟本机自己在计时同一个道理, 同一句话。
            if (IsScoringServerNoTiming) {
                bool rtcBusy = (_rtcRaceState == "READY" || _rtcRaceState == "RACING")
                    && _rtcSeenAt != DateTime.MinValue && (DateTime.Now - _rtcSeenAt).TotalSeconds <= 30;
                if (!rtcBusy) return false;
                why = "计时端正在比赛（" + (_rtcRaceState == "READY" ? "已就位" : "比赛中") + "）";
                return true;
            }

            if (_raceState == RaceState.Ready || _raceState == RaceState.Racing) {
                why = "主服务器正在计时（" + (_raceState == RaceState.Ready ? "已就位" : "比赛中") + "）";
                return true;
            }
            // 成绩已录但还没确认：重载会把内存里这批成绩冲掉
            if (!string.IsNullOrEmpty(_currentEvent) && _currentHeat > 0 && !_resultConfirmed) {
                bool anyResult = false;
                foreach (var s in GetCurrentHeatSwimmers()) {
                    var r = s.Results.FirstOrDefault(x => x.Stage == _currentStage && x.Heat == _currentHeat);
                    if (r != null && (r.FinalTime > 0 || !string.IsNullOrEmpty(r.Status))) { anyResult = true; break; }
                }
                if (anyResult) {
                    why = string.Format("第{0}组成绩已录入但尚未确认", _currentHeat);
                    return true;
                }
            }
            return false;
        }

        private void HandleEditorPushPackage(IWebSocketConnection sender, JObject msg) {
            try {
                var pkgToken = msg["package"];
                if (pkgToken == null) return;
                var package = pkgToken.ToObject<CompetitionPackage>();
                if (package == null) return;

                string why;
                if (IsPackageApplyBlocked(out why)) {
                    // 明确回执 —— 原来是静默失败, 编排端以为存上了
                    try {
                        var rej = new JObject();
                        rej["type"] = "EDITOR_PUSH_REJECTED";
                        rej["reason"] = why;
                        if (sender != null) sender.Send(rej.ToString(Formatting.None));
                    } catch { }
                    AddLog(Loc.F("Str_Log_RejectEditorPushFmt", why));
                    return;
                }

                ApplyPackageInMemory(package);     // 应用 + 落盘（AutoSaveData 会因 _applyingRemoteSync 跳过回推）

                // 其它在线编排端同步：把刚收到的包转发给除发送方外的编排客户端
                string env = BuildEditorPackageMessage();
                foreach (var sock in _editorSockets.ToList()) {
                    if (sock == sender) continue;
                    EnqueueToSocket(sock, env);   // 2026-06-18 per-socket 队列
                }
                // 其它端（HTML/EXE 大屏等）一律走标准 Broadcast
                Broadcast();
                AddLog(Loc.T("Str_Log_EditorPushPackageAppliedBroadcast"));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ApplyEditorPushPackageFailedFmt", ex.Message));
            }
        }

        // ── 全开/关闭设备覆盖处理 (2026-05-13) ──
        // 命令格式：{ type:"DEVICE_OVERRIDE", lane: -1|0~9, mode: "allOpen"|"normal" }
        //   lane = -1 → 全部泳道；其它 → 指定单道
        //   mode = "allOpen" → 该道(或全道)进入"全开"，任意信号都按正式成绩接收
        //   mode = "normal"  → 恢复正常状态机过滤
        private void HandleDeviceOverride(JObject msg) {
            int lane;
            try { lane = msg["lane"] != null ? (int)msg["lane"] : -1; } catch { lane = -1; }
            string mode = msg["mode"] != null ? msg["mode"].ToString() : "";
            if (mode == "allOpen") {
                _forceAllOpenLanes.Add(lane);
                AddLog(lane == -1 ? Loc.T("Str_Log_AllLanesForceOpenAll") : Loc.F("Str_Log_LaneForceOpenFmt", lane));
            } else if (mode == "normal") {
                if (lane == -1) { _forceAllOpenLanes.Clear(); AddLog(Loc.T("Str_Log_AllLanesFilterRestored")); }
                else { _forceAllOpenLanes.Remove(lane); AddLog(Loc.F("Str_Log_LaneFilterRestoredFmt", lane)); }
            } else {
                AddLog(Loc.F("Str_Log_DeviceOverrideUnknownModeFmt", mode));
                return;
            }
            // 2026-05-13 联动下发硬件 0x4C Set_ForceAllOpen：
            //   D3 = 0xFF 表示全部泳道，0~9 表示单道
            //   D4 = 1 全开 / 0 关闭
            if (_timingBridge != null && _timingBridge.IsConnected) {
                try {
                    byte laneByte = (byte)(lane == -1 ? 0xFF : (byte)lane);
                    byte modeByte = (byte)(mode == "allOpen" ? 1 : 0);
                    _timingBridge.SendFullFrame(0x4C, laneByte, modeByte);
                    AddLog(Loc.F("Str_Log_Hw4cSentFmt", laneByte, modeByte));
                } catch (Exception ex) {
                    AddLog(Loc.F("Str_Log_Hw4cSendFailedFmt", ex.Message));
                }
            } else {
                AddLog(Loc.T("Str_Log_NoHwSoftwareSwitchedNotSynced"));
            }
            UpdateLaneStatusDisplay();
            Broadcast();
        }

        // ─── 编辑锁：服务器端命令处理 ───
        // 编排/主服务器若想编辑某条数据，先 TryAcquireEditLock(key) — 主服务器自己直接占；
        // 编排端发 LOCK_REQUEST → 服务器查表，若被别人占就回 granted=false+holder，否则记账+回 granted=true。
        private void HandleLockRequest(IWebSocketConnection socket, JObject msg) {
            string key = msg["key"] != null ? msg["key"].ToString() : "";
            string corrId = msg["corrId"] != null ? msg["corrId"].ToString() : "";
            string clientName = msg["clientName"] != null ? msg["clientName"].ToString() : "未知客户端";
            if (string.IsNullOrEmpty(key)) return;
            bool granted;
            string holder = null;
            lock (_editLocks) {
                EditLock existing;
                if (_editLocks.TryGetValue(key, out existing)) {
                    if (existing.HolderSocket == socket) {
                        granted = true;   // 同一连接重复申请视为成功
                    } else {
                        granted = false;
                        holder = existing.HolderName;
                    }
                } else {
                    _editLocks[key] = new EditLock {
                        HolderSocket = socket, HolderName = clientName, AcquiredAt = DateTime.Now
                    };
                    granted = true;
                }
            }
            var reply = new JObject();
            reply["type"] = "LOCK_REPLY";
            reply["corrId"] = corrId;
            reply["key"] = key;
            reply["granted"] = granted;
            if (holder != null) reply["holder"] = holder;
            try { socket.Send(reply.ToString(Formatting.None)); } catch { }
            if (!granted) AddLog(Loc.F("Str_Log_LockRejectedFmt", clientName, key, holder));
        }

        private void HandleLockRelease(IWebSocketConnection socket, JObject msg) {
            string key = msg["key"] != null ? msg["key"].ToString() : "";
            if (string.IsNullOrEmpty(key)) return;
            lock (_editLocks) {
                EditLock existing;
                if (_editLocks.TryGetValue(key, out existing) && existing.HolderSocket == socket) {
                    _editLocks.Remove(key);
                }
            }
        }

        private void ReleaseLocksHeldBy(IWebSocketConnection socket) {
            lock (_editLocks) {
                var toRemove = new List<string>();
                foreach (var kv in _editLocks) {
                    if (kv.Value.HolderSocket == socket) toRemove.Add(kv.Key);
                }
                foreach (var k in toRemove) _editLocks.Remove(k);
            }
        }

        // ─── 编辑锁：统一 API（两端共用调用点）───
        // 服务器模式：直接占本机字典；编排模式：发 LOCK_REQUEST 等 LOCK_REPLY（带 2 秒超时，超时按成功放行）
        // 返回 true = 取到锁；false = 被别人锁住，holder 是对方显示名。离线/未连接也按 true 处理。
        private bool TryAcquireEditLock(string key, out string holder) {
            holder = null;
            if (string.IsNullOrEmpty(key)) return true;
            if (IsScheduleEditorMode) {
                if (_editorSyncClient == null || !_editorSyncClient.IsConnected) {
                    return true;  // 离线 → 直接放行
                }
                string corrId = Guid.NewGuid().ToString("N");
                var evt = new System.Threading.ManualResetEventSlim(false);
                lock (_lockSync) { _lockWaiters[corrId] = evt; }
                var req = new JObject();
                req["type"] = "LOCK_REQUEST";
                req["key"] = key;
                req["corrId"] = corrId;
                req["clientName"] = "编排端 " + Environment.MachineName;
                _editorSyncClient.Send(req.ToString(Formatting.None));
                bool gotReply = evt.Wait(2000);
                JObject reply = null;
                lock (_lockSync) {
                    _lockWaiters.Remove(corrId);
                    if (_lockReplies.TryGetValue(corrId, out reply)) _lockReplies.Remove(corrId);
                }
                if (!gotReply || reply == null) return true;   // 超时按成功放行（容错）
                bool granted = reply["granted"] != null && (bool)reply["granted"];
                if (!granted) holder = reply["holder"] != null ? reply["holder"].ToString() : "其它客户端";
                if (granted) lock (_heldLocks) { _heldLocks.Add(key); }
                return granted;
            } else {
                // 主服务器：直接占本机字典；同时同步告知所有在线编排端
                lock (_editLocks) {
                    EditLock existing;
                    if (_editLocks.TryGetValue(key, out existing)) {
                        if (existing.HolderSocket == null) return true;   // 本机已占，再占视为成功
                        holder = existing.HolderName;
                        return false;
                    }
                    _editLocks[key] = new EditLock {
                        HolderSocket = null, HolderName = "主服务器(本机)", AcquiredAt = DateTime.Now
                    };
                    return true;
                }
            }
        }

        // 编辑入口统一外壳：占锁 → 执行 body → 释放锁。被锁时弹窗提示，不执行 body。
        // 用法：RunWithEditLock("record:xxx", "纪录", delegate { /* 原编辑逻辑 */ });
        private void RunWithEditLock(string key, string entityLabel, Action body) {
            string holder;
            if (!TryAcquireEditLock(key, out holder)) {
                AppMessageBox.Show(
                    Loc.F("Str_Msg_EntityBeingEditedFmt", entityLabel, holder),
                    Loc.T("Str_MsgTitle_CannotEdit"), MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }
            try { body(); } finally { ReleaseEditLock(key); }
        }

        private void ReleaseEditLock(string key) {
            if (string.IsNullOrEmpty(key)) return;
            if (IsScheduleEditorMode) {
                lock (_heldLocks) { if (!_heldLocks.Remove(key)) return; }
                if (_editorSyncClient == null || !_editorSyncClient.IsConnected) return;
                var msg = new JObject();
                msg["type"] = "LOCK_RELEASE";
                msg["key"] = key;
                _editorSyncClient.Send(msg.ToString(Formatting.None));
            } else {
                lock (_editLocks) {
                    EditLock existing;
                    if (_editLocks.TryGetValue(key, out existing) && existing.HolderSocket == null) {
                        _editLocks.Remove(key);
                    }
                }
            }
        }

        // 把整包应用到内存 + 落盘。复用 LoadCompetitionFromFile 已有的字段恢复逻辑：
        // 写一个临时 JSON 文件再走 LoadCompetitionFromFile，避免重复维护两份字段填充代码。
        private void ApplyPackageInMemory(CompetitionPackage package) {
            if (package == null) return;
            _applyingRemoteSync = true;
            try {
                string tmpDir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database");
                if (!Directory.Exists(tmpDir)) Directory.CreateDirectory(tmpDir);
                // 直接覆盖正式文件即可（编排端、主服务器都把这份 JSON 当作权威数据）
                string targetName = string.IsNullOrEmpty(package.CompetitionName) ? "_remote_sync" : package.CompetitionName;
                string targetPath = IOPath.Combine(tmpDir, targetName + ".json");
                string json = JsonConvert.SerializeObject(package, Formatting.Indented);
                File.WriteAllText(targetPath, json, Encoding.UTF8);
                File.WriteAllText(
                    IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "last_competition.txt"),
                    targetName, Encoding.UTF8);
                LoadCompetitionFromFile(targetPath);
            } finally {
                _applyingRemoteSync = false;
            }
        }

        private void LoadLastCompetition() {
            try {
                string lastFile = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "last_competition.txt");
                if (File.Exists(lastFile)) {
                    string name = File.ReadAllText(lastFile, Encoding.UTF8).Trim();
                    string jsonFile = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database", name + ".json");
                    if (File.Exists(jsonFile)) {
                        LoadCompetitionFromFile(jsonFile);
                        return;
                    }
                }
            } catch { }
        }

        // ── 2026-08-24 迁移第 2 步：比赛热路径改走当前组库 ─────────────────
        // 就位 → OpenLiveHeat()   把本组名单灌进 current_heat.db 并加锁
        // 比赛中 → SaveHeatProgress()  只写那个几十 KB 的小库
        // 确认成绩 → CommitLiveHeat()  回写竞赛库、查破纪录、解锁、清小库
        //
        // 当前组库没就绪（库里找不到这一组、导入失败…）时一律降级回
        // AutoSaveData()，行为和改之前一模一样 —— 比赛不能因为新库出问题而停。

        // JSON 兜底的最小间隔。小库已经完整记着本组成绩了，JSON 只是防
        // 进程崩了之后老的恢复路径（重新加载档案）读不到东西。
        private DateTime _lastHeatJsonSave = DateTime.MinValue;
        private static readonly TimeSpan HeatJsonSaveGap = TimeSpan.FromSeconds(15);

        private void OpenLiveHeat() {
            try {
                // 2026-08-28 原来这里是【静默 return】—— 库没打开就什么都不做, 一声不吭。
                //   后果: 就位时当前组库没建, 确认成绩时 LiveActive=false 又静默跳过回写,
                //   成绩只进了内存/JSON, meet.db 一条都没有, 而界面上一切正常。
                //   今天挖出的问题清一色是这个毛病, 所以让它开口。
                if (!_meetDb.IsOpen) {
                    AddLog(Loc.T("Str_Log_MeetDbNotOpenSkipHeatDb"));
                    return;
                }
                if (_currentHeat <= 0 || string.IsNullOrEmpty(_currentEvent)) {
                    AddLog(Loc.T("Str_Log_NoEventStageSkipHeatDb"));
                    return;
                }
                _meetDb.LiveOpen(_currentAgeGroup, _currentGender, _currentEvent,
                                 _currentStage, _currentHeat, Environment.MachineName);
                if (!_meetDb.LiveActive)
                    AddLog(Loc.T("Str_Log_HeatDbNotBuiltWontWriteBack"));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_HeatDbOpenFailedFmt", ex.Message)); }
        }

        private void DiscardLiveHeat() {
            try { _meetDb.LiveDiscard(Environment.MachineName); } catch { }
        }

        /// <summary>
        /// 2026-09-18 确认成绩时破的纪录只写进了真身那份 records 表(LiveCommit/CommitHeatDirect
        /// 内部经 _meet 完成, DB 这一步一直是对的), 但没有一处把新纪录同步回本机内存的 _records——
        /// 泳道实时状态顶栏"MR: xxx CR: xxx"读的正是这份内存, 于是破纪录那一刻起, 连正在确认
        /// 这一组的机器自己, 顶栏都还显示着旧纪录, 要等重新导入/重启才会变, 别的机器更不用说。
        /// 记录编辑(手工改纪录)那条路早就有 PushChangedRecords/ApplyRecordsPatch 这一套经
        /// EditorSyncClient 同步给别的机器的机制, 这里只是把"自动破纪录"接进同一条已有的管道——
        /// 不新增协议、不新增轮询, 跟手工改纪录走的是同一份代码。
        /// </summary>
        private void ApplyRecordBreaksToLocalState(List<SwimmingScoreboard.Db.RecordBreak> breaks) {
            if (breaks == null || breaks.Count == 0) return;
            try {
                var before = SnapshotRecords();
                foreach (var b in breaks) {
                    if (b == null || b.Record == null) continue;
                    string k = (b.Record.AgeGroup ?? "") + "|" + (b.Record.Gender ?? "") + "|"
                             + (b.Record.EventName ?? "") + "|" + (b.Record.RecordType ?? "");
                    var cur = _records.FirstOrDefault(x => x != null && RecordKey(x) == k);
                    if (cur == null) continue;   // 内存里对不上号(纪录清单没导过这一条)就不硬凑, 宁可让它继续显示旧值
                    cur.HolderName = b.NewHolder ?? cur.HolderName;
                    cur.HolderCountry = b.NewCountry ?? cur.HolderCountry;
                    cur.Time = b.NewTime; cur.TimeInSeconds = b.NewTime;
                    cur.Date = DateTime.Now.ToString("yyyy-MM-dd");
                }
                try { UpdateRecordDisplay(); } catch { }   // 本机顶栏 MR/CR 立即刷新
                try { RefreshRecordFilterCombos(); ApplyRecordFilter(); } catch { }
                PushChangedRecords(before);   // 同步给别的联着 EditorSyncClient 的机器(RTC/编排端)
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_RecordBrokenSyncFailedFmt", ex.Message)); }
        }

        /// <summary>
        /// 2026-09-14 当前组库没激活时的回写路径 —— 直接把内存里这一组写进竞赛库。
        ///
        /// 什么时候会走到这儿:
        ///   · 【解锁本组成绩 → 改完 → 再确认】第一次确认时 LiveCommit 已经把当前组库
        ///     提交并关掉了, 第二次确认时它是关着的;
        ///   · 当前组库本来就没就绪(库里找不到这一组 / SQLite 加载失败)。
        ///
        /// 原来这两种情况都只记一行日志就 return —— 成绩留在内存和 JSON 里, 库里还是旧的。
        /// 而 10 秒一次的库回读(ApplyHeatFromDb)会拿库里那份旧值把内存盖回去:
        /// 现场看到的就是"改好了、大屏也对了, 过一会儿又变回改之前"。
        /// </summary>
        private void CommitHeatDirectToDb() {
            try {
                var live = new SwimmingScoreboard.Db.LiveHeat {
                    AgeGroup = _currentAgeGroup ?? "", Gender = _currentGender ?? "",
                    EventName = _currentEvent ?? "", Stage = _currentStage ?? "",
                    Heat = _currentHeat, TotalHeats = _totalHeats,
                    RaceState = "confirmed", ResultConfirmed = true,
                    Lanes = BuildLiveLanes()
                };
                var breaks = _meetDb.CommitHeatDirect(live, Environment.MachineName);
                foreach (var b in breaks) {
                    AddLog(Loc.F("Str_Log_RecordBrokenHeatFmt",
                        b.Record.Abbr, b.Record.EventName,
                        TimeFormatter.Format(b.Record.TimeSeconds), b.Record.HolderName,
                        TimeFormatter.Format(b.NewTime), b.NewHolder, b.IsTie ? " 平" : ""));
                }
                ApplyRecordBreaksToLocalState(breaks);
                try { FlushConfigToDb(); } catch { }
                // 写完再回读一次 —— 名次以库为准, 和正常那条路一个待遇
                ApplyHeatFromDb(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat);
                // 2026-09-15 【解锁再改再确认】漏掉了"重新生成组排名表(定稿)"这一步 ——
                //   heat_entries.rank 在 CommitHeatFrom 里确实当场重算对了(RecomputeRanks
                //   是跨组的, 见 ResultOrdering), 但"项目成绩打印"读的是 event_rankings
                //   这张【单独的定稿快照表】, 只有正常确认路径(CommitLiveHeat)才会在
                //   "全部组已确认"时调 GenerateEventRankingIfComplete 重新生成它。
                //   这条"解锁后直接回写"的路一直没调这一步 —— 于是改完重新确认后,
                //   heat_entries 里是对的、内存也是对的, 唯独定稿表还停在改之前那次的
                //   旧快照上, 打印出来就是"全部名次5个第9名, 一个'-'"这种明显不对的老照片。
                //   现在和正常路径同一个待遇: 全部组确认了就问一句、生成一次。
                TryGenerateEventRankingAfterCommit(_currentAgeGroup, _currentGender, _currentEvent, _currentStage);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_HeatResultDirectWriteFailedFmt", ex.Message));
            }
        }

        /// <summary>
        /// 2026-09-15 从 CommitLiveHeat 里提出来, 供正常确认路径和"解锁后直接回写"路径
        /// 共用同一份"全部组确认完就重新生成定稿表"逻辑 —— 两条路都会让 heat_entries.rank
        /// 变新, 定稿表 event_rankings 也必须两条路都跟着刷新, 不能只顾一条。
        /// </summary>
        private void TryGenerateEventRankingAfterCommit(string ageGroup, string gender, string eventName, string stage) {
            try {
                string _ag = ageGroup, _gd = gender, _ev = eventName, _st = stage;
                int made = _meetDb.GenerateEventRankingIfComplete(_ag, _gd, _ev, _st,
                    Environment.MachineName,
                    delegate() {
                        return AppMessageBox.Show(
                            Loc.F("Str_Msg_GenEventRankingFmt",
                                _ag, Loc.GenderDisplay(_gd), _ev, Loc.StageDisplay(_st)),
                            Loc.T("Str_MsgTitle_GenEventRanking"), MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes;
                    });
                if (made > 0) {
                    // 2026-09-18 生成/写表(上面 GenerateEventRankingIfComplete)和补空道试游
                    //   占位行(AppendTriPlaceholdersToEventRanking → AppendTriPlaceholderRankingRows)
                    //   现在统一经 IMeetService(_meet) 直接调用, 单机/联机都真正落在真身那份库
                    //   上——不再需要 PushGenerateEventRanking 经 EditorSyncClient 绕一圈去通知
                    //   服务器(那条老路子按 exe 名字判"是不是 RemoteTimingControl", 漏了"role=timing
                    //   的普通 SwimmingScoreboard.exe 当计时端"这种同样合法的部署, 见
                    //   MeetContracts.IMeetService.GenerateEventRankingIfComplete 的说明), 也不再
                    //   要求这台机器必须连着 EditorSyncClient 才补得上空道试游占位行。
                    AppendTriPlaceholdersToEventRanking(_ag, _gd, _ev, _st);
                }
            }
            catch (Exception ex) { AddLog(Loc.F("Str_Log_GenHeatRankingTableFailedFmt", ex.Message)); }
        }

        /// <summary>
        /// 2026-09-16 GenerateEventRankingIfComplete 成功之后调: 把这个 round/event 下所有
        /// "空道试游"(EmptyTriMarker)占位运动员收集出来, 追加进 event_rankings —— 这些人
        /// 从来不会自己进 heat_entries(见 CreateEmptyLaneTriSwimmer 的注释), 上面那次生成天生
        /// 看不到他们。在 RTC/计时端上调用时(_local 是空副本)AppendTriPlaceholderRankingRows
        /// 内部会因为查不到刚生成的 event_rankings 行而直接跳过, 不会写出脏数据 —— 真正落地
        /// 只会发生在事实上写了表的那台机器(通常是主服务器)。
        /// </summary>
        private void AppendTriPlaceholdersToEventRanking(string ageGroup, string gender, string eventName, string stage) {
            try {
                var list = new List<SwimmingScoreboard.Db.TriPlaceholderInfo>();
                foreach (var sw in _swimmers) {
                    if (sw.Notes != EmptyTriMarker) continue;
                    if ((sw.EventName ?? "") != eventName || (sw.AgeCategory ?? "") != (ageGroup ?? "")) continue;
                    if (!(sw.Gender == gender || gender == "男女" || sw.Gender == "男女")) continue;
                    var r = sw.GetResultForStage(stage);
                    if (r == null || r.Heat <= 0) continue;
                    list.Add(new SwimmingScoreboard.Db.TriPlaceholderInfo {
                        Heat = r.Heat, Lane = r.Lane, FinalTime = r.FinalTime, Name = sw.Name ?? ""
                    });
                }
                if (list.Count > 0) _meetDb.AppendTriPlaceholderRankingRows(ageGroup, gender, eventName, stage, list);
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_TriPlaceholderRowFailedFmt", ex.Message)); }
        }

        private void CommitLiveHeat() {
            if (!_meetDb.LiveActive) {
                // 2026-09-14 原来这里只记一行日志就走 —— 解锁改完再确认时成绩就这么丢在
                //   内存里没进库, 十秒后被库里的旧值盖回去。现在改成直接回写。
                AddLog(Loc.T("Str_Log_HeatDbNotActiveDirectWrite"));
                CommitHeatDirectToDb();
                return;
            }
            var breaks = _meetDb.LiveCommit(Environment.MachineName);
            foreach (var b in breaks) {
                AddLog(Loc.F("Str_Log_RecordBrokenHeatFmt",
                    b.Record.Abbr, b.Record.EventName,
                    TimeFormatter.Format(b.Record.TimeSeconds), b.Record.HolderName,
                    TimeFormatter.Format(b.NewTime), b.NewHolder, b.IsTie ? " 平" : ""));
            }
            ApplyRecordBreaksToLocalState(breaks);
            // 2026-08-31 比赛期间欠下的参数/设备状态, 到这一步一并补进库。
            //   顺序: 先补参数, 再回读成绩 —— 都在Loc.T("Str_MsgTitle_Confirm")这一个动作里完成。
            try { FlushConfigToDb(); } catch { }
            // 2026-08-30 成绩确定了 —— 从库里把这一组读回来, 覆盖内存。
            //   从这一刻起这组的名次只有库里那一份, 打印/大屏/查询都用它, 谁都别再算。
            ApplyHeatFromDb(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat);

            // 2026-08-31 如果这个项目【所有组都确认了】, 生成组排名表(定稿)。
            //   判定用"是不是全部确认", 不是"组次号最大" —— 中间可能有取消的组。
            //   生成前必须弹窗确认: 这是定稿动作(晋级依据/最终名次), 万一最后一组是
            //   误确认的, 定了稿再回头改就麻烦了。
            // 2026-09-15 这段跟"解锁后直接回写"共用, 提到 TryGenerateEventRankingAfterCommit 里去了。
            TryGenerateEventRankingAfterCommit(_currentAgeGroup, _currentGender, _currentEvent, _currentStage);
        }

        /// <summary>
        /// 把一组成绩从【竞赛库】读回来覆盖内存模型。
        ///
        /// 这是"成绩确定后只调数据库"的落地点。库里存着名次(组内 + 项目内)、成绩差、
        /// 并列、晋级标记, 内存原来装不下, 各个视图只好自己再算一遍 —— 口径还不一样,
        /// 于是出现过"打印出来的名次和大屏上的不一样""库里和界面上不一样"。
        /// 现在这些值一律以库为准, 内存只是它的镜像。
        ///
        /// 回读失败不阻断比赛: 内存里原来那份还在, 只是会在日志里明确说一声。
        /// </summary>
        /// <summary>
        /// 2026-08-31 把某个 (组别,性别,项目,赛次) 的【所有组】从竞赛库重新读一遍。
        ///
        /// 为什么需要: ApplyHeatFromDb 只在【本机确认成绩那一刻】跑一次。别的计算机
        /// (计时端、另一台控制台)往库里写了成绩或改了名次, 本机内存根本不知道 ——
        /// 于是"库里是新的、界面上是旧的", 而且不报错。
        /// 所以查询/打印之前必须先从库刷一遍, 拿库里的当准。
        ///
        /// ageGroup 传空表示"全部": 那就把内存里这个项目涉及到的组别挨个刷。
        /// </summary>
        // 2026-08-31 上次从库读到的各组"变更指纹"。只有指纹变了的组才重新读。
        private readonly Dictionary<string, string> _dbHeatStamps =
            new Dictionary<string, string>(StringComparer.Ordinal);

        /// <summary>
        /// 2026-08-31 【增量】从竞赛库刷新: 先用一条轻查询看哪些组变过, 只读变了的那几组。
        ///
        /// 上一版是 RefreshAllFromDb —— 每次开报表把全场成绩整个读一遍。
        /// 组数少时看不出来, 数据一大就是占内存、拖慢、还挤占别的程序 ——
        /// 这就是这个项目吃过大亏的"整包读写"。改掉。
        ///
        /// 代价: 全场没人改过时, 只有一条 GROUP BY 查询, 一行成绩都不读。
        /// 别的计算机改了哪几组, 就只读那几组。
        /// </summary>
        // ── 2026-08-31 大屏/网页的数据来自服务器内存, 而内存只在"本机确认"和
        //   "收到回推"时才从库刷新。第三台机器直接改了库(赛后改成绩、另一台控制台
        //   确认), 服务器不会知道, 大屏就一直是旧的。
        //
        //   这里用一个低频轮询补上: 每 10 秒跑一次【增量】刷新 —— 也就是一条
        //   GROUP BY 轻查询; 没人改过就一行成绩都不读, 几乎零开销。
        //   查询已经是"写入优先"的(见 MeetDb), 挡不住触板写入。
        //
        //   比赛进行中直接跳过: 那会儿正在写当前组, 没必要也不该去动内存。
        //   只有真的读到变化才 Broadcast, 不会平白增加大屏推送。
        private DispatcherTimer _dbPollTimer;

        private void StartDbPoll() {
            if (_dbPollTimer != null) return;
            _dbPollTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(10) };
            _dbPollTimer.Tick += DbPoll_Tick;
            _dbPollTimer.Start();
        }

        private void DbPoll_Tick(object sender, EventArgs e) {
            try {
                // 2026-09-19 见 PackageApplyDebounceTick 的说明: 比赛期间收到的整包同步
                //   被原样按下不表存在这里——每次轮询(含 DATA_CHANGED 触发的立即那一次)
                //   都问一句"这一组的临时数据库现在还在用吗", LiveActive 一变回 false
                //   (说明这一组已经确认成绩/取消, 数据已经安全写进 meet.db, 临时数据库
                //   使命完成)就把攒着的这份包应用上, 不用再等下一次主服务器主动推。
                if (_deferredEditorPackage != null && !_meetDb.LiveActive) {
                    var pkg = _deferredEditorPackage;
                    _deferredEditorPackage = null;
                    try {
                        ApplyPackageInMemory(pkg);
                        UpdateEditorSyncStatus(Loc.T("Str_SyncStatus_SyncedCaughtUp"), "#22C55E");
                        AddLog(Loc.T("Str_Log_HeatEndedCatchUpFullSync"));
                    } catch (Exception ex) { AddLog(Loc.F("Str_Log_DeferredFullSyncApplyFailedFmt", ex.Message)); }
                }
                // 2026-09-21 见 FlushPatchDeferred 的说明: 本机是"总线"(RTC 当主控)时,
                //   本机自己的 _raceState 从不经历 Ready/Racing/Finished, FlushDeferredSync
                //   那几个挂在本机race生命周期上的调用点一次都不会跑——这里靠轮询兜底,
                //   LiveActive 一变回 false 就把攒着的编排补丁广播/落盘补上, 不用等到下一次
                //   本机自己"就位/复位/确认"(可能永远不会发生)。
                try { FlushPatchDeferred(); } catch { }
                // 2026-09-13 计时端硬断电时 socket 可能迟迟不关, 光靠 OnClose 清不掉。
                //   30 秒没收到它的状态帧就当它走了(它正常时每 100ms 一帧)。
                if (_rtcDrivesCurrentRaceText && _rtcSeenAt != DateTime.MinValue
                    && (DateTime.Now - _rtcSeenAt).TotalSeconds > 30)
                    ClearRtcRaceDisplay("计时端已失联 30 秒");
                // 比赛中不动: 正在写当前组, 而且计时端会主动回推
                if (_raceState == RaceState.Racing || _raceState == RaceState.Ready) return;
                int before = _dbHeatStamps.Count;
                string beforeKey = _lastPollSignature;
                RefreshChangedFromDb();
                try { RetryPendingEventRankGen(); } catch { }   // 2026-09-01 挂起的组成绩再试一遍
                // 指纹集合有变化(新组或某组改过) 才推大屏, 免得平白刷屏
                string nowKey = _dbHeatStamps.Count + ":" + _confirmedHeats.Count;
                if (nowKey != beforeKey) {
                    _lastPollSignature = nowKey;
                    if (before > 0) {   // 开机第一次不算"变化", 别一启动就推
                        try { Broadcast(); } catch { }
                    }
                }
            } catch { }
        }

        private string _lastPollSignature = "";
        private string _lastRacingSignature = "";

        /// <summary>
        /// 2026-08-31 把【组排名表】里已定稿的名次和晋级标记灌回内存。
        ///
        /// 为什么这么做, 而不是让每个报表窗口各自去查表:
        ///   晋级查询、前八名、总排名、成绩公报、团体/个人总分, 现在读的都是
        ///   Swimmer.EventRankFor() 和成绩行上的 PromotionMark。只要把定稿值灌进这里,
        ///   这几张表立刻全都认定稿那一份 —— 不用把五个窗口的取数路径各改一遍,
        ///   也就不会改漏一个、留下一处还在自己汇总。
        ///
        ///   换句话说: 内存在这里只是【定稿表的镜像】, 不是第二个真相。
        ///
        /// 只覆盖已经定稿的项目(表里有行的)。没定稿的项目一个字不动 ——
        /// 那些还在比, 名次本来就是过程值。
        /// </summary>
        private int ApplyEventRankingsFromDb() {
            int applied = 0;
            try {
                var rows = _meetDb.GetEventRankings();
                if (rows == null || rows.Count == 0) return 0;
                foreach (var r in rows) {
                    string ag = (string)r[0], gd = (string)r[1], ev = (string)r[2], st = (string)r[3];
                    int heat = (int)r[4], lane = (int)r[5], rank = (int)r[6];
                    string mark = (string)r[7];
                    if (lane < 0 || heat <= 0) continue;
                    // 2026-09-16 rank<=0 (判罚/试游) 不再跳过 —— 要把内存里可能残留的旧正数
                    //   EventRank 明确清零, 见 GetEventRankings() 那条 SQL 同一次修改的说明。

                    foreach (var sw in GetHeatEntries(ag, gd, ev, st, heat)) {
                        if (LaneOfStage(sw, st) != lane) continue;
                        var res = sw.Results.FirstOrDefault(x => x.Stage == st && x.Heat == heat);
                        if (res == null) continue;
                        res.EventRank = rank > 0 ? rank : 0;           // 定稿的项目名次; 判罚/试游明确清零
                        res.PromotionMark = rank > 0 ? (mark ?? "") : "";  // 判罚/试游没有晋级标记
                        applied++;
                        break;
                    }
                }
                if (applied > 0)
                    AddLog(Loc.F("Str_Log_FinalRanksUpdatedFmt", applied));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ReadHeatRankingTableFailedFmt", ex.Message));
            }
            return applied;
        }

        internal void RefreshChangedFromDb() {
            try {
                var stamps = _meetDb.ListHeatStamps();
                if (stamps == null || stamps.Count == 0) return;
                int changed = 0;
                foreach (var s in stamps) {
                    int hno;
                    if (!int.TryParse(s[4], out hno) || hno <= 0) continue;
                    string key = s[0] + "|" + s[1] + "|" + s[2] + "|" + s[3] + "|" + hno;
                    string old;
                    if (_dbHeatStamps.TryGetValue(key, out old) && old == s[5]) continue;   // 没变, 不读
                    ApplyHeatFromDb(s[0], s[1], s[2], s[3], hno);
                    _dbHeatStamps[key] = s[5];
                    changed++;
                }
                if (changed > 0)
                    AddLog(Loc.F("Str_Log_IncrementalRefreshFmt",
                        changed, stamps.Count));

                // 2026-08-31 再把【组排名表】里已定稿的名次灌回内存 ——
                //   晋级查询/前八名/总排名/成绩公报/团体个人总分 读的都是它,
                //   这样这几张表就都认定稿那一份, 不再各自汇总。
                try { ApplyEventRankingsFromDb(); } catch { }

                // 赛程树的"已完赛"读 _confirmedHeats(内存集合), 同样会落后于库。
                // 这一条也是轻查询(只返回 key, 不带成绩), 按库补齐。
                // 【只加不删】: 库里没有、内存里有的先留着(可能是刚确认还没落库的那一组) ——
                // 少标一个"已完赛"比多标一个危险。
                try {
                    var confirmed = _meetDb.ListConfirmedHeats();
                    int add = 0;
                    foreach (var c in confirmed) {
                        int hno2;
                        if (!int.TryParse(c[4], out hno2) || hno2 <= 0) continue;
                        // 2026-09-13 刚在本机解过锁的组别再从库里捡回来 —— 库里那条还是"已确认",
                        //   不挡一下, 10 秒一次的轮询会把刚解开的锁又扣上。
                        if (IsHeatUnlocked(c[0], c[1], c[2], c[3], hno2)) continue;
                        if (_confirmedHeats.Add(ConfirmedHeatKey(c[0], c[1], c[2], c[3], hno2))) add++;
                    }
                    if (add > 0) {
                        AddLog(Loc.F("Str_Log_FinishedFlagsBackfilledFmt", add));
                        try { BuildScheduleTree(); } catch { }
                    }
                } catch (Exception ex) { AddLog(Loc.F("Str_Log_BackfillFinishedFlagFailedFmt", ex.Message)); }

                // 2026-09-18 本机没在计时(没走 EnterReadyStateInternal 那条本地补刷) 时,
                //   "赛程导航"的[正在计时]全指望这 10 秒一次的轮询捡回来 —— 只有"谁在
                //   racing"这个集合真变了(开新组/组结束)才重建树, 不然每 10 秒都重建太浪费。
                try {
                    var racing = _meetDb.GetRacingHeats() ?? new List<string[]>();
                    string sig = string.Join(",", racing.Select(r => (r != null && r.Length >= 5) ? string.Join("|", r) : ""));
                    if (sig != _lastRacingSignature) {
                        _lastRacingSignature = sig;
                        try { RebuildBothNavTrees(); } catch { }
                    }
                } catch (Exception ex) { AddLog(Loc.F("Str_Log_QueryTimingHeatFailedFmt", ex.Message)); }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_IncrementalRefreshFailedFmt", ex.Message));
            }
        }

        internal void RefreshStageFromDb(string ageGroup, string gender, string eventName, string stage) {
            try {
                if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(stage)) return;
                var ages = new List<string>();
                if (!string.IsNullOrEmpty(ageGroup)) ages.Add(ageGroup);
                else {
                    foreach (var s in _swimmers) {
                        if (s.EventName != eventName) continue;
                        string a = s.AgeCategory ?? "";
                        if (!ages.Contains(a)) ages.Add(a);
                    }
                }
                int nHeat = 0;
                foreach (string ag2 in ages) {
                    // 这个项目在这个组别下涉及哪些组次 —— 从内存的分组信息取(库里也一样)
                    var heats = new List<int>();
                    foreach (var s in _swimmers) {
                        if (s.EventName != eventName) continue;
                        if ((s.AgeCategory ?? "") != ag2) continue;
                        var sa = s.GetAssignmentForStage(stage);
                        int h = (sa != null && sa.Heat > 0) ? sa.Heat : 0;
                        if (h > 0 && !heats.Contains(h)) heats.Add(h);
                        foreach (var r in s.Results)
                            if (r.Stage == stage && r.Heat > 0 && !heats.Contains(r.Heat)) heats.Add(r.Heat);
                    }
                    string gd2 = gender;
                    foreach (int h in heats) { ApplyHeatFromDb(ag2, gd2, eventName, stage, h); nHeat++; }
                }
                if (nHeat > 0)
                    AddLog(Loc.F("Str_Log_PreQueryRefreshFmt",
                        string.IsNullOrEmpty(ageGroup) ? "全部组别" : ageGroup, eventName, stage, nHeat));
                // 2026-09-01 组次刷完还得把【组排名表】的定稿名次灌回来。
                //   原来这里漏了 —— ApplyHeatFromDb 只带回 heat_entries.rank(过程值),
                //   定稿值只有 RefreshChangedFromDb 那条路才灌。于是"项目成绩"窗口
                //   点查询, 拿到的是过程名次, 跟成绩公报/前八名不是同一份。
                try { ApplyEventRankingsFromDb(); } catch { }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_PreQueryRefreshFailedFmt", ex.Message));
            }
        }

        private void ApplyHeatFromDb(string ag, string gd, string ev, string st, int heat) {
            try {
                var rows = _meetDb.ReadBackHeat(ag, gd, ev, st, heat);
                if (rows == null || rows.Count == 0) {
                    AddLog(Loc.F("Str_Log_HeatReadbackFailedFmt", heat));
                    return;
                }
                var swimmers = GetHeatEntries(ag, gd, ev, st, heat);
                int applied = 0, missed = 0, noRow = 0;
                foreach (var row in rows) {
                    if (row.Lane == null) continue;
                    int lane = row.Lane.Value;
                    var sw = swimmers.FirstOrDefault(s => LaneOfStage(s, st) == lane);
                    if (sw == null) { missed++; continue; }
                    var r = sw.Results.FirstOrDefault(x => x.Stage == st && x.Heat == heat);
                    // 2026-09-01 人对上了, 但【内存里没有这一行成绩】—— 原来这里是静默 continue,
                    //   连 missed 都不算, 日志上只留一句"回读: 0 道", 看不出发生了什么。
                    //   这正是"库里有成绩、界面上查不到"的现场特征: 回读只能往已存在的行上
                    //   覆盖值, 建不出行来。数出来喊一声, 下次一眼就能认出。
                    // 2026-09-18 【光喊一声不够, 得真的把行建出来】——用户实拍到: DNS 的运动员
                    //   "项目成绩打印"(直接读库里 event_rankings)显示正常, "成绩与排名"(靠这个
                    //   函数从库回读进内存)那一行状态却是空的。根子就是这儿: DNS 的人从没真正
                    //   "发令/比赛"过, 内存里 sw.Results 压根没建过这个 (stage,heat) 的行——
                    //   多半是他所在那组只有他一个人(独苗组)、又是跨机器同步/断线补传进来的,
                    //   本机从没走过"就位→发令→出成绩"那条会顺带建行的路径。以前遇到这种
                    //   "建不出行"就放弃, DNS/DNF 这类【本来就没有成绩、只有一个状态】的行
                    //   反而是最常撞上这个空子的——恰恰是最需要把状态显示出来的那几行。
                    //   现在库里既然有这一道的数据(不然 rows 里不会有它), 直接在内存里新建
                    //   一行, 下面同一套赋值逻辑照旧把库里的值(状态/成绩/名次)灌进去。
                    if (r == null) {
                        r = new LaneResult { EventName = ev, Stage = st, Heat = heat, Lane = lane };
                        sw.Results.Add(r);
                        noRow++;
                    }
                    // 只覆盖"库说了算"的那几项。成绩本身也对一遍 ——
                    // 库和内存要是对不上, 说明回写出了问题, 必须让它暴露出来。
                    if (Math.Abs(r.FinalTime - row.FinalTime) > 0.0001 && row.FinalTime > 0) {
                        AddLog(Loc.F("Str_Log_HeatLaneResultMismatchFmt",
                            heat, lane, TimeFormatter.Format(r.FinalTime), TimeFormatter.Format(row.FinalTime)));
                        r.FinalTime = row.FinalTime;
                    }
                    // 2026-09-01 【只覆盖库里真有值的】。
                    //   这个方法每 10 秒轮询也会跑一次。原来无条件赋值 —— 库里那一列
                    //   还是 0(比如这一组刚写进去、项目名次还没重排)时, 会把内存里
                    //   原本有的名次【清成 0】, 界面上名次就变成 "-" 了, 而且是反复清。
                    //   库里有值才覆盖; 没值就保留内存里那份, 等库里算出来再说。
                    if (row.HeatRank > 0) r.Rank = row.HeatRank;
                    if (row.Rank > 0) r.EventRank = row.Rank;
                    if (row.Gap > 0) r.Gap = row.Gap;
                    r.IsTie = row.IsTie;
                    if (!string.IsNullOrEmpty(row.PromotionMark)) r.PromotionMark = row.PromotionMark;
                    if (!string.IsNullOrEmpty(row.RecordNote)) r.RecordNote = row.RecordNote;
                    // 2026-09-18 破纪录证书"原记录"栏一直是空的——OldRecordHolder/OldRecordTime/
                    //   OldRecordDate 只有 CheckRecords(实时出成绩那一刻, 在计时那台机器的内存里)
                    //   会填, 从不落库、也不跨机器同步。这条成绩要是换了台机器打证书, 或者是
                    //   像这行代码上面(r==null 分支)那样靠竞赛库回读新建出来的, 这几个字段
                    //   天生是空的——但原记录其实一直老实存在 meet.db 里(ApplyRecordBreak 早把
                    //   被打破那条 records 行置成历史, is_current=0, broken_by 指回这条成绩),
                    //   只是没人问过。这里补一次兜底查询, 只在"库说这条破了纪录、内存却还没有
                    //   原记录快照"时才查(避免每 10 秒轮询都白问一次)。
                    if (!string.IsNullOrEmpty(r.RecordNote) && string.IsNullOrEmpty(r.OldRecordHolder)) {
                        string abbr0 = r.RecordNote.Split(' ')[0].TrimStart('=');
                        var oldRec = _meetDb.GetOldRecordForHeatEntry(row.Id, abbr0);
                        if (oldRec != null) {
                            r.OldRecordHolder = oldRec.HolderName ?? "";
                            r.OldRecordCountry = oldRec.HolderCountry ?? "";
                            r.OldRecordTime = oldRec.TimeSeconds;
                            r.OldRecordDate = oldRec.Date ?? "";
                        }
                    }
                    // 2026-09-18 撤销 DSQ 用的原成绩备份, 库里有、内存这份却还没有时兜底补上
                    //   (同上一段一个道理——见 MeetSchema.cs 里 dsq_backup_* 几列的说明)。
                    //   只在"内存这份是空的"时才补, 不覆盖正在计时那台机器自己维护的那份。
                    if (r.DsqBackupFinalTime <= 0 && row.DsqBackupFinalTime > 0) {
                        r.DsqBackupFinalTime = row.DsqBackupFinalTime;
                        r.DsqBackupTimeInSeconds = row.DsqBackupFinalTime;
                        r.DsqBackupStartingBlockTime = row.DsqBackupStartBlockTime;
                        if (row.DsqBackupLegReactionTimes != null)
                            r.DsqBackupLegReactionTimes = new List<double>(row.DsqBackupLegReactionTimes);
                        if (row.DsqBackupSplits != null) {
                            r.DsqBackupSplits = new List<SplitTime>();
                            foreach (var sp in row.DsqBackupSplits) {
                                if (sp == null) continue;
                                r.DsqBackupSplits.Add(new SplitTime {
                                    Distance = sp.Distance, CumulativeTime = sp.CumulativeTime,
                                    Time = sp.LapTime, TimingSource = sp.TimingSource, IsManual = sp.IsManual });
                            }
                        }
                    }
                    // 2026-09-01 判罚状态也以库为准(只加不删: 库里没写的时候不要把内存里
                    //   刚标上的判罚抹掉 —— 少一个判罚比多一个危险)。
                    // 2026-09-13 【两份状态要一起对齐】。判罚状态在内存里存了两处:
                    //   成绩行 r.Status 和运动员 sw.Status。这里原来只写成绩行那一份 ——
                    //   而计时面板的"备注"栏、大屏 payload、打印、团体总分读的都是 sw.Status。
                    //   现场症状: 确认成绩之后(内存被整包/回读刷过一轮)再看, 成绩还在、
                    //   名次还在, 备注栏的 DNS/DNF/DSQ/TRI 却空了 —— 就是只回了一份。
                    //   HandleHeatConfirmedPush 早就是两份一起对齐的, 这条路一直漏着。
                    if (!string.IsNullOrEmpty(row.Status)) { r.Status = row.Status; sw.Status = row.Status; }
                    r.FromDb = true;
                    // CurrentRank 是老代码到处在用的字段, 一起对齐, 别让它成为第二个真主。
                    // 2026-09-13 【条件要跟 r.Rank 那行一致】。上面 r.Rank 是"库里有值才覆盖"
                    //   (库里那列还是 0 时保留内存那份), 这一行原来却是无条件赋值 ——
                    //   于是 HeatRank=0 的那一轮把 CurrentRank 清成 0, 而 r.Rank 还留着。
                    //   团体总分取分读的正是 CurrentRank: 名次界面上看着好好的, 分却算没了,
                    //   而且不报错。两行同一个条件, 就不会再分叉。
                    if (row.HeatRank > 0) sw.CurrentRank = row.HeatRank;
                    // 2026-09-01 判罚/弃权的人: 名次和纪录标识一律清干净。
                    //   现场实测过 —— 界面上成绩空了、名次空了, "纪录"列却还挂着 MR。
                    //   原因是判罚是在【另一台机器】上标的, 本机内存里那份 RecordNote
                    //   是判罚之前回推过来的, 而上面几行只覆盖"库里有值"的项, 从不清空。
                    //   这里补一道: 判了就不该有名次、也不该有纪录标识, 显示/打印/大屏
                    //   读的都是内存, 一处清掉处处就对。
                    //   TRI(试游)一样不排名、不算纪录, 只是成绩照显 —— 所以判的是
                    //   StatusOrder != 5 (= TRI/DSQ/DQ/DNF/DNS), 不是只看判罚。
                    if (SwimmingScoreboard.ResultOrdering.StatusOrder(r.Status ?? "") != 5) {
                        r.Rank = 0; r.EventRank = 0; r.RecordNote = ""; sw.CurrentRank = 0;
                    }
                    applied++;
                }
                AddLog(Loc.F("Str_Log_HeatReadbackDoneFmt",
                    heat, applied,
                    missed > 0 ? string.Format(", {0} 道在内存里找不到人", missed) : "",
                    noRow > 0 ? string.Format(", {0} 道内存里原没有成绩行(多半是从没在本机走过就位/发令, 比如独苗组的 DNS)已按库补建", noRow) : ""));
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_ReadbackFailedFmt", ex.Message));
            }
        }

        /// <summary>
        /// 2026-09-16 "裁判长改成绩"专用强制回读 —— 跟上面 ApplyHeatFromDb 的区别是不带
        /// "只加不删"的防抖。那条防抖(见 ApplyHeatFromDb 里"库里没写的时候不要把内存里
        /// 刚标上的判罚抹掉")是给【正常增量轮询】用的, 目的是防半头数据抢跑; 但它有个副作用:
        /// 库里的新值如果恰好是【空】(比如把 TRI 改回正常/留空), 这条防抖会把它当成
        /// "库还没写到"而按兵不动, 内存里的旧状态就永远留着不刷新。
        /// 裁判长这条路径不一样: SaveResult 刚成功返回, 库里就是最新、最权威的那份 ——
        /// 内存必须无条件跟着改, 包括"改成空值"这种情况(用户实拍到: 某道 TRI 标注改回
        /// 正常/留空, 存盘退出后"成绩与排名"还显示 TRI, 根子就是这条防抖挡住了空值)。
        /// </summary>
        private void ForceRefreshHeatAfterJudgeOverride(string ag, string gd, string ev, string st, int heat) {
            try {
                var rows = _meetDb.ReadBackHeat(ag, gd, ev, st, heat);
                if (rows == null || rows.Count == 0) return;
                var swimmers = GetHeatEntries(ag, gd, ev, st, heat);
                int applied = 0;
                foreach (var row in rows) {
                    if (row.Lane == null) continue;
                    int lane = row.Lane.Value;
                    var sw = swimmers.FirstOrDefault(s => LaneOfStage(s, st) == lane);
                    if (sw == null) continue;
                    var r = sw.Results.FirstOrDefault(x => x.Stage == st && x.Heat == heat);
                    // 2026-09-18 跟 ApplyHeatFromDb 同一个道理(见那边的说明): 内存里没有这一行
                    //   不代表库里没有, 建不出行就白改了——裁判长这条路径尤其容易撞上,
                    //   改的常常正是从没在本机走过流程的那一道(比如替判/补录)。
                    if (r == null) {
                        r = new LaneResult { EventName = ev, Stage = st, Heat = heat, Lane = lane };
                        sw.Results.Add(r);
                    }
                    r.FinalTime = row.FinalTime;
                    r.Status = row.Status ?? "";
                    sw.Status = row.Status ?? "";
                    // 2026-09-16 row.Note(heat_entries.note) 在内存 LaneResult 上没有对应字段
                    //   (只有 RecordNote), 库里这一列本来就只在数据库层面存, 不需要往内存同步。
                    r.RecordNote = row.RecordNote ?? "";
                    r.PromotionMark = row.PromotionMark ?? "";
                    r.Rank = row.HeatRank > 0 ? row.HeatRank : 0;
                    r.EventRank = row.Rank > 0 ? row.Rank : 0;
                    r.IsTie = row.IsTie;
                    r.FromDb = true;
                    sw.CurrentRank = r.Rank;
                    // 2026-09-18 跟 ApplyHeatFromDb 同一条规矩(见那边的说明): 原记录快照/撤销
                    //   DSQ 的原成绩备份都不在这几行"覆盖"范围内, 内存本来是空的才兜底补,
                    //   不然裁判长在换了台机器改这一组时, 补齐了名次却把这两样悄悄丢了。
                    if (!string.IsNullOrEmpty(r.RecordNote) && string.IsNullOrEmpty(r.OldRecordHolder)) {
                        string abbrJ = r.RecordNote.Split(' ')[0].TrimStart('=');
                        var oldRecJ = _meetDb.GetOldRecordForHeatEntry(row.Id, abbrJ);
                        if (oldRecJ != null) {
                            r.OldRecordHolder = oldRecJ.HolderName ?? "";
                            r.OldRecordCountry = oldRecJ.HolderCountry ?? "";
                            r.OldRecordTime = oldRecJ.TimeSeconds;
                            r.OldRecordDate = oldRecJ.Date ?? "";
                        }
                    }
                    if (r.DsqBackupFinalTime <= 0 && row.DsqBackupFinalTime > 0) {
                        r.DsqBackupFinalTime = row.DsqBackupFinalTime;
                        r.DsqBackupTimeInSeconds = row.DsqBackupFinalTime;
                        r.DsqBackupStartingBlockTime = row.DsqBackupStartBlockTime;
                        if (row.DsqBackupLegReactionTimes != null)
                            r.DsqBackupLegReactionTimes = new List<double>(row.DsqBackupLegReactionTimes);
                        if (row.DsqBackupSplits != null) {
                            r.DsqBackupSplits = new List<SplitTime>();
                            foreach (var sp in row.DsqBackupSplits) {
                                if (sp == null) continue;
                                r.DsqBackupSplits.Add(new SplitTime {
                                    Distance = sp.Distance, CumulativeTime = sp.CumulativeTime,
                                    Time = sp.LapTime, TimingSource = sp.TimingSource, IsManual = sp.IsManual });
                            }
                        }
                    }
                    // 判罚/试游的人不该有名次、不该有纪录标识 —— 跟 ApplyHeatFromDb 同一条规矩
                    if (SwimmingScoreboard.ResultOrdering.StatusOrder(r.Status ?? "") != 5) {
                        r.Rank = 0; r.EventRank = 0; r.RecordNote = ""; sw.CurrentRank = 0;
                    }
                    applied++;
                }
                AddLog(Loc.F("Str_Log_RefereeOverrideForceRefreshFmt", heat, applied));
            } catch (Exception ex) { AddLog(Loc.F("Str_Log_RefereeOverrideForceRefreshFailedFmt", ex.Message)); }
        }

        /// <summary>把本组各泳道的当前成绩写进当前组库。降级时退回 AutoSaveData()。</summary>
        // 2026-09-13 降级路径【必须限流】。
        //   当前组库没就绪(库打不开 / 这一组在库里找不到)或写失败时, 原来是直接
        //   AutoSaveData() —— 那就是每次触板都 BuildCurrentPackage + 整包序列化写盘,
        //   2026-08-24 治的那个"400 米涨几个 G"原样复活。而"库打不开"现场真发生过
        //   (缺 VC++ 运行库, SQLite.Interop.dll 加载失败), 界面上还看不出来。
        //   库坏了是异常, 不该连带把内存打爆: 比赛中按 15 秒一次落盘就够
        //   (正常路径的 JSON 兜底本来也是 15 秒一次), 崩了最多丢这 15 秒。
        //   不在比赛中(赛后改判、手输成绩)照旧立刻落盘, 那条路本来就不高频。
        // ── 2026-09-13 比赛中只写"当前组"这一份, 整包一次都不写 ────────────
        //
        // 定下来的规矩: 比赛过程中只往【当前组】那份存储里写, 中间过程一个字都不
        // 往主库/整包里写; 等操作员点了「确认本组成绩」, 才一次性回写主库并整份落盘。
        //
        // 原来这里有个暗门: 当前组库没就绪(库打不开 / 这一组在库里找不到)或写失败时,
        // 直接退回 AutoSaveData() —— 每次触板 BuildCurrentPackage + 整包序列化写盘,
        // 正是 2026-08-24 那个"400 米涨几个 G"的原样复活。而"库打不开"现场真发生过
        // (缺 VC++ 运行库, SQLite.Interop.dll 加载失败), 界面上还看不出来。
        //
        // 现在没有这个暗门了: 当前组的进度【总是】写本机那个几 KB 的小文件,
        // 小库能用就同时写小库(它才是回写主库的来源)。两条路都不碰整包。
        private string LiveHeatProgressPath {
            get {
                return IOPath.Combine(IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database"),
                                      "current_heat_progress.json");
            }
        }
        private bool _liveDegradeWarned;

        /// <summary>把当前组的泳道数据摊成 LiveLane 列表(小库和小文件共用)。</summary>
        private List<SwimmingScoreboard.Db.LiveLane> BuildLiveLanes() {
            var lanes = new List<SwimmingScoreboard.Db.LiveLane>();
            foreach (var s in GetCurrentHeatSwimmers()) {
                int lane = LaneOfStage(s, _currentStage);
                if (lane < 0) continue;
                var res = s.GetResultForStage(_currentStage);
                var ln = new SwimmingScoreboard.Db.LiveLane { Lane = lane, Name = s.Name };
                // 2026-09-13 状态取"两份里有的那份"(成绩行优先, 退回运动员那份)。
                //   原来只取成绩行: 检录台标的 DNS 只写在运动员身上, 而 DNS 的人不会触板、
                //   压根没有成绩行 —— 于是那个 DNS 一路进不了库, 报表上是空白不是 DNS。
                ln.Status = GetEffectiveStatus(s, res);
                if (res != null) {
                    ln.FinalTime      = res.FinalTime;
                    ln.Rank           = res.Rank;
                    ln.RecordNote     = res.RecordNote;
                    ln.TimingSource   = res.TimingSource;
                    ln.TouchpadTime   = res.TouchpadTime;
                    ln.StartBlockTime = res.StartingBlockTime;
                    ln.Pb1Time        = res.PushButton1Time;
                    ln.Pb2Time        = res.PushButton2Time;
                    ln.Pb3Time        = res.PushButton3Time;
                    ln.ManualLeft     = res.ManualTouchTimeLeft;
                    ln.ManualRight    = res.ManualTouchTimeRight;
                    ln.IsFinished     = res.FinalTime > 0;
                    if (res.Splits != null) {
                        ln.Splits = new List<SwimmingScoreboard.Db.SplitDto>();
                        foreach (var sp in res.Splits) {
                            if (sp == null || sp.IsDeleted || sp.Distance <= 0) continue;
                            ln.Splits.Add(new SwimmingScoreboard.Db.SplitDto {
                                Distance = sp.Distance, CumulativeTime = sp.CumulativeTime,
                                LapTime = sp.Time, TimingSource = sp.TimingSource, IsManual = sp.IsManual });
                        }
                    }
                    // 2026-09-18 撤销 DSQ 用的原成绩备份也跟着这一行走——见 MeetSchema.cs
                    //   里 dsq_backup_* 几列的说明。以前这份快照只活在 res.DsqBackup* 这几个
                    //   内存字段里, 从没跟着当前组库/竞赛库走过一步, 换机器/库回读撤销 DSQ
                    //   时只能把成绩恢复成 0。
                    ln.DsqBackupFinalTime = res.DsqBackupFinalTime;
                    ln.DsqBackupStartBlockTime = res.DsqBackupStartingBlockTime;
                    if (res.DsqBackupLegReactionTimes != null)
                        ln.DsqBackupLegReactionTimes = new List<double>(res.DsqBackupLegReactionTimes);
                    if (res.DsqBackupSplits != null) {
                        ln.DsqBackupSplits = new List<SwimmingScoreboard.Db.SplitDto>();
                        foreach (var sp in res.DsqBackupSplits) {
                            if (sp == null) continue;
                            ln.DsqBackupSplits.Add(new SwimmingScoreboard.Db.SplitDto {
                                Distance = sp.Distance, CumulativeTime = sp.CumulativeTime,
                                LapTime = sp.Time, TimingSource = sp.TimingSource, IsManual = sp.IsManual });
                        }
                    }
                }
                lanes.Add(ln);
            }
            return lanes;
        }

        /// <summary>当前组进度小文件: 只有本组这几条道, 几 KB。崩了就靠它恢复。</summary>
        private void SaveLiveHeatProgressFile(List<SwimmingScoreboard.Db.LiveLane> lanes) {
            try {
                string dir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Database");
                if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
                var o = new JObject();
                o["competition"] = _competitionName ?? "";
                o["ageGroup"]    = _currentAgeGroup ?? "";
                o["gender"]      = _currentGender ?? "";
                o["eventName"]   = _currentEvent ?? "";
                o["stage"]       = _currentStage ?? "";
                o["heat"]        = _currentHeat;
                o["savedAt"]     = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                o["lanes"]       = JArray.FromObject(lanes);
                // 先写 .tmp 再替换: 写一半断电不会把上一份也毁掉
                string path = LiveHeatProgressPath, tmp = path + ".tmp";
                File.WriteAllText(tmp, o.ToString(Formatting.None), Encoding.UTF8);
                if (File.Exists(path)) File.Replace(tmp, path, null); else File.Move(tmp, path);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_HeatProgressFileWriteFailedFmt", ex.Message));
            }
        }

        /// <summary>本组已经确认/作废, 进度文件没用了。留着反而会在下次启动误恢复。</summary>
        private void ClearLiveHeatProgressFile() {
            try { if (File.Exists(LiveHeatProgressPath)) File.Delete(LiveHeatProgressPath); } catch { }
            _liveDegradeWarned = false;
        }

        /// <summary>
        /// 装载档案后调: 上次比赛中途崩了的话, 把那一组的进度捡回来。
        /// 比赛中不写整包, 档案里就没有这一组的过程数据 —— 全靠这个小文件。
        /// </summary>
        private void TryRestoreLiveHeatProgress() {
            try {
                string path = LiveHeatProgressPath;
                if (!File.Exists(path)) return;
                var o = JObject.Parse(File.ReadAllText(path, Encoding.UTF8));
                string comp = o["competition"] != null ? o["competition"].ToString() : "";
                if (!string.Equals(comp, _competitionName ?? "", StringComparison.Ordinal)) return;  // 别的比赛的, 不碰
                string ag = o["ageGroup"] != null ? o["ageGroup"].ToString() : "";
                string gd = o["gender"] != null ? o["gender"].ToString() : "";
                string ev = o["eventName"] != null ? o["eventName"].ToString() : "";
                string st = o["stage"] != null ? o["stage"].ToString() : "";
                int ht = 0;
                try { if (o["heat"] != null) ht = (int)o["heat"]; } catch { }
                if (ht <= 0 || string.IsNullOrEmpty(ev)) return;
                // 已经确认过的组不用恢复(正常收尾会把文件删掉, 这是防万一)
                if (IsHeatMarkedFinished(ag, gd, ev, st, ht)) { ClearLiveHeatProgressFile(); return; }

                var lanes = o["lanes"] as JArray;
                if (lanes == null || lanes.Count == 0) return;
                var entries = GetHeatEntries(ag, gd, ev, st, ht);
                int n = 0;
                foreach (var t in lanes) {
                    var jl = t as JObject;
                    if (jl == null) continue;
                    int lane = 0;
                    try { if (jl["Lane"] != null) lane = (int)jl["Lane"]; } catch { }
                    double ft = 0;
                    try { if (jl["FinalTime"] != null) ft = (double)jl["FinalTime"]; } catch { }
                    string status = jl["Status"] != null ? jl["Status"].ToString() : "";
                    if (ft <= 0 && string.IsNullOrEmpty(status)) continue;
                    var sw = entries.FirstOrDefault(x => LaneOfStage(x, st) == lane);
                    if (sw == null) continue;
                    var res = sw.Results.FirstOrDefault(r => r.Stage == st && r.Heat == ht);
                    if (res == null) {
                        res = new LaneResult { EventName = ev, Stage = st, Heat = ht, Lane = lane };
                        sw.Results.Add(res);
                    }
                    if (res.FinalTime > 0) continue;          // 内存里已经有了, 不覆盖
                    res.FinalTime = ft; res.TimeInSeconds = ft;
                    if (!string.IsNullOrEmpty(status)) { res.Status = status; sw.Status = status; }
                    if (jl["TimingSource"] != null) res.TimingSource = jl["TimingSource"].ToString();
                    n++;
                }
                if (n > 0) {
                    string savedAt = o["savedAt"] != null ? o["savedAt"].ToString() : "";
                    AddLog(Loc.F("Str_Log_HeatProgressRestoredFmt",
                        n, Loc.GenderDisplay(gd), ev, Loc.StageDisplay(st), ht, savedAt));
                    AppMessageBox.Show(Loc.F("Str_Msg_ProgressRestoredFmt",
                        Loc.GenderDisplay(gd), ev, Loc.StageDisplay(st), ht, n, savedAt), Loc.T("Str_MsgTitle_ProgressRestored"),
                        MessageBoxButton.OK, MessageBoxImage.Information);
                }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_HeatProgressRestoreFailedFmt", ex.Message));
            }
        }

        private void SaveHeatProgress() {
            var lanes = BuildLiveLanes();

            // 小库能用就写小库 —— 它是确认成绩时回写主库的来源
            bool dbOk = _meetDb.LiveActive && _meetDb.LiveSaveLanes(lanes);
            if (!dbOk && !_liveDegradeWarned) {
                _liveDegradeWarned = true;
                AddLog(Loc.T("Str_Log_HeatDbUnavailableProgressOnly"));
            }

            // 进度小文件总是写 —— 几 KB, 而且是崩溃恢复的唯一凭据
            SaveLiveHeatProgressFile(lanes);

            // 本组还没确认 = 中间过程, 一个字都不写整包。
            // 确认之后(赛后改判、手输成绩这些低频操作)照旧立刻整份落盘。
            if (_resultConfirmed) AutoSaveData();
        }

        // ── 2026-08-24 竞赛管理库同步（迁移第 1 步：只写不读）──────────────
        // 打开档案时把包灌进 meet.db，然后逐组比对库和内存的名单。
        // 现阶段库不参与任何读，自检不通过也只记日志、不阻断 ——
        // 它的作用是在真正把读路径搬到库上之前，先把差异暴露出来。
        private void SyncToMeetDb(CompetitionPackage package) {
            try {
                if (!_meetDb.Open(_competitionName)) {
                    // 2026-09-01 竞赛库打不开是【致命】的, 不能只记一行日志就接着跑。
                    //   实际发生过: SQLite.Interop.dll 加载失败(目标机缺 VC++ 运行库),
                    //   库从头到尾没打开过 —— 成绩全进不了库、没有项目名次、组排名表不生成,
                    //   而界面上一点异常都看不出来, 就这么跑了一整天。
                    //   现在必须弹出来, 让人当场知道。每次加载档案只弹一次, 不烦人。
                    if (!_meetDbFailWarned) {
                        _meetDbFailWarned = true;
                        AddLog(Loc.T("Str_Log_MeetDbCannotOpenSevere"));
                        try {
                            AppMessageBox.Show(
                                Loc.T("Str_Msg_MeetDbCannotOpen"),
                                Loc.T("Str_MsgTitle_MeetDbCannotOpen"), MessageBoxButton.OK, MessageBoxImage.Error);
                        } catch { }
                    }
                    return;
                }
                if (!_meetDb.ImportPackage(package)) return;
                // 2026-08-31 【不在这里重算名次】。
                //   名次在"确认本组成绩"那一刻就固定了, 是正式成绩的一部分,
                //   事后任何自动动作都不许改它 —— 加载一次档案名次就变一次,
                //   这在比赛里是不能接受的。
                //   (曾经这里调过 RecomputeAllRanks 去修正旧算法留下的名次, 是我不懂规则。
                //    历史数据若确有问题, 只能由裁判长明确决定后单独处理, 不能悄悄自动改。)

                // 2026-08-31 一次性订正历史名次到当前并列口径(1/100 秒)。
                //   这【不是】恢复"每次加载都重算" —— 那条已经撤了, 名次确认后就固定。
                //   这里只把当初因旧口径(1e-9)该并列却没并列的订正过来, 成绩一个字不动,
                //   而且靠 settings 里的 rank_rule_version 记账, 全场只跑一次。
                //   每条改动都会写进日志, 便于事后核对。
                try { _meetDb.MigrateRanksOnce(Environment.MachineName); }
                catch (Exception ex) { AddLog(Loc.F("Str_Log_HistoricalRankFixFailedFmt", ex.Message)); }

                var chk = _meetDb.SelfCheck(package);
                AddLog(chk.ToString());
                foreach (var d in chk.Diffs.Take(5)) AddLog(Loc.F("Str_Log_DiffLineFmt", d));
                // 2026-08-29 库和包对不上 => 编排改过了(或者上次导入没导全)。
                //   计时端必须拿着【最新的】日程和分组表, 否则主服务器一停,
                //   它就在用旧分组跑比赛 —— 这是"服务器停了也能比"的前提条件。
                //   重建会保住已经跑出来的成绩; 平时自检一致, 一次也不会跑。
                // 2026-08-29 库和包对不上 => 编排改过了。计时端必须拿着【最新的】
                //   日程和分组表, 否则主服务器一停, 它就在用旧分组跑比赛 ——
                //   这是"服务器停了也能比"的前提条件。
                //   重建是【在旁边建新库、建成了再换】, 原库全程不动;
                //   成绩差一条都不换库。平时自检一致, 一次也不会跑。
                //   (第一版写成"先清空再重导", 重导失败时库已经空了, 真丢过一组成绩。)
                if (chk.Diffs.Count > 0) {
                    AddLog(Loc.F("Str_Log_MeetDbDiffRebuildFmt",
                        chk.Diffs.Count));
                    if (_meetDb.RebuildFromPackage(package)) {
                        var again = _meetDb.SelfCheck(package);
                        AddLog(Loc.F("Str_Log_RebuildSelfCheckFmt", again.ToString()));
                        foreach (var d in again.Diffs.Take(5)) AddLog(Loc.F("Str_Log_StillDiffLineFmt", d));
                    }
                }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_MeetDbSyncFailedFmt", ex.Message));
            }
        }

        private void LoadCompetitionFromFile(string path) {
            try {
                string json = File.ReadAllText(path, Encoding.UTF8);
                var package = JsonConvert.DeserializeObject<CompetitionPackage>(json);
                if (package == null) return;

                _competitionName = package.CompetitionName ?? "";
                _competitionMode = package.CompetitionMode ?? "domestic";
                _competitionRule = package.CompetitionRule ?? "U系列青少年游泳比赛";
                CompNameBox.Text = _competitionName;
                CompModeCombo.SelectedIndex = _competitionMode == "domestic" ? 0 : 1;
                if (CompRuleCombo != null) {
                    _suppressCompRuleAutoLoad = true;
                    try {
                        if (_competitionRule == "国际比赛") CompRuleCombo.SelectedIndex = 0;
                        else if (_competitionRule == "国内大赛") CompRuleCombo.SelectedIndex = 1;
                        else if (_competitionRule == "地区级比赛") CompRuleCombo.SelectedIndex = 3;
                        else CompRuleCombo.SelectedIndex = 2;   // U系列青少年游泳比赛 / 旧存档默认值
                    } finally { _suppressCompRuleAutoLoad = false; }
                }
                SetDatePicker(StartDatePicker, package.StartDate);
                SetDatePicker(EndDatePicker, package.EndDate);
                LocationBox.Text = package.Location ?? "";
                OrganizerBox.Text = package.Organizer ?? "";
                HostBox.Text = package.Host ?? "";
                _certCommitteeText = package.CertCommittee ?? "";
                _awardCertRankLimit = package.AwardCertRankLimit > 0 ? package.AwardCertRankLimit : 3;
                TechDelegateBox.Text = package.TechnicalDelegate ?? "";
                RefereeBox.Text = package.Referee ?? "";
                // 2026-05-26 UI 已删发令员，旧存档的 Starter 合并到仲裁委员展示前缀避免数据丢失
                ArbiterBox.Text = package.Arbiter
                    ?? (string.IsNullOrEmpty(package.Starter) ? "" : "(原发令员: " + package.Starter + ")");
                ChiefJudgeBox.Text = package.ChiefJudge ?? "";

                _poolConfig.Length = package.PoolLength > 0 ? package.PoolLength : 50;
                _poolConfig.SetLaneCount(package.LaneCount > 0 ? package.LaneCount : 10);
                PoolLengthCombo.SelectedIndex = _poolConfig.Length == 25 ? 1 : 0;
                LaneCountCombo.SelectedIndex = _poolConfig.LaneCount == 8 ? 1 : (_poolConfig.LaneCount == 6 ? 2 : 0);

                if (package.LaneCloseSettings != null) {
                    _laneCloseSettings = package.LaneCloseSettings;
                    // 兼容旧数据：FinishPosition为空时，用StartPosition作为默认终点位置
                    if (string.IsNullOrEmpty(_laneCloseSettings.FinishPosition))
                        _laneCloseSettings.FinishPosition = _laneCloseSettings.StartPosition;
                }
                // 团体计分配置：旧档案没有就保留默认；空字段补默认值
                if (package.ScoringConfig != null) {
                    _scoringConfig = package.ScoringConfig;
                    if (_scoringConfig.IndividualPoints == null || _scoringConfig.IndividualPoints.Count == 0
                        || _scoringConfig.RelayPoints == null || _scoringConfig.RelayPoints.Count == 0) {
                        _scoringConfig.ResetToDefaults();
                    }
                }
                // 项目用时配置：旧档案没有就保留默认；空字段补默认值
                if (package.DurationConfig != null) {
                    _durationConfig = package.DurationConfig;
                    if (_durationConfig.IndividualMinutesPerHeat == null || _durationConfig.IndividualMinutesPerHeat.Count == 0) {
                        _durationConfig.ResetToDefaults();
                    }
                }
                if (package.Events != null && package.Events.Count > 0) _events = package.Events;
                if (package.AgeGroups != null && package.AgeGroups.Count > 0) _ageGroups = package.AgeGroups;
                if (package.Genders != null && package.Genders.Count > 0) _genders = package.Genders;
                if (package.Stages != null && package.Stages.Count > 0) _stages = package.Stages;
                if (package.HeatCounts != null && package.HeatCounts.Count > 0) _heatCounts = package.HeatCounts;
                AgeGroupRegistry.Set(_ageGroups);
                // 2026-08-21 原来只更新了 _genders 和"参数设置"里的预览表，
                //   五个性别下拉(报名筛选/编辑/成绩/注册/纪录筛选)还是 XAML 里写死的
                //   男/女/混合 —— 现场表现为"性别框没跟着比赛参数设置管理更新"，
                //   男女接力队因此选不到性别、录不了 4 棒姓名。赛次下拉同一个毛病。
                GenderRegistry.Set(_genders);
                // 2026-09-03 赛次/组数也进静态表 —— 弹窗(项目成绩/批量公布…)拿不到 _stages,
                //   只能走 StageRegistry。不同步就还是 XAML 里写死的那三个。
                StageRegistry.Set(_stages);
                HeatCountRegistry.Set(_heatCounts);
                try { RefillGenderCombos(); } catch { }
                try { RefillStageCombos(); } catch { }
                RefreshEventComboBoxes();
                RefreshEventsPreview();
                RefreshAgeGroupsPreview();
                RefreshDisplayRecordLabelText();
                RefreshGendersPreview();
                RefreshStagesPreview();
                RefreshHeatCountsPreview();
                RefreshAllAgeGroupFilterCombos();
                _bibRanges = package.BibRanges ?? new List<BibRange>();
                // 2026-05-24 P0-3 参赛单位
                _units.Clear();
                if (package.Units != null) foreach (var u in package.Units) _units.Add(u);
                // 2026-05-24 P0-D 工作人员（2026-05-25 旧分组名自动迁移）
                _staff.Clear();
                if (package.StaffList != null) {
                    foreach (var s in package.StaffList) {
                        s.Group = StaffGroups.Migrate(s.Group);
                        _staff.Add(s);
                    }
                }
                // 2026-05-25 秩序册向导草稿
                _wizardDraft = package.WizardDraft;
                _programBook = package.ProgramBook ?? new ProgramBookData();
                _resultBook = package.ResultBook ?? new ResultBookData();
                if (!string.IsNullOrEmpty(package.DisplayRecordLabel)) _displayRecordLabel = package.DisplayRecordLabel;
                if (!string.IsNullOrEmpty(package.DisplayRecordTypeName)) _displayRecordTypeName = package.DisplayRecordTypeName;
                if (package.DisplayRecordOptions != null && package.DisplayRecordOptions.Count > 0) _displayRecordOptions = package.DisplayRecordOptions;
                _confirmedHeats = new HashSet<string>(package.ConfirmedHeats ?? new List<string>());
                _unlockedHeats = new HashSet<string>(package.UnlockedHeats ?? new List<string>());
                _checkedInHeats = new HashSet<string>(package.CheckedInHeats ?? new List<string>());
                // 2026-06-08 P3: 加载赛事档案时同步清 per-lane 事件日志与原始计时日志 (防御性 — 跨档案切换
                //   时, 上一档的尾部日志缓冲不应残留. Ready/Restart 路径已在同场比赛换组时清, 加载档案是另一入口.)
                _laneEventLog.Clear();
                if (_rawTimingLog != null) _rawTimingLog.Clear();

                // 2026-09-19 【订正】上一版这里是"重建前摘成绩、重建完再贴回去"——用户
                //   指出比赛实时性太强, 摘/贴两步之间理论上仍有缝隙, 算不上万无一失。
                //   真正的防线挪到了更早的地方: PackageApplyDebounceTick(编排端/计时端
                //   收远程整包那一步)现在会先查 _meetDb.LiveActive, 只要这一组的当前组
                //   临时数据库(current_heat.db)还在用, 整包直接原样按下不表、存进
                //   _deferredEditorPackage, 连这个函数都不会被调用——不是"重建后恢复",
                //   是压根不给重建发生的机会。等这一组confirm/丢弃(LiveActive 变回
                //   false, 数据已经安全写进 meet.db)才由 DbPoll_Tick 补上。
                //   这里只留一道兜底断言: 万一真的在 LiveActive 期间走到了这一步(说明
                //   上面那道防线出了漏洞), 大声记一条日志, 不要悄悄地把成绩冲掉却没人
                //   发现——这属于不该发生的情况, 发生了要能一眼看出来去查原因。
                if (_applyingRemoteSync && _meetDb.LiveActive) {
                    AddLog(Loc.T("Str_Log_RemoteSyncReloadDuringLiveActiveSevere"));
                }

                _swimmers.Clear();
                if (package.Swimmers != null) {
                    foreach (var sw in package.Swimmers) {
                        // 兼容旧数据：如果没有StageAssignments，从已有数据重建
                        if (sw.StageAssignments == null || sw.StageAssignments.Count == 0) {
                            // 从当前Heat/Lane重建当前赛次的分组记录
                            if (sw.Heat > 0 && !string.IsNullOrEmpty(sw.CurrentStage)) {
                                sw.SetStageAssignment(sw.CurrentStage, sw.Heat, sw.Lane, sw.EntryTimeSeconds, sw.EntryTime);
                            }
                            // 从比赛成绩LaneResult重建历史赛次的分组记录
                            foreach (var r in sw.Results) {
                                if (r.Heat > 0 && !string.IsNullOrEmpty(r.Stage) && sw.GetAssignmentForStage(r.Stage) == null) {
                                    sw.SetStageAssignment(r.Stage, r.Heat, r.Lane, 0, "");
                                }
                            }
                        }
                        _swimmers.Add(sw);
                    }
                }
                _relayTeams.Clear();
                if (package.RelayTeams != null) {
                    foreach (var rt in package.RelayTeams) {
                        _relayTeams.Add(rt);
                        // 兼容旧数据：确保接力队在_swimmers中有对应条目
                        if (!string.IsNullOrEmpty(rt.EventName)) {
                            bool exists = false;
                            foreach (var s in _swimmers) {
                                // 2026-06-18 加 AgeCategory 比较, 修跨年龄段同代表队同项目误判 exists
                                if (s.Name == rt.TeamName && s.EventName == rt.EventName && s.Gender == rt.Gender
                                    && (s.AgeCategory ?? "") == (rt.AgeGroup ?? "")) { exists = true; break; }
                            }
                            if (!exists) {
                                string legNames = "";
                                foreach (var leg in rt.Legs) legNames += (legNames.Length > 0 ? "," : "") + leg.SwimmerName;
                                _swimmers.Add(new Swimmer {
                                    BibNumber = "R" + _relayTeams.Count.ToString("D3"),
                                    Name = rt.TeamName,
                                    Gender = rt.Gender,
                                    Country = rt.TeamName,
                                    EventName = rt.EventName,
                                    AgeCategory = rt.AgeGroup,    // 2026-05-25 接力组别同步
                                    EntryTime = rt.EntryTime,
                                    EntryTimeSeconds = rt.EntryTimeSeconds,
                                    CurrentStage = rt.Stage ?? "预赛",
                                    Heat = rt.Heat,
                                    Lane = rt.Lane,
                                    Notes = string.Format("接力队 棒次:{0}", legNames)
                                });
                            }
                        }
                    }
                }
                _records.Clear();
                if (package.Records != null) foreach (var r in package.Records) _records.Add(r);
                ResetRecordsBaseline();   // 2026-09-12 表格就地编辑的基准线, 从这一刻算起
                _teamScores.Clear();
                if (package.TeamScores != null) foreach (var ts in package.TeamScores) _teamScores.Add(ts);
                _schedule.Clear();
                if (package.Schedule != null) foreach (var s in package.Schedule) _schedule.Add(s);

                // 2026-09-19 用户实拍到现场事故: 计时端正在比赛中, 收到一次跟硬件设备
                //   毫不相干的远程同步(比如编排端改了个接力队信息、走的是还没搬完补丁的
                //   老整包路)重新加载赛事包——这里原来无条件 Clear() 重建所有泳道的
                //   LaneDeviceState 对象。TP/MB"当下有没有连上、有没有在收信号"这类
                //   实时状态压根不在赛事包这份数据里、也不在 ApplyPersistedDeviceStates
                //   读的那份 device_states.json 持久化配置里——一重建就成了全新对象、
                //   全部默认值(未连接), 界面上立刻看到"TP/MB 从打开变成关闭", 而这时候
                //   比赛正在进行中。不是数据错了, 是这几个纯反映"硬件此刻状态"的内存
                //   对象被一次跟硬件毫不相干的同步动作捎带手清空了。
                //   区分开: 本机用户自己在设置里改赛事名称/泳道数(_applyingRemoteSync
                //   为 false)才是真的需要重建；远程同步触发的重载(_applyingRemoteSync
                //   为 true, 且已经有过一次初始化)只需要让持久化配置(损坏/未安装)照常
                //   生效, 那几个反映硬件当下连接状态的对象原样保留, 不重建。
                if (_applyingRemoteSync && _laneDeviceStates.Count > 0) {
                    ApplyPersistedDeviceStates();
                } else {
                    InitLaneDeviceStates();
                    ApplyPersistedDeviceStates();   // 加载赛事 package 时不要冲掉用户的设备状态
                }
                BuildScheduleTree();
                RebuildRelayGroupedView();
                UpdateRaceStateDisplay();
                RefreshOverviewStats();
                RefreshRecordFilterCombos();

                AddLog(Loc.F("Str_Log_CompetitionLoadedFmt", _competitionName));
                SyncToMeetDb(package);
                // 2026-09-13 比赛中不写整包了, 档案里就没有正在比那一组的过程数据 ——
                //   上次要是比到一半崩了, 靠当前组进度小文件把它捡回来。
                try { TryRestoreLiveHeatProgress(); } catch { }
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_CompetitionLoadFailedFmt", ex.Message));
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 赛事概览统计
        // ═══════════════════════════════════════════════════════════════
        private void RefreshOverviewStats() {
            if (OverviewSummaryPanel == null || OverviewStatsPanel == null) return;

            // 统计各项目、各性别的报名人数（排除接力队员子条目）
            var athletes = _swimmers.Where(s => s.Notes == null || !s.Notes.StartsWith("接力队员")).ToList();

            // 按项目+性别统计
            var eventStats = new Dictionary<string, int[]>(); // eventName -> [男, 女, 混合]
            var teamSet = new HashSet<string>();
            foreach (var s in athletes) {
                string ev = s.EventName ?? "";
                if (string.IsNullOrEmpty(ev)) continue;
                if (!eventStats.ContainsKey(ev)) eventStats[ev] = new int[3];
                if (s.Gender == "男") eventStats[ev][0]++;
                else if (s.Gender == "女") eventStats[ev][1]++;
                else eventStats[ev][2]++;
                if (!string.IsNullOrEmpty(s.Country)) teamSet.Add(s.Country);
            }

            int totalMale = athletes.Count(s => s.Gender == "男");
            int totalFemale = athletes.Count(s => s.Gender == "女");
            int totalMixed = athletes.Count(s => s.Gender != "男" && s.Gender != "女");
            int totalAthletes = athletes.Count;
            int totalEvents = eventStats.Count;
            int totalTeams = teamSet.Count;

            // 汇总条
            OverviewSummaryPanel.Children.Clear();
            var summaryItems = new[] {
                new { Label = Loc.T("Str_EM_RegStats_Teams"), Value = totalTeams.ToString(), Color = "#8B5CF6" },
                new { Label = Loc.T("Str_EM_RegStats_Entries"), Value = totalAthletes.ToString(), Color = "#3B82F6" },
                new { Label = Loc.T("Str_EM_RegStats_Male"), Value = totalMale.ToString(), Color = "#2563EB" },
                new { Label = Loc.T("Str_EM_RegStats_Female"), Value = totalFemale.ToString(), Color = "#EC4899" },
                new { Label = Loc.T("Str_EM_RegStats_EventCount"), Value = totalEvents.ToString(), Color = "#F59E0B" }
            };
            if (totalMixed > 0) summaryItems = new[] {
                new { Label = Loc.T("Str_EM_RegStats_Teams"), Value = totalTeams.ToString(), Color = "#8B5CF6" },
                new { Label = Loc.T("Str_EM_RegStats_Entries"), Value = totalAthletes.ToString(), Color = "#3B82F6" },
                new { Label = Loc.T("Str_EM_RegStats_Male"), Value = totalMale.ToString(), Color = "#2563EB" },
                new { Label = Loc.T("Str_EM_RegStats_Female"), Value = totalFemale.ToString(), Color = "#EC4899" },
                new { Label = Loc.T("Str_EM_RegStats_Mixed"), Value = totalMixed.ToString(), Color = "#10B981" },
                new { Label = Loc.T("Str_EM_RegStats_EventCount"), Value = totalEvents.ToString(), Color = "#F59E0B" }
            };

            foreach (var item in summaryItems) {
                var sp = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 24, 0) };
                sp.Children.Add(new TextBlock {
                    Text = item.Label + "  ",
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")),
                    VerticalAlignment = VerticalAlignment.Center, FontSize = 13
                });
                sp.Children.Add(new TextBlock {
                    Text = item.Value,
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString(item.Color)),
                    FontWeight = FontWeights.Bold, FontSize = 20, VerticalAlignment = VerticalAlignment.Center
                });
                OverviewSummaryPanel.Children.Add(sp);
            }

            // 项目明细表
            OverviewStatsPanel.Children.Clear();
            if (eventStats.Count == 0) {
                OverviewStatsPanel.Children.Add(new TextBlock {
                    Text = Loc.T("Str_EM_NoEventData"), Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8")),
                    HorizontalAlignment = HorizontalAlignment.Center, Margin = new Thickness(0, 10, 0, 0)
                });
                return;
            }

            // 按_events中的顺序排列，分为个人项目和接力项目
            var personalEvents = new List<string>();
            var relayEvents = new List<string>();
            foreach (string ev in _events) {
                if (!eventStats.ContainsKey(ev)) continue;
                if (ev.Contains("接力")) relayEvents.Add(ev);
                else personalEvents.Add(ev);
            }
            // 补充不在_events中的项目
            foreach (var ev in eventStats.Keys) {
                if (!personalEvents.Contains(ev) && !relayEvents.Contains(ev)) {
                    if (ev.Contains("接力")) relayEvents.Add(ev);
                    else personalEvents.Add(ev);
                }
            }

            // 创建表格
            Action<string, List<string>> buildTable = (title, evList) => {
                if (evList.Count == 0) return;
                var titleBlock = new TextBlock {
                    Text = title, FontSize = 13, FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")),
                    Margin = new Thickness(0, 8, 0, 6)
                };
                OverviewStatsPanel.Children.Add(titleBlock);

                var grid = new Grid();
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(30) });    // 序号
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); // 项目名
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(70) });    // 男
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(70) });    // 女
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(70) });    // 合计

                // 表头
                grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
                var headerBg = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E2E8F0"));
                string[] headers = { Loc.T("Str_EM_RegStats_ColIndex"), Loc.T("Str_EM_RegStats_ColEventName"), Loc.T("Str_EM_RegStats_Male"), Loc.T("Str_EM_RegStats_Female"), Loc.T("Str_EM_RegStats_ColTotal") };
                for (int c = 0; c < headers.Length; c++) {
                    var border = new Border { Background = headerBg, Padding = new Thickness(6, 0, 6, 0) };
                    var tb = new TextBlock {
                        Text = headers[c], FontWeight = FontWeights.SemiBold, FontSize = 12,
                        Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#475569")),
                        VerticalAlignment = VerticalAlignment.Center,
                        TextAlignment = c >= 2 ? TextAlignment.Center : TextAlignment.Left
                    };
                    border.Child = tb;
                    Grid.SetRow(border, 0);
                    Grid.SetColumn(border, c);
                    grid.Children.Add(border);
                }

                int sumM = 0, sumF = 0, sumT = 0;
                for (int i = 0; i < evList.Count; i++) {
                    string ev = evList[i];
                    int[] counts = eventStats[ev];
                    int m = counts[0], f = counts[1], t = m + f + counts[2];
                    sumM += m; sumF += f; sumT += t;

                    grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
                    int row = i + 1;
                    var rowBg = i % 2 == 0 ? Brushes.White : new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC"));
                    var dimColor = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#94A3B8"));
                    var textColor = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155"));
                    var maleColor = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#2563EB"));
                    var femaleColor = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EC4899"));
                    var totalColor = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E293B"));

                    Action<int, string, Brush, TextAlignment, bool> addCell = (col, text, fg, align, bold) => {
                        var border2 = new Border { Background = rowBg, Padding = new Thickness(6, 0, 6, 0),
                            BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F1F5F9")), BorderThickness = new Thickness(0, 0, 0, 1) };
                        var tb2 = new TextBlock {
                            Text = text, FontSize = 12, Foreground = fg,
                            VerticalAlignment = VerticalAlignment.Center, TextAlignment = align
                        };
                        if (bold) tb2.FontWeight = FontWeights.SemiBold;
                        border2.Child = tb2;
                        Grid.SetRow(border2, row);
                        Grid.SetColumn(border2, col);
                        grid.Children.Add(border2);
                    };

                    addCell(0, (i + 1).ToString(), dimColor, TextAlignment.Left, false);
                    addCell(1, ev, textColor, TextAlignment.Left, false);
                    addCell(2, m > 0 ? m.ToString() : "-", m > 0 ? maleColor : dimColor, TextAlignment.Center, m > 0);
                    addCell(3, f > 0 ? f.ToString() : "-", f > 0 ? femaleColor : dimColor, TextAlignment.Center, f > 0);
                    addCell(4, t.ToString(), totalColor, TextAlignment.Center, true);
                }

                // 合计行
                grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
                int sumRow = evList.Count + 1;
                var sumBg = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#EFF6FF"));
                var sumFg = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E40AF"));
                Action<int, string> addSumCell = (col, text) => {
                    var border3 = new Border { Background = sumBg, Padding = new Thickness(6, 0, 6, 0) };
                    var tb3 = new TextBlock {
                        Text = text, FontSize = 12, FontWeight = FontWeights.Bold,
                        Foreground = sumFg, VerticalAlignment = VerticalAlignment.Center,
                        TextAlignment = col >= 2 ? TextAlignment.Center : TextAlignment.Left
                    };
                    border3.Child = tb3;
                    Grid.SetRow(border3, sumRow);
                    Grid.SetColumn(border3, col);
                    grid.Children.Add(border3);
                };
                addSumCell(0, "");
                addSumCell(1, string.Format(Loc.T("Str_EM_RegStats_Subtotal"), evList.Count));
                addSumCell(2, sumM.ToString());
                addSumCell(3, sumF.ToString());
                addSumCell(4, sumT.ToString());

                OverviewStatsPanel.Children.Add(grid);
            };

            buildTable(Loc.T("Str_EM_RegStats_Personal"), personalEvents);
            buildTable(Loc.T("Str_EM_RegStats_Relay"), relayEvents);
        }

