        // 计时硬件连接
        // ═══════════════════════════════════════════════════════════════
        private void PopulateComPorts() {
            try {
                ComPortCombo.Items.Clear();
                foreach (string port in SerialPort.GetPortNames()) {
                    ComPortCombo.Items.Add(port);
                }
                if (ComPortCombo.Items.Count > 0) ComPortCombo.SelectedIndex = 0;
            } catch { }
        }

        private void ConnectSerial_Click(object sender, RoutedEventArgs e) {
            if (ComPortCombo.SelectedItem == null) { AddLog(Loc.T("Str_Log_PleaseSelectSerialPort")); return; }
            string portName = ComPortCombo.SelectedItem.ToString();
            int baud = ReadBaudRateFromUi();
            _timingBridge.ConnectSerial(portName, baud);
            AddLog(Loc.F("Str_Log_SerialConnectedFmt", portName, baud));
            UpdateConnectionStatus();
            // 通讯参数立即落盘 — 下次启动自动还原 UI 选择
            _timingConn.SerialPort = portName;
            _timingConn.SerialBaudRate = baud;
            _timingConn.LastType = "serial";
            SaveTimingConnectionConfig();
        }

        // "比赛控制"面板上的"连接串口"快捷按钮：
        // - 已连接 → 断开
        // - 未连接 → 用 timing_connection.json 里保存的串口/波特率连接；没保存就提示去 系统工作状态 配
        // 2026-05-14 顶部"系统硬件"栏的连接按钮改走网络连接（TCP），按钮文字也改为"网络连接"。
        // 串口连接仍保留在"系统工作状态 → 硬件计时器连接"详细面板里，这里只负责快速 TCP 连/断。
        private void QuickConnectSerial_Click(object sender, RoutedEventArgs e) {
            if (_timingBridge != null && _timingBridge.IsConnected) {
                // 2026-05-30 v2: 只有 Waiting 状态允许; Ready/Racing/Finished 直接 return
                if (_raceState != RaceState.Waiting) {
                    AddLog(Loc.T("Str_Log_QuickDisconnectIgnoredNotWaiting"));
                    return;
                }
                _timingBridge.Disconnect();
                UpdateConnectionStatus();
                UpdateQuickConnectButton();
                AddLog(Loc.T("Str_Log_HwDisconnected"));
                return;
            }
            string host = _timingConn != null ? _timingConn.TcpHost : null;
            int port = _timingConn != null && _timingConn.TcpPort > 0 ? _timingConn.TcpPort : 5000;
            if (string.IsNullOrEmpty(host)) {
                AppMessageBox.Show(
                    Loc.T("Str_Msg_NoDefaultAddress"),
                    Loc.T("Str_MsgTitle_NoDefaultAddress"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            try {
                _timingBridge.ConnectTcp(host, port);
                AddLog(Loc.F("Str_Log_QuickNetConnectedFmt", host, port));
                _timingConn.LastType = "tcp";
                SaveTimingConnectionConfig();
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_QuickNetConnectFailedFmt", ex.Message));
            }
            UpdateConnectionStatus();
            UpdateQuickConnectButton();
        }

        // 测试模式下事件类型简短名（用于贴到 Remain 框，长字符串会撑破布局）
        private static string TestModeShortName(string cmdType) {
            switch (cmdType) {
                case "Touchpad":
                case "ManualTouchpad":    // 2026-06-14 MB 代触显示同 "触"
                    return "触";
                case "StartingBlock": return "出发";
                case "PushButton1": return "盲1";
                case "PushButton2": return "盲2";
                case "PushButton3": return "盲3";
                default: return cmdType;
            }
        }

        // 设备测试模式下：对应设备点先 Touched（红）→ 500ms 后回 Open（绿），实时可视
        // 当 _testMode 中途被关闭，定时器到点不再恢复 Open，避免和正常状态机冲突。
        private void FlashDeviceInTestMode(int lane, string cmdType, string side) {
            var ls = _laneDeviceStates.FirstOrDefault(s => s.Lane == lane);
            if (ls == null) return;
            bool isLeft = side != "right";

            // 设置目标设备点为 Touched
            switch (cmdType) {
                case "Touchpad":
                case "ManualTouchpad":   // 2026-06-14 MB 代触在测试模式下也闪 TP 指示灯
                    if (isLeft) ls.LeftTouchpadStatus = DeviceStatus.Touched;
                    else        ls.RightTouchpadStatus = DeviceStatus.Touched;
                    break;
                case "StartingBlock":
                    if (isLeft) ls.LeftStartBlockStatus = DeviceStatus.Touched;
                    else        ls.RightStartBlockStatus = DeviceStatus.Touched;
                    break;
                case "PushButton1":
                    if (isLeft) ls.LeftBlindWatch1Status = DeviceStatus.Touched;
                    else        ls.RightBlindWatch1Status = DeviceStatus.Touched;
                    break;
                case "PushButton2":
                    if (isLeft) ls.LeftBlindWatch2Status = DeviceStatus.Touched;
                    else        ls.RightBlindWatch2Status = DeviceStatus.Touched;
                    break;
                case "PushButton3":
                    if (isLeft) ls.LeftBlindWatch3Status = DeviceStatus.Touched;
                    else        ls.RightBlindWatch3Status = DeviceStatus.Touched;
                    break;
                default:
                    return;
            }
            UpdateLaneStatusDisplay();   // 立即显示红色闪烁

            int capLane = lane;
            string capCmd = cmdType;
            bool capLeft = isLeft;
            var t = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(500) };
            t.Tick += delegate {
                t.Stop();
                if (!_testMode) return;     // 已退出测试，让退出逻辑里的 Closed 生效
                var ls2 = _laneDeviceStates.FirstOrDefault(s => s.Lane == capLane);
                if (ls2 == null) return;
                switch (capCmd) {
                    case "Touchpad":
                    case "ManualTouchpad":   // 2026-06-14 MB 代触跟真触板恢复 Open 共用同一定时器
                        if (capLeft) { if (!ls2.LeftTouchpadBroken) ls2.LeftTouchpadStatus = DeviceStatus.Open; }
                        else          { if (!ls2.RightTouchpadBroken) ls2.RightTouchpadStatus = DeviceStatus.Open; }
                        break;
                    case "StartingBlock":
                        if (capLeft) { if (!ls2.LeftStartBlockBroken) ls2.LeftStartBlockStatus = DeviceStatus.Open; }
                        else          { if (!ls2.RightStartBlockBroken) ls2.RightStartBlockStatus = DeviceStatus.Open; }
                        break;
                    case "PushButton1":
                        if (capLeft) { if (!ls2.LeftBlindWatch1Broken && !ls2.LeftBlindWatch1NotInstalled) ls2.LeftBlindWatch1Status = DeviceStatus.Open; }
                        else          { if (!ls2.RightBlindWatch1Broken && !ls2.RightBlindWatch1NotInstalled) ls2.RightBlindWatch1Status = DeviceStatus.Open; }
                        break;
                    case "PushButton2":
                        if (capLeft) { if (!ls2.LeftBlindWatch2Broken && !ls2.LeftBlindWatch2NotInstalled) ls2.LeftBlindWatch2Status = DeviceStatus.Open; }
                        else          { if (!ls2.RightBlindWatch2Broken && !ls2.RightBlindWatch2NotInstalled) ls2.RightBlindWatch2Status = DeviceStatus.Open; }
                        break;
                    case "PushButton3":
                        if (capLeft) { if (!ls2.LeftBlindWatch3Broken && !ls2.LeftBlindWatch3NotInstalled) ls2.LeftBlindWatch3Status = DeviceStatus.Open; }
                        else          { if (!ls2.RightBlindWatch3Broken && !ls2.RightBlindWatch3NotInstalled) ls2.RightBlindWatch3Status = DeviceStatus.Open; }
                        break;
                }
                UpdateLaneStatusDisplay();
                Broadcast();
            };
            t.Start();
        }

        // "系统硬件"栏 — 设备测试：参考 C:\2024年11月2日PM SWIM串口通讯程序Server 的 OnBnClickedTestSystemButton。
        // 进入测试：发 0x1D 给硬件、所有触板/出发台/盲表强制 Open、_testMode=true、状态条改字提示。
        // 退出测试：再次点击恢复正常 — 关掉 _testMode，所有设备重置为 Closed（用户可重新开比赛）。
        private void DeviceTest_Click(object sender, RoutedEventArgs e) {
            // 2026-05-30 本地点击 (sender!=null) 时检查硬件连接
            if (sender != null && !EnsureHardwareConnected(Loc.T("Str_RC_DeviceTest"))) return;
            if (!_testMode) {
                // 2026-05-30 v2: 只有 Waiting 状态允许; Ready/Racing/Finished 直接 return
                if (_raceState != RaceState.Waiting) {
                    AddLog(Loc.T("Str_Log_DeviceTestIgnoredNotWaiting"));
                    return;
                }
                if (sender != null) {
                    var r = AppMessageBox.Show(
                        Loc.T("Str_Msg_ConfirmDeviceTest"),
                        Loc.T("Str_MsgTitle_ConfirmDeviceTest"), MessageBoxButton.YesNo, MessageBoxImage.Question);
                    if (r != MessageBoxResult.Yes) return;
                } else {
                    AddLog(Loc.T("Str_Log_RemoteRequestedDeviceTestMode"));
                }

                _testMode = true;

                // 清空原始计时日志缓冲（与参考程序 m_ReceiveData.Empty 等价）+ 滚动时间归零
                _testLastEventLeft.Clear();
                _testLastEventRight.Clear();
                _rawTimingLog.Clear();
                _runningTime = 0;
                _firstPlaceFinishTime = "";
                _firstPlaceShowStart = DateTime.MinValue;
                _lastLeaderSplitCount = 0;   // 2026-05-26 测试模式入口也清 1 名 split-count 跟踪
                if (RunningTimeText != null) {
                    RunningTimeText.Text = "0.00";
                    RunningTimeText.Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F59E0B"));
                }

                // 把所有泳道的设备都打开（损坏/未安装的不强开）
                foreach (var st in _laneDeviceStates) {
                    if (!st.LeftTouchpadBroken)   st.LeftTouchpadStatus   = DeviceStatus.Open;
                    if (!st.RightTouchpadBroken)  st.RightTouchpadStatus  = DeviceStatus.Open;
                    if (!st.LeftStartBlockBroken) st.LeftStartBlockStatus = DeviceStatus.Open;
                    if (!st.RightStartBlockBroken) st.RightStartBlockStatus = DeviceStatus.Open;
                    if (!st.LeftBlindWatch1Broken && !st.LeftBlindWatch1NotInstalled)   st.LeftBlindWatch1Status   = DeviceStatus.Open;
                    if (!st.LeftBlindWatch2Broken && !st.LeftBlindWatch2NotInstalled)   st.LeftBlindWatch2Status   = DeviceStatus.Open;
                    if (!st.LeftBlindWatch3Broken && !st.LeftBlindWatch3NotInstalled)   st.LeftBlindWatch3Status   = DeviceStatus.Open;
                    if (!st.RightBlindWatch1Broken && !st.RightBlindWatch1NotInstalled) st.RightBlindWatch1Status  = DeviceStatus.Open;
                    if (!st.RightBlindWatch2Broken && !st.RightBlindWatch2NotInstalled) st.RightBlindWatch2Status  = DeviceStatus.Open;
                    if (!st.RightBlindWatch3Broken && !st.RightBlindWatch3NotInstalled) st.RightBlindWatch3Status  = DeviceStatus.Open;
                    st.LaneCloseCountdown = 0;
                }

                // 0x1D Test_Command — 让硬件进入"任何设备触发都上报"的测试模式
                if (_timingBridge != null && _timingBridge.IsConnected) {
                    try {
                        _timingBridge.SendCommand(0x1D);
                        AddLog(Loc.T("Str_Log_Hw1dSent"));
                    } catch (Exception ex) {
                        AddLog(Loc.F("Str_Log_Hw1dSendFailedFmt", ex.Message));
                    }
                }

                UpdateLaneStatusDisplay();
                Broadcast();
                AddLog(Loc.T("Str_Log_DeviceTestModeEntered"));
            } else {
                _testMode = false;
                _testLastEventLeft.Clear();
                _testLastEventRight.Clear();
                // 退出测试：把所有设备回到 Closed（与"全部关闭"等价），用户后续可正常 Ready
                foreach (var st in _laneDeviceStates) {
                    st.LeftTouchpadStatus = DeviceStatus.Closed;
                    st.RightTouchpadStatus = DeviceStatus.Closed;
                    st.LeftStartBlockStatus = DeviceStatus.Closed;
                    st.RightStartBlockStatus = DeviceStatus.Closed;
                    st.LeftBlindWatch1Status = DeviceStatus.Closed;
                    st.LeftBlindWatch2Status = DeviceStatus.Closed;
                    st.LeftBlindWatch3Status = DeviceStatus.Closed;
                    st.RightBlindWatch1Status = DeviceStatus.Closed;
                    st.RightBlindWatch2Status = DeviceStatus.Closed;
                    st.RightBlindWatch3Status = DeviceStatus.Closed;
                }
                UpdateLaneStatusDisplay();
                Broadcast();
                AddLog(Loc.T("Str_Log_DeviceTestModeExited"));
            }
            UpdateDeviceTestButton();
        }

        // 设备测试按钮文字/底色随 _testMode 变化
        private void UpdateDeviceTestButton() {
            if (DeviceTestButton == null) return;
            // 2026-09-21 查表, 别再硬编码中文字面量——理由同 RefreshRecordsHiddenBtn。
            string label = _testMode ? Loc.T("Str_RC_DeviceTestExit") : Loc.T("Str_RC_DeviceTest");
            string bgHex = _testMode ? "#EF4444" : "#0EA5E9";
            try {
                DeviceTestButton.ApplyTemplate();
                var tb = DeviceTestButton.Template.FindName("DeviceTestButtonText", DeviceTestButton) as TextBlock;
                if (tb != null) tb.Text = label;
                if (VisualTreeHelper.GetChildrenCount(DeviceTestButton) > 0) {
                    var root = VisualTreeHelper.GetChild(DeviceTestButton, 0) as Border;
                    if (root != null) root.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString(bgHex));
                }
            } catch { }
        }

        // 根据当前连接状态刷新"系统硬件"栏里"连接串口"按钮的文字与底色（模板里的内层 TextBlock + Border）
        private void UpdateQuickConnectButton() {
            if (QuickConnectSerialButton == null) return;
            bool connected = _timingBridge != null && _timingBridge.IsConnected;
            //2026-05-14 顶栏改走网络连接，未连接时文字为"网络连接"，已连接显示"断开"
            // 2026-09-21 查表(复用"设置"页已有的 Str_Settings_Disconnect), 别再硬编码中文字面量。
            string label = connected ? Loc.T("Str_Settings_Disconnect") : Loc.T("Str_RC_NetworkConnect");
            string bgHex = connected ? "#EF4444" : "#22C55E";
            // 模板内的 TextBlock 用 x:Name="QuickConnectSerialButtonText"，
            // 模板里的 Border 是按钮 Template 的根元素 — 通过 VisualTreeHelper 拿到再改 Background
            try {
                QuickConnectSerialButton.ApplyTemplate();
                var tb = QuickConnectSerialButton.Template.FindName("QuickConnectSerialButtonText", QuickConnectSerialButton) as TextBlock;
                if (tb != null) tb.Text = label;
                if (VisualTreeHelper.GetChildrenCount(QuickConnectSerialButton) > 0) {
                    var root = VisualTreeHelper.GetChild(QuickConnectSerialButton, 0) as Border;
                    if (root != null) root.Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString(bgHex));
                }
            } catch { }
        }

        private int ReadBaudRateFromUi() {
            if (BaudRateCombo == null || BaudRateCombo.SelectedItem == null) {
                return _timingConn != null && _timingConn.SerialBaudRate > 0 ? _timingConn.SerialBaudRate : 9600;
            }
            string txt = (BaudRateCombo.SelectedItem is ComboBoxItem)
                ? ((ComboBoxItem)BaudRateCombo.SelectedItem).Content.ToString()
                : BaudRateCombo.SelectedItem.ToString();
            int v;
            return int.TryParse(txt.Trim(), out v) && v > 0 ? v : 9600;
        }

        private void BaudRate_Changed(object sender, SelectionChangedEventArgs e) {
            // 用户改波特率即落盘；连接已建立时不会立刻断开重连，等下次 ConnectSerial_Click 才生效
            if (!_initialized || _timingConn == null) return;
            int v = ReadBaudRateFromUi();
            if (v > 0 && v != _timingConn.SerialBaudRate) {
                _timingConn.SerialBaudRate = v;
                SaveTimingConnectionConfig();
                AddLog(Loc.F("Str_Log_BaudRateSavedFmt", v));
            }
        }

        private void ConnectTcp_Click(object sender, RoutedEventArgs e) {
            string addr = TcpHostBox.Text.Trim();
            string[] parts = addr.Split(':');
            string host = parts[0];
            int port = 5000;
            if (parts.Length > 1) int.TryParse(parts[1], out port);
            _timingBridge.ConnectTcp(host, port);
            UpdateConnectionStatus();
            _timingConn.TcpHost = host;
            _timingConn.TcpPort = port;
            _timingConn.LastType = "tcp";
            SaveTimingConnectionConfig();
        }

        private void ConnectUdp_Click(object sender, RoutedEventArgs e) {
            int listenPort = 5001;
            int.TryParse(UdpPortBox.Text.Trim(), out listenPort);
            string sendHost = null;
            int sendPort = 0;
            string sendText = UdpSendBox.Text.Trim();
            if (!string.IsNullOrEmpty(sendText)) {
                string[] parts = sendText.Split(':');
                if (parts.Length == 2) {
                    sendHost = parts[0];
                    int.TryParse(parts[1], out sendPort);
                }
            }
            _timingBridge.ConnectUdp(listenPort, sendHost, sendPort);
            UpdateConnectionStatus();
            _timingConn.UdpListenPort = listenPort;
            _timingConn.UdpSendHost = sendHost ?? "";
            _timingConn.UdpSendPort = sendPort;
            _timingConn.LastType = "udp";
            SaveTimingConnectionConfig();
        }

        private void DisconnectTiming_Click(object sender, RoutedEventArgs e) {
            // 2026-05-30 v2: 只有 Waiting 状态允许; Ready/Racing/Finished 直接 return
            //   (按钮已在 UpdateRaceStateDisplay 里 IsEnabled=false 禁用, 这里是 backup guard)
            if (_raceState != RaceState.Waiting) {
                AddLog(Loc.T("Str_Log_HwDisconnectIgnoredNotWaiting"));
                return;
            }
            _timingBridge.Disconnect();
            UpdateConnectionStatus();
            try { UpdateQuickConnectButton(); } catch { }
            AddLog(Loc.T("Str_Log_HwDisconnected"));
            try { Broadcast(); } catch { }
        }

        // ═══════════════════════════════════════════════════════════════
        // 纪录管理
        // ═══════════════════════════════════════════════════════════════
        private bool _recordFilterUpdating = false;

        private void RefreshRecordFilterCombos() {
            if (_recordFilterUpdating) return;
            _recordFilterUpdating = true;
            try {
                // 刷新项目下拉框
                string prevEvent = RecordFilterEvent.SelectedItem != null ? RecordFilterEvent.SelectedItem.ToString() : "";
                RecordFilterEvent.Items.Clear();
                RecordFilterEvent.Items.Add(Loc.T("Str_Common_All"));
                var eventSet = new HashSet<string>();
                foreach (var r in _records) {
                    if (!string.IsNullOrEmpty(r.EventName) && eventSet.Add(r.EventName))
                        RecordFilterEvent.Items.Add(r.EventName);
                }
                RecordFilterEvent.SelectedItem = RecordFilterEvent.Items.Contains(prevEvent) ? prevEvent : Loc.T("Str_Common_All");

                // 刷新类型下拉框
                string prevType = RecordFilterType.SelectedItem != null ? RecordFilterType.SelectedItem.ToString() : "";
                RecordFilterType.Items.Clear();
                RecordFilterType.Items.Add(Loc.T("Str_Common_All"));
                var typeSet = new HashSet<string>();
                foreach (var r in _records) {
                    if (!string.IsNullOrEmpty(r.RecordType) && typeSet.Add(r.RecordType))
                        RecordFilterType.Items.Add(r.RecordType);
                }
                RecordFilterType.SelectedItem = RecordFilterType.Items.Contains(prevType) ? prevType : Loc.T("Str_Common_All");
            } finally {
                _recordFilterUpdating = false;
            }
        }

        private void ApplyRecordFilter() {
            if (_recordFilterUpdating || RecordGrid == null) return;

            string ageFilter = RecordFilterAgeGroup != null && RecordFilterAgeGroup.SelectedItem != null ? RecordFilterAgeGroup.SelectedItem.ToString() : Loc.T("Str_Common_All");
            // 2026-10-05 RecordFilterGender 用 Tag 存中文哨兵值(展示走 Loc.GenderDisplay),
            // 这里跟着读 Tag, 下面比较也固定用原始"全部"(不随语言变)
            string gender = RecordFilterGender.SelectedItem != null ? ((ComboBoxItem)RecordFilterGender.SelectedItem).Tag.ToString() : "全部";
            string eventName = RecordFilterEvent.SelectedItem != null ? RecordFilterEvent.SelectedItem.ToString() : Loc.T("Str_Common_All");
            string recordType = RecordFilterType.SelectedItem != null ? RecordFilterType.SelectedItem.ToString() : Loc.T("Str_Common_All");
            string keyword = RecordFilterKeyword != null ? RecordFilterKeyword.Text.Trim() : "";

            var filtered = new List<SwimmingRecord>();
            foreach (var r in _records) {
                if (ageFilter != Loc.T("Str_Common_All") && (r.AgeGroup ?? "") != ageFilter) continue;
                if (gender != "全部" && r.Gender != gender) continue;
                if (eventName != Loc.T("Str_Common_All") && r.EventName != eventName) continue;
                if (recordType != Loc.T("Str_Common_All") && r.RecordType != recordType) continue;
                if (!string.IsNullOrEmpty(keyword)) {
                    bool match = false;
                    if (r.HolderName != null && r.HolderName.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0) match = true;
                    if (r.HolderCountry != null && r.HolderCountry.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0) match = true;
                    if (r.Location != null && r.Location.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0) match = true;
                    if (!match) continue;
                }
                filtered.Add(r);
            }
            RecordGrid.ItemsSource = filtered;
            RecordFilterCount.Text = Loc.F("Str_RecordMgmt_CountFilteredFmt", filtered.Count, _records.Count);
        }

        private void RecordFilter_Changed(object sender, SelectionChangedEventArgs e) {
            if (_initialized && !_recordFilterUpdating) ApplyRecordFilter();
        }

        private void RecordFilter_Changed(object sender, TextChangedEventArgs e) {
            if (_initialized && !_recordFilterUpdating) ApplyRecordFilter();
        }

        private void RecordFilterReset_Click(object sender, RoutedEventArgs e) {
            _recordFilterUpdating = true;
            if (RecordFilterAgeGroup != null && RecordFilterAgeGroup.Items.Count > 0) RecordFilterAgeGroup.SelectedIndex = 0;
            RecordFilterGender.SelectedIndex = 0;
            if (RecordFilterEvent.Items.Count > 0) RecordFilterEvent.SelectedIndex = 0;
            if (RecordFilterType.Items.Count > 0) RecordFilterType.SelectedIndex = 0;
            RecordFilterKeyword.Text = "";
            _recordFilterUpdating = false;
            RecordGrid.ItemsSource = _records;
            RecordFilterCount.Text = Loc.F("Str_RecordMgmt_CountAllFmt", _records.Count);
        }

        private void ClearAllRecords_Click(object sender, RoutedEventArgs e) {
            if (_records.Count == 0) {
                AppMessageBox.Show(Loc.T("Str_Msg_NoRecordData"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            RunWithEditLock("records-all", Loc.T("Str_Entity_RecordsList"), delegate {
                var result = AppMessageBox.Show(
                    Loc.F("Str_Msg_ConfirmDeleteAllRecordsFmt", _records.Count),
                    Loc.T("Str_SysLog_ClearRecords"), MessageBoxButton.YesNo, MessageBoxImage.Warning);
                if (result == MessageBoxResult.Yes) {
                    int count = _records.Count;
                    var recBefore = SnapshotRecords();
                    _records.Clear();
                    SaveWithoutPush();
                    PushChangedRecords(recBefore);   // 2026-09-12 按条同步, 不推整包
                    Broadcast();
                    RefreshRecordFilterCombos();
                    RecordFilterReset_Click(null, null);
                    AddLog(Loc.F("Str_Log_AllRecordsDeletedFmt", count));
                }
            });
        }

        private void AddRecord_Click(object sender, RoutedEventArgs e) {
            RunWithEditLock("records-all", Loc.T("Str_Entity_RecordsList"), delegate {
                _records.Add(new SwimmingRecord { RecordType = "赛会纪录", Gender = "男" });
                RefreshRecordFilterCombos();
                AddLog(Loc.T("Str_Log_BlankRecordRowAdded"));
            });
        }

        // ── 2026-09-12 纪录表的"保存" ────────────────────────────────────
        // 这张表是就地编辑的(IsReadOnly=False), 原来从头到尾【没有一个保存动作】:
        // 在格子里改完的值只能等别的操作顺带 AutoSaveData 才落盘, 而比赛中那条路是
        // 推整包、会被主服务器拒收 —— 于是"比赛中改纪录"实际上改不动, 还看不出原因。
        //
        // 这里显式落盘 + 按条推补丁。按条而不是推整张表: 比赛中一份旧表盖过去,
        // 刚破的纪录就没了 —— 那是出过事的形状(见 ApplyRecordsPatch 上面那段)。
        private void SaveRecords_Click(object sender, RoutedEventArgs e) {
            // 光标还停在格子里时这一格的值还没写回对象, 先逼它提交, 否则"改了没保存上"
            try {
                if (RecordGrid != null) {
                    RecordGrid.CommitEdit(DataGridEditingUnit.Cell, true);
                    RecordGrid.CommitEdit(DataGridEditingUnit.Row, true);
                }
            } catch { }

            int blank = 0;
            foreach (var r in _records) if (r != null && string.IsNullOrWhiteSpace(r.EventName)) blank++;

            var before = _recordsBaseline != null ? _recordsBaseline : SnapshotRecords();
            SaveWithoutPush();
            int changed = PushChangedRecords(before);
            RefreshRecordFilterCombos();
            ApplyRecordFilter();
            Broadcast();

            string msg = changed > 0 ? Loc.F("Str_Msg_RecordsSavedChangedFmt", changed) : Loc.T("Str_Msg_RecordsNoChange");
            if (blank > 0) msg += Loc.F("Str_Msg_RecordsBlankRowsFmt", blank);
            AppMessageBox.Show(msg, Loc.T("Str_MsgTitle_SaveRecord"), MessageBoxButton.OK, MessageBoxImage.Information);
            AddLog(Loc.F("Str_Log_RecordsSavedFmt", changed, blank > 0 ? Loc.F("Str_Log_RecordsBlankSkippedFmt", blank) : ""));
        }

        private void DeleteRecord_Click(object sender, RoutedEventArgs e) {
            var selected = RecordGrid.SelectedItem as SwimmingRecord;
            if (selected == null) return;
            string lockKey = string.Format("record:{0}:{1}:{2}:{3}",
                selected.RecordType ?? "", selected.EventName ?? "", selected.Gender ?? "", selected.AgeGroup ?? "");
            RunWithEditLock(lockKey, Loc.F("Str_Entity_RecordEntryFmt", selected.RecordType, selected.EventName, Loc.GenderDisplay(selected.Gender)), delegate {
                var recBefore = SnapshotRecords();
                _records.Remove(selected);
                SaveWithoutPush();
                PushChangedRecords(recBefore);   // 2026-09-12 按条同步, 不推整包
                RefreshRecordFilterCombos();
                ApplyRecordFilter();
            });
        }

