        private void ImportRecordsCSV_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.OpenFileDialog {
                Filter = Loc.T("Str_Filter_CsvTxtAll"),
                Title = Loc.T("Str_Win_ImportRecords_Title")
            };
            if (dlg.ShowDialog() == true) {
                try {
                    var recBefore = SnapshotRecords();   // 2026-09-12 改完跟它一比, 只发变动的那几条
                    // 检查是否为Excel二进制格式（.xls/.xlsx），提示用户先另存为CSV
                    string ext = System.IO.Path.GetExtension(dlg.FileName).ToLower();
                    if (ext == ".xls" || ext == ".xlsx") {
                        AppMessageBox.Show(
                            Loc.T("Str_Msg_XlsxReadFailedTipLong"),
                            Loc.T("Str_MsgTitle_FormatNote"), MessageBoxButton.OK, MessageBoxImage.Warning);
                        return;
                    }

                    // 自动检测编码：有UTF-8 BOM用UTF-8，否则用系统默认编码（中文Windows为GBK）
                    Encoding csvEncoding = Encoding.Default;
                    byte[] rawBytes = File.ReadAllBytes(dlg.FileName);
                    if (rawBytes.Length >= 3 && rawBytes[0] == 0xEF && rawBytes[1] == 0xBB && rawBytes[2] == 0xBF)
                        csvEncoding = Encoding.UTF8;
                    string[] lines = File.ReadAllLines(dlg.FileName, csvEncoding);
                    int imported = 0, updated = 0, skippedEmpty = 0, skippedParse = 0, skippedDup = 0;
                    for (int i = 1; i < lines.Length; i++) {
                        string line = lines[i].Trim();
                        if (string.IsNullOrEmpty(line)) continue;

                        // 支持逗号分隔和Tab分隔（Excel另存为文本时用Tab）
                        char delimiter = line.Contains('\t') ? '\t' : ',';
                        string[] cols = line.Split(delimiter);
                        if (cols.Length < 3) continue;

                        // 兼容 9 列（含组别）与 8 列（旧）两种格式：首列值是性别关键字则视为无组别
                        string first = cols[0].Trim();
                        bool hasAge = !(first == "男" || first == "女" || first == "混合");
                        int colIdx = 0;
                        string ageGroup = hasAge ? cols[colIdx++].Trim() : "";
                        if (cols.Length < (hasAge ? 4 : 3)) continue;
                        string gender = cols[colIdx++].Trim();
                        // 规范化项目名：去除多余空格（如"50 米自由泳"→"50米自由泳"）
                        string eventName = System.Text.RegularExpressions.Regex.Replace(cols[colIdx++].Trim(), @"\s+", "");
                        string recordType = cols[colIdx++].Trim();
                        string holderName = cols.Length > colIdx ? cols[colIdx++].Trim() : "";
                        string holderCountry = cols.Length > colIdx ? cols[colIdx++].Trim() : "";
                        string timeStr = cols.Length > colIdx ? cols[colIdx++].Trim() : "";
                        string dateStr = cols.Length > colIdx ? cols[colIdx++].Trim() : "";
                        string location = cols.Length > colIdx ? cols[colIdx++].Trim() : "";

                        // 跳过成绩或保持者为空的行（模板占位行）
                        if (string.IsNullOrEmpty(timeStr) || string.IsNullOrEmpty(holderName)) { skippedEmpty++; continue; }

                        // 清理成绩字符串：去除Excel可能添加的多余字符
                        // Excel可能将 1:42.00 显示为 0:01:42.00 或 1:42:00 等
                        timeStr = timeStr.Replace("'", "").Replace("\u2019", "").Trim();

                        double t = TimeFormatter.Parse(timeStr);
                        if (t <= 0) {
                            AddLog(Loc.F("Str_Log_RowParseFailedFmt", i + 1, timeStr, Loc.GenderDisplay(gender), eventName));
                            skippedParse++;
                            continue;
                        }

                        // 查找是否已存在相同纪录（组别+性别+项目+类型共同决定唯一性）
                        SwimmingRecord existing = null;
                        foreach (var r in _records) {
                            if ((r.AgeGroup ?? "") == (ageGroup ?? "") && r.Gender == gender
                                && r.EventName == eventName && r.RecordType == recordType) {
                                existing = r; break;
                            }
                        }
                        if (existing != null) {
                            if (t < existing.Time || existing.Time <= 0) {
                                existing.HolderName = holderName; existing.HolderCountry = holderCountry;
                                existing.Time = t; existing.TimeInSeconds = t;
                                existing.Date = dateStr; existing.Location = location;
                                updated++;
                            } else { skippedDup++; }
                        } else {
                            _records.Add(new SwimmingRecord {
                                AgeGroup = ageGroup, Gender = gender, EventName = eventName, RecordType = recordType,
                                HolderName = holderName, HolderCountry = holderCountry,
                                Time = t, TimeInSeconds = t, Date = dateStr, Location = location
                            });
                            imported++;
                        }
                    }
                    AddLog(Loc.F("Str_Log_CsvImportRecordsFmt",
                        imported, updated, skippedEmpty, skippedParse, skippedDup));
                    SaveWithoutPush();
                    PushChangedRecords(recBefore);   // 2026-09-12 按条同步, 不推整包
                    Broadcast();
                    RefreshRecordFilterCombos();
                } catch (Exception ex) {
                    AddLog(Loc.F("Str_Log_CsvImportRecordsFailedFmt", ex.Message));
                }
            }
        }

        private void ExportRecordTemplate_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_Csv"),
                Title = Loc.T("Str_Win_SaveRecordTemplate_Title"),
                FileName = Loc.T("Str_FileName_RecordTemplate") + ".csv"
            };
            if (dlg.ShowDialog() != true) return;
            try {
                // 所有比赛项目（个人 + 接力）
                var events = new[] {
                    "50米自由泳", "100米自由泳", "200米自由泳", "400米自由泳", "800米自由泳", "1500米自由泳",
                    "50米仰泳", "100米仰泳", "200米仰泳",
                    "50米蛙泳", "100米蛙泳", "200米蛙泳",
                    "50米蝶泳", "100米蝶泳", "200米蝶泳",
                    "200米个人混合泳", "400米个人混合泳",
                    "4×100米自由泳接力", "4×200米自由泳接力", "4×100米混合泳接力"
                };
                var genders = new[] { "男", "女" };
                var recordTypes = new[] { "世界纪录", "奥运会纪录", "亚洲纪录", "亚洲青年纪录", "全国纪录", "省运会纪录", "赛会纪录" };

                var sb = new System.Text.StringBuilder();
                // 2026-05-21 已移除显式 BOM；Encoding.UTF8 自带 BOM 前导（删除下行 sb.Append）
                // (removed: explicit BOM redundant — Encoding.UTF8 自带 BOM)
                sb.AppendLine(string.Join(",", new[] { Loc.T("Str_Col_Group"), Loc.T("Str_DocC_ColGender"), Loc.T("Str_Col_Event"), Loc.T("Str_Col_RecordType"), Loc.T("Str_Col_Holder"), Loc.T("Str_Col_Team"), Loc.T("Str_Col_RecordTime"), Loc.T("Str_Col_Date"), Loc.T("Str_Col_Location") }));

                // 已有的纪录数据先填入对应位置
                var existingMap = new Dictionary<string, SwimmingRecord>();
                foreach (var r in _records) {
                    string key = (r.AgeGroup ?? "") + "|" + r.Gender + "|" + r.EventName + "|" + r.RecordType;
                    existingMap[key] = r;
                }

                foreach (string recType in recordTypes) {
                    foreach (string gender in genders) {
                        foreach (string ev in events) {
                            string key = "" + "|" + gender + "|" + ev + "|" + recType;
                            SwimmingRecord existing;
                            if (existingMap.TryGetValue(key, out existing) && existing.Time > 0) {
                                sb.AppendLine(string.Format("{0},{1},{2},{3},{4},{5},{6},{7},{8}",
                                    existing.AgeGroup ?? "",
                                    gender, ev, recType,
                                    existing.HolderName ?? "", existing.HolderCountry ?? "",
                                    TimeFormatter.Format(existing.Time),
                                    existing.Date ?? "", existing.Location ?? ""));
                            } else {
                                sb.AppendLine(string.Format(",{0},{1},{2},,,,,", gender, ev, recType));
                            }
                        }
                    }
                    // 混合接力（仅部分项目）
                    if (recType == "世界纪录" || recType == "奥运会纪录") {
                        foreach (string ev in new[] { "4×100米自由泳接力", "4×100米混合泳接力" }) {
                            string key = "混合|" + ev + "|" + recType;
                            SwimmingRecord existing;
                            if (existingMap.TryGetValue(key, out existing) && existing.Time > 0) {
                                sb.AppendLine(string.Format("混合,{0},{1},{2},{3},{4},{5},{6}",
                                    ev, recType,
                                    existing.HolderName ?? "", existing.HolderCountry ?? "",
                                    TimeFormatter.Format(existing.Time),
                                    existing.Date ?? "", existing.Location ?? ""));
                            } else {
                                sb.AppendLine(string.Format("混合,{0},{1},,,,,", ev, recType));
                            }
                        }
                    }
                }

                File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
                AddLog(Loc.F("Str_Log_RecordTemplateExportedFmt", dlg.FileName));
                AppMessageBox.Show(
                    Loc.T("Str_Msg_RecordTemplateSaved"),
                    Loc.T("Str_MsgTitle_RecordTemplate"), MessageBoxButton.OK, MessageBoxImage.Information);
            } catch (Exception ex) {
                AddLog(Loc.F("Str_Log_RecordTemplateExportFailedFmt", ex.Message));
            }
        }

        // ═══════════════════════════════════════════════════════════════
        // 比赛参数设置管理：比赛项目 / 组别（数据库持久化 + Excel CSV 导入导出）
        // ═══════════════════════════════════════════════════════════════

        // 若组别为空/"全部"/"不限"，则不过滤（兼容旧逻辑）；否则运动员的 AgeCategory 必须与之一致
        private bool MatchesAgeGroup(Swimmer s, string ageGroup) {
            if (string.IsNullOrEmpty(ageGroup) || ageGroup == Loc.T("Str_Common_All") || ageGroup == "不限") return true;
            // 2026-06-24 "(无组别)" sentinel: EditAgeGroupCombo 专用, 仅匹配 AgeCategory 空的运动员 (= 无组别比赛)
            if (ageGroup == "(无组别)") return string.IsNullOrEmpty(s.AgeCategory);
            string sg = s.AgeCategory ?? "";
            if (sg == ageGroup) return true;
            // 2026-06-04 并项组别 (e.g. schedule "12-15岁组" 覆盖 swimmer "12-13岁组" / "14-15岁组")
            // 当 schedule 是 X-Y岁组 区间, swimmer 是其内 a-b岁组 子区间 (X<=a, b<=Y) 也算匹配
            int sLo, sHi, gLo, gHi;
            if (TryParseAgeRange(ageGroup, out gLo, out gHi) && TryParseAgeRange(sg, out sLo, out sHi)) {
                return gLo <= sLo && sHi <= gHi;
            }
            return false;
        }

        private static bool TryParseAgeRange(string s, out int lo, out int hi) {
            lo = hi = 0;
            if (string.IsNullOrEmpty(s)) return false;
            // 2026-06-05 加 全角波浪号 ~ (.xls 跨年龄并项写法 '12~15岁组') 和 半角 ~ 支持
            var m = System.Text.RegularExpressions.Regex.Match(s, @"(\d+)\s*[-~~]\s*(\d+)\s*岁组");
            if (!m.Success) {
                var m2 = System.Text.RegularExpressions.Regex.Match(s, @"(\d+)\s*岁组");
                if (m2.Success) {
                    int a; if (int.TryParse(m2.Groups[1].Value, out a)) { lo = hi = a; return true; }
                }
                return false;
            }
            return int.TryParse(m.Groups[1].Value, out lo) && int.TryParse(m.Groups[2].Value, out hi) && lo <= hi;
        }

        // 2026-06-01 性别匹配 (含混合): 选 男 时 男 + 混合 都算; 选 女 时 女 + 混合 都算; 选 混合 严格只含 混合.
        //   FINA 惯例: 男女混合接力项目对 男/女 单性别筛选 应可见, 避免用户在"出场编排微调"等界面找不到接力.
        private bool GenderMatchesIncludingMixed(string swimmerGender, string filterGender) {
            if (string.IsNullOrEmpty(filterGender)) return true;
            if (filterGender == Loc.T("Str_Common_All") || filterGender == "不限") return true;
            string sg = swimmerGender ?? "";
            if (filterGender == "混合") return sg == "混合";
            // 2026-06-04 男女 并项: 选 男女 时, 男 + 女 都算 (青少年并项个人项目)
            // 2026-06-05 加 男女: 接力 TEAM swimmer 条目 Gender 本身就是 '男女'
            // 2026-08-22 只收紧这一支: 数据里存在 Gender 就是"男女"的条目(= 混合接力)时,
            //   选"男女"只出混合接力本身, 不再把同名的男子/女子项拉进来
            //   (成绩录入表格、编辑分组下拉都受此影响)。
            //   反方向"选男时也显示混合接力"是 2026-06-01 按 FINA 惯例特意做的, 保持不变。
            if (filterGender == "男女") {
                if (AnyExplicitMixedSwimmer()) return sg == "男女" || sg == "混合";
                return sg == "男" || sg == "女" || sg == "男女";
            }
            // 选 男 或 女 时, 同性别 + 混合 都算
            return sg == filterGender || sg == "混合";
        }

        // ══════════════════════════════════════════════════════════════
        // 2026-08-21 性别匹配修正 —— 混合接力与男子/女子同名项目互相串
        //
        // 现象：甘肃省十六运大屏出现重复道次 3,3,4,4,5,5。
        // 背景：本届 4x50米自由泳接力(少年组) 同时排了 男女 / 男 / 女 三个项目，
        //       4x100米自由泳接力(青年组) 排了 男女 / 男 两个。它们的
        //       项目名 + 组别 + 赛次 + 组次 完全相同，只有性别不同。
        // 原来的判定有两处让它们互相串：
        //   1) s.Gender.StartsWith(gender) —— 本意是兼容 "男"/"男子" 两种写法，
        //      但 "男女".StartsWith("男") 也为真，混合接力队被捞进了男子项；
        //   2) gender == "男女" 时无条件把 男 和 女 都并进来 —— 这本是给
        //      "男女并项"(男女同场比、分开排名) 用的，用在混合接力项目上会把
        //      男子项和女子项整个并进来（男女少年组4x50 应 7 队，实际出 23 条）。
        //
        // 现在的规则：
        //   · 先归一 男子→男 / 女子→女 / 混合→男女，再精确比（不再用前缀）；
        //   · gender == "男女" 分两种情形，用 hasExplicitMixed 区分：
        //       该项目里存在 Gender 本身就是"男女"的报名条目 → 混合接力，只取这些；
        //       不存在                                        → 男女并项，男和女都并进来。
        // 2026-08-21 把一个性别下拉按 GenderRegistry 重填。
        //   保留原有的"全部"项和当前选中值；档案里没有但当前选着的值也补进来，
        //   免得下拉一重填就把用户的选择改掉。各结果/打印窗口共用。
        /// <summary>
        /// 2026-09-03 按【比赛参数设置管理 → 赛次】填赛次下拉。跟 FillGenderCombo 一个用法:
        /// 原来有"全部"的保留"全部", 尽量保住原选中项。
        /// 弹窗(项目成绩/批量公布…)拿不到 _stages, 走 StageRegistry。
        /// </summary>
        public static void FillStageCombo(System.Windows.Controls.ComboBox cb) {
            if (cb == null) return;
            string prev = "";
            var selItem = cb.SelectedItem as System.Windows.Controls.ComboBoxItem;
            if (selItem != null && selItem.Content != null) prev = selItem.Content.ToString();
            else if (cb.SelectedItem is string) prev = (string)cb.SelectedItem;
            bool hasAll = false;
            foreach (var it in cb.Items) {
                var ci = it as System.Windows.Controls.ComboBoxItem;
                if (ci != null && ci.Content != null && ci.Content.ToString() == Loc.T("Str_Common_All")) { hasAll = true; break; }
            }
            cb.Items.Clear();
            if (hasAll) cb.Items.Add(new System.Windows.Controls.ComboBoxItem { Content = Loc.T("Str_Common_All") });
            foreach (var s in StageRegistry.List) cb.Items.Add(new System.Windows.Controls.ComboBoxItem { Content = s });
            for (int i = 0; i < cb.Items.Count; i++) {
                var ci = cb.Items[i] as System.Windows.Controls.ComboBoxItem;
                if (ci != null && ci.Content != null && ci.Content.ToString() == prev) { cb.SelectedIndex = i; return; }
            }
            // 原来选的赛次被改没了 → 落到最后一个(通常是决赛), 比落到"全部"更贴近日常用法
            if (cb.Items.Count > 0) cb.SelectedIndex = cb.Items.Count - 1;
        }

        // 2026-10-05 同 RefillGenderCombos: Tag=中文哨兵(比较用), Content=展示翻译
        public static void FillGenderCombo(System.Windows.Controls.ComboBox cb) {
            if (cb == null) return;
            string prev = "";
            var selItem = cb.SelectedItem as System.Windows.Controls.ComboBoxItem;
            if (selItem != null && selItem.Tag != null) prev = selItem.Tag.ToString();
            else if (cb.SelectedItem is string) prev = (string)cb.SelectedItem;
            bool hasAll = false;
            foreach (var it in cb.Items) {
                var ci = it as System.Windows.Controls.ComboBoxItem;
                if (ci != null && ci.Tag != null && ci.Tag.ToString() == "全部") { hasAll = true; break; }
            }
            cb.Items.Clear();
            if (hasAll) cb.Items.Add(new System.Windows.Controls.ComboBoxItem { Tag = "全部", Content = Loc.T("Str_Common_All") });
            foreach (var g in GenderRegistry.List) cb.Items.Add(new System.Windows.Controls.ComboBoxItem { Tag = g, Content = Loc.GenderDisplay(g) });
            if (!string.IsNullOrEmpty(prev) && !GenderRegistry.List.Contains(prev) && prev != "全部")
                cb.Items.Add(new System.Windows.Controls.ComboBoxItem { Tag = prev, Content = Loc.GenderDisplay(prev) });
            for (int i = 0; i < cb.Items.Count; i++) {
                var ci = cb.Items[i] as System.Windows.Controls.ComboBoxItem;
                if (ci != null && ci.Tag != null && ci.Tag.ToString() == prev) { cb.SelectedIndex = i; return; }
            }
            if (cb.Items.Count > 0) cb.SelectedIndex = 0;
        }

        private static string NormGender(string g) {
            if (string.IsNullOrEmpty(g)) return "";
            if (g == "男子") return "男";
            if (g == "女子") return "女";
            if (g == "混合") return "男女";
            return g;
        }
        private static bool GenderMatchEx(string swimmerGender, string filterGender, bool hasExplicitMixed) {
            string s = NormGender(swimmerGender);
            string f = NormGender(filterGender);
            if (string.IsNullOrEmpty(f)) return true;
            if (f == "男女") {
                return hasExplicitMixed ? (s == "男女")
                                        : (s == "男" || s == "女" || s == "男女");
            }
            return s == f;
        }
        // 该项目(项目名+组别)里有没有 Gender 本身就是"男女"/"混合"的报名条目 = 是不是混合接力项目
        private bool HasExplicitMixedEntry(string eventName, string ageGroup) {
            if (string.IsNullOrEmpty(eventName) || _swimmers == null) return false;
            foreach (var s in _swimmers) {
                if (s.EventName != eventName) continue;
                if (NormGender(s.Gender) != "男女") continue;
                if (!MatchesAgeGroup(s, ageGroup)) continue;
                return true;
            }
            return false;
        }

        // 2026-06-04 严格相等 + 男女并项: 给原本写 SgMatch(s.Gender, gender) 的位置用
        //   gender == "男女" 时, swimmer 是 男 或 女 都匹配 (并项项目)
        //   其它情况: 严格相等 (维持旧行为)
        // 2026-08-22 现场第三批：筛"男女"时原来无条件把 男 和 女 都并进来，
        //   那是给"男女并项"(男女同场比、分开排名)用的。本届 4x50/4x100 接力
        //   同时排了 男女/男/女 同名项目，于是：
        //     · 总排名里混进别项目的道次；
        //     · 每组成绩 txt 用泳道号做字典键，后来的把有成绩的覆盖成 0。
        //   改为：数据里若存在 Gender 本身就是"男女"的报名条目(= 混合接力)，
        //   就按精确比对；否则维持并项的旧行为。SgMatch 有 42 处调用，
        //   在这里统一收紧，比逐处改安全。
        private bool SgMatch(string swimmerGender, string filterGender) {
            return GenderMatchEx(swimmerGender, filterGender, AnyExplicitMixedSwimmer());
        }

        // 报名数据里有没有 Gender 就是"男女"/"混合"的条目。按 _swimmers.Count 缓存，
        // 增删运动员会自动重算；就地改性别的路径调 InvalidateMixedCache()。
        private bool _mixedCacheValue = false;
        private int  _mixedCacheCount = -1;
        private bool AnyExplicitMixedSwimmer() {
            if (_swimmers == null) return false;
            if (_mixedCacheCount != _swimmers.Count) {
                _mixedCacheCount = _swimmers.Count;
                _mixedCacheValue = false;
                foreach (var s in _swimmers) {
                    if (NormGender(s.Gender) == "男女") { _mixedCacheValue = true; break; }
                }
            }
            return _mixedCacheValue;
        }
        private void InvalidateMixedCache() { _mixedCacheCount = -1; }

        private void RefreshEventComboBoxes() {
            // 重建依赖 _events 的下拉：RegEventCombo / FilterEventCombo / ResultEventCombo / RecordFilterEvent
            if (RegEventCombo != null) {
                object prev = RegEventCombo.SelectedItem;
                RegEventCombo.Items.Clear();
                foreach (string ev in _events) RegEventCombo.Items.Add(new ComboBoxItem { Content = ev });
                if (RegEventCombo.Items.Count > 0) RegEventCombo.SelectedIndex = 0;
            }
            if (FilterEventCombo != null) {
                FilterEventCombo.Items.Clear();
                FilterEventCombo.Items.Add(new ComboBoxItem { Content = Loc.T("Str_Common_All"), IsSelected = true });
                foreach (string ev in _events) FilterEventCombo.Items.Add(new ComboBoxItem { Content = ev });
            }
            if (ResultEventCombo != null) {
                string prev = ResultEventCombo.SelectedItem as string;
                ResultEventCombo.Items.Clear();
                foreach (string ev in _events) ResultEventCombo.Items.Add(ev);
                if (!string.IsNullOrEmpty(prev) && ResultEventCombo.Items.Contains(prev))
                    ResultEventCombo.SelectedItem = prev;
                else if (ResultEventCombo.Items.Count > 0) ResultEventCombo.SelectedIndex = 0;
            }
            if (RecordFilterEvent != null) {
                string prev = RecordFilterEvent.SelectedItem as string;
                RecordFilterEvent.Items.Clear();
                RecordFilterEvent.Items.Add(Loc.T("Str_Common_All"));
                foreach (string ev in _events) RecordFilterEvent.Items.Add(ev);
                if (!string.IsNullOrEmpty(prev) && RecordFilterEvent.Items.Contains(prev))
                    RecordFilterEvent.SelectedItem = prev;
                else RecordFilterEvent.SelectedIndex = 0;
            }
        }

