        // ═══════════════════════════════════════════════════════════════
        // 赛程/分组表 CSV 导入导出（Excel/WPS 可直接打开或另存为 CSV 导入）
        // ═══════════════════════════════════════════════════════════════

        // —— 日程表 CSV ——
        // 列: 场,日期,时间,性别,项目,阶段,组数
        private static string CsvEscape(string s) {
            if (s == null) return "";
            if (s.IndexOfAny(new[] { ',', '"', '\n', '\r' }) >= 0)
                return "\"" + s.Replace("\"", "\"\"") + "\"";
            return s;
        }

        private static List<string[]> ReadCsvLines(string path) {
            byte[] raw = File.ReadAllBytes(path);

            // 2026-05-21 智能编码嗅探（修"UTF-8 无 BOM 文件被当 GBK 读出乱码"的 bug）：
            //   1. BOM 优先：UTF-8 BOM / UTF-16 LE BOM / UTF-16 BE BOM 直接用对应编码
            //   2. 无 BOM 时：先用 UTF-8 严格解码（new UTF8Encoding(false, true) 遇非法
            //      字节会抛 DecoderFallbackException），成功 → 当 UTF-8；
            //      抛异常 → 退化到 Encoding.Default（中文 Windows = GBK），向后兼容旧
            //      版 Excel "另存为 CSV" 输出的 GBK 文件。
            //   这样 VS Code / WPS / Mac 工具 / 任何 UTF-8-no-BOM 来源的 CSV 都能正确读。
            string text;
            if (raw.Length >= 3 && raw[0] == 0xEF && raw[1] == 0xBB && raw[2] == 0xBF) {
                text = Encoding.UTF8.GetString(raw, 3, raw.Length - 3);
            } else if (raw.Length >= 2 && raw[0] == 0xFF && raw[1] == 0xFE) {
                text = Encoding.Unicode.GetString(raw, 2, raw.Length - 2);            // UTF-16 LE
            } else if (raw.Length >= 2 && raw[0] == 0xFE && raw[1] == 0xFF) {
                text = Encoding.BigEndianUnicode.GetString(raw, 2, raw.Length - 2);   // UTF-16 BE
            } else {
                try {
                    var strictUtf8 = new UTF8Encoding(false, true);   // throwOnInvalidBytes
                    text = strictUtf8.GetString(raw);
                } catch (DecoderFallbackException) {
                    text = Encoding.Default.GetString(raw);            // 旧版 GBK CSV 兜底
                }
            }

            var rows = new List<string[]>();
            var row = new List<string>();
            var cur = new StringBuilder();
            bool inQuotes = false;
            for (int i = 0; i < text.Length; i++) {
                char ch = text[i];
                if (inQuotes) {
                    if (ch == '"') {
                        if (i + 1 < text.Length && text[i + 1] == '"') { cur.Append('"'); i++; }
                        else inQuotes = false;
                    } else cur.Append(ch);
                } else {
                    if (ch == '"') inQuotes = true;
                    else if (ch == ',' || ch == '\t') { row.Add(cur.ToString()); cur.Length = 0; }
                    else if (ch == '\r') { }
                    else if (ch == '\n') { row.Add(cur.ToString()); cur.Length = 0; rows.Add(row.ToArray()); row = new List<string>(); }
                    else cur.Append(ch);
                }
            }
            if (cur.Length > 0 || row.Count > 0) { row.Add(cur.ToString()); rows.Add(row.ToArray()); }
            return rows;
        }

        private void ExportScheduleCSV_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.SaveFileDialog {
                Filter = Loc.T("Str_Filter_Csv"),
                Title = Loc.T("Str_Win_ExportScheduleCsv_Title"),
                // 2026-09-30 现场反馈: 起了运动会名称的比赛, 导出文件名只有运动会名, 没有"日程表"
                //   字样, 看文件名认不出是赛程——不管有没有起运动会名, 都加上"_日程表"后缀。
                FileName = (string.IsNullOrEmpty(_competitionName) ? "" : _competitionName + "_") + Loc.T("Str_FileName_Schedule") + ".csv"
            };
            if (dlg.ShowDialog() != true) return;
            try {
                var sb = new StringBuilder();
                // 2026-05-21 已移除显式 BOM，Encoding.UTF8 在写入时自带 BOM
                sb.AppendLine(string.Join(",", new[] { Loc.T("Str_DocC_ColSession"), Loc.T("Str_Col_Date"), Loc.T("Str_DocC_ColTime"), Loc.T("Str_Col_Group"), Loc.T("Str_DocC_ColGender"), Loc.T("Str_Col_Event"), Loc.T("Str_DocC_ColStage"), Loc.T("Str_Col_HeatCount") }));
                foreach (var s in _schedule) {
                    sb.AppendLine(string.Format("{0},{1},{2},{3},{4},{5},{6},{7}",
                        s.SessionNumber,
                        CsvEscape(s.Date),
                        CsvEscape(s.Time),
                        CsvEscape(s.AgeGroup),
                        CsvEscape(s.Gender),
                        CsvEscape(s.EventName),
                        CsvEscape(s.Stage),
                        s.HeatCount));
                }
                File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
                AddLog(Loc.F("Str_Log_ScheduleCsvExportedFmt", _schedule.Count, dlg.FileName));
                AppMessageBox.Show(Loc.T("Str_Msg_ScheduleExported"), Loc.T("Str_MsgTitle_Done"));
            } catch (Exception ex) {
                AppMessageBox.Show(Loc.F("Str_Msg_ExportFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"));
            }
        }

        private void ImportScheduleCSV_Click(object sender, RoutedEventArgs e) {
            var dlg = new Microsoft.Win32.OpenFileDialog {
                Filter = Loc.T("Str_Filter_CsvTxtAll"),
                Title = Loc.T("Str_Win_ImportScheduleCsv_Title")
            };
            if (dlg.ShowDialog() != true) return;
            string ext = IOPath.GetExtension(dlg.FileName).ToLower();
            if (ext == ".xls" || ext == ".xlsx") {
                AppMessageBox.Show(Loc.T("Str_Msg_XlsxReadFailedTip2"),
                    Loc.T("Str_MsgTitle_FormatNote"), MessageBoxButton.OK, MessageBoxImage.Warning); return;
            }
            if (_schedule.Count > 0) {
                if (AppMessageBox.Show(Loc.F("Str_Msg_ConfirmReplaceScheduleFmt", _schedule.Count),
                    Loc.T("Str_MsgTitle_Confirm"), MessageBoxButton.YesNo) != MessageBoxResult.Yes) return;
            }
            try {
                var rows = ReadCsvLines(dlg.FileName);
                if (rows.Count < 2) { AppMessageBox.Show(Loc.T("Str_Msg_CsvNoValidData")); return; }
                _schedule.Clear();
                int imported = 0, skipped = 0;
                for (int i = 1; i < rows.Count; i++) {
                    var c = rows[i];
                    if (c.Length == 0 || (c.Length == 1 && string.IsNullOrWhiteSpace(c[0]))) { skipped++; continue; }
                    int sessionNum = 0;
                    if (c.Length > 0) int.TryParse((c[0] ?? "").Trim(), out sessionNum);
                    string date = c.Length > 1 ? NormalizeDate((c[1] ?? "").Trim()) : "";
                    string time = c.Length > 2 ? NormalizeTime((c[2] ?? "").Trim()) : "";
                    // 兼容 8 列（含组别）/ 7 列（旧：无组别）两种格式
                    string ageGroup = "";
                    string gender, eventName, stage;
                    int heatCount = 0;
                    if (c.Length >= 8) {
                        ageGroup = (c[3] ?? "").Trim();
                        gender = (c[4] ?? "").Trim();
                        eventName = System.Text.RegularExpressions.Regex.Replace((c[5] ?? "").Trim(), @"\s+", "");
                        stage = (c[6] ?? "").Trim();
                        int.TryParse((c[7] ?? "").Trim(), out heatCount);
                    } else {
                        gender = c.Length > 3 ? (c[3] ?? "").Trim() : "";
                        eventName = c.Length > 4 ? System.Text.RegularExpressions.Regex.Replace((c[4] ?? "").Trim(), @"\s+", "") : "";
                        stage = c.Length > 5 ? (c[5] ?? "").Trim() : "";
                        if (c.Length > 6) int.TryParse((c[6] ?? "").Trim(), out heatCount);
                    }
                    if (string.IsNullOrEmpty(eventName) || string.IsNullOrEmpty(gender) || string.IsNullOrEmpty(stage)) { skipped++; continue; }
                    _schedule.Add(new ScheduleItem {
                        SessionNumber = sessionNum, Date = date, Time = time, AgeGroup = ageGroup,
                        Gender = gender, EventName = eventName, Stage = stage,
                        HeatCount = heatCount, IsRelay = eventName.Contains("接力")
                    });
                    imported++;
                }
                BuildScheduleTree();
                FinishAndSyncPatch(BuildListSetPatch("schedule", JArray.FromObject(_schedule), ClientLabel()), "meet");
                AddLog(Loc.F("Str_Log_ScheduleImportedFmt", imported, skipped));
                AppMessageBox.Show(Loc.F("Str_Msg_ImportedScheduleFmt", imported, skipped), Loc.T("Str_MsgTitle_Done"));
            } catch (Exception ex) {
                AppMessageBox.Show(Loc.F("Str_Msg_ImportFailedFmt", ex.Message), Loc.T("Str_MsgTitle_Error"));
            }
        }

