            win = new ProgramBookEditWindow(_programBook, teamProvider, previewProvider) { Owner = this };
            if (win.ShowDialog() == true && win.Saved && win.Result != null) {
                _programBook = win.Result;
                AutoSaveData();
                AddLog(Loc.T("Str_Log_ProgramCustomContentSaved"));
