        // 比赛控制 Tab "确认本组成绩"下方的"打印成绩"按钮：
        // - 当前组成绩已确认 → 直接打印当前组成绩单
        // - 仍在比赛 / 未确认 → 弹窗提示"正在比赛中，不能打印，请稍后"
        private void PrintCurrentHeatResult_Click(object sender, RoutedEventArgs e) {
            // 2026-08-31 打印本组成绩单前先从库【增量】刷新 —— 别的计算机写的成绩才看得到。
            //   开销是一条轻查询; 没变动就一行成绩都不读。
            try { RefreshChangedFromDb(); } catch { }
            // 当前组是否已确认：以 _resultConfirmed（本次刚确认）或 _confirmedHeats（历史已确认）为准
            bool confirmed = _resultConfirmed
                || _confirmedHeats.Contains(ConfirmedHeatKey(_currentAgeGroup, _currentGender, _currentEvent, _currentStage, _currentHeat));
            if (!confirmed) {
                AppMessageBox.Show(Loc.T("Str_Msg_CannotPrintWhileRacing"), Loc.T("Str_MsgTitle_Info"), MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            GenerateAndOpenDocument(Loc.T("Str_DocTitle_HeatResults"), BuildHeatResultsHtml());
        }
        private void PrintEventResults_Click(object sender, RoutedEventArgs e) {
            RefreshChangedFromDb();   // 2026-09-01 开窗前先增量刷一次(别的计算机写的成绩/定稿名次)
            // 2026-06-01 传 _ageGroups 给窗口构造组别下拉
            var win = new EventResultPrintWindow(_swimmers, _schedule, _competitionName,
                LocationBox.Text, RefereeBox.Text, ChiefJudgeBox.Text, ArbiterBox.Text, _ageGroups);
            // 2026-08-31 查询/打印前先从库刷新 —— 别的计算机写了库, 本机内存不会知道
            win.RefreshFromDb = RefreshStageFromDb;
            // 2026-09-01 【项目成绩优先直接读库里的组排名表】。
            //   内存里的成绩行只有主服务器亲自收到过回推才有; 回推丢一次、道次对不上一次,
            //   库里明明是全的、名次也定了稿, 这张表照样是空的 —— 这就是"确认后的成绩查不到"。
            //   名次既然已经定稿在库里, 就该直接从库排版, 内存只当没有定稿时的退路。
            win.ReadEventRankings = delegate(string ag, string gd, string ev, string st) {
                return _meetDb.GetEventRankingRows(ag, gd, ev, st);
            };
            win.ReadEventProgress = delegate(string ag, string gd, string ev, string st) {
                int total, pending, ranked;
                _meetDb.GetEventRankingProgress(ag, gd, ev, st, out total, out pending, out ranked);
                return new int[] { total, pending, ranked };
            };
            // 2026-09-02 左侧赛程导航直接用主窗口那棵的构建函数, 跟"成绩与排名"同一份
            win.BuildNavTree = delegate(System.Windows.Controls.TreeView tv, string q, string filter) {
                RebuildNavTree(tv, q, filter);
            };
            win.GenerateEventRanking = delegate(string ag, string gd, string ev, string st) {
                int made = _meetDb.GenerateEventRankingIfComplete(ag, gd, ev, st, Environment.MachineName + "(补生成)");
                if (made > 0) {
                    AppendTriPlaceholdersToEventRanking(ag, gd, ev, st);
                    try { ApplyEventRankingsFromDb(); } catch { }
                }
                return made;
            };
            // 2026-09-17 打印选了【第X组】时, 只该看这一组自己确认没确认——跟"生成组
            //   成绩"要求的"全项目都确认"是两件事, 不能拿后者去卡前者。
            win.IsHeatConfirmed = delegate(string ag, string gd, string ev, string st, int heat) {
                return _meetDb.IsHeatConfirmed(ag, gd, ev, st, heat);
            };
            win.Owner = this;
            win.ShowDialog();
        }

