        // 2026-09-16 奖状改从选择窗口来 —— 原来是"决赛前 3 名, 一次性全出",
        //   现在先收集候选名单给 AwardCertificateWindow 挑选(单张/批量/按项目筛选),
        //   再拿选中的子集来生成。
        public class AwardCandidateRow {
            // 2026-09-17 原来是裸字段(public string X, Y, Z;)。WPF 的 {Binding} 只认
            //   公有属性, 不认公有字段——DataGrid 里除了靠"选中"复选框(程序里手动
            //   Selected=true 再 Items.Refresh, 不走绑定回写)之外, 其余每一列全部
            //   显示空白(用户截图"看不清"其实不是配色问题, 是整列压根没绑上)。
            //   改成自动属性后 Binding 才能真正读到值。
            public string Gender { get; set; }
            public string EventName { get; set; }
            public string EventLabel { get; set; }
            public string DisplayName { get; set; }
            public string Country { get; set; }
            public string RankLabel { get; set; }
            public string AgeGroup { get; set; }
            public string TimeText { get; set; }
            public int Rank { get; set; }
            public Swimmer Sw { get; set; }
            public bool Selected { get; set; }
        }

        private List<AwardCandidateRow> CollectAwardCandidates() {
            string[] rankNames = {
                Loc.T("Str_DocC_Rank1"), Loc.T("Str_DocC_Rank2"), Loc.T("Str_DocC_Rank3"), Loc.T("Str_DocC_Rank4"),
                Loc.T("Str_DocC_Rank5"), Loc.T("Str_DocC_Rank6"), Loc.T("Str_DocC_Rank7"), Loc.T("Str_DocC_Rank8")
            };
            var result = new List<AwardCandidateRow>();
            if (_swimmers == null) return result;
            // 2026-09-17 打印到第几名由"证书参数设置"里的下拉框决定(原来写死 Take(3))。
            //   rankNames 只备了 8 个名次, 超出的用"第N名"兜底, 但 UI 下拉框本身就
            //   限定在 1~8, 正常不会走到兜底分支。
            int rankLimit = _awardCertRankLimit > 0 ? _awardCertRankLimit : 3;
            // 2026-09-19 用户实拍到奖状窗口一直没有组别筛选——查到根子比"少个筛选框"
            //   严重得多: 这里分组一直没带组别, 只按"性别+项目"分——同一个项目甲组/乙组
            //   各游各的决赛, 名次却被按成绩混在一起重排一遍, 快的组别把慢的组别全部
            //   挤出前 3 名。青少年赛的组别就是分开发奖的依据, 混排等于把不同组别的
            //   比赛当成同一场比, 发错奖状认不出来(名字都对, 只是那个人根本没资格拿
            //   这个名次)。分组键加 AgeGroup, 各组别各排各的。
            var finalists = _swimmers.Where(s => s.CurrentStage == "决赛" && s.Results.Any(r => r.Stage == "决赛" && r.FinalTime > 0))
                .GroupBy(s => new { s.Gender, s.EventName, AgeGroup = s.AgeCategory ?? "" });
            foreach (var g in finalists) {
                var ranked = g.OrderBy(s => {
                    var r = s.GetResultForStage("决赛");
                    return r != null ? r.FinalTime : double.MaxValue;
                }).Take(rankLimit).ToList();
                for (int i = 0; i < ranked.Count; i++) {
                    var sw = ranked[i];
                    bool certRelay = g.Key.EventName.Contains("接力");
                    string displayName = sw.Name;
                    if (certRelay && !string.IsNullOrEmpty(sw.Notes) && sw.Notes.StartsWith("接力队 棒次:"))
                        displayName = sw.Country + "（" + sw.Notes.Substring("接力队 棒次:".Length) + "）";
                    var rFinal = sw.GetResultForStage("决赛");
                    result.Add(new AwardCandidateRow {
                        Gender = g.Key.Gender, EventName = g.Key.EventName,
                        EventLabel = g.Key.Gender + " " + g.Key.EventName,
                        Rank = i + 1, RankLabel = i < rankNames.Length ? rankNames[i] : Loc.F("Str_DocC_RankNFmt", i + 1),
                        Sw = sw, DisplayName = displayName, Country = sw.Country ?? "",
                        AgeGroup = sw.AgeCategory ?? "",
                        TimeText = (rFinal != null && rFinal.FinalTime > 0) ? TimeFormatter.Format(rFinal.FinalTime) : ""
                    });
                }
            }
            return result;
        }

        private void PrintAwardCertificate_Click(object sender, RoutedEventArgs e) {
            var candidates = CollectAwardCandidates();
            var win = new AwardCertificateWindow(candidates) { Owner = this };
            // 2026-09-17 标题里的"决赛前 N 名"要跟着上次设置的名次范围走, 不能一直
            //   显示写死的"3"——哪怕这次没改设置, 也用当前 _awardCertRankLimit 刷一遍。
            win.RefreshCandidates(candidates, _awardCertRankLimit);
            win.OnGenerate = delegate(List<AwardCandidateRow> selected, string template, double offX, double offY) {
                GenerateAndOpenDocument(Loc.T("Str_DocTitle_AwardCert"), BuildAwardCertificateHtml(selected, template, offX, offY));
                win.Close();
            };
            win.OnOpenCertSettings = delegate { OpenCertSettingsDialog(win, true); };
            win.ShowDialog();
        }

        // 2026-09-17 奖状/纪录证书选择窗口里的"证书参数设置"按钮共用这一个弹窗——
        //   主办单位/承办单位复用赛事信息里已有的 OrganizerBox/HostBox, 组委会(盖章)
        //   落款是新加的 _certCommitteeText, 确认后立即 AutoSaveData() 落盘, 不等下次
        //   自动保存。isAward=true 时额外带上"打印到第几名"(只有奖状才有名次这回事,
        //   纪录证书不显示这一项)——改了名次以后候选名单变了, 得把已经打开的
        //   AwardCertificateWindow 里的表格连同标题一起刷新, 不然用户看到的还是旧名单。
        private void OpenCertSettingsDialog(Window owner, bool isAward) {
            int? rankLimit = isAward ? (int?)_awardCertRankLimit : null;
            var dlg = new CertSettingsWindow(OrganizerBox.Text, HostBox.Text, _certCommitteeText, _competitionName, rankLimit) { Owner = owner };
            dlg.OnConfirm = delegate(string organizer, string host, string committee, int? newRankLimit) {
                OrganizerBox.Text = organizer;
                HostBox.Text = host;
                _certCommitteeText = committee;
                if (isAward && newRankLimit.HasValue) {
                    _awardCertRankLimit = newRankLimit.Value;
                    var awardWin = owner as AwardCertificateWindow;
                    if (awardWin != null) awardWin.RefreshCandidates(CollectAwardCandidates(), _awardCertRankLimit);
                }
                AutoSaveData();
            };
            dlg.ShowDialog();
        }

        // 2026-09-16 四选一模板:
        //   "full_haosha"/"full_gansu" = 完全自己画的完整证书(边框/大标题/底色都是程序画的,
        //     打在空白纸上就是整张证书), 分别照浩沙FAFA杯 / 甘肃省运动会那两张照片的
        //     配色版式画;
        //   "preprint_gansu"/"preprint_haosha" = 用户提供的两张已经印好边框图案+盖好章的
        //     实体证书纸(见 两种标准版的获奖证书模板2026-7-29.pdf), 现场只把姓名/项目/
        //     成绩这几项套打到纸上留白的横线位置, 不能再画任何装饰(纸上已经有了)。
        private string BuildAwardCertificateHtml(List<AwardCandidateRow> selected, string template, double offXmm, double offYmm) {
            if (template == "preprint_gansu" || template == "preprint_haosha")
                return BuildAwardCertificatePreprintedHtml(selected, template, offXmm, offYmm);
            if (template == "full_gansu")
                return BuildAwardCertificateFullGansuHtml(selected);
            return BuildAwardCertificateFullHaoshaHtml(selected);
        }

        // 2026-09-16 "预印证书套打"——字段坐标是照着用户给的实体证书照片目测的比例换算
        //   到 A4(210×297mm)的, 不是拿真尺量出来的, 打印机型号/纸张进纸位置都可能有偏差。
        //   选择窗口里留了"水平/垂直微调(mm)"，实机套打对不上时直接改那两个数, 不用回来
        //   改代码——两个数是整体平移, 4~5 个字段一起挪。
        private string BuildAwardCertificatePreprintedHtml(List<AwardCandidateRow> selected, string template, double offXmm, double offYmm) {
            var sb = new StringBuilder();
            sb.Append("<!DOCTYPE html><html><head><meta charset='UTF-8'><style>");
            sb.Append("body{font-family:'SimSun',serif;margin:0;padding:0;}");
            sb.Append(".cert-page{width:210mm;height:297mm;position:relative;page-break-after:always;box-sizing:border-box;overflow:hidden;}");
            sb.Append(".fld{position:absolute;font-size:13pt;color:#111;white-space:nowrap;}");
            sb.Append("@media print{@page{size:A4;margin:0;}}");
            sb.Append("</style></head><body>");

            string dateStr = GetDatePickerText(StartDatePicker);
            string endDateStr = GetDatePickerText(EndDatePicker);
            string dateRange = string.IsNullOrEmpty(dateStr) ? "" : (dateStr + (string.IsNullOrEmpty(endDateStr) || endDateStr == dateStr ? "" : (" " + Loc.T("Str_DocC_ToWord") + " " + endDateStr)));
            string location = LocationBox.Text ?? "";
            string timeLocation = (dateRange + (string.IsNullOrEmpty(location) ? "" : ("　" + location))).Trim();

            Func<AwardCandidateRow, string> eventScoreText = c => c.Gender + c.EventName + "　" + c.RankLabel + (string.IsNullOrEmpty(c.TimeText) ? "" : ("　" + c.TimeText));
            Func<AwardCandidateRow, string> groupEventText = c => (string.IsNullOrEmpty(c.AgeGroup) ? "" : (c.AgeGroup + " ")) + c.Gender + c.EventName;
            Func<AwardCandidateRow, string> rankScoreText = c => c.RankLabel + (string.IsNullOrEmpty(c.TimeText) ? "" : ("　" + c.TimeText));

            foreach (var c in selected ?? new List<AwardCandidateRow>()) {
                sb.Append("<div class='cert-page'>");
                if (template == "preprint_gansu") {
                    // 模板一: 竞赛名称/运动员姓名/项目与成绩/时间地点 四行, 从照片估约
                    //   62%/66%/70%/74% 卡片高度处起
                    AppendCertField(sb, 78, 184, offXmm, offYmm, _competitionName);
                    AppendCertField(sb, 78, 196, offXmm, offYmm, c.DisplayName);
                    AppendCertField(sb, 78, 208, offXmm, offYmm, eventScoreText(c));
                    AppendCertField(sb, 78, 220, offXmm, offYmm, timeLocation);
                } else {
                    // 模板二(浩沙FAFA杯): 比赛名称/运动员姓名/组别与项目/名次与成绩/
                    //   时间地点 五行, 从照片估约 34%/38%/42%/46%/50% 卡片高度处起
                    AppendCertField(sb, 74, 101, offXmm, offYmm, _competitionName);
                    AppendCertField(sb, 74, 113, offXmm, offYmm, c.DisplayName);
                    AppendCertField(sb, 74, 125, offXmm, offYmm, groupEventText(c));
                    AppendCertField(sb, 74, 137, offXmm, offYmm, rankScoreText(c));
                    AppendCertField(sb, 74, 149, offXmm, offYmm, timeLocation);
                }
                sb.Append("</div>");
            }
            if (selected == null || selected.Count == 0) {
                sb.Append("<div class='cert-page'><p style='text-align:center;font-size:18pt;margin-top:120mm;'>" + Loc.T("Str_DocC_NoAwardeesSelected") + "</p></div>");
            }
            sb.Append("</body></html>");
            return sb.ToString();
        }

        private static void AppendCertField(StringBuilder sb, double xMm, double yMm, double offXmm, double offYmm, string text) {
            sb.AppendFormat("<div class='fld' style='left:{0}mm;top:{1}mm;'>{2}</div>",
                (xMm + offXmm).ToString(System.Globalization.CultureInfo.InvariantCulture),
                (yMm + offYmm).ToString(System.Globalization.CultureInfo.InvariantCulture),
                System.Net.WebUtility.HtmlEncode(text ?? ""));
        }

        // 2026-09-16 "完整证书(自画)"改成浩沙FAFA杯标准版那份配色/版式(见用户给的
        //   两种标准版的获奖证书模板2026-7-29.pdf 第2页)——蓝色渐变底色 + 底部波浪色带、
        //   红色粗体"获奖证书"大字、五行字段(比赛名称/运动员姓名/组别与项目/名次与成绩/
        //   时间地点)、右下角主办单位。跟预印模板那两份不一样的是: 这份还是全部由程序
        //   画出来(边框/底色/大字都是画的), 打在空白纸上就是一张完整证书, 不需要另外
        //   准备印刷好的证书纸。
        private string BuildAwardCertificateFullHaoshaHtml(List<AwardCandidateRow> selected) {
            var sb = new StringBuilder();
            sb.Append("<!DOCTYPE html><html><head><meta charset='UTF-8'><style>");
            sb.Append("body{font-family:'SimSun',serif;margin:0;padding:0;}");
            sb.Append(".cert-page{width:210mm;height:297mm;margin:0 auto;box-sizing:border-box;position:relative;");
            sb.Append("page-break-after:always;overflow:hidden;background:linear-gradient(180deg,#eef6fc 0%,#eef6fc 62%,#dcebf7 100%);}");
            sb.Append(".cert-wave{position:absolute;left:0;right:0;bottom:0;height:78mm;");
            sb.Append("background:linear-gradient(120deg,#0ea5e9 0%,#22d3ee 35%,#7dd3fc 60%,#bae6fd 80%,#fef9c3 100%);opacity:0.9;}");
            sb.Append(".cert-border{position:absolute;top:9mm;left:9mm;right:9mm;bottom:9mm;border:2px solid #c9a45c;box-sizing:border-box;}");
            sb.Append(".cert-inner{position:relative;padding:14mm 18mm 0;text-align:center;}");
            sb.Append(".cert-tag{font-family:'KaiTi','SimSun',serif;font-size:14px;color:#1d4ed8;font-style:italic;margin-bottom:6mm;}");
            sb.Append(".cert-comp{font-size:24px;font-weight:bold;color:#0f172a;letter-spacing:1px;line-height:1.5;margin-bottom:10mm;}");
            sb.Append(".cert-title{font-size:58px;font-family:'SimHei';font-weight:bold;color:#dc2626;letter-spacing:16px;margin-bottom:16mm;}");
            sb.Append(".cert-fields{max-width:150mm;margin:0 auto;text-align:left;font-size:16pt;line-height:2.6;}");
            sb.Append(".cert-field{display:flex;align-items:baseline;}");
            sb.Append(".field-label{white-space:nowrap;color:#1e3a8a;font-weight:bold;min-width:130px;}");
            sb.Append(".field-value{flex:1;border-bottom:1px solid #64748b;padding-left:8px;min-width:140px;color:#111;}");
            // 2026-09-17 主办单位这行原来 bottom:16mm, 紧贴证书最下沿, 盖章章面(常见
            //   30-40mm 直径)根本按不下去(用户实拍)。16→30→38mm 两轮实际打印盖章后
            //   都反馈还不够高, 第三轮直接抬到 58mm。
            sb.Append(".cert-org{position:absolute;right:20mm;bottom:58mm;text-align:right;font-size:14pt;font-weight:bold;color:#0f172a;}");
            sb.Append("@media print{.cert-page{-webkit-print-color-adjust:exact;print-color-adjust:exact;}@page{size:A4;margin:0;}}");
            sb.Append("</style></head><body>");

            // 2026-09-16 奖状不要页码(证书是单独发给个人的凭证, 不是一本连续编号的
            //   书刊) —— 选择窗口里选中哪些, 这里就原样逐条出一张, 不再自己数张数。
            string dateStr0 = GetDatePickerText(StartDatePicker);
            string endDateStr0 = GetDatePickerText(EndDatePicker);
            string dateRange0 = string.IsNullOrEmpty(dateStr0) ? "" : (dateStr0 + (string.IsNullOrEmpty(endDateStr0) || endDateStr0 == dateStr0 ? "" : (" " + Loc.T("Str_DocC_ToWord") + " " + endDateStr0)));
            string location0 = LocationBox.Text ?? "";
            string timeLocation0 = (dateRange0 + (string.IsNullOrEmpty(location0) ? "" : ("　" + location0))).Trim();
            string organizer0 = OrganizerBox.Text ?? "";

            foreach (var c in selected ?? new List<AwardCandidateRow>()) {
                string groupEvent = (string.IsNullOrEmpty(c.AgeGroup) ? "" : (c.AgeGroup + " ")) + c.Gender + c.EventName;
                string rankScore = c.RankLabel + (string.IsNullOrEmpty(c.TimeText) ? "" : ("　" + c.TimeText));
                sb.Append("<div class='cert-page'>");
                sb.Append("<div class='cert-wave'></div>");
                sb.Append("<div class='cert-border'></div>");
                sb.Append("<div class='cert-inner'>");
                sb.Append("<div class='cert-tag'>" + Loc.T("Str_DocC_CertTag") + "</div>");
                sb.AppendFormat("<div class='cert-comp'>{0}</div>", System.Net.WebUtility.HtmlEncode(_competitionName));
                sb.Append("<div class='cert-title'>" + Loc.T("Str_DocC_CertTitleAward") + "</div>");
                sb.Append("<div class='cert-fields'>");
                sb.AppendFormat("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelCompName") + "</span><span class='field-value'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(_competitionName));
                sb.AppendFormat("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelAthleteName") + "</span><span class='field-value'>{0}</div>", System.Net.WebUtility.HtmlEncode(c.DisplayName));
                sb.AppendFormat("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelGroupEvent") + "</span><span class='field-value'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(groupEvent));
                sb.AppendFormat("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelRankScore") + "</span><span class='field-value'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(rankScore));
                sb.AppendFormat("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelTimeVenue") + "</span><span class='field-value'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(timeLocation0));
                sb.Append("</div></div>");
                if (!string.IsNullOrEmpty(organizer0))
                    sb.AppendFormat("<div class='cert-org'>{0}</div>", System.Net.WebUtility.HtmlEncode(organizer0));
                sb.Append("</div>");
            }

            if (selected == null || selected.Count == 0) {
                sb.Append("<div class='cert-page'><p style='text-align:center;font-size:24px;margin-top:200px;'>" + Loc.T("Str_DocC_NoAwardeesSelected") + "</p></div>");
            }

            sb.Append("</body></html>");
            return sb.ToString();
        }

        // 2026-09-16 "完整证书(自画)"第二种版式——照甘肃省运动会标准版那张照片的配色画:
        //   暖白底色、红色双线边框(花纹式的花边照片里那种精细回纹没法用 CSS 精确复刻,
        //   用双线+内层细线勾一个"证书感"的边框代替)、金色大字"获奖证书"+英文副标题、
        //   四行字段(竞赛名称/运动员姓名/项目与成绩/时间地点, 跟预印版 preprint_gansu
        //   模板字段一致)、左下角主办/承办单位、右下角组委会+日期+盖章位置虚线圈(打完
        //   证书后拿真印章往虚线圈里盖, 不是画一个假印章冒充)。
        // 2026-09-17 证书右下角"组委会（盖章）"落款——_certCommitteeText 为空时用
        //   "赛事名称+组织委员会" 兜底(旧行为)。用户在设置窗口里按了回车的手动换行
        //   原样保留(按行编码后用 <br/> 拼回去), 配合 .cert-org-right 的 max-width
        //   自动换行(css white-space 默认值就会在容器变窄时换行), 长落款不会撑出证书。
        private string BuildCertCommitteeHtml() {
            string text = string.IsNullOrEmpty(_certCommitteeText) ? (_competitionName + Loc.T("Str_DocC_CommitteeSuffix")) : _certCommitteeText;
            var lines = text.Replace("\r\n", "\n").Split('\n');
            return string.Join("<br/>", lines.Select(l => System.Net.WebUtility.HtmlEncode(l)));
        }

        private string BuildAwardCertificateFullGansuHtml(List<AwardCandidateRow> selected) {
            var sb = new StringBuilder();
            sb.Append("<!DOCTYPE html><html><head><meta charset='UTF-8'><style>");
            sb.Append("body{font-family:'SimSun',serif;margin:0;padding:0;}");
            sb.Append(".cert-page{width:210mm;height:297mm;margin:0 auto;box-sizing:border-box;position:relative;");
            sb.Append("page-break-after:always;overflow:hidden;background:#fffdf6;}");
            sb.Append(".cert-frame{position:absolute;top:8mm;left:8mm;right:8mm;bottom:8mm;border:3px double #b8342a;box-sizing:border-box;}");
            sb.Append(".cert-frame-in{position:absolute;top:11.5mm;left:11.5mm;right:11.5mm;bottom:11.5mm;border:1px solid #e0a89e;box-sizing:border-box;}");
            sb.Append(".cert-inner2{position:relative;padding:22mm 22mm 0;text-align:center;}");
            sb.Append(".cert-comp-cn{font-size:22px;font-weight:bold;color:#7a1f1f;letter-spacing:2px;}");
            sb.Append(".cert-title-cn{font-size:56px;font-family:'SimHei';font-weight:bold;color:#b8860b;letter-spacing:18px;margin:14mm 0 4mm;}");
            sb.Append(".cert-title-en{font-size:13px;color:#b8860b;letter-spacing:6px;margin-bottom:16mm;}");
            sb.Append(".cert-fields2{max-width:140mm;margin:0 auto;text-align:left;font-size:15pt;line-height:2.7;}");
            sb.Append(".cert-field2{display:flex;align-items:baseline;}");
            sb.Append(".field-label2{white-space:nowrap;color:#7a1f1f;font-weight:bold;min-width:120px;}");
            sb.Append(".field-value2{flex:1;border-bottom:1px solid #94a3b8;padding-left:8px;min-width:140px;color:#111;}");
            // 2026-09-17 原来 bottom:16mm, 组委会/日期/印章圈紧贴证书最下沿, 盖章按不下去
            //   (用户实拍)。16→30→38mm 两轮实际打印盖章后都反馈还不够高, 第三轮
            //   直接抬到 58mm。
            sb.Append(".cert-bottom{position:absolute;left:22mm;right:22mm;bottom:58mm;display:flex;justify-content:space-between;align-items:flex-end;}");
            sb.Append(".cert-org-left{text-align:left;font-size:11pt;line-height:1.9;color:#333;max-width:75mm;}");
            // 2026-09-17 取消印章虚线圈(用户明确要求直接在证书上盖真章, 不需要引导圈)。
            //   组委会落款原来靠 padding-right:30mm 给虚线圈让位; 现在圈没了, 改成
            //   max-width 限制落款自身宽度——内容一长(默认换行规则)就自动折行,
            //   不再一行到底撑到边框外。
            sb.Append(".cert-org-right{text-align:right;font-size:11pt;line-height:1.9;color:#333;max-width:80mm;}");
            sb.Append("@media print{.cert-page{-webkit-print-color-adjust:exact;print-color-adjust:exact;}@page{size:A4;margin:0;}}");
            sb.Append("</style></head><body>");

            string dateStr1 = GetDatePickerText(StartDatePicker);
            string endDateStr1 = GetDatePickerText(EndDatePicker);
            string dateRange1 = string.IsNullOrEmpty(dateStr1) ? "" : (dateStr1 + (string.IsNullOrEmpty(endDateStr1) || endDateStr1 == dateStr1 ? "" : (" " + Loc.T("Str_DocC_ToWord") + " " + endDateStr1)));
            string location1 = LocationBox.Text ?? "";
            string timeLocation1 = (dateRange1 + (string.IsNullOrEmpty(location1) ? "" : ("　" + location1))).Trim();
            string organizer1 = OrganizerBox.Text ?? "";
            string host1 = HostBox.Text ?? "";
            DateTime dt1; bool hasDate1 = DateTime.TryParse(dateStr1, out dt1);

            foreach (var c in selected ?? new List<AwardCandidateRow>()) {
                string eventScore = c.Gender + c.EventName + "　" + c.RankLabel + (string.IsNullOrEmpty(c.TimeText) ? "" : ("　" + c.TimeText));
                sb.Append("<div class='cert-page'>");
                sb.Append("<div class='cert-frame'></div><div class='cert-frame-in'></div>");
                sb.Append("<div class='cert-inner2'>");
                sb.AppendFormat("<div class='cert-comp-cn'>{0}</div>", System.Net.WebUtility.HtmlEncode(_competitionName));
                sb.Append("<div class='cert-title-cn'>" + Loc.T("Str_DocC_CertTitleAward") + "</div>");
                sb.Append("<div class='cert-title-en'>CERTIFICATE OF AWARD</div>");
                sb.Append("<div class='cert-fields2'>");
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelCompName2") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(_competitionName));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelAthleteName") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(c.DisplayName));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelEventScore") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(eventScore));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelTimeVenue") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(timeLocation1));
                sb.Append("</div></div>");
                sb.Append("<div class='cert-bottom'>");
                sb.Append("<div class='cert-org-left'>");
                if (!string.IsNullOrEmpty(organizer1)) sb.AppendFormat("" + Loc.F("Str_DocC_CertOrganizerFmt", "{0}") + "", System.Net.WebUtility.HtmlEncode(organizer1));
                if (!string.IsNullOrEmpty(host1)) sb.AppendFormat("" + Loc.F("Str_DocC_CertHostFmt", "{0}") + "", System.Net.WebUtility.HtmlEncode(host1));
                sb.Append("</div>");
                sb.Append("<div class='cert-org-right'>");
                sb.Append(BuildCertCommitteeHtml());
                if (hasDate1) sb.Append(Loc.F("Str_DocC_CertDateBrFmt", dt1.Year, dt1.Month, dt1.Day));
                sb.Append("</div>");
                sb.Append("</div>");
                sb.Append("</div>");
            }

            if (selected == null || selected.Count == 0) {
                sb.Append("<div class='cert-page'><p style='text-align:center;font-size:24px;margin-top:200px;'>" + Loc.T("Str_DocC_NoAwardeesSelected") + "</p></div>");
            }

            sb.Append("</body></html>");
            return sb.ToString();
        }

        private void PrintRecordCertificate_Click(object sender, RoutedEventArgs e) {
            var records = CollectBrokenRecords();
            var win = new RecordCertificateWindow(records) { Owner = this };
            win.OnGenerate = delegate(List<BrokenRecordRow> selected, string template) {
                GenerateAndOpenDocument(Loc.T("Str_DocTitle_RecordCert"), BuildRecordCertificateHtml(selected, template));
                win.Close();
            };
            win.OnOpenCertSettings = delegate { OpenCertSettingsDialog(win, false); };
            win.ShowDialog();
        }

        // 2026-09-16 纪录证书两选一: "full_gansu"=照甘肃省运动会标准版配色画(跟奖状那份
        //   完整证书－甘肃省运动会风格是同一套 CSS 风格, 红双线边框+金字), 其它(含默认)
        //   =原来那份深蓝双线边框的样式。纪录证书目前没有对应的预印证书纸模板(用户只
        //   给了获奖证书的两张照片), 所以不像奖状那样有"预印套打"选项。
        private string BuildRecordCertificateHtml(List<BrokenRecordRow> selected, string template) {
            if (template == "full_gansu") return BuildRecordCertificateFullGansuHtml(selected);
            return BuildRecordCertificateFullHtml(selected);
        }

        // 2026-09-16 纪录证书"甘肃省运动会风格"——跟 BuildAwardCertificateFullGansuHtml
        //   同一套配色/边框/角标(红双线边框、金色大字、虚线印章圈), 字段换成纪录证书
        //   自己的: 竞赛名称/运动员姓名/项目与成绩/纪录类型/时间地点, 比奖状那份多一行
        //   "纪录类型"(破的是哪项纪录), 少不了——不然证书上看不出破的是什么纪录。
        private string BuildRecordCertificateFullGansuHtml(List<BrokenRecordRow> selected) {
            var sb = new StringBuilder();
            sb.Append("<!DOCTYPE html><html><head><meta charset='UTF-8'><style>");
            sb.Append("body{font-family:'SimSun',serif;margin:0;padding:0;}");
            sb.Append(".cert-page{width:210mm;height:297mm;margin:0 auto;box-sizing:border-box;position:relative;");
