                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelEventScore") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(eventScore));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelMeetRank") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(r.CompRankLabel ?? "-"));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelRecordType") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(r.RecordType ?? ""));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelOldRecord") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(oldRecordLine));
                sb.AppendFormat("<div class='cert-field2'><span class='field-label2'>" + Loc.T("Str_DocC_CertLabelTimeVenue") + "</span><span class='field-value2'>{0}</span></div>", System.Net.WebUtility.HtmlEncode(timeLocation2));
                sb.Append("</div></div>");
                sb.Append("<div class='cert-bottom'>");
                sb.Append("<div class='cert-org-left'>");
                if (!string.IsNullOrEmpty(organizer2)) sb.AppendFormat("" + Loc.F("Str_DocC_CertOrganizerFmt", "{0}") + "", System.Net.WebUtility.HtmlEncode(organizer2));
                if (!string.IsNullOrEmpty(host2)) sb.AppendFormat("" + Loc.F("Str_DocC_CertHostFmt", "{0}") + "", System.Net.WebUtility.HtmlEncode(host2));
                sb.Append("</div>");
                sb.Append("<div class='cert-org-right'>");
                sb.Append(BuildCertCommitteeHtml());
                if (hasDate2) sb.Append(Loc.F("Str_DocC_CertDateBrFmt", dt2.Year, dt2.Month, dt2.Day));
                sb.Append("</div>");
                sb.Append("</div>");
                sb.Append("</div>");
            }

            if (selected == null || selected.Count == 0) {
                sb.Append("<div class='cert-page'><p style='text-align:center;font-size:24px;margin-top:200px;'>" + Loc.T("Str_DocC_NoRecordsSelected") + "</p></div>");
            }

            sb.Append("</body></html>");
            return sb.ToString();
        }

        private string BuildRecordCertificateFullHtml(List<BrokenRecordRow> selected) {
            // 查找本次比赛中破纪录的运动员
            var sb = new StringBuilder();
            sb.Append("<!DOCTYPE html><html><head><meta charset='UTF-8'><style>");
            sb.Append("body{font-family:'SimSun',serif;margin:0;padding:0;}");
            sb.Append(".cert-page{width:210mm;min-height:297mm;margin:0 auto;box-sizing:border-box;");
            sb.Append("padding:24mm 22mm;border:10px double #1a3a6e;position:relative;page-break-after:always;}");
            sb.Append(".cert-title{font-size:54px;font-family:'SimHei';text-align:center;letter-spacing:18px;color:#1a3a6e;margin-bottom:18px;}");
            sb.Append(".cert-divider{border:none;border-top:3px solid #1a3a6e;margin:0 0 28px;}");
            sb.Append(".cert-body{font-size:22px;line-height:2.6;color:#111;}");
            sb.Append(".cert-name{font-size:26px;font-weight:bold;color:#1a0000;text-decoration:underline;text-underline-offset:5px;}");
            sb.Append(".cert-text{text-indent:2em;}");
            sb.Append(".cert-comp-name{font-weight:bold;color:#1a3a6e;text-decoration:underline;text-underline-offset:4px;}");
            sb.Append(".cert-event-name{font-weight:bold;text-decoration:underline;text-underline-offset:4px;}");
            sb.Append(".cert-score{font-size:24px;font-weight:bold;color:#cc0000;text-decoration:underline;text-underline-offset:4px;}");
            sb.Append(".cert-record-type{font-weight:bold;color:#1a3a6e;text-decoration:underline;text-underline-offset:4px;}");
            sb.Append(".cert-fields{margin-top:40px;font-size:20px;line-height:2.8;}");
            sb.Append(".cert-field{display:flex;align-items:baseline;margin-bottom:4px;}");
            sb.Append(".field-label{white-space:nowrap;color:#222;font-weight:bold;}");
            sb.Append(".field-value{flex:1;border-bottom:1px solid #555;padding-left:10px;min-width:120px;color:#111;}");
            sb.Append(".field-blank{flex:1;border-bottom:1px solid #555;min-width:120px;}");
            sb.Append(".cert-date{text-align:right;font-size:20px;margin-top:20px;color:#333;letter-spacing:3px;}");
            sb.Append("@media print{.cert-page{-webkit-print-color-adjust:exact;}@page{size:A4;margin:0;}}");
            sb.Append("</style></head><body>");

            // 2026-09-16 纪录证书改从选择窗口来, 数据源是 CollectBrokenRecords() 那份
            //   真实"破纪录"名单(跟成绩册"破纪录统计表"同一处来源), 不再是手填占位模板。
            //   不要页码(单独发给个人的凭证, 不是连续编号的书刊)。
            string dateStr = GetDatePickerText(StartDatePicker);
            DateTime dt; bool hasDate = DateTime.TryParse(dateStr, out dt);
            foreach (var r in selected ?? new List<BrokenRecordRow>()) {
                // 2026-09-16 用户要求纪录证书要印"原记录成绩/谁的记录/时间/运动会名次"。
                string oldRecordLine = (!string.IsNullOrEmpty(r.OldHolder) || !string.IsNullOrEmpty(r.OldTime) || !string.IsNullOrEmpty(r.OldDate))
                    ? (r.OldHolder + (string.IsNullOrEmpty(r.OldHolder) || string.IsNullOrEmpty(r.OldTime) ? "" : "　") + r.OldTime
                       + (string.IsNullOrEmpty(r.OldDate) ? "" : ("　" + r.OldDate)))
                    : "该项目原无纪录";
                sb.Append("<div class='cert-page'>");
                sb.Append("<div class='cert-title'>" + Loc.T("Str_DocC_CertTitleRecord") + "</div>");
                sb.Append("<hr class='cert-divider'/>");
                sb.Append("<div class='cert-body'>");
                sb.AppendFormat("<div style='font-size:24px;'><span class='cert-name'>{0}</span>：</div>", r.Athlete);
                sb.Append("<div class='cert-text'>");
                sb.AppendFormat("" + Loc.F("Str_DocC_CertInCompFmt", "{0}") + "", _competitionName);
                sb.AppendFormat("" + Loc.F("Str_DocC_CertEventNameFmt", "{0}", "{1}") + "", r.Gender, r.EventName);
                sb.AppendFormat("" + Loc.F("Str_DocC_CertAchievedFmt", "{0}", "{1}") + "", r.Time, r.CompRankLabel ?? "-");
                sb.AppendFormat("" + Loc.F("Str_DocC_CertBrokeRecordFmt", "{0}", "{1}") + "", r.RecordType, System.Net.WebUtility.HtmlEncode(oldRecordLine));
                sb.Append("" + Loc.T("Str_DocC_CertAwardedText") + "");
                sb.Append("</div></div>");
                sb.Append("<div class='cert-fields'>");
                sb.AppendFormat("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelUnit") + "</span><span class='field-value'>{0}</span></div>", r.Country);
                // 2026-05-26 删除"裁判长签字"行 (该字段历史用 ChiefJudgeBox 即编排长数据)
                sb.Append("<div class='cert-field'><span class='field-label'>" + Loc.T("Str_DocC_CertLabelSeal") + "</span><span class='field-blank'>&nbsp;</span></div>");
                if (hasDate)
                    sb.Append("<div class='cert-date'>" + Loc.F("Str_DocC_CertDateFmt", dt.Year, dt.Month, dt.Day) + "</div>");
                sb.Append("</div></div>");
            }

            if (selected == null || selected.Count == 0) {
                sb.Append("<div class='cert-page'><p style='text-align:center;font-size:24px;margin-top:200px;'>" + Loc.T("Str_DocC_NoRecordsSelected") + "</p></div>");
            }
            sb.Append("</body></html>");
            return sb.ToString();
        }

        private string BuildSplitTimeReportHtml() {
            var sb = new StringBuilder();
            sb.AppendFormat("<html><head><meta charset='UTF-8'><style>{0}</style></head><body>", DocCss());
            sb.Append(DocHeader(Loc.T("Str_DocC_HeadSplitReport")));

            // 2026-06-04 顺序统一: 性别 组别 项目 赛次 第N组
            string ageGroupSpaceS = string.IsNullOrEmpty(_currentAgeGroup) ? "" : (_currentAgeGroup + " ");
            string eventTitle = Loc.GenderDisplay(_currentGender) + " " + ageGroupSpaceS + _currentEvent + " " + Loc.StageDisplay(_currentStage) + Loc.F("Str_DocC_HeatDisplayFmt", _currentHeat);
            sb.Append("<h3>" + Loc.F("Str_DocC_EventTitleSimpleFmt", eventTitle) + "</h3>");

            // 2026-06-16 加 _currentAgeGroup 筛选, 跨组别共用 (gender,event,stage) 不会拿错 Date/Time
            var sch = _schedule.FirstOrDefault(s => s.Gender == _currentGender && s.EventName == _currentEvent && s.Stage == _currentStage
                && (string.IsNullOrEmpty(_currentAgeGroup) || (s.AgeGroup ?? "") == _currentAgeGroup));
            string dateTimeInfo = sch != null ? string.Format("{0} {1}", sch.Date, sch.Time).Trim() : Loc.T("Str_DocC_TimeTBD");
            sb.Append("<h4>" + Loc.F("Str_DocC_LabelRaceTime", dateTimeInfo, LocationBox.Text) + "</h4>");

            // 合并表：每位运动员一行，每段距离一列（与 BuildSplitTimeReportHtmlFor 共用）
            var heatSwimmers = GetCurrentHeatSwimmers().OrderBy(s => s.Lane).ToList();
            sb.Append(BuildMergedSplitsTableHtml(heatSwimmers, _currentStage, _currentHeat, _isRelay));
            sb.Append(DocSignatureRow());
            sb.Append(DocFooter());
            sb.Append("</body></html>");
            return sb.ToString();
        }

        // ═══════════════════════════════════════════════════════════════
        // 工具方法
        // ═══════════════════════════════════════════════════════════════
        // 2026-06-10 Helper: 秒数转 "M:SS.CC" 或 "SS.CC" 格式 (= 比赛日志 [T=...] 显示用)
        private static string FormatElapsedMSS(double sec) {
            if (sec < 0) return "—";
            int m = (int)(sec / 60);
            double s = sec - m * 60;
            if (m > 0) return string.Format("{0}:{1:00.00}", m, s);
            return s.ToString("F2");
        }

        private void AddLog(string msg) {
            // 2026-06-06 系统工作状态 → 比赛日志 (LogListBox) 已下线 (= 与 系统日志与数据 → 运行日志
            //   SystemLogListBox 同内容, 用户要求精简, 只保留后者). AddLog 现只写 SystemLogListBox.
            string entry = string.Format("[{0}] {1}", DateTime.Now.ToString("HH:mm:ss"), msg);
            // 2026-08-28 同时落盘。界面那个列表只留 300 行、还带虚拟化, 出了问题
            //   既翻不到历史也没法远程看 —— 排查现场问题时这是最要命的一点。
            //   写文件是尽力而为: 任何异常都吞掉, 绝不能因为记日志把比赛搞停。
            AppendLogFile(entry);
            if (SystemLogListBox == null) return;
            SystemLogListBox.Items.Insert(0, entry);
            if (SystemLogListBox.Items.Count > 300) SystemLogListBox.Items.RemoveAt(SystemLogListBox.Items.Count - 1);
        }

        private static readonly object _logFileLock = new object();
        private static string _logFilePath;

        /// <summary>把一行日志追加到 &lt;程序目录&gt;\Logs\yyyyMMdd.log。失败一律忽略。</summary>
        private static void AppendLogFile(string entry) {
            try {
                lock (_logFileLock) {
                    string today = DateTime.Now.ToString("yyyyMMdd");
                    if (_logFilePath == null || !_logFilePath.EndsWith(today + ".log", StringComparison.Ordinal)) {
                        string dir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs");
                        if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
                        _logFilePath = IOPath.Combine(dir, today + ".log");
                        // 顺手清掉 14 天前的, 免得越积越多
                        try {
                            foreach (var old in Directory.GetFiles(dir, "*.log"))
                                if (File.GetLastWriteTime(old) < DateTime.Now.AddDays(-14)) File.Delete(old);
                        } catch { }
                    }
                    File.AppendAllText(_logFilePath, entry + Environment.NewLine, Encoding.UTF8);
                }
            } catch { }
        }

        /// <summary>
        /// 2026-09-17 用户要求: 运行日志能存成一个文件, 方便出问题时直接拷给开发方分析。
        ///
        /// 界面上那个 SystemLogListBox 只留最近 300 行(还带虚拟化), 复制粘贴很不方便,
        /// 而且早就重启过的话当次启动之前的日志根本不在列表里。AddLog 其实一直有落盘
        /// (AppendLogFile, Logs\yyyyMMdd.log 按天分文件, 14 天自动清理), 只是这个路径
        /// 藏在安装目录里, 现场没人会主动去翻——这里直接把 Logs 目录下所有还没被清理掉
        /// 的日志文件(=最近 14 天内)按日期顺序拼成一份, 弹保存对话框让用户自己选地方存,
        /// 不用再教人怎么找安装目录、怎么复制文本。
        /// </summary>
        private void ExportLog_Click(object sender, RoutedEventArgs e) {
            try {
                string dir = IOPath.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs");
                if (!Directory.Exists(dir)) {
                    AppMessageBox.Show(Loc.T("Str_Msg_NoLogFile"), Loc.T("Str_MsgTitle_ExportLog"), MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                var files = Directory.GetFiles(dir, "*.log").OrderBy(f => f).ToList();
                if (files.Count == 0) {
                    AppMessageBox.Show(Loc.T("Str_Msg_NoLogFile"), Loc.T("Str_MsgTitle_ExportLog"), MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                string defaultName = string.Format("运行日志_{0}_{1}.txt",
                    string.IsNullOrEmpty(_competitionName) ? "游泳赛事" : _competitionName,
                    DateTime.Now.ToString("yyyyMMdd_HHmmss"));
                var dlg = new Microsoft.Win32.SaveFileDialog {
                    Filter = Loc.T("Str_Filter_TxtFile"),
                    Title = Loc.T("Str_Win_ExportRunLog_Title"),
                    FileName = defaultName,
                    InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)
                };
                if (dlg.ShowDialog() != true) return;

                var sb = new StringBuilder();
                sb.AppendFormat("运行日志导出 —— {0}（共 {1} 天）", DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"), files.Count);
                sb.AppendLine();
                foreach (var f in files) {
                    sb.AppendLine();
                    sb.AppendFormat("══════ {0} ══════", IOPath.GetFileNameWithoutExtension(f));
                    sb.AppendLine();
                    try { sb.Append(File.ReadAllText(f, Encoding.UTF8)); }
                    catch (Exception exRead) { sb.AppendFormat("（这一天的日志读取失败: {0}）", exRead.Message).AppendLine(); }
                }
                File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
                AppMessageBox.Show(Loc.F("Str_Msg_ExportedToFmt", dlg.FileName), Loc.T("Str_MsgTitle_ExportLog"), MessageBoxButton.OK, MessageBoxImage.Information);
            } catch (Exception ex) {
                AppMessageBox.Show(Loc.F("Str_Msg_ExportFailedFmt", ex.Message), Loc.T("Str_MsgTitle_ExportLog"), MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private string GetLocalIP() {
            try {
                using (Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, 0)) {
                    socket.Connect("8.8.8.8", 65530);
                    IPEndPoint endPoint = socket.LocalEndPoint as IPEndPoint;
                    return endPoint.Address.ToString();
                }
            } catch {
                return "127.0.0.1";
            }
        }

        private void Window_Closing(object sender, CancelEventArgs e) {
            if (AppMessageBox.Show(Loc.T("Str_Msg_ConfirmExit"), Loc.T("Str_MsgTitle_ConfirmExit"), MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) {
                e.Cancel = true;
                return;
            }
            AutoSaveData();
            _raceTimer.Stop();
            _countdownTimer.Stop();
            try { CancelAllLaneCloseTimers(); } catch { }
            if (_timingBridge != null) _timingBridge.Dispose();
            if (_server != null) _server.Dispose();
            // 2026-09-14 RTC/编排端退出时连接数不 -1、下次连上又 +1 的根 ——
            //   RTC/ScheduleEditor 模式不开本机 _server(上面这行 Dispose 是空操作),
            //   它们连主服务器靠的是 _editorSyncClient 这条单独的 TCP 连接, 但这里
            //   从来没关过它: 点窗口右上角 X 正常关闭时, 只是进程退出把 TCP 硬断,
            //   没发 WebSocket 关闭帧。主服务器那端全靠 Fleck 探测到连接失效才会
            //   触发 OnClose 把它从 _timingExeSockets/_editorSockets 里摘掉 ——
            //   这个探测不是即时的(经常要等到主服务器下次给这条连接写数据失败才发现),
            //   现场看到的就是"退出时数量不减, 下次连上又多一个"。
            //   退出前主动断开, 发出正经的 WebSocket 关闭帧, 主服务器立刻 OnClose。
            if (_editorSyncClient != null) { try { _editorSyncClient.Disconnect(); } catch { } }
        }

